def _safe_call_destination_overlay_after_import_skipped(
    host: Any, *, skip_reason: str, overlay_reason: str | None = None
) -> None:
    """Unit-test materialize hosts may omit import-followup diagnostics; avoid AttributeError."""
    fn = getattr(host, "_log_destination_overlay_after_import_skipped", None)
    if callable(fn):
        fn(skip_reason=skip_reason, overlay_reason=overlay_reason)


def _safe_call_destination_overlay_entry_context(host: Any, reason: str) -> None:
    fn = getattr(host, "_log_destination_overlay_entry_context", None)
    if callable(fn):
        fn(reason)


def _destination_fingerprint_path_segments(path: str) -> List[str]:
    normalized = normalize_manifest_path(path)
    if not normalized:
        return []
    return [segment for segment in normalized.split("\\") if segment]


def destination_projection_segments_explicit(path: str, context_segments: List[str]) -> List[str]:
    """Graph-relative segments for SharePoint — same coordinate system as live Graph ``item_path``.

    Only the legacy internal namespace prefix ``Root\\`` (see :data:`LEGACY_INTERNAL_ROOT_SEGMENT`)
    is removed. No other leading segment is treated as synthetic; real folders such as ``Root3``,
    ``Root2``, or ``FTBMRoot`` are preserved. Site/library display labels are stripped when they
    match the active destination context, not arbitrary first segments.
    """
    raw = normalize_manifest_path(str(path or "").strip())
    if not raw:
        return []
    stripped = strip_legacy_internal_root_prefix(raw)
    if not stripped:
        return []
    segments = [s for s in stripped.split("\\") if s]
    if not segments:
        return []
    lowered = [segment.lower() for segment in segments]
    ctx = [str(s or "").strip() for s in (context_segments or []) if str(s or "").strip()]
    if ctx:
        lowered_ctx = [c.lower() for c in ctx]
        library_segment = lowered_ctx[-1]
        if library_segment in lowered:
            library_index = lowered.index(library_segment)
            return segments[library_index + 1 :]
        site_segment = lowered_ctx[0]
        if site_segment in lowered:
            site_index = lowered.index(site_segment)
            trimmed = segments[site_index + 1 :]
            if trimmed:
                trimmed_lowered = [segment.lower() for segment in trimmed]
                if library_segment in trimmed_lowered:
                    library_index = trimmed_lowered.index(library_segment)
                    trimmed = trimmed[library_index + 1 :]
            return trimmed
    return segments


def canonical_destination_path_for_library_fingerprint(path: str, context_segments: List[str]) -> str:
    raw = str(path or "").strip()
    if is_absolute_local_path(raw):
        return normalize_manifest_path(raw)
    segments = destination_projection_segments_explicit(raw, context_segments)
    if not segments:
        return ""
    return normalize_manifest_path("\\".join(segments))


def destination_library_structural_fingerprint_from_items(
    items: Optional[List[Any]],
    *,
    context_segments: List[str],
) -> Tuple[str, int]:
    """Deterministic full-library digest: sorted ``canonical_path\\x1fid`` per row (detects same-count topology changes)."""
    lines: List[str] = []
    ctx = context_segments or []
    for item in items or []:
        if not isinstance(item, dict):
            continue
        path = (
            item.get("display_path")
            or item.get("item_path")
            or item.get("destination_path")
            or ""
        )
        canon = canonical_destination_path_for_library_fingerprint(str(path), ctx)
        if not canon:
            continue
        iid = str(item.get("id", "") or "").strip()
        if iid:
            lines.append(f"{canon}\x1f{iid}")
    lines.sort()
    return hashlib.sha256("\n".join(lines).encode("utf-8")).hexdigest(), len(lines)


def destination_root_child_fingerprint_from_normalized_items(
    items: Optional[List[Any]],
    *,
    context_segments: List[str],
) -> Tuple[str, int]:
    """Root-level child id fingerprint aligned with ``_destination_root_children_fingerprint_from_full_snapshot``."""
    ids: List[str] = []
    ctx = context_segments or []
    for item in items or []:
        if not isinstance(item, dict):
            continue
        path = (
            item.get("display_path")
            or item.get("item_path")
            or item.get("destination_path")
            or ""
        )
        canon = canonical_destination_path_for_library_fingerprint(str(path), ctx)
        segs = _destination_fingerprint_path_segments(canon)
        if len(segs) != 1:
            continue
        iid = str(item.get("id", "") or "").strip()
        if iid:
            ids.append(iid)
    ids.sort()
    fp = hashlib.sha256("|".join(ids).encode("utf-8")).hexdigest()
    return fp, len(ids)


class LoginWorker(QThread):
    success = Signal(dict)
    error = Signal(str)

    def __init__(self, graph):
        super().__init__()
        self.graph = graph

    def run(self):
        log_trace("worker", "LoginWorker_start")
        try:
            self.graph.acquire_token()
            session_context = self.graph.build_session_context()
            log_trace("worker", "LoginWorker_success", user_role=session_context.get("user_role", ""))
            self.success.emit({
                "profile": session_context.get("profile", {}),
                "session_context": session_context,
            })
        except Exception as e:
            log_trace("worker", "LoginWorker_error", error_excerpt=str(e)[:500])
            self.error.emit(str(e))


class SilentGraphSessionRestoreWorker(QThread):
    """Background: MSAL silent token + /me profile after cold start (e.g. dev process respawn)."""

    success = Signal(dict)
    failed = Signal()

    def __init__(self, graph):
        super().__init__()
        self.graph = graph

    def run(self):
        log_trace("worker", "SilentGraphSessionRestoreWorker_start")
        try:
            if not self.graph.refresh_access_token_silently(force_refresh=False):
                log_trace("worker", "SilentGraphSessionRestoreWorker_no_cached_session")
                self.failed.emit()
                return
            session_context = self.graph.build_session_context()
            profile = session_context.get("profile") or {}
            log_trace(
                "worker",
                "SilentGraphSessionRestoreWorker_success",
                user_role=session_context.get("user_role", ""),
            )
            self.success.emit({"profile": profile, "session_context": session_context})
        except Exception as e:
            log_trace("worker", "SilentGraphSessionRestoreWorker_error", error_excerpt=str(e)[:500])
            self.failed.emit()


