class RootLoadWorker(QThread):
    success = Signal(dict)
    error = Signal(dict)

    def __init__(self, graph, panel_key, drive_id, context):
        super().__init__()
        self.graph = graph
        self.panel_key = panel_key
        self.drive_id = drive_id
        self.context = context

    def run(self):
        log_trace(
            "worker",
            "RootLoadWorker_start",
            panel_key=self.panel_key,
            drive_id_suffix=str(self.drive_id)[-16:],
            cache_only=bool((self.context or {}).get("cache_only")),
        )
        try:
            items = self.graph.list_drive_root_items_normalized(self.drive_id, **self.context)
            log_trace(
                "worker",
                "RootLoadWorker_success",
                panel_key=self.panel_key,
                item_count=len(items or []),
            )
            self.success.emit({
                "panel_key": self.panel_key,
                "drive_id": self.drive_id,
                "items": items,
            })
        except Exception as e:
            log_trace("worker", "RootLoadWorker_error", panel_key=self.panel_key, error_excerpt=str(e)[:500])
            self.error.emit({
                "panel_key": self.panel_key,
                "drive_id": self.drive_id,
                "error": str(e),
            })


def _graph_destination_child_load_max_active() -> int:
    """Parallel Graph /children workers for destination (env-tunable, clamped 12..32, default 16)."""
    try:
        v = int(os.environ.get("OZLINK_GRAPH_DEST_CHILD_LOAD_MAX", "16"))
    except Exception:
        v = 16
    return max(12, min(32, v))


# Max model nodes visited per subtree hydration walk (safety; avoids main-thread freeze on pathological trees).
_GRAPH_SUBTREE_HYDRATION_WALK_NODE_CAP = 8192


@dataclass(frozen=True)
class _GraphDestinationChildBacklogEntry:
    """Backlog item for Graph destination folder child loads when the active worker cap is reached."""

    pending_key: str
    drive_id: str
    item_id: str
    trigger: str
    reason: str
    path_excerpt: str
    enqueued_perf: float = 0.0
    graph_child_union_fingerprint: Optional[dict] = field(default=None)


def _graph_destination_child_load_request_is_high_priority(trigger: str, reason: str) -> bool:
    t = str(trigger or "").strip().lower()
    r = str(reason or "").strip().lower()
    if t in ("tree_expanded", "subtree_hydrate_batch", "post_bind_visible_subtree"):
        return True
    if r in (
        "user_expand",
        "eager_visible_descendant",
        "expanded_child_folder",
        "subtree_hydration",
        "subtree_hydration_progressive",
    ):
        return True
    return False


# Keys accepted by :meth:`GraphClient.list_drive_item_children_normalized` — worker ``context`` may add
# underscore-prefixed timing fields (e.g. ``_graph_request_perf``) that must not be forwarded as ``**kwargs``.
_FOLDER_LOAD_WORKER_GRAPH_CHILD_KW = frozenset(
    {"site_id", "site_name", "library_id", "library_name", "tree_role", "parent_item_path", "cache_only"}
)


def _folder_load_worker_graph_list_children_kwargs(context) -> dict:
    if not isinstance(context, dict):
        return {}
    return {k: v for k, v in context.items() if k in _FOLDER_LOAD_WORKER_GRAPH_CHILD_KW}


class FolderLoadWorker(QThread):
    success = Signal(dict)
    error = Signal(dict)

    def __init__(self, graph, panel_key, drive_id, item_id, context):
        super().__init__()
        self.graph = graph
        self.panel_key = panel_key
        self.drive_id = drive_id
        self.item_id = item_id
        self.context = context

    def run(self):
        log_trace(
            "worker",
            "FolderLoadWorker_start",
            panel_key=self.panel_key,
            drive_id_suffix=str(self.drive_id)[-16:],
            item_id_suffix=str(self.item_id)[-16:],
            cache_only=bool((self.context or {}).get("cache_only")),
        )
        _t_worker = time.perf_counter()
        _req_t = (self.context or {}).get("_graph_request_perf")
        _wait_ms = 0.0
        try:
            if isinstance(_req_t, (int, float)) and float(_req_t) > 0.0:
                _wait_ms = max(0.0, (_t_worker - float(_req_t)) * 1000.0)
        except Exception:
            _wait_ms = 0.0
        log_info(
            "graph_child_load_started",
            panel_key=self.panel_key,
            parent_item_path_excerpt=str((self.context or {}).get("parent_item_path") or "")[:400],
            graph_item_id_suffix=str(self.item_id)[-16:],
            drive_id_suffix=str(self.drive_id)[-16:],
            cache_only=bool((self.context or {}).get("cache_only")),
            wait_ms=int(_wait_ms),
        )
        log_info(
            "graph_child_load_wait_ms",
            phase="pre_graph_fetch",
            panel_key=self.panel_key,
            wait_ms=int(_wait_ms),
            graph_item_id_suffix=str(self.item_id)[-16:],
            parent_item_path_excerpt=str((self.context or {}).get("parent_item_path") or "")[:400],
        )
        try:
            _t_fetch = time.perf_counter()
            items = self.graph.list_drive_item_children_normalized(
                self.drive_id, self.item_id, **_folder_load_worker_graph_list_children_kwargs(self.context)
            )
            _fetch_ms = int(max(0.0, (time.perf_counter() - _t_fetch) * 1000.0))
            log_trace(
                "worker",
                "FolderLoadWorker_success",
                panel_key=self.panel_key,
                item_count=len(items or []),
            )
            log_info(
                "graph_child_fetch_result_count",
                panel_key=self.panel_key,
                result_count=len(items or []),
                graph_item_id_suffix=str(self.item_id)[-16:],
                parent_item_path_excerpt=str((self.context or {}).get("parent_item_path") or "")[:400],
                fetch_ms=int(_fetch_ms),
            )
            self.success.emit({
                "panel_key": self.panel_key,
                "drive_id": self.drive_id,
                "item_id": self.item_id,
                "items": items,
                "_graph_worker_fetch_ms": int(_fetch_ms),
                "_graph_worker_wait_ms": int(_wait_ms),
            })
        except Exception as e:
            log_trace("worker", "FolderLoadWorker_error", panel_key=self.panel_key, error_excerpt=str(e)[:500])
            log_info(
                "graph_child_fetch_failed",
                panel_key=self.panel_key,
                phase="worker_exception",
                graph_item_id_suffix=str(self.item_id)[-16:],
                parent_item_path_excerpt=str((self.context or {}).get("parent_item_path") or "")[:400],
                error_excerpt=str(e)[:500],
            )
            self.error.emit({
                "panel_key": self.panel_key,
                "drive_id": self.drive_id,
                "item_id": self.item_id,
                "error": str(e),
            })


OZLINK_DESTINATION_PLANNING_DRAG_MIME = "application/x-ozlink-destination-planning-drag"

_DRAGTRACE_MSG = "DRAGTRACE"
_DRAGPROOF_MSG = "DRAGPROOF"

_DRAGPROOF_DRAG_EVENT_TYPES = (
    QEvent.Type.DragEnter,
    QEvent.Type.DragMove,
    QEvent.Type.Drop,
    QEvent.Type.DragLeave,
)

_ozlink_dragproof_saved_notify = None


def _dragproof_destination_tree_ids(tree) -> dict:
    if tree is None:
        return {
            "tree_class": None,
            "tree_id": None,
            "viewport_id": None,
            "header_id": None,
            "vsb_id": None,
            "hsb_id": None,
        }
    try:
        vp = tree.viewport()
        hdr = tree.header()
        vsb = tree.verticalScrollBar()
        hsb = tree.horizontalScrollBar()
        return {
            "tree_class": tree.__class__.__name__,
            "tree_id": id(tree),
            "viewport_id": id(vp),
            "header_id": id(hdr),
            "vsb_id": id(vsb),
            "hsb_id": id(hsb),
        }
    except Exception:
        return {
            "tree_class": type(tree).__name__,
            "tree_id": id(tree),
            "viewport_id": None,
            "header_id": None,
            "vsb_id": None,
            "hsb_id": None,
        }


def dragproof_log(phase: str, tree, **extra) -> None:
    payload = {"phase": phase, **_dragproof_destination_tree_ids(tree)}
    payload.update(extra)
    log_info(_DRAGPROOF_MSG, **payload)


def _dragproof_dest_ids_for_main_window(mw) -> dict:
    """Reference SharePoint destination tree vs active (may be local) tree for DRAGTRACE start."""
    if mw is None:
        return {
            "dest_tree_id": None,
            "dest_viewport_id": None,
            "dest_header_id": None,
            "active_tree_id": None,
            "active_viewport_id": None,
            "active_header_id": None,
            "browse_mode": None,
        }
    ref = getattr(mw, "destination_tree_widget", None)
    dref = _dragproof_destination_tree_ids(ref)
    act = mw._active_destination_tree_widget()
    dact = _dragproof_destination_tree_ids(act)
    return {
        "dest_tree_id": dref.get("tree_id"),
        "dest_viewport_id": dref.get("viewport_id"),
        "dest_header_id": dref.get("header_id"),
        "active_tree_id": dact.get("tree_id"),
        "active_viewport_id": dact.get("viewport_id"),
        "active_header_id": dact.get("header_id"),
        "browse_mode": mw._planning_browse_mode("destination"),
    }


def _dragproof_qcore_notify(self, receiver, event):
    et = event.type()
    if et in _DRAGPROOF_DRAG_EVENT_TYPES:
        try:
            acc = event.isAccepted()
        except Exception:
            acc = False
        try:
            log_info(
                _DRAGPROOF_MSG,
                phase="app_event",
                receiver_class=receiver.__class__.__name__,
                receiver_id=id(receiver),
                ev=int(et),
                accepted=acc,
                proposed=_dragtrace_proposed_int(event),
                drop=_dragtrace_drop_action_int(event),
            )
        except Exception:
            pass
    return _ozlink_dragproof_saved_notify(self, receiver, event)


def install_dragproof_qcoreapplication_notify_hook() -> None:
    """Intercept QCoreApplication.notify once to log real drag event receivers (per-widget delivery)."""
    global _ozlink_dragproof_saved_notify
    from PySide6.QtWidgets import QApplication

    if QApplication.instance() is None or getattr(QCoreApplication, "_ozlink_dragproof_notify_installed", False):
        return
    _ozlink_dragproof_saved_notify = QCoreApplication.notify
    QCoreApplication.notify = _dragproof_qcore_notify
    QCoreApplication._ozlink_dragproof_notify_installed = True


def _dragtrace_global_pos_str(event) -> str:
    try:
        gp = event.globalPosition()
        p = gp.toPoint()
        return f"{p.x()},{p.y()}"
    except Exception:
        pass
    try:
        pos = event.position()
        p = pos.toPoint()
        return f"local:{p.x()},{p.y()}"
    except Exception:
        return "?"


def _dragtrace_mime_ok(event) -> bool:
    md = event.mimeData()
    return bool(md and md.hasFormat(OZLINK_DESTINATION_PLANNING_DRAG_MIME))


def _dragtrace_drop_action_int(event):
    try:
        da = event.dropAction()
        if hasattr(da, "value"):
            return int(da.value)
        return int(da)
    except Exception:
        return None


def _dragtrace_proposed_int(event):
    try:
        pa = event.proposedAction()
        if hasattr(pa, "value"):
            return int(pa.value)
        return int(pa)
    except Exception:
        return None


def _qt_drop_action_to_int(action) -> int | None:
    """PySide6 drag.exec() may return DropAction enum; int() on it raises on some Python/Qt stacks."""
    if action is None:
        return None
    try:
        if hasattr(action, "value"):
            return int(action.value)
        return int(action)
    except Exception:
        return None


_MANUALDRAG_MSG = "MANUALDRAG"


def _manualdrag_log(phase: str, *, tree_class: str, **data) -> None:
    log_info(_MANUALDRAG_MSG, phase=phase, tree_class=tree_class, **data)


def _manualdrag_commit_target_fields(mw, target_node: dict | None) -> dict[str, str]:
    """MANUALDRAG extras for resolved commit target (allocated folder diagnostics)."""
    if mw is None or not isinstance(target_node, dict) or not target_node:
        return {"target_row_type": "", "allocated_flag": "no"}
    if target_node.get("is_folder") is False:
        row_kind = "file"
    elif bool(target_node.get("is_folder")):
        row_kind = "folder"
    elif mw.node_is_planned_allocation(target_node):
        row_kind = "folder"
    else:
        row_kind = "folder" if target_node.get("is_folder", True) else "file"
    return {
        "target_row_type": row_kind,
        "allocated_flag": "yes" if mw.node_is_planned_allocation(target_node) else "no",
    }


def _manualdrag_destination_row_diagnostics(mw, node: dict | None) -> dict[str, str]:
    """MANUALDRAG classification for allocation-projected descendant rows (logging only)."""
    if mw is None or not isinstance(node, dict) or not node:
        return {
            "allocation_descendant": "no",
            "projected_descendant": "no",
            "real_container": "no",
        }
    origin = str(node.get("node_origin", "")).lower()
    return {
        "allocation_descendant": "yes" if bool(node.get("planned_allocation_descendant")) else "no",
        "projected_descendant": "yes" if origin == "projectedallocationdescendant" else "no",
        "real_container": "yes" if mw.node_is_manual_drag_destination_folder(node) else "no",
    }


def _destination_drop_band_margin_px(row_height: int) -> int:
    """Narrow top/bottom band so most pointer positions classify as OnItem (was up to 8px)."""
    h = int(row_height)
    if h <= 0:
        return 1
    return max(1, min(2, h // 8))


class DestinationPlanningTreeView(QTreeView):
    """QTreeView + model path; manual planning drag — no model/Qt default drag pipeline."""

    proposedBranchMoveRequested = Signal(object, object)

    def __init__(self, parent=None):
        super().__init__(parent)
        self._dd_press_pos = QPoint()
        self._dd_press_index = QModelIndex()
        self._manual_drag_source_persistent = QPersistentModelIndex()
        self._dd_drag_active = False
        self._manualdrag_hover_sig = None
        self._manual_override_cursor = False
        self._dd_overlay_ref = QPersistentModelIndex()
        self._dd_overlay_commit = QPersistentModelIndex()
        self._dd_overlay_dip = QAbstractItemView.DropIndicatorPosition.OnItem
        self._drop_highlight = None
        self._drop_line = None
        self._init_destination_drag_overlay_widgets()
        self.verticalScrollBar().valueChanged.connect(self._destination_drag_on_scroll)
        self.horizontalScrollBar().valueChanged.connect(self._destination_drag_on_scroll)
        self.verticalScrollBar().valueChanged.connect(self._destination_planning_tree_scroll_activity_bump)
        self.horizontalScrollBar().valueChanged.connect(self._destination_planning_tree_scroll_activity_bump)
        self.verticalScrollBar().sliderPressed.connect(self._destination_planning_tree_scroll_activity_bump)
        self.verticalScrollBar().actionTriggered.connect(self._destination_planning_tree_scroll_activity_bump)
        self.horizontalScrollBar().sliderPressed.connect(self._destination_planning_tree_scroll_activity_bump)
        self.horizontalScrollBar().actionTriggered.connect(self._destination_planning_tree_scroll_activity_bump)

    def _destination_planning_tree_scroll_activity_bump(self, *_args):
        mw = getattr(self, "_ozlink_main_window", None)
        if mw is not None:
            fn = getattr(mw, "_destination_note_destination_tree_scroll_activity", None)
            if callable(fn):
                fn()

    def wheelEvent(self, event):
        mw = getattr(self, "_ozlink_main_window", None)
        if mw is not None:
            prof = getattr(mw, "_dest_scroll_profiler", None)
            if prof is not None:
                prof.note_scroll("wheelEvent")
            fn = getattr(mw, "_destination_note_destination_tree_scroll_activity", None)
            if callable(fn):
                fn()
        super().wheelEvent(event)

    def scrollContentsBy(self, dx, dy):
        mw = getattr(self, "_ozlink_main_window", None)
        if mw is not None:
            prof = getattr(mw, "_dest_scroll_profiler", None)
            if prof is not None:
                prof.note_scroll("scrollContentsBy")
        super().scrollContentsBy(dx, dy)

    def _init_destination_drag_overlay_widgets(self):
        vp = self.viewport()
        hl = QFrame(vp)
        hl.setVisible(False)
        hl.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        hl.setStyleSheet(
            "background-color: rgba(64, 156, 255, 0.28); border: 1px solid rgba(64, 156, 255, 0.85); border-radius: 2px;"
        )
        ln = QFrame(vp)
        ln.setVisible(False)
        ln.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        ln.setStyleSheet("background-color: rgba(64, 156, 255, 0.95);")
        ln.setFixedHeight(2)
        hl.raise_()
        ln.raise_()
        self._drop_highlight = hl
        self._drop_line = ln

    def _destination_drag_on_scroll(self, *_args):
        if self._dd_drag_active:
            self._reposition_destination_drop_overlay_widgets()

    def _hide_destination_drop_overlay(self):
        if self._drop_highlight is not None:
            self._drop_highlight.setVisible(False)
        if self._drop_line is not None:
            self._drop_line.setVisible(False)
        self._dd_overlay_ref = QPersistentModelIndex()
        self._dd_overlay_commit = QPersistentModelIndex()

    def _reposition_destination_drop_overlay_widgets(self):
        if not self._dd_drag_active or self._drop_highlight is None or self._drop_line is None:
            return
        if not self._dd_overlay_commit.isValid():
            self._hide_destination_drop_overlay()
            return
        vp = self.viewport()
        w = vp.width()
        on_item = QAbstractItemView.DropIndicatorPosition.OnItem
        above_item = QAbstractItemView.DropIndicatorPosition.AboveItem
        below_item = QAbstractItemView.DropIndicatorPosition.BelowItem
        if self._dd_overlay_dip in (above_item, below_item) and self._dd_overlay_ref.isValid():
            r = self.visualRect(QModelIndex(self._dd_overlay_ref))
            if not r.isValid() or r.height() <= 0:
                self._hide_destination_drop_overlay()
                return
            y = r.top() if self._dd_overlay_dip == above_item else r.bottom()
            self._drop_line.setGeometry(0, max(0, y - 1), w, 2)
            self._drop_line.setVisible(True)
            self._drop_highlight.setVisible(False)
        else:
            cix = QModelIndex(self._dd_overlay_commit)
            r = self.visualRect(cix)
            if not r.isValid() or r.height() <= 0:
                self._hide_destination_drop_overlay()
                return
            self._drop_highlight.setGeometry(0, r.top(), w, r.height())
            self._drop_highlight.setVisible(True)
            self._drop_line.setVisible(False)

    def _drop_band_at_pos_view(self, pos: QPoint) -> tuple[QModelIndex, int]:
        ix = self.indexAt(pos)
        if not ix.isValid():
            return QModelIndex(), QAbstractItemView.DropIndicatorPosition.OnViewport.value
        ix0 = ix.siblingAtColumn(0) if ix.column() != 0 else ix
        r = self.visualRect(ix0)
        if not r.isValid() or r.height() <= 0:
            return ix0, QAbstractItemView.DropIndicatorPosition.OnItem.value
        y = pos.y() - r.top()
        h = r.height()
        margin = _destination_drop_band_margin_px(h)
        if y < margin:
            dip = QAbstractItemView.DropIndicatorPosition.AboveItem
        elif y >= h - margin:
            dip = QAbstractItemView.DropIndicatorPosition.BelowItem
        else:
            dip = QAbstractItemView.DropIndicatorPosition.OnItem
        return ix0, dip.value

    def _planning_manual_source_path_view(self) -> str:
        mw = getattr(self, "_ozlink_main_window", None)
        six = QModelIndex(self._manual_drag_source_persistent)
        if mw is None or not six.isValid():
            return ""
        node = mw.get_tree_item_node_data(six) or {}
        return str(mw._destination_row_semantic_path(node) or "")[:240]

    def _planning_manual_cleanup_view(self) -> None:
        try:
            self.viewport().releaseMouse()
        except Exception:
            pass
        if self._manual_override_cursor:
            self._manual_override_cursor = False
            QApplication.restoreOverrideCursor()
        self._dd_drag_active = False
        self._manual_drag_source_persistent = QPersistentModelIndex()
        self._manualdrag_hover_sig = None
        self._hide_destination_drop_overlay()
        self.viewport().update()

    def _planning_manual_cancel_view(self, reason: str) -> None:
        if not self._dd_drag_active:
            return
        _manualdrag_log(
            "cancel",
            tree_class="QTreeView",
            source_path=self._planning_manual_source_path_view()[:200],
            reject_reason=reason,
        )
        self._planning_manual_cleanup_view()

    def _planning_manual_begin_view(self, source_index: QModelIndex) -> None:
        mw = getattr(self, "_ozlink_main_window", None)
        if mw is None or not source_index.isValid():
            return
        node = mw.get_tree_item_node_data(source_index) or {}
        start_path = str(mw._destination_row_semantic_path(node) or "")[:240]
        self._manual_drag_source_persistent = QPersistentModelIndex(source_index)
        self._dd_drag_active = True
        self._manualdrag_hover_sig = None
        try:
            self.viewport().grabMouse()
        except Exception:
            pass
        QApplication.setOverrideCursor(Qt.CursorShape.ClosedHandCursor)
        self._manual_override_cursor = True
        if is_dev_mode():
            log_info(
                "debug_pass_destination_manual_drag",
                phase="drag_start",
                tree="QTreeView",
                drag_start_path=start_path,
            )
        _manualdrag_log("drag_begin", tree_class="QTreeView", source_path=start_path[:200])
        try:
            pos_vp = self.viewport().mapFromGlobal(QCursor.pos())
        except Exception:
            pos_vp = QPoint(0, 0)
        self._planning_manual_update_hover_view(pos_vp)

    def _planning_manual_hover_signature_view(self, mw, pos, ref_ix, dip, commit_ix, meta) -> tuple:
        vp = self.viewport()
        if mw is None:
            return ("no_mw",)
        if not ref_ix.isValid():
            return ("provisional_viewport",) if vp.rect().contains(pos) else ("outside",)
        mode = str((meta or {}).get("indicator_mode", ""))
        htype = str((meta or {}).get("hover_row_type", ""))
        hp = str((meta or {}).get("hovered_path", ""))[:200]
        if commit_ix is None or not commit_ix.isValid():
            return ("provisional_unresolved", hp, mode, str((meta or {}).get("drop_rejected_reason", "")))
        resolved = str((meta or {}).get("resolved_target_path", ""))[:240]
        return ("commit", resolved, mode, htype, dip.value)

    def _planning_manual_update_hover_view(self, pos: QPoint) -> None:
        mw = getattr(self, "_ozlink_main_window", None)
        ref_ix, dip_int = self._drop_band_at_pos_view(pos)
        dip = QAbstractItemView.DropIndicatorPosition(dip_int)
        meta: dict = {}
        commit_ix = QModelIndex()
        if mw is None:
            self._hide_destination_drop_overlay()
        elif not ref_ix.isValid():
            self._hide_destination_drop_overlay()
        else:
            cand, meta = mw._resolve_destination_manual_drop_folder_index(ref_ix, dip)
            if cand is None or not cand.isValid():
                commit_ix = QModelIndex()
                self._hide_destination_drop_overlay()
            else:
                commit_ix = cand
                self._dd_overlay_ref = QPersistentModelIndex(ref_ix)
                self._dd_overlay_commit = QPersistentModelIndex(commit_ix)
                self._dd_overlay_dip = dip
                self._reposition_destination_drop_overlay_widgets()
        sig = self._planning_manual_hover_signature_view(mw, pos, ref_ix, dip, commit_ix, meta)
        if sig != self._manualdrag_hover_sig:
            self._manualdrag_hover_sig = sig
            hover_path = str(meta.get("hovered_path", ""))[:200] if meta else ""
            resolved = str(meta.get("resolved_target_path", ""))[:240] if meta else ""
            cnode = mw.get_tree_item_node_data(commit_ix) if mw is not None and commit_ix.isValid() else None
            dnode = cnode
            if dnode is None and mw is not None and ref_ix.isValid():
                dnode = mw.get_tree_item_node_data(ref_ix) or None
            tgt_fields = _manualdrag_commit_target_fields(mw, cnode)
            diag = _manualdrag_destination_row_diagnostics(mw, dnode)
            _manualdrag_log(
                "hover_update",
                tree_class="QTreeView",
                source_path=self._planning_manual_source_path_view()[:200],
                hover_path=hover_path,
                resolved_target_path=resolved,
                hover_mode=repr(sig),
                drop_indicator=dip.value,
                commit_preview=commit_ix.isValid(),
                commit_allowed="yes" if commit_ix.isValid() else "no",
                reject_reason=str(meta.get("drop_rejected_reason", ""))[:120] if meta else "",
                target_row_type=tgt_fields["target_row_type"],
                allocated_flag=tgt_fields["allocated_flag"],
                **diag,
            )

    def _planning_manual_finish_view(self, pos: QPoint) -> None:
        mw = getattr(self, "_ozlink_main_window", None)
        source_ix = QModelIndex(self._manual_drag_source_persistent)
        ref_ix, dip_int = self._drop_band_at_pos_view(pos)
        dip = QAbstractItemView.DropIndicatorPosition(dip_int)
        meta: dict = {}
        target_ix = QModelIndex()
        if mw is not None and ref_ix.isValid():
            cand, meta = mw._resolve_destination_manual_drop_folder_index(ref_ix, dip)
            if cand is not None and cand.isValid():
                target_ix = cand
        committed_path = str(meta.get("resolved_target_path", ""))[:240]
        hover_path = str(meta.get("hovered_path", ""))[:200]
        mode = str(meta.get("indicator_mode", ""))
        htype = str(meta.get("hover_row_type", ""))
        if is_dev_mode():
            log_info(
                "debug_pass_destination_manual_drag",
                phase="drop",
                tree="QTreeView",
                drag_mime_seen=False,
                hover_row_path=hover_path,
                hover_row_type=htype,
                indicator_mode=mode,
                drop_indicator=dip.value,
                resolved_target_path=str(meta.get("resolved_target_path", ""))[:200],
                drop_committed_path=committed_path[:200],
                drop_rejected_reason=str(meta.get("drop_rejected_reason", "")),
                rejection_reason=str(meta.get("drop_rejected_reason", "")),
                accepted_drop_action="Move" if target_ix.isValid() else "",
            )
        if not source_ix.isValid() or not target_ix.isValid() or source_ix == target_ix:
            tnode_r = mw.get_tree_item_node_data(target_ix) if mw is not None and target_ix.isValid() else None
            tf_r = _manualdrag_commit_target_fields(mw, tnode_r)
            dr_r = _manualdrag_destination_row_diagnostics(mw, tnode_r)
            _manualdrag_log(
                "release_reject",
                tree_class="QTreeView",
                source_path=self._planning_manual_source_path_view()[:200],
                hover_path=hover_path,
                resolved_target_path=committed_path,
                hover_mode=mode or htype,
                commit="no",
                commit_allowed="no",
                reject_reason=str(meta.get("drop_rejected_reason", ""))[:160] if meta else "no_target",
                target_row_type=tf_r["target_row_type"],
                allocated_flag=tf_r["allocated_flag"],
                **dr_r,
            )
            self._planning_manual_cleanup_view()
            return
        tnode_ok = mw.get_tree_item_node_data(target_ix) if mw is not None else None
        tf_ok = _manualdrag_commit_target_fields(mw, tnode_ok)
        dr_ok = _manualdrag_destination_row_diagnostics(mw, tnode_ok)
        _manualdrag_log(
            "release_commit",
            tree_class="QTreeView",
            source_path=self._planning_manual_source_path_view()[:200],
            hover_path=hover_path,
            resolved_target_path=committed_path,
            hover_mode=mode or htype,
            commit="yes",
            commit_allowed="yes",
            reject_reason="",
            target_row_type=tf_ok["target_row_type"],
            allocated_flag=tf_ok["allocated_flag"],
            **dr_ok,
        )
        self.proposedBranchMoveRequested.emit(source_ix, target_ix)
        self._planning_manual_cleanup_view()

    def mousePressEvent(self, event):
        if self._dd_drag_active:
            return
        super().mousePressEvent(event)
        if event.button() != Qt.MouseButton.LeftButton:
            self._dd_press_index = QModelIndex()
            return
        self._dd_press_pos = self.viewport().mapFromGlobal(event.globalPosition().toPoint())
        self._dd_press_index = self.indexAt(self._dd_press_pos)
        ix = (
            self._dd_press_index.siblingAtColumn(0)
            if self._dd_press_index.column() != 0
            else self._dd_press_index
        )
        mw = getattr(self, "_ozlink_main_window", None)
        if mw is not None and ix.isValid() and mw.destination_planning_row_allows_manual_drag_index(ix):
            node = mw.get_tree_item_node_data(ix) or {}
            sp = str(mw._destination_row_semantic_path(node) or "")[:200]
            _manualdrag_log("press_candidate", tree_class="QTreeView", source_path=sp)

    def mouseMoveEvent(self, event):
        if self._dd_drag_active:
            pos_vp = self.viewport().mapFromGlobal(event.globalPosition().toPoint())
            self._planning_manual_update_hover_view(pos_vp)
            event.accept()
            return
        if (
            self._dd_press_index.isValid()
            and (event.buttons() & Qt.MouseButton.LeftButton)
            and (
                self.viewport().mapFromGlobal(event.globalPosition().toPoint()) - self._dd_press_pos
            ).manhattanLength()
            >= QApplication.startDragDistance()
        ):
            ix = (
                self._dd_press_index.siblingAtColumn(0)
                if self._dd_press_index.column() != 0
                else self._dd_press_index
            )
            mw = getattr(self, "_ozlink_main_window", None)
            if mw is not None and mw.destination_planning_row_allows_manual_drag_index(ix):
                self._dd_press_index = QModelIndex()
                self._planning_manual_begin_view(ix)
                return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton and self._dd_drag_active:
            pos_vp = self.viewport().mapFromGlobal(event.globalPosition().toPoint())
            self._planning_manual_finish_view(pos_vp)
            event.accept()
            return
        if event.button() == Qt.MouseButton.LeftButton:
            self._dd_press_index = QModelIndex()
        super().mouseReleaseEvent(event)

    def leaveEvent(self, event):
        if self._dd_drag_active:
            self._planning_manual_cancel_view("leave_view")
        super().leaveEvent(event)

    def keyPressEvent(self, event):
        if self._dd_drag_active and event.key() == Qt.Key.Key_Escape:
            self._planning_manual_cancel_view("escape")
            event.accept()
            return
        super().keyPressEvent(event)


