class DeviceFlowPromptDialog(QDialog):
    cancel_requested = Signal()

    def __init__(self, parent=None):
        super().__init__(parent)
        self._service_context = ""
        self.setWindowTitle("Microsoft 365 Sign-In")
        self.setModal(False)
        self.setMinimumWidth(560)
        self.setObjectName("DeviceFlowPromptDialog")
        self._wait_seconds = 0
        self._wait_timer = QTimer(self)
        self._wait_timer.setInterval(1000)
        self._wait_timer.timeout.connect(self._tick_wait_counter)

        layout = QVBoxLayout(self)
        layout.setContentsMargins(20, 18, 20, 18)
        layout.setSpacing(10)

        self.title_label = QLabel("Microsoft 365 sign-in")
        self.title_label.setObjectName("SectionTitle")
        self.title_label.setWordWrap(True)

        self.message_primary_label = QLabel("")
        self.message_primary_label.setObjectName("CardBody")
        self.message_primary_label.setWordWrap(True)

        self.message_emphasis_label = QLabel("")
        self.message_emphasis_label.setObjectName("CardBody")
        self.message_emphasis_label.setWordWrap(True)

        self.message_secondary_label = QLabel("")
        self.message_secondary_label.setObjectName("CardBody")
        self.message_secondary_label.setWordWrap(True)

        self.status_label = QLabel("")
        self.status_label.setObjectName("MutedText")
        self.status_label.setWordWrap(True)
        self._pulse_phase = 0

        actions = QHBoxLayout()
        actions.setContentsMargins(0, 0, 0, 0)
        actions.addStretch()

        self.cancel_button = QPushButton("Cancel")
        self.cancel_button.setMinimumWidth(84)

        self.cancel_button.clicked.connect(self._on_cancel_clicked)

        actions.addWidget(self.cancel_button)

        layout.addWidget(self.title_label)
        layout.addWidget(self.message_primary_label)
        layout.addWidget(self.message_emphasis_label)
        layout.addWidget(self.message_secondary_label)
        layout.addWidget(self.status_label)
        layout.addLayout(actions)

    def _on_cancel_clicked(self):
        self.cancel_requested.emit()

    def _tick_wait_counter(self):
        self._wait_seconds += 1
        if self._wait_seconds >= 45:
            self.status_label.setText(
                f"Still contacting Microsoft… {self._wait_seconds}s. "
                "If this never finishes, check internet, VPN, or firewall/proxy allowing login.microsoftonline.com."
            )
        else:
            self.status_label.setText(f"Contacting Microsoft to start sign-in… {self._wait_seconds}s")
        self._pulse_phase += 1
        self._apply_pulse_styles()

    def _apply_pulse_styles(self):
        red_palette = ["#FF9DA0", "#FF858A", "#FFB3B5"]
        green_palette = ["#6DE7A0", "#59D88F", "#8DF0B8"]
        self.message_emphasis_label.setStyleSheet(
            f"color:{red_palette[self._pulse_phase % len(red_palette)]}; font-weight:700; font-size:11pt;"
        )
        self.message_secondary_label.setStyleSheet(
            f"color:{green_palette[self._pulse_phase % len(green_palette)]}; font-weight:700; font-size:11pt;"
        )
        self.status_label.setStyleSheet("color:#B7C9EE; font-weight:600; font-size:11pt;")

    def set_service_context(self, context: str) -> None:
        self._service_context = (context or "").strip()

    def _sign_in_headline(self, entered_email: str) -> tuple[str, str]:
        ctx = getattr(self, "_service_context", "") or ""
        if ctx == "destination_sharepoint":
            headline = "Microsoft 365 for destination SharePoint"
        elif ctx == "source_sharepoint":
            headline = "Microsoft 365 for source SharePoint"
        else:
            headline = "Microsoft 365 sign-in"
        email = (entered_email or "").strip()
        if email:
            label = f"{headline}\nAccount: {email}"
        else:
            label = headline
        window_title = "Secure sign-in — Microsoft 365" if ctx else "Microsoft 365 Sign-In"
        return label, window_title

    def set_prompt_state(self, entered_email="", *, stage="waiting"):
        label, window_title = self._sign_in_headline(entered_email)
        self.title_label.setText(label)
        self.setWindowTitle(window_title)

        if stage == "opened":
            self._wait_timer.stop()
            self.message_primary_label.setText("")
            self.message_emphasis_label.setText("")
            self.message_secondary_label.setText("")
            self.status_label.setText(
                "Microsoft sign-in opened. Your device code is copied to the clipboard. "
                "Press Ctrl+V in the browser sign-in page."
            )
            self.status_label.setStyleSheet("color:#59D88F; font-weight:700; font-size:11pt;")
            self.cancel_button.hide()
        elif stage == "ready":
            self._wait_timer.stop()
            self.message_primary_label.setText("")
            self.message_emphasis_label.setText("")
            self.message_secondary_label.setText("")
            self.status_label.setText(
                "Microsoft sign-in opened. Your device code is copied to the clipboard. "
                "Press Ctrl+V in the browser sign-in page."
            )
            self.status_label.setStyleSheet("color:#59D88F; font-weight:700; font-size:11pt;")
            self.cancel_button.show()
        else:
            self.message_primary_label.setText(
                "Contacting Microsoft to start device sign-in. This step uses the network and may take a little while."
            )
            self.message_emphasis_label.setText(
                "When Microsoft responds, your default browser should open to the sign-in page automatically."
            )
            self.message_secondary_label.setText(
                "Your device code will be copied to the clipboard — paste it with Ctrl+V on that page when asked."
            )
            self._wait_seconds = 0
            self._pulse_phase = 0
            self.status_label.setText("Contacting Microsoft to start sign-in… 0s")
            self._apply_pulse_styles()
            if not self._wait_timer.isActive():
                self._wait_timer.start()
            self.cancel_button.show()


class ArrowComboBox(QComboBox):
    def paintEvent(self, event):
        super().paintEvent(event)

        arrow_box_width = 28
        rect = self.rect().adjusted(self.width() - arrow_box_width, 0, -1, -1)
        painter = QPainter(self)
        painter.setRenderHint(QPainter.Antialiasing)
        painter.setPen(QColor("#2C456F"))
        painter.drawLine(rect.left(), 4, rect.left(), rect.bottom() - 4)
        painter.setBrush(QColor("#EAF0FF"))
        painter.setPen(Qt.NoPen)
        center_x = rect.center().x()
        center_y = rect.center().y() + 1
        painter.drawPolygon(QPolygon([
            QPoint(center_x - 5, center_y - 2),
            QPoint(center_x + 5, center_y - 2),
            QPoint(center_x, center_y + 4),
        ]))
        painter.end()


class SourceTreeRelationshipDelegate(QStyledItemDelegate):
    def __init__(self, window, parent=None):
        super().__init__(parent)
        self.window = window

    def paint(self, painter, option, index):
        node_data = index.data(Qt.UserRole) or {}
        excluded = self.window._plan_leaf_exclusion_display_active("source", node_data)
        relationship = self.window.get_source_relationship_display(node_data)
        if relationship["mode"] == "none" and not excluded:
            super().paint(painter, option, index)
            return

        custom_option = QStyleOptionViewItem(option)
        self.initStyleOption(custom_option, index)
        base_text = self.window.get_source_item_display_name(node_data, custom_option.text)
        suffix_text = relationship["suffix"] if relationship["mode"] != "none" else ""
        if excluded:
            base_text = f"\u2298 {base_text}"
        custom_option.text = ""

        style = custom_option.widget.style() if custom_option.widget else QApplication.style()
        style.drawControl(QStyle.CE_ItemViewItem, custom_option, painter, custom_option.widget)

        text_rect = style.subElementRect(QStyle.SE_ItemViewItemText, custom_option, custom_option.widget)
        if not text_rect.isValid():
            text_rect = custom_option.rect.adjusted(4, 0, -4, 0)

        painter.save()
        painter.setClipRect(text_rect)

        font = QFont(custom_option.font)
        if excluded:
            font.setStrikeOut(True)
        painter.setFont(font)
        metrics = painter.fontMetrics()
        spacing = 8
        drawn_base = base_text
        drawn_base_width = metrics.horizontalAdvance(drawn_base)
        drawn_suffix = suffix_text

        if excluded:
            base_color = QColor("#9AA0A6")
            if custom_option.state & QStyle.State_Selected:
                base_color = QColor("#C8CED4")
        else:
            base_color = QColor("#FFFFFF")
        suffix_color = QColor("#59D88F") if relationship["mode"] == "direct" else QColor("#79B7FF")
        if custom_option.state & QStyle.State_Selected:
            suffix_color = QColor("#C8F7DA") if relationship["mode"] == "direct" else QColor("#D6E8FF")

        painter.setPen(base_color)
        painter.drawText(text_rect, Qt.AlignVCenter | Qt.AlignLeft, drawn_base)

        if drawn_suffix:
            suffix_x = text_rect.x() + drawn_base_width + spacing
            suffix_rect = QRect(suffix_x, text_rect.y(), max(text_rect.right() - suffix_x, 0), text_rect.height())
            painter.setPen(suffix_color)
            painter.drawText(suffix_rect, Qt.AlignVCenter | Qt.AlignLeft, drawn_suffix)
        painter.restore()


class DestinationPlanningTreeDelegate(QStyledItemDelegate):
    """Muted strikethrough + glyph for source files excluded from the plan (destination projection)."""

    def __init__(self, window, parent=None):
        super().__init__(parent)
        self.window = window

    def paint(self, painter, option, index):
        prof = getattr(self.window, "_dest_scroll_profiler", None)
        _t0 = None
        if prof is not None and prof.should_record_fine_grained():
            _t0 = time.perf_counter()
        try:
            # Delegate is installed for column 0 only; keep exclusion fast-path when no plan-leaf exclusions.
            if not (getattr(self.window, "_plan_leaf_exclusions", None) or set()):
                super().paint(painter, option, index)
                return
            model = index.model()
            if isinstance(model, DestinationPlanningTreeModel):
                excluded = bool(index.data(DESTINATION_PLAN_LEAF_EXCLUSION_PAINT_ROLE))
            else:
                node_data_probe = index.data(Qt.UserRole) or {}
                excluded = self.window._plan_leaf_exclusion_display_active("destination", node_data_probe)
            if not excluded:
                super().paint(painter, option, index)
                return

            node_data = index.data(Qt.UserRole) or {}
            custom_option = QStyleOptionViewItem(option)
            self.initStyleOption(custom_option, index)
            base_text = self.window.get_source_item_display_name(node_data, custom_option.text)
            display = f"\u2298 {base_text}"
            custom_option.text = ""

            style = custom_option.widget.style() if custom_option.widget else QApplication.style()
            style.drawControl(QStyle.CE_ItemViewItem, custom_option, painter, custom_option.widget)

            text_rect = style.subElementRect(QStyle.SE_ItemViewItemText, custom_option, custom_option.widget)
            if not text_rect.isValid():
                text_rect = custom_option.rect.adjusted(4, 0, -4, 0)

            painter.save()
            painter.setClipRect(text_rect)
            font = QFont(custom_option.font)
            font.setStrikeOut(True)
            painter.setFont(font)
            base_color = QColor("#9AA0A6")
            if custom_option.state & QStyle.State_Selected:
                base_color = QColor("#C8CED4")
            painter.setPen(base_color)
            painter.drawText(text_rect, Qt.AlignVCenter | Qt.AlignLeft, display)
            painter.restore()
        finally:
            if _t0 is not None:
                prof.record(
                    "paint",
                    "DestinationPlanningTreeDelegate.paint",
                    time.perf_counter() - _t0,
                )

    def setModelData(self, editor, model, index):
        if (
            isinstance(model, DestinationPlanningTreeModel)
            and index.isValid()
            and index.column() == 0
        ):
            nd = index.data(Qt.UserRole) or {}
            if nd.get("_inline_new_proposed") or nd.get("_inline_rename_proposed"):
                if isinstance(editor, QLineEdit):
                    text = editor.text().strip()
                    self.window._commit_destination_inline_proposed_model_index(index, text)
                    return
        super().setModelData(editor, model, index)


class ManifestRunWorker(QThread):
    """Runs transfer_job_runner on a manifest in a background thread."""

    finished_ok = Signal(object)
    failed = Signal(str)

    def __init__(self, manifest: dict, *, dry_run: bool, log_file: str, graph_client=None):
        super().__init__()
        self._manifest = manifest
        self._dry_run = dry_run
        self._log_file = log_file
        self._graph_client = graph_client

    def run(self):
        try:
            from pathlib import Path

            from ozlink_console.transfer_job_runner import run_manifest_local_filesystem

            lp = Path(self._log_file)
            audit_file = str(lp.with_suffix(".audit.jsonl"))
            job_report_file = str(lp.parent / f"{lp.stem}_report.json")

            result = run_manifest_local_filesystem(
                self._manifest,
                dry_run=self._dry_run,
                log_file=self._log_file,
                audit_file=audit_file,
                job_report_file=job_report_file,
                graph_client=self._graph_client,
            )
            self.finished_ok.emit(result)
        except Exception as exc:
            self.failed.emit(str(exc))


class SnapshotPipelineRunWorker(QThread):
    """Runs ``ExecutionOrchestrator.run_snapshot`` (harness-backed) off the UI thread."""

    finished_ok = Signal(object, object)
    failed = Signal(str)

    def __init__(
        self,
        *,
        bundle_folder: str,
        manifest_path: str,
        environment_context: dict,
        graph_client=None,
        dry_run: bool = True,
        snapshot_scoped_mode: str = "",
        scoped_seed_mapping_ids: frozenset | None = None,
    ):
        super().__init__()
        self._bundle_folder = str(bundle_folder or "")
        self._manifest_path = str(manifest_path or "")
        self._environment_context = dict(environment_context or {})
        self._graph_client = graph_client
        self._dry_run = bool(dry_run)
        self._snapshot_scoped_mode = str(snapshot_scoped_mode or "").strip()
        self._scoped_seed_mapping_ids = scoped_seed_mapping_ids

    def run(self):
        try:
            from ozlink_console.execution import ExecutionOrchestrator

            orch = ExecutionOrchestrator()
            ctx, result = orch.run_snapshot(
                manifest_path=self._manifest_path,
                bundle_folder=self._bundle_folder,
                dry_run=self._dry_run,
                environment_context=self._environment_context,
                graph_client=self._graph_client,
                snapshot_scoped_mode=self._snapshot_scoped_mode,
                scoped_seed_mapping_ids=self._scoped_seed_mapping_ids,
            )
            self.finished_ok.emit(ctx, result)
        except Exception as exc:
            self.failed.emit(str(exc))


def _m365_sign_in_error_dialog(message: str) -> tuple[str, str]:
    """Return (title, text) for sign-in failures so DNS/network issues read clearly."""
    raw = str(message or "")
    lm = raw.lower()
    if (
        "getaddrinfo failed" in lm
        or "failed to resolve" in lm
        or "nameresolutionerror" in lm
        or "[errno 11001]" in lm
    ):
        return (
            "Cannot reach Microsoft sign-in",
            "Your PC could not look up Microsoft's sign-in address on the network. That usually means "
            "no internet connection, a DNS problem, or a firewall/VPN blocking access to "
            "login.microsoftonline.com.\n\n"
            "What to try:\n"
            "• Open a normal website in a browser to confirm you have internet.\n"
            "• Open https://login.microsoftonline.com in a browser. If that fails too, fix network or DNS first.\n"
            "• On corporate networks, ask IT whether sign-in to Microsoft 365 is allowed from your PC.\n"
            "• Reconnect Wi‑Fi or set DNS to automatic (or try 1.1.1.1 / 8.8.8.8).\n\n"
            f"Technical details:\n{raw}",
        )
    if "max retries exceeded" in lm or "connection refused" in lm or "connection aborted" in lm:
        return (
            "Cannot reach Microsoft sign-in",
            "The app could not complete a connection to Microsoft's servers. Check internet, VPN, proxy, and firewall settings.\n\n"
            f"Technical details:\n{raw}",
        )
    return ("Error", raw)


_JSON_PERSIST_OMIT = object()

# Throttle perf_explorer JSON lines in --dev (high-volume path lookups were flooding logs and I/O).
_perf_explorer_log_last_ts: dict[str, float] = {}


def _perf_explorer_throttle_interval_sec() -> float:
    raw = os.environ.get("OZLINK_PERF_EXPLORER_LOG_MIN_INTERVAL_MS", "2000").strip()
    try:
        ms = int(raw)
    except ValueError:
        ms = 2000
    if ms <= 0:
        return 0.0
    return max(0.05, float(ms) / 1000.0)


def _perf_explorer_throttle_key(phase: str, kwargs: dict[str, Any]) -> str:
    if phase in (
        "find_visible_source_item_by_path",
        "find_visible_destination_item_by_path",
    ):
        return f"{phase}\0{kwargs.get('match') or ''}"
    if phase == "refresh_source_projection_for_paths":
        return f"{phase}\0{kwargs.get('phase_name') or ''}\0{kwargs.get('chunked')!r}"
    if phase in ("materialize_destination_future_model", "destination_real_tree_snapshot_refresh_skipped"):
        return f"{phase}\0{kwargs.get('reason') or ''}"
    parts: list[str] = []
    for k in sorted(kwargs):
        if k == "elapsed_ms":
            continue
        parts.append(f"{k}={kwargs[k]!r}")
    return f"{phase}\0" + "|".join(parts)


def _perf_explorer_log(phase: str, **kwargs: Any) -> None:
    """Dev-only structured timing/diagnostic events for explorer responsiveness work.

    Throttled per (phase, coarse key) to avoid log storms under ``--dev``; set
    ``OZLINK_PERF_EXPLORER_LOG_MIN_INTERVAL_MS`` (default 2000) or ``0`` for every event.
    """
    if not is_dev_mode():
        return
    interval = _perf_explorer_throttle_interval_sec()
    if interval <= 0:
        log_info("perf_explorer", phase=phase, **kwargs)
        return
    key = _perf_explorer_throttle_key(phase, kwargs)
    now = time.monotonic()
    last = _perf_explorer_log_last_ts.get(key, 0.0)
    if now - last < interval:
        return
    _perf_explorer_log_last_ts[key] = now
    log_info("perf_explorer", phase=phase, **kwargs)


class _PerfExplorerTimer:
    """Context manager: logs perf_explorer with elapsed_ms on exit (dev-only)."""

    __slots__ = ("phase", "extra", "_timer")

    def __init__(self, phase: str, **extra: Any):
        self.phase = phase
        self.extra = extra
        self._timer: QElapsedTimer | None = None

    def __enter__(self):
        if is_dev_mode():
            self._timer = QElapsedTimer()
            self._timer.start()
        return self

    def __exit__(self, exc_type, exc, tb):
        if is_dev_mode() and self._timer is not None:
            _perf_explorer_log(self.phase, elapsed_ms=self._timer.elapsed(), **self.extra)
        return False


class FramelessTitleBar(QWidget):
    """Minimal desktop-style title strip (VS Code–like): drag, double-click maximize, sys buttons."""

    def __init__(self, main_window: QMainWindow):
        super().__init__(main_window)
        self._main = main_window
        self.setObjectName("FramelessTitleBar")
        self.setFixedHeight(32)
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)

        self._drag_anchor: QPointF | None = None
        self._window_start_geo: QRect | None = None

        layout = QHBoxLayout(self)
        layout.setContentsMargins(12, 0, 2, 0)
        layout.setSpacing(8)

        self._title_label = QLabel(main_window._base_window_title)
        self._title_label.setObjectName("TitleBarCaptionLabel")
        self._title_label.setAlignment(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft)
        self._title_label.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Preferred)
        self._title_label.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        layout.addWidget(self._title_label, 1)

        def _mk_btn(text: str, obj_name: str, tip: str) -> QPushButton:
            b = QPushButton(text)
            b.setObjectName(obj_name)
            b.setFixedSize(46, 32)
            b.setFocusPolicy(Qt.FocusPolicy.NoFocus)
            b.setCursor(QCursor(Qt.CursorShape.ArrowCursor))
            b.setToolTip(tip)
            return b

        self._btn_min = _mk_btn("\u2014", "TitleBarSysButton", "Minimize")
        self._btn_max = _mk_btn("\u25a1", "TitleBarSysButton", "Maximize")
        self._btn_close = _mk_btn("\u2715", "TitleBarCloseButton", "Close")

        self._btn_min.clicked.connect(self._main.showMinimized)
        self._btn_max.clicked.connect(self._toggle_maximize)
        self._btn_close.clicked.connect(self._main.close)

        layout.addWidget(self._btn_min, 0, Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
        layout.addWidget(self._btn_max, 0, Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
        layout.addWidget(self._btn_close, 0, Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)

    def _toggle_maximize(self):
        if self._main.isMaximized():
            self._main.showNormal()
        else:
            self._main.showMaximized()
        self._sync_maximize_glyph()

    def _sync_maximize_glyph(self):
        if self._main.isMaximized():
            self._btn_max.setText("\u29c9")
            self._btn_max.setToolTip("Restore")
        else:
            self._btn_max.setText("\u25a1")
            self._btn_max.setToolTip("Maximize")

    def _is_on_sys_button(self, pos: QPoint) -> bool:
        return any(
            btn.geometry().contains(pos)
            for btn in (self._btn_min, self._btn_max, self._btn_close)
        )

    def mousePressEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            if self._is_on_sys_button(event.position().toPoint()):
                return super().mousePressEvent(event)
            if self._main.isMaximized():
                self._main.showNormal()
            self._drag_anchor = event.globalPosition()
            self._window_start_geo = self._main.frameGeometry()
            event.accept()
            return
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event):
        if (
            event.buttons() & Qt.MouseButton.LeftButton
            and self._drag_anchor is not None
            and self._window_start_geo is not None
        ):
            delta = event.globalPosition() - self._drag_anchor
            self._main.move(self._window_start_geo.topLeft() + delta.toPoint())
            event.accept()
            return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event):
        self._drag_anchor = None
        self._window_start_geo = None
        super().mouseReleaseEvent(event)

    def mouseDoubleClickEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            if self._is_on_sys_button(event.position().toPoint()):
                return super().mouseDoubleClickEvent(event)
            self._toggle_maximize()
            event.accept()
            return
        super().mouseDoubleClickEvent(event)


