# Full destination semantic bind/reconcile reasons deferred while folder workers
# or pending loads are active (coalesced; one flush after stabilize).
_DESTINATION_BIND_RECONCILE_GATE_REASONS = frozenset(
    {
        "destination_bind_sync_model",
        "destination_bind_post_hydrate_sync_model",
        "destination_bind_post_hydrate_chunked_lazy",
        "destination_bind_chunked_async",
        "destination_restore_queue_bootstrap",
    }
)


class _ReactiveNotifyList(list):
    """``list`` subclass that invokes :meth:`MainWindow._on_destination_state_mutation` on mutations (reactive invariant)."""

    __slots__ = ("_mw_ref", "_reason_prefix", "_bulk_depth")

    def __init__(self, main_window: "MainWindow", reason_prefix: str, iterable=()):
        super().__init__(iterable)
        self._mw_ref = weakref.ref(main_window)
        self._reason_prefix = reason_prefix
        self._bulk_depth = 0

    def _emit_immediate(self, reason: str) -> None:
        mw = self._mw_ref()
        if mw is None or not hasattr(mw, "_on_destination_state_mutation"):
            return
        if int(getattr(mw, "_overlay_invariant_suppress_depth", 0) or 0) > 0:
            if not getattr(mw, "_disable_overlay_invariant_timer_for_test", False):
                mw._schedule_destination_overlay_source_projection_invariant(reason)
            return
        mw._on_destination_state_mutation(reason, {"surface": self._reason_prefix})

    def _emit(self, reason: str) -> None:
        if self._bulk_depth > 0:
            return
        self._emit_immediate(reason)

    @contextmanager
    def bulk_mutation(self, reason_suffix: str = "bulk"):
        self._bulk_depth += 1
        rs = reason_suffix
        try:
            yield
        finally:
            self._bulk_depth -= 1
            if self._bulk_depth == 0:
                self._emit_immediate(f"{self._reason_prefix}_{rs}")

    def append(self, item):
        super().append(item)
        self._emit(f"{self._reason_prefix}_append")

    def extend(self, iterable):
        before = len(self)
        super().extend(iterable)
        if len(self) != before:
            self._emit(f"{self._reason_prefix}_extend")

    def pop(self, index=-1):
        r = super().pop(index)
        self._emit(f"{self._reason_prefix}_pop")
        return r

    def remove(self, value):
        super().remove(value)
        self._emit(f"{self._reason_prefix}_remove")

    def clear(self):
        if not self:
            return
        super().clear()
        self._emit(f"{self._reason_prefix}_clear")

    def sort(self, *a, **k):
        super().sort(*a, **k)
        self._emit(f"{self._reason_prefix}_sort")

    def reverse(self):
        super().reverse()
        self._emit(f"{self._reason_prefix}_reverse")

    def __setitem__(self, key, value):
        super().__setitem__(key, value)
        self._emit(f"{self._reason_prefix}_setitem")

    def __delitem__(self, key):
        super().__delitem__(key)
        self._emit(f"{self._reason_prefix}_delitem")

    def insert(self, index, item):
        super().insert(index, item)
        self._emit(f"{self._reason_prefix}_insert")

    def __iadd__(self, other):
        before = len(self)
        super().__iadd__(other)
        if len(self) != before:
            self._emit(f"{self._reason_prefix}_iadd")
        return self


def _shutdown_mutation_skip_for_host(host: Any, mutation_path: str, **extra: Any) -> bool:
    """Call :meth:`MainWindow._if_shutdown_skip_mutation` when present (partial test hosts may omit it)."""
    fn = getattr(host, "_if_shutdown_skip_mutation", None)
    if not callable(fn):
        return False
    return bool(fn(mutation_path, **extra))


# Strong refs so QThread wrappers are not destroyed while the native thread is still running after
# bounded ``wait`` during window close (avoids "QThread: Destroyed while thread is still running").
_SHUTDOWN_ORPHAN_QTHREADS: list[Any] = []


def _shutdown_orphan_qthread_finalize(worker: Any) -> None:
    # Use ``is True`` so MagicMock auto-attrs (truthy) do not short-circuit tests / odd wrappers.
    if getattr(worker, "_oz_shutdown_orphan_finalize_done", False) is True:
        return
    try:
        setattr(worker, "_oz_shutdown_orphan_finalize_done", True)
    except Exception:
        pass
    try:
        while worker in _SHUTDOWN_ORPHAN_QTHREADS:
            _SHUTDOWN_ORPHAN_QTHREADS.remove(worker)
    except Exception:
        pass
    try:
        if _shiboken_is_valid(worker):
            worker.deleteLater()
    except Exception:
        pass


