    _DEFERRED_EXPAND_MAX_PATH_RETRIES: int = 25
    _DEFERRED_EXPAND_PARK_PARENT_AFTER: int = 5
    _DEFERRED_EXPAND_ENQUEUE_DELAY_MS: int = 50
    _DEFERRED_EXPAND_TAIL_DELAY_MS: int = 50
