    def _setup_developer_menu(self):
        if not is_dev_mode():
            return
        dev_menu = self.menuBar().addMenu("Developer")
        restart = QAction("Restart App", self)
        restart.setShortcut(QKeySequence("Ctrl+Shift+R"))
        restart.triggered.connect(self._dev_restart_app)
        dev_menu.addAction(restart)
        dest_prof = QAction("Enable destination scroll profiling", self)
        dest_prof.setCheckable(True)
        with QSignalBlocker(dest_prof):
            dest_prof.setChecked(bool(getattr(self, "_dest_scroll_profile_enabled", True)))
        dest_prof.toggled.connect(self._on_dest_scroll_profile_toggled)
        dev_menu.addAction(dest_prof)
        act_visible_tree = QAction(
            "Export visible + Graph + Memory snapshot trees (session log folder, txt+json)…",
            self,
        )
        act_visible_tree.setToolTip(
            "Writes visible, graph, and raw memory snapshot trees into the current session Logs folder "
            "(visible__ / graph__ / memory__ … same timestamp). Requires dev mode (OZLINK_DEV or --dev)."
        )
        act_visible_tree.triggered.connect(self._dev_export_visible_destination_model_tree)
        dev_menu.addAction(act_visible_tree)
        truth_menu = dev_menu.addMenu("Graph truth forensic")
        act_app = QAction("Export app destination audit (JSONL)…", self)
        act_app.triggered.connect(self._dev_export_graph_truth_app_audit_jsonl)
        truth_menu.addAction(act_app)
        act_live = QAction("Export live Graph only (JSONL)…", self)
        act_live.triggered.connect(self._dev_export_graph_truth_live_graph_jsonl)
        truth_menu.addAction(act_live)
        act_bundle = QAction("Run bundle: app + live + compare…", self)
        act_bundle.triggered.connect(self._dev_run_graph_truth_bundle)
        truth_menu.addAction(act_bundle)

    def _on_dest_scroll_profile_toggled(self, checked: bool):
        self._dest_scroll_profile_enabled = bool(checked)
        QSettings().setValue("debug/dest_scroll_profile", self._dest_scroll_profile_enabled)

    def _dev_restart_app(self):
        from ozlink_console.dev_restart import respawn_and_exit

        respawn_and_exit()

    def _dev_graph_truth_pick_output_dir(self) -> str:
        return str(QFileDialog.getExistingDirectory(self, "Graph truth — choose export folder", "") or "").strip()

    def _auto_debug_dest_tree_export_env_enabled(self) -> bool:
        v = os.environ.get("OZLINK_AUTO_DEBUG_DEST_TREE_EXPORT", "1").strip().lower()
        return v not in ("0", "false", "no", "off")

    def _should_run_auto_debug_destination_tree_pair(self) -> tuple[bool, str]:
        if not self._auto_debug_dest_tree_export_env_enabled():
            return False, "env_disabled"
        if self._auto_debug_dest_tree_pair_ran:
            return False, "already_ran"
        if running_under_pytest():
            return False, "pytest"
        g = getattr(self, "graph", None)
        if g is None or not getattr(g, "token", None):
            return False, "no_graph_token"
        if self._planning_browse_mode("destination") == "local":
            return False, "local_destination"
        did = ""
        try:
            if hasattr(self, "_current_selected_destination_drive_id"):
                did = str(self._current_selected_destination_drive_id() or "").strip()
        except Exception:
            did = ""
        if not did:
            p = getattr(self, "pending_root_drive_ids", None) or {}
            if isinstance(p, dict):
                did = str(p.get("destination") or "").strip()
        if not did:
            return False, "no_destination_drive"
        return True, ""

    def _run_auto_debug_destination_tree_pair_once(self, reason: str = "") -> None:
        ok, why = self._should_run_auto_debug_destination_tree_pair()
        if not ok:
            log_info(
                "debug_auto_destination_tree_pair_skipped",
                reason=str(reason)[:200],
                why=why,
            )
            return
        try:
            log_info("debug_auto_destination_tree_pair_started", reason=str(reason)[:200])
            t, j, s = self.debug_export_visible_destination_tree(out_dir=None)
            self._auto_debug_dest_tree_pair_ran = True
            gerr = s.get("graph_error")
            gsum = s.get("graph_summary")
            if not gerr and isinstance(gsum, dict):
                gerr = gsum.get("error")
            log_info(
                "debug_auto_destination_tree_pair_finished",
                reason=str(reason)[:200],
                visible_txt=str(t)[:500],
                visible_json=str(j)[:500],
                graph_txt=str(s.get("graph_txt_path") or "")[:500],
                graph_json=str(s.get("graph_json_path") or "")[:500],
                graph_error=str(gerr)[:500] if gerr else None,
                memory_txt=str(s.get("memory_txt_path") or "")[:500],
                memory_json=str(s.get("memory_json_path") or "")[:500],
                memory_error=str(s.get("memory_error") or "")[:500] or None,
            )
        except Exception as exc:
            log_info("debug_auto_destination_tree_pair_failed", reason=str(reason)[:200], error=str(exc)[:500])

    def debug_export_visible_destination_tree(
        self, out_dir: str | None = None
    ) -> tuple[str, str, dict[str, Any]]:
        """Debug: write visible + graph + **memory snapshot** destination exports in one folder (txt+json each), same timestamp.

        Filenames: ``visible__...``, ``graph__...``, ``memory__...`` with
        ``<site>__<library>__<YYYY-MM-DD_HH-MM-SS>`` (site/library segments sanitized).

        * Visible: :class:`DestinationPlanningTreeModel` only.
        * Graph: :meth:`ozlink_console.graph.GraphClient.list_drive_all_items_normalized` (read-only).
        * Memory: raw ``_pending_session_tree_snapshots`` / ``_runtime_session_tree_snapshots`` destination
          list (same source as ``_destination_apply_provisional_session_snapshot_if_eligible``), no UI/Graph.

        If ``out_dir`` is None, use :func:`ozlink_console.logger.get_session_logs_dir`. Returns
        ``(visible_txt, visible_json, combined_summary)``; graph and memory paths/summaries are on
        the third dict (e.g. ``graph_txt_path``, ``memory_txt_path``, ``memory_summary``).
        """
        from ozlink_console.logger import get_session_logs_dir

        from ozlink_console.debug_graph_tree_export import export_graph_destination_tree
        from ozlink_console.debug_memory_destination_tree import export_memory_destination_tree
        from ozlink_console.debug_visible_destination_tree import export_visible_destination_tree

        if out_dir is None:
            o = get_session_logs_dir()
        else:
            o = Path(str(out_dir))
        from ozlink_console.debug_dest_tree_export_naming import (
            dest_tree_export_timestamp_str,
            dest_tree_triple_file_stems,
        )

        ctx0 = self._destination_full_tree_context() or {}
        if not isinstance(ctx0, dict):
            ctx0 = {}
        _site = str(ctx0.get("site_name") or "")
        _lib = str(ctx0.get("library_name") or "")
        _ts = dest_tree_export_timestamp_str()
        v_stem, g_stem, m_stem = dest_tree_triple_file_stems(_site, _lib, _ts)
        t0 = time.perf_counter()
        log_info(
            "debug_destination_tree_pair_export_started",
            out_dir=str(o.resolve()),
            export_pair_timestamp=_ts,
            site_name_for_filename=_site,
            library_name_for_filename=_lib,
            visible_stem=v_stem,
            graph_stem=g_stem,
            memory_stem=m_stem,
        )
        t_v0 = time.perf_counter()
        t, j, s = export_visible_destination_tree(self, out_dir=o, file_stem=v_stem)
        visible_ms = round((time.perf_counter() - t_v0) * 1000.0, 2)
        combined: dict[str, Any] = dict(s)
        combined["export_pair_timestamp"] = _ts
        combined["export_site_name"] = _site
        combined["export_library_name"] = _lib
        combined["visible_file_stem"] = v_stem
        combined["graph_file_stem"] = g_stem
        combined["memory_file_stem"] = m_stem
        graph_ms: float | None = None
        t_g0 = time.perf_counter()
        try:
            gt, gj, gs = export_graph_destination_tree(self, out_dir=o, file_stem=g_stem)
            graph_ms = round((time.perf_counter() - t_g0) * 1000.0, 2)
            combined["graph_txt_path"] = str(gt)
            combined["graph_json_path"] = str(gj)
            combined["graph_summary"] = gs
        except Exception as exc:
            log_info("debug_graph_destination_tree_export_skipped", error=str(exc)[:500])
            combined["graph_error"] = str(exc)[:500]
        memory_ms: float | None = None
        t_m0 = time.perf_counter()
        try:
            mt, mj, ms = export_memory_destination_tree(self, out_dir=o, file_stem=m_stem)
            memory_ms = round((time.perf_counter() - t_m0) * 1000.0, 2)
            combined["memory_txt_path"] = str(mt)
            combined["memory_json_path"] = str(mj)
            combined["memory_summary"] = ms
        except Exception as exc:
            log_info("debug_memory_destination_tree_export_skipped", error=str(exc)[:500])
            combined["memory_error"] = str(exc)[:500]
        wall_ms = round((time.perf_counter() - t0) * 1000.0, 2)
        try:
            from ozlink_console.destination_visible_graph_export_audit import build_visible_vs_graph_path_diff_audit

            if combined.get("graph_json_path") and not combined.get("graph_error"):
                with open(Path(j), encoding="utf-8") as _vf:
                    _vdoc = json.load(_vf)
                with open(Path(str(combined["graph_json_path"])), encoding="utf-8") as _gf:
                    _gdoc = json.load(_gf)
                _audit = build_visible_vs_graph_path_diff_audit(_vdoc, _gdoc)
                # Flatten nested flags for log_json-friendly keys (some back-ends do not like nested dicts in JSON fields).
                _f = (_audit.get("audit_path_flags") or {}) if isinstance(_audit, dict) else {}
                if isinstance(_f, dict) and _f:
                    for _fk, _fv in _f.items():
                        _audit["audit_path_flag__" + str(_fk)] = _fv
                    if "audit_path_flags" in _audit:
                        del _audit["audit_path_flags"]
                log_info("destination_visible_vs_graph_path_diff_audit", **_audit)
                _sample = _audit.get("missing_graph_sample")
                if isinstance(_sample, list):
                    for _cand in (
                        r"root3\it",
                        r"root3\marketing",
                    ):
                        pcf2 = str(_cand).replace("/", "\\")
                        pcf2_cf = pcf2.casefold()
                        if pcf2_cf in {str(x).casefold() for x in _sample} or any(
                            pcf2_cf in str(x or "").casefold() for x in _sample
                        ):
                            log_info(
                                "destination_graph_live_row_missing_from_visible_model",
                                audit_hint="graph_only_path_in_export_diff_sample",
                                path_excerpt=pcf2[:400],
                            )
        except Exception as _aexc:
            log_info("destination_visible_vs_graph_path_diff_audit_failed", error=str(_aexc)[:500])
        _cgp = s.get("count_graph_vs_planned")
        if isinstance(_cgp, dict):
            log_info(
                "destination_visible_export_graph_row_count",
                count_graph_vs_planned_live_graph=int(_cgp.get("live_graph") or 0),
                count_graph_vs_planned_planned=int(_cgp.get("planned") or 0),
                count_graph_vs_planned_other=int(_cgp.get("other") or 0),
                total_visible_rows=int(s.get("total_visible_rows") or 0),
            )
        _dm = getattr(self, "destination_planning_model", None)
        _merge_t = 0.0
        if _dm is not None and hasattr(_dm, "_graph_root_merge_last_at_monotonic"):
            try:
                _merge_t = float(getattr(_dm, "_graph_root_merge_last_at_monotonic", 0.0) or 0.0)
            except Exception:
                _merge_t = 0.0
        _now_m = time.monotonic()
        log_info(
            "destination_export_timing_visible_vs_graph",
            order=["visible", "graph", "memory"],
            visible_export_ms=float(visible_ms),
            graph_export_ms=float(graph_ms) if graph_ms is not None else -1.0,
            memory_export_ms=float(memory_ms) if memory_ms is not None else -1.0,
            wall_total_ms=wall_ms,
            note="visible_model_walk_happens_before_Graph_list_drive_in_same_function",
        )
        log_info(
            "destination_graph_bind_completed_before_visible_export",
            visible_export_captures_UI_before_graph_list_call_in_this_debug_routine=True,
            seconds_since_model_root_graph_merge_at_export=(round(_now_m - _merge_t, 4) if _merge_t > 0 else None),
            had_recorded_model_root_graph_merge=bool(_merge_t > 0),
        )
        try:
            log_info(
                "destination_graph_bind_is_authoritative_at_debug_export",
                is_authoritative=bool(self._destination_root_bind_is_authoritative()),
            )
        except Exception:
            pass
        log_info(
            "debug_destination_tree_pair_export_completed",
            out_dir=str(o.resolve()),
            wall_ms=wall_ms,
            visible_txt=str(t),
            visible_json=str(j),
            graph_txt=str(combined.get("graph_txt_path") or ""),
            graph_json=str(combined.get("graph_json_path") or ""),
            graph_error=str(combined.get("graph_error") or "")[:500] or None,
            memory_txt=str(combined.get("memory_txt_path") or ""),
            memory_json=str(combined.get("memory_json_path") or ""),
            memory_error=str(combined.get("memory_error") or "")[:500] or None,
        )
        return str(t), str(j), combined

    def _dev_export_visible_destination_model_tree(self) -> None:
        """One-click: write to the current session's log directory (no folder dialog)."""
        t, j, s = self.debug_export_visible_destination_tree(out_dir=None)
        g1 = s.get("graph_txt_path", "")
        g2 = s.get("graph_json_path", "")
        m1 = s.get("memory_txt_path", "")
        m2 = s.get("memory_json_path", "")
        ge = s.get("graph_error")
        me = s.get("memory_error")
        _gs = s.get("graph_summary") if isinstance(s.get("graph_summary"), dict) else {}
        _ms = s.get("memory_summary") if isinstance(s.get("memory_summary"), dict) else {}
        gn = int(( _gs or {}).get("total_nodes") or 0)  # type: ignore[union-attr, misc]
        mn = int(( _ms or {}).get("total_nodes") or 0)  # type: ignore[union-attr, misc]
        if not ge and isinstance(_gs, dict):
            ge = _gs.get("error")
        extra = ""
        if g1 or g2:
            extra = f"\n\nGraph (live) export:\n{g1}\n{g2}\ngraph_nodes={gn}"
        if m1 or m2:
            extra = f"{extra}\n\nMemory (snapshot) export:\n{m1}\n{m2}\nmemory_nodes={mn}"
        if ge:
            extra = f"{extra}\n\nGraph export note: {ge}"
        if me:
            extra = f"{extra}\n\nMemory export note: {me}"
        QMessageBox.information(
            self,
            "Visible + graph + memory destination tree",
            f"Wrote to session log folder:\n{t}\n{j}{extra}\n"
            f"\nrows={s.get('total_visible_rows', 0)} top_level={s.get('top_level_row_count', 0)}",
        )

    def _graph_truth_canonicalize_raw(self, raw_path: str) -> str:
        return str(
            self._canonical_planned_memory_path_for_graph_match(
                self.normalize_memory_path(str(raw_path or "").strip())
            )
            or ""
        ).strip()

    def _dev_export_graph_truth_app_audit_jsonl(self) -> None:
        if not self._destination_sharepoint_planning_destination_active():
            QMessageBox.warning(self, "Graph truth", "Open SharePoint destination planning first.")
            return
        out_dir = self._dev_graph_truth_pick_output_dir()
        if not out_dir:
            return
        try:
            rows = collect_app_destination_audit_rows(self)
            path = os.path.join(out_dir, "graph_truth_app_audit.jsonl")
            write_jsonl(path, rows)
            log_info("graph_truth_export_app_audit", row_count=len(rows), path=path)
            QMessageBox.information(self, "Graph truth", f"Wrote {len(rows)} rows to:\n{path}")
        except Exception as exc:
            log_warn("graph_truth_export_app_audit_failed", error=str(exc)[:500])
            QMessageBox.warning(self, "Graph truth", f"Export failed:\n{exc}")

    def _dev_graph_truth_configure_enumeration_scope(self) -> dict[str, Any] | None:
        items = [
            "Full selected library",
            "Selected folder subtree",
            "Full library — filter by path prefix",
        ]
        choice, ok = QInputDialog.getItem(
            self,
            "Graph truth — scope",
            "Live Graph enumeration (Microsoft Graph API only):",
            items,
            0,
            False,
        )
        if not ok:
            return None
        drive_id = str(self._current_selected_destination_drive_id() or "").strip()
        if not drive_id:
            QMessageBox.warning(self, "Graph truth", "Select a destination library (drive) first.")
            return None
        ctx = self._destination_full_tree_context()
        if choice == items[0]:
            return {
                "mode": "full_library",
                "drive_id": drive_id,
                "context": ctx,
                "subtree_item_id": "",
                "subtree_parent_item_path": "",
                "anchor_records": [],
                "prefix_filter": "",
            }
        if choice == items[1]:
            ix = self.destination_tree_widget.currentIndex()
            if not ix.isValid():
                QMessageBox.warning(self, "Graph truth", "Select a destination folder in the tree.")
                return None
            pl = self._destination_model_index_user_role_dict(ix)
            sid = str(pl.get("id") or "").strip()
            if not sid:
                QMessageBox.warning(
                    self,
                    "Graph truth",
                    "Selected row has no Graph driveItem id — pick a live folder or use full library scope.",
                )
                return None
            raw_ip = str(pl.get("item_path") or "").strip() or "/"
            parent_gid = ""
            pref = pl.get("parentReference")
            if isinstance(pref, dict):
                parent_gid = str(pref.get("id") or "").strip()
            if not parent_gid and ix.parent().isValid():
                ppl = self._destination_model_index_user_role_dict(ix.parent())
                parent_gid = str(ppl.get("id") or "").strip()
            model = getattr(self, "destination_planning_model", None)
            col0 = ix.siblingAtColumn(0) if ix.column() != 0 else ix
            nch = 0
            if model is not None:
                try:
                    nch = int(model.rowCount(col0))
                except Exception:
                    nch = 0
            folder_meta = pl.get("folder") if isinstance(pl.get("folder"), dict) else {}
            anchor = {
                "item_path": raw_ip,
                "name": str(pl.get("name") or pl.get("real_name") or ""),
                "is_folder": bool(pl.get("is_folder")),
                "graph_item_id": sid,
                "graph_parent_id": parent_gid,
                "child_count_graph": int(pl.get("child_count") or folder_meta.get("childCount") or nch),
                "web_url": str(pl.get("web_url") or pl.get("webUrl") or ""),
                "drive_id": str(pl.get("drive_id") or drive_id),
            }
            return {
                "mode": "subtree",
                "drive_id": drive_id,
                "context": ctx,
                "subtree_item_id": sid,
                "subtree_parent_item_path": raw_ip,
                "anchor_records": [anchor],
                "prefix_filter": "",
            }
        prefix, ok2 = QInputDialog.getText(
            self,
            "Graph truth — prefix",
            "Canonical path prefix (e.g. Root3\\\\Finance):",
            text="Root3\\Finance",
        )
        if not ok2:
            return None
        return {
            "mode": "full_library",
            "drive_id": drive_id,
            "context": ctx,
            "subtree_item_id": "",
            "subtree_parent_item_path": "",
            "anchor_records": [],
            "prefix_filter": str(prefix or "").strip(),
        }

    def _dev_export_graph_truth_live_graph_jsonl(self) -> None:
        if not getattr(self, "graph", None):
            QMessageBox.warning(self, "Graph truth", "Graph client is not available.")
            return
        cfg = self._dev_graph_truth_configure_enumeration_scope()
        if not cfg:
            return
        out_dir = self._dev_graph_truth_pick_output_dir()
        if not out_dir:
            return
        self._graph_truth_pending = {
            "out_dir": out_dir,
            "app_rows": None,
            "prefix_filter": cfg.get("prefix_filter") or "",
            "anchor_records": list(cfg.get("anchor_records") or []),
            "bundle": False,
        }
        worker = GraphLiveEnumerateWorker(
            self.graph,
            cfg["drive_id"],
            mode=cfg["mode"],
            subtree_item_id=cfg.get("subtree_item_id") or "",
            subtree_parent_item_path=cfg.get("subtree_parent_item_path") or "",
            context=cfg.get("context") or {},
            parent=None,
        )
        self._graph_truth_worker = worker
        worker.finished_ok.connect(self._dev_on_graph_truth_live_enumeration_done)
        worker.failed.connect(self._dev_on_graph_truth_worker_failed)
        worker.finished.connect(worker.deleteLater)
        worker.start()
        QMessageBox.information(
            self,
            "Graph truth",
            "Live Graph enumeration running in the background.\n"
            "You will get a message when the JSONL file is written.",
        )

    def _dev_on_graph_truth_worker_failed(self, msg: str) -> None:
        log_warn("graph_truth_graph_enumerate_failed", error_excerpt=str(msg)[:800])
        QMessageBox.warning(self, "Graph truth", f"Graph enumeration failed:\n{msg}")

    def _dev_on_graph_truth_live_enumeration_done(self, normalized_items: list) -> None:
        pending = getattr(self, "_graph_truth_pending", None) or {}
        out_dir = str(pending.get("out_dir") or "").strip()
        prefix = str(pending.get("prefix_filter") or "").strip()
        anchor_records = list(pending.get("anchor_records") or [])
        do_bundle = bool(pending.get("bundle"))
        app_rows = pending.get("app_rows")
        self._graph_truth_pending = {}
        if not out_dir:
            return
        try:
            base_live = list(anchor_records) + live_graph_rows_to_export_records(list(normalized_items or []))
            rows = add_live_canonical_paths(base_live, self._graph_truth_canonicalize_raw)
            pfx_canon = self._graph_truth_canonicalize_raw(prefix) if prefix else ""
            if pfx_canon:
                rows = [r for r in rows if path_matches_canonical_prefix(str(r.get("canonical_path") or ""), pfx_canon)]
            path = os.path.join(out_dir, "graph_truth_live_graph.jsonl")
            write_jsonl(path, rows)
            log_info("graph_truth_export_live_graph", row_count=len(rows), path=path, prefix_filter=prefix or None)
            if do_bundle and isinstance(app_rows, list):
                app_use = list(app_rows)
                if pfx_canon:
                    app_use = [
                        a
                        for a in app_use
                        if path_matches_canonical_prefix(str(a.get("canonical_path") or ""), pfx_canon)
                    ]
                cmp_path = os.path.join(out_dir, "graph_truth_comparison.jsonl")
                comp = build_graph_truth_comparison_records(app_use, rows)
                write_jsonl(cmp_path, comp)
                live_map = index_live_rows_by_canonical_path(rows)
                viol = log_graph_truth_violations(app_use, live_map)
                summ_path = os.path.join(out_dir, "graph_truth_summary.txt")
                with open(summ_path, "w", encoding="utf-8") as sf:
                    sf.write(comparison_summary_text(comp))
                    sf.write(f"\n\ndestination_graph_truth_violation count: {viol}\n")
                app_path = os.path.join(out_dir, "graph_truth_app_audit.jsonl")
                write_jsonl(app_path, app_use)
                log_info(
                    "graph_truth_bundle_complete",
                    app_rows=len(app_use),
                    live_rows=len(rows),
                    comparison_rows=len(comp),
                    violations=int(viol),
                )
                QMessageBox.information(
                    self,
                    "Graph truth",
                    f"Bundle written to:\n{out_dir}\n\n"
                    f"app rows: {len(app_use)}\nlive rows: {len(rows)}\n"
                    f"comparison rows: {len(comp)}\ntruth violations: {viol}",
                )
            else:
                QMessageBox.information(
                    self,
                    "Graph truth",
                    f"Wrote {len(rows)} live Graph rows to:\n{path}",
                )
        except Exception as exc:
            log_warn("graph_truth_live_export_failed", error=str(exc)[:800])
            QMessageBox.warning(self, "Graph truth", f"Failed to write export:\n{exc}")

    def _dev_run_graph_truth_bundle(self) -> None:
        if not self._destination_sharepoint_planning_destination_active():
            QMessageBox.warning(self, "Graph truth", "Open SharePoint destination planning first.")
            return
        if not getattr(self, "graph", None):
            QMessageBox.warning(self, "Graph truth", "Graph client is not available.")
            return
        cfg = self._dev_graph_truth_configure_enumeration_scope()
        if not cfg:
            return
        out_dir = self._dev_graph_truth_pick_output_dir()
        if not out_dir:
            return
        try:
            app_rows = collect_app_destination_audit_rows(self)
        except Exception as exc:
            QMessageBox.warning(self, "Graph truth", f"Failed to collect app rows:\n{exc}")
            return
        self._graph_truth_pending = {
            "out_dir": out_dir,
            "app_rows": app_rows,
            "prefix_filter": cfg.get("prefix_filter") or "",
            "anchor_records": list(cfg.get("anchor_records") or []),
            "bundle": True,
        }
        worker = GraphLiveEnumerateWorker(
            self.graph,
            cfg["drive_id"],
            mode=cfg["mode"],
            subtree_item_id=cfg.get("subtree_item_id") or "",
            subtree_parent_item_path=cfg.get("subtree_parent_item_path") or "",
            context=cfg.get("context") or {},
            parent=None,
        )
        self._graph_truth_worker = worker
        worker.finished_ok.connect(self._dev_on_graph_truth_live_enumeration_done)
        worker.failed.connect(self._dev_on_graph_truth_worker_failed)
        worker.finished.connect(worker.deleteLater)
        worker.start()
        QMessageBox.information(
            self,
            "Graph truth",
            "Collecting live Graph data in the background.\n"
            "Large libraries can take several minutes.",
        )

    def _schedule_progress_summary_refresh(self, delay_ms: int = 180):
        if not hasattr(self, "_progress_summary_refresh_timer") or self._progress_summary_refresh_timer is None:
            self.update_progress_summaries()
            return
        if getattr(self, "_sharepoint_lazy_mode", False) and self._planning_workspace_is_busy():
            delay_ms = max(delay_ms, 2500)
        self._progress_summary_refresh_timer.start(max(0, int(delay_ms)))

    def _planning_workspace_is_busy(self):
        pending_source = bool(self.pending_folder_loads.get("source"))
        pending_destination = bool(self.pending_folder_loads.get("destination"))
        return bool(
            self._root_tree_bind_in_progress
            or self._expand_all_pending.get("source")
            or self._expand_all_pending.get("destination")
            or pending_source
            or pending_destination
            or getattr(self, "_lazy_destination_projection_pending_reason", "")
        )

    def _workspace_ui_persist_should_defer(self) -> bool:
        """True while restore/finalisation or destination materialisation is active — avoid forced draft save."""
        if getattr(self, "_memory_restore_in_progress", False):
            return True
        if getattr(self, "_restore_finalization_deferred_active", False):
            return True
        if getattr(self, "_destination_chunked_bind_state", None) is not None:
            return True
        if getattr(self, "_destination_future_bind_sync_active", False):
            return True
        if getattr(self, "_destination_future_projection_async_state", None) is not None:
            return True
        if getattr(self, "_destination_snapshot_chunked_restore_active", False):
            return True
        if self._planning_workspace_is_busy():
            return True
        return False

    def _workspace_ui_persist_defer_reason(self) -> str:
        """Short machine-readable reason for :meth:`_workspace_ui_persist_should_defer` (logging only)."""
        if getattr(self, "_memory_restore_in_progress", False):
            return "restore_in_progress"
        if getattr(self, "_restore_finalization_deferred_active", False):
            return "restore_finalization_deferred"
        if getattr(self, "_destination_chunked_bind_state", None) is not None:
            return "destination_chunked_bind"
        if getattr(self, "_destination_future_bind_sync_active", False):
            return "destination_future_bind_sync"
        if getattr(self, "_destination_future_projection_async_state", None) is not None:
            return "destination_future_projection_async"
        if getattr(self, "_destination_snapshot_chunked_restore_active", False):
            return "destination_snapshot_chunked_restore"
        if self._planning_workspace_is_busy():
            return "planning_workspace_busy"
        return "unknown"

    def _start_session_keepalive(self):
        timer = getattr(self, "_session_keepalive_timer", None)
        if timer is None or not self.current_session_context.get("connected"):
            return
        if not timer.isActive():
            timer.start()
        log_info("Session keepalive started.", interval_ms=timer.interval())

    def _stop_session_keepalive(self):
        timer = getattr(self, "_session_keepalive_timer", None)
        if timer is not None and timer.isActive():
            timer.stop()
        worker = getattr(self, "session_keepalive_worker", None)
        if worker is not None and worker.isRunning():
            worker.requestInterruption()
        self.session_keepalive_worker = None
        log_info("Session keepalive stopped.")

    def _run_session_keepalive(self):
        try:
            if not self.current_session_context.get("connected"):
                self._stop_session_keepalive()
                return
            if self.session_keepalive_worker and self.session_keepalive_worker.isRunning():
                return
            if self._login_in_progress or (self.worker and self.worker.isRunning()) or (self.device_flow_worker and self.device_flow_worker.isRunning()):
                return
            self.session_keepalive_worker = SessionKeepAliveWorker(self.graph)
            self.session_keepalive_worker.success.connect(
                lambda payload: self._safe_invoke("session_keepalive.success", self.on_session_keepalive_success, payload)
            )
            self.session_keepalive_worker.error.connect(
                lambda error: self._safe_invoke("session_keepalive.error", self.on_session_keepalive_error, error)
            )
            self.session_keepalive_worker.finished.connect(
                lambda: self._safe_invoke("session_keepalive.finished", self.on_session_keepalive_finished)
            )
            self.session_keepalive_worker.start()
        except Exception as exc:
            self._log_restore_exception("run_session_keepalive", exc)

    def on_session_keepalive_success(self, payload):
        refreshed = bool((payload or {}).get("refreshed"))
        log_info("Session keepalive completed.", refreshed=refreshed)

    def on_session_keepalive_error(self, error):
        log_warn("Session keepalive failed.", error=str(error or ""))

    def on_session_keepalive_finished(self):
        self.session_keepalive_worker = None

    def _schedule_deferred_background_load(self, panel_key, drive_id):
        if getattr(self, "_sharepoint_lazy_mode", False):
            self._deferred_background_load_targets[panel_key] = str(drive_id or "")
            if panel_key == "destination" and drive_id:
                self._ensure_sharepoint_destination_full_tree_worker_scheduled(
                    drive_id,
                    schedule_reason="deferred_background_load_lazy_destination",
                    routine_followup=True,
                    skeleton_first_bootstrap=True,
                )
            elif panel_key == "source" and drive_id:
                self._schedule_full_count_with_restore_backoff(drive_id)
            return
        timer = self._deferred_background_load_timers.get(panel_key)
        if timer is None:
            if panel_key == "source":
                self._schedule_full_count_with_restore_backoff(drive_id)
            elif panel_key == "destination":
                self._ensure_sharepoint_destination_full_tree_worker_scheduled(
                    drive_id,
                    schedule_reason="deferred_background_timer_destination",
                    routine_followup=True,
                    skeleton_first_bootstrap=True,
                )
                return

        self._deferred_background_load_targets[panel_key] = str(drive_id or "")
        timer.stop()
        timer.start(1500)

    def _run_deferred_background_load(self, panel_key):
        if getattr(self, "_application_shutting_down", False):
            return
        if getattr(self, "_sharepoint_lazy_mode", False):
            return
        drive_id = self._deferred_background_load_targets.get(panel_key, "")
        if not drive_id:
            return
        if panel_key == "source":
            self._schedule_full_count_with_restore_backoff(drive_id)
        elif panel_key == "destination":
            self._ensure_sharepoint_destination_full_tree_worker_scheduled(
                drive_id,
                schedule_reason="deferred_background_run_destination",
                routine_followup=True,
                skeleton_first_bootstrap=True,
            )

    def _refresh_tree_column_width(self, panel_key):
        tree = self.source_tree_widget if panel_key == "source" else self.destination_tree_widget
        if tree is None:
            return
        try:
            if isinstance(tree, QTreeView) and tree.model() is not None:
                for col in range(1, EXPLORER_COLUMN_COUNT):
                    tree.resizeColumnToContents(col)
                return
            if isinstance(tree, QTreeWidget):
                for col in range(1, EXPLORER_COLUMN_COUNT):
                    tree.resizeColumnToContents(col)
                return
        except Exception:
            return

    def _reset_source_background_preload_state(self):
        self._source_background_preload_pending = False
        self._source_background_preload_queue = []
        self._source_background_preload_seen = set()
        timer = getattr(self, "_source_background_preload_timer", None)
        if timer is not None:
            timer.stop()

    def _queue_source_background_preload_item(self, item):
        if item is None:
            return
        node_data = item.data(0, Qt.UserRole) or {}
        if node_data.get("placeholder") or not node_data.get("is_folder"):
            return
        item_key = id(item)
        if item_key in self._source_background_preload_seen:
            return
        self._source_background_preload_seen.add(item_key)
        self._source_background_preload_queue.append(item)

    def _schedule_source_background_preload(self, delay_ms=10):
        timer = getattr(self, "_source_background_preload_timer", None)
        if timer is not None and not timer.isActive():
            timer.start(max(0, int(delay_ms)))

    def _start_source_background_preload(self):
        if not getattr(self, "_sharepoint_lazy_mode", False):
            return
        tree = getattr(self, "source_tree_widget", None)
        if tree is None:
            return
        self._source_background_preload_pending = True
        self._source_background_preload_queue = []
        self._source_background_preload_seen = set()
        for top_row in self._iter_panel_top_level_rows("source"):
            if isinstance(top_row, QModelIndex):
                continue
            self._queue_source_background_preload_item(top_row)
        self._schedule_source_background_preload(delay_ms=0)

    def _continue_source_background_preload(self, item=None):
        if not self._source_background_preload_pending:
            return
        if item is not None:
            for index in range(item.childCount()):
                self._queue_source_background_preload_item(item.child(index))
        self._schedule_source_background_preload(delay_ms=0)

    def _process_source_background_preload_queue(self):
        if not self._source_background_preload_pending:
            return
        if self._expand_all_pending.get("source"):
            self._reset_source_background_preload_state()
            return

        tree = getattr(self, "source_tree_widget", None)
        if tree is None:
            self._reset_source_background_preload_state()
            return

        processed = 0
        max_per_tick = 2
        waiting_for_async_load = False

        while self._source_background_preload_queue and processed < max_per_tick:
            item = self._source_background_preload_queue.pop(0)
            if item is None:
                continue
            node_data = item.data(0, Qt.UserRole) or {}
            if node_data.get("placeholder") or not node_data.get("is_folder"):
                continue

            if bool(node_data.get("children_loaded")):
                for index in range(item.childCount()):
                    self._queue_source_background_preload_item(item.child(index))
                processed += 1
                continue

            if self._ensure_tree_item_load_started("source", item):
                waiting_for_async_load = True
                break
            processed += 1

        if waiting_for_async_load or self.pending_folder_loads.get("source"):
            self._schedule_source_background_preload(delay_ms=25)
            return

        if self._source_background_preload_queue:
            self._schedule_source_background_preload(delay_ms=10)
            return

        self._source_background_preload_pending = False

