    def _needs_review_rows_for_display(self) -> list:
        rows = list(getattr(self, "_workflow_needs_review_rows", None) or [])
        dismissed = getattr(self, "_needs_review_dismissed_inherited_paths", None) or set()
        cb = getattr(self, "needs_review_show_inherited_checkbox", None)
        show_inherited = bool(cb is not None and cb.isChecked())
        out = []
        for r in rows:
            if not isinstance(r, dict):
                continue
            rt = str(r.get("review_type", "") or "").strip()
            sp = self.normalize_memory_path(str(r.get("source_path", "") or ""))
            if rt == "inherited_mapping":
                if sp in dismissed:
                    continue
                if not show_inherited:
                    continue
            out.append(r)
        return out

    def _needs_review_status_line(self, all_rows: list, display_rows: list) -> str:
        if not all_rows:
            return "No review issues detected from the current planning state."
        cb = getattr(self, "needs_review_show_inherited_checkbox", None)
        show_inherited = bool(cb is not None and cb.isChecked())
        dismissed = getattr(self, "_needs_review_dismissed_inherited_paths", None) or set()
        conflict_types = {
            "duplicate_destination_projection",
            "proposed_branch_dependency",
            "weak_suggestion",
            "migration_live_duplicate_proposed_folder",
            REVIEW_TYPE_LIVE_MEMORY_DUPLICATE,
            REVIEW_TYPE_DESTINATION_ANCHOR_MISSING,
        }
        n_inherited_not_dismissed = 0
        for r in all_rows:
            if not isinstance(r, dict) or str(r.get("review_type", "") or "").strip() != "inherited_mapping":
                continue
            sp = self.normalize_memory_path(str(r.get("source_path", "") or ""))
            if sp not in dismissed:
                n_inherited_not_dismissed += 1
        n_hidden = 0 if show_inherited else n_inherited_not_dismissed
        n_actionable_shown = sum(
            1
            for r in display_rows
            if isinstance(r, dict) and str(r.get("review_type", "") or "").strip() in conflict_types
        )
        n_inherited_shown = sum(
            1
            for r in display_rows
            if isinstance(r, dict) and str(r.get("review_type", "") or "").strip() == "inherited_mapping"
        )
        parts = []
        if n_actionable_shown and n_hidden:
            parts.append(
                f"{n_actionable_shown} actionable item(s). "
                f"{n_hidden} inherited mapping(s) hidden (likely OK)."
            )
        elif n_actionable_shown:
            parts.append(f"{n_actionable_shown} actionable item(s) in this list.")
        elif n_hidden:
            parts.append(
                f"No conflicts or low-confidence suggestions need action. "
                f"{n_hidden} inherited mapping(s) hidden (likely OK)."
            )
        elif show_inherited and n_inherited_shown:
            parts.append(
                f"No conflicts or low-confidence suggestions in this list. "
                f"{n_inherited_shown} inherited mapping(s) listed for your information."
            )
        else:
            parts.append("No conflicts or low-confidence suggestions need review right now.")
        if show_inherited and n_inherited_shown and n_actionable_shown:
            parts.append(f"{n_inherited_shown} inherited mapping(s) listed for your information.")
        return " ".join(parts)

    def _apply_needs_review_table_view(self) -> None:
        table = getattr(self, "needs_review_table", None)
        if table is None:
            return
        all_rows = list(getattr(self, "_workflow_needs_review_rows", None) or [])
        display_rows = self._needs_review_rows_for_display()
        self._set_workflow_table_rows(
            table,
            display_rows,
            ["item_name", "source_path", "reason", "action"],
        )
        if hasattr(self, "needs_review_status"):
            self.needs_review_status.setText(self._needs_review_status_line(all_rows, display_rows))
        self._sync_needs_review_action_buttons()

    def _needs_review_selected_row_data(self) -> dict:
        table = getattr(self, "needs_review_table", None)
        if table is None:
            return {}
        selected = table.selectedItems()
        if not selected:
            return {}
        row = selected[0].row()
        it = table.item(row, 0)
        if it is None:
            return {}
        data = it.data(Qt.UserRole)
        return data if isinstance(data, dict) else {}

    def _sync_needs_review_action_buttons(self) -> None:
        rd = self._needs_review_selected_row_data()
        rt = str(rd.get("review_type", "") or "").strip()
        sp = str(rd.get("source_path", "") or "").strip()
        go_btn = getattr(self, "needs_review_go_btn", None)
        confirm_btn = getattr(self, "needs_review_confirm_btn", None)
        dup_btn = getattr(self, "needs_review_dup_dialog_btn", None)
        if go_btn is not None:
            go_btn.setEnabled(bool(sp))
        if confirm_btn is not None:
            confirm_btn.setEnabled(rt == "inherited_mapping" and bool(sp))
        if dup_btn is not None:
            dup_btn.setEnabled(rt == "duplicate_destination_projection")

    def _on_needs_review_selection_changed(self) -> None:
        self._sync_needs_review_action_buttons()

    def _on_needs_review_show_inherited_toggled(self, _checked: bool) -> None:
        self._apply_needs_review_table_view()

    def _on_needs_review_go_to_item(self) -> None:
        rd = self._needs_review_selected_row_data()
        if not rd:
            return
        self._activate_workflow_source_row(rd)

    def _on_needs_review_mark_inherited_confirmed(self) -> None:
        rd = self._needs_review_selected_row_data()
        if str(rd.get("review_type", "") or "").strip() != "inherited_mapping":
            return
        sp = self.normalize_memory_path(str(rd.get("source_path", "") or ""))
        if not sp:
            return
        self._needs_review_dismissed_inherited_paths.add(sp)
        self._apply_needs_review_table_view()
        self._save_draft_shell()
        self._refresh_planning_derived_state("needs_review_inherited_dismiss")

    def _on_needs_review_open_duplicate_file_review(self) -> None:
        self._show_duplicate_destination_file_review_dialog()

    def refresh_requests_page(self):
        if not hasattr(self, "requests_table"):
            return

        rows = self.request_store.list_submission_batches()
        self._request_batch_rows = rows
        self.requests_table.setRowCount(len(rows))
        live_count = 0
        test_count = 0
        total_moves = 0

        for row_index, row in enumerate(rows):
            live_count += 0 if row.get("is_test") else 1
            test_count += 1 if row.get("is_test") else 0
            total_moves += int(row.get("planned_move_count", 0) or 0)
            values = [
                row.get("batch_id", ""),
                "Test" if row.get("is_test") else "Live",
                row.get("status", ""),
                row.get("submitted_utc", ""),
                str(row.get("planned_move_count", 0)),
                str(row.get("proposed_folder_count", 0)),
                row.get("draft_name", "") or row.get("draft_id", ""),
            ]
            for column_index, value in enumerate(values):
                item = QTableWidgetItem(value)
                item.setData(Qt.UserRole, row_index)
                self.requests_table.setItem(row_index, column_index, item)

        self.requests_live_count.setText(str(live_count))
        self.requests_test_count.setText(str(test_count))
        self.requests_total_moves.setText(str(total_moves))

        if rows:
            self.requests_status.setText(f"{len(rows)} request batch(es) available.")
            if self.requests_table.currentRow() < 0:
                self.requests_table.selectRow(0)
                self.on_requests_selection_changed()
        else:
            self.requests_status.setText("No submission batches yet.")
            self.requests_detail_text.setPlainText("Select a request batch to review its packaged details.")
            if hasattr(self, "requests_export_zip_btn"):
                self.requests_export_zip_btn.setEnabled(False)
            if hasattr(self, "requests_email_btn"):
                self.requests_email_btn.setEnabled(False)
            if hasattr(self, "requests_delete_test_btn"):
                self.requests_delete_test_btn.setEnabled(False)

    def on_requests_selection_changed(self):
        if not hasattr(self, "requests_table"):
            return
        selected_ranges = self.requests_table.selectedRanges()
        if not selected_ranges:
            self.requests_detail_text.setPlainText("Select a request batch to review its packaged details.")
            if hasattr(self, "requests_export_zip_btn"):
                self.requests_export_zip_btn.setEnabled(False)
            if hasattr(self, "requests_email_btn"):
                self.requests_email_btn.setEnabled(False)
            if hasattr(self, "requests_delete_test_btn"):
                self.requests_delete_test_btn.setEnabled(False)
            return
        row_index = selected_ranges[0].topRow()
        if row_index < 0 or row_index >= len(getattr(self, "_request_batch_rows", [])):
            self.requests_detail_text.setPlainText("Select a request batch to review its packaged details.")
            if hasattr(self, "requests_export_zip_btn"):
                self.requests_export_zip_btn.setEnabled(False)
            if hasattr(self, "requests_email_btn"):
                self.requests_email_btn.setEnabled(False)
            if hasattr(self, "requests_delete_test_btn"):
                self.requests_delete_test_btn.setEnabled(False)
            return

        row = self._request_batch_rows[row_index]
        if hasattr(self, "requests_export_zip_btn"):
            self.requests_export_zip_btn.setEnabled(True)
        if hasattr(self, "requests_email_btn"):
            self.requests_email_btn.setEnabled(True)
        if hasattr(self, "requests_delete_test_btn"):
            self.requests_delete_test_btn.setEnabled(
                bool(self.current_session_context.get("user_role", "user") == "admin" and row.get("is_test"))
            )
        payload = self.request_store.load_submission_batch(
            row.get("batch_id", ""),
            test_mode=bool(row.get("is_test")),
        )
        default_zip = Path(str(payload.get("path", ""))).with_suffix(".zip") if payload.get("path") else ""
        request = payload.get("request", {}) if isinstance(payload.get("request", {}), dict) else {}
        allocations = payload.get("allocations", []) if isinstance(payload.get("allocations", []), list) else []
        proposed = payload.get("proposed_folders", []) if isinstance(payload.get("proposed_folders", []), list) else []

        lines = [
            f"Batch ID: {row.get('batch_id', '')}",
            f"Type: {'Test' if row.get('is_test') else 'Live'}",
            f"Status: {row.get('status', '')}",
            f"Submitted: {row.get('submitted_utc', '')}",
            f"Submitted By: {row.get('submitted_by', '')}",
            f"Tenant: {row.get('tenant_domain', '') or 'Not available'}",
            f"Draft: {row.get('draft_name', '') or row.get('draft_id', '') or 'Not available'}",
            f"Source: {row.get('source_site', '')} / {row.get('source_library', '')}",
            f"Destination: {row.get('destination_site', '')} / {row.get('destination_library', '')}",
            f"Stored At: {payload.get('path', '')}",
            f"Default Zip: {default_zip or 'Not created yet'}",
            "",
            f"Allocations: {len(allocations)}",
        ]
        for allocation in allocations[:12]:
            lines.append(
                f"- {allocation.get('SourceItemName', '')} -> {allocation.get('RequestedDestinationPath', '')}"
            )
        if len(allocations) > 12:
            lines.append(f"... and {len(allocations) - 12} more allocation(s)")

        lines.extend(["", f"Proposed Folders: {len(proposed)}"])
        for proposed_folder in proposed[:12]:
            lines.append(f"- {proposed_folder.get('DestinationPath', '')}")
        if len(proposed) > 12:
            lines.append(f"... and {len(proposed) - 12} more proposed folder(s)")

        warnings = request.get("ValidationWarnings", []) if isinstance(request.get("ValidationWarnings", []), list) else []
        if warnings:
            lines.extend(["", "Validation Warnings:"])
            lines.extend(f"- {warning}" for warning in warnings)

        self.requests_detail_text.setPlainText("\n".join(lines))

    def _selected_request_batch_row(self):
        selected_ranges = self.requests_table.selectedRanges() if hasattr(self, "requests_table") else []
        if not selected_ranges:
            return None
        row_index = selected_ranges[0].topRow()
        if row_index < 0 or row_index >= len(getattr(self, "_request_batch_rows", [])):
            return None
        return self._request_batch_rows[row_index]

    def handle_export_request_zip(self):
        row = self._selected_request_batch_row()
        if row is None:
            QMessageBox.information(self, "Export Request Zip", "Select a request batch first.")
            return

        batch_id = str(row.get("batch_id", "")).strip()
        is_test = bool(row.get("is_test"))
        default_zip = self.request_store.export_submission_batch_zip(batch_id, test_mode=is_test)
        custom_zip_path, _ = QFileDialog.getSaveFileName(
            self,
            "Save Request Zip Copy",
            str(default_zip),
            "Submission Zip Bundle (*.zip)",
        )
        custom_zip_destination = None
        if custom_zip_path:
            custom_zip_destination = Path(custom_zip_path)
            if custom_zip_destination.suffix.lower() != ".zip":
                custom_zip_destination = custom_zip_destination.with_suffix(".zip")
            self.request_store.export_submission_batch_zip(
                batch_id,
                test_mode=is_test,
                destination_zip=custom_zip_destination,
            )

        if custom_zip_destination is not None:
            QMessageBox.information(
                self,
                "Export Request Zip",
                f"Default zip created at:\n{default_zip}\n\nAdditional zip copy saved to:\n{custom_zip_destination}",
            )
        else:
            QMessageBox.information(
                self,
                "Export Request Zip",
                f"Default zip created at:\n{default_zip}",
            )

    def handle_email_request_batch(self):
        row = self._selected_request_batch_row()
        if row is None:
            QMessageBox.information(self, "Email Ozlink IT", "Select a request batch first.")
            return

        batch_id = str(row.get("batch_id", "")).strip()
        is_test = bool(row.get("is_test"))
        default_zip = self.request_store.export_submission_batch_zip(batch_id, test_mode=is_test)
        subject = f"SharePoint Relocation Request {batch_id}"
        body = (
            f"Hello Ozlink IT,%0D%0A%0D%0A"
            f"Please find attached submission batch {batch_id}.%0D%0A%0D%0A"
            f"Default zip path:%0D%0A{default_zip}%0D%0A"
        )
        mail_url = QUrl(f"mailto:support@ozlink.it?subject={QUrl.toPercentEncoding(subject).data().decode()}&body={body}")
        QDesktopServices.openUrl(mail_url)
        QMessageBox.information(
            self,
            "Email Ozlink IT",
            f"Your mail client was opened for batch {batch_id}.\n\nPlease attach this zip:\n{default_zip}",
        )

    def handle_delete_test_request(self):
        if self.current_session_context.get("user_role", "user") != "admin":
            QMessageBox.warning(self, "Delete Test Batch", "Only admins can delete test batches.")
            return
        selected_ranges = self.requests_table.selectedRanges() if hasattr(self, "requests_table") else []
        if not selected_ranges:
            QMessageBox.information(self, "Delete Test Batch", "Select a test batch first.")
            return
        row_index = selected_ranges[0].topRow()
        if row_index < 0 or row_index >= len(getattr(self, "_request_batch_rows", [])):
            QMessageBox.information(self, "Delete Test Batch", "Select a test batch first.")
            return
        row = self._request_batch_rows[row_index]
        if not row.get("is_test"):
            QMessageBox.information(self, "Delete Test Batch", "Only test batches can be deleted.")
            return

        batch_id = str(row.get("batch_id", "")).strip()
        decision = QMessageBox.question(
            self,
            "Delete Test Batch",
            f"Delete test batch {batch_id}?\n\nThis will remove the packaged test request from disk.",
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.No,
        )
        if decision != QMessageBox.Yes:
            return

        self.request_store.delete_submission_batch(batch_id, test_mode=True)
        self.refresh_requests_page()
        self.requests_detail_text.setPlainText("Select a request batch to review its packaged details.")
        QMessageBox.information(self, "Delete Test Batch", f"Deleted test batch {batch_id}.")

    def build_tree_panel(self, title_text, empty_message, panel_key):
        box = QFrame()
        box.setObjectName("SectionBox")
        layout = QVBoxLayout(box)
        layout.setContentsMargins(18, 16, 18, 16)
        layout.setSpacing(12)

        title = QLabel(title_text)
        title.setObjectName("SectionTitle")
        expand_button = QPushButton(_EXPAND_ALL_TREE_GLYPH_EXPAND)
        expand_button.setObjectName("IconToolButton")
        expand_button.setToolTip("Expand all folders in this tree (may load in the background)")
        expand_button.clicked.connect(lambda _=False, panel_key=panel_key: self.handle_expand_all(panel_key))
        if panel_key == "source":
            refresh_cache_button = QPushButton(_REFRESH_CACHE_TREE_GLYPH)
            refresh_cache_button.setObjectName("IconToolButton")
            refresh_cache_button.setToolTip(_REFRESH_CACHE_TREE_TOOLTIP_IDLE)
            refresh_cache_button.clicked.connect(
                lambda _=False, panel_key=panel_key: self.handle_refresh_cache_for_panel(panel_key)
            )
            self.source_expand_all_button = expand_button
            self.source_refresh_cache_button = refresh_cache_button
            tree_refresh_widget = refresh_cache_button
        else:
            dest_refresh_tb = QToolButton()
            dest_refresh_tb.setObjectName("IconToolButton")
            dest_refresh_tb.setText(_REFRESH_CACHE_TREE_GLYPH)
            dest_refresh_tb.setToolTip(
                _REFRESH_CACHE_TREE_TOOLTIP_IDLE + " Use the arrow for Rebuild Cache / Full Resync (clears and reloads)."
            )
            dest_refresh_tb.setPopupMode(QToolButton.ToolButtonPopupMode.MenuButtonPopup)
            dest_menu = QMenu(dest_refresh_tb)
            act_rebuild = QAction("Rebuild Cache / Full Resync…", dest_refresh_tb)
            act_rebuild.setToolTip(
                "Clears the SharePoint folder cache for this library and reloads the destination tree from Microsoft 365. "
                "Slower; use when the incremental refresh is not enough."
            )
            act_rebuild.triggered.connect(self._handle_destination_rebuild_cache_full_resync)
            dest_menu.addAction(act_rebuild)
            dest_refresh_tb.setMenu(dest_menu)
            dest_refresh_tb.clicked.connect(lambda: self.handle_refresh_cache_for_panel("destination"))
            self.destination_expand_all_button = expand_button
            self.destination_refresh_cache_button = dest_refresh_tb
            tree_refresh_widget = dest_refresh_tb

        title_row = QHBoxLayout()
        title_row.setContentsMargins(0, 0, 0, 0)
        title_row.setSpacing(10)
        title_row.addWidget(title)
        title_row.addStretch()
        title_row.addWidget(tree_refresh_widget)
        title_row.addWidget(expand_button)

        surface = QFrame()
        surface.setObjectName("TreeSurface")
        surface_layout = QVBoxLayout(surface)
        surface_layout.setContentsMargins(6, 6, 6, 6)
        surface_layout.setSpacing(6)

        local_model = QFileSystemModel()
        local_model.setFilter(
            QDir.Filter.AllDirs | QDir.Filter.Files | QDir.Filter.NoDotAndDotDot
        )
        settings = QSettings()
        settings_key = f"planning/local_{panel_key}_root"
        default_root = QDir.homePath()
        root_path = str(settings.value(settings_key, default_root) or default_root).strip() or default_root
        try:
            if not Path(root_path).exists():
                root_path = default_root
        except OSError:
            root_path = default_root
        local_model.setRootPath(root_path)
        hdr_labels = []
        for i in range(EXPLORER_COLUMN_COUNT):
            lab = local_model.headerData(i, Qt.Horizontal, Qt.DisplayRole)
            hdr_labels.append(str(lab) if lab else EXPLORER_COLUMN_LABELS[i])

        if panel_key == "source":
            tree = QTreeView()
            self.source_sharepoint_model = SharePointSourceTreeModel(
                parent=tree,
                column_labels=hdr_labels,
                source_index_key_fn=self._source_payload_index_key,
            )
            tree.setModel(self.source_sharepoint_model)
            sharepoint_model_view = True
        elif panel_key == "destination":
            tree = DestinationPlanningTreeView()
            self.destination_planning_model = DestinationPlanningTreeModel(
                parent=tree,
                column_labels=hdr_labels,
                destination_index_key_fn=self._destination_payload_index_key,
            )
            self.destination_planning_model.destination_structure_changed.connect(
                self._on_destination_planning_model_structure_changed
            )
            tree.setModel(self.destination_planning_model)
            if getattr(self, "_dest_scroll_profiler", None) is not None:
                self._dest_scroll_profiler.install_on_destination_tree(tree, self.destination_planning_model)
                self.destination_planning_model._dest_scroll_profiler_ref = self._dest_scroll_profiler
            else:
                self.destination_planning_model._dest_scroll_profiler_ref = None
            self._sync_destination_plan_leaf_exclusion_paint_contract()
            sharepoint_model_view = True
        else:
            raise RuntimeError(f"build_tree_panel: unexpected panel_key {panel_key!r}")
        tree.setRootIsDecorated(True)
        tree.setItemsExpandable(True)
        tree.setExpandsOnDoubleClick(True)
        tree.setAnimated(False)
        tree.setAlternatingRowColors(False)
        tree.setUniformRowHeights(True)
        # Source: Ctrl+click multi-select for "Assign individually…"; destination stays single-select.
        tree.setSelectionMode(
            QAbstractItemView.ExtendedSelection if panel_key == "source" else QAbstractItemView.SingleSelection
        )
        tree.setIndentation(18)
        tree.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOn)
        tree.setHorizontalScrollMode(QAbstractItemView.ScrollPerPixel)
        tree.setVerticalScrollMode(QAbstractItemView.ScrollPerPixel)
        # Elide long names so Size/Type/Date columns are not painted over (ElideNone overflows cells).
        tree.setTextElideMode(Qt.ElideRight)
        if sharepoint_model_view:
            self._apply_planning_explorer_header_qtreeview_sharepoint(tree)
        else:
            self._apply_planning_explorer_header_qtreewidget(tree, hdr_labels)
        if panel_key == "destination":
            # Manual planning drag/drop on destination trees only (no Qt default model drag pipeline).
            tree.setDragEnabled(False)
            # Planning moves use internal mouse-driven drag only — no native Qt drop surface.
            tree.setAcceptDrops(False)
            tree.viewport().setAcceptDrops(False)
            tree.header().setAcceptDrops(False)
            tree.setDropIndicatorShown(False)
            tree.setDragDropMode(QAbstractItemView.NoDragDrop)
            tree.setDefaultDropAction(Qt.MoveAction)
            tree._ozlink_main_window = self
            if hasattr(tree, "proposedBranchMoveRequested"):
                tree.proposedBranchMoveRequested.connect(self.handle_destination_manual_drag_move)
            dragproof_log("tree_created", tree)

        local_tree = QTreeView()
        local_tree.setModel(local_model)
        local_tree.setRootIndex(local_model.index(local_model.rootPath()))
        local_tree.setRootIsDecorated(True)
        local_tree.setItemsExpandable(True)
        local_tree.setExpandsOnDoubleClick(True)
        local_tree.setAnimated(False)
        local_tree.setAlternatingRowColors(False)
        local_tree.setUniformRowHeights(True)
        local_tree.setSelectionMode(QAbstractItemView.SingleSelection)
        local_tree.setIndentation(18)
        local_tree.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOn)
        local_tree.setHorizontalScrollMode(QAbstractItemView.ScrollPerPixel)
        local_tree.setVerticalScrollMode(QAbstractItemView.ScrollPerPixel)
        local_tree.setTextElideMode(Qt.ElideRight)
        self._apply_planning_explorer_header_qtreeview_local(local_tree)
        local_tree.setDragDropMode(QAbstractItemView.NoDragDrop)

        tree_stack = QStackedWidget()
        tree_stack.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)
        tree_stack.setMinimumWidth(0)
        tree_stack.addWidget(tree)
        tree_stack.addWidget(local_tree)
        tree.setMinimumWidth(0)
        local_tree.setMinimumWidth(0)

        if panel_key == "source":
            self._source_tree_stack = tree_stack
            self.source_local_fs_tree = local_tree
            self.source_local_fs_model = local_model
            self._source_browse_mode = "sharepoint"
        else:
            self._destination_tree_stack = tree_stack
            self.destination_local_fs_tree = local_tree
            self.destination_local_fs_model = local_model
            self._destination_browse_mode = "sharepoint"

        status = QLabel(empty_message)
        status.setObjectName("MutedText")
        status.setWordWrap(False)
        status.setMinimumWidth(0)
        status.setSizePolicy(QSizePolicy.Ignored, QSizePolicy.Fixed)
        status.setStyleSheet("padding-top:6px; border-top:1px solid #20355E;")

        selection_summary = QLabel("")
        selection_summary.setVisible(False)
        selection_summary.setWordWrap(False)
        selection_summary.setAlignment(Qt.AlignRight | Qt.AlignVCenter)
        selection_summary.setSizePolicy(QSizePolicy.Ignored, QSizePolicy.Fixed)
        selection_summary.setFixedHeight(24)
        selection_summary.setMaximumWidth(520)
        selection_summary.setStyleSheet(
            "padding-top:6px; border-top:1px solid #20355E; color:#51E3F6; font-weight:700;"
        )

        footer_row = QHBoxLayout()
        footer_row.setContentsMargins(0, 0, 0, 0)
        footer_row.setSpacing(12)
        footer_row.addWidget(status, 1)
        footer_row.addWidget(selection_summary, 0)

        surface_layout.addWidget(tree_stack, 1)
        surface_layout.addLayout(footer_row)

        if panel_key == "source":
            self.source_tree_selection_summary = selection_summary
        else:
            self.destination_tree_selection_summary = selection_summary

        layout.addLayout(title_row)
        layout.addWidget(surface, 1)

        box.setMinimumWidth(0)
        surface.setMinimumWidth(0)

        return box, tree, status

    def _apply_planning_explorer_header_qtreewidget(self, tree, hdr_labels=None):
        tree.setColumnCount(EXPLORER_COLUMN_COUNT)
        labels = list(hdr_labels) if hdr_labels else list(EXPLORER_COLUMN_LABELS)
        tree.setHeaderLabels(labels[:EXPLORER_COLUMN_COUNT])
        tree.setHeaderHidden(False)
        hdr = tree.header()
        # Only the Name column absorbs extra width; Size/Type/Date stay content-sized (no overlap).
        hdr.setStretchLastSection(False)
        hdr.setMinimumSectionSize(48)
        hdr.setSectionResizeMode(0, QHeaderView.Stretch)
        hdr.setSectionResizeMode(1, QHeaderView.ResizeToContents)
        hdr.setSectionResizeMode(2, QHeaderView.ResizeToContents)
        hdr.setSectionResizeMode(3, QHeaderView.ResizeToContents)

    def _apply_planning_explorer_header_qtreeview_sharepoint(self, tree):
        tree.setHeaderHidden(False)
        hdr = tree.header()
        hdr.setStretchLastSection(False)
        hdr.setMinimumSectionSize(48)
        hdr.setSectionResizeMode(0, QHeaderView.Stretch)
        hdr.setSectionResizeMode(1, QHeaderView.ResizeToContents)
        hdr.setSectionResizeMode(2, QHeaderView.ResizeToContents)
        hdr.setSectionResizeMode(3, QHeaderView.ResizeToContents)

    def _apply_planning_explorer_header_qtreeview_local(self, tree):
        """Match QFileSystemModel: Name, Size, Type, Date modified — same as This PC / network."""
        tree.setHeaderHidden(False)
        hdr = tree.header()
        hdr.setStretchLastSection(False)
        hdr.setMinimumSectionSize(48)
        hdr.setSectionResizeMode(0, QHeaderView.Stretch)
        hdr.setSectionResizeMode(1, QHeaderView.ResizeToContents)
        hdr.setSectionResizeMode(2, QHeaderView.ResizeToContents)
        hdr.setSectionResizeMode(3, QHeaderView.ResizeToContents)

    def _apply_explorer_metadata_columns(self, item, node_data):
        if item is None or item.columnCount() < EXPLORER_COLUMN_COUNT:
            return
        if not isinstance(node_data, dict) or node_data.get("placeholder"):
            item.setText(1, "")
            item.setText(2, "")
            item.setText(3, "")
            return
        item.setText(1, explorer_size_label(node_data))
        item.setText(2, explorer_type_label(node_data))
        item.setText(3, explorer_date_label(node_data))

    def _tree_name_column_label(self, name: str, *, tag: str | None = None) -> str:
        """Name column text only (icons + Type column replace legacy ``Folder:`` / ``File:`` prefixes)."""
        base = str(name or "").strip() or "Unnamed Item"
        t = str(tag or "").strip()
        if t:
            return f"{base} {t}"
        return base

    def _planning_browse_mode(self, panel_key: str) -> str:
        return getattr(self, f"_{panel_key}_browse_mode", "sharepoint") or "sharepoint"

    def _active_source_tree_widget(self):
        return (
            self.source_local_fs_tree
            if self._planning_browse_mode("source") == "local"
            else self.source_tree_widget
        )

    def _active_destination_tree_widget(self):
        return (
            self.destination_local_fs_tree
            if self._planning_browse_mode("destination") == "local"
            else self.destination_tree_widget
        )

    def _expand_source_tree_item(self, item) -> None:
        """Expand one SharePoint source row (:class:`QTreeView` / :class:`QModelIndex`)."""
        tree = getattr(self, "source_tree_widget", None)
        if tree is None or item is None:
            return
        try:
            idx = item
            if isinstance(item, QPersistentModelIndex):
                idx = QModelIndex(item)
            if isinstance(idx, QModelIndex) and idx.isValid():
                if idx.column() != 0:
                    idx = idx.siblingAtColumn(0)
                _fte = getattr(self, "_full_trace_enabled", None)
                if callable(_fte) and _fte() and getattr(self, "_go_to_source_trace_session", False):
                    log_trace(
                        "ui",
                        "go_to_source_expand_source_tree_item",
                        row=idx.row(),
                        column=idx.column(),
                    )
                tree.expand(idx)
                pl_expand = idx.data(Qt.UserRole) or {}
                lazy_path = str(pl_expand.get("item_path") or pl_expand.get("display_path") or "").strip()
                if lazy_path and self.planned_moves:
                    self._schedule_source_projection_refresh_for_paths(
                        [lazy_path],
                        "source_projection_lazy_expand",
                        trigger_path=lazy_path,
                        delay_ms=0,
                        subtree_scope="roots_only",
                    )
            else:
                log_trace(
                    "ui",
                    "expand_source_tree_item_skipped",
                    reason="expected_qmodelindex",
                    item_type=type(item).__name__,
                )
        except Exception as exc:
            log_trace("ui", "expand_source_tree_item_failed", error=str(exc)[:200])

    def _apply_planning_panel_platform(self, panel_key: str, mode) -> None:
        """Sync header stacks, tree stack, and footer hint when source/destination platform changes."""
        mode = mode if mode in ("sharepoint", "local") else "sharepoint"
        setattr(self, f"_{panel_key}_browse_mode", mode)
        detail_stack = (
            self.source_platform_detail_stack
            if panel_key == "source"
            else self.destination_platform_detail_stack
        )
        tree_stack = self._source_tree_stack if panel_key == "source" else self._destination_tree_stack
        platform_combo = (
            self.source_platform_combo if panel_key == "source" else self.dest_platform_combo
        )
        if detail_stack is not None:
            detail_stack.setCurrentIndex(0 if mode == "sharepoint" else 1)
        if tree_stack is not None:
            tree_stack.setCurrentIndex(1 if mode == "local" else 0)
        if platform_combo is not None:
            platform_combo.blockSignals(True)
            platform_combo.setCurrentIndex(0 if mode == "sharepoint" else 1)
            platform_combo.blockSignals(False)
        status = self.source_tree_status if panel_key == "source" else self.destination_tree_status
        if status is not None:
            if mode == "local":
                status.setText(
                    "Local or UNC paths (C:\\… or \\\\server\\share\\…). Use header to change folder root, "
                    "select items, then Assign. Save a manifest and use Execution to dry-run or run copies."
                )
            else:
                base = (
                    "Review SharePoint folders here. Choose site and library in the header to load the tree."
                    if panel_key == "source"
                    else "Review destination folders here. Choose site and library in the header to load the tree."
                )
                if not self._graph_token_ready_for_sharepoint():
                    base += (
                        " In-app Microsoft 365 sign-in starts when you pick a library (or use Connect on the dashboard)."
                    )
                status.setText(base)
        self._refresh_local_platform_root_label(panel_key)
        self.update_selector_context_labels()
        self.on_tree_selection_changed(panel_key)
        if panel_key == "destination":
            ts = self._destination_tree_stack
            dragproof_log(
                "tree_shown",
                self.destination_tree_widget,
                browse_mode=mode,
                tree_stack_current=ts.currentIndex() if ts is not None else None,
                reason="apply_planning_panel_platform",
            )
            dragproof_log("tree_shown_active", self._active_destination_tree_widget(), browse_mode=mode)

    def _refresh_local_platform_root_label(self, panel_key: str) -> None:
        label = (
            self.source_header_root_label
            if panel_key == "source"
            else getattr(self, "destination_header_root_label", None)
        )
        model = (
            self.source_local_fs_model
            if panel_key == "source"
            else getattr(self, "destination_local_fs_model", None)
        )
        if label is None or model is None:
            return
        rp = model.rootPath()
        label.setText(rp or "—")
        label.setToolTip(rp or "")

    def _choose_local_fs_root(self, panel_key: str):
        model = self.source_local_fs_model if panel_key == "source" else self.destination_local_fs_model
        view = self.source_local_fs_tree if panel_key == "source" else self.destination_local_fs_tree
        start = model.rootPath()
        path = QFileDialog.getExistingDirectory(self, "Choose root folder for tree", start)
        if not path:
            return
        norm = self.normalize_memory_path(path)
        QSettings().setValue(f"planning/local_{panel_key}_root", norm)
        model.setRootPath(norm)
        view.setRootIndex(model.index(model.rootPath()))
        self._refresh_local_platform_root_label(panel_key)

    def _local_fs_node_from_index(self, tree_view: QTreeView, index: QModelIndex, tree_role: str):
        if index is None or not index.isValid():
            return None
        if index.column() != 0:
            index = index.siblingAtColumn(0)
        if not index.isValid():
            return None
        model = tree_view.model()
        if not isinstance(model, QFileSystemModel):
            return None
        abs_path = model.filePath(index)
        fi = model.fileInfo(index)
        if not fi.exists():
            return None
        name = fi.fileName()
        is_dir = fi.isDir()
        path_norm = self.normalize_memory_path(abs_path)
        prefix = "Folder" if is_dir else "File"
        node_id = f"localfs:{path_norm.casefold()}"
        row = {
            "id": node_id,
            "name": name,
            "real_name": name,
            "display_path": path_norm,
            "item_path": path_norm,
            "tree_role": tree_role,
            "drive_id": "",
            "library_id": "",
            "site_id": "",
            "is_folder": is_dir,
            "node_origin": "LocalFilesystem",
            "base_display_label": self._tree_name_column_label(name),
            "children_loaded": True,
            "placeholder": False,
        }
        if tree_role == "source":
            row["source_path"] = path_norm
        else:
            row["destination_path"] = path_norm
        try:
            st = Path(abs_path).stat()
            row["last_modified"] = datetime.fromtimestamp(st.st_mtime, tz=timezone.utc).strftime(
                "%Y-%m-%d %H:%M UTC"
            )
        except OSError:
            pass
        return row

    def _planned_move_uses_local_destination(self, move):
        if not isinstance(move, dict):
            return False
        dest = move.get("destination") if isinstance(move.get("destination"), dict) else {}
        return str(dest.get("node_origin", "")).lower() == "localfilesystem"

    def _loading_palette_color(self):
        colors = ["#FF5A5F", "#59D88F", "#51E3F6"]
        return colors[self._loading_visual_phase % len(colors)]

    def _success_palette_color(self):
        colors = ["#59D88F", "#7BE3A8", "#A7F1C4"]
        return colors[self._loading_visual_phase % len(colors)]

    def _refresh_loading_visual_timer(self):
        timer = getattr(self, "_loading_visual_timer", None)
        if timer is None:
            return
        tracked_labels = [
            getattr(self, "dashboard_status", None),
            getattr(self, "source_tree_status", None),
            getattr(self, "destination_tree_status", None),
        ]
        active = any(bool(label and label.property("loading_emphasis")) for label in tracked_labels)
        active = active or bool(
            getattr(self, "planning_loading_banner", None)
            and self.planning_loading_banner.property("loading_emphasis")
        )
        if active:
            if not timer.isActive():
                timer.start()
        else:
            timer.stop()

    def _apply_loading_visual_state(self, label, *, loading=False, kind="generic"):
        if label is None:
            return
        label.setProperty("loading_emphasis", bool(loading))
        label.setProperty("loading_emphasis_kind", kind)
        if loading:
            color = self._success_palette_color() if kind == "dashboard_success" else self._loading_palette_color()
            if kind == "tree":
                label.setStyleSheet(
                    f"padding-top:6px; border-top:1px solid #20355E; color:{color}; font-weight:700; font-size:10.8pt;"
                )
            else:
                label.setStyleSheet(
                    f"color:{color}; font-weight:700; font-size:11pt;"
                )
        else:
            if kind == "tree":
                label.setStyleSheet("padding-top:6px; border-top:1px solid #20355E;")
            else:
                label.setStyleSheet("")
        self._refresh_loading_visual_timer()

    def _animate_loading_visuals(self):
        self._loading_visual_phase += 1
        tracked_labels = [
            getattr(self, "dashboard_status", None),
            getattr(self, "source_tree_status", None),
            getattr(self, "destination_tree_status", None),
        ]
        for label in tracked_labels:
            if not label or not label.property("loading_emphasis"):
                continue
            kind = str(label.property("loading_emphasis_kind") or "generic")
            self._apply_loading_visual_state(label, loading=True, kind=kind)
        self._apply_planning_loading_banner_visual_state(
            bool(getattr(self, "planning_loading_banner", None) and self.planning_loading_banner.property("loading_emphasis"))
        )

    def _apply_planning_loading_banner_visual_state(self, loading=False):
        banner = getattr(self, "planning_loading_banner", None)
        if banner is None:
            return
        banner.setProperty("loading_emphasis", bool(loading))
        if loading:
            color = self._loading_palette_color()
            banner.setStyleSheet(
                f"QFrame#SoftBanner {{"
                f"background-color:#101C33;"
                f"border:1px solid {color};"
                f"border-radius:0px;"
                f"}}"
                f"QLabel#SectionTitle {{ color:{color}; font-weight:800; }}"
                f"QLabel#CardBody {{ color:#DCE8FF; }}"
            )
        else:
            banner.setStyleSheet("")
        self._refresh_loading_visual_timer()

    def _set_dashboard_status_message(self, message, *, loading=False):
        if hasattr(self, "dashboard_status") and self.dashboard_status is not None:
            self.dashboard_status.setText(message)
            self._apply_loading_visual_state(self.dashboard_status, loading=loading, kind="dashboard")

    def _set_dashboard_success_message(self, message):
        if hasattr(self, "dashboard_status") and self.dashboard_status is not None:
            self.dashboard_status.setText(message)
            self._apply_loading_visual_state(self.dashboard_status, loading=True, kind="dashboard_success")

    def _set_tree_status_message(self, panel_key, message, *, loading=False):
        # Keep destination expand-all status stable while the queue is active.
        # Other background status writes can rapidly toggle loading styles/colors.
        if (
            panel_key == "destination"
            and bool(getattr(self, "_expand_all_pending", {}).get("destination"))
        ):
            message_text = str(message or "")
            allowed_prefixes = (
                "Expanding branches",
                "Loading full destination tree",
                "All loaded branches expanded.",
                "Expand all cancelled.",
                "Loaded branches collapsed.",
                "Building destination preview",
                "Merging destination",
                "Destination preview",
            )
            if not any(message_text.startswith(prefix) for prefix in allowed_prefixes):
                return
        label = (
            getattr(self, "source_tree_status", None)
            if panel_key == "source"
            else getattr(self, "destination_tree_status", None)
        )
        if label is not None:
            label.setText(message)
            self._apply_loading_visual_state(label, loading=loading, kind="tree")

    def _destination_preview_async_status_message(self, state: dict[str, Any]) -> str:
        """User-facing destination preview progress during async descendant projection (chunked)."""
        ex = int(state.get("projection_descendants_examined", 0) or 0)
        sched = int(state.get("projection_descendants_scheduled", 0) or 0)
        mi = int(state.get("move_index", 0) or 0)
        moves = state.get("moves") or []
        total_moves = len(moves)
        sched_show = max(sched, ex)
        alloc_hint = ""
        if total_moves > 0:
            alloc_hint = f" · allocation {min(mi + 1, total_moves)}/{total_moves}"
        if sched <= 0 and ex <= 0:
            return (
                f"Building destination preview — projecting folders (scanning allocations){alloc_hint}…"
            )
        return (
            f"Building destination preview — projecting folders: {ex:,}/{sched_show:,} items{alloc_hint}"
        )

    def _set_window_title_status(self, status_text=""):
        title = str(getattr(self, "_base_window_title", "Ozlink IT – SharePoint File Relocation Console"))
        status_text = str(status_text or "").strip()
        if status_text:
            title = f"{title} • {status_text}"
        self.setWindowTitle(title)
        cap = getattr(self, "_custom_window_title_label", None)
        if cap is not None:
            cap.setText(title)

    def _collect_current_source_projection_paths(self):
        source_projection_paths = set(self._build_source_materialization_paths())
        source_projection_paths.update(self._collect_visible_source_relationship_paths())
        return source_projection_paths

    def _notify_planning_change_saved(self, message="Change saved. Background refresh queued."):
        if hasattr(self, "planned_moves_status") and self.planned_moves_status is not None:
            self.planned_moves_status.setText(message)
        self._set_window_title_status("Changes saved")

    def _graph_ids_enqueue_refresh_batch(
        self,
        spaths: set[str],
        *,
        notify_saved: bool,
        clear_source_path_lookups: bool,
    ) -> None:
        """Coalesce bursty ``graph_ids_resolved_from_sharepoint_paths`` persists into one flush + one deferred refresh."""
        if getattr(self, "_application_shutting_down", False):
            return
        merged_before = len(self._graph_ids_refresh_batch_paths)
        for p in spaths or set():
            c = self._canonical_source_projection_path(p)
            if c:
                self._graph_ids_refresh_batch_paths.add(c)
        self._graph_ids_refresh_batch_merge_events = int(self._graph_ids_refresh_batch_merge_events) + 1
        self._graph_ids_refresh_batch_notify_saved = bool(
            getattr(self, "_graph_ids_refresh_batch_notify_saved", False) or notify_saved
        )
        self._graph_ids_refresh_batch_clear_source_lookups = bool(
            getattr(self, "_graph_ids_refresh_batch_clear_source_lookups", False) or clear_source_path_lookups
        )
        if getattr(self, "_deferred_planning_refresh_running", False):
            self._graph_ids_refresh_followup_due = True
            tmr = getattr(self, "_graph_ids_refresh_batch_timer", None)
            if tmr is not None:
                tmr.stop()
            if is_dev_mode():
                log_info(
                    "graph_ids_refresh_batch_coalesce_enqueue",
                    action="merged_while_deferred_planning_refresh_running",
                    merge_event=int(self._graph_ids_refresh_batch_merge_events),
                    pending_path_count=len(self._graph_ids_refresh_batch_paths),
                    prior_pending_path_count=int(merged_before),
                    deferred_planning_refresh_running=True,
                )
            return
        delay_ms = 160
        try:
            if callable(getattr(self, "_destination_user_scroll_interaction_active", None)) and self._destination_user_scroll_interaction_active():
                delay_ms = max(delay_ms, 520)
        except Exception:
            pass
        if getattr(self, "_sharepoint_lazy_mode", False) and self._planning_workspace_is_busy():
            delay_ms = max(delay_ms, 900)
        tmr = getattr(self, "_graph_ids_refresh_batch_timer", None)
        if tmr is None:
            return
        tmr.stop()
        tmr.start(int(delay_ms))
        if is_dev_mode():
            log_info(
                "graph_ids_refresh_batch_coalesce_enqueue",
                action="scheduled_coalesced_flush",
                merge_event=int(self._graph_ids_refresh_batch_merge_events),
                pending_path_count=len(self._graph_ids_refresh_batch_paths),
                prior_pending_path_count=int(merged_before),
                delay_ms=int(delay_ms),
                deferred_planning_refresh_running=False,
            )

    def _graph_ids_drain_followup_after_deferred_refresh(self) -> None:
        """If graph-id work accumulated while ``_run_deferred_planning_refresh`` was running, run at most one coalesced flush."""
        if getattr(self, "_application_shutting_down", False):
            return
        if not getattr(self, "_graph_ids_refresh_followup_due", False) and not getattr(
            self, "_graph_ids_refresh_batch_paths", set()
        ):
            return
        self._graph_ids_refresh_followup_due = False
        self._flush_graph_ids_refresh_batch(flush_phase="followup_after_deferred")

    def _flush_graph_ids_refresh_batch(self, *, flush_phase: str = "coalesce_timer") -> None:
        """Single invalidate + deferred planning refresh after coalescing graph-id resolution bursts."""
        if getattr(self, "_application_shutting_down", False):
            return
        if getattr(self, "_deferred_planning_refresh_running", False):
            self._graph_ids_refresh_followup_due = True
            tmr = getattr(self, "_graph_ids_refresh_batch_timer", None)
            if tmr is not None:
                tmr.stop()
            if is_dev_mode():
                log_info(
                    "graph_ids_refresh_batch_flush_deferred",
                    reason="deferred_planning_refresh_running",
                    pending_path_count=len(self._graph_ids_refresh_batch_paths),
                )
            return
        paths = set(self._graph_ids_refresh_batch_paths)
        merged_events = int(getattr(self, "_graph_ids_refresh_batch_merge_events", 0) or 0)
        if not paths and merged_events == 0:
            return
        self._graph_ids_refresh_batch_paths.clear()
        self._graph_ids_refresh_batch_merge_events = 0
        clear_src = bool(getattr(self, "_graph_ids_refresh_batch_clear_source_lookups", False))
        self._graph_ids_refresh_batch_clear_source_lookups = False
        notify_combined = bool(getattr(self, "_graph_ids_refresh_batch_notify_saved", False))
        self._graph_ids_refresh_batch_notify_saved = False
        self._graph_ids_last_coalesced_merge_events = int(merged_events)
        if paths:
            self._evict_source_path_lookup_cache_entries(paths)
        self._invalidate_projection_lookup_caches(
            bump_generation=True,
            clear_source_path_cache=clear_src,
        )
        _t0 = time.perf_counter()
        try:
            self._queue_deferred_planning_refresh(
                "graph_ids_resolved_from_sharepoint_paths",
                source_projection_paths=paths,
                delay_ms=120,
                notify_saved=notify_combined,
            )
            if getattr(self, "source_tree_widget", None) is not None:
                self.source_tree_widget.viewport().update()
            if getattr(self, "destination_tree_widget", None) is not None:
                self.destination_tree_widget.viewport().update()
            self.update_progress_summaries()
        except Exception as exc:
            self._log_restore_exception("graph_ids_refresh_batch_flush.deferred_queue", exc)

        self._notify_planning_mutation_destination_snapshot_dirty(
            str(flush_phase or "graph_ids_refresh_batch_flush"),
            surface="graph_ids_batch",
        )
        _elapsed_ms = round((time.perf_counter() - _t0) * 1000.0, 3)
        log_info(
            "graph_ids_refresh_batch_flushed",
            flush_phase=str(flush_phase or "coalesce_timer"),
            merged_enqueue_events=int(merged_events),
            canonical_path_count=len(paths),
            flush_elapsed_ms=_elapsed_ms,
            followup_still_due=bool(getattr(self, "_graph_ids_refresh_followup_due", False)),
        )

    def _queue_deferred_planning_refresh(
        self, reason, *, source_projection_paths=None, delay_ms=None, notify_saved=True
    ):
        if getattr(self, "_application_shutting_down", False):
            log_info(
                "shutdown_trace",
                event="deferred_planning_refresh_queue_skipped",
                reason=str(reason or "")[:220],
            )
            return
        prev_reasons = list(getattr(self, "_deferred_planning_refresh_reasons", []))
        pending_before = bool(getattr(self, "_deferred_planning_refresh_pending", False))
        reason_text = str(reason or "").strip() or "planning_change"
        _incoming_paths = (
            [str(path or "").strip() for path in (source_projection_paths or []) if str(path or "").strip()]
            if source_projection_paths
            else []
        )
        if (
            reason_text == "graph_ids_resolved_from_sharepoint_paths"
            and getattr(self, "_graph_ids_deferred_planning_refresh_chunk_state", None) is not None
        ):
            _added = self._graph_ids_deferred_planning_refresh_merge_paths_into_active_chunk(_incoming_paths)
            if notify_saved:
                self._notify_planning_change_saved()
            log_info(
                "graph_ids_deferred_planning_refresh_queue_merged_into_active_chunk",
                added_paths=int(_added),
                skipped_deferred_timer_restart=True,
            )
            return
        if reason_text not in self._deferred_planning_refresh_reasons:
            self._deferred_planning_refresh_reasons.append(reason_text)
        if _incoming_paths:
            self._deferred_source_projection_paths.update(_incoming_paths)
        self._deferred_planning_refresh_pending = True
        if notify_saved:
            self._notify_planning_change_saved()

        timer = getattr(self, "_deferred_planning_refresh_timer", None)
        if timer is None:
            return

        interval = 450 if delay_ms is None else max(0, int(delay_ms))
        if getattr(self, "_sharepoint_lazy_mode", False) and self._planning_workspace_is_busy():
            interval = max(interval, 1200)
        timer.stop()
        timer.start(interval)
        if reason_text == "graph_ids_resolved_from_sharepoint_paths":
            log_info(
                "graph_ids_deferred_planning_queue",
                had_pending_deferred_refresh=bool(pending_before),
                reason_already_in_queue=bool(reason_text in prev_reasons),
                merged_into_existing_timer=bool(pending_before and (reason_text in prev_reasons)),
                deferred_path_accum_after=int(len(self._deferred_source_projection_paths)),
                timer_restart_ms=int(interval),
            )

    def _deferred_planning_refresh_compute_skip_full_and_overlay_decision(self, reasons, combined_reason):
        """Shared skip/overlay flags for deferred planning refresh (inner + graph_ids chunk driver).

        When several incremental reasons coalesce (e.g. ``planning_change_lightweight`` + manual drag),
        we must keep ``skip_full_destination_future_model`` true and avoid escalating overlay backlog
        into a broad destination finalize — that path treated narrowed bind scope like a full replay and
        collapsed most visible planned rows (see narrow overlay routing + ``deferred_*__*`` reason parsing).
        """
        _manual_drag_only = (
            len(reasons) == 1
            and bool(reasons)
            and str(reasons[0] or "") == "planned_item_moved_manual_drag"
        )
        # Coalesced queues join multiple reasons with "__"; every incremental-only reason must still
        # skip full destination finalize — otherwise a drag follow-up merged with
        # planning_change_lightweight ran a broad materialize path and collapsed visible planned rows.
        _all_incremental_only = planning_interaction_contract.deferred_refresh_reasons_are_all_incremental(
            reasons,
            _INCREMENTAL_DEFERRED_PLANNING_REFRESH_REASONS,
        )
        skip_full_destination_future_model = bool(_all_incremental_only)
        if _manual_drag_only:
            skip_full_destination_future_model = True
        if reasons == ["graph_ids_resolved_from_sharepoint_paths"]:
            skip_full_destination_future_model = True
        force_dest_full = bool(getattr(self, "_destination_require_deferred_full_materialize_once", False))
        if _manual_drag_only:
            force_dest_full = False
            skip_full_destination_future_model = True
        elif force_dest_full:
            skip_full_destination_future_model = False
        overlay_backlog = int(self._unresolved_proposed_queue_size() or 0) + int(
            self._unresolved_allocation_queue_size() or 0
        )
        # Do not force broad destination overlay for backlog when the batch is still incremental-only
        # (narrow drag-move follow-up must not escalate to full-tree rebuild).
        if overlay_backlog > 0 and not _manual_drag_only and not _all_incremental_only:
            skip_full_destination_future_model = False
            if is_dev_mode():
                log_info(
                    "deferred_planning_refresh",
                    mode="overlay_backlog_forces_full_destination",
                    reasons=combined_reason,
                    unresolved_proposed=int(self._unresolved_proposed_queue_size() or 0),
                    unresolved_allocation=int(self._unresolved_allocation_queue_size() or 0),
                )
        _quiet_struct_sup = bool(getattr(self, "_destination_quiet_startup_overlay_structural_suppress", False))
        if _quiet_struct_sup:
            if overlay_backlog > 0:
                self._destination_quiet_startup_overlay_structural_suppress = False
                log_info(
                    "destination_quiet_startup_overlay_suppress_cleared",
                    reason="unresolved_overlay_backlog_nonzero",
                    unresolved_proposed=int(self._unresolved_proposed_queue_size() or 0),
                    unresolved_allocation=int(self._unresolved_allocation_queue_size() or 0),
                )
            else:
                force_dest_full = False
                skip_full_destination_future_model = True
                log_info(
                    "destination_quiet_startup_deferred_overlay_suppressed",
                    reasons=str(combined_reason)[:220],
                    skip_full_destination_future_model=True,
                )
        _dest_tree = getattr(self, "destination_tree_widget", None)
        _outer_dest_overlay = (
            _dest_tree is not None
            and ((not skip_full_destination_future_model) or force_dest_full)
        )
        _run_dest_overlay = bool(
            _outer_dest_overlay and not self._destination_steady_state_full_materialize_redundant()
        )
        return {
            "skip_full_destination_future_model": bool(skip_full_destination_future_model),
            "force_dest_full": bool(force_dest_full),
            "overlay_backlog": int(overlay_backlog),
            "_run_dest_overlay": bool(_run_dest_overlay),
        }

    def _graph_ids_deferred_planning_refresh_merge_paths_into_active_chunk(self, paths) -> int:
        """Append unique source projection paths to an in-flight graph_ids chunk job; returns paths added."""
        st = getattr(self, "_graph_ids_deferred_planning_refresh_chunk_state", None)
        if not isinstance(st, dict):
            return 0
        base = st.setdefault("source_paths", [])
        seen = set(base)
        added = 0
        for p in paths or []:
            s = str(p or "").strip()
            if not s or s in seen:
                continue
            seen.add(s)
            base.append(s)
            added += 1
        return int(added)

    def _graph_ids_deferred_planning_refresh_chunk_schedule_next(self) -> None:
        QTimer.singleShot(
            0,
            lambda: self._safe_invoke(
                "graph_ids_deferred_planning_refresh_chunk",
                self._graph_ids_deferred_planning_refresh_chunk_tick,
            ),
        )

    def _graph_ids_deferred_planning_refresh_chunk_complete(self) -> None:
        self._graph_ids_deferred_planning_refresh_chunk_state = None
        self._deferred_planning_refresh_running = False
        self._graph_ids_drain_followup_after_deferred_refresh()
        if getattr(self, "_deferred_planning_refresh_pending", False):
            _tmr = getattr(self, "_deferred_planning_refresh_timer", None)
            if _tmr is not None:
                _tmr.start(0)

    def _graph_ids_deferred_planning_refresh_begin_chunked(
        self, reasons, combined_reason, source_projection_paths
    ) -> None:
        paths_list = sorted({str(p).strip() for p in source_projection_paths if str(p or "").strip()})
        st = getattr(self, "_graph_ids_deferred_planning_refresh_chunk_state", None)
        if isinstance(st, dict):
            self._graph_ids_deferred_planning_refresh_merge_paths_into_active_chunk(paths_list)
            prev_r = list(st.get("reasons") or [])
            for _r in list(reasons or []):
                if _r not in prev_r:
                    prev_r.append(_r)
            st["reasons"] = prev_r
            st["combined_reason"] = "__".join(prev_r) if prev_r else str(combined_reason)
            log_info(
                "graph_ids_deferred_planning_refresh_chunk_restarted_merge",
                combined_reason=str(st.get("combined_reason") or combined_reason)[:220],
                source_projection_path_count=int(len(st.get("source_paths") or [])),
                merged_reason_count=int(len(prev_r)),
            )
            return
        if (
            "graph_ids_resolved_from_sharepoint_paths" in list(reasons or [])
            and not self._destination_startup_heavy_work_allowed()
        ):
            self._destination_merge_deferred_graph_ids_refresh_pending(reasons, combined_reason, paths_list)
            pend = getattr(self, "_destination_deferred_graph_ids_refresh_pending", None) or {}
            log_info(
                "graph_ids_overlay_queued_until_background_hydration",
                startup_ui_phase=str(getattr(self, "_destination_startup_ui_phase", "") or "")[:40],
                merged_reason_count=len(list(pend.get("reasons") or [])),
                pending_path_count=len(list(pend.get("source_paths") or [])),
            )
            return
        log_info(
            "graph_ids_deferred_planning_refresh_chunk_path_entered",
            combined_reason=str(combined_reason)[:220],
            reason_count=int(len(reasons or [])),
            reasons_excerpt=[str(x)[:120] for x in (reasons or [])][:12],
            source_projection_path_count=int(len(paths_list)),
        )
        self._graph_ids_deferred_planning_refresh_chunk_state = {
            "reasons": list(reasons),
            "combined_reason": str(combined_reason),
            "source_paths": paths_list,
            "source_cursor": 0,
            "phase": 0,
            "chunk_seq": 0,
        }
        self._graph_ids_deferred_planning_refresh_chunk_schedule_next()

    def _graph_ids_deferred_planning_refresh_chunk_tick(self) -> None:
        if getattr(self, "_application_shutting_down", False):
            self._graph_ids_deferred_planning_refresh_chunk_state = None
            self._deferred_planning_refresh_running = False
            return
        st = getattr(self, "_graph_ids_deferred_planning_refresh_chunk_state", None)
        if not isinstance(st, dict):
            return
        if "graph_ids_resolved_from_sharepoint_paths" in (st.get("reasons") or []):
            _scroll_fn = getattr(self, "_destination_user_scroll_interaction_active", None)
            try:
                _scrolling = bool(callable(_scroll_fn) and _scroll_fn())
            except Exception:
                _scrolling = False
            if _scrolling:
                _defer_ms = max(120, int(getattr(self, "_destination_tree_scroll_idle_ms", 280) or 280))
                QTimer.singleShot(
                    _defer_ms,
                    lambda: self._safe_invoke(
                        "graph_ids_deferred_planning_refresh_chunk_scroll_idle",
                        self._graph_ids_deferred_planning_refresh_chunk_tick,
                    ),
                )
                log_info(
                    "graph_ids_deferred_planning_refresh_chunk_deferred_for_destination_scroll",
                    defer_ms=int(_defer_ms),
                    phase=int(st.get("phase", 0) or 0),
                )
                return

        phase = int(st.get("phase", 0) or 0)
        st["chunk_seq"] = int(st.get("chunk_seq", 0) or 0) + 1
        chunk_seq = int(st["chunk_seq"])
        t_chunk0 = time.perf_counter()
        reasons = list(st.get("reasons") or [])
        combined_reason = str(st.get("combined_reason") or "")
        _path_budget = 24
        _chunk_budget_ms = 4.0

        def _phase_name(p: int) -> str:
            return {
                0: "init_flags",
                1: "enumerate_first",
                2: "destination_overlay",
                3: "source_projection_paths",
                4: "enumerate_second",
                5: "finalize",
            }.get(p, f"phase_{p}")

        def _chunk_log(phase_idx: int, items_processed: int, extra: Optional[Dict[str, Any]] = None) -> None:
            elapsed_ms = round((time.perf_counter() - t_chunk0) * 1000.0, 3)
            payload = {
                "phase": int(phase_idx),
                "phase_name": str(_phase_name(phase_idx)),
                "chunk_seq": int(chunk_seq),
                "items_processed": int(items_processed),
                "elapsed_ms": float(elapsed_ms),
            }
            if extra:
                payload.update(extra)
            log_info("graph_ids_deferred_planning_refresh_chunk", **payload)
            if elapsed_ms > _chunk_budget_ms:
                log_info(
                    "graph_ids_deferred_planning_refresh_chunk_budget_exceeded",
                    phase=int(phase_idx),
                    phase_name=str(_phase_name(phase_idx)),
                    chunk_seq=int(chunk_seq),
                    elapsed_ms=float(elapsed_ms),
                    budget_ms=float(_chunk_budget_ms),
                )

        try:
            if phase == 0:
                _gid_wall0 = time.perf_counter()
                st["_gid_wall0"] = _gid_wall0
                log_info(
                    "graph_ids_deferred_planning_refresh_begin",
                    combined_reason=str(combined_reason)[:220],
                    source_projection_path_count=int(len(st.get("source_paths") or [])),
                    graph_ids_coalesced_merge_events=int(
                        getattr(self, "_graph_ids_last_coalesced_merge_events", 0) or 0
                    ),
                )
                _dec = self._deferred_planning_refresh_compute_skip_full_and_overlay_decision(reasons, combined_reason)
                st.update(_dec)
                self._destination_lifecycle_trace_TEMP(
                    fn="_run_deferred_planning_refresh",
                    reason=combined_reason,
                    step_kind="projection_materialize",
                    extra=(
                        "skip_full_destination_future_model="
                        + str(st.get("skip_full_destination_future_model"))
                        + ";n_src_paths="
                        + str(len(st.get("source_paths") or []))
                    ),
                )
                if is_dev_mode():
                    if st.get("skip_full_destination_future_model"):
                        log_info(
                            "deferred_planning_refresh",
                            mode="incremental_only",
                            reasons=combined_reason,
                            skip_full_destination=True,
                        )
                    else:
                        violators = [r for r in reasons if r not in _INCREMENTAL_DEFERRED_PLANNING_REFRESH_REASONS]
                        log_info(
                            "deferred_planning_refresh",
                            mode="full_destination_finalize",
                            reasons=combined_reason,
                            skip_full_destination=False,
                            non_incremental_reasons=violators,
                        )
                st["_finalize_overlay_structural"] = False
                st["_vp_finalize_before"] = -1
                st["_vp_finalize_after"] = -1
                st["_pex"] = {}
                _chunk_log(0, 0)
                st["phase"] = 1
                self._graph_ids_deferred_planning_refresh_chunk_schedule_next()
                return

            if phase == 1:
                _pex = st.setdefault("_pex", {})
                _run_dest_overlay = bool(st.get("_run_dest_overlay"))
                _t_enum0 = time.perf_counter()
                _vp_finalize_before = -1
                try:
                    if getattr(self, "destination_planning_model", None) is not None:
                        _vp_fb, _av_fb = self._destination_enumerate_visible_planned_paths_and_all_visible()
                        _vp_finalize_before = len(_vp_fb)
                        if not _run_dest_overlay:
                            st["_vp_finalize_after"] = _vp_finalize_before
                except Exception:
                    _vp_finalize_before = -1
                    if not _run_dest_overlay:
                        st["_vp_finalize_after"] = -1
                finally:
                    _pex["enumerate_first_wall_ms"] = round((time.perf_counter() - _t_enum0) * 1000.0, 3)
                st["_vp_finalize_before"] = int(_vp_finalize_before)
                log_info(
                    "destination_finalize_started",
                    combined_reason=str(combined_reason)[:220],
                    skip_full_destination_future_model=bool(st.get("skip_full_destination_future_model")),
                    force_destination_full=bool(st.get("force_dest_full")),
                    visible_planned_before=int(_vp_finalize_before),
                    run_destination_overlay=bool(_run_dest_overlay),
                )
                _chunk_log(1, max(0, int(_vp_finalize_before)))
                st["phase"] = 2
                self._graph_ids_deferred_planning_refresh_chunk_schedule_next()
                return

            if phase == 2:
                _pex = st.setdefault("_pex", {})
                _run_dest_overlay = bool(st.get("_run_dest_overlay"))
                items_overlay = 0
                if _run_dest_overlay:
                    st["_finalize_overlay_structural"] = True
                    _graph_resolve = "graph_ids_resolved_from_sharepoint_paths" in reasons
                    if (
                        bool(getattr(self, "_memory_restore_in_progress", False))
                        and self._destination_graph_authority_supersedes_memory_restore_gate()
                    ):
                        log_info(
                            "destination_overlay_gate_bypass_for_authority",
                            caller="_run_deferred_planning_refresh_chunked",
                            combined_reason=str(combined_reason)[:200],
                            detail="deferred_planning_refresh_runs_destination_overlays_under_graph_authority",
                        )
                    _forensic_deferred = dest_forensic.slow_pass_forensic_enabled() and (
                        "graph_ids_resolved_from_sharepoint_paths" in reasons
                    )
                    st["_forensic_deferred"] = bool(_forensic_deferred)
                    _mat_reason = f"deferred_{combined_reason}"
                    _t_def = time.perf_counter()
                    self._apply_destination_planning_overlays(
                        _mat_reason,
                        allow_defer=True,
                        prefer_chunked_projection=bool(_graph_resolve),
                    )
                    _pex["apply_destination_planning_overlays_wall_ms"] = round(
                        (time.perf_counter() - _t_def) * 1000.0, 3
                    )
                    items_overlay = 1
                    if _forensic_deferred:
                        log_info(
                            "destination_slow_pass_forensic",
                            phase="deferred_graph_ids_resolved_from_sharepoint_paths",
                            combined_reason=str(combined_reason)[:220],
                            materialize_reason=str(_mat_reason)[:220],
                            apply_destination_planning_overlays_ms=round(
                                (time.perf_counter() - _t_def) * 1000.0, 2
                            ),
                            skip_full_destination_future_model=bool(st.get("skip_full_destination_future_model")),
                            allow_defer_destination=True,
                            overlay_terminal_reconcile_done_after_apply=bool(
                                getattr(self, "_destination_overlay_terminal_reconcile_done", False)
                            ),
                        )
                    if bool(st.get("force_dest_full")):
                        self._destination_require_deferred_full_materialize_once = False
                _chunk_log(2, int(items_overlay))
                st["phase"] = 3
                self._graph_ids_deferred_planning_refresh_chunk_schedule_next()
                return

            if phase == 3:
                _pex = st.setdefault("_pex", {})
                paths = list(st.get("source_paths") or [])
                _t_src = time.perf_counter()
                if getattr(self, "source_tree_widget", None) is None or not paths:
                    _pex["source_projection_schedule_wall_ms"] = round((time.perf_counter() - _t_src) * 1000.0, 3)
                    _pex["source_projection_paths_scheduled"] = 0
                    _chunk_log(3, 0, {"source_cursor": int(len(paths)), "source_total": int(len(paths))})
                    st["phase"] = 4
                    self._graph_ids_deferred_planning_refresh_chunk_schedule_next()
                    return
                try:
                    i0 = int(st.get("source_cursor", 0) or 0)
                    processed = 0
                    t_budget = time.perf_counter()
                    while i0 < len(paths):
                        batch = paths[i0 : i0 + _path_budget]
                        i0 += len(batch)
                        processed += len(batch)
                        self._schedule_source_projection_refresh_for_paths(
                            batch,
                            f"source_projection_deferred_{combined_reason}",
                            delay_ms=50,
                            subtree_scope="roots_only",
                        )
                        if (time.perf_counter() - t_budget) * 1000.0 >= _chunk_budget_ms:
                            break
                    st["source_cursor"] = int(i0)
                    _pex["source_projection_paths_scheduled"] = int(len(paths))
                    _pex["source_projection_schedule_wall_ms"] = round((time.perf_counter() - _t_src) * 1000.0, 3)
                    _chunk_log(3, int(processed), {"source_cursor": int(i0), "source_total": int(len(paths))})
                    if i0 < len(paths):
                        self._graph_ids_deferred_planning_refresh_chunk_schedule_next()
                        return
                except Exception as exc:
                    self._log_restore_exception("deferred_planning_refresh.source", exc)
                    _pex["source_projection_schedule_wall_ms"] = round((time.perf_counter() - _t_src) * 1000.0, 3)
                st["phase"] = 4
                self._graph_ids_deferred_planning_refresh_chunk_schedule_next()
                return

            if phase == 4:
                _pex = st.setdefault("_pex", {})
                _run_dest_overlay = bool(st.get("_run_dest_overlay"))
                if _run_dest_overlay:
                    _t_enum1 = time.perf_counter()
                    try:
                        if getattr(self, "destination_planning_model", None) is not None:
                            _vp_fa, _av_fa = self._destination_enumerate_visible_planned_paths_and_all_visible()
                            st["_vp_finalize_after"] = len(_vp_fa)
                        else:
                            st["_vp_finalize_after"] = int(st.get("_vp_finalize_before", -1) or -1)
                    except Exception:
                        st["_vp_finalize_after"] = -1
                    _pex["enumerate_second_wall_ms"] = round((time.perf_counter() - _t_enum1) * 1000.0, 3)
                    _pex["destination_enumerate_second_pass"] = True
                else:
                    _pex["destination_enumerate_second_pass_skipped"] = True
                    _pex["enumerate_second_wall_ms"] = 0.0
                _vp_b = int(st.get("_vp_finalize_before", -1) or -1)
                _vp_a = int(st.get("_vp_finalize_after", -1) or -1)
                log_info(
                    "destination_finalize_finished",
                    combined_reason=str(combined_reason)[:220],
                    skip_full_destination_future_model=bool(st.get("skip_full_destination_future_model")),
                    visible_planned_before=int(_vp_b),
                    visible_planned_after=int(_vp_a),
                    ran_full_destination_overlay_pass=bool(st.get("_finalize_overlay_structural")),
                    destination_enumerate_second_pass_skipped=bool(not _run_dest_overlay),
                )
                _chunk_log(4, max(0, _vp_a))
                st["phase"] = 5
                self._graph_ids_deferred_planning_refresh_chunk_schedule_next()
                return

            if phase == 5:
                _pex = st.setdefault("_pex", {})
                _t_prog = time.perf_counter()
                self.update_progress_summaries()
                _pex["progress_summaries_wall_ms"] = round((time.perf_counter() - _t_prog) * 1000.0, 3)
                _t_title = time.perf_counter()
                self._set_window_title_status()
                _pex["window_title_status_wall_ms"] = round((time.perf_counter() - _t_title) * 1000.0, 3)
                if "graph_ids_resolved_from_sharepoint_paths" in reasons:
                    _pex["graph_ids_coalesced_merge_events"] = int(
                        getattr(self, "_graph_ids_last_coalesced_merge_events", 0) or 0
                    )
                    self._graph_ids_last_coalesced_merge_events = 0
                _gid_wall0 = float(st.get("_gid_wall0") or time.perf_counter())
                log_info(
                    "graph_ids_deferred_planning_refresh_end",
                    combined_reason=str(combined_reason)[:220],
                    elapsed_ms=round((time.perf_counter() - _gid_wall0) * 1000.0, 2),
                    source_projection_path_count=int(len(st.get("source_paths") or [])),
                )
                _chunk_log(5, 1, {"chunk_driver": "graph_ids_cooperative"})
                self._graph_ids_deferred_planning_refresh_chunk_complete()
                return
        except Exception as exc:
            self._log_restore_exception("graph_ids_deferred_planning_refresh_chunk", exc)
            self._graph_ids_deferred_planning_refresh_chunk_complete()

    def _run_deferred_planning_refresh(self):
        if getattr(self, "_application_shutting_down", False):
            timer = getattr(self, "_deferred_planning_refresh_timer", None)
            if timer is not None:
                try:
                    timer.stop()
                except Exception:
                    pass
            had_pending = bool(getattr(self, "_deferred_planning_refresh_pending", False))
            self._deferred_planning_refresh_pending = False
            self._deferred_planning_refresh_reasons = []
            self._deferred_source_projection_paths = set()
            self._graph_ids_deferred_planning_refresh_chunk_state = None
            log_info(
                "shutdown_trace",
                event="deferred_planning_refresh_skipped",
                reason="application_shutting_down",
                had_pending_refresh=had_pending,
            )
            return
        if not getattr(self, "_deferred_planning_refresh_pending", False):
            return
        if self._restore_abort_active():
            self._deferred_planning_refresh_pending = False
            self._deferred_planning_refresh_reasons = []
            self._deferred_source_projection_paths = set()
            self._graph_ids_deferred_planning_refresh_chunk_state = None
            self._log_restore_phase(
                "deferred_planning_refresh_skipped",
                reason="restore_abort_mode",
                restore_abort_reason=str(getattr(self, "_restore_abort_reason", "") or ""),
            )
            return

        reasons = list(getattr(self, "_deferred_planning_refresh_reasons", []))
        combined_reason = "__".join(reasons) if reasons else "deferred_planning_refresh"
        source_projection_paths = set(getattr(self, "_deferred_source_projection_paths", set()))

        if (
            getattr(self, "_graph_ids_deferred_planning_refresh_chunk_state", None) is not None
            and "graph_ids_resolved_from_sharepoint_paths" in reasons
        ):
            self._graph_ids_deferred_planning_refresh_merge_paths_into_active_chunk(
                [str(p) for p in source_projection_paths]
            )
            self._deferred_planning_refresh_pending = False
            self._deferred_planning_refresh_reasons = []
            self._deferred_source_projection_paths = set()
            log_info(
                "graph_ids_deferred_planning_refresh_timer_flush_merged_into_active_chunk",
                merged_source_paths=int(len(source_projection_paths)),
            )
            return

        # Graph-ID refresh walks overlays / projection caches on the GUI thread (~seconds). If the user is
        # actively scrolling the destination tree, postpone until scroll idle (same window as indicator defer).
        if "graph_ids_resolved_from_sharepoint_paths" in reasons:
            _scroll_fn = getattr(self, "_destination_user_scroll_interaction_active", None)
            try:
                _scrolling = bool(callable(_scroll_fn) and _scroll_fn())
            except Exception:
                _scrolling = False
            if _scrolling:
                _defer_ms = max(120, int(getattr(self, "_destination_tree_scroll_idle_ms", 280) or 280))
                _tmr = getattr(self, "_deferred_planning_refresh_timer", None)
                if _tmr is not None:
                    _tmr.stop()
                    _tmr.start(_defer_ms)
                log_info(
                    "graph_ids_deferred_planning_refresh_deferred_for_destination_scroll",
                    defer_ms=int(_defer_ms),
                    source_projection_path_count=int(len(source_projection_paths)),
                    combined_reason=str(combined_reason)[:220],
                )
                return

        self._deferred_planning_refresh_pending = False
        self._deferred_planning_refresh_reasons = []
        self._deferred_source_projection_paths = set()

        if "graph_ids_resolved_from_sharepoint_paths" in reasons:
            self._deferred_planning_refresh_running = True
            try:
                self._graph_ids_deferred_planning_refresh_begin_chunked(
                    reasons,
                    combined_reason,
                    source_projection_paths,
                )
            except Exception:
                self._deferred_planning_refresh_running = False
                self._graph_ids_deferred_planning_refresh_chunk_state = None
                raise
            return

        self._deferred_planning_refresh_running = True
        try:
            self._run_deferred_planning_refresh_inner(
                reasons,
                combined_reason,
                source_projection_paths,
            )
        finally:
            self._deferred_planning_refresh_running = False
            self._graph_ids_drain_followup_after_deferred_refresh()

    def _run_deferred_planning_refresh_inner(self, reasons, combined_reason, source_projection_paths):
        _gid_wall0 = None
        if "graph_ids_resolved_from_sharepoint_paths" in reasons:
            _gid_wall0 = time.perf_counter()
            log_info(
                "graph_ids_deferred_planning_refresh_begin",
                combined_reason=str(combined_reason)[:220],
                source_projection_path_count=int(len(source_projection_paths)),
                graph_ids_coalesced_merge_events=int(
                    getattr(self, "_graph_ids_last_coalesced_merge_events", 0) or 0
                ),
            )
        _dec = self._deferred_planning_refresh_compute_skip_full_and_overlay_decision(reasons, combined_reason)
        skip_full_destination_future_model = _dec["skip_full_destination_future_model"]
        force_dest_full = _dec["force_dest_full"]
        _run_dest_overlay = _dec["_run_dest_overlay"]
        if reasons == ["planned_item_moved_manual_drag"]:
            log_info(
                "drag_move_finalize_narrow_path_enforced",
                combined_reason=str(combined_reason)[:220],
                skip_full_destination_future_model=bool(skip_full_destination_future_model),
                run_destination_overlay=bool(_run_dest_overlay),
            )
        self._destination_lifecycle_trace_TEMP(
            fn="_run_deferred_planning_refresh",
            reason=combined_reason,
            step_kind="projection_materialize",
            extra=f"skip_full_destination_future_model={skip_full_destination_future_model};n_src_paths={len(source_projection_paths)}",
        )
        if is_dev_mode():
            if skip_full_destination_future_model:
                log_info(
                    "deferred_planning_refresh",
                    mode="incremental_only",
                    reasons=combined_reason,
                    skip_full_destination=True,
                )
            else:
                violators = [r for r in reasons if r not in _INCREMENTAL_DEFERRED_PLANNING_REFRESH_REASONS]
                log_info(
                    "deferred_planning_refresh",
                    mode="full_destination_finalize",
                    reasons=combined_reason,
                    skip_full_destination=False,
                    non_incremental_reasons=violators,
                )

        _finalize_overlay_structural = False
        _vp_finalize_before = -1
        _vp_finalize_after = -1
        with _PerfExplorerTimer(
            "run_deferred_planning_refresh",
            combined_reason=combined_reason,
            skip_full_destination_future_model=bool(skip_full_destination_future_model),
            source_projection_path_count=len(source_projection_paths),
            run_destination_overlay=bool(_run_dest_overlay),
        ) as _deferred_plan_perf_cm:
            _pex = _deferred_plan_perf_cm.extra
            _t_enum0 = time.perf_counter()
            try:
                if getattr(self, "destination_planning_model", None) is not None:
                    _vp_fb, _av_fb = self._destination_enumerate_visible_planned_paths_and_all_visible()
                    _vp_finalize_before = len(_vp_fb)
                    if not _run_dest_overlay:
                        _vp_finalize_after = _vp_finalize_before
            except Exception:
                _vp_finalize_before = -1
                if not _run_dest_overlay:
                    _vp_finalize_after = -1
            finally:
                _pex["enumerate_first_wall_ms"] = round((time.perf_counter() - _t_enum0) * 1000.0, 3)
            log_info(
                "destination_finalize_started",
                combined_reason=str(combined_reason)[:220],
                skip_full_destination_future_model=bool(skip_full_destination_future_model),
                force_destination_full=bool(force_dest_full),
                visible_planned_before=int(_vp_finalize_before),
                run_destination_overlay=bool(_run_dest_overlay),
            )
            try:
                if _run_dest_overlay:
                    _finalize_overlay_structural = True
                    # Graph path/id enrichment may queue folder loads; allow idle defer again so the
                    # GUI thread can paint between materialize/reconcile chunks (see startup chunking).
                    _graph_resolve = "graph_ids_resolved_from_sharepoint_paths" in reasons
                    if (
                        bool(getattr(self, "_memory_restore_in_progress", False))
                        and self._destination_graph_authority_supersedes_memory_restore_gate()
                    ):
                        log_info(
                            "destination_overlay_gate_bypass_for_authority",
                            caller="_run_deferred_planning_refresh",
                            combined_reason=str(combined_reason)[:200],
                            detail="deferred_planning_refresh_runs_destination_overlays_under_graph_authority",
                        )
                    _forensic_deferred = dest_forensic.slow_pass_forensic_enabled() and (
                        "graph_ids_resolved_from_sharepoint_paths" in reasons
                    )
                    _mat_reason = f"deferred_{combined_reason}"
                    _t_def = time.perf_counter()
                    self._apply_destination_planning_overlays(
                        _mat_reason,
                        allow_defer=True,
                        prefer_chunked_projection=bool(_graph_resolve),
                    )
                    _pex["apply_destination_planning_overlays_wall_ms"] = round(
                        (time.perf_counter() - _t_def) * 1000.0, 3
                    )
                    if _forensic_deferred:
                        log_info(
                            "destination_slow_pass_forensic",
                            phase="deferred_graph_ids_resolved_from_sharepoint_paths",
                            combined_reason=str(combined_reason)[:220],
                            materialize_reason=str(_mat_reason)[:220],
                            apply_destination_planning_overlays_ms=round(
                                (time.perf_counter() - _t_def) * 1000.0, 2
                            ),
                            skip_full_destination_future_model=bool(skip_full_destination_future_model),
                            allow_defer_destination=True,
                            overlay_terminal_reconcile_done_after_apply=bool(
                                getattr(self, "_destination_overlay_terminal_reconcile_done", False)
                            ),
                        )
                    if force_dest_full:
                        self._destination_require_deferred_full_materialize_once = False
            except Exception as exc:
                self._log_restore_exception("deferred_planning_refresh.destination", exc)

            try:
                _t_src = time.perf_counter()
                if getattr(self, "source_tree_widget", None) is not None and source_projection_paths:
                    self._schedule_source_projection_refresh_for_paths(
                        source_projection_paths,
                        f"source_projection_deferred_{combined_reason}",
                        delay_ms=50,
                    )
                _pex["source_projection_schedule_wall_ms"] = round((time.perf_counter() - _t_src) * 1000.0, 3)
                _pex["source_projection_paths_scheduled"] = int(len(source_projection_paths))
            except Exception as exc:
                self._log_restore_exception("deferred_planning_refresh.source", exc)
                _pex["source_projection_schedule_wall_ms"] = round((time.perf_counter() - _t_src) * 1000.0, 3)

            if _run_dest_overlay:
                _t_enum1 = time.perf_counter()
                try:
                    if getattr(self, "destination_planning_model", None) is not None:
                        _vp_fa, _av_fa = self._destination_enumerate_visible_planned_paths_and_all_visible()
                        _vp_finalize_after = len(_vp_fa)
                    else:
                        _vp_finalize_after = _vp_finalize_before
                except Exception:
                    _vp_finalize_after = -1
                _pex["enumerate_second_wall_ms"] = round((time.perf_counter() - _t_enum1) * 1000.0, 3)
                _pex["destination_enumerate_second_pass"] = True
            else:
                _pex["destination_enumerate_second_pass_skipped"] = True
                _pex["enumerate_second_wall_ms"] = 0.0
            log_info(
                "destination_finalize_finished",
                combined_reason=str(combined_reason)[:220],
                skip_full_destination_future_model=bool(skip_full_destination_future_model),
                visible_planned_before=int(_vp_finalize_before),
                visible_planned_after=int(_vp_finalize_after),
                ran_full_destination_overlay_pass=bool(_finalize_overlay_structural),
                destination_enumerate_second_pass_skipped=bool(not _run_dest_overlay),
            )

            _t_prog = time.perf_counter()
            self.update_progress_summaries()
            _pex["progress_summaries_wall_ms"] = round((time.perf_counter() - _t_prog) * 1000.0, 3)

            _t_title = time.perf_counter()
            self._set_window_title_status()
            _pex["window_title_status_wall_ms"] = round((time.perf_counter() - _t_title) * 1000.0, 3)
            if "graph_ids_resolved_from_sharepoint_paths" in reasons:
                _pex["graph_ids_coalesced_merge_events"] = int(
                    getattr(self, "_graph_ids_last_coalesced_merge_events", 0) or 0
                )
                self._graph_ids_last_coalesced_merge_events = 0

        if "graph_ids_resolved_from_sharepoint_paths" in reasons and _gid_wall0 is not None:
            log_info(
                "graph_ids_deferred_planning_refresh_end",
                combined_reason=str(combined_reason)[:220],
                elapsed_ms=round((time.perf_counter() - _gid_wall0) * 1000.0, 2),
                source_projection_path_count=int(len(source_projection_paths)),
            )

    def _flush_deferred_planning_refresh(self):
        timer = getattr(self, "_deferred_planning_refresh_timer", None)
        if timer is not None:
            timer.stop()
        self._run_deferred_planning_refresh()

    def _tree_selection_summary_label(self, panel_key):
        if panel_key == "source":
            return getattr(self, "source_tree_selection_summary", None)
        return getattr(self, "destination_tree_selection_summary", None)

    def _set_tree_selection_summary(self, panel_key, text=""):
        label = self._tree_selection_summary_label(panel_key)
        if label is None:
            return
        message = str(text or "").strip()
        label.setToolTip(message)
        if message:
            metrics = label.fontMetrics()
            available_width = max(220, label.width() or 420)
            message = metrics.elidedText(message, Qt.ElideRight, available_width)
        label.setText(message)
        label.setVisible(bool(message))

    def _expand_all_button_for_panel(self, panel_key):
        if panel_key == "source":
            return getattr(self, "source_expand_all_button", None)
        return getattr(self, "destination_expand_all_button", None)

    def _set_expand_all_button_label(self, panel_key, expanded):
        button = self._expand_all_button_for_panel(panel_key)
        if button is None:
            return
        if expanded:
            button.setText(_EXPAND_ALL_TREE_GLYPH_COLLAPSE)
            tip = "Collapse all expanded folders in this tree"
        else:
            button.setText(_EXPAND_ALL_TREE_GLYPH_EXPAND)
            tip = "Expand all folders in this tree (may load in the background)"
        if hasattr(button, "setToolTip"):
            button.setToolTip(tip)

    def _destination_note_expand_state_changed_for_loaded_branch_cache(self, *_args) -> None:
        """Expand/collapse does not change model structure; invalidate sliced loaded-branch cache."""
        self._destination_invalidate_loaded_branch_state_cache()
        self._destination_schedule_loaded_branch_state_recompute()

    def _destination_invalidate_loaded_branch_state_cache(self) -> None:
        self._destination_lbs_cache_valid = False
        self._destination_lbs_recompute_queue = None
        t = getattr(self, "_destination_lbs_recompute_timer", None)
        if t is not None and t.isActive():
            t.stop()

    def _destination_schedule_loaded_branch_state_recompute(self) -> None:
        t = getattr(self, "_destination_lbs_recompute_timer", None)
        if t is None:
            return
        if not t.isActive():
            t.start(0)

    def _destination_tick_loaded_branch_state_recompute(self) -> None:
        """Time-sliced BFS for loaded-branch / expand-all button state (no single-tick full tree walk)."""
        tree = getattr(self, "destination_tree_widget", None)
        model = getattr(self, "destination_planning_model", None)
        if model is None or tree is None:
            return
        if self._destination_user_scroll_interaction_active():
            t = getattr(self, "_destination_lbs_recompute_timer", None)
            if t is not None:
                t.start(max(40, int(getattr(self, "_destination_lbs_defer_during_scroll_ms", 80) or 80)))
            return
        op = QElapsedTimer()
        op.start()
        budget_ms = int(getattr(self, "_destination_lbs_budget_ms", 5) or 5)
        if self._destination_lbs_recompute_queue is None:
            q: list = []
            for r in range(model.rowCount(QModelIndex())):
                q.append(model.index(r, 0, QModelIndex()))
            self._destination_lbs_recompute_queue = q
            self._destination_lbs_partial_has_loaded = False
            self._destination_lbs_loaded_folder_total = 0
            self._destination_lbs_expanded_loaded_total = 0
        queue = self._destination_lbs_recompute_queue
        while queue and op.elapsed() < budget_ms:
            ix = queue.pop(0)
            if not ix.isValid():
                continue
            node_data = ix.data(Qt.UserRole) or {}
            if node_data.get("placeholder"):
                continue
            real_children = []
            for r in range(model.rowCount(ix)):
                cix = model.index(r, 0, ix)
                cdata = cix.data(Qt.UserRole) or {}
                if cdata.get("placeholder"):
                    continue
                real_children.append(cix)
            if bool(node_data.get("is_folder")) and real_children:
                self._destination_lbs_partial_has_loaded = True
                self._destination_lbs_loaded_folder_total += 1
                if tree.isExpanded(ix):
                    self._destination_lbs_expanded_loaded_total += 1
            queue.extend(real_children)
        if queue:
            self._destination_lbs_recompute_queue = queue
            self._destination_lbs_recompute_timer.start(0)
            return
        loaded_n = int(getattr(self, "_destination_lbs_loaded_folder_total", 0) or 0)
        exp_n = int(getattr(self, "_destination_lbs_expanded_loaded_total", 0) or 0)
        self._destination_loaded_folder_count = loaded_n
        self._destination_expanded_loaded_folder_count = exp_n
        has_loaded = bool(self._destination_lbs_partial_has_loaded)
        self._destination_lbs_cache_has_loaded = has_loaded
        self._destination_lbs_cache_all_expanded = (not has_loaded) or (exp_n == loaded_n)
        self._destination_lbs_cache_valid = True
        self._destination_lbs_recompute_queue = None

    def _panel_loaded_branch_state_planning_model(self, tree):
        model = getattr(self, "destination_planning_model", None)
        if model is None or tree is None:
            return False, False
        if not getattr(self, "_destination_lbs_cache_valid", False):
            self._destination_schedule_loaded_branch_state_recompute()
            return (
                getattr(self, "_destination_lbs_cache_has_loaded", False),
                getattr(self, "_destination_lbs_cache_all_expanded", True),
            )
        return self._destination_lbs_cache_has_loaded, self._destination_lbs_cache_all_expanded

    def _panel_loaded_branch_state(self, panel_key):
        tree = self.source_tree_widget if panel_key == "source" else self.destination_tree_widget
        if tree is None:
            return False, False
        if not callable(getattr(tree, "topLevelItemCount", None)):
            return self._panel_loaded_branch_state_planning_model(tree)

        has_loaded_branches = False
        all_loaded_branches_expanded = True
        queue = list(self._iter_panel_top_level_rows(panel_key))
        while queue:
            item = queue.pop(0)
            if item is None:
                continue
            node_data = self.get_tree_item_node_data(item) or {}
            if node_data.get("placeholder"):
                continue
            real_children = []
            if isinstance(item, QModelIndex):
                model = item.model()
                if model is not None:
                    for index in range(model.rowCount(item)):
                        child = model.index(index, 0, item)
                        child_data = child.data(Qt.UserRole) or {}
                        if child_data.get("placeholder"):
                            continue
                        real_children.append(child)
            else:
                for index in range(item.childCount()):
                    child = item.child(index)
                    child_data = child.data(0, Qt.UserRole) or {}
                    if child_data.get("placeholder"):
                        continue
                    real_children.append(child)
            if bool(node_data.get("is_folder")) and real_children:
                has_loaded_branches = True
                if isinstance(item, QModelIndex):
                    if not tree.isExpanded(item):
                        all_loaded_branches_expanded = False
                elif not item.isExpanded():
                    all_loaded_branches_expanded = False
            queue.extend(real_children)
        return has_loaded_branches, all_loaded_branches_expanded

    def _panel_is_expanded_all(self, panel_key):
        has_loaded_branches, all_loaded_branches_expanded = self._panel_loaded_branch_state(panel_key)
        # "All expanded" should also require no remaining lazy/unloaded folders.
        # Otherwise the button can claim completion while branches still show
        # "Expand to load contents" placeholders.
        if self._tree_has_unloaded_folder_nodes(panel_key):
            return False
        if has_loaded_branches:
            return all_loaded_branches_expanded
        return False

    def _panel_can_collapse_loaded_branches(self, panel_key):
        """True when every folder that already has real (non-placeholder) children is expanded.

        Unlike _panel_is_expanded_all, this ignores lazy/unloaded folder rows. Otherwise after
        expand-all stops early (allocations, throttling), the button still said Expand All and
        the next click started another expand pass (bigger counter, Expanding...) instead of
        Collapse All.
        """
        has_loaded_branches, all_loaded_branches_expanded = self._panel_loaded_branch_state(panel_key)
        return bool(has_loaded_branches and all_loaded_branches_expanded)

    def _sync_expand_all_button_from_tree(self, panel_key, fallback_expanded=False):
        has_loaded_branches, all_loaded_branches_expanded = self._panel_loaded_branch_state(panel_key)
        expanded = all_loaded_branches_expanded if has_loaded_branches else bool(fallback_expanded)
        self._set_expand_all_button_label(panel_key, expanded)
        return expanded

    def _refresh_expand_all_button_for_panel(self, panel_key):
        """Align expand/collapse label with session intent only when it matches the real tree.

        If the session says expand-all was saved but loaded branches are not all expanded yet
        (large snapshot restore, lazy folders, or destination semantic-path mismatch), forcing
        *Collapse All* makes the next click run the collapse path and feels like expand-all is
        broken.
        """
        intent = getattr(self, "_workspace_restore_expanded_all_intent", None) or {}
        if intent.get(panel_key) and self._panel_can_collapse_loaded_branches(panel_key):
            self._set_expand_all_button_label(panel_key, True)
            return
        self._sync_expand_all_button_from_tree(panel_key, fallback_expanded=False)

    def _persist_workspace_ui_state_safely(self):
        try:
            if self._workspace_ui_persist_should_defer():
                self._workspace_ui_snapshot_dirty_panels.update({"source", "destination"})
                t = getattr(self, "_workspace_ui_persist_timer", None)
                if t is not None:
                    t.start(2000)
                log_info(
                    "Workspace UI persist deferred (restore or materialisation active).",
                    workspace_ui_persist_deferred=True,
                )
                log_info(
                    "draft_save_deferred",
                    reason="workspace_ui_persist_defer",
                    detail=self._workspace_ui_persist_defer_reason(),
                )
                return
            self._save_draft_shell(force=True, include_workspace_ui=True)
        except Exception as exc:
            self._log_restore_exception("persist_workspace_ui_state", exc)

    def _destination_force_live_snapshot_allowed(self) -> bool:
        """Force-live destination snapshot walk is UI-heavy; allow only during save or shutdown capture."""
        return bool(getattr(self, "_destination_save_in_progress", False)) or bool(
            getattr(self, "_application_shutting_down", False)
        )

    def _refresh_runtime_tree_snapshot(self, panel_key):
        if panel_key not in {"source", "destination"}:
            return []
        if panel_key == "destination":
            _fr = bool(getattr(self, "_destination_runtime_snapshot_force_refresh_during_tick", False))
            if _fr and not self._destination_force_live_snapshot_allowed():
                self._destination_runtime_snapshot_force_refresh_during_tick = False
        dirty_dest_before = bool(
            panel_key == "destination" and getattr(self, "_destination_tree_snapshot_dirty_for_persist", False)
        )
        if (
            panel_key == "destination"
            and getattr(self, "_destination_descendant_apply_tick_running", False)
            and not bool(getattr(self, "_destination_runtime_snapshot_force_refresh_during_tick", False))
        ):
            self._post_tick_snapshot_refresh_pending = True
            self._destination_post_tick_deferred_boundary_log(
                "snapshot_refresh_deferred_because_tick_running",
                panel_key=str(panel_key),
            )
            rs = getattr(self, "_runtime_session_tree_snapshots", None)
            return list(rs.get("destination", [])) if isinstance(rs, dict) and isinstance(rs.get("destination"), list) else []
        snapshots = self._capture_tree_items_snapshot(panel_key)
        runtime_snapshots = getattr(self, "_runtime_session_tree_snapshots", None)
        if not isinstance(runtime_snapshots, dict):
            runtime_snapshots = {"source": [], "destination": []}
            self._runtime_session_tree_snapshots = runtime_snapshots
        runtime_snapshots[panel_key] = list(snapshots or [])
        if panel_key == "destination":
            try:
                _snap_n = int(self._count_tree_snapshot_nodes(snapshots or []))
            except Exception:
                _snap_n = -1
            _prev_sn = int(getattr(self, "_destination_snapshot_prev_recursive_node_count", -1) or -1)
            if _snap_n >= 0:
                log_info(
                    "destination_snapshot_node_count_transition",
                    previous_recursive_nodes=int(_prev_sn),
                    current_recursive_nodes=int(_snap_n),
                    delta=int(_snap_n - _prev_sn) if _prev_sn >= 0 else None,
                )
                if _prev_sn >= 0 and _snap_n < _prev_sn:
                    log_info(
                        "destination_snapshot_node_drop_audit",
                        previous_recursive_nodes=int(_prev_sn),
                        current_recursive_nodes=int(_snap_n),
                        drop_kind_hint="compare_placeholder_dedupe_and_metrics",
                    )
                    if (_prev_sn - _snap_n) <= max(1, int(_prev_sn * 0.05)):
                        log_info(
                            "destination_snapshot_node_drop_metric_difference",
                            note="small_delta_may_be_placeholder_or_recursive_counting_difference",
                        )
                self._destination_snapshot_prev_recursive_node_count = int(_snap_n)
        if panel_key == "destination" and dirty_dest_before:
            log_info(
                "destination_snapshot_refreshed_from_live_model",
                trigger="runtime_session_cache_refresh_after_dirty_injection",
                top_level_nodes=len(snapshots or []),
            )
        return runtime_snapshots[panel_key]

    def _destination_descendant_allocation_descendant_burst_active(self) -> bool:
        if bool(getattr(self, "_destination_descendant_apply_tick_running", False)):
            return True
        if getattr(self, "_destination_descendant_apply_state", None) is not None:
            return True
        dq = getattr(self, "_destination_descendant_apply_queue", None)
        try:
            if dq is not None and len(dq) > 0:
                return True
        except Exception:
            pass
        try:
            hdq = getattr(self, "_destination_deferred_heavy_replay_queue", None)
            if hdq is not None and len(hdq) > 0:
                return True
        except Exception:
            pass
        return False

    def _destination_heavy_replay_threshold(self) -> int:
        raw = str(os.environ.get("OZLINK_HEAVY_DESCENDANT_REPLAY_THRESHOLD", "") or "").strip()
        if raw:
            try:
                return max(50, min(500_000, int(raw)))
            except ValueError:
                pass
        return 400

    def _destination_heavy_replay_max_ops_per_tick(self) -> int:
        raw = str(os.environ.get("OZLINK_HEAVY_REPLAY_MAX_OPS_PER_TICK", "") or "").strip()
        if raw:
            try:
                return max(1, min(32, int(raw)))
            except ValueError:
                pass
        return 3

    def _destination_heavy_replay_defer_drain_base_ms(self) -> int:
        raw = str(os.environ.get("OZLINK_HEAVY_REPLAY_DEFER_BASE_MS", "") or "").strip()
        if raw:
            try:
                return max(120, min(120_000, int(raw)))
            except ValueError:
                pass
        return 800

    def _destination_heavy_replay_should_defer_enqueue(self, expected_descendant_count: int) -> tuple[bool, str]:
        th = int(self._destination_heavy_replay_threshold())
        if int(expected_descendant_count or 0) < th:
            return False, f"below_threshold_n={th}"
        if self._destination_user_scroll_interaction_active():
            return True, "user_scrolling"
        if not self._destination_startup_heavy_work_allowed():
            return True, f"startup_ui_phase={str(getattr(self, '_destination_startup_ui_phase', '') or '')[:32]}"
        return False, "admit_immediately"

    def _destination_deferred_heavy_replay_enqueue(
        self,
        parent_ix: QModelIndex,
        move,
        on_complete,
        *,
        enqueue_reason: str,
        collect_reason: str,
        expected_n: int,
        defer_code: str,
        idle_bounded: bool = False,
        explicit_repair_authorized: bool = False,
    ) -> None:
        mk = str(self._allocation_move_key(move) or "")[:220]
        dq = getattr(self, "_destination_deferred_heavy_replay_queue", None)
        if dq is None:
            dq = deque()
            self._destination_deferred_heavy_replay_queue = dq
        for ent in dq:
            try:
                if len(ent) > 5 and str(ent[5] or "") == mk:
                    log_info(
                        "destination_heavy_replay_deferred_deduped",
                        move_key_excerpt=mk[:120],
                        expected_descendant_count=int(expected_n),
                    )
                    return
            except Exception:
                continue
        dq.append(
            (
                parent_ix,
                move,
                on_complete,
                str(enqueue_reason or ""),
                str(collect_reason or ""),
                mk,
                int(expected_n or 0),
                bool(idle_bounded),
                bool(explicit_repair_authorized),
            )
        )
        log_info(
            "destination_heavy_descendant_classified_deferred",
            expected_descendant_count=int(expected_n),
            threshold=int(self._destination_heavy_replay_threshold()),
            defer_reason=str(defer_code or "")[:80],
            queue_len=len(dq),
            move_key_excerpt=mk[:120],
        )
        self._destination_schedule_deferred_heavy_replay_drain(
            int(self._destination_heavy_replay_defer_drain_base_ms())
        )

    def _destination_schedule_deferred_heavy_replay_drain(self, delay_ms: int) -> None:
        if getattr(self, "_application_shutting_down", False):
            return
        t = getattr(self, "_destination_heavy_replay_drain_timer", None)
        if t is None:
            t = QTimer(self)
            t.setSingleShot(True)
            t.timeout.connect(
                lambda: self._safe_invoke("destination_deferred_heavy_replay_drain", self._destination_drain_deferred_heavy_replay_one)
            )
            self._destination_heavy_replay_drain_timer = t
        try:
            t.start(max(80, int(delay_ms)))
        except Exception:
            t.start(500)

    def _destination_drain_deferred_heavy_replay_one(self) -> None:
        """Try to admit at most one heavy replay from the deferred queue when user + startup are idle."""
        if getattr(self, "_application_shutting_down", False):
            return
        if getattr(self, "_destination_descendant_apply_state", None) is not None:
            return
        try:
            if len(getattr(self, "_destination_descendant_apply_queue", None) or ()):
                return
        except Exception:
            return
        hdq = getattr(self, "_destination_deferred_heavy_replay_queue", None)
        if not hdq or len(hdq) == 0:
            return
        _ent0 = hdq[0]
        try:
            peek = int(_ent0[6] or 0) if len(_ent0) > 6 else int(_ent0[-1] or 0)
        except Exception:
            peek = 0
        defer, code = self._destination_heavy_replay_should_defer_enqueue(peek)
        if defer:
            log_info(
                "destination_heavy_replay_still_deferred",
                expected_descendant_count=int(peek),
                reason=str(code)[:100],
                queue_len=len(hdq),
            )
            if "scroll" in str(code).lower() or "scrolling" in str(code).lower():
                self._destination_schedule_deferred_heavy_replay_drain(420)
            else:
                self._destination_schedule_deferred_heavy_replay_drain(650)
            return
        ent = hdq.popleft()
        if len(ent) < 7:
            return
        parent_ix, move, on_complete, enq_r, col_r, _mk = ent[0], ent[1], ent[2], ent[3], ent[4], ent[5]
        try:
            exp_n = int(ent[6] or 0)
        except Exception:
            exp_n = 0
        idle_b = bool(ent[7]) if len(ent) > 7 else False
        exp_repair = bool(ent[8]) if len(ent) > 8 else False
        log_info(
            "destination_heavy_replay_resumed_after_idle",
            expected_descendant_count=int(exp_n),
            queue_remaining=len(hdq),
            move_key_excerpt=str(_mk or "")[:120],
        )
        self._enqueue_destination_descendant_apply_to_model(
            parent_ix,
            move,
            on_complete,
            enqueue_reason=str(enq_r or ""),
            collect_reason=str(col_r or ""),
            skip_heavy_replay_defer=True,
            user_initiated=True,
            idle_bounded=idle_b,
            explicit_repair_authorized=bool(exp_repair),
        )

    def _destination_after_descendant_apply_job_slot_cleared(self) -> None:
        if getattr(self, "_destination_descendant_apply_state", None) is not None:
            return
        try:
            if len(getattr(self, "_destination_descendant_apply_queue", None) or ()):
                return
        except Exception:
            return
        self._destination_drain_deferred_heavy_replay_one()

    def _destination_descendant_snapshot_coalescing_eligible(self, reason: str) -> bool:
        """Allocation-descendant injection reasons batch post-tick promotion; planning/other stay immediate."""
        r = str(reason or "")
        return bool(r.startswith("allocation_descendant"))

    def _destination_descendant_snapshot_batch_chunk_threshold(self) -> int:
        raw = os.environ.get("OZLINK_DESCENDANT_SNAPSHOT_BATCH_CHUNK_SUPPRESSIONS", "").strip()
        if raw:
            try:
                return max(8, min(512, int(raw)))
            except ValueError:
                pass
        return 32

    def _destination_descendant_snapshot_batch_max_delay_ms(self) -> int:
        raw = os.environ.get("OZLINK_DESCENDANT_SNAPSHOT_BATCH_MAX_DELAY_MS", "").strip()
        if raw:
            try:
                return max(400, min(60000, int(raw)))
            except ValueError:
                pass
        return 2000

    def _destination_maybe_schedule_descendant_snapshot_max_delay_timer(self) -> None:
        if getattr(self, "_application_shutting_down", False):
            return
        delay_ms = int(self._destination_descendant_snapshot_batch_max_delay_ms())
        t = getattr(self, "_destination_descendant_snapshot_dirty_max_delay_timer", None)
        if t is None:
            try:
                t = QTimer(self)
                t.setSingleShot(True)
                t.timeout.connect(
                    lambda: self._safe_invoke(
                        "destination_descendant_snapshot_max_delay_flush",
                        lambda: self._destination_flush_descendant_snapshot_dirty_batch(
                            "max_delay_timer",
                            force=True,
                            skip_scroll_guard=True,
                        ),
                    )
                )
                self._destination_descendant_snapshot_dirty_max_delay_timer = t
            except Exception:
                return
        try:
            t.stop()
            t.start(max(1, delay_ms))
        except Exception:
            pass

    def _destination_flush_descendant_snapshot_dirty_batch(
        self,
        flush_reason: str,
        *,
        force: bool = False,
        skip_scroll_guard: bool = False,
    ) -> bool:
        """Coalesced flush: promote runtime snapshot + schedule workspace persist once."""
        fr = str(flush_reason or "")[:120]
        pending_batch = bool(getattr(self, "_destination_descendant_snapshot_dirty_pending", False))
        if not pending_batch:
            log_info(
                "destination_descendant_snapshot_dirty_flush_skipped",
                flush_reason=fr,
                note="no_pending_batched_dirty",
            )
            return False
        scroll_active = False
        try:
            scroll_active = bool(self._destination_user_scroll_interaction_active())
        except Exception:
            scroll_active = False
        if scroll_active and not force and not skip_scroll_guard and fr not in (
            "shutdown",
            "before_shutdown",
            "before_save",
            "draft_save",
            "before_export",
            "max_delay_timer",
        ):
            self._destination_descendant_snapshot_dirty_flush_pending_after_scroll = True
            log_info(
                "destination_descendant_snapshot_dirty_flush_deferred_for_scroll",
                flush_reason=fr,
                suppressed_since_flush=int(getattr(self, "_destination_descendant_snapshot_dirty_suppressed_post_tick", 0) or 0),
            )
            return False

        t0 = time.perf_counter()
        try:
            rc = dict(getattr(self, "_destination_descendant_snapshot_dirty_reason_counts", Counter()) or {})
        except Exception:
            rc = {}
        affected_n = 0
        try:
            affected_n = len(getattr(self, "_destination_descendant_snapshot_dirty_affected_paths", set()) or set())
        except Exception:
            affected_n = 0

        self._destination_descendant_snapshot_dirty_batch_active = False
        self._destination_descendant_snapshot_dirty_pending = False
        self._destination_descendant_snapshot_dirty_reason_counts = Counter()
        self._destination_descendant_snapshot_dirty_first_mono = 0.0
        self._destination_descendant_snapshot_dirty_suppressed_post_tick = 0
        self._destination_descendant_snapshot_dirty_affected_paths = set()
        tmr = getattr(self, "_destination_descendant_snapshot_dirty_max_delay_timer", None)
        if tmr is not None:
            try:
                tmr.stop()
            except Exception:
                pass

        self._destination_descendant_snapshot_coalesce_actual_flushes += 1
        # Deferred runner refuses while tick_running — pending survives until end of tick / idle.
        self._post_tick_snapshot_refresh_pending = True
        try:
            if not bool(getattr(self, "_destination_descendant_apply_tick_running", False)):
                self._destination_run_post_tick_descendant_deferred()
        except Exception as exc:
            self._log_restore_exception("destination_descendant_snapshot_dirty_flush_deferred_invoke", exc)
        self._destination_descendant_snapshot_dirty_last_flush_ms = time.perf_counter() * 1000.0
        elapsed_ms = round((time.perf_counter() - t0) * 1000.0, 2)
        log_info(
            "destination_descendant_snapshot_dirty_flushed",
            flush_reason=fr,
            reason_counts=rc,
            elapsed_ms=elapsed_ms,
            affected_path_count=int(affected_n),
            descendant_apply_active=bool(self._destination_descendant_allocation_descendant_burst_active()),
            queue_size=int(len(getattr(self, "_destination_descendant_apply_queue", []) or [])),
        )
        log_info("destination_descendant_snapshot_dirty_flush_reason", flush_reason=fr)
        if fr == "max_delay_timer":
            log_info("destination_descendant_snapshot_dirty_flush_max_delay")

        dq_len = 0
        try:
            dq_len = len(getattr(self, "_destination_descendant_apply_queue", []) or [])
        except Exception:
            dq_len = 0
        log_info(
            "destination_descendant_snapshot_coalesce_summary",
            dirty_mark_calls=int(getattr(self, "_destination_descendant_snapshot_coalesce_dirty_mark_calls", 0) or 0),
            suppressed_dirty_marks=int(getattr(self, "_destination_descendant_snapshot_coalesce_suppressed_marks", 0) or 0),
            actual_flushes=int(getattr(self, "_destination_descendant_snapshot_coalesce_actual_flushes", 0) or 0),
            descendant_generation_guard_skips_seen=int(
                getattr(self, "_destination_descendant_snapshot_coalesce_guard_skip_observed", 0) or 0
            ),
            post_tick_refreshes_seen_if_available=int(
                getattr(self, "_destination_descendant_snapshot_coalesce_post_tick_refreshes", 0) or 0
            ),
            flush_reason=fr,
            queue_size=int(dq_len),
        )
        return True

    def _mark_destination_tree_snapshot_dirty_after_injection(self, *, reason: str, affected_path: str = "") -> None:
        self._destination_tree_snapshot_dirty_for_persist = True
        try:
            self._workspace_ui_snapshot_dirty_panels.add("destination")
        except Exception:
            pass
        rsn = str(reason or "")[:220]
        log_info(
            "destination_snapshot_marked_dirty_after_injection",
            reason=rsn,
        )
        burst = bool(self._destination_descendant_allocation_descendant_burst_active())
        coalesce = bool(self._destination_descendant_snapshot_coalescing_eligible(rsn) and burst)
        if coalesce:
            ap = str(affected_path or "").strip()
            if ap:
                try:
                    s = getattr(self, "_destination_descendant_snapshot_dirty_affected_paths", None)
                    if not isinstance(s, set):
                        self._destination_descendant_snapshot_dirty_affected_paths = set()
                        s = self._destination_descendant_snapshot_dirty_affected_paths
                    if len(s) < 64:
                        s.add(ap[:400])
                except Exception:
                    pass
            self._destination_descendant_snapshot_coalesce_dirty_mark_calls += 1
            if not getattr(self, "_destination_descendant_snapshot_dirty_batch_active", False):
                self._destination_descendant_snapshot_dirty_batch_active = True
                self._destination_descendant_snapshot_dirty_first_mono = time.monotonic()
                log_info(
                    "destination_descendant_snapshot_dirty_batch_started",
                    reason=str(rsn)[:220],
                    queue_size=int(len(getattr(self, "_destination_descendant_apply_queue", []) or [])),
                )
            self._destination_descendant_snapshot_dirty_pending = True
            try:
                self._destination_descendant_snapshot_dirty_reason_counts[str(rsn)] += 1
            except Exception:
                pass
            self._destination_descendant_snapshot_coalesce_suppressed_marks += 1
            self._destination_descendant_snapshot_dirty_suppressed_post_tick += 1
            n_sup = int(getattr(self, "_destination_descendant_snapshot_dirty_suppressed_post_tick", 0) or 0)
            log_info(
                "destination_descendant_snapshot_dirty_suppressed",
                suppressed_count=n_sup,
                reason_counts=dict(self._destination_descendant_snapshot_dirty_reason_counts or {}),
                reason=str(rsn)[:220],
            )
            self._destination_maybe_schedule_descendant_snapshot_max_delay_timer()
            chunk = int(self._destination_descendant_snapshot_batch_chunk_threshold())
            st_h = getattr(self, "_destination_descendant_apply_state", None)
            if isinstance(st_h, dict) and st_h.get("heavy_replay"):
                chunk = max(chunk, 160)
                log_info(
                    "destination_descendant_snapshot_coalesce_chunk_raised",
                    chunk_threshold=int(chunk),
                    reason="heavy_replay",
                )
            if n_sup >= chunk:
                self._destination_flush_descendant_snapshot_dirty_batch(
                    "chunk_threshold",
                    force=False,
                    skip_scroll_guard=False,
                )
            return
        st_x = getattr(self, "_destination_descendant_apply_state", None)
        hdq_n = 0
        try:
            hdq_n = len(getattr(self, "_destination_deferred_heavy_replay_queue", None) or ())
        except Exception:
            hdq_n = 0
        if (isinstance(st_x, dict) and st_x.get("heavy_replay")) or hdq_n > 0:
            self._destination_post_tick_snapshot_suppressed_during_heavy = int(
                getattr(self, "_destination_post_tick_snapshot_suppressed_during_heavy", 0) or 0
            ) + 1
            log_info(
                "post_tick_snapshot_refresh_suppressed_heavy_replay",
                heavy_active=bool(isinstance(st_x, dict) and st_x.get("heavy_replay")),
                deferred_heavy_queue_len=int(hdq_n),
                suppressed_total=int(
                    getattr(self, "_destination_post_tick_snapshot_suppressed_during_heavy", 0) or 0
                ),
            )
            return
        self._post_tick_snapshot_refresh_pending = True

    def _destination_maybe_flush_descendant_snapshot_batch_after_apply_job_complete(self) -> None:
        """End-of-job flush: always promote after allocation descendant replay completes."""
        if getattr(self, "_destination_descendant_snapshot_dirty_pending", False):
            ok = self._destination_flush_descendant_snapshot_dirty_batch(
                "after_descendant_apply_complete",
                force=True,
                skip_scroll_guard=True,
            )
            if ok:
                log_info("destination_descendant_snapshot_dirty_flush_after_descendant_apply_complete")
        else:
            st_y = getattr(self, "_destination_descendant_apply_state", None)
            hdq2 = 0
            try:
                hdq2 = len(getattr(self, "_destination_deferred_heavy_replay_queue", None) or ())
            except Exception:
                hdq2 = 0
            if (isinstance(st_y, dict) and st_y.get("heavy_replay")) or hdq2 > 0:
                log_info(
                    "post_tick_snapshot_refresh_suppressed_after_job_heavy_replay",
                    heavy_active=bool(isinstance(st_y, dict) and st_y.get("heavy_replay")),
                    deferred_heavy_queue_len=int(hdq2),
                )
                return
            self._post_tick_snapshot_refresh_pending = True

    def _notify_planning_mutation_destination_snapshot_dirty(
        self,
        reason: str = "",
        *,
        surface: str = "",
    ) -> None:
        """Mark destination tree snapshot dirty and schedule debounced draft save (user planning mutations).

        Covers reactive ``planned_moves`` / ``proposed_folders`` updates, persist helpers, and callers that
        mutate planning state without going through :class:`_ReactiveNotifyList` alone.
        """
        if getattr(self, "_application_shutting_down", False):
            return
        r = str(reason or "").strip() or "planning_mutation"
        surf = str(surface or "").strip()
        log_info(
            "planning_mutation_snapshot_dirty",
            reason=r[:220],
            surface=surf[:120],
        )
        self._mark_session_dirty_from_user_edit(reason=f"planning_mutation:{r[:120]}")
        self._mark_destination_tree_snapshot_dirty_after_injection(
            reason=f"planning_mutation:{r[:200]}",
        )
        self._schedule_planning_mutation_debounced_autosave(reason=r, surface=surf)

    def _schedule_planning_mutation_debounced_autosave(self, *, reason: str, surface: str = "") -> None:
        """Debounce :meth:`_save_draft_shell` so rapid planning edits coalesce; restarts timer on each call."""
        if getattr(self, "_application_shutting_down", False):
            return
        if getattr(self, "memory_manager", None) is None:
            return
        if bool(getattr(self, "_destination_save_in_progress", False)):
            log_info(
                "planning_mutation_autosave_skipped_existing_pending",
                reason=str(reason or "")[:220],
                surface=str(surface or "")[:120],
                note="draft_save_already_in_progress",
            )
            return
        delay_ms = max(400, int(os.environ.get("OZLINK_PLANNING_MUTATION_AUTOSAVE_DEBOUNCE_MS", "") or 1200) or 1200)
        tmr = getattr(self, "_planning_mutation_autosave_timer", None)
        if tmr is None:
            try:
                tmr = QTimer(self)
                tmr.setSingleShot(True)
                tmr.timeout.connect(self._on_planning_mutation_autosave_timer)
                self._planning_mutation_autosave_timer = tmr
            except Exception as exc:
                log_info(
                    "planning_mutation_autosave_timer_init_failed",
                    error=str(exc)[:240],
                    note="fallback_single_shot_partial_host",
                )
                QTimer.singleShot(
                    int(delay_ms),
                    lambda: self._safe_invoke(
                        "planning_mutation_autosave_fallback",
                        self._on_planning_mutation_autosave_timer,
                    ),
                )
                log_info(
                    "planning_mutation_autosave_scheduled",
                    delay_ms=int(delay_ms),
                    reason=str(reason or "")[:220],
                    surface=str(surface or "")[:120],
                    debounce_reset=False,
                    fallback_single_shot=True,
                )
                return
        was_active = bool(tmr.isActive()) if hasattr(tmr, "isActive") else False
        try:
            tmr.stop()
        except Exception:
            pass
        self._planning_mutation_autosave_pending_reason = str(reason or "")[:220]
        try:
            tmr.start(int(delay_ms))
        except Exception as exc:
            self._log_restore_exception("planning_mutation_autosave_scheduled", exc)
            return
        log_info(
            "planning_mutation_autosave_scheduled",
            delay_ms=int(delay_ms),
            reason=str(reason or "")[:220],
            surface=str(surface or "")[:120],
            debounce_reset=bool(was_active),
        )

    def _on_planning_mutation_autosave_timer(self) -> None:
        reason = str(getattr(self, "_planning_mutation_autosave_pending_reason", "") or "")[:220]
        self._planning_mutation_autosave_pending_reason = ""
        if getattr(self, "_application_shutting_down", False):
            return
        if getattr(self, "memory_manager", None) is None:
            return
        if bool(getattr(self, "_destination_save_in_progress", False)):
            log_info(
                "planning_mutation_autosave_skipped_existing_pending",
                reason=reason[:220],
                note="draft_save_started_before_timer_fire",
            )
            return
        if self._destination_shell_persist_heavy_deferred():
            dcnt = int(getattr(self, "_session_user_edited_unsaved_count", 0) or 0)
            log_info("recovery_journal_flush_scheduled", dirty_count=dcnt, reason=reason[:120])
            n = 0
            try:
                n = int(self._flush_recovery_journal_lightweight() or 0)
            except Exception as exc:
                self._log_restore_exception("planning_mutation_recovery_journal", exc)
            log_info(
                "planning_mutation_autosave_complete",
                success=True,
                reason=reason[:220] + ":recovery_journal",
                destination_snapshot_dirty=bool(getattr(self, "_destination_tree_snapshot_dirty_for_persist", False)),
            )
            return
        ok = False
        try:
            ok = bool(self._save_draft_shell(force=True, include_workspace_ui=False))
        except Exception as exc:
            self._log_restore_exception("planning_mutation_autosave", exc)
        log_info(
            "planning_mutation_autosave_complete",
            success=bool(ok),
            reason=reason[:220],
            destination_snapshot_dirty=bool(getattr(self, "_destination_tree_snapshot_dirty_for_persist", False)),
        )

    def _schedule_startup_replay_settle_autosave(
        self,
        *,
        suppress_startup_replay: bool,
        n_min_total: int,
        n_persisted: int,
        min_rep: dict[str, Any] | None,
        settle_reason: str,
    ) -> None:
        """Queue a one-shot delayed draft save so replay-expanded destination rows reach DestinationTreeSnapshot.

        Startup-only: does not alter global autosave timers. Skips when replay was suppressed with no work,
        when nothing changed, when a delayed save is already pending, or when no memory manager exists.
        """
        if getattr(self, "_application_shutting_down", False):
            log_info(
                "startup_replay_autosave_skipped",
                reason="application_shutting_down",
                suppress_startup_replay=bool(suppress_startup_replay),
                minimal_overlay_rows=int(n_min_total),
                persisted_overlay_rows=int(n_persisted),
                minimal_replay_rounds=int((min_rep or {}).get("rounds", 0) or 0),
                destination_snapshot_dirty=bool(getattr(self, "_destination_tree_snapshot_dirty_for_persist", False)),
            )
            return
        if suppress_startup_replay:
            log_info(
                "startup_replay_autosave_skipped",
                reason="startup_replay_suppressed",
                suppress_startup_replay=True,
                minimal_overlay_rows=0,
                persisted_overlay_rows=0,
                minimal_replay_rounds=0,
                destination_snapshot_dirty=bool(getattr(self, "_destination_tree_snapshot_dirty_for_persist", False)),
            )
            return
        rounds = int((min_rep or {}).get("rounds", 0) or 0)
        replay_work = int(n_min_total) + int(n_persisted) > 0 or rounds > 0
        if not replay_work:
            log_info(
                "startup_replay_autosave_skipped",
                reason="no_replay_work_to_persist",
                suppress_startup_replay=False,
                minimal_overlay_rows=int(n_min_total),
                persisted_overlay_rows=int(n_persisted),
                minimal_replay_rounds=int(rounds),
                destination_snapshot_dirty=bool(getattr(self, "_destination_tree_snapshot_dirty_for_persist", False)),
            )
            return
        if getattr(self, "memory_manager", None) is None:
            log_info(
                "startup_replay_autosave_skipped",
                reason="no_memory_manager",
                suppress_startup_replay=False,
                minimal_overlay_rows=int(n_min_total),
                persisted_overlay_rows=int(n_persisted),
                minimal_replay_rounds=int(rounds),
                destination_snapshot_dirty=bool(getattr(self, "_destination_tree_snapshot_dirty_for_persist", False)),
            )
            return
        if getattr(self, "_startup_replay_settle_autosave_timer_pending", False):
            log_info(
                "startup_replay_autosave_skipped",
                reason="startup_replay_autosave_already_pending",
                suppress_startup_replay=False,
                minimal_overlay_rows=int(n_min_total),
                persisted_overlay_rows=int(n_persisted),
                minimal_replay_rounds=int(rounds),
                destination_snapshot_dirty=bool(getattr(self, "_destination_tree_snapshot_dirty_for_persist", False)),
            )
            return
        delay_ms = 1600
        self._startup_replay_settle_autosave_timer_pending = True
        log_info(
            "startup_replay_autosave_scheduled",
            delay_ms=int(delay_ms),
            settle_reason=str(settle_reason or "")[:200],
            minimal_overlay_rows=int(n_min_total),
            persisted_overlay_rows=int(n_persisted),
            minimal_replay_rounds=int(rounds),
            destination_snapshot_dirty=bool(getattr(self, "_destination_tree_snapshot_dirty_for_persist", False)),
        )

        def _run() -> None:
            self._safe_invoke(
                "startup_replay_settle_autosave",
                lambda: self._run_startup_replay_settle_autosave(
                    settle_reason=str(settle_reason or "")[:200],
                    minimal_overlay_rows=int(n_min_total),
                    persisted_overlay_rows=int(n_persisted),
                    minimal_replay_rounds=int(rounds),
                ),
            )

        QTimer.singleShot(int(delay_ms), _run)

    def _run_startup_replay_settle_autosave(
        self,
        *,
        settle_reason: str,
        minimal_overlay_rows: int,
        persisted_overlay_rows: int,
        minimal_replay_rounds: int,
    ) -> None:
        self._startup_replay_settle_autosave_timer_pending = False
        if getattr(self, "_application_shutting_down", False):
            log_info(
                "startup_replay_autosave_skipped",
                reason="application_shutting_down_at_fire",
                settle_reason=str(settle_reason or "")[:200],
                minimal_overlay_rows=int(minimal_overlay_rows),
                persisted_overlay_rows=int(persisted_overlay_rows),
                minimal_replay_rounds=int(minimal_replay_rounds),
                destination_snapshot_dirty=bool(getattr(self, "_destination_tree_snapshot_dirty_for_persist", False)),
            )
            return
        log_info(
            "startup_replay_autosave_begin",
            settle_reason=str(settle_reason or "")[:200],
            minimal_overlay_rows=int(minimal_overlay_rows),
            persisted_overlay_rows=int(persisted_overlay_rows),
            minimal_replay_rounds=int(minimal_replay_rounds),
            destination_snapshot_dirty=bool(getattr(self, "_destination_tree_snapshot_dirty_for_persist", False)),
        )
        ok = False
        try:
            ok = bool(self._save_draft_shell(force=True, include_workspace_ui=False))
        except Exception as exc:
            self._log_restore_exception("startup_replay_settle_autosave", exc)
        log_info(
            "startup_replay_autosave_complete",
            success=bool(ok),
            settle_reason=str(settle_reason or "")[:200],
            minimal_overlay_rows=int(minimal_overlay_rows),
            persisted_overlay_rows=int(persisted_overlay_rows),
            minimal_replay_rounds=int(minimal_replay_rounds),
            destination_snapshot_dirty=bool(getattr(self, "_destination_tree_snapshot_dirty_for_persist", False)),
        )

    def _destination_startup_snapshot_root_context(self) -> DestinationStartupSnapshotRootContext:
        """Identity context for validating persisted destination snapshot roots at workspace restore."""

        mode = self._planning_browse_mode("destination")
        dest = self._intended_destination_drive_id_for_snapshot_validation()
        src = str(self._current_selected_source_drive_id() or "").strip()
        if not src:
            src = str((getattr(self, "pending_root_drive_ids", {}) or {}).get("source") or "").strip()
        gnames = getattr(self, "_destination_graph_shallow_destination_root_names_cf", None)
        gfrozen = gnames if isinstance(gnames, frozenset) else (frozenset(gnames) if isinstance(gnames, (set, list, tuple)) and gnames else None)
        strict_row = str(mode or "").strip().lower() == "sharepoint"
        return DestinationStartupSnapshotRootContext(
            browse_mode=str(mode or "")[:40],
            destination_drive_id=dest,
            source_drive_id=src,
            graph_shallow_root_names_cf=gfrozen,
            strict_missing_row_drive=strict_row,
        )

    def _apply_destination_tree_snapshot_identity_fields(self, state: SessionState, destination_library, destination_site) -> None:
        """Persist snapshot-level destination library identity alongside DestinationTreeSnapshot."""
        did = str(destination_library.get("id", "") or "").strip() if isinstance(destination_library, dict) else ""
        state.DestinationTreeSnapshotIdentityDriveId = did
        state.DestinationTreeSnapshotIdentityLibraryId = did
        state.DestinationTreeSnapshotIdentityLibraryName = (
            str(destination_library.get("name", "") or "").strip() if isinstance(destination_library, dict) else ""
        )
        site_id = ""
        if isinstance(destination_site, dict):
            site_id = str(destination_site.get("id", "") or "").strip()
        state.DestinationTreeSnapshotIdentitySiteId = site_id
        state.DestinationTreeSnapshotIdentityInferredFromLegacy = False
        if did or state.DestinationTreeSnapshotIdentityLibraryName:
            log_info(
                "destination_snapshot_identity_persisted",
                source="session_state",
                drive_id_suffix=did[-16:] if len(did) > 16 else did,
                library_id_suffix=did[-16:] if len(did) > 16 else did,
                library_name_excerpt=str(state.DestinationTreeSnapshotIdentityLibraryName or "")[:120],
                site_id_suffix=site_id[-16:] if len(site_id) > 16 else site_id,
            )

    def _destination_legacy_snapshot_library_candidates(self) -> list[DestinationLibraryCandidate]:
        """Destination document libraries in the current site selector (for legacy snapshot inference only)."""
        out: list[DestinationLibraryCandidate] = []
        if not getattr(self, "planning_inputs", None):
            return out
        lib_sel = self.planning_inputs.get("Destination Library")
        site_sel = self.planning_inputs.get("Destination Site")
        site = site_sel.currentData() if site_sel is not None else None
        site_id = ""
        if isinstance(site, dict):
            site_id = str(site.get("id") or "").strip()
        gnames = getattr(self, "_destination_graph_shallow_destination_root_names_cf", None)
        gfrozen: frozenset[str] | None
        if isinstance(gnames, frozenset):
            gfrozen = gnames
        elif isinstance(gnames, (set, list, tuple)) and gnames:
            gfrozen = frozenset(str(x).casefold() for x in gnames)
        else:
            gfrozen = None
        active = str(self._current_selected_destination_drive_id() or "").strip()
        if lib_sel is None:
            return out
        for i in range(lib_sel.count()):
            data = lib_sel.itemData(i)
            if not isinstance(data, dict):
                continue
            did = str(data.get("id") or "").strip()
            if not did:
                continue
            roots = gfrozen if active and did.casefold() == active.casefold() else None
            out.append(
                DestinationLibraryCandidate(
                    drive_id=did,
                    library_id=did,
                    display_name=str(data.get("name") or "").strip(),
                    site_id=site_id,
                    graph_shallow_root_names_cf=roots,
                )
            )
        return out

    def _apply_destination_snapshot_legacy_identity_stamp(self, meta: dict | None) -> None:
        """After startup snapshot selection, persist inferred legacy identity onto SessionState for next save."""
        if not isinstance(meta, dict):
            return
        label = str(meta.get("chosen_label") or "")
        stamp = None
        if "WorkspaceSnapshot.destination_tree_snapshot" in label and "fallback" not in label:
            stamp = meta.get("sidecar_legacy_identity_stamp")
        elif "SessionState.DestinationTreeSnapshot" in label:
            stamp = meta.get("session_legacy_identity_stamp")
        else:
            stamp = meta.get("session_legacy_identity_stamp") or meta.get("sidecar_legacy_identity_stamp")
        if not isinstance(stamp, dict) or not stamp.get("destination_snapshot_identity_inferred_from_legacy"):
            return
        state = self._draft_shell_state if isinstance(self._draft_shell_state, SessionState) else None
        if state is None:
            return
        state.DestinationTreeSnapshotIdentityDriveId = str(stamp.get("matched_drive_id") or "").strip()
        state.DestinationTreeSnapshotIdentityLibraryId = str(stamp.get("matched_library_id") or "").strip()
        state.DestinationTreeSnapshotIdentityLibraryName = str(stamp.get("matched_library_name") or "").strip()
        state.DestinationTreeSnapshotIdentitySiteId = str(stamp.get("matched_site_id") or "").strip()
        state.DestinationTreeSnapshotIdentityInferredFromLegacy = True
        self._destination_tree_snapshot_dirty_for_persist = True
        try:
            self._workspace_ui_snapshot_dirty_panels.add("destination")
        except Exception:
            pass
        log_info(
            "destination_snapshot_identity_inferred_from_legacy_applied",
            drive_id_suffix=str(state.DestinationTreeSnapshotIdentityDriveId)[-16:]
            if len(str(state.DestinationTreeSnapshotIdentityDriveId)) > 16
            else str(state.DestinationTreeSnapshotIdentityDriveId),
            library_name_excerpt=str(state.DestinationTreeSnapshotIdentityLibraryName or "")[:120],
        )

    def _destination_retry_site_identity_key(self) -> str:
        if not getattr(self, "planning_inputs", None):
            return ""
        site_sel = self.planning_inputs.get("Destination Site")
        site = site_sel.currentData() if site_sel is not None else None
        if isinstance(site, dict):
            return str(site.get("id") or "").strip()
        return ""

    def _legacy_snapshot_identity_inference_meta_should_retry(self, meta: dict | None) -> bool:
        if not isinstance(meta, dict):
            return False
        if not meta.get("legacy_inference_retry_recommended"):
            return False
        r = meta.get("reason")
        return r in ("blocked_legacy_no_candidates", "low_confidence", "insufficient_signal")

    def _meta_legacy_inference_resolved_with_stamp(self, meta: dict | None) -> bool:
        if not isinstance(meta, dict):
            return False
        label = str(meta.get("chosen_label") or "")
        stamp = None
        if "WorkspaceSnapshot.destination_tree_snapshot" in label and "fallback" not in label:
            stamp = meta.get("sidecar_legacy_identity_stamp")
        elif "SessionState.DestinationTreeSnapshot" in label:
            stamp = meta.get("session_legacy_identity_stamp")
        else:
            stamp = meta.get("session_legacy_identity_stamp") or meta.get("sidecar_legacy_identity_stamp")
        return isinstance(stamp, dict) and bool(stamp.get("destination_snapshot_identity_inferred_from_legacy"))

    def _maybe_schedule_legacy_snapshot_identity_inference_retry(self, trigger: str) -> None:
        if not getattr(self, "_main_window_qobject_ready", False):
            return
        key = self._destination_retry_site_identity_key()
        prev = getattr(self, "_legacy_identity_inference_retry_site_key", None)
        if prev != key:
            self._legacy_identity_inference_retry_attempt_count = 0
            self._legacy_identity_inference_authoritative_rebind_done = False
            self._legacy_identity_inference_retry_site_key = key
        if self._legacy_identity_inference_retry_attempt_count >= 2:
            return
        if self._legacy_identity_inference_retry_timer_pending:
            return
        meta = getattr(self, "_last_destination_snapshot_selection_meta", None)
        if not self._legacy_snapshot_identity_inference_meta_should_retry(meta):
            return
        self._legacy_identity_inference_retry_timer_pending = True
        self._legacy_identity_inference_retry_trigger = str(trigger or "")[:120]

        def _run():
            self._legacy_identity_inference_retry_timer_pending = False
            self._safe_invoke(
                "legacy_snapshot_identity_inference_retry",
                lambda: self._retry_legacy_snapshot_identity_inference(self),
            )

        QTimer.singleShot(0, _run)

    def _legacy_identity_inference_authoritative_rebind_after_retry(
        self,
        *,
        dest_snaps: list,
        trigger: str,
        sel_src: str,
    ) -> None:
        """After legacy identity inference succeeds, mirror startup: stamp, provisional snapshot paint, overlay materialize."""
        if getattr(self, "_legacy_identity_inference_authoritative_rebind_done", False):
            return
        t = str(trigger or "")[:120]
        dm = getattr(self, "destination_planning_model", None)
        nodes_before = -1
        if dm is not None and hasattr(dm, "iter_depth_first"):
            try:
                nodes_before = sum(1 for _ in dm.iter_depth_first())
            except Exception:
                nodes_before = -1
        _fld = getattr(self, "folder_load_workers", None) or {}
        _dest_gw = sum(1 for k in _fld if str(k).startswith("destination:"))
        log_info(
            "destination_legacy_inference_authoritative_rebind_started",
            trigger=t,
            sel_src=str(sel_src or "")[:220],
            top_level_roots=len(dest_snaps) if isinstance(dest_snaps, list) else -1,
            model_nodes_iter_depth_first_before=int(nodes_before),
            destination_root_worker_running=bool(MainWindow._root_load_worker_running(self, "destination")),
            active_destination_graph_folder_workers=int(_dest_gw),
            pending_destination_folder_loads=len(
                (getattr(self, "pending_folder_loads", None) or {}).get("destination", set()) or set()
            ),
        )
        prov = False
        overlay_ret = 0
        try:
            destination_stamp_snapshot_tree_workspace_state(dest_snaps)
            if self._planning_browse_mode("destination") != "local":
                prov = bool(
                    self._destination_apply_provisional_session_snapshot_if_eligible(
                        phase="legacy_identity_inference_retry"
                    )
                )
            overlay_ret = int(
                self._apply_destination_planning_overlays(
                    "legacy_identity_inference_retry",
                    allow_defer=False,
                    prefer_chunked_projection=False,
                    narrow_restore_real_snapshot=False,
                    force_authoritative_bind=True,
                )
                or 0
            )
            self._legacy_identity_inference_authoritative_rebind_done = True
            nodes_after = -1
            if dm is not None and hasattr(dm, "iter_depth_first"):
                try:
                    nodes_after = sum(1 for _ in dm.iter_depth_first())
                except Exception:
                    nodes_after = -1
            _fld2 = getattr(self, "folder_load_workers", None) or {}
            _dest_gw2 = sum(1 for k in _fld2 if str(k).startswith("destination:"))
            log_info(
                "destination_legacy_inference_authoritative_rebind_completed",
                trigger=t,
                ok=True,
                provisional_applied=bool(prov),
                overlay_applied_count=int(overlay_ret),
                sel_src=str(sel_src or "")[:220],
                model_nodes_iter_depth_first_before=int(nodes_before),
                model_nodes_iter_depth_first_after=int(nodes_after),
                destination_root_worker_running=bool(MainWindow._root_load_worker_running(self, "destination")),
                active_destination_graph_folder_workers=int(_dest_gw2),
                pending_destination_folder_loads=len(
                    (getattr(self, "pending_folder_loads", None) or {}).get("destination", set()) or set()
                ),
            )
        except Exception as exc:
            self._log_restore_exception("legacy_identity_inference_authoritative_rebind", exc)
            log_info(
                "destination_legacy_inference_authoritative_rebind_completed",
                trigger=t,
                ok=False,
                error=str(exc)[:500],
            )

    def _retry_legacy_snapshot_identity_inference(self, win=None) -> None:
        if self._legacy_identity_inference_retry_attempt_count >= 2:
            return
        self._legacy_identity_inference_retry_attempt_count += 1
        trigger = str(getattr(self, "_legacy_identity_inference_retry_trigger", "") or "")[:120]
        state = self._draft_shell_state if isinstance(self._draft_shell_state, SessionState) else None
        before_inferred = bool(state and getattr(state, "DestinationTreeSnapshotIdentityInferredFromLegacy", False))
        try:
            log_info(
                "destination_legacy_inference_retry_started",
                trigger=trigger,
                site_key_excerpt=self._destination_retry_site_identity_key()[:48],
            )
            tree_snapshots = self._session_workspace_tree_snapshots()
            dest_snaps_session = list(tree_snapshots.get("destination", []) or [])
            mm = getattr(self, "memory_manager", None)
            sidecar = mm.read_workspace_snapshot_optional() if mm is not None else None
            dest_snaps, sel_src, _n_sess, _n_side, meta = self._select_destination_tree_snapshot_for_startup(
                dest_snaps_session,
                workspace_sidecar=sidecar,
            )
            pending = dict(self._pending_session_tree_snapshots or {})
            pending["destination"] = list(dest_snaps)
            self._pending_session_tree_snapshots = pending
            rs = getattr(self, "_runtime_session_tree_snapshots", None)
            if isinstance(rs, dict):
                rs["destination"] = list(dest_snaps)
            if isinstance(sel_src, str) and sel_src.startswith("Workspace") and isinstance(self._draft_shell_state, SessionState):
                self._draft_shell_state.DestinationTreeSnapshot = list(dest_snaps)
            try:
                self._destination_startup_allowed_semantic_root_segments_cf = allowed_semantic_root_segments_cf_from_snapshot(
                    dest_snaps
                )
            except Exception:
                self._destination_startup_allowed_semantic_root_segments_cf = set()
            after_inferred = bool(state and getattr(state, "DestinationTreeSnapshotIdentityInferredFromLegacy", False))
            stamp_ok = self._meta_legacy_inference_resolved_with_stamp(meta)
            still_blocked = bool(meta.get("legacy_inference_retry_recommended"))
            tree_materialized = bool(
                getattr(self, "_destination_provisional_startup_applied", False)
                or getattr(self, "_destination_startup_snapshot_mount_seen", False)
            )
            if still_blocked:
                log_info(
                    "destination_legacy_inference_retry_failed",
                    trigger=trigger,
                    reason=str(meta.get("reason") or "")[:80],
                    session_gate=str(meta.get("session_identity_gate") or "")[:80],
                    sidecar_gate=str(meta.get("sidecar_identity_gate") or "")[:80],
                )
            else:
                log_info(
                    "destination_legacy_inference_retry_success",
                    trigger=trigger,
                    stamp_applied=bool(stamp_ok),
                    identity_inferred_from_legacy=after_inferred,
                )
            identity_ok = bool(stamp_ok or after_inferred or before_inferred)
            needs_authoritative_rebind = (
                not still_blocked
                and identity_ok
                and not getattr(self, "_legacy_identity_inference_authoritative_rebind_done", False)
                and (
                    not before_inferred
                    or not tree_materialized
                    or bool(dest_snaps)
                    or not dest_snaps
                )
            )
            if needs_authoritative_rebind:
                self._legacy_identity_inference_authoritative_rebind_after_retry(
                    dest_snaps=list(dest_snaps),
                    trigger=trigger,
                    sel_src=str(sel_src or ""),
                )
        except Exception as exc:
            log_info(
                "destination_legacy_inference_retry_failed",
                trigger=trigger,
                reason="exception",
                error=str(exc)[:500],
            )
            self._log_restore_exception("legacy_snapshot_identity_inference_retry", exc)

    def _intended_destination_drive_id_for_snapshot_validation(self) -> str:
        """Prefer persisted session/snapshot envelope over combo (combo may be wrong before selector restore)."""
        shell = getattr(self, "_draft_shell_state", None)
        state = shell if isinstance(shell, SessionState) else SessionState()
        for key in (
            "DestinationTreeSnapshotIdentityDriveId",
            "SelectedDestinationLibraryId",
        ):
            v = str(getattr(state, key, "") or "").strip()
            if v:
                return v
        dest = str(self._current_selected_destination_drive_id() or "").strip()
        if dest:
            return dest
        return str((getattr(self, "pending_root_drive_ids", {}) or {}).get("destination") or "").strip()

    def _persisted_destination_library_drive_id_from_session(self) -> str:
        """Persisted session destination library Graph drive id only (no combo / pending fallbacks).

        Used to avoid binding a stale combo index (e.g. first library in a partial site list) while the
        saved library row is not present yet.
        """
        shell = getattr(self, "_draft_shell_state", None)
        state = shell if isinstance(shell, SessionState) else SessionState()
        return str(getattr(state, "SelectedDestinationLibraryId", "") or "").strip()

    def _persisted_source_library_drive_id_from_session(self) -> str:
        """Persisted session source library Graph drive id only (no combo / pending fallbacks)."""
        shell = getattr(self, "_draft_shell_state", None)
        state = shell if isinstance(shell, SessionState) else SessionState()
        return str(getattr(state, "SelectedSourceLibraryId", "") or "").strip()

    def _planning_library_selector_has_drive_id(self, library_selector, drive_id: str) -> bool:
        if library_selector is None:
            return False
        did = str(drive_id or "").strip()
        if not did:
            return False
        dcf = did.casefold()
        try:
            for i in range(int(library_selector.count() or 0)):
                data = library_selector.itemData(i)
                if isinstance(data, dict):
                    pid = str(data.get("id") or data.get("drive_id") or "").strip()
                    if pid and pid.casefold() == dcf:
                        return True
        except Exception:
            return False
        return False

    def _destination_library_selector_has_drive_id(self, library_selector, drive_id: str) -> bool:
        return self._planning_library_selector_has_drive_id(library_selector, drive_id)

    def _planning_should_defer_or_block_wrong_library_bind(
        self,
        selector_group: str,
        *,
        selected_library: dict,
        library_selector,
    ) -> str:
        """Return '' to proceed, 'deferred' to skip load until selector is ready, 'blocked' if wrong id known."""
        intended = (
            self._persisted_source_library_drive_id_from_session()
            if selector_group == "source"
            else self._persisted_destination_library_drive_id_from_session()
        )
        if not intended:
            return ""
        sel_id = str(selected_library.get("id") or selected_library.get("drive_id") or "").strip()
        if not sel_id:
            return ""
        if sel_id.casefold() == intended.casefold():
            return ""
        in_combo = self._planning_library_selector_has_drive_id(library_selector, intended)
        _tag = f"{selector_group}_wrong_library_bind_blocked"
        _tag_defer = f"{selector_group}_library_bind_deferred_selector_not_ready"
        if in_combo:
            log_info(
                _tag,
                selected_drive_suffix=sel_id[-16:] if len(sel_id) > 16 else sel_id,
                intended_drive_suffix=intended[-16:] if len(intended) > 16 else intended,
                selector_item_count=int(library_selector.count() if library_selector is not None else 0),
            )
            return "blocked"
        log_info(
            _tag_defer,
            selected_drive_suffix=sel_id[-16:] if len(sel_id) > 16 else sel_id,
            intended_drive_suffix=intended[-16:] if len(intended) > 16 else intended,
            selector_item_count=int(library_selector.count() if library_selector is not None else 0),
        )
        return "deferred"

    def _destination_should_defer_or_block_wrong_library_bind(
        self,
        *,
        selected_library: dict,
        library_selector,
    ) -> str:
        return self._planning_should_defer_or_block_wrong_library_bind(
            "destination", selected_library=selected_library, library_selector=library_selector
        )

    def _sync_library_selector_to_persisted_session_drive(self, selector_group: str, library_selector) -> None:
        """After site library list (re)built, select saved drive id from draft shell or no selection."""
        if library_selector is None:
            return
        intended = (
            self._persisted_source_library_drive_id_from_session()
            if selector_group == "source"
            else self._persisted_destination_library_drive_id_from_session()
        )
        library_selector.blockSignals(True)
        try:
            if not intended:
                return
            for i in range(int(library_selector.count() or 0)):
                data = library_selector.itemData(i)
                if not isinstance(data, dict):
                    continue
                pid = str(data.get("id") or data.get("drive_id") or "").strip()
                if pid and pid.casefold() == intended.casefold():
                    library_selector.setCurrentIndex(i)
                    log_info(
                        "library_selector_restore_selected_saved_drive",
                        selector_group=selector_group,
                        saved_drive_suffix=intended[-16:] if len(intended) > 16 else intended,
                        index=int(i),
                    )
                    return
            try:
                library_selector.setCurrentIndex(-1)
            except Exception:
                pass
        finally:
            library_selector.blockSignals(False)

    def _destination_sync_library_selector_to_persisted_intent(self, library_selector) -> None:
        self._sync_library_selector_to_persisted_session_drive("destination", library_selector)

    def _schedule_saved_library_selector_hydration_retry(self, selector_group: str) -> None:
        """Re-fetch list_site_drives and retry bind when saved drive was missing from a partial library list."""
        attempt = int(self._saved_library_selector_hydration_attempt.get(selector_group, 0) or 0)
        if attempt >= 6:
            log_info(
                "destination_saved_library_wait_retry_failed"
                if selector_group == "destination"
                else "source_saved_library_wait_retry_failed",
                selector_group=selector_group,
                attempts=int(attempt),
            )
            return
        delay_ms = min(2800, max(120, 180 * (2**attempt)))
        self._saved_library_selector_hydration_attempt[selector_group] = attempt + 1
        log_info(
            "destination_saved_library_wait_retry_scheduled"
            if selector_group == "destination"
            else "source_saved_library_wait_retry_scheduled",
            selector_group=selector_group,
            attempt=int(attempt + 1),
            delay_ms=int(delay_ms),
        )

        def _run():
            try:
                self._populate_library_selector_for_group(selector_group)
                lib_sel = (
                    self.planning_inputs.get("Source Library")
                    if selector_group == "source"
                    else self.planning_inputs.get("Destination Library")
                )
                intended = (
                    self._persisted_source_library_drive_id_from_session()
                    if selector_group == "source"
                    else self._persisted_destination_library_drive_id_from_session()
                )
                if intended and self._planning_library_selector_has_drive_id(lib_sel, intended):
                    log_info(
                        "destination_saved_library_wait_retry_success"
                        if selector_group == "destination"
                        else "source_saved_library_wait_retry_success",
                        selector_group=selector_group,
                        intended_drive_suffix=intended[-16:] if len(intended) > 16 else intended,
                    )
                    self._saved_library_selector_hydration_attempt[selector_group] = 0
                    self.on_library_selector_changed(selector_group, force=True)
                    return
                self._schedule_saved_library_selector_hydration_retry(selector_group)
            except Exception as exc:
                log_warn(
                    "saved_library_hydration_retry_run_failed",
                    selector_group=selector_group,
                    error=str(exc)[:400],
                )
                self._schedule_saved_library_selector_hydration_retry(selector_group)

        QTimer.singleShot(delay_ms, lambda: self._safe_invoke(f"saved_library_hydration_retry.{selector_group}", _run))

    def _planning_sharepoint_site_selector_resolved_for_libraries(self, site_selector) -> bool:
        """Site combo must expose a dict with a Graph site id before list_site_drives / library restore."""
        if site_selector is None:
            return False
        try:
            raw = site_selector.currentData()
        except Exception:
            raw = None
        if not isinstance(raw, dict):
            return False
        sid = str(raw.get("id") or raw.get("site_id") or "").strip()
        return bool(sid)

    def _schedule_selector_restore_library_retry_after_site_resolved(self, selector_group: str) -> None:
        """Retry library hydrate/load after site context becomes resolvable (async site lists, lazy dict)."""
        att = getattr(self, "_selector_restore_site_retry_attempt", None)
        if not isinstance(att, dict):
            att = {}
            self._selector_restore_site_retry_attempt = att
        n = int(att.get(selector_group, 0) or 0)
        if n >= 10:
            log_warn(
                "selector_restore_library_retry_after_site_exhausted",
                selector_group=selector_group,
                attempts=int(n),
            )
            return
        att[selector_group] = n + 1
        delay_ms = min(3200, 150 + 220 * n)

        def _run() -> None:
            self._run_selector_restore_library_retry_after_site_resolved(selector_group)

        QTimer.singleShot(
            delay_ms,
            lambda g=selector_group: self._safe_invoke(f"selector_restore_library_retry_after_site.{g}", _run),
        )

    def _run_selector_restore_library_retry_after_site_resolved(self, selector_group: str) -> None:
        if self._planning_browse_mode(selector_group) != "sharepoint":
            return
        site_sel = (
            self.planning_inputs.get("Source Site")
            if selector_group == "source"
            else self.planning_inputs.get("Destination Site")
        )
        lib_sel = (
            self.planning_inputs.get("Source Library")
            if selector_group == "source"
            else self.planning_inputs.get("Destination Library")
        )
        if not self._planning_sharepoint_site_selector_resolved_for_libraries(site_sel):
            self._schedule_selector_restore_library_retry_after_site_resolved(selector_group)
            return
        log_info("selector_restore_library_retry_after_site_resolved", selector_group=selector_group)
        try:
            self._populate_library_selector_for_group(selector_group)
        except Exception as exc:
            log_warn(
                "selector_restore_library_retry_populate_failed",
                selector_group=selector_group,
                error=str(exc)[:400],
            )
            self._schedule_selector_restore_library_retry_after_site_resolved(selector_group)
            return
        intended = (
            self._persisted_source_library_drive_id_from_session()
            if selector_group == "source"
            else self._persisted_destination_library_drive_id_from_session()
        )
        if intended and self._planning_library_selector_has_drive_id(lib_sel, intended):
            self.on_library_selector_changed(selector_group, force=True)
            return
        if str(intended or "").strip():
            self._schedule_saved_library_selector_hydration_retry(selector_group)

    def _destination_library_context_unresolved_for_graph_display(self) -> bool:
        """True when we must not treat the destination explorer model as authoritative Graph structure."""
        if self._planning_browse_mode("destination") == "local":
            return False
        sel = self.planning_inputs.get("Destination Library") if hasattr(self, "planning_inputs") else None
        if sel is None:
            return True
        try:
            ix = int(sel.currentIndex())
        except Exception:
            ix = -1
        try:
            data = sel.currentData()
        except Exception:
            data = None
        if ix < 0 or not isinstance(data, dict):
            return True
        lid = str(data.get("id") or data.get("drive_id") or "").strip()
        if not lid:
            return True
        persisted = self._persisted_destination_library_drive_id_from_session()
        if persisted and str(lid).strip().casefold() != persisted.casefold():
            return True
        return False

    def _destination_suppress_stale_visible_tree_if_needed(self) -> None:
        """Clear destination model rows when library selector is not bound to the saved/resolved drive."""
        if self._planning_browse_mode("destination") == "local":
            return
        if not self._destination_library_context_unresolved_for_graph_display():
            return
        dm = getattr(self, "destination_planning_model", None)
        rows = 0
        try:
            rows = int(dm.rowCount(QModelIndex())) if dm is not None else 0
        except Exception:
            rows = -1
        log_info(
            "destination_snapshot_display_blocked_library_unresolved",
            model_top_level_rows=int(rows),
        )
        if rows <= 0:
            self.set_tree_placeholder("destination", "Select a destination library to load root content.")
            log_info(
                "destination_stale_visible_tree_hidden_until_library_resolved",
                cleared_model=False,
                reason="already_empty",
            )
            return
        log_info(
            "destination_stale_visible_tree_hidden_until_library_resolved",
            cleared_model=True,
            model_top_level_rows=int(rows),
        )
        try:
            if dm is not None:
                dm.clear()
        except Exception:
            pass
        try:
            self.pending_root_drive_ids["destination"] = ""
            self._destination_sharepoint_root_graph_bound_drive_id = ""
            self.active_root_request_signatures["destination"] = None
            self.loaded_root_request_signatures["destination"] = None
        except Exception:
            pass
        self.set_tree_placeholder("destination", "Select a destination library to load root content.")

    def _destination_skeleton_pending_top_level_for_watchdog(self, did: str) -> bool:
        if self._destination_library_context_unresolved_for_graph_display():
            return False
        dcf = str(did or "").strip().casefold()
        if not dcf:
            return False
        pend = str((self.pending_root_drive_ids or {}).get("destination") or "").strip()
        if pend and pend.casefold() != dcf:
            return False
        dm = getattr(self, "destination_planning_model", None)
        if dm is None:
            return False
        inv = QModelIndex()
        try:
            rc = int(dm.rowCount(inv))
        except Exception:
            return False
        for r in range(min(rc, 48)):
            try:
                ix = dm.index(r, 0, inv)
            except Exception:
                continue
            if not ix.isValid():
                continue
            pl = self._destination_model_index_user_role_dict(ix)
            if not isinstance(pl, dict):
                continue
            if not self._destination_row_is_live_graph_structure(pl) or not pl.get("is_folder", True):
                continue
            if pl.get("children_loaded") or pl.get("load_failed"):
                continue
            return True
        return False

    def _destination_try_watchdog_skeleton_child_retry_instead_of_full_tree(self, did: str) -> bool:
        if self._destination_library_context_unresolved_for_graph_display():
            return False
        if not self._destination_skeleton_pending_top_level_for_watchdog(did):
            return False
        if not destination_graph_delta_cursor_present(getattr(self, "graph", None), did):
            return False
        root_w = (self.root_load_workers or {}).get("destination")
        if not isinstance(root_w, dict):
            return False
        wid = root_w.get("id")
        if wid is None:
            return False
        try:
            self._destination_schedule_skeleton_first_level_graph_child_loads(
                str(did), wid, worker_tag="watchdog_stall_recovery"
            )
        except Exception:
            return False
        log_info(
            "destination_authority_stall_recovered_by_skeleton_child_retry",
            drive_id_suffix=str(did)[-16:] if len(str(did)) > 16 else str(did),
        )
        log_info(
            "destination_full_tree_recovery_suppressed_skeleton_child_pending",
            drive_id_suffix=str(did)[-16:] if len(str(did)) > 16 else str(did),
        )
        return True

    def _destination_graph_skeleton_schedule_after_live_root_bind(
        self,
        drive_id: str,
        worker_id: Any,
        *,
        worker_tag: str,
        schedule_phase: str,
    ) -> None:
        """Wrap skeleton scheduling with entry/exit logs; call while root worker is still registered (sync path)."""
        log_info(
            "destination_graph_skeleton_schedule_entry",
            phase=str(schedule_phase)[:160],
            worker_tag=str(worker_tag)[:80],
            drive_id_suffix=str(drive_id)[-16:] if len(str(drive_id)) > 16 else str(drive_id),
        )
        try:
            self._destination_schedule_skeleton_first_level_graph_child_loads(
                str(drive_id or ""), worker_id, worker_tag=worker_tag
            )
        finally:
            log_info(
                "destination_graph_skeleton_schedule_exit",
                phase=str(schedule_phase)[:160],
                worker_tag=str(worker_tag)[:80],
                drive_id_suffix=str(drive_id)[-16:] if len(str(drive_id)) > 16 else str(drive_id),
            )

    def _destination_schedule_skeleton_first_level_graph_child_loads(
        self, drive_id: str, worker_id: Any, *, worker_tag: str = "post_root"
    ) -> None:
        """Load first-level Graph children for a single top-level folder (e.g. library root) without full-tree."""
        if self._destination_library_context_unresolved_for_graph_display():
            log_info(
                "destination_skeleton_child_load_blocked_library_unresolved",
                worker_tag=str(worker_tag)[:80],
                drive_id_suffix=str(drive_id)[-16:] if len(str(drive_id)) > 16 else str(drive_id),
            )
            return
        if self._planning_browse_mode("destination") == "local":
            log_info(
                "destination_graph_skeleton_child_load_skipped",
                reason="local_browse_mode",
                worker_tag=str(worker_tag)[:80],
                drive_id_suffix=str(drive_id)[-16:] if len(str(drive_id)) > 16 else str(drive_id),
            )
            return
        active_entry = self.root_load_workers.get("destination")
        _dcf = str(drive_id or "").strip().casefold()
        pend = str((self.pending_root_drive_ids or {}).get("destination") or "").strip()
        pend_matches = bool(_dcf and pend and pend.casefold() == _dcf)
        if active_entry:
            if active_entry.get("id") != worker_id:
                log_info(
                    "destination_graph_skeleton_schedule_blocked",
                    reason="stale_root_worker_id_active_registry_mismatch",
                    worker_tag=str(worker_tag)[:80],
                    drive_id_suffix=str(drive_id)[-16:] if len(str(drive_id)) > 16 else str(drive_id),
                )
                log_info(
                    "destination_graph_skeleton_child_load_skipped",
                    reason="stale_root_worker_id",
                    worker_tag=str(worker_tag)[:80],
                    drive_id_suffix=str(drive_id)[-16:] if len(str(drive_id)) > 16 else str(drive_id),
                )
                return
        else:
            # Root worker often cleans up before deferred timers fire; pending drive match is authoritative.
            if not pend_matches:
                log_info(
                    "destination_graph_skeleton_schedule_blocked",
                    reason="no_active_root_worker_pending_mismatch",
                    worker_tag=str(worker_tag)[:80],
                    drive_id_suffix=str(drive_id)[-16:] if len(str(drive_id)) > 16 else str(drive_id),
                )
                log_info(
                    "destination_graph_skeleton_child_load_skipped",
                    reason="stale_root_worker_id",
                    worker_tag=str(worker_tag)[:80],
                    drive_id_suffix=str(drive_id)[-16:] if len(str(drive_id)) > 16 else str(drive_id),
                )
                return
            log_info(
                "destination_root_worker_success_accepted_for_selected_drive",
                context="skeleton_child_load",
                note="root_worker_registry_cleared_after_thread_finished_pending_drive_matches",
                drive_id_suffix=str(drive_id)[-16:] if len(str(drive_id)) > 16 else str(drive_id),
            )
        if pend and str(drive_id or "").strip() and pend.casefold() != str(drive_id or "").strip().casefold():
            log_info(
                "destination_graph_skeleton_child_load_skipped",
                reason="pending_drive_mismatch",
                worker_tag=str(worker_tag)[:80],
                pending_drive_suffix=pend[-16:] if len(pend) > 16 else pend,
                drive_id_suffix=str(drive_id)[-16:] if len(str(drive_id)) > 16 else str(drive_id),
            )
            return
        model = getattr(self, "destination_planning_model", None)
        if model is None:
            log_info(
                "destination_graph_skeleton_child_load_skipped",
                reason="no_model",
                worker_tag=str(worker_tag)[:80],
            )
            return
        inv0 = QModelIndex()
        try:
            _rc_pre = int(model.rowCount(inv0))
        except Exception:
            _rc_pre = 0
        _pre_rows: list[dict[str, Any]] = []
        for _pr in range(min(_rc_pre, 48)):
            try:
                _pix = model.index(_pr, 0, inv0)
            except Exception:
                continue
            if not _pix.isValid():
                continue
            _ppl = self._destination_model_index_user_role_dict(_pix)
            if not isinstance(_ppl, dict):
                continue
            try:
                _psub = int(model.rowCount(_pix))
            except Exception:
                _psub = -1
            _pre_rows.append(
                {
                    "row": int(_pr),
                    "name_excerpt": str(_ppl.get("name", "") or "")[:80],
                    "children_loaded": bool(_ppl.get("children_loaded")),
                    "subtree_child_rows": int(_psub),
                    "item_id_suffix": str(_ppl.get("id", "") or "")[-16:],
                }
            )
        log_info(
            "destination_graph_skeleton_row_state_before_schedule",
            phase="pre_children_loaded_reconcile",
            worker_tag=str(worker_tag)[:80],
            drive_id_suffix=str(drive_id)[-16:] if len(str(drive_id)) > 16 else str(drive_id),
            top_level_rows=int(_rc_pre),
            rows=_pre_rows[:32],
        )
        try:
            if hasattr(model, "reconcile_top_level_live_graph_children_loaded_when_subtree_empty"):
                _sk_reset = model.reconcile_top_level_live_graph_children_loaded_when_subtree_empty(
                    reason=f"graph_skeleton_preflight:{str(worker_tag)[:80]}"
                )
            else:
                _sk_reset = 0
        except Exception as _sk_exc:
            _sk_reset = -1
            log_warn(
                "destination_graph_skeleton_reconcile_preflight_failed",
                error=str(_sk_exc)[:220],
                worker_tag=str(worker_tag)[:80],
            )
        log_info(
            "destination_graph_skeleton_row_state_after_schedule",
            phase="after_children_loaded_reconcile",
            worker_tag=str(worker_tag)[:80],
            resets_applied=int(_sk_reset),
            drive_id_suffix=str(drive_id)[-16:] if len(str(drive_id)) > 16 else str(drive_id),
        )
        inv = QModelIndex()
        try:
            rc = int(model.rowCount(inv))
        except Exception:
            rc = 0
        tw = getattr(self, "destination_tree_widget", None)
        eligible: list[tuple[int, dict]] = []
        _dcf_sel = _dcf
        _row_snapshots: list[dict[str, Any]] = []
        for r in range(rc):
            _tag = ""
            try:
                ix = model.index(r, 0, inv)
            except Exception:
                _tag = "index_error"
                _row_snapshots.append({"row": int(r), "eligibility_tag": _tag})
                continue
            if not ix.isValid():
                _tag = "invalid_index"
                _row_snapshots.append({"row": int(r), "eligibility_tag": _tag})
                continue
            pl = self._destination_model_index_user_role_dict(ix)
            _nm = str(pl.get("name", "") or "")[:80] if isinstance(pl, dict) else ""
            _iid = str(pl.get("id", "") or "").strip() if isinstance(pl, dict) else ""
            _did = str(pl.get("drive_id", "") or "").strip() if isinstance(pl, dict) else ""
            try:
                n_sub = int(model.rowCount(ix))
            except Exception:
                n_sub = -1
            _cl = bool(pl.get("children_loaded")) if isinstance(pl, dict) else False
            _lf = bool(pl.get("load_failed")) if isinstance(pl, dict) else False
            _expanded = False
            try:
                if tw is not None:
                    _expanded = bool(tw.isExpanded(ix))
            except Exception:
                _expanded = False
            _drive_match = bool(_dcf_sel and _did and _dcf_sel == _did.casefold())
            if not isinstance(pl, dict) or pl.get("placeholder"):
                _tag = "placeholder"
            elif _lf:
                _tag = "load_failed"
            elif not pl.get("is_folder", True):
                _tag = "not_folder"
            elif not self._destination_row_is_live_graph_structure(pl):
                _tag = "not_live_graph_row"
            elif _cl and not self._destination_row_needs_live_graph_child_refresh(pl):
                _tag = "already_children_loaded"
            elif not _did:
                _tag = "missing_drive_id"
            elif not _iid:
                _tag = "missing_item_id"
            else:
                _tag = "eligible_candidate"
                eligible.append((r, pl))
            _row_snapshots.append(
                {
                    "row": int(r),
                    "name_excerpt": _nm,
                    "eligibility_tag": _tag,
                    "children_loaded": _cl,
                    "subtree_child_rows": int(n_sub),
                    "load_failed": _lf,
                    "expanded": _expanded,
                    "item_id_suffix": _iid[-16:] if len(_iid) > 16 else _iid,
                    "drive_id_suffix": _did[-16:] if len(_did) > 16 else _did,
                    "selected_drive_matches_row_drive": _drive_match,
                }
            )
            log_info(
                "destination_graph_skeleton_top_level_row_gate",
                worker_tag=str(worker_tag)[:80],
                row=int(r),
                eligibility_tag=str(_tag)[:80],
                name_excerpt=_nm,
                subtree_child_rows=int(n_sub),
                children_loaded=_cl,
            )
        log_info(
            "destination_graph_skeleton_eligibility_snapshot",
            worker_tag=str(worker_tag)[:80],
            drive_id_suffix=str(drive_id)[-16:] if len(str(drive_id)) > 16 else str(drive_id),
            top_level_rows=int(rc),
            rows=_row_snapshots[:32],
        )
        if not eligible:
            log_info(
                "destination_graph_skeleton_child_load_skipped",
                reason="no_eligible_top_level_folders",
                worker_tag=str(worker_tag)[:80],
                top_level_rows=int(rc),
            )
            try:
                _deleg = False
                for _r in range(min(int(rc), 48)):
                    try:
                        _six = model.index(_r, 0, inv)
                    except Exception:
                        continue
                    if not _six.isValid():
                        continue
                    _spl = self._destination_model_index_user_role_dict(_six)
                    if not isinstance(_spl, dict):
                        continue
                    if self._destination_row_needs_live_graph_child_refresh(_spl):
                        _deleg = True
                        break
                if _deleg:
                    log_info(
                        "destination_skeleton_skip_delegated_to_snapshot_branch_refresh",
                        worker_tag=str(worker_tag)[:80],
                        drive_id_suffix=str(drive_id)[-16:] if len(str(drive_id)) > 16 else str(drive_id),
                    )
                    QTimer.singleShot(
                        0,
                        lambda d=str(drive_id or ""): self._safe_invoke(
                            "destination_skeleton_delegated_snapshot_branch_refresh",
                            lambda: self._destination_schedule_unverified_snapshot_branches_live_refresh(
                                drive_id=d,
                                reason=f"skeleton_skip_delegate:{worker_tag}",
                            ),
                        ),
                    )
            except Exception:
                pass
            return
        targets: list[int] = []
        if len(eligible) == 1:
            targets = [eligible[0][0]]
            log_info(
                "destination_graph_skeleton_child_load_scheduled",
                mode="single_top_level_folder",
                folder_count=1,
                drive_id_suffix=str(drive_id)[-16:] if len(str(drive_id)) > 16 else str(drive_id),
            )
        else:
            for r, _pl in eligible:
                try:
                    ix = model.index(r, 0, inv)
                    if tw is not None and tw.isExpanded(ix):
                        targets.append(r)
                except Exception:
                    continue
            if not targets:
                log_info(
                    "destination_graph_skeleton_child_load_skipped",
                    reason="multi_top_level_expand_to_load",
                    worker_tag=str(worker_tag)[:80],
                    eligible_top_level=len(eligible),
                )
                return
            log_info(
                "destination_graph_skeleton_child_load_scheduled",
                mode="expanded_top_level_only",
                folder_count=len(targets),
                drive_id_suffix=str(drive_id)[-16:] if len(str(drive_id)) > 16 else str(drive_id),
            )
        log_info(
            "destination_graph_skeleton_first_level_bound",
            drive_id_suffix=str(drive_id)[-16:] if len(str(drive_id)) > 16 else str(drive_id),
            target_row_count=len(targets),
        )
        for r in targets:
            try:
                ix = model.index(int(r), 0, inv)
            except Exception:
                continue
            if not ix.isValid():
                continue
            log_info(
                "destination_graph_skeleton_child_load_started",
                row=int(r),
                drive_id_suffix=str(drive_id)[-16:] if len(str(drive_id)) > 16 else str(drive_id),
            )
            ok = self._request_graph_destination_children_load(
                ix, reason="skeleton_first_level", trigger=f"graph_skeleton:{worker_tag}"
            )
            _payload = {
                "row": int(r),
                "queued_or_started": bool(ok),
                "drive_id_suffix": str(drive_id)[-16:] if len(str(drive_id)) > 16 else str(drive_id),
            }
            if ok:
                log_info("destination_graph_skeleton_child_load_completed", **_payload)
            else:
                log_info("destination_graph_skeleton_child_load_skipped", reason="queue_or_worker", **_payload)

    def _destination_full_tree_worker_running_for_ui(self) -> bool:
        w = getattr(self, "_destination_full_tree_worker", None)
        try:
            return w is not None and w.isRunning()
        except Exception:
            return False

    def _destination_status_message_authority_pending_or_reconcile(self) -> tuple[str, bool]:
        """Status when authority shell is pending: full-tree walking vs skeleton-first lazy loading."""
        if self._destination_full_tree_worker_running_for_ui():
            return "Destination library: reconciling full structure from Microsoft 365…", True
        return "Destination library ready — live folders loading on demand.", False

    def _destination_startup_snapshot_identity_matches_active(self, active_drive_id: str) -> bool:
        m = str(getattr(self, "_destination_snapshot_mount_drive_id", "") or "").strip()
        a = str(active_drive_id or "").strip()
        return bool(m and a and m.casefold() == a.casefold())

    def _destination_startup_promoted_semantic_paths_note(self, paths: list[str] | set[str]) -> None:
        """Bounded set of planning semantic paths that must win over full-tree enumerate during merge."""
        cap = int(getattr(self, "_destination_startup_promoted_semantic_paths_cap", 4000) or 4000)
        cap = max(1, min(cap, 50_000))
        s = getattr(self, "_destination_startup_promoted_semantic_paths", None)
        if not isinstance(s, set):
            s = set()
            self._destination_startup_promoted_semantic_paths = s
        allowed = getattr(self, "_destination_startup_allowed_semantic_root_segments_cf", None)
        filtered = filter_promoted_semantic_paths_for_destination_roots(paths, allowed if allowed else None)
        for raw in filtered:
            p = self.normalize_memory_path(str(raw or "").strip())
            if not p:
                continue
            s.add(p.casefold())
        while len(s) > cap:
            try:
                s.pop()
            except KeyError:
                break

    def _destination_collect_path_keys_from_session_snapshot_nodes(self, nodes: list | None) -> list[str]:
        """Walk persisted session snapshot tree nodes; return normalized path strings for merge keys."""

        def _walk(n: dict, acc: list[str]) -> None:
            if not isinstance(n, dict):
                return
            d = dict(n.get("data") or {})
            for k in ("item_path", "destination_path", "display_path"):
                v = str(d.get(k) or "").strip()
                if v:
                    acc.append(self.normalize_memory_path(v))
            for ch in list(n.get("children") or []):
                if isinstance(ch, dict):
                    _walk(ch, acc)

        out: list[str] = []
        for root in list(nodes or []):
            if isinstance(root, dict):
                _walk(root, out)
        return out

    def _destination_startup_promote_runtime_snapshot_after_graph_bind(self, *, branch_path_excerpt: str) -> None:
        """Best-effort runtime snapshot refresh after graph bind (never force-live: avoids UI-thread freeze)."""
        nodes_before = -1
        try:
            rs0 = getattr(self, "_runtime_session_tree_snapshots", None)
            if isinstance(rs0, dict) and isinstance(rs0.get("destination"), list):
                try:
                    nodes_before = int(self._count_tree_snapshot_nodes(rs0.get("destination")))
                except Exception:
                    nodes_before = -1
            self._refresh_runtime_tree_snapshot("destination")
            rs = getattr(self, "_runtime_session_tree_snapshots", None)
            dest_snaps = list(rs.get("destination", [])) if isinstance(rs, dict) and isinstance(rs.get("destination"), list) else []
            paths = self._destination_collect_path_keys_from_session_snapshot_nodes(dest_snaps)
            self._destination_startup_promoted_semantic_paths_note(paths)
            nodes_after = int(self._count_tree_snapshot_nodes(dest_snaps))
            rows_delta = nodes_after - nodes_before if nodes_before >= 0 else nodes_after
            log_info(
                "destination_startup_descendant_promoted_to_snapshot",
                branch_path_excerpt=str(branch_path_excerpt or "")[:400],
                rows_promoted_hint=max(0, int(rows_delta)),
                snapshot_recursive_nodes_after=int(nodes_after),
            )
        except Exception as exc:
            self._log_restore_exception("destination_startup_promote_runtime_snapshot_after_graph_bind", exc)

    def _destination_startup_snapshot_handoff_before_authority_full_walk(self) -> None:
        """Best-effort refresh before full-tree walk (no force-live during startup)."""
        if not bool(getattr(self, "_destination_tree_snapshot_dirty_for_persist", False)):
            return
        try:
            self._refresh_runtime_tree_snapshot("destination")
            rs = getattr(self, "_runtime_session_tree_snapshots", None)
            dest_snaps = list(rs.get("destination", [])) if isinstance(rs, dict) and isinstance(rs.get("destination"), list) else []
            self._destination_startup_promoted_semantic_paths_note(
                self._destination_collect_path_keys_from_session_snapshot_nodes(dest_snaps)
            )
        except Exception as exc:
            self._log_restore_exception("destination_startup_snapshot_handoff_before_authority_full_walk", exc)

    def _destination_maybe_log_startup_descendant_queue_completed(self) -> None:
        if not bool(getattr(self, "_destination_startup_descendant_injection_active", False)):
            return
        if bool(getattr(self, "_destination_startup_descendant_queue_completed_logged", False)):
            return
        dq = getattr(self, "_destination_descendant_apply_queue", None)
        st = getattr(self, "_destination_descendant_apply_state", None)
        if st is not None:
            return
        if dq and len(dq) > 0:
            return
        self._destination_startup_descendant_queue_completed_logged = True
        log_info(
            "destination_startup_descendant_queue_completed",
            note="destination_descendant_apply_queue_and_state_idle_after_startup_injection",
        )

    def _destination_resume_startup_descendant_queue_after_authority_if_paused(self, *, phase: str) -> None:
        if not bool(getattr(self, "_destination_startup_descendant_queue_paused_for_authority", False)):
            return
        self._destination_startup_descendant_queue_paused_for_authority = False
        log_info(
            "destination_startup_descendant_queue_resumed_after_authority",
            phase=str(phase or "")[:120],
        )
        try:
            self._schedule_destination_descendant_apply_tick()
        except Exception as exc:
            self._log_restore_exception("destination_resume_startup_descendant_queue_after_authority", exc)

    def _destination_prepare_destination_snapshot_for_shutdown_save(self) -> None:
        """Drain descendant apply then capture destination from the live model for session JSON.

        Runs under ``_application_shutting_down`` before :meth:`_save_draft_shell` so injected rows are
        not dropped solely because post-tick promotion is suppressed during shutdown.
        """
        try:
            if bool(getattr(self, "_destination_descendant_snapshot_dirty_pending", False)):
                self._destination_flush_descendant_snapshot_dirty_batch(
                    "before_shutdown",
                    force=True,
                    skip_scroll_guard=True,
                )
                log_info("destination_descendant_snapshot_dirty_flush_before_shutdown")
        except Exception as exc:
            self._log_restore_exception("destination_descendant_snapshot_dirty_flush_before_shutdown_prep", exc)
        try:
            self._destination_finalize_inflight_descendant_apply_for_snapshot_capture()
        except Exception as exc:
            self._log_restore_exception("destination_prepare_shutdown_finalize", exc)
        log_info("destination_shutdown_bounded_flush_start", phase="shutdown_prepare")
        _flush_stats: dict[str, int] = {}
        try:
            _flush_stats = self._destination_prune_invalid_unresolved_replay_parent_paths(
                context="shutdown_prepare"
            )
        except Exception as exc:
            self._log_restore_exception("destination_shutdown_prune_invalid_unresolved", exc)
            _flush_stats = {}
        try:
            _def_alloc = int(self._unresolved_allocation_queue_size() or 0)
            _def_prop = int(self._unresolved_proposed_queue_size() or 0)
            log_info(
                "destination_shutdown_bounded_flush_summary",
                flushed_valid_items=0,
                deferred_valid_items=int(_def_alloc + _def_prop),
                pruned_invalid_items=int(_flush_stats.get("pruned_entry_total", 0) or 0),
                pruned_invalid_proposed_parents=int(_flush_stats.get("pruned_proposed_parents", 0) or 0),
                pruned_invalid_allocation_parents=int(_flush_stats.get("pruned_allocation_parents", 0) or 0),
                remaining_nonblocking_items=int(_def_alloc + _def_prop),
                note="no_full_overlay_convergence_shutdown_persist",
            )
        except Exception as exc:
            self._log_restore_exception("destination_shutdown_bounded_flush_summary_log", exc)
        log_info(
            "destination_shutdown_bounded_persist_skip_full_overlay",
            reason="bounded_persist_prune_then_capture",
        )
        if getattr(self, "_destination_descendant_apply_tick_running", False):
            log_info(
                "destination_snapshot_saved_from_stale_cache",
                context="shutdown_pre_save",
                reason="tick_still_running_after_finalize",
            )
            return
        try:
            try:
                _live_np = int(self._count_destination_model_non_placeholder_nodes())
            except Exception:
                _live_np = -1
            log_info("destination_shutdown_snapshot_enrichment_started")
            fresh = self._capture_tree_items_snapshot("destination")
            try:
                _n_b = int(self._count_tree_snapshot_nodes(fresh))
            except Exception:
                _n_b = -1
            st_d = getattr(self, "_draft_shell_state", None)
            ex_s = list(st_d.DestinationTreeSnapshot or []) if isinstance(st_d, SessionState) else []
            rs0 = getattr(self, "_runtime_session_tree_snapshots", None)
            rt_d = list(rs0.get("destination") or []) if isinstance(rs0, dict) else []
            pr_w: list = []
            mm0 = getattr(self, "memory_manager", None)
            if mm0 is not None:
                try:
                    wso0 = mm0.read_workspace_snapshot_optional()  # type: ignore[union-attr]  # noqa: E501
                    if isinstance(wso0, dict):
                        pr_w = list(wso0.get("destination_tree_snapshot") or [])
                        if not isinstance(pr_w, list):
                            pr_w = []
                except Exception:
                    pr_w = []
            h0 = self._destination_bounded_history_snapshot_source_lists()
            try:
                fresh = self._destination_enrich_persisted_destination_tree_snapshot(
                    list(fresh or []),
                    existing_session_roots=ex_s,
                    runtime_session_roots=rt_d,
                    prior_workspace_roots=pr_w,
                    history_sources=h0,
                    phase="shutdown_prepare",
                )
            except Exception as exc:
                self._log_restore_exception("destination_shutdown_snapshot_enrich", exc)
            try:
                _n = int(self._count_tree_snapshot_nodes(fresh))
            except Exception:
                _n = -1
            _delta_nodes = int(_n) - int(_n_b) if _n >= 0 and _n_b >= 0 else 0
            log_info(
                "destination_shutdown_snapshot_enrichment_completed",
                recursive_nodes_before=int(_n_b),
                recursive_nodes_after=int(_n),
                preserved_branch_count=int(max(0, _delta_nodes)),
            )
            _bc = 0
            _ix = getattr(self, "_destination_shutdown_richest_planned_path_index", None)
            if isinstance(_ix, dict):
                _bc = int(len(_ix))
            log_info(
                "destination_shutdown_preservation_index_used",
                branch_count=_bc,
                had_runtime_index=bool(
                    isinstance(getattr(self, "_destination_shutdown_preservation_branch_index", None), dict)
                ),
            )
            rs = getattr(self, "_runtime_session_tree_snapshots", None)
            if isinstance(rs, dict):
                rs["destination"] = list(fresh or [])
            log_info(
                "destination_shutdown_final_snapshot_capture",
                destination_snapshot_recursive_nodes=int(_n),
                immediate_pre_save_live_non_placeholder_nodes=int(_live_np),
            )
            log_info(
                "destination_snapshot_saved_fresh_on_shutdown",
                destination_snapshot_recursive_nodes=int(_n),
                immediate_pre_save_live_non_placeholder_nodes=int(_live_np),
            )
            if _live_np >= 0 and _n >= 0 and _live_np != _n:
                log_info(
                    "destination_snapshot_shutdown_count_mismatch",
                    immediate_pre_save_live_non_placeholder_nodes=int(_live_np),
                    snapshot_recursive_nodes_captured=int(_n),
                    note="snapshot_walk_may_count_placeholder_or_differ_from_model_iter; investigate if persistent",
                )
            self._destination_tree_snapshot_dirty_for_persist = False
        except Exception as exc:
            self._log_restore_exception("destination_prepare_shutdown_capture", exc)

    def _promote_destination_workspace_snapshot_after_structure_change(self) -> None:
        """After projected descendants or allocation subtree mutations, refresh the cached destination snapshot.

        Session ``DestinationTreeSnapshot`` is only refreshed when ``include_workspace_ui=True`` saves run.
        Without this, incremental injection can leave persisted JSON stale until a full workspace save
        (e.g. close/sign-out), so the next launch replays from an incomplete tree while resume metadata
        still reflects progress — matching scroll-deferred overlay / re-hydration behavior.
        """
        if getattr(self, "_application_shutting_down", False):
            return
        if getattr(self, "_destination_snapshot_capture_drain_active", False):
            return
        if getattr(self, "_destination_descendant_apply_tick_running", False):
            self._post_tick_snapshot_refresh_pending = True
            self._destination_post_tick_deferred_boundary_log("snapshot_promotion_deferred_because_tick_running")
            return
        try:
            self._refresh_runtime_tree_snapshot("destination")
        except Exception as exc:
            self._log_restore_exception("promote_destination_snapshot_refresh", exc)
        self._schedule_workspace_ui_persist(panel_key="destination", delay_ms=850)

    def _schedule_workspace_ui_persist(self, delay_ms=1200, *, panel_key=None):
        if getattr(self, "_application_shutting_down", False):
            return
        try:
            if panel_key in {"source", "destination"}:
                self._workspace_ui_snapshot_dirty_panels.add(panel_key)
                if self._expand_all_pending.get(panel_key):
                    return
            else:
                self._workspace_ui_snapshot_dirty_panels.update({"source", "destination"})
                if self._expand_all_pending.get("source") or self._expand_all_pending.get("destination"):
                    return
            if self._planning_workspace_is_busy():
                delay_ms = max(delay_ms, 1800)
            if hasattr(self, "_workspace_ui_persist_timer") and self._workspace_ui_persist_timer is not None:
                self._workspace_ui_persist_timer.start(max(0, int(delay_ms)))
        except Exception as exc:
            self._log_restore_exception("schedule_workspace_ui_persist", exc)

    def _on_workspace_ui_persist_timer(self):
        try:
            if self._workspace_ui_persist_should_defer():
                self._workspace_ui_persist_timer.start(2000)
                return
            dirty_panels = set(self._workspace_ui_snapshot_dirty_panels or set())
            if not dirty_panels:
                dirty_panels = {"source", "destination"}
            for panel in sorted(dirty_panels):
                self._refresh_runtime_tree_snapshot(panel)
            self._workspace_ui_snapshot_dirty_panels.clear()
            self._persist_workspace_ui_state_safely()
        except Exception as exc:
            self._log_restore_exception("on_workspace_ui_persist_timer", exc)

    def showEvent(self, event):
        super().showEvent(event)
        print(
            f"[window-startup] showEvent state={self._window_state_repr()} "
            f"geometry={self.geometry().getRect()}"
        )
        if hasattr(self, "work_email_input") and self.work_email_input is not None:
            self._schedule_safe_timer(0, "startup_focus_work_email", self.work_email_input.setFocus)
        if not self._startup_post_show_logged:
            self._startup_post_show_logged = True
            self._schedule_safe_timer(0, "startup_post_show_log", self._log_post_startup_state)
        if not self._auto_debug_dest_tree_show_fallback_scheduled:
            self._auto_debug_dest_tree_show_fallback_scheduled = True
            if (
                not running_under_pytest()
                and os.environ.get("OZLINK_AUTO_DEBUG_DEST_TREE_EXPORT", "1").strip().lower()
                not in ("0", "false", "no", "off")
            ):
                QTimer.singleShot(
                    45_000,
                    lambda: self._safe_invoke(
                        "auto_debug_dest_tree_show_fallback",
                        self._run_auto_debug_destination_tree_pair_once,
                        "post_show_45s",
                    ),
                )
        if not self._silent_graph_restore_scheduled:
            self._silent_graph_restore_scheduled = True
            self._schedule_safe_timer(200, "silent_graph_session_restore", self._begin_silent_graph_session_restore)
        if sys.platform == "win32":
            QTimer.singleShot(0, self._clamp_main_window_minimum_size_to_available_work_area)
            QTimer.singleShot(120, self._clamp_main_window_minimum_size_to_available_work_area)

    def changeEvent(self, event):
        if event.type() == QEvent.Type.WindowStateChange:
            tb = getattr(self, "_custom_title_bar", None)
            if tb is not None:
                tb._sync_maximize_glyph()
            QTimer.singleShot(0, self._clamp_main_window_minimum_size_to_available_work_area)
        super().changeEvent(event)

    def nativeEvent(self, eventType, message):
        if sys.platform != "win32":
            return False, 0
        try:
            import ctypes
            from ctypes import wintypes
        except ImportError:
            return False, 0
        et = eventType
        if isinstance(et, QByteArray):
            et = bytes(et)
        elif not isinstance(et, (bytes, bytearray)):
            return False, 0
        if et != b"windows_generic_MSG":
            return False, 0
        WM_NCHITTEST = 0x0084
        WM_GETMINMAXINFO = 0x0024
        try:
            msg = wintypes.MSG.from_address(int(message))
        except (TypeError, ValueError, OSError):
            return False, 0
        if msg.message == WM_GETMINMAXINFO:
            wid = int(self.winId())
            ex = tuple(h for h in (wid,) if h)
            qt_native_clamp_getminmaxinfo(eventType, message, extra_hwnds=ex)
            try:
                out = super(MainWindow, self).nativeEvent(eventType, message)
            except Exception:
                out = False, 0
            qt_native_clamp_getminmaxinfo(eventType, message, extra_hwnds=ex)
            return out
        if msg.message != WM_NCHITTEST:
            return False, 0

        lp = int(msg.lParam)
        gx = lp & 0xFFFF
        if gx >= 32768:
            gx -= 65536
        gy = (lp >> 16) & 0xFFFF
        if gy >= 32768:
            gy -= 65536
        gpt = QPoint(int(gx), int(gy))
        pos = self.mapFromGlobal(gpt)

        menu_h = 0
        mb = self.menuBar()
        if mb is not None and mb.isVisible():
            menu_h = mb.height()
        if pos.y() < menu_h:
            return False, 0

        if self.isMaximized():
            tb = getattr(self, "_custom_title_bar", None)
            if tb is not None and not self._frameless_hit_sys_buttons_global(gpt):
                tl = tb.mapTo(self, QPoint(0, 0))
                if QRect(tl, tb.size()).contains(pos):
                    return True, 2
            return False, 0

        edge = 6
        w, h = self.width(), self.height()
        on_left = pos.x() < edge
        on_right = pos.x() >= w - edge
        on_bottom = pos.y() >= h - edge
        if on_bottom and on_left:
            return True, 16
        if on_bottom and on_right:
            return True, 17
        if on_left:
            return True, 10
        if on_right:
            return True, 11
        if on_bottom:
            return True, 15

        tb = getattr(self, "_custom_title_bar", None)
        if tb is not None:
            tl = tb.mapTo(self, QPoint(0, 0))
            trect = QRect(tl, tb.size())
            if trect.contains(pos):
                if self._frameless_hit_sys_buttons_global(gpt):
                    return False, 0
                return True, 2

        return False, 0

    def _frameless_hit_sys_buttons_global(self, gpt: QPoint) -> bool:
        tb = getattr(self, "_custom_title_bar", None)
        if tb is None:
            return False
        local = tb.mapFromGlobal(gpt)
        return tb._is_on_sys_button(local)

    def show(self):
        print("[window-startup] show() called")
        if not self._startup_geometry_applied:
            self._startup_geometry_applied = True
            self.apply_startup_window_geometry()
            self._clamp_main_window_minimum_size_to_available_work_area()
            print(
                "[window-startup] pre-final-show "
                f"flags={int(self.windowFlags())} "
                f"geometry={self.geometry().getRect()}"
            )
            super().showMaximized()
            if sys.platform == "win32":
                self._clamp_main_window_minimum_size_to_available_work_area()
            QTimer.singleShot(0, self._clamp_main_window_minimum_size_to_available_work_area)
            QTimer.singleShot(80, self._clamp_main_window_minimum_size_to_available_work_area)
            return

        super().show()

    def _log_shutdown_trace_stage(self, stage: str, t_stage_start: float, **extra) -> float:
        """End of a shutdown stage: log elapsed_ms since ``t_stage_start``; return new perf_counter for next stage."""
        elapsed_ms = round((time.perf_counter() - t_stage_start) * 1000.0, 2)
        log_info("shutdown_trace", event="stage_end", stage=stage, elapsed_ms=elapsed_ms, **extra)
        return time.perf_counter()

    def _if_shutdown_skip_mutation(self, mutation_path: str, **extra: Any) -> bool:
        """When True, caller must fast-return; logs structured skip (throttled for descendant ticks)."""
        if not getattr(self, "_application_shutting_down", False):
            return False
        mp = str(mutation_path)[:200]
        if mp == "_apply_destination_planning_overlays" and getattr(
            self, "_destination_shutdown_pre_save_overlay_flush", False
        ):
            return False
        if mp == "_run_destination_descendant_apply_tick" and getattr(
            self, "_destination_snapshot_capture_drain_active", False
        ):
            return False
        try:
            if mp == "_run_destination_descendant_apply_tick":
                if not getattr(self, "_shutdown_descendant_tick_skip_event_logged", False):
                    self._shutdown_descendant_tick_skip_event_logged = True
                    log_info(
                        "shutdown_trace",
                        event="shutdown_mutation_skipped",
                        mutation_path=mp,
                        **{k: v for k, v in extra.items() if v is not None},
                    )
                else:
                    self._shutdown_descendant_tick_skip_logs_suppressed = (
                        int(getattr(self, "_shutdown_descendant_tick_skip_logs_suppressed", 0) or 0) + 1
                    )
            else:
                log_info(
                    "shutdown_trace",
                    event="shutdown_mutation_skipped",
                    mutation_path=mp,
                    **{k: v for k, v in extra.items() if v is not None},
                )
        except Exception:
            pass
        return True

    def _stop_all_shutdown_mutation_timers(self) -> None:
        """Stop Qt timers that can enqueue destination / planning work during :meth:`closeEvent`."""
        for name in (
            "_wait_timer",
            "_destination_full_tree_materialize_timer",
            "_destination_idle_materialize_timer",
            "_lazy_destination_projection_timer",
            "_destination_expand_burst_timer",
            "_destination_future_projection_timer",
            "_destination_bind_reconcile_after_workers_timer",
            "_destination_indicator_refresh_timer",
            "_destination_tree_scroll_idle_timer",
            "_destination_lbs_recompute_timer",
            "_destination_structure_reactive_coalesce_timer",
            "_destination_descendant_apply_timer",
            "_destination_overlay_source_invariant_timer",
            "_progress_summary_refresh_timer",
            "_deferred_planning_refresh_timer",
            "_graph_ids_refresh_batch_timer",
            "_destination_planning_overlay_gui_chunk_timer",
            "_source_background_preload_timer",
            "_destination_incremental_merge_timer",
            "_graph_linkage_progress_success_hide_timer",
            "_session_keepalive_timer",
            "_loading_visual_timer",
            "_planning_graph_assurance_hide_timer",
            "_planning_mutation_autosave_timer",
        ):
            timer = getattr(self, name, None)
            if timer is None:
                continue
            try:
                timer.stop()
            except Exception:
                pass
        for timer_map_attr in ("_expand_all_timers", "_deferred_background_load_timers"):
            tm = getattr(self, timer_map_attr, None)
            if isinstance(tm, dict):
                for tmr in tm.values():
                    if tmr is None:
                        continue
                    try:
                        tmr.stop()
                    except Exception:
                        pass

    def _abort_destination_descendant_apply_for_shutdown(self) -> None:
        timer = getattr(self, "_destination_descendant_apply_timer", None)
        if timer is not None:
            try:
                timer.stop()
            except Exception:
                pass
        dq = getattr(self, "_destination_descendant_apply_queue", None)
        q_before = len(dq) if dq else 0
        had_state = getattr(self, "_destination_descendant_apply_state", None) is not None
        if dq is not None:
            try:
                dq.clear()
            except Exception:
                pass
        self._destination_descendant_apply_state = None
        self._destination_descendant_apply_tick_running = False
        self._destination_descendant_apply_inline_drain = False
        self._shutdown_descendant_tick_skip_logs_suppressed = 0
        self._shutdown_descendant_tick_skip_event_logged = False
        log_info(
            "shutdown_trace",
            event="descendant_apply_queue_cleared",
            queue_len_before=int(q_before),
            had_active_state=bool(had_state),
        )
        self._post_tick_descendant_drain_pending = False
        self._post_tick_snapshot_refresh_pending = False
        self._post_tick_inline_descendant_schedule_pending = False
        try:
            self._post_tick_descendant_deferred_reenter_depth = 0
        except Exception:
            pass

    def _shutdown_abort_restore_side_pipelines(self) -> None:
        """Stop graph-enrichment generators and async destination projection without full restore-abort semantics."""
        try:
            self._close_post_import_graph_enrichment_generator()
        except Exception:
            pass
        try:
            self._post_import_graph_enrich_run_id = int(getattr(self, "_post_import_graph_enrich_run_id", 0)) + 1
        except Exception:
            pass
        try:
            self._cancel_destination_future_async_projection("application_shutdown")
        except Exception:
            pass
        try:
            self._cancel_destination_incremental_merge_session("application_shutdown")
        except Exception:
            pass

    def _shutdown_worker_safe_join(self, worker: Any, *, timeout_ms: int = 2500) -> None:
        """``requestInterruption`` + ``wait`` without touching deleted ``QThread`` wrappers."""
        if worker is None:
            return
        try:
            if not _shiboken_is_valid(worker):
                return
        except Exception:
            return
        try:
            if not hasattr(worker, "isRunning") or not worker.isRunning():
                return
        except RuntimeError:
            return
        except Exception:
            return
        try:
            if isinstance(worker, QThread):
                try:
                    worker.quit()
                except Exception:
                    pass
        except Exception:
            pass
        try:
            worker.requestInterruption()
        except RuntimeError:
            return
        except Exception:
            pass
        try:
            if not _shiboken_is_valid(worker):
                return
            worker.wait(int(timeout_ms))
        except RuntimeError:
            return
        except Exception:
            pass

    def closeEvent(self, event):
        t0 = time.perf_counter()
        t = t0
        if getattr(self, "_shutdown_close_event_active", False):
            log_info("shutdown_trace", event="closeEvent_reentrant_guard_skip")
            try:
                event.accept()
            except Exception:
                pass
            return
        self._close_event_skip_draft_persist = False
        if self._session_has_unsaved_user_changes() and not getattr(
            self, "_application_shutting_down", False
        ):
            log_info(
                "close_prompt_unsaved_changes_shown",
                dirty_count=int(getattr(self, "_session_user_edited_unsaved_count", 0) or 0),
            )
            box = QMessageBox(self)
            box.setWindowTitle("Unsaved planning")
            box.setText("Save your planning changes before closing?")
            box.setIcon(QMessageBox.Question)
            _bs = (
                QMessageBox.Save | QMessageBox.Discard | QMessageBox.Cancel
            )  # type: ignore[operator]
            box.setStandardButtons(_bs)
            box.setDefaultButton(QMessageBox.Save)
            res = int(box.exec())
            if res == int(QMessageBox.Cancel):
                log_info("close_prompt_save_choice", choice="cancel")
                try:
                    event.ignore()
                except Exception:
                    pass
                return
            if res == int(QMessageBox.Discard):
                log_info("close_prompt_save_choice", choice="dont_save")
                self._close_event_skip_draft_persist = True
            else:
                log_info("close_prompt_save_choice", choice="save")
                self._explicit_session_save_user_triggered = True
                try:
                    self._save_draft_shell(force=True, include_workspace_ui=True)
                except Exception as exc:
                    self._log_restore_exception("closeEvent_save_before_close", exc)
                finally:
                    self._explicit_session_save_user_triggered = False
                self._session_user_edited_unsaved = False
                self._clear_planning_user_checkpoint()
                self._update_window_user_dirty_title_suffix()
        self._shutdown_close_event_active = True
        log_info("shutdown_trace", event="closeEvent_enter")
        log_info("shutdown_trace", event="shutdown_begin")
        try:
            log_info(
                "shutdown_trace",
                event="shutdown_begin_inventory",
                **thread_inventory_snapshot(),
                **qt_threadpool_snapshot(),
            )
        except Exception as exc:
            log_info("shutdown_trace", event="shutdown_begin_inventory_failed", error=str(exc)[:240])
        wu = getattr(self, "_workspace_ui_persist_timer", None)
        wu_was_active = bool(wu.isActive()) if wu is not None else False
        if wu is not None:
            try:
                wu.stop()
            except Exception:
                pass
        dirty_ui = sorted(getattr(self, "_workspace_ui_snapshot_dirty_panels", set()) or [])
        log_info(
            "shutdown_trace",
            event="workspace_ui_persist_timer_stopped",
            had_dirty_panels=dirty_ui,
            workspace_ui_timer_was_active=wu_was_active,
        )
        t_stop0 = time.perf_counter()
        log_info("shutdown_trace", event="stop_timers_begin")
        self._stop_all_shutdown_mutation_timers()
        log_info(
            "shutdown_trace",
            event="stop_timers_end",
            elapsed_ms=round((time.perf_counter() - t_stop0) * 1000.0, 2),
        )
        self._application_shutting_down = True
        try:
            self._source_projection_restore_chunk_gen = int(getattr(self, "_source_projection_restore_chunk_gen", 0) or 0) + 1000
            self._source_projection_restore_chunk_active = False
            log_info("source_startup_deferred_work_cancelled_on_close", segment="source_projection_chunked_refresh")
        except Exception:
            pass
        self._shutdown_descendant_tick_skip_logs_suppressed = 0
        self._shutdown_descendant_tick_skip_event_logged = False
        # Descendant-apply queue clear is deferred until AFTER save (see close_post_save_descendant_apply_abort).
        # Clearing before capture would drop pending ticks and persist a thinner DestinationTreeSnapshot than the UI.

        t_rs0 = time.perf_counter()
        log_info("shutdown_trace", event="restore_abort_begin")
        self._shutdown_abort_restore_side_pipelines()
        log_info(
            "shutdown_trace",
            event="restore_abort_end",
            elapsed_ms=round((time.perf_counter() - t_rs0) * 1000.0, 2),
        )

        try:
            self._deferred_planning_refresh_pending = False
            self._deferred_planning_refresh_reasons = []
            self._deferred_source_projection_paths = set()
            self._graph_ids_refresh_batch_paths.clear()
            self._graph_ids_refresh_followup_due = False
            _gbt = getattr(self, "_graph_ids_refresh_batch_timer", None)
            if _gbt is not None:
                try:
                    _gbt.stop()
                except Exception:
                    pass
            self._destination_planning_overlay_gui_chunk_state = None
            _oct = getattr(self, "_destination_planning_overlay_gui_chunk_timer", None)
            if _oct is not None:
                try:
                    _oct.stop()
                except Exception:
                    pass
            self._destination_global_reconcile_overlay_deferred = None
            self._destination_overlay_terminal_reconcile_completion_pending = False
            self._destination_reconcile_in_progress = False
        except Exception:
            pass
        t = self._log_shutdown_trace_stage(
            "deferred_planning_cleared_no_flush",
            t,
            note="close_gate_skip_materialize_flush_deferred_planning_refresh_not_run",
        )

        self._destination_branch_forensic_log("close_pre_save_live_model")
        try:
            self._shutdown_running_workers_for_close()
        except Exception as exc:
            self._log_restore_exception("closeEvent.shutdown_workers", exc)
        t = self._log_shutdown_trace_stage("shutdown_workers", t)

        t_tp0 = time.perf_counter()
        try:
            self._drain_global_qthreadpool_for_shutdown()
        except Exception as exc:
            log_info("shutdown_trace", event="qthreadpool_drain_outer_failed", error=str(exc)[:240])
        log_info(
            "shutdown_trace",
            event="qthreadpool_drain_stage",
            elapsed_ms=round((time.perf_counter() - t_tp0) * 1000.0, 2),
        )

        t_sn0 = time.perf_counter()
        log_info("shutdown_trace", event="snapshot_begin")
        t_sv0 = time.perf_counter()
        log_info("shutdown_trace", event="save_begin")
        try:
            self._destination_prepare_destination_snapshot_for_shutdown_save()
        except Exception as exc:
            self._log_restore_exception("closeEvent.destination_prepare_snapshot", exc)
        if not bool(getattr(self, "_close_event_skip_draft_persist", False)):
            try:
                self._save_draft_shell(force=True, include_workspace_ui=True)
            except Exception:
                pass
        else:
            log_info("closeEvent_draft_save_skipped_user_chose_discard", note="skip_full_persist")
        log_info(
            "shutdown_trace",
            event="save_end",
            elapsed_ms=round((time.perf_counter() - t_sv0) * 1000.0, 2),
        )
        log_info(
            "shutdown_trace",
            event="snapshot_end",
            elapsed_ms=round((time.perf_counter() - t_sn0) * 1000.0, 2),
            note="tree_snapshot_built_inside_save_draft_shell",
        )
        t_da0 = time.perf_counter()
        log_info("shutdown_trace", event="descendant_apply_abort_begin", phase="post_save")
        self._abort_destination_descendant_apply_for_shutdown()
        log_info(
            "shutdown_trace",
            event="descendant_apply_abort_end",
            phase="post_save",
            elapsed_ms=round((time.perf_counter() - t_da0) * 1000.0, 2),
        )
        self._destination_branch_forensic_log(
            "close_post_save_persisted_session_json",
            snapshots=self._destination_branch_forensic_read_persisted_session_snapshot(),
        )
        t = self._log_shutdown_trace_stage("save_draft_shell_close", t, include_workspace_ui=True)
        try:
            self._auto_export_draft_on_exit()
        except Exception:
            pass
        t = self._log_shutdown_trace_stage("auto_export_draft_on_exit", t)
        try:
            self.save_window_preferences()
        except Exception:
            pass
        t = self._log_shutdown_trace_stage("save_window_preferences", t)
        super().closeEvent(event)
        try:
            self._shutdown_terminal_completion_gate(phase="close_event")
        except Exception as exc:
            log_info("shutdown_trace", event="shutdown_terminal_gate_failed", phase="close_event", error=str(exc)[:240])
        try:
            log_info(
                "shutdown_trace",
                event="shutdown_end",
                total_elapsed_ms=round((time.perf_counter() - t0) * 1000.0, 2),
                **thread_inventory_snapshot(),
                **qt_threadpool_snapshot(),
            )
            log_info(
                "shutdown_trace",
                event="closeEvent_exit",
                total_elapsed_ms=round((time.perf_counter() - t0) * 1000.0, 2),
                **thread_inventory_snapshot(),
                **qt_threadpool_snapshot(),
            )
            flush_logger()
        except Exception as exc:
            log_info("shutdown_trace", event="shutdown_end_thread_inventory_failed", error=str(exc)[:240])

    def _purge_worker_from_shutdown_registries(self, worker: Any) -> int:
        """Drop *worker* from MainWindow registries so close does not retain or double-delete QThread wrappers."""
        if worker is None:
            return 0
        cleared = 0
        for attr_name in (
            "worker",
            "device_flow_worker",
            "discovery_worker",
            "full_count_worker",
            "cache_refresh_worker",
            "destination_incremental_refresh_worker",
            "_destination_full_tree_worker",
            "_preview_worker",
            "session_keepalive_worker",
            "_silent_graph_restore_worker",
            "_destination_snapshot_light_validation_worker",
            "_manifest_run_worker",
            "_snapshot_pipeline_run_worker",
            "_graph_truth_worker",
        ):
            try:
                if getattr(self, attr_name, None) is worker:
                    setattr(self, attr_name, None)
                    cleared += 1
            except Exception:
                pass
        try:
            ddw = getattr(self, "_drive_delta_workers", None) or {}
            for k, w in list(ddw.items()):
                if w is worker:
                    ddw.pop(k, None)
                    cleared += 1
        except Exception:
            pass
        try:
            for pk, entry in list((self.root_load_workers or {}).items()):
                if isinstance(entry, dict) and entry.get("worker") is worker:
                    self.root_load_workers.pop(pk, None)
                    cleared += 1
        except Exception:
            pass
        try:
            for wk, entry in list((self.folder_load_workers or {}).items()):
                if isinstance(entry, dict) and entry.get("worker") is worker:
                    self.folder_load_workers.pop(wk, None)
                    cleared += 1
        except Exception:
            pass
        try:
            for wid, entry in list((self.root_load_retired_workers or {}).items()):
                if isinstance(entry, dict) and entry.get("worker") is worker:
                    self.root_load_retired_workers.pop(wid, None)
                    cleared += 1
        except Exception:
            pass
        try:
            for wid, entry in list((self.folder_load_retired_workers or {}).items()):
                if isinstance(entry, dict) and entry.get("worker") is worker:
                    self.folder_load_retired_workers.pop(wid, None)
                    cleared += 1
        except Exception:
            pass
        for retired_map in (
            getattr(self, "_retired_preview_workers", None) or {},
            getattr(self, "_retired_destination_full_tree_workers", None) or {},
            getattr(self, "_retired_full_count_workers", None) or {},
        ):
            try:
                for rk, w in list(retired_map.items()):
                    if w is worker:
                        retired_map.pop(rk, None)
                        cleared += 1
            except Exception:
                pass
        return int(cleared)

    def _shutdown_running_workers_for_close(self):
        """Best-effort worker shutdown to avoid QThread destruction during app exit."""
        workers = []
        seen_ids = set()

        def _add_worker(worker):
            if worker is None:
                return
            worker_id = id(worker)
            if worker_id in seen_ids:
                return
            seen_ids.add(worker_id)
            workers.append(worker)

        for attr_name in (
            "worker",
            "device_flow_worker",
            "discovery_worker",
            "full_count_worker",
            "cache_refresh_worker",
            "destination_incremental_refresh_worker",
            "_destination_full_tree_worker",
            "_preview_worker",
            "session_keepalive_worker",
            "_silent_graph_restore_worker",
            "_destination_snapshot_light_validation_worker",
            "_manifest_run_worker",
            "_snapshot_pipeline_run_worker",
            "_graph_truth_worker",
        ):
            _add_worker(getattr(self, attr_name, None))

        for dw in (getattr(self, "_drive_delta_workers", None) or {}).values():
            _add_worker(dw)

        for entry in (self.root_load_workers or {}).values():
            if isinstance(entry, dict):
                _add_worker(entry.get("worker"))
        for entry in (self.folder_load_workers or {}).values():
            if isinstance(entry, dict):
                _add_worker(entry.get("worker"))

        for retired_map in (
            getattr(self, "_retired_preview_workers", None) or {},
            getattr(self, "_retired_destination_full_tree_workers", None) or {},
            getattr(self, "_retired_full_count_workers", None) or {},
        ):
            for w in retired_map.values():
                _add_worker(w)

        for retired_map in (getattr(self, "root_load_retired_workers", None) or {}, getattr(self, "folder_load_retired_workers", None) or {}):
            for entry in retired_map.values():
                if isinstance(entry, dict):
                    _add_worker(entry.get("worker"))

        running_workers = []
        for worker in workers:
            try:
                if not _shiboken_is_valid(worker):
                    continue
                if hasattr(worker, "isRunning") and worker.isRunning():
                    running_workers.append(worker)
            except RuntimeError:
                continue
            except Exception:
                continue
        log_info(
            "shutdown_trace",
            event="shutdown_workers_inventory",
            total_worker_refs=int(len(workers)),
            running_worker_count=int(len(running_workers)),
            orphan_qthreads_held=int(len(_SHUTDOWN_ORPHAN_QTHREADS)),
        )
        if not running_workers:
            log_info(
                "shutdown_trace",
                event="shutdown_workers",
                phase="join_skipped_no_running_threads",
                running_worker_count=0,
                wait_ms=0.0,
                orphan_detached_count=0,
                registry_slots_cleared_total=0,
            )
            return

        log_info("Close requested with running workers.", running_worker_count=len(running_workers))
        t_wait0 = time.perf_counter()
        for worker in running_workers:
            self._shutdown_worker_safe_join(worker, timeout_ms=2500)
            try:
                if _shiboken_is_valid(worker) and worker.isRunning():
                    log_warn(
                        "Worker still running during close wait.",
                        worker_type=type(worker).__name__,
                    )
            except Exception:
                pass
        still_running: list[Any] = []
        for worker in running_workers:
            try:
                if _shiboken_is_valid(worker) and worker.isRunning():
                    still_running.append(worker)
            except Exception:
                pass
        orphan_detached = 0
        registry_slots_cleared_total = 0
        for worker in still_running:
            try:
                worker.disconnect()
            except Exception:
                pass
            try:
                fin = getattr(worker, "finished", None)
                if fin is not None:
                    fin.disconnect()
            except Exception:
                pass
            try:
                if _shiboken_is_valid(worker) and not worker.isRunning():
                    _shutdown_orphan_qthread_finalize(worker)
                    try:
                        registry_slots_cleared_total += int(self._purge_worker_from_shutdown_registries(worker))
                    except Exception:
                        pass
                    orphan_detached += 1
                    log_info(
                        "shutdown_trace",
                        event="shutdown_worker_orphan_already_stopped",
                        worker_type=type(worker).__name__,
                    )
                    continue
            except Exception:
                pass
            try:
                if worker not in _SHUTDOWN_ORPHAN_QTHREADS:
                    _SHUTDOWN_ORPHAN_QTHREADS.append(worker)
            except Exception:
                pass
            try:
                worker.finished.connect(partial(_shutdown_orphan_qthread_finalize, worker))
            except Exception:
                pass
            try:
                registry_slots_cleared_total += int(self._purge_worker_from_shutdown_registries(worker))
            except Exception:
                pass
            orphan_detached += 1
            log_info(
                "shutdown_trace",
                event="shutdown_worker_orphan_detached",
                worker_type=type(worker).__name__,
            )
        log_info(
            "shutdown_trace",
            event="shutdown_workers",
            running_worker_count=len(running_workers),
            wait_ms=round((time.perf_counter() - t_wait0) * 1000.0, 2),
            still_running_after_join=int(len(still_running)),
            orphan_detached_count=int(orphan_detached),
            registry_slots_cleared_total=int(registry_slots_cleared_total),
            orphan_qthreads_held_after=int(len(_SHUTDOWN_ORPHAN_QTHREADS)),
        )

    def _drain_global_qthreadpool_for_shutdown(self) -> None:
        """Wait for Qt global pool workers; clear queued runnables so process can exit."""
        tp = QThreadPool.globalInstance()
        log_info("shutdown_trace", event="qthreadpool_drain_enter", **qt_threadpool_snapshot())
        try:
            tp.waitForDone(8000)
        except Exception:
            pass
        try:
            tp.clear()
        except Exception:
            pass
        try:
            tp.waitForDone(3000)
        except Exception:
            pass
        log_info("shutdown_trace", event="qthreadpool_drain_exit", **qt_threadpool_snapshot())

    def _shutdown_terminal_completion_gate(self, *, phase: str = "close_event") -> None:
        """Last-line shutdown: stop revivable timers, clear deferred flags, re-join orphans, drain global pool.

        Called from :meth:`closeEvent` and from ``QApplication.aboutToQuit`` so post-tick / workspace persist
        hooks cannot re-arm the event loop after the UI path has begun teardown.
        """
        ph = str(phase or "close_event")[:80]
        try:
            self._stop_all_shutdown_mutation_timers()
            wu = getattr(self, "_workspace_ui_persist_timer", None)
            if wu is not None:
                try:
                    wu.stop()
                except Exception:
                    pass
            try:
                self._stop_session_keepalive()
            except Exception:
                pass
            self._post_tick_descendant_drain_pending = False
            self._post_tick_snapshot_refresh_pending = False
            self._post_tick_inline_descendant_schedule_pending = False
            try:
                self._post_tick_descendant_deferred_reenter_depth = 0
            except Exception:
                pass
            self._destination_deferred_reconcile_burst_pending = False
            self._deferred_planning_refresh_pending = False
            self._deferred_planning_refresh_reasons = []
            self._deferred_source_projection_paths = set()
            self._graph_ids_refresh_batch_paths.clear()
            self._graph_ids_refresh_followup_due = False
            self._destination_global_reconcile_overlay_deferred = None
            self._destination_overlay_terminal_reconcile_completion_pending = False
            self._destination_reconcile_in_progress = False
        except Exception:
            pass
        log_info("shutdown_trace", event="shutdown_all_timers_stopped", phase=ph)
        try:
            orphans = list(_SHUTDOWN_ORPHAN_QTHREADS)
            for worker in orphans:
                self._shutdown_worker_safe_join(worker, timeout_ms=4000)
        except Exception:
            pass
        try:
            self._drain_global_qthreadpool_for_shutdown()
        except Exception:
            pass
        dq = getattr(self, "_destination_descendant_apply_queue", None)
        q_len = len(dq) if dq else 0
        st_active = getattr(self, "_destination_descendant_apply_state", None) is not None
        tmr_active = 0
        try:
            for name in (
                "_destination_descendant_apply_timer",
                "_deferred_planning_refresh_timer",
                "_graph_ids_refresh_batch_timer",
                "_workspace_ui_persist_timer",
                "_session_keepalive_timer",
            ):
                t = getattr(self, name, None)
                if t is not None and hasattr(t, "isActive") and t.isActive():
                    tmr_active += 1
        except Exception:
            pass
        log_info(
            "shutdown_trace",
            event="shutdown_no_active_background_state",
            phase=ph,
            descendant_queue_len=int(q_len),
            descendant_apply_state_active=bool(st_active),
            known_mutation_timers_active=int(tmr_active),
            deferred_planning_refresh_pending=bool(getattr(self, "_deferred_planning_refresh_pending", False)),
            orphan_qthreads_held=int(len(_SHUTDOWN_ORPHAN_QTHREADS)),
            **qt_threadpool_snapshot(),
        )
        log_info(
            "shutdown_trace",
            event="shutdown_all_workers_retired",
            phase=ph,
            orphan_qthreads_held=int(len(_SHUTDOWN_ORPHAN_QTHREADS)),
        )
        if ph == "aboutToQuit":
            log_info(
                "shutdown_trace",
                event="shutdown_qt_quit_requested",
                phase=ph,
                note="qt_aboutToQuit_terminal_gate_complete",
            )
        log_info(
            "shutdown_trace",
            event="shutdown_process_terminal_state_reached",
            phase=ph,
        )

    def _auto_export_draft_on_exit(self):
        if self.memory_manager is None:
            return None
        if not self.active_draft_session_id and not self.planned_moves and not self.proposed_folders:
            return None

        try:
            try:
                self._persist_workspace_snapshot_file(phase="auto_exit_export")
            except Exception as snap_exc:
                log_warn("workspace_snapshot_write_failed", phase="auto_exit_export", error=str(snap_exc))
            bundle_folder = self.memory_manager.export_bundle(reason="Auto Exit Export")
            bundle_zip = self.memory_manager.export_bundle_zip(bundle_folder)
            log_info(
                "Draft auto-export completed on exit.",
                bundle_folder=str(bundle_folder),
                bundle_zip=str(bundle_zip),
            )
            return bundle_zip
        except Exception as exc:
            log_warn("Draft auto-export failed on exit.", error=str(exc))
            return None

    def _init_memory_services(self):
        try:
            self.memory_manager = MemoryManager(
                tenant_domain=self.current_session_context.get("tenant_domain", ""),
                operator_upn=self.current_session_context.get("operator_upn", ""),
            )
            log_info(
                "Memory services initialized.",
                memory_root=str(self.memory_manager.root),
                python_primary_storage_root=str(self.memory_manager.python_primary_storage_root),
                legacy_compatibility_root=str(self.memory_manager.legacy_compatibility_root),
                memory_write_root=str(self.memory_manager.current_write_root),
                memory_scope_root=str(self.memory_manager.storage_scope_root),
                memory_scope_user=self.current_session_context.get("operator_upn", ""),
            )
            self._load_draft_shell_into_runtime()
        except Exception as exc:
            self.memory_manager = None
            self.active_draft_session_id = ""
            self._draft_shell_state = SessionState()
            self._draft_shell_raw = {}
            self._memory_restore_candidate = None
            self._memory_restore_in_progress = False
            self._memory_restore_complete = False
            self._suppress_autosave = True
            log_warn("Memory services unavailable.", error=str(exc))

    def _clear_runtime_draft_state(self, *, refresh_ui: bool = True):
        self.active_draft_session_id = ""
        self._draft_shell_state = SessionState()
        self._draft_shell_raw = {}
        self._memory_restore_candidate = None
        self._restore_payload_source = ""
        self._restore_selected_candidate_path = ""
        self.planned_moves = []
        self._plan_leaf_exclusions = set()
        self._sync_destination_plan_leaf_exclusion_paint_contract()
        self._clear_source_projection_descendants_cache(reason="runtime_draft_cleared", caller="_clear_runtime_draft_state")
        self.proposed_folders = []
        self._memory_restore_complete = False
        self._restore_destination_overlay_pending = False
        self._destination_restore_completed_once = False
        self._restored_allocation_count = 0
        self._restored_proposed_count = 0
        self._needs_review_dismissed_inherited_paths = set()
        self._reset_unresolved_proposed_queue()
        self._reset_unresolved_allocation_queue()
        self.planned_rows_by_parent_path = {}
        self._destination_pending_planned_reconcile_parent_paths = set()
        self._destination_tree_snapshot_dirty_for_persist = False
        self._source_snapshot_shell_prearmed = False
        if refresh_ui:
            self.refresh_planned_moves_table()

    def _draft_selected_source_library_id(self) -> str:
        shell = getattr(self, "_draft_shell_state", None)
        state = shell if isinstance(shell, SessionState) else SessionState()
        return str(getattr(state, "SelectedSourceLibraryId", "") or "").strip()

    def _early_hydrate_pending_session_source_snapshots_for_login(self) -> None:
        """Populate pending source snapshot list from restored draft before any loading placeholder runs."""
        if getattr(self, "memory_manager", None) is None:
            return
        try:
            ts = self._session_workspace_tree_snapshots()
        except Exception:
            return
        src = list(ts.get("source") or [])
        if not src:
            return
        pending = dict(getattr(self, "_pending_session_tree_snapshots", {}) or {})
        pending["source"] = list(src)
        self._pending_session_tree_snapshots = pending
        self._source_snapshot_shell_prearmed = True
        draft_did = self._draft_selected_source_library_id()
        if draft_did and not str((getattr(self, "pending_root_drive_ids", {}) or {}).get("source") or "").strip():
            self.pending_root_drive_ids["source"] = draft_did
        did_excerpt = ""
        for snap in src:
            if isinstance(snap, dict):
                d = snap.get("data")
                if isinstance(d, dict):
                    did_excerpt = str(d.get("drive_id") or "").strip()
                    if did_excerpt:
                        break
        log_info(
            "source_snapshot_shell_prearmed",
            phase="before_planning_loading_placeholders",
            source_snapshot_roots=len(src),
            drive_id_suffix=did_excerpt[-16:] if len(did_excerpt) > 16 else did_excerpt,
            draft_selected_library_id_suffix=draft_did[-16:] if len(draft_did) > 16 else draft_did,
        )

    def _finish_login_workspace_restore(self, *, role: str, had_login_error: bool):
        self._pending_login_restore_args = None
        self._clear_runtime_draft_state(refresh_ui=True)
        self._init_memory_services()
        if self.planned_moves or self.proposed_folders:
            self.refresh_planned_moves_table()
            self._log_restore_state_snapshot("restore_ui_bound", destination_replay_invoked=False)

        self.bottom_mode.setText(f"Mode: {role.title()}")
        self.bottom_refresh.setText("Last Refresh: SharePoint Sites Loaded")
        self._apply_restored_selector_state()
        self._log_restore_state_snapshot(
            "login_success_post_error",
            had_restored_state=self._has_restored_runtime_state(),
            login_in_progress=self._login_in_progress,
            clear_allowed=False,
            reason="post_error_success" if had_login_error else "success_without_prior_error",
        )
        self.try_restore_main_window()
        self.flash_taskbar()

    def _destination_force_live_destination_snapshot_for_session_persist(self, *, reason: str = "draft_save") -> list:
        """Capture live destination planning model and mirror into runtime session cache for JSON persist.

        Uses force-live only while :attr:`_destination_save_in_progress` or shutdown so startup restore paths
        never block the UI thread on a full model walk.
        """
        _save_or_shutdown = bool(getattr(self, "_destination_save_in_progress", False)) or bool(
            getattr(self, "_application_shutting_down", False)
        )
        if getattr(self, "_destination_startup_memory_workspace_building", False) and not _save_or_shutdown:
            log_info(
                "snapshot_capture_skipped",
                phase="force_live_preflight",
                skip_reason="startup_memory_workspace_building",
                save_in_progress=False,
            )
            log_info("startup_snapshot_capture_deferred", reason="startup_memory_tree_still_building")
            rs = getattr(self, "_runtime_session_tree_snapshots", None)
            if isinstance(rs, dict) and isinstance(rs.get("destination"), list):
                return list(rs["destination"])
            return []
        if not self._destination_force_live_snapshot_allowed():
            log_info(
                "snapshot_capture_skipped",
                phase="force_live_preflight",
                skip_reason="force_live_not_allowed_outside_save_or_shutdown",
                save_in_progress=bool(getattr(self, "_destination_save_in_progress", False)),
            )
            rs = getattr(self, "_runtime_session_tree_snapshots", None)
            if isinstance(rs, dict) and isinstance(rs.get("destination"), list):
                return list(rs["destination"])
            return []
        self._destination_session_snapshot_force_live_once = True
        self._destination_runtime_snapshot_force_refresh_during_tick = True
        try:
            fresh = list(self._capture_tree_items_snapshot("destination") or [])
            try:
                st_d = getattr(self, "_draft_shell_state", None)
                ex_f = list(st_d.DestinationTreeSnapshot or []) if isinstance(st_d, SessionState) else []
                rs_f = getattr(self, "_runtime_session_tree_snapshots", None)
                rt_f = list(rs_f.get("destination") or []) if isinstance(rs_f, dict) else []
                pr_f: list = []
                mm_f = getattr(self, "memory_manager", None)
                if mm_f is not None:
                    wso_f = mm_f.read_workspace_snapshot_optional()  # type: ignore[union-attr]  # noqa: E501
                    if isinstance(wso_f, dict):
                        pr_f = list(wso_f.get("destination_tree_snapshot") or [])
                        if not isinstance(pr_f, list):
                            pr_f = []
                h_f = self._destination_bounded_history_snapshot_source_lists()
                fresh = self._destination_enrich_persisted_destination_tree_snapshot(
                    fresh,
                    existing_session_roots=ex_f,
                    runtime_session_roots=rt_f,
                    prior_workspace_roots=pr_f,
                    history_sources=h_f,
                    phase=str(reason)[:80] or "force_live",
                )
            except Exception:
                pass
            snap_n = int(self._count_tree_snapshot_nodes(fresh))
            thin_capture_nodes = int(snap_n)
            try:
                mqual0 = self._destination_memory_snapshot_quality_metrics(fresh)
                log_info("destination_memory_snapshot_quality_metrics", context="force_live_preflight", **mqual0)
            except Exception:
                pass
            n_applied_inconsistent = int(
                self._destination_snapshot_has_applied_planned_allocations_with_empty_subtrees(fresh)
            )
            thin_risk = bool(n_applied_inconsistent) or self._destination_thin_planned_memory_over_rich_reference(
                thin_capture_nodes
            )
            block_thin, block_reason = self._destination_should_block_thin_destination_snapshot_over_rich_sidecar(
                thin_capture_nodes
            )
            if not block_thin and thin_risk:
                block_thin, block_reason = (
                    True,
                    "missing_applied_descendants_or_thin_planned" if n_applied_inconsistent else "thin_risk_overlay",
                )
            if block_thin:
                rs_try = getattr(self, "_runtime_session_tree_snapshots", None)
                rt_dest: list = (
                    list(rs_try.get("destination") or [])
                    if isinstance(rs_try, dict) and isinstance(rs_try.get("destination"), list)
                    else []
                )
                st = getattr(self, "_draft_shell_state", None)
                dr_alt: list = list(st.DestinationTreeSnapshot or []) if isinstance(st, SessionState) else []
                best = fresh
                bn = snap_n
                best_src = "live_capture"
                for cand, lbl in ((rt_dest, "runtime_session"), (dr_alt, "draft_shell")):
                    cn = int(self._count_tree_snapshot_nodes(cand))
                    if cn > bn:
                        best, bn, best_src = list(cand), cn, lbl
                if bn > thin_capture_nodes:
                    fresh = best
                    snap_n = bn
                    log_info(
                        "destination_snapshot_persist_blocked_during_startup_hydration",
                        block_reason=str(block_reason or "")[:120],
                        thin_capture_nodes=int(thin_capture_nodes),
                        rich_baseline=int(self._destination_rich_reference_snapshot_node_count_baseline()),
                        selected_nodes=int(snap_n),
                        selected_source=str(best_src)[:40],
                    )
                    log_info(
                        "destination_snapshot_persist_blocked_richer_sidecar_exists",
                        thin_capture_nodes=int(thin_capture_nodes),
                        selected_nodes=int(snap_n),
                        selected_source=str(best_src)[:40],
                    )
            rs = getattr(self, "_runtime_session_tree_snapshots", None)
            if isinstance(rs, dict):
                rs["destination"] = list(fresh)
            snap_n = int(self._count_tree_snapshot_nodes(fresh))
            try:
                mod_n = int(self._count_destination_model_non_placeholder_nodes())
            except Exception:
                mod_n = -1
            diff = int(mod_n - snap_n) if mod_n >= 0 and snap_n >= 0 else None
            log_info(
                "destination_save_live_snapshot_capture_forced",
                reason=str(reason)[:120],
                snapshot_recursive_nodes=int(snap_n),
                model_non_placeholder_nodes=int(mod_n),
                node_count_delta=diff,
            )
            log_info(
                "destination_save_using_runtime_snapshot",
                snapshot_recursive_nodes=int(snap_n),
                model_non_placeholder_nodes=int(mod_n),
                difference=diff,
            )
            if getattr(self, "_destination_startup_memory_workspace_building", False):
                log_info(
                    "snapshot_capture_partial",
                    phase="force_live_preflight",
                    note="captured_during_startup_workspace_building_save_allowed",
                    snapshot_recursive_nodes=int(snap_n),
                    model_non_placeholder_nodes=int(mod_n),
                )
            return fresh
        finally:
            self._destination_session_snapshot_force_live_once = False
            self._destination_runtime_snapshot_force_refresh_during_tick = False

    def _planning_memory_nonempty(self) -> bool:
        return bool(getattr(self, "planned_moves", None) or getattr(self, "proposed_folders", None))

    def _count_planned_workspace_rows_in_destination_snapshot_roots(self, roots: list) -> int:
        """Recursive count of planned-workspace rows in persisted snapshot JSON (for save validation)."""

        def walk(snap: dict) -> int:
            if not isinstance(snap, dict):
                return 0
            n = 0
            data = snap.get("data")
            if isinstance(data, dict) and destination_payload_is_planned_workspace_row(data):
                n += 1
            for ch in list(snap.get("children") or []):
                if isinstance(ch, dict):
                    n += walk(ch)
            return n

        total = 0
        for root in roots or []:
            if isinstance(root, dict):
                total += walk(root)
        return int(total)

    def _count_planned_and_proposed_rows_in_destination_model(self) -> tuple[int, int]:
        """Return (planned_workspace_row_count, proposed_row_count) in the live destination planning model."""
        planned_n = 0
        proposed_n = 0
        dm = getattr(self, "destination_planning_model", None)
        if dm is None:
            return 0, 0
        try:
            for ix in dm.iter_depth_first():
                pl = ix.data(Qt.UserRole) or {}
                if not isinstance(pl, dict) or pl.get("placeholder"):
                    continue
                if destination_payload_is_planned_workspace_row(pl):
                    planned_n += 1
                if self.is_proposed_destination_node(pl):
                    proposed_n += 1
        except Exception:
            return 0, 0
        return int(planned_n), int(proposed_n)

    def _log_destination_snapshot_persist_validation(self, state: SessionState, *, phase: str = "draft_save") -> None:
        """Compare session destination snapshot to live model; log mismatches (persistence contract)."""
        try:
            roots = list(getattr(state, "DestinationTreeSnapshot", []) or [])
            snap_n = int(self._count_tree_snapshot_nodes(roots))
            snap_planned = int(self._count_planned_workspace_rows_in_destination_snapshot_roots(roots))
            mod_n = int(self._count_destination_model_non_placeholder_nodes())
            mod_planned, mod_prop = self._count_planned_and_proposed_rows_in_destination_model()
            pm = len(getattr(self, "planned_moves", None) or [])
            pf = len(getattr(self, "proposed_folders", None) or [])
            log_info(
                "snapshot_persist_validation",
                phase=str(phase)[:120],
                session_destination_snapshot_recursive_nodes=int(snap_n),
                live_model_non_placeholder_nodes=int(mod_n),
                snapshot_planned_workspace_rows=int(snap_planned),
                live_model_planned_workspace_rows=int(mod_planned),
                live_model_proposed_rows_visible=int(mod_prop),
                planned_moves_list_count=int(pm),
                proposed_folders_list_count=int(pf),
            )
            if (pm > 0 or pf > 0) and snap_n <= 0 and not roots:
                log_info(
                    "snapshot_planning_mismatch_detected",
                    phase=str(phase)[:120],
                    mismatch_reason="planning_lists_nonempty_but_destination_snapshot_empty",
                    planned_moves_list_count=int(pm),
                    proposed_folders_list_count=int(pf),
                )
            elif mod_n >= 0 and snap_n >= 0 and mod_n != snap_n:
                log_info(
                    "snapshot_planning_mismatch_detected",
                    phase=str(phase)[:120],
                    mismatch_reason="non_placeholder_count_differs_from_snapshot_recursive_count",
                    live_model_non_placeholder_nodes=int(mod_n),
                    session_destination_snapshot_recursive_nodes=int(snap_n),
                )
            if snap_planned >= 0 and mod_planned >= 0 and snap_planned != mod_planned:
                log_info(
                    "snapshot_planning_mismatch_detected",
                    phase=str(phase)[:120],
                    mismatch_reason="planned_workspace_row_count_snapshot_vs_model",
                    snapshot_planned_workspace_rows=int(snap_planned),
                    live_model_planned_workspace_rows=int(mod_planned),
                )
            n_empty_applied = int(
                self._destination_snapshot_has_applied_planned_allocations_with_empty_subtrees(roots, log_event=False)
            )
            if n_empty_applied <= 0:
                log_info(
                    "destination_snapshot_persist_allowed_planned_memory_safe",
                    phase=str(phase)[:120],
                    session_destination_snapshot_recursive_nodes=int(snap_n),
                )
        except Exception as exc:
            self._log_restore_exception("destination_snapshot_persist_validation", exc)

    def _build_current_draft_shell_state(self, *, include_workspace_ui: bool = False, save_reason: str = ""):
        state = SessionState()
        existing_state = self._draft_shell_state if isinstance(self._draft_shell_state, SessionState) else SessionState()
        workspace_ui_state = self._capture_workspace_tree_state() if include_workspace_ui and hasattr(self, "source_tree_widget") else {
            "source_expanded_paths": set(),
            "destination_expanded_paths": set(),
            "source_selected_path": "",
            "destination_selected_path": "",
        }
        _dest_persist = getattr(self, "_destination_draft_save_destination_snapshot_override", None)
        workspace_tree_snapshots = (
            {
                "source": self._capture_tree_items_snapshot("source"),
                "destination": (
                    list(_dest_persist)
                    if _dest_persist is not None
                    else self._capture_tree_items_snapshot("destination")
                ),
            }
            if include_workspace_ui and hasattr(self, "source_tree_widget")
            else {
                "source": list(getattr(existing_state, "SourceTreeSnapshot", []) or []),
                "destination": (
                    list(_dest_persist)
                    if _dest_persist is not None
                    else list(getattr(existing_state, "DestinationTreeSnapshot", []) or [])
                ),
            }
        )
        _need_dest_refresh = bool(
            _dest_persist is None
            and (not include_workspace_ui)
            and hasattr(self, "source_tree_widget")
            and (
                getattr(self, "_destination_tree_snapshot_dirty_for_persist", False)
                or self._planning_memory_nonempty()
            )
        )
        if _need_dest_refresh:
            if getattr(self, "_destination_startup_memory_workspace_building", False):
                log_info(
                    "snapshot_capture_partial",
                    phase="draft_shell_partial_refresh",
                    reason="startup_memory_tree_still_building",
                    planning_lists_nonempty=bool(self._planning_memory_nonempty()),
                )
                log_info(
                    "startup_snapshot_capture_deferred",
                    reason="startup_memory_tree_still_building",
                    context="draft_shell_partial_refresh",
                )
            elif getattr(self, "_destination_descendant_apply_tick_running", False):
                log_info(
                    "snapshot_capture_partial",
                    phase="draft_shell_partial_refresh",
                    reason="destination_descendant_tick_running",
                    planning_lists_nonempty=bool(self._planning_memory_nonempty()),
                )
                log_info(
                    "destination_snapshot_saved_from_stale_cache",
                    context="draft_shell_partial_refresh_deferred_tick",
                    reason="destination_tick_running",
                )
            else:
                workspace_tree_snapshots = dict(workspace_tree_snapshots)
                cap_dest = list(self._capture_tree_items_snapshot("destination") or [])
                try:
                    ex_s0 = list(getattr(existing_state, "DestinationTreeSnapshot", []) or [])
                    rt0 = getattr(self, "_runtime_session_tree_snapshots", None)
                    rt_d0 = list(rt0.get("destination") or []) if isinstance(rt0, dict) else []
                    pr_w0: list = []
                    mm_d = getattr(self, "memory_manager", None)
                    if mm_d is not None:
                        wso_d = mm_d.read_workspace_snapshot_optional()  # type: ignore[union-attr]  # noqa: E501
                        if isinstance(wso_d, dict):
                            pr_w0 = list(wso_d.get("destination_tree_snapshot") or [])
                            if not isinstance(pr_w0, list):
                                pr_w0 = []
                    hsrc0 = self._destination_bounded_history_snapshot_source_lists()
                    cap_dest = self._destination_enrich_persisted_destination_tree_snapshot(
                        cap_dest,
                        existing_session_roots=ex_s0,
                        runtime_session_roots=rt_d0,
                        prior_workspace_roots=pr_w0,
                        history_sources=hsrc0,
                        phase="draft_shell_partial_refresh",
                    )
                except Exception:
                    pass
                cap_n = int(self._count_tree_snapshot_nodes(cap_dest))
                n_incons2 = int(
                    self._destination_snapshot_has_applied_planned_allocations_with_empty_subtrees(
                        cap_dest, log_event=False
                    )
                )
                thin2 = n_incons2 > 0 or self._destination_thin_planned_memory_over_rich_reference(int(cap_n))
                block_thin, block_reason = self._destination_should_block_thin_destination_snapshot_over_rich_sidecar(
                    cap_n
                )
                if not block_thin and thin2:
                    block_thin, block_reason = (
                        True,
                        "missing_applied_descendants_or_thin_planned" if n_incons2 else "thin_risk_overlay",
                    )
                if block_thin:
                    ex_dest = list(getattr(existing_state, "DestinationTreeSnapshot", []) or [])
                    rt = getattr(self, "_runtime_session_tree_snapshots", None)
                    rt_dest = list(rt.get("destination") or []) if isinstance(rt, dict) else []
                    best: list = cap_dest
                    bn = cap_n
                    best_src = "live_capture"
                    for cand, lbl in ((ex_dest, "existing_draft_shell"), (rt_dest, "runtime_session")):
                        cn = int(self._count_tree_snapshot_nodes(cand))
                        if cn > bn:
                            best, bn, best_src = list(cand), cn, lbl
                    if bn > cap_n:
                        workspace_tree_snapshots["destination"] = best
                        log_info(
                            "destination_snapshot_persist_blocked_during_startup_hydration",
                            block_reason=str(block_reason or "")[:120],
                            phase="draft_shell_partial_refresh",
                            thin_capture_nodes=int(cap_n),
                            rich_baseline=int(self._destination_rich_reference_snapshot_node_count_baseline()),
                            selected_nodes=int(bn),
                            selected_source=str(best_src)[:40],
                        )
                        log_info(
                            "destination_snapshot_persist_blocked_richer_sidecar_exists",
                            phase="draft_shell_partial_refresh",
                            thin_capture_nodes=int(cap_n),
                            selected_nodes=int(bn),
                            selected_source=str(best_src)[:40],
                        )
                    else:
                        workspace_tree_snapshots["destination"] = cap_dest
                else:
                    workspace_tree_snapshots["destination"] = cap_dest
                log_info(
                    "destination_snapshot_refreshed_from_live_model",
                    trigger="draft_shell_partial_refresh_include_workspace_ui_false",
                    top_level_nodes=len(workspace_tree_snapshots["destination"]),
                    planning_lists_nonempty=bool(self._planning_memory_nonempty()),
                    dirty_flag=bool(getattr(self, "_destination_tree_snapshot_dirty_for_persist", False)),
                )
                self._destination_tree_snapshot_dirty_for_persist = False

        source_site_selector = self.planning_inputs.get("Source Site") if hasattr(self, "planning_inputs") else None
        source_library_selector = self.planning_inputs.get("Source Library") if hasattr(self, "planning_inputs") else None
        destination_site_selector = self.planning_inputs.get("Destination Site") if hasattr(self, "planning_inputs") else None
        destination_library_selector = self.planning_inputs.get("Destination Library") if hasattr(self, "planning_inputs") else None

        source_site = source_site_selector.currentData() if source_site_selector is not None else None
        destination_site = destination_site_selector.currentData() if destination_site_selector is not None else None
        destination_library = destination_library_selector.currentData() if destination_library_selector is not None else None

        sk_src = ""
        if isinstance(source_site, dict):
            sk_src = str(source_site.get("site_key") or source_site.get("web_url") or source_site.get("id", "") or "").strip()
        sk_dst = ""
        if isinstance(destination_site, dict):
            sk_dst = str(
                destination_site.get("site_key") or destination_site.get("web_url") or destination_site.get("id", "") or ""
            ).strip()

        cap_sn, cap_si = self._extract_sharepoint_planning_library_fields_for_save("source", source_library_selector)
        cap_dn, cap_di = self._extract_sharepoint_planning_library_fields_for_save("destination", destination_library_selector)

        def _sf(x: str) -> str:
            t = str(x or "").strip()
            return t[-24:] if len(t) > 24 else t

        log_info(
            "draft_shell_selector_state_before_save",
            include_workspace_ui=bool(include_workspace_ui),
            save_reason=str(save_reason or "")[:240],
            existing_source_library_id_suffix=_sf(getattr(existing_state, "SelectedSourceLibraryId", "") or ""),
            existing_source_library_name=str(getattr(existing_state, "SelectedSourceLibrary", "") or "")[:160],
            captured_source_library_id_suffix=_sf(cap_si),
            captured_source_library_name=str(cap_sn or "")[:160],
            existing_destination_library_id_suffix=_sf(getattr(existing_state, "SelectedDestinationLibraryId", "") or ""),
            existing_destination_library_name=str(getattr(existing_state, "SelectedDestinationLibrary", "") or "")[:160],
            captured_destination_library_id_suffix=_sf(cap_di),
            captured_destination_library_name=str(cap_dn or "")[:160],
        )

        src_lib_name, src_lib_id = self._merge_persisted_library_fields_for_draft_shell(
            group="source",
            existing=existing_state,
            site_key_new=sk_src,
            library_selector=source_library_selector,
            name_new=cap_sn,
            id_new=cap_si,
        )
        dst_lib_name, dst_lib_id = self._merge_persisted_library_fields_for_draft_shell(
            group="destination",
            existing=existing_state,
            site_key_new=sk_dst,
            library_selector=destination_library_selector,
            name_new=cap_dn,
            id_new=cap_di,
        )

        state.DraftId = self.active_draft_session_id or existing_state.DraftId
        state.DraftName = existing_state.DraftName or state.DraftId
        state.IsActiveDraft = True
        state.CreatedUtc = existing_state.CreatedUtc or datetime.utcnow().isoformat()
        state.LastWorkspace = "Planning Workspace" if hasattr(self, "app_subtitle") else (existing_state.LastWorkspace or "Planning Workspace")
        state.LastSavedUtc = datetime.utcnow().isoformat()
        state.EnvironmentMode = existing_state.EnvironmentMode or self.current_session_context.get("user_role", "Client").title()
        state.SelectedSourceSite = source_site.get("name", "") if isinstance(source_site, dict) else ""
        state.SelectedSourceSiteKey = sk_src
        state.SelectedSourceLibrary = src_lib_name
        state.SelectedSourceLibraryId = src_lib_id
        state.SelectedDestinationSite = destination_site.get("name", "") if isinstance(destination_site, dict) else ""
        state.SelectedDestinationSiteKey = sk_dst
        state.SelectedDestinationLibrary = dst_lib_name
        state.SelectedDestinationLibraryId = dst_lib_id
        state.SourceBrowseMode = self._planning_browse_mode("source")
        state.DestinationBrowseMode = self._planning_browse_mode("destination")
        operator_upn = self.current_session_context.get("operator_upn", "")
        tenant_domain = self.current_session_context.get("tenant_domain", "")
        state.SessionFingerprint = existing_state.SessionFingerprint or f"{operator_upn}|{tenant_domain}".strip("|")
        merged_dst_lib: dict[str, Any] = {}
        if str(state.SelectedDestinationLibraryId or "").strip() or str(state.SelectedDestinationLibrary or "").strip():
            merged_dst_lib = {"id": state.SelectedDestinationLibraryId, "name": state.SelectedDestinationLibrary}
        elif isinstance(destination_library, dict) and str(destination_library.get("id") or "").strip():
            merged_dst_lib = destination_library
        if include_workspace_ui:
            state.SourceExpandedAll = self._panel_is_expanded_all("source")
            state.DestinationExpandedAll = self._panel_is_expanded_all("destination")
            state.PlanningHeaderCollapsed = bool(getattr(self, "_planning_header_collapsed", False))
            state.WorkspacePanelCollapsed = bool(getattr(self, "_workspace_tabs_collapsed", False))
            state.SourceExpandedPaths = [] if state.SourceExpandedAll else sorted(workspace_ui_state.get("source_expanded_paths", set()))
            state.DestinationExpandedPaths = [] if state.DestinationExpandedAll else sorted(workspace_ui_state.get("destination_expanded_paths", set()))
            state.SourceSelectedPath = str(workspace_ui_state.get("source_selected_path", "") or "")
            state.DestinationSelectedPath = str(workspace_ui_state.get("destination_selected_path", "") or "")
            state.SourceTreeSnapshot = list(workspace_tree_snapshots.get("source", []) or [])
            state.DestinationTreeSnapshot = list(workspace_tree_snapshots.get("destination", []) or [])
            self._apply_destination_tree_snapshot_identity_fields(state, merged_dst_lib, destination_site)
        else:
            state.SourceExpandedAll = bool(getattr(existing_state, "SourceExpandedAll", False))
            state.DestinationExpandedAll = bool(getattr(existing_state, "DestinationExpandedAll", False))
            state.PlanningHeaderCollapsed = bool(getattr(existing_state, "PlanningHeaderCollapsed", False))
            state.WorkspacePanelCollapsed = bool(getattr(existing_state, "WorkspacePanelCollapsed", False))
            state.SourceExpandedPaths = list(getattr(existing_state, "SourceExpandedPaths", []) or [])
            state.DestinationExpandedPaths = list(getattr(existing_state, "DestinationExpandedPaths", []) or [])
            state.SourceSelectedPath = str(getattr(existing_state, "SourceSelectedPath", "") or "")
            state.DestinationSelectedPath = str(getattr(existing_state, "DestinationSelectedPath", "") or "")
            state.SourceTreeSnapshot = list(workspace_tree_snapshots.get("source", []) or [])
            state.DestinationTreeSnapshot = list(workspace_tree_snapshots.get("destination", []) or [])
            self._apply_destination_tree_snapshot_identity_fields(state, merged_dst_lib, destination_site)
        if not state.DraftName:
            operator_display = self.current_session_context.get("operator_display_name", "") or "Planning Session"
            state.DraftName = f"{operator_display} Draft"
        state.PlanLeafExclusions = sorted(getattr(self, "_plan_leaf_exclusions", set()) or [])
        state.NeedsReviewDismissedInheritedSourcePaths = sorted(
            getattr(self, "_needs_review_dismissed_inherited_paths", set()) or set()
        )
        if getattr(self, "_destination_draft_save_destination_snapshot_override", None) is not None:
            self._destination_tree_snapshot_dirty_for_persist = False
        elif include_workspace_ui and hasattr(self, "source_tree_widget") and not getattr(
            self, "_destination_descendant_apply_tick_running", False
        ):
            self._destination_tree_snapshot_dirty_for_persist = False
        self._log_draft_shell_selector_fields(
            "draft_shell_selector_state_written",
            state=state,
            include_workspace_ui=bool(include_workspace_ui),
            save_reason=str(save_reason or "")[:240],
        )
        return state

    def _create_new_draft_session_id(self):
        operator_upn = str(self.current_session_context.get("operator_upn", "") or "").strip()
        operator_token = operator_upn.split("@", 1)[0] if operator_upn else "SESSION"
        operator_token = re.sub(r"[^A-Za-z0-9]+", "", operator_token).upper() or "SESSION"
        timestamp = datetime.utcnow().strftime("%Y%m%d-%H%M%S-%f")[:-3]
        return f"DRAFT-{timestamp}-{operator_token}"

    def _ensure_active_draft_session(self):
        if self.active_draft_session_id:
            return True

        if isinstance(self._draft_shell_state, SessionState) and self._draft_shell_state.DraftId:
            self.active_draft_session_id = self._draft_shell_state.DraftId
            return True

        self.active_draft_session_id = self._create_new_draft_session_id()
        if not isinstance(self._draft_shell_state, SessionState):
            self._draft_shell_state = SessionState()
        self._draft_shell_state.DraftId = self.active_draft_session_id
        if not self._draft_shell_state.CreatedUtc:
            self._draft_shell_state.CreatedUtc = datetime.utcnow().isoformat()
        if not self._draft_shell_state.DraftName:
            operator_display = self.current_session_context.get("operator_display_name", "") or "Planning Session"
            self._draft_shell_state.DraftName = f"{operator_display} Draft"
        self._draft_shell_raw = self._draft_shell_state.to_dict()
        log_info(
            "Active draft session created for empty runtime state.",
            draft_id=self.active_draft_session_id,
            restore_complete=self._memory_restore_complete,
            planned_moves_count=len(self.planned_moves),
            proposed_folders_count=len(self.proposed_folders),
        )
        return True

    def _maybe_show_restore_backup_banner(self, selected: dict):
        if not isinstance(selected, dict):
            return
        name = str(selected.get("name", "") or "").lower()
        if "backup" not in name:
            return
        path_hint = str(selected.get("session_path", "") or "")
        msg = (
            "Session restored from a backup file (live session was empty or older). "
            f"Path: {path_hint}"
        )
        log_info("restore_from_backup_notice", candidate=selected.get("name", ""), session_path=path_hint)
        status = self.statusBar()
        if status is not None:
            status.showMessage(msg, 45000)

    def _log_restore_phase(self, phase, *, verbose=False, **data):
        """
        Restore paths can iterate thousands of nodes; avoid per-item INFO logs by default.
        Set OZLINK_RESTORE_VERBOSE_LOG=1 to log verbose_only phases (per file/branch, etc.).
        """
        if verbose:
            flag = os.environ.get("OZLINK_RESTORE_VERBOSE_LOG", "").strip().lower()
            if flag not in ("1", "true", "yes"):
                return
        restore_busy_for_log = bool(self._memory_restore_in_progress) and not bool(
            getattr(self, "_memory_restore_background_trees", False)
        )
        data.setdefault("restore_in_progress", restore_busy_for_log)
        data.setdefault("selector_suppressed", self._suppress_selector_change_handlers)
        data.setdefault("window_visible", self.isVisible())
        log_info(f"Memory restore {phase}.", **data)

    def _log_restore_state_snapshot(self, phase, *, selected_candidate_path="", destination_replay_invoked=False, **extra):
        payload_source = self._restore_payload_source or "unknown"
        candidate_path = selected_candidate_path or self._restore_selected_candidate_path
        data = {
            "planned_moves_count": len(self.planned_moves),
            "proposed_folders_count": len(self.proposed_folders),
            "selected_candidate_path": candidate_path,
            "source_of_payload": payload_source,
            "destination_replay_invoked": destination_replay_invoked,
        }
        data.update(extra)
        self._log_restore_phase(phase, **data)

    def _destination_root_bind_is_authoritative(self):
        if not hasattr(self, "destination_tree_widget"):
            return False
        if self._planning_tree_top_level_count(getattr(self, "destination_tree_widget", None)) == 0:
            return False
        loaded_signature = self.loaded_root_request_signatures.get("destination")
        active_signature = self.active_root_request_signatures.get("destination")
        if loaded_signature and active_signature:
            return loaded_signature == active_signature
        return bool(loaded_signature)

    def _destination_parent_has_future_state_children_model(self, parent_ix: QModelIndex) -> bool:
        model = getattr(self, "destination_planning_model", None)
        if model is None or not parent_ix.isValid():
            return False
        for r in range(model.rowCount(parent_ix)):
            pl = model.index(r, 0, parent_ix).data(Qt.UserRole) or {}
            if self._destination_is_future_state_node(pl):
                return True
        return False

    def _destination_visible_subtree_merge_priority(self, semantic_path: str, expanded_paths, selected_path: str) -> int:
        sp = self.normalize_memory_path(str(semantic_path or "").strip()).casefold()
        if not sp:
            return 0
        best = 0
        paths = expanded_paths or set()
        for ep in paths:
            e = self.normalize_memory_path(str(ep).strip()).casefold()
            if not e:
                continue
            if sp == e or sp.startswith(e + "\\"):
                best = max(best, len(e))
            if e.startswith(sp + "\\"):
                best = max(best, len(sp))
        sel = self.normalize_memory_path(str(selected_path or "").strip()).casefold()
        if sel:
            if sp == sel or sp.startswith(sel + "\\"):
                best = max(best, len(sel))
            if sel.startswith(sp + "\\"):
                best = max(best, len(sp))
        return best

    def _destination_replay_parent_path_priority_score(self, parent_path: str, trigger_path: str) -> int:
        pp = self.normalize_memory_path(str(parent_path or "").strip()).casefold()
        if not pp:
            return 0
        best = 0
        tp = self.normalize_memory_path(str(trigger_path or "").strip()).casefold()
        if tp:
            if pp == tp or pp.startswith(tp + "\\"):
                best = max(best, len(tp) + 2000)
            if tp == pp or tp.startswith(pp + "\\"):
                best = max(best, len(pp) + 1000)
        try:
            ui = self._capture_workspace_tree_state()
            for ep in ui.get("destination_expanded_paths") or set():
                e = self.normalize_memory_path(str(ep).strip()).casefold()
                if not e:
                    continue
                if pp == e or pp.startswith(e + "\\"):
                    best = max(best, len(e))
                if e == pp or e.startswith(pp + "\\"):
                    best = max(best, len(pp))
            sp = self.normalize_memory_path(str(ui.get("destination_selected_path") or "").strip()).casefold()
            if sp:
                if pp == sp or pp.startswith(sp + "\\"):
                    best = max(best, len(sp))
                if sp == pp or sp.startswith(pp + "\\"):
                    best = max(best, len(pp))
        except Exception:
            pass
        return best

    def _destination_restore_replay_reason_uses_worker_budget(self, reason: object) -> bool:
        """Use folder-worker replay slice/parent budget for heavy full-materialize paths."""
        r = str(reason or "").strip()
        if r in {"folder_worker_success", "folder_load"}:
            return True
        if "startup_memory_minimal_replay" in r:
            return True
        return r.startswith("deferred_graph_ids_resolved")

    def _destination_projection_survival_context_after_root_bind(self) -> dict[str, Any]:
        """Visible future-state may lag async replay; include unresolved overlay queues in survival."""
        visible_fs = self._count_visible_destination_future_state_nodes()
        unresolved = self._unresolved_proposed_queue_size() + self._unresolved_allocation_queue_size()
        overlay_pending = bool(getattr(self, "_restore_destination_overlay_pending", False))
        survived_logical = visible_fs > 0 or overlay_pending or unresolved > 0
        return {
            "future_state_count": visible_fs,
            "unresolved_overlay_entries": unresolved,
            "restore_destination_overlay_pending": overlay_pending,
            "survived_logical": survived_logical,
        }

    def _has_restored_runtime_state(self):
        return bool(self.planned_moves or self.proposed_folders or self._memory_restore_candidate or self._memory_restore_complete)

    def _restore_abort_active(self) -> bool:
        return bool(getattr(self, "_restore_abort_mode", False))

    def _enter_restore_abort_mode(self, reason: str, *, phase: str = "") -> None:
        if self._restore_abort_active():
            return
        self._restore_abort_mode = True
        self._restore_abort_reason = str(reason or "restore_error")
        self._restore_destination_overlay_pending = False
        self._restore_finalization_deferred_active = False
        self._restore_finalization_deferred_reason = ""
        self._destination_restore_materialization_queue = []
        self._destination_restore_materialization_seen = set()
        self._source_restore_materialization_queue = []
        self._source_restore_materialization_seen = set()
        self._source_projection_refresh_paths = set()
        self._deferred_planning_refresh_pending = False
        self._deferred_planning_refresh_reasons = []
        self._deferred_source_projection_paths = set()
        self._destination_idle_materialize_reentrancy_block = 0
        self._destination_restore_completed_once = False
        self._memory_restore_in_progress = False
        self._memory_restore_background_trees = False
        self._full_count_pending_drive_id_after_restore = ""
        loaded_items = (
            self.count_tree_items(self.source_tree_widget) if hasattr(self, "source_tree_widget") else 0
        )
        self._update_source_count_labels(loaded_items)
        # Keep autosave suppressed so partially-restored state cannot overwrite disk snapshot.
        self._suppress_autosave = True
        self._log_restore_phase(
            "restore_abort_mode_entered",
            reason=self._restore_abort_reason,
            source_phase=phase,
        )

    def _log_restore_exception(self, phase, exc):
        log_error(
            "Memory restore step failed.",
            phase=phase,
            error=str(exc),
            traceback=traceback.format_exc(),
        )
        if (
            (getattr(self, "_memory_restore_in_progress", False) or getattr(self, "_memory_restore_background_trees", False))
            and not self._restore_abort_active()
        ):
            self._enter_restore_abort_mode(str(exc), phase=str(phase))

    def _projection_diag_verbose_enabled(self):
        flag = os.environ.get("OZLINK_PROJECTION_DIAG_LOG", "").strip().lower()
        return flag in ("1", "true", "yes")

    def _full_trace_enabled(self):
        """Set OZLINK_FULL_TRACE=1 for exhaustive tree/projection/worker decision logs."""
        flag = os.environ.get("OZLINK_FULL_TRACE", "").strip().lower()
        return flag in ("1", "true", "yes")

    def _destination_placement_bind_log_enabled(self) -> bool:
        """Set OZLINK_DEST_PLACEMENT_BIND_LOG=1 to log every planned-segment bind (verbose)."""
        flag = os.environ.get("OZLINK_DEST_PLACEMENT_BIND_LOG", "").strip().lower()
        return flag in ("1", "true", "yes")

    def _destination_placement_audit_enabled(self) -> bool:
        """Set OZLINK_DEST_PLACEMENT_AUDIT=1 for post-overlay intended-vs-visible path audit."""
        flag = os.environ.get("OZLINK_DEST_PLACEMENT_AUDIT", "").strip().lower()
        return flag in ("1", "true", "yes")

    def _destination_bind_trace_enabled(self) -> bool:
        return dest_forensic.bind_trace_enabled()

    def _destination_reconcile_trace_enabled(self) -> bool:
        return dest_forensic.reconcile_trace_enabled()

    def _destination_empty_trace_enabled(self) -> bool:
        return dest_forensic.empty_trace_enabled()

    def _destination_forensic_terminal_empty_context(
        self, parent_ix: QModelIndex, *, graph_payload_child_count: int, phase: str
    ) -> None:
        if not self._destination_empty_trace_enabled():
            return
        if not destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            return
        model = getattr(self, "destination_planning_model", None)
        if model is None or not parent_ix.isValid():
            return
        col0 = parent_ix.siblingAtColumn(0) if parent_ix.column() != 0 else parent_ix
        pd = self._destination_model_index_user_role_dict(col0)
        folder_canon = (
            self._canonical_destination_projection_path(self._tree_item_path(pd) or "") or ""
        ).strip()
        sem = self._destination_semantic_path(pd) or folder_canon
        rc = int(model.rowCount(col0))
        terminal_empty_visible = False
        if rc == 1:
            only = self._destination_model_index_user_role_dict(model.index(0, 0, col0))
            terminal_empty_visible = bool(only.get("placeholder")) and str(
                only.get("placeholder_role") or ""
            ) == "terminal_empty"
        planned_expect = self._destination_folder_expects_planned_workspace_underneath(sem)
        unresolved_under = 0
        prop_under = 0
        fc_l = folder_canon.casefold()
        sem_l = str(sem or "").casefold()
        for bucket in (getattr(self, "unresolved_proposed_by_parent_path", None) or {}).values():
            for pf in (bucket or {}).values():
                pp = self._proposed_parent_path(pf)
                if not pp:
                    continue
                c = self._canonical_destination_projection_path(pp) or self.normalize_memory_path(pp)
                cl = c.casefold()
                if cl == fc_l or cl == sem_l or cl.startswith(fc_l + "\\") or cl.startswith(sem_l + "\\"):
                    prop_under += 1
        for bucket in (getattr(self, "unresolved_allocations_by_parent_path", None) or {}).values():
            for mv in (bucket or {}).values():
                ap = self._allocation_parent_path(mv)
                if not ap:
                    continue
                c = self._canonical_destination_projection_path(ap) or self.normalize_memory_path(ap)
                cl = c.casefold()
                if cl == fc_l or cl == sem_l or cl.startswith(fc_l + "\\") or cl.startswith(sem_l + "\\"):
                    unresolved_under += 1
        dest_overlay_targets = 0
        for t in self._destination_collect_unresolved_overlay_target_canonical_paths():
            tl = t.casefold()
            if tl == fc_l or tl.startswith(fc_l + "\\"):
                dest_overlay_targets += 1
        dest_forensic.log_empty(
            phase=str(phase or "")[:120],
            folder_canonical_path=str(folder_canon)[:400],
            folder_semantic_path_excerpt=str(sem)[:400],
            graph_child_count_returned=int(graph_payload_child_count),
            model_child_row_count=int(rc),
            planned_descendants_expected_under_folder=bool(planned_expect),
            unresolved_allocation_queue_rows_under_folder=int(unresolved_under),
            proposed_planned_target_descendants_under_folder=int(prop_under),
            unresolved_overlay_canonical_targets_under_or_at_folder=int(dest_overlay_targets),
            terminal_empty_placeholder_visible=bool(terminal_empty_visible),
            empty_placeholder_suppressed=bool(planned_expect and rc == 0),
            suppression_note=(
                "strip_terminal_empty_removed_placeholder"
                if planned_expect and rc == 0
                else (
                    "terminal_empty_still_visible"
                    if terminal_empty_visible
                    else "not_terminal_empty_or_multiple_children"
                )
            ),
        )

    def _destination_forensic_strip_terminal_empty_decision(
        self, *, folder_semantic_path: str, decision: str, detail: str
    ) -> None:
        if not self._destination_empty_trace_enabled():
            return
        dest_forensic.log_empty(
            phase="strip_terminal_empty_when_planned_descendants_expected",
            folder_semantic_path_excerpt=str(folder_semantic_path or "")[:400],
            strip_decision=str(decision)[:80],
            strip_detail=str(detail)[:400],
        )

    def _tree_item_ui_snapshot(self, panel_key, item):
        """Compact row state for tracing (source or destination trees)."""
        if item is None:
            return {"panel": panel_key, "item_alive": False}
        node_data = item.data(0, Qt.UserRole) or {}
        path = self._tree_item_path(node_data)
        placeholders = []
        for index in range(item.childCount()):
            ch = item.child(index)
            cd = ch.data(0, Qt.UserRole) or {}
            if cd.get("placeholder"):
                placeholders.append(str(cd.get("placeholder_role", "") or "unknown"))
        policy = item.childIndicatorPolicy()
        snap = {
            "panel": panel_key,
            "path": path,
            "is_expanded": bool(item.isExpanded()),
            "child_count": item.childCount(),
            "placeholder_roles": placeholders,
            "child_indicator_show": policy == QTreeWidgetItem.ShowIndicator,
            "children_loaded": bool(node_data.get("children_loaded")),
            "load_failed": bool(node_data.get("load_failed")),
            "is_folder": bool(node_data.get("is_folder")),
            "row_is_placeholder": bool(node_data.get("placeholder")),
            "label_excerpt": (item.text(0) or "")[:160],
        }
        if panel_key == "destination":
            snap["is_planned_allocation"] = bool(self.node_is_planned_allocation(node_data))
            snap["planned_allocation_descendant"] = bool(node_data.get("planned_allocation_descendant"))
            snap["projection_unresolved_terminal"] = bool(node_data.get("projection_unresolved_terminal"))
            snap["node_origin"] = str(node_data.get("node_origin", ""))[:120]
        elif panel_key == "source":
            snap["source_relationship_mode"] = str(node_data.get("source_relationship_mode", ""))[:40]
        return snap

    def _ui_trace(self, category, action, *, panel_key=None, item=None, **extra):
        if not self._full_trace_enabled():
            return
        payload = dict(extra)
        if panel_key is not None and item is not None:
            payload.update(self._tree_item_ui_snapshot(panel_key, item))
        elif item is not None:
            payload.update(self._tree_item_ui_snapshot("unknown", item))
        log_trace(category, action, **payload)

    def _destination_projection_diag_payload(self, source_root_data, move, source_item):
        """Structured fields for projection troubleshooting (no tokens)."""
        move = move or {}
        path_from_move = self._canonical_source_projection_path(move.get("source_path", ""))
        path_from_root = self._canonical_source_projection_path(self._tree_item_path(source_root_data))
        drive_id = source_root_data.get("drive_id", "") or ""
        item_id = source_root_data.get("id", "") or ""
        payload = {
            "canonical_source_path_from_move": path_from_move,
            "canonical_source_path_from_root_data": path_from_root,
            "drive_id_present": bool(drive_id),
            "item_id_present": bool(item_id),
            "site_id_present": bool(source_root_data.get("site_id")),
            "source_is_folder": bool(source_root_data.get("is_folder", True)),
            "source_item_found_in_tree": source_item is not None,
            "drive_id_suffix": drive_id[-16:] if len(drive_id) > 16 else drive_id,
            "item_id_suffix": item_id[-16:] if len(item_id) > 16 else item_id,
        }
        if source_item is not None:
            sid = self._source_tree_row_payload(source_item)
            payload["source_root_children_loaded"] = bool(sid.get("children_loaded"))
            payload["source_root_child_count"] = self._source_tree_row_child_count(source_item)
            payload["source_subtree_fully_loaded"] = self._source_subtree_fully_loaded_in_tree(source_item)
        else:
            payload["source_root_children_loaded"] = None
            payload["source_root_child_count"] = None
            payload["source_subtree_fully_loaded"] = False
        if self._projection_diag_verbose_enabled():
            src = move.get("source") or {}
            payload["move_source_path_raw"] = move.get("source_path", "")
            payload["root_item_path_raw"] = source_root_data.get("item_path", "")
            payload["move_source_keys"] = sorted(src.keys())
        return payload

    def _log_destination_projection_collect_result(
        self,
        descendants,
        *,
        branch,
        graph_attempted=False,
        graph_error=None,
        **diag,
    ):
        count = len(descendants)
        sample_paths = []
        for data in descendants[:5]:
            sample_paths.append(self._canonical_source_projection_path(self._tree_item_path(data)))
        if count == 0:
            self._log_restore_phase(
                "destination_projection_collect_empty",
                branch=branch,
                descendant_count=0,
                graph_attempted=graph_attempted,
                graph_error=graph_error,
                sample_paths=sample_paths,
                **diag,
            )
        elif self._projection_diag_verbose_enabled():
            self._log_restore_phase(
                "destination_projection_collect_ok",
                branch=branch,
                descendant_count=count,
                graph_attempted=graph_attempted,
                graph_error=graph_error,
                sample_paths=sample_paths,
                **diag,
            )

    def _destination_projection_ui_snapshot(self, item):
        """Visible row state for projection / chevron / placeholder diagnostics."""
        if item is None:
            return {"item": None}
        node_data = item.data(0, Qt.UserRole) or {}
        path = self._tree_item_path(node_data)
        placeholders = []
        for index in range(item.childCount()):
            ch = item.child(index)
            cd = ch.data(0, Qt.UserRole) or {}
            if cd.get("placeholder"):
                placeholders.append(str(cd.get("placeholder_role", "") or "unknown"))
        policy = item.childIndicatorPolicy()
        show_chevron = policy == QTreeWidgetItem.ShowIndicator
        text_excerpt = (item.text(0) or "")[:160]
        return {
            "destination_path": path,
            "is_expanded": bool(item.isExpanded()),
            "child_count": item.childCount(),
            "placeholder_roles": placeholders,
            "child_indicator_show": show_chevron,
            "children_loaded": bool(node_data.get("children_loaded")),
            "load_failed": bool(node_data.get("load_failed")),
            "projection_unresolved_terminal": bool(node_data.get("projection_unresolved_terminal")),
            "is_planned_allocation": bool(self.node_is_planned_allocation(node_data)),
            "is_allocation_descendant": bool(node_data.get("planned_allocation_descendant")),
            "label_excerpt": text_excerpt,
        }

    def _log_destination_projection_ui(self, phase, *, item=None, **extra):
        if not self._projection_diag_verbose_enabled():
            return
        payload = dict(extra)
        if item is not None:
            payload.update(self._destination_projection_ui_snapshot(item))
        self._log_restore_phase(phase, **payload)

    def _run_restore_phase(self, phase_name, func, *, fatal=False):
        self._log_restore_phase(f"{phase_name} start")
        try:
            result = func()
            self._log_restore_phase(f"{phase_name} end")
            return result
        except Exception as exc:
            self._log_restore_exception(phase_name, exc)
            if fatal:
                raise
            return None

    def _planning_tree_top_level_count(self, tree):
        """``QTreeWidget.topLevelItemCount()`` or ``QTreeView.model().rowCount(root)``."""
        if tree is None:
            return 0
        top_fn = getattr(tree, "topLevelItemCount", None)
        if callable(top_fn):
            try:
                return int(top_fn())
            except (TypeError, AttributeError, RuntimeError):
                return 0
        if isinstance(tree, QTreeView):
            model = tree.model()
            if model is not None:
                try:
                    return int(model.rowCount(QModelIndex()))
                except (TypeError, AttributeError, RuntimeError):
                    return 0
        return 0

    def _iter_destination_top_level_rows(self):
        tree = getattr(self, "destination_tree_widget", None)
        if tree is None:
            return
        n = self._planning_tree_top_level_count(tree)
        if isinstance(tree, QTreeView):
            model = tree.model()
            if model is None:
                return
            for r in range(n):
                yield model.index(r, 0, QModelIndex())
            return
        for r in range(n):
            yield tree.topLevelItem(r)

    def _iter_panel_top_level_rows(self, panel_key: str):
        tree, _status = self._get_tree_and_status(panel_key)
        if tree is None:
            return
        n = self._planning_tree_top_level_count(tree)
        if isinstance(tree, QTreeView):
            model = tree.model()
            if model is None:
                return
            for r in range(n):
                yield model.index(r, 0, QModelIndex())
            return
        for r in range(n):
            yield tree.topLevelItem(r)

    def _count_visible_destination_future_state_nodes(self):
        count = 0
        for top in self._iter_destination_top_level_rows():
            for item in self._iter_tree_items(top):
                node_data = self.get_tree_item_node_data(item) or {}
                if (
                    self.node_is_proposed(node_data)
                    or self.node_is_planned_allocation(node_data)
                    or str(node_data.get("node_origin", "")).lower() == "projecteddestination"
                ):
                    count += 1
        return count

    def _destination_overlay_fingerprint_context(
        self, skip_allocation_descendants: bool, restrict_real_snapshot: bool = False
    ):
        current_drive_id = self._current_selected_destination_drive_id() or self.pending_root_drive_ids.get(
            "destination", ""
        ) or ""
        full_tree_n = (
            len(self._destination_full_tree_snapshot or [])
            if (
                bool(self._destination_full_tree_snapshot)
                and self._destination_full_tree_completed_drive_id == current_drive_id
            )
            else 0
        )
        snap_sig = real_snapshot_signature(
            self._destination_real_tree_snapshot,
            drive_id=current_drive_id,
            full_tree_entry_count=full_tree_n,
        )
        prop_sig = proposed_folders_signature(self.proposed_folders)
        moves_sig = aggregate_moves_signature(self.planned_moves)
        full_fp = full_overlay_fingerprint(
            moves_sig=moves_sig,
            proposed_sig=prop_sig,
            snapshot_sig=snap_sig,
            skip_allocation_descendants=bool(skip_allocation_descendants),
            restrict_real_snapshot=bool(restrict_real_snapshot),
        )
        return snap_sig, prop_sig, moves_sig, full_fp

    def _current_destination_full_overlay_fingerprint(self, *, force_refresh_snapshot: bool = True) -> str:
        _light_idle = bool(getattr(self, "_destination_full_tree_idle_light_overlay", False))
        self._refresh_destination_real_tree_snapshot(force=bool(force_refresh_snapshot) and not _light_idle)
        return self._destination_overlay_fingerprint_context(False)[3]

    def _destination_materialize_reason_may_skip_without_interrupting_async(self, reason: str) -> bool:
        r = str(reason or "")
        if r in _DESTINATION_MATERIALIZE_BENIGN_SECOND_PASS_REASONS:
            return True
        if r.startswith("deferred_"):
            return True
        if r.startswith("source_restore_flush_"):
            return True
        return False

    def _bump_destination_materialized_overlay_fingerprint(self, *, phase: str, first_render_path: str = "") -> None:
        """Record that the visible destination tree matches current planning overlay (anti double-bind)."""
        try:
            self._destination_last_materialized_overlay_fp = self._current_destination_full_overlay_fingerprint()
        except Exception:
            self._destination_last_materialized_overlay_fp = ""
        if is_dev_mode():
            fp = str(getattr(self, "_destination_last_materialized_overlay_fp", "") or "")
            log_info(
                "destination_double_render_guard",
                phase=phase,
                first_render_path=first_render_path or phase,
                overlay_fp_bumped=True,
                overlay_fp_prefix=fp[:16] if fp else "",
            )

    def _dev_log_destination_folder_allocation_lifecycle(
        self, phase: str, path: str, *, source: str = ""
    ) -> None:
        """Dev-only: trace allocation badge attach/refresh on destination folder rows."""
        if not is_dev_mode():
            return
        try:
            log_info(
                "destination_allocation_folder_lifecycle",
                phase=str(phase or "")[:120],
                path_excerpt=str(path or "")[:260],
                source=str(source or "")[:120],
            )
        except Exception:
            pass

    def _dev_log_watch_folder_badge_owners(self, context: str) -> None:
        """Dev-only: sample rows whose path contains known folder container names from manual QA.

        Supports QTreeWidget and model-backed :class:`DestinationPlanningTreeView`. Never raises.
        """
        if not is_dev_mode():
            return
        try:
            self._dev_log_watch_folder_badge_owners_impl(context)
        except Exception as exc:
            log_warn(
                "destination_allocation_folder_lifecycle",
                phase="final_watch_folder_badge_probe_error",
                context=context,
                error=str(exc),
            )

    def _dev_log_watch_folder_badge_owners_impl(self, context: str) -> None:
        tree = getattr(self, "destination_tree_widget", None)
        if tree is None:
            log_info(
                "destination_allocation_folder_lifecycle",
                phase="final_watch_folder_badge_probe",
                context=context,
                rows=[],
            )
            return

        watches = ("100GOPRO", "Employee Hours")
        rows: list[dict] = []

        if self._destination_tree_uses_model_view():
            if self._planning_tree_top_level_count(tree) <= 0:
                log_info(
                    "destination_allocation_folder_lifecycle",
                    phase="final_watch_folder_badge_probe",
                    context=context,
                    rows=[],
                )
                return
            model = getattr(self, "destination_planning_model", None)
            if model is None or not hasattr(model, "iter_depth_first"):
                log_info(
                    "destination_allocation_folder_lifecycle",
                    phase="final_watch_folder_badge_probe",
                    context=context,
                    note="model_view_missing_iter_depth_first",
                    rows=[],
                )
                return
            for ix in model.iter_depth_first():
                nd = self.get_tree_item_node_data(ix) or {}
                if not isinstance(nd, dict):
                    continue
                sp = self._destination_row_semantic_path(nd) or ""
                if not sp or not any(w in sp for w in watches):
                    continue
                label = str(nd.get("base_display_label", "") or nd.get("name", "") or "")[:120]
                rows.append(
                    {
                        "path": sp[:200],
                        "has_allocated_tag": "[Allocated]" in label,
                        "planned_allocation": bool(nd.get("planned_allocation")),
                    }
                )
        elif hasattr(tree, "topLevelItemCount") and hasattr(tree, "topLevelItem"):
            if tree.topLevelItemCount() <= 0:
                log_info(
                    "destination_allocation_folder_lifecycle",
                    phase="final_watch_folder_badge_probe",
                    context=context,
                    rows=[],
                )
                return
            for ti in range(tree.topLevelItemCount()):
                root = tree.topLevelItem(ti)
                for item in self._iter_tree_items(root):
                    nd = item.data(0, Qt.UserRole) or {}
                    if not isinstance(nd, dict):
                        continue
                    sp = self._destination_row_semantic_path(nd) or ""
                    if not sp or not any(w in sp for w in watches):
                        continue
                    label = str(nd.get("base_display_label", "") or item.text(0) or "")[:120]
                    rows.append(
                        {
                            "path": sp[:200],
                            "has_allocated_tag": "[Allocated]" in label,
                            "planned_allocation": bool(nd.get("planned_allocation")),
                        }
                    )
        else:
            log_info(
                "destination_allocation_folder_lifecycle",
                phase="final_watch_folder_badge_probe",
                context=context,
                note="unsupported_destination_tree_type",
                tree_class=tree.__class__.__name__,
                rows=[],
            )
            return

        log_info(
            "destination_allocation_folder_lifecycle",
            phase="final_watch_folder_badge_probe",
            context=context,
            rows=rows[:16],
        )

    def _destination_steady_state_full_materialize_redundant(self) -> bool:
        """True when restore has finalized and overlay fingerprint matches the last successful bind.

        Requires both fingerprints non-empty so we never skip the first post-restore materialize
        or a bind before ``_destination_last_materialized_overlay_fp`` was recorded.

        Never "steady" while proposed/allocation overlays are still queued for replay — fingerprint
        alone can match even when bind paths have not drained (deferred refresh coalescing bug).
        """
        if getattr(self, "_destination_suppress_steady_materialize_skip_once", False):
            return False
        if not getattr(self, "_destination_restore_completed_once", False):
            return False
        u = int(self._unresolved_proposed_queue_size() or 0) + int(self._unresolved_allocation_queue_size() or 0)
        if u > 0:
            return False
        if bool(getattr(self, "_restore_destination_overlay_pending", False)):
            return False
        try:
            current_fp = self._current_destination_full_overlay_fingerprint()
        except Exception:
            current_fp = ""
        last_fp = str(getattr(self, "_destination_last_materialized_overlay_fp", "") or "")
        return bool(current_fp and last_fp and current_fp == last_fp)

    def _try_skip_redundant_destination_future_model_materialize(self, reason) -> int | None:
        """If overlay fingerprint matches last materialization, skip a redundant bind (preserve async projection).

        Only *benign* second-pass reasons may skip. Non-benign reasons may cancel in-flight descendant
        projection; they must never hit a fp-based skip afterward or we drop the full rebind that
        restores folder-level [Allocated] chrome on real rows.
        """
        r = str(reason or "")
        if r == "destination_full_tree_idle_success" and self._destination_should_block_idle_full_tree_materialize():
            self._destination_full_tree_materialization_pending = True
            self._schedule_destination_full_tree_materialization(3200)
            if is_dev_mode():
                log_info(
                    "destination_double_render_guard",
                    phase="idle_full_tree_deferred_interactive_expand",
                    incoming_reason=r,
                    note="blocked_before_fp_mismatch_admission",
                )
            return 0
        if r == "deferred_reconcile_folder_worker_success" and self._destination_should_block_idle_full_tree_materialize():
            self._destination_idle_materialize_pending_reason = r
            idle_timer = getattr(self, "_destination_idle_materialize_timer", None)
            if idle_timer is not None:
                idle_timer.stop()
                idle_timer.start(max(0, 3200))
            else:
                QTimer.singleShot(
                    3200,
                    lambda: self._safe_invoke(
                        "deferred_destination_materialization_interactive_expand_retry",
                        self._run_deferred_destination_materialization,
                    ),
                )
            if is_dev_mode():
                log_info(
                    "destination_double_render_guard",
                    phase="drfws_deferred_interactive_expand",
                    incoming_reason=r,
                    note="blocked_before_fp_mismatch_admission",
                )
            return 0
        tree = getattr(self, "destination_tree_widget", None)
        if tree is None or self._planning_tree_top_level_count(tree) <= 0:
            return None
        benign = self._destination_materialize_reason_may_skip_without_interrupting_async(r)
        try:
            current_full_fp = self._current_destination_full_overlay_fingerprint(force_refresh_snapshot=False)
        except Exception:
            current_full_fp = ""
        last_fp = str(getattr(self, "_destination_last_materialized_overlay_fp", "") or "")
        fp_match = bool(current_full_fp and last_fp and current_full_fp == last_fp)
        async_on = getattr(self, "_destination_future_projection_async_state", None) is not None
        if is_dev_mode() and fp_match and not benign:
            log_info(
                "destination_double_render_guard",
                phase="redundant_skip_declined_non_benign",
                incoming_reason=r,
                fp_match=True,
                note="full_materialize_required_after_possible_async_cancel",
            )
        if not fp_match:
            if is_dev_mode() and benign:
                log_info(
                    "destination_double_render_guard",
                    phase="materialize_allowed_fp_mismatch",
                    incoming_reason=r,
                    fp_match=False,
                )
            return None
        if not benign:
            return None
        visible_future_branch_count = self._count_visible_destination_future_state_nodes()
        u_prop = self._unresolved_proposed_queue_size()
        u_alloc = self._unresolved_allocation_queue_size()
        unresolved_total = int(u_prop + u_alloc)
        has_planning_memory = bool(getattr(self, "planned_moves", None) or getattr(self, "proposed_folders", None))
        graph_auth = destination_authority_contract.graph_owns_visible_real_destination_structure(self)
        parent_vis = self._destination_unresolved_overlay_parent_visibility_diag()
        allow_fp_skip = True
        skip_blocker = ""
        missing_overlay_targets: list[str] = []
        if unresolved_total > 0:
            allow_fp_skip = False
            skip_blocker = "unresolved_overlay_backlog"
        elif graph_auth and has_planning_memory and visible_future_branch_count <= 0:
            allow_fp_skip = False
            skip_blocker = "graph_authority_no_visible_overlay_evidence"
        elif graph_auth and has_planning_memory:
            missing_overlay_targets = self._destination_planning_overlay_targets_missing_visible_evidence()
            if missing_overlay_targets:
                allow_fp_skip = False
                skip_blocker = "planning_overlay_targets_missing_visible_evidence"
        self._log_restore_phase(
            "destination_overlay_skip_decision",
            scope="redundant_fp_match" if fp_match else "fp_mismatch",
            benign_second_pass=bool(benign),
            incoming_reason=str(r)[:200],
            fp_match=bool(fp_match),
            visible_attached_overlay_evidence_count=int(visible_future_branch_count),
            unresolved_proposed=int(u_prop),
            unresolved_allocation=int(u_alloc),
            has_planning_memory=bool(has_planning_memory),
            graph_authority=bool(graph_auth),
            skip_blocker=str(skip_blocker or ""),
            unresolved_parent_visibility=parent_vis,
            planning_overlay_target_miss_count=len(missing_overlay_targets),
            planning_overlay_target_miss_samples=missing_overlay_targets[:12],
            final_decision="skip" if allow_fp_skip else "apply",
        )
        if not allow_fp_skip:
            if is_dev_mode():
                log_info(
                    "destination_double_render_guard",
                    phase="fp_skip_declined_overlay_replay_required",
                    incoming_reason=r,
                    skip_blocker=skip_blocker,
                    visible_future_branch_count=visible_future_branch_count,
                    unresolved_total=unresolved_total,
                    has_planning_memory=has_planning_memory,
                    graph_authority=graph_auth,
                    **parent_vis,
                )
            return None
        if is_dev_mode():
            log_info(
                "destination_double_render_guard",
                phase="redundant_materialize_skipped",
                first_render_path="visible_tree_matches_overlay_fp",
                second_scheduled_reason=r,
                async_projection_preserved=async_on,
                skipped=True,
                visible_future_branch_count=visible_future_branch_count,
                fingerprint_short_circuit=True,
                unresolved_total=0,
            )
        self._log_restore_phase(
            "destination_future_model_materialize_skipped",
            reason=reason,
            skip_reason="already_materialized_same_overlay",
            visible_future_branch_count=visible_future_branch_count,
            async_projection_preserved=async_on,
            fingerprint_short_circuit=True,
            unresolved_proposed=int(u_prop),
            unresolved_allocation=int(u_alloc),
        )
        if self._destination_forensic_planned_item_materialization_logging_enabled():
            log_info(
                "destination_forensic_materialize_suppressed",
                suppression_kind="overlay_fingerprint_match_benign_skip",
                incoming_reason=str(reason)[:200],
                unresolved_proposed=int(u_prop),
                unresolved_allocation=int(u_alloc),
                visible_future_branch_count=int(visible_future_branch_count),
                note="full_overlay_pass_including_replay_unresolved_proposed_overlay_not_run",
            )
        self._set_tree_status_message("destination", "Destination structure ready.", loading=False)
        return visible_future_branch_count

    def _safe_invoke(self, callback_name, fn, *args, **kwargs):
        should_log = self._should_log_safe_callback(callback_name)
        if should_log:
            restore_log = bool(self._memory_restore_in_progress) and not bool(
                getattr(self, "_memory_restore_background_trees", False)
            )
            log_info(
                "Safe callback entered.",
                callback=callback_name,
                restore_in_progress=restore_log,
                selector_suppressed=self._suppress_selector_change_handlers,
                destination_tree_ready=self._planning_tree_top_level_count(getattr(self, "destination_tree_widget", None)) > 0,
                window_visible=self.isVisible(),
            )
        try:
            result = fn(*args, **kwargs)
            if should_log:
                log_info("Safe callback exited.", callback=callback_name, window_visible=self.isVisible())
            return result
        except Exception as exc:
            self._log_restore_exception(callback_name, exc)
            return None

    def _should_log_safe_callback(self, callback_name):
        # Keep callback logging lightweight by default; very chatty logging can choke the UI thread.
        flag = os.environ.get("OZLINK_SAFE_CALLBACK_VERBOSE", "").strip().lower()
        if flag in ("1", "true", "yes"):
            return True
        important_callbacks = {
            "phase2_post_login_restore_timer",
            "phase4_destination_overlay_timer",
            "phase4_destination_overlay_immediate",
            "phase4_destination_overlay_after_destination_ui",
            "login.restore_workspace",
            "login_worker.success",
            "discovery_worker.success",
            "discovery_worker.finished",
            "device_flow_worker.success",
            "destination_full_tree.success",
            "destination_full_tree.finished",
        }
        return callback_name in important_callbacks

    def _schedule_safe_timer(self, delay_ms, callback_name, fn, *args, **kwargs):
        if self._should_log_safe_callback(callback_name):
            log_info("Scheduling safe timer callback.", callback=callback_name, delay_ms=delay_ms)
        QTimer.singleShot(max(0, int(delay_ms)), lambda: self._safe_invoke(callback_name, fn, *args, **kwargs))

    def _next_worker_id(self, prefix):
        self._worker_sequence += 1
        return f"{prefix}-{self._worker_sequence:04d}"

    def _log_worker_lifecycle(self, event, worker_kind, worker_id, worker_key, **data):
        data.setdefault("worker_kind", worker_kind)
        data.setdefault("worker_id", worker_id)
        data.setdefault("worker_key", worker_key)
        data.setdefault("active_root_workers", len(self.root_load_workers))
        data.setdefault("retired_root_workers", len(self.root_load_retired_workers))
        data.setdefault("active_folder_workers", len(self.folder_load_workers))
        data.setdefault("retired_folder_workers", len(self.folder_load_retired_workers))
        log_info(f"Worker lifecycle {event}.", **data)

    def _register_root_worker(self, panel_key, worker):
        worker_id = self._next_worker_id("root")
        existing_entry = self.root_load_workers.get(panel_key)
        if existing_entry:
            existing_entry["stale"] = True
            self.root_load_retired_workers[existing_entry["id"]] = existing_entry
            self._log_worker_lifecycle(
                "superseded",
                "root",
                existing_entry["id"],
                panel_key,
                running=existing_entry["worker"].isRunning(),
            )

        entry = {
            "id": worker_id,
            "worker": worker,
            "panel_key": panel_key,
            "stale": False,
        }
        self.root_load_workers[panel_key] = entry
        self._log_worker_lifecycle("created", "root", worker_id, panel_key)
        self._log_worker_lifecycle("registered_active", "root", worker_id, panel_key)
        return entry

    def _folder_load_worker_thread_running(self, worker_key: str) -> bool:
        """True when an active folder worker slot still has a running QThread (in-flight load)."""
        entry = (getattr(self, "folder_load_workers", None) or {}).get(worker_key)
        if not entry:
            return False
        w = entry.get("worker")
        try:
            return w is not None and w.isRunning()
        except Exception:
            return False

    def _register_folder_worker(
        self,
        worker_key,
        worker,
        item,
        *,
        pending_key: str = "",
        source_folder_parent_persistent=None,
        destination_folder_parent_persistent=None,
        destination_graph_union_merge_at_model_root: bool = False,
        graph_union_mode: str = "",
        graph_child_union_bootstrap: bool = False,
    ):
        worker_id = self._next_worker_id("folder")
        existing_entry = self.folder_load_workers.get(worker_key)
        if existing_entry:
            existing_entry["stale"] = True
            self.folder_load_retired_workers[existing_entry["id"]] = existing_entry
            self._log_worker_lifecycle(
                "superseded",
                "folder",
                existing_entry["id"],
                worker_key,
                running=existing_entry["worker"].isRunning(),
            )

        entry: dict = {
            "id": worker_id,
            "worker": worker,
            "item": item,
            "worker_key": worker_key,
            "stale": False,
            "pending_key": str(pending_key or ""),
            "source_folder_parent_persistent": source_folder_parent_persistent,
            "destination_folder_parent_persistent": destination_folder_parent_persistent,
        }
        if destination_graph_union_merge_at_model_root:
            entry["destination_graph_union_merge_at_model_root"] = True
        if str(graph_union_mode or "").strip():
            entry["graph_union_mode"] = str(graph_union_mode or "").strip()
        if graph_child_union_bootstrap:
            entry["graph_child_union_bootstrap"] = True
        if str(worker_key).startswith("source:") and getattr(self, "source_sharepoint_model", None) is not None:
            entry["source_model_structure_generation_at_request"] = int(
                self.source_sharepoint_model.structure_generation()
            )
        else:
            entry["source_model_structure_generation_at_request"] = None
        self.folder_load_workers[worker_key] = entry
        self._log_worker_lifecycle("created", "folder", worker_id, worker_key)
        self._log_worker_lifecycle("registered_active", "folder", worker_id, worker_key)
        return entry

    def _build_root_request_signature(self, panel_key, site, library):
        site_payload = site if isinstance(site, dict) else {}
        library_payload = library if isinstance(library, dict) else {}
        return {
            "panel_key": panel_key,
            "site_id": site_payload.get("id", ""),
            "library_id": library_payload.get("id", ""),
            "drive_id": library_payload.get("id", ""),
            "tree_role": panel_key,
        }

    def _tree_has_bound_root_content(self, panel_key):
        tree, _status = self._get_tree_and_status(panel_key)
        if tree is None:
            return False
        if panel_key == "source":
            model = getattr(self, "source_sharepoint_model", None)
            if model is None or model.rowCount(QModelIndex()) == 0:
                return False
            first_ix = model.index(0, 0, QModelIndex())
            first_data = first_ix.data(Qt.UserRole) or {}
            return not first_data.get("placeholder")
        if panel_key == "destination":
            model = getattr(self, "destination_planning_model", None)
            if model is None or model.rowCount(QModelIndex()) == 0:
                return False
            for r in range(model.rowCount(QModelIndex())):
                ix = model.index(r, 0, QModelIndex())
                row_data = ix.data(Qt.UserRole) or {}
                if not row_data.get("placeholder"):
                    return True
            return False
        if self._planning_tree_top_level_count(tree) == 0:
            return False
        if isinstance(tree, QTreeView):
            model = tree.model()
            if model is None:
                return False
            first_ix = model.index(0, 0, QModelIndex())
            first_data = first_ix.data(Qt.UserRole) or {}
        else:
            first_item = tree.topLevelItem(0)
            first_data = first_item.data(0, Qt.UserRole) or {}
        return not first_data.get("placeholder")

    def _cleanup_root_worker(self, panel_key, worker_id):
        entry = None
        active_entry = self.root_load_workers.get(panel_key)
        if active_entry and active_entry.get("id") == worker_id:
            entry = self.root_load_workers.pop(panel_key, None)
        else:
            entry = self.root_load_retired_workers.pop(worker_id, None)

        if not entry:
            self._log_worker_lifecycle("cleanup_missing", "root", worker_id, panel_key)
            return

        worker = entry.get("worker")
        self._log_worker_lifecycle(
            "finished",
            "root",
            worker_id,
            panel_key,
            running=worker.isRunning() if worker else False,
        )
        if worker is not None:
            still_running = False
            try:
                still_running = bool(
                    _shiboken_is_valid(worker) and hasattr(worker, "isRunning") and worker.isRunning()
                )
            except Exception:
                still_running = False
            if still_running:
                log_info(
                    "destination_rebind_worker_cleanup_deferred_until_finished",
                    worker_role="root",
                    panel_key=panel_key,
                    worker_id=worker_id,
                    note="join_before_deleteLater",
                )
                try:
                    self._shutdown_worker_safe_join(worker, timeout_ms=1800)
                except Exception:
                    pass
                try:
                    still_running = bool(
                        _shiboken_is_valid(worker) and hasattr(worker, "isRunning") and worker.isRunning()
                    )
                except Exception:
                    still_running = False
            if still_running:
                log_info(
                    "root_worker_cleanup_delete_deferred_until_thread_finished",
                    panel_key=panel_key,
                    worker_id=worker_id,
                )
                try:
                    fin = getattr(worker, "finished", None)
                    if fin is not None:
                        fin.disconnect()
                except Exception:
                    pass
                try:
                    worker.finished.connect(worker.deleteLater)
                except Exception:
                    pass
                return
            try:
                if _shiboken_is_valid(worker):
                    worker.deleteLater()
            except Exception:
                pass
        self._log_worker_lifecycle("cleaned_up", "root", worker_id, panel_key)

    def _cleanup_folder_worker(self, worker_key, worker_id):
        entry = None
        active_entry = self.folder_load_workers.get(worker_key)
        if active_entry and active_entry.get("id") == worker_id:
            entry = self.folder_load_workers.pop(worker_key, None)
        else:
            entry = self.folder_load_retired_workers.pop(worker_id, None)

        if not entry:
            self._log_worker_lifecycle("cleanup_missing", "folder", worker_id, worker_key)
            return

        worker = entry.get("worker")
        self._log_worker_lifecycle(
            "finished",
            "folder",
            worker_id,
            worker_key,
            running=worker.isRunning() if worker else False,
        )
        if worker is not None:
            still_running = False
            try:
                still_running = bool(
                    _shiboken_is_valid(worker) and hasattr(worker, "isRunning") and worker.isRunning()
                )
            except Exception:
                still_running = False
            if still_running:
                log_info(
                    "destination_rebind_worker_cleanup_deferred_until_finished",
                    worker_role="folder",
                    panel_key=str(worker_key)[:200],
                    worker_id=worker_id,
                    note="join_before_deleteLater",
                )
                try:
                    self._shutdown_worker_safe_join(worker, timeout_ms=1800)
                except Exception:
                    pass
                try:
                    still_running = bool(
                        _shiboken_is_valid(worker) and hasattr(worker, "isRunning") and worker.isRunning()
                    )
                except Exception:
                    still_running = False
            if still_running:
                log_info(
                    "folder_worker_cleanup_delete_deferred_until_thread_finished",
                    worker_key=str(worker_key)[:200],
                    worker_id=worker_id,
                )
                try:
                    fin = getattr(worker, "finished", None)
                    if fin is not None:
                        fin.disconnect()
                except Exception:
                    pass
                try:
                    worker.finished.connect(worker.deleteLater)
                except Exception:
                    pass
                return
            try:
                if _shiboken_is_valid(worker):
                    worker.deleteLater()
            except Exception:
                pass
        self._log_worker_lifecycle("cleaned_up", "folder", worker_id, worker_key)

    def _tree_item_is_alive(self, item):
        if item is None:
            return False
        if isinstance(item, QModelIndex):
            return item.isValid()
        try:
            item.childCount()
            item.data(0, Qt.UserRole)
            return True
        except RuntimeError:
            return False

    def _build_restored_planned_move_record(self, row: AllocationRow):
        source_path = str(row.SourcePath or "")
        destination_path = str(row.RequestedDestinationPath or "")
        destination_leaf = destination_path.replace("/", "\\").rstrip("\\").split("\\")[-1] if destination_path else row.SourceItemName
        source_is_folder = row.SourceType.lower() == "folder"
        sid = str(row.SourceItemId or "").strip()
        sdrv = str(row.SourceDriveId or "").strip()
        did = str(row.DestinationParentItemId or "").strip()
        ddrv = str(row.DestinationDriveId or "").strip()
        return {
            "request_id": row.RequestId,
            "allocation_method": row.AllocationMethod,
            "requested_by": row.RequestedBy,
            "requested_date": row.RequestedDate,
            "status": row.Status,
            "LegacyMigrationAnchorClassification": str(row.LegacyMigrationAnchorClassification or ""),
            "LegacyMigrationPlannedScaffoldOnly": bool(row.LegacyMigrationPlannedScaffoldOnly),
            "LegacyMigrationRootNotLiveConfirmed": bool(row.LegacyMigrationRootNotLiveConfirmed),
            "LegacyMigrationUnresolvedGraphAnchor": bool(row.LegacyMigrationUnresolvedGraphAnchor),
            "LegacyForeignRootBlocked": bool(row.LegacyForeignRootBlocked),
            "LegacyMigrationPlannedParentResolved": bool(row.LegacyMigrationPlannedParentResolved),
            "LegacyMigrationDestinationParentResolution": str(row.LegacyMigrationDestinationParentResolution or ""),
            "DestinationParentPlannedPath": str(row.DestinationParentPlannedPath or ""),
            "LegacyMigrationPlannedParentMatchKind": str(row.LegacyMigrationPlannedParentMatchKind or ""),
            "source_id": sid,
            "source_name": row.SourceItemName,
            "source_path": source_path,
            "source": {
                "id": sid,
                "name": row.SourceItemName,
                "real_name": row.SourceItemName,
                "display_path": source_path,
                "item_path": source_path,
                "tree_role": "source",
                "drive_id": sdrv,
                "is_folder": source_is_folder,
            },
            "destination_id": did,
            "destination_name": destination_leaf,
            "destination_path": destination_path,
            "destination": {
                "id": did,
                "name": destination_leaf,
                "real_name": destination_leaf,
                "display_path": destination_path,
                "item_path": destination_path,
                "tree_role": "destination",
                "drive_id": ddrv,
                "is_folder": True,
            },
        }

    def _restore_memory_payload(self, session_state: SessionState, allocations: list[AllocationRow], proposed: list[ProposedFolder], session_raw: dict):
        self.planned_rows_by_parent_path = {}
        self._graph_linkage_context_retry_count = 0
        self._graph_linkage_enrich_busy_skips = 0
        self._destination_deferred_reconcile_burst_pending = False
        self._reset_projection_delta_coalesce_state()
        self._draft_shell_state = session_state
        self._draft_shell_raw = dict(session_raw or {})
        self.active_draft_session_id = session_state.DraftId or self.active_draft_session_id
        self.planned_moves = [self._build_restored_planned_move_record(row) for row in allocations]
        self._plan_leaf_exclusions = set()
        for p in getattr(session_state, "PlanLeafExclusions", None) or []:
            if isinstance(p, str) and p.strip():
                cp = self._canonical_source_projection_path(p)
                if cp:
                    self._plan_leaf_exclusions.add(cp)
        self._sync_destination_plan_leaf_exclusion_paint_contract()
        self._needs_review_dismissed_inherited_paths = set()
        for p in getattr(session_state, "NeedsReviewDismissedInheritedSourcePaths", None) or []:
            if isinstance(p, str) and p.strip():
                self._needs_review_dismissed_inherited_paths.add(self.normalize_memory_path(p))
        self._clear_source_projection_descendants_cache(reason="restored_memory_payload", caller="_restore_memory_payload")
        self.proposed_folders = list(proposed)
        self._ensure_proposed_folders_stable_keys_assigned()
        self._reset_unresolved_proposed_queue()
        self._reset_unresolved_allocation_queue()
        self._restored_allocation_count = len(allocations)
        self._restored_proposed_count = len(proposed)
        self._sync_restore_destination_overlay_pending_from_unresolved_queues()
        self.refresh_planned_moves_table()
        try:
            self._destination_filter_restored_planning_against_session_identity(
                session_state,
                context="restore_memory_payload",
            )
        except Exception:
            pass
        log_info(
            "Draft payload restored into runtime.",
            draft_id=self.active_draft_session_id,
            planned_moves_restored=len(allocations),
            proposed_folders_restored=len(proposed),
        )
        try:
            _sess_n = int(self._count_tree_snapshot_nodes(list(session_state.DestinationTreeSnapshot or [])))
            log_info(
                "snapshot_restore_forensic",
                phase="restore_memory_payload_session_only",
                session_json_destination_snapshot_count_loaded=int(_sess_n),
                note="workspace_sidecar_merged_later_in_begin_session_workspace_ui_restore",
            )
        except Exception:
            pass
        self._log_restore_state_snapshot("restore_runtime_applied")
        self._log_restored_planning_runtime_counts(context="restore_memory_payload")

    def _log_restored_planning_runtime_counts(self, *, context: str = "") -> None:
        """Summarize restored draft rows for diagnostics (runtime ``planned_moves`` / ``proposed_folders``)."""
        pm = list(getattr(self, "planned_moves", None) or [])
        pfolders = list(getattr(self, "proposed_folders", None) or [])
        by_res: Counter[str] = Counter()
        dest_parent_item_nonempty = 0
        dest_parent_planned_nonempty = 0
        requested_dest_nonempty = 0
        for m in pm:
            if not isinstance(m, dict):
                continue
            r = str(m.get("LegacyMigrationDestinationParentResolution", "") or "").strip().casefold()
            if not r:
                r = "(blank)"
            elif r not in ("graph", "planned_parent"):
                r = "other"
            by_res[r] += 1
            if str(m.get("destination_id", "") or "").strip():
                dest_parent_item_nonempty += 1
            if str(m.get("DestinationParentPlannedPath", "") or "").strip():
                dest_parent_planned_nonempty += 1
            if str(m.get("destination_path", "") or "").strip():
                requested_dest_nonempty += 1
        log_info(
            "restored_planning_runtime_counts",
            context=str(context or "")[:120],
            allocation_row_count=len(pm),
            proposed_folder_row_count=len(pfolders),
            planned_moves_runtime=len(pm),
            proposed_folders_runtime=len(pfolders),
        )
        log_info(
            "restored_planning_resolution_summary",
            context=str(context or "")[:120],
            legacy_migration_destination_parent_resolution=dict(by_res),
            destination_parent_item_id_nonempty=int(dest_parent_item_nonempty),
            destination_parent_planned_path_nonempty=int(dest_parent_planned_nonempty),
            destination_path_or_requested_nonempty=int(requested_dest_nonempty),
        )

    def _log_destination_overlay_entry_context(self, reason: str) -> None:
        """Single place for overlay entry diagnostics (``destination_overlay_entry_counts``)."""
        did = str(
            (getattr(self, "pending_root_drive_ids", None) or {}).get("destination")
            or (
                self._current_selected_destination_drive_id()
                if hasattr(self, "_current_selected_destination_drive_id")
                else ""
            )
            or ""
        ).strip()
        sid = str(
            (getattr(self, "pending_root_drive_ids", None) or {}).get("source")
            or (
                self._current_selected_source_drive_id()
                if hasattr(self, "_current_selected_source_drive_id")
                else ""
            )
            or ""
        ).strip()
        mod_n = -1
        dm = getattr(self, "destination_planning_model", None)
        if dm is not None and hasattr(dm, "iter_depth_first"):
            try:
                mod_n = sum(1 for _ in dm.iter_depth_first())
            except Exception:
                mod_n = -1
        root_bound = bool(
            getattr(self, "_root_tree_bind_in_progress", False) is False
            and getattr(self, "_destination_root_prime_pending", True) is not True
        )
        try:
            root_bound = root_bound and bool(getattr(self, "destination_tree_widget", None) is not None)
        except Exception:
            pass
        log_info(
            "destination_overlay_entry_counts",
            overlay_reason=str(reason or "")[:220],
            planned_moves_count=len(getattr(self, "planned_moves", None) or []),
            proposed_folders_count=len(getattr(self, "proposed_folders", None) or []),
            unresolved_allocation_queue_size=int(self._unresolved_allocation_queue_size() or 0),
            unresolved_proposed_queue_size=int(self._unresolved_proposed_queue_size() or 0),
            selected_destination_drive_id_suffix=did[-16:] if len(did) > 16 else did,
            selected_source_drive_id_suffix=sid[-16:] if len(sid) > 16 else sid,
            destination_model_node_count=int(mod_n),
            destination_live_root_ready_hint=bool(root_bound),
            restore_destination_overlay_pending=bool(getattr(self, "_restore_destination_overlay_pending", False)),
            memory_restore_in_progress=bool(getattr(self, "_memory_restore_in_progress", False)),
            full_tree_ready=bool(self._destination_full_tree_ready()) if hasattr(self, "_destination_full_tree_ready") else False,
        )
        self._planned_parent_overlay_diag_count = 0
        self._recoverable_graph_overlay_diag_count = 0

    def _log_destination_overlay_after_import_skipped(self, *, skip_reason: str, overlay_reason: str | None = None) -> None:
        if not getattr(self, "_overlay_followup_after_import", False):
            return
        log_info(
            "destination_overlay_after_import_skipped",
            skip_reason=str(skip_reason)[:160],
            overlay_reason=str(overlay_reason or getattr(self, "_destination_materialize_active_reason", "") or "")[:220],
        )

    def _load_draft_shell_into_runtime(self):
        if self.memory_manager is None:
            return

        try:
            self._restore_abort_mode = False
            self._restore_abort_reason = ""
            self._destination_restore_completed_once = False
            self._memory_restore_in_progress = True
            self._memory_restore_complete = False
            self._suppress_autosave = True
            self._restore_finalization_deferred_active = False
            self._restore_finalization_deferred_reason = ""
            self._graph_linkage_restore_finalize_pending_last_sig = None
            self._graph_linkage_banner_ui_last_sig = ""
            self._graph_linkage_ui_mode = "idle"
            self._graph_dest_parent_negative_cache.clear()
            candidates = self.memory_manager.discover_restore_candidates()
            for candidate in candidates:
                log_info(
                    "Memory restore candidate found.",
                    candidate=candidate.get("name"),
                    draft_id=candidate.get("draft_id", ""),
                    allocation_count=candidate.get("allocation_count", 0),
                    proposed_count=candidate.get("proposed_count", 0),
                    populated=bool(candidate.get("populated")),
                    session_path=str(candidate.get("session_path", "")),
                )

            selected, reason = self.memory_manager.select_restore_candidate(candidates)
            selected = self.memory_manager.prepare_selected_candidate_for_runtime(selected, candidates)
            self._memory_restore_candidate = selected
            if selected is None:
                self._clear_runtime_draft_state(refresh_ui=True)
                log_warn(
                    "No draft restore candidate available.",
                    memory_root=str(self.memory_manager.root),
                    python_primary_storage_root=str(self.memory_manager.python_primary_storage_root),
                    legacy_compatibility_root=str(self.memory_manager.legacy_compatibility_root),
                )
                return

            self._restore_payload_source = (
                "powershell_compat"
                if str(selected.get("name", "")).startswith("legacy_")
                else "python_root"
            )
            self._restore_selected_candidate_path = str(selected.get("session_path", ""))
            self._log_restore_state_snapshot(
                "restore_candidate_selected",
                selected_candidate_path=self._restore_selected_candidate_path,
                selection_reason=reason,
                selected_candidate=selected.get("name", ""),
            )

            session_state, allocations, proposed, session_raw = self.memory_manager.load_candidate_payload(selected)
            log_info(
                "Memory restore candidate selected.",
                reason=reason,
                selected_candidate=selected.get("name"),
                selected_storage_root=selected.get("storage_root", ""),
                restore_source=self.memory_manager.current_restore_source,
                write_root=str(self.memory_manager.current_write_root),
            )
            self._log_restore_state_snapshot(
                "restore_payload_loaded",
                selected_candidate_path=self._restore_selected_candidate_path,
                raw_allocation_count=len(allocations),
                raw_proposed_count=len(proposed),
            )
            self._maybe_show_restore_backup_banner(selected)
            self._run_restore_phase(
                "phase1_load_canonical_state",
                lambda: self._restore_memory_payload(session_state, allocations, proposed, session_raw),
                fatal=True,
            )
        except Exception as exc:
            self._log_restore_exception("phase1_load_canonical_state", exc)
        finally:
            self._memory_restore_in_progress = False

    def _hydrate_runtime_from_import_bundle_primary_memory(self) -> None:
        """After :meth:`MemoryManager.import_bundle`, hydrate runtime from active primary JSON (no restore-candidate promotion).

        Restore-candidate selection can prefer backups or mis-score the freshly imported primary; the import path must
        reflect exactly what was just written under ``memory_write_root``.
        """
        mm = self.memory_manager
        if mm is None:
            return
        log_info("import_restore_runtime_load_started", memory_write_root=str(mm.root))
        _ok = False
        try:
            self._restore_abort_mode = False
            self._restore_abort_reason = ""
            self._destination_restore_completed_once = False
            self._memory_restore_in_progress = True
            self._memory_restore_complete = False
            self._suppress_autosave = True
            self._restore_finalization_deferred_active = False
            self._restore_finalization_deferred_reason = ""
            self._graph_dest_parent_negative_cache.clear()
            session_raw, allocations, proposed = mm.load_session_raw_and_allocations_proposed()
            session_state = SessionState.from_dict(session_raw if isinstance(session_raw, dict) else {})
            log_info("import_restore_runtime_allocations_loaded", count=len(allocations))
            log_info("import_restore_runtime_proposed_loaded", count=len(proposed))
            self._memory_restore_candidate = {
                "name": "import_primary_memory",
                "allocation_count": len(allocations),
                "proposed_count": len(proposed),
                "session_path": str(mm.paths.get("session") or ""),
                "populated": bool(allocations or proposed),
                "valid": True,
            }
            self._restore_payload_source = "python_import_bundle"
            self._restore_selected_candidate_path = str(mm.paths.get("session") or "")
            self._run_restore_phase(
                "import_load_primary_memory",
                lambda: self._restore_memory_payload(session_state, allocations, proposed, session_raw or {}),
                fatal=True,
            )
            log_info(
                "import_restore_runtime_counts",
                planned_moves=len(self.planned_moves),
                proposed_folders=len(self.proposed_folders),
            )
            self.update_progress_summaries()
            log_info(
                "import_restore_overlay_scheduled",
                planned_moves=len(self.planned_moves),
                proposed_folders=len(self.proposed_folders),
            )
            self._overlay_followup_after_import = True
            self._import_overlay_started_logged = False
            log_info(
                "destination_overlay_after_import_pending",
                note="next_destination_overlay_pass_will_emit_entry_and_completion_logs",
            )
            _ok = True
        except Exception as exc:
            self._log_restore_exception("import_hydrate_primary_memory", exc)
            mm.clear_import_restore_empty_guard()
        finally:
            self._memory_restore_in_progress = False
            if _ok:
                mm.confirm_import_restore_runtime_loaded()

    def _build_memory_allocation_rows(self):
        rows = []
        for index, move in enumerate(self.planned_moves):
            rows.append(self._build_allocation_row_for_move(move, index))
        return rows

    def _build_memory_proposed_folders(self):
        return list(self.proposed_folders)

    def _planning_side_context_for_snapshot(self, *, side: str) -> dict[str, Any]:
        """SharePoint-oriented site/library identifiers from live selectors (best-effort, read-only)."""
        out: dict[str, Any] = {
            "platform": "",
            "site_name": "",
            "site_key": "",
            "site_id": "",
            "library_name": "",
            "library_id": "",
            "library_web_url": "",
        }
        if side not in ("Source", "Destination"):
            return out
        if not getattr(self, "planning_inputs", None):
            return out
        plat = self.source_platform_combo if side == "Source" else self.dest_platform_combo
        if plat is not None:
            try:
                out["platform"] = str(plat.currentData() or plat.currentText() or "").strip()
            except Exception:
                out["platform"] = ""
        site_sel = self.planning_inputs.get(f"{side} Site")
        lib_sel = self.planning_inputs.get(f"{side} Library")
        try:
            s_data = site_sel.currentData() if site_sel is not None else None
        except Exception:
            s_data = None
        try:
            l_data = lib_sel.currentData() if lib_sel is not None else None
        except Exception:
            l_data = None
        if isinstance(s_data, dict):
            out["site_name"] = str(s_data.get("name") or "").strip()
            out["site_key"] = str(s_data.get("site_key") or s_data.get("key") or "").strip()
            out["site_id"] = str(s_data.get("id") or "").strip()
        if isinstance(l_data, dict):
            out["library_name"] = str(l_data.get("name") or "").strip()
            out["library_id"] = str(l_data.get("id") or "").strip()
            out["library_web_url"] = str(l_data.get("webUrl") or l_data.get("web_url") or "").strip()
        return out

    def _build_workspace_snapshot_payload(self, *, trigger_phase: str = "") -> dict[str, Any]:
        """Full workspace snapshot sidecar: planning context, Graph row footprint, linkage audit (same as banner)."""
        state = self._draft_shell_state if isinstance(self._draft_shell_state, SessionState) else SessionState()
        audit = self._audit_planned_moves_graph_destination_identity()
        rows = self._build_memory_allocation_rows()
        allocation_graph_identity = [
            {
                "RequestId": str(getattr(r, "RequestId", "") or ""),
                "SourceDriveId": str(getattr(r, "SourceDriveId", "") or ""),
                "SourceItemId": str(getattr(r, "SourceItemId", "") or ""),
                "DestinationDriveId": str(getattr(r, "DestinationDriveId", "") or ""),
                "DestinationParentItemId": str(getattr(r, "DestinationParentItemId", "") or ""),
            }
            for r in rows
        ]
        session_echo = {
            "SourceBrowseMode": str(getattr(state, "SourceBrowseMode", "") or ""),
            "DestinationBrowseMode": str(getattr(state, "DestinationBrowseMode", "") or ""),
            "SelectedSourceSite": str(getattr(state, "SelectedSourceSite", "") or ""),
            "SelectedSourceSiteKey": str(getattr(state, "SelectedSourceSiteKey", "") or ""),
            "SelectedSourceLibrary": str(getattr(state, "SelectedSourceLibrary", "") or ""),
            "SelectedSourceLibraryId": str(getattr(state, "SelectedSourceLibraryId", "") or ""),
            "SelectedDestinationSite": str(getattr(state, "SelectedDestinationSite", "") or ""),
            "SelectedDestinationSiteKey": str(getattr(state, "SelectedDestinationSiteKey", "") or ""),
            "SelectedDestinationLibrary": str(getattr(state, "SelectedDestinationLibrary", "") or ""),
            "SelectedDestinationLibraryId": str(getattr(state, "SelectedDestinationLibraryId", "") or ""),
        }
        graph_audit_stored = dict(audit)
        graph_audit_stored["phase"] = str(trigger_phase or "workspace_snapshot")
        graph_audit_stored["last_run_utc"] = datetime.now(timezone.utc).isoformat()
        dest_snap = list(getattr(state, "DestinationTreeSnapshot", []) or [])
        try:
            dest_tree_node_count = int(self._count_tree_snapshot_nodes(dest_snap))
        except Exception:
            dest_tree_node_count = -1
        return {
            "schema_version": WORKSPACE_SNAPSHOT_SCHEMA_VERSION,
            "snapshot_type": "workspace_full",
            "app_version": str(APP_VERSION or ""),
            "created_at": datetime.now(timezone.utc).isoformat(),
            "saved_trigger": str(trigger_phase or ""),
            "planning_context": {
                "source": self._planning_side_context_for_snapshot(side="Source"),
                "destination": self._planning_side_context_for_snapshot(side="Destination"),
                "session_echo": session_echo,
            },
            "allocation_graph_identity": allocation_graph_identity,
            "graph_linkage_audit": graph_audit_stored,
            # Mirror of SessionState.DestinationTreeSnapshot for startup merge when session JSON is stale/minimal.
            "destination_tree_snapshot": dest_snap,
            "destination_tree_snapshot_node_count": dest_tree_node_count,
            "destination_tree_snapshot_identity": {
                "drive_id": str(getattr(state, "DestinationTreeSnapshotIdentityDriveId", "") or ""),
                "library_id": str(getattr(state, "DestinationTreeSnapshotIdentityLibraryId", "") or ""),
                "library_name": str(getattr(state, "DestinationTreeSnapshotIdentityLibraryName", "") or ""),
                "site_id": str(getattr(state, "DestinationTreeSnapshotIdentitySiteId", "") or ""),
                "destination_snapshot_identity_inferred_from_legacy": bool(
                    getattr(state, "DestinationTreeSnapshotIdentityInferredFromLegacy", False)
                ),
            },
        }

    def _persist_workspace_snapshot_file(
        self, *, phase: str = "", allow_strip_allocation_graph: bool | None = None
    ) -> None:
        if self.memory_manager is None:
            return
        payload = self._build_workspace_snapshot_payload(trigger_phase=phase)
        _sr = f"workspace_snapshot:{phase}" if phase else "workspace_snapshot"
        if allow_strip_allocation_graph is not None:
            _strip = bool(allow_strip_allocation_graph)
        else:
            _strip = bool(getattr(self, "_allow_empty_planning_persist", False))
        self.memory_manager.write_workspace_snapshot(
            payload,
            allow_strip_allocation_graph=_strip,
            save_reason=_sr,
        )

    def _validate_imported_workspace_snapshot(self, snap: dict[str, Any]) -> list[str]:
        """Lightweight import checks; does not block load."""
        issues: list[str] = []
        if not isinstance(snap, dict):
            return ["snapshot_not_object"]
        sv = int(snap.get("schema_version", 0) or 0)
        if sv < 1:
            issues.append("missing_or_invalid_schema_version")
        if sv > WORKSPACE_SNAPSHOT_SCHEMA_VERSION:
            issues.append("schema_newer_than_app")
        st = str(snap.get("snapshot_type") or "").strip()
        if st and st != "workspace_full":
            issues.append(f"unexpected_snapshot_type:{st}")
        pc = snap.get("planning_context")
        if isinstance(pc, dict):
            for pole, key in (("source", "source"), ("destination", "destination")):
                pole_d = pc.get(pole)
                if not isinstance(pole_d, dict):
                    continue
                if str(pole_d.get("platform") or "").lower() == "sharepoint":
                    if not str(pole_d.get("library_id") or "").strip():
                        issues.append(f"missing_context:sharepoint_library_id:{key}")
        ga = snap.get("graph_linkage_audit")
        if isinstance(ga, dict):
            if int(ga.get("rows_missing_graph_ids") or 0) > 0:
                issues.append("embedded_audit:rows_missing_graph_ids")
            if int(ga.get("proposed_rows_missing_graph_ids") or 0) > 0:
                issues.append("embedded_audit:proposed_missing_graph_ids")
        agi = snap.get("allocation_graph_identity")
        if isinstance(agi, list):
            missing_dest = sum(
                1
                for x in agi
                if isinstance(x, dict)
                and (
                    not str(x.get("DestinationDriveId") or "").strip()
                    or not str(x.get("DestinationParentItemId") or "").strip()
                )
            )
            if missing_dest:
                issues.append(f"embedded_row_footprint:missing_destination_graph_ids:{missing_dest}")
        return issues

    def _finalize_import_workspace_snapshot_hydration(self, runtime_audit: dict[str, Any], *, source: str = "") -> None:
        """Log snapshot validation and compare embedded audit vs runtime after import."""
        if self.memory_manager is None:
            return
        snap = self.memory_manager.read_workspace_snapshot_optional()
        if not snap:
            return
        issues = self._validate_imported_workspace_snapshot(snap)
        log_info(
            "workspace_snapshot_import_validation",
            issues=issues,
            schema_version=snap.get("schema_version"),
            snapshot_type=snap.get("snapshot_type"),
            created_at=str(snap.get("created_at") or "")[:40],
            source=source,
        )
        if issues:
            for tag in ("schema_newer_than_app", "unexpected_snapshot_type"):
                if any(tag in i for i in issues):
                    log_warn("workspace_snapshot_import_validation_warn", issues=issues, source=source)
                    break
        emb = snap.get("graph_linkage_audit")
        if isinstance(emb, dict):
            log_info(
                "workspace_snapshot_audit_compare",
                embedded_rows_missing=int(emb.get("rows_missing_graph_ids") or 0),
                runtime_rows_missing=int(runtime_audit.get("rows_missing_graph_ids") or 0),
                embedded_proposed_missing=int(emb.get("proposed_rows_missing_graph_ids") or 0),
                runtime_proposed_missing=int(runtime_audit.get("proposed_rows_missing_graph_ids") or 0),
                source=source,
            )

    def _planning_persist_context(self, *, save_reason: str = "") -> dict[str, Any]:
        """Structured context for planning queue persist logs (memory + JSON guard)."""
        st = self._draft_shell_state if isinstance(self._draft_shell_state, SessionState) else SessionState()
        return {
            "startup_restore_in_progress": bool(getattr(self, "_pending_login_restore_args", None)),
            "memory_restore_in_progress": bool(getattr(self, "_memory_restore_in_progress", False)),
            "suppress_autosave": bool(getattr(self, "_suppress_autosave", False)),
            "planning_memory_clear_reason": str(getattr(self, "_planning_memory_clear_reason", "") or "")[:200],
            "selected_source_site_key_suffix": str(getattr(st, "SelectedSourceSiteKey", "") or "")[-40:],
            "selected_source_library_id_suffix": str(getattr(st, "SelectedSourceLibraryId", "") or "")[-32:],
            "selected_destination_site_key_suffix": str(getattr(st, "SelectedDestinationSiteKey", "") or "")[-40:],
            "selected_destination_library_id_suffix": str(getattr(st, "SelectedDestinationLibraryId", "") or "")[-32:],
            "save_reason": str(save_reason or "")[:240],
            "planned_moves_runtime_count": len(getattr(self, "planned_moves", None) or []),
            "proposed_folders_runtime_count": len(getattr(self, "proposed_folders", None) or []),
        }

    def _save_draft_shell(self, *, force: bool = False, include_workspace_ui: bool = False):
        if self.memory_manager is None:
            log_info("draft_save_skipped", reason="no_memory_manager", force=bool(force))
            return False

        if not self._destination_should_allow_draft_save_now(force=bool(force)):
            self._destination_startup_shell_persistence_pending_dirty = True
            log_info(
                "destination_draft_save_deferred_startup_shell_active",
                reason="graph_destination_startup_shell",
                pending_dirty=1,
            )
            return False

        if self._memory_restore_in_progress:
            if not force:
                log_info("Draft save suppressed while restore is in progress.", autosave_suppressed=True)
                log_info(
                    "draft_save_skipped",
                    reason="restore_in_progress",
                    suppression_flag="memory_restore_in_progress",
                    force=bool(force),
                )
                return False
            log_info("Forced draft save allowed while restore is still in progress.", autosave_forced=True)

        if self._suppress_autosave and not force:
            log_info("Draft save suppressed until restore completes.", autosave_suppressed=True)
            log_info(
                "draft_save_skipped",
                reason="suppress_autosave",
                suppression_flag="suppress_autosave",
                force=bool(force),
            )
            return False

        try:
            if not self._ensure_active_draft_session():
                log_info("draft_save_skipped", reason="no_active_draft_session", force=bool(force))
                return False

            log_info(
                "draft_save_attempt",
                force=bool(force),
                include_workspace_ui=bool(include_workspace_ui),
            )
            self._destination_save_in_progress = True
            try:
                if bool(getattr(self, "_destination_descendant_snapshot_dirty_pending", False)):
                    self._destination_flush_descendant_snapshot_dirty_batch(
                        "before_save",
                        force=True,
                        skip_scroll_guard=True,
                    )
                    log_info("destination_descendant_snapshot_dirty_flush_before_save")
            except Exception as exc:
                self._log_restore_exception("destination_descendant_snapshot_dirty_flush_before_save_hook", exc)
            self._destination_draft_save_destination_snapshot_override = None
            try:
                _preflight = self._destination_force_live_destination_snapshot_for_session_persist(
                    reason="draft_save_preflight"
                )
                self._destination_draft_save_destination_snapshot_override = list(_preflight or [])
            except Exception as exc:
                self._log_restore_exception("destination_draft_save_live_snapshot_preflight", exc)
                self._destination_draft_save_destination_snapshot_override = None

            _shut = getattr(self, "_application_shutting_down", False)
            _t_build = time.perf_counter() if _shut else None
            _save_ctx = f"draft_save force={bool(force)} include_workspace_ui={bool(include_workspace_ui)}"
            state = self._build_current_draft_shell_state(
                include_workspace_ui=include_workspace_ui,
                save_reason=_save_ctx,
            )
            if include_workspace_ui:
                self._destination_branch_forensic_log(
                    "save_draft_shell_built_state_snapshot",
                    snapshots=list(state.DestinationTreeSnapshot or []),
                )
            if _t_build is not None:
                _dn = -1
                if include_workspace_ui:
                    try:
                        _dn = int(self._count_tree_snapshot_nodes(list(state.DestinationTreeSnapshot or [])))
                    except Exception:
                        _dn = -1
                log_info(
                    "shutdown_trace",
                    event="draft_shell_built_state",
                    elapsed_ms=round((time.perf_counter() - _t_build) * 1000.0, 2),
                    include_workspace_ui=include_workspace_ui,
                    destination_snapshot_nodes=_dn,
                )
                if include_workspace_ui:
                    try:
                        _snap_n = int(self._count_tree_snapshot_nodes(list(state.DestinationTreeSnapshot or [])))
                        _mn_post = int(self._count_destination_model_non_placeholder_nodes())
                        _pre_np = getattr(self, "_destination_shutdown_capture_pre_drain_model_np", None)
                        _pre_int = int(_pre_np) if _pre_np is not None else None
                        log_info(
                            "destination_shutdown_capture_persist_forensic",
                            destination_snapshot_recursive_nodes=int(_snap_n),
                            model_non_placeholder_after_capture=int(_mn_post),
                            pre_drain_model_non_placeholder=_pre_int,
                            materialization_improved_nodes=(
                                int(_mn_post) - int(_pre_int) if _pre_int is not None else None
                            ),
                            bounded_shutdown_capture_drain_ran=_pre_int is not None,
                        )
                    except Exception:
                        pass
                    try:
                        delattr(self, "_destination_shutdown_capture_pre_drain_model_np")
                    except Exception:
                        pass
            self._draft_shell_state = state
            self._draft_shell_raw = state.to_dict()
            self.active_draft_session_id = state.DraftId
            try:
                self._log_destination_snapshot_persist_validation(state, phase="draft_save")
            except Exception as exc:
                self._log_restore_exception("draft_save_snapshot_validation", exc)
            allocation_rows = self._build_memory_allocation_rows()
            proposed_rows = self._build_memory_proposed_folders()
            _t_mem = time.perf_counter() if _shut else None
            log_info(
                "draft_save_executed",
                force=bool(force),
                include_workspace_ui=bool(include_workspace_ui),
                draft_id=str(getattr(state, "DraftId", "") or "")[:80],
            )
            _persist_ctx = self._planning_persist_context(save_reason=_save_ctx)
            _explicit_empty = bool(getattr(self, "_allow_empty_planning_persist", False))
            _workspace_sidecar_allow_strip_graph = bool(_explicit_empty)
            self.memory_manager.save_allocations(
                allocation_rows,
                allow_empty_planning_persist=_explicit_empty,
                save_reason=_save_ctx,
                persist_context=_persist_ctx,
            )
            self.memory_manager.save_proposed(
                proposed_rows,
                allow_empty_planning_persist=_explicit_empty,
                save_reason=_save_ctx,
                persist_context=_persist_ctx,
            )
            self._allow_empty_planning_persist = False
            self._planning_memory_clear_reason = ""
            self._log_draft_shell_selector_fields(
                "save_session_selector_fields",
                state=state,
                include_workspace_ui=bool(include_workspace_ui),
                save_reason=_save_ctx,
            )
            self.memory_manager.save_session(state)
            self.memory_manager.refresh_manifest(
                draft_id=state.DraftId,
                fingerprint=state.SessionFingerprint,
                status="Healthy",
            )
            log_info(
                "draft_save_success",
                timestamp=time.time(),
                draft_id=str(getattr(state, "DraftId", "") or "")[:80],
                force=bool(force),
                include_workspace_ui=bool(include_workspace_ui),
            )
            if _shut and include_workspace_ui:
                try:
                    _final_snap_n = int(self._count_tree_snapshot_nodes(list(state.DestinationTreeSnapshot or [])))
                    _final_mn = int(self._count_destination_model_non_placeholder_nodes())
                    log_info(
                        "destination_shutdown_save_final_parity",
                        final_saved_destination_snapshot_recursive_nodes=int(_final_snap_n),
                        live_model_non_placeholder_nodes=int(_final_mn),
                        dirty_flag_state=bool(getattr(self, "_destination_tree_snapshot_dirty_for_persist", False)),
                        tick_running_state=bool(getattr(self, "_destination_descendant_apply_tick_running", False)),
                    )
                    if _final_snap_n != _final_mn:
                        log_info(
                            "destination_snapshot_shutdown_count_mismatch",
                            phase="post_save_session_json",
                            final_saved_destination_snapshot_recursive_nodes=int(_final_snap_n),
                            live_model_non_placeholder_nodes=int(_final_mn),
                            note="compare_recursive_snapshot_to_model_np; investigate structural or capture gaps",
                        )
                except Exception:
                    pass
            if include_workspace_ui and self._destination_branch_forensic_enabled():
                mmp = getattr(self.memory_manager, "paths", {}) or {}
                log_info(
                    "destination_branch_forensic",
                    stage="close_save_targets",
                    session_state_write_path=str(mmp.get("session") or ""),
                    workspace_sidecar_write_path=str(mmp.get("workspace_snapshot") or ""),
                    destination_snapshot_nodes=int(
                        self._count_tree_snapshot_nodes(list(state.DestinationTreeSnapshot or []))
                    ),
                )
            if _t_mem is not None:
                log_info(
                    "shutdown_trace",
                    event="draft_shell_memory_persist",
                    elapsed_ms=round((time.perf_counter() - _t_mem) * 1000.0, 2),
                )
            log_info(
                "Draft shell saved.",
                draft_id=state.DraftId,
                workspace=state.LastWorkspace,
                allocation_count=len(allocation_rows),
                proposed_count=len(proposed_rows),
            )
            if include_workspace_ui:
                _t_ws = time.perf_counter() if _shut else None
                try:
                    self._persist_workspace_snapshot_file(
                        phase="draft_save_include_workspace_ui",
                        allow_strip_allocation_graph=_workspace_sidecar_allow_strip_graph,
                    )
                except Exception as snap_exc:
                    log_warn(
                        "workspace_snapshot_write_failed",
                        phase="draft_save_include_workspace_ui",
                        error=str(snap_exc),
                    )
                finally:
                    if _t_ws is not None:
                        log_info(
                            "shutdown_trace",
                            event="draft_shell_workspace_sidecar_file",
                            elapsed_ms=round((time.perf_counter() - _t_ws) * 1000.0, 2),
                        )
                try:
                    _sess_w = int(self._count_tree_snapshot_nodes(list(state.DestinationTreeSnapshot or [])))
                    _ws_opt = self.memory_manager.read_workspace_snapshot_optional()
                    _side_w = int(
                        self._count_tree_snapshot_nodes(list((_ws_opt or {}).get("destination_tree_snapshot") or []))
                    )
                    log_info(
                        "snapshot_persist_forensic",
                        session_json_destination_snapshot_count_written=int(_sess_w),
                        workspace_sidecar_destination_snapshot_count_written=int(_side_w),
                        session_json_destination_snapshot_top_level_written=len(list(state.DestinationTreeSnapshot or [])),
                        workspace_sidecar_destination_snapshot_top_level_written=(
                            len(list((_ws_opt or {}).get("destination_tree_snapshot") or []))
                        ),
                    )
                except Exception:
                    pass
            if _shut and include_workspace_ui:
                log_info(
                    "destination_shutdown_final_save_complete",
                    phase="draft_shell_persist_including_sidecar_attempt",
                )
            if bool(include_workspace_ui) or bool(getattr(self, "_explicit_session_save_user_triggered", False)):
                self._session_user_edited_unsaved = False
                self._clear_planning_user_checkpoint()
            self._update_window_user_dirty_title_suffix()
            return True
        except Exception as exc:
            log_warn("Draft shell save failed.", error=str(exc))
            if getattr(self, "_application_shutting_down", False):
                log_info(
                    "destination_shutdown_final_save_blocked",
                    error_excerpt=str(exc)[:400],
                )
            return False
        finally:
            self._destination_save_in_progress = False
            self._destination_draft_save_destination_snapshot_override = None

    def _on_explicit_session_save_action(self) -> None:
        log_info("save_ui_action_triggered", source="overflow_menu")
        if getattr(self, "memory_manager", None) is None:
            QMessageBox.information(self, "Save", "Session save is not available (memory store missing).")
            return
        self._explicit_session_save_user_triggered = True
        log_info("explicit_session_save_started", include_workspace_ui=True)
        ok = False
        try:
            if bool(getattr(self, "_destination_descendant_snapshot_dirty_pending", False)):
                try:
                    self._destination_flush_descendant_snapshot_dirty_batch(
                        "before_explicit_save",
                        force=True,
                        skip_scroll_guard=True,
                    )
                except Exception as exc:
                    self._log_restore_exception("explicit_session_save_descendant_flush", exc)
            ok = bool(self._save_draft_shell(force=True, include_workspace_ui=True))
        finally:
            self._explicit_session_save_user_triggered = False
        try:
            _st = self._draft_shell_state
            _ds = list(_st.DestinationTreeSnapshot or []) if isinstance(_st, SessionState) else []
            _sn = int(self._count_tree_snapshot_nodes(_ds))
        except Exception:
            _sn = -1
        if ok:
            self._session_user_edited_unsaved = False
            self._clear_planning_user_checkpoint()
            self._update_window_user_dirty_title_suffix()
            self._destination_startup_shell_persistence_pending_dirty = False
        log_info(
            "explicit_session_save_completed",
            saved_nodes=int(_sn),
            dirty_cleared=bool(ok and not self._session_user_edited_unsaved),
        )
        if ok:
            QMessageBox.information(self, "Save", "Session saved.")
        else:
            QMessageBox.warning(self, "Save", "Save did not complete; see logs for details.")

    def _handle_export_draft(self):
        if self.memory_manager is None:
            QMessageBox.information(self, "Export Draft", "Draft export is not available right now.")
            return

        try:
            if bool(getattr(self, "_destination_descendant_snapshot_dirty_pending", False)):
                try:
                    self._destination_flush_descendant_snapshot_dirty_batch(
                        "before_export",
                        force=True,
                        skip_scroll_guard=True,
                    )
                    log_info("destination_descendant_snapshot_dirty_flush_before_export")
                except Exception as exc:
                    self._log_restore_exception("destination_descendant_snapshot_dirty_flush_before_export_hook", exc)
            if self._memory_restore_complete:
                self._save_draft_shell(force=True)
            try:
                self._persist_workspace_snapshot_file(phase="manual_export")
            except Exception as snap_exc:
                log_warn("workspace_snapshot_write_failed", phase="manual_export", error=str(snap_exc))
            default_destination = self.memory_manager.export_bundle(reason="Manual Export")
            default_zip = self.memory_manager.export_bundle_zip(default_destination)
            custom_zip_path, _ = QFileDialog.getSaveFileName(
                self,
                "Save Draft Zip Copy As",
                str(default_zip),
                "Draft Zip Bundle (*.zip)",
            )
            custom_zip_destination = None
            if custom_zip_path:
                custom_zip_destination = Path(custom_zip_path)
                if custom_zip_destination.suffix.lower() != ".zip":
                    custom_zip_destination = custom_zip_destination.with_suffix(".zip")
                self.memory_manager.export_bundle_zip(default_destination, custom_zip_destination)
            log_info(
                "Draft export completed.",
                default_destination=str(default_destination),
                default_zip=str(default_zip),
                custom_zip_destination=str(custom_zip_destination) if custom_zip_destination else "",
            )
            if custom_zip_destination is not None:
                QMessageBox.information(
                    self,
                    "Export Draft",
                    f"Draft exported to default folder:\n{default_destination}\n\n"
                    f"Default zip created at:\n{default_zip}\n\n"
                    f"Additional zip copy saved to:\n{custom_zip_destination}",
                )
            else:
                QMessageBox.information(
                    self,
                    "Export Draft",
                    f"Draft exported to default folder:\n{default_destination}\n\n"
                    f"Default zip created at:\n{default_zip}",
                )
        except Exception as exc:
            log_error("Draft export failed.", error=str(exc))
            QMessageBox.warning(self, "Export Draft", "Could not export the draft.")

    def _planned_moves_serializable_for_backup(self) -> list:
        """Best-effort JSON round-trip of runtime ``planned_moves`` for recovery tooling."""
        out: list = []
        for move in self.planned_moves:
            if not isinstance(move, dict):
                continue
            try:
                out.append(json.loads(json.dumps(move, default=str)))
            except Exception:
                out.append(
                    {
                        "_serialization_note": "partial",
                        "source_path": str(move.get("source_path", "") or ""),
                        "destination_path": str(move.get("destination_path", "") or ""),
                    }
                )
        return out

    def _build_draft_reset_backup_payload(self) -> dict:
        """In-memory draft source of truth: session shell, persisted allocation rows, proposed, runtime moves."""
        state = self._build_current_draft_shell_state(include_workspace_ui=True)
        allocations = [row.to_dict() for row in self._build_memory_allocation_rows()]
        proposed = [pf.to_dict() for pf in self._build_memory_proposed_folders()]
        return {
            "schema_version": 1,
            "kind": "draft_reset_backup",
            "created_utc": datetime.utcnow().isoformat(),
            "draft_id": self.active_draft_session_id or "",
            "session": state.to_dict(),
            "allocations": allocations,
            "proposed_folders": proposed,
            "planned_moves": self._planned_moves_serializable_for_backup(),
        }

    def _apply_draft_reset_after_backup(self) -> None:
        """Clear draft memory, reset planning trees and selectors (factory-style), persist a new empty session."""
        pre_pm = len(self.planned_moves)
        pre_pf = len(self.proposed_folders)
        log_info(
            "DRAFTRESET",
            event="apply_reset_pre_counts",
            pre_reset_planned_moves_count=pre_pm,
            pre_reset_proposed_folders_count=pre_pf,
        )
        self._clear_runtime_draft_state(refresh_ui=False)
        self.planned_moves = []
        self._factory_reset_clear_snapshot_ephemeral_bundle()
        dpt = getattr(self, "_deferred_planning_refresh_timer", None)
        if dpt is not None:
            dpt.stop()
        self._deferred_planning_refresh_pending = False
        self._deferred_planning_refresh_reasons = []
        self._deferred_source_projection_paths = set()
        self._source_projection_refresh_scheduled = False
        self._source_projection_refresh_paths = set()
        self._invalidate_projection_lookup_caches(bump_generation=True)
        self._cancel_destination_future_async_projection("draft_factory_reset")
        self._destination_expand_all_after_full_tree = False
        self.reset_root_panels()
        self.populate_planning_selectors(
            list(getattr(self, "discovered_sites", None) or []),
            auto_load_initial=False,
        )
        self._set_planning_site_selectors_no_selection()
        self._reset_planning_trees_to_select_library_prompt()
        self._refresh_planning_loading_banner()
        self._clear_execution_manifest_for_workspace_reset()
        fresh = self._build_current_draft_shell_state(include_workspace_ui=True)
        fresh.DraftId = self._create_new_draft_session_id()
        fresh.CreatedUtc = datetime.utcnow().isoformat()
        fresh.LastSavedUtc = fresh.CreatedUtc
        operator_upn = self.current_session_context.get("operator_upn", "")
        tenant_domain = self.current_session_context.get("tenant_domain", "")
        fresh.SessionFingerprint = f"{operator_upn}|{tenant_domain}".strip("|")
        if not fresh.DraftName:
            op = self.current_session_context.get("operator_display_name", "") or "Planning Session"
            fresh.DraftName = f"{op} Draft"
        self.active_draft_session_id = fresh.DraftId
        self._draft_shell_state = fresh
        self._draft_shell_raw = fresh.to_dict()

        _persist = self._planning_persist_context(save_reason="apply_draft_reset_after_backup_new_session")
        self.memory_manager.save_allocations(
            [],
            allow_empty_planning_persist=True,
            save_reason="apply_draft_reset_after_backup_new_session",
            persist_context=_persist,
        )
        self.memory_manager.save_proposed(
            [],
            allow_empty_planning_persist=True,
            save_reason="apply_draft_reset_after_backup_new_session",
            persist_context=_persist,
        )
        self.memory_manager.save_session(fresh)
        self.memory_manager.refresh_manifest(
            draft_id=fresh.DraftId,
            fingerprint=fresh.SessionFingerprint,
            status="Healthy",
        )
        self._suppress_autosave = False
        self._rebuild_submission_visual_cache()
        self.refresh_planned_moves_table()
        if getattr(self, "planned_moves_table", None) is not None:
            self.planned_moves_table.clearSelection()
        self.clear_selection_details()
        self.update_progress_summaries()
        if getattr(self, "planned_moves_status", None) is not None:
            self.planned_moves_status.setText("Workspace reset: choose source and destination libraries, then plan.")
        source_traceability_cleared = False
        if getattr(self, "source_tree_widget", None) is not None:
            self._refresh_source_projection("draft_reset_source_reconcile")
            self.source_tree_widget.viewport().update()
            source_traceability_cleared = True
        dest_materialize_return = -1
        destination_projection_cleared = False
        try:
            raw_ret = self._apply_destination_planning_overlays(
                "draft_reset_immediate",
                allow_defer=False,
                prefer_chunked_projection=False,
            )
            dest_materialize_return = int(raw_ret or 0)
            destination_projection_cleared = True
        except Exception as exc:
            log_warn(
                "DRAFTRESET",
                event="destination_immediate_materialize_failed",
                error=str(exc),
            )
        # Empty workspace: draft_reset_immediate already ran a full synchronous destination bind.
        # Scheduling deferred materialization here forced a second chunked projection pass and
        # redundant branch expansion (major latency) with no planned rows to overlay.
        self._set_tree_status_message("destination", "Destination structure ready.", loading=False)
        log_info(
            "destination_phase_timing",
            phase="draft_reset_skip_redundant_deferred_materialize",
            reason="empty_workspace_after_reset",
            planned_moves=0,
            proposed_folders=0,
        )
        if getattr(self, "destination_tree_widget", None) is not None:
            self.destination_tree_widget.viewport().update()
        log_info(
            "DRAFTRESET",
            event="apply_reset_post_baseline",
            post_reset_planned_moves_count=len(self.planned_moves),
            post_reset_proposed_folders_count=len(self.proposed_folders),
            source_traceability_cleared=source_traceability_cleared,
            destination_projection_cleared=destination_projection_cleared,
            destination_materialize_return=dest_materialize_return,
            planned_moves_table_cleared=True,
            cache_invalidation_done=True,
            factory_workspace_reset=True,
        )
        log_info("factory_reset", planned_moves=len(self.planned_moves))

    def _factory_reset_clear_snapshot_ephemeral_bundle(self) -> None:
        """Remove snapshot-pipeline temp bundle dir and drop the handle (factory / full workspace reset)."""
        import shutil

        ep = getattr(self, "_snapshot_pipeline_ephemeral_bundle_dir", None)
        if not ep:
            return
        try:
            shutil.rmtree(str(ep), ignore_errors=True)
        finally:
            self._snapshot_pipeline_ephemeral_bundle_dir = None

    @staticmethod
    def _qt_worker_is_running(worker) -> bool:
        try:
            return worker is not None and worker.isRunning()
        except RuntimeError:
            return False

    @staticmethod
    def _root_load_worker_running(win, panel_key: str) -> bool:
        entry = (getattr(win, "root_load_workers", None) or {}).get(panel_key) or {}
        return MainWindow._qt_worker_is_running(entry.get("worker"))

    @staticmethod
    def _any_folder_load_worker_running(win) -> bool:
        for entry in (getattr(win, "folder_load_workers", None) or {}).values():
            if MainWindow._qt_worker_is_running((entry or {}).get("worker")):
                return True
        return False

    def _memory_restore_async_busy_for_reset_draft(self) -> bool:
        """True while tree loads, projection binds, or expand-all could still be running."""
        if getattr(self, "_memory_ui_rebind_in_progress", False):
            return True
        if getattr(self, "_root_tree_bind_in_progress", False):
            return True
        if MainWindow._root_load_worker_running(self, "source") or MainWindow._root_load_worker_running(
            self, "destination"
        ):
            return True
        if MainWindow._any_folder_load_worker_running(self):
            return True
        pending = getattr(self, "pending_folder_loads", None) or {}
        if pending.get("source") or pending.get("destination"):
            return True
        if len(getattr(self, "_destination_restore_materialization_queue", []) or []):
            return True
        if len(getattr(self, "_source_restore_materialization_queue", []) or []):
            return True
        if getattr(self, "_destination_chunked_bind_state", None) is not None:
            return True
        if getattr(self, "_destination_future_bind_sync_active", False):
            return True
        if getattr(self, "_destination_future_projection_async_state", None) is not None:
            return True
        if getattr(self, "_destination_snapshot_chunked_restore_active", False):
            return True
        expand_pending = getattr(self, "_expand_all_pending", None) or {}
        if expand_pending.get("source") or expand_pending.get("destination"):
            return True
        if bool(getattr(self, "_lazy_destination_projection_pending_reason", "")):
            return True
        return False

    def _reset_draft_memory_restore_diagnostics(self) -> dict:
        """Structured snapshot for logs when Reset Draft is blocked (see DRAFTRESET)."""
        workers = getattr(self, "root_load_workers", None) or {}
        pending = getattr(self, "pending_folder_loads", None) or {}
        src_root = workers.get("source") or {}
        dst_root = workers.get("destination") or {}
        src_w = src_root.get("worker")
        dst_w = dst_root.get("worker")

        return {
            "memory_restore_in_progress": bool(getattr(self, "_memory_restore_in_progress", False)),
            "memory_ui_rebind_in_progress": bool(getattr(self, "_memory_ui_rebind_in_progress", False)),
            "root_tree_bind_in_progress": bool(getattr(self, "_root_tree_bind_in_progress", False)),
            "source_root_worker_registered": bool(src_root),
            "source_root_worker_running": MainWindow._qt_worker_is_running(src_w),
            "destination_root_worker_registered": bool(dst_root),
            "destination_root_worker_running": MainWindow._qt_worker_is_running(dst_w),
            "folder_workers_running": MainWindow._any_folder_load_worker_running(self),
            "pending_source_folder_loads": len(pending.get("source", set()) or set()),
            "pending_destination_folder_loads": len(pending.get("destination", set()) or set()),
            "unresolved_proposed": self._unresolved_proposed_queue_size(),
            "unresolved_allocation": self._unresolved_allocation_queue_size(),
            "destination_materialization_queue": len(getattr(self, "_destination_restore_materialization_queue", []) or []),
            "source_materialization_queue": len(getattr(self, "_source_restore_materialization_queue", []) or []),
            "restore_destination_overlay_pending": bool(getattr(self, "_restore_destination_overlay_pending", False)),
            "destination_root_prime_pending": bool(getattr(self, "_destination_root_prime_pending", False)),
            "destination_chunked_bind_state": getattr(self, "_destination_chunked_bind_state", None) is not None,
            "destination_future_bind_sync_active": bool(getattr(self, "_destination_future_bind_sync_active", False)),
            "destination_future_projection_async_state": getattr(self, "_destination_future_projection_async_state", None)
            is not None,
            "destination_snapshot_chunked_restore_active": bool(
                getattr(self, "_destination_snapshot_chunked_restore_active", False)
            ),
            "expand_all_pending_source": bool((getattr(self, "_expand_all_pending", None) or {}).get("source")),
            "expand_all_pending_destination": bool((getattr(self, "_expand_all_pending", None) or {}).get("destination")),
            "lazy_destination_projection_pending_reason": str(
                getattr(self, "_lazy_destination_projection_pending_reason", "") or ""
            )[:200],
        }

    def _clear_stale_pending_folder_loads_if_no_workers(self) -> None:
        """Drop stuck pending-folder keys when no root/folder workers are running (unblocks Reset Draft)."""
        if MainWindow._root_load_worker_running(self, "source") or MainWindow._root_load_worker_running(
            self, "destination"
        ):
            return
        if MainWindow._any_folder_load_worker_running(self):
            return
        pending = getattr(self, "pending_folder_loads", None) or {}
        ps = pending.get("source", set()) or set()
        pd = pending.get("destination", set()) or set()
        if not ps and not pd:
            return
        log_warn(
            "DRAFTRESET",
            event="stale_pending_folder_loads_cleared_idle_workers",
            pending_source=len(ps),
            pending_destination=len(pd),
        )
        pending.setdefault("source", set()).clear()
        pending.setdefault("destination", set()).clear()

    def _reset_draft_recover_stale_async_state_if_no_workers(self) -> None:
        """Clear stuck planning flags when no load workers are running (fixes endless Reset Draft wait)."""
        if MainWindow._root_load_worker_running(self, "source") or MainWindow._root_load_worker_running(
            self, "destination"
        ):
            return
        if MainWindow._any_folder_load_worker_running(self):
            return

        cleared: list[str] = []
        if getattr(self, "_memory_ui_rebind_in_progress", False):
            self._memory_ui_rebind_in_progress = False
            cleared.append("memory_ui_rebind_in_progress")
        if getattr(self, "_root_tree_bind_in_progress", False):
            self._root_tree_bind_in_progress = False
            cleared.append("root_tree_bind_in_progress")
        if len(getattr(self, "_destination_restore_materialization_queue", []) or []):
            self._destination_restore_materialization_queue = []
            cleared.append("destination_restore_materialization_queue")
        if len(getattr(self, "_source_restore_materialization_queue", []) or []):
            self._source_restore_materialization_queue = []
            cleared.append("source_restore_materialization_queue")
        if getattr(self, "_destination_chunked_bind_state", None) is not None:
            self._destination_chunked_bind_state = None
            cleared.append("destination_chunked_bind_state")
        if getattr(self, "_destination_future_bind_sync_active", False):
            self._destination_future_bind_sync_active = False
            cleared.append("destination_future_bind_sync_active")
        if getattr(self, "_destination_snapshot_chunked_restore_active", False):
            self._destination_snapshot_chunked_restore_active = False
            cleared.append("destination_snapshot_chunked_restore_active")
        ep = getattr(self, "_expand_all_pending", None) or {}
        if ep.get("source") or ep.get("destination"):
            self._expand_all_pending["source"] = False
            self._expand_all_pending["destination"] = False
            cleared.append("expand_all_pending")
        if bool(getattr(self, "_lazy_destination_projection_pending_reason", "")):
            setattr(self, "_lazy_destination_projection_pending_reason", "")
            cleared.append("lazy_destination_projection_pending_reason")
        if getattr(self, "_destination_future_projection_async_state", None) is not None:
            self._cancel_destination_future_async_projection("reset_draft_stale_async_recover")
            cleared.append("destination_future_projection_async_state")

        if cleared:
            log_warn(
                "DRAFTRESET",
                event="reset_draft_stale_async_flags_cleared",
                cleared_flags=cleared,
            )

    def _release_stalled_memory_restore_gate_for_reset_draft(self) -> None:
        """Clear bookkeeping flags that kept finalize from running when no async work remains."""
        log_info(
            "DRAFTRESET",
            event="stalled_memory_restore_gate_release",
            had_overlay_pending=bool(getattr(self, "_restore_destination_overlay_pending", False)),
        )
        self._restore_destination_overlay_pending = False
        setattr(self, "_destination_root_prime_pending", False)
        self._reset_unresolved_proposed_queue()
        self._reset_unresolved_allocation_queue()
        self._finalize_memory_restore_if_ready("reset_draft_stalled_gate_release")

    def _prepare_memory_restore_finalize_for_reset_workspace(self) -> None:
        """Clear stale destination bookkeeping so finalize can run (user confirmed Backup && Reset)."""
        if MainWindow._root_load_worker_running(self, "source") or MainWindow._root_load_worker_running(
            self, "destination"
        ):
            return
        if MainWindow._any_folder_load_worker_running(self):
            return
        for pk in ("source", "destination"):
            if (self.root_load_workers or {}).get(pk):
                self.root_load_workers.pop(pk, None)
                log_warn("DRAFTRESET", event="stale_root_worker_registry_cleared", panel_key=pk)
        self._destination_restore_materialization_queue = []
        self._restore_destination_overlay_pending = False
        setattr(self, "_destination_root_prime_pending", False)
        self._reset_unresolved_proposed_queue()
        self._reset_unresolved_allocation_queue()
        self.pending_folder_loads.setdefault("source", set()).clear()
        self.pending_folder_loads.setdefault("destination", set()).clear()
        self._destination_clear_graph_child_load_backlog()
        self._finalize_memory_restore_if_ready("reset_workspace_prepare_finalize")

    def _force_memory_restore_complete_after_reset_workspace_confirm(self) -> None:
        """Last resort when finalize still cannot clear the flag after user confirmed reset."""
        if not getattr(self, "_memory_restore_in_progress", False):
            return
        log_warn(
            "DRAFTRESET",
            event="memory_restore_finalize_forced_after_reset_workspace_confirm",
        )
        self._memory_restore_apply_finalize_success("reset_workspace_user_confirmed_force")

    def _handle_reset_draft(self) -> None:
        if self.memory_manager is None:
            QMessageBox.information(self, "Reset Workspace", "Draft storage is not available.")
            return
        if getattr(self, "_memory_restore_in_progress", False):
            self._finalize_memory_restore_if_ready("reset_draft_precheck")
        self._clear_stale_pending_folder_loads_if_no_workers()
        self._reset_draft_recover_stale_async_state_if_no_workers()
        if getattr(self, "_memory_restore_in_progress", False):
            self._finalize_memory_restore_if_ready("reset_draft_precheck_after_stale_recover")
        if getattr(self, "_memory_restore_in_progress", False) and self._memory_restore_async_busy_for_reset_draft():
            log_warn(
                "DRAFTRESET",
                event="reset_draft_blocked_precheck",
                **self._reset_draft_memory_restore_diagnostics(),
            )
            wait_box = QMessageBox(self)
            wait_box.setIcon(QMessageBox.Icon.Information)
            wait_box.setWindowTitle("Reset Workspace")
            wait_box.setText(
                "The workspace is still loading or reconciling your saved draft. "
                "Reset is paused until that finishes so your backup stays consistent."
            )
            wait_box.setInformativeText(
                "Most of the time this finishes within a minute or two after sign-in. "
                "If you have many planned moves, trees and projections can keep working for several minutes.\n\n"
                "If the window has looked fully idle (no loading in the trees) for more than about ten minutes "
                "and you still see this, install the latest build (it clears stuck planning flags when no loads "
                "are running), or close and restart the app.\n\n"
                "Technical detail is logged under your Ozlink console Logs folder "
                "(search the newest OzlinkConsole log for DRAFTRESET / reset_draft_blocked_precheck or "
                "reset_draft_stale_async_flags_cleared)."
            )
            wait_box.exec()
            return

        dlg = QMessageBox(self)
        dlg.setIcon(QMessageBox.Icon.Warning)
        dlg.setWindowTitle("Reset Workspace")
        dlg.setText(
            "This backs up your current draft, then performs a factory-style reset: "
            "new empty draft, cleared trees, and no site or library selected."
        )
        dlg.setInformativeText(
            "A timestamped backup is saved under your user Memory/Backups folder. "
            "You remain signed in to Microsoft 365; rediscover sites if needed, then pick "
            "source and destination sites and libraries again. "
            "The Execution page is cleared too (no manifest in memory; “last manifest” path is forgotten). "
            "Nothing else outside this app’s Memory folder is removed."
        )
        reset_btn = dlg.addButton("Backup && Reset Workspace", QMessageBox.ButtonRole.AcceptRole)
        dlg.addButton(QMessageBox.StandardButton.Cancel)
        dlg.setDefaultButton(QMessageBox.StandardButton.Cancel)
        dlg.exec()
        if dlg.clickedButton() != reset_btn:
            return

        if getattr(self, "_memory_restore_in_progress", False):
            self._finalize_memory_restore_if_ready("reset_draft_precheck_post_confirm")
        self._clear_stale_pending_folder_loads_if_no_workers()
        self._reset_draft_recover_stale_async_state_if_no_workers()
        if getattr(self, "_memory_restore_in_progress", False):
            self._finalize_memory_restore_if_ready("reset_draft_precheck_post_confirm_after_recover")
        if getattr(self, "_memory_restore_in_progress", False):
            if self._memory_restore_async_busy_for_reset_draft():
                QMessageBox.critical(
                    self,
                    "Reset Workspace",
                    "Memory restore became active before the backup could start. "
                    "Wait for trees and planning views to finish loading, then try again.",
                )
                return
            self._release_stalled_memory_restore_gate_for_reset_draft()
        if getattr(self, "_memory_restore_in_progress", False):
            self._prepare_memory_restore_finalize_for_reset_workspace()
        if getattr(self, "_memory_restore_in_progress", False):
            self._force_memory_restore_complete_after_reset_workspace_confirm()
        if getattr(self, "_memory_restore_in_progress", False):
            QMessageBox.critical(
                self,
                "Reset Workspace",
                "The workspace is still marked as restoring memory state and cannot be reset safely. "
                "Try again shortly, or restart the app if this persists.",
            )
            return

        log_info(
            "DRAFTRESET",
            event="backup_started",
            planned_moves_count=len(self.planned_moves),
            proposed_folders_count=len(self.proposed_folders),
        )
        backup_path = ""
        ac = pf = pm = 0
        try:
            if not self._ensure_active_draft_session():
                raise RuntimeError("Could not prepare an active draft session for backup.")
            payload = self._build_draft_reset_backup_payload()
            ac = len(payload.get("allocations") or [])
            pf = len(payload.get("proposed_folders") or [])
            pm = len(payload.get("planned_moves") or [])
            log_info(
                "DRAFTRESET",
                event="backup_payload_built",
                allocation_count=ac,
                proposed_count=pf,
                planned_moves_runtime_count=pm,
            )
            backup_path = str(self.memory_manager.save_draft_reset_backup(payload))
        except Exception as exc:
            log_warn(
                "DRAFTRESET",
                event="reset_aborted_backup_failed",
                error=str(exc),
            )
            QMessageBox.critical(
                self,
                "Reset Workspace",
                "Backup failed; the workspace was not reset.\n\n" + str(exc),
            )
            return

        log_info(
            "DRAFTRESET",
            event="backup_saved",
            backup_path=backup_path,
            restore_payload_counts=f"allocations={ac} proposed={pf} planned_moves_json={pm}",
        )
        log_info("DRAFTRESET", event="reset_started", backup_path=backup_path)
        try:
            self._apply_draft_reset_after_backup()
        except Exception as exc:
            log_error(
                "DRAFTRESET",
                event="reset_failed_after_backup",
                error=str(exc),
                backup_path=backup_path,
            )
            QMessageBox.critical(
                self,
                "Reset Workspace",
                "Backup was saved but clearing the workspace failed.\n"
                f"Backup path:\n{backup_path}\n\nError:\n{exc}",
            )
            return

        log_info(
            "DRAFTRESET",
            event="reset_completed",
            backup_path=backup_path,
            restore_payload_counts=f"allocations={ac} proposed={pf} planned_moves_json={pm}",
        )
        QMessageBox.information(
            self,
            "Reset Workspace",
            f"Workspace reset complete. Backup saved to:\n{backup_path}",
        )

    def _import_ok_trace_enabled(self) -> bool:
        v = str(os.environ.get("OZLINK_IMPORT_OK_TRACE", "") or "").strip().lower()
        return v in ("1", "true", "yes", "on")

    def _import_ok_trace(self, phase: str, **extra) -> None:
        if not self._import_ok_trace_enabled():
            return
        log_info("IMPORT_OK_TRACE", phase=phase, **extra)

    def _import_ok_timing(self, phase: str, t0: float, **extra) -> None:
        if not self._import_ok_trace_enabled():
            return
        ms = round((time.perf_counter() - t0) * 1000.0, 3)
        log_info("IMPORT_OK_TIMING", phase=phase, elapsed_ms=ms, **extra)

    def _run_after_import_success_dialog_idle(
        self,
        callback_name: str,
        fn,
        *,
        delay_ms: int = 50,
    ) -> None:
        """Run callback after a short delay and only once the import success dialog is closed."""
        delay_ms = max(1, int(delay_ms))
        t0 = time.perf_counter()

        def _tick() -> None:
            if bool(getattr(self, "_import_success_dialog_active", False)):
                self._import_ok_trace(
                    "deferred_work_waiting_for_import_dialog_close",
                    callback=callback_name,
                )
                QTimer.singleShot(delay_ms, _tick)
                return
            self._import_ok_trace(
                "deferred_work_dispatch",
                callback=callback_name,
                ms_since_schedule=round((time.perf_counter() - t0) * 1000.0, 3),
            )
            self._safe_invoke(callback_name, fn)

        QTimer.singleShot(delay_ms, _tick)

    def _migration_identity_preflight_from_ui(self) -> MigrationIdentityPreflight:
        inputs = getattr(self, "planning_inputs", None) or {}
        src_site_w = inputs.get("Source Site")
        dst_site_w = inputs.get("Destination Site")
        src_lib_w = inputs.get("Source Library")
        dst_lib_w = inputs.get("Destination Library")
        src_site_d = src_site_w.currentData() if src_site_w is not None else None
        dst_site_d = dst_site_w.currentData() if dst_site_w is not None else None
        src_lib_d = src_lib_w.currentData() if src_lib_w is not None else None
        dst_lib_d = dst_lib_w.currentData() if dst_lib_w is not None else None

        def _site_key(site: Any) -> str:
            if not isinstance(site, dict):
                return ""
            return str(site.get("site_key") or site.get("web_url") or site.get("id") or "").strip()

        def _site_id(site: Any) -> str:
            if not isinstance(site, dict):
                return ""
            return str(site.get("id") or "").strip()

        src_drv = str(src_lib_d.get("id", "")).strip() if isinstance(src_lib_d, dict) else ""
        dst_drv = str(dst_lib_d.get("id", "")).strip() if isinstance(dst_lib_d, dict) else ""
        src_lib_disp = src_lib_w.currentText().strip() if src_lib_w is not None else ""
        dst_lib_disp = dst_lib_w.currentText().strip() if dst_lib_w is not None else ""

        anchor_name = ""
        anchor_path_full = ""
        anchor_payload: dict[str, Any] | None = None
        try:
            anchor_path_full, anchor_payload = self._destination_visible_library_anchor_resolution()
            if anchor_path_full:
                norm = str(anchor_path_full).replace("/", "\\").strip()
                parts = [x for x in norm.split("\\") if x]
                if parts:
                    anchor_name = parts[-1]
        except Exception:
            anchor_name = ""

        item_id = ""
        row_drive = ""
        if isinstance(anchor_payload, dict):
            item_id = str(anchor_payload.get("id") or anchor_payload.get("graph_item_id") or "").strip()
            row_drive = str(anchor_payload.get("drive_id") or anchor_payload.get("library_id") or "").strip()
        anchor_drive = row_drive or dst_drv
        verified_utc = datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")
        path_only_binding = bool(anchor_path_full) and not bool(item_id)
        log_info(
            "destination_visible_anchor_resolved",
            destination_visible_anchor_item_id=str(item_id or "(none)"),
            destination_visible_anchor_display_path=str(anchor_path_full or "")[:500],
        )

        return MigrationIdentityPreflight(
            source_site_key=_site_key(src_site_d),
            source_site_id=_site_id(src_site_d),
            source_drive_id=src_drv,
            destination_site_key=_site_key(dst_site_d),
            destination_site_id=_site_id(dst_site_d),
            destination_drive_id=dst_drv,
            source_library_display_name=src_lib_disp,
            destination_library_display_name=dst_lib_disp,
            visible_destination_anchor=anchor_name,
            destination_anchor_item_id=item_id,
            destination_anchor_drive_id=anchor_drive,
            destination_anchor_display_path=str(anchor_path_full or ""),
            destination_anchor_path_verified_at_utc=verified_utc,
            destination_anchor_path_only_binding=path_only_binding,
        )

    def _draft_import_validate_migrated_interactive(self, bundle_dir: Path) -> bool:
        """Return True only if validation passes (optionally after user confirms rows_rejected / offline migration)."""
        conf_r = False
        conf_o = False
        while True:
            vr = validate_migrated_import_bundle(
                bundle_dir,
                user_confirmed_rows_rejected=conf_r,
                user_confirmed_offline_migration=conf_o,
            )
            if vr.ok:
                return True
            err = (vr.error or "").strip()
            friendly = user_message_for_migrated_validation_error(err)
            el = err.lower()
            if "rows_rejected" in el and "confirm" in el:
                r = QMessageBox.question(
                    self,
                    "Import Draft",
                    f"{friendly}\n\nDo you want to import this package anyway?",
                    QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                    QMessageBox.StandardButton.No,
                )
                if r == QMessageBox.StandardButton.Yes:
                    conf_r = True
                    continue
                log_info(
                    "migrated_package_restore_cancelled",
                    reason="rows_rejected_confirmation_declined",
                    folder=str(bundle_dir),
                )
                return False
            if "graph resolution disabled" in el or "offline" in el:
                # Offline / skip-graph migrations require explicit confirmation (see validate_migrated_import_bundle).
                r = QMessageBox.question(
                    self,
                    "Import Draft",
                    f"{friendly}\n\nDo you want to import this package anyway?",
                    QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                    QMessageBox.StandardButton.No,
                )
                if r == QMessageBox.StandardButton.Yes:
                    conf_o = True
                    continue
                log_info(
                    "migrated_package_restore_cancelled",
                    reason="offline_migration_confirmation_declined",
                    folder=str(bundle_dir),
                )
                return False
            QMessageBox.warning(self, "Import Draft", friendly or "Migrated package validation failed.")
            log_info(
                "migrated_package_restore_cancelled",
                reason="validation_failed",
                folder=str(bundle_dir),
            )
            return False

    def _show_migration_preflight_result_dialog(self, report: dict[str, Any], output_folder: Path) -> bool:
        """Show migration summary; return True if user chooses to import the migrated folder."""
        out_folder_s = str(Path(output_folder).resolve())
        log_info("migration_report_dialog_shown", output_folder=out_folder_s)
        dlg = QDialog(self)
        dlg.setWindowTitle("Legacy migration")
        dlg.resize(640, 420)
        lay = QVBoxLayout(dlg)
        txt = QTextEdit()
        txt.setReadOnly(True)
        txt.setPlainText(build_migration_report_summary_text(report))
        lay.addWidget(txt)
        row = QHBoxLayout()
        btn_cancel = QPushButton("Cancel")
        btn_open = QPushButton("Open report")
        btn_open_folder = QPushButton("Open migrated output folder")
        btn_save = QPushButton("Save report as…")
        btn_restore = QPushButton("Restore migrated backup")
        row.addWidget(btn_cancel)
        row.addStretch(1)
        row.addWidget(btn_open)
        row.addWidget(btn_open_folder)
        row.addWidget(btn_save)
        row.addWidget(btn_restore)
        lay.addLayout(row)
        out = {"go": False}

        def _open_report() -> None:
            log_info("migration_report_open_requested", output_folder=out_folder_s)
            md = output_folder / "LegacyMigrationReport.md"
            js = output_folder / "LegacyMigrationReport.json"
            p = md if md.is_file() else js
            if p.is_file():
                QDesktopServices.openUrl(QUrl.fromLocalFile(str(p.resolve())))
            else:
                QMessageBox.information(
                    dlg,
                    "Legacy migration",
                    "No LegacyMigrationReport.md or LegacyMigrationReport.json was found in the output folder.",
                )

        def _open_folder() -> None:
            log_info("migration_output_folder_open_requested", output_folder=out_folder_s)
            if not output_folder.is_dir():
                QMessageBox.warning(dlg, "Legacy migration", "The migrated output folder is not available.")
                return
            QDesktopServices.openUrl(QUrl.fromLocalFile(out_folder_s))

        def _save_report_as() -> None:
            log_info("migration_report_save_requested", output_folder=out_folder_s)
            md = output_folder / "LegacyMigrationReport.md"
            js = output_folder / "LegacyMigrationReport.json"
            if md.is_file():
                default_name = "LegacyMigrationReport.md"
                chosen_src = md
                filt = "Markdown report (*.md);;JSON report (*.json);;All files (*.*)"
            elif js.is_file():
                default_name = "LegacyMigrationReport.json"
                chosen_src = js
                filt = "JSON report (*.json);;Markdown report (*.md);;All files (*.*)"
            else:
                QMessageBox.information(
                    dlg,
                    "Legacy migration",
                    "No LegacyMigrationReport.md or LegacyMigrationReport.json was found to save.",
                )
                return
            dest, _sel = QFileDialog.getSaveFileName(
                dlg,
                "Save migration report as",
                str(output_folder / default_name),
                filt,
            )
            if not dest:
                return
            try:
                _shutil.copy2(str(chosen_src), dest)
                log_info("migration_report_saved", dest=str(Path(dest).resolve()))
            except OSError as exc:
                QMessageBox.warning(
                    dlg,
                    "Legacy migration",
                    f"Could not save the migration report:\n{exc}",
                )

        def _do_restore() -> None:
            log_info("migrated_package_restore_confirmed", output_folder=out_folder_s)
            out["go"] = True
            dlg.accept()

        def _on_dialog_finished(result: int) -> None:
            if result == int(QDialog.DialogCode.Accepted) and out.get("go"):
                return
            log_info("legacy_import_preflight_cancelled_after_report", output_folder=out_folder_s)
            log_info("migrated_package_restore_cancelled", output_folder=out_folder_s)

        btn_cancel.clicked.connect(dlg.reject)
        btn_open.clicked.connect(_open_report)
        btn_open_folder.clicked.connect(_open_folder)
        btn_save.clicked.connect(_save_report_as)
        btn_restore.clicked.connect(_do_restore)
        btn_restore.setDefault(True)
        dlg.finished.connect(_on_dialog_finished)
        if dlg.exec() != QDialog.DialogCode.Accepted:
            return False
        return bool(out["go"])

    def _show_non_modal_import_success_message(self, text: str) -> None:
        """Non-modal confirmation so the event loop keeps servicing timers (Graph enrichment, trees)."""
        box = QMessageBox(self)
        box.setWindowTitle("Import Draft")
        box.setIcon(QMessageBox.Icon.Information)
        box.setText(text)
        box.setStandardButtons(QMessageBox.StandardButton.Ok)
        box.setWindowModality(Qt.WindowModality.NonModal)
        try:
            box.setAttribute(Qt.WidgetAttribute.WA_DeleteOnClose, True)
        except Exception:
            pass
        t_show = time.perf_counter()
        self._import_success_dialog_active = True
        self._import_ok_trace("success_dialog_show")

        def _on_finished(result: int) -> None:
            self._import_success_dialog_active = False
            self._import_ok_timing(
                "success_dialog_finished",
                t_show,
                result=int(result),
                seconds_since_import_t0=(
                    round(time.perf_counter() - float(self._import_ok_trace_import_t0), 4)
                    if getattr(self, "_import_ok_trace_import_t0", None) is not None
                    else None
                ),
            )
            self._import_ok_trace("success_dialog_closed", result=int(result))

        box.finished.connect(_on_finished)
        box.show()

    def _handle_import_draft(self):
        if self.memory_manager is None:
            QMessageBox.information(self, "Import Draft", "Draft import is not available right now.")
            return

        self._graph_linkage_context_retry_count = 0
        self._graph_linkage_enrich_busy_skips = 0
        self._destination_deferred_reconcile_burst_pending = False
        self._reset_projection_delta_coalesce_state()
        _import_t0 = time.perf_counter()
        self._import_ok_trace_import_t0 = _import_t0
        self._import_ok_trace_graph_tick_logged = False
        self._import_ok_trace("import_handler_enter")
        source_file = ""
        source_folder = ""
        temp_dirs: list[Path] = []
        source_description = ""

        def _cleanup_import_temps() -> None:
            for d in temp_dirs:
                try:
                    _shutil.rmtree(str(d), ignore_errors=True)
                except Exception:
                    pass

        try:
            source_file, _ = QFileDialog.getOpenFileName(
                self,
                "Import Draft Zip Bundle",
                "",
                "Draft Zip Bundle (*.zip)",
            )
            bundle_dir: Path | None = None
            if source_file:
                td = Path(tempfile.mkdtemp(prefix="ozlink_draft_import_zip_"))
                temp_dirs.append(td)
                extract_root = td / "bundle"
                extract_root.mkdir(parents=True, exist_ok=True)
                with zipfile.ZipFile(Path(source_file), "r") as zf:
                    zf.extractall(extract_root)
                bundle_dir = extract_root
                source_description = source_file
            else:
                source_folder = QFileDialog.getExistingDirectory(self, "Import Draft Bundle Folder")
                if not source_folder:
                    self._import_ok_trace("import_handler_cancelled_no_folder")
                    return
                bundle_dir = Path(source_folder)
                source_description = source_folder

            _legacy_mig_root: Path | None = None
            _import_bundle_succeeded = False
            try:
                kind, meta = classify_import_bundle(bundle_dir)

                if kind == INVALID_UNKNOWN:
                    QMessageBox.warning(
                        self,
                        "Import Draft",
                        user_message_for_import_bundle_classification_error(str(meta.get("error") or "unknown")),
                    )
                    return

                self._migration_import_needs_review_rows = []

                if kind == RAW_LEGACY_EXPORT:
                    ident = self._migration_identity_preflight_from_ui()
                    if not migration_identity_complete(ident):
                        QMessageBox.warning(
                            self,
                            "Import Draft",
                            user_message_for_legacy_identity_incomplete(),
                        )
                        return
                    if not (
                        is_valid_migration_drive_id(ident.source_drive_id)
                        and is_valid_migration_drive_id(ident.destination_drive_id)
                    ):
                        QMessageBox.warning(
                            self,
                            "Import Draft",
                            user_message_for_placeholder_drive_ids(),
                        )
                        return
                    mig_parent = Path(tempfile.mkdtemp(prefix="ozlink_legacy_mig_out_"))
                    _legacy_mig_root = mig_parent
                    log_info(
                        "legacy_import_preflight_started",
                        bundle=str(bundle_dir),
                        source_drive_suffix=str(ident.source_drive_id or "")[-16:],
                        destination_drive_suffix=str(ident.destination_drive_id or "")[-16:],
                    )
                    connected = bool(self.current_session_context.get("connected"))
                    graph = getattr(self, "graph", None)
                    skip_g = not connected or (graph is None and connected)
                    res = migrate_legacy_backup_folder(
                        bundle_dir,
                        mig_parent,
                        identity=ident,
                        graph=graph,
                        skip_graph_resolution=skip_g,
                    )
                    if not res.ok:
                        log_info(
                            "legacy_import_preflight_failed",
                            error=str(res.error_message or "")[:400],
                            needs_identity=bool(getattr(res, "needs_identity_confirmation", False)),
                        )
                        try:
                            _shutil.rmtree(str(mig_parent), ignore_errors=True)
                        except Exception:
                            pass
                        _legacy_mig_root = None
                        QMessageBox.warning(
                            self,
                            "Import Draft",
                            res.error_message or "Legacy migration preflight failed.",
                        )
                        return
                    log_info("legacy_import_preflight_completed", output_folder=str(res.output_folder or ""))
                    rep = res.report if isinstance(res.report, dict) else {}
                    out_fold = res.output_folder
                    if out_fold is None or not self._show_migration_preflight_result_dialog(rep, Path(out_fold)):
                        return
                    bundle_dir = Path(out_fold)

                    kind = MIGRATED_LEGACY_PACKAGE

                if kind == MIGRATED_LEGACY_PACKAGE:
                    if not self._draft_import_validate_migrated_interactive(bundle_dir):
                        return
                    self._migration_import_needs_review_rows = load_migration_conflicts_for_review(bundle_dir)
                elif kind == MODERN_EXPORT:
                    self._migration_import_needs_review_rows = []

                self.memory_manager.import_bundle(bundle_dir)
                _import_bundle_succeeded = True
            finally:
                _cleanup_import_temps()
                if _import_bundle_succeeded and _legacy_mig_root is not None:
                    try:
                        _shutil.rmtree(str(_legacy_mig_root), ignore_errors=True)
                    except Exception:
                        pass

            self._import_ok_timing("after_bundle_import_io", _import_t0)
            self._import_rehydration_verify_pending = True
            self._import_tree_reload_retry_used = False
            self._close_post_import_graph_enrichment_generator()
            self._post_import_graph_enrich_run_id += 1
            self._hydrate_runtime_from_import_bundle_primary_memory()
            if self.memory_manager is not None:
                self.memory_manager.log_planning_recovery_hint_if_primary_empty_after_import()
            self._import_ok_timing("after_hydrate_runtime_from_import_bundle_primary_memory", _import_t0)
            _cand = self._memory_restore_candidate if isinstance(self._memory_restore_candidate, dict) else {}
            log_info(
                "planning_state_snapshot",
                phase="import_after_shell_load",
                planned_moves_count=len(self.planned_moves),
                proposed_folders_count=len(self.proposed_folders),
                restore_candidate_name=str(_cand.get("name", "") or ""),
                source=source_description,
            )
            _audit_import = self._audit_planned_moves_graph_destination_identity()
            log_info(
                "graph_linkage_audit",
                phase="import_after_shell_load",
                source=source_description,
                **self._graph_linkage_audit_for_log(_audit_import),
            )
            self._apply_graph_linkage_banner_from_audit(_audit_import, phase="import_after_shell_load")
            self._import_ok_timing("after_import_shell_load_audit_banner", _import_t0)
            _import_graph_enrich_async = False
            if self.current_session_context.get("connected"):
                _t_sel = time.perf_counter()
                self._apply_restored_selector_state()
                self._import_ok_timing("after_apply_restored_selector_state", _import_t0, block_ms=round((time.perf_counter() - _t_sel) * 1000.0, 3))
                # Enrich missing Graph ids using the same logic as ensure_planned_moves_resolved_via_graph,
                # but sliced across event-loop ticks so the UI stays responsive (see _schedule_post_import_graph_enrichment).
                try:
                    _missing_graph = (
                        int(_audit_import.get("rows_missing_graph_ids") or 0)
                        + int(_audit_import.get("proposed_rows_missing_graph_ids") or 0)
                    )
                    if _missing_graph > 0:
                        self._graph_linkage_progress_session_begin()
                        self._schedule_post_import_graph_enrichment(source_description=source_description)
                        _import_graph_enrich_async = True
                except Exception as exc:
                    self._log_restore_exception("import_draft_graph_enrich_schedule", exc)
            else:
                self._import_rehydration_verify_pending = False
            log_info(
                "planning_state_snapshot",
                phase="import_after_rehydration",
                planned_moves_count=len(self.planned_moves),
                proposed_folders_count=len(self.proposed_folders),
                restore_candidate_name=str(_cand.get("name", "") or ""),
                source=source_description,
            )
            _audit_final = self._audit_planned_moves_graph_destination_identity()
            log_info(
                "graph_linkage_audit",
                phase="import_after_rehydration",
                source=source_description,
                **self._graph_linkage_audit_for_log(_audit_final),
            )
            self._apply_graph_linkage_banner_from_audit(_audit_final, phase="import_after_rehydration")
            _t_fin = time.perf_counter()
            self._finalize_import_workspace_snapshot_hydration(_audit_final, source=source_description)
            self._import_ok_timing("after_finalize_import_workspace_snapshot_hydration", _import_t0, block_ms=round((time.perf_counter() - _t_fin) * 1000.0, 3))
            log_info("Draft import completed.", source=source_description)
            _t_req = time.perf_counter()
            self.refresh_requests_page()
            self._import_ok_timing("after_refresh_requests_page", _import_t0, block_ms=round((time.perf_counter() - _t_req) * 1000.0, 3))
            if _import_graph_enrich_async:
                _import_ok_msg = (
                    "Draft bundle imported.\n\n"
                    "Microsoft 365 folder links are still being resolved in the background; "
                    "watch the planning header for progress."
                )
                if hasattr(self, "planned_moves_status") and self.planned_moves_status is not None:
                    self.planned_moves_status.setText(
                        "Draft imported. Resolving Microsoft 365 folder links in the background…"
                    )
            else:
                _import_ok_msg = "Draft bundle imported."
                if hasattr(self, "planned_moves_status") and self.planned_moves_status is not None:
                    self.planned_moves_status.setText("Draft imported.")
            self._import_ok_trace("before_show_success_dialog", graph_enrich_async=bool(_import_graph_enrich_async))
            self._show_non_modal_import_success_message(_import_ok_msg)
            self._import_ok_timing("import_handler_exit_after_show_success_dialog", _import_t0)
        except Exception as exc:
            self._import_rehydration_verify_pending = False
            self._import_ok_trace("import_handler_exception", error=str(exc))
            log_error("Draft import failed.", error=str(exc), source=source_file if 'source_file' in locals() else source_folder)
            _blocked = user_message_for_import_blocked_exception(exc)
            QMessageBox.warning(
                self,
                "Import Draft",
                _blocked if _blocked else "Could not import the selected draft bundle.",
            )

    def _workspace_reset_backup_dialog_dir(self):
        """Prefer ``Backups/WorkspaceReset``; fall back to ``Backups`` if older builds only wrote there."""
        mm = self.memory_manager
        if mm is None:
            return None
        wr = mm.workspace_reset_backups_dir
        try:
            wr.mkdir(parents=True, exist_ok=True)
        except Exception:
            pass
        try:
            if any(wr.glob("DraftReset*.json")):
                return wr
            if any(mm.backups.glob("DraftReset*.json")):
                return mm.backups
        except Exception:
            pass
        return wr

    def _handle_open_memory_backups_folder(self) -> None:
        """Open ``Memory/Backups/WorkspaceReset`` (DraftReset_*.json). The parent ``Backups`` folder also holds manifest rotation copies."""
        if self.memory_manager is None:
            QMessageBox.information(self, "Workspace reset backups", "Draft storage is not available right now.")
            return
        target = self._workspace_reset_backup_dialog_dir()
        if target is None:
            return
        try:
            target.mkdir(parents=True, exist_ok=True)
        except Exception as exc:
            QMessageBox.warning(
                self,
                "Workspace reset backups",
                f"Could not open folder:\n{exc}",
            )
            return
        resolved = target.resolve()
        QDesktopServices.openUrl(QUrl.fromLocalFile(str(resolved)))
        log_info("Workspace reset backups folder opened.", path=str(resolved))

    def _handle_restore_workspace_reset_backup(self) -> None:
        """Restore a ``DraftReset_*.json`` created when using Backup && Reset Workspace."""
        if self.memory_manager is None:
            QMessageBox.information(self, "Restore Reset Backup", "Draft storage is not available right now.")
            return
        start_dir = self._workspace_reset_backup_dialog_dir()
        if start_dir is None:
            return
        try:
            start_dir.mkdir(parents=True, exist_ok=True)
        except Exception:
            pass
        path, _ = QFileDialog.getOpenFileName(
            self,
            "Restore Workspace Reset Backup",
            str(start_dir),
            "Workspace reset backup (DraftReset_*.json); JSON (*.json)",
        )
        if not path:
            return
        try:
            self._import_rehydration_verify_pending = True
            self._import_tree_reload_retry_used = False
            session_state, allocations, proposed, session_raw, pm_override = self.memory_manager.apply_draft_reset_backup(
                Path(path)
            )
            self._restore_memory_payload(session_state, allocations, proposed, session_raw)
            if pm_override is not None:
                self.planned_moves = list(pm_override)
                self.refresh_planned_moves_table()
                self._clear_source_projection_descendants_cache(
                    reason="workspace_reset_backup_pm_override", caller="apply_draft_reset_backup"
                )
            self._rebuild_submission_visual_cache()
            self.update_progress_summaries()
            if self.current_session_context.get("connected"):
                self._apply_restored_selector_state()
                try:
                    self.ensure_planned_moves_resolved_via_graph(
                        persist=True,
                        quiet=False,
                        refresh_sources=False,
                    )
                except Exception as exc:
                    self._log_restore_exception("restore_workspace_reset_backup_graph_enrich", exc)
            else:
                self._import_rehydration_verify_pending = False
            log_info("Workspace reset backup restored.", source=path)
            self.refresh_requests_page()
            QMessageBox.information(
                self,
                "Restore Reset Backup",
                "The workspace reset backup was restored into your draft memory.\n\n"
                "If sites and libraries do not match the tree, re-select them or use Refresh.",
            )
        except Exception as exc:
            self._import_rehydration_verify_pending = False
            log_error("Restore workspace reset backup failed.", error=str(exc), source=path)
            QMessageBox.warning(
                self,
                "Restore Reset Backup",
                f"Could not restore backup:\n{exc}",
            )

    def _handle_unlock_draft(self):
        submitted_moves = [
            move for move in self.planned_moves
            if str((move or {}).get("status", "")).strip().lower() in {"submitted", "testsubmitted"}
        ]
        submitted_proposed = [
            proposed_folder for proposed_folder in self.proposed_folders
            if str(getattr(proposed_folder, "Status", "")).strip().lower() in {"submitted", "testsubmitted"}
            or bool(getattr(proposed_folder, "SubmittedBatchId", ""))
        ]

        if not submitted_moves and not submitted_proposed:
            QMessageBox.information(self, "Unlock Draft", "The current draft has no submitted items to unlock.")
            return

        decision = QMessageBox.question(
            self,
            "Unlock Draft",
            "\n".join(
                [
                    "This will clear the submitted and locked state from the current draft.",
                    "",
                    f"Planned moves to unlock: {len(submitted_moves)}",
                    f"Proposed folders to unlock: {len(submitted_proposed)}",
                    "",
                    "Saved submission batches in Requests are not deleted.",
                    "Continue?",
                ]
            ),
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.No,
        )
        if decision != QMessageBox.Yes:
            return

        for move in submitted_moves:
            move["status"] = "Draft"
            move.pop("submitted_batch_id", None)
            move.pop("submitted_utc", None)

        for proposed_folder in submitted_proposed:
            proposed_folder.Status = "Draft"
            if hasattr(proposed_folder, "SubmittedBatchId"):
                delattr(proposed_folder, "SubmittedBatchId")

        self._rebuild_submission_visual_cache()
        self.refresh_planned_moves_table()
        self._persist_planning_change("draft_unlocked")
        self.planned_moves_status.setText(
            f"Unlocked {len(submitted_moves)} move(s) and {len(submitted_proposed)} proposed folder(s) in the draft."
        )
        QMessageBox.information(
            self,
            "Unlock Draft",
            f"Unlocked {len(submitted_moves)} move(s) and {len(submitted_proposed)} proposed folder(s).",
        )

    def handle_refresh_cache(self):
        self._request_cache_refresh_for_panels({"source", "destination"})

    def _restore_refresh_cache_icon_buttons(self):
        """Keep refresh controls icon-only (wide labels overflow the fixed-width toolbar)."""
        if hasattr(self, "source_refresh_cache_button"):
            self.source_refresh_cache_button.setEnabled(True)
            self.source_refresh_cache_button.setText(_REFRESH_CACHE_TREE_GLYPH)
            self.source_refresh_cache_button.setToolTip(_REFRESH_CACHE_TREE_TOOLTIP_IDLE)
        if hasattr(self, "destination_refresh_cache_button"):
            tb = self.destination_refresh_cache_button
            tb.setEnabled(True)
            tb.setText(_REFRESH_CACHE_TREE_GLYPH)
            if isinstance(tb, QToolButton):
                tb.setToolTip(
                    _REFRESH_CACHE_TREE_TOOLTIP_IDLE + " Use the arrow for Rebuild Cache / Full Resync (clears and reloads)."
                )
            else:
                tb.setToolTip(_REFRESH_CACHE_TREE_TOOLTIP_IDLE)

    def handle_refresh_cache_for_panel(self, panel_key):
        if panel_key not in {"source", "destination"}:
            return
        if self._planning_browse_mode(panel_key) == "local":
            QMessageBox.information(
                self,
                "Refresh Cache",
                "Refresh cache applies to SharePoint libraries. Switch Browse to SharePoint to refresh the Microsoft 365 cache.",
            )
            return
        self._request_cache_refresh_for_panels({panel_key})

    def _handle_destination_rebuild_cache_full_resync(self):
        if self._planning_browse_mode("destination") == "local":
            QMessageBox.information(
                self,
                "Rebuild Cache",
                "Switch the destination browse mode to SharePoint to rebuild the Microsoft 365 cache.",
            )
            return
        decision = QMessageBox.question(
            self,
            "Rebuild Cache / Full Resync",
            "This clears the cached folder listings for the destination library and reloads the full tree from Microsoft 365.\n\n"
            "The main refresh button performs a faster incremental update that keeps the workspace visible.\n\n"
            "Continue with full rebuild?",
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.No,
        )
        if decision != QMessageBox.Yes:
            return
        self._destination_cache_refresh_force_full_resync = True
        self._request_cache_refresh_for_panels({"destination"})

    def _request_cache_refresh_for_panels(self, panel_keys):
        try:
            if self.cache_refresh_worker and self.cache_refresh_worker.isRunning():
                return
            if getattr(self, "destination_incremental_refresh_worker", None) and self.destination_incremental_refresh_worker.isRunning():
                return
            target_panels = {key for key in (panel_keys or set()) if key in {"source", "destination"}}
            if not target_panels:
                return
            self._flush_deferred_planning_refresh()
            self._cache_refresh_restore_active = True
            self._pending_cache_refresh_ui_state = self._capture_workspace_tree_state()
            self._pending_cache_refresh_panels = set()
            force_dest_full = bool(getattr(self, "_destination_cache_refresh_force_full_resync", False))
            self._destination_cache_refresh_force_full_resync = False
            dest_option3 = (
                "destination" in target_panels
                and self._planning_browse_mode("destination") != "local"
                and not force_dest_full
            )
            self._cache_refresh_option3_destination = dest_option3
            # Restoring thousands of expanded paths immediately after cache refresh causes
            # aggressive lazy-load churn and UI scroll jank, especially for source.
            self._cache_refresh_skip_expanded_restore_panels = set()
            if "source" in target_panels:
                self._cache_refresh_skip_expanded_restore_panels.add("source")
            if "destination" in target_panels and not dest_option3:
                self._cache_refresh_skip_expanded_restore_panels.add("destination")
            self._pending_cache_refresh_tree_snapshots = {
                "source": self._capture_tree_items_snapshot("source"),
                "destination": self._capture_tree_items_snapshot("destination"),
            }
            if "source" in target_panels:
                self._cancel_expand_all("source")
                self._set_expand_all_button_label("source", False)
            if "destination" in target_panels and not dest_option3:
                self._cancel_expand_all("destination")
                self._destination_expand_all_after_full_tree = False
                self._set_expand_all_button_label("destination", False)
                destination_button = self._expand_all_button_for_panel("destination")
                if destination_button is not None:
                    destination_button.setEnabled(True)
            source_site = self.planning_inputs.get("Source Site").currentData() if hasattr(self, "planning_inputs") else None
            source_library = self.planning_inputs.get("Source Library").currentData() if hasattr(self, "planning_inputs") else None
            destination_site = self.planning_inputs.get("Destination Site").currentData() if hasattr(self, "planning_inputs") else None
            destination_library = self.planning_inputs.get("Destination Library").currentData() if hasattr(self, "planning_inputs") else None
            drive_ids = []
            if "source" in target_panels and isinstance(source_library, dict) and source_library.get("id"):
                drive_ids.append(source_library.get("id"))
                self._pending_cache_refresh_panels.add("source")
            if "destination" in target_panels and isinstance(destination_library, dict) and destination_library.get("id"):
                self._pending_cache_refresh_panels.add("destination")
                if not dest_option3:
                    drive_ids.append(destination_library.get("id"))

            dest_incr_alone = (
                dest_option3
                and self._pending_cache_refresh_panels == {"destination"}
                and isinstance(destination_site, dict)
                and isinstance(destination_library, dict)
                and destination_library.get("id")
            )
            if not drive_ids and not dest_incr_alone:
                self._cache_refresh_restore_active = False
                self._pending_cache_refresh_ui_state = None
                self._pending_cache_refresh_panels = set()
                self._cache_refresh_refreshed_panels_snapshot = set()
                self._cache_refresh_skip_expanded_restore_panels = set()
                self._pending_cache_refresh_tree_snapshots = {}
                return

            self._cache_refresh_refreshed_panels_snapshot = set(self._pending_cache_refresh_panels)

            if "source" in self._pending_cache_refresh_panels:
                self._set_tree_status_message("source", "Refreshing source cache...", loading=True)
                if hasattr(self, "source_refresh_cache_button"):
                    self.source_refresh_cache_button.setEnabled(False)
                    self.source_refresh_cache_button.setToolTip(_REFRESH_CACHE_TREE_TOOLTIP_BUSY)
            if "destination" in self._pending_cache_refresh_panels:
                msg = (
                    "Refreshing live SharePoint content…"
                    if dest_option3
                    else "Refreshing destination cache..."
                )
                self._set_tree_status_message("destination", msg, loading=bool(dest_option3))
                if hasattr(self, "destination_refresh_cache_button"):
                    self.destination_refresh_cache_button.setEnabled(False)
                    self.destination_refresh_cache_button.setToolTip(_REFRESH_CACHE_TREE_TOOLTIP_BUSY)
            if hasattr(self, "planned_moves_status"):
                label = (
                    "Refreshing source cache; refreshing live SharePoint content on destination…"
                    if self._pending_cache_refresh_panels == {"source", "destination"} and dest_option3
                    else (
                        "Refreshing source and destination cache..."
                        if self._pending_cache_refresh_panels == {"source", "destination"}
                        else (
                            "Refreshing source cache..."
                            if "source" in self._pending_cache_refresh_panels
                            else (
                                "Refreshing live SharePoint content…"
                                if dest_option3
                                else "Refreshing destination cache..."
                            )
                        )
                    )
                )
                self.planned_moves_status.setText(label)

            if dest_incr_alone:
                log_info(
                    "graph_cache_refresh_requested",
                    panels=["destination"],
                    mode="destination_incremental_option3",
                    destination_library=str((destination_library or {}).get("name", "")) if isinstance(destination_library, dict) else "",
                )
                self._start_destination_incremental_graph_refresh_worker(destination_site, destination_library)
                return

            self.cache_refresh_worker = CacheRefreshWorker(self.graph, drive_ids)
            self.cache_refresh_worker.success.connect(lambda payload: self._safe_invoke("cache_refresh.success", self.on_cache_refresh_success, payload))
            self.cache_refresh_worker.error.connect(lambda error: self._safe_invoke("cache_refresh.error", self.on_cache_refresh_error, error))
            self.cache_refresh_worker.finished.connect(lambda: self._safe_invoke("cache_refresh.finished", self.on_cache_refresh_worker_finished))
            self.cache_refresh_worker.start()
            log_info(
                "graph_cache_refresh_requested",
                panels=sorted(self._pending_cache_refresh_panels),
                mode="disk_clear_then_reload" if not dest_option3 else "disk_clear_mixed_incremental_destination",
                source_library=str((source_library or {}).get("name", "")) if isinstance(source_library, dict) else "",
                destination_library=str((destination_library or {}).get("name", "")) if isinstance(destination_library, dict) else "",
                destination_incremental_option3=bool(dest_option3),
            )
        except Exception as exc:
            self._cache_refresh_restore_active = False
            self._pending_cache_refresh_ui_state = None
            self._pending_cache_refresh_panels = set()
            self._cache_refresh_refreshed_panels_snapshot = set()
            self._cache_refresh_skip_expanded_restore_panels = set()
            log_error("Graph cache refresh failed.", error=str(exc))
            QMessageBox.warning(self, "Refresh Cache", "Could not refresh the SharePoint cache right now.")

    def _handle_submit_request(self):
        try:
            test_mode = bool(getattr(self, "_submission_test_mode", False))
            issues, warnings, draft_moves, draft_proposed = self._validate_submission_readiness()
            if issues:
                QMessageBox.warning(
                    self,
                    "Submit Request",
                    "Please fix the following before submitting:\n\n- " + "\n- ".join(issues),
                )
                return

            # Persist Microsoft Graph drive/item ids from saved paths before building the zip
            # (legacy drafts from mapped-drive builds often have paths only).
            self.ensure_planned_moves_resolved_via_graph(persist=True, quiet=True)

            source_site = self.planning_inputs["Source Site"].currentData() or {}
            source_library = self.planning_inputs["Source Library"].currentData() or {}
            destination_site = self.planning_inputs["Destination Site"].currentData() or {}
            destination_library = self.planning_inputs["Destination Library"].currentData() or {}
            submitted_utc = datetime.utcnow().isoformat()
            batch_id = self._next_submission_batch_id()

            confirmation_lines = [
                "This will create an immutable submission batch for Ozlink IT."
                if not test_mode
                else "This will create a TEST submission batch without locking the live draft.",
                "",
                f"Planned moves to submit: {len(draft_moves)}",
                f"Proposed folders to submit: {len(draft_proposed)}",
                f"Needs review currently shown: {len(self._workflow_needs_review_rows)}",
                "",
                (
                    "Submitted items will remain visible in the draft but will become locked."
                    if not test_mode
                    else "Test submissions are stored separately and do not change the live draft."
                ),
                (
                    "Only new draft items will be included in later submissions."
                    if not test_mode
                    else "Use this to validate the handoff package safely before a real submit."
                ),
            ]
            if warnings:
                confirmation_lines.extend(["", "Warnings:"])
                confirmation_lines.extend(f"- {warning}" for warning in warnings)

            decision = QMessageBox.question(
                self,
                "Submit Request to Ozlink IT",
                "\n".join(confirmation_lines),
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.No,
            )
            if decision != QMessageBox.Yes:
                return

            allocation_rows = []
            allocation_payload = []
            allocation_request_ids = []
            for index, move in enumerate(draft_moves):
                row = self._build_allocation_row_for_move(move, index)
                row.Status = "TestSubmitted" if test_mode else "Submitted"
                allocation_rows.append(row)
                allocation_payload.append(row.to_dict())
                allocation_request_ids.append(row.RequestId)

            proposed_payload = []
            proposed_destination_ids = []
            for index, proposed_folder in enumerate(draft_proposed):
                self._ensure_proposed_destination_id(proposed_folder, index)
                proposed_data = proposed_folder.to_dict()
                proposed_data["RequestedBy"] = proposed_data.get("RequestedBy", "") or self.current_session_context.get("operator_display_name", "")
                proposed_data["RequestedDate"] = proposed_data.get("RequestedDate", "") or submitted_utc
                proposed_data["Status"] = "TestSubmitted" if test_mode else "Submitted"
                proposed_payload.append(proposed_data)
                proposed_destination_ids.append(proposed_folder.DestinationId)

            batch = SubmissionBatch(
                BatchId=batch_id,
                DraftId=self.active_draft_session_id,
                DraftName=getattr(self, "_draft_shell_state", SessionState()).DraftName if isinstance(getattr(self, "_draft_shell_state", None), SessionState) else "",
                SubmittedUtc=submitted_utc,
                SubmittedBy=self.current_session_context.get("operator_display_name", ""),
                SubmittedByUpn=self.current_session_context.get("operator_upn", ""),
                TenantDomain=self.current_session_context.get("tenant_domain", ""),
                Status="TestSubmitted" if test_mode else "Submitted",
                SourceSite=source_site.get("name", ""),
                SourceLibrary=source_library.get("name", ""),
                DestinationSite=destination_site.get("name", ""),
                DestinationLibrary=destination_library.get("name", ""),
                PlannedMoveCount=len(allocation_payload),
                ProposedFolderCount=len(proposed_payload),
                NeedsReviewCount=len(self._workflow_needs_review_rows),
                ValidationWarnings=list(warnings),
                AllocationRequestIds=allocation_request_ids,
                ProposedDestinationIds=proposed_destination_ids,
            )

            batch_path = self.request_store.create_submission_batch(
                batch,
                allocation_payload,
                proposed_payload,
                test_mode=test_mode,
            )

            if not test_mode:
                self._mark_items_submitted(batch_id, submitted_utc, draft_moves, draft_proposed)
                self.refresh_planned_moves_table()
                self._persist_planning_change("request_submitted")
                self.planned_moves_status.setText(
                    f"Submission batch {batch_id} created with {len(allocation_payload)} move(s) and {len(proposed_payload)} proposed folder(s)."
                )
            else:
                self.planned_moves_status.setText(
                    f"Test submission batch {batch_id} created with {len(allocation_payload)} move(s) and {len(proposed_payload)} proposed folder(s)."
                )
            log_info(
                "Submission batch created.",
                batch_id=batch_id,
                draft_id=self.active_draft_session_id,
                destination=str(batch_path),
                planned_move_count=len(allocation_payload),
                proposed_folder_count=len(proposed_payload),
                test_mode=test_mode,
            )
            default_zip = self.request_store.export_submission_batch_zip(batch_id, test_mode=test_mode)
            zip_save_path, _ = QFileDialog.getSaveFileName(
                self,
                "Save Submission Zip Copy",
                str(default_zip),
                "Submission Zip Bundle (*.zip)",
            )
            custom_zip_destination = None
            if zip_save_path:
                custom_zip_destination = Path(zip_save_path)
                if custom_zip_destination.suffix.lower() != ".zip":
                    custom_zip_destination = custom_zip_destination.with_suffix(".zip")
                self.request_store.export_submission_batch_zip(
                    batch_id,
                    test_mode=test_mode,
                    destination_zip=custom_zip_destination,
                )
            self.refresh_requests_page()
            info_lines = [
                "Test submission batch created successfully." if test_mode else "Submission batch created successfully.",
                "",
                f"Batch ID: {batch_id}",
                f"Planned moves: {len(allocation_payload)}",
                f"Proposed folders: {len(proposed_payload)}",
                "",
                (
                    "This test batch was stored separately and did not lock the live draft."
                    if test_mode
                    else "Submitted items are now locked in the draft."
                ),
                "",
                "A submission zip was created for email handoff.",
                f"Default zip: {default_zip}",
            ]
            if custom_zip_destination is not None:
                info_lines.extend(["", f"Additional zip copy: {custom_zip_destination}"])
            info_lines.extend(
                [
                    "",
                    "Please email the zip to: support@ozlink.it",
                    "The app can open your mail client with the address and subject prefilled.",
                ]
            )

            email_prompt = QMessageBox(self)
            email_prompt.setIcon(QMessageBox.Information)
            email_prompt.setWindowTitle("Submit Request")
            email_prompt.setText("\n".join(info_lines))
            open_email_btn = email_prompt.addButton("Open Email Draft", QMessageBox.AcceptRole)
            email_prompt.addButton(QMessageBox.Ok)
            email_prompt.exec()

            if email_prompt.clickedButton() == open_email_btn:
                subject = f"SharePoint Relocation Request {batch_id}"
                body = (
                    f"Hello Ozlink IT,%0D%0A%0D%0A"
                    f"Please find attached submission batch {batch_id}.%0D%0A%0D%0A"
                    f"Default zip path:%0D%0A{default_zip}%0D%0A"
                )
                mail_url = QUrl(f"mailto:support@ozlink.it?subject={QUrl.toPercentEncoding(subject).data().decode()}&body={body}")
                QDesktopServices.openUrl(mail_url)
        except Exception as exc:
            log_error("Submit request failed.", error=str(exc))
            QMessageBox.warning(self, "Submit Request", "Could not prepare the current draft.")

    def _load_saved_window_preferences(self):
        settings = QSettings()
        self._saved_window_rect = settings.value("main_window/normal_geometry", QRect(), type=QRect)
        self._saved_window_maximized = settings.value("main_window/maximized", True, type=bool)
        self._saved_window_rect_loaded = isinstance(self._saved_window_rect, QRect) and self._saved_window_rect.isValid()

    def save_window_preferences(self):
        settings = QSettings()
        settings.setValue("main_window/maximized", self.isMaximized())
        normal_rect = self.normalGeometry() if self.isMaximized() else self.geometry()
        if isinstance(normal_rect, QRect) and normal_rect.isValid():
            settings.setValue("main_window/normal_geometry", normal_rect)

    def apply_startup_window_geometry(self):
        print("[window-startup] apply_startup_window_geometry() called")
        self.setWindowState(Qt.WindowNoState)
        self._apply_native_window_flags()

        target_screen = self._current_target_screen()
        available_geometry = target_screen.availableGeometry() if target_screen else QRect(80, 80, 1600, 980)
        safe_normal = available_geometry.adjusted(32, 32, -32, -32)
        self._apply_clamped_normal_geometry(safe_normal, available_geometry)
        print(
            "[window-startup] "
            f"flags={int(self.windowFlags())} "
            f"screen={target_screen.name() if target_screen else 'None'} "
            f"available_geometry={available_geometry.getRect()} "
            f"saved_geometry_loaded={getattr(self, '_saved_window_rect_loaded', False)} "
            f"saved_geometry_rejected=True "
            f"fallback_maximize_used=True"
        )

    def _current_target_screen(self):
        cursor_screen = QGuiApplication.screenAt(QCursor.pos())
        if cursor_screen is not None:
            return cursor_screen

        screen = self.screen()
        if screen is not None:
            return screen

        frame_center = self.frameGeometry().center()
        screen = QGuiApplication.screenAt(frame_center)
        if screen is not None:
            return screen

        return QGuiApplication.primaryScreen()

    def _apply_clamped_normal_geometry(self, target_rect, available_geometry):
        if not isinstance(target_rect, QRect) or target_rect.isEmpty():
            self.setGeometry(available_geometry)
            return

        width = min(max(target_rect.width(), 1100), available_geometry.width())
        height = min(max(target_rect.height(), 760), available_geometry.height())

        x = target_rect.x()
        y = target_rect.y()
        max_x = available_geometry.right() - width + 1
        max_y = available_geometry.bottom() - height + 1
        min_x = available_geometry.x()
        min_y = available_geometry.y()

        if x < min_x or x > max_x:
            x = min(max(x, min_x), max_x)
        if y < min_y or y > max_y:
            y = min(max(y, min_y), max_y)

        clamped = QRect(x, y, width, height)
        if not available_geometry.contains(clamped):
            clamped.moveLeft(max(min_x, min(clamped.x(), max_x)))
            clamped.moveTop(max(min_y, min(clamped.y(), max_y)))

        self.setGeometry(clamped)

    def _win32_logical_work_area_dimensions_for_window(self) -> Optional[Tuple[int, int]]:
        """Return work-area width/height in Qt device-independent pixels for the monitor nearest this window.

        Qt ``QScreen.availableGeometry()`` can disagree with Win32 ``MINMAXINFO`` on mixed-DPI setups;
        using ``GetMonitorInfo`` + the screen DPR matches the shell's 3840×2064-style caps.
        """
        if not sys.platform.startswith("win"):
            return None
        try:
            hwnd = int(self.winId())
        except (TypeError, ValueError, RuntimeError):
            return None
        if hwnd == 0:
            return None

        phys = _win32_monitor_rc_work_phys(hwnd)
        if phys is None:
            return None
        phys_w, phys_h = phys

        dpr: float | None = None
        try:
            dpi = int(ctypes.windll.user32.GetDpiForWindow(int(hwnd)))
            if dpi > 0:
                dpr = float(dpi) / 96.0
        except Exception:
            dpr = None
        wh = self.windowHandle()
        center = self.geometry().center()
        screen = QGuiApplication.screenAt(center)
        if screen is None and wh is not None:
            screen = wh.screen()
        if screen is None:
            screen = self.screen()
        if screen is None:
            screen = QGuiApplication.primaryScreen()
        if dpr is None or dpr <= 0:
            # Fallback when GetDpiForWindow is unavailable; effective DPR can differ from QScreen.
            if wh is not None:
                dpr = float(wh.devicePixelRatio() or 1.0)
            elif screen is not None:
                dpr = float(screen.devicePixelRatio() or 1.0)
            else:
                dpr = 1.0
        if dpr <= 0:
            dpr = 1.0
        return int(phys_w / dpr), int(phys_h / dpr)

    def _shrink_planning_layout_minimums_to_fit_work_area(self, cap_w: int, cap_h: int) -> None:
        """When layout minimumSizeHint exceeds the work area, lower splitter/tab minimum heights.

        ``QMainWindow.setMinimumSize`` does not override QLayout minimum hints; Win32 then advertises a
        ``mintrack`` taller than the monitor work rect (``QWindowsWindow::setGeometry`` warnings).
        """
        st = getattr(self, "source_tree_box", None)
        dt = getattr(self, "destination_tree_box", None)
        wt = getattr(self, "workspace_tabs", None)
        if st is None or dt is None or wt is None:
            return
        if getattr(self, "_planning_layout_baseline_mins", None) is None:
            self._planning_layout_baseline_mins = {
                "source_h": max(1, int(st.minimumHeight())),
                "dest_h": max(1, int(dt.minimumHeight())),
                "tabs_h": max(1, int(wt.minimumHeight())),
                "tabs_max": max(1, int(wt.maximumHeight())),
                "collapsed": bool(getattr(self, "_workspace_tabs_collapsed", False)),
            }
        b = self._planning_layout_baseline_mins
        cum_scale = 1.0
        for _ in range(12):
            try:
                self.updateGeometry()
                hint = self.minimumSizeHint()
                if not hint.isValid():
                    break
                bw = max(1, int(hint.width()))
                bh = max(1, int(hint.height()))
            except Exception:
                break
            if bw <= cap_w and bh <= cap_h:
                break
            step_h = min(1.0, (cap_h / float(bh)) * 0.995) if bh > cap_h else 1.0
            step_w = min(1.0, (cap_w / float(bw)) * 0.995) if bw > cap_w else 1.0
            step = min(step_h, step_w)
            if step >= 0.999:
                break
            cum_scale *= step
            scale = cum_scale
            st.setMinimumHeight(max(120, int(int(b["source_h"]) * scale)))
            dt.setMinimumHeight(max(120, int(int(b["dest_h"]) * scale)))
            collapsed_now = bool(getattr(self, "_workspace_tabs_collapsed", False))
            if not collapsed_now and not bool(b.get("collapsed")):
                nh = max(160, int(int(b["tabs_h"]) * scale))
                wt.setMinimumHeight(nh)
                nmax = max(nh, int(int(b["tabs_max"]) * scale))
                wt.setMaximumHeight(nmax)

    def _clamp_main_window_minimum_size_to_available_work_area(self):
        """Avoid Win32 MINMAXINFO mintrack larger than the monitor work area (causes setGeometry
        fights, maximized frame clipping, and taskbar/shell flicker on show)."""
        try:
            wh = self.windowHandle()
            screen = wh.screen() if wh is not None else self.screen()
            if screen is None:
                screen = QGuiApplication.primaryScreen()
            if screen is None:
                return
            ag = screen.availableGeometry()
            if not ag.isValid() or ag.isEmpty():
                return
            floor_w, floor_h = 800, 600
            cap_w = max(floor_w, int(ag.width()))
            cap_h = max(floor_h, int(ag.height()))
            win32_cap = self._win32_logical_work_area_dimensions_for_window()
            if win32_cap is not None:
                w32_w, w32_h = win32_cap
                cap_w = max(floor_w, min(cap_w, w32_w))
                cap_h = max(floor_h, min(cap_h, w32_h))
            # Reserve non-client chrome so client minSize × DPR does not exceed the shell work rect
            # (Qt warning: requested frame height > availableGeometry; common with FramelessWindowHint).
            try:
                if self.isVisible():
                    fg = self.frameGeometry()
                    g = self.geometry()
                    extra_h = max(0, fg.height() - g.height())
                    extra_w = max(0, fg.width() - g.width())
                    cap_h = max(floor_h, cap_h - extra_h)
                    cap_w = max(floor_w, cap_w - extra_w)
            except Exception:
                pass
            self._shrink_planning_layout_minimums_to_fit_work_area(cap_w, cap_h)
            hint = self.minimumSizeHint()
            base_w = max(int(self.minimumWidth()), int(hint.width()))
            base_h = max(int(self.minimumHeight()), int(hint.height()))
            new_w = min(base_w, cap_w)
            new_h = min(base_h, cap_h)
            if new_w < base_w or new_h < base_h:
                self.setMinimumSize(int(new_w), int(new_h))
        except Exception:
            return

    def _saved_rect_is_safe(self, target_rect, available_geometry):
        if not isinstance(target_rect, QRect) or not target_rect.isValid() or target_rect.isEmpty():
            return False

        title_bar_height = 48
        safe_rect = QRect(target_rect)
        safe_rect.setHeight(max(safe_rect.height(), title_bar_height))

        if safe_rect.top() < available_geometry.top():
            return False
        if safe_rect.left() < available_geometry.left():
            return False
        if safe_rect.top() + title_bar_height > available_geometry.bottom():
            return False

        visible_width = min(safe_rect.width(), available_geometry.width())
        visible_height = min(safe_rect.height(), available_geometry.height())
        visible_rect = QRect(safe_rect.x(), safe_rect.y(), visible_width, visible_height)
        return available_geometry.intersects(visible_rect)

    def _apply_native_window_flags(self):
        self.setWindowFlags(Qt.WindowType.Window | Qt.WindowType.FramelessWindowHint)

    def _log_post_startup_state(self):
        print(
            "[window-startup] post-show "
            f"state={self._window_state_repr()} "
            f"geometry={self.geometry().getRect()} "
            f"frame_geometry={self.frameGeometry().getRect()}"
        )

    def _window_state_repr(self):
        state = self.windowState()
        return getattr(state, "value", state)

    def _log_post_login_window_state(self, prefix="[window-login]"):
        print(
            f"{prefix} "
            f"post_restore maximized={self.isMaximized()} "
            f"state={self._window_state_repr()} "
            f"geometry={self.geometry().getRect()} "
            f"frame_geometry={self.frameGeometry().getRect()}"
        )

    def _clear_bad_window_preferences(self):
        settings = QSettings()
        settings.remove("main_window/normal_geometry")
        settings.remove("main_window/maximized")
        self._saved_window_rect = QRect()
        self._saved_window_maximized = True
        self._saved_window_rect_loaded = False

    def build_details_panel(self):
        box = QFrame()
        box.setObjectName("SectionBox")
        box.setMinimumWidth(0)
        box.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Preferred)
        layout = QVBoxLayout(box)
        layout.setContentsMargins(12, 10, 12, 10)
        layout.setSpacing(10)

        title = QLabel("Selection")
        title.setObjectName("SectionTitle")

        self.details_fields = {}

        actions_row = QHBoxLayout()
        actions_row.setContentsMargins(0, 0, 0, 0)
        actions_row.setSpacing(6)

        self.details_action_buttons = {}
        for index, (text, handler) in enumerate([
            ("Open File", self.handle_open_selected_file),
            ("Open in SharePoint", self.handle_open_selected_in_browser),
            ("Copy Link", self.handle_copy_selected_link),
            ("Go to source", lambda: self.handle_go_to_source(entry_point="selection_details_panel")),
            ("Go to Destination", self.handle_go_to_destination),
        ]):
            button = QPushButton(text)
            button.setMinimumHeight(28)
            button.setSizePolicy(QSizePolicy.MinimumExpanding, QSizePolicy.Fixed)
            button.clicked.connect(handler)
            button.setEnabled(False)
            self.details_action_buttons[text] = button
            actions_row.addWidget(button)

        metadata_wrap = QFrame()
        metadata_wrap.setObjectName("TreeSurface")
        metadata_wrap.setMinimumWidth(0)
        metadata_layout = QVBoxLayout(metadata_wrap)
        metadata_layout.setContentsMargins(8, 8, 8, 8)
        metadata_layout.setSpacing(4)
        metadata_title = QLabel("Metadata")
        metadata_title.setObjectName("HeaderEyebrow")
        metadata_layout.addWidget(metadata_title)
        self.details_metadata_summary = QTextEdit()
        self.details_metadata_summary.setReadOnly(True)
        self.details_metadata_summary.setObjectName("DetailsNotes")
        self.details_metadata_summary.setMinimumHeight(80)
        self.details_metadata_summary.setPlainText("Select an item to review its metadata.")
        metadata_layout.addWidget(self.details_metadata_summary, 1)

        self.details_notes = QTextEdit()
        self.details_notes.setReadOnly(True)
        self.details_notes.setObjectName("DetailsNotes")
        self.details_notes.setMinimumHeight(40)
        self.details_notes.setMaximumHeight(48)
        self.details_notes.setPlainText("Selection guidance and allocation notes will appear here.")
        self.details_notes.hide()

        layout.addWidget(title)
        layout.addWidget(metadata_wrap, 1)
        layout.addLayout(actions_row)

        return box

    def build_preview_tab_panel(self):
        """Dedicated Preview tab: explicit workflow via tree context menu (no auto-load on selection)."""
        box = QFrame()
        box.setObjectName("SectionBox")
        box.setMinimumWidth(0)
        box.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)
        outer = QVBoxLayout(box)
        outer.setContentsMargins(12, 10, 12, 10)
        outer.setSpacing(8)

        self.preview_stack = QStackedWidget()
        self.preview_stack.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)

        empty_page = QWidget()
        empty_layout = QVBoxLayout(empty_page)
        empty_layout.setContentsMargins(8, 8, 8, 8)
        self.preview_empty_label = QLabel(
            "Select a file or folder in a tree and choose Preview to open it here.\n\n"
            "Preview does not load automatically when you change selection."
        )
        self.preview_empty_label.setObjectName("CardBody")
        self.preview_empty_label.setWordWrap(True)
        empty_layout.addWidget(self.preview_empty_label)
        empty_layout.addStretch(1)

        loading_page = QWidget()
        loading_layout = QVBoxLayout(loading_page)
        loading_layout.setContentsMargins(8, 8, 8, 8)
        self.preview_loading_label = QLabel("Loading preview…")
        self.preview_loading_label.setObjectName("SectionTitle")
        loading_layout.addWidget(self.preview_loading_label)
        loading_layout.addStretch(1)

        unsupported_page = QWidget()
        unsupported_layout = QVBoxLayout(unsupported_page)
        unsupported_layout.setContentsMargins(8, 8, 8, 8)
        self.preview_unsupported_label = QLabel("")
        self.preview_unsupported_label.setObjectName("CardBody")
        self.preview_unsupported_label.setWordWrap(True)
        unsupported_layout.addWidget(self.preview_unsupported_label)
