    def _sync_planned_moves_issue_strip_visibility(self) -> None:
        strip = getattr(self, "planned_moves_issue_strip", None)
        sep = getattr(self, "planned_moves_issue_separator", None)
        proj = getattr(self, "planned_moves_projection_review_banner", None)
        dup = getattr(self, "planned_moves_duplicate_banner", None)
        if strip is None:
            return
        pv = proj.isVisible() if proj is not None else False
        dv = dup.isVisible() if dup is not None else False
        strip.setVisible(pv or dv)
        if sep is not None:
            sep.setVisible(pv and dv)

    def _on_planned_moves_duplicate_hub_apply_suggested(self) -> None:
        self._planning_bulk_apply_duplicate_suggested_names(parent=self, quiet_success=False)
        self._update_planned_moves_duplicate_destination_banner()
        self._update_planned_moves_projection_review_banner()

    def _update_planned_moves_duplicate_destination_banner(self) -> None:
        row = getattr(self, "planned_moves_duplicate_banner", None)
        if row is None:
            return
        groups = grouped_duplicate_destination_moves(
            list(self.planned_moves or []),
            destination_file_key=self._destination_file_key_for_execution_validation,
        )
        self._cached_duplicate_destination_groups = {k: list(v) for k, v in groups.items()}
        row.setVisible(bool(groups))
        title = getattr(self, "planned_moves_duplicate_banner_title", None)
        if title is not None and groups:
            n_groups = len(groups)
            n_files = sum(len(m) for m in groups.values())
            title.setText(f"Duplicate targets: {n_groups} group(s), {n_files} file(s)")
        self._sync_planned_moves_issue_strip_visibility()

    def _refresh_planning_derived_state(self, reason: str = "") -> None:
        """Recompute planning-only readiness from cached duplicate groups and workflow rows (no manifest / Graph)."""
        _ = reason
        groups = getattr(self, "_cached_duplicate_destination_groups", None)
        if not isinstance(groups, dict):
            groups = {}
        dgc = len(groups)
        dic = sum(len(m) for m in groups.values()) if groups else 0
        has_dup = dgc > 0

        rows = list(getattr(self, "_workflow_needs_review_rows", None) or [])
        nrt = len(rows)
        actionable_types = {
            "duplicate_destination_projection",
            "proposed_branch_dependency",
            "weak_suggestion",
            REVIEW_TYPE_DESTINATION_ANCHOR_MISSING,
            REVIEW_TYPE_LIVE_MEMORY_DUPLICATE,
        }
        nra = sum(
            1
            for r in rows
            if isinstance(r, dict) and str(r.get("review_type", "") or "").strip() in actionable_types
        )
        has_nr = nra > 0

        dismissed = getattr(self, "_needs_review_dismissed_inherited_paths", None) or set()
        has_inherited_signal = any(
            isinstance(r, dict)
            and str(r.get("review_type", "") or "").strip() == "inherited_mapping"
            and self.normalize_memory_path(str(r.get("source_path", "") or "")) not in dismissed
            for r in rows
        )
        has_folder_move = any(
            bool((m.get("source") or {}).get("is_folder"))
            for m in (self.planned_moves or [])
            if isinstance(m, dict)
        )
        has_exclusions = bool(getattr(self, "_plan_leaf_exclusions", None))

        blockers = has_dup or has_nr
        want_runtime_hint = (not blockers) and (has_folder_move or has_inherited_signal or has_exclusions)

        if has_dup:
            state: Literal["ready", "needs_attention", "runtime_check_recommended"] = "needs_attention"
            label = "Duplicate file targets need resolution"
            rtc_flag = False
        elif has_nr:
            state = "needs_attention"
            label = "Planning overlaps need review"
            rtc_flag = False
        elif want_runtime_hint:
            state = "runtime_check_recommended"
            label = "Runtime check may still be required"
            rtc_flag = True
        else:
            state = "ready"
            label = "Ready for execution"
            rtc_flag = False

        self._planning_derived_state = PlanningDerivedState(
            duplicate_group_count=dgc,
            duplicate_item_count=dic,
            has_duplicate_conflicts=has_dup,
            needs_review_total=nrt,
            needs_review_actionable_total=nra,
            has_needs_review_conflicts=has_nr,
            runtime_check_recommended=rtc_flag,
            readiness_state=state,
            readiness_label=label,
        )
        self._apply_planning_derived_state_to_ui()

    def _apply_planning_derived_state_to_ui(self) -> None:
        lbl = getattr(self, "planning_readiness_summary_label", None)
        if lbl is None:
            return
        st = getattr(self, "_planning_derived_state", None)
        if st is None:
            return
        lbl.setText(st.readiness_label)
        lbl.setToolTip(
            "This summary reflects planning-visible issues only. "
            "Recursive or subset execution may still require runtime validation."
        )

    def _update_planned_moves_projection_review_banner(self) -> None:
        row = getattr(self, "planned_moves_projection_review_banner", None)
        if row is None:
            return
        projection_types = {
            "duplicate_destination_projection",
            "proposed_branch_dependency",
            "inherited_mapping",
            REVIEW_TYPE_DESTINATION_ANCHOR_MISSING,
        }
        review_rows = getattr(self, "_workflow_needs_review_rows", None) or []
        show = any(
            isinstance(r, dict) and str(r.get("review_type", "") or "").strip() in projection_types
            for r in review_rows
        )
        row.setVisible(bool(show))
        self._sync_planned_moves_issue_strip_visibility()

    def _on_planned_moves_projection_review_banner_open(self) -> None:
        tabs = getattr(self, "workspace_tabs", None)
        box = getattr(self, "review_fix_box", None)
        table = getattr(self, "needs_review_table", None)
        if tabs is None or box is None:
            return
        tabs.setCurrentWidget(box)
        if table is not None:
            table.setFocus()

    def _planning_selector_still_on_login_placeholder(self) -> bool:
        """True only for known pre-populate combo placeholders (not real sites/libraries named 'Loading…')."""
        markers = (
            "loading sharepoint...",
            "not loaded yet",
        )
        for label_text in ("Source Site", "Source Library", "Destination Site", "Destination Library"):
            selector = self.planning_inputs.get(label_text) if hasattr(self, "planning_inputs") else None
            if selector is None:
                continue
            text = str(selector.currentText() or "").strip().lower()
            if text in markers:
                return True
        return False

    def _planning_workspace_loading_message(self):
        if not self.current_session_context.get("connected"):
            return ""

        if self.discovery_worker and self.discovery_worker.isRunning():
            return "Loading SharePoint sites and libraries. Your planned moves will appear here shortly."

        loading_selector = self._planning_selector_still_on_login_placeholder()

        active_root_workers = any(
            bool(entry and entry.get("worker") and entry["worker"].isRunning())
            for entry in self.root_load_workers.values()
        )
        if loading_selector or active_root_workers:
            # Trees + plan can be ready while a root worker thread has not cleared yet; avoid a stuck banner.
            if (
                self.planned_moves
                and not loading_selector
                and self._tree_has_bound_root_content("source")
                and self._tree_has_bound_root_content("destination")
            ):
                return ""
            return "Loading SharePoint content and restoring your planning workspace. Planned moves will appear here shortly."

        return ""

    def _refresh_planning_loading_banner(self):
        banner = getattr(self, "planning_loading_banner", None)
        if banner is None:
            return
        message = self._planning_workspace_loading_message()
        if message:
            detail = "Please wait while we load your SharePoint sites and libraries."
            if self.discovery_worker and self.discovery_worker.isRunning():
                detail = "Please wait while we discover your accessible SharePoint sites and document libraries."
            self.planning_loading_label.setText(detail)
            self.planning_loading_loading_detail.setText(message)
            self._apply_planning_loading_banner_visual_state(True)
            banner.show()
        else:
            self._apply_planning_loading_banner_visual_state(False)
            banner.hide()

    def update_dashboard_session_summary(self, connected, display_name="", tenant="", role="user"):
        if hasattr(self, "dashboard_stack"):
            self.dashboard_stack.setCurrentIndex(1 if connected else 0)

        if not hasattr(self, "dashboard_session_state"):
            return

        if connected:
            self.dashboard_session_state.setText("Connection: Connected")
            self.dashboard_session_operator.setText(f"Operator: {display_name or 'Connected User'}")
            self.dashboard_session_tenant.setText(f"Tenant: {tenant or 'Connected'}")
            self.dashboard_session_mode.setText(f"Mode: {role.title()}")
            self.dashboard_next_step.setText(
                "Your planning session is connected, but the source and destination context are not loaded yet. Please contact Ozlink IT if this does not update."
            )
        else:
            self.dashboard_session_state.setText("Connection: Not connected")
            self.dashboard_session_operator.setText("Operator: Not signed in")
            self.dashboard_session_tenant.setText("Tenant: Not connected")
            self.dashboard_session_mode.setText("Mode: Client")
            self.dashboard_next_step.setText(
                "Ready to open your planning session."
            )

    def count_tree_items(self, tree):
        if isinstance(tree, QTreeView) and tree.model() is getattr(self, "source_sharepoint_model", None):
            model = tree.model()
            total_count = 0
            for ix in model.iter_depth_first():
                data = ix.data(Qt.UserRole) or {}
                if not data.get("placeholder"):
                    total_count += 1
            return total_count

        def count_item(item):
            if isinstance(item, QModelIndex):
                data = item.data(Qt.UserRole) or {}
                total = 0 if data.get("placeholder") else 1
                model = item.model()
                if model is None:
                    return total
                for i in range(model.rowCount(item)):
                    total += count_item(model.index(i, 0, item))
                return total
            data = item.data(0, Qt.UserRole) or {}
            total = 0 if data.get("placeholder") else 1
            for index in range(item.childCount()):
                total += count_item(item.child(index))
            return total

        def iter_top_rows(target_tree):
            n = self._planning_tree_top_level_count(target_tree)
            if isinstance(target_tree, QTreeView):
                model = target_tree.model()
                if model is None:
                    return []
                return [model.index(i, 0, QModelIndex()) for i in range(n)]
            return [target_tree.topLevelItem(i) for i in range(n)]

        total_count = 0
        for top_row in iter_top_rows(tree):
            total_count += count_item(top_row)
        return total_count

    def _current_selected_source_drive_id(self):
        if not hasattr(self, "planning_inputs"):
            return ""
        selector = self.planning_inputs.get("Source Library")
        if selector is None:
            return ""
        library = selector.currentData()
        if isinstance(library, dict):
            return library.get("id", "")
        return ""

    def _current_selected_destination_drive_id(self):
        if not hasattr(self, "planning_inputs"):
            return ""
        selector = self.planning_inputs.get("Destination Library")
        if selector is None:
            return ""
        library = selector.currentData()
        if isinstance(library, dict):
            return library.get("id", "")
        return ""

    def _canonical_destination_site_identity_from_data(self, site: dict | None) -> str:
        """Stable site key for destination identity (matches snapshot / gate comparisons)."""
        if not isinstance(site, dict):
            return ""
        return str(site.get("id") or site.get("site_key") or site.get("web_url") or "").strip()

    def _current_selected_destination_site_id(self) -> str:
        """Graph site id for the current Destination Site selector (strict identity with snapshot site)."""
        if not hasattr(self, "planning_inputs"):
            return ""
        selector = self.planning_inputs.get("Destination Site")
        if selector is None:
            return ""
        site = selector.currentData()
        return self._canonical_destination_site_identity_from_data(site if isinstance(site, dict) else None)

    def _planned_move_destination_drive_id(self, move) -> str:
        if not isinstance(move, dict):
            return ""
        d = str(move.get("DestinationDriveId") or "").strip()
        if d:
            return d
        dest = move.get("destination")
        if isinstance(dest, dict):
            return str(dest.get("drive_id") or "").strip()
        return ""

    def _proposed_folder_destination_drive_id(self, pf) -> str:
        if isinstance(pf, dict):
            return str(pf.get("DestinationDriveId") or "").strip()
        return str(getattr(pf, "DestinationDriveId", "") or "").strip()

    def _destination_planned_row_matches_selected_identity(
        self,
        move,
        *,
        sel_drive: str,
        sel_site: str,
        strict: bool,
    ) -> bool:
        if not isinstance(move, dict):
            return False
        md = self._planned_move_destination_drive_id(move)
        if md and sel_drive and md.casefold() != sel_drive.casefold():
            return False
        if strict and sel_drive and (not md):
            return False
        ms = str(move.get("DestinationSiteId") or move.get("destination_site_id") or "").strip()
        if sel_site and ms and ms.casefold() != sel_site.casefold():
            return False
        return True

    def _destination_proposed_row_matches_selected_identity(
        self,
        pf,
        *,
        sel_drive: str,
        sel_site: str,
        strict: bool,
    ) -> bool:
        md = self._proposed_folder_destination_drive_id(pf)
        if md and sel_drive and md.casefold() != sel_drive.casefold():
            return False
        if strict and sel_drive and (not md):
            return False
        if isinstance(pf, dict):
            ms = str(pf.get("DestinationSiteId") or pf.get("destination_site_id") or "").strip()
        else:
            ms = str(getattr(pf, "DestinationSiteId", "") or "").strip()
        if sel_site and ms and ms.casefold() != sel_site.casefold():
            return False
        return True

    def _destination_filter_planning_memory_to_selected_identity(self, *, context: str) -> tuple[int, int]:
        """Drop planned_moves / proposed_folders that do not match the selected destination site/drive."""
        if self._planning_browse_mode("destination") == "local":
            return 0, 0
        sel_drive = str(self._current_selected_destination_drive_id() or "").strip()
        if not sel_drive:
            sel_drive = str((getattr(self, "pending_root_drive_ids", None) or {}).get("destination") or "").strip()
        sel_site = str(self._current_selected_destination_site_id() or "").strip()
        strict = bool(getattr(self, "_destination_strict_planning_identity_required", False))
        if not sel_drive and not strict:
            return 0, 0
        if strict and not sel_drive:
            skipped_m = 0
            kept_m: list = []
            for m in list(self.planned_moves or []):
                if self._planned_move_destination_drive_id(m):
                    kept_m.append(m)
                else:
                    skipped_m += 1
                    log_info(
                        "destination_foreign_planning_row_skipped",
                        kind="planned_move",
                        context=str(context or "")[:160],
                        strict=bool(strict),
                        reason="strict_requires_destination_drive_on_row",
                    )
            if skipped_m:
                self.planned_moves = kept_m
            skipped_p = 0
            kept_p: list = []
            for pf in list(self.proposed_folders or []):
                if self._proposed_folder_destination_drive_id(pf):
                    kept_p.append(pf)
                else:
                    skipped_p += 1
                    log_info(
                        "destination_foreign_planning_row_skipped",
                        kind="proposed_folder",
                        context=str(context or "")[:160],
                        strict=bool(strict),
                        reason="strict_requires_destination_drive_on_row",
                    )
            if skipped_p:
                self.proposed_folders = kept_p
            return skipped_m, skipped_p
        skipped_m = 0
        kept_m: list = []
        legacy_tol_m = 0
        for m in list(self.planned_moves or []):
            md = self._planned_move_destination_drive_id(m) if isinstance(m, dict) else ""
            ms = str((m or {}).get("DestinationSiteId") or (m or {}).get("destination_site_id") or "").strip() if isinstance(m, dict) else ""
            if self._destination_planned_row_matches_selected_identity(
                m, sel_drive=sel_drive, sel_site=sel_site, strict=strict
            ):
                if isinstance(m, dict) and sel_drive and not md:
                    legacy_tol_m += 1
                kept_m.append(m)
                continue
            skipped_m += 1
            if md and sel_drive and md.casefold() != sel_drive.casefold():
                log_info(
                    "destination_planning_row_rejected_explicit_identity_mismatch",
                    kind="planned_move",
                    reason="drive_mismatch",
                    context=str(context or "")[:160],
                )
            elif sel_site and ms and ms.casefold() != sel_site.casefold():
                log_info(
                    "destination_planning_row_rejected_explicit_identity_mismatch",
                    kind="planned_move",
                    reason="site_mismatch",
                    context=str(context or "")[:160],
                )
            else:
                log_info(
                    "destination_foreign_planning_row_skipped",
                    kind="planned_move",
                    context=str(context or "")[:160],
                    strict=bool(strict),
                )
        if skipped_m:
            self.planned_moves = kept_m
        if legacy_tol_m:
            log_info(
                "destination_legacy_planning_identity_tolerated",
                kind="planned_move",
                count=int(legacy_tol_m),
                context=str(context or "")[:160],
            )
        skipped_p = 0
        kept_p: list = []
        legacy_tol_p = 0
        for pf in list(self.proposed_folders or []):
            md = self._proposed_folder_destination_drive_id(pf)
            if isinstance(pf, dict):
                ms = str(pf.get("DestinationSiteId") or pf.get("destination_site_id") or "").strip()
            else:
                ms = str(getattr(pf, "DestinationSiteId", "") or "").strip()
            if self._destination_proposed_row_matches_selected_identity(
                pf, sel_drive=sel_drive, sel_site=sel_site, strict=strict
            ):
                if sel_drive and not md:
                    legacy_tol_p += 1
                kept_p.append(pf)
                continue
            skipped_p += 1
            if md and sel_drive and md.casefold() != sel_drive.casefold():
                log_info(
                    "destination_planning_row_rejected_explicit_identity_mismatch",
                    kind="proposed_folder",
                    reason="drive_mismatch",
                    context=str(context or "")[:160],
                )
            elif sel_site and ms and ms.casefold() != sel_site.casefold():
                log_info(
                    "destination_planning_row_rejected_explicit_identity_mismatch",
                    kind="proposed_folder",
                    reason="site_mismatch",
                    context=str(context or "")[:160],
                )
            else:
                log_info(
                    "destination_foreign_planning_row_skipped",
                    kind="proposed_folder",
                    context=str(context or "")[:160],
                    strict=bool(strict),
                )
        if skipped_p:
            self.proposed_folders = kept_p
        if legacy_tol_p:
            log_info(
                "destination_legacy_planning_identity_tolerated",
                kind="proposed_folder",
                count=int(legacy_tol_p),
                context=str(context or "")[:160],
            )
        return skipped_m, skipped_p

    def _destination_filter_restored_planning_against_session_identity(
        self,
        session_state: SessionState,
        *,
        context: str,
    ) -> tuple[int, int]:
        """Skip draft allocations whose destination drive/site do not match the restored session selection."""
        exp_drive = str(getattr(session_state, "SelectedDestinationLibraryId", "") or "").strip()
        exp_site = str(getattr(session_state, "SelectedDestinationSiteKey", "") or "").strip()
        if not exp_drive and not exp_site:
            return 0, 0
        skipped_m = 0
        kept_m: list = []
        for m in list(self.planned_moves or []):
            md = self._planned_move_destination_drive_id(m)
            ok = True
            if exp_drive and md and md.casefold() != exp_drive.casefold():
                ok = False
            if ok and exp_site:
                ms = str((m or {}).get("DestinationSiteId") or (m or {}).get("destination_site_id") or "").strip()
                if ms and ms.casefold() != exp_site.casefold():
                    ok = False
            if ok:
                kept_m.append(m)
                continue
            skipped_m += 1
            log_info(
                "destination_foreign_planning_reload_skipped",
                kind="planned_move",
                context=str(context or "")[:160],
            )
        if skipped_m:
            self.planned_moves = kept_m
        skipped_p = 0
        kept_p: list = []
        for pf in list(self.proposed_folders or []):
            md = self._proposed_folder_destination_drive_id(pf)
            ok = True
            if exp_drive and md and md.casefold() != exp_drive.casefold():
                ok = False
            if ok and exp_site:
                if isinstance(pf, dict):
                    ms = str(pf.get("DestinationSiteId") or "").strip()
                else:
                    ms = str(getattr(pf, "DestinationSiteId", "") or "").strip()
                if ms and ms.casefold() != exp_site.casefold():
                    ok = False
            if ok:
                kept_p.append(pf)
                continue
            skipped_p += 1
            log_info(
                "destination_foreign_planning_reload_skipped",
                kind="proposed_folder",
                context=str(context or "")[:160],
            )
        if skipped_p:
            self.proposed_folders = kept_p
        return skipped_m, skipped_p

    def _destination_prune_multi_hub_foreign_roots(self, *, intended_drive_id: str) -> None:
        """When multiple top-level hubs exist, remove non–live-graph scaffolds that conflict with the selected drive."""
        model = getattr(self, "destination_planning_model", None)
        if model is None:
            return
        did = str(intended_drive_id or "").strip()
        if not did:
            return
        inv = QModelIndex()
        try:
            rc = int(model.rowCount(inv))
        except Exception:
            return
        if rc <= 1:
            return
        good_tr: list[int] = []
        bad_tr: list[int] = []
        for tr in range(rc):
            ix = model.index(tr, 0, inv)
            pl = ix.data(Qt.UserRole) or {}
            if not isinstance(pl, dict) or pl.get("placeholder"):
                continue
            rd = str(pl.get("drive_id") or "").strip()
            live = destination_payload_is_live_graph_row(pl)
            if live and rd and rd.casefold() == did.casefold():
                good_tr.append(tr)
                continue
            if live and rd and rd.casefold() != did.casefold():
                bad_tr.append(tr)
                continue
            if not live:
                bad_tr.append(tr)
        if not good_tr or not bad_tr:
            return
        for tr in sorted(set(bad_tr), reverse=True):
            try:
                model._remove_root_row(tr)
            except Exception:
                pass
        log_info(
            "destination_multi_hub_foreign_prune",
            removed=len(bad_tr),
            kept_live=len(good_tr),
            intended_drive_suffix=did[-16:] if len(did) > 16 else did,
        )

    def _memory_restore_blocks_source_full_count(self) -> bool:
        """True while memory restore owns the session; full library counts must not run yet."""
        return bool(
            getattr(self, "_memory_restore_in_progress", False)
            or getattr(self, "_memory_restore_background_trees", False)
        )

    def _memory_restore_foreground_phase_busy(self) -> bool:
        """True during selector/UI rebind before async tree work; False during background tree materialization."""
        return bool(
            getattr(self, "_memory_restore_in_progress", False)
            and not getattr(self, "_memory_restore_background_trees", False)
        )

    def _graph_file_count_display(self):
        current_drive_id = self._current_selected_source_drive_id()
        if not current_drive_id:
            return "0"
        if (
            self._memory_restore_blocks_source_full_count()
            and str(getattr(self, "_full_count_pending_drive_id_after_restore", "") or "") == current_drive_id
        ):
            return "Deferred"
        if (
            self.full_source_file_count is not None
            and self._full_count_completed_drive_id == current_drive_id
        ):
            return str(int(self.full_source_file_count))
        if self._full_count_error_message and self._full_count_requested_drive_id == current_drive_id:
            return "—"
        if self._full_count_requested_drive_id == current_drive_id:
            return "…"
        if getattr(self, "_sharepoint_lazy_mode", False):
            return "On demand"
        return "0"

    def _graph_folder_count_display(self):
        current_drive_id = self._current_selected_source_drive_id()
        if not current_drive_id:
            return "0"
        if (
            self._memory_restore_blocks_source_full_count()
            and str(getattr(self, "_full_count_pending_drive_id_after_restore", "") or "") == current_drive_id
        ):
            return "Deferred"
        if (
            self.full_source_folder_count is not None
            and self._full_count_completed_drive_id == current_drive_id
        ):
            return str(int(self.full_source_folder_count))
        if self._full_count_error_message and self._full_count_requested_drive_id == current_drive_id:
            return "—"
        if self._full_count_requested_drive_id == current_drive_id:
            return "…"
        if getattr(self, "_sharepoint_lazy_mode", False):
            return "On demand"
        return "0"

    def _update_source_count_labels(self, loaded_items):
        self._cached_loaded_source_items = int(loaded_items or 0)
        loaded_text = str(loaded_items)
        files_text = self._graph_file_count_display()
        folders_text = self._graph_folder_count_display()

        for label in [
            getattr(self, "dashboard_loaded_items", None),
            getattr(self, "workspace_loaded_items", None),
        ]:
            if label is not None:
                label.setText(loaded_text)

        for label in [
            getattr(self, "dashboard_graph_files", None),
            getattr(self, "workspace_graph_files", None),
        ]:
            if label is not None:
                label.setText(files_text)

        for label in [
            getattr(self, "dashboard_graph_folders", None),
            getattr(self, "workspace_graph_folders", None),
        ]:
            if label is not None:
                label.setText(folders_text)

    def _reset_full_count_state(self):
        self.full_source_item_count = None
        self.full_source_file_count = None
        self.full_source_folder_count = None
        self._full_count_error_message = ""
        self._full_count_requested_drive_id = ""
        self._full_count_completed_drive_id = ""
        self._full_count_pending_drive_id_after_restore = ""
        self._update_source_count_labels(0)

    def _reset_destination_full_tree_state(self):
        self._destination_full_tree_snapshot = []
        self._mark_destination_real_tree_snapshot_stale()
        self._destination_full_tree_requested_drive_id = ""
        self._destination_full_tree_completed_drive_id = ""
        self._destination_full_tree_materialization_pending = False
        self._destination_idle_materialize_parked_for_full_tree_reason = ""
        self._destination_idle_materialize_full_tree_park_requested_drive_id = ""
        self._destination_invalidate_spo_snapshot_trust("reset_full_tree_state")
        self._destination_authoritative_recursive_item_total = 0
        self._destination_authoritative_structure_fp = ""
        timer = getattr(self, "_destination_full_tree_materialize_timer", None)
        if timer is not None:
            timer.stop()

    def _invalidate_destination_full_tree_for_live_reconcile(self, drive_id: str) -> None:
        """Drop completed full-tree results so the next walk re-reads live Graph (used after force_refresh)."""
        did = str(drive_id or "").strip()
        if not did:
            return
        if self._destination_full_tree_completed_drive_id == did:
            self._destination_full_tree_snapshot = []
            self._destination_full_tree_completed_drive_id = ""
            self._destination_authoritative_recursive_item_total = 0
            self._destination_authoritative_structure_fp = ""
        self._mark_destination_real_tree_snapshot_stale()
        self._destination_invalidate_spo_snapshot_trust("invalidate_full_tree_reconcile")

    def _destination_invalidate_spo_snapshot_trust(self, reason: str) -> None:
        self._destination_snapshot_valid_for_drive = False
        self._destination_snapshot_trust_drive_id = ""
        self._destination_snapshot_trust_monotonic = 0.0
        if str(reason or "") == "full_live_walk_started":
            log_info(
                "destination_authority_invalidated_unpromoted_startup_branch",
                note="spo_enumeration_trust_reset_runtime_session_snapshot_may_still_hold_promoted_rows",
                promoted_startup_paths_tracked=len(getattr(self, "_destination_startup_promoted_semantic_paths", set()) or set()),
            )
        self._log_restore_phase(
            "snapshot_trust_invalidated",
            reason=str(reason or ""),
        )

    def _destination_mark_spo_snapshot_trust_valid(self, drive_id: str, validation_kind: str) -> None:
        did = str(drive_id or "").strip()
        if not did:
            return
        self._destination_snapshot_valid_for_drive = True
        self._destination_snapshot_trust_drive_id = did
        self._destination_snapshot_trust_monotonic = time.monotonic()
        self._log_restore_phase(
            "snapshot_validated_against_live",
            drive_id_suffix=did[-16:] if len(did) > 16 else did,
            validation_kind=str(validation_kind or ""),
        )

    def _destination_snapshot_spo_trust_valid(self, drive_id: str) -> bool:
        did = str(drive_id or "").strip()
        if not did or not self._destination_snapshot_valid_for_drive:
            return False
        if str(self._destination_snapshot_trust_drive_id or "").strip() != did:
            return False
        ttl = float(getattr(self, "_DESTINATION_SPO_SNAPSHOT_TRUST_TTL_SEC", 300.0) or 300.0)
        age = time.monotonic() - float(self._destination_snapshot_trust_monotonic or 0.0)
        return age <= ttl

    def _destination_root_children_fingerprint_from_full_snapshot(self) -> tuple[str, int]:
        """Stable fingerprint of root-level item ids in the completed full-library snapshot."""
        root_keys = frozenset({self.normalize_memory_path("Root"), ""})
        ids: list[str] = []
        for entry in self._destination_full_tree_snapshot or []:
            raw_parent = str(entry.get("parent_semantic_path", "") or "").strip()
            parent = self.normalize_memory_path(raw_parent)
            if parent not in root_keys and raw_parent != OVERLAY_LIB_ROOT_SEMANTIC:
                continue
            data = entry.get("data") or {}
            iid = str(data.get("id", "") or "").strip()
            if iid:
                ids.append(iid)
        ids.sort()
        fp = hashlib.sha256("|".join(ids).encode("utf-8")).hexdigest()
        return fp, len(ids)

    def _destination_authoritative_structure_fp_resolve(self) -> str:
        """Baseline structural digest for trust checks (persisted field or backfill from in-memory snapshot)."""
        fp = str(getattr(self, "_destination_authoritative_structure_fp", "") or "").strip()
        if fp:
            return fp
        lines: list[str] = []
        for entry in self._destination_full_tree_snapshot or []:
            if not isinstance(entry, dict):
                continue
            sp = str(entry.get("semantic_path", "") or "").strip()
            data = entry.get("data") or {}
            iid = str(data.get("id", "") or "").strip()
            if sp and iid:
                lines.append(f"{sp}\x1f{iid}")
        lines.sort()
        if not lines:
            return ""
        return hashlib.sha256("\n".join(lines).encode("utf-8")).hexdigest()

    def _destination_tree_shows_authority_pending_shell(self) -> bool:
        if self._planning_browse_mode("destination") != "local" and getattr(
            self, "_destination_authority_pending_shell", False
        ):
            return True
        if self._planning_browse_mode("destination") != "local" and getattr(
            self, "_destination_full_library_reconcile_pending", False
        ):
            return True
        dm = getattr(self, "destination_planning_model", None)
        if dm is None:
            return False
        root = QModelIndex()
        if dm.rowCount(root) < 1:
            return False
        for tr in range(dm.rowCount(root)):
            top_ix = dm.index(tr, 0, root)
            pl = dm.data(top_ix, Qt.UserRole)
            if isinstance(pl, dict) and pl.get("placeholder_role") == "destination_authority_pending":
                return True
            for r in range(dm.rowCount(top_ix)):
                ix = dm.index(r, 0, top_ix)
                ch = dm.data(ix, Qt.UserRole)
                if isinstance(ch, dict) and ch.get("placeholder_role") == "destination_authority_pending":
                    return True
        return False

    def _destination_materialize_requires_authoritative_hard_flush(self, reason: str) -> bool:
        """When the full-library snapshot is ready and trusted, flush the non-authoritative shell with no deferrals.

        Bypasses steady-state skip, incremental-merge / restore / redundant-materialize / bind-signature shortcuts
        so the placeholder cannot outlive a trusted authoritative enumerate.
        """
        if self._planning_browse_mode("destination") == "local":
            return False
        if not self._destination_sharepoint_planning_destination_active():
            return False
        if not self._destination_full_tree_ready():
            return False
        did = str(
            self._current_selected_destination_drive_id()
            or self.pending_root_drive_ids.get("destination", "")
            or getattr(self, "_destination_full_tree_completed_drive_id", "")
            or ""
        ).strip()
        if not did or not self._destination_snapshot_spo_trust_valid(did):
            return False
        r = str(reason or "")
        if r in _DESTINATION_AUTHORITY_SHELL_HARD_FLUSH_REASONS:
            return True
        if self._destination_tree_shows_authority_pending_shell():
            return True
        if getattr(self, "_destination_non_authoritative_shell_active", False):
            return True
        return False

    def _schedule_destination_authority_shell_watchdog(self, delay_ms: int = 35000) -> None:
        self._destination_authority_shell_watchdog_generation = int(
            getattr(self, "_destination_authority_shell_watchdog_generation", 0) or 0
        ) + int(1)
        gen = int(self._destination_authority_shell_watchdog_generation)

        def _fire():
            self._destination_authority_shell_watchdog_fire(gen)

        QTimer.singleShot(max(500, int(delay_ms)), lambda: self._safe_invoke("destination_authority_shell_watchdog", _fire))

    def _destination_authority_shell_watchdog_fire(self, generation: int) -> None:
        if int(generation) != int(getattr(self, "_destination_authority_shell_watchdog_generation", 0) or 0):
            return
        if self._planning_browse_mode("destination") == "local":
            return
        if not self._destination_tree_shows_authority_pending_shell():
            return
        did = str(
            self.pending_root_drive_ids.get("destination") or self._current_selected_destination_drive_id() or ""
        ).strip()
        ft_running = self._destination_full_tree_worker is not None and self._destination_full_tree_worker.isRunning()
        ready = self._destination_full_tree_ready()
        trust_ok = bool(did) and self._destination_snapshot_spo_trust_valid(did)
        mat_pending = bool(getattr(self, "_destination_full_tree_materialization_pending", False))
        restore_wait = bool(getattr(self, "_destination_snapshot_chunked_restore_active", False))
        proj_wait = getattr(self, "_destination_future_projection_async_state", None) is not None
        chunked = getattr(self, "_destination_chunked_bind_state", None) is not None
        bind_sync = bool(getattr(self, "_destination_future_bind_sync_active", False))
        light_w = getattr(self, "_destination_snapshot_light_validation_worker", None)
        light_running = light_w is not None and light_w.isRunning()

        stall_kind = "unknown_stall"
        if light_running and not trust_ok:
            stall_kind = "waiting_for_trust_validation"
        elif restore_wait:
            stall_kind = "waiting_for_restore_overlay"
        elif proj_wait:
            stall_kind = "waiting_for_finalize"
        elif chunked or bind_sync:
            stall_kind = "waiting_for_materialize"
        elif ready and trust_ok:
            stall_kind = "waiting_for_materialize"
        elif ft_running:
            stall_kind = "worker_running_slow"
        elif did and ready and not trust_ok:
            stall_kind = "snapshot_trust_expired_or_invalid"
        elif not ft_running and not ready:
            stall_kind = "worker_not_running"

        self._log_restore_phase(
            "destination_authority_shell_stall",
            stall_kind=stall_kind,
            drive_id_suffix=did[-16:] if len(did) > 16 else did,
            full_tree_worker_running=bool(ft_running),
            full_tree_ready=bool(ready),
            snapshot_trust_valid=bool(trust_ok),
            full_tree_materialize_pending=bool(mat_pending),
            waiting_restore_overlay=bool(restore_wait),
            async_projection_pending=bool(proj_wait),
            chunked_bind_pending=bool(chunked),
            bind_sync_active=bool(bind_sync),
            light_validation_running=bool(light_running),
        )
        recovered_trust = False
        if (
            did
            and self._destination_tree_shows_authority_pending_shell()
            and self._destination_full_tree_ready()
            and not trust_ok
        ):
            recovered_trust = bool(self._destination_try_recover_stall_trust_and_flush(did))
        if recovered_trust:
            log_info(
                "destination_authority_shell_stall_recovered",
                stall_kind=str(stall_kind or "")[:80],
                drive_id_suffix=did[-16:] if len(did) > 16 else did,
                recovery="trust_ttl_refresh",
            )
            return
        if ready and trust_ok:
            self._flush_destination_authority_shell_if_ready("destination_authority_shell_watchdog_flush")
        elif stall_kind == "worker_not_running" and did:
            if self._destination_try_watchdog_skeleton_child_retry_instead_of_full_tree(did):
                return
            log_info(
                "destination_full_tree_worker_rekick_after_stall",
                drive_id_suffix=did[-16:] if len(did) > 16 else did,
            )
            self._ensure_sharepoint_destination_full_tree_worker_scheduled(
                did,
                schedule_reason="destination_authority_stall_rekick",
                recovery=True,
            )

    def _destination_planned_reconcile_after_authority_or_flush_overlay(self, *, exception_log_key: str) -> None:
        """Run global planned-parent reconcile once per overlay stack.

        :meth:`_apply_destination_planning_overlays_body` already reconciles at end of a full
        ``destination_planning_overlay_pass``. Authority-shell wrappers used to call reconcile again
        unconditionally, doubling whole-tree work when the overlay pass completed.
        """
        if bool(getattr(self, "_destination_overlay_terminal_reconcile_done", False)):
            return
        try:
            self._destination_reconcile_all_planned_parents_after_graph_update(
                _request_overlay_terminal_completion_mark=True,
            )
        except Exception as exc:
            self._log_restore_exception(exception_log_key, exc)

    def _flush_destination_authority_shell_if_ready(self, reason: str) -> None:
        if self._planning_browse_mode("destination") == "local":
            return
        if not self._destination_tree_shows_authority_pending_shell():
            return
        if not self._destination_full_tree_ready():
            return
        did = str(
            self.pending_root_drive_ids.get("destination")
            or self._current_selected_destination_drive_id()
            or getattr(self, "_destination_full_tree_completed_drive_id", "")
            or ""
        ).strip()
        if not did or not self._destination_snapshot_spo_trust_valid(did):
            return
        self._log_restore_phase(
            "destination_authority_forced_shell_flush",
            reason=str(reason or "")[:120],
            drive_id_suffix=did[-16:] if len(did) > 16 else did,
        )
        self._destination_full_tree_materialization_pending = False
        tmr = getattr(self, "_destination_full_tree_materialize_timer", None)
        if tmr is not None:
            try:
                tmr.stop()
            except Exception:
                pass
        _forensic = dest_forensic.slow_pass_forensic_enabled()
        _t_flush = time.perf_counter()
        self._apply_destination_planning_overlays(
            "destination_authority_shell_hard_flush",
            allow_defer=False,
            prefer_chunked_projection=True,
        )
        _apply_ms = (time.perf_counter() - _t_flush) * 1000.0
        _t_rec = time.perf_counter()
        _done_before = bool(getattr(self, "_destination_overlay_terminal_reconcile_done", False))
        self._destination_planned_reconcile_after_authority_or_flush_overlay(
            exception_log_key="destination_authority_shell_flush_global_planned_reconcile",
        )
        _rec_ms = (time.perf_counter() - _t_rec) * 1000.0
        if _forensic:
            log_info(
                "destination_slow_pass_forensic",
                phase="authority_shell_hard_flush",
                flush_reason=str(reason or "")[:160],
                apply_destination_planning_overlays_ms=round(_apply_ms, 2),
                planned_reconcile_ms=round(_rec_ms, 2),
                    skipped_planned_reconcile=_done_before,
            )

    def _destination_try_recover_stall_trust_and_flush(self, did: str) -> bool:
        """Re-latch SPO trust when full enumerate completed but TTL/trust dropped while shell still pending.

        Avoids indefinite 'reconciling' when ``_destination_snapshot_spo_trust_valid`` expires (300s TTL) after
        ``on_destination_full_tree_success`` already marked the walk complete.
        """
        did = str(did or "").strip()
        if not did:
            return False
        if self._planning_browse_mode("destination") == "local":
            return False
        if not self._destination_tree_shows_authority_pending_shell():
            return False
        if not self._destination_full_tree_ready():
            return False
        done = str(getattr(self, "_destination_full_tree_completed_drive_id", "") or "").strip()
        if done.casefold() != did.casefold():
            return False
        if self._destination_snapshot_spo_trust_valid(did):
            return False
        self._destination_mark_spo_snapshot_trust_valid(did, "stall_recovery_trust_ttl_refresh")
        log_info(
            "destination_full_tree_ready_latched",
            recovery_kind="trust_ttl_refresh",
            drive_id_suffix=did[-16:] if len(did) > 16 else did,
        )
        self._flush_destination_authority_shell_if_ready("destination_authority_shell_stall_recovery")
        log_info(
            "destination_reconcile_status_cleared",
            trigger="stall_recovery_trust_refresh",
            drive_id_suffix=did[-16:] if len(did) > 16 else did,
        )
        return True

    def _destination_model_has_authority_pending_placeholder_rows(self) -> bool:
        """Model scan only (ignores reconcile / shell latches)."""
        dm = getattr(self, "destination_planning_model", None)
        if dm is None:
            return False
        root = QModelIndex()
        if dm.rowCount(root) < 1:
            return False
        for tr in range(dm.rowCount(root)):
            top_ix = dm.index(tr, 0, root)
            pl = dm.data(top_ix, Qt.UserRole)
            if isinstance(pl, dict) and pl.get("placeholder_role") == "destination_authority_pending":
                return True
            for r in range(dm.rowCount(top_ix)):
                ix = dm.index(r, 0, top_ix)
                ch = dm.data(ix, Qt.UserRole)
                if isinstance(ch, dict) and ch.get("placeholder_role") == "destination_authority_pending":
                    return True
        return False

    def _destination_force_clear_authority_shell_state_after_authoritative_bind(self, trigger: str) -> None:
        """Clear shell latches and re-apply overlays when bind is authoritative (not gated like flush-if-ready).

        Invoked from authoritative bind commit only — not from steady-state gate evaluation — so this does
        not thrash on each reconcile tick.
        """
        try:
            if self._planning_browse_mode("destination") == "local":
                return
            if not self._destination_graph_enumeration_ignores_memory_restore_gate():
                return
            if not self._destination_root_bind_is_authoritative():
                return
        except Exception:
            return
        prev_ap = bool(getattr(self, "_destination_authority_pending_shell", False))
        prev_nauth = bool(getattr(self, "_destination_non_authoritative_shell_active", False))
        prev_reconcile = bool(getattr(self, "_destination_full_library_reconcile_pending", False))
        try:
            model_ph = self._destination_model_has_authority_pending_placeholder_rows()
        except Exception:
            model_ph = False
        if not (prev_ap or prev_nauth or prev_reconcile or model_ph):
            return
        had_latch = prev_ap or prev_nauth or prev_reconcile
        _forensic = dest_forensic.slow_pass_forensic_enabled()
        _t_shell = time.perf_counter()
        if had_latch:
            log_info(
                "destination_authority_shell_force_cleared_after_authoritative_bind",
                previous_authority_pending_shell=prev_ap,
                previous_non_authoritative_shell_active=prev_nauth,
                destination_root_bind_is_authoritative=True,
                trigger=str(trigger or "")[:200],
            )
            self._destination_authority_pending_shell = False
            self._destination_non_authoritative_shell_active = False
            self._destination_full_library_reconcile_pending = False
            self._destination_full_tree_materialization_pending = False
            tmr = getattr(self, "_destination_full_tree_materialize_timer", None)
            if tmr is not None:
                try:
                    tmr.stop()
                except Exception:
                    pass
        _precheck_ms = (time.perf_counter() - _t_shell) * 1000.0
        _t_apply = time.perf_counter()
        try:
            self._apply_destination_planning_overlays(
                "destination_authority_shell_force_cleared_after_authoritative_bind",
                allow_defer=False,
                prefer_chunked_projection=True,
            )
        except Exception:
            pass
        _apply_ms = (time.perf_counter() - _t_apply) * 1000.0
        _t_rec = time.perf_counter()
        _done_before = bool(getattr(self, "_destination_overlay_terminal_reconcile_done", False))
        self._destination_planned_reconcile_after_authority_or_flush_overlay(
            exception_log_key="destination_authority_shell_force_cleared_global_planned_reconcile",
        )
        _rec_ms = (time.perf_counter() - _t_rec) * 1000.0
        if _forensic:
            log_info(
                "destination_slow_pass_forensic",
                phase="authority_shell_force_cleared_after_authoritative_bind",
                trigger=str(trigger or "")[:200],
                had_authority_shell_latch=bool(had_latch),
                precheck_after_latch_clear_ms=round(_precheck_ms, 2),
                apply_destination_planning_overlays_ms=round(_apply_ms, 2),
                planned_reconcile_ms=round(_rec_ms, 2),
                skipped_planned_reconcile=_done_before,
            )

    def _destination_on_authoritative_tree_bind_committed(self, bind_kind: str) -> None:
        bk = str(bind_kind or "")
        had_non_auth = bool(getattr(self, "_destination_non_authoritative_shell_active", False))
        try:
            had_pending_shell = bool(self._destination_tree_shows_authority_pending_shell())
        except Exception:
            had_pending_shell = False
        self._destination_force_clear_authority_shell_state_after_authoritative_bind(
            f"authoritative_tree_bind_committed:{bk[:80]}"
        )
        if had_non_auth or had_pending_shell:
            self._log_restore_phase(
                "destination_authority_pipeline",
                step="authoritative_bind_complete",
                bind_kind=bk,
            )
            self._destination_clear_restore_blockers_after_authoritative_bind(bk)
            self._destination_resume_snapshot_branch_refresh_after_authority()
        self._destination_try_clear_stale_foreground_memory_restore_gate(
            f"authoritative_tree_bind_committed:{bk[:80]}"
        )

    def _destination_materialize_authoritative_if_shell_still_showing(self, tag: str) -> None:
        """Last-resort: trusted full-library snapshot exists but the authority placeholder row is still visible."""
        if self._planning_browse_mode("destination") == "local":
            return
        if not self._destination_sharepoint_planning_destination_active():
            return
        if not self._destination_full_tree_ready():
            return
        if not self._destination_tree_shows_authority_pending_shell():
            return
        did = str(
            self._current_selected_destination_drive_id()
            or self.pending_root_drive_ids.get("destination", "")
            or getattr(self, "_destination_full_tree_completed_drive_id", "")
            or ""
        ).strip()
        if not did or not self._destination_snapshot_spo_trust_valid(did):
            return
        self._log_restore_phase(
            "destination_authority_pipeline",
            step="authority_shell_safety_net_materialize",
            tag=str(tag or "")[:120],
            drive_id_suffix=did[-16:] if len(did) > 16 else did,
        )
        self._apply_destination_planning_overlays(
            "destination_authority_shell_hard_flush",
            allow_defer=False,
            prefer_chunked_projection=True,
        )

    def _destination_begin_spo_snapshot_light_validation(self, drive_id: str) -> None:
        did = str(drive_id or "").strip()
        if not did or not getattr(self, "graph", None):
            return
        if self._destination_full_tree_worker is not None and self._destination_full_tree_worker.isRunning():
            return
        lw = getattr(self, "_destination_snapshot_light_validation_worker", None)
        if lw is not None and lw.isRunning():
            return
        w = DestinationSnapshotLightValidationWorker(self.graph, did, self._destination_full_tree_context())
        self._destination_snapshot_light_validation_worker = w
        w.success.connect(
            lambda payload: self._safe_invoke(
                "destination_spo_light_validation.success",
                self._on_destination_spo_snapshot_light_validation_success,
                payload,
            )
        )
        w.error.connect(
            lambda payload: self._safe_invoke(
                "destination_spo_light_validation.error",
                self._on_destination_spo_snapshot_light_validation_error,
                payload,
            )
        )
        w.finished.connect(self._on_destination_spo_snapshot_light_validation_finished)
        self._log_restore_phase(
            "destination_authority_pipeline",
            step="live_validation_full_library_enumerate_started",
            drive_id_suffix=did[-16:] if len(did) > 16 else did,
        )
        w.start()

    def _on_destination_spo_snapshot_light_validation_finished(self) -> None:
        w = getattr(self, "_destination_snapshot_light_validation_worker", None)
        self._destination_snapshot_light_validation_worker = None
        if w is not None:
            w.deleteLater()

    def _on_destination_spo_snapshot_light_validation_success(self, payload: dict) -> None:
        drive_id = str((payload or {}).get("drive_id", "") or "").strip()
        if not drive_id or self._destination_full_tree_completed_drive_id != drive_id:
            return
        live_fp = str((payload or {}).get("root_fingerprint", "") or "")
        snap_fp, snap_n = self._destination_root_children_fingerprint_from_full_snapshot()
        live_n = int((payload or {}).get("root_child_count") or 0)
        if live_fp != snap_fp:
            self._log_restore_phase(
                "snapshot_invalid_requires_live_check",
                reason="root_fingerprint_mismatch",
                drive_id_suffix=drive_id[-16:] if len(drive_id) > 16 else drive_id,
                snapshot_root_children=snap_n,
                live_root_children=live_n,
            )
            self._invalidate_destination_full_tree_for_live_reconcile(drive_id)
            QTimer.singleShot(
                0,
                lambda d=drive_id: self._safe_invoke(
                    "destination_spo_light_mismatch_full_walk",
                    lambda: self._ensure_sharepoint_destination_full_tree_worker_scheduled(
                        d,
                        schedule_reason="spo_snapshot_root_fingerprint_mismatch",
                        recovery=True,
                    ),
                ),
            )
            return
        stored_deep = int(getattr(self, "_destination_authoritative_recursive_item_total", 0) or 0)
        _raw_deep = (payload or {}).get("recursive_item_total_live")
        live_deep = int(_raw_deep) if _raw_deep is not None else -1
        if stored_deep > 0 and live_deep >= 0 and live_deep != stored_deep:
            self._log_restore_phase(
                "snapshot_invalid_requires_live_check",
                reason="recursive_item_total_mismatch",
                drive_id_suffix=drive_id[-16:] if len(drive_id) > 16 else drive_id,
                snapshot_recursive_item_total=stored_deep,
                live_recursive_item_total=live_deep,
            )
            self._invalidate_destination_full_tree_for_live_reconcile(drive_id)
            QTimer.singleShot(
                0,
                lambda d=drive_id: self._safe_invoke(
                    "destination_spo_deep_count_mismatch_full_walk",
                    lambda: self._ensure_sharepoint_destination_full_tree_worker_scheduled(
                        d,
                        schedule_reason="spo_snapshot_recursive_count_mismatch",
                        recovery=True,
                    ),
                ),
            )
            return
        stored_struct = self._destination_authoritative_structure_fp_resolve()
        live_struct = str((payload or {}).get("structure_fingerprint", "") or "")
        if stored_struct and live_struct and live_struct != stored_struct:
            self._log_restore_phase(
                "snapshot_invalid_requires_live_check",
                reason="structure_fingerprint_mismatch",
                drive_id_suffix=drive_id[-16:] if len(drive_id) > 16 else drive_id,
                snapshot_structure_prefix=stored_struct[:16],
                live_structure_prefix=live_struct[:16],
            )
            self._invalidate_destination_full_tree_for_live_reconcile(drive_id)
            QTimer.singleShot(
                0,
                lambda d=drive_id: self._safe_invoke(
                    "destination_spo_structure_mismatch_full_walk",
                    lambda: self._ensure_sharepoint_destination_full_tree_worker_scheduled(
                        d,
                        schedule_reason="spo_snapshot_structure_fingerprint_mismatch",
                        recovery=True,
                    ),
                ),
            )
            return
        self._destination_mark_spo_snapshot_trust_valid(drive_id, "lightweight_root_plus_structure_digest")
        self._log_restore_phase(
            "destination_authority_pipeline",
            step="snapshot_trust_valid",
            drive_id_suffix=drive_id[-16:] if len(drive_id) > 16 else drive_id,
            validation_kind="lightweight_root_plus_structure_digest",
        )
        self._log_restore_phase(
            "snapshot_reuse_allowed",
            drive_id_suffix=drive_id[-16:] if len(drive_id) > 16 else drive_id,
            validation_kind="lightweight_root_plus_structure_digest",
            root_child_count=live_n,
            live_recursive_item_total=live_deep,
            snapshot_recursive_item_total=stored_deep,
        )
        self._destination_flush_trust_gate_pending_materialize()

    def _on_destination_spo_snapshot_light_validation_error(self, payload: dict) -> None:
        drive_id = str((payload or {}).get("drive_id", "") or "").strip()
        self._log_restore_phase(
            "snapshot_invalid_requires_live_check",
            reason="light_validation_error",
            drive_id_suffix=drive_id[-16:] if len(drive_id) > 16 else drive_id,
            error_excerpt=str((payload or {}).get("error", "") or "")[:240],
        )
        if drive_id:
            self._invalidate_destination_full_tree_for_live_reconcile(drive_id)
            QTimer.singleShot(
                0,
                lambda d=drive_id: self._safe_invoke(
                    "destination_spo_light_error_full_walk",
                    lambda: self._ensure_sharepoint_destination_full_tree_worker_scheduled(
                        d,
                        schedule_reason="spo_snapshot_light_validation_error",
                        recovery=True,
                    ),
                ),
            )

    def _destination_flush_trust_gate_pending_materialize(self) -> None:
        pending = getattr(self, "_destination_trust_gate_pending_materialize", None)
        if pending is None:
            return
        self._destination_trust_gate_pending_materialize = None
        reason, allow_defer, prefer_chunked, narrow = pending
        shell_active = bool(
            self._destination_tree_shows_authority_pending_shell()
            or getattr(self, "_destination_non_authoritative_shell_active", False)
        )

        def _run():
            self._apply_destination_planning_overlays(
                reason,
                allow_defer=False if shell_active else allow_defer,
                prefer_chunked_projection=prefer_chunked,
                narrow_restore_real_snapshot=narrow,
            )

        QTimer.singleShot(0, lambda: self._safe_invoke("destination_trust_gate_materialize_flush", _run))

    def _destination_full_tree_context(self):
        if not hasattr(self, "planning_inputs"):
            return {}
        destination_site_selector = self.planning_inputs.get("Destination Site")
        destination_library_selector = self.planning_inputs.get("Destination Library")
        site = destination_site_selector.currentData() if destination_site_selector is not None else {}
        library = destination_library_selector.currentData() if destination_library_selector is not None else {}
        site = site if isinstance(site, dict) else {}
        library = library if isinstance(library, dict) else {}
        return {
            "site_id": site.get("id", ""),
            "site_name": site.get("name", ""),
            "library_id": library.get("id", ""),
            "library_name": library.get("name", ""),
            "tree_role": "destination",
        }

    def _destination_full_tree_ready(self):
        """True when an in-memory full-library snapshot exists for the active destination library context.

        If the selector and pending root ids are momentarily empty (UI churn) but a completed enumerate exists,
        we still treat the snapshot as ready unless the user has explicitly selected a *different* library id.

        A successful Graph walk can yield items that do not project into ``_destination_full_tree_snapshot``
        (canonical-path filtering) or an **empty** document library (zero items). In those cases we still
        treat the completed walk as ready when ``_destination_full_tree_completed_drive_id`` matches and
        the walk reported a definitive item total (including zero).
        """
        done = str(getattr(self, "_destination_full_tree_completed_drive_id", "") or "").strip()
        if not done:
            return False
        sel = str(self._current_selected_destination_drive_id() or "").strip()
        pend = str(self.pending_root_drive_ids.get("destination", "") or "").strip()
        if sel and sel != done:
            return False
        if pend and pend != done:
            return False
        snap = getattr(self, "_destination_full_tree_snapshot", None)
        if snap:
            return True
        # Walk completed: snapshot rows may be empty while Graph reported items (path canonicalization), or library may be empty.
        return True

    def _destination_sharepoint_planning_destination_active(self) -> bool:
        return self._planning_browse_mode("destination") != "local" and getattr(
            self, "destination_planning_model", None
        ) is not None

    def _destination_sharepoint_live_graph_structure_authority_active(self) -> bool:
        """Visible real destination rows are owned by Graph root/folder loads, not future-model snapshot import."""
        return destination_authority_contract.graph_owns_visible_real_destination_structure(self)

    def _destination_infer_single_library_folder_anchor_from_live_model(self) -> str:
        """Like :meth:`_destination_infer_single_library_folder_anchor_path` but reads the live planning model."""
        dm = getattr(self, "destination_planning_model", None)
        if dm is None:
            return ""
        root = QModelIndex()
        children: list[str] = []
        for r in range(dm.rowCount(root)):
            ix = dm.index(r, 0, root)
            pl = ix.data(Qt.UserRole) or {}
            if pl.get("placeholder"):
                continue
            if not bool(pl.get("is_folder")):
                continue
            sp = self._destination_semantic_path(pl)
            if not sp or self.normalize_memory_path(str(sp)).lower() == "root":
                continue
            children.append(self.normalize_memory_path(str(sp)))
        if len(children) != 1:
            return ""
        return children[0]

    def _destination_resolve_overlay_incremental_parent_item(self, parent_semantic_path: str):
        """Map internal ``Root`` parent to the invisible model root; otherwise resolve a live Graph row."""
        raw_parent = str(parent_semantic_path or "").strip()
        if raw_parent == OVERLAY_LIB_ROOT_SEMANTIC:
            return QModelIndex()
        pp = self.normalize_memory_path(raw_parent)
        if is_internal_planning_root_semantic_path(pp):
            return QModelIndex()
        item = self._resolve_incremental_merge_parent_item(pp)
        if item is None:
            return None
        if isinstance(item, QModelIndex):
            return item if item.isValid() else None
        return item

    def _destination_authoritative_preview_pipeline_idle(self) -> bool:
        """True when live library enumeration and in-flight structural work are finished (SharePoint)."""
        if not self._destination_sharepoint_planning_destination_active():
            return True
        if self._destination_tree_shows_authority_pending_shell():
            return False
        if not self._destination_full_tree_ready():
            return False
        if self.pending_folder_loads.get("destination"):
            return False
        if getattr(self, "_destination_incremental_merge_in_progress", False):
            return False
        if getattr(self, "_destination_incremental_merge_session", None) is not None:
            return False
        if getattr(self, "_destination_future_projection_async_state", None) is not None:
            return False
        if getattr(self, "_destination_descendant_apply_paused_for_finalize_alloc", False):
            return False
        dq = getattr(self, "_destination_descendant_apply_queue", None)
        if dq is not None and len(dq) > 0:
            return False
        if getattr(self, "_destination_descendant_apply_state", None) is not None:
            return False
        cur_did = self._current_selected_destination_drive_id() or self.pending_root_drive_ids.get("destination", "")
        if cur_did and not self._destination_snapshot_spo_trust_valid(cur_did):
            return False
        _lv = getattr(self, "_destination_snapshot_light_validation_worker", None)
        if _lv is not None and _lv.isRunning():
            return False
        return True

    def _destination_preview_incomplete_diag(self) -> dict:
        cur_did = self._current_selected_destination_drive_id() or self.pending_root_drive_ids.get("destination", "")
        _lv = getattr(self, "_destination_snapshot_light_validation_worker", None)
        return {
            "authority_pending_shell_visible": self._destination_tree_shows_authority_pending_shell(),
            "full_tree_ready": self._destination_full_tree_ready(),
            "spo_snapshot_trust_valid": self._destination_snapshot_spo_trust_valid(cur_did) if cur_did else False,
            "spo_light_validation_running": bool(_lv is not None and _lv.isRunning()),
            "pending_destination_folder_loads": len(self.pending_folder_loads.get("destination", set()) or ()),
            "incremental_merge_in_progress": bool(getattr(self, "_destination_incremental_merge_in_progress", False)),
            "incremental_merge_session": getattr(self, "_destination_incremental_merge_session", None) is not None,
            "future_projection_async": getattr(self, "_destination_future_projection_async_state", None) is not None,
            "descendant_apply_paused_finalize": bool(
                getattr(self, "_destination_descendant_apply_paused_for_finalize_alloc", False)
            ),
            "descendant_apply_queue_len": len(getattr(self, "_destination_descendant_apply_queue", None) or ()),
            "descendant_apply_state_active": getattr(self, "_destination_descendant_apply_state", None) is not None,
        }

    def _destination_try_emit_preview_complete_status(self, source_tag: str) -> None:
        """Emit the final destination preview status only when the authoritative pipeline is idle."""
        if not self._destination_sharepoint_planning_destination_active():
            self._set_tree_status_message("destination", "Destination preview ready — all phases complete.", loading=False)
            return
        if self._destination_authoritative_preview_pipeline_idle():
            self._log_restore_phase("destination_preview_complete_allowed", source=str(source_tag or ""))
            self._log_restore_phase(
                "destination_authority_pipeline",
                step="destination_preview_complete_allowed",
                source=str(source_tag or ""),
            )
            self._set_tree_status_message("destination", "Destination preview ready — all phases complete.", loading=False)
            return
        self._log_restore_phase(
            "destination_preview_complete_blocked",
            source=str(source_tag or ""),
            **self._destination_preview_incomplete_diag(),
        )
        self._set_tree_status_message(
            "destination",
            "Finalizing destination preview (live library structure / pending work)…",
            loading=True,
        )
        self._destination_preview_complete_retry_generation += 1
        gen = int(self._destination_preview_complete_retry_generation)

        def _tick(attempt: int, g: int):
            if g != int(getattr(self, "_destination_preview_complete_retry_generation", 0) or 0):
                return
            if self._destination_authoritative_preview_pipeline_idle():
                self._log_restore_phase("destination_preview_complete_allowed", source="retry_tick", attempts=attempt)
                self._log_restore_phase(
                    "destination_authority_pipeline",
                    step="destination_preview_complete_allowed",
                    source="retry_tick",
                    attempts=attempt,
                )
                self._set_tree_status_message(
                    "destination",
                    "Destination preview ready — all phases complete.",
                    loading=False,
                )
                return
            if attempt >= 150:
                self._log_restore_phase(
                    "destination_preview_complete_retry_exhausted",
                    attempts=attempt,
                    **self._destination_preview_incomplete_diag(),
                )
                self._set_tree_status_message(
                    "destination",
                    "Destination preview incomplete — see logs for blocked reasons.",
                    loading=False,
                )
                return
            QTimer.singleShot(
                220,
                lambda: self._safe_invoke(
                    "destination_preview_complete_retry",
                    lambda: _tick(attempt + 1, g),
                ),
            )

        QTimer.singleShot(
            220,
            lambda: self._safe_invoke("destination_preview_complete_retry_kick", lambda: _tick(0, gen)),
        )

    def _should_park_deferred_materialize_for_full_tree(self, reason) -> bool:
        """True while destination full-tree snapshot is loading; idle timer retries would only re-hit waiting_for_full_tree."""
        r = str(reason or "")
        if r in (
            "destination_full_tree_success",
            "destination_full_tree_idle_success",
            "destination_expand_all_full_tree",
        ) or r.startswith("destination_full_tree"):
            return False
        if not (
            self._destination_full_tree_worker is not None
            and self._destination_full_tree_worker.isRunning()
            and not self._destination_full_tree_ready()
        ):
            return False
        return True

    def _park_deferred_destination_materialize_for_full_tree_wait(self, incoming_reason: str) -> str:
        prev = str(getattr(self, "_destination_idle_materialize_parked_for_full_tree_reason", "") or "").strip()
        merged = self._merge_pending_materialize_after_async(prev, str(incoming_reason or "").strip())
        self._destination_idle_materialize_parked_for_full_tree_reason = merged
        self._destination_idle_materialize_full_tree_park_requested_drive_id = (
            str(getattr(self, "_destination_full_tree_requested_drive_id", "") or "")
        )
        idle_timer = getattr(self, "_destination_idle_materialize_timer", None)
        if idle_timer is not None:
            idle_timer.stop()
        self._destination_idle_materialize_pending_reason = ""
        return merged

    def _flush_parked_destination_materialize_after_full_tree_completion(self):
        parked = str(getattr(self, "_destination_idle_materialize_parked_for_full_tree_reason", "") or "").strip()
        if not parked:
            return
        self._destination_idle_materialize_parked_for_full_tree_reason = ""
        self._destination_idle_materialize_full_tree_park_requested_drive_id = ""
        self._log_restore_phase(
            "destination_idle_materialize_resume_after_full_tree",
            resume_reason=parked,
        )

        def _go():
            self._apply_destination_planning_overlays(
                parked,
                allow_defer=False,
                prefer_chunked_projection=True,
            )

        QTimer.singleShot(
            0,
            lambda: self._safe_invoke("destination_resume_parked_after_full_tree", _go),
        )

    def _reset_projection_delta_coalesce_state(self):
        """Clear delta/work-signature state after import, restore, or other global planning resets."""
        self._destination_drfws_affected_paths.clear()
        self._destination_last_drfws_completed_work_sig = ""
        self._destination_bind_scope_paths = None
        self._source_projection_row_relationship_sig.clear()
        self._source_projection_refresh_eval_plan_sig = ""

    def _merge_destination_drfws_affected_paths(self, paths: Optional[Iterable[str]]) -> None:
        if not paths:
            return
        for p in paths:
            c = self._canonical_destination_projection_path(str(p or ""))
            if c:
                self._destination_drfws_affected_paths.add(c)

    def _destination_drfws_pending_work_signature(self) -> str:
        paths = sorted(self._destination_drfws_affected_paths or [])
        uqp = self._unresolved_proposed_queue_size()
        uqa = self._unresolved_allocation_queue_size()
        cache = getattr(self, "_destination_future_model_overlay_cache", None) or {}
        fp = str((cache or {}).get("full_fp") or "")
        if not fp:
            fp = str(getattr(self, "_destination_last_materialized_overlay_fp", "") or "")
        return f"{fp}\x00{uqp}\x00{uqa}\x00" + "\x00".join(paths)

    def _destination_collect_overlay_replay_bind_scope_paths(self) -> set[str]:
        """Canonical paths where unresolved proposed/allocation replay still needs destination bind work."""
        out: set[str] = set()
        for p in (self.unresolved_proposed_by_parent_path or {}).keys():
            c = self._canonical_destination_projection_path(str(p or ""))
            if c:
                out.add(c)
        for p in (self.unresolved_allocations_by_parent_path or {}).keys():
            c = self._canonical_destination_projection_path(str(p or ""))
            if c:
                out.add(c)
        out |= set(getattr(self, "_destination_drfws_affected_paths", None) or set())
        return {x for x in out if x}

    def _destination_folder_worker_materialize_scope_paths(self, semantic_path: str) -> set[str]:
        """Narrow bind scope for a single folder load: that branch plus any coalesced DRfWS paths."""
        out: set[str] = set()
        if semantic_path:
            c = self._canonical_destination_projection_path(str(semantic_path or ""))
            if c:
                out.add(c)
        out |= set(getattr(self, "_destination_drfws_affected_paths", None) or set())
        return {x for x in out if x}

    def _destination_bump_interactive_expand_idle_full_tree_lockout(self, delay_ms: float = 1350) -> None:
        until = time.monotonic() + max(0.0, float(delay_ms) or 0.0) / 1000.0
        cur = float(getattr(self, "_destination_interactive_expand_idle_full_tree_lockout_until", 0) or 0)
        self._destination_interactive_expand_idle_full_tree_lockout_until = max(cur, until)

    def _destination_should_block_idle_full_tree_materialize(self) -> bool:
        # Interactive folder loads still clear from pending before burst/deferred pipeline finishes;
        # keep idle full-tree off the UI thread until lockout / burst state says otherwise.
        if self.pending_folder_loads.get("destination"):
            return True
        if self._destination_expand_burst_ctx is not None:
            return True
        if self._destination_expand_burst_queue:
            return True
        t = getattr(self, "_destination_expand_burst_timer", None)
        if t is not None and t.isActive():
            return True
        if time.monotonic() < float(getattr(self, "_destination_interactive_expand_idle_full_tree_lockout_until", 0) or 0):
            return True
        # Burst/lockout can clear while destination preview bind or merge is still active; fp-mismatch
        # would otherwise admit destination_full_tree_idle_success into a full build (materialize_allowed_fp_mismatch).
        if getattr(self, "_destination_chunked_bind_state", None) is not None:
            return True
        if getattr(self, "_destination_future_projection_async_state", None) is not None:
            return True
        if getattr(self, "_destination_incremental_merge_in_progress", False):
            return True
        return False

    def _expand_idle_path_diag(self) -> dict:
        lock_ms = max(
            0,
            int(
                (
                    float(getattr(self, "_destination_interactive_expand_idle_full_tree_lockout_until", 0) or 0)
                    - time.monotonic()
                )
                * 1000
            ),
        )
        return {
            "lockout_remaining_ms": lock_ms,
            "burst_ctx_active": bool(self._destination_expand_burst_ctx is not None),
            "burst_queue_len": len(self._destination_expand_burst_queue or []),
            "burst_timer_active": bool(
                getattr(self, "_destination_expand_burst_timer", None) is not None
                and self._destination_expand_burst_timer.isActive()
            ),
            "pending_destination_folder_loads": len(self.pending_folder_loads.get("destination") or set()),
        }

    def _destination_expand_burst_should_coalesce(self, semantic_path_captured: str) -> bool:
        """True when the heavy folder_worker_success pipeline can be merged into a debounced burst."""
        if self._expand_all_pending.get("destination"):
            return False
        # Root during post-login memory restore must run the immediate deferred pipeline (handoff + restore
        # queue), not merge into a burst — unless Graph already owns visible structure (live SPO wins).
        if (
            getattr(self, "_memory_restore_in_progress", False)
            and semantic_path_captured == "Root"
            and not destination_authority_contract.graph_owns_visible_real_destination_structure(self)
        ):
            return False
        if getattr(self, "_sharepoint_lazy_mode", False):
            if getattr(self, "_destination_root_prime_pending", False) and semantic_path_captured != "Root":
                return False
            if semantic_path_captured == "Root":
                return False
        return True

    def _destination_expand_burst_schedule(self, entry: dict) -> None:
        self._destination_expand_burst_queue.append(entry)
        self._destination_bump_interactive_expand_idle_full_tree_lockout(1400)
        n = len(self._destination_expand_burst_queue)
        timer = self._destination_expand_burst_timer
        had_active = timer.isActive()
        if had_active:
            timer.stop()
        ms = int(getattr(self, "_destination_expand_burst_debounce_ms", 160) or 160)
        timer.start(ms)
        if is_dev_mode():
            log_info(
                "EXPAND_BURST_DEBOUNCE_COALESCED" if had_active else "EXPAND_BURST_DEBOUNCE_SCHEDULED",
                queue_len=n,
                debounce_ms=ms,
                timer_reused=bool(had_active),
            )

    def _on_destination_expand_burst_timer_fired(self) -> None:
        self._safe_invoke("destination_expand_burst_pipeline", self._run_destination_expand_burst_pipeline)

    def _run_destination_expand_burst_pipeline(self) -> None:
        if _shutdown_mutation_skip_for_host(self, "_run_destination_expand_burst_pipeline"):
            self._destination_expand_burst_queue = []
            return
        entries = self._destination_expand_burst_queue
        self._destination_expand_burst_queue = []
        if not entries:
            return
        self._destination_expand_burst_run_id += 1
        run_id = self._destination_expand_burst_run_id
        t_burst_0 = time.perf_counter()
        panel_key = "destination"
        n_entries = len(entries)
        last_trigger_fallback = str(entries[-1].get("trigger_path_captured") or "")

        def _footer(trigger_for_nav: str) -> None:
            if self._expand_all_pending.get("destination"):
                self._schedule_destination_expand_all_continue()
            else:
                self._continue_expand_all("destination", None)
            self._refresh_tree_column_width("destination")
            self._process_pending_destination_navigation("folder_load", trigger_path=trigger_for_nav)
            self._schedule_workspace_ui_persist(panel_key=panel_key)
            if self._pending_snapshot_branch_refresh.get(panel_key) and not self._expand_all_pending.get(panel_key):
                self._schedule_snapshot_branch_refresh(panel_key, delay_ms=0)
            self._schedule_progress_summary_refresh()

        model_now = getattr(self, "destination_planning_model", None)
        tree_now = getattr(self, "destination_tree_widget", None)
        if model_now is None or tree_now is None:
            if is_dev_mode():
                log_info("EXPAND_BURST_PIPELINE_RUN", skipped=True, reason="destination_model_or_tree_missing")
            _footer(last_trigger_fallback)
            return

        if is_dev_mode():
            log_info(
                "EXPAND_BURST_PIPELINE_RUN",
                burst_entry_count=n_entries,
                debounce_ms=int(getattr(self, "_destination_expand_burst_debounce_ms", 160) or 160),
                run_id=run_id,
            )
            log_info(
                "EXPAND_BURST_STAGE_START",
                stage="A_per_folder_slice",
                run_id=run_id,
                item_count=n_entries,
                scope_count=0,
            )

        self._destination_bump_interactive_expand_idle_full_tree_lockout(1500)
        self._destination_expand_burst_ctx = {
            "run_id": run_id,
            "t_burst_0": t_burst_0,
            "panel_key": panel_key,
            "entries": entries,
            "entry_index": 0,
            "n_entries": n_entries,
            "model_now": model_now,
            "tree_now": tree_now,
            "all_semantic_paths": [],
            "sum_handoff": 0,
            "sum_direct": 0,
            "sum_alloc": 0,
            "root_drive_id": "",
            "root_item_id": "",
            "last_trigger": last_trigger_fallback,
        }
        QTimer.singleShot(
            0,
            lambda rid=run_id: self._safe_invoke(
                "destination_expand_burst_stage_a",
                lambda: self._destination_expand_burst_stage_a_tick(rid),
            ),
        )

    def _destination_expand_burst_stage_a_tick(self, run_id: int) -> None:
        ctx = self._destination_expand_burst_ctx
        if ctx is None or int(ctx.get("run_id") or 0) != int(run_id):
            return
        t_slice_0 = time.perf_counter()
        panel_key = str(ctx.get("panel_key") or "destination")
        model_now = ctx.get("model_now")
        entries = ctx.get("entries") or []
        idx = int(ctx.get("entry_index") or 0)
        if idx >= len(entries):
            if is_dev_mode():
                log_info(
                    "EXPAND_BURST_STAGE_DONE",
                    stage="A_per_folder_slice",
                    run_id=run_id,
                    wall_ms=int((time.perf_counter() - t_slice_0) * 1000),
                    items_processed=len(ctx.get("all_semantic_paths") or []),
                )
            asp = list(ctx.get("all_semantic_paths") or [])
            if not asp:
                if is_dev_mode():
                    log_info(
                        "EXPAND_BURST_STAGE_NEXT",
                        run_id=run_id,
                        from_stage="A",
                        to_stage="E_skip_empty",
                    )
                QTimer.singleShot(
                    0,
                    lambda rid=run_id: self._safe_invoke(
                        "destination_expand_burst_stage_e",
                        lambda: self._destination_expand_burst_stage_e(rid),
                    ),
                )
            else:
                if is_dev_mode():
                    log_info("EXPAND_BURST_STAGE_NEXT", run_id=run_id, from_stage="A", to_stage="B")
                QTimer.singleShot(
                    0,
                    lambda rid=run_id: self._safe_invoke(
                        "destination_expand_burst_stage_b",
                        lambda: self._destination_expand_burst_stage_b(rid),
                    ),
                )
            return
        ent = entries[idx]
        ctx["entry_index"] = idx + 1
        drive_id_captured = str(ent.get("drive_id") or "")
        item_id_captured = str(ent.get("item_id") or "")
        semantic_path_captured = str(ent.get("semantic_path_captured") or "")
        preserved_nested = ent.get("preserved_nested") or []
        previous_child_paths = ent.get("previous_child_paths") or set()

        parent_index_now = QModelIndex()
        if drive_id_captured and item_id_captured and model_now is not None:
            parent_index_now = model_now.find_index_by_drive_item(drive_id_captured, item_id_captured)
        if (not parent_index_now.isValid()) and semantic_path_captured and model_now is not None:
            idxs = model_now.find_indices_for_canonical_destination_path(semantic_path_captured)
            if idxs:
                parent_index_now = idxs[0]
        if (
            model_now is None
            or not parent_index_now.isValid()
            or (hasattr(model_now, "is_index_live") and not model_now.is_index_live(parent_index_now))
        ):
            self._log_restore_phase(
                "destination_folder_worker_success_deferred_skipped",
                reason="burst_parent_index_not_resolved_or_stale",
                semantic_path=str(semantic_path_captured or "")[:240],
                drive_id=str(drive_id_captured or "")[:80],
                item_id=str(item_id_captured or "")[:80],
            )
            QTimer.singleShot(
                0,
                lambda rid=run_id: self._safe_invoke(
                    "destination_expand_burst_stage_a",
                    lambda: self._destination_expand_burst_stage_a_tick(rid),
                ),
            )
            return
        nd_now = dict(parent_index_now.data(Qt.UserRole) or {})
        sp_resolved = self._destination_semantic_path(nd_now)
        if semantic_path_captured and sp_resolved:
            c0 = self._canonical_destination_projection_path(semantic_path_captured)
            c1 = self._canonical_destination_projection_path(sp_resolved)
            if c0 and c1 and c0 != c1:
                self._log_restore_phase(
                    "destination_folder_worker_success_deferred_skipped",
                    reason="burst_semantic_path_mismatch_after_resolve",
                    semantic_path_captured=str(c0)[:240],
                    semantic_path_resolved=str(c1)[:240],
                )
                QTimer.singleShot(
                    0,
                    lambda rid=run_id: self._safe_invoke(
                        "destination_expand_burst_stage_a",
                        lambda: self._destination_expand_burst_stage_a_tick(rid),
                    ),
                )
                return
        semantic_path = sp_resolved
        ctx.setdefault("all_semantic_paths", []).append(semantic_path)
        current_child_paths = self._capture_child_path_set_for_destination_model_index(parent_index_now)
        if previous_child_paths:
            added_count = len(current_child_paths - previous_child_paths)
            removed_count = len(previous_child_paths - current_child_paths)
            if added_count or removed_count:
                self._set_tree_status_message(
                    panel_key,
                    f"Refreshing saved branches... {added_count} added, {removed_count} removed in {nd_now.get('name', 'folder')}.",
                    loading=bool(self._pending_snapshot_branch_refresh.get(panel_key)),
                )
        if semantic_path == "Root":
            self._destination_root_prime_pending = False
            ctx["root_drive_id"] = str(nd_now.get("drive_id") or drive_id_captured or "")
            ctx["root_item_id"] = str(nd_now.get("id") or item_id_captured or "")
        ctx["sum_handoff"] = int(ctx.get("sum_handoff") or 0) + self._restore_destination_future_state_children_model(
            parent_index_now, preserved_nested
        )
        ctx["sum_direct"] = int(ctx.get("sum_direct") or 0) + self._apply_proposed_children_to_item(parent_index_now)
        ctx["sum_alloc"] = int(ctx.get("sum_alloc") or 0) + self._apply_allocation_children_to_item(parent_index_now)

        if is_dev_mode():
            log_info(
                "EXPAND_BURST_STAGE_DONE",
                stage="A_per_folder_slice",
                run_id=run_id,
                wall_ms=int((time.perf_counter() - t_slice_0) * 1000),
                entry_index_done=idx,
                more_entries_remain=ctx["entry_index"] < len(entries),
            )
        QTimer.singleShot(
            0,
            lambda rid=run_id: self._safe_invoke(
                "destination_expand_burst_stage_a",
                lambda: self._destination_expand_burst_stage_a_tick(rid),
            ),
        )

    def _log_expand_burst_stage_timing(
        self,
        *,
        stage: str,
        run_id: int,
        wall_ms: int,
        semantic_path_count: int,
        scope_count: int,
        replay_applied: int = 0,
        allocation_replay: int = 0,
        merge_moved: Optional[int] = None,
        future_model_applied: Optional[int] = None,
        more_work_remains: bool = True,
    ) -> None:
        if not is_dev_mode():
            return
        payload: dict = {
            "stage": stage,
            "run_id": run_id,
            "wall_ms": wall_ms,
            "semantic_path_count": semantic_path_count,
            "scope_count": scope_count,
            "replay_applied": replay_applied,
            "allocation_replay": allocation_replay,
            "more_work_remains": more_work_remains,
        }
        if merge_moved is not None:
            payload["merge_moved"] = merge_moved
        if future_model_applied is not None:
            payload["future_model_applied"] = future_model_applied
        log_info("EXPAND_BURST_STAGE_TIMING", **payload)

    def _destination_expand_burst_stage_b(self, run_id: int) -> None:
        ctx = self._destination_expand_burst_ctx
        if ctx is None or int(ctx.get("run_id") or 0) != int(run_id):
            return
        t0 = time.perf_counter()
        all_semantic_paths = list(ctx.get("all_semantic_paths") or [])
        last_trigger = str(ctx.get("last_trigger") or "")
        if is_dev_mode():
            log_info(
                "EXPAND_BURST_STAGE_START",
                stage="B_replay_overlays",
                run_id=run_id,
                item_count=len(all_semantic_paths),
                scope_count=len(all_semantic_paths),
            )
        uqp = self._unresolved_proposed_queue_size()
        uqa = self._unresolved_allocation_queue_size()
        ctx["replay_applied_count"] = (
            self._replay_unresolved_proposed_overlay("folder_worker_success", trigger_path=last_trigger) if uqp else 0
        )
        ctx["allocation_replay_count"] = (
            self._replay_unresolved_allocation_overlay("folder_worker_success", trigger_path=last_trigger) if uqa else 0
        )
        wall_ms_b = int((time.perf_counter() - t0) * 1000)
        rap = int(ctx.get("replay_applied_count") or 0)
        ral = int(ctx.get("allocation_replay_count") or 0)
        if is_dev_mode():
            log_info(
                "EXPAND_BURST_STAGE_DONE",
                stage="B_replay_overlays",
                run_id=run_id,
                wall_ms=wall_ms_b,
            )
            self._log_expand_burst_stage_timing(
                stage="B_replay_overlays",
                run_id=run_id,
                wall_ms=wall_ms_b,
                semantic_path_count=len(all_semantic_paths),
                scope_count=len(all_semantic_paths),
                replay_applied=rap,
                allocation_replay=ral,
                more_work_remains=True,
            )
            log_info("EXPAND_BURST_STAGE_NEXT", run_id=run_id, from_stage="B", to_stage="C")
        QTimer.singleShot(
            0,
            lambda rid=run_id: self._safe_invoke(
                "destination_expand_burst_stage_c",
                lambda: self._destination_expand_burst_stage_c(rid),
            ),
        )

    def _destination_expand_burst_stage_c(self, run_id: int) -> None:
        """Yield one event-loop turn before heavy reconcile (same semantics as C_run)."""
        ctx = self._destination_expand_burst_ctx
        if ctx is None or int(ctx.get("run_id") or 0) != int(run_id):
            return
        t_yield = time.perf_counter()
        all_semantic_paths = list(ctx.get("all_semantic_paths") or [])
        if is_dev_mode():
            log_info(
                "EXPAND_BURST_LATE_STAGE_START",
                stage="C_reconcile_yield",
                run_id=run_id,
                semantic_path_count=len(all_semantic_paths),
                sliced_continuation_scheduled=True,
            )
            log_info("EXPAND_BURST_STAGE_NEXT", run_id=run_id, from_stage="C_entry", to_stage="C_run")
        QTimer.singleShot(
            0,
            lambda rid=run_id: self._safe_invoke(
                "destination_expand_burst_stage_c_run",
                lambda: self._destination_expand_burst_stage_c_run(rid),
            ),
        )
        if is_dev_mode():
            log_info(
                "EXPAND_BURST_LATE_STAGE_DONE",
                stage="C_reconcile_yield",
                run_id=run_id,
                wall_ms=int((time.perf_counter() - t_yield) * 1000),
                sliced_continuation_scheduled=True,
            )

    def _destination_expand_burst_stage_c_run(self, run_id: int) -> None:
        ctx = self._destination_expand_burst_ctx
        if ctx is None or int(ctx.get("run_id") or 0) != int(run_id):
            return
        t0 = time.perf_counter()
        all_semantic_paths = list(ctx.get("all_semantic_paths") or [])
        if is_dev_mode():
            log_info(
                "EXPAND_BURST_LATE_STAGE_START",
                stage="C_reconcile",
                run_id=run_id,
                semantic_path_count=len(all_semantic_paths),
            )
            log_info(
                "EXPAND_BURST_STAGE_START",
                stage="C_reconcile",
                run_id=run_id,
                item_count=len(all_semantic_paths),
                scope_count=len(all_semantic_paths),
            )
        ctx["merge_moved_count"] = self._reconcile_destination_semantic_duplicates_maybe_deferred(
            "folder_worker_success",
            affected_destination_paths=tuple(p for p in all_semantic_paths if p),
        )
        wall_ms_c = int((time.perf_counter() - t0) * 1000)
        mmc = int(ctx.get("merge_moved_count") or 0)
        if is_dev_mode():
            log_info(
                "EXPAND_BURST_LATE_STAGE_DONE",
                stage="C_reconcile",
                run_id=run_id,
                wall_ms=wall_ms_c,
                sliced_continuation_scheduled=True,
            )
            log_info(
                "EXPAND_BURST_STAGE_DONE",
                stage="C_reconcile",
                run_id=run_id,
                wall_ms=wall_ms_c,
            )
            self._log_expand_burst_stage_timing(
                stage="C_reconcile",
                run_id=run_id,
                wall_ms=wall_ms_c,
                semantic_path_count=len(all_semantic_paths),
                scope_count=len(all_semantic_paths),
                merge_moved=mmc,
                more_work_remains=True,
            )
            log_info(
                "EXPAND_BURST_LATE_STAGE_NEXT",
                run_id=run_id,
                from_stage="C_reconcile",
                to_stage="D_prepare_scope",
            )
            log_info("EXPAND_BURST_STAGE_NEXT", run_id=run_id, from_stage="C", to_stage="D_prepare_scope")
        QTimer.singleShot(
            0,
            lambda rid=run_id: self._safe_invoke(
                "destination_expand_burst_stage_d_prepare",
                lambda: self._destination_expand_burst_stage_d_prepare(rid),
            ),
        )

    def _destination_expand_burst_stage_d_prepare(self, run_id: int) -> None:
        """Compute combined materialize scope on one tick; materialize runs next tick."""
        ctx = self._destination_expand_burst_ctx
        if ctx is None or int(ctx.get("run_id") or 0) != int(run_id):
            return
        t0 = time.perf_counter()
        all_semantic_paths = list(ctx.get("all_semantic_paths") or [])
        combined_scope: set[str] = set()
        for sp in all_semantic_paths:
            combined_scope |= self._destination_folder_worker_materialize_scope_paths(sp)
        ctx["combined_scope"] = combined_scope
        ctx["fw_mat_scope_n"] = len(combined_scope)
        wall_ms_dp = int((time.perf_counter() - t0) * 1000)
        if is_dev_mode():
            log_info(
                "EXPAND_BURST_LATE_STAGE_START",
                stage="D_prepare_scope",
                run_id=run_id,
                semantic_path_count=len(all_semantic_paths),
                scope_count=len(combined_scope),
            )
            log_info(
                "EXPAND_BURST_STAGE_START",
                stage="D_prepare_scope",
                run_id=run_id,
                item_count=len(all_semantic_paths),
                scope_count=len(combined_scope),
            )
            log_info(
                "EXPAND_BURST_SCOPE_COUNT",
                scope_path_count=len(combined_scope),
                scope_paths_preview=sorted(list(combined_scope))[:12],
                semantic_path_count=len(all_semantic_paths),
            )
            log_info(
                "EXPAND_BURST_LATE_STAGE_DONE",
                stage="D_prepare_scope",
                run_id=run_id,
                wall_ms=wall_ms_dp,
                sliced_continuation_scheduled=True,
                remaining_scope_work=len(combined_scope),
            )
            log_info(
                "EXPAND_BURST_STAGE_DONE",
                stage="D_prepare_scope",
                run_id=run_id,
                wall_ms=wall_ms_dp,
            )
            self._log_expand_burst_stage_timing(
                stage="D_prepare_scope",
                run_id=run_id,
                wall_ms=wall_ms_dp,
                semantic_path_count=len(all_semantic_paths),
                scope_count=len(combined_scope),
                more_work_remains=True,
            )
            log_info(
                "EXPAND_BURST_LATE_STAGE_NEXT",
                run_id=run_id,
                from_stage="D_prepare_scope",
                to_stage="D_materialize",
            )
            log_info("EXPAND_BURST_STAGE_NEXT", run_id=run_id, from_stage="D_prepare_scope", to_stage="D_materialize")
        QTimer.singleShot(
            0,
            lambda rid=run_id: self._safe_invoke(
                "destination_expand_burst_stage_d_materialize",
                lambda: self._destination_expand_burst_stage_d_materialize(rid),
            ),
        )

    def _destination_expand_burst_stage_d_materialize(self, run_id: int) -> None:
        ctx = self._destination_expand_burst_ctx
        if ctx is None or int(ctx.get("run_id") or 0) != int(run_id):
            return
        t0 = time.perf_counter()
        all_semantic_paths = list(ctx.get("all_semantic_paths") or [])
        combined_scope = set(ctx.get("combined_scope") or set())
        fw_n = int(ctx.get("fw_mat_scope_n") or len(combined_scope))
        if is_dev_mode():
            log_info(
                "EXPAND_BURST_LATE_STAGE_START",
                stage="D_materialize",
                run_id=run_id,
                semantic_path_count=len(all_semantic_paths),
                scope_count=fw_n,
            )
            log_info(
                "EXPAND_BURST_STAGE_START",
                stage="D_materialize",
                run_id=run_id,
                item_count=len(all_semantic_paths),
                scope_count=len(combined_scope),
            )
        if getattr(self, "_sharepoint_lazy_mode", False):
            ctx["future_model_applied_count"] = 0
            ctx["fw_mat_scope_n"] = 0
        else:
            ctx["future_model_applied_count"] = self._destination_materialize_with_optional_overlay_scope(
                "folder_worker_success",
                allow_defer=True,
                prefer_chunked_projection=True,
                scope_paths=combined_scope,
            )
        fmac = int(ctx.get("future_model_applied_count") or 0)
        wall_ms_dm = int((time.perf_counter() - t0) * 1000)
        if is_dev_mode():
            log_info(
                "EXPAND_BURST_LATE_STAGE_DONE",
                stage="D_materialize",
                run_id=run_id,
                wall_ms=wall_ms_dm,
                sliced_continuation_scheduled=True,
            )
            log_info(
                "EXPAND_BURST_STAGE_DONE",
                stage="D_materialize",
                run_id=run_id,
                wall_ms=wall_ms_dm,
            )
            self._log_expand_burst_stage_timing(
                stage="D_materialize",
                run_id=run_id,
                wall_ms=wall_ms_dm,
                semantic_path_count=len(all_semantic_paths),
                scope_count=fw_n,
                future_model_applied=fmac,
                more_work_remains=True,
            )
            log_info(
                "EXPAND_BURST_LATE_STAGE_NEXT",
                run_id=run_id,
                from_stage="D_materialize",
                to_stage="E_finalize_body",
            )
            log_info("EXPAND_BURST_STAGE_NEXT", run_id=run_id, from_stage="D_materialize", to_stage="E")
        QTimer.singleShot(
            0,
            lambda rid=run_id: self._safe_invoke(
                "destination_expand_burst_stage_e",
                lambda: self._destination_expand_burst_stage_e(rid),
            ),
        )

    def _destination_expand_burst_stage_e(self, run_id: int) -> None:
        ctx = self._destination_expand_burst_ctx
        if ctx is None or int(ctx.get("run_id") or 0) != int(run_id):
            return
        t0 = time.perf_counter()
        t_burst_0 = float(ctx.get("t_burst_0") or time.perf_counter())
        panel_key = str(ctx.get("panel_key") or "destination")
        n_entries = int(ctx.get("n_entries") or 0)
        all_semantic_paths = list(ctx.get("all_semantic_paths") or [])
        last_trigger = str(ctx.get("last_trigger") or "")
        model_now = ctx.get("model_now")
        tree_now = ctx.get("tree_now")
        sum_handoff = int(ctx.get("sum_handoff") or 0)
        sum_direct = int(ctx.get("sum_direct") or 0)
        sum_alloc = int(ctx.get("sum_alloc") or 0)
        replay_applied_count = int(ctx.get("replay_applied_count") or 0)
        allocation_replay_count = int(ctx.get("allocation_replay_count") or 0)
        merge_moved_count = int(ctx.get("merge_moved_count") or 0)
        future_model_applied_count = int(ctx.get("future_model_applied_count") or 0)
        fw_mat_scope_n = int(ctx.get("fw_mat_scope_n") or 0)

        def _footer(trigger_for_nav: str) -> None:
            if self._expand_all_pending.get("destination"):
                self._schedule_destination_expand_all_continue()
            else:
                self._continue_expand_all("destination", None)
            self._refresh_tree_column_width("destination")
            self._process_pending_destination_navigation("folder_load", trigger_path=trigger_for_nav)
            self._schedule_workspace_ui_persist(panel_key=panel_key)
            if self._pending_snapshot_branch_refresh.get(panel_key) and not self._expand_all_pending.get(panel_key):
                self._schedule_snapshot_branch_refresh(panel_key, delay_ms=0)
            self._schedule_progress_summary_refresh()

        if not all_semantic_paths:
            if is_dev_mode():
                log_info("EXPAND_BURST_PIPELINE_RUN", skipped=True, reason="no_valid_entries_after_stage_a")
            wall_ms_e0 = int((time.perf_counter() - t0) * 1000)
            self._destination_expand_burst_ctx = None
            _footer(last_trigger)
            if is_dev_mode():
                self._log_expand_burst_stage_timing(
                    stage="E_empty_skip",
                    run_id=run_id,
                    wall_ms=wall_ms_e0,
                    semantic_path_count=0,
                    scope_count=0,
                    replay_applied=replay_applied_count,
                    allocation_replay=allocation_replay_count,
                    more_work_remains=False,
                )
                log_info(
                    "EXPAND_BURST_TOTAL_DONE",
                    run_id=run_id,
                    burst_wall_ms=int((time.perf_counter() - t_burst_0) * 1000),
                    stage_E_wall_ms=wall_ms_e0,
                )
                log_info(
                    "EXPAND_BURST_LATE_STAGE_TOTAL_DONE",
                    run_id=run_id,
                    burst_wall_ms=int((time.perf_counter() - t_burst_0) * 1000),
                    footer_deferred=False,
                )
            return

        if is_dev_mode():
            log_info(
                "EXPAND_BURST_STAGE_START",
                stage="E_finalize_body",
                run_id=run_id,
                item_count=len(all_semantic_paths),
                scope_count=fw_mat_scope_n,
            )

        try:
            self._log_restore_phase(
                "destination_replay_attachment_applied",
                trigger_path=self.normalize_memory_path(last_trigger),
                handoff_moved_count=sum_handoff,
                direct_applied_count=sum_direct,
                replay_applied_count=replay_applied_count,
                allocation_applied_count=sum_alloc,
                allocation_replay_count=allocation_replay_count,
                merge_moved_count=merge_moved_count,
                future_model_applied_count=future_model_applied_count,
                queue_size=self._unresolved_proposed_queue_size(),
                folder_worker_materialize_scope_count=fw_mat_scope_n,
                burst_coalesced_entry_count=n_entries,
            )
            t_fw_diag = time.perf_counter()
            dest_worker_slots = sum(
                1 for k in (self.folder_load_workers or {}) if str(k).startswith("destination:")
            )
            mat_mode = (
                "scoped_overlay"
                if fw_mat_scope_n
                else ("none_or_deferred" if not future_model_applied_count else "applied_unscoped")
            )
            self._log_restore_phase(
                "folder_worker_success_destination_diag",
                worker_id="burst_sliced",
                drive_id_excerpt="",
                trigger_path=self.normalize_memory_path(last_trigger),
                semantic_path_excerpt="; ".join(str(p) for p in all_semantic_paths[:6])[:240],
                elapsed_children_replace_ms=0,
                elapsed_overlay_block_ms=int((t_fw_diag - t_burst_0) * 1000),
                elapsed_replay_overlay_block_ms=0,
                elapsed_overlay_materialize_ms=0,
                burst_wall_ms=int((t_fw_diag - t_burst_0) * 1000),
                pending_destination_folder_loads=len(self.pending_folder_loads.get("destination", set())),
                active_destination_worker_slots=dest_worker_slots,
                unresolved_proposed_after=self._unresolved_proposed_queue_size(),
                unresolved_allocation_after=self._unresolved_allocation_queue_size(),
                bind_scope_active=bool(getattr(self, "_destination_bind_scope_paths", None)),
                destination_bind_sync_active=bool(getattr(self, "_destination_future_bind_sync_active", False)),
                chunked_bind_active=bool(getattr(self, "_destination_chunked_bind_state", None) is not None),
                full_tree_worker_running=bool(
                    self._destination_full_tree_worker is not None
                    and self._destination_full_tree_worker.isRunning()
                ),
                expand_all_pending_destination=bool(self._expand_all_pending.get("destination")),
                memory_restore_in_progress=bool(getattr(self, "_memory_restore_in_progress", False)),
                restore_destination_overlay_pending=bool(
                    getattr(self, "_restore_destination_overlay_pending", False)
                ),
                materialize_mode=mat_mode,
                materialize_applied_count=future_model_applied_count,
                materialize_scope_path_count=fw_mat_scope_n,
                burst_entry_count=n_entries,
            )
            if not self._expand_all_pending.get("destination"):
                if not getattr(self, "_destination_restore_completed_once", False):
                    if any((sp or "") == "Root" for sp in all_semantic_paths) and (
                        getattr(self, "_sharepoint_lazy_mode", False)
                        or getattr(self, "_memory_restore_in_progress", False)
                    ):
                        self._start_destination_restore_materialization()
                    if not getattr(self, "_destination_root_prime_pending", False):
                        self._schedule_destination_restore_materialization_queue(
                            "folder_load",
                            trigger_path=last_trigger,
                        )
                if tree_now is not None:
                    self._schedule_refresh_destination_tree_indicators()
                    tree_now.viewport().update()
                if (
                    self._unresolved_proposed_queue_size() == 0
                    and self._unresolved_allocation_queue_size() == 0
                    and getattr(self, "_memory_restore_in_progress", False)
                ):
                    self._finalize_memory_restore_if_ready(f"folder_load_burst:{len(all_semantic_paths)}")
            rd = str(ctx.get("root_drive_id") or "")
            ri = str(ctx.get("root_item_id") or "")
            if (
                getattr(self, "_sharepoint_lazy_mode", False)
                and rd
                and ri
                and model_now is not None
                and not self._expand_all_pending.get("destination")
            ):
                root_ix = model_now.find_index_by_drive_item(rd, ri)
                if root_ix.isValid():
                    self._set_tree_status_message(
                        "destination",
                        f"{model_now.rowCount(root_ix)} top-level destination folder(s) loaded.",
                        loading=False,
                    )
        except Exception as exc:
            self._log_restore_exception("destination_overlay_folder_load_success_burst", exc)
        wall_ms_e_body = int((time.perf_counter() - t0) * 1000)
        self._destination_expand_burst_ctx = None
        if is_dev_mode():
            log_info(
                "EXPAND_BURST_STAGE_DONE",
                stage="E_finalize_body",
                run_id=run_id,
                wall_ms=wall_ms_e_body,
            )
            self._log_expand_burst_stage_timing(
                stage="E_finalize_body",
                run_id=run_id,
                wall_ms=wall_ms_e_body,
                semantic_path_count=len(all_semantic_paths),
                scope_count=fw_mat_scope_n,
                replay_applied=replay_applied_count,
                allocation_replay=allocation_replay_count,
                merge_moved=merge_moved_count,
                future_model_applied=future_model_applied_count,
                more_work_remains=True,
            )
            log_info(
                "EXPAND_BURST_LATE_STAGE_NEXT",
                run_id=run_id,
                from_stage="E_finalize_body",
                to_stage="E_footer",
            )
        QTimer.singleShot(
            0,
            lambda rid=run_id,
            pk=panel_key,
            lt=last_trigger,
            tb=t_burst_0,
            nsp=len(all_semantic_paths),
            fwn=fw_mat_scope_n,
            wb=wall_ms_e_body: self._safe_invoke(
                "destination_expand_burst_stage_e_footer",
                lambda: self._destination_expand_burst_stage_e_footer(
                    rid,
                    panel_key=pk,
                    last_trigger=lt,
                    t_burst_0=tb,
                    n_semantic=nsp,
                    fw_mat_scope_n=fwn,
                    t_body_wall_ms=wb,
                ),
            ),
        )

    def _destination_expand_burst_stage_e_footer(
        self,
        run_id: int,
        *,
        panel_key: str,
        last_trigger: str,
        t_burst_0: float,
        n_semantic: int,
        fw_mat_scope_n: int,
        t_body_wall_ms: int,
    ) -> None:
        t0 = time.perf_counter()
        if is_dev_mode():
            log_info(
                "EXPAND_BURST_LATE_STAGE_START",
                stage="E_footer",
                run_id=run_id,
                semantic_path_count=n_semantic,
                scope_count=fw_mat_scope_n,
            )

        def _footer(trigger_for_nav: str) -> None:
            if self._expand_all_pending.get("destination"):
                self._schedule_destination_expand_all_continue()
            else:
                self._continue_expand_all("destination", None)
            self._refresh_tree_column_width("destination")
            self._process_pending_destination_navigation("folder_load", trigger_path=trigger_for_nav)
            self._schedule_workspace_ui_persist(panel_key=panel_key)
            if self._pending_snapshot_branch_refresh.get(panel_key) and not self._expand_all_pending.get(panel_key):
                self._schedule_snapshot_branch_refresh(panel_key, delay_ms=0)
            self._schedule_progress_summary_refresh()

        _footer(last_trigger)
        self._destination_bump_interactive_expand_idle_full_tree_lockout(1300)
        wall_ms_ef = int((time.perf_counter() - t0) * 1000)
        if is_dev_mode():
            log_info(
                "EXPAND_BURST_LATE_STAGE_DONE",
                stage="E_footer",
                run_id=run_id,
                wall_ms=wall_ms_ef,
                sliced_continuation_scheduled=False,
            )
            log_info(
                "EXPAND_BURST_STAGE_DONE",
                stage="E_footer",
                run_id=run_id,
                wall_ms=wall_ms_ef,
            )
            self._log_expand_burst_stage_timing(
                stage="E_footer",
                run_id=run_id,
                wall_ms=wall_ms_ef,
                semantic_path_count=n_semantic,
                scope_count=fw_mat_scope_n,
                more_work_remains=False,
            )
            log_info(
                "EXPAND_BURST_TOTAL_DONE",
                run_id=run_id,
                burst_wall_ms=int((time.perf_counter() - t_burst_0) * 1000),
                semantic_paths=n_semantic,
                stage_E_body_wall_ms=t_body_wall_ms,
                stage_E_footer_wall_ms=wall_ms_ef,
            )
            log_info(
                "EXPAND_BURST_LATE_STAGE_TOTAL_DONE",
                run_id=run_id,
                burst_wall_ms=int((time.perf_counter() - t_burst_0) * 1000),
                footer_deferred=True,
            )

    def _destination_materialize_with_optional_overlay_scope(
        self,
        reason: str,
        *,
        allow_defer: bool = True,
        prefer_chunked_projection: bool = False,
        narrow_restore_real_snapshot: bool = False,
        scope_paths: Optional[set[str]] = None,
    ) -> int:
        """Temporarily set bind scope from overlay/replay deltas so materialize/bind stay subtree-scoped."""
        scope = set(scope_paths) if scope_paths is not None else self._destination_collect_overlay_replay_bind_scope_paths()
        prev = getattr(self, "_destination_bind_scope_paths", None)
        if scope:
            self._destination_bind_scope_paths = set(scope)
            self._log_restore_phase(
                "destination_materialize_bind_scope_from_overlay_replay",
                reason=str(reason or ""),
                bind_scope_candidate_count=len(scope),
            )
        try:
            return self._apply_destination_planning_overlays(
                reason,
                allow_defer=allow_defer,
                prefer_chunked_projection=prefer_chunked_projection,
                narrow_restore_real_snapshot=narrow_restore_real_snapshot,
            )
        finally:
            if scope:
                self._destination_bind_scope_paths = prev

    def _source_projection_planning_signature_refresh(self) -> str:
        try:
            sigs = move_list_signatures(self.planned_moves or [])
            return hashlib.sha256(repr(sigs).encode()).hexdigest()[:32]
        except Exception:
            return ""

    def _source_relationship_row_signature(self, node_data, eval_index) -> str:
        if not node_data:
            return ""
        rel = self._evaluate_source_relationship(node_data, eval_index=eval_index)
        sp = self._canonical_source_projection_path(self._tree_item_path(node_data))
        needs = self._has_needs_review_for_source_path(self._tree_item_path(node_data))
        return (
            f"{sp}\x00{rel.get('mode', '')}\x00{rel.get('suffix', '')}\x00{needs}\x00"
            f"{rel.get('normalized_planned_source_path', '')}"
        )

    def _schedule_destination_full_tree_materialization(self, delay_ms=2500):
        timer = getattr(self, "_destination_full_tree_materialize_timer", None)
        if timer is None:
            self._maybe_materialize_destination_full_tree_snapshot()
            return
        timer.start(max(0, int(delay_ms)))

    def _schedule_lazy_destination_projection_refresh(self, reason, delay_ms=2200):
        if getattr(self, "_sharepoint_lazy_mode", False):
            return
        self._lazy_destination_projection_pending_reason = str(reason or "lazy_projection")
        timer = getattr(self, "_lazy_destination_projection_timer", None)
        if timer is None:
            self._run_lazy_destination_projection_refresh()
            return
        timer.start(max(0, int(delay_ms)))

    def _run_lazy_destination_projection_refresh(self):
        if _shutdown_mutation_skip_for_host(self, "_run_lazy_destination_projection_refresh"):
            self._lazy_destination_projection_pending_reason = ""
            return
        if getattr(self, "_sharepoint_lazy_mode", False):
            self._lazy_destination_projection_pending_reason = ""
            return
        reason = getattr(self, "_lazy_destination_projection_pending_reason", "") or "lazy_projection"
        if self._root_tree_bind_in_progress or self.pending_folder_loads.get("destination") or self._expand_all_pending.get("destination"):
            self._schedule_lazy_destination_projection_refresh(reason, 1800)
            return
        self._lazy_destination_projection_pending_reason = ""
        self._destination_lifecycle_trace_TEMP(
            fn="_run_lazy_destination_projection_refresh",
            reason=str(reason),
            step_kind="projection_materialize",
            extra="invoking_apply_destination_planning_overlays",
        )
        self._apply_destination_planning_overlays(f"lazy_{reason}")

    def _is_graph_ids_deferred_destination_materialize_reason(self, reason) -> bool:
        """True for destination materialize reasons produced after Graph ID / path enrichment (deferred planning refresh)."""
        return str(reason or "").startswith("deferred_graph_ids_resolved")

    def _merge_pending_materialize_after_async(self, prev: str, new: str) -> str:
        """When multiple materialize requests arrive during chunked descendant projection, keep the stronger follow-up."""
        p, n = str(prev or "").strip(), str(new or "").strip()
        if not p:
            return n
        if not n:
            return p
        if self._is_graph_ids_deferred_destination_materialize_reason(n):
            return n
        if self._is_graph_ids_deferred_destination_materialize_reason(p):
            return p
        return n

    def _destination_materialize_reason_should_queue_until_async_finishes(self, reason) -> bool:
        """True when a full materialize must not cancel in-flight (n/n planned-moves) descendant projection."""
        r = str(reason or "")
        if r.startswith("deferred_reconcile"):
            return True
        if self._is_graph_ids_deferred_destination_materialize_reason(r):
            return True
        if r.startswith("deferred_graph_ids_resolved"):
            return True
        return False

    def _should_defer_destination_materialization(self, reason):
        r = str(reason or "")
        if getattr(self, "_startup_destination_eager_full_memory", False) and (
            r.startswith("startup_planned_workspace_memory_truth") or r.startswith("phase4_destination_overlay")
        ):
            return False
        if planning_interaction_contract.is_local_first_deferred_materialize_reason(str(reason or "")):
            return False
        destination_tree = getattr(self, "destination_tree_widget", None)
        if destination_tree is None:
            return False
        if getattr(self, "_destination_non_authoritative_shell_active", False) and self._destination_full_tree_ready():
            cur = self._current_selected_destination_drive_id() or self.pending_root_drive_ids.get("destination", "")
            if cur and self._destination_snapshot_spo_trust_valid(cur):
                return False
        # Post-Graph-ID refresh must be allowed to bind while destination expand-all is still in progress.
        # Otherwise allow_defer schedules an idle pass that cannot run until expand finishes, while expand
        # waits on lazy loads that only resolve after projection — deadlock + endless second_pass_scheduled logs.
        if self._expand_all_pending.get("destination") and not self._is_graph_ids_deferred_destination_materialize_reason(
            reason
        ):
            return True
        if self.pending_folder_loads.get("destination"):
            return True
        if self._root_tree_bind_in_progress:
            return True
        large_tree = self._count_expandable_tree_nodes("destination") > 120
        heavy_reasons = {
            "root_bind",
            "folder_worker_success",
            "destination_expand_all_complete",
            "destination_fast_expand_all",
            "source_expand_all_complete",
            "destination_expand_all_full_tree",
            "destination_full_tree_idle_success",
            "destination_full_tree_success",
        }
        return large_tree and reason in heavy_reasons

    def _destination_future_model_blocked_by_source_restore(self, reason):
        """Avoid building/binding destination projection while source folder loads are in flight.

        Previously we also blocked when `_source_restore_materialization_queue` was non-empty. That
        queue can hold many deferred branch jobs while **no** `FolderLoadWorker` is running
        (`pending_source_folder_loads` == 0), which blocked destination materialization for a long
        time and produced logs like `destination_future_model_materialize_deferred` with
        `waiting_for_source_restore` + large `source_restore_queue_size` while loads were idle.
        """
        if getattr(self, "_startup_destination_eager_full_memory", False):
            return False
        skip = {
            "destination_expand_all_full_tree",
            "destination_root_error_fallback",
            "destination_full_tree_idle_success",
            "destination_expand_all_complete",
            "destination_fast_expand_all",
            "source_expand_all_complete",
        }
        if reason in skip or str(reason or "").startswith("source_restore_flush_"):
            return False
        if not self.planned_moves:
            return False
        pending_source = self.pending_folder_loads.get("source") or set()
        if len(pending_source) > 0:
            return True
        return False

    def _try_flush_destination_future_model_after_source_restore(self, trigger=""):
        if getattr(self, "_sharepoint_lazy_mode", False):
            self._destination_future_model_pending_after_source_restore = False
            return
        if self._expand_all_pending.get("source"):
            return
        if not self._destination_future_model_pending_after_source_restore:
            return
        if self._destination_future_model_blocked_by_source_restore("source_restore_flush"):
            return
        self._apply_destination_planning_overlays(f"source_restore_flush_{trigger}", allow_defer=False)

    def _schedule_deferred_destination_materialization(self, reason, delay_ms=180):
        reason = str(reason or "idle_destination_materialize")
        if reason == "planned_item_moved":
            timer_dedupe = getattr(self, "_destination_idle_materialize_timer", None)
            prev_r = str(getattr(self, "_destination_idle_materialize_pending_reason", "") or "")
            if (
                timer_dedupe is not None
                and timer_dedupe.isActive()
                and prev_r == "planned_item_moved"
            ):
                if is_dev_mode():
                    log_info(
                        "destination_double_render_guard",
                        phase="coalesce_duplicate_planned_item_moved",
                        scheduling_path="_schedule_deferred_destination_materialization",
                        reason=reason,
                        delay_ms=int(delay_ms),
                    )
                return
        if self._should_park_deferred_materialize_for_full_tree(reason):
            had_parked = bool(str(getattr(self, "_destination_idle_materialize_parked_for_full_tree_reason", "") or "").strip())
            merged = self._park_deferred_destination_materialize_for_full_tree_wait(reason)
            if is_dev_mode():
                log_info(
                    "destination_double_render_guard",
                    phase="second_pass_coalesced_full_tree_wait",
                    scheduling_path="_schedule_deferred_destination_materialization",
                    reason=reason,
                    delay_ms=int(delay_ms),
                    coalesced_duplicate_schedule=bool(had_parked),
                    pending_followup_reason=merged,
                )
            return
        drfws = "deferred_reconcile_folder_worker_success"
        if reason == drfws:
            if (
                getattr(self, "_destination_chunked_bind_state", None) is None
                and getattr(self, "_destination_future_projection_async_state", None) is None
            ):
                if self._try_skip_redundant_destination_future_model_materialize(drfws) is not None:
                    self._schedule_proactive_graph_parent_chains_for_unresolved_overlays(reason=drfws)
                    if is_dev_mode():
                        log_info(
                            "destination_double_render_guard",
                            phase="second_pass_coalesced_redundant_overlay",
                            scheduling_path="_schedule_deferred_destination_materialization",
                            reason=reason,
                            coalesced_duplicate_schedule=True,
                        )
                    return
            if self._destination_drfws_affected_paths:
                sig = self._destination_drfws_pending_work_signature()
                last = str(getattr(self, "_destination_last_drfws_completed_work_sig", "") or "")
                if sig and last and sig == last:
                    if is_dev_mode():
                        log_info(
                            "destination_double_render_guard",
                            phase="second_pass_skipped_unchanged_drfws_work_signature",
                            scheduling_path="_schedule_deferred_destination_materialization",
                            reason=reason,
                            coalesced_duplicate_schedule=True,
                            affected_path_count=len(self._destination_drfws_affected_paths),
                            work_signature_prefix=sig[:48],
                        )
                    self._destination_drfws_affected_paths.clear()
                    return
        prev_pending = str(getattr(self, "_destination_idle_materialize_pending_reason", "") or "")
        self._destination_idle_materialize_pending_reason = reason
        timer = getattr(self, "_destination_idle_materialize_timer", None)
        coalesce_same_deferred_reconcile = (
            reason == prev_pending
            and timer is not None
            and timer.isActive()
            and (
                reason == drfws
                or self._is_graph_ids_deferred_destination_materialize_reason(reason)
            )
        )
        if is_dev_mode():
            log_info(
                "destination_double_render_guard",
                phase="second_pass_coalesced" if coalesce_same_deferred_reconcile else "second_pass_scheduled",
                scheduling_path="_schedule_deferred_destination_materialization",
                reason=reason,
                delay_ms=int(delay_ms),
                coalesced_duplicate_schedule=bool(coalesce_same_deferred_reconcile),
            )
        if timer is None:
            self._run_deferred_destination_materialization()
            return
        if coalesce_same_deferred_reconcile:
            return
        # Do not override expand-all status or flash "Finalizing..." on a tight timer while
        # destination expand-all is active (materialization is deferred until loads finish).
        if not self._expand_all_pending.get("destination"):
            self._set_tree_status_message("destination", "Finalizing destination structure...", loading=True)
        timer.stop()
        timer.start(max(0, int(delay_ms)))

    def _schedule_local_first_edit_deferred_followup(
        self,
        action: str,
        scope_paths: Optional[set[str]] = None,
        *,
        path_excerpt: str = "",
    ) -> None:
        act = str(action or "").strip().lower().replace(" ", "_")
        reason = f"local_first_edit_{act}"
        self._destination_local_first_edit_bind_scope = set(scope_paths) if scope_paths else None
        log_info("local_first_edit_applied", action=act, path=str(path_excerpt or "")[:400])
        log_info(
            "local_first_deferred_followup_scheduled",
            reason=reason,
            scope_paths=sorted(list(scope_paths or []))[:48],
        )
        self._schedule_deferred_destination_materialization(reason, delay_ms=120)

    def _run_deferred_destination_materialization(self):
        if _shutdown_mutation_skip_for_host(self, "_run_deferred_destination_materialization"):
            return
        reason = getattr(self, "_destination_idle_materialize_pending_reason", "") or "idle_destination_materialize"
        if int(getattr(self, "_destination_idle_materialize_reentrancy_block", 0) or 0) > 0:
            self._schedule_deferred_destination_materialization(reason, delay_ms=220)
            return
        _probe = (
            "draft_reset" in str(reason)
            or "destination_reconcile" in str(reason)
            or "deferred_reconcile" in str(reason)
            or str(reason).startswith("import_")
            or str(reason).startswith("deferred_graph_ids_resolved")
            or "phase4" in str(reason)
        )
        if _probe:
            log_info(
                "destination_phase_timing",
                phase="run_deferred_destination_materialization_enter",
                reason=str(reason),
            )
        if (
            (self._expand_all_pending.get("destination") and not self._is_graph_ids_deferred_destination_materialize_reason(reason))
            or self.pending_folder_loads.get("destination")
            or self._root_tree_bind_in_progress
        ):
            self._schedule_deferred_destination_materialization(reason, delay_ms=220)
            return
        if getattr(self, "_destination_chunked_bind_state", None) is not None:
            drfws = "deferred_reconcile_folder_worker_success"
            tidle = getattr(self, "_destination_idle_materialize_timer", None)
            if (
                str(reason or "") == drfws
                and tidle is not None
                and tidle.isActive()
                and getattr(self, "_destination_idle_materialize_pending_reason", "") == drfws
            ):
                if _probe or is_dev_mode():
                    log_info(
                        "destination_phase_timing",
                        phase="run_deferred_skip_reschedule_chunked_bind_timer_armed",
                        reason=str(reason),
                    )
                return
            self._schedule_deferred_destination_materialization(reason, delay_ms=220)
            return
        if getattr(self, "_destination_snapshot_chunked_restore_active", False):
            self._schedule_deferred_destination_materialization(reason, delay_ms=220)
            return
        if getattr(self, "_destination_future_projection_async_state", None) is not None:
            r = str(reason or "")
            if r.startswith("deferred_reconcile"):
                merged = self._merge_pending_materialize_after_async(
                    getattr(self, "_destination_materialize_pending_after_async_projection", "") or "",
                    r,
                )
                self._destination_materialize_pending_after_async_projection = merged
                idle_timer = getattr(self, "_destination_idle_materialize_timer", None)
                if idle_timer is not None:
                    idle_timer.stop()
                self._destination_idle_materialize_pending_reason = ""
                if _probe or is_dev_mode():
                    log_info(
                        "destination_phase_timing",
                        phase="run_deferred_destination_materialize_coalesced_with_async_projection",
                        reason=r,
                        pending_followup_reason=merged,
                    )
                return
            if _probe:
                log_info(
                    "destination_phase_timing",
                    phase="run_deferred_destination_materialize_waiting_async_projection",
                    reason=str(reason),
                )
            self._schedule_deferred_destination_materialization(reason, delay_ms=max(480, 220))
            return
        if self._should_park_deferred_materialize_for_full_tree(reason):
            merged = self._park_deferred_destination_materialize_for_full_tree_wait(reason)
            if _probe or is_dev_mode():
                log_info(
                    "destination_phase_timing",
                    phase="run_deferred_destination_materialize_parked_full_tree_wait",
                    reason=str(reason),
                    pending_followup_reason=merged,
                )
            return
        self._destination_idle_materialize_pending_reason = ""
        _mat_t0 = time.perf_counter()
        drfws_r = "deferred_reconcile_folder_worker_success"
        if str(reason or "") == drfws_r:
            self._destination_bind_scope_paths = (
                set(self._destination_drfws_affected_paths) if self._destination_drfws_affected_paths else None
            )
        elif planning_interaction_contract.is_local_first_deferred_materialize_reason(reason):
            merged_scope: set[str] = set()
            _pms = getattr(self, "_destination_planned_move_materialize_bind_scope", None)
            _lfs = getattr(self, "_destination_local_first_edit_bind_scope", None)
            if _pms:
                merged_scope |= set(_pms)
            if _lfs:
                merged_scope |= set(_lfs)
            self._destination_bind_scope_paths = merged_scope if merged_scope else None
        else:
            self._destination_bind_scope_paths = None
        _allow_defer = planning_interaction_contract.is_local_first_deferred_materialize_reason(reason)
        _pref_chunk = not planning_interaction_contract.is_narrow_planned_item_move_overlay_reason(reason)
        try:
            applied_count = self._apply_destination_planning_overlays(
                reason, allow_defer=_allow_defer, prefer_chunked_projection=_pref_chunk
            )
        finally:
            self._destination_bind_scope_paths = None
            if planning_interaction_contract.is_local_first_deferred_materialize_reason(reason):
                self._destination_planned_move_materialize_bind_scope = None
                self._destination_local_first_edit_bind_scope = None
        self._destination_deferred_reconcile_burst_pending = False
        if _probe:
            log_info(
                "destination_phase_timing",
                phase="run_deferred_destination_materialization_materialized",
                reason=str(reason),
                applied_count=int(applied_count or 0),
                elapsed_ms=int((time.perf_counter() - _mat_t0) * 1000),
            )
        if getattr(self, "_destination_future_model_last_blocked_source_restore", False):
            # If we are blocked by source restore but there are no running source folder-load
            # workers, the pending-key set may be stale. This can otherwise cause an
            # "Finalizing destination structure..." retry loop with no progress.
            pending_source = bool(self.pending_folder_loads.get("source", set()))
            source_worker_running = any(
                bool((entry or {}).get("worker", None) and getattr(entry.get("worker"), "isRunning", lambda: False)())
                for entry in (self.folder_load_workers or {}).values()
                if str((entry or {}).get("worker_key", "") or "").startswith("source:")
            )
            if pending_source and not source_worker_running:
                self.pending_folder_loads.get("source", set()).clear()
                self._destination_future_model_pending_after_source_restore = False
                self._destination_future_model_last_blocked_source_restore = False
                applied_count = self._apply_destination_planning_overlays(
                    f"{reason}_stale_source_pending_break",
                    allow_defer=False,
                    prefer_chunked_projection=True,
                )
            self._destination_idle_materialize_pending_reason = reason
            self._schedule_deferred_destination_materialization(reason, delay_ms=220)
            return
        if getattr(self, "_destination_future_projection_async_state", None) is not None:
            self._schedule_deferred_destination_materialization(reason, delay_ms=220)
            return
        if getattr(self, "_destination_chunked_bind_state", None) is not None:
            drfws = "deferred_reconcile_folder_worker_success"
            tidle = getattr(self, "_destination_idle_materialize_timer", None)
            if (
                str(reason or "") == drfws
                and tidle is not None
                and tidle.isActive()
                and getattr(self, "_destination_idle_materialize_pending_reason", "") == drfws
            ):
                return
            self._destination_idle_materialize_pending_reason = reason
            self._schedule_deferred_destination_materialization(reason, delay_ms=220)
            return
        if str(reason or "") == drfws_r:
            completed = int(applied_count or 0) > 0 or self._destination_steady_state_full_materialize_redundant()
            if completed and getattr(self, "_destination_chunked_bind_state", None) is None:
                sig_done = self._destination_drfws_pending_work_signature()
                self._destination_last_drfws_completed_work_sig = sig_done
                self._destination_drfws_affected_paths.clear()
        if applied_count or not self.pending_folder_loads.get("destination"):
            self._set_tree_status_message("destination", "Destination structure ready.", loading=False)
            if self._is_graph_ids_deferred_destination_materialize_reason(reason) and self._expand_all_pending.get(
                "destination"
            ):
                self._schedule_expand_all("destination", delay_ms=0)

    def _maybe_materialize_destination_full_tree_snapshot(self):
        if (
            getattr(self, "_destination_non_authoritative_shell_active", False)
            and self._destination_full_tree_ready()
            and self._destination_tree_shows_authority_pending_shell()
        ):
            if getattr(self, "_destination_quiet_startup_overlay_structural_suppress", False):
                log_info(
                    "startup_lifecycle_temp_full_tree_shell_flush_suppressed",
                    reason="quiet_startup_overlay_structural_suppress",
                )
                return
            did = str(
                self.pending_root_drive_ids.get("destination") or self._current_selected_destination_drive_id() or ""
            ).strip()
            if did and self._destination_snapshot_spo_trust_valid(did):
                self._destination_full_tree_materialization_pending = False
                t_stop = getattr(self, "_destination_full_tree_materialize_timer", None)
                if t_stop is not None:
                    try:
                        t_stop.stop()
                    except Exception:
                        pass
                self._log_restore_phase(
                    "destination_authority_pipeline",
                    step="materialize_started",
                    materialize_reason="destination_full_tree_idle_shell_priority_flush",
                    drive_id_suffix=did[-16:] if len(did) > 16 else did,
                )
                self._apply_destination_planning_overlays(
                    "destination_authority_shell_hard_flush",
                    allow_defer=False,
                    prefer_chunked_projection=True,
                )
                return
        if not self._destination_full_tree_materialization_pending:
            return
        if is_dev_mode():
            d = self._expand_idle_path_diag()
            log_info(
                "EXPAND_IDLE_PATH_ENTER",
                function="_maybe_materialize_destination_full_tree_snapshot",
                reason="destination_full_tree_idle_success",
                **d,
            )
        if self._destination_should_block_idle_full_tree_materialize():
            self._schedule_destination_full_tree_materialization(2800)
            if is_dev_mode():
                d = self._expand_idle_path_diag()
                log_info(
                    "EXPAND_BLOCK_IDLE_FULL_TREE",
                    reason="destination_full_tree_idle_success",
                    **d,
                )
                log_info(
                    "EXPAND_IDLE_PATH_BLOCKED",
                    function="_maybe_materialize_destination_full_tree_snapshot",
                    bypass_source="interactive_expand_guard",
                    intended_guard_checked=True,
                    **d,
                )
                log_info(
                    "EXPAND_IDLE_PATH_RESCHEDULED",
                    function="_maybe_materialize_destination_full_tree_snapshot",
                    delay_ms=2800,
                )
            return
        if self._expand_all_pending.get("destination"):
            self._schedule_destination_full_tree_materialization(2500)
            return
        if self.pending_folder_loads.get("destination"):
            self._schedule_destination_full_tree_materialization(2500)
            return
        if self._root_tree_bind_in_progress:
            self._schedule_destination_full_tree_materialization(2000)
            return
        if getattr(self, "_destination_chunked_bind_state", None) is not None:
            self._schedule_destination_full_tree_materialization(2500)
            return
        if getattr(self, "_destination_snapshot_chunked_restore_active", False):
            self._schedule_destination_full_tree_materialization(2500)
            return
        if getattr(self, "_destination_future_projection_async_state", None) is not None:
            self._schedule_destination_full_tree_materialization(2500)
            return
        destination_tree = getattr(self, "destination_tree_widget", None)
        source_tree = getattr(self, "source_tree_widget", None)
        if (destination_tree is not None and destination_tree.hasFocus()) or (
            source_tree is not None and source_tree.hasFocus()
        ):
            self._schedule_destination_full_tree_materialization(2000)
            return
        if is_dev_mode():
            d = self._expand_idle_path_diag()
            log_info(
                "EXPAND_IDLE_PATH_ALLOWED",
                function="_maybe_materialize_destination_full_tree_snapshot",
                reason="destination_full_tree_idle_success",
                intended_guard_checked=True,
                **d,
            )
        self._destination_full_tree_materialization_pending = False
        if not self._destination_steady_state_full_materialize_redundant():
            self._destination_deferred_uncovered_overlay_paths.clear()
            overlay_scope = self._destination_collect_overlay_replay_bind_scope_paths()
            if overlay_scope:
                self._destination_materialize_with_optional_overlay_scope(
                    "destination_full_tree_idle_success",
                    allow_defer=True,
                    prefer_chunked_projection=True,
                    scope_paths=overlay_scope,
                )
            else:
                self._apply_destination_planning_overlays(
                    "destination_full_tree_idle_success",
                    allow_defer=True,
                    prefer_chunked_projection=True,
                )

    def _destination_graph_enumeration_ignores_memory_restore_gate(self) -> bool:
        """Live SharePoint destination tree uses Graph enumeration; restore metadata must not defer it."""
        try:
            return bool(destination_authority_contract.graph_owns_visible_real_destination_structure(self))
        except Exception:
            return False

    def _destination_graph_authority_supersedes_memory_restore_gate_core(self) -> tuple[bool, str]:
        """Pure predicate for Graph authority superseding memory-restore gating; ``fail_reason`` empty when True.

        When ``destination_root_bind_is_authoritative`` is True, authority-pending / non-authoritative shell
        UI state is treated as stale and must not block supersede (reconcile, overlay replay, restore gate).
        """
        if not self._destination_graph_enumeration_ignores_memory_restore_gate():
            return False, "not_graph_owned_visible_structure"
        try:
            root_auth = bool(self._destination_root_bind_is_authoritative())
            if not root_auth:
                if self._destination_tree_shows_authority_pending_shell():
                    return False, "authority_pending_shell_visible"
                if bool(getattr(self, "_destination_non_authoritative_shell_active", False)):
                    return False, "non_authoritative_shell_active"
                return False, "destination_root_bind_not_authoritative"
            # Root bind is already authoritative: the QThread may still report isRunning() briefly
            # after success is delivered on the GUI thread — do not block restore-gate supersede.
        except Exception:
            return False, "predicate_exception"
        return True, ""

    def _destination_graph_authority_supersedes_memory_restore_gate(self) -> bool:
        """When True, stale ``_memory_restore_in_progress`` must not block destination reconcile/overlays/follow-up.

        Graph-visible structure is Graph-owned and root bind matches the active request. A destination
        ``RootLoadWorker`` thread may still report running briefly after GUI-thread success; that must
        not block supersede. Stale shell latches after an authoritative root bind do not block this
        predicate; shell state is cleared from ``_destination_on_authoritative_tree_bind_committed``.
        """
        result, fail_reason = self._destination_graph_authority_supersedes_memory_restore_gate_core()
        root_auth = False
        pending_shell = False
        non_auth_shell = False
        try:
            root_auth = bool(self._destination_root_bind_is_authoritative())
            pending_shell = bool(self._destination_tree_shows_authority_pending_shell())
            non_auth_shell = bool(getattr(self, "_destination_non_authoritative_shell_active", False))
        except Exception:
            pass
        try:
            graph_planning_active = bool(destination_authority_contract.sharepoint_planning_tree_active(self))
        except Exception:
            graph_planning_active = False
        mem = bool(getattr(self, "_memory_restore_in_progress", False))
        bg = bool(getattr(self, "_memory_restore_background_trees", False))
        mem_foreground = mem and not bg
        audit_env = os.environ.get("OZLINK_DEST_AUTHORITY_GATE_EVAL", "").strip().lower() in ("1", "true", "yes")
        if audit_env or mem_foreground or (not result and graph_planning_active):
            try:
                root_worker = bool(MainWindow._root_load_worker_running(self, "destination"))
            except Exception:
                root_worker = False
            authority_shell_present = bool(pending_shell or non_auth_shell)
            log_info(
                "destination_authority_gate_eval",
                graph_planning_active=graph_planning_active,
                graph_owns_visible_structure=bool(self._destination_graph_enumeration_ignores_memory_restore_gate()),
                destination_root_bind_is_authoritative=root_auth,
                destination_root_worker_running=root_worker,
                authority_shell_present=authority_shell_present,
                authority_pending_shell=pending_shell,
                non_authoritative_shell_active=non_auth_shell,
                memory_restore_in_progress=mem,
                memory_restore_background_trees=bg,
                authority_supersedes_memory_gate_result=bool(result),
                fail_reason=str(fail_reason or "")[:120],
            )
        return result

    def _destination_log_restore_gate_decision(
        self,
        *,
        caller: str,
        blocked: bool,
        reason: str,
        **extra: Any,
    ) -> None:
        try:
            graph_auth = bool(destination_authority_contract.graph_owns_visible_real_destination_structure(self))
        except Exception:
            graph_auth = False
        authority_shell_active = bool(getattr(self, "_destination_non_authoritative_shell_active", False)) or bool(
            self._destination_tree_shows_authority_pending_shell()
        )
        mem = bool(getattr(self, "_memory_restore_in_progress", False))
        bg = bool(getattr(self, "_memory_restore_background_trees", False))
        restore_busy_for_log = mem and not bg
        _sup_core, _sup_why = self._destination_graph_authority_supersedes_memory_restore_gate_core()
        log_info(
            "destination_restore_gate_decision",
            caller=str(caller)[:200],
            memory_restore_in_progress=mem,
            memory_restore_background_trees=bg,
            restore_in_progress=restore_busy_for_log,
            graph_authority=graph_auth,
            authority_shell_active=authority_shell_active,
            authority_supersedes_memory_gate=bool(_sup_core),
            authority_supersedes_fail_reason_excerpt=str(_sup_why or "")[:120],
            blocked=bool(blocked),
            reason=str(reason)[:260],
            **extra,
        )

    def _destination_try_clear_stale_foreground_memory_restore_gate(self, where: str) -> None:
        """Clear a stuck foreground restore flag once Graph destination authority is live (not background-tree phase)."""
        if not self._destination_graph_authority_supersedes_memory_restore_gate():
            return
        if not bool(getattr(self, "_memory_restore_in_progress", False)):
            return
        if bool(getattr(self, "_memory_restore_background_trees", False)):
            return
        prior = True
        self._memory_restore_in_progress = False
        log_info(
            "destination_restore_gate_cleared",
            cleared_at=str(where)[:200],
            prior_foreground_memory_restore_in_progress=prior,
            why_safe="graph_authority_live_and_root_bind_authoritative_foreground_restore_flag_stale",
        )
        try:
            self._finalize_memory_restore_if_ready(f"authority_memory_gate_cleared:{where}")
        except Exception as exc:
            self._log_restore_exception("destination_try_clear_stale_memory_restore_gate_finalize", exc)

    def _destination_full_tree_memory_restore_may_block_worker(self, drive_id: str) -> bool:
        """When False, memory restore must not defer the full-library worker for this drive."""
        if self._destination_graph_enumeration_ignores_memory_restore_gate():
            return False
        if not bool(getattr(self, "_memory_restore_in_progress", False)):
            return False
        did = str(drive_id or "").strip()
        bound = str(getattr(self, "_destination_sharepoint_root_graph_bound_drive_id", "") or "").strip()
        if did and bound and did == bound:
            return False
        return True

    def _ensure_sharepoint_destination_full_tree_worker_scheduled(
        self,
        drive_id: str,
        *,
        schedule_reason: str = "unspecified",
        routine_followup: bool = False,
        bootstrap: bool = False,
        explicit_refresh: bool = False,
        recovery: bool = False,
        delta_failed: bool = False,
        force_refresh: bool = False,
        skeleton_first_bootstrap: bool = False,
    ) -> None:
        """Start (or keep) the full-library walk when SharePoint authority is required; retries past transient skips."""
        if getattr(self, "_application_shutting_down", False):
            return
        did = str(drive_id or "").strip()
        if not did:
            self._log_restore_phase(
                "destination_full_tree_worker_not_scheduled",
                reason="missing_drive_id",
            )
            return
        if (
            hasattr(self, "planning_inputs")
            and self._destination_library_context_unresolved_for_graph_display()
            and not (bool(explicit_refresh) or bool(force_refresh))
        ):
            log_info(
                "destination_full_tree_blocked_library_unresolved",
                schedule_reason=str(schedule_reason)[:160],
                drive_id_suffix=did[-16:] if len(did) > 16 else did,
            )
            return
        _shell_waiting_authority = bool(
            getattr(self, "_destination_non_authoritative_shell_active", False)
        ) or self._destination_tree_shows_authority_pending_shell()
        if (
            not _shell_waiting_authority
            and self._destination_full_tree_ready()
            and self._destination_full_tree_completed_drive_id == did
        ):
            return
        _ft_worker = getattr(self, "_destination_full_tree_worker", None)
        _ft_req = str(getattr(self, "_destination_full_tree_requested_drive_id", "") or "")
        if _ft_worker is not None and _ft_worker.isRunning() and _ft_req == did:
            return
        if getattr(self, "_destination_future_bind_sync_active", False):
            QTimer.singleShot(
                400,
                lambda d=did: self._safe_invoke(
                    "destination_full_tree_retry_after_bind_sync",
                    lambda: self._ensure_sharepoint_destination_full_tree_worker_scheduled(
                        d,
                        schedule_reason="retry_after_bind_sync",
                        recovery=True,
                    ),
                ),
            )
            return
        if not self._destination_startup_full_tree_worker_allowed() and not _shell_waiting_authority:
            self._log_restore_phase(
                "destination_full_tree_deferred_startup_phase",
                drive_id_suffix=did[-16:] if len(did) > 16 else did,
                startup_ui_phase=str(getattr(self, "_destination_startup_ui_phase", "") or "")[:40],
            )
            QTimer.singleShot(
                420,
                lambda d=did: self._safe_invoke(
                    "destination_full_tree_retry_after_startup_phase",
                    lambda: self._ensure_sharepoint_destination_full_tree_worker_scheduled(
                        d,
                        schedule_reason="retry_after_startup_phase",
                        bootstrap=True,
                    ),
                ),
            )
            return
        _burst_would_block = self._destination_expand_burst_ctx is not None
        _mem_restore_blocks = self._destination_full_tree_memory_restore_may_block_worker(did)
        if (_mem_restore_blocks and not _shell_waiting_authority) or (
            _burst_would_block and not _shell_waiting_authority
        ):
            _mem_restore = bool(getattr(self, "_memory_restore_in_progress", False))
            self._log_restore_phase(
                "destination_full_tree_deferred_until_restore_or_burst",
                drive_id_suffix=did[-16:] if len(did) > 16 else did,
                memory_restore_in_progress=_mem_restore,
                memory_restore_blocking_full_tree=bool(_mem_restore_blocks and not _shell_waiting_authority),
                expand_burst_blocking_full_tree=bool(_burst_would_block and not _shell_waiting_authority),
            )
            QTimer.singleShot(
                320,
                lambda d=did: self._safe_invoke(
                    "destination_full_tree_retry_after_restore_or_burst",
                    lambda: self._ensure_sharepoint_destination_full_tree_worker_scheduled(
                        d,
                        schedule_reason="retry_after_restore_or_burst",
                        recovery=True,
                    ),
                ),
            )
            return
        _sched = should_schedule_destination_full_tree(
            reason=str(schedule_reason),
            drive_id=did,
            force_refresh=bool(force_refresh),
            delta_failed=bool(delta_failed),
            bootstrap=bool(bootstrap),
            explicit_refresh=bool(explicit_refresh),
            recovery=bool(recovery),
            routine_followup=bool(routine_followup),
            delta_cursor_present=destination_graph_delta_cursor_present(getattr(self, "graph", None), did),
            bootstrap_complete=bool(
                self._destination_full_tree_ready()
                and str(getattr(self, "_destination_full_tree_completed_drive_id", "") or "").strip() == did
            ),
            skeleton_first_bootstrap=bool(skeleton_first_bootstrap),
        )
        if not _sched.allowed:
            return
        self._log_restore_phase(
            "destination_authority_pipeline",
            step="authority_worker_scheduled",
            drive_id_suffix=did[-16:] if len(did) > 16 else did,
            full_tree_schedule_reason=str(schedule_reason)[:120],
        )
        self.start_destination_full_tree_worker(did)

    def start_destination_full_tree_worker(self, drive_id):
        if not drive_id:
            self._reset_destination_full_tree_state()
            return

        if getattr(self, "_destination_future_bind_sync_active", False):
            did_bind = str(drive_id or "").strip()
            log_info(
                "destination_full_tree_skipped_bind_sync_active",
                drive_id=did_bind[:80] if did_bind else "",
                hint="defer_full_tree_until_bind_sync_idle",
            )
            QTimer.singleShot(
                400,
                lambda d=did_bind: self._safe_invoke(
                    "destination_full_tree_retry_after_bind_sync_start",
                    lambda: self._ensure_sharepoint_destination_full_tree_worker_scheduled(
                        d,
                        schedule_reason="retry_after_bind_sync_start",
                        recovery=True,
                    ),
                ),
            )
            return

        _authority_shell_up = bool(getattr(self, "_destination_non_authoritative_shell_active", False)) or (
            self._destination_tree_shows_authority_pending_shell()
        )
        _burst_would_block_start = self._destination_expand_burst_ctx is not None
        _mem_restore_blocks_start = self._destination_full_tree_memory_restore_may_block_worker(str(drive_id or ""))
        if (_mem_restore_blocks_start and not _authority_shell_up) or (
            _burst_would_block_start and not _authority_shell_up
        ):
            did = str(drive_id or "")
            _mem_restore_start = bool(getattr(self, "_memory_restore_in_progress", False))
            log_info(
                "destination_full_tree_deferred_restore_or_burst",
                drive_id=did[:80],
                memory_restore_in_progress=_mem_restore_start,
                memory_restore_blocking_full_tree=bool(_mem_restore_blocks_start and not _authority_shell_up),
                expand_burst_ctx_active=bool(_burst_would_block_start and not _authority_shell_up),
            )
            QTimer.singleShot(
                280,
                lambda d=did: self._safe_invoke(
                    "destination_full_tree.retry_after_restore_burst",
                    self.start_destination_full_tree_worker,
                    d,
                ),
            )
            return

        if bool(getattr(self, "_memory_restore_in_progress", False)) and not _mem_restore_blocks_start:
            if self._destination_graph_enumeration_ignores_memory_restore_gate():
                log_info(
                    "authority_override_restore_block",
                    authority_override_restore_block=True,
                    pipeline="destination_full_tree_worker_start",
                    drive_id=str(drive_id)[:120],
                )

        if (
            self._destination_full_tree_worker is not None
            and self._destination_full_tree_worker.isRunning()
            and self._destination_full_tree_requested_drive_id == drive_id
        ):
            return

        if (
            not _authority_shell_up
            and self._destination_full_tree_snapshot
            and self._destination_full_tree_completed_drive_id == drive_id
        ):
            if getattr(self, "_destination_force_next_spo_snapshot_open_check", False):
                self._destination_force_next_spo_snapshot_open_check = False
                self._log_restore_phase(
                    "snapshot_invalid_requires_live_check",
                    reason="destination_library_reopen_open_validation",
                    drive_id_suffix=str(drive_id)[-16:] if len(str(drive_id)) > 16 else str(drive_id),
                )
                self._destination_begin_spo_snapshot_light_validation(drive_id)
                return
            if not self._destination_snapshot_spo_trust_valid(drive_id):
                self._log_restore_phase(
                    "snapshot_invalid_requires_live_check",
                    reason="trust_expired_or_unvalidated",
                    drive_id_suffix=str(drive_id)[-16:] if len(str(drive_id)) > 16 else str(drive_id),
                )
                self._destination_begin_spo_snapshot_light_validation(drive_id)
                return
            self._log_restore_phase(
                "snapshot_reuse_allowed",
                drive_id_suffix=str(drive_id)[-16:] if len(str(drive_id)) > 16 else str(drive_id),
                validation_kind="trust_ttl_still_valid",
            )
            return

        if self._destination_full_tree_worker is not None and self._destination_full_tree_worker.isRunning():
            self._retired_destination_full_tree_workers[self._active_destination_full_tree_worker_id] = self._destination_full_tree_worker

        try:
            self._destination_startup_snapshot_handoff_before_authority_full_walk()
        except Exception:
            pass
        _dq = getattr(self, "_destination_descendant_apply_queue", None)
        _qlen = len(_dq) if _dq else 0
        _st_on = getattr(self, "_destination_descendant_apply_state", None) is not None
        if _qlen > 0 or _st_on:
            self._destination_startup_descendant_queue_paused_for_authority = True
            log_info(
                "destination_startup_descendant_queue_paused_for_authority",
                queue_len=int(_qlen),
                apply_state_active=bool(_st_on),
                drive_id_suffix=str(drive_id)[-16:] if len(str(drive_id)) > 16 else str(drive_id),
            )

        self._destination_full_tree_snapshot = []
        self._mark_destination_real_tree_snapshot_stale()
        self._destination_invalidate_spo_snapshot_trust("full_live_walk_started")
        self._destination_authoritative_recursive_item_total = 0
        self._destination_authoritative_structure_fp = ""
        self._destination_full_tree_requested_drive_id = drive_id
        self._destination_full_tree_completed_drive_id = ""
        self._destination_full_tree_sequence += 1
        worker_id = self._destination_full_tree_sequence
        self.graph.clear_drive_children_cache(drive_id)
        log_info(
            "destination_full_tree_cleared_graph_children_cache",
            drive_id=str(drive_id)[:80],
            note="live_graph_walk_not_stale_disk_cache",
        )
        worker = DestinationFullTreeWorker(self.graph, drive_id, self._destination_full_tree_context())
        self._destination_full_tree_worker = worker
        self._active_destination_full_tree_worker_id = worker_id
        log_info("destination_full_tree_started", drive_id=drive_id)
        log_info(
            "destination_full_tree_worker_started",
            drive_id=str(drive_id)[:120],
            worker_id=int(worker_id),
        )
        self._destination_full_tree_heartbeat_generation = int(
            getattr(self, "_destination_full_tree_heartbeat_generation", 0) or 0
        ) + int(1)
        _hb_gen = int(self._destination_full_tree_heartbeat_generation)
        self._destination_full_tree_worker_started_monotonic = time.monotonic()
        _dsuf = str(drive_id)[-16:] if len(str(drive_id)) > 16 else str(drive_id)
        self._log_restore_phase(
            "destination_authority_pipeline",
            step="full_tree_walk_started",
            drive_id_suffix=_dsuf,
        )

        def _heartbeat_tick():
            if _hb_gen != int(getattr(self, "_destination_full_tree_heartbeat_generation", 0) or 0):
                return
            w = getattr(self, "_destination_full_tree_worker", None)
            if w is None or not w.isRunning():
                return
            t0 = float(getattr(self, "_destination_full_tree_worker_started_monotonic", 0.0) or 0.0)
            self._log_restore_phase(
                "destination_authority_pipeline",
                step="full_tree_walk_in_progress",
                drive_id_suffix=_dsuf,
                elapsed_sec=round(time.monotonic() - t0, 1),
            )
            QTimer.singleShot(
                10000,
                lambda: self._safe_invoke("destination_full_tree_walk_heartbeat", _heartbeat_tick),
            )

        QTimer.singleShot(
            8000,
            lambda: self._safe_invoke("destination_full_tree_walk_heartbeat", _heartbeat_tick),
        )
        worker.success.connect(lambda payload, worker_id=worker_id: self._safe_invoke("destination_full_tree.success", self.on_destination_full_tree_success, payload, worker_id))
        worker.error.connect(lambda payload, worker_id=worker_id: self._safe_invoke("destination_full_tree.error", self.on_destination_full_tree_error, payload, worker_id))
        worker.finished.connect(lambda worker_id=worker_id: self._safe_invoke("destination_full_tree.finished", self.on_destination_full_tree_finished, worker_id))
        worker.start()

    def on_destination_full_tree_success(self, payload, worker_id):
        drive_id = payload.get("drive_id", "")
        if worker_id != self._active_destination_full_tree_worker_id or drive_id != self._destination_full_tree_requested_drive_id:
            return
        _bound_live = str(getattr(self, "_destination_sharepoint_root_graph_bound_drive_id", "") or "").strip()
        _pend = str((self.pending_root_drive_ids or {}).get("destination") or "").strip()
        _auth = _bound_live or _pend
        if _auth and str(drive_id or "").strip() and _auth.casefold() != str(drive_id or "").strip().casefold():
            log_info(
                "destination_stale_full_tree_worker_ignored_wrong_drive",
                active_drive_suffix=_auth[-16:] if len(_auth) > 16 else _auth,
                payload_drive_suffix=str(drive_id)[-16:] if len(str(drive_id)) > 16 else str(drive_id),
                worker_id_suffix=str(worker_id)[:24],
            )
            return

        snapshot_entries = []
        for item in payload.get("items", []):
            semantic_path = self._canonical_destination_projection_path(
                item.get("display_path") or item.get("item_path") or item.get("destination_path") or ""
            )
            if not semantic_path:
                continue
            item_data = dict(item)
            item_data["children_loaded"] = True
            snapshot_entries.append({
                "semantic_path": semantic_path,
                "parent_semantic_path": self.normalize_memory_path("\\".join(self._path_segments(semantic_path)[:-1])),
                "data": item_data,
                "children": [],
            })

        # Background knowledge only under Graph structural authority — never the source of visible real rows.
        self._destination_full_tree_snapshot = snapshot_entries
        self._destination_full_library_reconcile_pending = False
        self._destination_authority_pending_shell = False
        self._destination_full_tree_completed_drive_id = drive_id
        self._destination_authoritative_recursive_item_total = len(payload.get("items") or [])
        _ft_ctx = self._destination_full_tree_context()
        _ctx_seg = [s for s in (_ft_ctx.get("site_name", ""), _ft_ctx.get("library_name", "")) if s]
        _struct_fp, _struct_n = destination_library_structural_fingerprint_from_items(
            payload.get("items"), context_segments=_ctx_seg
        )
        self._destination_authoritative_structure_fp = _struct_fp
        self._mark_destination_real_tree_snapshot_stale()
        self._destination_mark_spo_snapshot_trust_valid(drive_id, "full_library_walk")
        log_info("destination_full_tree_completed", drive_id=drive_id, total_count=len(snapshot_entries))
        QTimer.singleShot(
            3_000,
            lambda: self._safe_invoke(
                "auto_debug_dest_tree_post_full_tree",
                self._run_auto_debug_destination_tree_pair_once,
                "post_full_tree_3s",
            ),
        )
        if self._destination_memory_overlay_mode_enabled():
            QTimer.singleShot(
                0,
                lambda: self._safe_invoke(
                    "destination_graph_overlay_promote_post_full_tree",
                    self._destination_graph_overlay_promote_rows_from_full_tree_snapshot,
                ),
            )
        _dsuf2 = str(drive_id)[-16:] if len(str(drive_id)) > 16 else str(drive_id)
        self._log_restore_phase(
            "destination_authority_pipeline",
            step="full_walk_success",
            drive_id_suffix=_dsuf2,
            graph_item_count=len(payload.get("items") or []),
            snapshot_entries=len(snapshot_entries),
            structure_digest_rows=int(_struct_n),
        )
        self._log_restore_phase(
            "destination_authority_pipeline",
            step="snapshot_imported",
            drive_id_suffix=_dsuf2,
            snapshot_entries=len(snapshot_entries),
        )
        self._log_restore_phase(
            "destination_authority_pipeline",
            step="snapshot_trust_valid",
            drive_id_suffix=_dsuf2,
            validation_kind="full_library_walk",
        )
        if self._destination_expand_all_after_full_tree:
            self._destination_full_tree_materialization_pending = False
            # expand_all_pending is still True here; defer would block materialize until later.
            self._log_restore_phase(
                "destination_authority_pipeline",
                step="materialize_started",
                materialize_reason="destination_expand_all_full_tree",
                drive_id_suffix=_dsuf2,
            )
            self._apply_destination_planning_overlays(
                "destination_expand_all_full_tree",
                allow_defer=False,
                prefer_chunked_projection=True,
            )
            self._destination_expand_all_after_full_tree = False
            button = self._expand_all_button_for_panel("destination")
            if button is not None:
                button.setEnabled(True)
            if self._destination_pipeline_blocks_user_expand_gesture():
                self._destination_expand_all_start_pending = True
                self._log_restore_phase(
                    "destination_expand_all_deferred_until_structure_settled",
                    reason="after_full_tree_materialize",
                )
                self._update_expand_all_status(
                    "destination",
                    "Waiting for destination preview to finish updating…",
                    loading=True,
                )
                QTimer.singleShot(
                    0,
                    lambda: self._safe_invoke(
                        "destination_expand_all_deferred_kick_full_tree",
                        self._try_deferred_destination_expand_all_start,
                    ),
                )
            elif self._can_fast_bulk_expand("destination"):
                self._fast_expand_all_loaded_tree("destination")
            else:
                self._begin_destination_model_expand_all()
        else:
            if getattr(self, "_destination_non_authoritative_shell_active", False):
                self._destination_full_tree_materialization_pending = False
                self._log_restore_phase(
                    "destination_authority_pipeline",
                    step="materialize_started",
                    materialize_reason="destination_full_tree_after_non_auth_shell",
                    drive_id_suffix=_dsuf2,
                )
                self._apply_destination_planning_overlays(
                    "destination_full_tree_after_non_auth_shell",
                    allow_defer=False,
                    prefer_chunked_projection=True,
                )
            else:
                self._destination_full_tree_materialization_pending = True
                self._schedule_destination_full_tree_materialization(4000)
        self._destination_flush_trust_gate_pending_materialize()
        self._flush_parked_destination_materialize_after_full_tree_completion()
        self._destination_resume_startup_descendant_queue_after_authority_if_paused(phase="full_tree_success")

        def _shell_safety_net():
            self._destination_materialize_authoritative_if_shell_still_showing("after_full_tree_success")

        QTimer.singleShot(
            0,
            lambda: self._safe_invoke("destination_authority_shell_safety_net_tick", _shell_safety_net),
        )

    def on_destination_full_tree_error(self, payload, worker_id):
        drive_id = payload.get("drive_id", "")
        if worker_id != self._active_destination_full_tree_worker_id or drive_id != self._destination_full_tree_requested_drive_id:
            return
        self._destination_full_tree_snapshot = []
        self._destination_full_library_reconcile_pending = False
        self._destination_authority_pending_shell = False
        self._destination_full_tree_completed_drive_id = ""
        self._destination_authoritative_recursive_item_total = 0
        self._destination_authoritative_structure_fp = ""
        self._mark_destination_real_tree_snapshot_stale()
        self._destination_invalidate_spo_snapshot_trust("full_tree_walk_error")
        self._destination_full_tree_materialization_pending = False
        self._destination_expand_all_after_full_tree = False
        self._expand_all_pending["destination"] = False
        self._destination_idle_materialize_parked_for_full_tree_reason = ""
        self._destination_idle_materialize_full_tree_park_requested_drive_id = ""
        button = self._expand_all_button_for_panel("destination")
        if button is not None:
            button.setEnabled(True)
            self._set_expand_all_button_label("destination", False)
        log_warn("destination_full_tree_failed", drive_id=drive_id, error=payload.get("error", "Unknown error"))
        self._destination_resume_startup_descendant_queue_after_authority_if_paused(phase="full_tree_error")

    def on_destination_full_tree_finished(self, worker_id):
        if worker_id == self._active_destination_full_tree_worker_id:
            worker = self._destination_full_tree_worker
            self._destination_full_tree_worker = None
        else:
            worker = self._retired_destination_full_tree_workers.pop(worker_id, None)
        if worker is not None:
            worker.deleteLater()

    def start_full_count_worker(self, drive_id):
        if not drive_id:
            self._reset_full_count_state()
            return

        if self._memory_restore_blocks_source_full_count():
            self._full_count_pending_drive_id_after_restore = str(drive_id)
            log_info(
                "full_count_skipped_restore_active",
                drive_id=drive_id,
                reason="memory_restore_blocks_source_full_count",
            )
            loaded_items = (
                self.count_tree_items(self.source_tree_widget) if hasattr(self, "source_tree_widget") else 0
            )
            self._update_source_count_labels(loaded_items)
            return
        _cnt_ok, _cnt_why = self._source_should_run_startup_count_worker(str(drive_id))
        if not _cnt_ok:
            self._full_count_pending_drive_id_after_restore = str(drive_id)
            log_info(
                "source_startup_count_worker_blocked_policy",
                root_path_count=0,
                row_count=0,
                reason=str(_cnt_why)[:120],
            )
            loaded_items = (
                self.count_tree_items(self.source_tree_widget) if hasattr(self, "source_tree_widget") else 0
            )
            self._update_source_count_labels(loaded_items)
            return

        if (
            self.full_count_worker is not None
            and self.full_count_worker.isRunning()
            and self._full_count_requested_drive_id == drive_id
        ):
            self._update_source_count_labels(
                self.count_tree_items(self.source_tree_widget) if hasattr(self, "source_tree_widget") else 0
            )
            return

        if (
            self.full_source_file_count is not None
            and self.full_source_folder_count is not None
            and self._full_count_completed_drive_id == drive_id
        ):
            self._update_source_count_labels(
                self.count_tree_items(self.source_tree_widget) if hasattr(self, "source_tree_widget") else 0
            )
            return

        if self.full_count_worker is not None and self.full_count_worker.isRunning():
            prev = self.full_count_worker
            try:
                prev.requestInterruption()
            except Exception:
                pass
            self._retired_full_count_workers[self._active_full_count_worker_id] = prev

        self.full_source_item_count = None
        self.full_source_file_count = None
        self.full_source_folder_count = None
        self._full_count_error_message = ""
        self._full_count_requested_drive_id = drive_id
        self._full_count_completed_drive_id = ""
        self._update_source_count_labels(
            self.count_tree_items(self.source_tree_widget) if hasattr(self, "source_tree_widget") else 0
        )

        self._full_count_sequence += 1
        worker_id = self._full_count_sequence
        worker = FullCountWorker(self.graph, drive_id, worker_id=worker_id)
        self.full_count_worker = worker
        self._active_full_count_worker_id = worker_id

        worker.success.connect(lambda payload, worker_id=worker_id: self._safe_invoke("full_count.success", self.on_full_count_success, payload, worker_id))
        worker.error.connect(lambda payload, worker_id=worker_id: self._safe_invoke("full_count.error", self.on_full_count_error, payload, worker_id))
        worker.finished.connect(lambda worker_id=worker_id: self._safe_invoke("full_count.finished", self.on_full_count_finished, worker_id))
        log_info("full_count_started", drive_id=drive_id)
        worker.start()

    def _heavy_session_for_background_graph_walk(self):
        ep = getattr(self, "_expand_all_pending", None) or {}
        return (
            len(self.planned_moves) > 24
            or len(getattr(self, "_source_restore_materialization_queue", []) or []) > 15
            or bool(ep.get("source"))
            or bool(ep.get("destination"))
        )

    def _schedule_full_count_with_restore_backoff(self, drive_id):
        if not drive_id:
            return
        if self._memory_restore_blocks_source_full_count():
            self._full_count_pending_drive_id_after_restore = str(drive_id)
            log_info(
                "full_count_deferred_restore_active",
                drive_id=drive_id,
                reason="skip_schedule_until_memory_restore_finishes",
            )
            loaded_items = (
                self.count_tree_items(self.source_tree_widget) if hasattr(self, "source_tree_widget") else 0
            )
            self._update_source_count_labels(loaded_items)
            return
        if self._heavy_session_for_background_graph_walk():
            delay_ms = 42000
            log_info(
                "full_count_deferred",
                drive_id=drive_id,
                delay_ms=delay_ms,
                reason="heavy_session_background_graph_walk",
                planned_moves=len(self.planned_moves),
            )

            def _deferred():
                if self._current_selected_source_drive_id() != drive_id:
                    return
                if self.full_count_worker is not None and self.full_count_worker.isRunning():
                    return
                if self._memory_restore_blocks_source_full_count():
                    self._full_count_pending_drive_id_after_restore = str(drive_id)
                    log_info(
                        "full_count_deferred_restore_active",
                        drive_id=drive_id,
                        reason="heavy_backoff_timer_skipped_restore_still_active",
                    )
                    loaded = (
                        self.count_tree_items(self.source_tree_widget)
                        if hasattr(self, "source_tree_widget")
                        else 0
                    )
                    self._update_source_count_labels(loaded)
                    return
                self.start_full_count_worker(drive_id)

            QTimer.singleShot(delay_ms, _deferred)
            return
        self.start_full_count_worker(drive_id)

    def _flush_pending_source_full_count_after_memory_restore(self) -> None:
        pending = str(getattr(self, "_full_count_pending_drive_id_after_restore", "") or "")
        if not pending:
            return
        self._full_count_pending_drive_id_after_restore = ""
        if pending != self._current_selected_source_drive_id():
            loaded_items = (
                self.count_tree_items(self.source_tree_widget) if hasattr(self, "source_tree_widget") else 0
            )
            self._update_source_count_labels(loaded_items)
            return
        self._schedule_full_count_with_restore_backoff(pending)

    def on_full_count_success(self, payload, worker_id):
        drive_id = payload.get("drive_id", "")
        total_count = int(payload.get("total_count", 0))
        file_count = int(payload.get("file_count", 0))
        folder_count = int(payload.get("folder_count", 0))
        if file_count == 0 and folder_count == 0 and total_count > 0:
            file_count = total_count
            folder_count = 0
        if worker_id != self._active_full_count_worker_id or drive_id != self._full_count_requested_drive_id:
            return
        self.full_source_item_count = total_count
        self.full_source_file_count = file_count
        self.full_source_folder_count = folder_count
        self._full_count_completed_drive_id = drive_id
        self._full_count_error_message = ""
        log_info(
            "full_count_completed",
            drive_id=drive_id,
            total_count=total_count,
            file_count=file_count,
            folder_count=folder_count,
        )
        self._update_source_count_labels(
            self.count_tree_items(self.source_tree_widget) if hasattr(self, "source_tree_widget") else 0
        )

    def on_full_count_error(self, payload, worker_id):
        drive_id = payload.get("drive_id", "")
        if worker_id != self._active_full_count_worker_id or drive_id != self._full_count_requested_drive_id:
            return
        self.full_source_item_count = None
        self.full_source_file_count = None
        self.full_source_folder_count = None
        self._full_count_completed_drive_id = ""
        self._full_count_error_message = payload.get("error", "Unknown counting error.")
        log_warn("full_count_failed", drive_id=drive_id, error=self._full_count_error_message)
        self._update_source_count_labels(
            self.count_tree_items(self.source_tree_widget) if hasattr(self, "source_tree_widget") else 0
        )

    def on_full_count_finished(self, worker_id):
        if worker_id == self._active_full_count_worker_id:
            worker = self.full_count_worker
            self.full_count_worker = None
        else:
            worker = self._retired_full_count_workers.pop(worker_id, None)
        if worker is not None:
            worker.deleteLater()

    def update_progress_summaries(self):
        if getattr(self, "_sharepoint_lazy_mode", False):
            if self._planning_workspace_is_busy() or getattr(self, "_memory_restore_in_progress", False):
                loaded_items = int(getattr(self, "_cached_loaded_source_items", 0) or 0)
            else:
                loaded_items = self.count_tree_items(self.source_tree_widget) if hasattr(self, "source_tree_widget") else 0
            planned_items = len(self.planned_moves)
            self._update_source_count_labels(loaded_items)
            for label in [
                getattr(self, "dashboard_planned_items", None),
                getattr(self, "workspace_planned_items", None),
            ]:
                if label is not None:
                    label.setText(str(planned_items))
            existing_not_planned = len(getattr(self, "_workflow_not_planned_rows", []))
            existing_needs_review = len(getattr(self, "_workflow_needs_review_rows", []))
            for label in [
                getattr(self, "dashboard_not_planned_items", None),
                getattr(self, "workspace_not_planned_items", None),
            ]:
                if label is not None:
                    label.setText(str(existing_not_planned))
            for label in [
                getattr(self, "dashboard_needs_review_items", None),
                getattr(self, "workspace_needs_review_items", None),
            ]:
                if label is not None:
                    label.setText(str(existing_needs_review))
            if self._planning_workspace_is_busy():
                self._schedule_progress_summary_refresh(2500)
            self._update_planned_moves_duplicate_destination_banner()
            self._refresh_planning_derived_state("progress_summary_lazy")
            return

        workflow_state = self._compute_planning_workflow_state()
        loaded_items = workflow_state["total_items"]
        planned_items = len(self.planned_moves)
        not_planned_items = workflow_state["not_planned_count"]
        needs_review_items = workflow_state["needs_review_count"]

        self._apply_planning_workflow_state(workflow_state)
        self._update_source_count_labels(loaded_items)

        for label in [
            getattr(self, "dashboard_planned_items", None),
            getattr(self, "workspace_planned_items", None),
        ]:
            if label is not None:
                label.setText(str(planned_items))

        for label in [
            getattr(self, "dashboard_not_planned_items", None),
            getattr(self, "workspace_not_planned_items", None),
        ]:
            if label is not None:
                label.setText(str(not_planned_items))

        for label in [
            getattr(self, "dashboard_needs_review_items", None),
            getattr(self, "workspace_needs_review_items", None),
        ]:
            if label is not None:
                label.setText(str(needs_review_items))

        self._update_planned_moves_duplicate_destination_banner()
        self._refresh_planning_derived_state("progress_summary")

    def _refresh_workflow_state_on_demand(self):
        workflow_state = self._compute_planning_workflow_state()
        self._apply_planning_workflow_state(workflow_state)

        not_planned_items = workflow_state["not_planned_count"]
        needs_review_items = workflow_state["needs_review_count"]

        for label in [
            getattr(self, "dashboard_not_planned_items", None),
            getattr(self, "workspace_not_planned_items", None),
        ]:
            if label is not None:
                label.setText(str(not_planned_items))

        for label in [
            getattr(self, "dashboard_needs_review_items", None),
            getattr(self, "workspace_needs_review_items", None),
        ]:
            if label is not None:
                label.setText(str(needs_review_items))

        self._update_planned_moves_duplicate_destination_banner()
        self._refresh_planning_derived_state("workflow_on_demand")

    def on_workspace_tab_changed(self, index):
        if not getattr(self, "_sharepoint_lazy_mode", False):
            # Do not force-expand here: tree selection calls setCurrentWidget(details_box), which
            # emits currentChanged and would immediately undo a user collapse (non-lazy sessions).
            return
        if not hasattr(self, "workspace_tabs"):
            return
        if getattr(self, "_workspace_tabs_collapsed", False):
            self._apply_workspace_tabs_collapsed_state(False)
        widget = self.workspace_tabs.widget(index)
        if widget in (
            getattr(self, "planned_moves_box", None),
            getattr(self, "review_fix_box", None),
        ):
            self._schedule_safe_timer(0, "workspace_tab_workflow_refresh", self._refresh_workflow_state_on_demand)

    def _planning_header_collapsed_height(self):
        if not hasattr(self, "planning_header_toggle_button"):
            return 48
        toggle_h = self.planning_header_toggle_button.sizeHint().height()
        title_h = 20
        if hasattr(self, "planning_header_title_label") and self.planning_header_title_label is not None:
            title_h = self.planning_header_title_label.sizeHint().height()
        return max(48, max(toggle_h, title_h) + 18)

    def _apply_planning_header_collapsed_state(self, collapsed):
        header_content = getattr(self, "planning_header_content", None)
        toggle_button = getattr(self, "planning_header_toggle_button", None)
        if header_content is None or toggle_button is None:
            return
        self._planning_header_collapsed = bool(collapsed)
        header_content.setVisible(not self._planning_header_collapsed)
        header_frame = header_content.parentWidget()
        if self._planning_header_collapsed:
            collapsed_height = self._planning_header_collapsed_height()
            header_frame.setMinimumHeight(collapsed_height)
            header_frame.setMaximumHeight(collapsed_height)
            header_frame.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
            toggle_button.setText("▾")
            toggle_button.setToolTip("Expand planning header")
        else:
            header_frame.setMinimumHeight(self._planning_header_expanded_min_height)
            header_frame.setMaximumHeight(16777215)
            header_frame.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Maximum)
            toggle_button.setText("▴")
            toggle_button.setToolTip("Collapse planning header")
        header_frame.updateGeometry()
        header_frame.update()

    def toggle_planning_header_collapsed(self):
        self._apply_planning_header_collapsed_state(not getattr(self, "_planning_header_collapsed", False))

    def _workspace_tabs_collapsed_height(self):
        if not hasattr(self, "workspace_tabs"):
            return 42
        tab_bar = self.workspace_tabs.tabBar()
        if tab_bar is None:
            return 42
        return max(38, tab_bar.sizeHint().height() + 10)

    def _apply_workspace_tabs_collapsed_state(self, collapsed):
        if not hasattr(self, "workspace_tabs"):
            return
        self._workspace_tabs_collapsed = bool(collapsed)
        tw = self.workspace_tabs
        tw.blockSignals(True)
        try:
            if self._workspace_tabs_collapsed:
                collapsed_height = self._workspace_tabs_collapsed_height()
                tw.setMinimumHeight(collapsed_height)
                tw.setMaximumHeight(collapsed_height)
                tw.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
                self.workspace_tabs_toggle_button.setText("▾")
                self.workspace_tabs_toggle_button.setToolTip("Expand bottom panel")
                tw.setDocumentMode(True)
            else:
                tw.setMinimumHeight(self._workspace_tabs_expanded_min_height)
                tw.setMaximumHeight(self._workspace_tabs_expanded_max_height)
                tw.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Preferred)
                self.workspace_tabs_toggle_button.setText("▴")
                self.workspace_tabs_toggle_button.setToolTip("Collapse bottom panel")
                tw.setDocumentMode(False)
            tw.updateGeometry()
            tw.update()
        finally:
            tw.blockSignals(False)

    def toggle_workspace_tabs_collapsed(self):
        self._apply_workspace_tabs_collapsed_state(not getattr(self, "_workspace_tabs_collapsed", False))

    def _source_parent_path(self, source_path):
        segments = self._path_segments(self._canonical_source_projection_path(source_path))
        if len(segments) <= 1:
            return ""
        return "\\".join(segments[:-1])

    def _destination_parent_path(self, destination_path):
        segments = self._path_segments(self._canonical_destination_projection_path(destination_path))
        if len(segments) <= 1:
            return ""
        return "\\".join(segments[:-1])

    def _destination_drag_move_narrow_bind_scope_paths(
        self,
        *,
        old_proj: str,
        new_proj: str,
        target_path: str,
        current_projection_path: str,
        target_projection_path: str,
    ) -> set[str]:
        """Endpoints plus immediate parents only — local-first manual drag idle follow-up bind scope."""
        s: set[str] = set()
        for _p in (old_proj, new_proj, target_path, current_projection_path, target_projection_path):
            raw = str(_p or "").strip()
            if not raw:
                continue
            _c = self._canonical_destination_projection_path(raw) or self.normalize_memory_path(raw)
            if _c:
                s.add(_c)
                pp = self._destination_parent_path(_c)
                if pp:
                    pc = self._canonical_destination_projection_path(pp) or self.normalize_memory_path(str(pp).strip())
                    if pc:
                        s.add(pc)
        return s

    def _show_proposed_path_builder_dialog(self, base_path):
        dialog = QDialog(self)
        dialog.setWindowTitle("New Proposed Folder")
        dialog.setModal(True)
        dialog.resize(520, 170)

        layout = QVBoxLayout(dialog)
        form = QFormLayout()

        base_path_label = QLabel(base_path or "Root")
        base_path_label.setWordWrap(True)
        relative_path_input = QLineEdit()
        relative_path_input.setPlaceholderText(r"Example: Projects\Completed\YMCA")
        preview_label = QLabel(base_path or "Root")
        preview_label.setWordWrap(True)
        preview_label.setObjectName("MutedText")

        def update_preview():
            relative_path = self.normalize_memory_path(relative_path_input.text())
            if relative_path:
                preview_label.setText(
                    self.normalize_memory_path("\\".join(part for part in [base_path, relative_path] if part))
                )
            else:
                preview_label.setText(base_path or "Root")

        relative_path_input.textChanged.connect(lambda _text: update_preview())
        update_preview()

        form.addRow("Base path:", base_path_label)
        form.addRow("Folder or relative path:", relative_path_input)
        form.addRow("Preview:", preview_label)
        layout.addLayout(form)

        hint = QLabel("Add a single folder name or a nested relative path. Click OK to create the proposed branch.")
        hint.setWordWrap(True)
        hint.setObjectName("MutedText")
        layout.addWidget(hint)

        buttons = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
        buttons.accepted.connect(dialog.accept)
        buttons.rejected.connect(dialog.reject)
        layout.addWidget(buttons)

        relative_path_input.setFocus()
        if dialog.exec() != QDialog.Accepted:
            return "", False
        return self.normalize_memory_path(relative_path_input.text()), True

    def _most_common_path(self, paths):
        counts = {}
        first_seen = {}
        for index, path in enumerate(paths):
            if not path:
                continue
            counts[path] = counts.get(path, 0) + 1
            first_seen.setdefault(path, index)
        if not counts:
            return "", 0, 0
        ordered = sorted(counts.items(), key=lambda item: (-item[1], first_seen[item[0]], item[0].lower()))
        best_path, best_count = ordered[0]
        return best_path, best_count, sum(counts.values())

    def _iter_visible_source_nodes(self):
        tree = getattr(self, "source_tree_widget", None)
        if tree is None:
            return []
        visible_nodes = []
        seen_paths = set()
        for top_item in self._iter_panel_top_level_rows("source"):
            for item in self._iter_tree_items(top_item):
                node_data = self.get_tree_item_node_data(item) or {}
                if node_data.get("placeholder"):
                    continue
                canonical_path = self._canonical_source_projection_path(self._tree_item_path(node_data))
                if not canonical_path or canonical_path in seen_paths:
                    continue
                seen_paths.add(canonical_path)
                visible_nodes.append(dict(node_data))
        visible_nodes.sort(key=lambda node: self._canonical_source_projection_path(self._tree_item_path(node)).lower())
        return visible_nodes

    def _build_suggestion_for_source_node(self, node_data):
        source_name = node_data.get("name", "Unnamed Item")
        source_path = self._canonical_source_projection_path(self._tree_item_path(node_data))
        if not source_path:
            return None

        source_parent = self._source_parent_path(source_path)
        sibling_destination_parents = []
        nearby_destination_parents = []
        repeated_name_destination_parents = []
        source_segments = self._path_segments(source_path)

        for move in self.planned_moves:
            move_source_path = self._canonical_source_projection_path(move.get("source_path", ""))
            if not move_source_path or self._paths_equivalent(move_source_path, source_path, "source"):
                continue
            destination_parent = self._canonical_destination_projection_path(self._allocation_parent_path(move))
            if not destination_parent:
                continue

            move_source_parent = self._source_parent_path(move_source_path)
            if source_parent and move_source_parent == source_parent:
                sibling_destination_parents.append(destination_parent)

            move_name = str(move.get("source_name", "")).strip().lower()
            if move_name and move_name == str(source_name).strip().lower():
                repeated_name_destination_parents.append(destination_parent)

            move_segments = self._path_segments(move_source_path)
            common_prefix = 0
            for left, right in zip(source_segments, move_segments):
                if left.lower() != right.lower():
                    break
                common_prefix += 1
            if common_prefix >= 2:
                nearby_destination_parents.append(destination_parent)

        if sibling_destination_parents:
            parent_path, best_count, total = self._most_common_path(sibling_destination_parents)
            confidence = 0.92 if best_count == total else 0.78
            return {
                "destination_path": self.normalize_memory_path(f"{parent_path}\\{source_name}"),
                "confidence": confidence,
                "reason": "Matched sibling planning pattern in the same source branch.",
                "rule": "sibling_pattern",
            }

        if repeated_name_destination_parents:
            parent_path, best_count, total = self._most_common_path(repeated_name_destination_parents)
            confidence = 0.74 if best_count == total else 0.64
            return {
                "destination_path": self.normalize_memory_path(f"{parent_path}\\{source_name}"),
                "confidence": confidence,
                "reason": "Matched another planned item with the same source name.",
                "rule": "repeated_name_pattern",
            }

        if nearby_destination_parents:
            parent_path, best_count, total = self._most_common_path(nearby_destination_parents)
            confidence = 0.7 if best_count == total else 0.58
            return {
                "destination_path": self.normalize_memory_path(f"{parent_path}\\{source_name}"),
                "confidence": confidence,
                "reason": "Matched nearby planning patterns within the same source area.",
                "rule": "nearby_branch_pattern",
            }

        return None

    def _log_destination_anchor_missing_review_transition(self, row: dict[str, Any] | None) -> None:
        """Emit created/updated logs when the missing-anchor review row appears or its signature changes."""
        if row is None:
            self._destination_anchor_missing_review_sig = None
            return
        sig = str(row.get("_review_sig") or "")
        prev = self._destination_anchor_missing_review_sig
        payload = {
            "anchor_display_path": str(row.get("source_path") or "")[:500],
            "anchor_item_id_suffix": str(row.get("anchor_item_id_suffix") or ""),
            "destination_drive_id_suffix": str(row.get("destination_drive_id_suffix") or ""),
            "planned_moves_count": len(self.planned_moves),
            "proposed_folders_count": len(self.proposed_folders),
            "affected_planning_total": int(row.get("affected_planning_total") or 0),
        }
        if prev is None:
            log_info("destination_anchor_missing_review_item_created", **payload)
        elif prev != sig:
            log_info("destination_anchor_missing_review_item_updated", **payload)
        self._destination_anchor_missing_review_sig = sig

    def _append_needs_review_row(self, rows, seen_keys, *, item_name, source_path, reason, action, review_type):
        key = (review_type, self.normalize_memory_path(source_path), reason)
        if key in seen_keys:
            return
        seen_keys.add(key)
        rows.append({
            "item_name": item_name,
            "source_path": self.normalize_memory_path(source_path),
            "reason": reason,
            "action": action,
            "review_type": review_type,
        })

    def _compute_planning_workflow_state(self):
        visible_nodes = self._iter_visible_source_nodes()
        total_items = len(visible_nodes)
        not_planned_rows = []
        suggestion_rows = []
        needs_review_rows = []
        review_seen = set()

        duplicate_projection_paths = {}
        for move in self.planned_moves:
            projection_path = self._canonical_destination_projection_path(self._allocation_projection_path(move))
            if not projection_path:
                continue
            duplicate_projection_paths.setdefault(projection_path, []).append(move)

        proposed_paths = {
            self._canonical_destination_projection_path(folder.DestinationPath)
            for folder in self.proposed_folders
            if self._canonical_destination_projection_path(folder.DestinationPath)
        }

        for node_data in visible_nodes:
            source_name = node_data.get("name", "Unnamed Item")
            source_path = self.normalize_memory_path(self._tree_item_path(node_data))
            relationship = self._evaluate_source_relationship(node_data)
            relationship_mode = relationship.get("mode", "none")

            if relationship_mode == "none":
                not_planned_rows.append({
                    "source_name": source_name,
                    "source_path": source_path,
                    "status": "No direct or inherited mapping yet.",
                })
                suggestion = self._build_suggestion_for_source_node(node_data)
                if suggestion is not None:
                    suggestion_row = {
                        "source_name": source_name,
                        "source_path": source_path,
                        "destination_path": suggestion["destination_path"],
                        "confidence": suggestion["confidence"],
                        "reason": suggestion["reason"],
                        "rule": suggestion["rule"],
                    }
                    suggestion_rows.append(suggestion_row)
                    if suggestion["confidence"] < 0.75:
                        self._append_needs_review_row(
                            needs_review_rows,
                            review_seen,
                            item_name=source_name,
                            source_path=source_path,
                            reason="Low-confidence suggestion needs confirmation.",
                            action=suggestion["destination_path"],
                            review_type="weak_suggestion",
                        )
            elif relationship_mode == "inherited":
                self._append_needs_review_row(
                    needs_review_rows,
                    review_seen,
                    item_name=source_name,
                    source_path=source_path,
                    reason="This item currently inherits its destination from a parent mapping.",
                    action=relationship.get("suffix", ""),
                    review_type="inherited_mapping",
                )

        for projection_path, moves in duplicate_projection_paths.items():
            if len(moves) <= 1:
                continue
            for move in moves:
                self._append_needs_review_row(
                    needs_review_rows,
                    review_seen,
                    item_name=move.get("source_name", "Unnamed Item"),
                    source_path=move.get("source_path", ""),
                    reason="Multiple planned moves resolve to the same projected destination path.",
                    action=projection_path,
                    review_type="duplicate_destination_projection",
                )

        for move in self.planned_moves:
            allocation_parent_path = self._canonical_destination_projection_path(self._allocation_parent_path(move))
            if not allocation_parent_path:
                continue
            depends_on_proposed = False
            for proposed_path in proposed_paths:
                if self._paths_equivalent(allocation_parent_path, proposed_path, "destination") or self._path_is_descendant(
                    allocation_parent_path,
                    proposed_path,
                    "destination",
                ):
                    depends_on_proposed = True
                    break
            if depends_on_proposed:
                self._append_needs_review_row(
                    needs_review_rows,
                    review_seen,
                    item_name=move.get("source_name", "Unnamed Item"),
                    source_path=move.get("source_path", ""),
                    reason="Mapped into a proposed destination branch that should be confirmed.",
                    action=move.get("destination_path", ""),
                    review_type="proposed_branch_dependency",
                )

        shell = self._draft_shell_state if isinstance(self._draft_shell_state, SessionState) else None
        anchor_row: dict[str, Any] | None = None
        if shell is not None:
            anchor_row = build_destination_anchor_missing_needs_review_row(
                shell,
                planned_moves_count=len(self.planned_moves),
                proposed_folders_count=len(self.proposed_folders),
            )
        if anchor_row is None:
            self._log_destination_anchor_missing_review_transition(None)
        else:
            self._log_destination_anchor_missing_review_transition(anchor_row)
            k = (
                str(anchor_row.get("review_type") or "").strip(),
                self.normalize_memory_path(str(anchor_row.get("source_path") or "")),
                str(anchor_row.get("reason") or ""),
            )
            if k not in review_seen:
                review_seen.add(k)
                needs_review_rows.append({kk: vv for kk, vv in anchor_row.items() if not str(kk).startswith("_")})

        suggestion_rows.sort(key=lambda row: (-row["confidence"], row["source_path"].lower()))
        not_planned_rows.sort(key=lambda row: row["source_path"].lower())
        mig_extra = list(getattr(self, "_migration_import_needs_review_rows", None) or [])
        if mig_extra:
            needs_review_rows.extend(mig_extra)

        for row in list(getattr(self, "_runtime_live_memory_conflict_rows", None) or []):
            if not isinstance(row, dict):
                continue
            key = (
                str(row.get("review_type") or "").strip(),
                self.normalize_memory_path(str(row.get("source_path") or "")),
                str(row.get("reason") or ""),
            )
            if key in review_seen:
                continue
            review_seen.add(key)
            needs_review_rows.append(row)

        needs_review_rows.sort(key=lambda row: (row["review_type"], row["source_path"].lower()))

        self._workflow_not_planned_rows = not_planned_rows
        self._workflow_suggestion_rows = suggestion_rows
        self._workflow_needs_review_rows = needs_review_rows
        return {
            "total_items": total_items,
            "not_planned_count": len(not_planned_rows),
            "needs_review_count": len(needs_review_rows),
            "not_planned_rows": not_planned_rows,
            "suggestion_rows": suggestion_rows,
            "needs_review_rows": needs_review_rows,
        }

    def _set_workflow_table_rows(self, table, rows, columns):
        if table is None:
            return
        table.setRowCount(len(rows))
        for row_index, row_data in enumerate(rows):
            for column_index, column_key in enumerate(columns):
                value = row_data.get(column_key, "")
                item = QTableWidgetItem(value)
                item.setData(Qt.UserRole, dict(row_data))
                table.setItem(row_index, column_index, item)
        table.clearSelection()

    def _apply_planning_workflow_state(self, workflow_state):
        self._set_workflow_table_rows(
            getattr(self, "not_planned_table", None),
            workflow_state["not_planned_rows"],
            ["source_name", "source_path", "status"],
        )
        self._set_workflow_table_rows(
            getattr(self, "suggestions_table", None),
            [
                {
                    **row,
                    "confidence_reason": f"{int(round(row['confidence'] * 100))}% - {row['reason']}",
                }
                for row in workflow_state["suggestion_rows"]
            ],
            ["source_name", "source_path", "destination_path", "confidence_reason"],
        )
        self._apply_needs_review_table_view()

        if hasattr(self, "not_planned_status"):
            self.not_planned_status.setText(
                "All visible source items are covered by direct or inherited planning."
                if not workflow_state["not_planned_rows"]
                else f"{len(workflow_state['not_planned_rows'])} visible source item(s) still need planning."
            )
        if hasattr(self, "suggestions_status"):
            self.suggestions_status.setText(
                "No deterministic suggestions are available yet."
                if not workflow_state["suggestion_rows"]
                else f"{len(workflow_state['suggestion_rows'])} suggested mapping(s) are ready for review."
            )
        self._refresh_tree_visual_states("source")
        self._refresh_tree_visual_states("destination")
        self._update_planned_moves_projection_review_banner()

    def handle_workflow_source_row_activated(self, item, workflow_name):
        row_data = item.data(Qt.UserRole) or {}
        self._activate_workflow_source_row(row_data if isinstance(row_data, dict) else {})

    def _activate_workflow_source_row(self, row_data: dict) -> None:
        if isinstance(row_data, dict) and str(row_data.get("review_type") or "").strip() == REVIEW_TYPE_LIVE_MEMORY_DUPLICATE:
            log_info(
                "destination_live_memory_duplicate_needs_review_activation",
                subtype=str(row_data.get("live_memory_subtype") or ""),
                source_path=str(row_data.get("source_path") or "")[:260],
                live_path=str(row_data.get("live_graph_path") or row_data.get("action") or "")[:260],
            )
            if str(row_data.get("live_memory_subtype") or "").strip() == "live_duplicate_proposed_folder":
                self._show_live_duplicate_proposed_folder_resolution_dialog(row_data)
                if hasattr(self, "destination_tree_widget"):
                    try:
                        self.destination_tree_widget.setFocus(Qt.FocusReason.OtherFocusReason)
                    except Exception:
                        pass
                return
            QMessageBox.information(
                self,
                "Live vs planning conflict",
                "Microsoft 365 already has an item at a path that matches pending planning. "
                "The live library structure wins; choose how to reconcile planning when actions are available.",
            )
            if hasattr(self, "destination_tree_widget"):
                try:
                    self.destination_tree_widget.setFocus(Qt.FocusReason.OtherFocusReason)
                except Exception:
                    pass
            return
        if isinstance(row_data, dict) and str(row_data.get("review_type") or "").strip() == REVIEW_TYPE_DESTINATION_ANCHOR_MISSING:
            QMessageBox.information(
                self,
                "Destination anchor",
                "The remembered destination anchor may no longer exist at the expected path in SharePoint. "
                "Use the destination tree and planning header to review and rebind the visible anchor folder.",
            )
            if hasattr(self, "destination_tree_widget"):
                try:
                    self.destination_tree_widget.setFocus(Qt.FocusReason.OtherFocusReason)
                except Exception:
                    pass
            return
        source_path = row_data.get("source_path", "") if isinstance(row_data, dict) else ""
        source_item = self._find_visible_source_item_by_path(source_path)
        if source_item is None:
            QMessageBox.information(
                self,
                "Planning Workflow",
                "That source item is not loaded in the visible source tree yet.",
            )
            return

        tw = self.source_tree_widget
        sm = tw.selectionModel()
        ix = source_item
        if isinstance(ix, QModelIndex):
            if ix.column() != 0:
                ix = ix.siblingAtColumn(0)
            if sm is not None:
                sm.clearSelection()
            tw.setCurrentIndex(ix)
            if sm is not None:
                sm.select(
                    ix,
                    QItemSelectionModel.SelectionFlag.ClearAndSelect
                    | QItemSelectionModel.SelectionFlag.Rows,
                )
            tw.scrollTo(ix)
        self.on_tree_selection_changed("source")
        if hasattr(self, "workspace_tabs"):
            self.workspace_tabs.setCurrentWidget(self.details_box)

    def _coerce_proposed_folder_model(self, raw: Any) -> ProposedFolder | None:
        if isinstance(raw, ProposedFolder):
            return raw
        if isinstance(raw, dict):
            try:
                return ProposedFolder.from_dict(raw)
            except Exception:
                return None
        return None

    def _proposed_folder_index_for_live_duplicate_row(self, row_data: dict) -> int:
        sp = self.normalize_memory_path(str(row_data.get("source_path") or ""))
        if not sp:
            return -1
        want = self._canonical_destination_projection_path(sp) or sp
        want_key = normalize_path_key(want)
        for i, raw in enumerate(self.proposed_folders or []):
            pf = self._coerce_proposed_folder_model(raw)
            if pf is None:
                continue
            dp = self._canonical_destination_projection_path(getattr(pf, "DestinationPath", "") or "") or ""
            if not dp:
                continue
            ck = normalize_path_key(dp)
            if ck == want_key:
                return i
        return -1

    def _planned_moves_dependent_on_proposed_destination(self, proposed_canon: str) -> list[dict]:
        """Same dependency rule as proposed_branch_dependency in the planning workflow."""
        out: list[dict] = []
        prop = self._canonical_destination_projection_path(proposed_canon) or self.normalize_memory_path(proposed_canon)
        if not prop:
            return out
        for move in self.planned_moves or []:
            if not isinstance(move, dict):
                continue
            allocation_parent_path = self._canonical_destination_projection_path(self._allocation_parent_path(move))
            if not allocation_parent_path:
                continue
            if self._paths_equivalent(allocation_parent_path, prop, "destination") or self._path_is_descendant(
                allocation_parent_path,
                prop,
                "destination",
            ):
                out.append(move)
        return out

    def _drop_runtime_live_memory_conflict_row(self, row_data: dict) -> None:
        rows = list(getattr(self, "_runtime_live_memory_conflict_rows", None) or [])
        new_rows, _ = filter_runtime_live_memory_rows(
            rows,
            normalized_source_path=str(row_data.get("source_path") or ""),
            live_memory_subtype=str(row_data.get("live_memory_subtype") or ""),
            normalize_path=self.normalize_memory_path,
        )
        self._runtime_live_memory_conflict_rows = new_rows

    def _log_live_memory_duplicate_resolved(self, *, resolved_by: str, row_data: dict) -> None:
        log_info(
            "destination_live_memory_duplicate_resolved",
            resolved_by=str(resolved_by or "")[:120],
            subtype=str(row_data.get("live_memory_subtype") or "")[:80],
            source_path=str(row_data.get("source_path") or "")[:260],
            live_item_id=str(row_data.get("live_item_id") or "")[:120],
            live_item_path=str(row_data.get("live_graph_path") or row_data.get("action") or "")[:260],
        )

    def _show_live_duplicate_proposed_folder_resolution_dialog(self, row_data: dict) -> None:
        dlg = QDialog(self)
        dlg.setWindowTitle("Proposed folder conflicts with live library")
        dlg.setMinimumWidth(460)
        v = QVBoxLayout(dlg)
        v.addWidget(
            QLabel(
                "A proposed destination folder matches a folder that already exists in Microsoft 365. "
                "Resolve the planning conflict here (no SharePoint changes)."
            )
        )
        detail = QLabel(
            f"Proposed path:\n{str(row_data.get('source_path') or '')}\n\n"
            f"Live path:\n{str(row_data.get('live_graph_path') or row_data.get('action') or '')}"
        )
        detail.setWordWrap(True)
        detail.setObjectName("MutedText")
        v.addWidget(detail)

        btn_accept = QPushButton("Accept existing live folder")
        btn_accept.setToolTip(
            "Keep the live folder; mark this proposed folder satisfied and clear the conflict (planning only)."
        )
        btn_remove = QPushButton("Remove proposed folder")
        btn_remove.setToolTip("Delete this entry from proposed folders in the draft only; live folder unchanged.")
        btn_rename = QPushButton("Rename proposed…")
        btn_rename.setToolTip("Use the proposed-folder rename flow in the workspace when available.")
        btn_retarget = QPushButton("Retarget allocations…")
        btn_retarget.setToolTip("Point dependent mappings at another folder (opens when integrated).")
        btn_close = QPushButton("Close")

        row1 = QWidget()
        h1 = QHBoxLayout(row1)
        h1.setContentsMargins(0, 0, 0, 0)
        h1.addWidget(btn_accept)
        h1.addWidget(btn_remove)
        v.addWidget(row1)
        row2 = QWidget()
        h2 = QHBoxLayout(row2)
        h2.setContentsMargins(0, 0, 0, 0)
        h2.addWidget(btn_rename)
        h2.addWidget(btn_retarget)
        v.addWidget(row2)
        v.addWidget(btn_close, 0, Qt.AlignmentFlag.AlignRight)

        def _on_accept() -> None:
            if self._resolve_live_duplicate_proposed_folder_accept_existing(row_data):
                dlg.accept()

        def _on_remove() -> None:
            if self._resolve_live_duplicate_proposed_folder_remove_proposed(row_data):
                dlg.accept()

        def _on_rename() -> None:
            self._live_duplicate_proposed_folder_run_rename(row_data, parent=dlg)

        def _on_retarget() -> None:
            self._live_duplicate_proposed_folder_begin_retarget(row_data, parent=dlg)

        btn_accept.clicked.connect(_on_accept)
        btn_remove.clicked.connect(_on_remove)
        btn_rename.clicked.connect(_on_rename)
        btn_retarget.clicked.connect(_on_retarget)
        btn_close.clicked.connect(dlg.reject)
        dlg.exec()

    def _resolve_live_duplicate_proposed_folder_accept_existing(self, row_data: dict) -> bool:
        log_info(
            "destination_live_memory_duplicate_accept_existing_requested",
            subtype=str(row_data.get("live_memory_subtype") or "")[:80],
            source_path=str(row_data.get("source_path") or "")[:260],
            live_item_id=str(row_data.get("live_item_id") or "")[:120],
            live_item_path=str(row_data.get("live_graph_path") or row_data.get("action") or "")[:260],
        )
        idx = self._proposed_folder_index_for_live_duplicate_row(row_data)
        if idx < 0:
            QMessageBox.warning(
                self,
                "Accept existing live folder",
                "Could not find a matching proposed folder for this review item.",
            )
            return False
        raw = (self.proposed_folders or [])[idx]
        pf = self._coerce_proposed_folder_model(raw)
        if pf is None:
            QMessageBox.warning(self, "Accept existing live folder", "Invalid proposed folder row.")
            return False
        live_id = str(row_data.get("live_item_id") or "")
        live_path = str(row_data.get("live_graph_path") or row_data.get("action") or "")
        new_pf = apply_accept_existing_live_folder_to_proposed_folder(
            pf,
            live_item_id=live_id,
            live_item_path=live_path,
        )
        folders = list(self.proposed_folders)
        folders[idx] = new_pf
        self.proposed_folders = folders
        self._drop_runtime_live_memory_conflict_row(row_data)
        log_info(
            "destination_live_memory_duplicate_accept_existing_completed",
            resolved_by=RESOLVED_BY_ACCEPT_EXISTING_LIVE_FOLDER,
            live_item_id=live_id[:120],
            live_item_path=live_path[:260],
            resolved_at_utc=str(getattr(new_pf, "LiveMemoryDuplicateResolvedAtUtc", "") or "")[:80],
        )
        self._log_live_memory_duplicate_resolved(
            resolved_by=RESOLVED_BY_ACCEPT_EXISTING_LIVE_FOLDER,
            row_data=row_data,
        )
        self._refresh_workflow_state_on_demand()
        self._refresh_proposed_folders_table()
        self._notify_planning_mutation_destination_snapshot_dirty(
            reason="live_memory_duplicate_accept_existing",
            surface="live_memory_duplicate",
        )
        return True

    def _resolve_live_duplicate_proposed_folder_remove_proposed(self, row_data: dict) -> bool:
        log_info(
            "destination_live_memory_duplicate_remove_proposed_requested",
            subtype=str(row_data.get("live_memory_subtype") or "")[:80],
            source_path=str(row_data.get("source_path") or "")[:260],
        )
        idx = self._proposed_folder_index_for_live_duplicate_row(row_data)
        if idx < 0:
            QMessageBox.warning(
                self,
                "Remove proposed folder",
                "Could not find a matching proposed folder for this review item.",
            )
            return False
        raw = (self.proposed_folders or [])[idx]
        pf = self._coerce_proposed_folder_model(raw)
        if pf is None:
            QMessageBox.warning(self, "Remove proposed folder", "Invalid proposed folder row.")
            return False
        dp = self._canonical_destination_projection_path(getattr(pf, "DestinationPath", "") or "") or ""
        deps = self._planned_moves_dependent_on_proposed_destination(dp)
        if deps:
            log_info(
                "destination_live_memory_duplicate_remove_proposed_blocked",
                dependent_planned_moves=len(deps),
                proposed_path_excerpt=dp[:240],
            )
            QMessageBox.warning(
                self,
                "Cannot remove proposed folder",
                f"{len(deps)} planned allocation(s) depend on this proposed folder branch. "
                "Retarget those mappings first, then remove the proposed entry.",
            )
            return False
        folders = list(self.proposed_folders)
        folders.pop(idx)
        self.proposed_folders = folders
        self._drop_runtime_live_memory_conflict_row(row_data)
        log_info(
            "destination_live_memory_duplicate_remove_proposed_completed",
            resolved_by="remove_proposed_folder",
            removed_destination_path_excerpt=dp[:260],
        )
        self._log_live_memory_duplicate_resolved(
            resolved_by="remove_proposed_folder",
            row_data=row_data,
        )
        self._refresh_workflow_state_on_demand()
        self._refresh_proposed_folders_table()
        self._notify_planning_mutation_destination_snapshot_dirty(
            reason="live_memory_duplicate_remove_proposed",
            surface="live_memory_duplicate",
        )
        return True

    def _disconnect_live_memory_duplicate_retarget_tree(self) -> None:
        for sig, slot in list(getattr(self, "_live_memory_retarget_tree_hook", []) or []):
            try:
                sig.disconnect(slot)
            except Exception:
                pass
        self._live_memory_retarget_tree_hook = []

    def _connect_live_memory_duplicate_retarget_tree(self) -> None:
        self._disconnect_live_memory_duplicate_retarget_tree()
        tw = getattr(self, "destination_tree_widget", None)
        if tw is None:
            return
        if isinstance(tw, QTreeView):

            def _slot(ix: QModelIndex) -> None:
                self._on_live_memory_retarget_destination_pick(ix)

            tw.clicked.connect(_slot)
            self._live_memory_retarget_tree_hook.append((tw.clicked, _slot))
        else:

            def _slot2(it: QTreeWidgetItem, _col: int) -> None:
                self._on_live_memory_retarget_destination_pick(it)

            tw.itemClicked.connect(_slot2)
            self._live_memory_retarget_tree_hook.append((tw.itemClicked, _slot2))

    def _end_live_memory_duplicate_retarget_session(
        self, *, cancelled: bool = False, failed: bool = False, error_excerpt: str = ""
    ) -> None:
        self._disconnect_live_memory_duplicate_retarget_tree()
        self._live_memory_retarget_pending_indices = []
        if cancelled:
            log_info("destination_live_memory_duplicate_retarget_cancelled")
        elif failed:
            log_info(
                "destination_live_memory_duplicate_retarget_failed",
                error_excerpt=str(error_excerpt or "")[:400],
            )

    def _on_live_memory_retarget_destination_pick(self, item_ref) -> None:
        if not getattr(self, "_live_memory_retarget_pending_indices", None):
            return
        if self._planning_browse_mode("destination") == "local":
            QMessageBox.warning(
                self,
                "Retarget allocations",
                "Switch the destination panel to SharePoint, then pick a folder.",
            )
            return
        idx = int(self._live_memory_retarget_pending_indices[0])
        n = len(self.planned_moves or [])
        if idx < 0 or idx >= n:
            self._end_live_memory_duplicate_retarget_session(failed=True, error_excerpt="planned_move_index_out_of_range")
            return
        nd = self.get_tree_item_node_data(item_ref) or {}
        if not self.node_is_manual_drag_destination_folder(nd):
            QMessageBox.information(
                self,
                "Retarget allocations",
                "Select a valid destination folder row (not a file).",
            )
            return
        ok = self._planning_retarget_planned_file_to_folder_node(self, idx, nd, interactive_confirm=True)
        if not ok:
            log_info(
                "destination_live_memory_duplicate_retarget_cancelled",
                reason="retarget_not_applied",
                planned_index=int(idx),
            )
            return
        self._live_memory_retarget_pending_indices.pop(0)
        self.refresh_planned_moves_table()
        self._refresh_workflow_state_on_demand()
        self._refresh_planning_derived_state("live_memory_duplicate_retarget")
        self._notify_planning_mutation_destination_snapshot_dirty(
            reason="live_memory_duplicate_retarget",
            surface="live_memory_duplicate",
        )
        if not self._live_memory_retarget_pending_indices:
            n0 = int(getattr(self, "_live_memory_retarget_initial_count", 0) or 0)
            log_info("destination_live_memory_duplicate_retarget_completed", retargeted_planned_rows=int(n0))
            self._disconnect_live_memory_duplicate_retarget_tree()
            QMessageBox.information(
                self,
                "Retarget allocations",
                "Retarget completed for dependent mappings.",
            )
        else:
            QMessageBox.information(
                self,
                "Retarget allocations",
                f"{len(self._live_memory_retarget_pending_indices)} mapping(s) remain — pick another folder.",
            )

    def _live_duplicate_proposed_folder_begin_retarget(self, row_data: dict, parent: QWidget | None = None) -> None:
        log_info(
            "destination_live_memory_duplicate_retarget_requested",
            subtype=str(row_data.get("live_memory_subtype") or "")[:80],
            source_path=str(row_data.get("source_path") or "")[:260],
        )
        host = parent or self
        if self._live_memory_retarget_pending_indices:
            self._end_live_memory_duplicate_retarget_session(cancelled=True)
        idx_pf = self._proposed_folder_index_for_live_duplicate_row(row_data)
        if idx_pf < 0:
            QMessageBox.warning(host, "Retarget allocations", "Could not find the matching proposed folder row.")
            return
        pf = self._coerce_proposed_folder_model((self.proposed_folders or [])[idx_pf])
        if pf is None:
            QMessageBox.warning(host, "Retarget allocations", "Invalid proposed folder row.")
            return
        proposed_canon = self._canonical_destination_projection_path(getattr(pf, "DestinationPath", "") or "") or ""
        deps = self._planned_moves_dependent_on_proposed_destination(proposed_canon)
        indices: list[int] = []
        for i, m in enumerate(self.planned_moves or []):
            if not any(m is d for d in deps):
                continue
            src = m.get("source") or {}
            if isinstance(src, dict) and bool(src.get("is_folder")):
                continue
            indices.append(i)
        if not indices:
            QMessageBox.information(
                host,
                "Retarget allocations",
                "No dependent file allocations need retarget. Folder mappings are not retargeted from this dialog.",
            )
            return
        log_info(
            "destination_live_memory_duplicate_retarget_started",
            dependent_count=len(indices),
            proposed_path_excerpt=str(proposed_canon)[:260],
        )
        self._live_memory_retarget_initial_count = int(len(indices))
        self._live_memory_retarget_pending_indices = list(indices)
        self._connect_live_memory_duplicate_retarget_tree()
        QMessageBox.information(
            host,
            "Retarget allocations",
            f"{len(indices)} planned file mapping(s) depend on this proposed folder.\n\n"
            "Click a destination folder in the SharePoint destination tree for each mapping. "
            "This is planning-only and does not change SharePoint content.",
        )

    def _live_duplicate_proposed_folder_run_rename(self, row_data: dict, parent: QWidget | None = None) -> None:
        log_info(
            "destination_live_memory_duplicate_rename_requested",
            subtype=str(row_data.get("live_memory_subtype") or "")[:80],
            source_path=str(row_data.get("source_path") or "")[:260],
        )
        host = parent or self
        live_path = str(row_data.get("live_graph_path") or row_data.get("action") or "")
        idx = self._proposed_folder_index_for_live_duplicate_row(row_data)
        if idx < 0:
            log_info("destination_live_memory_duplicate_rename_failed", reason="proposed_folder_not_found")
            QMessageBox.warning(host, "Rename proposed folder", "Could not find the matching proposed folder row.")
            return
        pf = self._coerce_proposed_folder_model((self.proposed_folders or [])[idx])
        if pf is None:
            log_info("destination_live_memory_duplicate_rename_failed", reason="invalid_proposed_model")
            QMessageBox.warning(host, "Rename proposed folder", "Invalid proposed folder row.")
            return
        existing_proposed = self._find_proposed_folder_record_by_path(
            str(getattr(pf, "DestinationPath", "") or ""),
        )
        if existing_proposed is not None and self._is_proposed_folder_submitted(existing_proposed):
            log_info("destination_live_memory_duplicate_rename_failed", reason="submitted_locked")
            self._show_submitted_item_locked_message(
                "Rename proposed folder",
                f"'{getattr(pf, 'FolderName', 'This proposed folder')}'",
                self._submitted_batch_id_for_proposed_folder(existing_proposed),
            )
            return
        orig_canon = self._canonical_destination_projection_path(getattr(pf, "DestinationPath", "") or "") or ""
        segs = self._path_segments(orig_canon)
        leaf = segs[-1] if segs else str(getattr(pf, "FolderName", "") or "").strip()
        new_name, accepted = QInputDialog.getText(
            host,
            "Rename proposed folder",
            "New folder name (planning only — does not rename anything in SharePoint):",
            text=str(leaf or ""),
        )
        if not accepted:
            log_info("destination_live_memory_duplicate_rename_cancelled", reason="input_dialog_rejected")
            return
        new_name = str(new_name or "").strip()
        if not new_name:
            log_info("destination_live_memory_duplicate_rename_cancelled", reason="empty_name")
            return
        if new_name.casefold() == str(leaf or "").strip().casefold():
            log_info("destination_live_memory_duplicate_rename_cancelled", reason="unchanged_name")
            return
        parent_path = self._destination_parent_path(orig_canon)
        proposed_path = self.normalize_memory_path("\\".join(part for part in [parent_path, new_name] if part))
        if not proposed_path:
            log_info("destination_live_memory_duplicate_rename_failed", reason="empty_destination_path")
            return
        if normalize_path_key(proposed_path) == normalize_path_key(live_path):
            log_info(
                "destination_live_memory_duplicate_rename_failed",
                reason="collides_with_live_graph_path",
            )
            QMessageBox.warning(
                host,
                "Rename proposed folder",
                "That path still matches the live folder at the same location. Choose a different name.",
            )
            return
        log_info(
            "destination_live_memory_duplicate_rename_started",
            from_path_excerpt=str(orig_canon)[:260],
            to_path_excerpt=str(proposed_path)[:260],
        )
        visible = self._find_visible_destination_item_by_path(orig_canon)
        try:
            self._rewrite_proposed_branch_runtime_paths(orig_canon, proposed_path)
            if visible is not None and isinstance(visible, QModelIndex) and visible.isValid():
                self._rename_visible_destination_subtree_index(visible, orig_canon, proposed_path)
            elif visible is not None and not isinstance(visible, QModelIndex):
                self._rename_visible_destination_subtree(visible, orig_canon, proposed_path)
        except Exception as exc:
            log_info("destination_live_memory_duplicate_rename_failed", error=str(exc)[:400])
            QMessageBox.warning(
                host,
                "Rename proposed folder",
                f"Rename failed: {str(exc)[:500]}",
            )
            return
        self._drop_runtime_live_memory_conflict_row(row_data)
        self._refresh_workflow_state_on_demand()
        self._refresh_proposed_folders_table()
        self._refresh_planning_derived_state("live_memory_duplicate_rename")
        self._notify_planning_mutation_destination_snapshot_dirty(
            reason="live_memory_duplicate_rename",
            surface="live_memory_duplicate",
        )
        log_info(
            "destination_live_memory_duplicate_rename_completed",
            new_path_excerpt=str(proposed_path)[:260],
        )
        if hasattr(self, "destination_tree_status") and self.destination_tree_status is not None:
            self.destination_tree_status.setText("Proposed folder renamed (live folder unchanged).")

    def update_selector_context_labels(self):
        if not hasattr(self, "planning_inputs"):
            return

        source_site = self.planning_inputs.get("Source Site").currentText() if self.planning_inputs.get("Source Site") else ""
        source_library = self.planning_inputs.get("Source Library").currentText() if self.planning_inputs.get("Source Library") else ""
        destination_site = self.planning_inputs.get("Destination Site").currentText() if self.planning_inputs.get("Destination Site") else ""
        destination_library = self.planning_inputs.get("Destination Library").currentText() if self.planning_inputs.get("Destination Library") else ""

        src_mode = self._planning_browse_mode("source")
        dst_mode = self._planning_browse_mode("destination")
        src_root = ""
        dst_root = ""
        if getattr(self, "source_local_fs_model", None) is not None:
            src_root = self.source_local_fs_model.rootPath() or ""
        if getattr(self, "destination_local_fs_model", None) is not None:
            dst_root = self.destination_local_fs_model.rootPath() or ""

        if hasattr(self, "source_context_label"):
            if src_mode == "local":
                self.source_context_label.setText(
                    f"Current source: This PC / network — {src_root or 'set folder root in header'}"
                )
            else:
                self.source_context_label.setText(
                    f"Current source: SharePoint — {source_site or 'Not selected'} → {source_library or 'Not selected'}"
                )
        if hasattr(self, "dashboard_source_summary"):
            if src_mode == "local":
                self.dashboard_source_summary.setText(f"Source: This PC / network / {src_root or 'Not set'}")
            else:
                self.dashboard_source_summary.setText(
                    f"Source: {(source_site or 'Not set')} / {(source_library or 'Not set')}"
                )
        if hasattr(self, "destination_context_label"):
            if dst_mode == "local":
                self.destination_context_label.setText(
                    f"Current destination: This PC / network — {dst_root or 'set folder root in header'}"
                )
            else:
                self.destination_context_label.setText(
                    f"Current destination: SharePoint — {destination_site or 'Not selected'} → {destination_library or 'Not selected'}"
                )
        if hasattr(self, "dashboard_destination_summary"):
            if dst_mode == "local":
                self.dashboard_destination_summary.setText(f"Destination: This PC / network / {dst_root or 'Not set'}")
            else:
                self.dashboard_destination_summary.setText(
                    f"Destination: {(destination_site or 'Not set')} / {(destination_library or 'Not set')}"
                )

