    def _on_settings_execution_path_toggle_changed(self, _checked: bool):
        self._refresh_execution_path_toggle_status()

    def _refresh_execution_path_toggle_status(self):
        label = getattr(self, "_settings_execution_path_status", None)
        if label is None:
            return
        enabled, source = self._resolve_draft_pipeline_toggle_state()
        if source == "env":
            if enabled:
                label.setText(
                    "Current execution path: snapshot pipeline (ENABLE_DRAFT_PIPELINE_EXECUTION forces on)."
                )
            else:
                label.setText(
                    "Current execution path: legacy manifest (ENABLE_DRAFT_PIPELINE_EXECUTION forces off)."
                )
        elif source == "ui":
            label.setText("Current execution path: legacy manifest (internal fallback toggle is on).")
        else:
            label.setText("Current execution path: snapshot pipeline (default internal mode).")

    def _graph_settings_delta_sync_enabled(self) -> bool:
        env = os.environ.get("OZLINK_GRAPH_DELTA_SYNC", "").strip().lower()
        if env in ("0", "false", "no"):
            return False
        if env in ("1", "true", "yes"):
            return True
        return QSettings().value("graph/delta_sync_enabled", True, type=bool)

    def _graph_settings_delta_bootstrap_allowed(self) -> bool:
        env = os.environ.get("OZLINK_GRAPH_DELTA_DISABLE_BOOTSTRAP", "").strip().lower()
        if env in ("1", "true", "yes"):
            return False
        return QSettings().value("graph/delta_auto_bootstrap", True, type=bool)

    def _persist_settings_delta_sync(self, checked: bool):
        if os.environ.get("OZLINK_GRAPH_DELTA_SYNC", "").strip().lower() in ("0", "false", "no"):
            return
        QSettings().setValue("graph/delta_sync_enabled", bool(checked))

    def _persist_settings_delta_bootstrap(self, checked: bool):
        if os.environ.get("OZLINK_GRAPH_DELTA_DISABLE_BOOTSTRAP", "").strip().lower() in ("1", "true", "yes"):
            return
        QSettings().setValue("graph/delta_auto_bootstrap", bool(checked))

    def build_bottom_status_bar(self):
        self.bottom_bar = QFrame()
        self.bottom_bar.setObjectName("BottomStatusBar")
        self.bottom_bar.setFixedHeight(44)

        layout = QHBoxLayout(self.bottom_bar)
        layout.setContentsMargins(14, 6, 14, 6)
        layout.setSpacing(18)

        self.bottom_tenant = QLabel("Tenant: Not Connected")
        self.bottom_source = QLabel("Source: Not Set")
        self.bottom_destination = QLabel("Destination: Not Set")
        self.bottom_mode = QLabel("Mode: Client")
        self.bottom_version = QLabel("Version: v1.0.0")
        self.bottom_refresh = QLabel("Last Refresh: Not Started")

        for lbl in [
            self.bottom_tenant,
            self.bottom_source,
            self.bottom_destination,
            self.bottom_mode,
            self.bottom_version,
            self.bottom_refresh,
        ]:
            lbl.setObjectName("FooterText")
            layout.addWidget(lbl)

        layout.addStretch()
        self.root_layout.addWidget(self.bottom_bar)

    def clear_dashboard_fields(self):
        self.work_email_input.clear()
        self._set_dashboard_status_message("Ready to open your planning session.", loading=False)

    def _planning_workspace_available(self):
        return bool(self.current_session_context.get("connected"))

    def _show_planning_sign_in_message(self):
        QMessageBox.information(
            self,
            "Sign In Required",
            "Please sign in first to load your SharePoint sites and libraries.",
        )

    def _update_planning_workspace_access(self):
        planning_available = self._planning_workspace_available()

        planning_nav_btn = self.nav_buttons.get("Planning Workspace")
        if planning_nav_btn is not None:
            planning_nav_btn.setEnabled(planning_available)
            if planning_available:
                planning_nav_btn.setToolTip("")
            else:
                planning_nav_btn.setToolTip("Please sign in first to load your SharePoint sites and libraries.")

        if hasattr(self, "dashboard_open_workspace_btn"):
            self.dashboard_open_workspace_btn.setEnabled(planning_available)
        if hasattr(self, "dashboard_connected_continue_btn"):
            self.dashboard_connected_continue_btn.setEnabled(planning_available)

    def switch_page(self, name):
        if name not in self.page_map:
            return

        if name == "Planning Workspace" and not self._planning_workspace_available():
            self.pages.setCurrentWidget(self.page_map["Dashboard"])
            self._set_active_nav_button("Dashboard")
            self.app_subtitle.setText("Dashboard")
            self._set_dashboard_status_message("Please sign in first to load your SharePoint sites and libraries.", loading=False)
            self._show_planning_sign_in_message()
            return

        if not self._is_page_allowed(name):
            allowed_pages = self.nav_allowed_by_role.get(self._navigation_role(), self.nav_allowed_by_role["guest"])
            fallback_page = allowed_pages[0] if allowed_pages else "Dashboard"
            name = fallback_page

        if name == "Requests":
            self.refresh_requests_page()

        if name == "Execution":
            self._maybe_autoload_execution_manifest_on_show()

        self.pages.setCurrentWidget(self.page_map[name])
        self._set_active_nav_button(name)
        self.app_subtitle.setText(name)
        if name == "Dashboard" and hasattr(self, "work_email_input") and self.work_email_input is not None:
            self._schedule_safe_timer(0, "dashboard_focus_work_email", self.work_email_input.setFocus)

    def _set_active_nav_button(self, active_name):
        for name, btn in self.nav_buttons.items():
            if not btn.isVisible():
                continue

            if name == active_name:
                btn.setObjectName("NavButtonActive")
            else:
                btn.setObjectName("NavButton")
            btn.style().unpolish(btn)
            btn.style().polish(btn)
            btn.update()

    def _navigation_role(self) -> str:
        """Sidebar / page access key: ``guest`` when not signed in; else ``user`` or ``admin``."""
        if not self.current_session_context.get("connected"):
            return "guest"
        role = self.current_session_context.get("user_role", "user")
        if role not in self.nav_allowed_by_role:
            return "user"
        return role

    def _is_page_allowed(self, page_name):
        nav_role = self._navigation_role()
        allowed_pages = self.nav_allowed_by_role.get(nav_role, self.nav_allowed_by_role["guest"])
        return page_name in allowed_pages

    def apply_role_visibility(self):
        """Refresh nav and settings visibility from ``current_session_context``."""
        nav_role = self._navigation_role()
        allowed_pages = self.nav_allowed_by_role.get(nav_role, self.nav_allowed_by_role["guest"])

        for name, btn in self.nav_buttons.items():
            btn.setVisible(name in allowed_pages)

        self._update_planning_workspace_access()
        is_admin = bool(self.current_session_context.get("connected")) and self.current_session_context.get("user_role") == "admin"
        if hasattr(self, "_settings_admin_submissions_card"):
            self._settings_admin_submissions_card.setVisible(is_admin)
            if hasattr(self, "test_mode_toggle") and not is_admin:
                self.test_mode_toggle.setChecked(False)
        if hasattr(self, "requests_delete_test_btn"):
            self.requests_delete_test_btn.setVisible(is_admin)
            self.requests_delete_test_btn.setEnabled(False)
        if hasattr(self, "_settings_execution_path_toggle"):
            self._settings_execution_path_toggle.setVisible(is_admin)
            if hasattr(self, "_settings_execution_path_hint"):
                self._settings_execution_path_hint.setVisible(is_admin)
            if hasattr(self, "_settings_execution_path_status"):
                self._settings_execution_path_status.setVisible(is_admin)
            self._refresh_execution_path_toggle_status()

        current_page_name = self.app_subtitle.text()
        if current_page_name not in allowed_pages:
            self.switch_page(allowed_pages[0])

        if nav_role == "guest":
            self.mode_label.setText("Sign in to use Planning and Audit")
        elif is_admin:
            self.mode_label.setText("Admin planning and operations mode")
        else:
            self.mode_label.setText("Client planning mode")

    def _is_valid_work_email(self, email):
        value = str(email or "").strip()
        if not value:
            return False
        if " " in value:
            return False
        return re.fullmatch(r"[A-Za-z0-9._%+\-']+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}", value) is not None

    def _normalize_login_email(self, email):
        return str(email or "").strip().lower()

    def _graph_token_ready_for_sharepoint(self) -> bool:
        try:
            if getattr(self.graph, "token", None):
                return True
            return bool(self.graph.refresh_access_token_silently())
        except Exception:
            return False

    def _clear_pending_library_reload_after_auth(self) -> None:
        self._pending_library_reload_after_auth = None

    def _flush_pending_sharepoint_library_reload_after_auth(self) -> None:
        pending = getattr(self, "_pending_library_reload_after_auth", None)
        if not pending:
            return
        self._clear_pending_library_reload_after_auth()

        def _go():
            try:
                self.on_library_selector_changed(pending, force=True)
            except Exception as exc:
                self._log_restore_exception("pending_library_reload_after_auth", exc)

        QTimer.singleShot(150, _go)

    def _cancel_pending_sign_in(self, *, message="Microsoft 365 sign-in cancelled. You can try again."):
        self._active_auth_attempt_id += 1
        self._login_in_progress = False
        self._login_error_seen = False
        self._pending_login_email = ""
        self._pending_login_restore_args = None
        self._clear_pending_library_reload_after_auth()
        self._close_device_flow_prompt_dialog()
        try:
            if isinstance(getattr(self.graph, "device_flow", None), dict):
                self.graph.device_flow["expires_at"] = 0
        except Exception:
            pass
        self.update_session_state(False)
        self._set_dashboard_status_message(message, loading=False)

    def _show_device_flow_prompt_dialog(self, entered_email="", *, ready=False, attempt_id=None, service_context=""):
        dialog = getattr(self, "device_flow_prompt_dialog", None)
        if dialog is None:
            dialog = DeviceFlowPromptDialog(self)
            dialog.finished.connect(self._on_device_flow_prompt_finished)
            dialog.cancel_button.clicked.connect(self._on_device_flow_prompt_cancel_requested)
            self.device_flow_prompt_dialog = dialog

        self._device_flow_prompt_ready = bool(ready)
        dialog.setProperty("attempt_id", attempt_id if attempt_id is not None else self._active_auth_attempt_id)
        dialog.set_service_context(service_context or "")
        dialog.set_prompt_state(entered_email, stage="waiting")
        dialog.show()
        dialog.raise_()
        dialog.activateWindow()

    def _close_device_flow_prompt_dialog(self):
        dialog = getattr(self, "device_flow_prompt_dialog", None)
        if dialog is None:
            return
        try:
            dialog.blockSignals(True)
            if hasattr(dialog, "_wait_timer"):
                dialog._wait_timer.stop()
            dialog.hide()
            dialog.deleteLater()
        finally:
            self.device_flow_prompt_dialog = None
            self._device_flow_prompt_ready = False

    def _launch_device_login_page(self):
        verification_uri = ""
        try:
            if isinstance(getattr(self.graph, "device_flow", None), dict):
                verification_uri = str(self.graph.device_flow.get("verification_uri", "")).strip()
        except Exception:
            verification_uri = ""

        opened = False
        if verification_uri:
            try:
                subprocess.Popen(["cmd", "/c", "start", "", verification_uri], shell=False)
                opened = True
            except Exception:
                opened = False
        if not opened and verification_uri:
            try:
                os.startfile(verification_uri)
                opened = True
            except Exception:
                opened = False
        if not opened and verification_uri:
            try:
                shell_result = ctypes.windll.shell32.ShellExecuteW(None, "open", verification_uri, None, None, 1)
                opened = int(shell_result) > 32
            except Exception:
                opened = False
        if not opened and verification_uri:
            try:
                opened = QDesktopServices.openUrl(QUrl(verification_uri))
            except Exception:
                opened = False
        if not opened:
            try:
                opened = bool(self.graph.open_device_login_page())
            except Exception:
                opened = False
        if not opened and verification_uri:
            QMessageBox.information(
                self,
                "Open Microsoft Sign-In",
                f"We could not automatically open your browser.\n\nPlease open this address manually:\n{verification_uri}",
            )
        return opened

    def _begin_silent_graph_session_restore(self):
        if self.current_session_context.get("connected"):
            return
        if self._login_in_progress:
            return
        w = getattr(self, "_silent_graph_restore_worker", None)
        if w is not None and w.isRunning():
            return
        worker = SilentGraphSessionRestoreWorker(self.graph)
        self._silent_graph_restore_worker = worker
        worker.success.connect(
            lambda payload: self._safe_invoke(
                "silent_graph_restore.success",
                self._on_silent_graph_session_restore_success,
                payload,
            )
        )
        worker.finished.connect(worker.deleteLater)
        worker.start()

    def _on_silent_graph_session_restore_success(self, payload):
        if self.current_session_context.get("connected"):
            return
        if self._login_in_progress:
            return
        if not isinstance(payload, dict):
            return
        self.on_login_success(payload, attempt_id=None)

    def _start_login_worker_after_browser_open(self, attempt_id=None):
        self.update_session_state(False, waiting=True)

        self._login_in_progress = True
        self._login_error_seen = False
        self._pending_login_restore_args = None
        self.worker = LoginWorker(self.graph)
        self.worker.success.connect(lambda payload, attempt_id=attempt_id: self._safe_invoke("login_worker.success", self.on_login_success, payload, attempt_id))
        self.worker.error.connect(lambda error, attempt_id=attempt_id: self._safe_invoke("login_worker.error", self.on_login_error, error, attempt_id))
        self.worker.finished.connect(lambda attempt_id=attempt_id: self._safe_invoke("login_worker.finished", self.on_login_worker_finished, attempt_id))
        self.worker.start()

    def _on_device_flow_prompt_finished(self, result):
        if result == int(QDialog.Accepted):
            self._close_device_flow_prompt_dialog()
            return
        dialog = self.sender()
        if dialog is None:
            return
        attempt_id = dialog.property("attempt_id")
        if attempt_id is not None and attempt_id != self._active_auth_attempt_id:
            return
        self._close_device_flow_prompt_dialog()
        self.graph.device_flow = None
        self._pending_login_email = ""
        self.top_connect_btn.setEnabled(True)
        self.dashboard_connect_btn.setEnabled(True)
        self.update_session_state(False)
        self._set_dashboard_status_message("Microsoft 365 sign-in cancelled. Update the email and click Connect again.", loading=False)

    def _on_device_flow_prompt_cancel_requested(self, *_args):
        dialog = getattr(self, "device_flow_prompt_dialog", None)
        if dialog is None:
            return
        dialog.reject()

    def handle_connect(self, allow_prompt_for_email=False, service_context=""):
        if self.current_session_context.get("connected"):
            self.handle_sign_out()
            return

        if (
            (self.device_flow_worker and self.device_flow_worker.isRunning())
            or self._login_in_progress
        ):
            self._cancel_pending_sign_in()
            return

        try:
            self._was_maximized_before_login = self.isMaximized()
            print(
                "[window-login] "
                f"before_sign_in maximized={self.isMaximized()} "
                f"state={self._window_state_repr()} "
                f"geometry={self.geometry().getRect()}"
            )

            entered_email = ""
            if hasattr(self, "work_email_input") and self.work_email_input is not None:
                entered_email = self.work_email_input.text().strip()

            if not self._is_valid_work_email(entered_email) and allow_prompt_for_email:
                text, ok = QInputDialog.getText(
                    self,
                    "Microsoft 365 sign-in",
                    "Work email for secure sign-in:",
                    QLineEdit.Normal,
                    entered_email or "",
                )
                if not ok:
                    self._clear_pending_library_reload_after_auth()
                    return
                entered_email = (text or "").strip()
                if hasattr(self, "work_email_input") and self.work_email_input is not None:
                    self.work_email_input.setText(entered_email)

            if not self._is_valid_work_email(entered_email):
                self._set_dashboard_status_message("Enter a valid work email address before continuing.", loading=False)
                if hasattr(self, "work_email_input") and self.work_email_input is not None:
                    self.work_email_input.setFocus()
                    self.work_email_input.selectAll()
                QMessageBox.information(
                    self,
                    "Work Email Required",
                    "Enter a valid work email address before continuing to Microsoft sign-in.",
                )
                self._clear_pending_library_reload_after_auth()
                return

            if entered_email:
                self._set_dashboard_status_message(f"Preparing Microsoft 365 sign-in for {entered_email}...", loading=True)
            else:
                self._set_dashboard_status_message("Preparing Microsoft 365 sign-in...", loading=True)
            self._pending_login_email = self._normalize_login_email(entered_email)
            self._auth_attempt_sequence += 1
            attempt_id = self._auth_attempt_sequence
            self._active_auth_attempt_id = attempt_id

            self.top_connect_btn.setText("Cancel Sign-In")
            self.dashboard_connect_btn.setText("Cancel Sign-In")
            self.top_connect_btn.setEnabled(True)
            self.dashboard_connect_btn.setEnabled(True)
            self._show_device_flow_prompt_dialog(
                entered_email,
                ready=False,
                attempt_id=attempt_id,
                service_context=service_context or "",
            )
            QApplication.processEvents()

            self.device_flow_worker = DeviceFlowWorker(self.graph)
            self.device_flow_worker.success.connect(lambda payload, attempt_id=attempt_id: self._safe_invoke("device_flow_worker.success", self.on_device_flow_ready, payload, attempt_id))
            self.device_flow_worker.error.connect(lambda error, attempt_id=attempt_id: self._safe_invoke("device_flow_worker.error", self.on_device_flow_error, error, attempt_id))
            self.device_flow_worker.finished.connect(lambda attempt_id=attempt_id: self._safe_invoke("device_flow_worker.finished", self.on_device_flow_worker_finished, attempt_id))
            self.device_flow_worker.start()

        except Exception as e:
            self._pending_login_email = ""
            self._login_in_progress = False
            self._clear_pending_library_reload_after_auth()
            self._close_device_flow_prompt_dialog()
            self.device_flow_worker = None
            self.worker = None
            self.update_session_state(False)
            self._set_dashboard_status_message("Could not start Microsoft 365 sign-in.", loading=False)
            et, em = _m365_sign_in_error_dialog(str(e))
            QMessageBox.critical(self, et, em)

    def handle_sign_out(self):
        if (self.worker and self.worker.isRunning()) or (self.device_flow_worker and self.device_flow_worker.isRunning()):
            return

        self._stop_session_keepalive()
        self._login_in_progress = False
        self._login_error_seen = False
        self._pending_login_email = ""
        self._pending_login_restore_args = None
        self._clear_pending_library_reload_after_auth()
        self._destination_expand_all_after_full_tree = False
        self._log_restore_state_snapshot("restore_state_cleared", reason="sign_out")
        self._save_draft_shell(include_workspace_ui=True)
        self.graph.disconnect()
        self.current_profile = None
        self.discovered_sites = []
        self._clear_runtime_draft_state(refresh_ui=False)
        self._reset_full_count_state()
        self._reset_destination_full_tree_state()
        self._memory_restore_complete = False
        self._suppress_autosave = True
        self.current_session_context = {
            "connected": False,
            "user_role": "user",
            "operator_display_name": "",
            "operator_upn": "",
            "tenant_domain": "",
            "discovered_sites": [],
        }

        self.apply_role_visibility()
        self.switch_page("Dashboard")
        self.update_session_state(False)
        self.reset_planning_selectors()
        self.reset_root_panels()
        self.clear_selection_details()
        self.refresh_planned_moves_table()
        self.bottom_source.setText("Source: Not Set")
        self.bottom_destination.setText("Destination: Not Set")
        self.bottom_refresh.setText("Last Refresh: Not Started")
        self._set_dashboard_status_message("Signed out of Microsoft 365.", loading=False)

    def on_login_worker_finished(self, attempt_id=None):
        try:
            if attempt_id is not None and attempt_id != self._active_auth_attempt_id:
                return
            self.worker = None
            if not self.current_session_context.get("connected"):
                self._login_in_progress = False
        except Exception as exc:
            self._log_restore_exception("on_login_worker_finished", exc)

    def on_device_flow_worker_finished(self, attempt_id=None):
        try:
            if attempt_id is not None and attempt_id != self._active_auth_attempt_id:
                return
            self.device_flow_worker = None
        except Exception as exc:
            self._log_restore_exception("on_device_flow_worker_finished", exc)

    def on_device_flow_ready(self, flow_payload, attempt_id=None):
        try:
            if attempt_id is not None and attempt_id != self._active_auth_attempt_id:
                return
            self._launch_device_login_page()
            self._close_device_flow_prompt_dialog()
            self._start_login_worker_after_browser_open(attempt_id=attempt_id)
        except Exception as exc:
            self._pending_login_email = ""
            self._login_in_progress = False
            self._close_device_flow_prompt_dialog()
            self.update_session_state(False)
            self.top_connect_btn.setEnabled(True)
            self.dashboard_connect_btn.setEnabled(True)
            self._log_restore_exception("on_device_flow_ready", exc)
            et, em = _m365_sign_in_error_dialog(str(exc))
            QMessageBox.critical(self, et, em)

    def on_device_flow_error(self, error, attempt_id=None):
        if attempt_id is not None and attempt_id != self._active_auth_attempt_id:
            return
        self._clear_pending_library_reload_after_auth()
        self._close_device_flow_prompt_dialog()
        self._pending_login_email = ""
        self._login_in_progress = False
        self.update_session_state(False)
        self.top_connect_btn.setEnabled(True)
        self.dashboard_connect_btn.setEnabled(True)
        self._set_dashboard_status_message("Could not start Microsoft 365 sign-in.", loading=False)
        et, em = _m365_sign_in_error_dialog(str(error))
        QMessageBox.critical(self, et, em)

    def on_discovery_worker_finished(self):
        try:
            self.discovery_worker = None
            self._refresh_planning_loading_banner()
            if hasattr(self, "planned_moves_table"):
                self.refresh_planned_moves_table()
        except Exception as exc:
            self._log_restore_exception("on_discovery_worker_finished", exc)

    def on_cache_refresh_worker_finished(self):
        try:
            self.cache_refresh_worker = None
            QTimer.singleShot(0, self._maybe_restore_cache_refresh_icon_buttons_after_jobs)
            if not self._pending_cache_refresh_panels:
                self._cache_refresh_restore_active = False
        except Exception as exc:
            self._log_restore_exception("on_cache_refresh_worker_finished", exc)

    def on_cache_refresh_success(self, payload):
        try:
            source_site = self.planning_inputs.get("Source Site").currentData() if hasattr(self, "planning_inputs") else None
            source_library = self.planning_inputs.get("Source Library").currentData() if hasattr(self, "planning_inputs") else None
            destination_site = self.planning_inputs.get("Destination Site").currentData() if hasattr(self, "planning_inputs") else None
            destination_library = self.planning_inputs.get("Destination Library").currentData() if hasattr(self, "planning_inputs") else None

            if (
                "source" in self._pending_cache_refresh_panels
                and isinstance(source_site, dict)
                and isinstance(source_library, dict)
                and source_library.get("id")
            ):
                self.loaded_root_request_signatures["source"] = None
                self.load_library_root("source", source_site, source_library, force_refresh=False)

            if (
                "destination" in self._pending_cache_refresh_panels
                and isinstance(destination_site, dict)
                and isinstance(destination_library, dict)
                and destination_library.get("id")
            ):
                if bool(getattr(self, "_cache_refresh_option3_destination", False)):
                    self._start_destination_incremental_graph_refresh_worker(destination_site, destination_library)
                else:
                    log_info(
                        "destination_cache_refresh_destructive_full_resync_path",
                        reason="rebuild_or_non_option3_destination_refresh",
                        note="load_library_root_may_apply_loading_placeholder",
                    )
                    self.loaded_root_request_signatures["destination"] = None
                    self.load_library_root("destination", destination_site, destination_library, force_refresh=False)

            if hasattr(self, "planned_moves_status"):
                dest_incr = bool(getattr(self, "_cache_refresh_option3_destination", False))
                label = (
                    "Source cache cleared; refreshing live SharePoint content on destination…"
                    if self._pending_cache_refresh_panels == {"source", "destination"} and dest_incr
                    else (
                        "Source and destination cache refreshed. Reloading libraries."
                        if self._pending_cache_refresh_panels == {"source", "destination"}
                        else (
                            "Source cache refreshed. Reloading source library."
                            if "source" in self._pending_cache_refresh_panels
                            else (
                                "Refreshing live SharePoint content…"
                                if dest_incr
                                else "Destination cache refreshed. Reloading destination library."
                            )
                        )
                    )
                )
                self.planned_moves_status.setText(label)
        except Exception as exc:
            self._log_restore_exception("on_cache_refresh_success", exc)

    def _finalize_cache_refresh_workspace_restore(self):
        ui_state = self._pending_cache_refresh_ui_state
        refreshed_panels = set(getattr(self, "_cache_refresh_refreshed_panels_snapshot", set()) or set())
        if not refreshed_panels:
            refreshed_panels = set(self._pending_cache_refresh_panels or set())
        ui_state_for_restore = dict(ui_state or {})
        for panel_key in refreshed_panels:
            if panel_key in {"source", "destination"} and panel_key in self._cache_refresh_skip_expanded_restore_panels:
                ui_state_for_restore[f"{panel_key}_expanded_paths"] = set()
        self._restore_workspace_tree_state(ui_state_for_restore)
        try:
            if getattr(self, "destination_tree_widget", None) is not None:
                if not self._destination_steady_state_full_materialize_redundant():
                    self._apply_destination_planning_overlays("cache_refresh_restore_complete")
                self._start_destination_restore_materialization()
                self.destination_tree_widget.viewport().update()

                def _post_cache_refresh_destination_dedup():
                    try:
                        self._reconcile_destination_semantic_duplicates("cache_refresh_destination_dedup")
                    except Exception as dedup_exc:
                        self._log_restore_exception("cache_refresh_destination_dedup", dedup_exc)

                QTimer.singleShot(0, _post_cache_refresh_destination_dedup)
        except Exception as exc:
            self._log_restore_exception("cache_refresh_restore.destination_overlay", exc)
        try:
            if getattr(self, "source_tree_widget", None) is not None:
                self._refresh_source_projection("source_projection_cache_refresh_restore")
                self.source_tree_widget.viewport().update()
        except Exception as exc:
            self._log_restore_exception("cache_refresh_restore.source_projection", exc)
        self._cache_refresh_restore_active = False
        self._pending_cache_refresh_ui_state = None
        self._pending_cache_refresh_panels = set()
        self._cache_refresh_refreshed_panels_snapshot = set()
        self._cache_refresh_skip_expanded_restore_panels = set()
        self._pending_cache_refresh_tree_snapshots = {}
        self._schedule_progress_summary_refresh()

    def _maybe_restore_cache_refresh_icon_buttons_after_jobs(self):
        try:
            if self.cache_refresh_worker and self.cache_refresh_worker.isRunning():
                return
            wr = getattr(self, "destination_incremental_refresh_worker", None)
            if wr is not None and wr.isRunning():
                return
            self._restore_refresh_cache_icon_buttons()
        except Exception as exc:
            self._log_restore_exception("_maybe_restore_cache_refresh_icon_buttons_after_jobs", exc)

    def _start_destination_incremental_graph_refresh_worker(self, site: dict, library: dict) -> None:
        drive_id = str((library or {}).get("id") or "").strip()
        if not drive_id or getattr(self, "graph", None) is None:
            self._on_destination_incremental_graph_refresh_error("missing_graph_client_or_drive_id")
            return
        if getattr(self, "destination_incremental_refresh_worker", None) and self.destination_incremental_refresh_worker.isRunning():
            return
        if not isinstance(site, dict) or not isinstance(library, dict):
            self._on_destination_incremental_graph_refresh_error("missing_site_or_library_selection")
            return
        worker_context = {
            "site_id": site.get("id", ""),
            "site_name": site.get("name", ""),
            "library_id": library.get("id", drive_id),
            "library_name": library.get("name", ""),
            "tree_role": "destination",
        }
        self.destination_incremental_refresh_worker = DestinationIncrementalGraphRefreshWorker(
            self.graph, drive_id, worker_context
        )
        self.destination_incremental_refresh_worker.success.connect(
            lambda payload: self._safe_invoke(
                "destination_incremental_graph_refresh.success",
                self._on_destination_incremental_graph_refresh_success,
                payload,
            )
        )
        self.destination_incremental_refresh_worker.error.connect(
            lambda msg: self._safe_invoke(
                "destination_incremental_graph_refresh.error",
                self._on_destination_incremental_graph_refresh_error,
                msg,
            )
        )
        self.destination_incremental_refresh_worker.finished.connect(
            lambda: self._safe_invoke(
                "destination_incremental_graph_refresh.finished",
                self._on_destination_incremental_graph_refresh_finished,
            )
        )
        self.destination_incremental_refresh_worker.start()
        log_info(
            "destination_incremental_graph_refresh_worker_started",
            drive_id_suffix=drive_id[-16:] if len(drive_id) > 16 else drive_id,
            incremental_refresh_no_tree_wipe=True,
            note="default_destination_refresh_avoids_load_library_root_placeholder",
        )

    def _on_destination_incremental_graph_refresh_finished(self):
        try:
            self.destination_incremental_refresh_worker = None
            QTimer.singleShot(0, self._maybe_restore_cache_refresh_icon_buttons_after_jobs)
        except Exception as exc:
            self._log_restore_exception("_on_destination_incremental_graph_refresh_finished", exc)

    def _on_destination_incremental_graph_refresh_error(self, message: str):
        try:
            log_warn("destination_incremental_graph_refresh_failed", error=str(message)[:500])
            self._set_tree_status_message(
                "destination",
                "Destination refresh could not complete; the tree was not cleared.",
                loading=False,
            )
            pending = set(self._pending_cache_refresh_panels or set())
            pending.discard("destination")
            self._pending_cache_refresh_panels = pending
            if not pending:
                self._finalize_cache_refresh_workspace_restore()
        except Exception as exc:
            self._log_restore_exception("_on_destination_incremental_graph_refresh_error", exc)

    def _on_destination_incremental_graph_refresh_success(self, payload: dict):
        try:
            items = payload.get("items") or []
            drive_id = str(payload.get("drive_id") or "").strip()
            delta = payload.get("delta") or {}
            model = getattr(self, "destination_planning_model", None)
            stats: dict = {}
            if model is not None and self._planning_browse_mode("destination") != "local":
                raw_items = items if isinstance(items, list) else []
                payloads = self._destination_root_payloads_from_graph_items(raw_items)
                dest_did = str(
                    self.pending_root_drive_ids.get("destination")
                    or self._current_selected_destination_drive_id()
                    or drive_id
                    or ""
                ).strip()
                stats = model.merge_sharepoint_library_root_graph_children(
                    payloads,
                    intended_drive_id=dest_did,
                    intended_site_id=self._current_selected_destination_site_id(),
                    strict_planned_root_identity=bool(
                        getattr(self, "_destination_strict_planning_identity_required", False)
                    ),
                )
                try:
                    self._destination_prune_multi_hub_foreign_roots(intended_drive_id=dest_did)
                except Exception:
                    pass
            tree = getattr(self, "destination_tree_widget", None)
            if tree is not None:
                tree.setEnabled(True)
            inv = int((delta or {}).get("invalidated_folders") or 0)
            entries = (delta or {}).get("invalidated_entries") or []
            if drive_id and inv > 0 and isinstance(entries, list):
                self._apply_graph_delta_to_visible_trees(drive_id, entries)
            dest_did = str(
                self.pending_root_drive_ids.get("destination")
                or self._current_selected_destination_drive_id()
                or ""
            ).strip()
            if dest_did and drive_id and str(drive_id).strip() == dest_did and inv > 0:
                self._invalidate_destination_full_tree_for_live_reconcile(drive_id)
                QTimer.singleShot(
                    0,
                    lambda d=drive_id: self._safe_invoke(
                        "destination_reconcile_after_incremental_cache_refresh",
                        lambda: self._ensure_sharepoint_destination_full_tree_worker_scheduled(
                            d,
                            schedule_reason="incremental_destination_cache_refresh_explicit",
                            explicit_refresh=True,
                        ),
                    ),
                )
            self._set_tree_status_message(
                "destination",
                "Live SharePoint content refresh applied (workspace was not cleared).",
                loading=False,
            )
            self._refresh_tree_column_width("destination")
            if not self._destination_steady_state_full_materialize_redundant():
                self._apply_destination_planning_overlays("incremental_destination_cache_refresh")
            log_info(
                "destination_incremental_cache_refresh_merged",
                drive_id_suffix=drive_id[-16:] if len(drive_id) > 16 else drive_id,
                graph_root_children=len(items or []),
                merge_stats=stats,
                merge_updated=int((stats or {}).get("updated") or 0),
                merge_inserted=int((stats or {}).get("inserted") or 0),
                merge_removed=int((stats or {}).get("removed") or 0),
                merge_skipped_planned=int((stats or {}).get("skipped_planned") or 0),
                delta_pages=int((delta or {}).get("pages") or 0),
                delta_invalidated_folders=inv,
                destructive_placeholder_refresh=False,
            )
            pending = set(self._pending_cache_refresh_panels or set())
            pending.discard("destination")
            self._pending_cache_refresh_panels = pending
            if not pending:
                self._finalize_cache_refresh_workspace_restore()
        except Exception as exc:
            self._log_restore_exception("_on_destination_incremental_graph_refresh_success", exc)

    def on_cache_refresh_error(self, error):
        try:
            self._cache_refresh_restore_active = False
            self._pending_cache_refresh_ui_state = None
            self._pending_cache_refresh_panels = set()
            self._cache_refresh_refreshed_panels_snapshot = set()
            self._cache_refresh_skip_expanded_restore_panels = set()
            self._pending_cache_refresh_tree_snapshots = {}
            if hasattr(self, "planned_moves_status"):
                self.planned_moves_status.setText("Could not refresh the SharePoint cache.")
            self._maybe_restore_cache_refresh_icon_buttons_after_jobs()
            QMessageBox.warning(self, "Refresh Cache", "The SharePoint cache could not be refreshed.")
            self._log_restore_exception("on_cache_refresh_error", Exception(str(error)))
        except Exception as exc:
            self._log_restore_exception("on_cache_refresh_error_handler", exc)

    def _start_discovery_worker(self):
        if self.discovery_worker and self.discovery_worker.isRunning():
            return
        self.discovery_worker = DiscoverSitesWorker(self.graph)
        self.discovery_worker.success.connect(lambda payload: self._safe_invoke("discovery_worker.success", self.on_discovery_success, payload))
        self.discovery_worker.error.connect(lambda error: self._safe_invoke("discovery_worker.error", self.on_discovery_error, error))
        self.discovery_worker.finished.connect(lambda: self._safe_invoke("discovery_worker.finished", self.on_discovery_worker_finished))
        self.discovery_worker.start()

    def _complete_login_restore_after_discovery(self):
        args = self._pending_login_restore_args or {}
        role = args.get("role", self.current_session_context.get("user_role", "user"))
        had_login_error = bool(args.get("had_login_error", False))
        self._safe_invoke(
            "login.restore_workspace",
            self._finish_login_workspace_restore,
            role=role,
            had_login_error=had_login_error,
        )

    def on_discovery_success(self, payload):
        discovered_sites = payload.get("discovered_sites", [])
        self.discovered_sites = discovered_sites
        self.current_session_context["discovered_sites"] = discovered_sites
        pending_restore = bool(self._pending_login_restore_args)
        self.populate_planning_selectors(discovered_sites, auto_load_initial=not pending_restore)
        self._set_dashboard_status_message("Microsoft 365 sign-in completed successfully.", loading=False)
        self._complete_login_restore_after_discovery()
        self._flush_pending_sharepoint_library_reload_after_auth()

    def on_discovery_error(self, error):
        self.discovered_sites = []
        self.current_session_context["discovered_sites"] = []
        self.populate_planning_selectors([], auto_load_initial=False)
        self._set_dashboard_status_message("Signed in, but SharePoint site discovery could not complete.", loading=False)
        self._clear_pending_library_reload_after_auth()
        self._complete_login_restore_after_discovery()

    def on_login_success(self, login_result, attempt_id=None):
        try:
            if attempt_id is not None and attempt_id != self._active_auth_attempt_id:
                return
            self._close_device_flow_prompt_dialog()
            print(
                "[window-login] "
                f"on_login_success before_refresh maximized={self.isMaximized()} "
                f"state={self._window_state_repr()} "
                f"geometry={self.geometry().getRect()}"
            )
            profile = login_result.get("profile", {})
            session_context = login_result.get("session_context", {})
            had_login_error = self._login_error_seen
            expected_email = self._normalize_login_email(getattr(self, "_pending_login_email", ""))
            actual_upn = self._normalize_login_email(session_context.get("operator_upn", profile.get("userPrincipalName", "")))
            actual_mail = self._normalize_login_email(profile.get("mail", ""))
            actual_email = actual_upn or actual_mail

            if expected_email and actual_email and expected_email != actual_email:
                self.graph.disconnect()
                self.worker = None
                self._login_in_progress = False
                self._login_error_seen = False
                self._pending_login_email = ""
                self.current_profile = None
                self.discovered_sites = []
                self.current_session_context = {
                    "connected": False,
                    "user_role": "user",
                    "operator_display_name": "",
                    "operator_upn": "",
                    "tenant_domain": "",
                    "discovered_sites": [],
                }
                self.apply_role_visibility()
                self.update_session_state(False)
                self._set_dashboard_status_message("The Microsoft account did not match the email entered in the app.", loading=False)
                if hasattr(self, "work_email_input") and self.work_email_input is not None:
                    self.work_email_input.setFocus()
                    self.work_email_input.selectAll()
                log_warn(
                    "Login email mismatch blocked.",
                    expected_email=expected_email,
                    actual_email=actual_email,
                )
                QMessageBox.warning(
                    self,
                    "Email Mismatch",
                    "The Microsoft account used in the browser does not match the email entered in the app.\n\n"
                    f"Entered email: {expected_email}\n"
                    f"Signed-in account: {actual_email}\n\n"
                    "Please try again with the matching Microsoft 365 account.",
                )
                self._clear_pending_library_reload_after_auth()
                return

            self.current_profile = profile
            self.worker = None
            self._login_in_progress = False
            self._login_error_seen = False
            self._pending_login_email = ""

            session_context["profile"] = profile
            session_context["discovered_sites"] = []
            self.discovered_sites = []
            self.current_session_context = session_context

            display_name = session_context.get("operator_display_name", profile.get("displayName", "Unknown User"))
            upn = session_context.get("operator_upn", profile.get("userPrincipalName", ""))
            domain = session_context.get("tenant_domain", upn.split("@", 1)[1] if "@" in upn else "Connected")
            role = session_context.get("user_role", "user")
            if role not in ("user", "admin"):
                role = "user"
            session_context["user_role"] = role

            try:
                self._init_memory_services()
                self._early_hydrate_pending_session_source_snapshots_for_login()
            except Exception as exc:
                self._log_restore_exception("early_memory_for_source_snapshot_shell", exc)

            self.apply_role_visibility()
            self._set_planning_workspace_loading_state("Loading SharePoint...")
            self.switch_page("Planning Workspace")
            self._set_dashboard_status_message("Signed in. Loading SharePoint sites and libraries...", loading=True)
            self.update_session_state(True, display_name, upn, domain, role=role)
            self._start_session_keepalive()
            self._pending_login_restore_args = {"role": role, "had_login_error": had_login_error}
            self._start_discovery_worker()
            print(
                "[window-login] "
                f"on_login_success after_refresh maximized={self.isMaximized()} "
                f"state={self._window_state_repr()} "
                f"geometry={self.geometry().getRect()}"
            )
        except Exception as exc:
            self._log_restore_exception("on_login_success", exc)
            self._set_dashboard_status_message("Microsoft 365 sign-in completed, but draft restore was skipped.", loading=False)
            self.update_session_state(True)

    def on_login_error(self, error, attempt_id=None):
        if attempt_id is not None and attempt_id != self._active_auth_attempt_id:
            return
        self._clear_pending_library_reload_after_auth()
        self._close_device_flow_prompt_dialog()
        if not self._login_in_progress:
            self.worker = None
            self.update_session_state(False)
            self.top_connect_btn.setEnabled(True)
            self.dashboard_connect_btn.setEnabled(True)
            self._set_dashboard_status_message("Microsoft 365 sign-in cancelled. You can try again.", loading=False)
            return
        had_restored_state = self._has_restored_runtime_state()
        self._login_error_seen = True
        self._log_restore_state_snapshot(
            "login_error_received",
            had_restored_state=had_restored_state,
            login_in_progress=self._login_in_progress,
            clear_allowed=False,
            reason="login_worker_error_received",
            error=str(error),
        )

        clear_allowed = not had_restored_state
        classification_reason = (
            "fatal_clear_empty_state"
            if clear_allowed
            else "transient_preserve_restored_state"
        )
        self._log_restore_state_snapshot(
            "login_error_classified",
            had_restored_state=had_restored_state,
            login_in_progress=self._login_in_progress,
            clear_allowed=clear_allowed,
            reason=classification_reason,
            error=str(error),
        )

        self.worker = None
        self._pending_login_email = ""
        self.current_session_context = {
            "connected": False,
            "user_role": "user",
            "operator_display_name": "",
            "operator_upn": "",
            "tenant_domain": "",
            "discovered_sites": [],
        }
        self._stop_session_keepalive()
        self.apply_role_visibility()
        self.update_session_state(False)
        if clear_allowed:
            self._log_restore_state_snapshot("login_error_state_cleared", had_restored_state=had_restored_state, login_in_progress=self._login_in_progress, clear_allowed=clear_allowed, reason=classification_reason)
            self._log_restore_state_snapshot("restore_state_cleared", reason="login_error")
            self._memory_restore_complete = False
            self._suppress_autosave = True
            self._login_in_progress = False
            self.discovered_sites = []
            self.planned_moves = []
            self._clear_source_projection_descendants_cache(reason="login_error_cleared", caller="_handle_m365_sign_in_error")
            self.proposed_folders = []
            self._reset_full_count_state()
            self._reset_destination_full_tree_state()
            self.reset_planning_selectors()
            self.reset_root_panels()
            self.clear_selection_details()
            self.refresh_planned_moves_table()
            self._set_dashboard_status_message("Microsoft 365 sign-in failed.", loading=False)
        else:
            self._log_restore_state_snapshot("login_error_state_preserved", had_restored_state=had_restored_state, login_in_progress=self._login_in_progress, clear_allowed=clear_allowed, reason=classification_reason)
            self._set_dashboard_status_message("Microsoft 365 sign-in reported an error. Restored planning state was preserved.", loading=False)
            self.refresh_planned_moves_table()
        et, em = _m365_sign_in_error_dialog(str(error))
        QMessageBox.critical(self, et if et != "Error" else "Login Failed", em)

    def update_session_state(self, connected, display_name="", upn="", tenant="", waiting=False, role="user"):
        if waiting:
            self.operator_label.setText("Waiting For Sign-In")
            if hasattr(self, "top_tenant_label"):
                self.top_tenant_label.setText("Connecting...")
            self.session_badge.setObjectName("FooterText")
            self.session_badge.setText("Session: Waiting For Sign-In")
            self.bottom_tenant.setText("Tenant: Connecting...")
            self.bottom_mode.setText("Mode: Pending")
            self.top_connect_btn.setText("Cancel Sign-In")
            self.dashboard_connect_btn.setText("Cancel Sign-In")
            if hasattr(self, "dashboard_connected_continue_btn"):
                self.dashboard_connected_continue_btn.setEnabled(False)
            if hasattr(self, "dashboard_connected_switch_btn"):
                self.dashboard_connected_switch_btn.setEnabled(False)
            self._update_planning_workspace_access()
            self.update_dashboard_session_summary(False)
            self.statusBar_update()
            self.top_connect_btn.setEnabled(True)
            self.dashboard_connect_btn.setEnabled(True)
            return

        if connected:
            self._start_session_keepalive()
            operator_text = display_name if display_name else "Connected User"
            self.operator_label.setText(operator_text)
            self.session_badge.setObjectName("StatusGood")
            self.session_badge.setText("■ Session: Connected")
            tenant_text = tenant if tenant else "Connected"
            if hasattr(self, "top_tenant_label"):
                self.top_tenant_label.setText(tenant_text)
            self.bottom_tenant.setText(f"Tenant: {tenant_text}")
            self.bottom_mode.setText(f"Mode: {role.title()}")
            self._set_dashboard_status_message("Planning session ready.", loading=False)
            self.top_connect_btn.setText("Sign Out")
            self.top_connect_btn.setEnabled(True)
            self.dashboard_connect_btn.setText("Connect to Microsoft 365")
            self.dashboard_connect_btn.setEnabled(True)
            if hasattr(self, "dashboard_connected_continue_btn"):
                self.dashboard_connected_continue_btn.setEnabled(True)
            if hasattr(self, "dashboard_connected_switch_btn"):
                self.dashboard_connected_switch_btn.setEnabled(True)
                self.dashboard_connected_switch_btn.setText("Sign Out / Switch Account")
            self._update_planning_workspace_access()
            self.update_dashboard_session_summary(True, display_name=operator_text, tenant=tenant_text, role=role)
        else:
            self._stop_session_keepalive()
            self.operator_label.setText("Not Signed In")
            self.session_badge.setObjectName("StatusBad")
            self.session_badge.setText("■ Session: Not Connected")
            if hasattr(self, "top_tenant_label"):
                self.top_tenant_label.setText("Not Connected")
            self.bottom_tenant.setText("Tenant: Not Connected")
            self.bottom_mode.setText("Mode: Client")
            self.top_connect_btn.setText("Connect to Microsoft 365")
            self.dashboard_connect_btn.setText("Connect to Microsoft 365")
            self.top_connect_btn.setEnabled(True)
            self.dashboard_connect_btn.setEnabled(True)
            if hasattr(self, "dashboard_connected_continue_btn"):
                self.dashboard_connected_continue_btn.setEnabled(False)
            if hasattr(self, "dashboard_connected_switch_btn"):
                self.dashboard_connected_switch_btn.setEnabled(False)
                self.dashboard_connected_switch_btn.setText("Sign In / Switch Account")
            self._update_planning_workspace_access()
            self.update_dashboard_session_summary(False)

        self.statusBar_update()

    def statusBar_update(self):
        self.session_badge.style().unpolish(self.session_badge)
        self.session_badge.style().polish(self.session_badge)
        self.session_badge.update()

    def reset_planning_selectors(self):
        for label_text in [
            "Source Site",
            "Source Library",
            "Destination Site",
            "Destination Library",
        ]:
            selector = self.planning_inputs.get(label_text)
            if selector is None:
                continue

            selector.blockSignals(True)
            selector.clear()
            selector.addItem("Not loaded yet")
            selector.setEnabled(False)
            selector.blockSignals(False)

        self.bottom_source.setText("Source: Not Set")
        self.bottom_destination.setText("Destination: Not Set")
        self.update_selector_context_labels()

    def _set_planning_workspace_loading_state(self, message):
        for label_text in [
            "Source Site",
            "Source Library",
            "Destination Site",
            "Destination Library",
        ]:
            selector = self.planning_inputs.get(label_text)
            if selector is None:
                continue
            selector.blockSignals(True)
            selector.clear()
            selector.addItem(message)
            selector.setEnabled(False)
            selector.blockSignals(False)

        self.set_tree_placeholder("source", "Loading source library...")
        self.set_tree_placeholder("destination", "Loading destination library...")
        self._set_tree_status_message("source", "Loading source structure...", loading=True)
        self._set_tree_status_message("destination", "Loading destination structure...", loading=True)
        self.bottom_source.setText("Source: Loading...")
        self.bottom_destination.setText("Destination: Loading...")
        self.update_selector_context_labels()
        self._refresh_planning_loading_banner()

    def _reset_planning_trees_to_select_library_prompt(self):
        """Clear post-login loading placeholders when sites are ready but no library is chosen yet."""
        self.set_tree_placeholder(
            "source",
            "Review the current source folders here. Select a source library to load the current folder structure.",
        )
        self.set_tree_placeholder(
            "destination",
            "Review the destination folders here. Select a destination library to load the target folder structure.",
        )
        self._set_tree_status_message(
            "source",
            "Select a source site and library to load folders.",
            loading=False,
        )
        self._set_tree_status_message(
            "destination",
            "Select a destination site and library to load folders.",
            loading=False,
        )
        self.bottom_source.setText("Source: Not Set")
        self.bottom_destination.setText("Destination: Not Set")

    def populate_planning_selectors(self, sites, *, auto_load_initial=True):
        self.discovered_sites = sites or []
        site_labels = ["Source Site", "Destination Site"]
        library_labels = ["Source Library", "Destination Library"]

        for label_text in site_labels:
            selector = self.planning_inputs.get(label_text)
            if selector is None:
                continue

            selector.blockSignals(True)
            selector.clear()

            if self.discovered_sites:
                for site in self.discovered_sites:
                    selector.addItem(site.get("name", "Unnamed Site"), site)
                selector.setEnabled(True)
            else:
                selector.addItem("No SharePoint sites found")
                selector.setEnabled(False)

            selector.blockSignals(False)

        for label_text in library_labels:
            selector = self.planning_inputs.get(label_text)
            if selector is None:
                continue

            selector.blockSignals(True)
            selector.clear()
            selector.addItem("Select a site first")
            selector.setEnabled(False)
            selector.blockSignals(False)

        restore_state = self._draft_shell_state if isinstance(self._draft_shell_state, SessionState) else SessionState()
        has_saved_selector_restore = any(
            [
                bool(getattr(restore_state, "SelectedSourceSite", "") or getattr(restore_state, "SelectedSourceSiteKey", "")),
                bool(getattr(restore_state, "SelectedSourceLibrary", "") or getattr(restore_state, "SelectedSourceLibraryId", "")),
                bool(getattr(restore_state, "SelectedDestinationSite", "") or getattr(restore_state, "SelectedDestinationSiteKey", "")),
                bool(
                    getattr(restore_state, "SelectedDestinationLibrary", "")
                    or getattr(restore_state, "SelectedDestinationLibraryId", "")
                ),
            ]
        )

        if self.discovered_sites and auto_load_initial and not has_saved_selector_restore:
            self.on_site_selector_changed("source")
            self.on_site_selector_changed("destination")
        else:
            if not self.discovered_sites:
                self.reset_root_panels()
            elif not auto_load_initial:
                self._reset_planning_trees_to_select_library_prompt()
        self.update_selector_context_labels()
        self._refresh_planning_loading_banner()

    def _normalize_selector_token(self, value):
        return str(value or "").strip().lower()

    def _find_selector_index(self, selector, expected_values, *, data_keys=()):
        if selector is None:
            return -1

        expected = {self._normalize_selector_token(value) for value in expected_values if str(value or "").strip()}
        if not expected:
            return -1

        for index in range(selector.count()):
            payload = selector.itemData(index)
            if isinstance(payload, dict):
                candidates = {self._normalize_selector_token(payload.get(key, "")) for key in data_keys}
                candidates.add(self._normalize_selector_token(payload.get("name", "")))
            else:
                candidates = set()
            candidates.add(self._normalize_selector_token(selector.itemText(index)))
            if expected.intersection(candidates):
                return index

        return -1

    def _set_selector_index_safely(self, selector, index):
        if selector is None or index < 0:
            return False

        selector.blockSignals(True)
        try:
            selector.setCurrentIndex(index)
            return True
        finally:
            selector.blockSignals(False)

    def _planning_library_selector_item_rows(self, selector):
        rows: list[tuple[str, Any]] = []
        if selector is None:
            return rows
        try:
            for i in range(selector.count()):
                rows.append((selector.itemText(i), selector.itemData(i)))
        except Exception:
            return []
        return rows

    def _planning_library_combo_has_explicit_empty_catalog(self, library_selector) -> bool:
        text = ""
        try:
            text = (library_selector.currentText() or "").strip() if library_selector is not None else ""
        except Exception:
            text = ""
        return "no usable libraries" in text.casefold()

    def _should_preserve_existing_library_shell_fields(self) -> bool:
        """Startup/restore paths where combo currentData may temporarily lag persisted shell JSON."""
        return bool(
            getattr(self, "_memory_restore_in_progress", False)
            or getattr(self, "_suppress_autosave", False)
            or getattr(self, "_memory_ui_rebind_in_progress", False)
        )

    def _planning_library_display_text_is_placeholder(self, text: str) -> bool:
        """True when combo shows loading/waiting instructional text — not a real library name for draft shell."""
        raw = str(text or "").strip()
        if not raw:
            return True
        cf = raw.casefold()
        blobs = (
            "loading sharepoint",
            "select a site first",
            "not selected",
            "no usable libraries",
            "waiting for the saved source library",
            "waiting for the saved destination library",
            "choose the source library that matches",
            "choose the destination library that matches",
        )
        if any(b in cf for b in blobs):
            return True
        if raw in ("—", "-"):
            return True
        return False

    def _extract_sharepoint_planning_library_fields_for_save(self, group: str, library_selector) -> tuple[str, str]:
        """Return (display_name, graph_drive_id) for Draft-SessionState library fields."""
        name, did = "", ""
        if library_selector is None:
            return name, did
        data = None
        try:
            data = library_selector.currentData()
        except Exception:
            data = None
        if isinstance(data, dict):
            did = str(data.get("id") or data.get("drive_id") or "").strip()
            name = str(data.get("name") or "").strip()
            if did:
                return name, did
        try:
            ix = library_selector.currentIndex()
            if ix >= 0:
                idata = library_selector.itemData(ix)
                if isinstance(idata, dict):
                    did2 = str(idata.get("id") or idata.get("drive_id") or "").strip()
                    if did2:
                        did = did2
                        name = name or str(idata.get("name") or "").strip()
                        return name, did
        except Exception:
            pass
        pend = str((getattr(self, "pending_root_drive_ids", {}) or {}).get(group) or "").strip()
        if not did and pend:
            did = pend
            ct = ""
            try:
                ct = (library_selector.currentText() or "").strip()
            except Exception:
                ct = ""
            if ct and "no usable libraries" not in ct.casefold():
                name = name or ct
        if not did:
            rows: list = []
            try:
                rows = self._planning_library_selector_item_rows(library_selector)
            except Exception:
                rows = []
            ct = ""
            try:
                ct = (library_selector.currentText() or "").strip()
            except Exception:
                ct = ""
            ccf = ct.casefold()
            for text, payload in rows:
                if not isinstance(payload, dict):
                    continue
                pid = str(payload.get("id") or "").strip()
                if not pid:
                    continue
                pnm = str(payload.get("name") or "").strip().casefold()
                tcf = str(text or "").strip().casefold()
                if ccf and (ccf == tcf or ccf == pnm):
                    did = pid
                    name = str(payload.get("name") or text or "").strip()
                    break
        try:
            ct_chk = (library_selector.currentText() or "").strip()
        except Exception:
            ct_chk = ""
        if self._planning_library_display_text_is_placeholder(ct_chk) and not did:
            return "", ""
        if self._planning_library_display_text_is_placeholder(name) and not did:
            return "", ""
        return name, did

    def _merge_persisted_library_fields_for_draft_shell(
        self,
        *,
        group: str,
        existing: SessionState,
        site_key_new: str,
        library_selector,
        name_new: str,
        id_new: str,
    ) -> tuple[str, str]:
        if group == "source":
            ex_key = str(getattr(existing, "SelectedSourceSiteKey", "") or "").strip()
            ex_id = str(getattr(existing, "SelectedSourceLibraryId", "") or "").strip()
            ex_name = str(getattr(existing, "SelectedSourceLibrary", "") or "").strip()
        else:
            ex_key = str(getattr(existing, "SelectedDestinationSiteKey", "") or "").strip()
            ex_id = str(getattr(existing, "SelectedDestinationLibraryId", "") or "").strip()
            ex_name = str(getattr(existing, "SelectedDestinationLibrary", "") or "").strip()
        sk_new = str(site_key_new or "").strip()
        if ex_key and sk_new and ex_key.casefold() != sk_new.casefold():
            return str(name_new or "").strip(), str(id_new or "").strip()
        id_n = str(id_new or "").strip()
        nm_n = str(name_new or "").strip()
        if id_n:
            if self._planning_library_display_text_is_placeholder(nm_n) and ex_name and ex_id:
                log_info(
                    "draft_shell_selector_placeholder_name_preserved",
                    group=group,
                    existing_library_name_excerpt=ex_name[:160],
                )
                return ex_name, id_n
            return nm_n, id_n
        if self._planning_library_display_text_is_placeholder(nm_n):
            nm_n = ""
            log_info(
                "draft_shell_selector_placeholder_name_blocked",
                group=group,
                had_blank_id=True,
                existing_library_id_suffix=ex_id[-24:] if len(ex_id) > 24 else ex_id if ex_id else "",
            )
        if self._planning_library_combo_has_explicit_empty_catalog(library_selector):
            if ex_id:
                log_info(
                    "draft_shell_selector_hydration_incomplete_preserved",
                    group=group,
                    reason="explicit_empty_catalog_keeps_saved_drive",
                    existing_library_id_suffix=ex_id[-24:] if len(ex_id) > 24 else ex_id,
                )
                log_info(
                    "draft_shell_selector_blank_write_blocked_selector_hydrating",
                    group=group,
                    existing_library_id_suffix=ex_id[-24:] if len(ex_id) > 24 else ex_id,
                )
                return ex_name, ex_id
            return "", ""
        if ex_id and not id_n:
            log_info(
                "draft_shell_selector_hydration_incomplete_preserved",
                group=group,
                reason="blank_combo_capture_preserves_existing_id",
                existing_library_id_suffix=ex_id[-24:] if len(ex_id) > 24 else ex_id,
            )
            log_info(
                "draft_shell_selector_blank_write_blocked_selector_hydrating",
                group=group,
                existing_library_id_suffix=ex_id[-24:] if len(ex_id) > 24 else ex_id,
            )
            return ex_name, ex_id
        if not ex_id:
            return nm_n, id_n
        try:
            if library_selector is not None and int(library_selector.count() or 0) == 0 and ex_id:
                log_info(
                    "draft_shell_selector_blank_preserved_from_existing",
                    group=group,
                    preserve_reason="library_selector_not_hydrated",
                    existing_library_id_suffix=ex_id[-24:] if len(ex_id) > 24 else ex_id,
                    existing_library_name_excerpt=ex_name[:160],
                )
                return ex_name, ex_id
        except Exception:
            pass
        preserve = self._should_preserve_existing_library_shell_fields()
        if preserve:
            log_info(
                "draft_shell_selector_blank_preserved_from_existing",
                group=group,
                preserve_reason="startup_or_restore_shell",
                existing_library_id_suffix=ex_id[-24:] if len(ex_id) > 24 else ex_id,
                existing_library_name_excerpt=ex_name[:160],
            )
            if getattr(self, "_memory_restore_in_progress", False):
                log_info(
                    "draft_shell_selector_blank_write_blocked_during_restore",
                    group=group,
                    existing_library_id_suffix=ex_id[-24:] if len(ex_id) > 24 else ex_id,
                )
            return ex_name, ex_id
        return nm_n, id_n

    def _log_draft_shell_selector_fields(
        self,
        message: str,
        *,
        state: Any,
        include_workspace_ui: bool,
        save_reason: str,
    ) -> None:
        def _sfx(s: str) -> str:
            t = str(s or "").strip()
            return t[-24:] if len(t) > 24 else t

        log_info(
            message,
            include_workspace_ui=bool(include_workspace_ui),
            save_reason=str(save_reason or "")[:240],
            source_site_name=str(getattr(state, "SelectedSourceSite", "") or "")[:160],
            source_site_key_suffix=_sfx(getattr(state, "SelectedSourceSiteKey", "") or ""),
            source_library_name=str(getattr(state, "SelectedSourceLibrary", "") or "")[:160],
            source_library_id_suffix=_sfx(getattr(state, "SelectedSourceLibraryId", "") or ""),
            destination_site_name=str(getattr(state, "SelectedDestinationSite", "") or "")[:160],
            destination_site_key_suffix=_sfx(getattr(state, "SelectedDestinationSiteKey", "") or ""),
            destination_library_name=str(getattr(state, "SelectedDestinationLibrary", "") or "")[:160],
            destination_library_id_suffix=_sfx(getattr(state, "SelectedDestinationLibraryId", "") or ""),
        )

    def _set_planning_library_selector_unresolved(self, panel_key: str, *, selector, outcome_tag: str) -> None:
        """Clear library selection and show a safe placeholder (no implicit index-0 bind)."""
        if selector is None:
            return
        selector.blockSignals(True)
        try:
            try:
                selector.setCurrentIndex(-1)
            except Exception:
                pass
        finally:
            selector.blockSignals(False)
        if panel_key == "source":
            try:
                self.bottom_source.setText("Source: Not Set")
            except Exception:
                pass
            self.set_tree_placeholder("source", "Select a source library to load root content.")
        else:
            try:
                self.bottom_destination.setText("Destination: Not Set")
            except Exception:
                pass
            self.set_tree_placeholder("destination", "Select a destination library to load root content.")
        try:
            self.pending_root_drive_ids[panel_key] = ""
            self.active_root_request_signatures[panel_key] = None
            self.loaded_root_request_signatures[panel_key] = None
        except Exception:
            pass
        self.update_selector_context_labels()
        log_info(
            "destination_library_restore_blocked_unresolved"
            if panel_key == "destination"
            else "source_library_restore_blocked_unresolved",
            panel_key=panel_key,
            outcome_tag=str(outcome_tag or "")[:120],
        )

    def _quiesce_destination_workers_for_rebind(self, *, reason: str, incoming_signature: dict[str, Any] | None = None) -> None:
        """Bounded wait so destination root/folder QThreads retire before a new library bind."""
        t0 = time.perf_counter()
        log_info(
            "destination_rebind_worker_quiesce_begin",
            reason=str(reason or "")[:240],
            incoming_signature=dict(incoming_signature or {}),
        )
        workers: list[tuple[str, str, Any]] = []

        entry = (self.root_load_workers or {}).get("destination")
        if isinstance(entry, dict):
            w = entry.get("worker")
            wid = str(entry.get("id") or "")
            if w is not None:
                try:
                    if _shiboken_is_valid(w) and hasattr(w, "isRunning") and w.isRunning():
                        workers.append(("destination_root_active", wid, w))
                except Exception:
                    pass

        for wid, rentry in list((self.root_load_retired_workers or {}).items()):
            if not isinstance(rentry, dict) or rentry.get("panel_key") != "destination":
                continue
            w = rentry.get("worker")
            if w is None:
                continue
            try:
                if _shiboken_is_valid(w) and hasattr(w, "isRunning") and w.isRunning():
                    workers.append(("destination_root_retired", str(wid), w))
            except Exception:
                pass

        for wk, fentry in list((self.folder_load_workers or {}).items()):
            if not str(wk).startswith("destination:") or not isinstance(fentry, dict):
                continue
            w = fentry.get("worker")
            if w is None:
                continue
            try:
                if _shiboken_is_valid(w) and hasattr(w, "isRunning") and w.isRunning():
                    workers.append(("destination_folder_active", str(wk), w))
            except Exception:
                pass

        for fwid, fentry in list((self.folder_load_retired_workers or {}).items()):
            if not isinstance(fentry, dict):
                continue
            wk = str(fentry.get("worker_key") or "")
            if not wk.startswith("destination:"):
                continue
            w = fentry.get("worker")
            if w is None:
                continue
            try:
                if _shiboken_is_valid(w) and hasattr(w, "isRunning") and w.isRunning():
                    workers.append(("destination_folder_retired", str(fwid), w))
            except Exception:
                pass

        budget_ms = 2400
        per_cap = max(200, budget_ms // max(1, len(workers))) if workers else budget_ms
        still: list[tuple[str, str]] = []
        for slot, wid, w in workers:
            try:
                self._shutdown_worker_safe_join(w, timeout_ms=min(800, per_cap))
            except Exception:
                pass
            try:
                if _shiboken_is_valid(w) and hasattr(w, "isRunning") and w.isRunning():
                    still.append((slot, wid))
                    log_info(
                        "destination_rebind_worker_retired_waiting",
                        slot=str(slot)[:80],
                        worker_id=str(wid)[:160],
                    )
            except Exception:
                pass

        log_info(
            "destination_rebind_worker_quiesce_summary",
            reason=str(reason or "")[:240],
            workers_seen=int(len(workers)),
            still_running=int(len(still)),
            wall_ms=round((time.perf_counter() - t0) * 1000.0, 2),
        )
        if not still:
            log_info("destination_rebind_worker_safe_to_replace", reason=str(reason or "")[:240])

    def _populate_library_selector_for_group(self, selector_group):
        if selector_group == "source":
            site_selector = self.planning_inputs.get("Source Site")
            library_selector = self.planning_inputs.get("Source Library")
        else:
            site_selector = self.planning_inputs.get("Destination Site")
            library_selector = self.planning_inputs.get("Destination Library")

        if site_selector is None or library_selector is None:
            return False

        intended_persisted = (
            self._persisted_source_library_drive_id_from_session()
            if selector_group == "source"
            else self._persisted_destination_library_drive_id_from_session()
        )
        log_info(
            "library_selector_hydration_started",
            selector_group=selector_group,
            intended_drive_suffix=intended_persisted[-16:] if len(intended_persisted) > 16 else intended_persisted,
            had_intended=bool(intended_persisted),
        )

        selected_site = site_selector.currentData()
        libraries: list = []
        site_id = ""
        if isinstance(selected_site, dict):
            libraries = list(selected_site.get("libraries") or [])
            site_id = str(selected_site.get("id", "") or "").strip()
            if not libraries and site_id and self.graph is not None:
                try:
                    self._startup_post_snapshot_trace_event(
                        "list_site_drives_enter",
                        selector_group=str(selector_group),
                        site_id_excerpt=str(site_id)[:32],
                    )
                    _t_drv = time.perf_counter()
                    drives = self.graph.list_site_drives(site_id)
                    libraries = [
                        self.graph.normalize_drive(drive)
                        for drive in drives
                        if self.graph.is_usable_document_library(drive)
                    ]
                    self._startup_post_snapshot_trace_event(
                        "list_site_drives_exit",
                        selector_group=str(selector_group),
                        wall_ms=round((time.perf_counter() - _t_drv) * 1000.0, 2),
                        raw_drive_count=len(drives) if drives is not None else -1,
                        usable_library_count=len(libraries),
                    )
                    selected_site["libraries"] = libraries
                except Exception as exc:
                    log_warn(
                        "planning_library_selector_site_drives_failed",
                        error=str(exc)[:500],
                        site_id_excerpt=site_id[:48],
                    )
                    libraries = []
            # Source & destination: partial cached site["libraries"] can omit the saved drive; refresh from Graph.
            if libraries and site_id and self.graph is not None and intended_persisted:
                _dcf = intended_persisted.casefold()
                has_intended = any(
                    isinstance(lib, dict)
                    and str(lib.get("id") or lib.get("drive_id") or "").strip().casefold() == _dcf
                    for lib in libraries
                )
                if not has_intended:
                    try:
                        log_info(
                            "library_selector_hydration_replaced_partial_list",
                            selector_group=selector_group,
                            site_id_excerpt=str(site_id)[:40],
                            prior_count=int(len(libraries)),
                            intended_drive_suffix=intended_persisted[-16:] if len(intended_persisted) > 16 else intended_persisted,
                        )
                        self._startup_post_snapshot_trace_event(
                            "list_site_drives_refresh_missing_persisted_library",
                            selector_group=str(selector_group),
                            site_id_excerpt=str(site_id)[:32],
                            intended_drive_suffix=intended_persisted[-16:] if len(intended_persisted) > 16 else intended_persisted,
                        )
                        _t_drv2 = time.perf_counter()
                        drives2 = self.graph.list_site_drives(site_id)
                        libraries = [
                            self.graph.normalize_drive(drive)
                            for drive in drives2
                            if self.graph.is_usable_document_library(drive)
                        ]
                        selected_site["libraries"] = libraries
                        self._startup_post_snapshot_trace_event(
                            "list_site_drives_refresh_missing_persisted_library_exit",
                            selector_group=str(selector_group),
                            wall_ms=round((time.perf_counter() - _t_drv2) * 1000.0, 2),
                            usable_library_count=len(libraries),
                        )
                    except Exception as exc:
                        log_warn(
                            "planning_library_selector_site_drives_refresh_failed",
                            error=str(exc)[:500],
                            site_id_excerpt=site_id[:48],
                        )

        if intended_persisted:
            _dcg = intended_persisted.casefold()
            if any(
                isinstance(lib, dict)
                and str(lib.get("id") or lib.get("drive_id") or "").strip().casefold() == _dcg
                for lib in (libraries or [])
            ):
                log_info(
                    "library_selector_hydration_saved_drive_found",
                    selector_group=selector_group,
                    drive_suffix=intended_persisted[-16:] if len(intended_persisted) > 16 else intended_persisted,
                    list_len=int(len(libraries or [])),
                )
                self._saved_library_selector_hydration_attempt[selector_group] = 0
            else:
                log_info(
                    "library_selector_hydration_saved_drive_missing",
                    selector_group=selector_group,
                    drive_suffix=intended_persisted[-16:] if len(intended_persisted) > 16 else intended_persisted,
                    list_len=int(len(libraries or [])),
                )

        library_selector.blockSignals(True)
        try:
            library_selector.clear()
            if libraries:
                for library in libraries:
                    library_selector.addItem(library.get("name", "Unnamed Library"), library)
                library_selector.setEnabled(True)
            else:
                library_selector.addItem("No usable libraries found")
                library_selector.setEnabled(False)
        finally:
            library_selector.blockSignals(False)

        self._sync_library_selector_to_persisted_session_drive(selector_group, library_selector)
        log_info(
            "library_selector_hydration_completed",
            selector_group=selector_group,
            combo_count=int(library_selector.count()) if library_selector is not None else -1,
            current_index=int(library_selector.currentIndex()) if library_selector is not None else -1,
        )
        if selector_group == "destination" and libraries:
            self._maybe_schedule_legacy_snapshot_identity_inference_retry("destination_libraries_loaded")

        return True

    def _apply_browse_modes_from_session_state(self) -> None:
        """Re-apply source/destination platform from the session shell (import / memory restore).

        Runs before site+library matching so SharePoint vs local stacks match the saved draft.
        """
        state = self._draft_shell_state if isinstance(self._draft_shell_state, SessionState) else SessionState()
        raw = self._draft_shell_raw if isinstance(self._draft_shell_raw, dict) else {}
        sm = str(getattr(state, "SourceBrowseMode", "") or raw.get("SourceBrowseMode") or "").strip().lower()
        dm = str(getattr(state, "DestinationBrowseMode", "") or raw.get("DestinationBrowseMode") or "").strip().lower()
        if sm not in ("sharepoint", "local"):
            sm = "sharepoint"
        if dm not in ("sharepoint", "local"):
            dm = "sharepoint"
        self._apply_planning_panel_platform("source", sm)
        self._apply_planning_panel_platform("destination", dm)
        log_info(
            "session_browse_modes_applied",
            source_browse_mode=sm,
            destination_browse_mode=dm,
        )

    def _verify_import_rehydration_trees(self) -> None:
        """After bundle import / reset-backup restore: if SharePoint trees stayed empty, reload library roots once."""
        if not self.current_session_context.get("connected"):
            return
        if getattr(self, "_import_tree_reload_retry_used", False):
            return
        empty_src = False
        empty_dst = False
        if self._planning_browse_mode("source") == "sharepoint":
            ss = self.planning_inputs.get("Source Site")
            sl = self.planning_inputs.get("Source Library")
            site = ss.currentData() if ss is not None else None
            lib = sl.currentData() if sl is not None else None
            if isinstance(site, dict) and isinstance(lib, dict) and str(lib.get("id", "") or "").strip():
                stw = getattr(self, "source_tree_widget", None)
                if stw is not None and self._planning_tree_top_level_count(stw) == 0:
                    empty_src = True
        if self._planning_browse_mode("destination") == "sharepoint":
            ds = self.planning_inputs.get("Destination Site")
            dl = self.planning_inputs.get("Destination Library")
            site = ds.currentData() if ds is not None else None
            lib = dl.currentData() if dl is not None else None
            if isinstance(site, dict) and isinstance(lib, dict) and str(lib.get("id", "") or "").strip():
                dtw = self._active_destination_tree_widget()
                if dtw is not None and self._planning_tree_top_level_count(dtw) == 0:
                    empty_dst = True
        if not empty_src and not empty_dst:
            return
        log_warn(
            "import_rehydration_empty_tree",
            source_empty=empty_src,
            destination_empty=empty_dst,
        )
        self._import_tree_reload_retry_used = True
        try:
            if empty_src:
                self.on_library_selector_changed("source", force=True)
            if empty_dst:
                self.on_library_selector_changed("destination", force=True)
        except Exception as exc:
            log_warn("import_rehydration_retry_failed", error=str(exc)[:400])

    def _restore_selector_matches(self):
        self._log_restore_phase("phase2_restore_selector_matches_start")
        self._selector_restore_site_retry_attempt = {"source": 0, "destination": 0}
        state = self._draft_shell_state if isinstance(self._draft_shell_state, SessionState) else SessionState()
        source_site_selector = self.planning_inputs.get("Source Site")
        destination_site_selector = self.planning_inputs.get("Destination Site")
        source_library_selector = self.planning_inputs.get("Source Library")
        destination_library_selector = self.planning_inputs.get("Destination Library")
        if self._planning_browse_mode("destination") == "sharepoint":
            self._destination_suppress_stale_visible_tree_if_needed()

        source_site_index = self._find_selector_index(
            source_site_selector,
            [state.SelectedSourceSite, state.SelectedSourceSiteKey],
            data_keys=("id", "site_key", "web_url"),
        )
        destination_site_index = self._find_selector_index(
            destination_site_selector,
            [state.SelectedDestinationSite, state.SelectedDestinationSiteKey],
            data_keys=("id", "site_key", "web_url"),
        )

        source_site_matched = self._set_selector_index_safely(source_site_selector, source_site_index)
        destination_site_matched = self._set_selector_index_safely(destination_site_selector, destination_site_index)
        self._log_restore_phase(
            "phase2_selector_match",
            source_site_matched=source_site_matched,
            source_site_index=source_site_index,
            destination_site_matched=destination_site_matched,
            destination_site_index=destination_site_index,
        )

        if source_site_matched:
            self.on_site_selector_changed("source", force=True, chain_library=False)
        preserved_dst_lib_id = str(getattr(state, "SelectedDestinationLibraryId", "") or "").strip()
        preserved_dst_lib_name = str(getattr(state, "SelectedDestinationLibrary", "") or "").strip()
        log_info(
            "destination_restore_selector_stored_library_preserved",
            stored_drive_id_suffix=preserved_dst_lib_id[-16:] if len(preserved_dst_lib_id) > 16 else preserved_dst_lib_id,
            stored_name_excerpt=preserved_dst_lib_name[:120],
        )

        if destination_site_matched:
            self.on_site_selector_changed(
                "destination",
                force=True,
                chain_library=False,
                destination_site_clear_reason="restore_rebind",
            )

        src_sp = self._planning_browse_mode("source") == "sharepoint"
        dst_sp = self._planning_browse_mode("destination") == "sharepoint"
        if src_sp and source_site_matched and self._planning_sharepoint_site_selector_resolved_for_libraries(source_site_selector):
            _raw_s = source_site_selector.currentData() if source_site_selector is not None else None
            _sid_s = str(_raw_s.get("id", ""))[:48] if isinstance(_raw_s, dict) else ""
            if _sid_s:
                log_info(
                    "selector_restore_site_context_resolved",
                    selector_group="source",
                    site_id_excerpt=_sid_s,
                )
        if dst_sp and destination_site_matched and self._planning_sharepoint_site_selector_resolved_for_libraries(destination_site_selector):
            _raw_d = destination_site_selector.currentData() if destination_site_selector is not None else None
            _sid_d = str(_raw_d.get("id", ""))[:48] if isinstance(_raw_d, dict) else ""
            if _sid_d:
                log_info(
                    "selector_restore_site_context_resolved",
                    selector_group="destination",
                    site_id_excerpt=_sid_d,
                )

        source_library_matched = False
        src_idx = -1
        src_tag = "no_session_hint"
        persisted_src_lib_id = str(getattr(state, "SelectedSourceLibraryId", "") or "").strip()

        if src_sp:
            if not source_site_matched:
                if persisted_src_lib_id:
                    log_info(
                        "source_library_restore_deferred_site_context_missing",
                        reason="source_site_selector_not_matched_yet",
                        intended_drive_suffix=persisted_src_lib_id[-16:]
                        if len(persisted_src_lib_id) > 16
                        else persisted_src_lib_id,
                    )
                    self._schedule_selector_restore_library_retry_after_site_resolved("source")
                src_idx, src_tag = -1, "deferred_source_site_not_matched"
            elif not self._planning_sharepoint_site_selector_resolved_for_libraries(source_site_selector):
                if persisted_src_lib_id:
                    log_info(
                        "source_library_restore_deferred_site_context_missing",
                        reason="source_site_dict_or_site_id_missing",
                        intended_drive_suffix=persisted_src_lib_id[-16:]
                        if len(persisted_src_lib_id) > 16
                        else persisted_src_lib_id,
                    )
                    self._schedule_selector_restore_library_retry_after_site_resolved("source")
                src_idx, src_tag = -1, "deferred_site_context"
            else:
                self._populate_library_selector_for_group("source")
                src_rows = self._planning_library_selector_item_rows(source_library_selector)
                src_idx, src_tag = library_combo_index_for_session_restore(
                    stored_drive_id=str(getattr(state, "SelectedSourceLibraryId", "") or ""),
                    stored_display_name=str(getattr(state, "SelectedSourceLibrary", "") or ""),
                    item_rows=src_rows,
                )
                if src_idx >= 0:
                    if self._set_selector_index_safely(source_library_selector, src_idx):
                        source_library_matched = True
                        log_info(
                            "source_library_restore_match_success",
                            outcome_tag=src_tag,
                            index=src_idx,
                            stored_drive_id=str(getattr(state, "SelectedSourceLibraryId", "") or ""),
                            stored_name=str(getattr(state, "SelectedSourceLibrary", "") or ""),
                            selector_item_count=len(src_rows),
                        )
                        if src_tag == "legacy_name_only":
                            log_info(
                                "source_library_restore_legacy_name_only",
                                stored_name=str(getattr(state, "SelectedSourceLibrary", "") or ""),
                                selector_item_count=len(src_rows),
                            )
                            log_info(
                                "source_library_restore_used_fallback_name_match",
                                stored_name=str(getattr(state, "SelectedSourceLibrary", "") or ""),
                            )
                elif src_tag == "no_session_hint":
                    pass
                else:
                    self._set_planning_library_selector_unresolved(
                        "source", selector=source_library_selector, outcome_tag=src_tag
                    )
                    log_info(
                        "source_library_restore_match_failed",
                        stored_name=str(getattr(state, "SelectedSourceLibrary", "") or ""),
                        stored_drive_id=str(getattr(state, "SelectedSourceLibraryId", "") or ""),
                        outcome_tag=src_tag,
                        selector_item_count=len(src_rows),
                        source_site_context=str(getattr(state, "SelectedSourceSite", "") or ""),
                    )

        if not src_sp:
            src_rows = self._planning_library_selector_item_rows(source_library_selector)
            src_idx, src_tag = library_combo_index_for_session_restore(
                stored_drive_id=str(getattr(state, "SelectedSourceLibraryId", "") or ""),
                stored_display_name=str(getattr(state, "SelectedSourceLibrary", "") or ""),
                item_rows=src_rows,
            )
            source_library_matched = False
            if src_idx >= 0:
                if self._set_selector_index_safely(source_library_selector, src_idx):
                    source_library_matched = True
                    log_info(
                        "source_library_restore_match_success",
                        outcome_tag=src_tag,
                        index=src_idx,
                        stored_drive_id=str(getattr(state, "SelectedSourceLibraryId", "") or ""),
                        stored_name=str(getattr(state, "SelectedSourceLibrary", "") or ""),
                        selector_item_count=len(src_rows),
                    )
                    if src_tag == "legacy_name_only":
                        log_info(
                            "source_library_restore_legacy_name_only",
                            stored_name=str(getattr(state, "SelectedSourceLibrary", "") or ""),
                            selector_item_count=len(src_rows),
                        )
                        log_info(
                            "source_library_restore_used_fallback_name_match",
                            stored_name=str(getattr(state, "SelectedSourceLibrary", "") or ""),
                        )
            elif src_tag == "no_session_hint":
                source_library_matched = False
            else:
                self._set_planning_library_selector_unresolved("source", selector=source_library_selector, outcome_tag=src_tag)
                log_info(
                    "source_library_restore_match_failed",
                    stored_name=str(getattr(state, "SelectedSourceLibrary", "") or ""),
                    stored_drive_id=str(getattr(state, "SelectedSourceLibraryId", "") or ""),
                    outcome_tag=src_tag,
                    selector_item_count=len(src_rows),
                    source_site_context=str(getattr(state, "SelectedSourceSite", "") or ""),
                )

        destination_library_matched = False
        dst_idx = -1
        dst_tag = "no_session_hint"

        if dst_sp:
            if not destination_site_matched:
                if preserved_dst_lib_id:
                    log_info(
                        "destination_library_restore_deferred_site_context_missing",
                        reason="destination_site_selector_not_matched_yet",
                        intended_drive_suffix=preserved_dst_lib_id[-16:]
                        if len(preserved_dst_lib_id) > 16
                        else preserved_dst_lib_id,
                    )
                    self._schedule_selector_restore_library_retry_after_site_resolved("destination")
                dst_idx, dst_tag = -1, "deferred_destination_site_not_matched"
            elif not self._planning_sharepoint_site_selector_resolved_for_libraries(destination_site_selector):
                if preserved_dst_lib_id:
                    log_info(
                        "destination_library_restore_deferred_site_context_missing",
                        reason="destination_site_dict_or_site_id_missing",
                        intended_drive_suffix=preserved_dst_lib_id[-16:]
                        if len(preserved_dst_lib_id) > 16
                        else preserved_dst_lib_id,
                    )
                    self._schedule_selector_restore_library_retry_after_site_resolved("destination")
                dst_idx, dst_tag = -1, "deferred_site_context"
            else:
                self._populate_library_selector_for_group("destination")
                dst_rows = self._planning_library_selector_item_rows(destination_library_selector)
                dst_idx, dst_tag = library_combo_index_for_session_restore(
                    stored_drive_id=preserved_dst_lib_id,
                    stored_display_name=preserved_dst_lib_name,
                    item_rows=dst_rows,
                )
                if dst_idx >= 0:
                    if self._set_selector_index_safely(destination_library_selector, dst_idx):
                        destination_library_matched = True
                        log_info(
                            "destination_restore_selector_library_match_using_preserved_values",
                            outcome_tag=dst_tag,
                            index=dst_idx,
                            stored_drive_id=preserved_dst_lib_id,
                            stored_name=preserved_dst_lib_name,
                            selector_item_count=len(dst_rows),
                        )
                        log_info(
                            "destination_library_restore_match_success",
                            outcome_tag=dst_tag,
                            index=dst_idx,
                            stored_drive_id=preserved_dst_lib_id,
                            stored_name=preserved_dst_lib_name,
                            selector_item_count=len(dst_rows),
                        )
                        if dst_tag == "legacy_name_only":
                            log_info(
                                "destination_library_restore_legacy_name_only",
                                stored_name=str(getattr(state, "SelectedDestinationLibrary", "") or ""),
                                selector_item_count=len(dst_rows),
                            )
                            log_info(
                                "destination_library_restore_used_fallback_name_match",
                                stored_name=str(getattr(state, "SelectedDestinationLibrary", "") or ""),
                            )
                elif dst_tag == "no_session_hint":
                    pass
                else:
                    self._set_planning_library_selector_unresolved(
                        "destination", selector=destination_library_selector, outcome_tag=dst_tag
                    )
                    log_info(
                        "destination_library_restore_match_failed",
                        stored_name=preserved_dst_lib_name,
                        stored_drive_id=preserved_dst_lib_id,
                        outcome_tag=dst_tag,
                        selector_item_count=len(dst_rows),
                        destination_site_context=str(getattr(state, "SelectedDestinationSite", "") or ""),
                    )

        if not dst_sp:
            dst_rows = self._planning_library_selector_item_rows(destination_library_selector)
            dst_idx, dst_tag = library_combo_index_for_session_restore(
                stored_drive_id=preserved_dst_lib_id,
                stored_display_name=preserved_dst_lib_name,
                item_rows=dst_rows,
            )
            destination_library_matched = False
            if dst_idx >= 0:
                if self._set_selector_index_safely(destination_library_selector, dst_idx):
                    destination_library_matched = True
                    log_info(
                        "destination_restore_selector_library_match_using_preserved_values",
                        outcome_tag=dst_tag,
                        index=dst_idx,
                        stored_drive_id=preserved_dst_lib_id,
                        stored_name=preserved_dst_lib_name,
                        selector_item_count=len(dst_rows),
                    )
                    log_info(
                        "destination_library_restore_match_success",
                        outcome_tag=dst_tag,
                        index=dst_idx,
                        stored_drive_id=preserved_dst_lib_id,
                        stored_name=preserved_dst_lib_name,
                        selector_item_count=len(dst_rows),
                    )
                    if dst_tag == "legacy_name_only":
                        log_info(
                            "destination_library_restore_legacy_name_only",
                            stored_name=str(getattr(state, "SelectedDestinationLibrary", "") or ""),
                            selector_item_count=len(dst_rows),
                        )
                        log_info(
                            "destination_library_restore_used_fallback_name_match",
                            stored_name=str(getattr(state, "SelectedDestinationLibrary", "") or ""),
                        )
            elif dst_tag == "no_session_hint":
                destination_library_matched = False
            else:
                self._set_planning_library_selector_unresolved(
                    "destination", selector=destination_library_selector, outcome_tag=dst_tag
                )
                log_info(
                    "destination_library_restore_match_failed",
                    stored_name=preserved_dst_lib_name,
                    stored_drive_id=preserved_dst_lib_id,
                    outcome_tag=dst_tag,
                    selector_item_count=len(dst_rows),
                    destination_site_context=str(getattr(state, "SelectedDestinationSite", "") or ""),
                )

        if self._planning_browse_mode("destination") == "sharepoint" and not destination_library_matched:
            self._destination_suppress_stale_visible_tree_if_needed()

        self._log_restore_phase(
            "phase2_library_match",
            source_library_matched=source_library_matched,
            source_library_index=src_idx,
            source_restore_tag=src_tag,
            destination_library_matched=destination_library_matched,
            destination_library_index=dst_idx,
            destination_restore_tag=dst_tag,
            selector_signals_suppressed=self._suppress_selector_change_handlers,
        )

        if source_library_matched:
            self._log_restore_phase("phase2_restore_source_library_start")
            self.on_library_selector_changed("source", force=True)
            self._log_restore_phase("phase2_restore_source_library_end")
        if destination_library_matched:
            if getattr(self, "_sharepoint_lazy_mode", False):
                self._schedule_safe_timer(
                    900,
                    "phase2_restore_destination_library_delayed",
                    self._trigger_delayed_destination_library_restore,
                )
            else:
                self._log_restore_phase("phase2_restore_destination_library_start")
                self.on_library_selector_changed("destination", force=True)
                self._log_restore_phase("phase2_restore_destination_library_end")
        self._log_restore_phase("phase2_restore_selector_matches_end")

    def _trigger_delayed_destination_library_restore(self):
        self.on_library_selector_changed("destination", force=True)

    def _startup_post_snapshot_trace_reset(self) -> None:
        self._startup_post_snapshot_trace_t0 = time.perf_counter()
        self._startup_post_snapshot_trace_prev = float(self._startup_post_snapshot_trace_t0)
        self._startup_post_snapshot_trace_seq = 0

    def _startup_post_snapshot_trace_event(self, phase: str, **extra: Any) -> None:
        """Log up to 10 phases after ``startup_snapshot_first_visible`` for startup hang diagnosis."""
        t0 = float(getattr(self, "_startup_post_snapshot_trace_t0", 0.0) or 0.0)
        if t0 <= 0.0:
            return
        seq = int(getattr(self, "_startup_post_snapshot_trace_seq", 0) or 0)
        if seq >= 10:
            return
        now = time.perf_counter()
        prev = float(getattr(self, "_startup_post_snapshot_trace_prev", t0) or t0)
        self._startup_post_snapshot_trace_seq = seq + 1
        self._startup_post_snapshot_trace_prev = now
        payload = {
            "seq": seq,
            "phase": str(phase)[:200],
            "elapsed_ms_since_first_visible": round((now - t0) * 1000.0, 2),
            "delta_ms_since_prev": round((now - prev) * 1000.0, 2),
        }
        for k, v in extra.items():
            if v is None:
                continue
            payload[str(k)[:80]] = v
        log_info("startup_post_snapshot_phase", **payload)

    def _post_login_restore_phase2_finally_body(self) -> None:
        self._suppress_selector_change_handlers = False
        self._memory_ui_rebind_in_progress = False
        # Async tree materialization continues while this flag is True; logs use
        # restore_in_progress=False so operators are not misled during long expand/projection.
        self._memory_restore_background_trees = True
        self._log_restore_state_snapshot(
            "restore_phase2_complete_waiting_for_destination_queue",
            destination_replay_invoked=False,
            draft_id=self.active_draft_session_id,
            autosave_suppressed=self._suppress_autosave,
        )
        if (self.planned_moves or self.proposed_folders) and not getattr(self, "_sharepoint_lazy_mode", False):
            self._restore_narrow_destination_future_snapshot_once = True
            self._log_restore_phase(
                "restore_narrow_destination_future_snapshot_scheduled",
                planned_moves_count=len(self.planned_moves or []),
                proposed_folders_count=len(self.proposed_folders or []),
            )
        # Defer phase-4 to keep the success dialog responsive while visible.
        self._run_after_import_success_dialog_idle(
            "phase4_destination_overlay_deferred",
            self._post_login_restore_phase4,
            delay_ms=50,
        )
        self._log_restore_phase("phase2_post_login_restore_exit")
        if self._planning_browse_mode("destination") != "local":
            self._log_restore_phase(
                "destination_restore_sharepoint_authority_contract",
                expansion_selection_overlay_after_graph_or_queued_loads=True,
                no_fabricated_visible_real_from_snapshot_bind=True,
            )

    def _post_login_restore_phase2_selectors_and_planned_moves_inner(self) -> None:
        self._startup_post_snapshot_trace_event("phase2_restore_selector_matches_enter")
        _t_sel = time.perf_counter()
        self._run_restore_phase("phase2_restore_selectors", self._restore_selector_matches)
        self._startup_post_snapshot_trace_event(
            "phase2_restore_selector_matches_exit",
            wall_ms=round((time.perf_counter() - _t_sel) * 1000.0, 2),
        )
        self._log_restore_phase("phase2_post_login_restore_after_selectors")
        self._startup_post_snapshot_trace_event("phase3_refresh_planned_moves_enter")
        _t_pm = time.perf_counter()
        self._run_restore_phase(
            "phase3_refresh_planned_moves",
            lambda: self.refresh_planned_moves_table(),
        )
        self._startup_post_snapshot_trace_event(
            "phase3_refresh_planned_moves_exit",
            wall_ms=round((time.perf_counter() - _t_pm) * 1000.0, 2),
        )
        self._log_restore_phase("phase2_post_login_restore_after_planned_moves")
        self._log_restore_state_snapshot("restore_ui_bound", destination_replay_invoked=False)

    def _post_login_restore_phase2(self):
        if not self.current_session_context.get("connected"):
            self._log_restore_phase("phase2_restore_selectors skipped", reason="session not connected")
            return

        self._log_restore_phase("phase2_post_login_restore_enter")
        self._restore_abort_mode = False
        self._restore_abort_reason = ""
        self._memory_ui_rebind_in_progress = True
        self._destination_restore_completed_once = False
        self._memory_restore_in_progress = True
        self._memory_restore_background_trees = False
        self._suppress_selector_change_handlers = True
        self._restore_finalization_deferred_active = False
        self._restore_finalization_deferred_reason = ""
        prov_applied = False
        try:
            self._apply_browse_modes_from_session_state()
            _id = self._intended_destination_drive_id_for_snapshot_validation()
            log_info(
                "destination_startup_selector_identity_ready",
                has_intended=bool(_id),
                intended_drive_suffix=_id[-16:] if len(_id) > 16 else _id,
            )
            try:
                self._post_login_restore_phase2_selectors_and_planned_moves_inner()
            finally:
                pass
            self._refresh_pending_destination_snapshot_after_selector_identity()
            prov_applied = bool(
                self._destination_apply_provisional_session_snapshot_if_eligible(phase="post_login_phase2_pre_selectors")
            )
        except Exception:
            self._post_login_restore_phase2_finally_body()
            raise

        if prov_applied:
            self._startup_post_snapshot_trace_event("phase2_deferred_tail_scheduled", defer_ms=0)

            def _deferred_tail():
                try:
                    pass
                finally:
                    self._post_login_restore_phase2_finally_body()

            QTimer.singleShot(
                0,
                lambda: self._safe_invoke("post_login_phase2_after_provisional_snapshot", _deferred_tail),
            )
        else:
            self._post_login_restore_phase2_finally_body()

    def _schedule_post_login_restore_phase4_if_pending(self) -> None:
        """Re-run phase-4 when the first invoke ran before the destination tree was ready."""
        if not getattr(self, "_memory_restore_in_progress", False):
            return
        _persisted_planning = bool(getattr(self, "planned_moves", None) or getattr(self, "proposed_folders", None))
        if not getattr(self, "_restore_destination_overlay_pending", False) and not _persisted_planning:
            return
        if self._restore_abort_active():
            return
        t0 = time.perf_counter()
        imp_t0 = getattr(self, "_import_ok_trace_import_t0", None)
        self._import_ok_trace(
            "phase4_reschedule_scheduled",
            seconds_since_import_start=round(t0 - float(imp_t0), 4) if imp_t0 is not None else None,
        )

        self._run_after_import_success_dialog_idle(
            "phase4_destination_overlay_after_destination_ui",
            self._post_login_restore_phase4,
            delay_ms=50,
        )
        self._import_ok_timing("phase4_reschedule_deferred_tick_exit", t0)

    def _post_login_restore_phase4(self):
        _ph4_t0 = time.perf_counter()
        self._import_ok_trace("post_login_restore_phase4_enter")
        self._startup_post_snapshot_trace_event("post_login_restore_phase4_enter")
        try:
            if self._restore_abort_active():
                self._log_restore_phase(
                    "phase4_destination_overlay skipped",
                    reason="restore_abort_mode",
                    restore_abort_reason=str(getattr(self, "_restore_abort_reason", "") or ""),
                )
                self._finalize_memory_restore_if_ready("phase4_skipped_restore_abort")
                return
            if self._planning_browse_mode("destination") != "local":
                self._destination_merge_planning_bootstrap_folder_paths_if_needed(phase="post_login_restore_phase4")
            _persisted_planning = bool(getattr(self, "planned_moves", None) or getattr(self, "proposed_folders", None))
            if not self._restore_destination_overlay_pending and not _persisted_planning:
                self._log_restore_phase(
                    "phase4_destination_overlay skipped",
                    reason="no_unresolved_replay_or_persisted_planning",
                )
                self._finalize_memory_restore_if_ready("phase4_no_overlay_pending")
                return

            try:
                dest_tree = getattr(self, "destination_tree_widget", None)
                destination_ready = bool(dest_tree is not None and self._planning_tree_top_level_count(dest_tree) > 0)
                if not destination_ready:
                    self._log_restore_phase(
                        "phase4_destination_overlay skipped",
                        reason="destination tree not ready",
                        top_level_count=self._planning_tree_top_level_count(dest_tree),
                    )
                    return
                if not self._destination_root_bind_is_authoritative():
                    if not getattr(self, "_destination_provisional_startup_applied", False):
                        self._restore_destination_overlay_pending = True
                        self._log_restore_phase(
                            "destination_replay_deferred_until_final_root_bind",
                            reason="destination_root_bind_not_authoritative_yet",
                            planned_moves_count=len(self.planned_moves),
                            proposed_folders_count=len(self.proposed_folders),
                            active_request_signature=self.active_root_request_signatures.get("destination"),
                            loaded_request_signature=self.loaded_root_request_signatures.get("destination"),
                        )
                        return
                    log_info(
                        "destination_phase4_overlay_on_provisional_shell",
                        reason="authoritative_graph_root_pending",
                        top_level_count=self._planning_tree_top_level_count(dest_tree),
                    )

                applied_count = 0
                if getattr(self, "_sharepoint_lazy_mode", False):
                    self._sync_restore_destination_overlay_pending_from_unresolved_queues()
                    if self.planned_moves or self.proposed_folders:
                        _eager_startup = bool(getattr(self, "_startup_destination_eager_full_memory", False))
                        applied_count += self._apply_destination_planning_overlays(
                            "phase4_destination_overlay_lazy_memory_truth",
                            allow_defer=not _eager_startup,
                            prefer_chunked_projection=not _eager_startup,
                            narrow_restore_real_snapshot=getattr(
                                self, "_restore_narrow_destination_future_snapshot_once", False
                            ),
                        )
                    self._log_restore_phase(
                        "phase4_destination_overlay skipped",
                        reason="lazy_mode_uses_restore_queue",
                        top_level_count=self._planning_tree_top_level_count(dest_tree),
                        queue_size=self._unresolved_proposed_queue_size(),
                        allocation_queue_size=self._unresolved_allocation_queue_size(),
                        memory_truth_overlay_applied_count=int(applied_count),
                    )
                    self._finalize_memory_restore_if_ready("phase4_lazy_mode_queue")
                    return
                for top_row in self._iter_destination_top_level_rows():
                    applied_count += self._apply_proposed_children_to_item(top_row)
                applied_count += self._replay_unresolved_proposed_overlay("phase4_destination_overlay")
                applied_count += self._replay_unresolved_allocation_overlay("phase4_destination_allocation_overlay")
                applied_count += self._reconcile_destination_semantic_duplicates_maybe_deferred(
                    "phase4_destination_overlay"
                )
                if not getattr(self, "_sharepoint_lazy_mode", False):
                    # Prefer chunked projection/bind during restore to avoid long UI
                    # blocking "merge/materialize" work on the main thread.
                    _eager_startup = bool(getattr(self, "_startup_destination_eager_full_memory", False))
                    applied_count += self._apply_destination_planning_overlays(
                        "phase4_destination_overlay",
                        allow_defer=not _eager_startup,
                        prefer_chunked_projection=not _eager_startup,
                        narrow_restore_real_snapshot=getattr(
                            self, "_restore_narrow_destination_future_snapshot_once", False
                        ),
                    )
                self._sync_restore_destination_overlay_pending_from_unresolved_queues()
                self._log_restore_phase(
                    "phase4_destination_overlay applied",
                    proposed_folders=len(self.proposed_folders),
                    applied_count=applied_count,
                    visible_proposed_count=self._count_visible_destination_proposed_nodes(),
                )
                self._log_restore_state_snapshot(
                    "restore_post_bind_counts",
                    destination_replay_invoked=True,
                    applied_count=applied_count,
                    visible_proposed_count=self._count_visible_destination_proposed_nodes(),
                )
            except Exception as exc:
                self._log_restore_exception("phase4_destination_overlay", exc)
            finally:
                self._finalize_memory_restore_if_ready("phase4_complete")
        finally:
            self._import_ok_timing("post_login_restore_phase4_exit", _ph4_t0)

    def _memory_restore_apply_finalize_success(self, reason: str = "") -> None:
        """Apply the normal success-path side effects of memory restore finalize."""
        self._restore_finalization_deferred_active = False
        self._restore_finalization_deferred_reason = ""
        self._graph_linkage_restore_finalize_pending_last_sig = None
        self._destination_restore_completed_once = True
        self._memory_restore_in_progress = False
        self._memory_restore_background_trees = False
        self._memory_restore_complete = True
        self._suppress_autosave = False
        self._destination_restore_session_expanded_paths_intent = set()
        self._destination_restore_session_selected_path_intent = ""
        # Stop restore-driven source expansion work once restore is finalized.
        # This prevents long-lived background source queue churn from competing
        # with user-triggered expand-all actions.
        self._source_restore_materialization_queue = []
        self._source_restore_materialization_seen = set()
        self._pending_source_navigation = None
        self._pending_destination_navigation = None
        self._prime_source_root_children_after_snapshot()
        self._prime_destination_root_children_after_snapshot()
        if getattr(self, "_restore_narrow_destination_future_snapshot_once", False):
            self._restore_narrow_destination_future_snapshot_once = False
        self._try_flush_destination_future_model_after_source_restore("memory_restore_finalize")
        self._log_restore_state_snapshot(
            "restore_final_ready",
            destination_replay_invoked=False,
            draft_id=self.active_draft_session_id,
            autosave_suppressed=self._suppress_autosave,
            finalization_reason=reason,
        )
        _fc = self._memory_restore_candidate if isinstance(self._memory_restore_candidate, dict) else {}
        log_info(
            "planning_state_snapshot",
            phase="restore_finalize",
            planned_moves_count=len(self.planned_moves),
            proposed_folders_count=len(self.proposed_folders),
            restore_candidate_name=str(_fc.get("name", "") or ""),
            finalization_reason=str(reason or ""),
        )
        # After restoring from local memory/cache snapshot, do not force-clear tree cache.
        # This keeps startup fast and avoids immediately replacing snapshot content with live root fetches.
        self._schedule_live_root_refresh("source", delay_ms=900, force_refresh=False)
        self._schedule_live_root_refresh("destination", delay_ms=1200, force_refresh=False)
        self._flush_pending_source_full_count_after_memory_restore()
        if getattr(self, "_import_rehydration_verify_pending", False):
            self._import_rehydration_verify_pending = False
            QTimer.singleShot(
                600,
                lambda: self._safe_invoke("import_rehydration_tree_verify", self._verify_import_rehydration_trees),
            )
        # Older/path-only drafts (e.g. first-generation builds) may have missed Graph id enrichment
        # because _try_resolve_planned_move_graph_ids_debounced returns while restore was still in progress.
        self._schedule_post_memory_restore_graph_id_enrichment()

    def _schedule_post_memory_restore_graph_id_enrichment(self) -> None:
        """After successful memory-restore finalize, retry resolving drive/item ids from paths when needed."""
        QTimer.singleShot(
            2000,
            lambda: self._safe_invoke(
                "post_memory_restore_graph_id_enrichment",
                self._post_memory_restore_graph_id_enrichment,
            ),
        )

    def _dismiss_planning_graph_linkage_assurance_banner(self) -> None:
        t = getattr(self, "_planning_graph_assurance_hide_timer", None)
        if isinstance(t, QTimer):
            t.stop()
            self._planning_graph_assurance_hide_timer = None
        t2 = getattr(self, "_graph_linkage_progress_success_hide_timer", None)
        if isinstance(t2, QTimer):
            t2.stop()
        self._graph_linkage_progress_success_hide_timer = None
        b = getattr(self, "planning_graph_assurance_banner", None)
        if b is not None:
            b.hide()
        cr = getattr(self, "planning_graph_linkage_compact_row", None)
        if cr is not None:
            cr.hide()
        ps = getattr(self, "planning_graph_linkage_progress_strip", None)
        if ps is not None:
            ps.hide()
        self._graph_linkage_progress_session_arm = False
        self._graph_linkage_ui_mode = "idle"
        if getattr(self, "_planning_header_restore_collapsed_after_banner", None):
            self._apply_planning_header_collapsed_state(True)
        self._planning_header_restore_collapsed_after_banner = None
        self._graph_linkage_strip_user_suppressed = True

    def _dismiss_graph_linkage_progress_strip_user(self) -> None:
        """User dismiss for the determinate Graph strip only (session-local hide).

        Hides: progress strip, auto-hide timer. Does not: change planned moves, Graph ids, negative cache,
        or ``ensure_planned_moves_resolved_via_graph`` / session arm state — resolution keeps running.

        Reappear: next ``_graph_linkage_progress_session_begin`` (new import/post-restore/debounce linkage pass)
        clears suppression so the strip may show again if work remains.
        """
        self._graph_linkage_strip_user_suppressed = True
        t2 = getattr(self, "_graph_linkage_progress_success_hide_timer", None)
        if isinstance(t2, QTimer):
            t2.stop()
        self._graph_linkage_progress_success_hide_timer = None
        ps = getattr(self, "planning_graph_linkage_progress_strip", None)
        if ps is not None:
            ps.hide()
        if getattr(self, "_graph_linkage_ui_mode", "") == "strip":
            self._graph_linkage_ui_mode = "idle"
        log_info(
            "graph_linkage_strip_user_dismissed",
            progress_session_id=int(getattr(self, "_graph_linkage_progress_session_id", 0) or 0),
            session_armed=bool(getattr(self, "_graph_linkage_progress_session_arm", False)),
        )

    def _show_planning_graph_linkage_assurance_banner(self, *, title: str, detail: str) -> None:
        """Visible confirmation after post-restore Microsoft Graph linkage checks (upgrade / legacy drafts)."""
        if getattr(self, "planning_graph_assurance_title", None) is None:
            return
        as_banner = getattr(self, "planning_graph_assurance_banner", None)
        if as_banner is not None and not as_banner.isVisible():
            self._planning_header_restore_collapsed_after_banner = bool(
                getattr(self, "_planning_header_collapsed", False)
            )
        if getattr(self, "_planning_header_collapsed", False):
            self._apply_planning_header_collapsed_state(False)
        cr = getattr(self, "planning_graph_linkage_compact_row", None)
        if cr is not None:
            cr.hide()
        ps = getattr(self, "planning_graph_linkage_progress_strip", None)
        if ps is not None:
            ps.hide()
        self.planning_graph_assurance_title.show()
        self.planning_graph_assurance_detail.show()
        self.planning_graph_assurance_title.setText(title)
        self.planning_graph_assurance_detail.setText(detail)
        self.planning_graph_assurance_banner.show()
        status = self.statusBar()
        if status is not None:
            status.showMessage(detail.replace("\n", " ")[:400], 50000)
        t = getattr(self, "_planning_graph_assurance_hide_timer", None)
        if isinstance(t, QTimer):
            t.stop()
        self._planning_graph_assurance_hide_timer = QTimer(self)
        self._planning_graph_assurance_hide_timer.setSingleShot(True)
        self._planning_graph_assurance_hide_timer.timeout.connect(self._dismiss_planning_graph_linkage_assurance_banner)
        self._planning_graph_assurance_hide_timer.start(120000)

    def _post_memory_restore_graph_id_enrichment(self) -> None:
        audit = self._audit_planned_moves_graph_destination_identity()
        log_info("graph_linkage_audit", phase="post_memory_restore", **self._graph_linkage_audit_for_log(audit))

        if not self.current_session_context.get("connected"):
            log_info("graph_linkage_enrich_skipped", reason="not_connected")
            self._apply_graph_linkage_banner_from_audit(audit, phase="post_memory_restore_disconnected")
            return

        if self._restore_abort_active():
            log_info("graph_linkage_enrich_skipped", reason="restore_abort")
            self._apply_graph_linkage_banner_from_audit(audit, phase="post_memory_restore_abort")
            return

        if self._memory_restore_foreground_phase_busy():
            n = int(getattr(self, "_graph_linkage_enrich_busy_skips", 0) or 0)
            if n < 15:
                self._graph_linkage_enrich_busy_skips = n + 1
                log_info(
                    "graph_linkage_enrich_deferred",
                    reason="memory_restore_foreground_busy",
                    attempt=n + 1,
                    **self._graph_linkage_audit_for_log(audit),
                )
                QTimer.singleShot(
                    2000,
                    lambda: self._safe_invoke(
                        "post_memory_restore_graph_id_enrichment_busy",
                        self._post_memory_restore_graph_id_enrichment,
                    ),
                )
            else:
                log_warn(
                    "graph_linkage_enrich_gave_up",
                    reason="memory_restore_foreground_busy_stale",
                    **self._graph_linkage_audit_for_log(audit),
                )
                self._apply_graph_linkage_banner_from_audit(audit, phase="post_memory_restore_still_busy")
            return
        self._graph_linkage_enrich_busy_skips = 0

        if not self.planned_moves and not self.proposed_folders:
            log_info(
                "graph_linkage_enrich_skipped",
                reason="empty_workspace",
                **self._graph_linkage_audit_for_log(audit),
            )
            self._apply_graph_linkage_banner_from_audit(audit, phase="post_memory_restore_empty")
            return

        _will_enrich = (
            bool(self.current_session_context.get("connected"))
            and bool(self._graph_resolve_planning_context())
            and (
                int(audit.get("rows_missing_graph_ids") or 0) + int(audit.get("proposed_rows_missing_graph_ids") or 0)
                > 0
            )
        )

        self._apply_graph_linkage_banner_from_audit(audit, phase="post_memory_restore_pre_resolve")

        if audit.get("rows_missing_graph_ids", 0) == 0 and audit.get("proposed_rows_missing_graph_ids", 0) == 0:
            log_info(
                "post_memory_restore_graph_id_enrichment",
                event="skipped_already_linked",
                planned_moves=len(self.planned_moves or []),
                proposed_folders=len(self.proposed_folders or []),
                **self._graph_linkage_audit_for_log(audit),
            )
            self._graph_linkage_context_retry_count = 0
            return

        if not self._graph_resolve_planning_context():
            log_info(
                "graph_linkage_enrich_deferred",
                reason="no_planning_context",
                retry_count=self._graph_linkage_context_retry_count,
                **self._graph_linkage_audit_for_log(audit),
            )
            self._apply_graph_linkage_banner_from_audit(audit, phase="post_memory_restore_no_context")
            self._schedule_graph_linkage_context_retry()
            return

        self._graph_linkage_context_retry_count = 0
        log_info(
            "post_memory_restore_graph_id_enrichment",
            event="starting",
            planned_moves=len(self.planned_moves or []),
            proposed_folders=len(self.proposed_folders or []),
            **self._graph_linkage_audit_for_log(audit),
        )
        try:
            if _will_enrich:
                self._graph_linkage_progress_session_begin()
            move_rows_updated, proposed_updated = self.ensure_planned_moves_resolved_via_graph(
                persist=True, quiet=True, refresh_sources=True
            )
            audit_after = self._audit_planned_moves_graph_destination_identity()
            log_info(
                "graph_linkage_audit",
                phase="post_memory_restore_post_resolve",
                move_rows_updated=int(move_rows_updated or 0),
                proposed_rows_updated=int(proposed_updated or 0),
                **self._graph_linkage_audit_for_log(audit_after),
            )
            self._apply_graph_linkage_banner_from_audit(audit_after, phase="post_memory_restore_post_resolve")
            if (
                audit_after.get("rows_missing_graph_ids", 0) == 0
                and audit_after.get("proposed_rows_missing_graph_ids", 0) == 0
                and (move_rows_updated or proposed_updated)
            ):
                self._show_planning_graph_linkage_assurance_banner(
                    title="Microsoft 365 linkage updated",
                    detail=(
                        f"Graph metadata was refreshed for this draft: {move_rows_updated} planned move row(s) "
                        f"and {proposed_updated} proposed folder(s). Changes are saved."
                    ),
                )
        except Exception as exc:
            log_warn("post_memory_restore_graph_id_enrichment_failed", error=str(exc))
            audit_err = self._audit_planned_moves_graph_destination_identity()
            log_info(
                "graph_linkage_audit",
                phase="post_memory_restore_resolve_failed",
                **self._graph_linkage_audit_for_log(audit_err),
            )
            self._apply_graph_linkage_banner_from_audit(audit_err, phase="post_memory_restore_resolve_failed")
            if (
                audit_err.get("rows_missing_graph_ids", 0) == 0
                and audit_err.get("proposed_rows_missing_graph_ids", 0) == 0
            ):
                self._show_planning_graph_linkage_assurance_banner(
                    title="Microsoft 365 linkage",
                    detail=(
                        "Automatic Graph ID refresh did not complete. You can still plan; before submitting, "
                        f"ensure you are online or try Refresh. Detail: {str(exc)[:200]}"
                    ),
                )

    def _finalize_memory_restore_if_ready(self, reason=""):
        if self._restore_abort_active():
            self._destination_restore_completed_once = False
            self._memory_restore_in_progress = False
            self._memory_restore_background_trees = False
            self._destination_restore_session_expanded_paths_intent = set()
            self._destination_restore_session_selected_path_intent = ""
            self._full_count_pending_drive_id_after_restore = ""
            loaded_items = (
                self.count_tree_items(self.source_tree_widget) if hasattr(self, "source_tree_widget") else 0
            )
            self._update_source_count_labels(loaded_items)
            self._memory_restore_complete = False
            self._suppress_autosave = True
            self._log_restore_phase(
                "restore_finalization_skipped",
                reason=reason,
                stop_reason="restore_abort_mode",
                restore_abort_reason=str(getattr(self, "_restore_abort_reason", "") or ""),
            )
            return False
        unresolved_count = self._unresolved_proposed_queue_size() + self._unresolved_allocation_queue_size()
        destination_queue_size = len(getattr(self, "_destination_restore_materialization_queue", []) or [])
        pending_destination_root_load = 1 if self.root_load_workers.get("destination") else 0
        pending_destination_folder_loads = bool(self.pending_folder_loads.get("destination"))
        root_prime_pending = bool(getattr(self, "_destination_root_prime_pending", False))
        # Overlay pending can remain True after unresolved queues drain (e.g. phase4 set it earlier);
        # if there is no destination work left, clear it so restore can finalize and Reset Draft can run.
        if (
            not unresolved_count
            and not destination_queue_size
            and not pending_destination_root_load
            and not pending_destination_folder_loads
            and not root_prime_pending
            and getattr(self, "_restore_destination_overlay_pending", False)
        ):
            self._restore_destination_overlay_pending = False
            self._log_restore_phase(
                "restore_destination_overlay_pending_cleared_no_outstanding_work",
                finalize_reason=reason,
            )
            unresolved_count = self._unresolved_proposed_queue_size() + self._unresolved_allocation_queue_size()
            destination_queue_size = len(getattr(self, "_destination_restore_materialization_queue", []) or [])
            pending_destination_root_load = 1 if self.root_load_workers.get("destination") else 0
            pending_destination_folder_loads = bool(self.pending_folder_loads.get("destination"))
            root_prime_pending = bool(getattr(self, "_destination_root_prime_pending", False))
        destination_busy = bool(
            unresolved_count
            or destination_queue_size
            or getattr(self, "_restore_destination_overlay_pending", False)
            or root_prime_pending
            or pending_destination_folder_loads
            or pending_destination_root_load
        )
        if destination_busy:
            if not getattr(self, "_restore_finalization_deferred_active", False):
                self._restore_finalization_deferred_active = True
                self._restore_finalization_deferred_reason = str(reason or "")
                self._log_restore_phase(
                    "restore_finalization_deferred_start",
                    reason=reason,
                    unresolved_count=unresolved_count,
                    destination_queue_size=destination_queue_size,
                    overlay_pending=bool(getattr(self, "_restore_destination_overlay_pending", False)),
                    root_prime_pending=bool(getattr(self, "_destination_root_prime_pending", False)),
                    pending_destination_folder_loads=len(self.pending_folder_loads.get("destination", set())),
                    pending_destination_root_loads=pending_destination_root_load,
                )
                QTimer.singleShot(
                    4000,
                    lambda: self._safe_invoke(
                        "graph_linkage_audit_restore_finalize_pending",
                        self._maybe_publish_graph_linkage_audit_if_restore_finalize_still_deferred,
                    ),
                )
            return False
        if getattr(self, "_restore_finalization_deferred_active", False):
            self._log_restore_phase(
                "restore_finalization_deferred_resolved",
                start_reason=self._restore_finalization_deferred_reason,
                resolve_reason=reason,
                unresolved_count=unresolved_count,
                destination_queue_size=destination_queue_size,
                pending_destination_folder_loads=len(self.pending_folder_loads.get("destination", set())),
                pending_destination_root_loads=pending_destination_root_load,
            )
            self._restore_finalization_deferred_active = False
            self._restore_finalization_deferred_reason = ""
        if not self._memory_restore_in_progress and self._memory_restore_complete and not self._suppress_autosave:
            return True
        self._memory_restore_apply_finalize_success(reason)
        return True

    def _schedule_live_root_refresh(self, panel_key, delay_ms=1200, site=None, library=None, force_refresh=True):
        if panel_key not in {"source", "destination"}:
            return
        if self._live_root_refresh_scheduled.get(panel_key):
            return
        if getattr(self, "_memory_restore_in_progress", False):
            return
        if panel_key == "source":
            site_selector = self.planning_inputs.get("Source Site")
            library_selector = self.planning_inputs.get("Source Library")
        else:
            site_selector = self.planning_inputs.get("Destination Site")
            library_selector = self.planning_inputs.get("Destination Library")
        selected_site = site if isinstance(site, dict) else (site_selector.currentData() if site_selector is not None else None)
        selected_library = library if isinstance(library, dict) else (library_selector.currentData() if library_selector is not None else None)
        if not isinstance(selected_site, dict) or not isinstance(selected_library, dict):
            return
        drive_id = str(selected_library.get("id", "")).strip()
        if not drive_id:
            return
        self._live_root_refresh_scheduled[panel_key] = True
        self._live_root_refresh_request_signature[panel_key] = self._build_root_request_signature(panel_key, selected_site, selected_library)
        self._live_root_refresh_ui_state[panel_key] = self._capture_workspace_tree_state()

        def _run():
            self._live_root_refresh_scheduled[panel_key] = False
            if getattr(self, "_memory_restore_in_progress", False):
                self._schedule_live_root_refresh(panel_key, delay_ms=delay_ms, site=selected_site, library=selected_library)
                return
            if panel_key == "destination" and self._destination_live_refresh_blocked_for_restore_ux():
                self._schedule_live_root_refresh(panel_key, delay_ms=max(500, int(delay_ms)), site=selected_site, library=selected_library)
                return
            current_site = site_selector.currentData() if site_selector is not None else None
            current_library = library_selector.currentData() if library_selector is not None else None
            current_signature = self._build_root_request_signature(panel_key, current_site or {}, current_library or {})
            if current_signature != self._live_root_refresh_request_signature.get(panel_key, ""):
                self._live_root_refresh_request_signature[panel_key] = ""
                self._live_root_refresh_ui_state[panel_key] = None
                return
            if (
                not bool(force_refresh)
                and current_signature == self.loaded_root_request_signatures.get(panel_key)
                and self._tree_has_bound_root_content(panel_key)
            ):
                self._live_root_refresh_request_signature[panel_key] = ""
                self._live_root_refresh_ui_state[panel_key] = None
                return
            self.load_library_root(panel_key, current_site, current_library, force_refresh=bool(force_refresh))

        QTimer.singleShot(max(0, int(delay_ms)), _run)

    def _run_drive_delta_sync_best_effort(self, drive_id: str):
        drive_id = str(drive_id or "").strip()
        if not drive_id or not getattr(self, "graph", None):
            return
        if self._restore_abort_active() or getattr(self, "_memory_restore_in_progress", False):
            self._log_restore_phase(
                "drive_delta_sync_skipped",
                drive_id_suffix=drive_id[-16:] if len(drive_id) > 16 else drive_id,
                reason="restore_busy_or_abort",
            )
            return
        if not self._graph_settings_delta_sync_enabled():
            log_trace(
                "drive_delta_sync",
                "skipped_settings_disabled",
                drive_id_suffix=drive_id[-16:] if len(drive_id) > 16 else drive_id,
            )
            return
        workers = self._drive_delta_workers
        existing = workers.get(drive_id)
        if existing is not None and existing.isRunning():
            return
        allow_bootstrap = self._graph_settings_delta_bootstrap_allowed()
        worker = DriveDeltaSyncWorker(
            self.graph,
            drive_id,
            allow_initial_bootstrap=allow_bootstrap,
        )
        workers[drive_id] = worker

        def _cleanup():
            if self._drive_delta_workers.get(drive_id) is worker:
                self._drive_delta_workers.pop(drive_id, None)

        worker.finished.connect(_cleanup)
        worker.success.connect(
            lambda payload, d=drive_id: self._safe_invoke(
                "drive_delta.success",
                self._on_drive_delta_sync_success,
                payload,
                d,
            )
        )
        worker.error.connect(
            lambda msg, d=drive_id: self._safe_invoke(
                "drive_delta.error",
                self._on_drive_delta_sync_error,
                msg,
                d,
            )
        )
        worker.start()

    def _on_drive_delta_sync_success(self, payload: dict, drive_id: str):
        _dsuf = drive_id[-16:] if len(drive_id) > 16 else drive_id
        log_destination_graph_delta_lifecycle("destination_graph_delta_started", drive_id_suffix=_dsuf)
        if self._restore_abort_active():
            self._log_restore_phase(
                "drive_delta_sync_success_ignored",
                drive_id_suffix=_dsuf,
                reason="restore_abort_mode",
            )
            return
        if payload.get("skipped"):
            log_trace(
                "drive_delta_sync",
                "skipped",
                drive_id_suffix=_dsuf,
                reason=payload.get("reason", ""),
            )
            return
        log_info(
            "drive_delta_sync_completed",
            drive_id_suffix=_dsuf,
            pages=int(payload.get("pages") or 0),
            invalidated_folders=int(payload.get("invalidated_folders") or 0),
            initial_token_run=bool(payload.get("initial_token_run")),
        )
        inv = int(payload.get("invalidated_folders") or 0)
        initial = bool(payload.get("initial_token_run"))
        items_seen = int(payload.get("items_seen") or 0)
        entries = payload.get("invalidated_entries") or []
        dest_did = str(
            self.pending_root_drive_ids.get("destination")
            or self._current_selected_destination_drive_id()
            or ""
        ).strip()

        if inv <= 0:
            log_destination_graph_delta_lifecycle(
                "destination_graph_delta_no_change",
                drive_id_suffix=_dsuf,
                changed_items=items_seen,
                invalidated_folders=0,
            )
        else:
            log_destination_graph_delta_lifecycle(
                "destination_graph_delta_items_changed",
                drive_id_suffix=_dsuf,
                changed_items=items_seen,
                invalidated_folders=inv,
            )

        expanded_reloads = 0
        if isinstance(entries, list) and inv > 0:
            for row in entries:
                if isinstance(row, dict) and str(row.get("drive_id") or "").strip() == drive_id:
                    log_destination_graph_delta_lifecycle(
                        "destination_graph_delta_branch_updated",
                        drive_id_suffix=_dsuf,
                        invalidated_item_id_suffix=str(row.get("item_id") or "")[-16:],
                    )
            expanded_reloads = int(self._apply_graph_delta_to_visible_trees(drive_id, entries) or 0)
            if dest_did and str(drive_id).strip() == dest_did:
                self._detect_runtime_live_memory_duplicate_conflicts_after_graph_delta(drive_id, entries)
                self._destination_try_scoped_planning_overlay_after_delta(drive_id, entries)

        log_destination_graph_delta_lifecycle(
            "destination_graph_delta_completed",
            drive_id_suffix=_dsuf,
            invalidated_folders=inv,
            expanded_branch_reload_count=expanded_reloads,
        )
        log_destination_graph_delta_lifecycle(
            "destination_graph_delta_cursor_saved",
            drive_id_suffix=_dsuf,
            delta_cursor_present=destination_graph_delta_cursor_present(getattr(self, "graph", None), drive_id),
            initial_token_run=initial,
        )

        # Delta-first: do not run full-tree enumeration after a successful delta; Graph cache invalidation + branch reloads suffice.
        if inv > 0 and dest_did and str(drive_id).strip() == dest_did:
            should_schedule_destination_full_tree(
                reason="post_graph_delta_success_routine_followup_would_have_run",
                drive_id=drive_id,
                routine_followup=True,
                delta_cursor_present=destination_graph_delta_cursor_present(getattr(self, "graph", None), drive_id),
                bootstrap_complete=bool(
                    self._destination_full_tree_ready()
                    and str(getattr(self, "_destination_full_tree_completed_drive_id", "") or "").strip() == drive_id
                ),
            )

        status = getattr(self, "planned_moves_status", None)
        if status is not None:
            if initial:
                status.setText(
                    "Incremental SharePoint sync is ready. Later updates only refresh folders that changed remotely."
                )
            elif inv > 0:
                status.setText(
                    f"SharePoint cache updated ({inv} folder branch(es)). Expanded folders reload when needed."
                )

    def _on_drive_delta_sync_error(self, message: str, drive_id: str):
        _dsuf = drive_id[-16:] if len(drive_id) > 16 else drive_id
        log_warn(
            "drive_delta_sync_failed",
            drive_id_suffix=_dsuf,
            error=str(message)[:500],
        )
        did = str(drive_id or "").strip()
        if did:
            QTimer.singleShot(
                0,
                lambda d=did: self._safe_invoke(
                    "destination_full_tree_after_delta_sync_error",
                    lambda: self._ensure_sharepoint_destination_full_tree_worker_scheduled(
                        d,
                        schedule_reason="drive_delta_sync_error_fallback",
                        delta_failed=True,
                        recovery=True,
                    ),
                ),
            )
        status = getattr(self, "planned_moves_status", None)
        if status is not None:
            status.setText(
                "Incremental SharePoint sync failed (cache still works; use Refresh Cache if needed)."
            )

    def _apply_graph_delta_to_visible_trees(self, drive_id: str, entries: list) -> int:
        """Mark affected folders stale and reload expanded Graph-backed branches so the UI matches cache invalidation.

        Returns the number of expanded branch reload kicks applied (destination + source panels).
        """
        ids = set()
        for row in entries:
            if not isinstance(row, dict):
                continue
            if str(row.get("drive_id") or "").strip() != drive_id:
                continue
            iid = str(row.get("item_id") or "").strip()
            if iid:
                ids.add(iid)
        if not ids:
            return 0
        expanded_reloads = 0
        for panel_key in ("source", "destination"):
            tree = self.source_tree_widget if panel_key == "source" else self.destination_tree_widget
            if tree is None:
                continue
            for top in self._iter_panel_top_level_rows(panel_key):
                for item in self._iter_tree_items(top):
                    node_data = self.get_tree_item_node_data(item) or {}
                    if node_data.get("placeholder"):
                        continue
                    item_id = str(node_data.get("id") or "").strip()
                    if item_id not in ids:
                        continue
                    resolved_drive = self._resolve_tree_item_drive_id(panel_key, node_data)
                    if resolved_drive != drive_id:
                        continue
                    if panel_key == "destination" and self.node_is_planned_allocation(node_data):
                        node_data["children_loaded"] = False
                        self.set_tree_item_node_data(item, node_data)
                        continue
                    node_data["children_loaded"] = False
                    node_data["load_failed"] = False
                    self.set_tree_item_node_data(item, node_data)
                    tree_panel = self.source_tree_widget if panel_key == "source" else self.destination_tree_widget
                    if isinstance(item, QModelIndex):
                        if tree_panel is not None and bool(tree_panel.isExpanded(item)):
                            self._ensure_tree_item_load_started(panel_key, item)
                            expanded_reloads += 1
                    else:
                        if item.isExpanded():
                            self.on_tree_item_expanded(panel_key, item)
                            expanded_reloads += 1
        return expanded_reloads

    def _destination_delta_entry_item_ids(self, drive_id: str, entries: list) -> list[str]:
        out: list[str] = []
        for row in entries or []:
            if not isinstance(row, dict):
                continue
            if str(row.get("drive_id") or "").strip() != drive_id:
                continue
            iid = str(row.get("item_id") or "").strip()
            if iid:
                out.append(iid)
        return out

    def _destination_live_path_meta_for_delta_item_ids(self, drive_id: str, item_ids: list[str]) -> dict[str, dict[str, Any]]:
        """Resolve Graph item ids to library-relative canonical paths without scanning the whole tree."""
        out: dict[str, dict[str, Any]] = {}
        if not item_ids:
            return out
        model = getattr(self, "destination_planning_model", None)
        graph = getattr(self, "graph", None)
        for iid in item_ids[:128]:
            if model is not None:
                try:
                    ix = model.find_index_by_drive_item(drive_id, iid)
                except Exception:
                    ix = QModelIndex()
                if ix is not None and ix.isValid():
                    pl = ix.data(Qt.UserRole) or {}
                    if not isinstance(pl, dict):
                        pl = {}
                    canon = self._destination_row_semantic_path(pl)
                    canon = self._canonical_destination_projection_path(canon) or self.normalize_memory_path(canon)
                    key = normalize_path_key(canon)
                    if not key:
                        continue
                    is_file = not bool(pl.get("is_folder", True))
                    out[key] = {
                        "path": canon,
                        "id": iid,
                        "name": str(pl.get("name") or ""),
                        "type": "file" if is_file else "folder",
                        "webUrl": str(pl.get("webUrl") or pl.get("web_url") or ""),
                        "branch": canon,
                    }
                    continue
            if graph is None:
                continue
            raw_item = graph.get_drive_item_optional(drive_id, iid)
            if not isinstance(raw_item, dict):
                continue
            ip = graph_item_path_to_raw_windows_path(GraphClient.build_item_path(raw_item))
            canon = self._canonical_destination_projection_path(ip) or self.normalize_memory_path(ip)
            key = normalize_path_key(canon)
            if not key:
                continue
            is_file = bool(raw_item.get("file"))
            out[key] = {
                "path": canon,
                "id": iid,
                "name": str(raw_item.get("name") or ""),
                "type": "file" if is_file else "folder",
                "webUrl": str(raw_item.get("webUrl") or ""),
                "branch": canon,
            }
        return out

    def _destination_memory_paths_for_live_conflict_detection(self) -> tuple[list[str], list[str], list[str]]:
        proposed: list[str] = []
        for raw in self.proposed_folders or []:
            if isinstance(raw, dict):
                try:
                    folder = ProposedFolder.from_dict(raw)
                except Exception:
                    continue
            elif isinstance(raw, ProposedFolder):
                folder = raw
            else:
                continue
            if proposed_folder_accepts_existing_live_folder(folder):
                continue
            p = self._canonical_destination_projection_path(getattr(folder, "DestinationPath", "") or "")
            if p:
                proposed.append(p)
        planned: list[str] = []
        alloc_targets: list[str] = []
        for move in self.planned_moves or []:
            if not isinstance(move, dict):
                continue
            proj = self._canonical_destination_projection_path(self._allocation_projection_path(move))
            if proj:
                planned.append(proj)
            raw_t = str(move.get("destination_path", "") or "").strip()
            ap = self._canonical_destination_projection_path(raw_t)
            if ap:
                alloc_targets.append(ap)
        return proposed, planned, alloc_targets

    def _destination_try_scoped_planning_overlay_after_delta(self, drive_id: str, entries: list) -> None:
        """Apply planning overlays only for Graph delta branches that intersect planning (no broad global overlay)."""
        item_ids = self._destination_delta_entry_item_ids(drive_id, entries)
        live_by_key = self._destination_live_path_meta_for_delta_item_ids(drive_id, item_ids)
        scope_keys = {normalize_path_key(str(m.get("path") or "")) for m in live_by_key.values()}
        scope_keys.discard("")
        if not scope_keys:
            log_info(
                "destination_overlay_delta_scope_noop",
                drive_id_suffix=drive_id[-16:] if len(drive_id) > 16 else drive_id,
                reason="no_resolved_paths_for_delta_items",
            )
            return
        proposed, planned, alloc_targets = self._destination_memory_paths_for_live_conflict_detection()
        hit = 0
        for lst in (proposed, planned, alloc_targets):
            for p in lst:
                if normalize_path_key(p) in scope_keys:
                    hit += 1
                    break
        if hit == 0:
            log_info(
                "destination_overlay_scoped_apply_skipped",
                drive_id_suffix=drive_id[-16:] if len(drive_id) > 16 else drive_id,
                reason="planning_paths_do_not_intersect_delta_scope",
                scope_path_sample=sorted({m.get("path") for m in list(live_by_key.values())[:8] if m.get("path")}),
            )
            log_info(
                "destination_overlay_delta_scope_noop",
                drive_id_suffix=drive_id[-16:] if len(drive_id) > 16 else drive_id,
                reason="planning_paths_do_not_intersect_delta_scope",
                scope_path_sample=sorted({m.get("path") for m in list(live_by_key.values())[:8] if m.get("path")}),
            )
            return
        log_info(
            "destination_overlay_scoped_to_delta_branch",
            drive_id_suffix=drive_id[-16:] if len(drive_id) > 16 else drive_id,
            intersected_planning_rows=hit,
            delta_scope_path_sample=sorted({m.get("path") for m in list(live_by_key.values())[:12] if m.get("path")}),
        )
        scope_paths = build_delta_overlay_scope_paths(
            live_meta_by_key=dict(live_by_key),
            proposed_paths=proposed,
            planned_paths=planned,
            allocation_paths=alloc_targets,
            normalize=lambda p: str(
                self._canonical_destination_projection_path(str(p or "").strip()) or self.normalize_memory_path(str(p or "").strip())
            ).strip(),
        )
        if not scope_paths:
            log_info(
                "destination_overlay_delta_scope_noop",
                drive_id_suffix=drive_id[-16:] if len(drive_id) > 16 else drive_id,
                reason="scoped_overlay_path_set_empty",
            )
            log_info(
                "destination_overlay_scoped_apply_skipped",
                drive_id_suffix=drive_id[-16:] if len(drive_id) > 16 else drive_id,
                reason="empty_scope_paths",
            )
            return
        log_info(
            "destination_overlay_scoped_apply_started",
            drive_id_suffix=drive_id[-16:] if len(drive_id) > 16 else drive_id,
            scope_path_count=len(scope_paths),
            scope_path_sample=sorted(list(scope_paths))[:16],
        )
        prev_drf = set(getattr(self, "_destination_drfws_affected_paths", None) or set())
        applied = 0
        try:
            self._destination_drfws_affected_paths = set(prev_drf) | set(scope_paths)
            applied = int(
                self._destination_materialize_with_optional_overlay_scope(
                    "local_first_edit_graph_delta_scoped",
                    allow_defer=True,
                    prefer_chunked_projection=True,
                    narrow_restore_real_snapshot=False,
                    scope_paths=set(scope_paths),
                )
                or 0
            )
        except Exception as exc:
            log_info(
                "destination_overlay_scoped_apply_failed",
                drive_id_suffix=drive_id[-16:] if len(drive_id) > 16 else drive_id,
                error=str(exc)[:400],
            )
            return
        finally:
            self._destination_drfws_affected_paths = set(prev_drf)
        log_info(
            "destination_overlay_scoped_apply_completed",
            drive_id_suffix=drive_id[-16:] if len(drive_id) > 16 else drive_id,
            overlay_applied_rows=int(applied),
            scope_path_count=len(scope_paths),
        )

    def _detect_runtime_live_memory_duplicate_conflicts_after_graph_delta(self, drive_id: str, entries: list) -> None:
        active = str(
            self.pending_root_drive_ids.get("destination")
            or self._current_selected_destination_drive_id()
            or ""
        ).strip()
        if not active or str(drive_id).strip().casefold() != active.casefold():
            return
        item_ids = self._destination_delta_entry_item_ids(drive_id, entries)
        live_by_key = self._destination_live_path_meta_for_delta_item_ids(drive_id, item_ids)
        proposed, planned, alloc_targets = self._destination_memory_paths_for_live_conflict_detection()
        recs = detect_conflicts_for_live_paths(
            live_path_by_key=dict(live_by_key),
            proposed_destination_paths=proposed,
            planned_destination_paths=planned,
            allocation_targets=alloc_targets,
        )
        if not recs:
            return
        log_info(
            "destination_live_memory_duplicate_detected",
            drive_id_suffix=drive_id[-16:] if len(drive_id) > 16 else drive_id,
            conflict_count=len(recs),
            live_paths_resolved=len(live_by_key),
            delta_items=len(item_ids),
        )
        for rec in recs:
            log_info(
                "destination_planned_path_conflicts_with_live_graph",
                subtype=rec.subtype,
                memory_path=rec.planned_or_proposed_path,
                live_path=rec.live_graph_path,
            )
            if rec.subtype == "live_duplicate_proposed_folder":
                log_info(
                    "destination_proposed_folder_conflicts_with_live_graph",
                    memory_path=rec.planned_or_proposed_path,
                    live_path=rec.live_graph_path,
                )
        merged = merge_unique(recs, list(getattr(self, "_runtime_live_memory_conflict_rows", None) or []))
        self._runtime_live_memory_conflict_rows = merged
        log_info(
            "destination_live_memory_duplicate_review_item_created",
            count=len(recs),
            total_runtime_rows=len(merged),
            drive_id_suffix=drive_id[-16:] if len(drive_id) > 16 else drive_id,
        )
        self._refresh_workflow_state_on_demand()

    def _destination_live_refresh_still_blocked(self):
        mem = bool(getattr(self, "_memory_restore_in_progress", False))
        if mem and self._destination_graph_authority_supersedes_memory_restore_gate():
            mem = False
        if mem:
            return True
        if getattr(self, "_destination_incremental_merge_in_progress", False):
            return True
        if getattr(self, "_restore_destination_overlay_pending", False):
            return True
        if self._unresolved_proposed_queue_size() > 0 or self._unresolved_allocation_queue_size() > 0:
            return True
        if bool(getattr(self, "_destination_restore_materialization_queue", []) or []):
            return True
        if bool(getattr(self, "_destination_idle_materialize_pending_reason", "")):
            return True
        timer = getattr(self, "_destination_idle_materialize_timer", None)
        if timer is not None and timer.isActive():
            return True
        return False

    def _destination_live_refresh_blocked_for_restore_ux(self) -> bool:
        """Same as :meth:`_destination_live_refresh_still_blocked` but never during the SharePoint authority shell.

        Restore/snapshot branch refresh must not show “Restoring projections…” or defer live root refresh
        while the tree is still the non-authoritative placeholder; authority bind is not gated by this flag.
        """
        if self._planning_browse_mode("destination") != "local" and self._destination_tree_shows_authority_pending_shell():
            return False
        return self._destination_live_refresh_still_blocked()

    def _destination_restore_branch_refresh_paused_for_authority(self) -> bool:
        """Do not walk saved expanded paths until real destination rows exist (not placeholder shell)."""
        if self._planning_browse_mode("destination") == "local":
            return False
        if getattr(self, "destination_planning_model", None) is None:
            return False
        return bool(self._destination_tree_shows_authority_pending_shell())

    def _destination_clear_restore_blockers_after_authoritative_bind(self, bind_kind: str) -> None:
        """Drop stale destination-restore deferrals that deadlocked against the authority shell."""
        q = getattr(self, "_destination_restore_materialization_queue", None) or []
        _t0 = getattr(self, "_destination_idle_materialize_timer", None)
        self._log_restore_phase(
            "restore_blocking_flags_cleared_on_authority_bind",
            bind_kind=str(bind_kind or "")[:80],
            had_destination_restore_queue=bool(q),
            idle_materialize_reason_excerpt=str(getattr(self, "_destination_idle_materialize_pending_reason", "") or "")[:120],
            idle_timer_active=bool(_t0 is not None and _t0.isActive()),
        )
        self._destination_restore_materialization_queue = []
        self._destination_restore_materialization_seen = set()
        self._destination_idle_materialize_pending_reason = ""
        if _t0 is not None:
            try:
                if _t0.isActive():
                    _t0.stop()
            except Exception:
                pass
        try:
            self._sync_restore_destination_overlay_pending_from_unresolved_queues()
        except Exception:
            pass
        self._destination_try_clear_stale_foreground_memory_restore_gate(
            f"clear_restore_blockers_after_authoritative_bind:{str(bind_kind or '')[:80]}"
        )

    def _destination_resume_snapshot_branch_refresh_after_authority(self) -> None:
        dest_pending = self._pending_snapshot_branch_refresh.get("destination") if isinstance(
            getattr(self, "_pending_snapshot_branch_refresh", None), dict
        ) else None
        if isinstance(dest_pending, set) and dest_pending:
            self._log_restore_phase(
                "restore_pipeline_resumed_after_authority",
                pending_path_count=len(dest_pending),
            )
            self._schedule_snapshot_branch_refresh("destination", delay_ms=0)
        else:
            self._log_restore_phase("restore_pipeline_resumed_after_authority", pending_path_count=0)

    def _schedule_post_login_restore(self):
        self._log_restore_phase(
            "schedule_post_login_restore",
            connected=self.current_session_context.get("connected", False),
            planned_moves=len(self.planned_moves),
            proposed_folders=len(self.proposed_folders),
        )
        # Run phase-2 restore immediately to avoid occasional QTimer starvation
        # windows that make startup appear hung.
        self._safe_invoke("phase2_post_login_restore_immediate", self._post_login_restore_phase2)

    def _apply_restored_selector_state(self):
        self._begin_session_workspace_ui_restore()
        self._schedule_post_login_restore()

    def _session_workspace_ui_state(self):
        state = self._draft_shell_state if isinstance(self._draft_shell_state, SessionState) else SessionState()
        return {
            "source_expanded_paths": set(getattr(state, "SourceExpandedPaths", []) or []),
            "destination_expanded_paths": set(getattr(state, "DestinationExpandedPaths", []) or []),
            "source_selected_path": str(getattr(state, "SourceSelectedPath", "") or ""),
            "destination_selected_path": str(getattr(state, "DestinationSelectedPath", "") or ""),
            "source_expanded_all": bool(getattr(state, "SourceExpandedAll", False)),
            "destination_expanded_all": bool(getattr(state, "DestinationExpandedAll", False)),
            "planning_header_collapsed": bool(getattr(state, "PlanningHeaderCollapsed", False)),
            "workspace_panel_collapsed": bool(getattr(state, "WorkspacePanelCollapsed", False)),
        }

    def _session_workspace_tree_snapshots(self):
        state = self._draft_shell_state if isinstance(self._draft_shell_state, SessionState) else SessionState()
        return {
            "source": list(getattr(state, "SourceTreeSnapshot", []) or []),
            "destination": list(getattr(state, "DestinationTreeSnapshot", []) or []),
        }

    def _destination_clear_stale_snapshot_state_on_library_change(
        self,
        *,
        selected_site: dict | None,
        selected_library: dict | None,
    ) -> None:
        """Clear runtime/pending destination snapshots when the picker library no longer matches mounted memory."""
        if self._planning_browse_mode("destination") == "local":
            return
        new_drive = str((selected_library or {}).get("id") or "").strip()
        if not new_drive:
            return
        prev = str(getattr(self, "_destination_last_bound_library_drive_id", "") or "").strip()
        mount = str(getattr(self, "_destination_snapshot_mount_drive_id", "") or "").strip()
        rs = getattr(self, "_runtime_session_tree_snapshots", None)
        has_runtime = bool(isinstance(rs, dict) and list(rs.get("destination") or []))
        pend = getattr(self, "_pending_session_tree_snapshots", None)
        has_pend = bool(isinstance(pend, dict) and list(pend.get("destination") or []))
        prov = bool(getattr(self, "_destination_provisional_startup_applied", False))

        library_changed = bool(prev and new_drive and prev.casefold() != new_drive.casefold())
        mount_mismatch = bool(
            mount and new_drive and mount.casefold() != new_drive.casefold() and (has_runtime or has_pend or prov)
        )
        need_clear = bool(library_changed or mount_mismatch)

        shell = getattr(self, "_draft_shell_state", None)
        if isinstance(shell, SessionState):
            shell.SelectedDestinationLibraryId = new_drive
            shell.SelectedDestinationLibrary = str((selected_library or {}).get("name") or "")
            if isinstance(selected_site, dict):
                shell.SelectedDestinationSite = str(selected_site.get("name") or "")
                shell.SelectedDestinationSiteKey = str(
                    selected_site.get("site_key") or selected_site.get("web_url") or selected_site.get("id") or ""
                ).strip()

        if need_clear:
            log_info(
                "destination_library_change_cleared_stale_snapshot",
                previous_drive_suffix=prev[-16:] if len(prev) > 16 else prev,
                new_drive_suffix=new_drive[-16:] if len(new_drive) > 16 else new_drive,
                mount_drive_suffix=mount[-16:] if len(mount) > 16 else mount,
                had_runtime_snapshot=has_runtime,
                had_pending_snapshot=has_pend,
                library_changed=bool(library_changed),
                mount_mismatch=bool(mount_mismatch),
            )
            if isinstance(rs, dict):
                rs["destination"] = []
            if isinstance(pend, dict):
                pend["destination"] = []
                self._pending_session_tree_snapshots = pend
            self._destination_provisional_startup_applied = False
            self._startup_visible_snapshot_bound = False
            self._destination_startup_snapshot_mount_seen = False
            try:
                self._startup_memory_visible_tree_ready_mono = 0.0
            except Exception:
                pass
            model = getattr(self, "destination_planning_model", None)
            if model is not None:
                try:
                    model.clear()
                except Exception:
                    pass
            if isinstance(shell, SessionState):
                shell.DestinationTreeSnapshotIdentityDriveId = ""
                shell.DestinationTreeSnapshotIdentityLibraryId = ""
                shell.DestinationTreeSnapshotIdentityLibraryName = ""
                shell.DestinationTreeSnapshotIdentitySiteId = ""
                shell.DestinationTreeSnapshotIdentityInferredFromLegacy = False
            self._destination_snap_preserving_disabled_due_to_identity_change = True
            self._destination_strict_planning_identity_required = True
        else:
            log_info(
                "destination_library_change_snapshot_identity_verified",
                drive_suffix=new_drive[-16:] if len(new_drive) > 16 else new_drive,
                had_previous=bool(prev),
            )

        self._destination_last_bound_library_drive_id = new_drive

    def _destination_clear_stale_snapshot_state_on_site_change(
        self,
        *,
        selected_site: dict | None,
        previous_site_id: str,
        new_site_id: str,
        reason: str = "user_site_change",
    ) -> None:
        """Clear destination runtime memory when the destination site identity changes (before library validity).

        ``reason``:
        - ``user_site_change``: full unbind (planning lists, strict identity) for a real user site change.
        - ``restore_rebind``: clear stale snapshot/model/bind flags only; keep planned_moves/proposed_folders
          and do not erase persisted selector library fields needed by :meth:`_restore_selector_matches`.
        """
        if self._planning_browse_mode("destination") == "local":
            return
        rs = getattr(self, "_runtime_session_tree_snapshots", None)
        if isinstance(rs, dict):
            rs["destination"] = []
        pend = getattr(self, "_pending_session_tree_snapshots", None)
        if isinstance(pend, dict):
            pend["destination"] = []
            self._pending_session_tree_snapshots = pend
        self._destination_provisional_startup_applied = False
        self._startup_visible_snapshot_bound = False
        self._destination_startup_snapshot_mount_seen = False
        try:
            self._startup_memory_visible_tree_ready_mono = 0.0
        except Exception:
            pass
        self._destination_suppress_provisional_placeholder_preservation = True
        self._destination_snapshot_mount_drive_id = ""
        prd = getattr(self, "pending_root_drive_ids", None)
        if isinstance(prd, dict):
            prd["destination"] = ""
        prs = getattr(self, "pending_root_site_ids", None)
        if isinstance(prs, dict):
            prs["destination"] = ""
        self._destination_last_bound_library_drive_id = ""

        model = getattr(self, "destination_planning_model", None)
        if model is not None:
            try:
                model.clear()
            except Exception:
                pass

        prior_pm = len(self.planned_moves) if getattr(self, "planned_moves", None) else 0
        prior_pf = len(self.proposed_folders) if getattr(self, "proposed_folders", None) else 0
        if reason == "user_site_change" and (prior_pm or prior_pf):
            self.planned_moves = []
            self.proposed_folders = []
            self._allow_empty_planning_persist = True
            self._planning_memory_clear_reason = "user_confirmed_destination_site_change_unbind"
            try:
                self.refresh_planned_moves_table()
            except Exception:
                pass

        shell = getattr(self, "_draft_shell_state", None)
        if isinstance(shell, SessionState):
            shell.DestinationTreeSnapshotIdentityDriveId = ""
            shell.DestinationTreeSnapshotIdentityLibraryId = ""
            shell.DestinationTreeSnapshotIdentityLibraryName = ""
            shell.DestinationTreeSnapshotIdentitySiteId = ""
            shell.DestinationTreeSnapshotIdentityInferredFromLegacy = False
            if isinstance(selected_site, dict):
                shell.SelectedDestinationSite = str(selected_site.get("name") or "")
                shell.SelectedDestinationSiteKey = str(
                    selected_site.get("site_key") or selected_site.get("web_url") or selected_site.get("id") or ""
                ).strip()
            else:
                shell.SelectedDestinationSite = ""
                shell.SelectedDestinationSiteKey = ""

        log_info(
            "destination_site_change_cleared_stale_snapshot",
            previous_site_suffix=previous_site_id[-16:] if len(previous_site_id) > 16 else previous_site_id,
            new_site_suffix=new_site_id[-16:] if len(new_site_id) > 16 else new_site_id,
            reason=str(reason or "user_site_change")[:40],
        )
        if reason == "user_site_change":
            if prior_pm or prior_pf:
                log_info(
                    "destination_site_change_planning_memory_cleared",
                    prior_planned_count=int(prior_pm),
                    prior_proposed_count=int(prior_pf),
                )
            else:
                log_info(
                    "destination_site_change_planning_memory_cleared",
                    prior_planned_count=0,
                    prior_proposed_count=0,
                )
        else:
            log_info(
                "destination_site_change_planning_memory_preserved",
                reason=str(reason or "")[:40],
                prior_planned_count=int(prior_pm),
                prior_proposed_count=int(prior_pf),
            )
        self._destination_snap_preserving_disabled_due_to_identity_change = True
        if reason == "user_site_change":
            self._destination_strict_planning_identity_required = True

    def _select_destination_tree_snapshot_for_startup(
        self,
        session_destination_snaps: list,
        *,
        workspace_sidecar: dict | None,
    ) -> tuple[list, str, int, int, dict]:
        """Choose session vs workspace sidecar destination snapshot after root validation (validity > richness)."""

        state = self._draft_shell_state if isinstance(self._draft_shell_state, SessionState) else SessionState()
        combo_did = str(self._current_selected_destination_drive_id() or "").strip()
        snap_id_drive = str(getattr(state, "DestinationTreeSnapshotIdentityDriveId", "") or "").strip()
        selected_session_drive = str(getattr(state, "SelectedDestinationLibraryId", "") or "").strip()
        if combo_did:
            intended = combo_did
            source_of_intended = "current_combo_drive_id"
        elif selected_session_drive:
            intended = selected_session_drive
            source_of_intended = "selected_session_drive_id"
        elif snap_id_drive:
            intended = snap_id_drive
            source_of_intended = "snapshot_identity_cold_load_fallback"
        else:
            intended = ""
            source_of_intended = "none"

        combo_site = str(self._current_selected_destination_site_id() or "").strip()
        sess_site_key = str(getattr(state, "SelectedDestinationSiteKey", "") or "").strip()
        snap_site = str(getattr(state, "DestinationTreeSnapshotIdentitySiteId", "") or "").strip()
        if combo_site:
            intended_site = combo_site
        elif sess_site_key:
            intended_site = sess_site_key
        elif snap_site:
            intended_site = snap_site
        else:
            intended_site = ""

        log_info(
            "destination_snapshot_intended_drive_resolved",
            current_combo_drive_id=combo_did,
            selected_session_drive_id=selected_session_drive,
            snapshot_identity_drive_id=snap_id_drive,
            final_intended_drive_id=str(intended or "")[:120],
            source_of_intended_drive_id=str(source_of_intended)[:80],
            intended_site_id_suffix=intended_site[-16:] if len(intended_site) > 16 else intended_site,
        )

        sess_drive = str(getattr(state, "DestinationTreeSnapshotIdentityDriveId", "") or "").strip()
        sess_lib = str(getattr(state, "DestinationTreeSnapshotIdentityLibraryId", "") or "").strip()
        if not sess_drive and not sess_lib:
            sess_drive = sess_lib = str(getattr(state, "SelectedDestinationLibraryId", "") or "").strip()
        if not sess_drive and not sess_lib:
            sess_drive = sess_lib = combo_did
        sess_site_env = str(getattr(state, "DestinationTreeSnapshotIdentitySiteId", "") or "").strip()
        sidecar_d = ""
        sidecar_lib = ""
        sidecar_site = ""
        if isinstance(workspace_sidecar, dict):
            ident = workspace_sidecar.get("destination_tree_snapshot_identity")
            if isinstance(ident, dict):
                sidecar_d = str(ident.get("drive_id") or ident.get("library_id") or "").strip()
                sidecar_lib = str(ident.get("library_id") or ident.get("drive_id") or "").strip() or sidecar_d
                sidecar_site = str(ident.get("site_id") or "").strip()
        side_list: list = []
        if isinstance(workspace_sidecar, dict):
            raw = workspace_sidecar.get("destination_tree_snapshot")
            if isinstance(raw, list):
                side_list = list(raw)
        ctx = self._destination_startup_snapshot_root_context()
        legacy_cands = self._destination_legacy_snapshot_library_candidates()
        chosen, label, _n_sess_san, _n_side_san, meta = select_validated_destination_startup_snapshot(
            list(session_destination_snaps or []),
            side_list,
            ctx,
            session_envelope_drive_id=sess_drive,
            session_envelope_library_id=sess_lib,
            session_envelope_site_id=sess_site_env,
            sidecar_envelope_drive_id=sidecar_d,
            sidecar_envelope_library_id=sidecar_lib,
            sidecar_envelope_site_id=sidecar_site,
            intended_drive_id=intended,
            intended_site_id=intended_site,
            legacy_library_candidates=legacy_cands or None,
        )
        self._apply_destination_snapshot_legacy_identity_stamp(meta)
        self._last_destination_snapshot_selection_meta = meta
        n_sess = int(meta.get("session_raw_nodes", 0) or 0)
        n_side = int(meta.get("sidecar_raw_nodes", 0) or 0)
        return chosen, str(label), n_sess, n_side, meta

    def _refresh_pending_destination_snapshot_after_selector_identity(self) -> None:
        """Re-select destination snapshot using authoritative selector drive id (post phase2 selectors)."""
        try:
            tree_snapshots = self._session_workspace_tree_snapshots()
            dest_snaps_session = list(tree_snapshots.get("destination", []) or [])
            mm = getattr(self, "memory_manager", None)
            sidecar = mm.read_workspace_snapshot_optional() if mm is not None else None
            dest_snaps, sel_src, _, _, _meta = self._select_destination_tree_snapshot_for_startup(
                dest_snaps_session,
                workspace_sidecar=sidecar,
            )
            pending = dict(self._pending_session_tree_snapshots or {})
            pending["destination"] = list(dest_snaps)
            self._pending_session_tree_snapshots = pending
            rs = getattr(self, "_runtime_session_tree_snapshots", None)
            if isinstance(rs, dict):
                rs["destination"] = list(dest_snaps)
            try:
                self._destination_startup_allowed_semantic_root_segments_cf = allowed_semantic_root_segments_cf_from_snapshot(
                    dest_snaps
                )
            except Exception:
                self._destination_startup_allowed_semantic_root_segments_cf = set()
            log_info(
                "destination_startup_snapshot_applied_after_selector_identity_resolved",
                selected_source=str(sel_src)[:120],
                top_level_roots=len(dest_snaps),
            )
        except Exception as exc:
            self._log_restore_exception("refresh_pending_destination_snapshot_after_selector_identity", exc)

    def _runtime_tree_snapshot_for_panel(self, panel_key):
        snapshots = getattr(self, "_runtime_session_tree_snapshots", {}) or {}
        return list(snapshots.get(panel_key, []) or [])

    def _destination_branch_forensic_enabled(self) -> bool:
        return str(os.environ.get("OZLINK_DEST_BRANCH_FORENSIC", "") or "").strip().lower() in (
            "1",
            "true",
            "yes",
            "on",
        )

    def _destination_branch_forensic_targets(self) -> list[str]:
        raw = str(
            os.environ.get(
                "OZLINK_DEST_BRANCH_FORENSIC_TARGETS",
                "Pictures [Allocated];Contractor Resumes [Allocated]",
            )
            or ""
        ).strip()
        if not raw:
            return []
        return [x.strip() for x in raw.split(";") if str(x or "").strip()]

    def _destination_branch_forensic_match_payload(self, payload: dict, targets_cf: list[str]) -> bool:
        if not isinstance(payload, dict) or not targets_cf:
            return False
        texts = [
            str(payload.get("base_display_label") or ""),
            str(payload.get("name") or ""),
            str(payload.get("item_path") or ""),
            str(payload.get("display_path") or ""),
            str(payload.get("destination_path") or ""),
        ]
        cands = [t.casefold() for t in texts if t]
        if not cands:
            return False
        for t in targets_cf:
            if any(t in c for c in cands):
                return True
            if t.endswith("[allocated]"):
                bare = t[: -len("[allocated]")].strip()
                if bare and any(bare in c for c in cands):
                    return True
        return False

    def _destination_branch_forensic_collect_model(self) -> list[dict[str, Any]]:
        dm = getattr(self, "destination_planning_model", None)
        if dm is None:
            return []
        targets_cf = [x.casefold() for x in self._destination_branch_forensic_targets() if x]
        if not targets_cf:
            return []
        out: list[dict[str, Any]] = []
        root = QModelIndex()
        stack = [root]
        while stack:
            parent = stack.pop()
            rc = dm.rowCount(parent)
            for r in range(rc):
                ix = dm.index(r, 0, parent)
                if not ix.isValid():
                    continue
                pl = dict(ix.data(Qt.UserRole) or {})
                stack.append(ix)
                if pl.get("placeholder") or not bool(pl.get("is_folder", False)):
                    continue
                if not self._destination_branch_forensic_match_payload(pl, targets_cf):
                    continue
                branch_path = self._canonical_destination_projection_path(
                    self._tree_item_path(pl) or pl.get("destination_path") or pl.get("display_path") or ""
                ) or self.normalize_memory_path(
                    self._tree_item_path(pl) or pl.get("destination_path") or pl.get("display_path") or ""
                )
                child_paths: list[str] = []
                crc = dm.rowCount(ix)
                for cr in range(crc):
                    cix = dm.index(cr, 0, ix)
                    if not cix.isValid():
                        continue
                    cd = dict(cix.data(Qt.UserRole) or {})
                    if cd.get("placeholder"):
                        continue
                    cp = self._canonical_destination_projection_path(
                        self._tree_item_path(cd) or cd.get("destination_path") or cd.get("display_path") or ""
                    ) or self.normalize_memory_path(
                        self._tree_item_path(cd) or cd.get("destination_path") or cd.get("display_path") or ""
                    )
                    if cp:
                        child_paths.append(cp)
                out.append(
                    {
                        "branch_path": str(branch_path or "")[:500],
                        "branch_label": str(pl.get("base_display_label") or pl.get("name") or "")[:220],
                        "child_count": len(child_paths),
                        "child_paths": sorted(set(child_paths)),
                    }
                )
        return out

    def _destination_branch_forensic_collect_snapshot(self, snapshots: list[dict]) -> list[dict[str, Any]]:
        targets_cf = [x.casefold() for x in self._destination_branch_forensic_targets() if x]
        if not targets_cf:
            return []
        out: list[dict[str, Any]] = []

        def _walk(node):
            if not isinstance(node, dict):
                return
            data = dict(node.get("data") or {})
            if self._destination_branch_forensic_match_payload(data, targets_cf):
                branch_path = self._canonical_destination_projection_path(
                    data.get("item_path") or data.get("destination_path") or data.get("display_path") or ""
                ) or self.normalize_memory_path(
                    data.get("item_path") or data.get("destination_path") or data.get("display_path") or ""
                )
                child_paths: list[str] = []
                for ch in list(node.get("children") or []):
                    cd = dict((ch or {}).get("data") or {})
                    if cd.get("placeholder"):
                        continue
                    cp = self._canonical_destination_projection_path(
                        cd.get("item_path") or cd.get("destination_path") or cd.get("display_path") or ""
                    ) or self.normalize_memory_path(
                        cd.get("item_path") or cd.get("destination_path") or cd.get("display_path") or ""
                    )
                    if cp:
                        child_paths.append(cp)
                out.append(
                    {
                        "branch_path": str(branch_path or "")[:500],
                        "branch_label": str(data.get("base_display_label") or data.get("name") or "")[:220],
                        "child_count": len(child_paths),
                        "child_paths": sorted(set(child_paths)),
                    }
                )
            for ch in list(node.get("children") or []):
                _walk(ch)

        for root in list(snapshots or []):
            _walk(root)
        return out

    def _destination_branch_forensic_read_persisted_session_snapshot(self) -> list[dict]:
        mm = getattr(self, "memory_manager", None)
        if mm is None:
            return []
        p = (getattr(mm, "paths", {}) or {}).get("session")
        if p is None:
            return []
        try:
            raw = json.loads(Path(p).read_text(encoding="utf-8"))
        except Exception:
            return []
        return list((raw or {}).get("DestinationTreeSnapshot") or [])

    def _destination_branch_forensic_log(self, stage: str, *, snapshots: list[dict] | None = None) -> None:
        if not self._destination_branch_forensic_enabled():
            return
        try:
            model_rows = self._destination_branch_forensic_collect_model()
        except Exception:
            model_rows = []
        snap_rows = []
        if snapshots is not None:
            try:
                snap_rows = self._destination_branch_forensic_collect_snapshot(list(snapshots or []))
            except Exception:
                snap_rows = []
        log_info(
            "destination_branch_forensic",
            stage=str(stage)[:80],
            target_branches=self._destination_branch_forensic_targets(),
            model_match_count=len(model_rows),
            snapshot_match_count=len(snap_rows),
            model_rows=model_rows,
            snapshot_rows=snap_rows,
        )

    def _count_tree_snapshot_nodes(self, snapshots):
        count = 0

        def _walk(snapshot_node):
            nonlocal count
            if not isinstance(snapshot_node, dict):
                return
            count += 1
            for child_snapshot in list(snapshot_node.get("children", []) or []):
                _walk(child_snapshot)

        for snapshot in list(snapshots or []):
            _walk(snapshot)
        return count

    def _count_destination_model_non_placeholder_nodes(self) -> int:
        """All non-placeholder rows in the destination planning model (matches snapshot node cardinality)."""
        model = getattr(self, "destination_planning_model", None)
        if model is None or not hasattr(model, "iter_depth_first"):
            return 0
        n = 0
        for ix in model.iter_depth_first():
            pl = ix.data(Qt.UserRole) or {}
            if pl.get("placeholder"):
                continue
            n += 1
        return n

    def _destination_forensic_destination_model_counts(self) -> dict:
        """Iter-depth vs non-placeholder counts (snapshot mount uses non-placeholder)."""
        model = getattr(self, "destination_planning_model", None)
        if model is None or not hasattr(model, "iter_depth_first"):
            return {"model_nodes_iter_depth_first": 0, "model_nodes_non_placeholder": 0}
        n_iter = 0
        n_np = 0
        for ix in model.iter_depth_first():
            n_iter += 1
            pl = ix.data(Qt.UserRole) or {}
            if not pl.get("placeholder"):
                n_np += 1
        return {"model_nodes_iter_depth_first": n_iter, "model_nodes_non_placeholder": n_np}

    def _destination_rich_reference_snapshot_node_count_baseline(self) -> int:
        """Max of workspace-sidecar, selected startup snapshot, and last overlay audit row count (persist guard)."""
        try:
            a = int(getattr(self, "_destination_workspace_sidecar_destination_node_count_at_startup", 0) or 0)
        except Exception:
            a = 0
        try:
            b = int(getattr(self, "_destination_final_startup_destination_snapshot_node_count", 0) or 0)
        except Exception:
            b = 0
        try:
            c = int(getattr(self, "_destination_last_overlay_audit_total_rows", 0) or 0)
        except Exception:
            c = 0
        return int(max(a, b, c, 0))

    def _destination_should_block_thin_destination_snapshot_over_rich_sidecar(
        self, proposed_recursive_nodes: int
    ) -> tuple[bool, str]:
        """Block persisting a thin destination snapshot over a richer WorkspaceSnapshot during startup."""
        if getattr(self, "_application_shutting_down", False):
            return False, ""
        baseline = self._destination_rich_reference_snapshot_node_count_baseline()
        if baseline < 40:
            return False, ""
        if bool(getattr(self, "_destination_destination_snapshot_persist_startup_unlocked", False)):
            return False, ""
        try:
            prop = int(proposed_recursive_nodes)
        except Exception:
            prop = -1
        if prop < 0:
            return False, ""
        if bool(getattr(self, "_destination_snapshot_overlay_pipeline_in_progress", False)):
            if prop < baseline:
                return True, "overlay_pipeline_in_progress"
        if (
            getattr(self, "_destination_startup_snapshot_mount_seen", False)
            and not bool(getattr(self, "_destination_startup_overlay_snapshot_persist_ready", False))
            and baseline >= 80
            and prop < max(int(baseline * 0.55), baseline - 80)
        ):
            return True, "startup_overlay_snapshot_persist_gate_not_ready"
        if prop >= max(int(baseline * 0.42), baseline - 120):
            return False, ""
        if prop >= max(120, int(baseline * 0.22)):
            return False, ""
        return True, "thin_capture_below_rich_baseline_during_startup_hydration"

    def _destination_count_snapshot_substantive_child_nodes(self, node: dict) -> int:
        """All non-placeholder snapshot rows under node (recursive)."""
        n = 0
        for ch in list((node or {}).get("children") or []):
            if not isinstance(ch, dict):
                continue
            d0 = ch.get("data")
            if isinstance(d0, dict) and d0.get("placeholder"):
                continue
            n += 1
            n += self._destination_count_snapshot_substantive_child_nodes(ch)
        return n

    def _destination_count_snapshot_direct_substantive_children(self, node: dict) -> int:
        n = 0
        for ch in list((node or {}).get("children") or []):
            if not isinstance(ch, dict):
                continue
            d0 = ch.get("data")
            if isinstance(d0, dict) and d0.get("placeholder"):
                continue
            n += 1
        return n

    def _destination_snapshot_walk_applied_allocations_inconsistent(self, node: dict) -> int:
        """Count nodes that claim ``allocation_descendants_applied`` but have no substantive children in JSON."""
        n = 0
        if not isinstance(node, dict):
            return 0
        d = node.get("data")
        if isinstance(d, dict) and bool(d.get("allocation_descendants_applied")) and bool(d.get("is_folder", True)):
            subs = int(self._destination_count_snapshot_direct_substantive_children(node))
            if subs <= 0:
                n += 1
        for ch in list(node.get("children") or []):
            if isinstance(ch, dict):
                n += int(self._destination_snapshot_walk_applied_allocations_inconsistent(ch))
        return n

    def _destination_snapshot_has_applied_planned_allocations_with_empty_subtrees(
        self, roots_list: list, *, log_event: bool = True
    ) -> int:
        """Count snapshot nodes that claim ``allocation_descendants_applied`` but have no substantive children."""
        n_bad = 0
        for r in roots_list or []:
            if not isinstance(r, dict):
                continue
            n_bad += int(self._destination_snapshot_walk_applied_allocations_inconsistent(r))
        if n_bad and log_event:
            log_info(
                "destination_snapshot_persist_blocked_missing_applied_descendants",
                inconsistent_applied_folders_apx=int(n_bad),
            )
        return int(n_bad)

    def _destination_thin_planned_memory_over_rich_reference(self, proposed_recursive_nodes: int) -> bool:
        if not self._destination_memory_overlay_mode_enabled():
            return False
        baseline = self._destination_rich_reference_snapshot_node_count_baseline()
        if baseline < 120 or proposed_recursive_nodes < 0:
            return False
        if int(proposed_recursive_nodes) < max(60, int(baseline * 0.45)):
            log_info(
                "destination_snapshot_persist_blocked_thin_planned_memory",
                proposed_nodes=int(proposed_recursive_nodes),
                reference_baseline=int(baseline),
            )
            return True
        return False

    def _destination_selected_destination_library_id_key(self) -> str:
        s = str(getattr(self, "_draft_shell_state", None) and getattr(self._draft_shell_state, "SelectedDestinationLibraryId", "") or "")
        if s.strip():
            return s.strip().casefold()
        for sel, role in (("Destination Library", "destination"),):
            cmb = self.planning_inputs.get(sel) if hasattr(self, "planning_inputs") else None
            d = cmb.currentData() if cmb is not None else None
            if isinstance(d, dict) and str(d.get("id") or "").strip():
                return str(d.get("id") or "").strip().casefold()
        return ""

    def _destination_snapshot_data_lib_key(self, d: dict) -> str:
        if not isinstance(d, dict) or not d:
            return ""
        for k in (
            "library_id",
            "DestinationLibraryId",
            "destination_library_id",
        ):
            v = str(d.get(k) or "").strip()
            if v:
                return v.casefold()
        return ""

    def _destination_snapshot_data_planned_allocationish(self, d: dict) -> bool:
        if not isinstance(d, dict) or not d or d.get("placeholder"):
            return False
        o = str(d.get("node_origin", "") or "").lower()
        ov = str(d.get("overlay_state", "") or "").lower()
        return bool(
            d.get("planned_allocation")
            or o == "plannedallocation"
            or ov == "plannedallocation"
            or d.get("planned_allocation_descendant")
        )

    def _destination_extract_branch_snapshot_path(self, d: dict) -> str:
        if not isinstance(d, dict):
            return ""
        row_path = str(self._tree_item_path(d) or d.get("item_path") or d.get("destination_path") or d.get("display_path") or "")
        return str(
            self._canonical_planned_memory_path_for_graph_match(row_path) or self.normalize_memory_path(row_path) or ""
        ).strip()

    def _destination_branch_stats_for_snapshot_node(self, node: dict) -> dict[str, int | bool]:
        out: dict[str, int | bool] = {
            "descendants": 0,
            "direct": 0,
            "hollow_applied": False,
        }
        if not isinstance(node, dict):
            return out
        d0 = node.get("data")
        if isinstance(d0, dict) and d0.get("is_folder", True) and bool(d0.get("allocation_descendants_applied")):
            dsub = int(self._destination_count_snapshot_direct_substantive_children(node))
            if dsub <= 0:
                out["hollow_applied"] = True
        out["descendants"] = int(self._destination_count_snapshot_substantive_child_nodes(node))
        out["direct"] = int(self._destination_count_snapshot_direct_substantive_children(node))
        return out

    def _destination_compare_branch_snapshot_richness(
        self, a: dict[str, int | bool] | None, b: dict[str, int | bool] | None
    ) -> int:
        if not a or not b:
            return 0
        da, ddir, ha = int(a.get("descendants", 0)), int(a.get("direct", 0)), bool(a.get("hollow_applied"))
        db, dird, hb = int(b.get("descendants", 0)), int(b.get("direct", 0)), bool(b.get("hollow_applied"))
        if (da, ddir, 0 if ha else 1) > (db, dird, 0 if hb else 1):
            return 1
        if (db, dird, 0 if hb else 1) > (da, ddir, 0 if ha else 1):
            return -1
        return 0

    def _destination_should_preserve_richer_branch_payload(
        self,
        cur: dict,
        other: dict | None,
    ) -> bool:
        if not isinstance(cur, dict) or not other or not isinstance(other, dict):
            return False
        sa = self._destination_branch_stats_for_snapshot_node(cur)
        sb = self._destination_branch_stats_for_snapshot_node(other)
        return int(self._destination_compare_branch_snapshot_richness(sb, sa)) > 0

    def _destination_branch_library_key_compatible(self, lib_key: str, d: dict) -> bool:
        if not str(lib_key or "").strip():
            return True
        g = self._destination_snapshot_data_lib_key(d)
        if not str(g or "").strip():
            return True
        return g == str(lib_key).casefold()

    def _destination_bounded_history_snapshot_source_lists(
        self,
    ) -> list[tuple[str, list]]:
        out: list[tuple[str, list]] = []
        mm = getattr(self, "memory_manager", None)
        if mm is None:
            return out
        try:
            pth = (mm.paths or {}).get("session")
            if pth and Path(str(pth)).is_file():
                raw = json.loads(Path(str(pth)).read_text(encoding="utf-8", errors="ignore"))
                if isinstance(raw, dict):
                    dtn = raw.get("DestinationTreeSnapshot") or []
                    if isinstance(dtn, list) and dtn:
                        out.append(("session_json", dtn))
        except Exception:
            pass
        try:
            for folder, tag in ((getattr(mm, "quarantine", None), "quarantine"), (getattr(mm, "backups", None), "backups")):
                if folder is None or not Path(str(folder)).is_dir():
                    continue
                n_sc = 0
                for p in Path(str(folder)).glob("*.json"):
                    n_sc += 1
                    if n_sc > 8:
                        break
                    if p.name in ("MemoryManifest.json",) or p.stat().st_size > 1_500_000:
                        continue
                    try:
                        raw2 = json.loads(p.read_text(encoding="utf-8", errors="ignore"))
                    except Exception:
                        continue
                    dtn2 = None
                    if isinstance(raw2, dict):
                        dtn2 = raw2.get("DestinationTreeSnapshot") or raw2.get("destination_tree_snapshot")
                    if isinstance(dtn2, list) and dtn2 and len(dtn2) > 0:
                        out.append((f"{tag}/{p.name[:32]}", dtn2))
        except Exception:
            pass
        return out

    def _destination_enrich_persisted_destination_tree_snapshot(
        self,
        current_roots: list,
        *,
        existing_session_roots: list | None,
        runtime_session_roots: list | None,
        prior_workspace_roots: list | None,
        history_sources: list[tuple[str, list]] | None = None,
        phase: str = "",
    ) -> list:
        cur = copy.deepcopy(list(current_roots or []))
        lib_key = self._destination_selected_destination_library_id_key()
        cands: list[tuple[str, list]] = [
            ("existing_session", list(existing_session_roots or [])),
            ("runtime_session", list(runtime_session_roots or [])),
            ("prior_workspace", list(prior_workspace_roots or [])),
        ]
        if history_sources:
            cands.extend(list(history_sources or []))
        self._destination_merge_preserved_richer_planned_subtrees_in_place(
            cur, cands, lib_key=str(lib_key), phase=str(phase)[:80]
        )
        return cur

    def _destination_index_upsert_richest_planned_path_from_subtree(
        self,
        node: dict,
        source_lbl: str,
        acc: dict[str, tuple[dict, str, dict[str, int | bool]]],
        *,
        lib_key: str,
    ) -> None:
        d0 = node.get("data")
        if isinstance(d0, dict) and not d0.get("placeholder") and self._destination_snapshot_data_planned_allocationish(d0):
            if self._destination_branch_library_key_compatible(lib_key, d0):
                path = self._destination_extract_branch_snapshot_path(d0)
                pcf = path.casefold() if path else ""
                if pcf:
                    st = self._destination_branch_stats_for_snapshot_node(node)
                    cur = acc.get(pcf)
                    if cur is None or int(self._destination_compare_branch_snapshot_richness(st, cur[2])) > 0:
                        acc[pcf] = (node, str(source_lbl)[:80], st)
        for ch in (node.get("children") or []):
            if isinstance(ch, dict):
                self._destination_index_upsert_richest_planned_path_from_subtree(
                    ch, source_lbl, acc, lib_key=lib_key
                )

    def _destination_build_richest_planned_path_index_from_candidates(
        self, candidates: list[tuple[str, list]], *, lib_key: str
    ) -> dict[str, tuple[dict, str, dict[str, int | bool]]]:
        acc: dict[str, tuple[dict, str, dict[str, int | bool]]] = {}
        for lbl, rlist in (candidates or []):
            for r0 in (rlist or []):
                if isinstance(r0, dict):
                    self._destination_index_upsert_richest_planned_path_from_subtree(
                        r0, str(lbl)[:80], acc, lib_key=lib_key
                    )
        return acc

    def _destination_apply_planned_subtree_preserve_to_nodes(
        self,
        nodes: list,
        index: dict[str, tuple[dict, str, dict[str, int | bool]]],
        *,
        lib_key: str,
        phase: str = "",
        is_shutdown: bool = False,
    ) -> None:
        for i, node in enumerate(list(nodes or [])):
            if not isinstance(node, dict):
                continue
            d0 = node.get("data")
            if isinstance(d0, dict) and not d0.get("placeholder") and self._destination_snapshot_data_planned_allocationish(d0):
                path = self._destination_extract_branch_snapshot_path(d0)
                pcf = path.casefold() if path else ""
                if not pcf or not self._destination_branch_library_key_compatible(lib_key, d0):
                    if path:
                        log_info(
                            "destination_branch_history_lookup_rejected_incompatible",
                            canonical_path=path[:500],
                            source="capture",
                            compatibility_reason="library_mismatch" if str(lib_key) and self._destination_snapshot_data_lib_key(d0) and self._destination_snapshot_data_lib_key(d0) != str(lib_key).casefold() else "unclear",  # noqa: E501
                        )
                else:
                    nref = node
                    st_f = self._destination_branch_stats_for_snapshot_node(nref)
                    ent = index.get(pcf)
                    did_replace = False
                    if ent is not None:
                        cnode, clab, st_c = ent
                        if cnode is not nref and self._destination_should_preserve_richer_branch_payload(nref, cnode):
                            if is_shutdown:
                                log_info(
                                    "destination_shutdown_branch_subtree_richness_compared",
                                    canonical_path=path[:500],
                                    current_descendants=int(st_f.get("descendants", 0)),
                                    candidate_descendants=int(st_c.get("descendants", 0)),
                                    decision="replace_subtree",
                                )
                            if is_shutdown and int(st_f.get("descendants", 0)) < int(st_c.get("descendants", 0)):
                                log_info(
                                    "destination_shutdown_snapshot_branch_overwrite_blocked",
                                    canonical_path=path[:500],
                                    current_descendants=int(st_f.get("descendants", 0)),
                                    preserved_descendants=int(st_c.get("descendants", 0)),
                                )
                            log_info(
                                "destination_branch_snapshot_preserve_richer_payload",
                                canonical_path=path[:500],
                                preserved_from=str(clab)[:80],
                                current_reason_thin="fewer_substantive_nodes" if st_f.get("descendants", 0) < st_c.get("descendants", 0) else "hollow_applied",  # noqa: E501
                            )
                            log_info(
                                "destination_snapshot_persist_branch_thin_blocked",
                                canonical_path=path[:500],
                                current_descendants=int(st_f.get("descendants", 0)),
                                preserved_descendants=int(st_c.get("descendants", 0)),
                                block_reason="thinner_capture_than_preserved",
                            )
                            if is_shutdown:
                                log_info(
                                    "destination_shutdown_branch_subtree_preserved",
                                    canonical_path=path[:500],
                                    source=str(clab)[:80],
                                    preserved_descendants=int(st_c.get("descendants", 0)),
                                )
                                log_info(
                                    "destination_shutdown_snapshot_branch_preserved",
                                    canonical_path=path[:500],
                                    source=str(clab)[:80],
                                    preserved_descendants=int(st_c.get("descendants", 0)),
                                )
                            nodes[i] = copy.deepcopy(cnode)
                            did_replace = True
                    if not did_replace:
                        log_info(
                            "destination_snapshot_persist_branch_safe",
                            canonical_path=path[:500] if path else "",
                            reason="capture_unchanged_or_richest",
                        )
                        log_info(
                            "destination_branch_snapshot_overwrite_allowed",
                            canonical_path=path[:500] if path else "",
                            reason="no_replacement_richer_or_capture_ok",
                        )
                    if did_replace:
                        continue
            nref2 = nodes[i] if i < len(nodes) else None
            if isinstance(nref2, dict):
                subc = nref2.get("children")
                if isinstance(subc, list) and subc:
                    self._destination_apply_planned_subtree_preserve_to_nodes(
                        subc, index, lib_key=lib_key, phase=phase, is_shutdown=is_shutdown
                    )
        return

    def _destination_merge_preserved_richer_planned_subtrees_in_place(
        self,
        nodes: list,
        candidates: list[tuple[str, list]],
        *,
        lib_key: str,
        phase: str = "",
    ) -> None:
        index = self._destination_build_richest_planned_path_index_from_candidates(
            list(candidates or []), lib_key=str(lib_key)
        )
        self._destination_shutdown_richest_planned_path_index = index
        self._destination_shutdown_preservation_branch_index = {k: v[0] for k, v in index.items()}
        is_shutdown = "shutdown" in str(phase or "").casefold()
        if is_shutdown:
            self._destination_shutdown_preservation_index_built = True
            log_info(
                "destination_shutdown_preservation_index_built",
                branch_count=int(len(index)),
            )
        self._destination_apply_planned_subtree_preserve_to_nodes(
            nodes, index, lib_key=str(lib_key), phase=str(phase)[:80], is_shutdown=is_shutdown
        )
        return

    def _destination_select_richer_snapshot_node_for_rehydrate(
        self, canon: str, *, min_desc: int = 0
    ) -> tuple[dict | None, str, int, str, str]:
        cnorm = self._destination_snapshot_norm_path(canon)
        if not cnorm:
            return None, "", -1, "", "empty"
        log_info("destination_branch_history_lookup_started", canonical_path=str(cnorm)[:500])
        best: dict | None = None
        best_desc = -1
        best_src = ""
        why = "none"

        def _set_best(node: dict | None, label: str, dcount: int) -> None:
            nonlocal best, best_desc, best_src, why
            if node is not None and isinstance(node, dict) and dcount > best_desc:
                best, best_desc, best_src, why = node, int(dcount), label, "selected"

        roots0, t0 = self._destination_eager_destination_tree_snapshot_roots()
        a0 = self._destination_snapshot_find_node_by_canonical_path(roots0, canon) if roots0 else None
        d0c = int(self._destination_count_snapshot_substantive_child_nodes(a0)) if a0 else 0
        if a0 is not None and d0c > best_desc and d0c >= min_desc:
            _set_best(a0, f"active_{t0}", d0c)
        mm = getattr(self, "memory_manager", None)
        if mm is not None:
            try:
                wso = mm.read_workspace_snapshot_optional()
            except Exception:
                wso = None
            if isinstance(wso, dict):
                pr = wso.get("destination_tree_snapshot") or []
                if isinstance(pr, list) and pr:
                    pn = self._destination_snapshot_find_node_by_canonical_path(pr, canon)
                    dpc = int(self._destination_count_snapshot_substantive_child_nodes(pn)) if pn else 0
                    if pn is not None and dpc > best_desc and dpc >= min_desc:
                        _set_best(pn, "prior_workspace_json", dpc)
        for lbl, rlist in self._destination_bounded_history_snapshot_source_lists():
            pn2 = self._destination_snapshot_find_node_by_canonical_path(rlist, canon) if rlist else None
            d2 = int(self._destination_count_snapshot_substantive_child_nodes(pn2)) if pn2 else 0
            if pn2 is not None and d2 > best_desc and d2 >= min_desc:
                _set_best(pn2, lbl, d2)
        if best is not None and best_desc >= 0:
            log_info(
                "destination_branch_history_lookup_hit",
                canonical_path=str(cnorm)[:500],
                source=str(best_src)[:64],
                descendant_count=int(best_desc),
                direct_child_count=int(
                    self._destination_count_snapshot_direct_substantive_children(best)
                    if isinstance(best, dict)
                    else 0
                ),
                compatibility_reason=why,
            )
        else:
            log_info(
                "destination_branch_history_lookup_miss",
                canonical_path=str(cnorm)[:500],
            )
        return best, str(best_src)[:80], int(best_desc if best is not None else -1), str(why)[:64], t0

    def _destination_path_in_expanded_or_selected_startup_shell(self, pcf: str) -> bool:
        """True when path is on the selected chain or in an expanded destination folder (visible shell)."""
        if not pcf:
            return False
        try:
            ex = {str(x).casefold() for x in (self._destination_expanded_paths_for_planning_bind() or set()) if str(x).strip()}
        except Exception:
            ex = set()
        for e in ex:
            if e and (pcf == e or pcf.startswith(e + "\\") or e.startswith(pcf + "\\")):
                return True
        return False

    def _destination_post_shell_library_identity(self) -> str:
        did = str(self._current_selected_destination_drive_id() or "").strip()
        sid = str(getattr(self, "active_draft_session_id", "") or "").strip()[:24]
        return f"{did}|{sid}".casefold()[:200]

    def _destination_collect_visible_startup_shell_paths(self, *, max_rows: int = 800) -> set[str]:
        out: set[str] = set()
        dm = getattr(self, "destination_planning_model", None)
        if dm is None or not hasattr(dm, "iter_depth_first"):
            return out
        n = 0
        try:
            for ix in dm.iter_depth_first():
                if n >= int(max_rows):
                    break
                n += 1
                if not ix.isValid():
                    continue
                pl = dict(ix.data(Qt.UserRole) or {})
                if not pl or pl.get("placeholder"):
                    continue
                rp = str(
                    self._canonical_planned_memory_path_for_graph_match(
                        str(self._tree_item_path(pl) or self._destination_semantic_path(pl) or pl.get("item_path") or "")
                    )
                    or self.normalize_memory_path(self._tree_item_path(pl) or "")
                    or ""
                ).strip()
                c = str(self._destination_snapshot_norm_path(rp) or rp or "").casefold()
                if c:
                    out.add(c)
        except Exception:
            pass
        try:
            for ep in self._destination_expanded_paths_for_planning_bind() or set():
                e = str(self._destination_snapshot_norm_path(str(ep)) or str(ep) or "").casefold()
                if e:
                    out.add(e)
        except Exception:
            pass
        return out

    def _destination_is_branch_in_visible_startup_shell_context(self, pcf: str, shell_paths: set[str]) -> bool:
        if not pcf or not shell_paths:
            return False
        for s in shell_paths:
            if not s:
                continue
            if pcf == s or pcf.startswith(s + "\\") or s.startswith(pcf + "\\"):
                return True
        return False

    def _destination_schedule_post_shell_memory_rehydrate_if_ready(self, *, reason: str) -> None:
        if bool(getattr(self, "_application_shutting_down", False)):
            return
        if not destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            return
        dm = getattr(self, "destination_planning_model", None)
        if dm is None or not bool(getattr(self, "_destination_snapshot_overlay_classification_startup_complete", False)):
            return
        if not hasattr(dm, "rowCount"):
            return
        try:
            if int(dm.rowCount(QModelIndex()) or 0) <= 0:
                return
        except Exception:
            return
        ident = self._destination_post_shell_library_identity()
        if not ident or ident == "|":
            return
        if str(getattr(self, "_destination_post_shell_memory_rehydrate_done_key", "") or "") == ident and bool(
            getattr(self, "_destination_post_shell_rich_rehydrate_scan_ran", False)
        ):
            return
        if bool(getattr(self, "_destination_post_shell_memory_rehydrate_scheduled", False)):
            return
        self._destination_post_shell_memory_rehydrate_scheduled = True
        log_info(
            "destination_post_shell_memory_rehydrate_scheduled",
            reason=str(reason or "")[:200],
            library_identity=str(ident)[:200],
        )
        r2 = str(reason or "")[:200]
        i2 = str(ident)[:200]

        def _go() -> None:
            self._destination_run_post_shell_memory_rehydrate_once(reason=r2, library_identity=i2)

        QTimer.singleShot(0, lambda: self._safe_invoke("destination_post_shell_memory_rehydrate", _go))

    def _destination_run_post_shell_memory_rehydrate_once(self, *, reason: str, library_identity: str) -> None:
        if bool(getattr(self, "_application_shutting_down", False)):
            return
        if str(getattr(self, "_destination_post_shell_memory_rehydrate_done_key", "") or "") == str(
            library_identity
        ) and bool(getattr(self, "_destination_post_shell_rich_rehydrate_scan_ran", False)):
            return
        self._destination_post_shell_memory_rehydrate_scheduled = False
        log_info(
            "destination_post_shell_memory_rehydrate_started",
            reason=str(reason or "")[:200],
            library_identity=str(library_identity)[:200],
        )
        n_rh, n_sk = 0, 0
        try:
            shell = self._destination_collect_visible_startup_shell_paths()
            self._destination_visible_startup_shell_paths_cf = set(shell)
            ex = [p for p in list(shell)[:12]]
            log_info(
                "destination_visible_startup_shell_paths_collected",
                count=int(len(shell)),
                top_examples=ex,
            )
            n_rh, n_sk = self._destination_post_shell_memory_rehydrate_scan_body(shell)
        except Exception as exc:
            self._log_restore_exception("destination_post_shell_memory_rehydrate", exc)
            self._destination_post_shell_memory_rehydrate_done_key = str(library_identity)[:200]
            self._destination_post_shell_rich_rehydrate_scan_ran = True
        else:
            self._destination_post_shell_memory_rehydrate_done_key = str(library_identity)[:200]
            self._destination_post_shell_rich_rehydrate_scan_ran = True
        log_info(
            "destination_post_shell_memory_rehydrate_completed",
            reason=str(reason or "")[:200],
            library_identity=str(library_identity)[:200],
            scanned_branch_count=int(n_rh + n_sk),
            rehydrated_branch_count=int(n_rh),
            skipped_branch_count=int(n_sk),
        )
        self._destination_maybe_finish_graph_startup_phase(
            reason="post_shell_memory_rehydrate_completed",
        )

    def _destination_post_shell_memory_rehydrate_scan_body(self, shell: set[str]) -> tuple[int, int]:
        """Rich planned rows in the memory snapshot that are in startup shell context get one branch rehydrate."""
        n_rh = 0
        n_sk = 0
        if bool(getattr(self, "_application_shutting_down", False)):
            return 0, 0
        dm = getattr(self, "destination_planning_model", None)
        if dm is None or not hasattr(dm, "find_indices_for_canonical_destination_path"):
            return 0, 0
        roots, t_src = self._destination_eager_destination_tree_snapshot_roots()
        if not roots:
            return 0, 0
        n_cap = 36
        shell_cf = set(shell or set())
        t_src = str(t_src)[:32]

        def _consider(node: dict) -> bool:
            nonlocal n_rh, n_sk
            if n_rh >= n_cap:
                return True
            if not isinstance(node, dict):
                return False
            d0 = node.get("data") if isinstance(node.get("data"), dict) else None
            if not isinstance(d0, dict) or d0.get("placeholder"):
                for ch in node.get("children") or []:
                    if isinstance(ch, dict) and _consider(ch):
                        return True
                return False
            if not self._destination_snapshot_data_planned_allocationish(d0):
                for ch in node.get("children") or []:
                    if isinstance(ch, dict) and _consider(ch):
                        return True
                return False
            pth = self._destination_extract_branch_snapshot_path(d0)
            stn = self._destination_branch_stats_for_snapshot_node(node)
            sd = int(stn.get("descendants", 0) or 0)
            if sd < 4:
                for ch in node.get("children") or []:
                    if isinstance(ch, dict) and _consider(ch):
                        return True
                return False
            ixs = dm.find_indices_for_canonical_destination_path(str(pth).strip()) or []  # type: ignore[union-attr]  # noqa: E501
            ix0 = ixs[0] if ixs and ixs[0].isValid() else None
            v2 = 0
            if ix0 is not None and isinstance(ix0, QModelIndex) and ix0.isValid():
                try:
                    c0a = ix0.siblingAtColumn(0) if ix0.column() else ix0
                    v2 = int(self._destination_visible_descendant_counts_for_index(dm, c0a)[1] or 0)
                except Exception:
                    v2 = 0
            under = bool(sd > 0 and v2 < sd)
            el = self._destination_memory_rehydrate_eligibility_checked(
                canonical_path=pth,
                stored_descendants=sd,
                visible_descendant_count=int(v2),
                shell_paths_cf=shell_cf,
                model_underrepresents_memory=under,
            )
            if not el.get("eligible"):
                n_sk += 1
                for ch in node.get("children") or []:
                    if isinstance(ch, dict) and _consider(ch):
                        return True
                return False
            c0 = ix0.siblingAtColumn(0) if ix0 is not None and ix0.column() else ix0
            if ix0 is None or not isinstance(c0, QModelIndex) or not c0.isValid():
                n_sk += 1
                log_info(
                    "destination_visible_shell_branch_memory_rehydrate_skipped",
                    canonical_path=pth[:500],
                    skip_reason="no_model_index",
                )
                for ch in node.get("children") or []:
                    if isinstance(ch, dict) and _consider(ch):
                        return True
                return False
            c_live = c0.siblingAtColumn(0) if c0.column() else c0
            if hasattr(dm, "is_index_live") and not dm.is_index_live(c_live):
                n_sk += 1
                log_info(
                    "destination_visible_shell_branch_memory_rehydrate_skipped",
                    canonical_path=pth[:500],
                    skip_reason="index_not_live",
                )
                for ch in node.get("children") or []:
                    if isinstance(ch, dict) and _consider(ch):
                        return True
                return False
            mv = self._find_planned_move_for_destination_node((c0.data(Qt.UserRole) or {}))
            if not isinstance(mv, dict):
                n_sk += 1
                log_info(
                    "destination_visible_shell_branch_memory_rehydrate_skipped",
                    canonical_path=pth[:500],
                    skip_reason="no_planned_move",
                )
                for ch in node.get("children") or []:
                    if isinstance(ch, dict) and _consider(ch):
                        return True
                return False
            mark_r = "startup_visible_shell_context" if el.get("in_startup_visible_shell_context") else "visible_or_chain"
            log_info(
                "destination_visible_shell_branch_marked_for_memory_rehydrate",
                canonical_path=pth[:500],
                stored_descendant_count=int(sd),
                visible_descendant_count=int(v2),
                reason=mark_r[:64],
            )
            log_info(
                "destination_visible_shell_branch_memory_rehydrate_started",
                canonical_path=pth[:500],
                source=f"post_shell_scan+{t_src}"[:64],
                stored_descendant_count=int(sd),
            )
            rh = self._destination_rehydrate_visible_branch_from_memory_snapshot(
                c0, mv, audit_ctx="post_shell_rich_branch_scan"
            )
            v3 = -1
            try:
                v3 = int(self._destination_visible_descendant_counts_for_index(dm, c0)[1] or 0)
            except Exception:
                v3 = -1
            log_info(
                "destination_visible_shell_branch_memory_rehydrate_completed",
                canonical_path=pth[:500],
                source=str(rh.get("rehydrate_source") or "")[:32],
                stored_descendant_count=int(sd),
                inserted_rows=int(rh.get("inserted_rows") or 0),
                upgraded_rows=int(rh.get("upgraded_rows") or 0),
                preserved_live_rows=int(rh.get("preserved_live_rows") or 0),
                resulting_visible_descendants=int(v3),
            )
            n_rh += 1
            for ch in node.get("children") or []:
                if isinstance(ch, dict) and _consider(ch):
                    return True
            return n_rh >= n_cap

        try:
            for r0 in roots:
                if isinstance(r0, dict) and _consider(r0):
                    break
        except Exception as exc:
            self._log_restore_exception("destination_post_shell_memory_rehydrate_scan_body", exc)
        return n_rh, n_sk

    def _destination_map_rehydrate_log_source(self, best_source_label: str) -> str:
        """Map internal snapshot label to destination_visible_branch_rehydrate_source_selected log values."""
        bl = str(best_source_label or "")
        if bl.startswith("active_") or not bl:
            return "active_snapshot"
        if "prior_workspace" in bl or "session" in bl.lower() or "quarantine" in bl or "backup" in bl or "/" in bl:
            return "history_candidate"
        return "active_snapshot"

    def _destination_should_run_branch_local_startup_work(
        self,
        *,
        canonical_path: str,
        work_kind: str,
        explicit_repair: bool = False,
    ) -> bool:
        wk = str(work_kind or "")[:64]
        cpath = str(canonical_path or "").strip()
        pcf = cpath.casefold()
        if bool(explicit_repair):
            log_info(
                "destination_startup_branch_local_work_allowed",
                canonical_path=cpath[:500],
                work_kind=wk,
                reason="explicit_repair_authorized",
            )
            return True
        in_startup = bool(getattr(self, "_destination_startup_phase_active", False))
        if not in_startup:
            log_info(
                "destination_startup_branch_local_work_allowed",
                canonical_path=cpath[:500],
                work_kind=wk,
                reason="not_in_startup_phase",
            )
            return True
        if not pcf:
            log_info(
                "destination_startup_branch_local_work_blocked",
                canonical_path=cpath[:500],
                work_kind=wk,
                reason="empty_path_startup",
            )
            return False
        if self._destination_path_in_expanded_or_selected_startup_shell(pcf):
            log_info(
                "destination_startup_branch_local_work_allowed",
                canonical_path=cpath[:500],
                work_kind=wk,
                reason="visible_expanded_or_ancestor",
            )
            return True
        uo = getattr(self, "_destination_planned_user_opened_paths_cf", set()) or set()
        if pcf in uo:
            log_info(
                "destination_startup_branch_local_work_allowed",
                canonical_path=cpath[:500],
                work_kind=wk,
                reason="user_opened_after_shell_interactable",
            )
            return True
        sel = self._collect_selected_tree_path("destination")
        s_norm = (self._materialize_cached_destination_lookup_norm(str(sel or "")) or "").casefold() if sel else ""
        in_sel = bool(
            s_norm
            and (
                pcf == s_norm
                or pcf.startswith(s_norm + "\\")
                or s_norm.startswith(pcf + "\\")
            )
        )
        if in_sel:
            log_info(
                "destination_startup_branch_local_work_allowed",
                canonical_path=cpath[:500],
                work_kind=wk,
                reason="selected_or_ancestor",
            )
            return True
        try:
            self._destination_invariant_repair_known_thin_branch_paths.add(pcf)  # type: ignore[union-attr]
        except Exception:
            pass
        log_info(
            "destination_startup_branch_local_work_blocked",
            canonical_path=cpath[:500],
            work_kind=wk,
            reason="startup_not_visible_selected_or_user_opened",
        )
        return False

    def _destination_should_block_cold_planned_descendant_replay(
        self,
        *,
        enqueue_reason: str,
        collect_reason: str,
        user_initiated: bool,
    ) -> bool:
        """In Graph overlay mode, do not run allocation source replay on cold session paths; user explict expand unlocks."""
        if user_initiated or getattr(self, "_overlay_followup_after_import", False):
            return False
        if not self._destination_memory_overlay_mode_enabled():
            return False
        if not destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            return False
        er = f"{enqueue_reason or ''}|{collect_reason or ''}".lower()
        # overlay_projection_invariant_repair: intentional _enforce pass — not a cold user-expand
        # storm; blocking it would prevent overlay invariants from ever projecting in tests/restore.
        needles = (
            "load_projected_descendants_startup_visibility_bypass",
            "load_projected_descendants_children_loaded_graph_auth",
            "eager_bind_allocation_descendants",
            "deferred_projected_descendants_after_placeholder_strip",
            "load_projected_descendants_graph_shell_pending",
            "load_projected_descendants_graph_shell_pending_folder_alloc",
        )
        for nd in needles:
            if nd in er:
                return True
        if "load_projected_descendants" in er and "bypass" in er:
            return True
        return False

    def _destination_on_startup_replay_guard_idle_ready(self, *, reason: str) -> None:
        """End startup replay hard-block after UI is ready for non-user work (or local destination first tick)."""
        if not bool(getattr(self, "_destination_startup_phase_active", True)):
            return
        if destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            log_info(
                "destination_startup_replay_guard_skipped_for_graph_session",
                reason=str(reason or "")[:200],
            )
            return
        self._destination_startup_phase_active = False
        self._destination_expand_shell_ready = True
        log_info(
            "destination_startup_replay_summary",
            replay_enqueued_count=int(getattr(self, "_destination_startup_replay_enqueued_count", 0) or 0),
            replay_blocked_count=int(getattr(self, "_destination_startup_replay_blocked_count", 0) or 0),
            reason=str(reason or "")[:200],
        )
        log_info("destination_startup_shell_work_completed", reason=str(reason or "")[:120])
        # Post-shell rich rehydrate is scheduled from the Graph post-overlay pipeline when the visible shell is ready.

    def _destination_graph_startup_shell_bound_for_phase_completion(self) -> bool:
        if not destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            return False
        if not bool(getattr(self, "_destination_snapshot_overlay_classification_startup_complete", False)):
            return False
        ident = self._destination_post_shell_library_identity()
        if not str(ident or "").strip() or str(ident).strip() == "|":
            return False
        dm = getattr(self, "destination_planning_model", None)
        if dm is None:
            return False
        try:
            return int(dm.rowCount(QModelIndex())) > 0
        except Exception:
            return False

    def _destination_maybe_finish_graph_startup_phase(self, *, reason: str) -> None:
        """Complete destination startup once Graph shell + post-shell rehydrate are done; idempotent per drive/session."""
        if bool(getattr(self, "_application_shutting_down", False)):
            return
        if not destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            return
        ident = self._destination_post_shell_library_identity()
        key = str(ident or "")[:200]
        if not key or key == "|":
            return
        done = str(getattr(self, "_destination_graph_startup_phase_completion_key", "") or "")
        if done and done == key and not bool(getattr(self, "_destination_startup_phase_active", True)):
            return
        sh = self._destination_graph_startup_shell_bound_for_phase_completion()
        rehydr = str(getattr(self, "_destination_post_shell_memory_rehydrate_done_key", "") or "") == str(key)
        try:
            qn = len(getattr(self, "_destination_expand_user_deferred_queue", None) or ())
        except Exception:
            qn = -1
        in_start = bool(getattr(self, "_destination_startup_phase_active", False))
        rsn = "wait"
        if not sh:
            rsn = "shell_not_bound"
        elif not rehydr:
            rsn = "post_shell_rehydrate_incomplete"
        else:
            rsn = "ready"
        log_info(
            "destination_graph_startup_phase_completion_check",
            startup_phase=in_start,
            shell_bound=bool(sh),
            post_shell_rehydrate_done=bool(rehydr),
            deferred_expand_pending_count=int(qn) if qn >= 0 else -1,
            reason=rsn[:80],
        )
        if not sh or not rehydr:
            return
        self._destination_mark_graph_startup_phase_complete(
            reason=str(reason or "")[:200], drive_id=str(self._current_selected_destination_drive_id() or "")[:120]
        )

    def _destination_mark_graph_startup_phase_complete(
        self, *, reason: str, drive_id: str, pending_deferred_count: int = -1
    ) -> None:
        if bool(getattr(self, "_application_shutting_down", False)):
            return
        if not destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            return
        ident = self._destination_post_shell_library_identity()
        key = str(ident or "")[:200]
        if str(getattr(self, "_destination_graph_startup_phase_completion_key", "") or "") == key and not bool(
            getattr(self, "_destination_startup_phase_active", True)
        ):
            return
        self._destination_graph_startup_phase_completion_key = key
        self._destination_expand_shell_ready = True
        self._destination_startup_phase_active = False
        try:
            pdc = int(pending_deferred_count)
        except Exception:
            pdc = -1
        if pdc < 0:
            try:
                pdc = int(len(getattr(self, "_destination_expand_user_deferred_queue", None) or ()))
            except Exception:
                pdc = -1
        log_info(
            "destination_graph_startup_phase_completed",
            reason=str(reason or "")[:200],
            drive_id=str(drive_id or "")[:120],
            pending_count_at_completion=int(pdc) if pdc >= 0 else 0,
        )
        n_enq = int(getattr(self, "_destination_startup_replay_enqueued_count", 0) or 0)
        n_blk = int(getattr(self, "_destination_startup_replay_blocked_count", 0) or 0)
        log_info(
            "destination_startup_replay_summary",
            replay_enqueued_count=n_enq,
            replay_blocked_count=n_blk,
            reason="graph_lifecycle:" + str(reason or "")[:160],
        )
        self._destination_startup_replay_summary_logged = True
        log_info("destination_startup_shell_work_completed", reason="graph_lifecycle:" + str(reason or "")[:100])
        if bool(getattr(self, "_destination_startup_shell_persistence_pending_dirty", False)):
            log_info(
                "destination_startup_shell_persistence_flushed",
                reason=str(reason or "")[:120],
                save_count=0,
            )
            self._destination_startup_shell_persistence_pending_dirty = False

    def _destination_memory_rehydrate_eligibility_checked(
        self,
        *,
        canonical_path: str,
        stored_descendants: int,
        visible_descendant_count: int = -1,
        shell_paths_cf: set[str] | None = None,
        model_underrepresents_memory: bool = False,
    ) -> dict[str, Any]:
        c = str(self._destination_snapshot_norm_path(canonical_path) or canonical_path or "").casefold()
        pcf = c
        in_vis = self._destination_path_in_expanded_or_selected_startup_shell(pcf)
        sh = set(shell_paths_cf) if shell_paths_cf is not None else set(
            getattr(self, "_destination_visible_startup_shell_paths_cf", set()) or set()
        )
        in_sctx = self._destination_is_branch_in_visible_startup_shell_context(pcf, sh)
        sel = self._collect_selected_tree_path("destination")
        s_norm = (self._materialize_cached_destination_lookup_norm(str(sel or "")) or "").casefold() if sel else ""
        in_sel = bool(
            s_norm
            and (
                pcf == s_norm
                or pcf.startswith(s_norm + "\\")
                or s_norm.startswith(pcf + "\\")
            )
        )
        uo = getattr(self, "_destination_planned_user_opened_paths_cf", set()) or set()
        user_opened = pcf in uo
        vis_d = int(visible_descendant_count) if int(visible_descendant_count) >= 0 else -1
        stored = int(stored_descendants)
        class_chain = bool(in_vis or in_sel or user_opened)
        under = bool(model_underrepresents_memory) or (stored > 0 and vis_d >= 0 and vis_d < stored)
        # Startup shell context: bounded visible shell paths; allows Pictures-class rehydrate without user_opened.
        in_startup = bool(
            in_sctx
            and (stored >= 4 or (under and stored > 0)),
        )
        eligible = bool(stored > 0 and (class_chain or in_startup))
        dr = "ok"
        if not eligible:
            if stored <= 0:
                dr = "no_stored_substance"
            elif not class_chain and not in_startup:
                dr = "not_in_visible_startup_or_classic_context"
        out: dict[str, Any] = {
            "canonical_path": str(canonical_path)[:500],
            "in_visible_shell": bool(in_vis),
            "in_startup_visible_shell_context": bool(in_sctx),
            "in_selected_chain": bool(in_sel),
            "user_opened": bool(user_opened),
            "stored_descendant_count": int(stored),
            "visible_descendant_count": int(vis_d),
            "eligible": bool(eligible),
            "deny_reason": str(dr)[:120],
        }
        log_info("destination_memory_rehydrate_eligibility_checked", **out)
        return out

    def _destination_post_shell_rich_memory_rehydrate_scan(self) -> None:
        """Back-compat: route through the one-shot post-shell rehydrate runner (use overlay as primary)."""
        ident = self._destination_post_shell_library_identity()
        if str(getattr(self, "_destination_post_shell_memory_rehydrate_done_key", "") or "") == ident and bool(
            getattr(self, "_destination_post_shell_rich_rehydrate_scan_ran", False)
        ):
            return
        self._destination_run_post_shell_memory_rehydrate_once(
            reason="destination_post_shell_rich_memory_rehydrate_scan", library_identity=ident
        )

    def _destination_memory_snapshot_quality_metrics(self, roots_list: list) -> dict[str, int]:
        """Snapshot JSON counts for ``destination_memory_snapshot_quality_metrics`` diagnostics (lightweight)."""
        total = int(self._count_tree_snapshot_nodes(roots_list or []))
        planned = int(self._count_planned_workspace_rows_in_destination_snapshot_roots(roots_list or []))
        alloc_marked = 0
        planned_alloc_pending = 0
        stack: list[dict] = [r for r in (roots_list or []) if isinstance(r, dict)]
        while stack:
            n = stack.pop()
            d = n.get("data") if isinstance(n.get("data"), dict) else None
            if not isinstance(d, dict) or d.get("placeholder"):
                for ch in n.get("children") or []:
                    if isinstance(ch, dict):
                        stack.append(ch)
                continue
            if bool(d.get("allocation_descendants_applied")):
                alloc_marked += 1
            if d.get("allocation_descendant_projection_pending") or d.get("planned_allocation_subtree_stale"):
                planned_alloc_pending += 1
            for ch in n.get("children") or []:
                if isinstance(ch, dict):
                    stack.append(ch)
        applied_empty = int(
            self._destination_snapshot_has_applied_planned_allocations_with_empty_subtrees(roots_list or [], log_event=False)
        )
        return {
            "total_nodes": total,
            "planned_nodes": int(planned),
            "allocation_nodes": int(planned_alloc_pending),
            "allocation_descendant_stamped": int(alloc_marked),
            "applied_but_empty_count": int(applied_empty),
        }

    def _destination_classify_thin_active_snapshot(
        self, metrics: dict[str, int] | None, *, ref_baseline: int
    ) -> tuple[bool, str]:
        """``reason``: ``too_small`` | ``applied_empty`` | ``missing_descendants`` (stable ordering)."""
        m = dict(metrics or {})
        total = int(m.get("total_nodes") or 0)
        planned = int(m.get("planned_nodes") or 0)
        applied_empty = int(m.get("applied_but_empty_count") or 0)
        if applied_empty > 0:
            return True, "applied_empty"
        min_n = int(getattr(self, "_DESTINATION_MEMORY_MIN_EXPECTED_SNAPSHOT_NODES", 60) or 60)
        if ref_baseline > 0 and min_n > 0 and int(total) < int(min_n) and int(ref_baseline) > int(total) + 40:
            return True, "too_small"
        if planned > 0 and int(total) > 0 and int(total) - int(planned) == 0:
            return True, "missing_descendants"
        if int(planned) > 0 and int(m.get("allocation_nodes") or 0) > 0 and int(m.get("allocation_descendant_stamped") or 0) == 0:
            return True, "missing_descendants"
        if int(total) > 0 and int(total) < int(min_n) and int(ref_baseline) > 2 * int(total) and int(ref_baseline) >= 120:
            return True, "too_small"
        return False, ""

    def _destination_memory_snapshot_roots_for_hydration(self) -> tuple[list, str]:
        mm = getattr(self, "memory_manager", None)
        if mm is not None:
            try:
                wso = mm.read_workspace_snapshot_optional()
            except Exception:
                wso = None
            if isinstance(wso, dict):
                roots = wso.get("destination_tree_snapshot") or []
                if isinstance(roots, list) and roots:
                    return roots, "workspace_snapshot"
        rs = getattr(self, "_runtime_session_tree_snapshots", None)
        if isinstance(rs, dict):
            d = rs.get("destination")
            if isinstance(d, list) and d:
                return d, "runtime_session"
        return [], "none"

    def _destination_invalidate_workspace_snapshot_roots_cache(self) -> None:
        self._destination_wso_roots_cache = None
        self._destination_wso_roots_cache_tag = ""
        self._destination_wso_roots_cache_expiry_mono = 0.0

    def _destination_eager_destination_tree_snapshot_roots(self) -> tuple[list, str]:
        """Same sources as :meth:`_destination_memory_snapshot_roots_for_hydration` with a short TTL cache.

        If the first read is empty, perform one additional read of the workspace snapshot and log so
        memory-backed classification is not dropped on early timing windows.
        """
        t0 = time.monotonic()
        exp = float(getattr(self, "_destination_wso_roots_cache_expiry_mono", 0) or 0)
        c = getattr(self, "_destination_wso_roots_cache", None)
        if isinstance(c, list) and t0 < exp and c:
            return c, str(getattr(self, "_destination_wso_roots_cache_tag", "") or "")
        roots, tag = self._destination_memory_snapshot_roots_for_hydration()
        if not roots and getattr(self, "memory_manager", None) is not None:
            try:
                wso = self.memory_manager.read_workspace_snapshot_optional()  # type: ignore[union-attr]  # noqa: E501
            except Exception:
                wso = None
            if isinstance(wso, dict):
                dtn = wso.get("destination_tree_snapshot") or []
                if isinstance(dtn, list) and dtn:
                    roots, tag = dtn, "workspace_snapshot_ondemand_reread"
                    log_info(
                        "destination_memory_backed_lookup_on_demand_fallback_used",
                        lookup_source="workspace_snapshot_reread",
                        node_count_hint=int(len(roots)) if isinstance(roots, list) else 0,
                    )
        self._destination_wso_roots_cache = roots
        self._destination_wso_roots_cache_tag = tag
        self._destination_wso_roots_cache_expiry_mono = t0 + 2.0
        return roots, tag

    def _destination_infer_expand_auth_class(self) -> str:
        ex = str(getattr(self, "_destination_expand_invocation", "") or "").strip()
        if ex in ("explicit_repair", "explicit_repair_authorized_path"):
            return "explicit_user_repair"
        if ex == "deferred_gesture_queue":
            return "deferred_visibility_expand"
        if not bool(getattr(self, "_destination_startup_phase_active", False)):
            if bool(getattr(self, "_destination_expand_shell_ready", False)):
                return "real_user_expand"
            return "deferred_visibility_expand"
        if bool(getattr(self, "_destination_startup_first_interactable_logged", False)):
            return "real_user_expand"
        return "startup_shell_expand"

    def _destination_should_allow_deferred_startup_expand(self, *, canonical_path: str) -> tuple[bool, str, str]:
        """Narrow allowlist: block deep / unselected planned rows during early startup; log policy."""
        p = self._materialize_cached_destination_lookup_norm(str(canonical_path or "").strip())
        if not p:
            return False, "empty_path", ""
        if bool(getattr(self, "_destination_expand_shell_ready", False)) and not bool(
            getattr(self, "_destination_startup_phase_active", False)
        ):
            return True, "post_startup_relaxed", "relaxed"
        ex_n = int(getattr(self, "_destination_startup_deferred_expand_enqueued_count", 0) or 0)
        if ex_n > 200:
            return False, "session_deferred_cap_exceeded", "hard_cap"
        segs = [x for x in str(p).replace("/", "\\").split("\\") if x] if not hasattr(self, "_path_segments") else self._path_segments(p)  # noqa: E501
        depth = int(len(segs))
        sel = self._collect_selected_tree_path("destination")
        s_norm = (self._materialize_cached_destination_lookup_norm(str(sel or "")) or "").casefold() if sel else ""
        p_cf = p.casefold()
        in_sel_chain = bool(s_norm and (p_cf == s_norm or p_cf.startswith(s_norm + "\\") or s_norm.startswith(p_cf + "\\")))
        dm = getattr(self, "destination_planning_model", None)
        is_planned_alloc = False
        if dm is not None and hasattr(dm, "find_indices_for_canonical_destination_path"):
            for ix2 in (dm.find_indices_for_canonical_destination_path(p) or []):
                if not ix2.isValid():
                    continue
                ch = ix2.data(Qt.UserRole) or {}
                if self.node_is_planned_allocation(ch if isinstance(ch, dict) else {}):
                    is_planned_alloc = True
                    break
        if in_sel_chain:
            return True, "selected_or_ancestor", "nav_context"
        if depth <= 2 and not (is_planned_alloc and depth >= 3):
            return True, "shallow_2", "shell"
        if is_planned_alloc and depth > 2 and not in_sel_chain:
            return False, "deep_planned_allocation_unselected", "block_deep"
        if depth > 3 and not in_sel_chain:
            return False, "deep_unselected", "block_deep"
        return True, "default_admit", "admit"

    def _destination_snapshot_norm_path(self, raw: str) -> str:
        s = str(raw or "").strip()
        if not s:
            return ""
        p = self._canonical_planned_memory_path_for_graph_match(s) or self.normalize_memory_path(s) or s
        return str(p).strip().casefold()

    def _destination_snapshot_find_node_by_canonical_path(self, roots: list, canonical_path: str) -> dict | None:
        want = self._destination_snapshot_norm_path(canonical_path)
        if not want:
            return None

        def walk(n: dict) -> dict | None:
            if not isinstance(n, dict):
                return None
            d = n.get("data") if isinstance(n.get("data"), dict) else None
            if not isinstance(d, dict) or d.get("placeholder"):
                for ch in n.get("children") or []:
                    if isinstance(ch, dict):
                        r = walk(ch)
                        if r is not None:
                            return r
                return None
            raw = str(
                d.get("item_path") or d.get("destination_path") or d.get("display_path") or self._tree_item_path(d) or ""
            ).strip()
            c = self._destination_snapshot_norm_path(raw)
            if c and c == want:
                return n
            for ch in n.get("children") or []:
                if isinstance(ch, dict):
                    r = walk(ch)
                    if r is not None:
                        return r
            return None

        for r in roots or []:
            if isinstance(r, dict):
                f = walk(r)
                if f is not None:
                    return f
        return None

    def _destination_snapshot_subtree_substantive_node_count(self, node: dict) -> int:
        """Non-placeholder nodes in snapshot subtree under ``node`` (includes direct children; recursive)."""
        n = 0
        if not isinstance(node, dict):
            return 0
        for ch in list(node.get("children") or []):
            if not isinstance(ch, dict):
                continue
            d = ch.get("data") if isinstance(ch.get("data"), dict) else None
            if not isinstance(d, dict) or d.get("placeholder"):
                continue
            n += 1
            n += self._destination_snapshot_subtree_substantive_node_count(ch)
        return int(n)

    def _count_planned_snapshot_nested_spec_nodes(self, spec) -> int:
        """Count nodes in a nested (data, [children, ...]) spec for rehydration metrics."""
        if not spec:
            return 0
        try:
            ch = spec[1] if len(spec) > 1 else None
        except Exception:
            ch = None
        n = 1
        for sub in ch or ():
            n += self._count_planned_snapshot_nested_spec_nodes(sub)
        return int(n)

    def _destination_tag_user_expand_enqueue_reason(
        self, base: str, *, user_initiated: bool, explicit_repair_authorized: bool
    ) -> str:
        b = str(base or "")
        if bool(explicit_repair_authorized) or not bool(user_initiated):
            return b
        if "deferred_user_expand" in b:
            return b
        if b and not b.endswith("_deferred_user_expand"):
            return f"{b}_deferred_user_expand"
        return b

    def _destination_source_descendant_collect_permitted(
        self, *, expand_auth_class: str, explicit_repair_authorized: bool
    ) -> tuple[bool, str]:
        if bool(explicit_repair_authorized) or str(expand_auth_class or "") == "explicit_user_repair":
            return True, "explicit_repair"
        if not getattr(self, "_main_window_qobject_ready", False):
            return True, "pre_full_init_or_test_harness"
        if bool(getattr(self, "_destination_startup_phase_active", False)):
            return True, "startup_phase_full_projection"
        return (
            False,
            "post_startup_requires_explicit_repair_for_full_source_subtree",
        )

    def _destination_shell_persist_heavy_deferred(self) -> bool:
        """True while Graph destination startup shell is still in its heavy phase (no full tree autosave)."""
        if not destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            return bool(getattr(self, "_destination_startup_phase_active", False))
        if bool(getattr(self, "_destination_startup_phase_active", False)):
            return True
        if not str(getattr(self, "_destination_graph_startup_phase_completion_key", "") or "").strip():
            return True
        return False

    def _destination_should_allow_draft_save_now(self, *, force: bool) -> bool:
        if bool(force) or bool(getattr(self, "_application_shutting_down", False)):
            return True
        if bool(getattr(self, "_explicit_session_save_user_triggered", False)):
            return True
        return not self._destination_shell_persist_heavy_deferred()

    def _mark_session_dirty_from_user_edit(self, reason: str = "") -> None:
        if bool(getattr(self, "_application_shutting_down", False)):
            return
        self._session_user_edited_unsaved = True
        self._session_user_edited_unsaved_count = int(
            getattr(self, "_session_user_edited_unsaved_count", 0) or 0
        ) + 1
        self._update_window_user_dirty_title_suffix()
        log_info("session_dirty_marked_user_edit", reason=str(reason)[:200])

    def _session_has_unsaved_user_changes(self) -> bool:
        return bool(getattr(self, "_session_user_edited_unsaved", False))

    def _update_window_user_dirty_title_suffix(self) -> None:
        if not getattr(self, "_main_window_qobject_ready", False):
            return
        base = str(getattr(self, "_base_window_title", "") or "Ozlink")
        if not bool(getattr(self, "_session_user_edited_unsaved", False)):
            self.setWindowTitle(base)
            return
        if not str(self.windowTitle() or "").endswith("(unsaved planning)"):
            self.setWindowTitle(base + " — (unsaved planning)")

    def _planning_user_checkpoint_path(self) -> Path | None:
        mm = getattr(self, "memory_manager", None)
        if mm is None:
            return None
        try:
            return Path(mm.root) / "PlanningUserCheckpoint.pending"
        except Exception:
            return None

    def _touch_planning_user_checkpoint(self) -> None:
        p = self._planning_user_checkpoint_path()
        if p is None:
            return
        try:
            p.parent.mkdir(parents=True, exist_ok=True)
            p.write_text("pending\n", encoding="utf-8")
        except OSError:
            return

    def _clear_planning_user_checkpoint(self) -> None:
        p = self._planning_user_checkpoint_path()
        if p is None:
            return
        try:
            if p.is_file():
                p.unlink()
        except OSError:
            return

    def _flush_recovery_journal_lightweight(self) -> int:
        """Allocations + proposed to disk; no full session JSON / destination tree walk."""
        mm = getattr(self, "memory_manager", None)
        if mm is None:
            return 0
        n = 0
        _save_ctx = "recovery_journal_lightweight"
        ar = self._build_memory_allocation_rows()
        pr = self._build_memory_proposed_folders()
        n = int(len(ar)) + int(len(pr))
        _pctx = self._planning_persist_context(save_reason=_save_ctx)
        try:
            self._touch_planning_user_checkpoint()
        except Exception:
            pass
        try:
            mm.save_allocations(
                ar,
                allow_empty_planning_persist=bool(
                    not ar and (getattr(self, "_allow_empty_planning_persist", False) or n == 0)
                ),
                save_reason="recovery_journal_flush",
                persist_context=_pctx,
            )
        except Exception:
            return 0
        try:
            mm.save_proposed(
                pr,
                allow_empty_planning_persist=not bool(pr),
                save_reason="recovery_journal_flush",
                persist_context=_pctx,
            )
        except Exception:
            return 0
        log_info(
            "recovery_journal_flush_completed",
            delta_count=int(n),
        )
        if self._destination_shell_persist_heavy_deferred():
            log_info("destination_recovery_journal_only_mode_active", reason="graph_startup_or_shell_work")
        return n

    def _destination_visible_descendant_counts_for_index(self, dm, parent_ix: QModelIndex) -> tuple[int, int]:
        """Return (direct_non_placeholder, total_non_placeholder_under)."""
        if dm is None or not parent_ix.isValid():
            return 0, 0
        c0 = parent_ix.siblingAtColumn(0) if parent_ix.column() != 0 else parent_ix
        direct = 0
        try:
            rc = int(dm.rowCount(c0))
        except Exception:
            rc = 0
        for r in range(rc):
            try:
                cix = dm.index(r, 0, c0)
            except Exception:
                continue
            if not cix.isValid():
                continue
            pl = cix.data(Qt.UserRole) or {}
            if not isinstance(pl, dict) or pl.get("placeholder"):
                continue
            direct += 1
        total = 0

        def w(ix: QModelIndex) -> int:
            t = 0
            try:
                rc2 = int(dm.rowCount(ix))
            except Exception:
                return 0
            for rr in range(rc2):
                try:
                    c2 = dm.index(rr, 0, ix)
                except Exception:
                    continue
                if not c2.isValid():
                    continue
                p2 = c2.data(Qt.UserRole) or {}
                if not isinstance(p2, dict) or p2.get("placeholder"):
                    continue
                t += 1
                t += w(c2)
            return t

        total = w(c0)
        return int(direct), int(total)

    def _destination_assess_memory_backed_branch(
        self,
        *,
        canonical_path: str,
        move,
        node_data: dict,
        dm,
        parent_ix: QModelIndex,
    ) -> dict[str, Any]:
        out: dict[str, Any] = {
            "candid_memory_backing": False,
            "memory_backed_branch": False,
            "visible_underrepresents_memory": False,
            "snapshot_source": "none",
            "stored_children_count": 0,
            "stored_descendant_count": 0,
            "visible_child_count": 0,
            "visible_descendant_count": 0,
            "allocation_descendants_applied": bool((node_data or {}).get("allocation_descendants_applied")),
        }
        cnorm = self._destination_snapshot_norm_path(canonical_path)
        log_info(
            "destination_memory_backed_lookup_started",
            normalized_path=str(cnorm)[:500],
        )
        roots, src = self._destination_eager_destination_tree_snapshot_roots()
        out["snapshot_source"] = str(src)
        if not roots or not isinstance(move, dict):
            log_info(
                "destination_memory_backed_lookup_miss",
                lookup_source="no_roots",
                normalized_path=str(cnorm)[:500],
            )
            return out
        if not self.node_is_planned_allocation(node_data or {}):
            return out
        mem_node = self._destination_snapshot_find_node_by_canonical_path(roots, canonical_path)
        if mem_node is None:
            log_info(
                "destination_memory_backed_lookup_miss",
                lookup_source="path_not_in_snapshot",
                normalized_path=str(cnorm)[:500],
            )
            return out
        out["candid_memory_backing"] = True
        try:
            chn = list(mem_node.get("children") or [])
            out["stored_children_count"] = int(
                len([c for c in chn if isinstance(c, dict) and not (c.get("data") or {}).get("placeholder")])
            )
        except Exception:
            out["stored_children_count"] = 0
        out["stored_descendant_count"] = int(self._destination_snapshot_subtree_substantive_node_count(mem_node))
        log_info(
            "destination_memory_backed_lookup_hit",
            lookup_source=str(src)[:40],
            normalized_path=str(cnorm)[:500],
            hit_descendant_count=int(out.get("stored_descendant_count") or 0),
        )
        vdir, vtot = self._destination_visible_descendant_counts_for_index(dm, parent_ix)
        out["visible_child_count"] = int(vdir)
        out["visible_descendant_count"] = int(vtot)
        out["memory_backed_branch"] = bool(out["stored_descendant_count"] > 0)
        out["visible_underrepresents_memory"] = bool(
            out["memory_backed_branch"] and int(out["visible_descendant_count"]) < int(out["stored_descendant_count"])
        )
        return out

    def _destination_rehydrate_visible_branch_from_memory_snapshot(
        self,
        parent_ix: QModelIndex,
        move,
        *,
        audit_ctx: str,
    ) -> dict[str, Any]:
        out: dict[str, Any] = {
            "outcome": "skipped",
            "inserted_rows": 0,
            "upgraded_rows": 0,
            "preserved_live_rows": 0,
            "resulting_visible_descendants": -1,
            "rehydrate_source": "",
        }
        dm = getattr(self, "destination_planning_model", None)
        if dm is None or not parent_ix.isValid() or not isinstance(move, dict):
            return out
        c0 = parent_ix.siblingAtColumn(0) if parent_ix.column() != 0 else parent_ix
        if hasattr(dm, "is_index_live") and not dm.is_index_live(c0):
            return out
        pl0 = dict(c0.data(Qt.UserRole) or {})
        row_path = str(self._tree_item_path(pl0) or "").strip()
        canon = str(
            self._canonical_planned_memory_path_for_graph_match(row_path) or self.normalize_memory_path(row_path) or ""
        ).strip()
        roots, src = self._destination_eager_destination_tree_snapshot_roots()
        if not roots or not canon:
            log_info(
                "destination_visible_branch_rehydrate_from_memory_skipped",
                reason="no_snapshot_or_path",
                audit_context=str(audit_ctx or "")[:120],
                snapshot_source=str(src),
            )
            return out
        mem_node, best_lbl, _bd, _why, _t0 = self._destination_select_richer_snapshot_node_for_rehydrate(canon, min_desc=0)
        rehydr_source = self._destination_map_rehydrate_log_source(best_lbl)
        out["rehydrate_source"] = str(rehydr_source)[:32]
        if mem_node is None:
            mem_node = self._destination_snapshot_find_node_by_canonical_path(roots, canon)
        if mem_node is None:
            log_info(
                "destination_visible_branch_rehydrate_from_memory_skipped",
                reason="path_not_in_memory_snapshot",
                audit_context=str(audit_ctx or "")[:120],
                canonical_path_excerpt=canon[:400],
            )
            return out
        sel_d = int(self._destination_count_snapshot_substantive_child_nodes(mem_node))
        if sel_d < 0:
            sel_d = 0
        log_info(
            "destination_visible_branch_rehydrate_source_selected",
            canonical_path=canon[:500],
            source=str(rehydr_source)[:32],
            selected_descendant_count=int(sel_d),
            raw_source=str(best_lbl)[:80] if best_lbl else str(src)[:64],
        )
        c_cf = str(canon).casefold()
        vdir0, vtot0 = self._destination_visible_descendant_counts_for_index(dm, c0)
        sub_n = int(self._destination_snapshot_subtree_substantive_node_count(mem_node))
        fp = f"{c_cf}|v={vtot0}|m={sub_n}"
        dfp = getattr(self, "_destination_rehydrate_session_fingerprint", None)
        if not isinstance(dfp, dict):
            dfp = {}
        self._destination_rehydrate_session_fingerprint = dfp
        prev = str(dfp.get(c_cf) or "")
        if prev == fp and int(vtot0) > 0:
            log_info(
                "destination_visible_branch_rehydrate_from_memory_skipped_already_applied",
                canonical_path_excerpt=canon[:400],
                fingerprint_excerpt=fp[:200],
            )
            out["outcome"] = "skipped"
            return out
        if prev == fp and int(vtot0) == 0 and int(sub_n) > 0:
            log_info(
                "destination_visible_branch_rehydrate_from_memory_state_unchanged",
                canonical_path_excerpt=canon[:400],
                fingerprint_excerpt=fp[:200],
            )
            out["outcome"] = "skipped"
            return out
        log_info(
            "destination_visible_branch_rehydrate_from_memory_started",
            audit_context=str(audit_ctx or "")[:120],
            canonical_path_excerpt=canon[:400],
            snapshot_source=str(src),
        )
        inserted = 0
        preserved = 0
        chs = [c for c in (mem_node.get("children") or []) if isinstance(c, dict)]
        try:
            for ch in chs:
                d = ch.get("data") if isinstance(ch.get("data"), dict) else None
                if not isinstance(d, dict) or d.get("placeholder"):
                    continue
                ch_path = str(
                    d.get("item_path") or d.get("destination_path") or d.get("display_path") or self._tree_item_path(d) or ""
                ).strip()
                ch_canon = str(
                    self._canonical_planned_memory_path_for_graph_match(ch_path) or self.normalize_memory_path(ch_path) or ""
                ).strip()
                if not ch_canon:
                    continue
                existing = (
                    dm.find_indices_for_canonical_destination_path(ch_canon)
                    if hasattr(dm, "find_indices_for_canonical_destination_path")
                    else []
                )
                if existing and existing[0].isValid():
                    epl = existing[0].data(Qt.UserRole) or {}
                    if destination_payload_is_live_graph_row(epl if isinstance(epl, dict) else {}):
                        preserved += 1
                        continue
                spec = self._destination_tree_snapshot_dict_to_nested_spec(ch)
                if spec is None:
                    continue
                if not hasattr(dm, "append_nested_child"):
                    break
                try:
                    dm.append_nested_child(c0, spec)
                    inserted += int(self._count_planned_snapshot_nested_spec_nodes(spec))
                except Exception:
                    continue
        except Exception as ex:
            log_info(
                "destination_visible_branch_rehydrate_from_memory_failed",
                audit_context=str(audit_ctx or "")[:120],
                canonical_path_excerpt=canon[:400],
                error_excerpt=str(ex)[:200],
            )
            out["outcome"] = "failed"
            return out
        vdir, vtot = self._destination_visible_descendant_counts_for_index(dm, c0)
        out["inserted_rows"] = int(inserted)
        out["preserved_live_rows"] = int(preserved)
        out["resulting_visible_descendants"] = int(vtot)
        if inserted > 0:
            out["outcome"] = "completed"
            _fp2 = f"{c_cf}|v={vtot}|m={sub_n}"
            dfp[c_cf] = _fp2
            a_ctx = str(audit_ctx or "")
            if "post_shell" in a_ctx:
                bset = getattr(self, "_destination_post_shell_rehydrate_branches_cf", None)
                if not isinstance(bset, set):
                    bset = set()
                bset.add(c_cf)
                self._destination_post_shell_rehydrate_branches_cf = bset
                log_info(
                    "destination_branch_post_shell_rehydrate_marked_complete",
                    canonical_path=canon[:500],
                )
            self._mark_destination_tree_snapshot_dirty_after_injection(
                reason="rehydrate_visible_from_memory", affected_path=canon[:400]
            )
            log_info(
                "destination_visible_branch_rehydrate_from_memory_completed",
                audit_context=str(audit_ctx or "")[:120],
                source=str(rehydr_source)[:32],
                inserted_rows=int(inserted),
                upgraded_rows=0,
                preserved_live_rows=int(preserved),
                resulting_visible_descendants=int(vtot),
            )
        else:
            out["outcome"] = "no_op"
            log_info(
                "destination_visible_branch_rehydrate_from_memory_skipped",
                reason="no_insertions_or_all_live",
                audit_context=str(audit_ctx or "")[:120],
            )
        return out

    def _destination_enqueue_reason_hits_memory_backed_replay_deny(self, enqueue_reason: str) -> bool:
        er = str(enqueue_reason or "").strip()
        for k in self._DESTINATION_MEM_BACKED_REPLAY_DENY_ENQUEUE_REASONS:
            if k in er:
                return True
        el = er.lower()
        if "load_projected_descendants" in el and "bypass" in el:
            return True
        return False

    def _destination_invariant_repair_fingerprint(self, dm, ix: QModelIndex) -> str:
        pl = dict(ix.data(Qt.UserRole) or {})
        vdir, vtot = self._destination_visible_descendant_counts_for_index(dm, ix)
        return f"{vdir}|{vtot}|{int(bool(pl.get('allocation_descendants_applied')))}|{int(bool(pl.get('children_loaded')))}"

    def _destination_invariant_repair_should_skip_cooldown(self, path_cf: str, fp: str) -> bool:
        t0 = time.monotonic()
        exp = float(getattr(self, "_destination_invariant_repair_cooldown_s", 4.0) or 4.0)
        last_t = float(getattr(self, "_destination_invariant_repair_path_cooldown_mono", {}).get(path_cf) or 0.0)
        last_fp = str(getattr(self, "_destination_invariant_repair_path_last_fingerprint", {}).get(path_cf) or "")
        if (t0 - last_t) < exp and last_fp and last_fp == fp:
            return True
        return False

    def _destination_invariant_repair_mark_cooldown(self, path_cf: str, fp: str) -> None:
        pcf = str(path_cf).casefold()
        d1 = getattr(self, "_destination_invariant_repair_path_cooldown_mono", None)
        if not isinstance(d1, dict):
            d1 = {}
        d1[pcf] = time.monotonic()
        self._destination_invariant_repair_path_cooldown_mono = d1
        d2 = getattr(self, "_destination_invariant_repair_path_last_fingerprint", None)
        if not isinstance(d2, dict):
            d2 = {}
        old_fp = str(d2.get(pcf) or "")
        if old_fp and old_fp != str(fp):
            log_info(
                "destination_invariant_repair_cooldown_cleared",
                canonical_path=pcf[:500],
                prior_fingerprint=old_fp[:200],
                new_fingerprint=str(fp)[:200],
            )
        d2[pcf] = str(fp)
        self._destination_invariant_repair_path_last_fingerprint = d2

    def _destination_pre_descendant_replay_memory_branch_policy(
        self,
        parent_ix: QModelIndex,
        move,
        *,
        enqueue_reason: str,
        user_initiated: bool,
        idle_bounded: bool,
        explicit_repair_authorized: bool,
        expand_auth_class: str = "",
    ) -> str:
        """Return ``proceed`` | ``blocked`` | ``rehydrated_no_replay`` for graph allocation-descendant decoration.

        For planned allocation branches with substantive memory snapshot, full descendant replay is denied unless
        :meth:`_destination_infer_expand_auth_class` is ``explicit_user_repair`` (or ``explicit_repair_authorized``).
        """
        dm = getattr(self, "destination_planning_model", None)
        if (
            dm is None
            or not parent_ix.isValid()
            or not isinstance(move, dict)
            or not destination_authority_contract.graph_owns_visible_real_destination_structure(self)
        ):
            return "proceed"
        if not self._destination_memory_overlay_mode_enabled():
            return "proceed"
        c0 = parent_ix.siblingAtColumn(0) if parent_ix.column() != 0 else parent_ix
        pl = dict(c0.data(Qt.UserRole) or {})
        row_path = str(self._tree_item_path(pl) or "").strip()
        canon = str(
            self._canonical_planned_memory_path_for_graph_match(row_path) or self.normalize_memory_path(row_path) or ""
        ).strip()
        _eac = str(expand_auth_class or "").strip() or self._destination_infer_expand_auth_class()
        assess = self._destination_assess_memory_backed_branch(
            canonical_path=canon, move=move, node_data=pl, dm=dm, parent_ix=c0
        )
        if not bool(assess.get("memory_backed_branch")):
            return "proceed"
        log_info(
            "destination_memory_backed_branch_detected",
            canonical_path=canon[:500],
            stored_children_count=int(assess.get("stored_children_count") or 0),
            stored_descendant_count=int(assess.get("stored_descendant_count") or 0),
            visible_child_count=int(assess.get("visible_child_count") or 0),
            visible_descendant_count=int(assess.get("visible_descendant_count") or 0),
            allocation_descendants_applied=bool(assess.get("allocation_descendants_applied")),
            source=str(assess.get("snapshot_source") or "")[:40],
        )
        rehydr_out: dict[str, Any] = {}
        should_try_rehydrate = bool(assess.get("visible_underrepresents_memory")) or (
            bool((pl or {}).get("allocation_descendants_applied"))
            and int(assess.get("visible_descendant_count") or 0) < int(assess.get("stored_descendant_count") or 0)
        )
        if should_try_rehydrate and not bool(explicit_repair_authorized):
            _br = self._destination_should_run_branch_local_startup_work(
                canonical_path=canon,
                work_kind="visible_memory_rehydrate",
                explicit_repair=False,
            )
            if not _br and int(assess.get("stored_descendant_count") or 0) >= 4 and bool(
                assess.get("visible_underrepresents_memory")
            ):
                _el = self._destination_memory_rehydrate_eligibility_checked(
                    canonical_path=canon,
                    stored_descendants=int(assess.get("stored_descendant_count") or 0),
                    visible_descendant_count=int(assess.get("visible_descendant_count") or 0),
                    model_underrepresents_memory=bool(assess.get("visible_underrepresents_memory")),
                )
                _br = bool(_el.get("eligible"))
            if not _br:
                should_try_rehydrate = False
        if should_try_rehydrate:
            if bool((pl or {}).get("allocation_descendants_applied")) and int(assess.get("visible_descendant_count") or 0) < int(
                assess.get("stored_descendant_count") or 0
            ):
                log_info(
                    "destination_applied_empty_branch_rehydrate_attempted",
                    path_excerpt=row_path[:400],
                )
            rehydr_out = self._destination_rehydrate_visible_branch_from_memory_snapshot(
                c0, move, audit_ctx=str(enqueue_reason or "")[:120]
            )
            if int(rehydr_out.get("inserted_rows") or 0) > 0:
                log_info("destination_applied_empty_branch_rehydrate_succeeded", path_excerpt=row_path[:400])
        if bool(explicit_repair_authorized) or _eac == "explicit_user_repair":
            return "proceed"
        if not bool(assess.get("memory_backed_branch")):
            return "proceed"
        inserted = int((rehydr_out or {}).get("inserted_rows") or 0)
        assess2 = self._destination_assess_memory_backed_branch(
            canonical_path=canon, move=move, node_data=dict(c0.data(Qt.UserRole) or {}), dm=dm, parent_ix=c0
        )
        still_thin = bool(assess2.get("visible_underrepresents_memory"))
        if inserted > 0 and not still_thin:
            log_info(
                "destination_replay_blocked_memory_backed_branch_policy",
                canonical_path=canon[:500],
                enqueue_reason=str(enqueue_reason or "")[:200],
                user_initiated=bool(user_initiated),
                idle_bounded=bool(idle_bounded),
                auth_class=str(_eac)[:40],
                branch_memory_backed=True,
                rehydrate_attempted=True,
                pending_marker_added=False,
                explicit_repair_authorized=bool(explicit_repair_authorized),
            )
            return "rehydrated_no_replay"
        log_info(
            "destination_replay_blocked_memory_backed_branch_policy",
            canonical_path=canon[:500],
            enqueue_reason=str(enqueue_reason or "")[:200],
            user_initiated=bool(user_initiated),
            idle_bounded=bool(idle_bounded),
            auth_class=str(_eac)[:40],
            branch_memory_backed=True,
            rehydrate_attempted=bool(should_try_rehydrate and bool(rehydr_out)),
            pending_marker_added=bool(still_thin or inserted == 0),
            explicit_repair_authorized=bool(explicit_repair_authorized),
        )
        if still_thin and inserted == 0:
            log_info(
                "destination_applied_empty_branch_marked_pending_after_rehydrate",
                path_excerpt=row_path[:400],
            )
        if still_thin or inserted == 0:
            self._destination_planned_replay_deferred_marker(c0, move, log_reason="memory_backed_no_explicit_repair")
        if inserted > 0:
            return "rehydrated_no_replay"
        return "blocked"

    def _destination_planned_replay_deferred_marker(
        self,
        parent_ix: QModelIndex,
        move,
        *,
        log_reason: str,
    ) -> None:
        dm = getattr(self, "destination_planning_model", None)
        if dm is None or not isinstance(parent_ix, QModelIndex) or not parent_ix.isValid():
            return
        c0 = parent_ix.siblingAtColumn(0) if parent_ix.column() != 0 else parent_ix

        def _mut(p):
            p["children_loaded"] = False
            p["allocation_descendants_replay_deferred_cold_start"] = True
            p["allocation_descendant_projection_pending"] = True
            p["planned_allocation_subtree_stale"] = True

        try:
            dm.update_payload_for_index(c0, _mut)
        except Exception:
            return
        p_ex = ""
        try:
            p_ex = str((move or {}).get("destination_path") or self._tree_item_path(c0.data(Qt.UserRole) or {}))[:400]
        except Exception:
            p_ex = str(log_reason or "")[:120]
        log_info("destination_planned_allocation_pending_descendants_marker_added", path_excerpt=p_ex, reason_excerpt=str(log_reason)[:120])
        log_info("destination_planned_allocation_replay_deferred_until_user_or_idle", path_excerpt=p_ex)
        log_info(
            "destination_planned_allocation_expand_affordance_added",
            path_excerpt=p_ex,
        )

    def _destination_memory_active_vs_rich_candidate_audit_readonly(self) -> None:
        """Log active vs richer candidates on disk; never copies or overwrites (diagnostics only)."""
        if bool(getattr(self, "_destination_memory_active_rich_candidate_audit_ran", False)):
            return
        self._destination_memory_active_rich_candidate_audit_ran = True
        mm = getattr(self, "memory_manager", None)
        active_ws = 0
        session_dst = 0
        best = 0
        best_lbl = ""
        path_ws = path_sess = ""
        snap_for_metrics: list = []
        dtn_ws: list = []
        if mm is not None:
            mpaths = getattr(mm, "paths", None) or {}
            path_ws = str(mpaths.get("workspace_snapshot") or "")
            path_sess = str(mpaths.get("session") or "")
            wso = None
            try:
                wso = mm.read_workspace_snapshot_optional()
            except Exception:
                wso = None
            if isinstance(wso, dict):
                dtn = wso.get("destination_tree_snapshot") or []
                dtn_ws = list(dtn) if isinstance(dtn, list) else []
                if isinstance(dtn, list):
                    try:
                        active_ws = int(self._count_tree_snapshot_nodes(dtn))
                    except Exception:
                        active_ws = 0
            if path_sess and Path(path_sess).is_file():
                try:
                    sraw = json.loads(Path(path_sess).read_text(encoding="utf-8"))
                except Exception:
                    sraw = None
                if isinstance(sraw, dict):
                    dt = sraw.get("DestinationTreeSnapshot") or []
                    if isinstance(dt, list):
                        try:
                            session_dst = int(self._count_tree_snapshot_nodes(dt))
                        except Exception:
                            session_dst = 0
                        if dt:
                            snap_for_metrics = list(dt)
        try:
            for cand, lbl in ((active_ws, "WorkspaceSnapshot"), (session_dst, "Draft_SessionState")):
                if cand > best:
                    best, best_lbl = int(cand), str(lbl)
        except Exception:
            pass
        for extra_name, pth in (("quarantine", getattr(mm, "quarantine", None)), ("backups", getattr(mm, "backups", None))):
            if pth is None or not Path(str(pth)).is_dir():
                continue
            try:
                n_scanned = 0
                for p in Path(str(pth)).glob("*.json"):
                    if n_scanned >= 60:
                        break
                    n_scanned += 1
                    if p.name in ("MemoryManifest.json",) or p.stat().st_size > 4_000_000:
                        continue
                    try:
                        raw = json.loads(p.read_text(encoding="utf-8", errors="ignore"))
                    except Exception:
                        continue
                    dtn = None
                    if isinstance(raw, dict):
                        dtn = raw.get("DestinationTreeSnapshot") or raw.get("destination_tree_snapshot")
                    if not isinstance(dtn, list) or not dtn:
                        continue
                    try:
                        cn = int(self._count_tree_snapshot_nodes(dtn))
                    except Exception:
                        continue
                    if cn > best:
                        best, best_lbl = int(cn), f"{extra_name}/{p.name[:48]}"
            except Exception:
                pass
        ref = 0
        try:
            ref = int(self._destination_rich_reference_snapshot_node_count_baseline())
        except Exception:
            ref = 0
        log_info(
            "destination_memory_active_vs_rich_candidate_audit",
            active_workspace_nodes=int(active_ws),
            session_destination_nodes=int(session_dst),
            best_rich_node_count=int(best),
            best_label=str(best_lbl)[:120],
            reference_baseline=int(ref),
        )
        if best > 0 and best_lbl and best > max(session_dst, active_ws):
            log_info(
                "destination_memory_rich_candidate_found",
                node_count=int(best),
                where=str(best_lbl)[:200],
            )
        if not snap_for_metrics and dtn_ws:
            snap_for_metrics = list(dtn_ws)
        mqual: dict[str, int] = {}
        if snap_for_metrics:
            mqual = self._destination_memory_snapshot_quality_metrics(snap_for_metrics)
            log_info("destination_memory_snapshot_quality_metrics", **mqual)
        is_thin, th_reason = self._destination_classify_thin_active_snapshot(
            mqual or None, ref_baseline=int(ref)
        )
        if is_thin and th_reason and mqual:
            log_info(
                "destination_memory_active_snapshot_is_thin",
                reason=str(th_reason)[:40],
                reference_baseline=int(ref),
                **mqual,
            )
        elif (not mqual) and max(session_dst, active_ws) < 80 and ref > 0 and int(ref) > 2 * max(
            int(session_dst), int(active_ws)
        ) and max(int(session_dst), int(active_ws)) < int(ref) - 20:
            log_info(
                "destination_memory_active_snapshot_is_thin",
                reason="legacy_size_heuristic",
                active_max=int(max(session_dst, active_ws)),
                reference_baseline=int(ref),
            )
        if session_dst and active_ws and (session_dst < 80) and (active_ws < session_dst - 1):
            log_info(
                "destination_memory_sidecar_runtime_session_versus_workspace_note",
                session_json_nodes=int(session_dst),
                workspace_json_nodes=int(active_ws),
            )

    def _destination_loaded_snapshot_overlay_classification_audit(self) -> dict[str, Any]:
        """After snapshot bind: classify destination model rows for overlay vs live Graph (forensics)."""
        out: dict[str, Any] = {
            "total_rows": 0,
            "planned_workspace_strict": 0,
            "memory_overlay_reuse": 0,
            "live_graph": 0,
            "placeholder": 0,
            "workspace_row_state_nonempty": 0,
            "verification_state_nonempty": 0,
            "allocation_descendants_applied": 0,
            "destination_payload_is_planned_true": 0,
            "label_planned_tag": 0,
            "label_allocated_tag": 0,
            # Forensic: bump when overlay audit semantics change (strict planned also increments memory_overlay_reuse).
            "overlay_classification_counter_policy_version": 2,
        }
        model = getattr(self, "destination_planning_model", None)
        if model is None or not hasattr(model, "iter_depth_first"):
            log_info("destination_loaded_snapshot_overlay_classification_audit", **out)
            return out
        sample_planned: list[str] = []
        for ix in model.iter_depth_first():
            out["total_rows"] += 1
            pl = ix.data(Qt.UserRole) or {}
            if not isinstance(pl, dict):
                continue
            if pl.get("placeholder"):
                out["placeholder"] += 1
                continue
            if str(pl.get("workspace_row_state") or "").strip():
                out["workspace_row_state_nonempty"] += 1
            if str(pl.get("verification_state") or "").strip():
                out["verification_state_nonempty"] += 1
            if bool(pl.get("allocation_descendants_applied")):
                out["allocation_descendants_applied"] += 1
            if destination_payload_is_planned_workspace_row(pl):
                out["planned_workspace_strict"] += 1
                out["destination_payload_is_planned_true"] += 1
            if destination_payload_is_memory_overlay_row_for_reuse(pl):
                out["memory_overlay_reuse"] += 1
            if destination_payload_is_live_graph_row(pl):
                out["live_graph"] += 1
            lbl = f"{pl.get('base_display_label', '')!s} {pl.get('tree_label', '')!s}"
            if "[planned]" in lbl.casefold():
                out["label_planned_tag"] += 1
            if "[allocated]" in lbl.casefold():
                out["label_allocated_tag"] += 1
            if len(sample_planned) < 20 and (
                destination_payload_is_planned_workspace_row(pl)
                or destination_payload_is_memory_overlay_row_for_reuse(pl)
            ):
                tp = self._tree_item_path(pl) or pl.get("item_path") or pl.get("destination_path") or ""
                sample_planned.append(str(tp)[:420])
        try:
            self._destination_last_overlay_audit_total_rows = int(out.get("total_rows") or 0)
        except Exception:
            self._destination_last_overlay_audit_total_rows = 0
        log_info("destination_loaded_snapshot_overlay_classification_audit", **out)
        log_info(
            "destination_snapshot_overlay_predicate_alignment",
            planned_workspace_strict=int(out.get("planned_workspace_strict") or 0),
            memory_overlay_reuse_rows=int(out.get("memory_overlay_reuse") or 0),
            note="memory_overlay_reuse_uses_destination_payload_is_memory_overlay_row_for_reuse_including_strict_planned",
        )
        log_info(
            "destination_loaded_snapshot_overlay_row_sample",
            sample_paths=sample_planned,
            sample_count=len(sample_planned),
        )
        return out

    def _destination_loaded_snapshot_allocation_subtree_audit(self) -> None:
        """Fixed allocation roots: subtree counts and classification after snapshot reset."""
        roots = [
            r"Root3\HR\Employee Files\Contractor Resumes",
            r"Root3\Sales\Pictures",
            r"Root3\Management\Follow up",
            r"Root3\Management\Email attachments",
            r"Root3\Projects\Completed Projects\Soma Building Services",
        ]
        model = getattr(self, "destination_planning_model", None)
        if model is None or not hasattr(model, "iter_depth_first"):
            log_info("destination_loaded_snapshot_allocation_subtree_audit", note="no_model", roots=roots)
            return

        def _canon(p: str) -> str:
            return self._canonical_planned_memory_path_for_graph_match(str(p or "").strip())

        index_by_path: dict[str, QModelIndex] = {}
        for ix in model.iter_depth_first():
            pl = ix.data(Qt.UserRole) or {}
            if not isinstance(pl, dict) or pl.get("placeholder"):
                continue
            tp = self._tree_item_path(pl) or pl.get("item_path") or pl.get("destination_path") or ""
            ck = _canon(tp)
            if ck:
                index_by_path[ck] = ix

        for raw in roots:
            want = _canon(raw)
            ix_root = index_by_path.get(want)
            exists = bool(ix_root is not None and ix_root.isValid())
            planned_sub = 0
            alloc_tag = 0
            mem_ov = 0
            strict = 0
            live_sub = 0
            gen_sub = 0
            samples: list[str] = []
            if exists and ix_root is not None:
                stack = [ix_root]
                while stack:
                    cur = stack.pop()
                    if not cur.isValid():
                        continue
                    for r in range(model.rowCount(cur)):
                        ch = model.index(r, 0, cur)
                        if not ch.isValid():
                            continue
                        stack.append(ch)
                        cpl = ch.data(Qt.UserRole) or {}
                        if not isinstance(cpl, dict) or cpl.get("placeholder"):
                            continue
                        pth = self._tree_item_path(cpl) or cpl.get("item_path") or ""
                        lbl = f"{cpl.get('base_display_label', '')!s}".casefold()
                        is_live = destination_payload_is_live_graph_row(cpl)
                        is_strict = destination_payload_is_planned_workspace_row(cpl)
                        is_mem = destination_payload_is_memory_overlay_row_for_reuse(cpl)
                        if is_live:
                            live_sub += 1
                        elif is_strict or is_mem:
                            if is_strict:
                                strict += 1
                            if is_mem:
                                mem_ov += 1
                            planned_sub += 1
                        else:
                            gen_sub += 1
                        if "[allocated]" in lbl:
                            alloc_tag += 1
                        if len(samples) < 12:
                            samples.append(str(pth)[:400])
                log_info(
                    "destination_loaded_snapshot_allocation_subtree_audit",
                    allocation_root_raw=str(raw)[:420],
                    allocation_root_canonical=str(want)[:420],
                    root_row_exists=bool(exists),
                    descendant_rows_under_path=int(planned_sub + gen_sub + live_sub),
                    planned_workspace_descendant_rows=int(strict),
                    memory_overlay_descendant_rows=int(mem_ov),
                    generic_non_overlay_descendant_rows=int(gen_sub),
                    label_allocated_rows_near_descendants=int(alloc_tag),
                    live_graph_descendant_rows=int(live_sub),
                    sample_descendant_paths=samples,
                )

    def _destination_rehydrate_overlay_payloads_in_destination_model(self) -> int:
        """Stamp strict planned-workspace metadata onto model rows loaded from snapshots with weak pairing."""
        model = getattr(self, "destination_planning_model", None)
        if model is None or not hasattr(model, "iter_depth_first"):
            return 0
        n = 0
        for ix in model.iter_depth_first():
            pl = dict(ix.data(Qt.UserRole) or {})
            if not pl or pl.get("placeholder"):
                continue
            if destination_snapshot_rehydrate_overlay_payload(pl):
                n += 1
                model.update_payload_for_index(ix, lambda p, src=pl: p.update(src))
        if n:
            log_info(
                "destination_snapshot_overlay_metadata_rehydrated",
                model_rows_mutated=int(n),
                phase="destination_model_walk",
            )
        return n

    def _destination_run_post_snapshot_bind_overlay_pipeline(self, *, reason: str) -> None:
        """Classification + subtree audit + model rehydrate after ``reset_nested`` (provisional or pre-graph bind)."""
        self._destination_snapshot_overlay_pipeline_in_progress = True
        self._destination_snapshot_overlay_classification_startup_complete = False
        self._destination_startup_overlay_snapshot_persist_ready = False
        try:
            est_nodes = -1
            try:
                dm = getattr(self, "destination_planning_model", None)
                if dm is not None and hasattr(dm, "iter_depth_first"):
                    est_nodes = sum(1 for _ in dm.iter_depth_first())
            except Exception:
                est_nodes = -1
            log_info(
                "destination_memory_snapshot_authoritative_paint_started",
                reason=str(reason or "")[:200],
                model_rows_estimate=int(est_nodes),
            )
            self._destination_loaded_snapshot_overlay_classification_audit()
            self._destination_loaded_snapshot_allocation_subtree_audit()
            self._destination_rehydrate_overlay_payloads_in_destination_model()
            self._destination_loaded_snapshot_overlay_classification_audit()
        except Exception as exc:
            self._log_restore_exception("destination_loaded_snapshot_overlay_audit", exc)
            log_info(
                "destination_startup_overlay_classification_pipeline_failed",
                reason=str(reason or "")[:120],
                error_excerpt=str(exc)[:200],
            )
        finally:
            self._destination_snapshot_overlay_pipeline_in_progress = False
            self._destination_snapshot_overlay_classification_startup_complete = True
            self._destination_overlay_visibility_gate_reschedule_count = 0
            rs = str(reason or "")
            if "provisional" in rs:
                self._destination_startup_overlay_snapshot_persist_ready = True
            elif "pre_graph" in rs:
                self._destination_startup_overlay_snapshot_persist_ready = bool(
                    getattr(self, "_destination_startup_snapshot_preservation_applied", False)
                )
            else:
                self._destination_startup_overlay_snapshot_persist_ready = True
            log_info(
                "destination_startup_overlay_classification_pipeline_finished",
                reason=str(reason or "")[:200],
                overlay_audit_total_rows=int(getattr(self, "_destination_last_overlay_audit_total_rows", 0) or 0),
                persist_ready=bool(getattr(self, "_destination_startup_overlay_snapshot_persist_ready", False)),
            )
            if destination_authority_contract.graph_owns_visible_real_destination_structure(self):
                self._destination_schedule_post_shell_memory_rehydrate_if_ready(
                    reason=rs[:200] or "overlay_pipeline_complete"
                )

    def _destination_retry_load_projected_descendants_after_overlay_gate(self, dest_lookup_cf: str) -> None:
        """Resume visibility-bypass descendant load after overlay classification completed."""
        if not getattr(self, "_destination_snapshot_overlay_classification_startup_complete", False):
            n = int(getattr(self, "_destination_overlay_visibility_gate_reschedule_count", 0) or 0)
            if n < 100:
                self._destination_overlay_visibility_gate_reschedule_count = n + 1
                QTimer.singleShot(
                    40,
                    lambda p=str(dest_lookup_cf or ""): self._safe_invoke(
                        "destination_visibility_bypass_post_overlay_classification_retry",
                        lambda: self._destination_retry_load_projected_descendants_after_overlay_gate(p),
                    ),
                )
            return
        self._destination_overlay_visibility_gate_reschedule_count = 0
        ix = self._find_visible_destination_item_by_path(str(dest_lookup_cf or "").strip())
        if ix is None or not ix.isValid():
            return
        log_info(
            "destination_planned_allocation_replay_deferred_until_user_or_idle",
            path_excerpt=str(dest_lookup_cf or "")[:400],
        )
        log_info(
            "destination_descendant_replay_not_enqueued_startup_policy",
        )
        self._load_destination_projected_descendants_index(ix, user_initiated=False)

    def _destination_graph_bind_presnapshot_classify_row(
        self, pl: dict, *, parent_path_cf: str
    ) -> tuple[bool, str]:
        """Return (include_in_overlay_snapshot, ignore_reason) for a direct model child before Graph replace."""
        if not isinstance(pl, dict):
            return False, "unknown"
        if pl.get("placeholder"):
            return False, "placeholder"
        if destination_payload_is_live_graph_row(pl):
            return False, "live_graph_row"
        child_sem = str(self._destination_semantic_path(pl) or "").strip()
        child_path = str(
            self._canonical_planned_memory_path_for_graph_match(
                child_sem
                or str(
                    self._destination_row_raw_path_for_path_lookup_match(pl)
                    or self._tree_item_path(pl)
                    or pl.get("item_path")
                    or pl.get("destination_path")
                    or ""
                ).strip()
            )
        ).strip()
        parent_cf = str(parent_path_cf or "").strip()
        if parent_cf and child_path:
            cf_p = parent_cf.casefold()
            cf_c = child_path.casefold()
            if cf_c != cf_p and not cf_c.startswith(cf_p + "\\"):
                return False, "wrong_parent_path"
        if destination_payload_is_planned_workspace_row(pl):
            return True, ""
        if destination_payload_is_memory_overlay_row_for_reuse(pl):
            if not str(pl.get("allocation_id") or pl.get("request_id") or "").strip():
                if not (pl.get("planned_allocation_descendant") or pl.get("workspace_planned_row")):
                    lbl = f"{pl.get('base_display_label', '')!s} {pl.get('tree_label', '')!s}".casefold()
                    if "[planned]" not in lbl and "[allocated]" not in lbl:
                        return False, "missing_planning_identity"
            return True, ""
        return False, "not_planned_workspace_row"

    def _destination_graph_bind_presnapshot_overlay_scan(
        self, parent_ix: QModelIndex, *, parent_semantic_path: str
    ) -> None:
        """Log why rows under a Graph bind parent are included or ignored for overlay presnapshot."""
        model = getattr(self, "destination_planning_model", None)
        if model is None or not parent_ix.isValid():
            return
        col0 = parent_ix.siblingAtColumn(0) if parent_ix.column() != 0 else parent_ix
        parent_cf = self._canonical_planned_memory_path_for_graph_match(
            str(parent_semantic_path or "").strip()
        )
        log_info(
            "destination_graph_bind_presnapshot_overlay_scan_started",
            parent_path_excerpt=str(parent_semantic_path or "")[:400],
            parent_canonical_excerpt=str(parent_cf)[:400],
            child_rows=int(model.rowCount(col0)) if col0.isValid() else 0,
        )
        for r in range(model.rowCount(col0) if col0.isValid() else 0):
            ix = model.index(r, 0, col0)
            if not ix.isValid():
                continue
            pl = dict(ix.data(Qt.UserRole) or {})
            ok, reason = self._destination_graph_bind_presnapshot_classify_row(pl, parent_path_cf=parent_cf)
            tp = str(self._tree_item_path(pl) or pl.get("item_path") or "")[:400]
            if ok:
                log_info(
                    "destination_graph_bind_presnapshot_overlay_row_included",
                    parent_path_excerpt=str(parent_semantic_path or "")[:400],
                    row_path_excerpt=tp,
                    strict_planned_workspace=bool(destination_payload_is_planned_workspace_row(pl)),
                    memory_overlay_reuse=bool(destination_payload_is_memory_overlay_row_for_reuse(pl)),
                    workspace_row_state=str(pl.get("workspace_row_state") or "")[:24],
                    verification_state=str(pl.get("verification_state") or "")[:24],
                    row_kind=str(pl.get("row_kind") or "")[:40],
                    node_origin=str(pl.get("node_origin") or "")[:48],
                    overlay_state=str(pl.get("overlay_state") or "")[:48],
                    is_live_graph=bool(destination_payload_is_live_graph_row(pl)),
                    is_placeholder=bool(pl.get("placeholder")),
                )
            else:
                log_info(
                    "destination_graph_bind_presnapshot_overlay_row_ignored",
                    parent_path_excerpt=str(parent_semantic_path or "")[:400],
                    row_path_excerpt=tp,
                    ignore_reason=str(reason or "unknown")[:80],
                    strict_planned_workspace=bool(destination_payload_is_planned_workspace_row(pl)),
                    memory_overlay_reuse=bool(destination_payload_is_memory_overlay_row_for_reuse(pl)),
                    workspace_row_state=str(pl.get("workspace_row_state") or "")[:24],
                    verification_state=str(pl.get("verification_state") or "")[:24],
                    row_kind=str(pl.get("row_kind") or "")[:40],
                    node_origin=str(pl.get("node_origin") or "")[:48],
                    overlay_state=str(pl.get("overlay_state") or "")[:48],
                    is_live_graph=bool(destination_payload_is_live_graph_row(pl)),
                    is_placeholder=bool(pl.get("placeholder")),
                )

    def _destination_model_index_tree_depth(self, col0: QModelIndex) -> int:
        """Tree depth under the model root (0 = top-level rows under invisible root)."""
        d = -1
        ix = col0
        while ix is not None and ix.isValid():
            d += 1
            ix = ix.parent()
        return max(0, d)

    def _destination_graph_child_union_skip_refresh_gate(
        self, reason: str, node_data: dict, fingerprint: Optional[dict]
    ) -> bool:
        if str(reason or "") != "destination_graph_child_union" or not isinstance(fingerprint, dict):
            return False
        mode = str(fingerprint.get("mode") or "").strip()
        if mode == "folder_root":
            d0 = str(fingerprint.get("drive_id") or "").strip()
            i0 = str(fingerprint.get("item_id") or "").strip()
            d1 = str(self._resolve_tree_item_drive_id("destination", node_data) or "").strip()
            i1 = str(node_data.get("id") or "").strip()
            return bool(d0 and i0 and d0 == d1 and i0 == i1)
        if mode == "library_root":
            d0 = str(fingerprint.get("drive_id") or "").strip()
            i0 = str(fingerprint.get("item_id") or "").strip()
            d1 = str(self._resolve_tree_item_drive_id("destination", node_data) or "").strip()
            i1 = str(node_data.get("id") or "").strip()
            return bool(d0 and d0 == d1 and i0 and i0 == i1 and bool(fingerprint.get("item_id_is_drive_root")))
        return False

    def _destination_determine_graph_union_root_target(self) -> dict[str, Any]:
        out: dict[str, Any] = {
            "mode": "skipped",
            "parent_index": QModelIndex(),
            "parent_canonical_path": "",
            "drive_id": "",
            "item_id": "",
            "item_id_is_drive_root": False,
            "reason": "",
        }
        did = str(self._current_selected_destination_drive_id() or "").strip()
        if not did:
            out["reason"] = "no_selected_destination_drive"
            log_info(
                "destination_graph_union_root_target_skipped",
                mode="skipped",
                top_level_count=-1,
                selected_drive_id_suffix="",
                parent_path="",
                parent_item_id_suffix="",
                reason=str(out["reason"])[:200],
            )
            return out
        m = getattr(self, "destination_planning_model", None)
        if m is None or not hasattr(m, "rowCount"):
            out["reason"] = "no_model"
            log_info(
                "destination_graph_union_root_target_skipped",
                mode="skipped",
                top_level_count=-1,
                selected_drive_id_suffix=did[-16:],
                parent_path="",
                parent_item_id_suffix="",
                reason="no_model",
            )
            return out
        inv = QModelIndex()
        try:
            nroot = int(m.rowCount(inv))
        except Exception:
            nroot = 0
        out["drive_id"] = did
        nroot = min(int(nroot), 256)
        row_payloads: list[dict] = []
        for r in range(nroot):
            try:
                ix = m.index(r, 0, inv)
            except Exception:
                continue
            if not ix.isValid():
                continue
            pl = self._destination_model_index_user_role_dict(ix)
            if not isinstance(pl, dict) or pl.get("placeholder"):
                continue
            row_payloads.append(
                {
                    "row": int(r),
                    "ix": ix,
                    "pl": pl,
                    "name_excerpt": str(pl.get("name") or "")[:120],
                }
            )
        def _is_hub(p: dict) -> bool:
            if not p.get("is_folder", True):
                return False
            if not str(p.get("id") or "").strip():
                return False
            if str(self._resolve_tree_item_drive_id("destination", p) or "").strip() != did:
                return False
            if self._destination_row_is_live_graph_structure(p):
                return True
            wss = str(p.get("workspace_row_state") or "").strip()
            if wss and wss == WORKSPACE_ROW_STATE_CACHED_PROVISIONAL:
                return True
            return self._destination_row_is_graph_derived_dest_child_fetch_eligible(p)

        hubs = [e for e in row_payloads if _is_hub(e["pl"])]
        if len(hubs) > 1:
            out["mode"] = "ambiguous"
            out["reason"] = "multiple_graph_hub_candidates_at_top_level"
            log_info(
                "destination_graph_union_root_target_skipped",
                mode="ambiguous",
                top_level_count=int(len(row_payloads)),
                selected_drive_id_suffix=did[-16:],
                parent_path="",
                parent_item_id_suffix="",
                reason=str(out["reason"])[:200],
            )
            return out
        if len(hubs) == 1:
            h0 = hubs[0]
            plh = h0["pl"]
            out["mode"] = "folder_root"
            out["parent_index"] = h0["ix"]
            out["item_id"] = str(plh.get("id") or "").strip()
            out["item_id_is_drive_root"] = False
            pth = str(
                self._destination_semantic_path(plh) or plh.get("item_path") or plh.get("name") or ""
            ).strip()
            out["parent_canonical_path"] = pth
            out["reason"] = "single_top_level_graph_folder_hub"
            log_info(
                "destination_graph_union_root_target_detected",
                mode="folder_root",
                top_level_count=int(len(row_payloads)),
                selected_drive_id_suffix=did[-16:],
                parent_path=pth[:500],
                parent_item_id_suffix=str(out["item_id"])[-16:],
                reason=str(out["reason"])[:200],
            )
            log_info("destination_graph_union_root_mode_folder_root", top_level_count=int(len(row_payloads)))
            return out
        g = getattr(self, "graph", None)
        if g is None or not getattr(g, "token", None):
            out["reason"] = "no_graph_or_token"
            log_info(
                "destination_graph_union_root_target_skipped",
                mode="library_root",
                top_level_count=int(len(row_payloads)),
                selected_drive_id_suffix=did[-16:],
                parent_path="",
                parent_item_id_suffix="",
                reason=str(out["reason"])[:200],
            )
            return out
        try:
            root_item = g.get_drive_root_item(did)  # type: ignore[union-attr, unused-ignore]
        except Exception as exc:
            out["reason"] = f"get_drive_root_item_failed:{exc!s}"[:200]
            log_info(
                "destination_graph_union_root_target_skipped",
                mode="library_root",
                top_level_count=int(len(row_payloads)),
                selected_drive_id_suffix=did[-16:],
                parent_path="",
                parent_item_id_suffix="",
                reason=str(out["reason"])[:200],
            )
            return out
        if not isinstance(root_item, dict) or not str(root_item.get("id") or "").strip():
            out["reason"] = "no_drive_root_item_id"
            log_info(
                "destination_graph_union_root_target_skipped",
                mode="library_root",
                top_level_count=int(len(row_payloads)),
                selected_drive_id_suffix=did[-16:],
                parent_path="",
                parent_item_id_suffix="",
                reason=str(out["reason"])[:200],
            )
            return out
        out["mode"] = "library_root"
        out["parent_index"] = QModelIndex()
        out["item_id"] = str(root_item.get("id") or "").strip()
        out["item_id_is_drive_root"] = True
        out["parent_canonical_path"] = ""
        out["reason"] = "no_single_graph_hub_use_drive_root_children"
        log_info(
            "destination_graph_union_root_target_detected",
            mode="library_root",
            top_level_count=int(len(row_payloads)),
            selected_drive_id_suffix=did[-16:],
            parent_path="",
            parent_item_id_suffix=str(out["item_id"])[-16:],
            reason=str(out["reason"])[:200],
        )
        log_info("destination_graph_union_root_mode_library_root", top_level_count=int(len(row_payloads)))
        return out

    def _destination_start_graph_library_root_child_union_worker(self, det: dict[str, Any]) -> bool:
        if not destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            return False
        g = getattr(self, "graph", None)
        if g is None or not getattr(g, "token", None):
            return False
        did = str(det.get("drive_id") or "").strip()
        iid = str(det.get("item_id") or "").strip()
        if not did or not iid or not det.get("item_id_is_drive_root"):
            return False
        panel_key = "destination"
        pending_key = f"{did}:{iid}"
        worker_key = f"{panel_key}:{iid}"
        if self._folder_load_worker_thread_running(worker_key):
            self.pending_folder_loads[panel_key].add(pending_key)
            return False
        if pending_key in self.pending_folder_loads[panel_key]:
            return False
        if len(self.pending_folder_loads.get(panel_key, set())) >= _graph_destination_child_load_max_active():
            return False
        self.pending_folder_loads[panel_key].add(pending_key)
        worker_context = {
            "site_id": "",
            "site_name": "",
            "library_id": did,
            "library_name": "",
            "tree_role": panel_key,
            "parent_item_path": "",
            "cache_only": False,
            "_graph_request_perf": time.perf_counter(),
        }
        worker = FolderLoadWorker(self.graph, panel_key, did, iid, worker_context)
        worker_entry = self._register_folder_worker(
            worker_key,
            worker,
            None,
            pending_key=pending_key,
            destination_folder_parent_persistent=None,
            destination_graph_union_merge_at_model_root=True,
            graph_union_mode="library_root",
            graph_child_union_bootstrap=True,
        )
        worker.success.connect(
            lambda payload, worker_id=worker_entry["id"]: self._safe_invoke(
                "folder_worker.success", self.on_folder_load_success, payload, worker_id
            )
        )
        worker.error.connect(
            lambda payload, worker_id=worker_entry["id"]: self._safe_invoke(
                "folder_worker.error", self.on_folder_load_error, payload, worker_id
            )
        )
        worker.finished.connect(
            lambda key=worker_key, worker_id=worker_entry["id"]: self._safe_invoke(
                "folder_worker.finished", self.on_folder_worker_finished, key, worker_id
            )
        )
        worker.start()
        log_info(
            "destination_graph_library_root_child_union_dispatched",
            drive_id_suffix=did[-16:],
            item_id_suffix=iid[-16:],
        )
        return True

    def _destination_try_destination_graph_child_union_bootstrap(self) -> None:
        """One-level Graph :meth:`/children` union: folder-root (under one hub) or library-root (drive root)."""
        if not destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            return
        if not getattr(self, "graph", None) or not getattr(self.graph, "token", None):
            return
        m = getattr(self, "destination_planning_model", None)
        if m is None or not hasattr(m, "rowCount"):
            return
        det = self._destination_determine_graph_union_root_target()
        mode = str(det.get("mode") or "")
        if mode not in ("folder_root", "library_root"):
            return
        if mode == "library_root":
            self._destination_start_graph_library_root_child_union_worker(det)
            return
        p_ix = det.get("parent_index")
        if p_ix is None or not isinstance(p_ix, QModelIndex) or not p_ix.isValid():
            return
        pl = self._destination_model_index_user_role_dict(p_ix)
        if not str(pl.get("id") or "").strip():
            return
        path_ex = str(
            self._destination_semantic_path(pl) or pl.get("item_path") or pl.get("name") or ""
        )[:500]
        log_info("destination_graph_child_union_requested", path_excerpt=path_ex, mode="folder_root")
        fp = {
            "mode": "folder_root",
            "drive_id": str(det.get("drive_id") or "").strip(),
            "item_id": str(det.get("item_id") or "").strip(),
            "item_id_is_drive_root": False,
        }
        self._destination_start_graph_folder_load_worker_if_eligible(
            p_ix.siblingAtColumn(0) if p_ix.column() != 0 else p_ix,
            reason="destination_graph_child_union",
            trigger="destination_root_union_bootstrap",
            graph_child_union_fingerprint=fp,
        )

    def _destination_expand_request_live_graph_folder_child_load(self, col0: QModelIndex) -> None:
        """Graph authority: request /children for the expanded folder (any nesting depth)."""
        if not col0.isValid():
            log_info("destination_expand_live_folder_child_load_skipped", reason="invalid_index", gate="invalid_index")
            return
        _depth = self._destination_model_index_tree_depth(col0)
        pl_preview = dict(col0.data(Qt.UserRole) or {})
        log_info(
            "destination_deep_expand_handler_entered",
            depth=int(_depth),
            path_excerpt=str(
                self._destination_semantic_path(pl_preview)
                or pl_preview.get("item_path")
                or pl_preview.get("name")
                or ""
            )[:400],
            item_id_suffix=str(pl_preview.get("id") or "")[-16:],
            drive_id_suffix=str(self._resolve_tree_item_drive_id("destination", pl_preview) or "")[-16:],
        )
        pl = dict(col0.data(Qt.UserRole) or {})
        name_excerpt = str(pl.get("name", "") or "")[:120]
        drive_id = self._resolve_tree_item_drive_id("destination", pl)
        item_id = str(pl.get("id", "") or "").strip()
        dsfx = str(drive_id)[-16:] if len(str(drive_id)) > 16 else str(drive_id)
        isfx = str(item_id)[-16:] if len(str(item_id)) > 16 else str(item_id)
        model = getattr(self, "destination_planning_model", None)
        try:
            n_child_raw = int(model.rowCount(col0)) if model is not None else -1
        except Exception:
            n_child_raw = -1
        n_child = n_child_raw
        if model is not None and hasattr(model, "substantive_destination_folder_child_row_count"):
            try:
                n_child = int(model.substantive_destination_folder_child_row_count(col0))
            except Exception:
                n_child = n_child_raw
        ws = str(pl.get("workspace_row_state") or "").strip()
        is_live = self._destination_row_is_live_graph_structure(pl)
        cl = bool(pl.get("children_loaded"))
        lf = bool(pl.get("load_failed"))
        log_info(
            "destination_expand_live_folder_child_load_requested",
            name_excerpt=name_excerpt,
            drive_id_suffix=dsfx,
            item_id_suffix=isfx,
            is_live_graph_row=bool(is_live),
            workspace_row_state=ws,
            children_loaded_before_expand=cl,
            subtree_row_count_before_expand=int(n_child_raw),
            substantive_subtree_row_count_before_expand=int(n_child),
            load_failed=lf,
        )
        if lf:
            log_info(
                "destination_expand_live_folder_child_load_skipped",
                reason="load_failed",
                gate="load_failed",
                item_id_suffix=isfx,
            )
            return
        derived_ok = self._destination_row_is_graph_derived_dest_child_fetch_eligible(pl)
        if not is_live and not derived_ok:
            log_info(
                "destination_expand_live_folder_child_load_skipped",
                reason="not_live_graph_row",
                gate="not_live_graph_row",
                item_id_suffix=isfx,
            )
            log_info(
                "destination_expand_cached_graph_row_blocked",
                reason="not_live_or_graph_derived_for_child_fetch",
                gate="expand_direct_child_fetch",
                item_id_suffix=isfx,
            )
            return
        if not is_live and derived_ok:
            log_info(
                "destination_expand_cached_graph_row_allowed_for_child_load",
                item_id_suffix=isfx,
                drive_id_suffix=dsfx,
            )
        if not item_id:
            log_info("destination_expand_live_folder_missing_item_id", name_excerpt=name_excerpt, phase="expand_direct")
            log_info(
                "destination_expand_live_folder_child_load_skipped",
                reason="missing_item_id",
                gate="missing_item_id",
            )
            return
        if not drive_id:
            log_info(
                "destination_expand_live_folder_child_load_skipped",
                reason="missing_drive_id",
                gate="missing_drive_id",
            )
            return
        if cl and n_child > 0 and not self._destination_row_needs_live_graph_child_refresh(pl):
            log_info(
                "destination_expand_live_folder_already_loaded",
                name_excerpt=name_excerpt,
                subtree_row_count=int(n_child),
            )
            return
        if cl and n_child == 0:
            log_info(
                "destination_expand_live_folder_child_load_skipped",
                reason="children_loaded_but_subtree_empty_unexpected",
                gate="children_loaded_but_empty_after_preflight",
                item_id_suffix=isfx,
            )
            try:
                if model is not None and hasattr(model, "reconcile_folder_children_loaded_if_empty_subtree"):
                    model.reconcile_folder_children_loaded_if_empty_subtree(col0, reason="expand_inflight_reconcile")
                    pl2 = dict(col0.data(Qt.UserRole) or {})
                    if pl2.get("children_loaded"):
                        return
            except Exception:
                return
        ok = self._request_graph_destination_children_load(
            col0, reason="user_expand", trigger="tree_expanded_live_graph_folder"
        )
        log_info(
            "destination_deep_expand_request_result",
            depth=int(_depth),
            path_excerpt=str(
                self._destination_semantic_path(pl) or pl.get("item_path") or pl.get("name") or ""
            )[:400],
            item_id_suffix=isfx,
            drive_id_suffix=dsfx,
            children_loaded=cl,
            graph_children_verified=pl.get("graph_children_verified"),
            needs_live_child_refresh=bool(self._destination_row_needs_live_graph_child_refresh(pl)),
            workspace_row_state=ws,
            raw_child_count=int(n_child_raw),
            substantive_child_count=int(n_child),
            selected_drive_match=bool(
                str(drive_id or "").strip().casefold()
                == str(self._current_selected_destination_drive_id() or "").strip().casefold()
            ),
            request_result=bool(ok),
        )
        if ok:
            log_info(
                "destination_deep_graph_child_load_scheduled",
                depth=int(_depth),
                item_id_suffix=isfx,
                drive_id_suffix=dsfx,
            )
            log_info(
                "destination_expand_live_folder_child_load_completed",
                name_excerpt=name_excerpt,
                queued_or_started=True,
                item_id_suffix=isfx,
                drive_id_suffix=dsfx,
            )
            log_info(
                "destination_expand_live_folder_child_load_scheduled",
                name_excerpt=name_excerpt,
                item_id_suffix=isfx,
            )
        else:
            log_info(
                "destination_deep_expand_blocked",
                depth=int(_depth),
                reason="queue_or_worker_or_authority_gate",
                item_id_suffix=isfx,
            )
            log_info(
                "destination_expand_live_folder_child_load_skipped",
                reason="queue_or_worker",
                gate="queue_or_worker",
                item_id_suffix=isfx,
                name_excerpt=name_excerpt,
            )

    def _destination_expand_has_materialized_non_placeholder_children(self, index: QModelIndex) -> bool:
        """True if folder already has real child rows — never replace with a loading placeholder row."""
        model = getattr(self, "destination_planning_model", None)
        if model is None or index is None or not index.isValid():
            return False
        try:
            rc = int(model.rowCount(index))
        except Exception:
            return False
        for r in range(rc):
            try:
                cix = model.index(r, 0, index)
                pl = cix.data(Qt.UserRole) or {}
            except Exception:
                continue
            if isinstance(pl, dict) and not pl.get("placeholder"):
                return True
        return False

    def _destination_prune_pending_snapshot_branch_refresh_after_provisional_mount(self, snaps: list) -> None:
        """Drop pending snapshot branch-refresh paths already present in the model after reset_nested."""
        ps = getattr(self, "_pending_snapshot_branch_refresh", None)
        if not isinstance(ps, dict):
            return
        pending = set(ps.get("destination") or set())
        before = len(pending)
        if not pending:
            log_info(
                "snapshot_mount_forensic",
                selected_snapshot_node_count=int(self._count_tree_snapshot_nodes(snaps)),
                mounted_snapshot_node_count_after_initial_mount=int(self._count_destination_model_non_placeholder_nodes()),
                pending_branch_paths_count_before_mount=0,
                pending_branch_paths_count_after_mount=0,
                pruned_already_materialized_paths=0,
                skipped_snapshot_branches_sample=[],
            )
            return
        model = getattr(self, "destination_planning_model", None)
        if model is None or not hasattr(model, "find_indices_for_canonical_destination_path"):
            log_info(
                "snapshot_mount_forensic",
                selected_snapshot_node_count=int(self._count_tree_snapshot_nodes(snaps)),
                mounted_snapshot_node_count_after_initial_mount=int(self._count_destination_model_non_placeholder_nodes()),
                pending_branch_paths_count_before_mount=int(before),
                pending_branch_paths_count_after_mount=int(before),
                pruned_already_materialized_paths=0,
                skipped_snapshot_branches_sample=["model_or_lookup_missing"],
            )
            return
        still: set[str] = set()
        pruned_canon: list[str] = []
        skipped: list[str] = []
        for p in pending:
            raw = str(p or "").strip()
            if not raw:
                continue
            canon = self._canonical_destination_projection_path(raw)
            if not canon:
                still.add(raw)
                skipped.append("canonical_empty:" + raw[:160])
                continue
            hits = model.find_indices_for_canonical_destination_path(canon)
            if hits:
                pruned_canon.append(canon[:220])
            else:
                still.add(raw)
                skipped.append("not_in_model_after_mount:" + canon[:220])
        ps["destination"] = still
        log_info(
            "snapshot_mount_forensic",
            selected_snapshot_node_count=int(self._count_tree_snapshot_nodes(snaps)),
            mounted_snapshot_node_count_after_initial_mount=int(self._count_destination_model_non_placeholder_nodes()),
            pending_branch_paths_count_before_mount=int(before),
            pending_branch_paths_count_after_mount=len(still),
            pruned_already_materialized_paths=len(pruned_canon),
            skipped_snapshot_branches_sample=skipped[:16],
        )

    def _tree_snapshot_node_count_gt(self, snapshots, threshold: int) -> bool:
        """True if total snapshot nodes strictly exceed threshold. Stops after threshold+1 nodes."""
        if threshold < 0:
            threshold = 0
        count = 0

        def _walk(snapshot_node) -> None:
            nonlocal count
            if count > threshold:
                return
            if not isinstance(snapshot_node, dict):
                return
            count += 1
            if count > threshold:
                return
            for child_snapshot in list(snapshot_node.get("children", []) or []):
                _walk(child_snapshot)
                if count > threshold:
                    return

        for snapshot in list(snapshots or []):
            _walk(snapshot)
            if count > threshold:
                return True
        return False

    def _count_root_payload_nodes(self, items):
        count = 0

        def _walk(payload_node):
            nonlocal count
            if not isinstance(payload_node, dict):
                return
            count += 1
            for child_node in list(payload_node.get("children", []) or []):
                _walk(child_node)

        for item in list(items or []):
            _walk(item)
        return count

    def _snapshot_refresh_targets_for_panel(self, panel_key, ui_state):
        raw_paths = set(ui_state.get(f"{panel_key}_expanded_paths", set()) or set())
        if panel_key == "destination":
            return {self._canonical_destination_projection_path(path) for path in raw_paths if path}
        return {self._canonical_source_projection_path(path) for path in raw_paths if path}

    def _snapshot_refresh_targets_from_snapshot(self, panel_key, snapshots):
        targets = set()
        source_depth_limit = 3

        def _walk(snapshot_node):
            if not isinstance(snapshot_node, dict):
                return
            data = dict(snapshot_node.get("data", {}) or {})
            item_path = str(
                data.get("item_path")
                or data.get("display_path")
                or data.get("semantic_path")
                or ""
            ).strip()
            is_folder = bool(data.get("is_folder"))
            is_expanded = bool(snapshot_node.get("expanded", False))
            if item_path and is_folder and is_expanded:
                if panel_key == "destination":
                    targets.add(self._canonical_destination_projection_path(item_path))
                else:
                    canonical_path = self._canonical_source_projection_path(item_path)
                    if self._source_branch_depth(canonical_path) <= source_depth_limit:
                        targets.add(canonical_path)
            for child_snapshot in list(snapshot_node.get("children", []) or []):
                _walk(child_snapshot)

        for snapshot in list(snapshots or []):
            _walk(snapshot)
        return {path for path in targets if path}

    def _schedule_snapshot_branch_refresh(self, panel_key, delay_ms=0):
        pending = self._pending_snapshot_branch_refresh.get(panel_key, set())
        if not pending or self._snapshot_branch_refresh_scheduled.get(panel_key):
            return
        self._snapshot_branch_refresh_scheduled[panel_key] = True

        def _run():
            self._snapshot_branch_refresh_scheduled[panel_key] = False
            self._process_snapshot_branch_refresh(panel_key)

        QTimer.singleShot(max(0, int(delay_ms)), _run)

    def _process_snapshot_branch_refresh(self, panel_key):
        if panel_key == "source" and self._expand_all_pending.get("source"):
            # Avoid competing branch refresh traversal during source expand-all.
            self._schedule_snapshot_branch_refresh(panel_key, delay_ms=220)
            return
        if panel_key == "destination" and self._destination_restore_branch_refresh_paused_for_authority():
            self._log_restore_phase(
                "restore_pipeline_paused_for_authority",
                panel_key="destination",
            )
            return
        if panel_key == "destination":
            _sfn = getattr(self, "_destination_user_scroll_interaction_active", None)
            if callable(_sfn) and _sfn():
                delay = max(160, int(getattr(self, "_destination_tree_scroll_idle_ms", 280) or 280))
                self._schedule_snapshot_branch_refresh(panel_key, delay_ms=delay)
                return
        if panel_key == "destination":
            self._destination_lifecycle_trace_TEMP(
                fn="_process_snapshot_branch_refresh",
                reason="tick_start",
                step_kind="state_restore",
                extra="expand_existing_plus_lazy_folder_load_only",
            )
        pending_paths = set(self._pending_snapshot_branch_refresh.get(panel_key, set()) or set())
        if not pending_paths:
            if panel_key == "destination":
                if self._destination_tree_shows_authority_pending_shell():
                    _msg, _load = self._destination_status_message_authority_pending_or_reconcile()
                    self._set_tree_status_message(panel_key, _msg, loading=_load)
                elif self._destination_live_refresh_still_blocked():
                    self._set_tree_status_message(
                        panel_key,
                        "Restoring projections and expanded branches…",
                        loading=True,
                    )
                else:
                    self._set_tree_status_message(panel_key, "Saved branches are up to date.", loading=False)
            else:
                self._set_tree_status_message(panel_key, "Saved branches are up to date.", loading=False)
            if panel_key == "destination":
                self._destination_lifecycle_trace_TEMP(
                    fn="_process_snapshot_branch_refresh",
                    reason="saved_branches_up_to_date",
                    step_kind="state_restore",
                    extra="pending_empty",
                )
            return

        tree = getattr(self, f"{panel_key}_tree_widget", None)
        if tree is None:
            return

        find_item = (
            self._find_visible_destination_item_by_path
            if panel_key == "destination"
            else self._find_visible_source_item_by_path
        )
        remaining_paths = set()
        started_load = False
        started_count = 0
        max_starts_per_tick = 2 if panel_key == "destination" else 2

        sorted_pending = sorted(
            pending_paths,
            key=lambda path: (
                0 if panel_key == "destination" and self._destination_snapshot_path_should_prioritize_overlays(path) else 1,
                len(self._path_segments(path)),
            ),
        )
        source_item_map: dict[str, Any] | None = None
        if panel_key == "source" and sorted_pending:
            canon_src = {
                self._canonical_source_projection_path(p)
                for p in sorted_pending
                if self._canonical_source_projection_path(p)
            }
            if canon_src:
                source_item_map, _stats = self._map_visible_source_items_by_canonical_paths(canon_src)

        for target_path in sorted_pending:
            if source_item_map is not None:
                ck = self._canonical_source_projection_path(target_path)
                item = source_item_map.get(ck) if ck else None
                if item is None:
                    item = find_item(target_path)
            else:
                item = find_item(target_path)
                if item is None and panel_key == "destination":
                    dm = getattr(self, "destination_planning_model", None)
                    canon_d = self._canonical_destination_projection_path(target_path)
                    if dm is not None and canon_d:
                        _hits = dm.find_indices_for_canonical_destination_path(canon_d)
                        if _hits:
                            item = _hits[0]
            if item is None:
                remaining_paths.add(target_path)
                continue

            if panel_key == "source":
                node_data = self._source_tree_row_payload(item)
            else:
                # Destination can be either QTreeWidgetItem (QTreeWidget) or QModelIndex (QTreeView).
                if isinstance(item, QModelIndex):
                    node_data = item.data(Qt.UserRole) or {}
                else:
                    node_data = item.data(0, Qt.UserRole) or {}
            if node_data.get("placeholder") or not node_data.get("is_folder"):
                continue

            if panel_key == "source" and isinstance(item, QModelIndex):
                tree.expand(item)
            elif panel_key == "destination" and isinstance(item, QModelIndex):
                tree.expand(item)
            else:
                tree.expandItem(item)
            if bool(node_data.get("load_failed")):
                continue
            if not bool(node_data.get("children_loaded")):
                started_load = self._ensure_tree_item_load_started(panel_key, item) or started_load
                remaining_paths.add(target_path)
                if started_load:
                    started_count += 1
                    if started_count >= max_starts_per_tick:
                        break

        self._pending_snapshot_branch_refresh[panel_key] = remaining_paths
        if panel_key == "destination" and started_count > 0:
            _dslots = sum(
                1 for k in (self.folder_load_workers or {}) if str(k).startswith("destination:")
            )
            self._log_restore_phase(
                "destination_snapshot_worker_scheduling_tick",
                max_starts_per_tick=int(max_starts_per_tick),
                started_this_tick=int(started_count),
                remaining_pending=len(remaining_paths),
                active_destination_worker_slots=int(_dslots),
                pending_destination_keys=len(self.pending_folder_loads.get("destination", set()) or ()),
            )
        if remaining_paths and (
            started_load
            or bool(self.pending_folder_loads.get(panel_key))
            or bool(self.root_load_workers.get(panel_key))
        ):
            completed_count = max(0, len(pending_paths) - len(remaining_paths))
            total_count = max(len(pending_paths), completed_count)
            self._set_tree_status_message(
                panel_key,
                f"Refreshing saved branches... ({completed_count}/{total_count})",
                loading=True,
            )
            self._schedule_snapshot_branch_refresh(panel_key, delay_ms=150)
        else:
            if panel_key == "destination":
                if self._destination_tree_shows_authority_pending_shell():
                    _msg_b, _load_b = self._destination_status_message_authority_pending_or_reconcile()
                    self._set_tree_status_message(panel_key, _msg_b, loading=_load_b)
                elif self._destination_live_refresh_still_blocked():
                    self._set_tree_status_message(
                        panel_key,
                        "Restoring projections and expanded branches…",
                        loading=True,
                    )
                else:
                    self._set_tree_status_message(panel_key, "Saved branches are up to date.", loading=False)
            else:
                self._set_tree_status_message(panel_key, "Saved branches are up to date.", loading=False)

    def _capture_child_path_set(self, item):
        child_paths = set()
        if item is None:
            return child_paths
        for index in range(item.childCount()):
            child = item.child(index)
            child_data = child.data(0, Qt.UserRole) or {}
            if child_data.get("placeholder"):
                continue
            child_path = self._tree_item_path(child_data)
            if child_path:
                child_paths.add(str(child_path))
        return child_paths

    def _begin_session_workspace_ui_restore(self):
        try:
            self._destination_session_snapshot_force_live_once = False
            self._destination_runtime_snapshot_force_refresh_during_tick = False
        except Exception:
            pass
        ui_state = self._session_workspace_ui_state()
        tree_snapshots = self._session_workspace_tree_snapshots()
        dest_snaps_session = list(tree_snapshots.get("destination", []) or [])
        mm = getattr(self, "memory_manager", None)
        sidecar = mm.read_workspace_snapshot_optional() if mm is not None else None
        dest_snaps, sel_src, n_sess_nodes, n_side_nodes, _meta = self._select_destination_tree_snapshot_for_startup(
            dest_snaps_session,
            workspace_sidecar=sidecar,
        )
        try:
            self._destination_workspace_sidecar_destination_node_count_at_startup = int(n_side_nodes)
        except Exception:
            self._destination_workspace_sidecar_destination_node_count_at_startup = 0
        try:
            self._destination_startup_allowed_semantic_root_segments_cf = allowed_semantic_root_segments_cf_from_snapshot(
                dest_snaps
            )
        except Exception:
            self._destination_startup_allowed_semantic_root_segments_cf = set()
        if sel_src.startswith("Workspace") and isinstance(self._draft_shell_state, SessionState):
            self._draft_shell_state.DestinationTreeSnapshot = list(dest_snaps)
        try:
            n_final = int(self._count_tree_snapshot_nodes(dest_snaps))
        except Exception:
            n_final = -1
        try:
            self._destination_final_startup_destination_snapshot_node_count = int(n_final)
        except Exception:
            self._destination_final_startup_destination_snapshot_node_count = -1
        self._destination_destination_snapshot_persist_startup_unlocked = False
        mmp = getattr(mm, "paths", {}) if mm is not None else {}
        log_info(
            "snapshot_restore_forensic",
            session_json_destination_snapshot_node_count_loaded=int(n_sess_nodes),
            workspace_sidecar_destination_snapshot_node_count_loaded=int(n_side_nodes),
            session_json_destination_snapshot_top_level_count=len(dest_snaps_session),
            workspace_sidecar_destination_snapshot_top_level_count=(
                len(list(sidecar.get("destination_tree_snapshot") or [])) if isinstance(sidecar, dict) else 0
            ),
            final_startup_selected_snapshot_source=str(sel_src),
            final_startup_selected_snapshot_count=int(n_final),
            session_state_path=str(mmp.get("session") or "") if mmp else "",
            workspace_sidecar_path=str(mmp.get("workspace_snapshot") or "") if mmp else "",
            runtime_destination_snapshot_top_level_pre_restore=len(
                list((getattr(self, "_runtime_session_tree_snapshots", {}) or {}).get("destination", []) or [])
            ),
        )
        try:
            self._destination_memory_active_vs_rich_candidate_audit_readonly()
        except Exception as exc:
            self._log_restore_exception("destination_memory_active_rich_candidate_audit", exc)
        if self._destination_branch_forensic_enabled() and mm is not None:
            log_info(
                "destination_branch_forensic",
                stage="startup_snapshot_source_precedence",
                session_state_path=str(mmp.get("session") or ""),
                workspace_sidecar_path=str(mmp.get("workspace_snapshot") or ""),
                startup_destination_snapshot_source=str(sel_src),
                startup_destination_snapshot_node_count=int(n_final),
                startup_destination_snapshot_top_level_count=len(dest_snaps),
            )
        destination_stamp_snapshot_tree_workspace_state(dest_snaps)
        self._runtime_session_tree_snapshots = {
            "source": list(tree_snapshots.get("source", []) or []),
            "destination": dest_snaps,
        }
        self._apply_planning_header_collapsed_state(bool(ui_state.get("planning_header_collapsed", False)))
        self._apply_workspace_tabs_collapsed_state(bool(ui_state.get("workspace_panel_collapsed", False)))
        has_state = any([
            ui_state["source_expanded_paths"],
            ui_state["destination_expanded_paths"],
            ui_state["source_selected_path"],
            ui_state["destination_selected_path"],
            ui_state["source_expanded_all"],
            ui_state["destination_expanded_all"],
        ])
        has_tree_snapshots = any([
            tree_snapshots.get("source"),
            dest_snaps,
        ])
        if not has_state and not has_tree_snapshots:
            self._pending_session_workspace_ui_state = None
            self._pending_session_tree_snapshots = {}
            self._runtime_session_tree_snapshots = {"source": [], "destination": []}
            self._pending_session_workspace_restore_panels = set()
            self._pending_workspace_post_expand_selection = {"source": "", "destination": ""}
            self._workspace_restore_expanded_all_intent = {"source": False, "destination": False}
            self._destination_restore_session_expanded_paths_intent = set()
            self._destination_restore_session_selected_path_intent = ""
            return

        # Only treat *explicit* expand-all as eager projection intent. Using a path-count
        # threshold falsely flagged normal sessions (several folders expanded while browsing) as
        # expand-all, which forced every [Allocated] branch to materialize thousands of projected
        # rows during destination bind and froze the UI for minutes.
        self._workspace_restore_expanded_all_intent = {
            "source": bool(ui_state.get("source_expanded_all", False)),
            "destination": bool(ui_state.get("destination_expanded_all", False)),
        }

        pending_panels = set()
        state = self._draft_shell_state if isinstance(self._draft_shell_state, SessionState) else SessionState()
        if state.SelectedSourceLibrary or getattr(state, "SelectedSourceLibraryId", ""):
            pending_panels.add("source")
        if state.SelectedDestinationLibrary or getattr(state, "SelectedDestinationLibraryId", ""):
            pending_panels.add("destination")

        self._pending_session_workspace_ui_state = ui_state
        self._pending_session_tree_snapshots = {
            panel_key: (
                list(tree_snapshots.get(panel_key, []) or [])
                if panel_key != "destination"
                else list(dest_snaps)
            )
            for panel_key in ("source", "destination")
            if (tree_snapshots.get(panel_key) if panel_key != "destination" else dest_snaps)
        }
        _src_sess_snaps = list((self._pending_session_tree_snapshots or {}).get("source") or [])
        if _src_sess_snaps:
            self._source_snapshot_shell_prearmed = True
            log_info(
                "source_snapshot_shell_prearmed",
                phase="begin_session_workspace_ui_restore",
                source_snapshot_roots=len(_src_sess_snaps),
            )
        source_snapshot_targets = self._snapshot_refresh_targets_from_snapshot("source", self._pending_session_tree_snapshots.get("source", []))
        destination_snapshot_targets = self._snapshot_refresh_targets_from_snapshot("destination", self._pending_session_tree_snapshots.get("destination", []))
        dest_intent: set[str] = {
            str(p).strip() for p in (ui_state.get("destination_expanded_paths", set()) or set()) if str(p).strip()
        }
        if "destination" in pending_panels:
            dest_intent |= {str(p).strip() for p in destination_snapshot_targets if str(p).strip()}
        self._destination_restore_session_expanded_paths_intent = dest_intent
        self._destination_restore_session_selected_path_intent = str(
            ui_state.get("destination_selected_path", "") or ""
        ).strip()
        self._pending_snapshot_branch_refresh = {
            "source": (
                source_snapshot_targets
                if ui_state.get("source_expanded_all", False)
                else self._snapshot_refresh_targets_for_panel("source", ui_state)
            ) if "source" in pending_panels else set(),
            "destination": (
                destination_snapshot_targets
                if ui_state.get("destination_expanded_all", False)
                else self._snapshot_refresh_targets_for_panel("destination", ui_state)
            ) if "destination" in pending_panels else set(),
        }
        self._pending_session_workspace_restore_panels = pending_panels
        self._pending_workspace_post_expand_selection = {"source": "", "destination": ""}
        if "destination" in pending_panels:
            self._destination_lifecycle_trace_TEMP(
                fn="_begin_session_workspace_ui_restore",
                reason="session_workspace_restore_scheduled",
                step_kind="state_restore",
                extra=f"dest_snapshots={len(self._pending_session_tree_snapshots.get('destination', []) or [])};pending_branch_paths={len(self._pending_snapshot_branch_refresh.get('destination', set()) or set())}",
            )

    def _restore_workspace_tree_panel_state(self, panel_key, ui_state):
        if not ui_state:
            return
        expanded_paths = set(ui_state.get(f"{panel_key}_expanded_paths", set()) or set())
        if panel_key == "destination":
            snaps = list((self._pending_session_tree_snapshots or {}).get("destination", []) or []) or list(
                (getattr(self, "_runtime_session_tree_snapshots", {}) or {}).get("destination", []) or []
            )
            if snaps:
                expanded_paths |= self._snapshot_refresh_targets_from_snapshot("destination", snaps)
        selected_path = str(ui_state.get(f"{panel_key}_selected_path", "") or "")
        expanded_all = bool(ui_state.get(f"{panel_key}_expanded_all", False))
        self._restore_expanded_tree_paths(panel_key, expanded_paths)
        self._restore_selected_tree_path(panel_key, selected_path)
        if expanded_all:
            self._restore_panel_expanded_all_state(panel_key)
        self._refresh_expand_all_button_for_panel(panel_key)

    def _restore_panel_expanded_all_state(self, panel_key):
        self._destination_restore_materialization_user_paused = False
        if self._panel_is_expanded_all(panel_key):
            self._refresh_expand_all_button_for_panel(panel_key)
            return
        cached_snapshots = (
            self._pending_session_tree_snapshots.get(panel_key)
            or self._runtime_tree_snapshot_for_panel(panel_key)
        )
        if cached_snapshots:
            visible_node_count = self._count_expandable_tree_nodes(panel_key)
            if self._tree_snapshot_node_count_gt(cached_snapshots, visible_node_count):
                status_message = (
                    "Expanded from local snapshot. Refreshing live content..."
                )
                restored = self._restore_tree_items_snapshot_if_reasonable(
                    panel_key, cached_snapshots, status_message, context="expanded_all_restore"
                )
                if not restored:
                    self._schedule_snapshot_branch_refresh(panel_key, delay_ms=400)
            self._refresh_expand_all_button_for_panel(panel_key)
            self._set_tree_status_message(
                panel_key,
                "Expanded from local snapshot. Refreshing live content...",
                loading=bool(self._pending_snapshot_branch_refresh.get(panel_key)),
            )
            return
        if self._can_fast_bulk_expand(panel_key):
            self._fast_expand_all_loaded_tree(panel_key)
            return
        if panel_key == "source":
            self._begin_source_model_expand_all()
            return
        if panel_key == "destination":
            if getattr(self, "_destination_root_prime_pending", False):
                return
            self._begin_destination_model_expand_all()
            return

    def on_site_selector_changed(
        self,
        selector_group,
        *,
        force=False,
        chain_library: bool = True,
        destination_site_clear_reason: str | None = None,
    ):
        try:
            if self._pending_login_restore_args and not force:
                self._log_restore_phase(
                    "selector_change_deferred_for_pending_login_restore",
                    selector_group=selector_group,
                    handler="on_site_selector_changed",
                    ui_rebind_in_progress=self._memory_ui_rebind_in_progress,
                )
                return
            if self._suppress_selector_change_handlers and not force:
                self._log_restore_phase(
                    "selector_change_suppressed",
                    selector_group=selector_group,
                    handler="on_site_selector_changed",
                    ui_rebind_in_progress=self._memory_ui_rebind_in_progress,
                )
                return

            if selector_group == "source":
                site_selector = self.planning_inputs.get("Source Site")
                library_selector = self.planning_inputs.get("Source Library")
            else:
                site_selector = self.planning_inputs.get("Destination Site")
                library_selector = self.planning_inputs.get("Destination Library")

            if site_selector is None or library_selector is None:
                return

            if not isinstance(getattr(self, "_saved_library_selector_hydration_attempt", None), dict):
                self._saved_library_selector_hydration_attempt = {"source": 0, "destination": 0}
            self._saved_library_selector_hydration_attempt[selector_group] = 0
            self._populate_library_selector_for_group(selector_group)
            if selector_group == "destination":
                site_sel = self.planning_inputs.get("Destination Site")
                raw_site = site_sel.currentData() if site_sel is not None else None
                new_id = self._canonical_destination_site_identity_from_data(
                    raw_site if isinstance(raw_site, dict) else None
                )
                prev_id = str(getattr(self, "_destination_last_memory_site_id", "") or "").strip()
                initial_bind = (not prev_id) and bool(new_id)
                site_changed_for_memory = (
                    bool(prev_id or new_id)
                    and (prev_id.casefold() != new_id.casefold())
                    and (not initial_bind)
                )
                if site_changed_for_memory:
                    _site_clear_reason = str(destination_site_clear_reason or "user_site_change").strip() or "user_site_change"
                    self._destination_clear_stale_snapshot_state_on_site_change(
                        selected_site=raw_site if isinstance(raw_site, dict) else None,
                        previous_site_id=prev_id,
                        new_site_id=new_id,
                        reason=_site_clear_reason,
                    )
                log_info(
                    "destination_selected_site_identity_resolved",
                    resolved_site_suffix=new_id[-16:] if len(new_id) > 16 else new_id,
                    previous_site_suffix=prev_id[-16:] if len(prev_id) > 16 else prev_id,
                    initial_destination_site_bind=bool(initial_bind),
                    site_memory_reset=bool(site_changed_for_memory),
                )
                self._destination_last_memory_site_id = new_id
                self._maybe_schedule_legacy_snapshot_identity_inference_retry("destination_site_stabilized")
            if chain_library:
                self.on_library_selector_changed(selector_group, force=force)
        except Exception as exc:
            self._log_restore_exception("on_site_selector_changed", exc)

    def on_library_selector_changed(self, selector_group, *, force=False):
        try:
            self._log_library_restore_step("step_01_enter", selector_group=selector_group, force=force)
            if self._pending_login_restore_args and not force:
                self._log_restore_phase(
                    "selector_change_deferred_for_pending_login_restore",
                    selector_group=selector_group,
                    handler="on_library_selector_changed",
                    ui_rebind_in_progress=self._memory_ui_rebind_in_progress,
                )
                return
            if self._suppress_selector_change_handlers and not force:
                self._log_restore_phase(
                    "selector_change_suppressed",
                    selector_group=selector_group,
                    handler="on_library_selector_changed",
                    ui_rebind_in_progress=self._memory_ui_rebind_in_progress,
                )
                return

            if selector_group == "source":
                self._log_library_restore_step("step_02_resolve_source_selectors_enter", selector_group=selector_group)
                site_selector = self.planning_inputs.get("Source Site")
                library_selector = self.planning_inputs.get("Source Library")
                self.bottom_source.setText(f"Source: {library_selector.currentText()}" if library_selector else "Source: Not Set")
                self._log_library_restore_step("step_02_resolve_source_selectors_exit", selector_group=selector_group, has_site_selector=site_selector is not None, has_library_selector=library_selector is not None)
            else:
                self._log_library_restore_step("step_02_resolve_destination_selectors_enter", selector_group=selector_group)
                site_selector = self.planning_inputs.get("Destination Site")
                library_selector = self.planning_inputs.get("Destination Library")
                self.bottom_destination.setText(f"Destination: {library_selector.currentText()}" if library_selector else "Destination: Not Set")
                self._log_library_restore_step("step_02_resolve_destination_selectors_exit", selector_group=selector_group, has_site_selector=site_selector is not None, has_library_selector=library_selector is not None)

            self._log_library_restore_step("step_03_read_current_data_enter", selector_group=selector_group)
            selected_site = site_selector.currentData() if site_selector is not None else None
            selected_library = library_selector.currentData() if library_selector is not None else None
            self._log_library_restore_step(
                "step_03_read_current_data_exit",
                selector_group=selector_group,
                site_is_dict=isinstance(selected_site, dict),
                library_is_dict=isinstance(selected_library, dict),
                library_id=(selected_library or {}).get("id", "") if isinstance(selected_library, dict) else "",
                library_name=(selected_library or {}).get("name", "") if isinstance(selected_library, dict) else "",
            )
            if not isinstance(selected_site, dict) or not isinstance(selected_library, dict) or not selected_library.get("id"):
                self._log_library_restore_step("step_04_invalid_selection_enter", selector_group=selector_group)
                self.set_tree_placeholder(
                    selector_group,
                    "Select a library to load root content.",
                )
                if selector_group == "destination" and self._planning_browse_mode("destination") == "sharepoint":
                    self._destination_suppress_stale_visible_tree_if_needed()
                self.update_selector_context_labels()
                self._log_library_restore_step("step_04_invalid_selection_exit", selector_group=selector_group)
                return

            if self._planning_browse_mode(selector_group) == "sharepoint" and not self._graph_token_ready_for_sharepoint():
                self._log_library_restore_step("step_04b_auth_required_enter", selector_group=selector_group)
                side = "destination" if selector_group == "destination" else "source"
                service_context = "destination_sharepoint" if selector_group == "destination" else "source_sharepoint"
                self.set_tree_placeholder(
                    selector_group,
                    "Sign in to Microsoft 365 to load this SharePoint library.",
                )
                reply = QMessageBox.question(
                    self,
                    "Sign in required",
                    f"This {side} uses SharePoint. Sign in with Microsoft 365 in the app to load the library.",
                    QMessageBox.Yes | QMessageBox.No,
                    QMessageBox.Yes,
                )
                self.update_selector_context_labels()
                if reply != QMessageBox.Yes:
                    self._log_library_restore_step("step_04b_auth_required_declined", selector_group=selector_group)
                    return
                self._pending_library_reload_after_auth = selector_group
                self.handle_connect(allow_prompt_for_email=True, service_context=service_context)
                self._log_library_restore_step("step_04b_auth_required_started", selector_group=selector_group)
                return

            _bind_guard = self._planning_should_defer_or_block_wrong_library_bind(
                selector_group,
                selected_library=selected_library,
                library_selector=library_selector,
            )
            if _bind_guard == "deferred":
                if selector_group == "destination":
                    self.set_tree_placeholder(
                        "destination",
                        "Waiting for the saved destination library to appear in the list…",
                    )
                    if self._planning_browse_mode("destination") == "sharepoint":
                        self._destination_suppress_stale_visible_tree_if_needed()
                else:
                    self.set_tree_placeholder(
                        "source",
                        "Waiting for the saved source library to appear in the list…",
                    )
                self.update_selector_context_labels()
                self._schedule_saved_library_selector_hydration_retry(selector_group)
                return
            if _bind_guard == "blocked":
                if selector_group == "destination":
                    self.set_tree_placeholder(
                        "destination",
                        "Choose the destination library that matches your session — the current selection is not the saved destination drive.",
                    )
                    if self._planning_browse_mode("destination") == "sharepoint":
                        self._destination_suppress_stale_visible_tree_if_needed()
                else:
                    self.set_tree_placeholder(
                        "source",
                        "Choose the source library that matches your session — the current selection is not the saved source drive.",
                    )
                self.update_selector_context_labels()
                return

            self._log_library_restore_step("step_05_update_labels_enter", selector_group=selector_group)
            self.update_selector_context_labels()
            self._log_library_restore_step("step_05_update_labels_exit", selector_group=selector_group)
            if selector_group == "destination":
                self._destination_suppress_provisional_placeholder_preservation = False
                self._destination_last_memory_site_id = self._canonical_destination_site_identity_from_data(
                    selected_site if isinstance(selected_site, dict) else None
                )
                self._destination_clear_stale_snapshot_state_on_library_change(
                    selected_site=selected_site if isinstance(selected_site, dict) else None,
                    selected_library=selected_library if isinstance(selected_library, dict) else None,
                )
                # Valid destination library is bound: relax strict missing-drive rejection before filtering so
                # legacy rows without DestinationDriveId are kept unless an explicit drive/site mismatch exists.
                self._destination_strict_planning_identity_required = False
                self._destination_filter_planning_memory_to_selected_identity(context="on_library_selector_valid")
            self._log_library_restore_step("step_06_load_library_root_enter", selector_group=selector_group)
            self.load_library_root(selector_group, selected_site, selected_library)
            if not getattr(self, "_memory_restore_in_progress", False):
                self._schedule_live_root_refresh(
                    selector_group,
                    delay_ms=700,
                    site=selected_site,
                    library=selected_library,
                )
            self._log_library_restore_step("step_06_load_library_root_exit", selector_group=selector_group)
            self._log_library_restore_step("step_07_exit", selector_group=selector_group)
        except Exception as exc:
            self._log_restore_exception("on_library_selector_changed", exc)

    def reset_root_panels(self):
        self.pending_root_drive_ids = {"source": "", "destination": ""}
        self.pending_root_site_ids = {"source": "", "destination": ""}
        self.pending_folder_loads = {"source": set(), "destination": set()}
        self._destination_clear_graph_child_load_backlog()
        self._pending_source_navigation = None
        self._pending_destination_navigation = None
        self._workspace_restore_expanded_all_intent = {"source": False, "destination": False}
        self._expand_all_pending = {"source": False, "destination": False}
        self._expand_all_queue = {"source": deque(), "destination": deque()}
        self._expand_all_source_model_queue = deque()
        self._expand_all_destination_model_queue = deque()
        self._expand_all_seen = {"source": set(), "destination": set()}
        self._expand_all_requeue_attempts = {"source": {}, "destination": {}}
        self._expand_all_deferred_refresh = {"source": False, "destination": False}
        self._source_column_refresh_pending = False
        self._source_expand_all_folder_load_log_counter = 0
        self._expand_all_status_last_update_ms = {"source": 0, "destination": 0}
        for timer in getattr(self, "_expand_all_timers", {}).values():
            timer.stop()
        self.active_root_request_signatures = {"source": None, "destination": None}
        self.loaded_root_request_signatures = {"source": None, "destination": None}
        self._reset_full_count_state()
        self._reset_destination_full_tree_state()
        self.set_tree_placeholder("source", "Select a source library to load root content.")
        self.set_tree_placeholder("destination", "Select a destination library to load root content.")
        self._set_expand_all_button_label("source", False)
        self._set_expand_all_button_label("destination", False)
        self._destination_restore_materialization_user_paused = False
        self._schedule_progress_summary_refresh()

    def _set_planning_site_selectors_no_selection(self) -> None:
        """Clear source/destination site picker selection (no site chosen until the user picks again)."""
        for label in ("Source Site", "Destination Site"):
            selector = self.planning_inputs.get(label)
            if selector is None:
                continue
            selector.blockSignals(True)
            selector.setCurrentIndex(-1)
            selector.blockSignals(False)
        self.bottom_source.setText("Source: Not Set")
        self.bottom_destination.setText("Destination: Not Set")
        self.update_selector_context_labels()

    def set_tree_placeholder(self, panel_key, message):
        if panel_key == "source":
            tree = self.source_tree_widget
            status = self.source_tree_status
        else:
            tree = self.destination_tree_widget
            status = self.destination_tree_status

        if panel_key == "source":
            model = getattr(self, "source_sharepoint_model", None)
            if model is not None:
                msg_s = str(message or "").strip()
                before_fc = self._source_forensic_model_node_counts()
                suppress, forensic = self._source_loading_placeholder_shell_preservation_guard(message)
                if suppress:
                    after_fc = self._source_forensic_model_node_counts()
                    if not msg_s.lower().startswith("loading"):
                        log_info(
                            "source_placeholder_blocked_non_loading_message",
                            message_excerpt=msg_s[:160],
                            instructional_placeholder=bool(forensic.get("instructional_placeholder")),
                            action_taken=str(forensic.get("action_taken") or ""),
                        )
                        log_info(
                            "source_destructive_reset_blocked_non_loading",
                            message_excerpt=msg_s[:160],
                            mount_drive_id_suffix=str(forensic.get("mount_drive_id_suffix") or ""),
                            pending_drive_id_suffix=str(forensic.get("pending_drive_id_suffix") or ""),
                        )
                    if bool(forensic.get("pending_session_snapshot_match")) or bool(
                        forensic.get("snapshot_shell_prearmed")
                    ):
                        log_info(
                            "source_placeholder_blocked_by_pending_snapshot",
                            message_excerpt=msg_s[:160],
                            pending_session_snapshot_match=bool(forensic.get("pending_session_snapshot_match")),
                            snapshot_shell_prearmed=bool(forensic.get("snapshot_shell_prearmed")),
                        )
                        log_info(
                            "source_destructive_reset_blocked",
                            reason="pending_session_source_snapshot_or_prearm",
                            message_excerpt=msg_s[:160],
                        )
                    log_info(
                        "source_loading_placeholder_forensic",
                        before_count=int(before_fc.get("model_nodes_depth_first") or 0),
                        after_count=int(after_fc.get("model_nodes_depth_first") or 0),
                        shell_preservation_guard_active=True,
                        identity_match=True,
                        force_replace=bool(forensic.get("force_replace")),
                        action_taken="suppressed_preserve_shell",
                        mount_drive_id_suffix=str(forensic.get("mount_drive_id_suffix") or ""),
                        pending_drive_id_suffix=str(forensic.get("pending_drive_id_suffix") or ""),
                        current_drive_id_suffix=str(forensic.get("current_drive_id_suffix") or ""),
                    )
                    log_info(
                        "source_loading_placeholder_suppressed_for_startup_shell",
                        reason="same_identity_startup_shell",
                        message_excerpt=msg_s[:160],
                        mount_drive_id_suffix=str(forensic.get("mount_drive_id_suffix") or ""),
                        pending_drive_id_suffix=str(forensic.get("pending_drive_id_suffix") or ""),
                    )
                    self._set_tree_status_message(
                        panel_key,
                        msg_s or "Loading root content…",
                        loading=True,
                    )
                    try:
                        tree.setEnabled(True)
                    except Exception:
                        pass
                    if self._full_trace_enabled():
                        log_trace(
                            "tree",
                            "set_tree_placeholder",
                            panel_key=panel_key,
                            message_excerpt=msg_s[:200],
                            suppressed_for_source_startup_shell=True,
                            tree_enabled=True,
                            tree_kind="qtreeview_model",
                        )
                    return

                model.set_empty_library_message(message or "")
                after_fc = self._source_forensic_model_node_counts()
                log_info(
                    "source_loading_placeholder_forensic",
                    before_count=int(before_fc.get("model_nodes_depth_first") or 0),
                    after_count=int(after_fc.get("model_nodes_depth_first") or 0),
                    shell_preservation_guard_active=False,
                    identity_match=bool(forensic.get("identity_match")),
                    force_replace=bool(forensic.get("force_replace")),
                    action_taken="destructive_model_reset",
                    suppression_reason=str(forensic.get("action_taken") or ""),
                )
                log_info(
                    "source_loading_placeholder_destructive",
                    reason=str(forensic.get("action_taken") or "destructive_placeholder"),
                    before_nodes_depth_first=int(before_fc.get("model_nodes_depth_first") or 0),
                    after_nodes_depth_first=int(after_fc.get("model_nodes_depth_first") or 0),
                    message_excerpt=msg_s[:160],
                )
                tree.setEnabled(False)
                self._set_tree_status_message(
                    panel_key,
                    message,
                    loading=str(message or "").lower().startswith("loading"),
                )
                if self._full_trace_enabled():
                    log_trace(
                        "tree",
                        "set_tree_placeholder",
                        panel_key=panel_key,
                        message_excerpt=msg_s[:200],
                        tree_enabled=False,
                        tree_kind="qtreeview_model",
                    )
                return

        if panel_key == "destination":
            model = getattr(self, "destination_planning_model", None)
            if model is not None:
                msg_s = str(message or "").strip()
                if self._destination_memory_overlay_mode_enabled() and not msg_s.lower().startswith("loading"):
                    try:
                        _n_top = int(model.rowCount(QModelIndex()))
                    except Exception:
                        _n_top = 0
                    if _n_top > 0:
                        _has_graph = False
                        for _ri in range(min(_n_top, 12)):
                            try:
                                _d = model.index(_ri, 0, QModelIndex()).data(Qt.UserRole) or {}
                            except Exception:
                                _d = {}
                            if (
                                isinstance(_d, dict)
                                and not _d.get("placeholder")
                                and str(_d.get("id") or "").strip()
                            ):
                                _has_graph = True
                                break
                        if _has_graph:
                            log_info(
                                "destination_placeholder_reset_blocked_due_to_graph_overlay_mode",
                                message_excerpt=msg_s[:200],
                            )
                            self._set_tree_status_message(
                                panel_key, msg_s, loading=str(msg_s or "").lower().startswith("loading")
                            )
                            try:
                                tree.setEnabled(True)
                            except Exception:
                                pass
                            return
                did_pending = str((getattr(self, "pending_root_drive_ids", {}) or {}).get("destination") or "").strip()
                mount_did = str(getattr(self, "_destination_snapshot_mount_drive_id", "") or "").strip()
                loading_msg = msg_s.lower().startswith("loading")
                same_library_as_snapshot_mount = (not mount_did or not did_pending or mount_did == did_pending)
                if (
                    loading_msg
                    and same_library_as_snapshot_mount
                    and not getattr(self, "_destination_suppress_provisional_placeholder_preservation", False)
                    and (
                        getattr(self, "_destination_provisional_startup_applied", False)
                        or getattr(self, "_destination_startup_snapshot_mount_seen", False)
                        or self._pending_session_destination_snapshot_drive_match(did_pending)
                    )
                ):
                    quiet = str(
                        getattr(self, "_destination_provisional_startup_status_message", "") or ""
                    ).strip() or (
                        "Loaded saved workspace snapshot. Verifying live SharePoint content…"
                    )
                    self._set_tree_status_message(panel_key, quiet, loading=False)
                    try:
                        tree.setEnabled(True)
                    except Exception:
                        pass
                    log_info(
                        "startup_lifecycle_temp_placeholder_suppressed",
                        panel_key="destination",
                        would_have_set=msg_s[:160],
                        preserved_snapshot_mount=True,
                        snapshot_mount_drive_id_suffix=mount_did[-16:] if len(mount_did) > 16 else mount_did,
                        pending_root_drive_id_suffix=did_pending[-16:] if len(did_pending) > 16 else did_pending,
                        same_library_as_snapshot_mount=same_library_as_snapshot_mount,
                    )
                    if self._full_trace_enabled():
                        log_trace(
                            "tree",
                            "set_tree_placeholder",
                            panel_key=panel_key,
                            message_excerpt=msg_s[:200],
                            suppressed_for_provisional_snapshot=True,
                            tree_kind="destination_qtreeview_model",
                        )
                    return
                if getattr(self, "_destination_startup_snapshot_mount_seen", False):
                    self._destination_startup_lifecycle_temp_post_snapshot_mutation(
                        "set_tree_placeholder",
                        "set_empty_library_message",
                        message_excerpt=msg_s[:160],
                    )
                model.set_empty_library_message(message or "")
                tree.setEnabled(False)
                self._set_tree_status_message(
                    panel_key,
                    message,
                    loading=str(message or "").lower().startswith("loading"),
                )
                if self._full_trace_enabled():
                    log_trace(
                        "tree",
                        "set_tree_placeholder",
                        panel_key=panel_key,
                        message_excerpt=(message or "")[:200],
                        tree_enabled=False,
                        tree_kind="destination_qtreeview_model",
                    )
                return

        tree.clear()
        placeholder = QTreeWidgetItem([message, "", "", ""])
        placeholder.setData(0, Qt.UserRole, {"placeholder": True})
        tree.addTopLevelItem(placeholder)
        tree.setEnabled(False)
        self._set_tree_status_message(panel_key, message, loading=str(message or "").lower().startswith("loading"))
        if self._full_trace_enabled():
            log_trace(
                "tree",
                "set_tree_placeholder",
                panel_key=panel_key,
                message_excerpt=(message or "")[:200],
                tree_enabled=False,
                tree_kind="qtreewidget",
            )

    _JSON_PERSIST_MAX_DEPTH = 48

    def _sanitize_value_for_json_persist(self, val, depth: int = 0):
        """Recursively replace Qt GUI types with JSON-safe values; drop unsupported objects from dicts."""
        if depth > self._JSON_PERSIST_MAX_DEPTH:
            return _JSON_PERSIST_OMIT
        if val is None or isinstance(val, (str, int, float, bool)):
            return val
        if isinstance(val, QColor):
            return val.name(QColor.HexRgb) if val.isValid() else ""
        if isinstance(val, QBrush):
            c = val.color()
            return c.name(QColor.HexRgb) if c.isValid() else ""
        if isinstance(val, QFont):
            return val.toString()
        if isinstance(val, QByteArray):
            if val.size() > 4096:
                return ""
            return bytes(val).hex()
        if isinstance(val, dict):
            out: dict = {}
            for k, v in val.items():
                sk = str(k)
                sv = self._sanitize_value_for_json_persist(v, depth + 1)
                if sv is _JSON_PERSIST_OMIT:
                    continue
                out[sk] = sv
            return out
        if isinstance(val, (list, tuple)):
            acc: list = []
            for x in val:
                sx = self._sanitize_value_for_json_persist(x, depth + 1)
                acc.append(None if sx is _JSON_PERSIST_OMIT else sx)
            return acc
        return _JSON_PERSIST_OMIT

    def _sanitize_tree_snapshot_branch_for_persist(self, snap):
        if not isinstance(snap, dict):
            return
        data = snap.get("data")
        if isinstance(data, dict):
            cleaned = self._sanitize_value_for_json_persist(data, 0)
            snap["data"] = cleaned if isinstance(cleaned, dict) else {}
        for ch in list(snap.get("children") or []):
            self._sanitize_tree_snapshot_branch_for_persist(ch)

    def _destination_stamp_payload_workspace_state_for_persist(self, pl: dict) -> None:
        if not isinstance(pl, dict) or pl.get("placeholder"):
            return
        if destination_payload_is_planned_workspace_row(pl):
            pl["workspace_row_state"] = WORKSPACE_ROW_STATE_PLANNED_ONLY
            return
        if str(pl.get("workspace_row_state") or "").strip():
            return
        pl["workspace_row_state"] = WORKSPACE_ROW_STATE_LIVE_CONFIRMED

    def _destination_stamp_snapshot_branch_workspace_state_for_persist(self, snap: dict) -> None:
        if not isinstance(snap, dict):
            return
        self._destination_stamp_payload_workspace_state_for_persist(snap.get("data") or {})
        for ch in list(snap.get("children") or []):
            self._destination_stamp_snapshot_branch_workspace_state_for_persist(ch)

    def _serialize_source_model_subtree_snapshot(self, index, tree):
        model = index.model()
        if model is None:
            return None
        pl = index.data(Qt.UserRole) or {}
        if pl.get("placeholder"):
            return None
        snap = {
            "text": str(index.data(Qt.DisplayRole) or ""),
            "data": dict(pl),
            "expanded": bool(tree.isExpanded(index)),
            "children": [],
        }
        for r in range(model.rowCount(index)):
            ch = model.index(r, 0, index)
            child_snap = self._serialize_source_model_subtree_snapshot(ch, tree)
            if child_snap is not None:
                snap["children"].append(child_snap)
        return snap

    def _capture_tree_items_snapshot(self, panel_key):
        tree, _status = self._get_tree_and_status(panel_key)
        snapshots = []
        if tree is None:
            return snapshots
        if panel_key == "destination":
            try:
                self._destination_flush_descendant_apply_resume_to_model_payloads()
            except Exception:
                pass
            _raw_force = bool(getattr(self, "_destination_session_snapshot_force_live_once", False))
            _allowed = self._destination_force_live_snapshot_allowed()
            if _raw_force and not _allowed:
                log_info(
                    "destination_force_live_snapshot_blocked_startup",
                    note="force_live_only_during_save_or_shutdown",
                    tick_running=bool(getattr(self, "_destination_descendant_apply_tick_running", False)),
                )
                self._destination_session_snapshot_force_live_once = False
                self._destination_runtime_snapshot_force_refresh_during_tick = False
            _force_live = _raw_force and _allowed
            if getattr(self, "_destination_descendant_apply_tick_running", False) and not _force_live:
                self._post_tick_descendant_drain_pending = True
                self._destination_post_tick_deferred_boundary_log("snapshot_capture_deferred_tick_running")
                log_info(
                    "snapshot_capture_skipped",
                    phase="capture_tree_items_snapshot",
                    skip_reason="destination_descendant_tick_running_without_force_live",
                    force_live=bool(_force_live),
                    save_in_progress=bool(getattr(self, "_destination_save_in_progress", False)),
                )
                if getattr(self, "_destination_tree_snapshot_dirty_for_persist", False):
                    log_info(
                        "destination_snapshot_saved_from_stale_cache",
                        reason="tick_running_runtime_cache_return",
                        shutting_down=bool(getattr(self, "_application_shutting_down", False)),
                    )
                rs = getattr(self, "_runtime_session_tree_snapshots", None)
                if isinstance(rs, dict) and isinstance(rs.get("destination"), list):
                    return list(rs["destination"])
                return []
            if _force_live:
                self._destination_session_snapshot_force_live_once = False
            try:
                self._destination_finalize_inflight_descendant_apply_for_snapshot_capture()
            except Exception:
                pass
        if panel_key == "source":
            model = getattr(self, "source_sharepoint_model", None)
            if model is None:
                return snapshots
            root = QModelIndex()
            for r in range(model.rowCount(root)):
                ix = model.index(r, 0, root)
                sub = self._serialize_source_model_subtree_snapshot(ix, tree)
                if sub is not None:
                    snapshots.append(sub)
        elif panel_key == "destination" and not callable(getattr(tree, "topLevelItemCount", None)):
            model = getattr(self, "destination_planning_model", None)
            if model is None:
                return snapshots
            root = QModelIndex()
            for r in range(model.rowCount(root)):
                ix = model.index(r, 0, root)
                sub = self._serialize_source_model_subtree_snapshot(ix, tree)
                if sub is not None:
                    snapshots.append(sub)
        else:
            for index in range(tree.topLevelItemCount()):
                item = tree.topLevelItem(index)
                node_data = item.data(0, Qt.UserRole) or {}
                if node_data.get("placeholder"):
                    continue
                snapshots.append(self._serialize_tree_item_snapshot(item))
        if panel_key == "destination":
            for snap in snapshots:
                self._destination_stamp_snapshot_branch_workspace_state_for_persist(snap)
                self._normalize_destination_snapshot_tree_for_persist(snap)
        for snap in snapshots:
            self._sanitize_tree_snapshot_branch_for_persist(snap)
        return snapshots

    def _serialize_tree_item_snapshot(self, item):
        snapshot = {
            "text": item.text(0),
            "data": dict(item.data(0, Qt.UserRole) or {}),
            "expanded": bool(item.isExpanded()),
            "children": [],
        }
        for index in range(item.childCount()):
            snapshot["children"].append(self._serialize_tree_item_snapshot(item.child(index)))
        return snapshot

    def _deserialize_tree_item_snapshot(self, snapshot):
        data = dict((snapshot or {}).get("data", {}) or {})
        item = QTreeWidgetItem([str((snapshot or {}).get("text", "")), "", "", ""])
        item.setData(0, Qt.UserRole, data)
        self._apply_explorer_metadata_columns(item, data)
        for child_snapshot in list((snapshot or {}).get("children", []) or []):
            item.addChild(self._deserialize_tree_item_snapshot(child_snapshot))
        item.setExpanded(bool((snapshot or {}).get("expanded", False)))
        return item

    def _deserialize_tree_item_snapshot_shallow(self, snapshot):
        """Build one QTreeWidgetItem from snapshot without attaching children (for chunked restore)."""
        data = dict((snapshot or {}).get("data", {}) or {})
        item = QTreeWidgetItem([str((snapshot or {}).get("text", "")), "", "", ""])
        item.setData(0, Qt.UserRole, data)
        self._apply_explorer_metadata_columns(item, data)
        item.setExpanded(bool((snapshot or {}).get("expanded", False)))
        children = list((snapshot or {}).get("children", []) or [])
        return item, children

    def _snapshot_sync_restore_max_nodes(self):
        """Snapshots with more nodes use time-sliced restore to avoid blocking the UI thread."""
        raw = os.environ.get("OZLINK_SNAPSHOT_SYNC_NODE_MAX", "").strip()
        if not raw:
            return 500
        try:
            v = int(raw)
            return max(50, v)
        except ValueError:
            return 500

    def _snapshot_chunk_node_budget(self):
        raw = os.environ.get("OZLINK_SNAPSHOT_CHUNK_NODES", "").strip()
        if not raw:
            return 70
        try:
            v = int(raw)
            return max(20, min(2000, v))
        except ValueError:
            return 70

    def _tree_snapshot_restore_skip_legacy_enabled(self):
        return os.environ.get("OZLINK_SKIP_LARGE_SNAPSHOT_RESTORE", "").strip() in ("1", "true", "True", "yes", "YES")

    def _finalize_tree_snapshot_restore(self, panel_key, snapshots, status_message):
        if panel_key == "destination":
            self._destination_snapshot_chunked_restore_active = False
            self._mark_destination_real_tree_snapshot_stale()
            self._destination_lifecycle_trace_TEMP(
                fn="_finalize_tree_snapshot_restore",
                reason=str(status_message or "")[:120],
                step_kind="state_restore",
                extra=f"snapshot_top_nodes={len(snapshots or [])}",
            )
        tree, _status = self._get_tree_and_status(panel_key)
        if panel_key == "destination" and self._tree_snapshot_node_count_gt(snapshots, 1):
            self._destination_root_prime_pending = False
        if tree is not None:
            tree.setEnabled(True)
            tree.setUpdatesEnabled(True)
        self._set_tree_status_message(panel_key, status_message, loading=False)
        if tree is not None:
            tree.viewport().update()
        runtime_snapshots = getattr(self, "_runtime_session_tree_snapshots", None)
        if not isinstance(runtime_snapshots, dict):
            runtime_snapshots = {"source": [], "destination": []}
            self._runtime_session_tree_snapshots = runtime_snapshots
        runtime_snapshots[panel_key] = list(snapshots or [])
        if panel_key == "destination":
            self._destination_branch_forensic_log(
                "startup_post_restore_model_vs_snapshot",
                snapshots=list(snapshots or []),
            )

    def _abort_destination_chunked_bind_for_snapshot_restore(self):
        st = getattr(self, "_destination_chunked_bind_state", None)
        if not isinstance(st, dict):
            return
        self._destination_future_bind_generation = int(getattr(self, "_destination_future_bind_generation", 0)) + 1
        tree = getattr(self, "destination_tree_widget", None)
        try:
            if tree is not None:
                tree.blockSignals(False)
        except Exception:
            pass
        self._destination_chunked_bind_state = None
        self._log_restore_phase(
            "destination_chunked_bind_aborted",
            phase_failed="destination_snapshot_restore_preempt",
            bind_generation=st.get("gen"),
            wall_duration_ms=0.0,
            error_type="SnapshotRestorePreempt",
        )
        self._flush_pending_destination_library_root_if_any(flush_reason="after_snapshot_preempt_bind")

    def _restore_tree_items_snapshot_chunked(
        self, panel_key, snapshots, status_message, *, context, on_complete=None
    ):
        tree, _status = self._get_tree_and_status(panel_key)
        if tree is None or not snapshots:
            if on_complete:
                on_complete()
            return
        self._tree_snapshot_restore_generation[panel_key] = (
            int(self._tree_snapshot_restore_generation.get(panel_key, 0)) + 1
        )
        generation = self._tree_snapshot_restore_generation[panel_key]
        total_nodes = self._count_tree_snapshot_nodes(snapshots)
        budget = self._snapshot_chunk_node_budget()
        built = [0]

        if panel_key == "destination":
            self._abort_destination_chunked_bind_for_snapshot_restore()
            self._destination_snapshot_chunked_restore_active = False

        # QTreeView model-view mode for the source panel uses an underlying
        # SharePointSourceTreeModel and must not call QTreeWidget APIs like
        # ``tree.clear()`` / ``addTopLevelItem()``.
        if panel_key == "source":
            model = getattr(self, "source_sharepoint_model", None)
            if model is not None:
                try:
                    tree.setUpdatesEnabled(False)
                    tree.setEnabled(True)
                    snapshot_nodes = int(self._count_tree_snapshot_nodes(snapshots))
                    if self._planning_browse_mode("source") != "sharepoint":
                        log_info(
                            "source_sharepoint_snapshot_shell_skipped",
                            reason="browse_mode_not_sharepoint",
                            snapshot_nodes=snapshot_nodes,
                        )
                        self._finalize_tree_snapshot_restore(panel_key, snapshots, status_message)
                        if on_complete:
                            on_complete()
                        return
                    match, reason = self._source_sharepoint_snapshot_shell_identity_matches(snapshots)
                    if not match:
                        log_info(
                            "source_sharepoint_snapshot_shell_skipped",
                            reason=str(reason),
                            snapshot_nodes=snapshot_nodes,
                        )
                        self._finalize_tree_snapshot_restore(panel_key, snapshots, status_message)
                        if on_complete:
                            on_complete()
                        return
                    model.clear()
                    self._source_startup_snapshot_mount_seen = False
                    mounted_nodes = 0
                    with _PerfExplorerTimer(
                        "tree_snapshot_mount_recursive_source_shell",
                        panel_key="source",
                        top_level_snapshots=len(snapshots or []),
                    ):
                        mounted_nodes = int(model.mount_from_session_snapshot_roots(list(snapshots or [])))
                    self._source_startup_snapshot_mount_seen = mounted_nodes > 0
                    self._source_snapshot_mount_drive_id = str(
                        self._current_source_library_identity_tuple().get("drive_id") or ""
                    ).strip()
                    log_info(
                        "source_sharepoint_snapshot_shell_applied",
                        reason=str(reason),
                        snapshot_nodes=snapshot_nodes,
                        mounted_nodes=int(mounted_nodes),
                        identity_match=True,
                    )
                    if mounted_nodes <= 0:
                        self._set_tree_status_message(panel_key, "This library is empty.", loading=False)
                        model.set_empty_library_message("This library is empty.")
                        tree.setEnabled(False)
                    else:
                        self._set_tree_status_message(
                            panel_key,
                            f"Loading tree snapshot… ({mounted_nodes}/{snapshot_nodes})",
                            loading=False,
                        )

                    self._finalize_tree_snapshot_restore(panel_key, snapshots, status_message)
                    if on_complete:
                        on_complete()
                    return
                finally:
                    try:
                        tree.setUpdatesEnabled(True)
                    except Exception:
                        pass

        if panel_key == "destination":
            model = getattr(self, "destination_planning_model", None)
            if model is not None and tree is not None:
                try:
                    tree.setUpdatesEnabled(False)
                    tree.setEnabled(True)
                    self._destination_lifecycle_trace_TEMP(
                        fn="_restore_tree_items_snapshot_chunked",
                        reason=str(status_message or "")[:120],
                        step_kind="state_restore",
                        extra=f"context={str(context)[:40]};planning_skip_structural_snapshot",
                    )
                    self._finalize_tree_snapshot_restore(panel_key, snapshots, status_message)
                    if on_complete:
                        on_complete()
                    return
                finally:
                    try:
                        tree.setUpdatesEnabled(True)
                    except Exception:
                        pass

        tree.clear()
        tree.setUpdatesEnabled(False)
        tree.setEnabled(True)
        work = deque()
        for snap in snapshots:
            item, kids = self._deserialize_tree_item_snapshot_shallow(snap)
            tree.addTopLevelItem(item)
            built[0] += 1
            if kids:
                work.append((item, kids, 0))

        self._set_tree_status_message(
            panel_key,
            f"Loading tree snapshot… ({built[0]}/{total_nodes})",
            loading=True,
        )
        log_info(
            "tree_snapshot_chunked_restore_started",
            panel_key=panel_key,
            total_nodes=total_nodes,
            chunk_nodes=budget,
            context=context,
        )

        def tick():
            if generation != self._tree_snapshot_restore_generation.get(panel_key):
                return
            slice_timer = QElapsedTimer()
            slice_timer.start()
            max_slice_ms = 10
            raw_ms = os.environ.get("OZLINK_SNAPSHOT_CHUNK_MAX_MS", "").strip()
            if raw_ms:
                try:
                    max_slice_ms = max(4, min(50, int(raw_ms)))
                except ValueError:
                    pass
            b = budget
            while b > 0 and work:
                if slice_timer.elapsed() > max_slice_ms:
                    QTimer.singleShot(0, tick)
                    return
                parent, children, idx = work[0]
                if idx >= len(children):
                    work.popleft()
                    continue
                child_snap = children[idx]
                work[0] = (parent, children, idx + 1)
                child_item, grand = self._deserialize_tree_item_snapshot_shallow(child_snap)
                try:
                    parent.addChild(child_item)
                except RuntimeError as exc:
                    # Re-entrancy (e.g. combo currentData() while another path cleared the tree)
                    # can delete parents before this tick runs; invalidate this restore and stop.
                    err = str(exc).lower()
                    if "already deleted" not in err and "internal c++ object" not in err:
                        raise
                    self._tree_snapshot_restore_generation[panel_key] = (
                        int(self._tree_snapshot_restore_generation.get(panel_key, 0)) + 1
                    )
                    if panel_key == "destination":
                        self._destination_snapshot_chunked_restore_active = False
                    log_info(
                        "tree_snapshot_chunked_restore_aborted",
                        panel_key=panel_key,
                        context=context,
                        built_nodes=built[0],
                        total_nodes=total_nodes,
                        error=str(exc),
                    )
                    t_abort, _ = self._get_tree_and_status(panel_key)
                    if t_abort is not None:
                        t_abort.setEnabled(True)
                        t_abort.setUpdatesEnabled(True)
                        t_abort.viewport().update()
                    self._set_tree_status_message(
                        panel_key,
                        "Tree snapshot restore interrupted; try Refresh Cache.",
                        loading=False,
                    )
                    if on_complete:
                        on_complete()
                    return
                built[0] += 1
                b -= 1
                if grand:
                    work.append((child_item, grand, 0))
            if generation != self._tree_snapshot_restore_generation.get(panel_key):
                return
            if work:
                if built[0] % max(1, budget * 3) < budget or built[0] == total_nodes:
                    self._set_tree_status_message(
                        panel_key,
                        f"Loading tree snapshot… ({min(built[0], total_nodes)}/{total_nodes})",
                        loading=True,
                    )
                QTimer.singleShot(0, tick)
                return
            self._finalize_tree_snapshot_restore(panel_key, snapshots, status_message)
            log_info(
                "tree_snapshot_chunked_restore_complete",
                panel_key=panel_key,
                total_nodes=built[0],
                context=context,
            )
            if on_complete:
                on_complete()

        if work:
            if panel_key == "destination":
                self._destination_snapshot_chunked_restore_active = True
            QTimer.singleShot(0, tick)
        else:
            self._finalize_tree_snapshot_restore(panel_key, snapshots, status_message)
            log_info(
                "tree_snapshot_chunked_restore_complete",
                panel_key=panel_key,
                total_nodes=built[0],
                context=context,
            )
            if on_complete:
                on_complete()

    def _destination_snapshot_shows_materialized_allocation_children(self, snapshot):
        children = list((snapshot or {}).get("children") or [])
        if not children:
            return False
        for ch in children:
            d = (ch or {}).get("data") or {}
            if not d.get("placeholder"):
                return True
            role = str(d.get("placeholder_role") or "").strip()
            if role in ("projection_pending", "lazy_unloaded", "loading_in_progress"):
                return False
        return True

    def _normalize_destination_snapshot_tree_for_persist(self, snapshot):
        """Post-order: persist children_loaded + projection cache keys for [Allocated] folders in JSON snapshots."""
        for ch in list((snapshot or {}).get("children") or []):
            self._normalize_destination_snapshot_tree_for_persist(ch)
        data = snapshot.get("data")
        if not isinstance(data, dict):
            return
        if not self.node_is_planned_allocation(data) or not bool(data.get("is_folder", True)):
            return
        if not self._destination_snapshot_shows_materialized_allocation_children(snapshot):
            return
        data["children_loaded"] = True
        data["projection_unresolved_terminal"] = False
        path = self._canonical_destination_projection_path(
            data.get("item_path") or data.get("display_path") or data.get("destination_path") or ""
        )
        if path:
            data["allocation_projection_destination_path_saved"] = path
        parts = []
        for ch in (snapshot or {}).get("children") or []:
            cd = (ch or {}).get("data") or {}
            if cd.get("placeholder"):
                continue
            cp = self._canonical_destination_projection_path(
                cd.get("item_path") or cd.get("display_path") or cd.get("destination_path") or ""
            )
            parts.append((cp, bool(cd.get("is_folder")), str(cd.get("name") or "")))
        try:
            data["allocation_projection_children_signature"] = hashlib.sha256(
                repr(sorted(parts)).encode("utf-8")
            ).hexdigest()[:32]
        except Exception:
            pass

    def _allocation_projection_children_signature_from_index(self, index: QModelIndex) -> str:
        model = getattr(self, "destination_planning_model", None)
        if model is None or not index.isValid():
            return ""
        parts = []
        for r in range(model.rowCount(index)):
            ix = model.index(r, 0, index)
            cd = ix.data(Qt.UserRole) or {}
            if cd.get("placeholder"):
                continue
            cp = self._canonical_destination_projection_path(
                cd.get("item_path") or cd.get("display_path") or cd.get("destination_path") or ""
            )
            parts.append((cp, bool(cd.get("is_folder")), str(cd.get("name") or "")))
        try:
            return hashlib.sha256(repr(sorted(parts)).encode("utf-8")).hexdigest()[:32]
        except Exception:
            return ""

    def _invalidate_stale_destination_allocation_projection_index(self, index: QModelIndex, node_data, move):
        nd = dict(node_data or {})
        if not self.node_is_planned_allocation(nd) or not bool(nd.get("children_loaded")):
            return nd
        saved = str(nd.get("allocation_projection_destination_path_saved") or "").strip()
        if move is not None:
            expected = self._canonical_destination_projection_path(self._allocation_projection_path(move))
            if saved and expected and saved != expected:
                nd["children_loaded"] = False
                nd.pop("allocation_projection_destination_path_saved", None)
                nd.pop("allocation_projection_children_signature", None)
                nd.pop("allocation_descendants_applied", None)
                nd.pop("allocation_projection_resume_source_token", None)
                nd.pop("allocation_projection_resume_desc_index", None)
                nd.pop("allocation_projection_resume_descendants_total", None)
                return nd
        sig = str(nd.get("allocation_projection_children_signature") or "").strip()
        if sig and self._destination_allocation_folder_shows_materialized_children_index(index):
            current_sig = self._allocation_projection_children_signature_from_index(index)
            if current_sig and current_sig != sig:
                nd["children_loaded"] = False
                nd.pop("allocation_projection_destination_path_saved", None)
                nd.pop("allocation_projection_children_signature", None)
                nd.pop("allocation_descendants_applied", None)
                nd.pop("allocation_projection_resume_source_token", None)
                nd.pop("allocation_projection_resume_desc_index", None)
                nd.pop("allocation_projection_resume_descendants_total", None)
                return nd
        return nd

    def _stamp_allocation_projection_cache_metadata_index(self, index: QModelIndex, node_data: dict, move) -> dict:
        dmodel = getattr(self, "destination_planning_model", None)
        if dmodel is None or not index.isValid():
            return dict(node_data or {})
        nd = dict(node_data or {})
        expected = ""
        if move is not None:
            expected = self._canonical_destination_projection_path(self._allocation_projection_path(move))
        if not expected:
            expected = self._canonical_destination_projection_path(self._tree_item_path(nd))
        if expected:
            nd["allocation_projection_destination_path_saved"] = expected
        sig = self._allocation_projection_children_signature_from_index(index)
        if sig:
            nd["allocation_projection_children_signature"] = sig

        def _mut(p):
            if expected:
                p["allocation_projection_destination_path_saved"] = expected
            if sig:
                p["allocation_projection_children_signature"] = sig

        dmodel.update_payload_for_index(index, _mut)
        return nd

    def _log_ozlink_console_loaded_diagnostics_once(self) -> None:
        """One-shot forensic log proving which main_window.py and reuse helpers are in effect."""
        if getattr(self, "_ozlink_console_loaded_logged", False):
            return
        self._ozlink_console_loaded_logged = True
        try:
            mw_path = str(Path(__file__).resolve())
        except Exception:
            mw_path = str(__file__ or "")
        try:
            cwd = os.getcwd()
        except Exception:
            cwd = ""
        try:
            sp_head = list(sys.path[:5])
        except Exception:
            sp_head = []
        try:
            has_assess = hasattr(type(self), "_destination_descendant_snapshot_reuse_assess")
            has_mark = hasattr(type(self), "_destination_descendant_snapshot_reuse_mark_allocation_applied_index")
        except Exception:
            has_assess = False
            has_mark = False
        try:
            pid = int(os.getpid())
        except Exception:
            pid = -1
        g_commit = ""
        g_dirty: Optional[bool] = None
        try:
            repo_root = Path(__file__).resolve().parent.parent
            r = subprocess.run(
                ["git", "rev-parse", "--short", "HEAD"],
                cwd=str(repo_root),
                capture_output=True,
                text=True,
                timeout=3,
            )
            if r.returncode == 0 and (r.stdout or "").strip():
                g_commit = (r.stdout or "").strip()[:40]
            r2 = subprocess.run(
                ["git", "status", "--porcelain"],
                cwd=str(repo_root),
                capture_output=True,
                text=True,
                timeout=3,
            )
            if r2.returncode == 0:
                g_dirty = bool((r2.stdout or "").strip())
        except Exception:
            pass
        log_info(
            "ozlink_console_loaded",
            main_window_file=mw_path,
            cwd=cwd,
            sys_path_head_5=sp_head,
            has_descendant_snapshot_reuse_assess=bool(has_assess),
            has_descendant_snapshot_reuse_mark_applied=bool(has_mark),
            pid=int(pid),
            git_commit_short=g_commit or "",
            git_dirty=g_dirty,
        )

