    def _reclassify_planned_workspace_leaf_to_file_if_needed(
        self,
        leaf_col0: QModelIndex,
        *,
        segment_name: str,
        canonical_full_path: str,
        name_column_tag: str,
    ) -> None:
        """When a terminal file bind reuses an existing planned *folder* row, fix row_kind / is_folder (strips children)."""
        model = getattr(self, "destination_planning_model", None)
        if model is None or not leaf_col0.isValid():
            return
        if hasattr(model, "is_index_live") and not model.is_index_live(leaf_col0):
            return
        ch = self._destination_model_index_user_role_dict(leaf_col0)
        self._destination_leaf_forensic_trace_payload(
            "_reclassify_planned_workspace_leaf_to_file_if_needed:enter", ch, "existing_row_before_fix"
        )
        if not destination_payload_is_planned_workspace_row(ch) or destination_payload_is_live_graph_row(ch):
            return
        if str(ch.get("row_kind") or "").strip().lower() == "planned_file" and ch.get("is_folder") is False:
            return
        if str(ch.get("row_kind") or "").strip().lower() != "planned_folder" and ch.get("is_folder") is not True:
            return
        seg = str(segment_name or ch.get("name") or "").strip() or "File"
        canon = self._canonical_destination_projection_path(canonical_full_path) or self.normalize_memory_path(
            canonical_full_path
        )

        def _mut(p):
            p["is_folder"] = False
            p["row_kind"] = "planned_file"
            p["children_loaded"] = True
            p["name"] = seg
            p["real_name"] = seg
            p["item_path"] = canon
            p["destination_path"] = canon
            p["display_path"] = canon
            p["base_display_label"] = self._tree_name_column_label(seg, tag=name_column_tag)
            p.setdefault("verification_state", "planned_only")
            p["workspace_planned_row"] = True

        model.update_payload_for_index(leaf_col0, _mut)
        self._apply_tree_item_visual_state(None, self._destination_model_index_user_role_dict(leaf_col0))
        self._destination_leaf_forensic_trace_payload(
            "_reclassify_planned_workspace_leaf_to_file_if_needed:after",
            self._destination_model_index_user_role_dict(leaf_col0),
            "post_mutate",
        )

    def _destination_planned_bind_find_existing_planned_row_under_parent(
        self, parent_ix: QModelIndex, next_branch: str, model
    ) -> QModelIndex | None:
        """Return an existing planned overlay row for ``next_branch`` already attached under ``parent_ix`` (dedupe)."""
        if model is None or not parent_ix.isValid():
            return None
        nb = (
            self._canonical_planned_memory_path_for_graph_match(str(next_branch or "").strip())
            or self._canonical_destination_projection_path(str(next_branch or "").strip())
            or str(next_branch or "").strip()
        )
        p0 = parent_ix.siblingAtColumn(0) if parent_ix.column() != 0 else parent_ix
        try:
            for r in range(model.rowCount(p0)):
                ix = model.index(r, 0, p0)
                if not ix.isValid():
                    continue
                pl = dict(ix.data(Qt.UserRole) or {})
                if pl.get("placeholder"):
                    continue
                if destination_payload_is_live_graph_row(pl):
                    log_info(
                        "destination_planned_duplicate_runtime_merge_skipped_live_graph",
                        canonical_path_excerpt=str(nb)[:400],
                    )
                    continue
                if not destination_payload_is_planned_workspace_row(pl):
                    continue
                vis = (
                    self._canonical_planned_memory_path_for_graph_match(
                        str(self._tree_item_path(pl) or self._destination_row_raw_path_for_path_lookup_match(pl) or "")
                    )
                    or ""
                ).strip()
                if vis.casefold() == nb.casefold():
                    log_info(
                        "destination_planned_folder_canonical_path_key",
                        canonical_path_excerpt=str(nb)[:400],
                        under_parent_excerpt=str(
                            self._canonical_planned_memory_path_for_graph_match(
                                str(self._tree_item_path(self._destination_model_index_user_role_dict(p0)) or "")
                            )
                            or ""
                        )[:400],
                    )
                    log_info(
                        "destination_planned_duplicate_runtime_merge_started",
                        canonical_path_excerpt=str(nb)[:400],
                        reason="reuse_existing_child_under_parent",
                    )
                    log_info(
                        "destination_planned_duplicate_runtime_merge_completed",
                        canonical_path_excerpt=str(nb)[:400],
                        outcome="reuse_existing_planned",
                    )
                    return ix.siblingAtColumn(0) if ix.column() != 0 else ix
                dup_name = str(pl.get("name") or pl.get("real_name") or "").strip().casefold()
                want_seg = [s for s in str(nb).split("\\") if s][-1:][:1]
                if want_seg and dup_name == want_seg[0].strip().casefold():
                    log_info(
                        "destination_planned_folder_duplicate_sibling_detected",
                        parent_path_excerpt=str(
                            self._tree_item_path(self._destination_model_index_user_role_dict(p0)) or ""
                        )[:400],
                        duplicate_name_excerpt=str(dup_name)[:200],
                        canonical_path_excerpt=str(nb)[:400],
                    )
                    log_info(
                        "destination_planned_folder_duplicate_insert_blocked",
                        canonical_path_excerpt=str(nb)[:400],
                    )
                    log_info(
                        "destination_planned_folder_existing_reused_for_descendant",
                        canonical_path_excerpt=str(nb)[:400],
                    )
                    return ix.siblingAtColumn(0) if ix.column() != 0 else ix
        except RuntimeError:
            return None
        return None

    def _sharepoint_bind_planned_segment_chain(
        self,
        parent_ix: QModelIndex,
        suffix_segments: list[str],
        *,
        bind_kind: str,
        bind_context_excerpt: str = "",
        allocation_id: str = "",
        expected_parent_canonical: str | None = None,
        projection_target_canonical: str | None = None,
        terminal_is_file: bool = False,
        proposed_folder_stable_key: str = "",
    ) -> QModelIndex | None:
        """Create planned workspace rows for each suffix segment using a strict canonical prefix.

        Intermediate segments are ``planned_folder``; the last segment is ``planned_file`` when
        ``terminal_is_file`` is True (e.g. allocation of a document).

        Planned paths are ``canonical(join(anchor, seg_0, …, seg_k))`` from the validated anchor
        and suffix list — not by repeatedly extending each row's ``item_path``. That avoids wrong
        placement when a parent row carries a stale or aliased path.
        """
        model = getattr(self, "destination_planning_model", None)
        ft = self._destination_bind_trace_enabled()
        trace_id = dest_forensic.new_trace_id() if ft else ""
        row_kind_trace = dest_forensic.map_bind_kind_to_row_kind(
            str(bind_kind or ""), terminal_is_file=bool(terminal_is_file)
        )
        graph_strict = destination_authority_contract.graph_owns_visible_real_destination_structure(self)
        _pt_trace = dest_forensic.exact_target_pipeline_trace_enabled() and str(bind_kind or "").strip() == "exact_target_enforcement"

        def _bind_trace_fail(final_result: str, **extra: Any) -> None:
            if _pt_trace:
                try:
                    log_warn(
                        "destination_exact_target_pipeline_bind_exit_fail",
                        final_result_enum=str(final_result)[:80],
                        projection_target_canonical=str(projection_target_canonical or "")[:400],
                        bind_context_excerpt=str(bind_context_excerpt or "")[:220],
                        **{k: (str(v)[:400] if isinstance(v, str) else v) for k, v in extra.items()},
                    )
                except Exception:
                    pass
            if not ft:
                return
            dest_forensic.log_bind(
                trace_id=trace_id,
                record_phase="bind_fail",
                kind=row_kind_trace,
                bind_kind=str(bind_kind or "")[:80],
                graph_authority=bool(graph_strict),
                strict_path_required=bool(graph_strict),
                final_result_enum=str(final_result)[:80],
                bind_context_excerpt=str(bind_context_excerpt or "")[:220],
                source_request_or_allocation_excerpt=str(allocation_id or "")[:120],
                **extra,
            )

        if model is None or not parent_ix.isValid() or not suffix_segments:
            _bind_trace_fail("other", detail="invalid_model_parent_or_empty_suffix_input")
            return None
        col0 = parent_ix.siblingAtColumn(0) if parent_ix.column() != 0 else parent_ix
        if not col0.isValid():
            _bind_trace_fail("other", detail="parent_column0_invalid")
            return None
        cleaned_suffix = [str(s or "").strip() for s in suffix_segments if str(s or "").strip()]
        if not cleaned_suffix:
            _bind_trace_fail("other", detail="cleaned_suffix_empty")
            return None

        p0 = self._destination_model_index_user_role_dict(col0)
        actual_parent_canon = (
            self._canonical_destination_projection_path(self._tree_item_path(p0) or "") or ""
        ).strip()
        if not actual_parent_canon:
            self._log_restore_phase(
                "sharepoint_planned_bind_empty_anchor",
                bind_kind=str(bind_kind or "")[:80],
                bind_context_excerpt=str(bind_context_excerpt or "")[:220],
            )
            _bind_trace_fail("blocked_by_parent_lookup", anchor_parent_chosen="", detail="empty_actual_parent_canon")
            return None

        if _pt_trace:
            log_info(
                "destination_exact_target_pipeline_bind_enter",
                projection_target_canonical=str(projection_target_canonical or "")[:400],
                terminal_is_file=bool(terminal_is_file),
                suffix_segments="\\".join(cleaned_suffix)[:400],
                anchor_parent_actual=str(actual_parent_canon)[:400],
            )

        running_anchor = actual_parent_canon
        if expected_parent_canonical is not None:
            exp = str(expected_parent_canonical or "").strip()
            if exp:
                exp_norm = self._canonical_destination_projection_path(exp) or self.normalize_memory_path(exp)
                md = self._destination_parent_match_details(exp_norm, actual_parent_canon)
                if not md.get("exact_match"):
                    self._log_restore_phase(
                        "sharepoint_planned_bind_anchor_mismatch",
                        bind_kind=str(bind_kind or "")[:80],
                        bind_context_excerpt=str(bind_context_excerpt or "")[:220],
                        expected_parent_canonical=str(exp_norm)[:260],
                        actual_parent_canonical=str(actual_parent_canon)[:260],
                        suffix_excerpt="\\".join(cleaned_suffix)[:220],
                    )
                    _bind_trace_fail(
                        "blocked_by_parent_lookup",
                        anchor_parent_chosen=str(actual_parent_canon)[:400],
                        expected_parent_canonical=str(exp_norm)[:400],
                        detail="anchor_expected_vs_actual_mismatch",
                    )
                    return None
                running_anchor = exp_norm

        parts_seed = list(self._path_segments(running_anchor))
        if not parts_seed:
            self._log_restore_phase(
                "sharepoint_planned_bind_empty_anchor_segments",
                bind_kind=str(bind_kind or "")[:80],
                bind_context_excerpt=str(bind_context_excerpt or "")[:220],
                running_anchor_excerpt=str(running_anchor)[:220],
            )
            _bind_trace_fail(
                "blocked_by_parent_lookup",
                anchor_parent_chosen=str(running_anchor)[:400],
                detail="anchor_has_no_path_segments",
            )
            return None

        target_hint = ""
        raw_target_pre = str(projection_target_canonical or "").strip()
        if projection_target_canonical is not None and raw_target_pre:
            target_hint = (
                self._canonical_destination_projection_path(str(projection_target_canonical).strip())
                or str(projection_target_canonical).strip()
            )
        intended_for_trace = (
            (self._canonical_destination_projection_path(raw_target_pre) or self.normalize_memory_path(raw_target_pre))
            if raw_target_pre
            else ""
        )
        if ft:
            dest_forensic.log_bind(
                trace_id=trace_id,
                record_phase="bind_start",
                kind=row_kind_trace,
                bind_kind=str(bind_kind or "")[:80],
                graph_authority=bool(graph_strict),
                strict_path_required=bool(graph_strict),
                anchor_parent_chosen=str(running_anchor)[:400],
                relative_suffix_chosen="\\".join(cleaned_suffix)[:220],
                intended_canonical_target_path=str(intended_for_trace or target_hint or "")[:400],
                intended_parent_canonical_path=str(running_anchor)[:400],
                bind_context_excerpt=str(bind_context_excerpt or "")[:220],
                source_request_or_allocation_excerpt=str(allocation_id or "")[:120],
            )

        cur = col0
        created = 0
        alloc_for_first = str(allocation_id or "").strip()
        anchor_excerpt = running_anchor

        leaf_file_tag = (
            "[Allocated]"
            if str(bind_kind or "").strip().lower() in ("allocation", "allocation_descendant")
            else "[Planned]"
        )
        last_next_branch = ""
        for idx, seg in enumerate(cleaned_suffix):
            expected_cur = self._canonical_destination_projection_path("\\".join(parts_seed)) or "\\".join(parts_seed)
            cur = self._destination_model_index_for_canonical_under_anchor(col0, expected_cur)
            if not cur.isValid():
                self._log_restore_phase(
                    "sharepoint_planned_bind_walk_parent_reresolve_miss",
                    bind_kind=str(bind_kind or "")[:80],
                    bind_context_excerpt=str(bind_context_excerpt or "")[:220],
                    segment_index=int(idx),
                    expected_parent_canonical=str(expected_cur)[:400],
                )
                _bind_trace_fail(
                    "blocked_by_parent_lookup",
                    segment_index=int(idx),
                    expected_parent_canonical=str(expected_cur)[:400],
                    detail="bind_walk_parent_index_stale_or_missing_reresolve",
                )
                return None
            next_branch = self._canonical_destination_projection_path("\\".join(parts_seed + [seg]))
            if not next_branch:
                next_branch = self.normalize_memory_path("\\".join(parts_seed + [seg]))
            if not next_branch:
                self._log_restore_phase(
                    "sharepoint_planned_bind_empty_branch",
                    bind_kind=str(bind_kind or "")[:80],
                    bind_context_excerpt=str(bind_context_excerpt or "")[:220],
                    segment_index=int(idx),
                    segment_excerpt=str(seg)[:120],
                )
                _bind_trace_fail(
                    "blocked_by_child_lookup",
                    segment_index=int(idx),
                    next_segment_name=str(seg)[:200],
                    detail="empty_next_branch_canonical",
                )
                return None

            pd = self._destination_model_index_user_role_dict(cur)
            cur_canon = self._canonical_destination_projection_path(self._tree_item_path(pd) or "") or ""
            cur_md = self._destination_parent_match_details(expected_cur, cur_canon)
            if not cur_md.get("exact_match"):
                self._log_restore_phase(
                    "sharepoint_planned_bind_walk_parent_mismatch",
                    bind_kind=str(bind_kind or "")[:80],
                    bind_context_excerpt=str(bind_context_excerpt or "")[:220],
                    expected_parent_canonical=str(expected_cur)[:260],
                    actual_parent_canonical=str(cur_canon)[:260],
                    next_branch_excerpt=str(next_branch)[:260],
                    segment_index=int(idx),
                )
                _bind_trace_fail(
                    "blocked_by_parent_lookup",
                    segment_index=int(idx),
                    current_parent_path_expected=str(expected_cur)[:400],
                    current_parent_path_actual=str(cur_canon)[:400],
                    next_segment_name=str(seg)[:200],
                    detail="walk_parent_canonical_mismatch",
                )
                return None

            existing = self._find_destination_child_by_path(cur, next_branch, overlay_path_strict=graph_strict)
            if (
                existing is None
                and graph_strict
                and str(bind_kind or "").strip().lower() == "allocation_descendant"
                and model is not None
            ):
                dup = self._destination_planned_bind_find_existing_planned_row_under_parent(cur, next_branch, model)
                if dup is not None and dup.isValid():
                    existing = dup
            exact_hit = False
            row_inserted = False
            inserted_path = ""
            inserted_type = ""
            inserted_meta = ""
            if existing is not None and isinstance(existing, QModelIndex) and existing.isValid():
                ch = self._destination_model_index_user_role_dict(existing)
                if not destination_payload_is_structural_row_for_planned_workspace_bind(ch):
                    self._log_restore_phase(
                        "sharepoint_planned_bind_existing_not_projectable",
                        bind_kind=str(bind_kind or "")[:80],
                        bind_context_excerpt=str(bind_context_excerpt or "")[:220],
                        next_branch_excerpt=str(next_branch)[:260],
                    )
                    _bind_trace_fail(
                        "blocked_by_child_lookup",
                        segment_index=int(idx),
                        next_branch_canonical=str(next_branch)[:400],
                        detail="existing_child_not_live_or_planned_workspace",
                    )
                    return None
                _is_terminal_segment = idx == len(cleaned_suffix) - 1
                if not _is_terminal_segment and self._destination_payload_cannot_serve_as_folder_parent(ch):
                    self._log_restore_phase(
                        "sharepoint_planned_bind_file_as_intermediate_parent",
                        bind_kind=str(bind_kind or "")[:80],
                        bind_context_excerpt=str(bind_context_excerpt or "")[:220],
                        segment_index=int(idx),
                        next_branch_excerpt=str(next_branch)[:260],
                        row_kind_excerpt=str(ch.get("row_kind") or "")[:80],
                    )
                    _bind_trace_fail(
                        "blocked_by_child_lookup",
                        segment_index=int(idx),
                        next_branch_canonical=str(next_branch)[:400],
                        detail="file_row_as_non_terminal_parent",
                    )
                    return None
                child_canon = self._canonical_destination_projection_path(self._tree_item_path(ch) or "") or ""
                ch_md = self._destination_parent_match_details(next_branch, child_canon)
                if not ch_md.get("exact_match"):
                    self._log_restore_phase(
                        "sharepoint_planned_bind_existing_path_mismatch",
                        bind_kind=str(bind_kind or "")[:80],
                        bind_context_excerpt=str(bind_context_excerpt or "")[:220],
                        expected_child_canonical=str(next_branch)[:260],
                        actual_child_canonical=str(child_canon)[:260],
                    )
                    _bind_trace_fail(
                        "blocked_by_child_lookup",
                        segment_index=int(idx),
                        expected_child_canonical=str(next_branch)[:400],
                        actual_child_canonical=str(child_canon)[:400],
                        detail="existing_child_path_not_exact",
                    )
                    return None
                exact_hit = True
                inserted_path = str(child_canon)[:400]
                inserted_type = str(ch.get("row_kind") or ("live_folder" if ch.get("is_folder") else "live_file"))[
                    :80
                ]
                pu = str(ch.get("planning_uuid") or "").strip()
                inserted_meta = f"planning_uuid={pu[:40]}" if pu else f"id={str(ch.get('id') or '')[:24]}"
                cur = existing.siblingAtColumn(0) if existing.column() != 0 else existing
                if (
                    bool(terminal_is_file)
                    and idx == len(cleaned_suffix) - 1
                    and destination_payload_is_planned_workspace_row(ch)
                    and not destination_payload_is_live_graph_row(ch)
                ):
                    self._reclassify_planned_workspace_leaf_to_file_if_needed(
                        cur,
                        segment_name=seg,
                        canonical_full_path=next_branch,
                        name_column_tag=leaf_file_tag,
                    )
                    ch = self._destination_model_index_user_role_dict(cur)
                    inserted_type = str(ch.get("row_kind") or "")[:80]
                parts_seed = list(self._path_segments(next_branch))
            else:
                model.remove_placeholder_children(cur)
                aid = alloc_for_first if created == 0 else ""
                is_file_leaf = bool(terminal_is_file) and idx == len(cleaned_suffix) - 1
                if is_file_leaf:
                    pl = self._build_sharepoint_planned_file_payload(
                        pd,
                        seg,
                        next_branch,
                        allocation_id=aid,
                        parent_canonical_path=expected_cur,
                        name_column_tag=leaf_file_tag,
                    )
                else:
                    pf_stable = ""
                    if (
                        str(bind_kind or "").strip().lower() == "proposed_folder"
                        and not bool(terminal_is_file)
                        and idx == len(cleaned_suffix) - 1
                    ):
                        pf_stable = str(proposed_folder_stable_key or "").strip()
                    pl = self._build_sharepoint_planned_folder_payload(
                        pd,
                        seg,
                        next_branch,
                        allocation_id=aid,
                        parent_canonical_path=expected_cur,
                        proposed_folder_stable_id=pf_stable,
                    )
                self._destination_leaf_forensic_trace_payload(
                    "_sharepoint_bind_planned_segment_chain:insert", pl, "new_row_segment_chain"
                )
                model.append_child_payloads(cur, [pl])
                self._apply_tree_item_visual_state(None, pl)
                rc = model.rowCount(cur)
                if rc < 1:
                    _bind_trace_fail(
                        "other",
                        segment_index=int(idx),
                        detail="append_child_payloads_row_count_zero",
                    )
                    return None
                cur = model.index(rc - 1, 0, cur)
                parts_seed = list(self._path_segments(next_branch))
                created += 1
                self._refresh_destination_item_visibility_index(cur.parent(), expand=True)
                row_inserted = True
                inserted_path = str(pl.get("item_path") or next_branch)[:400]
                inserted_type = str(pl.get("row_kind") or "")[:80]
                inserted_meta = "planning_uuid=" + str(pl.get("planning_uuid") or "")[:40]
            if ft:
                dest_forensic.log_bind_step(
                    trace_id=trace_id,
                    kind=row_kind_trace,
                    segment_index=int(idx),
                    current_parent_path=str(expected_cur)[:400],
                    next_segment_name=str(seg)[:200],
                    next_branch_canonical=str(next_branch)[:400],
                    exact_canonical_child_match=bool(exact_hit),
                    row_inserted=bool(row_inserted),
                    inserted_row_path=str(inserted_path)[:400],
                    inserted_row_type=str(inserted_type)[:80],
                    inserted_row_planning_metadata_excerpt=str(inserted_meta)[:200],
                    graph_authority=bool(graph_strict),
                    strict_path_required=bool(graph_strict),
                )
            last_next_branch = next_branch

        raw_tp = str(projection_target_canonical or "").strip()
        if (
            str(bind_kind or "").strip().lower() == "allocation_descendant"
            and graph_strict
            and str(last_next_branch or "").strip()
        ):
            lb_full = (
                self._canonical_planned_memory_path_for_graph_match(str(last_next_branch).strip())
                or self._canonical_destination_projection_path(str(last_next_branch).strip())
                or str(last_next_branch).strip()
            )
            rp_full = (
                self._canonical_planned_memory_path_for_graph_match(raw_tp) if raw_tp else ""
            ) or (self._canonical_destination_projection_path(raw_tp) if raw_tp else "")
            if (not raw_tp) or (lb_full and rp_full and len(lb_full) > len(rp_full)):
                raw_tp = str(last_next_branch).strip()
                log_info(
                    "destination_descendant_leaf_intended_path_calculated",
                    intended_path=str(lb_full)[:400],
                    prior_projection_target_excerpt=str(rp_full)[:400],
                    bind_context_excerpt=str(bind_context_excerpt or "")[:220],
                )
        if raw_tp:
            term_resolved = (
                self._canonical_destination_projection_path(raw_tp) or self.normalize_memory_path(raw_tp) or raw_tp
            ).strip()
        else:
            term_resolved = (
                self._canonical_destination_projection_path(last_next_branch) or last_next_branch or ""
            ).strip()
        cur_terminal = self._destination_model_index_for_canonical_under_anchor(col0, term_resolved)
        if not cur_terminal.isValid() and term_resolved:
            alt = self._find_visible_destination_item_by_path(term_resolved)
            if alt is not None and isinstance(alt, QModelIndex) and alt.isValid():
                cur_terminal = alt.siblingAtColumn(0) if alt.column() != 0 else alt
        if not cur_terminal.isValid() and last_next_branch:
            term_fb = (self._canonical_destination_projection_path(last_next_branch) or last_next_branch).strip()
            cur_terminal = self._destination_model_index_for_canonical_under_anchor(col0, term_fb)
        cur_payload = self._destination_model_index_user_role_dict(cur_terminal) if cur_terminal.isValid() else {}
        term = self._tree_item_path(cur_payload) or ""
        visible_canon = (self._canonical_destination_projection_path(term) or str(term).strip())[:400]
        raw_target = str(projection_target_canonical or "").strip()
        if raw_target:
            _ic = self._canonical_destination_projection_path(raw_target) or self.normalize_memory_path(raw_target)
            intended_canon = (_ic or raw_target)[:400]
        else:
            intended_canon = visible_canon
        exact_path_match = (not raw_target) or (visible_canon.casefold() == intended_canon.casefold())
        bind_evidence = {
            "bind_kind": str(bind_kind or "")[:80],
            "bind_context_excerpt": str(bind_context_excerpt or "")[:220],
            "source_request_or_allocation_excerpt": str(alloc_for_first or "")[:120],
            "intended_canonical_target_path": intended_canon[:300],
            "resolved_anchor_parent_path": str(anchor_excerpt)[:300],
            "relative_suffix_used": "\\".join(cleaned_suffix)[:220],
            "actual_inserted_visible_path": visible_canon[:300],
            "exact_path_match": bool(exact_path_match),
            "placement_mismatch": not exact_path_match,
            "overlay_path_strict": bool(graph_strict),
        }
        if (not exact_path_match) or self._destination_placement_bind_log_enabled():
            log_info("destination_planned_bind_evidence", **bind_evidence)
        if not exact_path_match:
            self._log_restore_phase("destination_planned_bind_placement_mismatch", **bind_evidence)
        self._log_restore_phase(
            "sharepoint_planned_workspace_bind",
            projection_bind_mode="planned_bind",
            bind_kind=str(bind_kind or "")[:80],
            bind_context_excerpt=str(bind_context_excerpt or "")[:220],
            planned_rows_created=int(created),
            deepest_anchor_excerpt=str(anchor_excerpt)[:220],
            resolved_terminal_excerpt=str(term)[:220],
            canonical_suffix_excerpt="\\".join(cleaned_suffix)[:220],
            projection_target_excerpt=str(target_hint)[:260] if target_hint else "",
            exact_path_match=bool(exact_path_match),
        )
        if ft:
            leaf_pl = self._destination_model_index_user_role_dict(cur_terminal) if cur_terminal.isValid() else {}
            vis_ok = bool(cur_terminal.isValid() and bool(leaf_pl))
            is_live_leaf = destination_payload_is_live_graph_row(leaf_pl)
            is_planned_leaf = destination_payload_is_planned_workspace_row(leaf_pl)
            if exact_path_match and is_live_leaf:
                fre = "exact_visible_live"
            elif exact_path_match and is_planned_leaf:
                fre = "exact_visible_planned"
            elif (not exact_path_match) and vis_ok:
                fre = "misplaced_visible_row"
            elif not vis_ok:
                fre = "missing_visible_row"
            else:
                fre = "other"
            live_at_target = bool(raw_target and is_live_leaf and exact_path_match)
            dest_forensic.log_bind(
                trace_id=trace_id,
                record_phase="bind_terminal",
                kind=row_kind_trace,
                bind_kind=str(bind_kind or "")[:80],
                graph_authority=bool(graph_strict),
                strict_path_required=bool(graph_strict),
                intended_canonical_target_path=str(intended_canon)[:400],
                intended_parent_canonical_path=str(anchor_excerpt)[:400],
                final_visible_path=str(visible_canon)[:400],
                exact_path_match=bool(exact_path_match),
                final_visible_row_exists=bool(vis_ok),
                final_visible_row_type=str(leaf_pl.get("row_kind") or "")[:80],
                final_live_row_exists_at_exact_target=bool(live_at_target),
                final_result_enum=str(fre)[:80],
                source_request_or_allocation_excerpt=str(alloc_for_first)[:120],
            )
        if _pt_trace:
            log_info(
                "destination_exact_target_pipeline_bind_exit_ok",
                projection_target_canonical=str(projection_target_canonical or "")[:400],
                final_visible_path=str(visible_canon)[:400],
                exact_path_match=bool(exact_path_match),
                planned_rows_created=int(created),
            )
        return cur_terminal if cur_terminal.isValid() else None

    def _destination_row_is_overlay_snapshot_candidate_under_graph_folder(self, pl: Any) -> bool:
        """Memory overlay rows preserved across Graph ``replace_all_children`` (planned + restored metadata)."""
        if not isinstance(pl, dict) or pl.get("placeholder"):
            return False
        if destination_payload_is_live_graph_row(pl):
            return False
        return bool(destination_payload_is_memory_overlay_row_for_reuse(pl))

    def _destination_count_planned_snapshot_tree_nodes(self, nodes: list | None) -> int:
        """Count overlay snapshot rows in a nested tree built by :meth:`_destination_collect_planned_workspace_children_under_model`."""
        if not nodes:
            return 0
        n = 0
        for node in nodes:
            if not isinstance(node, dict):
                continue
            pl = node.get("payload")
            if isinstance(pl, dict) and self._destination_row_is_overlay_snapshot_candidate_under_graph_folder(pl):
                n += 1
                n += self._destination_count_planned_snapshot_tree_nodes(node.get("children"))
        return n

    def _destination_collect_planned_workspace_children_under_model(self, parent_ix: QModelIndex) -> list[dict]:
        """Deep snapshot of planned / memory overlay rows under ``parent_ix`` (recursive).

        Each node is ``{"payload": dict, "children": [ ... same shape ... ]}`` so nested planned
        chains survive ``replace_all_children`` (Graph folder refresh).
        """
        out: list[dict] = []
        model = getattr(self, "destination_planning_model", None)
        if model is None:
            return out
        col0 = parent_ix
        if parent_ix.isValid() and parent_ix.column() != 0:
            col0 = parent_ix.siblingAtColumn(0)
        elif not parent_ix.isValid():
            col0 = QModelIndex()
        for r in range(model.rowCount(col0)):
            ix = model.index(r, 0, col0)
            pl = self._destination_model_index_user_role_dict(ix)
            if not self._destination_row_is_overlay_snapshot_candidate_under_graph_folder(pl):
                continue
            children = self._destination_collect_planned_workspace_children_under_model(ix)
            out.append({"payload": dict(pl), "children": children})
        return out

    def _destination_planned_workspace_snapshot_identity_only_tree(self, nodes: list | None) -> list[dict[str, Any]]:
        """Strip path fields from planned snapshot nodes; reconcile resolves paths from planning memory only.

        Stored ``planned_rows_by_parent_path`` entries must not carry model-echo paths that could
        become authoritative via reconcile fallbacks.
        """
        if not nodes:
            return []
        out: list[dict[str, Any]] = []
        for item in nodes:
            if not isinstance(item, dict):
                continue
            pl = item.get("payload")
            ch = item.get("children")
            if isinstance(pl, dict) and self._destination_row_is_overlay_snapshot_candidate_under_graph_folder(dict(pl)):
                pc = dict(pl)
                for k in ("item_path", "destination_path", "display_path"):
                    pc.pop(k, None)
                kids = (
                    self._destination_planned_workspace_snapshot_identity_only_tree(list(ch))
                    if isinstance(ch, list)
                    else []
                )
                out.append({"payload": pc, "children": kids})
            elif isinstance(item, dict) and self._destination_row_is_overlay_snapshot_candidate_under_graph_folder(item):
                pc = dict(item)
                for k in ("item_path", "destination_path", "display_path"):
                    pc.pop(k, None)
                out.append({"payload": pc, "children": []})
        return out

    def _destination_folder_index_canonical_path(self, folder_ix: QModelIndex) -> str:
        """Canonical graph-relative folder path for a destination planning folder index (column 0)."""
        if folder_ix is None or not folder_ix.isValid():
            return ""
        col0 = folder_ix.siblingAtColumn(0) if folder_ix.column() != 0 else folder_ix
        pl = self._destination_model_index_user_role_dict(col0)
        tp = self._tree_item_path(pl) or ""
        return self._canonical_planned_memory_path_for_graph_match(str(tp).strip())

    def _proposed_folder_deterministic_stable_key(self, pf: ProposedFolder) -> str:
        """Stable key for legacy proposals missing ``StableKey`` (same inputs → same key across sessions)."""
        parts = [
            self.normalize_memory_path(str(pf.DestinationPath or "")),
            self.normalize_memory_path(str(pf.ParentPath or "")),
            str(pf.FolderName or "").strip().casefold(),
        ]
        digest = hashlib.sha256("|".join(parts).encode("utf-8")).hexdigest()[:32]
        return f"pf_det_{digest}"

    def _ensure_proposed_folder_stable_key(self, pf: ProposedFolder) -> str:
        sk = str(getattr(pf, "StableKey", "") or "").strip()
        if sk:
            return sk
        pf.StableKey = self._proposed_folder_deterministic_stable_key(pf)
        return pf.StableKey

    def _ensure_proposed_folders_stable_keys_assigned(self) -> None:
        for pf in getattr(self, "proposed_folders", None) or []:
            if isinstance(pf, ProposedFolder):
                self._ensure_proposed_folder_stable_key(pf)

    def _destination_reconcile_option3_snapshot_path_fallback_eligible(self, snap: dict) -> bool:
        """True when persisted snapshot path may be used as last-resort intended canonical (finalize enrich)."""
        if not isinstance(snap, dict) or snap.get("placeholder"):
            return False
        if destination_payload_is_planned_workspace_row(snap):
            # Stale exports may carry a display name that disagrees with the last path segment; do not
            # treat such snapshot paths as authoritative intended canonical (regression: phantom rows).
            nm = str(snap.get("name") or "").strip()
            path = str(snap.get("item_path") or snap.get("destination_path") or "").strip()
            if nm and path:
                segs = [p for p in str(path).replace("/", "\\").split("\\") if p]
                if segs and segs[-1].strip().casefold() != nm.casefold():
                    return False
            return True
        if destination_payload_workspace_row_state(snap) == WORKSPACE_ROW_STATE_CACHED_PROVISIONAL:
            return True
        if bool(snap.get("planned_allocation")) or bool(snap.get("planned_allocation_descendant")):
            return True
        rk = str(snap.get("row_kind") or "").strip().lower()
        if rk in {"planned_folder", "planned_file", "cached_provisional_shell"}:
            return True
        return False

    def _destination_reconcile_resolve_intended_canonical_meta(
        self, snap: dict, *, parent_folder_canonical: str
    ) -> tuple[str, dict[str, Any]]:
        """Resolve intended path from planning memory; return ``(canonical_path, trace_meta)``."""
        meta: dict[str, Any] = {
            "matched_source_type": "",
            "proposal_stable_id_excerpt": "",
            "intended_fallback_last_resort_snapshot": False,
        }
        if not isinstance(snap, dict):
            return "", meta
        graph_auth = destination_authority_contract.graph_owns_visible_real_destination_structure(self)
        ghost_path_excerpt = str(snap.get("item_path") or snap.get("destination_path") or "").strip()

        def _finalize(raw_in: str, source_type: str) -> tuple[str, dict[str, Any]]:
            out = self._canonical_planned_memory_path_for_graph_match(str(raw_in or "").strip())
            if out:
                meta["matched_source_type"] = str(source_type or "")[:80]
            return out, meta

        aid = str(snap.get("allocation_id") or "").strip()
        if aid:
            saw_move_for_aid = False
            for move in getattr(self, "planned_moves", None) or []:
                if not isinstance(move, dict):
                    continue
                mid = str(move.get("request_id") or move.get("allocation_id") or "").strip()
                if mid != aid:
                    continue
                saw_move_for_aid = True
                proj = self._allocation_projection_path(move)
                if not proj:
                    break
                out, _m = _finalize(proj, "allocation_move")
                if out:
                    return out, meta
                break
            if not saw_move_for_aid:
                log_warn(
                    "destination_reconcile_allocation_id_not_found_in_planned_moves",
                    allocation_id_excerpt=str(aid)[:120],
                )

        pfsid = str(snap.get("proposed_folder_stable_id") or "").strip()
        if pfsid:
            meta["proposal_stable_id_excerpt"] = str(pfsid)[:120]
            for pf in getattr(self, "proposed_folders", None) or []:
                if not isinstance(pf, ProposedFolder):
                    continue
                if str(getattr(pf, "StableKey", "") or "").strip() != pfsid:
                    continue
                dest = self._proposed_destination_path(pf)
                if dest:
                    out, _m = _finalize(dest, "proposed_folder_stable_key")
                    if out:
                        return out, meta
            meta["matched_source_type"] = "proposed_folder_stable_key_not_found"

        name_key = str(snap.get("name") or "").strip()
        pfc_graph = self._canonical_planned_memory_path_for_graph_match(str(parent_folder_canonical or "").strip())
        if name_key:
            matches: list[ProposedFolder] = []
            for pf in getattr(self, "proposed_folders", None) or []:
                if not isinstance(pf, ProposedFolder):
                    continue
                if str(pf.FolderName or "").strip() != name_key:
                    continue
                ppar_raw = str(pf.ParentPath or "").strip()
                ppar_graph = self._canonical_planned_memory_path_for_graph_match(ppar_raw)
                if pfc_graph and ppar_graph and self._destination_planned_snapshot_paths_exact_canonical(
                    ppar_graph, pfc_graph
                ):
                    matches.append(pf)
                elif not pfc_graph:
                    matches.append(pf)
            if len(matches) == 1:
                dest = self._proposed_destination_path(matches[0])
                if dest:
                    out, _m = _finalize(dest, "proposed_folder_name_parent_heuristic")
                    if out:
                        return out, meta
            elif len(matches) > 1:
                meta["matched_source_type"] = "proposed_folder_name_parent_heuristic_ambiguous"

        # Identity-only snapshots strip paths; nested planned_file nodes often have no allocation_id in the
        # payload. Resolve from planned_moves by parent folder + leaf name (file allocations only).
        if name_key and str(snap.get("row_kind") or "").strip().lower() == "planned_file":
            file_matches: list[dict] = []
            for move in getattr(self, "planned_moves", None) or []:
                if not isinstance(move, dict):
                    continue
                if not self._planned_move_terminal_is_file_leaf(move):
                    continue
                leaf = str(self._move_target_name(move) or "").strip()
                if not leaf or leaf.casefold() != name_key.casefold():
                    continue
                parent_m = str(self._allocation_parent_path(move) or "").strip()
                if not parent_m:
                    proj_try = self._allocation_projection_path(move)
                    segs = self._path_segments(proj_try) if proj_try else []
                    if len(segs) >= 2:
                        parent_m = "\\".join(segs[:-1])
                    parent_m = self._canonical_planned_memory_path_for_graph_match(parent_m)
                else:
                    parent_m = self._canonical_planned_memory_path_for_graph_match(parent_m)
                if pfc_graph and parent_m and self._destination_planned_snapshot_paths_exact_canonical(
                    parent_m, pfc_graph
                ):
                    file_matches.append(move)
                elif not pfc_graph:
                    file_matches.append(move)
            if len(file_matches) == 1:
                proj_fm = self._allocation_projection_path(file_matches[0])
                if proj_fm:
                    out_fm, _m = _finalize(proj_fm, "allocation_file_parent_name_heuristic")
                    if out_fm:
                        return out_fm, meta
            elif len(file_matches) > 1:
                meta["matched_source_type"] = "allocation_file_parent_name_heuristic_ambiguous"

        br = self._destination_forensic_canon_diff_branch_hit(str(parent_folder_canonical or "").strip())
        if br and graph_auth:
            sname = str(snap.get("name") or "").strip()
            cand_pf: list[str] = []
            for pf in getattr(self, "proposed_folders", None) or []:
                if not isinstance(pf, ProposedFolder):
                    continue
                if sname and str(pf.FolderName or "").strip() != sname:
                    continue
                pr = str(pf.ParentPath or "").strip()
                dr = str(pf.DestinationPath or "").strip()
                cand_pf.append(
                    f"FolderName={str(pf.FolderName or '')[:80]}|ParentPath_raw={pr[:220]}"
                    f"|DestPath_raw={dr[:220]}|ParentPath_graph={self._canonical_planned_memory_path_for_graph_match(pr)[:220]}"
                    f"|DestPath_graph={self._canonical_planned_memory_path_for_graph_match(dr)[:220]}"
                )
            log_info(
                "destination_forensic_reconcile_intended_resolve_bundle",
                branch_prefix_excerpt=str(br)[:200],
                visible_parent_folder_canonical_raw=str(parent_folder_canonical or "")[:400],
                visible_parent_folder_graph_canonical=str(pfc_graph)[:400],
                snapshot_name_excerpt=sname[:120],
                snapshot_path_raw_excerpt=str(ghost_path_excerpt)[:400],
                snapshot_path_graph_canonical=self._canonical_planned_memory_path_for_graph_match(
                    str(ghost_path_excerpt or "").strip()
                )[:400],
                proposed_same_name_parent_candidates=" || ".join(cand_pf[:14])[:2400],
                name_heuristic_ambiguous=bool(
                    meta.get("matched_source_type") == "proposed_folder_name_parent_heuristic_ambiguous"
                ),
                detail="reconcile_resolve_empty_compare_proposed_parent_raw_vs_visible_parent_graph_canon",
            )
        if graph_auth and ghost_path_excerpt and self._destination_reconcile_option3_snapshot_path_fallback_eligible(snap):
            fb = self._canonical_planned_memory_path_for_graph_match(ghost_path_excerpt)
            if fb:
                meta["intended_fallback_last_resort_snapshot"] = True
                if not str(meta.get("matched_source_type") or "").strip():
                    meta["matched_source_type"] = "option3_snapshot_path_fallback"
                log_info(
                    "destination_reconcile_intended_snapshot_path_fallback",
                    canonical_intended=str(fb)[:400],
                    snapshot_raw_excerpt=str(ghost_path_excerpt)[:400],
                    planning_uuid_excerpt=str(snap.get("planning_uuid") or "")[:80],
                    allocation_id_excerpt=str(snap.get("allocation_id") or "")[:80],
                    row_kind_excerpt=str(snap.get("row_kind") or "")[:40],
                    workspace_row_state_excerpt=str(snap.get("workspace_row_state") or "")[:40],
                )
                return fb, meta
        if graph_auth and ghost_path_excerpt:
            log_info(
                "destination_snapshot_path_ignored",
                path_excerpt=str(ghost_path_excerpt)[:400],
                planning_uuid_excerpt=str(snap.get("planning_uuid") or "")[:80],
                allocation_id_excerpt=str(snap.get("allocation_id") or "")[:80],
                proposed_folder_stable_id_excerpt=str(snap.get("proposed_folder_stable_id") or "")[:80],
                matched_planning_source_type=str(meta.get("matched_source_type") or "")[:80],
                detail="snapshot_paths_not_used_as_intended_under_graph_authority",
            )
        return "", meta

    def _destination_reconcile_intended_canonical_for_planned_snapshot(
        self, snap: dict, *, parent_folder_canonical: str
    ) -> str:
        path, _meta = self._destination_reconcile_resolve_intended_canonical_meta(
            snap, parent_folder_canonical=parent_folder_canonical
        )
        return path

    def _destination_planned_snapshot_payload_with_intended_paths(self, snap: dict, intended_canon: str) -> dict:
        pl = dict(snap)
        ic = str(intended_canon or "").strip()
        if ic:
            pl["item_path"] = ic
            pl["destination_path"] = ic
            pl["display_path"] = ic
        return pl

    def _destination_find_planned_workspace_row_for_snapshot_reconcile(
        self, snap: dict, *, path_lookup_canonical: str = ""
    ) -> QModelIndex:
        """Walk the planning model: match ``planning_uuid``, else ``allocation_id``, else canonical item path."""
        model = getattr(self, "destination_planning_model", None)
        if model is None or not isinstance(snap, dict):
            return QModelIndex()
        pu_snap = str(snap.get("planning_uuid") or "").strip()
        aid_snap = str(snap.get("allocation_id") or "").strip()
        snap_path = str(snap.get("item_path") or snap.get("destination_path") or "").strip()
        graph_snap = destination_authority_contract.graph_owns_visible_real_destination_structure(self)
        path_for_lookup = str(path_lookup_canonical or "").strip()
        if not path_for_lookup and not graph_snap:
            path_for_lookup = snap_path
        intended_cf = ""
        if path_for_lookup:
            ic = self._canonical_destination_projection_path(path_for_lookup) or self.normalize_memory_path(
                path_for_lookup
            )
            intended_cf = (ic or "").strip().casefold()

        def _c0(ix: QModelIndex) -> QModelIndex:
            return ix.siblingAtColumn(0) if ix.column() != 0 else ix

        for ix in model.iter_depth_first():
            ch2 = self._destination_model_index_user_role_dict(ix)
            if ch2.get("placeholder"):
                continue
            if not destination_payload_is_planned_workspace_row(ch2):
                continue
            if pu_snap and str(ch2.get("planning_uuid") or "").strip() == pu_snap:
                return _c0(ix)
        for ix in model.iter_depth_first():
            ch2 = self._destination_model_index_user_role_dict(ix)
            if ch2.get("placeholder"):
                continue
            if not destination_payload_is_planned_workspace_row(ch2):
                continue
            if aid_snap and str(ch2.get("allocation_id") or "").strip() == aid_snap:
                return _c0(ix)
        if intended_cf:
            for ix in model.iter_depth_first():
                ch2 = self._destination_model_index_user_role_dict(ix)
                if ch2.get("placeholder"):
                    continue
                if not destination_payload_is_planned_workspace_row(ch2):
                    continue
                rp2 = self._destination_row_raw_path_for_path_lookup_match(ch2) or str(ch2.get("item_path") or "") or ""
                ic2 = self._canonical_destination_projection_path(rp2) or self.normalize_memory_path(rp2)
                if (ic2 or "").strip().casefold() == intended_cf:
                    return _c0(ix)
        return QModelIndex()

    def _destination_planned_snapshot_paths_exact_canonical(self, snap_path: str, live_path: str) -> bool:
        a = (
            self._canonical_destination_projection_path(str(snap_path or "").strip())
            or self.normalize_memory_path(str(snap_path or "").strip())
        ).strip()
        b = (
            self._canonical_destination_projection_path(str(live_path or "").strip())
            or self.normalize_memory_path(str(live_path or "").strip())
        ).strip()
        if not a or not b:
            return False
        return bool(self._destination_parent_match_details(a, b).get("exact_match"))

    def _destination_reconcile_graph_enforcement_runtime_enabled(self) -> bool:
        """Always False: reconcile/bind/overlay must not mutate Microsoft Graph.

        SharePoint folder creation and corrective moves run only in the execution phase
        (transfer job runner), not during planning or UI reconcile.
        """
        return False

    def _destination_reconcile_graph_authoritative_enforcement_for_path(
        self,
        *,
        enforce_full_canon: str,
        snap: dict,
        parent_col0: QModelIndex,
    ) -> dict[str, Any]:
        """No-op: Graph mkdir/move during reconcile is forbidden (see execution phase only)."""
        _ = (enforce_full_canon, snap, parent_col0)
        return {"corrections": 0, "verified": False, "error": ""}

    def _destination_reconcile_planned_rows_after_graph_folder_load(
        self, parent_ix: QModelIndex, snapshots: list, *, allow_reappend: bool = True
    ) -> dict[str, int]:
        """Merge or re-append planned workspace snapshot trees after Graph ``replace_all_children``.

        Intended canonical paths are resolved from ``planned_moves`` / ``proposed_folders`` only.
        Snapshot ``item_path`` / ``destination_path`` are not authoritative. Under Graph authority,
        rows that do not resolve to planning memory are skipped (not re-appended).
        Snapshots supply identity (``planning_uuid`` / ``allocation_id`` / ``proposed_folder_stable_id``)
        and nested structure only.

        Name-only live match is allowed only when not under Graph authority and exactly one live sibling
        matches. Returns counts: ``matched_live``, ``reattached``, ``lost``.
        """
        empty = {"matched_live": 0, "reattached": 0, "lost": 0, "no_op": 0}
        model = getattr(self, "destination_planning_model", None)
        if model is None or not snapshots:
            return dict(empty)
        graph_auth_rec = destination_authority_contract.graph_owns_visible_real_destination_structure(self)
        norm_nodes: list[dict[str, Any]] = []
        for item in snapshots:
            if isinstance(item, dict) and isinstance(item.get("payload"), dict):
                ch = item.get("children")
                norm_nodes.append(
                    {
                        "payload": dict(item["payload"]),
                        "children": list(ch) if isinstance(ch, list) else [],
                    }
                )
            elif isinstance(item, dict) and destination_payload_is_planned_workspace_row(item):
                norm_nodes.append({"payload": dict(item), "children": []})
        if not norm_nodes:
            return dict(empty)
        seen_identity: set[str] = set()
        if not parent_ix.isValid():
            parent_col0 = QModelIndex()
            parent_folder_pl: dict = {}
            parent_folder_canon = ""
        else:
            parent_col0 = parent_ix.siblingAtColumn(0) if parent_ix.column() != 0 else parent_ix
            parent_folder_pl = self._destination_model_index_user_role_dict(parent_col0)
            parent_folder_canon = self._canonical_planned_memory_path_for_graph_match(
                str(self._tree_item_path(parent_folder_pl) or "").strip()
            )
        log_info(
            "destination_reconcile_planned_rows_entered",
            parent_path=str(self._destination_semantic_path(parent_folder_pl) or "")[:400],
        )

        def _reconcile_node(p_ix: QModelIndex, node: dict) -> dict[str, int]:
            st = {"matched_live": 0, "reattached": 0, "lost": 0, "no_op": 0}
            snap = node.get("payload")
            nested = node.get("children") if isinstance(node.get("children"), list) else []
            if not isinstance(snap, dict) or not destination_payload_is_planned_workspace_row(snap):
                st["lost"] += self._destination_count_planned_snapshot_tree_nodes(nested)
                return st
            if model is None:
                st["lost"] += 1 + self._destination_count_planned_snapshot_tree_nodes(nested)
                return st
            if p_ix.isValid() and p_ix.column() != 0:
                col0 = p_ix.siblingAtColumn(0)
            else:
                col0 = QModelIndex() if not p_ix.isValid() else p_ix
            ctx_parent_canon = self._destination_folder_index_canonical_path(col0)
            intended_canon, _resolve_meta = self._destination_reconcile_resolve_intended_canonical_meta(
                snap, parent_folder_canonical=ctx_parent_canon
            )
            intended_canon = self._normalize_to_graph_canonical_path(str(intended_canon or "").strip())
            snap_path_model = str(snap.get("item_path") or snap.get("destination_path") or "").strip()
            if graph_auth_rec and not str(intended_canon or "").strip():
                lost_sub = 1 + self._destination_count_planned_snapshot_tree_nodes(nested)
                st["lost"] += lost_sub
                log_info(
                    "destination_snapshot_orphan_skipped",
                    parent_folder_canonical_excerpt=str(ctx_parent_canon)[:400],
                    reconcile_parent_graph_canonical_excerpt=str(ctx_parent_canon)[:400],
                    reconcile_resolve_matched_source_type_excerpt=str(_resolve_meta.get("matched_source_type") or "")[
                        :120
                    ],
                    planning_uuid_excerpt=str(snap.get("planning_uuid") or "")[:80],
                    allocation_id_excerpt=str(snap.get("allocation_id") or "")[:80],
                    proposed_folder_stable_id_excerpt=str(snap.get("proposed_folder_stable_id") or "")[:80],
                    name_excerpt=str(snap.get("name") or "")[:120],
                    snapshot_path_excerpt=str(snap_path_model)[:400],
                    snapshot_path_graph_canonical_excerpt=self._canonical_planned_memory_path_for_graph_match(
                        snap_path_model
                    )[:400],
                    lost_subtree_nodes=int(lost_sub),
                    detail="no_planned_moves_or_proposed_match_under_graph_authority",
                    hint_under_graph_authority="compare_proposed_ParentPath_and_planned_moves_via__canonical_planned_memory_path_for_graph_match",
                )
                return st
            if graph_auth_rec:
                path_for_live = str(intended_canon or "").strip()
            else:
                path_for_live = str(intended_canon or "").strip() or snap_path_model
            graph_enf: dict[str, Any] = {"corrections": 0, "verified": False, "error": ""}
            enforce_target = str(path_for_live or "").strip()
            if (
                graph_auth_rec
                and enforce_target
                and self._destination_reconcile_graph_enforcement_runtime_enabled()
            ):
                graph_enf = self._destination_reconcile_graph_authoritative_enforcement_for_path(
                    enforce_full_canon=enforce_target,
                    snap=snap,
                    parent_col0=col0,
                )
                st["reattached"] += int(graph_enf.get("corrections") or 0)
            log_info(
                "destination_reconcile_planned_row_pre",
                row_kind=str(snap.get("row_kind") or "")[:40],
                planning_uuid_excerpt=str(snap.get("planning_uuid") or "")[:80],
                allocation_id_excerpt=str(snap.get("allocation_id") or "")[:80],
                proposed_folder_stable_id_excerpt=str(snap.get("proposed_folder_stable_id") or "")[:80],
                matched_planning_source_type=str(_resolve_meta.get("matched_source_type") or "")[:80],
                resolved_intended_canonical_path=str(intended_canon)[:400],
                intended_fallback_last_resort_snapshot=bool(
                    _resolve_meta.get("intended_fallback_last_resort_snapshot")
                ),
                parent_folder_canonical_excerpt=str(ctx_parent_canon)[:400],
                graph_authoritative_enforcement_corrections=int(graph_enf.get("corrections") or 0),
                graph_authoritative_enforcement_verified=bool(graph_enf.get("verified")),
                graph_authoritative_enforcement_error_excerpt=str(graph_enf.get("error") or "")[:300],
            )

            def _identity_key_reconcile(snap_dict: dict, intended: str) -> str:
                pu = str(snap_dict.get("planning_uuid") or "").strip()
                if pu:
                    return f"pu:{pu}"
                aid = str(snap_dict.get("allocation_id") or "").strip()
                if aid:
                    return f"aid:{aid}"
                p = str(intended or "").strip() or str(
                    snap_dict.get("item_path") or snap_dict.get("destination_path") or ""
                ).strip()
                return f"path:{p.casefold()}" if p else ""

            idk = _identity_key_reconcile(snap, intended_canon)
            if idk and idk in seen_identity:
                return st
            if idk:
                seen_identity.add(idk)
            snap_name = str(snap.get("name") or "").strip()
            matched: QModelIndex | None = None
            matched_by_exact_path = False
            name_match_indices: list[QModelIndex] = []
            for r in range(model.rowCount(col0)):
                ix = model.index(r, 0, col0)
                ch = self._destination_model_index_user_role_dict(ix)
                if ch.get("placeholder"):
                    continue
                if not destination_payload_is_reconcile_merge_target_row(ch):
                    continue
                rp = self._destination_row_raw_path_for_path_lookup_match(ch) or str(ch.get("item_path") or "") or ""
                if path_for_live and rp and self._destination_planned_snapshot_paths_exact_canonical(path_for_live, rp):
                    matched = ix
                    matched_by_exact_path = True
                    break
                if snap_name and str(ch.get("name") or "").strip().casefold() == snap_name.casefold():
                    name_match_indices.append(ix)
            used_name_only_fallback = False
            if matched is None and len(name_match_indices) == 1 and not graph_auth_rec:
                matched = name_match_indices[0]
                used_name_only_fallback = True
            match_method = "none"
            if matched is not None and matched.isValid():
                if matched_by_exact_path:
                    match_method = "canonical_path"
                elif used_name_only_fallback:
                    match_method = "name"
            if self._destination_reconcile_trace_enabled():
                mb = match_method if match_method != "none" else "none"
                if mb == "none" and (
                    int(graph_enf.get("corrections") or 0) > 0 or bool(graph_enf.get("verified"))
                ):
                    mb = "graph_authoritative_enforcement"
                dest_forensic.log_reconcile(
                    record_phase="reconcile_pre",
                    parent_folder_canonical_excerpt=str(parent_folder_canon)[:400],
                    planned_snapshot_path_excerpt=str(snap_path_model)[:400],
                    intended_from_planning_canonical_excerpt=str(intended_canon)[:400],
                    matched_planning_source_type_excerpt=str(_resolve_meta.get("matched_source_type") or "")[:80],
                    intended_fallback_last_resort_snapshot=bool(
                        _resolve_meta.get("intended_fallback_last_resort_snapshot")
                    ),
                    row_kind_excerpt=str(snap.get("row_kind") or "")[:40],
                    allocation_id_excerpt=str(snap.get("allocation_id") or "")[:80],
                    proposed_folder_stable_id_excerpt=str(snap.get("proposed_folder_stable_id") or "")[:80],
                    planned_snapshot_name_excerpt=str(snap_name)[:200],
                    planning_uuid_excerpt=str(snap.get("planning_uuid") or "")[:80],
                    graph_authority=bool(graph_auth_rec),
                    match_basis_selected=str(mb)[:40],
                    graph_authoritative_enforcement_corrections=int(graph_enf.get("corrections") or 0),
                    graph_authoritative_enforcement_verified=bool(graph_enf.get("verified")),
                    name_only_fallback_would_be_unsafe_under_graph=bool(graph_auth_rec and len(name_match_indices) == 1),
                )
            target_for_children: QModelIndex | None = None
            matched_pl_precheck = (
                self._destination_model_index_user_role_dict(matched)
                if matched is not None and matched.isValid()
                else {}
            )
            pre_live_path_conflict = (
                self._destination_row_raw_path_for_path_lookup_match(matched_pl_precheck)
                or str(matched_pl_precheck.get("item_path") or matched_pl_precheck.get("destination_path") or "")
                or ""
            ).strip()
            graph_bind_overlay_conflict = (
                matched is not None
                and matched.isValid()
                and matched_by_exact_path
                and graph_auth_rec
                and destination_payload_is_live_graph_row(matched_pl_precheck)
                and destination_payload_is_planned_workspace_row(snap)
            )
            if graph_bind_overlay_conflict:
                log_info(
                    "destination_live_memory_conflict_detected_after_graph_bind",
                    intended_path_excerpt=str(intended_canon or snap_name)[:400],
                    snapshot_model_path_excerpt=str(snap_path_model)[:400],
                    live_path_excerpt=str(pre_live_path_conflict)[:400],
                    row_kind_excerpt=str(snap.get("row_kind") or "")[:40],
                )
                _rec_g = LiveMemoryConflictRecord(
                    kind=REVIEW_TYPE_LIVE_MEMORY_DUPLICATE,
                    subtype="live_duplicate_graph_bind_planned_overlay",
                    planned_or_proposed_path=str(intended_canon or snap_path_model or "")[:512],
                    live_graph_path=str(pre_live_path_conflict or "")[:512],
                    live_item_id=str(matched_pl_precheck.get("id") or matched_pl_precheck.get("graph_item_id") or "")[
                        :240
                    ],
                    live_item_name=str(matched_pl_precheck.get("name") or "")[:240],
                    live_item_type="folder" if bool(matched_pl_precheck.get("is_folder", True)) else "file",
                    suggested_actions=(
                        "Review: live Graph item already exists at this path while planning still has a "
                        "pending overlay row; both are kept visible."
                    ),
                )
                _merged_conf = merge_unique(
                    [_rec_g],
                    list(getattr(self, "_runtime_live_memory_conflict_rows", None) or []),
                )
                self._runtime_live_memory_conflict_rows = _merged_conf
                log_info(
                    "destination_live_memory_conflict_created_after_graph_bind",
                    subtype="live_duplicate_graph_bind_planned_overlay",
                    intended_path_excerpt=str(intended_canon or snap_name)[:400],
                )
                snap_payload_g = self._destination_planned_snapshot_payload_with_intended_paths(snap, intended_canon)
                snap_payload_g["live_memory_overlay_conflict_with_live_row"] = True
                model.remove_placeholder_children(col0)
                model.append_child_payloads(col0, [snap_payload_g])
                rc_g = int(model.rowCount(col0))
                st["reattached"] += 1
                if rc_g > 0:
                    target_for_children = model.index(rc_g - 1, 0, col0)
                self._apply_tree_item_visual_state(None, snap_payload_g)
                self._refresh_destination_item_visibility_index(col0, expand=True)
                log_info(
                    "destination_graph_bind_overlay_conflict_row_created",
                    intended_path_excerpt=str(intended_canon or snap_name)[:400],
                )
                if nested and target_for_children is not None and target_for_children.isValid():
                    for ch_node in nested:
                        if not isinstance(ch_node, dict):
                            continue
                        sub_g = _reconcile_node(target_for_children, ch_node)
                        st["matched_live"] += sub_g["matched_live"]
                        st["reattached"] += sub_g["reattached"]
                        st["lost"] += sub_g["lost"]
                        st["no_op"] += int(sub_g.get("no_op", 0) or 0)
                elif nested:
                    st["lost"] += self._destination_count_planned_snapshot_tree_nodes(nested)
                return st
            if matched is not None and matched.isValid():
                pre_live_path = self._destination_row_raw_path_for_path_lookup_match(
                    self._destination_model_index_user_role_dict(matched)
                )
                merged = dict(matched.data(Qt.UserRole) or {})
                merged["workspace_row_state"] = WORKSPACE_ROW_STATE_LIVE_CONFIRMED
                merged["verification_state"] = "live_confirmed"
                merged["row_kind"] = "live_folder" if bool(merged.get("is_folder", True)) else "live_file"
                pu = str(snap.get("planning_uuid") or "").strip()
                if pu:
                    merged["planning_uuid"] = pu
                aid = str(snap.get("allocation_id") or "").strip()
                if aid:
                    merged["allocation_id"] = aid
                pfs = str(snap.get("proposed_folder_stable_id") or "").strip()
                if pfs:
                    merged["proposed_folder_stable_id"] = pfs
                merged.pop("workspace_planned_row", None)
                merged.pop("non_graph_structural_authority", None)
                merged.pop("destination_overlay_kind", None)

                def _mut(p, m=merged):
                    p.clear()
                    p.update(m)

                model.update_payload_for_index(matched, _mut)
                self._apply_tree_item_visual_state(None, merged)
                self._refresh_destination_item_visibility_index(matched)
                self._log_restore_phase(
                    "sharepoint_planned_workspace_reconcile",
                    projection_bind_mode="reconcile",
                    transition="planned_to_live",
                    path_excerpt=str(intended_canon or snap_name)[:220],
                )
                log_info(
                    "destination_reconcile_planned_row_after_graph_replace",
                    intended_path=str(intended_canon or snap_name)[:400],
                    snapshot_model_path_excerpt=str(snap_path_model)[:400],
                    matched_existing=True,
                    reattached=False,
                    match_method=str(match_method)[:40],
                )
                st["matched_live"] += 1
                target_for_children = matched
                if self._destination_reconcile_trace_enabled():
                    post_path = self._destination_row_raw_path_for_path_lookup_match(merged) or str(
                        merged.get("item_path") or ""
                    )
                    exact_equiv = bool(
                        intended_canon
                        and post_path
                        and self._destination_planned_snapshot_paths_exact_canonical(intended_canon, post_path)
                    )
                    post_result = "replaced_by_exact_live" if matched_by_exact_path else "merged_to_non_exact_live"
                    dest_forensic.log_reconcile(
                        record_phase="reconcile_post",
                        parent_folder_canonical_excerpt=str(parent_folder_canon)[:400],
                        pre_reconcile_planned_path_excerpt=str(snap_path_model)[:400],
                        intended_from_planning_canonical_excerpt=str(intended_canon)[:400],
                        pre_reconcile_row_type="planned_workspace_snapshot",
                        matched_live_row_path_excerpt=str(pre_live_path or "")[:400],
                        match_basis=str(match_method)[:40],
                        post_reconcile_result=str(post_result)[:40],
                        exact_canonical_equivalence_proven=bool(exact_equiv),
                        graph_authority=bool(graph_auth_rec),
                    )
                    if graph_auth_rec and not matched_by_exact_path:
                        dest_forensic.warn_unsafe_name_fallback_under_graph(
                            context="planned_workspace_reconcile",
                            planned_path_excerpt=str(intended_canon)[:400],
                            live_path_excerpt=str(pre_live_path or "")[:400],
                        )
            else:
                if len(name_match_indices) > 1:
                    lost_sub = 1 + self._destination_count_planned_snapshot_tree_nodes(nested)
                    st["lost"] += lost_sub
                    log_info(
                        "destination_reconcile_planned_row_ambiguous_live_name_matches",
                        snapshot_name_excerpt=str(snap_name)[:200],
                        live_name_match_count=int(len(name_match_indices)),
                        lost_subtree_nodes=int(lost_sub),
                    )
                    return st
                ex_ix = self._destination_find_planned_workspace_row_for_snapshot_reconcile(
                    snap, path_lookup_canonical=intended_canon
                )
                exp_parent_canon = self._destination_folder_index_canonical_path(col0)
                allow_create = bool(allow_reappend)
                cur_raw = ""
                act_parent_canon = ""
                if ex_ix.isValid():
                    ex_pl = self._destination_model_index_user_role_dict(ex_ix)
                    cur_raw = (
                        self._destination_row_raw_path_for_path_lookup_match(ex_pl)
                        or str(ex_pl.get("item_path") or ex_pl.get("destination_path") or "")
                        or ""
                    ).strip()
                    p_ex = ex_ix.parent()
                    if p_ex.isValid():
                        act_parent_canon = self._destination_folder_index_canonical_path(p_ex)
                cur_excerpt = str(cur_raw)[:400] if cur_raw else ""
                intended_excerpt = str(intended_canon or snap_name)[:400]
                snap_payload = self._destination_planned_snapshot_payload_with_intended_paths(snap, intended_canon)

                if not ex_ix.isValid():
                    if not allow_create:
                        self._log_restore_phase(
                            "sharepoint_planned_workspace_reconcile",
                            projection_bind_mode="reconcile",
                            transition="skipped_reappend_shallow_load",
                            path_excerpt=str(intended_canon or snap_name)[:220],
                        )
                        log_info(
                            "destination_reconcile_planned_row_after_graph_replace",
                            intended_path=intended_excerpt,
                            snapshot_model_path_excerpt=str(snap_path_model)[:400],
                            current_path="",
                            reconcile_action="none",
                            matched_existing=False,
                            reattached=False,
                            match_method="none",
                            reason="shallow_load_no_reappend",
                        )
                        st["lost"] += 1 + self._destination_count_planned_snapshot_tree_nodes(nested)
                        if self._destination_reconcile_trace_enabled():
                            dest_forensic.log_reconcile(
                                record_phase="reconcile_post",
                                post_reconcile_result="preserved",
                                detail="skipped_reappend_shallow_load",
                                planned_snapshot_path_excerpt=str(snap_path_model)[:400],
                                intended_from_planning_canonical_excerpt=str(intended_canon)[:400],
                                graph_authority=bool(graph_auth_rec),
                            )
                        return st
                    model.remove_placeholder_children(col0)
                    rc_before = int(model.rowCount(col0))
                    model.append_child_payloads(col0, [snap_payload])
                    rc_after = int(model.rowCount(col0))
                    self._apply_tree_item_visual_state(None, snap_payload)
                    self._refresh_destination_item_visibility_index(col0, expand=True)
                    self._log_restore_phase(
                        "sharepoint_planned_workspace_reconcile",
                        projection_bind_mode="reconcile",
                        transition="reappended_planned",
                        path_excerpt=str(intended_canon or snap_name)[:220],
                    )
                    log_info(
                        "destination_reconcile_planned_row_after_graph_replace",
                        intended_path=intended_excerpt,
                        snapshot_model_path_excerpt=str(snap_path_model)[:400],
                        current_path="",
                        reconcile_action="create",
                        matched_existing=False,
                        reattached=True,
                        match_method="reattached_planned",
                    )
                    st["reattached"] += 1
                    if rc_after > rc_before:
                        target_for_children = model.index(rc_after - 1, 0, col0)
                    if self._destination_reconcile_trace_enabled():
                        dest_forensic.log_reconcile(
                            record_phase="reconcile_post",
                            post_reconcile_result="reappended_planned",
                            planned_snapshot_path_excerpt=str(snap_path_model)[:400],
                            intended_from_planning_canonical_excerpt=str(intended_canon)[:400],
                            graph_authority=bool(graph_auth_rec),
                            exact_canonical_equivalence_proven=True,
                        )
                else:
                    path_ok = bool(
                        intended_canon
                        and cur_raw
                        and self._destination_planned_snapshot_paths_exact_canonical(intended_canon, cur_raw)
                    )
                    parent_ok = bool(
                        exp_parent_canon
                        and act_parent_canon
                        and self._destination_planned_snapshot_paths_exact_canonical(
                            exp_parent_canon, act_parent_canon
                        )
                    )
                    if path_ok and parent_ok:
                        self._log_restore_phase(
                            "sharepoint_planned_workspace_reconcile",
                            projection_bind_mode="reconcile",
                            transition="planned_placed_noop",
                            path_excerpt=str(intended_canon or snap_name)[:220],
                        )
                        log_info(
                            "destination_reconcile_planned_row_after_graph_replace",
                            intended_path=intended_excerpt,
                            snapshot_model_path_excerpt=str(snap_path_model)[:400],
                            current_path=cur_excerpt,
                            reconcile_action="no_op",
                            matched_existing=True,
                            reattached=False,
                            match_method="planned_workspace",
                        )
                        st["no_op"] += 1
                        target_for_children = ex_ix
                        if self._destination_reconcile_trace_enabled():
                            dest_forensic.log_reconcile(
                                record_phase="reconcile_post",
                                post_reconcile_result="planned_noop",
                                planned_snapshot_path_excerpt=str(snap_path_model)[:400],
                                intended_from_planning_canonical_excerpt=str(intended_canon)[:400],
                                graph_authority=bool(graph_auth_rec),
                                exact_canonical_equivalence_proven=True,
                            )
                    elif not parent_ok:
                        spec = model.remove_node_at(ex_ix)
                        if not spec:
                            st["lost"] += 1 + self._destination_count_planned_snapshot_tree_nodes(nested)
                            log_info(
                                "destination_reconcile_planned_row_after_graph_replace",
                                intended_path=intended_excerpt,
                                snapshot_model_path_excerpt=str(snap_path_model)[:400],
                                current_path=cur_excerpt,
                                reconcile_action="move",
                                matched_existing=True,
                                reattached=False,
                                match_method="none",
                                reason="remove_node_at_failed",
                            )
                        else:
                            root_pl = dict(spec[0])
                            root_pl.update(snap_payload)
                            root_pl["verification_state"] = "planned_only"
                            rk = str(snap.get("row_kind") or "").strip()
                            if rk:
                                root_pl["row_kind"] = rk
                            spec2 = (root_pl, spec[1])
                            model.remove_placeholder_children(col0)
                            model.append_nested_child(col0, spec2)
                            st["reattached"] += 1
                            rc_after = int(model.rowCount(col0))
                            if rc_after > 0:
                                target_for_children = model.index(rc_after - 1, 0, col0)
                            self._apply_tree_item_visual_state(None, root_pl)
                            self._refresh_destination_item_visibility_index(col0, expand=True)
                            self._log_restore_phase(
                                "sharepoint_planned_workspace_reconcile",
                                projection_bind_mode="reconcile",
                                transition="planned_reparented",
                                path_excerpt=str(intended_canon or snap_name)[:220],
                            )
                            log_info(
                                "destination_reconcile_planned_row_after_graph_replace",
                                intended_path=intended_excerpt,
                                snapshot_model_path_excerpt=str(snap_path_model)[:400],
                                current_path=cur_excerpt,
                                reconcile_action="move",
                                matched_existing=True,
                                reattached=True,
                                match_method="reattached_planned",
                            )
                            if self._destination_reconcile_trace_enabled():
                                dest_forensic.log_reconcile(
                                    record_phase="reconcile_post",
                                    post_reconcile_result="planned_reparented",
                                    planned_snapshot_path_excerpt=str(snap_path_model)[:400],
                                    intended_from_planning_canonical_excerpt=str(intended_canon)[:400],
                                    graph_authority=bool(graph_auth_rec),
                                )
                    else:
                        merged = dict(self._destination_model_index_user_role_dict(ex_ix))
                        merged.update(snap_payload)
                        merged["verification_state"] = "planned_only"
                        rk = str(snap.get("row_kind") or "").strip()
                        if rk:
                            merged["row_kind"] = rk

                        def _mut(p, m=merged):
                            p.clear()
                            p.update(m)

                        model.update_payload_for_index(ex_ix, _mut)
                        self._apply_tree_item_visual_state(None, merged)
                        self._refresh_destination_item_visibility_index(ex_ix)
                        self._log_restore_phase(
                            "sharepoint_planned_workspace_reconcile",
                            projection_bind_mode="reconcile",
                            transition="planned_path_fields_updated",
                            path_excerpt=str(intended_canon or snap_name)[:220],
                        )
                        log_info(
                            "destination_reconcile_planned_row_after_graph_replace",
                            intended_path=intended_excerpt,
                            snapshot_model_path_excerpt=str(snap_path_model)[:400],
                            current_path=cur_excerpt,
                            reconcile_action="move",
                            matched_existing=True,
                            reattached=True,
                            match_method="planned_workspace",
                        )
                        st["reattached"] += 1
                        target_for_children = ex_ix
                        if self._destination_reconcile_trace_enabled():
                            dest_forensic.log_reconcile(
                                record_phase="reconcile_post",
                                post_reconcile_result="planned_path_fields_updated",
                                planned_snapshot_path_excerpt=str(snap_path_model)[:400],
                                intended_from_planning_canonical_excerpt=str(intended_canon)[:400],
                                graph_authority=bool(graph_auth_rec),
                            )
            if nested and target_for_children is not None and target_for_children.isValid():
                for ch_node in nested:
                    if not isinstance(ch_node, dict):
                        continue
                    sub = _reconcile_node(target_for_children, ch_node)
                    st["matched_live"] += sub["matched_live"]
                    st["reattached"] += sub["reattached"]
                    st["lost"] += sub["lost"]
                    st["no_op"] += int(sub.get("no_op", 0) or 0)
            elif nested:
                st["lost"] += self._destination_count_planned_snapshot_tree_nodes(nested)
            return st

        _p_recon = parent_ix if parent_ix.isValid() else QModelIndex()
        totals = dict(empty)
        for node in norm_nodes:
            part = _reconcile_node(_p_recon, node)
            totals["matched_live"] += part["matched_live"]
            totals["reattached"] += part["reattached"]
            totals["lost"] += part["lost"]
            totals["no_op"] += int(part.get("no_op", 0) or 0)
        return totals

    def _destination_invoke_planned_workspace_reconcile_after_graph_folder_load(
        self,
        parent_ix: QModelIndex,
        planned_workspace_presnapshot: list,
        *,
        allow_reappend: bool,
    ) -> dict[str, int]:
        """Reattach planned workspace snapshot trees immediately after Graph child replace.

        Must run on the UI/model thread right after ``replace_all_children`` (or shallow-load
        equivalent), not only from deferred callbacks that may return early.
        """
        empty = {"matched_live": 0, "reattached": 0, "lost": 0, "no_op": 0}
        if not planned_workspace_presnapshot:
            return dict(empty)
        p_col = parent_ix.siblingAtColumn(0) if parent_ix.isValid() and parent_ix.column() != 0 else parent_ix
        if p_col.isValid():
            _pp = self._destination_semantic_path(dict(p_col.data(Qt.UserRole) or {}))
        else:
            _pp = ""
        _cnt = int(self._destination_count_planned_snapshot_tree_nodes(planned_workspace_presnapshot))
        log_info(
            "destination_reconcile_planned_rows_invoked",
            parent_path=str(_pp or "")[:400],
            snapshot_count=_cnt,
        )
        _stats = self._destination_reconcile_planned_rows_after_graph_folder_load(
            p_col,
            planned_workspace_presnapshot,
            allow_reappend=allow_reappend,
        )
        log_info(
            "destination_planned_rows_after_replace",
            parent_path=str(_pp or "")[:400],
            reattached_count=int(_stats.get("reattached", 0)),
            lost_count=int(_stats.get("lost", 0)),
            matched_live_count=int(_stats.get("matched_live", 0)),
        )
        if _pp:
            self._destination_discard_pending_planned_reconcile_parent(_pp)
        return _stats

    def _destination_planned_reconcile_parent_canonical_key(self, path_hint: str) -> str:
        return (
            self._canonical_destination_projection_path(str(path_hint or "").strip())
            or self.normalize_memory_path(str(path_hint or "").strip())
            or ""
        ).strip()

    def _destination_register_planned_workspace_snapshot_for_parent_path(
        self, parent_path_hint: str, snapshot: list | None
    ) -> None:
        ck = self._destination_planned_reconcile_parent_canonical_key(parent_path_hint)
        if not ck:
            return
        d = getattr(self, "planned_rows_by_parent_path", None)
        if not isinstance(d, dict):
            self.planned_rows_by_parent_path = {}
            d = self.planned_rows_by_parent_path
        if snapshot and self._destination_count_planned_snapshot_tree_nodes(snapshot) > 0:
            id_tree = self._destination_planned_workspace_snapshot_identity_only_tree(snapshot)
            d[ck] = copy.deepcopy(id_tree)
        else:
            d.pop(ck, None)

    def _destination_get_planned_rows_map_raw_entry(self, parent_canonical: str) -> tuple[Any | None, str, bool]:
        """Return ``(value, resolved_key, found)`` for :attr:`planned_rows_by_parent_path` (casefold key match)."""
        d = getattr(self, "planned_rows_by_parent_path", None) or {}
        ck = self._destination_planned_reconcile_parent_canonical_key(parent_canonical)
        if not ck:
            return None, "", False
        if ck in d:
            return d[ck], ck, True
        cf = ck.casefold()
        for sk, sv in d.items():
            if str(sk or "").casefold() == cf:
                return sv, str(sk), True
        return None, ck, False

    def _destination_stored_planned_workspace_snapshot_node_count_for_parent(self, path_hint: str) -> int:
        stored, _, found = self._destination_get_planned_rows_map_raw_entry(path_hint)
        if not found or stored is None:
            return 0
        return int(self._destination_count_planned_snapshot_tree_nodes(stored))

    def _destination_discard_pending_planned_reconcile_parent(self, parent_path_hint: str) -> None:
        s = getattr(self, "_destination_pending_planned_reconcile_parent_paths", None)
        if not isinstance(s, set):
            return
        ck = self._destination_planned_reconcile_parent_canonical_key(parent_path_hint)
        if not ck:
            return
        rm = {ck}
        cf = ck.casefold()
        for x in list(s):
            if str(x or "").casefold() == cf:
                rm.add(x)
        s.difference_update(rm)

    def _destination_try_reconcile_pending_planned_parents_after_folder_load(self) -> None:
        """After any destination Graph folder load, attach planned rows for parents now materialized."""
        if self._planning_browse_mode("destination") == "local":
            return
        if not destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            return
        pending = getattr(self, "_destination_pending_planned_reconcile_parent_paths", None)
        if not isinstance(pending, set) or not pending:
            return
        for ck in list(pending):
            ix = self._destination_find_planning_index_for_overlay_target_path(ck)
            if ix is None or not ix.isValid():
                continue
            pl_fold = self._destination_model_index_user_role_dict(ix)
            if not bool(pl_fold.get("is_folder", False)):
                continue
            snap = self._destination_planned_snapshot_for_parent_reconcile(ck, ix)
            prc = int(self._destination_count_planned_snapshot_tree_nodes(snap))
            if not prc and self._destination_stored_planned_workspace_snapshot_node_count_for_parent(ck) > 0:
                log_error(
                    "destination_reconcile_snapshot_empty_error",
                    parent_path=str(ck or "")[:400],
                    detail="pending_pass_retry_from_stored_map",
                )
                raw, _, _ = self._destination_get_planned_rows_map_raw_entry(ck)
                if raw:
                    snap = copy.deepcopy(raw)
                    prc = int(self._destination_count_planned_snapshot_tree_nodes(snap))
            if not prc:
                log_error(
                    "destination_reconcile_snapshot_empty_error",
                    parent_path=str(ck or "")[:400],
                    detail="pending_pass_no_snapshot_after_resolution",
                )
                self._destination_discard_pending_planned_reconcile_parent(ck)
                continue
            try:
                self._destination_invoke_planned_workspace_reconcile_after_graph_folder_load(
                    ix,
                    snap,
                    allow_reappend=True,
                )
            except Exception as exc:
                self._log_restore_exception("pending_planned_reconcile_after_folder_load", exc)

    def _destination_collect_parent_paths_with_planned_workspace_children_in_model(self) -> list[str]:
        dm = getattr(self, "destination_planning_model", None)
        if dm is None:
            return []
        try:
            indices = dm.iter_depth_first()
        except Exception:
            return []
        out: list[str] = []
        seen: set[str] = set()
        for pix in indices:
            if not pix.isValid():
                continue
            plp = self._destination_model_index_user_role_dict(pix)
            if not bool(plp.get("is_folder", False)):
                continue
            col0 = pix.siblingAtColumn(0) if pix.column() != 0 else pix
            try:
                rc = int(dm.rowCount(col0))
            except Exception:
                continue
            has_planned = False
            for r in range(rc):
                try:
                    cix = dm.index(r, 0, col0)
                except Exception:
                    continue
                if not cix.isValid():
                    continue
                ch = self._destination_model_index_user_role_dict(cix)
                if destination_payload_is_planned_workspace_row(ch):
                    has_planned = True
                    break
            if not has_planned:
                continue
            sp = self._destination_semantic_path(plp)
            ck = self._destination_planned_reconcile_parent_canonical_key(sp)
            if ck and ck not in seen:
                seen.add(ck)
                out.append(ck)
        return out

    def _destination_collect_planned_reconcile_parent_canonical_paths(self) -> list[str]:
        """Union of parents with planned workspace rows (memory index, unresolved queues, model scan)."""
        seen: set[str] = set()
        ordered: list[str] = []

        def _add_raw(hint: str) -> None:
            ck = self._destination_planned_reconcile_parent_canonical_key(hint)
            if ck and ck not in seen:
                seen.add(ck)
                ordered.append(ck)

        for k in (getattr(self, "planned_rows_by_parent_path", None) or {}).keys():
            _add_raw(str(k or ""))
        for k in (getattr(self, "unresolved_proposed_by_parent_path", None) or {}).keys():
            _add_raw(str(k or ""))
        for k in (getattr(self, "unresolved_allocations_by_parent_path", None) or {}).keys():
            _add_raw(str(k or ""))
        for ck in self._destination_collect_parent_paths_with_planned_workspace_children_in_model():
            if ck and ck not in seen:
                seen.add(ck)
                ordered.append(ck)
        return ordered

    def _destination_planned_snapshot_for_parent_reconcile(self, parent_canonical: str, parent_ix: QModelIndex) -> list:
        """Planned workspace snapshot for reconcile: :attr:`planned_rows_by_parent_path` is source of truth when present."""
        pp_excerpt = str(parent_canonical or "")[:400]
        stored, _map_key, in_map = self._destination_get_planned_rows_map_raw_entry(parent_canonical)
        if in_map:
            n_stored = int(self._destination_count_planned_snapshot_tree_nodes(stored or []))
            if n_stored > 0:
                log_info(
                    "destination_reconcile_snapshot_source",
                    parent_path=pp_excerpt,
                    source="stored_map",
                    snapshot_size=n_stored,
                )
                return copy.deepcopy(stored)
            log_error(
                "destination_reconcile_snapshot_empty_error",
                parent_path=pp_excerpt,
                detail="planned_rows_by_parent_path_entry_empty",
            )
            model_snap = self._destination_collect_planned_workspace_children_under_model(parent_ix)
            model_snap = self._destination_planned_workspace_snapshot_identity_only_tree(model_snap)
            n_m = int(self._destination_count_planned_snapshot_tree_nodes(model_snap))
            log_info(
                "destination_reconcile_snapshot_source",
                parent_path=pp_excerpt,
                source="model",
                snapshot_size=n_m,
            )
            if not n_m:
                log_error(
                    "destination_reconcile_snapshot_empty_error",
                    parent_path=pp_excerpt,
                    detail="stored_empty_and_model_empty",
                )
            return model_snap
        model_snap = self._destination_collect_planned_workspace_children_under_model(parent_ix)
        model_snap = self._destination_planned_workspace_snapshot_identity_only_tree(model_snap)
        n_m = int(self._destination_count_planned_snapshot_tree_nodes(model_snap))
        log_info(
            "destination_reconcile_snapshot_source",
            parent_path=pp_excerpt,
            source="model",
            snapshot_size=n_m,
        )
        return model_snap

    def _destination_reconcile_global_gate_eval(self) -> tuple[bool, dict]:
        """Return (allowed, diag) for expensive global planned-parent reconcile (coverage + dwell gates)."""
        self._destination_reconcile_gate_epoch_id = int(
            getattr(self, "_destination_reconcile_gate_epoch_id", 0) or 0
        ) + 1
        eid = int(getattr(self, "_destination_reconcile_gate_epoch_id", 0) or 0)
        full_tree_idle = True
        try:
            ftw = getattr(self, "_destination_full_tree_worker", None)
            if ftw is not None and ftw.isRunning():
                full_tree_idle = False
            elif not self._destination_full_tree_ready():
                full_tree_idle = False
        except Exception:
            full_tree_idle = False
        parent_paths = self._destination_collect_planned_reconcile_parent_canonical_paths()
        planned_parent_count = len(parent_paths)
        if planned_parent_count <= 0:
            return True, {
                "epoch_id": eid,
                "full_tree_idle": True,
                "visible_parent_count": 0,
                "planned_parent_count": 0,
                "coverage_ratio": 1.0,
                "last_zero_attachment": bool(
                    getattr(self, "_destination_reconcile_last_had_zero_attachment", False)
                ),
                "reason": "no_planned_reconcile_parents",
                "planning_cache_generation": int(getattr(self, "_planning_cache_generation", 0) or 0),
                "prior_plan_gen": int(getattr(self, "_destination_reconcile_last_plan_gen", -1)),
                "coverage_sig": "",
            }
        visible_parent_count = 0
        for pp in parent_paths:
            ix = self._destination_find_planning_index_for_overlay_target_path(
                pp, for_planned_workspace_reconcile=True
            )
            if ix is not None and ix.isValid():
                visible_parent_count += 1
        coverage_ratio = float(visible_parent_count) / float(max(1, planned_parent_count))
        sig = f"p{planned_parent_count};v{visible_parent_count};cov{round(coverage_ratio, 5)}"
        plan_gen = int(getattr(self, "_planning_cache_generation", 0) or 0)
        last_sig = str(getattr(self, "_destination_reconcile_last_coverage_sig", "") or "")
        last_zero = bool(getattr(self, "_destination_reconcile_last_had_zero_attachment", False))
        last_plan_gen = int(getattr(self, "_destination_reconcile_last_plan_gen", -1))
        material = plan_gen != last_plan_gen
        idle_or_cov = bool(full_tree_idle) or coverage_ratio >= 0.1
        repeat_zero_stale = bool(last_zero and sig == last_sig and not material)
        reason = "allowed"
        allow = True
        if not idle_or_cov:
            allow = False
            reason = "full_tree_busy_and_coverage_below_threshold"
        elif repeat_zero_stale:
            allow = False
            reason = "prior_zero_attachment_same_epoch_unchanged_coverage"
        diag = {
            "epoch_id": eid,
            "full_tree_idle": bool(full_tree_idle),
            "visible_parent_count": int(visible_parent_count),
            "planned_parent_count": int(planned_parent_count),
            "coverage_ratio": round(coverage_ratio, 6),
            "last_zero_attachment": bool(last_zero),
            "reason": reason,
            "planning_cache_generation": int(plan_gen),
            "prior_plan_gen": int(last_plan_gen),
            "coverage_sig": sig[:200],
        }
        return allow, diag

    def _destination_reconcile_invalidate_last_completed_plan_gen(self) -> None:
        self._destination_reconcile_last_completed_plan_gen = -1

    @staticmethod
    def _destination_destination_folder_workers_running_count(win) -> int:
        return sum(
            1
            for k, entry in (getattr(win, "folder_load_workers", None) or {}).items()
            if str(k).startswith("destination:")
            and MainWindow._qt_worker_is_running((entry or {}).get("worker"))
        )

    def _destination_true_idle_diagnostics(self) -> dict[str, object]:
        dq = getattr(self, "_destination_descendant_apply_queue", None)
        st = getattr(self, "_destination_descendant_apply_state", None)
        pending_fl = getattr(self, "pending_folder_loads", None) or {}
        dep = getattr(self, "_destination_global_reconcile_overlay_deferred", None)
        reconcile_idle_flush_pending = bool(isinstance(dep, dict) and dep.get("pending"))
        u_prop = int(self._unresolved_proposed_queue_size() or 0)
        u_alloc = int(self._unresolved_allocation_queue_size() or 0)
        dq_len = len(dq) if dq else 0
        dest_pend_fl = len(pending_fl.get("destination", set()) or set())
        root_dest_running = bool(MainWindow._root_load_worker_running(self, "destination"))
        dest_folder_workers = int(MainWindow._destination_destination_folder_workers_running_count(self))
        ft_running = bool(MainWindow._qt_worker_is_running(getattr(self, "_destination_full_tree_worker", None)))
        inc_running = bool(
            MainWindow._qt_worker_is_running(getattr(self, "destination_incremental_refresh_worker", None))
        )
        mat_q = len(getattr(self, "_destination_restore_materialization_queue", []) or [])
        gui_chunk = getattr(self, "_destination_planning_overlay_gui_chunk_state", None) is not None
        fixpoint_inc = bool(getattr(self, "_destination_fixpoint_slice_incomplete", False))
        drain_active = bool(getattr(self, "_destination_snapshot_capture_drain_active", False))
        desc_paused = bool(getattr(self, "_destination_descendant_apply_paused_for_finalize_alloc", False))
        truly_idle = (
            u_prop == 0
            and u_alloc == 0
            and dq_len == 0
            and st is None
            and not desc_paused
            and dest_pend_fl == 0
            and not root_dest_running
            and dest_folder_workers == 0
            and not ft_running
            and not inc_running
            and mat_q == 0
            and not gui_chunk
            and not fixpoint_inc
            and not drain_active
        )
        return {
            "truly_idle": bool(truly_idle),
            "unresolved_proposed": u_prop,
            "unresolved_allocation": u_alloc,
            "descendant_apply_queue_len": int(dq_len),
            "descendant_apply_state_active": bool(st is not None),
            "descendant_apply_paused_finalize_alloc": bool(desc_paused),
            "destination_pending_folder_loads": int(dest_pend_fl),
            "destination_root_worker_running": bool(root_dest_running),
            "destination_folder_workers_running": int(dest_folder_workers),
            "destination_full_tree_worker_running": bool(ft_running),
            "destination_incremental_refresh_worker_running": bool(inc_running),
            "destination_restore_materialization_queue_len": int(mat_q),
            "overlay_gui_chunk_state_active": bool(gui_chunk),
            "fixpoint_slice_incomplete": bool(fixpoint_inc),
            "snapshot_capture_drain_active": bool(drain_active),
            "reconcile_idle_flush_pending": bool(reconcile_idle_flush_pending),
            "planning_cache_generation": int(getattr(self, "_planning_cache_generation", 0) or 0),
        }

    def _destination_is_truly_idle(self) -> bool:
        return bool(self._destination_true_idle_diagnostics().get("truly_idle"))

    def _destination_descendant_apply_force_clear_on_stall(
        self,
        *,
        exit_reason: str,
        queue_len_after: int,
        state_active: bool,
        drain_fingerprint: tuple[Any, ...] | None = None,
        stall_ticks: int = -1,
        last_graph_tick_slice_kind: str = "",
        force_clear_due_true_dead_stall: bool = True,
    ) -> None:
        st = getattr(self, "_destination_descendant_apply_state", None)
        liv = -1
        if isinstance(st, dict) and st.get("graph_walk"):
            try:
                liv = int(st.get("_snapshot_drain_graph_liveness") or 0)
            except Exception:
                liv = -1
        log_info(
            "descendant_apply_forced_clear_on_stall",
            exit_reason=str(exit_reason or "")[:120],
            queue_len_after=int(queue_len_after),
            state_active_before=bool(state_active),
            had_state_object=bool(st is not None),
            drain_fingerprint_full=drain_fingerprint,
            stall_ticks=int(stall_ticks),
            last_graph_tick_slice_kind=str(last_graph_tick_slice_kind or "")[:80],
            graph_walk_liveness_heartbeat=int(liv),
            force_clear_due_true_dead_stall=bool(force_clear_due_true_dead_stall),
        )
        if st is not None:
            try:
                self._destination_descendant_apply_abort_stale(st, abort_kind="forced_clear_no_progress_stall")
            except Exception:
                pass
            self._destination_descendant_apply_state = None

    def _destination_run_global_planned_reconcile_if_gated(self, *, run_exact_target_after: bool = True) -> None:
        if self._destination_user_scroll_interaction_active():
            self._destination_global_planned_reconcile_pended_after_scroll = bool(run_exact_target_after)
            self._destination_note_destination_tree_scroll_activity()
            log_info(
                "destination_scroll_window_heavy_work_deferred",
                work_kind="global_planned_reconcile",
                run_exact_target_after=bool(run_exact_target_after),
            )
            _dsp_gp = getattr(self, "_dest_scroll_profiler", None)
            if _dsp_gp is not None:
                _dsp_gp.note_heavy_work_deferred("global_planned_reconcile")
            return
        allow, diag = self._destination_reconcile_global_gate_eval()
        if not allow:
            log_info("destination_reconcile_gate_blocked", **diag)
            return
        log_info("destination_reconcile_gate_allowed", **diag)
        self._destination_reconcile_all_planned_parents_after_graph_update(
            gate_already_verified=True,
            run_exact_target_after=bool(run_exact_target_after),
        )

    def _destination_schedule_global_reconcile_after_overlay_queue_drain(
        self,
        *,
        run_exact_target_after: bool,
        gate_already_verified: bool = True,
        _skip_overlay_queue_defer: bool = False,
        _request_overlay_terminal_completion_mark: bool = False,
        _bypass_true_idle_gate: bool = False,
    ) -> None:
        dep = getattr(self, "_destination_global_reconcile_overlay_deferred", None)
        if isinstance(dep, dict) and dep.get("pending"):
            dep["run_eta"] = bool(dep.get("run_eta")) or bool(run_exact_target_after)
            dep["gate_already_verified"] = bool(dep.get("gate_already_verified", True)) or bool(
                gate_already_verified
            )
            dep["_skip_overlay_queue_defer"] = bool(dep.get("_skip_overlay_queue_defer", False)) or bool(
                _skip_overlay_queue_defer
            )
            dep["_request_overlay_terminal_completion_mark"] = bool(
                dep.get("_request_overlay_terminal_completion_mark", False)
            ) or bool(_request_overlay_terminal_completion_mark)
            dep["_bypass_true_idle_gate"] = bool(dep.get("_bypass_true_idle_gate", False)) or bool(
                _bypass_true_idle_gate
            )
            log_info(
                "destination_reconcile_global_deferred_coalesce",
                pending_ticks=int(dep.get("ticks", 0) or 0),
            )
            return
        self._destination_global_reconcile_overlay_deferred = {
            "pending": True,
            "run_eta": bool(run_exact_target_after),
            "ticks": 0,
            "gate_already_verified": bool(gate_already_verified),
            "_skip_overlay_queue_defer": bool(_skip_overlay_queue_defer),
            "_request_overlay_terminal_completion_mark": bool(_request_overlay_terminal_completion_mark),
            "_bypass_true_idle_gate": bool(_bypass_true_idle_gate),
        }
        log_info(
            "destination_reconcile_global_deferred_overlay_queue",
            proposed_remaining=int(self._unresolved_proposed_queue_size() or 0),
            allocation_remaining=int(self._unresolved_allocation_queue_size() or 0),
        )
        QTimer.singleShot(
            0,
            lambda: self._safe_invoke(
                "destination_global_reconcile_after_overlay_queue_drain",
                self._destination_flush_deferred_global_reconcile_if_overlay_idle,
            ),
        )

    def _destination_flush_deferred_global_reconcile_if_overlay_idle(self) -> None:
        dep = getattr(self, "_destination_global_reconcile_overlay_deferred", None)
        if not isinstance(dep, dict) or not dep.get("pending"):
            return
        if getattr(self, "_application_shutting_down", False):
            self._destination_global_reconcile_overlay_deferred = None
            return
        dep["ticks"] = int(dep.get("ticks", 0) or 0) + 1
        ticks = int(dep["ticks"])
        idle_diag = self._destination_true_idle_diagnostics()
        log_info("destination_true_idle_state", phase="reconcile_idle_flush_poll", wait_tick=ticks, **idle_diag)
        if not self._destination_is_truly_idle():
            u_prop = int(idle_diag.get("unresolved_proposed", 0) or 0)
            u_alloc = int(idle_diag.get("unresolved_allocation", 0) or 0)
            if dep.get("_non_idle_flush_t0") is None:
                dep["_non_idle_flush_t0"] = time.perf_counter()
            t_block0 = float(dep.get("_non_idle_flush_t0") or time.perf_counter())
            elapsed = time.perf_counter() - t_block0
            fb_ticks = 28
            fb_secs = 2.8
            raw_fb_ticks = str(os.environ.get("OZLINK_RECONCILE_IDLE_FALLBACK_TICKS", "") or "").strip()
            raw_fb_secs = str(os.environ.get("OZLINK_RECONCILE_IDLE_FALLBACK_SECS", "") or "").strip()
            if raw_fb_ticks:
                try:
                    fb_ticks = max(1, int(raw_fb_ticks))
                except ValueError:
                    pass
            if raw_fb_secs:
                try:
                    fb_secs = max(0.2, float(raw_fb_secs))
                except ValueError:
                    pass
            if (u_prop > 0 or u_alloc > 0) and (ticks >= fb_ticks or elapsed >= fb_secs):
                log_info(
                    "reconcile_forced_flush_fallback_triggered",
                    reason="prolonged_non_idle",
                    unresolved_proposed=u_prop,
                    unresolved_allocation=u_alloc,
                    wait_ticks=ticks,
                    wait_elapsed_sec=round(elapsed, 3),
                )
                run_eta = bool(dep.get("run_eta", True))
                gate_ok = bool(dep.get("gate_already_verified", True))
                skip_def = bool(dep.get("_skip_overlay_queue_defer", False))
                self._destination_global_reconcile_overlay_deferred = None
                log_info(
                    "destination_reconcile_global_deferred_overlay_queue_cleared",
                    wait_ticks=ticks,
                    forced_idle_fallback=True,
                )
                mark = bool(getattr(self, "_destination_overlay_terminal_reconcile_completion_pending", False))
                self._destination_overlay_terminal_reconcile_completion_pending = False
                self._destination_reconcile_all_planned_parents_after_graph_update(
                    gate_already_verified=gate_ok,
                    run_exact_target_after=run_eta,
                    _skip_overlay_queue_defer=skip_def,
                    _request_overlay_terminal_completion_mark=mark,
                    _bypass_true_idle_gate=True,
                )
                return
            log_info(
                "reconcile_blocked_not_idle",
                phase="reconcile_idle_flush_wait",
                wait_tick=ticks,
                **idle_diag,
            )
            QTimer.singleShot(
                48,
                lambda: self._safe_invoke(
                    "destination_global_reconcile_after_overlay_queue_drain_continue",
                    self._destination_flush_deferred_global_reconcile_if_overlay_idle,
                ),
            )
            return
        run_eta = bool(dep.get("run_eta", True))
        gate_ok = bool(dep.get("gate_already_verified", True))
        skip_def = bool(dep.get("_skip_overlay_queue_defer", False))
        bypass = bool(dep.get("_bypass_true_idle_gate", False))
        self._destination_global_reconcile_overlay_deferred = None
        log_info(
            "destination_reconcile_global_deferred_overlay_queue_cleared",
            wait_ticks=ticks,
        )
        mark = bool(getattr(self, "_destination_overlay_terminal_reconcile_completion_pending", False))
        self._destination_overlay_terminal_reconcile_completion_pending = False
        self._destination_reconcile_all_planned_parents_after_graph_update(
            gate_already_verified=gate_ok,
            run_exact_target_after=run_eta,
            _skip_overlay_queue_defer=skip_def,
            _request_overlay_terminal_completion_mark=mark,
            _bypass_true_idle_gate=bypass,
        )

    def _destination_reconcile_global_planned_parents_process_chunk(self) -> None:
        st = getattr(self, "_destination_global_reconcile_chunk_state", None)
        if not isinstance(st, dict):
            self._destination_global_planned_reconcile_active = False
            self._destination_reconcile_in_progress = False
            return
        if self._destination_user_scroll_interaction_active():
            log_info(
                "startup_lifecycle_temp_interaction_deferral",
                work_kind="global_planned_reconcile_chunk",
                parent_count_pending=int(len(st["parent_paths"]) - int(st["i"])),
                detail="destination_tree_scroll_window_active",
            )
            QTimer.singleShot(
                120,
                lambda: self._safe_invoke(
                    "destination_global_reconcile_chunk_after_scroll",
                    self._destination_reconcile_global_planned_parents_process_chunk,
                ),
            )
            return
        parent_paths = list(st["parent_paths"])
        i = int(st["i"])
        budget_ms = float(st.get("budget_ms") or 18.0)
        max_pci = int(st.get("max_parents_per_chunk", 0) or 0)
        t0 = time.perf_counter()
        log_info(
            "startup_lifecycle_temp_reconcile_chunk_begin",
            phase="global_planned",
            parent_count_pending=int(len(parent_paths) - i),
            budget_ms=round(budget_ms, 2),
            max_parents_per_chunk=int(max_pci),
            destination_reconcile_batch=True,
        )
        processed = 0
        try:
            while i < len(parent_paths) and (time.perf_counter() - t0) * 1000.0 < budget_ms:
                if max_pci > 0 and processed >= max_pci:
                    break
                pp = parent_paths[i]
                ix = self._destination_find_planning_index_for_overlay_target_path(
                    pp, for_planned_workspace_reconcile=True
                )
                if ix is None or not ix.isValid():
                    i += 1
                    st["i"] = i
                    processed += 1
                    continue
                pl_fold = self._destination_model_index_user_role_dict(ix)
                if not bool(pl_fold.get("is_folder", False)):
                    i += 1
                    st["i"] = i
                    processed += 1
                    continue
                _, _, map_has_parent = self._destination_get_planned_rows_map_raw_entry(pp)
                snap = self._destination_planned_snapshot_for_parent_reconcile(pp, ix)
                prc = int(self._destination_count_planned_snapshot_tree_nodes(snap))
                if not prc:
                    log_error(
                        "destination_reconcile_snapshot_empty_error",
                        parent_path=str(pp or "")[:400],
                        detail="global_pass_initial_resolution_empty",
                    )
                    raw, _, found = self._destination_get_planned_rows_map_raw_entry(pp)
                    if found and raw:
                        snap = copy.deepcopy(raw)
                        prc = int(self._destination_count_planned_snapshot_tree_nodes(snap))
                        if prc:
                            log_info(
                                "destination_reconcile_snapshot_retry_from_stored_map",
                                parent_path=str(pp or "")[:400],
                                snapshot_size=prc,
                            )
                if not prc:
                    if map_has_parent:
                        log_error(
                            "destination_reconcile_snapshot_empty_error",
                            parent_path=str(pp or "")[:400],
                            detail="global_pass_invariant_map_has_parent_but_snapshot_empty",
                        )
                    i += 1
                    st["i"] = i
                    processed += 1
                    continue
                log_info(
                    "destination_reconcile_global_parent",
                    parent_path=str(pp or "")[:400],
                    planned_row_count=prc,
                )
                stats = self._destination_invoke_planned_workspace_reconcile_after_graph_folder_load(
                    ix,
                    snap,
                    allow_reappend=True,
                )
                st["total_reattached"] = int(st.get("total_reattached", 0)) + int(
                    (stats or {}).get("reattached", 0) or 0
                )
                st["total_no_op"] = int(st.get("total_no_op", 0) or 0) + int((stats or {}).get("no_op", 0) or 0)
                if map_has_parent and prc:
                    rea = int((stats or {}).get("reattached", 0) or 0)
                    mat = int((stats or {}).get("matched_live", 0) or 0)
                    if rea == 0 and mat == 0:
                        st["had_zero_attachment"] = True
                        log_error(
                            "destination_reconcile_stored_snapshot_zero_attachment",
                            parent_path=str(pp or "")[:400],
                            planned_row_count=prc,
                            detail="reconcile_returned_no_matched_live_or_reattached",
                        )
                i += 1
                st["i"] = i
                processed += 1
        except Exception as exc:
            self._log_restore_exception("destination_reconcile_global_planned_parents_chunk", exc)
            self._destination_global_reconcile_chunk_state = None
            self._destination_global_planned_reconcile_active = False
            self._destination_reconcile_in_progress = False
            return
        wall_ms = round((time.perf_counter() - t0) * 1000.0, 2)
        st["cumulative_chunk_wall_ms"] = float(st.get("cumulative_chunk_wall_ms", 0.0) or 0.0) + float(wall_ms)
        log_info(
            "startup_lifecycle_temp_reconcile_chunk_end",
            phase="global_planned",
            wall_ms=wall_ms,
            parent_count_processed=int(processed),
            max_parents_per_chunk=int(max_pci),
            cumulative_reconcile_wall_ms=round(float(st.get("cumulative_chunk_wall_ms", 0.0) or 0.0), 2),
            cumulative_no_op_rows=int(st.get("total_no_op", 0) or 0),
            norm_cache_hits_pass=int(getattr(self, "_destination_norm_cache_hits_pass", 0) or 0),
            destination_reconcile_batch=True,
        )
        if i < len(parent_paths):
            QTimer.singleShot(
                0,
                lambda: self._safe_invoke(
                    "destination_global_reconcile_chunk_continue",
                    self._destination_reconcile_global_planned_parents_process_chunk,
                ),
            )
            return
        log_info(
            "destination_reconcile_global_pass_completed",
            total_parents=len(parent_paths),
            total_reattached=int(st.get("total_reattached", 0)),
            total_reconcile_wall_ms=round(float(st.get("cumulative_chunk_wall_ms", 0.0) or 0.0), 2),
            total_no_op_rows=int(st.get("total_no_op", 0) or 0),
            norm_cache_hits_pass=int(getattr(self, "_destination_norm_cache_hits_pass", 0) or 0),
        )
        self._destination_reconcile_in_progress = False
        self._destination_reconcile_last_completed_plan_gen = int(st.get("start_gen", 0) or 0)
        log_info(
            "reconcile_completed",
            planning_cache_generation=int(self._destination_reconcile_last_completed_plan_gen),
            total_parents=len(parent_paths),
        )
        if bool(st.get("overlay_terminal_done_on_complete")):
            self._destination_overlay_terminal_reconcile_done = True
        self._destination_reconcile_last_coverage_sig = str(st.get("start_sig") or "")
        self._destination_reconcile_last_had_zero_attachment = bool(st.get("had_zero_attachment", False))
        self._destination_reconcile_last_plan_gen = int(st.get("start_gen", 0) or 0)
        run_eta = bool(st.get("run_exact_target_after", True))
        self._destination_global_reconcile_chunk_state = None
        self._destination_global_planned_reconcile_active = False
        if run_eta:
            try:
                with self._destination_materialize_profile_span("destination_run_exact_target_enforcement_pass"):
                    self._destination_run_exact_target_enforcement_pass("after_global_planned_reconcile")
            except Exception as exc:
                self._log_restore_exception(
                    "destination_exact_target_enforcement_after_global_planned_reconcile", exc
                )
            self._on_destination_state_mutation("after_global_planned_reconcile", None)

    def _destination_reconcile_all_planned_parents_after_graph_update(
        self,
        *,
        gate_already_verified: bool = False,
        run_exact_target_after: bool = True,
        _skip_overlay_queue_defer: bool = False,
        _request_overlay_terminal_completion_mark: bool = False,
        _bypass_true_idle_gate: bool = False,
    ) -> bool:
        """Re-run planned workspace reconcile for every parent that has planned rows (idempotent).

        Drive this from structural updates (Graph replace, overlay pass, authority shell clear), not from
        expand/UI alone, so branches that share no folder-load event still reattach.

        Returns False when global reconcile is deferred until the destination is truly idle; True otherwise.
        """
        if getattr(self, "_destination_global_planned_reconcile_active", False):
            self._destination_global_reconcile_chunk_state = None
            self._destination_global_planned_reconcile_active = False
            self._destination_reconcile_in_progress = False
            self._destination_reconcile_invalidate_last_completed_plan_gen()
        st_running = getattr(self, "_destination_global_reconcile_chunk_state", None)
        if getattr(self, "_destination_reconcile_in_progress", False) and isinstance(st_running, dict):
            pps = list(st_running.get("parent_paths") or [])
            if int(st_running.get("i", 0) or 0) < len(pps):
                log_info(
                    "reconcile_blocked_not_idle",
                    reason="reconcile_in_progress_chunk_pending",
                    **self._destination_true_idle_diagnostics(),
                )
                return False
        if getattr(self, "_destination_reconcile_in_progress", False) and not isinstance(st_running, dict):
            self._destination_reconcile_in_progress = False
        if self._planning_browse_mode("destination") == "local":
            if bool(_request_overlay_terminal_completion_mark):
                self._destination_overlay_terminal_reconcile_done = True
            return True
        if not destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            if bool(_request_overlay_terminal_completion_mark):
                self._destination_overlay_terminal_reconcile_done = True
            return True
        if not gate_already_verified:
            allow, _diag = self._destination_reconcile_global_gate_eval()
            if not allow:
                log_info("destination_reconcile_gate_blocked", **_diag)
                if bool(_request_overlay_terminal_completion_mark):
                    self._destination_overlay_terminal_reconcile_done = True
                return True
            log_info("destination_reconcile_gate_allowed", **_diag)
        if not bool(_bypass_true_idle_gate) and not self._destination_is_truly_idle():
            if bool(_request_overlay_terminal_completion_mark):
                self._destination_overlay_terminal_reconcile_completion_pending = True
            self._destination_schedule_global_reconcile_after_overlay_queue_drain(
                run_exact_target_after=bool(run_exact_target_after),
                gate_already_verified=True,
                _skip_overlay_queue_defer=bool(_skip_overlay_queue_defer),
                _request_overlay_terminal_completion_mark=bool(_request_overlay_terminal_completion_mark),
                _bypass_true_idle_gate=bool(_bypass_true_idle_gate),
            )
            log_info(
                "reconcile_blocked_not_idle",
                reason="destination_not_truly_idle_before_global_reconcile",
                **self._destination_true_idle_diagnostics(),
            )
            return False
        plan_gen = int(getattr(self, "_planning_cache_generation", 0) or 0)
        if (
            not bool(_bypass_true_idle_gate)
            and int(getattr(self, "_destination_reconcile_last_completed_plan_gen", -2) or -2) == plan_gen
            and plan_gen >= 0
        ):
            log_info("reconcile_skipped_same_generation", planning_cache_generation=plan_gen)
            if bool(_request_overlay_terminal_completion_mark):
                self._destination_overlay_terminal_reconcile_done = True
            return True
        self._destination_global_reconcile_overlay_deferred = None
        self._destination_global_planned_reconcile_active = True
        self._destination_reconcile_in_progress = True
        self._destination_norm_cache_hits_pass = 0
        start_gen = int(getattr(self, "_planning_cache_generation", 0) or 0)
        _rs_idle = self._destination_true_idle_diagnostics()
        log_info(
            "reconcile_started",
            planning_cache_generation=start_gen,
            truly_idle=bool(_rs_idle.get("truly_idle")),
            unresolved_proposed=int(_rs_idle.get("unresolved_proposed", 0) or 0),
            unresolved_allocation=int(_rs_idle.get("unresolved_allocation", 0) or 0),
            descendant_apply_state_active=bool(_rs_idle.get("descendant_apply_state_active")),
            destination_folder_workers_running=int(_rs_idle.get("destination_folder_workers_running", 0) or 0),
        )
        try:
            parent_paths = self._destination_collect_planned_reconcile_parent_canonical_paths()
            planned_n = len(parent_paths)
            vis_n = 0
            for _pp in parent_paths:
                _ix = self._destination_find_planning_index_for_overlay_target_path(
                    _pp, for_planned_workspace_reconcile=True
                )
                if _ix is not None and _ix.isValid():
                    vis_n += 1
            start_sig = f"p{planned_n};v{vis_n};cov{round(float(vis_n) / float(max(1, planned_n)), 5)}"
            log_info(
                "destination_reconcile_global_pass_started",
                parent_count=len(parent_paths),
            )
            overlay_mat = getattr(self, "_destination_overlay_active_materialize_reason", "") or ""
            use_chunk = len(parent_paths) > 3 or "deferred_graph_ids_resolved" in overlay_mat
            budget_ms = (
                float(getattr(self, "_destination_startup_global_reconcile_chunk_ms", 18.0) or 18.0)
                if use_chunk
                else 2000.0
            )
            _om = str(overlay_mat)
            _graph_overlay = "deferred_graph_ids_resolved" in _om
            _queues = int(self._unresolved_proposed_queue_size() or 0) + int(
                self._unresolved_allocation_queue_size() or 0
            )
            max_pci = 0
            if _graph_overlay or _queues > 0:
                max_pci = 1
            self._destination_global_reconcile_chunk_state = {
                "parent_paths": parent_paths,
                "i": 0,
                "total_reattached": 0,
                "had_zero_attachment": False,
                "start_sig": str(start_sig or ""),
                "start_gen": int(start_gen),
                "run_exact_target_after": bool(run_exact_target_after),
                "budget_ms": float(budget_ms),
                "max_parents_per_chunk": int(max_pci),
                "cumulative_chunk_wall_ms": 0.0,
                "total_no_op": 0,
                "overlay_terminal_done_on_complete": bool(_request_overlay_terminal_completion_mark),
            }
            self._destination_reconcile_global_planned_parents_process_chunk()
        except Exception as exc:
            self._log_restore_exception("destination_reconcile_all_planned_parents_after_graph_update", exc)
            self._destination_global_reconcile_chunk_state = None
            self._destination_global_planned_reconcile_active = False
            self._destination_reconcile_in_progress = False
            return True
        return True

    def _destination_collect_unresolved_overlay_target_canonical_paths(self) -> list[str]:
        """Canonical destination parent paths that still need overlay attachment (proposed + allocations)."""
        out: list[str] = []
        seen: set[str] = set()
        for bucket in (self.unresolved_proposed_by_parent_path or {}).values():
            for pf in bucket.values():
                pp = self._proposed_parent_path(pf)
                if not pp:
                    continue
                if self._destination_unresolved_replay_parent_path_structurally_invalid(pp)[0]:
                    continue
                c = self._canonical_destination_projection_path(pp) or self.normalize_memory_path(pp)
                if c and c not in seen:
                    seen.add(c)
                    out.append(c)
        for bucket in (self.unresolved_allocations_by_parent_path or {}).values():
            for mv in bucket.values():
                ap = self._allocation_parent_path(mv)
                if not ap:
                    continue
                if self._destination_unresolved_replay_parent_path_structurally_invalid(ap)[0]:
                    continue
                c = self._canonical_destination_projection_path(ap) or self.normalize_memory_path(ap)
                if c and c not in seen:
                    seen.add(c)
                    out.append(c)
        return out

    def _destination_visible_library_anchor_resolution(self) -> tuple[str, dict[str, Any] | None]:
        """Return ``(canonical_path, hub_payload)`` for the visible document-library hub row.

        The hub is a normal folder inside the selected destination document library (SharePoint).
        It must be tracked by Graph ``id`` + ``drive_id`` for durable identity; the returned path is
        mutable display state that may change when the folder is renamed in Graph.
        """
        if not destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            return "", None
        model = getattr(self, "destination_planning_model", None)
        if model is None:
            return "", None
        try:
            rc = int(model.rowCount(QModelIndex()))
        except Exception:
            return "", None
        if rc <= 0:
            return "", None
        root = QModelIndex()
        hubs: list[tuple[str, dict[str, Any]]] = []
        for tr in range(rc):
            ix = model.index(tr, 0, root)
            if not ix.isValid():
                continue
            pl = ix.data(Qt.UserRole) or {}
            if not isinstance(pl, dict):
                continue
            if pl.get("placeholder"):
                role = str(pl.get("placeholder_role") or "")
                if role == "destination_authority_pending" or pl.get("non_authoritative_destination_shell"):
                    continue
                continue
            if not bool(pl.get("is_folder", False)):
                continue
            p = self._tree_item_path(pl)
            if not p:
                continue
            c = self._canonical_destination_projection_path(p) or self.normalize_memory_path(p)
            if c:
                hubs.append((c, pl))
        if len(hubs) == 1:
            return hubs[0][0], hubs[0][1]
        if len(hubs) > 1:
            sel_drive = str(self._current_selected_destination_drive_id() or "").strip()
            if not sel_drive:
                sel_drive = str((getattr(self, "pending_root_drive_ids", None) or {}).get("destination") or "").strip()
            for tr in range(rc):
                ix = model.index(tr, 0, root)
                if not ix.isValid():
                    continue
                pl = ix.data(Qt.UserRole) or {}
                if not isinstance(pl, dict) or pl.get("placeholder"):
                    continue
                if not bool(pl.get("is_folder", False)):
                    continue
                rd = str(pl.get("drive_id") or "").strip()
                if (
                    sel_drive
                    and rd
                    and rd.casefold() == sel_drive.casefold()
                    and destination_payload_is_live_graph_row(pl)
                ):
                    p = self._tree_item_path(pl)
                    if not p:
                        continue
                    c = self._canonical_destination_projection_path(p) or self.normalize_memory_path(p)
                    if c:
                        log_info(
                            "destination_anchor_multiple_hubs_resolved_to_live_graph",
                            anchor_excerpt=str(c)[:200],
                            drive_suffix=sel_drive[-16:] if len(sel_drive) > 16 else sel_drive,
                        )
                        return c, pl
            log_info(
                "destination_anchor_multiple_hubs_blocked",
                hub_count=int(len(hubs)),
            )
            return "", None
        if rc == 1:
            ix = model.index(0, 0, root)
            if not ix.isValid():
                return "", None
            pl = ix.data(Qt.UserRole) or {}
            if not isinstance(pl, dict) or pl.get("placeholder"):
                return "", None
            p = self._tree_item_path(pl)
            if not p:
                return "", None
            c = self._canonical_destination_projection_path(p) or self.normalize_memory_path(p)
            return c, pl
        return "", None

    def _destination_visible_library_anchor_canonical_path(self) -> str:
        """See :meth:`_destination_visible_library_anchor_resolution` — path-only convenience."""
        p, _pl = self._destination_visible_library_anchor_resolution()
        return p

    def _destination_apply_anchor_graph_identity_delta_if_needed(self) -> None:
        """Reconcile persisted visible-anchor Graph identity with the live tree (rename updates paths; missing → review)."""
        try:
            if self._planning_browse_mode("destination") == "local":
                return
            mm = self.memory_manager
            if mm is None:
                return
            st = self._draft_shell_state if isinstance(self._draft_shell_state, SessionState) else None
            if st is None:
                return
            aid = str(getattr(st, "DestinationAnchorItemId", "") or "").strip()
            if not aid:
                return
            dd = str(getattr(st, "DestinationAnchorDriveId", "") or "").strip() or str(
                self._current_selected_destination_drive_id() or ""
            ).strip()
            if not dd:
                return
            dm = getattr(self, "destination_planning_model", None)
            if dm is None:
                return
            ix = dm.find_index_by_drive_item(dd, aid)
            old_disp = str(getattr(st, "DestinationAnchorDisplayPath", "") or "").strip()
            if not ix.isValid():
                if not bool(getattr(st, "DestinationAnchorLiveUnresolved", False)):
                    log_info(
                        "destination_anchor_missing_after_delta",
                        item_id_suffix=aid[-16:] if len(aid) > 16 else aid,
                        drive_suffix=dd[-16:] if len(dd) > 16 else dd,
                    )
                    log_info(
                        "destination_memory_anchor_unresolved",
                        reason="anchor_item_not_found_in_destination_tree",
                    )
                    st.DestinationAnchorLiveUnresolved = True
                    self._save_draft_shell()
                return
            pl = ix.data(Qt.UserRole) or {}
            if not isinstance(pl, dict):
                return
            live_id = str(pl.get("id") or pl.get("graph_item_id") or "").strip()
            if live_id and live_id.casefold() != aid.casefold():
                return
            new_path = str(self._destination_row_semantic_path(pl) or "").strip()
            st.DestinationAnchorLiveUnresolved = False
            if new_path and old_disp and new_path.casefold() != old_disp.casefold():
                log_info(
                    "destination_anchor_renamed_by_graph_delta",
                    old_excerpt=old_disp[:200],
                    new_excerpt=new_path[:200],
                    item_id_suffix=aid[-16:] if len(aid) > 16 else aid,
                )
                ad_raw = [r.to_dict() for r in mm.load_allocations()]
                pd_raw = [r.to_dict() for r in mm.load_proposed()]
                nchg, ad2, pd2 = rebase_allocation_and_proposed_paths_for_anchor_rename(
                    ad_raw, pd_raw, old_anchor_path=old_disp, new_anchor_path=new_path
                )
                if nchg:
                    log_info(
                        "destination_memory_paths_rebased_after_anchor_rename",
                        fields_updated=int(nchg),
                    )
                    mm.save_allocations(
                        [AllocationRow.from_dict(x) for x in ad2],
                        allow_empty_planning_persist=True,
                        save_reason="destination_anchor_display_rename",
                    )
                    mm.save_proposed(
                        [ProposedFolder.from_dict(x) for x in pd2],
                        allow_empty_planning_persist=True,
                        save_reason="destination_anchor_display_rename",
                    )
                st.DestinationAnchorDisplayPath = new_path
                st.DestinationAnchorPathVerifiedAtUtc = datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")
                self._save_draft_shell()
                session_raw = json.loads(mm.paths["session"].read_text(encoding="utf-8"))
                self._restore_memory_payload(
                    st,
                    mm.load_allocations(),
                    mm.load_proposed(),
                    session_raw,
                )
            elif new_path and not old_disp:
                st.DestinationAnchorDisplayPath = new_path
                st.DestinationAnchorPathVerifiedAtUtc = datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")
                self._save_draft_shell()
        except Exception as exc:
            self._log_restore_exception("destination_apply_anchor_graph_identity_delta", exc)

    def _canonical_destination_path_with_visible_library_anchor(self, raw_planning_path: str) -> str:
        """Same library re-anchor as :meth:`_ensure_destination_projection_path_sharepoint_graph_only`.

        Proposed/allocation memory paths often omit the visible hub (e.g. ``Finance\\Child``) while
        model parent rows are anchored under the live library hub folder (e.g. ``<hub>\\Finance``).
        Suffix-under-parent checks must compare like-for-like canonical paths.
        """
        from ozlink_console.destination_path_bridge import (
            remap_under_visible_library_anchor,
            strip_legacy_internal_root_prefix,
        )

        walk_base = str(raw_planning_path or "").strip()
        if not walk_base:
            return ""
        if not destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            return self._canonical_destination_projection_path(walk_base) or self.normalize_memory_path(walk_base)
        anchor = self._destination_visible_library_anchor_canonical_path()
        if not anchor:
            return self._canonical_destination_projection_path(walk_base) or self.normalize_memory_path(walk_base)
        ra = remap_under_visible_library_anchor(
            strip_legacy_internal_root_prefix(walk_base),
            strip_legacy_internal_root_prefix(anchor),
        )
        return (
            self._canonical_destination_projection_path(ra) or self.normalize_memory_path(ra) or walk_base
        )

    def _canonical_planned_memory_path_for_graph_match(self, raw_in: str) -> str:
        """Single canonical form for ``planned_moves`` / proposed memory vs visible model rows under Graph authority.

        Applies the same visible-library anchor remap as :meth:`_canonical_destination_path_with_visible_library_anchor`,
        then :meth:`_canonical_destination_projection_path`. Use this anywhere a persisted planning path must be
        compared to or aligned with graph-relative model ``item_path`` values (e.g. ``Root3\\HR\\...``).
        """
        raw = str(raw_in or "").strip()
        if not raw:
            return ""
        if destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            raw = self._canonical_destination_path_with_visible_library_anchor(raw) or raw
        return (
            self._canonical_destination_projection_path(raw) or self.normalize_memory_path(str(raw)) or ""
        ).strip()

    def _destination_forensic_canon_diff_branch_hit(self, path: str) -> str:
        """Return configured branch prefix if forensic canon-diff logging should emit a bundle for ``path``."""
        if not self._destination_forensic_planned_item_materialization_logging_enabled():
            return ""
        spec = str(os.getenv("OZLINK_DESTINATION_FORENSIC_CANON_DIFF_PREFIXES", "") or "").strip()
        if not spec:
            return ""
        pc = self._canonical_planned_memory_path_for_graph_match(path)
        if not pc:
            return ""
        pcf = pc.casefold()
        for pref in (p.strip() for p in spec.split(",") if p.strip()):
            pnorm = self._canonical_planned_memory_path_for_graph_match(pref)
            if not pnorm:
                continue
            nf = pnorm.casefold()
            if pcf == nf or pcf.startswith(nf + "\\"):
                return pref
        return ""

    def _log_sharepoint_overlay_destination_anchor_normalized(
        self,
        *,
        overlay_kind: str,
        raw_destination_excerpt: str,
        bare_canonical_excerpt: str,
        library_anchored_canonical_excerpt: str,
    ) -> None:
        if (bare_canonical_excerpt or "").casefold().strip() == (
            library_anchored_canonical_excerpt or ""
        ).casefold().strip():
            return
        self._log_restore_phase(
            "sharepoint_overlay_destination_path_anchor_normalized",
            overlay_kind=str(overlay_kind or "")[:80],
            raw_destination_excerpt=str(raw_destination_excerpt or "")[:260],
            bare_canonical_excerpt=str(bare_canonical_excerpt or "")[:260],
            library_anchored_canonical_excerpt=str(library_anchored_canonical_excerpt or "")[:260],
        )

    def _schedule_proactive_graph_parent_chains_for_unresolved_overlays(self, *, reason: str) -> int:
        """Walk unresolved overlay targets and queue Graph folder loads for missing real parents (Graph authority only)."""
        if not destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            return 0
        tree = getattr(self, "destination_tree_widget", None)
        if tree is None or self._planning_tree_top_level_count(tree) <= 0:
            return 0
        targets = self._destination_collect_unresolved_overlay_target_canonical_paths()
        if not targets:
            return 0
        _interact = False
        try:
            _fn = getattr(self, "_destination_user_scroll_interaction_active", None)
            _interact = callable(_fn) and bool(_fn())
        except Exception:
            _interact = False
        seen = getattr(self, "_destination_overlay_proactive_chain_seen", None)
        if not isinstance(seen, set):
            seen = set()
            self._destination_overlay_proactive_chain_seen = seen
        if len(seen) > 400:
            seen.clear()
        targets.sort(key=lambda p: len(self._path_segments(p)))
        scheduled_paths: list[str] = []
        deduped = 0
        max_targets = 32
        if _interact:
            max_targets = min(max_targets, 6)
            _lm = float(getattr(self, "_destination_interaction_throttle_log_mono", 0.0) or 0.0)
            if time.monotonic() - _lm > 1.8:
                self._destination_interaction_throttle_log_mono = time.monotonic()
                log_info(
                    "destination_interaction_throttle_engaged",
                    phase="proactive_parent_chain",
                    max_targets=int(max_targets),
                    reason_excerpt=str(reason or "")[:160],
                )
        from ozlink_console.destination_path_bridge import (
            canonical_planning_path_from_library_relative_segments,
            library_relative_segments_from_planning_path,
        )

        chain_preview: list[str] = []
        for t in targets[:4]:
            segs = library_relative_segments_from_planning_path(t)
            for d in range(1, len(segs)):
                cp = canonical_planning_path_from_library_relative_segments(segs[:d])
                if cp:
                    chain_preview.append(cp[:88])
        for t in targets[:max_targets]:
            key = str(t).casefold()
            if key in seen:
                deduped += 1
                continue
            seen.add(key)
            self._ensure_destination_projection_path_sharepoint_graph_only(t)
            scheduled_paths.append(t)
        if scheduled_paths or deduped:
            self._log_restore_phase(
                "destination_overlay_proactive_parent_chain_batch",
                reason=str(reason or "")[:120],
                target_count=len(targets),
                scheduled_count=len(scheduled_paths),
                deduped_same_pass=int(deduped),
                scheduled_path_excerpts=" | ".join(p[:80] for p in scheduled_paths[:6]),
                required_parent_chain_preview=" | ".join(chain_preview[:10]),
            )
        if scheduled_paths:
            log_info(
                "parent_chain_proactive_load_triggered",
                reason=str(reason or "")[:120],
                scheduled_count=len(scheduled_paths),
                target_count=len(targets),
            )
        return len(scheduled_paths)

    def _destination_snapshot_path_should_prioritize_overlays(self, path: str) -> bool:
        """True when a restore pending path is on or under an unresolved overlay parent chain."""
        if not path:
            return False
        pn = self._canonical_destination_projection_path(path) or self.normalize_memory_path(path)
        if not pn:
            return False
        pn_l = pn.casefold()
        for op in self._destination_collect_unresolved_overlay_target_canonical_paths():
            if not op:
                continue
            ol = op.casefold()
            if pn_l == ol or pn_l.startswith(ol + "\\") or ol.startswith(pn_l + "\\"):
                return True
        return False

    def _destination_folder_expects_planned_workspace_underneath(self, folder_canonical: str) -> bool:
        """True when workspace planning targets a descendant (or this folder) so ``terminal_empty`` would mislead."""
        if not folder_canonical:
            return False
        if self._destination_snapshot_path_should_prioritize_overlays(folder_canonical):
            return True
        fc = self._canonical_destination_projection_path(folder_canonical) or self.normalize_memory_path(folder_canonical)
        if not fc:
            return False
        fc_l = fc.casefold()
        graph_auth = destination_authority_contract.graph_owns_visible_real_destination_structure(self)
        for move in getattr(self, "planned_moves", None) or []:
            if not isinstance(move, dict):
                continue
            proj = self._allocation_projection_path(move)
            if not proj:
                continue
            if graph_auth:
                proj = self._canonical_destination_path_with_visible_library_anchor(proj) or proj
            d = self._canonical_destination_projection_path(proj) or self.normalize_memory_path(proj)
            if not d:
                continue
            dl = d.casefold()
            if dl == fc_l or dl.startswith(fc_l + "\\"):
                return True
        for pf in getattr(self, "proposed_folders", None) or []:
            dp = self._proposed_destination_path(pf)
            if not dp:
                continue
            if graph_auth:
                dp = self._canonical_destination_path_with_visible_library_anchor(dp) or dp
            d = self._canonical_destination_projection_path(dp) or self.normalize_memory_path(dp)
            if not d:
                continue
            dl = d.casefold()
            if dl == fc_l or dl.startswith(fc_l + "\\"):
                return True
        return False

    def _destination_strip_terminal_empty_when_planned_descendants_expected(
        self, parent_ix: QModelIndex, *, folder_semantic_path: str
    ) -> None:
        """Remove Graph ``terminal_empty`` placeholder when overlays will populate under this folder."""
        if not folder_semantic_path or not parent_ix.isValid():
            self._destination_forensic_strip_terminal_empty_decision(
                folder_semantic_path=str(folder_semantic_path or ""),
                decision="no_op",
                detail="invalid_folder_semantic_path_or_parent_index",
            )
            return
        if not destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            self._destination_forensic_strip_terminal_empty_decision(
                folder_semantic_path=str(folder_semantic_path),
                decision="no_op",
                detail="not_graph_authority",
            )
            return
        if not self._destination_folder_expects_planned_workspace_underneath(folder_semantic_path):
            self._destination_forensic_strip_terminal_empty_decision(
                folder_semantic_path=str(folder_semantic_path),
                decision="skip",
                detail="no_planned_workspace_or_overlay_expected_under_folder",
            )
            return
        model = getattr(self, "destination_planning_model", None)
        if model is None:
            self._destination_forensic_strip_terminal_empty_decision(
                folder_semantic_path=str(folder_semantic_path),
                decision="no_op",
                detail="no_destination_planning_model",
            )
            return
        col0 = parent_ix.siblingAtColumn(0) if parent_ix.column() != 0 else parent_ix
        if model.rowCount(col0) != 1:
            self._destination_forensic_strip_terminal_empty_decision(
                folder_semantic_path=str(folder_semantic_path),
                decision="skip",
                detail=f"row_count_not_1_got_{int(model.rowCount(col0))}",
            )
            return
        only_ix = model.index(0, 0, col0)
        pl = self._destination_model_index_user_role_dict(only_ix)
        if not pl.get("placeholder") or str(pl.get("placeholder_role") or "") != "terminal_empty":
            self._destination_forensic_strip_terminal_empty_decision(
                folder_semantic_path=str(folder_semantic_path),
                decision="skip",
                detail="sole_child_not_terminal_empty_placeholder",
            )
            return
        model.remove_placeholder_children(col0)
        self._destination_forensic_strip_terminal_empty_decision(
            folder_semantic_path=str(folder_semantic_path),
            decision="stripped",
            detail="removed_terminal_empty_placeholder",
        )
        log_info(
            "destination_terminal_empty_suppressed_for_planned_descendants",
            folder_path_excerpt=str(folder_semantic_path)[:260],
        )

    def _destination_finalize_pass_log_reason(self, reason: str) -> bool:
        """High-signal finalize/reconcile phases (avoid logging every lightweight overlay tick)."""
        r = str(reason or "").lower()
        if r in {"destination_full_tree_idle_success", "destination_authority_shell_hard_flush"}:
            return True
        for needle in (
            "deferred_",
            "graph_ids_resolved",
            "folder_worker_success",
            "idle_destination",
            "phase4",
            "import_",
            "draft_reset",
            "destination_reconcile",
            "cache_refresh",
            "lazy_",
            "source_restore_flush",
        ):
            if needle in r:
                return True
        return False

    def _destination_intended_workspace_prefix_closure_casefold(self, intended: list[str]) -> set[str]:
        """Prefix paths of every intended target (folder chain), for exact-target misplaced checks.

        Without this, intermediate ``planned_only`` folder rows under a file target are misclassified
        as misplaced and removed during finalize even though they are required workspace scaffolding.
        """
        out: set[str] = set()
        graph_auth = destination_authority_contract.graph_owns_visible_real_destination_structure(self)
        for p in intended or []:
            raw_full = str(p or "").strip()
            if not raw_full:
                continue
            segs = self._path_segments(raw_full)
            acc: list[str] = []
            for s in segs:
                acc.append(s)
                walk = "\\".join(acc)
                adj = walk
                if graph_auth:
                    adj = self._canonical_destination_path_with_visible_library_anchor(walk) or walk
                c = self._canonical_destination_projection_path(adj) or self.normalize_memory_path(adj)
                if c:
                    out.add(c.casefold())
        return out

    def _destination_collect_intended_workspace_target_canonical_paths(self) -> list[str]:
        """Canonical paths allocations/proposed intend to occupy (for placement audit)."""
        out: list[str] = []
        seen: set[str] = set()
        graph_auth = destination_authority_contract.graph_owns_visible_real_destination_structure(self)
        for move in getattr(self, "planned_moves", None) or []:
            if not isinstance(move, dict):
                continue
            proj = self._allocation_projection_path(move)
            if not proj:
                continue
            if graph_auth:
                proj = self._canonical_destination_path_with_visible_library_anchor(proj) or proj
            c = self._canonical_destination_projection_path(proj) or self.normalize_memory_path(proj)
            if c and c.casefold() not in seen:
                seen.add(c.casefold())
                out.append(c)
        for pf in getattr(self, "proposed_folders", None) or []:
            raw = self._proposed_destination_path(pf)
            if not raw:
                continue
            if graph_auth:
                raw = self._canonical_destination_path_with_visible_library_anchor(raw) or raw
            c = self._canonical_destination_projection_path(raw) or self.normalize_memory_path(raw)
            if c and c.casefold() not in seen:
                seen.add(c.casefold())
                out.append(c)
        if dest_forensic.exact_target_pipeline_trace_enabled():
            for i, p in enumerate(out):
                log_info(
                    "destination_exact_target_pipeline_intended_entry",
                    intended_index=int(i),
                    canonical_intended_path=str(p)[:400],
                    total_intended=len(out),
                )
        return out

    def _destination_forensic_nearest_visible_ancestor_path(self, intended_canonical: str, visible_paths_cf: set[str]) -> str:
        segs = self._path_segments(intended_canonical or "")
        if not segs:
            return ""
        acc: list[str] = []
        best = ""
        for s in segs[:-1]:
            acc.append(s)
            cand = self._canonical_destination_projection_path("\\".join(acc)) or "\\".join(acc)
            if cand.casefold() in visible_paths_cf:
                best = cand
        return best

    def _destination_audit_overlay_placement_after_pass(self, reason: str) -> None:
        """Compare intended workspace targets to visible model paths (Graph authority only)."""
        if not destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            return
        if not self._destination_placement_audit_enabled():
            return
        model = getattr(self, "destination_planning_model", None)
        if model is None:
            return
        intended = self._destination_collect_intended_workspace_target_canonical_paths()
        visible_planned: list[str] = []
        all_visible_realish_paths: list[str] = []
        terminal_empty_bad_folders: list[str] = []
        try:
            root = QModelIndex()
            stack: list[QModelIndex] = []
            for r in range(model.rowCount(root)):
                stack.append(model.index(r, 0, root))
            while stack:
                ix = stack.pop()
                if not ix.isValid():
                    continue
                pl = self._destination_model_index_user_role_dict(ix)
                if pl.get("placeholder"):
                    role = str(pl.get("placeholder_role") or "")
                    if role == "terminal_empty":
                        par = ix.parent()
                        if par.isValid():
                            ppl = self._destination_model_index_user_role_dict(par)
                            sp = self._destination_semantic_path(ppl) or self._tree_item_path(ppl)
                            if sp and self._destination_folder_expects_planned_workspace_underneath(sp):
                                cpath = (
                                    self._canonical_destination_projection_path(self._tree_item_path(ppl) or "")
                                    or sp
                                )
                                terminal_empty_bad_folders.append(str(cpath)[:400])
                    for c in range(model.rowCount(ix)):
                        stack.append(model.index(c, 0, ix))
                    continue
                rp = self._destination_row_raw_path_for_path_lookup_match(pl)
                if rp:
                    vc = self._canonical_destination_projection_path(rp) or rp
                    if vc:
                        all_visible_realish_paths.append(vc)
                        if destination_payload_is_planned_workspace_row(pl):
                            visible_planned.append(vc)
                for c in range(model.rowCount(ix)):
                    stack.append(model.index(c, 0, ix))
        except Exception as exc:
            self._log_restore_exception("destination_overlay_placement_audit_walk_failed", exc)
            return
        vis_set = {v.casefold() for v in visible_planned}
        intended_cf_closure = self._destination_intended_workspace_prefix_closure_casefold(intended)
        all_vis_cf = {p.casefold() for p in all_visible_realish_paths}
        missing = [p for p in intended if p.casefold() not in vis_set]
        misplaced = [v for v in visible_planned if v.casefold() not in intended_cf_closure]
        exact_visible_planned = len([p for p in intended if p.casefold() in vis_set])
        problematic_samples: list[dict[str, str]] = []
        for p in missing[:20]:
            nearest = self._destination_forensic_nearest_visible_ancestor_path(p, all_vis_cf)
            misplaced_hit = ""
            for m in misplaced:
                if self._path_segments(m) and self._path_segments(m)[-1].casefold() == self._path_segments(p)[
                    -1
                ].casefold() and m.casefold() != p.casefold():
                    misplaced_hit = m
                    break
            problematic_samples.append(
                {
                    "intended_canonical_path": p[:400],
                    "nearest_visible_ancestor": nearest[:400],
                    "visible_misplaced_path_guess": misplaced_hit[:400],
                    "reason_code": "missing_planned_workspace_row_at_intended_path",
                }
            )
        for m in misplaced[: max(0, 20 - len(problematic_samples))]:
            problematic_samples.append(
                {
                    "intended_canonical_path": "",
                    "nearest_visible_ancestor": "",
                    "visible_misplaced_path_guess": m[:400],
                    "reason_code": "visible_planned_row_not_in_intended_target_set",
                }
            )
        log_info(
            "destination_overlay_placement_audit",
            materialize_reason=str(reason or "")[:120],
            intended_count=len(intended),
            visible_planned_count=len(visible_planned),
            missing_exact_paths_count=len(missing),
            misplaced_visible_rows_count=len(misplaced),
            missing_path_excerpts=" | ".join(m[:72] for m in missing[:8]),
            misplaced_path_excerpts=" | ".join(m[:72] for m in misplaced[:8]),
            terminal_empty_despite_expected_descendants_count=len(terminal_empty_bad_folders),
            terminal_empty_bad_folder_excerpts=" | ".join(terminal_empty_bad_folders[:6]),
        )
        dest_forensic.log_placement_summary(
            materialize_reason=str(reason or "")[:120],
            total_intended_target_paths=len(intended),
            exact_visible_planned_matches=int(exact_visible_planned),
            visible_misplaced_rows=len(misplaced),
            missing_target_paths=len(missing),
            rows_merged_by_exact_path_skipped_here=0,
            rows_merged_by_non_exact_path_skipped_here=0,
            rows_removed_during_reconcile_skipped_here=0,
            folders_terminal_empty_despite_expected_descendants=len(terminal_empty_bad_folders),
            problematic_path_samples=problematic_samples[:20],
        )

    def _destination_enumerate_visible_planned_paths_and_all_visible(self) -> tuple[list[str], list[str]]:
        """Return ``(visible_planned_canonical_paths, all_visible_row_paths)`` from the destination model.

        **visible_planned**: canonical paths for rows where ``destination_payload_is_planned_workspace_row`` is true
        (planned allocations, proposed scaffolding, etc.) — a **depth-first walk of the in-memory model**, not
        replay counters and not Qt view paint state. Rows under collapsed tree branches are still counted here
        if they exist in the model.

        **Startup success metric**: ``startup_memory_planned_attach_complete`` previously reported
        ``attached_planned_rows=len(visible_planned)`` — that is **this** visible-planned enumeration, not
        ``n_prop+n_alloc`` replay totals. Gaps vs persisted planning usually meant: empty unresolved replay queues,
        bind gating on expanded paths only, or missing parent-chain rows before descendants could attach — not a
        wrong counter definition.
        """
        model = getattr(self, "destination_planning_model", None)
        if model is None:
            return [], []
        visible_planned: list[str] = []
        all_visible: list[str] = []
        try:
            root = QModelIndex()
            stack: list[QModelIndex] = []
            for r in range(model.rowCount(root)):
                stack.append(model.index(r, 0, root))
            while stack:
                ix = stack.pop()
                if not ix.isValid():
                    continue
                pl = self._destination_model_index_user_role_dict(ix)
                if pl.get("placeholder"):
                    for c in range(model.rowCount(ix)):
                        stack.append(model.index(c, 0, ix))
                    continue
                rp = self._destination_row_raw_path_for_path_lookup_match(pl)
                if rp:
                    vc = self._canonical_destination_projection_path(rp) or rp
                    if vc:
                        all_visible.append(vc)
                        if destination_payload_is_planned_workspace_row(pl):
                            visible_planned.append(vc)
                for c in range(model.rowCount(ix)):
                    stack.append(model.index(c, 0, ix))
        except Exception:
            return visible_planned, all_visible
        return visible_planned, all_visible

    def _destination_enforcement_terminal_is_file_for_intended_path(self, intended_canon: str) -> bool:
        """True when ``intended_canon`` matches a file allocation (not a folder move)."""
        graph_auth = destination_authority_contract.graph_owns_visible_real_destination_structure(self)
        icf = str(intended_canon or "").casefold().strip()
        if not icf:
            return False
        for move in getattr(self, "planned_moves", None) or []:
            if not isinstance(move, dict):
                continue
            proj = self._allocation_projection_path(move)
            if not proj:
                continue
            if graph_auth:
                proj = self._canonical_destination_path_with_visible_library_anchor(proj) or proj
            c = self._canonical_destination_projection_path(proj) or self.normalize_memory_path(proj)
            if not c or c.casefold() != icf:
                continue
            return self._planned_move_terminal_is_file_leaf(move)
        return False

    def _destination_enforcement_terminal_is_file_lookup_map(self) -> dict[str, bool]:
        """First match per canonical path (same semantics as scanning ``planned_moves`` per intended path)."""
        graph_auth = destination_authority_contract.graph_owns_visible_real_destination_structure(self)
        out: dict[str, bool] = {}
        for move in getattr(self, "planned_moves", None) or []:
            if not isinstance(move, dict):
                continue
            proj = self._allocation_projection_path(move)
            if not proj:
                continue
            if graph_auth:
                proj = self._canonical_destination_path_with_visible_library_anchor(proj) or proj
            c = self._canonical_destination_projection_path(proj) or self.normalize_memory_path(proj)
            if not c:
                continue
            cf = c.casefold()
            if cf in out:
                continue
            out[cf] = self._planned_move_terminal_is_file_leaf(move)
        return out

    def _destination_run_exact_target_enforcement_pass(self, reason: str) -> None:
        """Ensure every intended planning path has a visible planned/live row at that exact canonical path."""
        log_info(
            "destination_exact_target_enforcement_entered",
            reason=str(reason or "")[:240],
        )
        if not destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            return
        model = getattr(self, "destination_planning_model", None)
        if model is None:
            return
        intended = self._destination_collect_intended_workspace_target_canonical_paths()
        if not intended:
            return
        _term_file_by_cf = self._destination_enforcement_terminal_is_file_lookup_map()
        _pt = dest_forensic.exact_target_pipeline_trace_enabled()
        prev_tried = list(getattr(self, "_destination_exact_target_pipeline_last_bind_intendeds", None) or [])

        def _snapshot(enumerate_phase: str) -> tuple[list[str], list[str], set[str], list[str], list[str]]:
            with self._destination_materialize_profile_span(enumerate_phase):
                vp, av = self._destination_enumerate_visible_planned_paths_and_all_visible()
            icf = {i.casefold() for i in intended}
            icf_closure = self._destination_intended_workspace_prefix_closure_casefold(intended)
            vset = {p.casefold() for p in vp}
            missing = [p for p in intended if p.casefold() not in vset]
            misplaced = [p for p in vp if p.casefold() not in icf_closure]
            return vp, av, icf, missing, misplaced

        vp0, av0, intended_cf, missing_before, misplaced_before = _snapshot(
            "exact_target_enumerate_initial"
        )
        all_vis_cf0 = {p.casefold() for p in av0}
        vpl_cf0 = {p.casefold() for p in vp0}
        if _pt:
            for p in intended:
                log_info(
                    "destination_exact_target_pipeline_intended_vs_visible_planned",
                    canonical_intended=str(p)[:400],
                    visible_as_planned_exact=bool(p.casefold() in vpl_cf0),
                    enforcement_reason=str(reason or "")[:120],
                )
            for p in prev_tried:
                log_info(
                    "destination_exact_target_pipeline_survival_since_previous_pass",
                    canonical_intended=str(p)[:400],
                    visible_as_planned_exact_at_start_of_this_pass=bool(p.casefold() in vpl_cf0),
                    enforcement_reason=str(reason or "")[:120],
                )
        log_info(
            "destination_exact_target_enforcement_started",
            reason=str(reason or "")[:120],
            total_intended=len(intended),
            total_visible=len(vp0),
            visible_planned_workspace_rows=len(vp0),
            all_visible_destination_rows=len(av0),
            missing_count=len(missing_before),
            misplaced_count=len(misplaced_before),
            missing_paths_before=" | ".join(missing_before[:24]),
            misplaced_paths_before=" | ".join(misplaced_before[:24]),
        )

        misplaced_sorted = sorted(
            set(misplaced_before),
            key=lambda p: (-len(self._path_segments(p)), str(p).lower()),
        )
        _icf_closure_removal = self._destination_intended_workspace_prefix_closure_casefold(intended)
        with self._destination_materialize_profile_span("exact_target_misplaced_removal_loop"):
            for mpath in misplaced_sorted:
                ix = self._destination_find_planning_index_for_overlay_target_path(mpath)
                if ix is None or not ix.isValid():
                    continue
                pl = self._destination_model_index_user_role_dict(ix)
                if not destination_payload_is_planned_workspace_row(pl):
                    continue
                if destination_payload_is_live_graph_row(pl):
                    continue
                to_hint = ""
                dp = str(pl.get("destination_path") or pl.get("item_path") or "").strip()
                if dp:
                    dpc = self._canonical_destination_projection_path(dp) or self.normalize_memory_path(dp)
                    if dpc and dpc.casefold() in _icf_closure_removal:
                        to_hint = dpc
                col0 = ix.siblingAtColumn(0) if ix.column() != 0 else ix
                try:
                    model.remove_node_at(col0)
                except Exception as exc:
                    self._log_restore_exception("destination_exact_target_remove_misplaced", exc)
                    continue
                if to_hint:
                    log_info(
                        "destination_exact_target_force_move",
                        from_path=str(mpath)[:400],
                        to_path=str(to_hint)[:400],
                    )
                else:
                    log_info(
                        "destination_exact_target_force_move",
                        from_path=str(mpath)[:400],
                        to_path="(removed_orphan_planned_recreate_via_missing_pass)",
                    )

        vp1, av1, _icf, missing_mid, misplaced_mid = _snapshot(
            "exact_target_enumerate_after_misplaced"
        )
        all_vis_cf = {p.casefold() for p in av1}
        bind_tried: list[str] = []

        missing_before_cf = {x.casefold() for x in missing_before}
        with self._destination_materialize_profile_span("exact_target_missing_bind_loop"):
            for int_path in list(missing_mid):
                mb = int_path.casefold() in missing_before_cf
                if _pt:
                    log_info(
                        "destination_exact_target_pipeline_missing_classify",
                        canonical_intended=str(int_path)[:400],
                        in_missing_before_snapshot=bool(mb),
                        in_missing_after_misplaced_removal=bool(
                            int_path.casefold() in {x.casefold() for x in missing_mid}
                        ),
                        enforcement_reason=str(reason or "")[:120],
                    )
                nearest = self._destination_forensic_nearest_visible_ancestor_path(int_path, all_vis_cf)
                p_ix = QModelIndex()
                nearest_used = ""
                if nearest:
                    p_ix = self._destination_find_planning_index_for_overlay_target_path(nearest) or QModelIndex()
                    nearest_used = nearest
                fallback_best_c = ""
                if not p_ix.isValid():
                    segs = self._path_segments(int_path)
                    best_ix = QModelIndex()
                    best_c = ""
                    acc = []
                    for s in segs[:-1]:
                        acc.append(s)
                        cand = self._canonical_destination_projection_path("\\".join(acc)) or "\\".join(acc)
                        if not cand:
                            continue
                        if cand.casefold() not in all_vis_cf:
                            continue
                        hit = self._destination_find_planning_index_for_overlay_target_path(cand)
                        if hit is not None and hit.isValid():
                            best_ix, best_c = hit, cand
                    p_ix, nearest_used = best_ix, best_c
                    fallback_best_c = best_c
                if _pt:
                    log_info(
                        "destination_exact_target_pipeline_ancestor_resolution",
                        canonical_intended=str(int_path)[:400],
                        forensic_nearest_visible_ancestor=str(nearest)[:400],
                        fallback_prefix_selected=str(fallback_best_c or nearest_used)[:400],
                        parent_index_valid=bool(p_ix.isValid()),
                        enforcement_reason=str(reason or "")[:120],
                    )
                if not p_ix.isValid():
                    log_warn(
                        "destination_exact_target_force_create_skipped",
                        intended_path=str(int_path)[:400],
                        detail="no_visible_ancestor_index",
                    )
                    continue
                pcol = p_ix.siblingAtColumn(0) if p_ix.column() != 0 else p_ix
                anc_canon = self._canonical_destination_projection_path(nearest_used) or nearest_used
                rel = self._sharepoint_canonical_path_segments_under_parent(anc_canon, int_path)
                if not rel:
                    log_warn(
                        "destination_exact_target_force_create_skipped",
                        intended_path=str(int_path)[:400],
                        nearest_visible_ancestor=str(nearest_used)[:400],
                        detail="empty_relative_suffix_under_ancestor",
                    )
                    continue
                _icf_path = int_path.casefold()
                _tf_hit = _term_file_by_cf.get(_icf_path)
                if _tf_hit is None:
                    _tf_hit = self._destination_enforcement_terminal_is_file_for_intended_path(int_path)
                term_file = bool(_tf_hit)
                self._destination_leaf_forensic_trace_payload(
                    "_destination_run_exact_target_enforcement_pass",
                    {
                        "name": Path(str(int_path or "")).name,
                        "destination_path": str(int_path or ""),
                        "item_path": str(int_path or ""),
                        "is_folder": not bool(term_file),
                        "row_kind": "planned_file" if term_file else "planned_folder",
                    },
                    "exact_target_enforcement_terminal_classify",
                )
                if _pt:
                    log_info(
                        "destination_exact_target_pipeline_bind_attempt",
                        canonical_intended=str(int_path)[:400],
                        nearest_visible_ancestor=str(nearest_used)[:400],
                        relative_segments="\\".join(rel)[:400],
                        segment_count=len(rel),
                        terminal_is_file=bool(term_file),
                        enforcement_reason=str(reason or "")[:120],
                    )
                _ppl_et = self._destination_model_index_user_role_dict(pcol)
                _def_et, _miss_et, _cc_et = self._graph_authority_planned_structural_bind_deferred_miss(
                    int_path, live_graph_parent_pl=_ppl_et, parent_anchor_index_valid=True
                )
                if _def_et:
                    log_info(
                        "destination_planned_chain_bind_suppressed",
                        intended_path=str(int_path)[:400],
                        reason="graph_authority_exact_target_enforcement_deferred",
                        miss_reason=_miss_et,
                        path_excerpt=str(int_path)[:260],
                        nearest_visible_parent=str(nearest_used)[:400],
                        candidate_count=int(_cc_et),
                    )
                    bind_tried.append(str(int_path))
                    continue
                bound = self._sharepoint_bind_planned_segment_chain(
                    pcol,
                    rel,
                    bind_kind="exact_target_enforcement",
                    bind_context_excerpt=str(int_path)[:220],
                    expected_parent_canonical=None,
                    projection_target_canonical=int_path,
                    terminal_is_file=bool(term_file),
                )
                bind_tried.append(str(int_path))
                if bound is not None and bound.isValid() and not term_file:
                    _bpl = self._destination_model_index_user_role_dict(bound)
                    if (
                        destination_payload_is_live_graph_row(_bpl)
                        and bool(_bpl.get("is_folder", True))
                        and not bool(_bpl.get("children_loaded"))
                        and not bool(_bpl.get("load_failed"))
                        and self._destination_row_may_lazy_enumerate_graph_children(_bpl)
                    ):
                        _bc = bound.siblingAtColumn(0) if bound.column() != 0 else bound
                        self._request_graph_destination_children_load(
                            _bc, reason="exact_target_enforcement_live_folder"
                        )
                log_info(
                    "destination_exact_target_force_create",
                    intended_path=str(int_path)[:400],
                    nearest_visible_ancestor=str(nearest_used)[:400],
                    created_segments=len(rel),
                    bind_ok=bool(bound is not None and bound.isValid()),
                )
                if _pt:
                    with self._destination_materialize_profile_span("exact_target_enumerate_post_bind_trace"):
                        vp_q, _av_q = self._destination_enumerate_visible_planned_paths_and_all_visible()
                    vq_cf = {x.casefold() for x in vp_q}
                    log_info(
                        "destination_exact_target_pipeline_post_bind",
                        canonical_intended=str(int_path)[:400],
                        visible_planned_exact_match_immediately_after_bind=bool(int_path.casefold() in vq_cf),
                        bind_returned_valid=bool(bound is not None and bound.isValid()),
                        enforcement_reason=str(reason or "")[:120],
                    )

        self._destination_exact_target_pipeline_last_bind_intendeds = bind_tried
        vp2, _av2, _icf2, missing_after, misplaced_after = _snapshot("exact_target_enumerate_final")
        vpl_cf2 = {p.casefold() for p in vp2}
        if _pt:
            for p in bind_tried:
                log_info(
                    "destination_exact_target_pipeline_end_of_pass_visibility",
                    canonical_intended=str(p)[:400],
                    visible_as_planned_exact_after_full_pass=bool(p.casefold() in vpl_cf2),
                    still_in_missing_after=bool(p.casefold() in {x.casefold() for x in missing_after}),
                    enforcement_reason=str(reason or "")[:120],
                )
        log_info(
            "destination_exact_target_enforcement_completed",
            reason=str(reason or "")[:120],
            missing_before=len(missing_before),
            missing_after=len(missing_after),
            misplaced_before=len(misplaced_before),
            misplaced_after=len(misplaced_after),
            remaining_missing_paths=" | ".join(missing_after[:40]),
            remaining_misplaced_paths=" | ".join(misplaced_after[:24]),
        )

    def _ensure_destination_projection_path_sharepoint_graph_only(
        self, normalized_target: str, *, leaf_is_file: bool = False
    ):
        """Resolve a planning path to a Graph-backed or planned-workspace QModelIndex; queue Graph loads when needed.

        Under Graph authority, planned structural chains bind when a parent index exists; visible lookup ``not_loaded``
        no longer suppresses bind (Option 3). Only ``empty_model`` defers planned-chain creation. Graph loads may still
        be queued for traversal elsewhere; they are not a gate for materializing intended canonical chains.
        """
        from ozlink_console.destination_path_bridge import (
            canonical_planning_path_from_library_relative_segments,
            library_relative_segments_from_planning_path,
            remap_under_visible_library_anchor,
            strip_legacy_internal_root_prefix,
        )

        model = getattr(self, "destination_planning_model", None)
        if model is None:
            log_info(
                "destination_planned_chain_bind_skipped",
                intended_path=str(normalized_target or "")[:400],
                reason="no_destination_planning_model",
            )
            self._startup_memory_planned_attach_note_skip("no_destination_planning_model", str(normalized_target or ""))
            return None
        _graph_strict = destination_authority_contract.graph_owns_visible_real_destination_structure(self)
        walk_base = str(normalized_target or "").strip()
        anchor = self._destination_visible_library_anchor_canonical_path()
        if anchor and walk_base:
            ra = remap_under_visible_library_anchor(
                strip_legacy_internal_root_prefix(walk_base),
                strip_legacy_internal_root_prefix(anchor),
            )
            walk_base = self._canonical_destination_projection_path(ra) or self.normalize_memory_path(ra) or walk_base
        lib_segs = library_relative_segments_from_planning_path(walk_base)
        if not lib_segs:
            log_info(
                "destination_planned_chain_bind_skipped",
                intended_path=str(normalized_target or "")[:400],
                reason="empty_library_relative_segments",
            )
            self._startup_memory_planned_attach_note_skip("empty_library_relative_segments", str(normalized_target or ""))
            return QModelIndex()
        parent_ix = QModelIndex()
        nearest_visible = ""
        for depth in range(len(lib_segs)):
            current_path = canonical_planning_path_from_library_relative_segments(lib_segs[: depth + 1])
            if not current_path:
                continue
            child_ix = self._find_destination_child_by_path(
                parent_ix, current_path, overlay_path_strict=_graph_strict
            )
            if child_ix is None:
                child_ix = self._find_visible_destination_item_by_path(current_path)
            if child_ix is None or not isinstance(child_ix, QModelIndex) or not child_ix.isValid():
                if parent_ix.isValid():
                    ppl = self._destination_model_index_user_role_dict(parent_ix)
                    if self._destination_row_may_lazy_enumerate_graph_children(ppl):
                        self._request_graph_destination_children_load(parent_ix, reason="overlay_parent_chain")
                self._log_restore_phase(
                    "sharepoint_overlay_parent_unresolved",
                    normalized_target=normalized_target,
                    depth=depth,
                    path=current_path,
                )
                if parent_ix.isValid():
                    suffix = lib_segs[depth:]
                    if suffix:
                        col0 = parent_ix.siblingAtColumn(0) if parent_ix.column() != 0 else parent_ix
                        full_target = canonical_planning_path_from_library_relative_segments(lib_segs)
                        miss_s = "\\".join(suffix)
                        log_info(
                            "destination_planned_chain_bind_attempt",
                            intended_path=str(walk_base)[:400],
                            nearest_visible_parent=str(nearest_visible)[:400],
                            segments_missing=str(miss_s)[:260],
                            created_segments_count=len(suffix),
                            leaf_is_file=bool(leaf_is_file),
                        )
                        if _graph_strict:
                            _nt_cur = self._materialize_cached_destination_lookup_norm(current_path)
                            _ppl_gate = self._destination_model_index_user_role_dict(col0)
                            _defer, _vis_miss, _cand_ct = self._graph_authority_planned_structural_bind_deferred_miss(
                                current_path,
                                normalized_target=_nt_cur,
                                live_graph_parent_pl=_ppl_gate,
                                parent_anchor_index_valid=True,
                            )
                            if _defer and not getattr(self, "_destination_planned_chain_overlay_relax", False):
                                self._log_restore_phase(
                                    "sharepoint_overlay_planned_chain_suppressed_graph_authority",
                                    normalized_target=normalized_target,
                                    depth=depth,
                                    path=current_path,
                                    miss_reason=_vis_miss,
                                    candidate_count=int(_cand_ct),
                                )
                                log_info(
                                    "destination_planned_chain_bind_suppressed",
                                    intended_path=str(walk_base)[:400],
                                    reason="graph_authority_visible_miss_unresolved_not_absent",
                                    miss_reason=_vis_miss,
                                    path_excerpt=str(current_path)[:260],
                                    nearest_visible_parent=str(nearest_visible)[:400],
                                )
                                return None
                        bound = self._sharepoint_bind_planned_segment_chain(
                            col0,
                            suffix,
                            bind_kind="ensure_projection_path",
                            bind_context_excerpt=str(normalized_target)[:220],
                            expected_parent_canonical=None,
                            projection_target_canonical=full_target or None,
                            terminal_is_file=bool(leaf_is_file),
                        )
                        if bound is not None and bound.isValid():
                            self._log_restore_phase(
                                "sharepoint_overlay_parent_planned_chain",
                                normalized_target=normalized_target,
                                depth=depth,
                                missing_suffix=str(miss_s)[:220],
                                projection_bind_mode="planned_bind",
                            )
                            log_info(
                                "destination_planned_chain_bind_success",
                                final_path=str(full_target or walk_base)[:400],
                                depth_created=int(len(suffix)),
                            )
                            return bound
                        log_info(
                            "destination_planned_chain_bind_skipped",
                            intended_path=str(walk_base)[:400],
                            reason="planned_segment_chain_bind_returned_invalid",
                            nearest_visible_parent=str(nearest_visible)[:400],
                            segments_missing=str(miss_s)[:260],
                        )
                else:
                    log_info(
                        "destination_planned_chain_bind_skipped",
                        intended_path=str(walk_base)[:400],
                        reason="missing_child_and_no_valid_parent_index",
                        nearest_visible_parent="",
                        depth=int(depth),
                    )
                    self._startup_memory_planned_attach_note_skip(
                        "missing_child_and_no_valid_parent_index",
                        str(walk_base or normalized_target or "")[:400],
                    )
                return None
            pl = self._destination_model_index_user_role_dict(child_ix)
            if not self._destination_row_allows_sharepoint_projection_traversal(pl):
                if getattr(self, "_destination_planned_chain_overlay_relax", False):
                    log_info(
                        "destination_planned_chain_bind_memory_truth_traversal_relaxed",
                        intended_path=str(walk_base)[:400],
                        path_excerpt=str(current_path)[:260],
                    )
                else:
                    self._log_restore_phase(
                        "sharepoint_overlay_parent_not_graph_backed",
                        normalized_target=normalized_target,
                        path=current_path,
                    )
                    log_info(
                        "destination_planned_chain_bind_skipped",
                        intended_path=str(walk_base)[:400],
                        reason="row_does_not_allow_sharepoint_projection_traversal",
                        path_excerpt=str(current_path)[:260],
                    )
                    return None
            nearest_visible = current_path
            parent_ix = child_ix
        return parent_ix

    def _destination_row_allows_structural_folder_child_load(self, pl: dict) -> bool:
        if not isinstance(pl, dict) or pl.get("placeholder"):
            return False
        if not bool(pl.get("is_folder", True)):
            return False
        if self._destination_is_future_state_node(pl):
            return False
        if pl.get("children_loaded") or pl.get("load_failed"):
            return False
        drive_id = self._resolve_tree_item_drive_id("destination", pl)
        item_id = str(pl.get("id") or "").strip()
        return bool(drive_id and item_id)

    def _ensure_destination_projection_path_local_overlay_walk(self, normalized_target: str):
        """Resolve a planning path to an existing model index, or queue folder loads — no projected prefix rows."""
        from ozlink_console.destination_path_bridge import (
            canonical_planning_path_from_library_relative_segments,
            library_relative_segments_from_planning_path,
        )

        model = getattr(self, "destination_planning_model", None)
        if model is None:
            return None
        lib_segs = library_relative_segments_from_planning_path(normalized_target)
        if not lib_segs:
            return QModelIndex()
        parent_ix = QModelIndex()
        for depth in range(len(lib_segs)):
            current_path = canonical_planning_path_from_library_relative_segments(lib_segs[: depth + 1])
            if not current_path:
                continue
            child_ix = self._find_destination_child_by_path(parent_ix, current_path)
            if child_ix is None:
                child_ix = self._find_visible_destination_item_by_path(current_path)
            if child_ix is None or not isinstance(child_ix, QModelIndex) or not child_ix.isValid():
                if parent_ix.isValid():
                    ppl = self._destination_model_index_user_role_dict(parent_ix)
                    if self._destination_row_allows_structural_folder_child_load(ppl):
                        self._request_destination_structural_folder_load(parent_ix, reason="overlay_parent_chain_local")
                self._log_restore_phase(
                    "destination_overlay_parent_unresolved_local",
                    normalized_target=normalized_target,
                    depth=depth,
                    path=current_path,
                )
                return None
            pl = self._destination_model_index_user_role_dict(child_ix)
            if self._destination_is_future_state_node(pl):
                self._log_restore_phase(
                    "destination_overlay_parent_future_state_local",
                    normalized_target=normalized_target,
                    path=current_path,
                )
                return None
            parent_ix = child_ix
        return parent_ix

    def _request_destination_structural_folder_load(self, index: QModelIndex, *, reason: str = "") -> bool:
        """Start FolderLoadWorker for overlay parent-chain resolution (local or SharePoint)."""
        if destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            return self._request_graph_destination_children_load(index, reason=reason)
        if not index.isValid():
            return False
        panel_key = "destination"
        col0 = index.siblingAtColumn(0) if index.column() != 0 else index
        if not col0.isValid():
            return False
        node_data = dict(col0.data(Qt.UserRole) or {})
        if not self._destination_row_allows_structural_folder_child_load(node_data):
            return False
        drive_id = self._resolve_tree_item_drive_id(panel_key, node_data)
        item_id = str(node_data.get("id") or "").strip()
        pending_key = f"{drive_id}:{item_id}"
        worker_key = f"{panel_key}:{item_id}"
        if self._folder_load_worker_thread_running(worker_key):
            self.pending_folder_loads[panel_key].add(pending_key)
            return False
        if pending_key in self.pending_folder_loads[panel_key]:
            return False
        pending_count = len(self.pending_folder_loads.get(panel_key, set()))
        if pending_count >= 3:
            return False
        self.pending_folder_loads[panel_key].add(pending_key)
        model = self.destination_planning_model
        has_future_children = self._destination_parent_has_future_state_children_model(col0)
        if not has_future_children:
            model.set_loading_children(col0)
        item_path = self._tree_item_path(node_data)
        if item_path and item_path in self._pending_snapshot_branch_refresh.get(panel_key, set()):
            self._snapshot_branch_refresh_baseline_by_worker[worker_key] = (
                self._capture_child_path_set_for_destination_model_index(col0)
            )
        preserved_children = self._preserve_destination_future_state_children_model(col0)
        if preserved_children:
            self._destination_preserved_children_by_worker[worker_key] = preserved_children
        if has_future_children:
            model.set_loading_children(col0)
        use_cache_only = False
        worker_context = {
            "site_id": node_data.get("site_id", ""),
            "site_name": node_data.get("site_name", ""),
            "library_id": node_data.get("library_id", drive_id),
            "library_name": node_data.get("library_name", ""),
            "tree_role": panel_key,
            "parent_item_path": node_data.get("item_path", ""),
            "cache_only": use_cache_only,
        }
        worker = FolderLoadWorker(self.graph, panel_key, drive_id, item_id, worker_context)
        pmi = QPersistentModelIndex(col0)
        worker_entry = self._register_folder_worker(
            worker_key,
            worker,
            None,
            pending_key=pending_key,
            destination_folder_parent_persistent=pmi,
        )
        worker.success.connect(
            lambda payload, worker_id=worker_entry["id"]: self._safe_invoke(
                "folder_worker.success", self.on_folder_load_success, payload, worker_id
            )
        )
        worker.error.connect(
            lambda payload, worker_id=worker_entry["id"]: self._safe_invoke(
                "folder_worker.error", self.on_folder_load_error, payload, worker_id
            )
        )
        worker.finished.connect(
            lambda key=worker_key, worker_id=worker_entry["id"]: self._safe_invoke(
                "folder_worker.finished", self.on_folder_worker_finished, key, worker_id
            )
        )
        worker.start()
        if reason:
            self._log_restore_phase(
                "destination_overlay_queued_structural_folder_load",
                reason=reason,
                worker_key=worker_key,
            )
        return True

    def _destination_clear_graph_child_load_backlog(self) -> None:
        self._destination_graph_child_load_backlog_hi.clear()
        self._destination_graph_child_load_backlog_lo.clear()
        self._destination_graph_child_load_backlog_keys.clear()
        self._destination_graph_subtree_hydration_roots.clear()
        self._destination_graph_subtree_hydration_meta.clear()

    def _destination_graph_child_backlog_total(self) -> int:
        return len(self._destination_graph_child_load_backlog_hi) + len(self._destination_graph_child_load_backlog_lo)

    def _destination_pop_graph_child_backlog_entry(self) -> _GraphDestinationChildBacklogEntry | None:
        if self._destination_graph_child_load_backlog_hi:
            return self._destination_graph_child_load_backlog_hi.popleft()
        if self._destination_graph_child_load_backlog_lo:
            return self._destination_graph_child_load_backlog_lo.popleft()
        return None

    def _destination_graph_child_load_queue_diag(self) -> dict:
        hi = len(self._destination_graph_child_load_backlog_hi)
        lo = len(self._destination_graph_child_load_backlog_lo)
        return {
            "active_pending_count": len(self.pending_folder_loads.get("destination", set()) or ()),
            "queued_count": hi + lo,
            "queued_hi": hi,
            "queued_lo": lo,
        }

    def _destination_graph_child_load_log_queue_state(
        self,
        *,
        trigger: str = "",
        reason: str = "",
        path_excerpt: str = "",
        item_id_suffix: str = "",
        trace_note: str = "",
    ) -> None:
        d = self._destination_graph_child_load_queue_diag()
        log_info(
            "destination_graph_child_load_queue_state",
            trace_note=str(trace_note)[:80],
            trigger=str(trigger)[:80],
            reason=str(reason)[:120],
            path_excerpt=str(path_excerpt)[:400],
            item_id_suffix=str(item_id_suffix or "")[-16:],
            active_pending_count=int(d["active_pending_count"]),
            queued_count=int(d["queued_count"]),
            queued_hi=int(d.get("queued_hi", 0)),
            queued_lo=int(d.get("queued_lo", 0)),
        )

    def _destination_start_graph_folder_load_worker_if_eligible(
        self,
        col0: QModelIndex,
        *,
        reason: str = "",
        trigger: str = "",
        graph_request_perf_override: float = 0.0,
        graph_child_union_fingerprint: Optional[dict] = None,
    ) -> bool:
        """Start a Graph :class:`FolderLoadWorker` for a destination folder row under the active cap.

        Re-reads row payload from *col0* immediately before mutating the model or registering the worker.
        """
        panel_key = "destination"
        if not col0.isValid():
            return False
        if not getattr(self, "graph", None) or not getattr(self.graph, "token", None):
            return False
        if not destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            return False
        node_data = dict(col0.data(Qt.UserRole) or {})
        if node_data.get("placeholder"):
            return False
        _live_row = self._destination_row_is_live_graph_structure(node_data)
        _derived_ok = self._destination_row_is_graph_derived_dest_child_fetch_eligible(node_data)
        if not _live_row and not _derived_ok:
            return False
        _needs_live = self._destination_row_needs_live_graph_child_refresh(node_data)
        _graph_union = self._destination_graph_child_union_skip_refresh_gate(
            str(reason or ""), node_data, graph_child_union_fingerprint
        )
        if (node_data.get("children_loaded") or node_data.get("load_failed")) and not _needs_live and not _graph_union:
            return False
        drive_id = self._resolve_tree_item_drive_id(panel_key, node_data)
        item_id = str(node_data.get("id") or "").strip()
        if not drive_id or not item_id:
            return False
        pending_key = f"{drive_id}:{item_id}"
        worker_key = f"{panel_key}:{item_id}"
        if self._folder_load_worker_thread_running(worker_key):
            self.pending_folder_loads[panel_key].add(pending_key)
            return False
        if pending_key in self.pending_folder_loads[panel_key]:
            return False
        if len(self.pending_folder_loads.get(panel_key, set())) >= _graph_destination_child_load_max_active():
            return False
        self.pending_folder_loads[panel_key].add(pending_key)
        path_excerpt = str(
            self._destination_row_raw_path_for_path_lookup_match(node_data)
            or node_data.get("item_path")
            or node_data.get("destination_path")
            or ""
        )[:400]
        model = self.destination_planning_model
        has_future_children = self._destination_parent_has_future_state_children_model(col0)
        try:
            _rc_vis = int(model.rowCount(col0))
        except Exception:
            _rc_vis = 0
        _keep_snapshot_visible = bool(_needs_live and _rc_vis > 0)
        if not has_future_children and not _keep_snapshot_visible and not _graph_union:
            model.set_loading_children(col0)
        elif _keep_snapshot_visible:
            log_info(
                "destination_graph_child_load_keeps_snapshot_visible_until_live_bind",
                path_excerpt=path_excerpt[:400],
                graph_item_id_suffix=str(item_id)[-16:],
                visible_child_rows=int(_rc_vis),
            )
        item_path = self._tree_item_path(node_data)
        if item_path and item_path in self._pending_snapshot_branch_refresh.get(panel_key, set()):
            self._snapshot_branch_refresh_baseline_by_worker[worker_key] = (
                self._capture_child_path_set_for_destination_model_index(col0)
            )
        preserved_children = self._preserve_destination_future_state_children_model(col0)
        if preserved_children:
            self._destination_preserved_children_by_worker[worker_key] = preserved_children
        if has_future_children and not _keep_snapshot_visible and not _graph_union:
            model.set_loading_children(col0)
        use_cache_only = False
        _t_req = time.perf_counter()
        try:
            if float(graph_request_perf_override or 0.0) > 0.0:
                _t_req = float(graph_request_perf_override)
        except Exception:
            pass
        worker_context = {
            "site_id": node_data.get("site_id", ""),
            "site_name": node_data.get("site_name", ""),
            "library_id": node_data.get("library_id", drive_id),
            "library_name": node_data.get("library_name", ""),
            "tree_role": panel_key,
            "parent_item_path": node_data.get("item_path", ""),
            "cache_only": use_cache_only,
            "_graph_request_perf": _t_req,
        }
        worker = FolderLoadWorker(self.graph, panel_key, drive_id, item_id, worker_context)
        pmi = QPersistentModelIndex(col0)
        worker_entry = self._register_folder_worker(
            worker_key,
            worker,
            None,
            pending_key=pending_key,
            destination_folder_parent_persistent=pmi,
            graph_child_union_bootstrap=bool(str(reason or "") == "destination_graph_child_union"),
            graph_union_mode=str(
                (graph_child_union_fingerprint or {}).get("mode")
                or ("folder_root" if graph_child_union_fingerprint else "")
            )[:32],
        )
        worker.success.connect(
            lambda payload, worker_id=worker_entry["id"]: self._safe_invoke(
                "folder_worker.success", self.on_folder_load_success, payload, worker_id
            )
        )
        worker.error.connect(
            lambda payload, worker_id=worker_entry["id"]: self._safe_invoke(
                "folder_worker.error", self.on_folder_load_error, payload, worker_id
            )
        )
        worker.finished.connect(
            lambda key=worker_key, worker_id=worker_entry["id"]: self._safe_invoke(
                "folder_worker.finished", self.on_folder_worker_finished, key, worker_id
            )
        )
        worker.start()
        qd = self._destination_graph_child_load_queue_diag()
        log_info(
            "destination_graph_child_load_dispatch_started",
            trigger=str(trigger)[:80],
            reason=str(reason)[:120],
            path_excerpt=path_excerpt,
            item_id_suffix=str(item_id)[-16:],
            active_pending_count=int(qd["active_pending_count"]),
            queued_count=int(qd["queued_count"]),
            queued_hi=int(qd.get("queued_hi", 0)),
            queued_lo=int(qd.get("queued_lo", 0)),
        )
        log_info(
            "graph_child_load_queue_depth",
            active_pending_count=int(qd["active_pending_count"]),
            backlog_total=int(qd["queued_count"]),
            backlog_hi=int(qd.get("queued_hi", 0)),
            backlog_lo=int(qd.get("queued_lo", 0)),
            phase="dispatch_started",
            path_excerpt=path_excerpt[:400],
        )
        self._destination_graph_child_load_log_queue_state(
            trigger=trigger,
            reason=reason,
            path_excerpt=path_excerpt,
            item_id_suffix=str(item_id),
            trace_note="after_dispatch",
        )
        if reason:
            self._log_restore_phase(
                "sharepoint_overlay_queued_graph_folder_load",
                reason=reason,
                worker_key=worker_key,
            )
        return True

    def _destination_drain_graph_child_load_backlog(self) -> None:
        """Start backlog loads until the active cap is reached or the queue is empty."""
        panel_key = "destination"
        while (
            len(self.pending_folder_loads.get(panel_key, set()) or ())
            < _graph_destination_child_load_max_active()
            and self._destination_graph_child_backlog_total() > 0
        ):
            entry = self._destination_pop_graph_child_backlog_entry()
            if entry is None:
                break
            self._destination_graph_child_load_backlog_keys.discard(entry.pending_key)
            qd = self._destination_graph_child_load_queue_diag()
            _dq_wait_ms = 0
            try:
                if float(entry.enqueued_perf or 0.0) > 0.0:
                    _dq_wait_ms = int(max(0.0, (time.perf_counter() - float(entry.enqueued_perf)) * 1000.0))
            except Exception:
                _dq_wait_ms = 0
            log_info(
                "destination_graph_child_load_dequeued",
                trigger=str(entry.trigger)[:80],
                reason=str(entry.reason)[:120],
                path_excerpt=str(entry.path_excerpt)[:400],
                item_id_suffix=str(entry.item_id)[-16:],
                active_pending_count=int(qd["active_pending_count"]),
                queued_count=int(qd["queued_count"]),
                queued_hi=int(qd.get("queued_hi", 0)),
                queued_lo=int(qd.get("queued_lo", 0)),
                backlog_wait_ms=int(_dq_wait_ms),
            )
            log_info(
                "graph_child_load_wait_ms",
                phase="backlog_to_dispatch",
                backlog_wait_ms=int(_dq_wait_ms),
                trigger=str(entry.trigger)[:80],
                reason=str(entry.reason)[:120],
                path_excerpt=str(entry.path_excerpt)[:400],
                graph_item_id_suffix=str(entry.item_id)[-16:],
            )
            self._destination_graph_child_load_log_queue_state(
                trigger=entry.trigger,
                reason=entry.reason,
                path_excerpt=entry.path_excerpt,
                item_id_suffix=str(entry.item_id),
                trace_note="after_dequeue",
            )
            model = getattr(self, "destination_planning_model", None)
            if model is None:
                continue
            try:
                ix = model.find_index_by_drive_item(entry.drive_id, entry.item_id)
            except RuntimeError:
                continue
            if not ix.isValid():
                continue
            col0 = ix.siblingAtColumn(0) if ix.column() != 0 else ix
            if not col0.isValid():
                continue
            self._destination_start_graph_folder_load_worker_if_eligible(
                col0,
                reason=entry.reason,
                trigger=entry.trigger,
                graph_request_perf_override=float(entry.enqueued_perf or 0.0),
                graph_child_union_fingerprint=getattr(entry, "graph_child_union_fingerprint", None),
            )

    def _request_graph_destination_children_load(
        self,
        index: QModelIndex,
        *,
        reason: str = "",
        trigger: str = "",
        graph_child_union_fingerprint: Optional[dict] = None,
    ) -> bool:
        """Queue a Graph :class:`FolderLoadWorker` for a destination folder (SharePoint authority mode).

        When the active worker cap is reached, the request is **tiered-FIFO backlogged** (deduped by
        ``drive_id:item_id``): user expand / visible-gesture triggers use the high-priority queue ahead of
        overlay and prefetch traffic. Draining runs from :meth:`on_folder_worker_finished` and after
        prefetch bursts.
        """
        if not index.isValid():
            return False
        if not destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            return False
        panel_key = "destination"
        col0 = index.siblingAtColumn(0) if index.column() != 0 else index
        if not col0.isValid():
            return False
        _dm = getattr(self, "destination_planning_model", None)
        if _dm is not None and hasattr(_dm, "reconcile_folder_children_loaded_if_empty_subtree"):
            try:
                _dm.reconcile_folder_children_loaded_if_empty_subtree(
                    col0, reason="graph_child_request_preflight"
                )
            except Exception:
                pass
        node_data = dict(col0.data(Qt.UserRole) or {})
        if node_data.get("placeholder"):
            return False
        _live_row = self._destination_row_is_live_graph_structure(node_data)
        _derived_ok = self._destination_row_is_graph_derived_dest_child_fetch_eligible(node_data)
        if not _live_row and not _derived_ok:
            return False
        _needs_live_rq = self._destination_row_needs_live_graph_child_refresh(node_data)
        _graph_queue_union = self._destination_graph_child_union_skip_refresh_gate(
            str(reason or ""), node_data, graph_child_union_fingerprint
        )
        if (node_data.get("children_loaded") or node_data.get("load_failed")) and not _needs_live_rq and not _graph_queue_union:
            return False
        drive_id = self._resolve_tree_item_drive_id(panel_key, node_data)
        item_id = str(node_data.get("id") or "").strip()
        if not drive_id or not item_id:
            return False
        pending_key = f"{drive_id}:{item_id}"
        worker_key = f"{panel_key}:{item_id}"
        if self._folder_load_worker_thread_running(worker_key):
            self.pending_folder_loads[panel_key].add(pending_key)
            return False
        if pending_key in self.pending_folder_loads[panel_key]:
            return False
        pending_count = len(self.pending_folder_loads.get(panel_key, set()))
        path_excerpt = str(
            self._destination_row_raw_path_for_path_lookup_match(node_data)
            or node_data.get("item_path")
            or node_data.get("destination_path")
            or ""
        )[:400]
        if pending_count >= _graph_destination_child_load_max_active():
            if pending_key in self._destination_graph_child_load_backlog_keys:
                qd = self._destination_graph_child_load_queue_diag()
                log_info(
                    "destination_graph_child_load_dedup_skipped",
                    trigger=str(trigger)[:80],
                    reason=str(reason)[:120],
                    path_excerpt=path_excerpt,
                    item_id_suffix=str(item_id)[-16:],
                    active_pending_count=int(qd["active_pending_count"]),
                    queued_count=int(qd["queued_count"]),
                    pending_key_suffix=str(pending_key)[-48:],
                )
                self._destination_graph_child_load_log_queue_state(
                    trigger=trigger,
                    reason=reason,
                    path_excerpt=path_excerpt,
                    item_id_suffix=str(item_id),
                    trace_note="dedup_backlog",
                )
                return False
            _enq_perf = time.perf_counter()
            _entry = _GraphDestinationChildBacklogEntry(
                pending_key=pending_key,
                drive_id=drive_id,
                item_id=item_id,
                trigger=str(trigger)[:200],
                reason=str(reason)[:200],
                path_excerpt=path_excerpt,
                enqueued_perf=_enq_perf,
                graph_child_union_fingerprint=graph_child_union_fingerprint,
            )
            _hi = _graph_destination_child_load_request_is_high_priority(trigger, reason)
            if not _hi:
                try:
                    _tw_b = getattr(self, "destination_tree_widget", None)
                    if _tw_b is not None and _tw_b.isExpanded(col0):
                        _hi = True
                except Exception:
                    pass
            if _hi:
                self._destination_graph_child_load_backlog_hi.append(_entry)
            else:
                self._destination_graph_child_load_backlog_lo.append(_entry)
            self._destination_graph_child_load_backlog_keys.add(pending_key)
            qd = self._destination_graph_child_load_queue_diag()
            log_info(
                "destination_graph_child_load_enqueued",
                trigger=str(trigger)[:80],
                reason=str(reason)[:120],
                path_excerpt=path_excerpt,
                item_id_suffix=str(item_id)[-16:],
                active_pending_count=int(qd["active_pending_count"]),
                queued_count=int(qd["queued_count"]),
                queued_hi=int(qd.get("queued_hi", 0)),
                queued_lo=int(qd.get("queued_lo", 0)),
                priority_hi=bool(_hi),
            )
            log_info(
                "graph_child_load_queued",
                trigger=str(trigger)[:80],
                reason=str(reason)[:120],
                path_excerpt=path_excerpt[:400],
                graph_item_id_suffix=str(item_id)[-16:],
                priority_hi=bool(_hi),
                active_pending_count=int(qd["active_pending_count"]),
                backlog_total=int(qd["queued_count"]),
                backlog_hi=int(qd.get("queued_hi", 0)),
                backlog_lo=int(qd.get("queued_lo", 0)),
            )
            log_info(
                "graph_child_load_queue_depth",
                phase="after_enqueue",
                active_pending_count=int(qd["active_pending_count"]),
                backlog_total=int(qd["queued_count"]),
                backlog_hi=int(qd.get("queued_hi", 0)),
                backlog_lo=int(qd.get("queued_lo", 0)),
            )
            self._destination_graph_child_load_log_queue_state(
                trigger=trigger,
                reason=reason,
                path_excerpt=path_excerpt,
                item_id_suffix=str(item_id),
                trace_note="after_enqueue",
            )
            return True
        return self._destination_start_graph_folder_load_worker_if_eligible(
            col0,
            reason=reason,
            trigger=trigger,
            graph_child_union_fingerprint=graph_child_union_fingerprint,
        )

    def _destination_graph_subtree_hydration_root_key(self, path: str) -> str:
        p = self.normalize_memory_path(str(path or "").strip())
        p = self._canonical_destination_projection_path(p) or p
        return str(p or "").strip().casefold()

    def _destination_prune_subtree_hydration_roots_for_collapsed_path(self, collapsed_path: str) -> None:
        ck = self._destination_graph_subtree_hydration_root_key(collapsed_path)
        if not ck:
            return
        sep = "\\"
        victims = {r for r in self._destination_graph_subtree_hydration_roots if r == ck or r.startswith(ck + sep)}
        if not victims:
            return
        for v in victims:
            self._destination_graph_subtree_hydration_roots.discard(v)
            self._destination_graph_subtree_hydration_meta.pop(v, None)
        log_info(
            "graph_subtree_hydration_roots_pruned",
            collapsed_path_excerpt=str(collapsed_path)[:400],
            removed=int(len(victims)),
        )

    def _destination_semantic_path_is_under_any_subtree_hydration_root(self, semantic_path: str) -> bool:
        sp = self._destination_graph_subtree_hydration_root_key(semantic_path)
        if not sp:
            return False
        sep = "\\"
        for root in self._destination_graph_subtree_hydration_roots:
            if sp == root or sp.startswith(root + sep):
                return True
        return False

    def _destination_collect_visible_subtree_graph_folder_targets(
        self, root_ix: QModelIndex
    ) -> list[QModelIndex]:
        model = getattr(self, "destination_planning_model", None)
        tw = getattr(self, "destination_tree_widget", None)
        if model is None or tw is None or not root_ix.isValid():
            return []
        root0 = root_ix.siblingAtColumn(0) if root_ix.column() != 0 else root_ix
        out: list[QModelIndex] = []
        seen_pk: set[str] = set()
        stack: list[QModelIndex] = [root0]
        visited = 0
        while stack and visited < _GRAPH_SUBTREE_HYDRATION_WALK_NODE_CAP:
            visited += 1
            cur = stack.pop()
            if not cur.isValid():
                continue
            try:
                pl = dict(cur.data(Qt.UserRole) or {})
            except RuntimeError:
                continue
            if (
                (not pl.get("placeholder"))
                and self._destination_row_is_live_graph_structure(pl)
                and bool(pl.get("is_folder", True))
                and (not pl.get("children_loaded"))
                and (not pl.get("load_failed"))
            ):
                drive_id = self._resolve_tree_item_drive_id("destination", pl)
                iid = str(pl.get("id") or "").strip()
                if drive_id and iid:
                    pk = f"{drive_id}:{iid}"
                    if pk not in seen_pk:
                        seen_pk.add(pk)
                        out.append(cur)
            try:
                expanded = bool(tw.isExpanded(cur))
            except Exception:
                expanded = False
            if not expanded:
                continue
            try:
                rc = int(model.rowCount(cur))
            except RuntimeError:
                continue
            for r in range(rc):
                try:
                    cix = model.index(r, 0, cur)
                except RuntimeError:
                    continue
                if cix.isValid():
                    stack.append(cix)
        if visited >= _GRAPH_SUBTREE_HYDRATION_WALK_NODE_CAP:
            log_info(
                "graph_subtree_hydration_walk_capped",
                cap=int(_GRAPH_SUBTREE_HYDRATION_WALK_NODE_CAP),
                root_excerpt=str((root0.data(Qt.UserRole) or {}).get("item_path") or "")[:200],
            )
        return out

    def _schedule_graph_subtree_hydration(
        self, root_path: str, *, preferred_root_index: QModelIndex | None = None
    ) -> None:
        """Primary entry: schedule Graph /children for every live folder in the expanded visible subtree."""
        root_path = str(root_path or "").strip()
        if not root_path:
            return
        if not destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            return
        model = getattr(self, "destination_planning_model", None)
        if model is None:
            return
        if not getattr(self, "graph", None) or not getattr(self.graph, "token", None):
            return
        root_key = self._destination_graph_subtree_hydration_root_key(root_path)
        if not root_key:
            return
        self._destination_graph_subtree_hydration_roots.add(root_key)
        t0 = time.perf_counter()
        canon = self._canonical_destination_projection_path(root_path) or self.normalize_memory_path(root_path)
        canon = str(canon or "").strip()
        root_ix = QModelIndex()
        idxs = model.find_indices_for_canonical_destination_path(canon) if canon else []
        if idxs:
            ix0 = idxs[0]
            root_ix = ix0.siblingAtColumn(0) if ix0.column() != 0 else ix0
        if not root_ix.isValid() and preferred_root_index is not None:
            p0 = (
                preferred_root_index.siblingAtColumn(0)
                if preferred_root_index.column() != 0
                else preferred_root_index
            )
            if p0.isValid():
                try:
                    nd = dict(p0.data(Qt.UserRole) or {})
                    sp = self._destination_semantic_path(nd) or self._tree_item_path(nd) or ""
                    sp_canon = str(
                        self._canonical_destination_projection_path(sp) or self.normalize_memory_path(sp) or ""
                    ).strip()
                    if canon and sp_canon and sp_canon.casefold() == canon.casefold():
                        root_ix = p0
                except Exception:
                    pass
        if not root_ix.isValid():
            log_info(
                "graph_subtree_hydration_start",
                root_path_excerpt=root_path[:400],
                ok=False,
                reason="root_index_not_found",
            )
            self._destination_graph_subtree_hydration_roots.discard(root_key)
            return
        targets = self._destination_collect_visible_subtree_graph_folder_targets(root_ix)
        log_info(
            "graph_subtree_hydration_start",
            root_path_excerpt=root_path[:400],
            root_key_suffix=root_key[-120:],
            target_folder_count=int(len(targets)),
            ok=True,
        )
        honored = 0
        for ix in targets:
            col0 = ix.siblingAtColumn(0) if ix.column() != 0 else ix
            try:
                if self._request_graph_destination_children_load(
                    col0, reason="subtree_hydration", trigger="subtree_hydrate_batch"
                ):
                    honored += 1
            except Exception:
                pass
        self._destination_drain_graph_child_load_backlog()
        dt_ms = int(max(0.0, (time.perf_counter() - t0) * 1000.0))
        meta = self._destination_graph_subtree_hydration_meta.setdefault(root_key, {})
        meta["last_scheduled_perf"] = float(t0)
        meta["last_target_folder_count"] = int(len(targets))
        meta["last_honored_request_count"] = int(honored)
        qd = self._destination_graph_child_load_queue_diag()
        log_info(
            "graph_subtree_hydration_progress",
            root_path_excerpt=root_path[:400],
            loaded=-1,
            expected=int(len(targets)),
            honored_request_count=int(honored),
            backlog_hi=int(qd.get("queued_hi", 0)),
            backlog_lo=int(qd.get("queued_lo", 0)),
            active_pending_count=int(qd.get("active_pending_count", 0)),
        )
        log_info(
            "graph_subtree_hydration_complete",
            root_path_excerpt=root_path[:400],
            phase="batch_issue_complete",
            scheduled_folder_count=int(len(targets)),
        )
        log_info(
            "graph_subtree_total_time_ms",
            root_path_excerpt=root_path[:400],
            scheduler_sync_ms=int(dt_ms),
        )

    def _destination_graph_subtree_schedule_new_folders_after_bind(self, parent_index: QModelIndex) -> None:
        """Progressive: schedule HIGH-priority loads for new visible Graph folders under an active subtree root."""
        if not destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            return
        if not parent_index.isValid():
            return
        try:
            nd = dict(parent_index.data(Qt.UserRole) or {})
        except RuntimeError:
            return
        sp = self._destination_semantic_path(nd) or self._tree_item_path(nd) or ""
        if not self._destination_semantic_path_is_under_any_subtree_hydration_root(sp):
            return
        model = getattr(self, "destination_planning_model", None)
        tw = getattr(self, "destination_tree_widget", None)
        if model is None or tw is None:
            return
        p0 = parent_index.siblingAtColumn(0) if parent_index.column() != 0 else parent_index
        try:
            if not tw.isExpanded(p0):
                return
        except Exception:
            return
        try:
            rc = int(model.rowCount(p0))
        except RuntimeError:
            return
        n = 0
        for r in range(min(rc, 4096)):
            try:
                cix = model.index(r, 0, p0)
            except RuntimeError:
                continue
            if not cix.isValid():
                continue
            try:
                pl = dict(cix.data(Qt.UserRole) or {})
            except RuntimeError:
                continue
            if pl.get("placeholder"):
                continue
            if not self._destination_row_is_live_graph_structure(pl):
                continue
            if not pl.get("is_folder", True):
                continue
            if pl.get("children_loaded") or pl.get("load_failed"):
                continue
            try:
                if self._request_graph_destination_children_load(
                    cix,
                    reason="subtree_hydration_progressive",
                    trigger="post_bind_visible_subtree",
                ):
                    n += 1
            except Exception:
                pass
        if n:
            log_info(
                "graph_subtree_hydration_progressive_batch",
                parent_path_excerpt=str(nd.get("item_path") or "")[:400],
                queued_child_folders=int(n),
            )
        self._destination_drain_graph_child_load_backlog()

    def _destination_log_and_request_graph_children_load(
        self, col0: QModelIndex, *, trigger: str, reason: str
    ) -> bool:
        """Log ``destination_graph_child_load_triggered_for_visible_folder`` and queue Graph children load."""
        if not col0.isValid():
            return False
        c = col0.siblingAtColumn(0) if col0.column() != 0 else col0
        if not c.isValid():
            return False
        pl = self._destination_model_index_user_role_dict(c)
        path_excerpt = str(
            self._destination_row_raw_path_for_path_lookup_match(pl)
            or pl.get("item_path")
            or pl.get("destination_path")
            or ""
        )[:400]
        log_info(
            "destination_graph_child_load_triggered_for_visible_folder",
            trigger=str(trigger)[:80],
            reason=str(reason)[:120],
            path_excerpt=path_excerpt,
            item_id_suffix=str(pl.get("id") or "")[-16:],
        )
        return self._request_graph_destination_children_load(c, reason=reason, trigger=trigger)

    def _destination_immediate_graph_child_loads_for_all_visible_folders(self) -> None:
        """For every visible destination folder row, queue Graph child load (opt-in via env only).

        **Safe pattern:** read-only tree walk collects ``(drive_id, item_id)`` and planned paths; then
        re-resolve each row with :meth:`DestinationPlanningTreeModel.find_index_by_drive_item` before
        calling ``set_loading_children``. Holding ``QModelIndex`` from ``iter_depth_first()`` across a
        load invalidates internal pointers → access violation (2026-04-13 crash logs).
        """
        if not destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            return
        if not getattr(self, "graph", None) or not getattr(self.graph, "token", None):
            return
        model = getattr(self, "destination_planning_model", None)
        if model is None:
            return

        live_pairs: list[tuple[str, str]] = []
        live_keys: set[str] = set()
        planned_paths: list[str] = []
        planned_cf: set[str] = set()
        nudge_pairs: list[tuple[str, str]] = []
        nudge_keys: set[str] = set()

        def _add_live(did: str, iid: str, bucket: list[tuple[str, str]], keys: set[str]) -> None:
            d = str(did or "").strip()
            i = str(iid or "").strip()
            if not d or not i:
                return
            k = f"{d}:{i}"
            if k in keys:
                return
            keys.add(k)
            bucket.append((d, i))

        def walk(par: QModelIndex) -> None:
            try:
                rc = model.rowCount(par)
            except RuntimeError:
                return
            for r in range(rc):
                try:
                    ix = model.index(r, 0, par)
                except RuntimeError:
                    continue
                if not ix.isValid():
                    continue
                try:
                    pl = self._destination_model_index_user_role_dict(ix)
                except RuntimeError:
                    continue
                if not isinstance(pl, dict):
                    try:
                        walk(ix)
                    except RuntimeError:
                        pass
                    continue
                if pl.get("placeholder"):
                    try:
                        walk(ix)
                    except RuntimeError:
                        pass
                    continue

                if self._destination_row_is_live_graph_structure(pl) and bool(pl.get("is_folder", True)):
                    if not pl.get("children_loaded") and not pl.get("load_failed"):
                        _add_live(
                            str(pl.get("drive_id") or pl.get("library_id") or ""),
                            str(pl.get("id") or ""),
                            live_pairs,
                            live_keys,
                        )
                elif destination_payload_is_planned_workspace_row(pl) and bool(pl.get("is_folder", True)):
                    raw_path = (
                        self._destination_row_raw_path_for_path_lookup_match(pl)
                        or str(pl.get("item_path") or pl.get("destination_path") or "").strip()
                    )
                    pcanon = (
                        self._canonical_destination_projection_path(raw_path)
                        or self.normalize_memory_path(raw_path)
                        or ""
                    ).strip()
                    if pcanon:
                        cf = pcanon.casefold()
                        if cf not in planned_cf:
                            planned_cf.add(cf)
                            planned_paths.append(pcanon)
                    try:
                        pw = ix.parent()
                    except RuntimeError:
                        pw = QModelIndex()
                    while pw.isValid():
                        try:
                            ppar = self._destination_model_index_user_role_dict(pw)
                        except RuntimeError:
                            break
                        if (
                            self._destination_row_is_live_graph_structure(ppar)
                            and bool(ppar.get("is_folder", True))
                            and not ppar.get("children_loaded")
                            and not ppar.get("load_failed")
                        ):
                            _add_live(
                                str(ppar.get("drive_id") or ppar.get("library_id") or ""),
                                str(ppar.get("id") or ""),
                                nudge_pairs,
                                nudge_keys,
                            )
                            break
                        try:
                            pw = pw.parent()
                        except RuntimeError:
                            break

                try:
                    walk(ix)
                except RuntimeError:
                    pass

        try:
            walk(QModelIndex())
        except RuntimeError:
            return

        for pcanon in planned_paths:
            try:
                self._destination_request_graph_destination_children_load_for_path(
                    pcanon, reason="visible_planned_folder_immediate"
                )
            except Exception:
                pass

        ordered_live: list[tuple[str, str]] = list(nudge_pairs)
        nk = {f"{a}:{b}" for a, b in nudge_pairs}
        for d, i in live_pairs:
            k = f"{d}:{i}"
            if k not in nk:
                ordered_live.append((d, i))

        for did, iid in ordered_live:
            try:
                ix2 = model.find_index_by_drive_item(did, iid)
            except RuntimeError:
                continue
            if not ix2.isValid():
                continue
            try:
                pl2 = self._destination_model_index_user_role_dict(ix2)
            except RuntimeError:
                continue
            if not isinstance(pl2, dict):
                continue
            if not self._destination_row_is_live_graph_structure(pl2) or not bool(pl2.get("is_folder", True)):
                continue
            if pl2.get("children_loaded") or pl2.get("load_failed"):
                continue
            trig = "visible_planned_nearest_live_ancestor" if f"{did}:{iid}" in nudge_keys else "visible_live_folder_scan"
            self._destination_log_and_request_graph_children_load(
                ix2,
                trigger=trig,
                reason="visible_folder_immediate_structure_change",
            )

    def _destination_request_graph_destination_children_load_for_path(
        self, parent_canonical_path: str, *, reason: str = ""
    ) -> bool:
        """Walk library-relative segments; queue Graph FolderLoadWorker on deepest live parent missing a child.

        Does not create synthetic/planned structural rows — only triggers real Graph loads so missing
        folders can appear in the model.
        """
        if not destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            return False
        from ozlink_console.destination_path_bridge import (
            canonical_planning_path_from_library_relative_segments,
            library_relative_segments_from_planning_path,
            remap_under_visible_library_anchor,
            strip_legacy_internal_root_prefix,
        )

        model = getattr(self, "destination_planning_model", None)
        if model is None:
            return False
        walk_base = str(parent_canonical_path or "").strip()
        if not walk_base:
            return False
        anchor = self._destination_visible_library_anchor_canonical_path()
        if anchor:
            ra = remap_under_visible_library_anchor(
                strip_legacy_internal_root_prefix(walk_base),
                strip_legacy_internal_root_prefix(anchor),
            )
            walk_base = (
                self._canonical_destination_projection_path(ra) or self.normalize_memory_path(ra) or walk_base
            )
        lib_segs = library_relative_segments_from_planning_path(walk_base)
        if not lib_segs:
            return False
        parent_ix = QModelIndex()
        graph_strict = True
        rsn = str(reason or "planned_reconcile_parent_path")[:120]
        for depth in range(len(lib_segs)):
            current_path = canonical_planning_path_from_library_relative_segments(lib_segs[: depth + 1])
            if not current_path:
                continue
            child_ix = self._find_destination_child_by_path(
                parent_ix, current_path, overlay_path_strict=graph_strict
            )
            if child_ix is None:
                child_ix = self._find_visible_destination_item_by_path(current_path)
            if child_ix is None or not child_ix.isValid():
                if parent_ix.isValid():
                    ppl = self._destination_model_index_user_role_dict(parent_ix)
                    if (
                        self._destination_row_is_live_graph_structure(ppl)
                        and not ppl.get("children_loaded")
                        and not ppl.get("load_failed")
                    ):
                        ok = self._destination_log_and_request_graph_children_load(
                            parent_ix, trigger="path_walk_missing_child", reason=rsn
                        )
                        log_info(
                            "destination_graph_load_scheduled_for_planned_reconcile_parent_chain",
                            target_path=str(walk_base)[:400],
                            missing_child_path=str(current_path)[:400],
                            depth=int(depth),
                            load_scheduled=bool(ok),
                            reason=rsn,
                        )
                        return bool(ok)
                root = QModelIndex()
                if not parent_ix.isValid():
                    for tr in range(model.rowCount(root)):
                        top_ix = model.index(tr, 0, root)
                        if not top_ix.isValid():
                            continue
                        tpl = self._destination_model_index_user_role_dict(top_ix)
                        if not self._destination_row_is_live_graph_structure(tpl):
                            continue
                        if tpl.get("children_loaded") or tpl.get("load_failed"):
                            continue
                        ok = self._destination_log_and_request_graph_children_load(
                            top_ix, trigger="path_walk_top_level_hub_fallback", reason=rsn
                        )
                        if ok:
                            log_info(
                                "destination_graph_load_scheduled_for_planned_reconcile_parent_chain",
                                target_path=str(walk_base)[:400],
                                missing_child_path=str(current_path)[:400],
                                depth=int(depth),
                                load_scheduled=True,
                                reason=rsn,
                                top_level_hub_fallback=True,
                            )
                            return True
                log_info(
                    "destination_graph_load_for_path_skipped",
                    target_path=str(walk_base)[:400],
                    missing_child_path=str(current_path)[:400],
                    depth=int(depth),
                    reason=rsn,
                )
                return False
            pl = self._destination_model_index_user_role_dict(child_ix)
            if not self._destination_row_allows_sharepoint_projection_traversal(pl):
                return False
            parent_ix = child_ix
        # Full path already visible: load Graph children for the resolved leaf folder (inherited allocations).
        if parent_ix.isValid():
            leaf_pl = self._destination_model_index_user_role_dict(parent_ix)
            if (
                self._destination_row_is_live_graph_structure(leaf_pl)
                and bool(leaf_pl.get("is_folder", True))
                and not leaf_pl.get("children_loaded")
                and not leaf_pl.get("load_failed")
            ):
                return self._destination_log_and_request_graph_children_load(
                    parent_ix, trigger="path_walk_resolved_leaf", reason=rsn
                )
        return False

    def _destination_allocation_folder_shows_materialized_children_index(self, index: QModelIndex) -> bool:
        """True when the row has any non-placeholder child (e.g. explicit file allocations).

        Do not use this alone to decide whether descendant projection has run; use
        ``allocation_descendants_applied`` on the allocation folder payload.
        """
        model = getattr(self, "destination_planning_model", None)
        if model is None or not index.isValid():
            return False
        if model.rowCount(index) == 0:
            return False
        for r in range(model.rowCount(index)):
            ix = model.index(r, 0, index)
            d = ix.data(Qt.UserRole) or {}
            if not d.get("placeholder"):
                return True
            role = str(d.get("placeholder_role") or "").strip()
            if role in ("projection_pending", "lazy_unloaded", "loading_in_progress"):
                return False
        return False

    def _mark_allocation_descendants_applied_on_allocation_folder_model_index(self, parent_ix: QModelIndex, move) -> None:
        """Record that projected descendants were merged for this planned-allocation folder row.

        Distinct from `_destination_allocation_folder_shows_materialized_children_index`, which only
        detects non-placeholder children (explicit moves can satisfy that without a full descendant pass).
        """
        model = getattr(self, "destination_planning_model", None)
        if model is None or not parent_ix.isValid():
            return
        col0 = parent_ix.siblingAtColumn(0) if parent_ix.column() != 0 else parent_ix
        if not col0.isValid():
            return

        def _mut(p):
            p["allocation_descendants_applied"] = True
            p["children_loaded"] = True
            p["projection_unresolved_terminal"] = False
            p.pop("allocation_projection_resume_source_token", None)
            p.pop("allocation_projection_resume_desc_index", None)
            p.pop("allocation_projection_resume_descendants_total", None)

        model.update_payload_for_index(col0, _mut)

    def _mark_allocation_descendants_applied_on_allocation_folder_widget(self, parent_item, move) -> None:
        if parent_item is None:
            return
        nd = dict(parent_item.data(0, Qt.UserRole) or {})
        nd["allocation_descendants_applied"] = True
        nd["children_loaded"] = True
        nd["projection_unresolved_terminal"] = False
        nd.pop("allocation_projection_resume_source_token", None)
        nd.pop("allocation_projection_resume_desc_index", None)
        nd.pop("allocation_projection_resume_descendants_total", None)
        parent_item.setData(0, Qt.UserRole, nd)

    def _source_payload_from_graph_item(self, item):
        prefix = "Folder" if item.get("is_folder") else "File"
        base_label = self._tree_name_column_label(item.get("name", "Unnamed Item"))
        node_data = dict(item)
        node_data.setdefault("children_loaded", False)
        node_data.setdefault("load_failed", False)
        node_data.setdefault("tree_label", prefix)
        node_data.setdefault("base_display_label", base_label)
        node_data.setdefault("tree_role", "source")
        return node_data

    def _apply_root_payload_to_source_model_view(self, panel_key, items):
        self._log_root_success_step("step_01_resolve_tree_enter", panel_key=panel_key)
        tree, status = self._get_tree_and_status(panel_key)
        model = getattr(self, "source_sharepoint_model", None)
        self._log_root_success_step("step_01_resolve_tree_exit", panel_key=panel_key, tree_info=self._root_tree_identity(tree))
        if tree is None or status is None or model is None:
            self._log_root_success_step("step_02_validate_tree_exit", panel_key=panel_key, valid=False)
            return
        self._root_tree_bind_in_progress = True
        tree.blockSignals(True)
        tree.setUpdatesEnabled(False)
        try:
            tree.setEnabled(True)
            pre_fc = self._source_forensic_model_node_counts()
            try:
                pre_df = int(pre_fc.get("model_nodes_depth_first") or 0)
            except Exception:
                pre_df = 0
            pending_drive = str((getattr(self, "pending_root_drive_ids", None) or {}).get("source") or "").strip()
            force_replace = bool(getattr(self, "_source_sharepoint_root_force_replace", False))
            self._source_sharepoint_root_force_replace = False
            snap_preserving = (
                self._planning_browse_mode("source") == "sharepoint"
                and (
                    bool(getattr(self, "_source_startup_snapshot_mount_seen", False))
                    or bool(getattr(self, "_source_snapshot_shell_prearmed", False))
                    or self._pending_session_source_snapshot_drive_match(pending_drive)
                )
            )
            mount_did = str(getattr(self, "_source_snapshot_mount_drive_id", "") or "").strip()
            single_row_snapshot_shell = (
                snap_preserving
                and pre_df == 1
                and bool(pending_drive)
                and (
                    (bool(mount_did) and mount_did.casefold() == pending_drive.casefold())
                    or self._pending_session_source_snapshot_drive_match(pending_drive)
                )
            )
            shell_merge_eligible = (
                self._planning_browse_mode("source") == "sharepoint"
                and not force_replace
                and (
                    snap_preserving
                    or pre_df > 1
                    or single_row_snapshot_shell
                    or (
                        bool(getattr(self, "_source_snapshot_shell_prearmed", False))
                        and pre_df >= 1
                        and self._pending_session_source_snapshot_drive_match(pending_drive)
                    )
                )
            )
            if not items:
                if shell_merge_eligible:
                    log_info(
                        "source_sharepoint_shell_preserved_on_empty_graph_root",
                        **pre_fc,
                    )
                    self._set_tree_status_message(
                        panel_key,
                        "No root items returned from Graph (saved tree structure kept).",
                        loading=False,
                    )
                    return
                if snap_preserving:
                    log_info(
                        "source_sharepoint_shell_before_empty_graph_clear",
                        **pre_fc,
                    )
                self._source_startup_snapshot_mount_seen = False
                log_info(
                    "source_root_replace_destructive",
                    reason="empty_graph_root_non_merge",
                    pre_nodes_depth_first=pre_df,
                    force_replace=bool(force_replace),
                )
                model.clear()
                self._set_tree_status_message(panel_key, "This library is empty.", loading=False)
                model.set_empty_library_message("This library is empty.")
                tree.setEnabled(False)
                return
            sorted_items = sorted(items, key=lambda value: (not value.get("is_folder", False), value.get("name", "").lower()))
            payloads = []
            for it in sorted_items:
                pl = self._source_payload_from_graph_item(it)
                self._apply_tree_item_visual_state(None, pl)
                payloads.append(pl)
            if shell_merge_eligible and hasattr(model, "merge_sharepoint_source_root_graph_children"):
                log_info(
                    "source_destructive_reset_blocked",
                    reason="graph_root_merge_instead_of_replace",
                    pre_nodes_depth_first=pre_df,
                    graph_root_items=len(payloads),
                )
                log_info(
                    "source_startup_shell_before_graph_root_merge",
                    graph_root_items=len(payloads),
                    **pre_fc,
                )
                try:
                    stats = model.merge_sharepoint_source_root_graph_children(
                        payloads,
                        enrich_only=False,
                        default_drive_id=pending_drive,
                    )
                except Exception as exc:
                    log_info(
                        "source_startup_shell_graph_root_merge_failed",
                        error=str(exc)[:220],
                        fallback="preserve_shell_skip_destructive_reset",
                    )
                    self._set_tree_status_message(
                        panel_key,
                        "Could not merge live root into saved tree (structure kept).",
                        loading=False,
                    )
                    return
                post_fc = self._source_forensic_model_node_counts()
                log_info(
                    "source_startup_shell_graph_root_merge",
                    **stats,
                )
                log_info(
                    "source_startup_shell_after_graph_root_merge",
                    **post_fc,
                )
                self._set_tree_status_message(panel_key, f"{len(items)} root item(s) loaded.", loading=False)
                self._prewarm_source_path_lookup_cache_after_source_root_bind()
                return
            if pre_df > 0:
                log_info(
                    "source_model_clear_before_shallow_graph_bind",
                    pre_nodes_depth_first=pre_df,
                    graph_root_items=len(payloads),
                    force_replace=bool(force_replace),
                )
            log_info(
                "source_root_replace_destructive",
                reason="force_refresh" if force_replace else "non_shell_merge_bind",
                pre_nodes_depth_first=pre_df,
                graph_root_items=len(payloads),
            )
            model.clear()
            model.reset_root_payloads(payloads)
            self._set_tree_status_message(panel_key, f"{len(items)} root item(s) loaded.", loading=False)
            self._prewarm_source_path_lookup_cache_after_source_root_bind()
        finally:
            tree.setUpdatesEnabled(True)
            tree.blockSignals(False)
            self._root_tree_bind_in_progress = False

    def _capture_child_path_set_for_model_index(self, parent: QModelIndex):
        paths = set()
        model = getattr(self, "source_sharepoint_model", None)
        if model is None or not parent.isValid():
            return paths
        rows = model.rowCount(parent)
        for r in range(rows):
            ix = model.index(r, 0, parent)
            pl = ix.data(Qt.UserRole) or {}
            if pl.get("placeholder"):
                continue
            p = self._tree_item_path(pl)
            if p:
                paths.add(str(p))
        return paths

    def _on_source_sharepoint_model_collapsed(self, index):
        if not self._full_trace_enabled():
            return
        pl = index.data(Qt.UserRole) or {}
        if pl.get("placeholder"):
            self._ui_trace(
                "tree",
                "collapse_skipped_placeholder",
                panel_key="source",
                item=None,
            )
        else:
            self._ui_trace("tree", "collapsed", panel_key="source", item=None)

    def _source_model_request_folder_children_load(self, index, *, triggered_by_user_expand: bool) -> str:
        """Start a Graph folder load for a source model row if needed.

        Returns route name for tracing: ``noop``, ``throttled``, or ``started``.
        """
        panel_key = "source"
        node_data = index.data(Qt.UserRole) or {}
        base_label = str(node_data.get("base_display_label", "") or "").strip().lower()
        tree_label = str(node_data.get("tree_label", "") or "").strip().lower()
        text_label = str(node_data.get("base_display_label", "") or "").strip().lower()
        is_folder_like = bool(
            node_data.get("is_folder")
            or tree_label == "folder"
            or base_label.startswith("folder:")
            or text_label.startswith("folder:")
        )
        if node_data.get("placeholder") or not is_folder_like:
            return "noop"
        if node_data.get("children_loaded") or node_data.get("load_failed"):
            return "noop"

        drive_id = self._resolve_tree_item_drive_id(panel_key, node_data)
        item_id = node_data.get("id", "")
        if not drive_id or not item_id:
            return "noop"

        pending_key = f"{drive_id}:{item_id}"
        worker_key = f"{panel_key}:{item_id}"
        if self._folder_load_worker_thread_running(worker_key):
            self.pending_folder_loads[panel_key].add(pending_key)
            return "noop"
        if pending_key in self.pending_folder_loads[panel_key]:
            return "noop"

        pending_count = len(self.pending_folder_loads.get(panel_key, set()))
        max_inflight_loads = 1 if triggered_by_user_expand else 3
        if pending_count >= max_inflight_loads:
            return "throttled"

        self.pending_folder_loads[panel_key].add(pending_key)
        item_path = self._tree_item_path(node_data)
        if item_path and item_path in self._pending_snapshot_branch_refresh.get(panel_key, set()):
            self._snapshot_branch_refresh_baseline_by_worker[worker_key] = self._capture_child_path_set_for_model_index(
                index
            )
        if self._full_trace_enabled():
            self._ui_trace(
                "tree",
                "folder_load_take_children",
                panel_key=panel_key,
                item=None,
                worker_key=worker_key,
                prior_child_count_hint="cleared",
            )
        self.source_sharepoint_model.set_loading_children(index)

        use_cache_only = False
        worker_context = {
            "site_id": node_data.get("site_id", ""),
            "site_name": node_data.get("site_name", ""),
            "library_id": node_data.get("library_id", drive_id),
            "library_name": node_data.get("library_name", ""),
            "tree_role": panel_key,
            "parent_item_path": node_data.get("item_path", ""),
            "cache_only": use_cache_only,
        }
        worker = FolderLoadWorker(self.graph, panel_key, drive_id, item_id, worker_context)
        pmi = QPersistentModelIndex(index)
        worker_entry = self._register_folder_worker(
            worker_key,
            worker,
            None,
            pending_key=pending_key,
            source_folder_parent_persistent=pmi,
        )
        worker.success.connect(
            lambda payload, worker_id=worker_entry["id"]: self._safe_invoke(
                "folder_worker.success", self.on_folder_load_success, payload, worker_id
            )
        )
        worker.error.connect(
            lambda payload, worker_id=worker_entry["id"]: self._safe_invoke(
                "folder_worker.error", self.on_folder_load_error, payload, worker_id
            )
        )
        worker.finished.connect(
            lambda key=worker_key, worker_id=worker_entry["id"]: self._safe_invoke(
                "folder_worker.finished", self.on_folder_worker_finished, key, worker_id
            )
        )
        if self._full_trace_enabled():
            self._ui_trace(
                "tree",
                "expand_route",
                panel_key=panel_key,
                item=None,
                route="start_graph_folder_load_worker",
                worker_key=worker_key,
                cache_only=use_cache_only,
            )
        worker.start()
        return "started"

    def _on_source_sharepoint_model_expanded(self, index):
        panel_key = "source"
        if self._full_trace_enabled():
            self._ui_trace("tree", "expand_signal", panel_key=panel_key, item=None)
        route = self._source_model_request_folder_children_load(index, triggered_by_user_expand=True)
        if self._full_trace_enabled():
            self._ui_trace("tree", "expand_route", panel_key=panel_key, item=None, route=route)

    def _apply_source_folder_load_model_tail(
        self,
        parent_index,
        items,
        previous_child_paths,
        panel_key,
        *,
        worker_id=None,
        expected_structure_generation=None,
        drive_id="",
        item_id="",
    ):
        model = self.source_sharepoint_model
        iid_s = str(item_id or "")
        log_ctx_base = {
            "worker_id": worker_id,
            "drive_id": drive_id,
            "item_id": item_id,
            "item_id_suffix": iid_s[-16:] if len(iid_s) > 16 else iid_s,
            "parent_path_excerpt": "",
        }
        nd0 = parent_index.data(Qt.UserRole) or {} if isinstance(parent_index, QModelIndex) and parent_index.isValid() else {}
        log_ctx_base["parent_path_excerpt"] = str(nd0.get("item_path") or nd0.get("display_path") or "")[:220]

        cur_gen = model.structure_generation()
        if expected_structure_generation is not None and cur_gen != int(expected_structure_generation):
            log_info(
                "source_generation_mismatch_audit",
                phase="apply_source_folder_load_model_tail",
                expected_generation=expected_structure_generation,
                current_generation=cur_gen,
                child_count=len(items or []),
                worker_outcome="apply_if_parent_still_live",
                **{
                    k: log_ctx_base[k]
                    for k in ("worker_id", "drive_id", "item_id", "item_id_suffix", "parent_path_excerpt")
                    if log_ctx_base.get(k) not in (None, "")
                },
            )

        if not isinstance(parent_index, QModelIndex) or not parent_index.isValid():
            log_info(
                "source_replace_children_invalid_index",
                model_generation=cur_gen,
                child_count=len(items or []),
                **{
                    k: log_ctx_base[k]
                    for k in ("worker_id", "drive_id", "item_id", "item_id_suffix")
                    if log_ctx_base.get(k) not in (None, "")
                },
            )
            return
        if not model.is_index_live(parent_index):
            log_info(
                "source_replace_children_skip_stale_parent",
                reason="parent_not_live_before_replace",
                model_generation=cur_gen,
                child_count=len(items or []),
                **{
                    k: log_ctx_base[k]
                    for k in ("worker_id", "drive_id", "item_id", "item_id_suffix", "parent_path_excerpt")
                    if log_ctx_base.get(k) not in (None, "")
                },
            )
            return

        log_info(
            "source_replace_children_start",
            model_generation=cur_gen,
            child_count=len(items or []),
            **{
                k: log_ctx_base[k]
                for k in ("worker_id", "drive_id", "item_id", "item_id_suffix", "parent_path_excerpt")
                if log_ctx_base.get(k) not in (None, "")
            },
        )

        child_payloads = []
        for child in sorted(items, key=lambda value: (not value.get("is_folder", False), value.get("name", "").lower())):
            pl = self._source_payload_from_graph_item(child)
            self._apply_tree_item_visual_state(None, pl)
            child_payloads.append(pl)
        dd_folder = str(drive_id or log_ctx_base.get("drive_id") or "").strip()
        if hasattr(model, "merge_sharepoint_folder_children"):
            model.merge_sharepoint_folder_children(
                parent_index,
                child_payloads,
                drive_id=dd_folder,
                log_context=log_ctx_base,
            )
        else:
            model.replace_all_children(
                parent_index,
                child_payloads,
                log_context=dict(log_ctx_base, replace_reason="merge_unavailable_fallback"),
            )

        def _mut_parent(p):
            p["children_loaded"] = True
            p["load_failed"] = False

        model.update_payload_for_index(parent_index, _mut_parent)
        bound_rows = int(model.rowCount(parent_index))
        log_info(
            "source_replace_children_visibility_audit",
            parent_path_excerpt=str(log_ctx_base.get("parent_path_excerpt") or "")[:240],
            graph_item_count=len(items or []),
            payload_rows_built=len(child_payloads),
            model_child_row_count_after=bound_rows,
            model_generation_after=int(model.structure_generation()),
            **{
                k: log_ctx_base[k]
                for k in ("worker_id", "drive_id", "item_id", "item_id_suffix")
                if log_ctx_base.get(k) not in (None, "")
            },
        )
        node_data = parent_index.data(Qt.UserRole) or {}
        trigger_path = node_data.get("item_path") or node_data.get("display_path") or ""
        current_child_paths = self._capture_child_path_set_for_model_index(parent_index)
        if previous_child_paths:
            added_count = len(current_child_paths - previous_child_paths)
            removed_count = len(previous_child_paths - current_child_paths)
            if added_count or removed_count:
                self._set_tree_status_message(
                    panel_key,
                    f"Refreshing saved branches... {added_count} added, {removed_count} removed in {node_data.get('name', 'folder')}.",
                    loading=bool(self._pending_snapshot_branch_refresh.get(panel_key)),
                )

        projection_refresh_invoked = False
        will_apply_overlay_after_source_load = (
            not self._expand_all_pending.get("source")
            and getattr(self, "destination_tree_widget", None) is not None
            and bool(self.planned_moves)
            and not getattr(self, "_sharepoint_lazy_mode", False)
            and not self._destination_steady_state_full_materialize_redundant()
        )
        if self._expand_all_pending.get("source"):
            self._expand_all_deferred_refresh["source"] = True
        elif self._memory_restore_in_progress or bool(self._source_restore_materialization_queue):
            self._source_projection_refresh_pending = True
        else:
            self._schedule_source_projection_refresh_for_paths(
                [trigger_path],
                "source_projection_folder_load_applied",
                trigger_path=trigger_path,
            )
            projection_refresh_invoked = True
            if destination_authority_contract.graph_owns_visible_real_destination_structure(self):
                # When overlay materialize runs for this load, its batch ``finally`` already calls
                # ``_on_destination_state_mutation`` — avoid a duplicate full-tree invariant here.
                if not will_apply_overlay_after_source_load:
                    self._schedule_coalesced_overlay_invariant(
                        "source_folder_load_applied:" + str(trigger_path or "")[:200],
                        source_driven=True,
                    )
        destination_future_model_applied_count = 0
        if will_apply_overlay_after_source_load:
            destination_future_model_applied_count = self._apply_destination_planning_overlays(
                "source_folder_load_success"
            )
        should_log_source_branch_loaded = not self._expand_all_pending.get("source")
        if self._expand_all_pending.get("source"):
            self._source_expand_all_folder_load_log_counter = (
                int(getattr(self, "_source_expand_all_folder_load_log_counter", 0) or 0) + 1
            )
            should_log_source_branch_loaded = self._source_expand_all_folder_load_log_counter % 24 == 0
        if should_log_source_branch_loaded:
            self._log_restore_phase(
                "source_restore_branch_loaded",
                source_path=trigger_path,
                normalized_source_path=self._canonical_source_projection_path(trigger_path),
                queue_size=len(self._source_restore_materialization_queue),
                branch_depth=self._source_branch_depth(trigger_path),
                already_loaded=False,
                loaded_successfully=True,
                projection_refresh_invoked=projection_refresh_invoked,
                destination_future_model_applied_count=destination_future_model_applied_count,
                trigger_path=self.normalize_memory_path(trigger_path),
                verbose=True,
            )
        self._schedule_source_restore_materialization_queue("folder_load", trigger_path=trigger_path)
        self._process_pending_source_navigation("folder_load", trigger_path=trigger_path)
        if not self._expand_all_pending.get("source"):
            self._continue_source_background_preload()
        if self._expand_all_pending.get("source"):
            self._source_column_refresh_pending = True
        else:
            self._refresh_tree_column_width("source")
        if self._source_branch_depth(trigger_path) <= 1:
            self.source_tree_widget.expand(parent_index)
            rc = model.rowCount(parent_index)
            self._set_tree_status_message(
                "source",
                f"{rc} top-level source folder(s) loaded.",
                loading=False,
            )
        self._try_flush_destination_future_model_after_source_restore("source_folder_load")

    def _apply_root_payload_to_tree(self, panel_key, items):
        if panel_key == "source":
            self._apply_root_payload_to_source_model_view(panel_key, items)
            return
        if panel_key == "destination":
            self._apply_root_payload_to_destination_model_view(panel_key, items)
            return
        log_info("apply_root_payload_to_tree_unexpected_panel", panel_key=str(panel_key or ""))

    def _apply_proposed_overlay_after_root_bind(self, panel_key):
        tree, _status = self._get_tree_and_status(panel_key)
        if panel_key != "destination":
            return 0
        self._destination_lifecycle_trace_TEMP(
            fn="_apply_proposed_overlay_after_root_bind",
            reason="enter",
            step_kind="overlay_repaint",
            extra="root_bind_proposed_allocation_overlay",
        )

        def _dest_top_level_count():
            if tree is None:
                return 0
            dm = getattr(self, "destination_planning_model", None)
            return dm.rowCount(QModelIndex()) if dm is not None else 0

        dm = getattr(self, "destination_planning_model", None)

        def _destination_lazy_top_level_waiting_for_children() -> bool:
            if not getattr(self, "_sharepoint_lazy_mode", False) or dm is None:
                return False
            for r in range(dm.rowCount(QModelIndex())):
                ix = dm.index(r, 0, QModelIndex())
                d = ix.data(Qt.UserRole) or {}
                if d.get("placeholder"):
                    continue
                if not d.get("is_folder"):
                    continue
                if d.get("load_failed"):
                    continue
                if not d.get("id"):
                    continue
                if not d.get("children_loaded"):
                    return True
            return False

        if _destination_lazy_top_level_waiting_for_children():
            self._log_restore_phase(
                "root_bind destination_overlay_deferred",
                panel_key=panel_key,
                reason="waiting_for_root_children",
                top_level_count=_dest_top_level_count(),
            )
            self._sync_restore_destination_overlay_pending_from_unresolved_queues()
            self._destination_lifecycle_trace_TEMP(
                fn="_apply_proposed_overlay_after_root_bind",
                reason="deferred_waiting_for_root_children",
                step_kind="overlay_repaint",
                extra="lazy_top_level_children_pending",
            )
            return 0

        if self._memory_ui_rebind_in_progress or self._memory_restore_in_progress:
            self._log_restore_phase(
                "root_bind destination_overlay_deferred",
                panel_key=panel_key,
                reason="restore_or_ui_rebind_in_progress",
            )
            self._sync_restore_destination_overlay_pending_from_unresolved_queues()
            self._destination_lifecycle_trace_TEMP(
                fn="_apply_proposed_overlay_after_root_bind",
                reason="deferred_restore_or_ui_rebind",
                step_kind="overlay_repaint",
                extra="",
            )
            return 0

        if not self.proposed_folders and not self.planned_moves:
            self._log_restore_phase("root_bind destination_overlay_skipped", panel_key=panel_key, reason="no_destination_overlays")
            self._destination_lifecycle_trace_TEMP(
                fn="_apply_proposed_overlay_after_root_bind",
                reason="skipped_no_proposed_or_moves",
                step_kind="overlay_repaint",
                extra="",
            )
            return 0

        try:
            applied_count = 0
            self._log_restore_phase(
                "root_bind destination_overlay_start",
                panel_key=panel_key,
                top_level_count=_dest_top_level_count(),
                proposed_count=len(self.proposed_folders),
                allocation_count=len(self.planned_moves),
            )
            dm = getattr(self, "destination_planning_model", None)
            if dm is not None:
                for r in range(dm.rowCount(QModelIndex())):
                    ix = dm.index(r, 0, QModelIndex())
                    applied_count += self._apply_proposed_children_to_item(ix)
                    applied_count += self._apply_allocation_children_to_item(ix)
            applied_count += self._replay_unresolved_proposed_overlay("root_bind_destination_overlay")
            applied_count += self._replay_unresolved_allocation_overlay("root_bind_destination_allocation_overlay")
            applied_count += self._reconcile_destination_semantic_duplicates_maybe_deferred(
                "root_bind_destination_overlay"
            )
            self._schedule_refresh_destination_tree_indicators()
            self._sync_restore_destination_overlay_pending_from_unresolved_queues()
            self._log_restore_phase(
                "root_bind destination_overlay_end",
                panel_key=panel_key,
                applied_count=applied_count,
                visible_proposed_count=self._count_visible_destination_proposed_nodes(),
            )
            self._destination_lifecycle_trace_TEMP(
                fn="_apply_proposed_overlay_after_root_bind",
                reason="overlay_applied",
                step_kind="overlay_repaint",
                extra=f"applied_count={applied_count};visible_proposed={self._count_visible_destination_proposed_nodes()}",
            )
            return applied_count
        except Exception as exc:
            self._log_restore_exception("root_bind destination_overlay", exc)
            self._log_restore_phase(
                "root_bind destination_overlay_safe_skip",
                panel_key=panel_key,
                reason="overlay_exception",
                proposed_count=len(self.proposed_folders),
                allocation_count=len(self.planned_moves),
            )
            self._sync_restore_destination_overlay_pending_from_unresolved_queues()
            return 0

    def _refresh_tree_ui_after_root_bind(self, panel_key, restored_runtime_snapshot=False):
        self._log_root_success_step("step_11_ui_refresh_enter", panel_key=panel_key)
        if panel_key == "source":
            if restored_runtime_snapshot:
                self._refresh_expand_all_button_for_panel("source")
                self._set_tree_status_message(
                    "source",
                    "Expanded from local snapshot. Refreshing live content...",
                    loading=bool(self._pending_snapshot_branch_refresh.get("source")),
                )
                load_started = self._prime_source_root_children_after_snapshot(force=True)
                if not load_started:
                    self._schedule_safe_timer(220, "source_root_prime_retry", self._prime_source_root_children_after_snapshot)
            elif not getattr(self, "_memory_restore_in_progress", False):
                self._refresh_source_projection("source_projection_root_bind_applied")
            if not restored_runtime_snapshot and not getattr(
                self, "_source_startup_snapshot_mount_seen", False
            ):
                self._start_source_restore_materialization()
            elif not restored_runtime_snapshot and getattr(
                self, "_source_startup_snapshot_mount_seen", False
            ):
                self._log_restore_phase(
                    "source_restore_materialization_deferred_snapshot_shell",
                    reason="startup_snapshot_first_paint",
                )
        else:
            self._destination_lifecycle_trace_TEMP(
                fn="_refresh_tree_ui_after_root_bind",
                reason=f"destination_post_root_bind;restored_runtime_snapshot={bool(restored_runtime_snapshot)}",
                step_kind="state_restore",
                extra="before_prime_expand_all_overlay",
            )
            self._refresh_destination_real_tree_snapshot(force=True)
            dest_tree = getattr(self, "destination_tree_widget", None)
            destination_top_level_count = self._planning_tree_top_level_count(dest_tree)
            root_row = None
            root_data = {}
            root_has_visible_children = False
            if dest_tree is not None and destination_top_level_count > 0:
                if isinstance(dest_tree, QTreeView) and getattr(self, "destination_planning_model", None) is not None:
                    model = self.destination_planning_model
                    root_row = model.index(0, 0, QModelIndex())
                    if root_row.isValid():
                        root_data = dict(root_row.data(Qt.UserRole) or {})
                        for r in range(model.rowCount(root_row)):
                            cd = model.index(r, 0, root_row).data(Qt.UserRole) or {}
                            if not cd.get("placeholder"):
                                root_has_visible_children = True
                                break
                else:
                    root_item = dest_tree.topLevelItem(0)
                    root_row = root_item
                    if root_item is not None:
                        root_data = root_item.data(0, Qt.UserRole) or {}
                        root_has_visible_children = bool(
                            any(
                                not ((root_item.child(index).data(0, Qt.UserRole) or {}).get("placeholder"))
                                for index in range(root_item.childCount())
                            )
                        )
            dest_needs_top_level_prime = (
                destination_top_level_count <= 1
                and not root_has_visible_children
                and not bool(root_data.get("children_loaded"))
            )
            if getattr(self, "_sharepoint_lazy_mode", False) and dest_needs_top_level_prime:
                self._sync_restore_destination_overlay_pending_from_unresolved_queues()
                load_started = self._prime_destination_root_children_after_snapshot(force=True)
                if not load_started:
                    self._schedule_safe_timer(220, "destination_root_prime_retry", self._prime_destination_root_children_after_snapshot)
                self._log_restore_phase(
                    "root_bind destination_top_level_deferred",
                    panel_key=panel_key,
                    top_level_count=destination_top_level_count,
                    trigger_path=self.normalize_memory_path(root_data.get("item_path", "")),
                    verbose=True,
                )
                self._schedule_progress_summary_refresh()
                self._log_root_success_step("step_11_ui_refresh_exit", panel_key=panel_key)
                if panel_key == "destination":
                    self._schedule_post_login_restore_phase4_if_pending()
                return
            root_present = root_row is not None and (
                not isinstance(root_row, QModelIndex) or root_row.isValid()
            )
            should_prime_destination_root = (
                getattr(self, "_sharepoint_lazy_mode", False)
                and root_present
                and self._destination_semantic_path(root_data) == "Root"
                and bool(root_data.get("is_folder"))
                and (not bool(root_data.get("children_loaded")) or not root_has_visible_children)
                and not bool(root_data.get("load_failed"))
                and bool(root_data.get("id"))
            )
            if should_prime_destination_root:
                load_started = self._prime_destination_root_children_after_snapshot(force=True)
                if not load_started:
                    self._schedule_safe_timer(220, "destination_root_prime_retry", self._prime_destination_root_children_after_snapshot)
                self._log_restore_phase(
                    "root_bind destination_root_prime_started" if load_started else "root_bind destination_root_prime_waiting",
                    panel_key=panel_key,
                    trigger_path=self.normalize_memory_path(root_data.get("item_path", "")),
                )
                self._schedule_progress_summary_refresh()
                self._log_root_success_step("step_11_ui_refresh_exit", panel_key=panel_key)
                if panel_key == "destination":
                    self._schedule_post_login_restore_phase4_if_pending()
                return
            if getattr(self, "_sharepoint_lazy_mode", False):
                applied_count = 0
                self._sync_restore_destination_overlay_pending_from_unresolved_queues()
                self._start_destination_restore_materialization()
                lazy_followup = False
                if getattr(self, "_destination_restore_completed_once", False) and (
                    self._restore_destination_overlay_pending
                    or self._unresolved_proposed_queue_size()
                    or self._unresolved_allocation_queue_size()
                ):

                    def _root_bind_lazy_future_followup():
                        self._destination_materialize_with_optional_overlay_scope(
                            "root_bind_lazy_post_finalize_followup",
                            allow_defer=True,
                            prefer_chunked_projection=True,
                        )

                    lazy_followup = True
                    QTimer.singleShot(
                        420,
                        lambda: self._safe_invoke(
                            "root_bind_lazy_destination_future_materialize",
                            _root_bind_lazy_future_followup,
                        ),
                    )
                self.destination_tree_widget.viewport().update()
                self._log_restore_phase(
                    "root_bind destination_projection_applied",
                    panel_key=panel_key,
                    applied_count=applied_count,
                    future_model_applied_count=0,
                    visible_proposed_count=self._count_visible_destination_proposed_nodes(),
                    deferred=self._restore_destination_overlay_pending,
                    lazy_post_finalize_future_materialize_scheduled=lazy_followup,
                    destination_restore_expanded_intent_count=len(
                        getattr(self, "_destination_restore_session_expanded_paths_intent", set()) or set()
                    ),
                    live_destination_expanded_paths_count=len(
                        self._collect_expanded_tree_paths("destination") or set()
                    ),
                )
                self._schedule_progress_summary_refresh()
                self._log_root_success_step("step_11_ui_refresh_exit", panel_key=panel_key)
                if panel_key == "destination":
                    self._schedule_post_login_restore_phase4_if_pending()
                return
            applied_count = self._apply_proposed_overlay_after_root_bind(panel_key)
            self._start_destination_restore_materialization()
            if getattr(self, "_sharepoint_lazy_mode", False):
                future_model_applied_count = 0
            else:
                # Prefer chunked projection/bind during restore to keep startup
                # responsive even when the future model is moderately large.
                future_model_applied_count = self._apply_destination_planning_overlays(
                    "root_bind",
                    allow_defer=True,
                    prefer_chunked_projection=True,
                )
                applied_count += future_model_applied_count
            self.destination_tree_widget.viewport().update()
            self._log_restore_phase(
                "root_bind destination_projection_applied",
                panel_key=panel_key,
                applied_count=applied_count,
                future_model_applied_count=future_model_applied_count,
                visible_proposed_count=self._count_visible_destination_proposed_nodes(),
                deferred=self._restore_destination_overlay_pending,
                destination_restore_expanded_intent_count=len(
                    getattr(self, "_destination_restore_session_expanded_paths_intent", set()) or set()
                ),
                live_destination_expanded_paths_count=len(
                    self._collect_expanded_tree_paths("destination") or set()
                ),
            )
            if panel_key == "destination":
                self._schedule_post_login_restore_phase4_if_pending()
        self._schedule_progress_summary_refresh()
        self._log_root_success_step("step_11_ui_refresh_exit", panel_key=panel_key)

    def populate_root_tree(self, panel_key, items):
        restore_destination_state = not bool(self._expand_all_pending.get("destination"))
        if restore_destination_state:
            ui_state = {
                "source_expanded_paths": self._collect_expanded_tree_paths("source"),
                "source_selected_path": self._collect_selected_tree_path("source"),
                "destination_expanded_paths": self._collect_expanded_tree_paths("destination"),
                "destination_selected_path": self._collect_selected_tree_path("destination"),
            }
        else:
            ui_state = {
                "source_expanded_paths": set(),
                "source_selected_path": "",
                "destination_expanded_paths": set(),
                "destination_selected_path": "",
            }
        self._apply_root_payload_to_tree(panel_key, items)
        self._refresh_tree_ui_after_root_bind(panel_key)
        self._restore_workspace_tree_state(ui_state)

    def build_tree_item(self, item):
        prefix = "Folder" if item.get("is_folder") else "File"
        base_label = self._tree_name_column_label(item.get("name", "Unnamed Item"))
        node = QTreeWidgetItem([base_label, "", "", ""])

        node_data = dict(item)
        node_data.setdefault("children_loaded", False)
        node_data.setdefault("load_failed", False)
        node_data.setdefault("tree_label", prefix)
        node_data.setdefault("base_display_label", base_label)
        node.setData(0, Qt.UserRole, node_data)
        self._apply_tree_item_visual_state(node, node_data)

        if item.get("is_folder"):
            node.setChildIndicatorPolicy(QTreeWidgetItem.ShowIndicator)
            node.addChild(
                self.build_loading_placeholder_item("Expand to load contents", role="lazy_unloaded")
            )
        else:
            node.setChildIndicatorPolicy(QTreeWidgetItem.DontShowIndicator)

        return node

    def build_loading_placeholder_item(self, text, *, role="lazy_unloaded"):
        """role: lazy_unloaded | loading_in_progress | terminal_empty | error | projection_pending"""
        placeholder = QTreeWidgetItem([text, "", "", ""])
        placeholder.setData(0, Qt.UserRole, {"placeholder": True, "placeholder_role": role})
        if self._full_trace_enabled():
            log_trace(
                "placeholder",
                "build_loading_placeholder_item",
                role=role,
                text_excerpt=(text or "")[:160],
            )
        return placeholder

    def _has_needs_review_for_source_path(self, source_path):
        canonical_path = self._canonical_source_projection_path(source_path)
        if not canonical_path:
            return False
        for row in getattr(self, "_workflow_needs_review_rows", []):
            row_source_path = self._canonical_source_projection_path(row.get("source_path", ""))
            if row_source_path and row_source_path == canonical_path:
                return True
        return False

    def _apply_tree_item_visual_state(self, item, node_data, *, source_relationship_index=None):
        if not node_data or node_data.get("placeholder"):
            return

        if item is not None:
            ncol = min(EXPLORER_COLUMN_COUNT, item.columnCount())
            for col in range(ncol):
                item.setForeground(col, QBrush())
                item.setBackground(col, QBrush())
                item.setToolTip(col, "")
        elif node_data.get("tree_role") == "source":
            node_data.pop("_model_foreground", None)
            node_data.pop("_model_background", None)
            node_data.pop("_model_tooltip", None)

        color = None
        background_color = None
        role = node_data.get("tree_role", "")
        if role == "source":
            relationship = self._evaluate_source_relationship(
                node_data, eval_index=source_relationship_index
            )
            node_data["source_relationship_mode"] = relationship.get("mode", "none")
            node_data["source_relationship_suffix"] = relationship.get("suffix", "")
            source_path = self._tree_item_path(node_data)
            if self._has_needs_review_for_source_path(source_path):
                color = QColor("#F5A623")
            elif relationship.get("mode") == "direct":
                color = QColor("#59D88F")
            elif relationship.get("mode") == "inherited":
                color = QColor("#8FC9FF")
        elif role == "destination":
            origin = str(node_data.get("node_origin", "")).lower()
            branch_color, branch_depth = self._destination_branch_visual_color(node_data)
            background_color = self._destination_branch_background_color(branch_color, branch_depth)
            if str(node_data.get("verification_state") or "") == "planned_only" and str(node_data.get("row_kind") or "").startswith(
                "planned_"
            ):
                color = QColor("#8A93A3")
            elif self.node_is_proposed(node_data):
                color = QColor("#FFC14D")
            elif self.node_is_planned_allocation(node_data):
                color = QColor("#51E3F6")
            elif origin == "projectedallocationdescendant":
                color = QColor("#89C9D8")
            elif branch_color is not None:
                color = branch_color

        submitted_state = self._submitted_visual_state_for_node(node_data)
        node_data["submitted_visual"] = bool(submitted_state["submitted"])
        node_data["submitted_batch_visual"] = submitted_state["batch_id"]
        if item is not None:
            item.setData(0, Qt.UserRole, node_data)
            if role == "destination":
                base_label = str(node_data.get("base_display_label", "")).strip() or item.text(0).replace(
                    " [Submitted]", ""
                )
                item.setText(0, f"{base_label} [Submitted]" if submitted_state["submitted"] else base_label)

            if ncol >= EXPLORER_COLUMN_COUNT and role in ("source", "destination"):
                self._apply_explorer_metadata_columns(item, node_data)
            if ncol >= EXPLORER_COLUMN_COUNT:
                item.setIcon(0, explorer_icon_for_node(node_data))

            if color is not None:
                for col in range(ncol):
                    item.setForeground(col, QBrush(color))
            if background_color is not None and not submitted_state["submitted"]:
                for col in range(ncol):
                    item.setBackground(col, QBrush(background_color))
            if submitted_state["submitted"]:
                tip = (
                    f"Submitted and locked in batch {submitted_state['batch_id']}."
                    if submitted_state["batch_id"]
                    else "Submitted and locked."
                )
                for col in range(ncol):
                    item.setBackground(col, QBrush(QColor("#1B2942")))
                    item.setToolTip(col, tip)
        elif role == "source":
            if color is not None:
                node_data["_model_foreground"] = color
            if submitted_state["submitted"]:
                node_data["_model_background"] = QColor("#1B2942")
                node_data["_model_tooltip"] = (
                    f"Submitted and locked in batch {submitted_state['batch_id']}."
                    if submitted_state["batch_id"]
                    else "Submitted and locked."
                )
            elif background_color is not None:
                node_data["_model_background"] = background_color
        elif role == "destination" and item is None:
            node_data.pop("_model_foreground", None)
            node_data.pop("_model_background", None)
            node_data.pop("_model_tooltip", None)
            if color is not None:
                node_data["_model_foreground"] = color
            if submitted_state["submitted"]:
                node_data["_model_background"] = QColor("#1B2942")
                node_data["_model_tooltip"] = (
                    f"Submitted and locked in batch {submitted_state['batch_id']}."
                    if submitted_state["batch_id"]
                    else "Submitted and locked."
                )
            elif background_color is not None:
                node_data["_model_background"] = background_color
        if self._full_trace_enabled():
            pk = str(role or "unknown")
            if pk in ("source", "destination"):
                self._ui_trace(
                    "visual",
                    "apply_tree_item_visual_state",
                    panel_key=pk,
                    item=item,
                    relationship_mode=str(node_data.get("source_relationship_mode", ""))[:40] if role == "source" else "",
                    node_origin_excerpt=str(node_data.get("node_origin", ""))[:80] if role == "destination" else "",
                    foreground_tint=bool(color is not None),
                    background_tint=bool(background_color is not None and not submitted_state["submitted"]),
                    submitted_locked=submitted_state["submitted"],
                )

    def _destination_branch_color_map(self):
        return {
            "finance": "#7FD36B",
            "hr": "#F3B45A",
            "it": "#5DD0FF",
            "management": "#E78AB2",
            "marketing": "#C38BFF",
            "operations": "#3FD0B0",
            "projects": "#E9C15F",
            "sales": "#FF8A66",
        }

    def _blend_colors(self, start_color, end_color, ratio):
        ratio = max(0.0, min(1.0, float(ratio)))
        inverse_ratio = 1.0 - ratio
        return QColor(
            int((start_color.red() * inverse_ratio) + (end_color.red() * ratio)),
            int((start_color.green() * inverse_ratio) + (end_color.green() * ratio)),
            int((start_color.blue() * inverse_ratio) + (end_color.blue() * ratio)),
        )

    def _destination_branch_visual_context(self, node_data):
        destination_path = self._canonical_destination_projection_path(self._tree_item_path(node_data))
        segments = self._path_segments(destination_path)
        if len(segments) < 2 or str(segments[0]).lower() != "root":
            return "", 0
        return segments[1], len(segments) - 1

    def _destination_branch_visual_color(self, node_data):
        branch_name, branch_depth = self._destination_branch_visual_context(node_data)
        branch_hex = self._destination_branch_color_map().get(str(branch_name).lower())
        if not branch_hex:
            return None, branch_depth

        branch_color = QColor(branch_hex)
        neutral_color = QColor("#D6E8FF")
        if branch_depth <= 1:
            return branch_color, branch_depth
        if branch_depth == 2:
            return self._blend_colors(branch_color, neutral_color, 0.18), branch_depth
        if branch_depth == 3:
            return self._blend_colors(branch_color, neutral_color, 0.34), branch_depth
        return self._blend_colors(branch_color, neutral_color, 0.52), branch_depth

    def _destination_branch_background_color(self, branch_color, branch_depth):
        if branch_color is None or branch_depth <= 0:
            return None

        base_background = QColor("#09101A")
        if branch_depth == 1:
            return self._blend_colors(base_background, branch_color, 0.20)
        if branch_depth == 2:
            return self._blend_colors(base_background, branch_color, 0.12)
        if branch_depth == 3:
            return self._blend_colors(base_background, branch_color, 0.07)
        return self._blend_colors(base_background, branch_color, 0.04)

    def normalize_memory_path(self, path):
        return normalize_manifest_path(path)

    def _path_segments(self, path):
        normalized = self.normalize_memory_path(path)
        if not normalized:
            return []
        return [segment for segment in normalized.split("\\") if segment]

    def _destination_projection_segments(self, path):
        segments = self._path_segments(path)
        if not segments:
            return []

        browse_local = str(getattr(self, "_destination_browse_mode", "") or "").lower() == "local"
        try:
            browse_local = browse_local or self._planning_browse_mode("destination") == "local"
        except Exception:
            pass
        if not browse_local:
            return destination_projection_segments_explicit(path, self._current_destination_context_segments())

        lowered = [segment.lower() for segment in segments]
        if "root" in lowered:
            return segments[lowered.index("root"):]

        context_segments = [segment.lower() for segment in self._current_destination_context_segments()]
        if context_segments:
            library_segment = context_segments[-1]
            if library_segment in lowered:
                library_index = lowered.index(library_segment)
                trimmed = segments[library_index + 1:]
                return ["Root", *trimmed] if trimmed else ["Root"]

            site_segment = context_segments[0]
            if site_segment in lowered:
                site_index = lowered.index(site_segment)
                trimmed = segments[site_index + 1:]
                if trimmed:
                    trimmed_lowered = [segment.lower() for segment in trimmed]
                    if library_segment in trimmed_lowered:
                        library_index = trimmed_lowered.index(library_segment)
                        trimmed = trimmed[library_index + 1:]
                    return ["Root", *trimmed] if trimmed else ["Root"]

        return ["Root", *segments]

    def _canonical_destination_projection_path(self, path):
        raw = str(path or "").strip()
        if is_absolute_local_path(raw):
            return self.normalize_memory_path(raw)
        segments = self._destination_projection_segments(path)
        if not segments:
            return ""
        canonical_path = self.normalize_memory_path("\\".join(segments))
        return self._destination_semantic_alias_path(canonical_path)

    def _destination_parent_match_details(self, requested_parent_path, candidate_tree_path):
        normalized_requested = self._canonical_destination_projection_path(requested_parent_path)
        normalized_candidate = self._canonical_destination_projection_path(candidate_tree_path)
        requested_segments = [segment.lower() for segment in self._path_segments(normalized_requested)]
        candidate_segments = [segment.lower() for segment in self._path_segments(normalized_candidate)]
        exact_match = bool(requested_segments and candidate_segments and requested_segments == candidate_segments)
        prefix_only_match = False
        if requested_segments and candidate_segments and not exact_match:
            min_length = min(len(requested_segments), len(candidate_segments))
            prefix_only_match = requested_segments[:min_length] == candidate_segments[:min_length]
        return {
            "normalized_requested": normalized_requested,
            "normalized_candidate": normalized_candidate,
            "exact_match": exact_match,
            "prefix_only_match": prefix_only_match,
        }

    def _destination_semantic_alias_path(self, path):
        canonical_path = self.normalize_memory_path(path)
        return canonical_path

    def _current_destination_context_segments(self):
        site_name = ""
        library_name = ""
        if hasattr(self, "planning_inputs"):
            destination_site_selector = self.planning_inputs.get("Destination Site")
            destination_library_selector = self.planning_inputs.get("Destination Library")
            destination_site = destination_site_selector.currentData() if destination_site_selector is not None else None
            destination_library = destination_library_selector.currentData() if destination_library_selector is not None else None
            if isinstance(destination_site, dict):
                site_name = destination_site.get("name", "")
            if isinstance(destination_library, dict):
                library_name = destination_library.get("name", "")

        if not site_name and hasattr(self, "_draft_shell_state") and isinstance(self._draft_shell_state, SessionState):
            site_name = self._draft_shell_state.SelectedDestinationSite or ""
        if not library_name and hasattr(self, "_draft_shell_state") and isinstance(self._draft_shell_state, SessionState):
            library_name = self._draft_shell_state.SelectedDestinationLibrary or ""

        return [segment for segment in (site_name, library_name) if segment]

    def _destination_raw_path_uses_library_root_hub(self, tree_path: str) -> bool:
        """True when ``tree_path`` goes ``...\\<Library>\\Root\\...`` (visible hub), not ``...\\<Library>\\<dept>``."""
        segs = self._path_segments(tree_path or "")
        if len(segs) < 2:
            return False
        ctx = self._current_destination_context_segments()
        if len(ctx) < 2:
            return False
        lib_l = str(ctx[1] or "").strip().casefold()
        if not lib_l:
            return False
        lowered = [str(s or "").strip().casefold() for s in segs]
        try:
            li = lowered.index(lib_l)
        except ValueError:
            return False
        rest = segs[li + 1 :]
        return bool(rest and str(rest[0]).strip().casefold() == "root")

    def _current_source_context_segments(self):
        site_name = ""
        library_name = ""
        if hasattr(self, "planning_inputs"):
            source_site_selector = self.planning_inputs.get("Source Site")
            source_library_selector = self.planning_inputs.get("Source Library")
            source_site = source_site_selector.currentData() if source_site_selector is not None else None
            source_library = source_library_selector.currentData() if source_library_selector is not None else None
            if isinstance(source_site, dict):
                site_name = source_site.get("name", "")
            if isinstance(source_library, dict):
                library_name = source_library.get("name", "")

        if not site_name and hasattr(self, "_draft_shell_state") and isinstance(self._draft_shell_state, SessionState):
            site_name = self._draft_shell_state.SelectedSourceSite or ""
        if not library_name and hasattr(self, "_draft_shell_state") and isinstance(self._draft_shell_state, SessionState):
            library_name = self._draft_shell_state.SelectedSourceLibrary or ""

        return [segment for segment in (site_name, library_name) if segment]

    def _canonical_source_projection_path(self, path):
        raw = str(path or "").strip()
        if is_absolute_local_path(raw):
            return self.normalize_memory_path(raw)
        segments = self._path_segments(path)
        if not segments:
            return ""

        lowered_segments = [segment.lower() for segment in segments]
        context_segments = [segment.lower() for segment in self._current_source_context_segments()]
        if context_segments:
            library_segment = context_segments[-1]
            if library_segment in lowered_segments:
                library_index = lowered_segments.index(library_segment)
                trimmed = segments[library_index + 1:]
                if trimmed:
                    return "\\".join(trimmed)

            site_segment = context_segments[0]
            if site_segment in lowered_segments:
                site_index = lowered_segments.index(site_segment)
                trimmed = segments[site_index + 1:]
                if trimmed:
                    return "\\".join(trimmed)

        return "\\".join(segments)

    def _source_payload_index_key(self, payload: dict) -> str:
        """Canonical path key for SharePointSourceTreeModel path index (must match find_visible_source_item_by_path)."""
        if not isinstance(payload, dict) or payload.get("placeholder"):
            return ""
        mem = self.normalize_memory_path(
            payload.get("display_path")
            or payload.get("item_path")
            or payload.get("source_path")
            or ""
        )
        return self._canonical_source_projection_path(mem) or ""

    def _destination_payload_index_raw_mem(self, payload: dict) -> str:
        """Raw path string used to build :meth:`_destination_payload_index_key` (index bucket identity).

        Field precedence matches the model index only (not :meth:`_tree_item_path`, which prefers
        ``source_path`` over ``destination_path``). Incremental merge uses this to accept index
        hits when the primary visible-path match fails.

        Under Graph authority, ``display_path`` is often a human ``site / library / …`` string that
        does not canonicalize to the same keys as planning memory (graph-relative ``hub\\child``).
        Prefer drive-relative ``item_path`` so :meth:`find_indices_for_canonical_destination_path`
        hits overlay and hydrate lookups.
        """
        if not isinstance(payload, dict) or payload.get("placeholder"):
            return ""
        if destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            return self.normalize_memory_path(
                payload.get("item_path")
                or payload.get("destination_path")
                or payload.get("display_path")
                or payload.get("source_path")
                or ""
            )
        return self.normalize_memory_path(
            payload.get("display_path")
            or payload.get("item_path")
            or payload.get("destination_path")
            or payload.get("source_path")
            or ""
        )

    def _destination_payload_index_key(self, payload: dict) -> str:
        """Canonical path key for DestinationPlanningTreeModel index (must match _destination_parent_match_details)."""
        mem = self._destination_payload_index_raw_mem(payload)
        if not mem:
            return ""
        if destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            # Index keys must not depend on selector-backed context segments: FolderLoadWorker often
            # completes before planning_inputs/draft library context is populated, so
            # _canonical_destination_projection_path would keep the visible hub (Root3\\...) while
            # later lookups trim to library-relative keys — yielding candidate_count 0 and no overlays.
            segs = destination_projection_segments_explicit(mem, [])
            if not segs:
                return ""
            return self.normalize_memory_path("\\".join(segs))
        return self._canonical_destination_projection_path(mem) or ""

    def _normalized_path_variants(self, path, tree_role=""):
        if tree_role == "source":
            path = self._canonical_source_projection_path(path)
        segments = self._path_segments(path)
        if not segments:
            return set()

        variants = {"\\".join(segments)}
        min_suffix_length = 1 if tree_role == "destination" else (2 if len(segments) > 1 else 1)
        for start_index in range(max(0, len(segments) - 6), len(segments)):
            suffix = segments[start_index:]
            if len(suffix) >= min_suffix_length:
                variants.add("\\".join(suffix))

        lowered = [segment.lower() for segment in segments]
        if tree_role in {"source", "destination"} and "root" in lowered:
            root_index = lowered.index("root")
            variants.add("\\".join(segments[root_index:]))

        return {self.normalize_memory_path(variant) for variant in variants if variant}

    def _paths_equivalent(self, left_path, right_path, tree_role=""):
        left_variants = self._normalized_path_variants(left_path, tree_role)
        right_variants = self._normalized_path_variants(right_path, tree_role)
        return bool(left_variants and right_variants and left_variants.intersection(right_variants))

    def _path_is_descendant(self, child_path, parent_path, tree_role=""):
        child_variants = self._normalized_path_variants(child_path, tree_role)
        parent_variants = self._normalized_path_variants(parent_path, tree_role)
        for child_variant in child_variants:
            child_lower = child_variant.lower()
            for parent_variant in parent_variants:
                parent_lower = parent_variant.lower()
                if child_lower == parent_lower:
                    continue
                if child_lower.startswith(f"{parent_lower}\\"):
                    return True
        return False

    @staticmethod
    def _planning_path_key_backslash(path: str) -> str:
        s = str(path).strip().replace("/", "\\")
        while s.startswith("\\"):
            s = s[1:]
        return s

    def _strip_legacy_snapshot_wrapper_segment(self, path: str) -> str:
        """Drop one leading legacy library-relative segment (e.g. ``Root``) before graph-root anchoring.

        Only runs when :attr:`_destination_graph_root_name` is set, the path is not already under
        that graph root, and the first non-empty segment matches a known legacy singleton (segment
        equality, case-insensitive). Structural segment split — no substring trimming.
        """
        if not path:
            return path
        graph_root = getattr(self, "_destination_graph_root_name", None)
        gr = str(graph_root or "").strip()
        if not gr:
            return path
        s = self._planning_path_key_backslash(path)
        if not s:
            return path
        gr_cf = gr.casefold()
        s_cf = s.casefold()
        if s_cf == gr_cf or s_cf.startswith(gr_cf + "\\"):
            return path
        segments = [p for p in s.split("\\") if p]
        if len(segments) < 2:
            return path
        if segments[0].casefold() not in self._LEGACY_SNAPSHOT_LIBRARY_RELATIVE_ROOT_SEGMENTS:
            return path
        stripped = "\\".join(segments[1:])
        log_info(
            "destination_path_pre_normalization_guard",
            original_path=str(path)[:2000],
            stripped_path=str(stripped)[:2000],
            graph_root=str(gr)[:500],
        )
        return stripped

    def _normalize_to_graph_canonical_path(self, path: str) -> str:
        if not path:
            return path

        graph_root = getattr(self, "_destination_graph_root_name", None)

        if not graph_root:
            return path

        gr = str(graph_root).strip()
        if not gr:
            return path

        gen = int(getattr(self, "_planning_cache_generation", 0) or 0)
        if int(getattr(self, "_destination_graph_canon_norm_cache_gen", -1) or -1) != gen:
            self._destination_graph_canon_norm_cache = {}
            self._destination_graph_canon_norm_cache_gen = gen
        cache = getattr(self, "_destination_graph_canon_norm_cache", None) or {}
        self._destination_graph_canon_norm_cache = cache
        cache_key = (gen, gr.casefold(), str(path))
        hit = cache.get(cache_key)
        if hit is not None:
            self._destination_norm_cache_hits_pass = int(getattr(self, "_destination_norm_cache_hits_pass", 0) or 0) + 1
            return hit

        working = self._strip_legacy_snapshot_wrapper_segment(path)
        wk = self._planning_path_key_backslash(working)
        gr_cf = gr.casefold()
        wk_cf = wk.casefold()
        if wk_cf == gr_cf or wk_cf.startswith(gr_cf + "\\"):
            out = wk
            cache[cache_key] = out
            if len(cache) > 4096:
                for k in list(cache.keys())[:2048]:
                    cache.pop(k, None)
            return out

        normalized_path = f"{gr}\\{wk}"
        log_info(
            "destination_path_normalized",
            original=str(path)[:2000],
            normalized=str(normalized_path)[:2000],
            graph_root=str(gr)[:500],
        )
        cache[cache_key] = normalized_path
        if len(cache) > 4096:
            for k in list(cache.keys())[:2048]:
                cache.pop(k, None)
        return normalized_path

    def _proposed_parent_path(self, proposed_folder):
        if isinstance(proposed_folder, ProposedFolder):
            pp = str(proposed_folder.ParentPath or "").strip()
            if pp:
                proposed_parent_path = self._normalize_to_graph_canonical_path(pp)
                raw_path = self.normalize_memory_path(proposed_parent_path)
            else:
                raw_path = self.normalize_memory_path(
                    self._normalize_to_graph_canonical_path(str(proposed_folder.DestinationPath or "").strip())
                )
            return self._canonical_destination_projection_path(raw_path)
        return ""

    def _proposed_destination_path(self, proposed_folder):
        if isinstance(proposed_folder, ProposedFolder):
            raw_path = self.normalize_memory_path(
                self._normalize_to_graph_canonical_path(str(proposed_folder.DestinationPath or "").strip())
            )
            canon = self._canonical_destination_projection_path(raw_path)
            if canon:
                return canon
            parent = self.normalize_memory_path(
                self._normalize_to_graph_canonical_path(str(proposed_folder.ParentPath or "").strip())
            )
            name = str(proposed_folder.FolderName or "").strip()
            if parent and name:
                combined = self.normalize_memory_path(f"{parent}\\{name}")
                return self._canonical_destination_projection_path(combined) or combined
            return ""
        return ""

    def _proposed_folder_key(self, proposed_folder):
        return self._proposed_destination_path(proposed_folder)

    def _unresolved_proposed_queue_size(self):
        data = getattr(self, "unresolved_proposed_by_parent_path", None) or {}
        return sum(len(entries) for entries in data.values())

    def _allocation_projection_destination_path_source(self, move) -> str:
        """Canonical destination path for overlay geometry (parent path, projection, queue keys).

        When legacy migration resolved a **planned parent** (Graph id absent), ``destination_path`` may still
        carry a pre–re-anchor ``Root\\...`` prefix while ``DestinationParentPlannedPath`` matches the visible
        library layout (e.g. ``Root3\\...``). Overlay and unresolved replay must use the planned-parent
        composition so file/folder rows bucket and paint under the same canonical parents as Graph skeleton.
        """
        if not isinstance(move, dict):
            return ""
        raw_in = str(move.get("destination_path", "") or "").strip()
        planned_parent = str(move.get("DestinationParentPlannedPath", "") or "").strip()
        res = str(move.get("LegacyMigrationDestinationParentResolution", "") or "").strip().casefold()
        legacy_pp = bool(move.get("LegacyMigrationPlannedParentResolved"))
        leaf = str(self._move_target_name(move) or "").strip()
        use_pp = (res == "planned_parent" or legacy_pp) and bool(planned_parent) and bool(leaf)
        if use_pp:
            combined = self.normalize_memory_path(f"{planned_parent}\\{leaf}")
            out = self._normalize_to_graph_canonical_path(combined) or combined
            if out and raw_in and out.casefold() != self._normalize_to_graph_canonical_path(raw_in).casefold():
                log_info(
                    "destination_planned_parent_path_override_applied",
                    request_excerpt=str(move.get("request_id", "") or "")[:80],
                    legacy_destination_excerpt=str(raw_in)[:260],
                    effective_destination_excerpt=str(out)[:260],
                    planned_parent_excerpt=str(planned_parent)[:260],
                )
            return out
        raw = self._normalize_to_graph_canonical_path(raw_in)
        return raw

    def _allocation_destination_path_canonical_segments(self, move) -> list[str]:
        """Segments of the planned destination path after graph-authoritative planned-path canonicalization."""
        if not isinstance(move, dict):
            return []
        raw = str(self._allocation_projection_destination_path_source(move) or "").strip()
        if not raw:
            return []
        canon = self._canonical_planned_memory_path_for_graph_match(raw)
        return [s for s in str(canon).replace("/", "\\").split("\\") if s]

    def _allocation_destination_path_includes_target_leaf(self, move) -> bool:
        """True when ``destination_path`` already ends with the planned destination leaf (full-path shape).

        Graph-expanded and some persisted rows store the complete destination file (or folder) path in
        ``destination_path``. Legacy rows store the parent folder only and rely on ``target_name`` /
        ``source_name`` for the leaf. Appending the leaf again would duplicate the segment and make
        unrelated files share one projection key.
        """
        if not isinstance(move, dict):
            return False
        leaf = str(self._move_target_name(move) or "").strip()
        if not leaf:
            return False
        segs = self._allocation_destination_path_canonical_segments(move)
        return bool(segs) and segs[-1].strip().lower() == leaf.lower()

    def _allocation_parent_path(self, move):
        if not isinstance(move, dict):
            return ""
        raw = str(self._allocation_projection_destination_path_source(move) or "").strip()
        if not raw:
            return ""
        if self._allocation_destination_path_includes_target_leaf(move):
            segs = self._allocation_destination_path_canonical_segments(move)
            if len(segs) <= 1:
                return ""
            parent = "\\".join(segs[:-1])
            return self._canonical_planned_memory_path_for_graph_match(parent)
        return self._canonical_planned_memory_path_for_graph_match(raw)

    def _move_target_name(self, move):
        if not isinstance(move, dict):
            return ""
        target_name = str(move.get("target_name", "") or "").strip()
        if target_name:
            return target_name
        source_name = str(move.get("source_name", "") or "").strip()
        if source_name:
            return source_name
        source_node = move.get("source", {}) if isinstance(move.get("source", {}), dict) else {}
        return str(source_node.get("name", "") or "").strip()

    def _destination_leaf_forensic_trace_payload(self, fn: str, pl: dict, source_of_truth: str) -> None:
        """Opt-in tracing: set ``OZLINK_DEST_LEAF_TRACE`` to a substring of the leaf path or name."""
        frag = (os.environ.get("OZLINK_DEST_LEAF_TRACE") or "").strip().casefold()
        if not frag:
            return
        if not isinstance(pl, dict):
            return
        name = str(pl.get("real_name") or pl.get("name") or "")
        path = str(pl.get("destination_path") or pl.get("item_path") or "").replace("/", "\\")
        blob = f"{name}\n{path}".casefold()
        if frag not in blob:
            return
        log_info(
            "destination_leaf_forensic_trace",
            function=str(fn or "")[:120],
            path=path[:400],
            name=name[:200],
            is_folder=pl.get("is_folder"),
            row_kind=str(pl.get("row_kind") or "")[:40],
            source_of_truth=str(source_of_truth or "")[:120],
        )

    def _destination_structural_path_chain_invalid_for_container_parent(self, canonical_path: str) -> tuple[bool, str]:
        """True when any segment before the terminal looks like a document file (illegal folder parent chain).

        Container chains must be folder-like at every intermediate segment; a ``.docx``/``.pdf`` leaf name
        cannot appear before the final segment (prevents file-as-folder parent bugs in exact-move ownership).
        """
        raw = (canonical_path or "").strip().replace("/", "\\")
        if not raw:
            return False, ""
        segs = self._path_segments(raw)
        if len(segs) <= 1:
            return False, ""
        for seg in segs[:-1]:
            if planned_leaf_filename_implies_document_file(seg):
                return True, "file_segment_before_terminal"
        return False, ""

    def _destination_unresolved_replay_parent_path_structurally_invalid(
        self, parent_path: str
    ) -> tuple[bool, str]:
        """True when a queued parent path cannot be a graph-backed folder parent for overlay replay.

        Rejects file-like terminal segments (e.g. ``...\\report.docx`` as a "parent folder" key) and
        any intermediate document-file segments. Valid folder parents that are not yet Graph-visible
        are **not** rejected here.
        """
        raw = (parent_path or "").strip().replace("/", "\\")
        if not raw:
            return False, ""
        segs = self._path_segments(raw)
        if not segs:
            return False, ""
        if planned_leaf_filename_implies_document_file(segs[-1]):
            return True, "parent_terminal_segment_file_like"
        mid_invalid, mid_reason = self._destination_structural_path_chain_invalid_for_container_parent(raw)
        if mid_invalid:
            return True, mid_reason or "structural_chain_invalid"
        return False, ""

    def _destination_remember_invalid_unresolved_parent_terminal(self, canon_cf: str) -> None:
        """Bounded terminal set so invalid parents are not re-enqueued indefinitely."""
        if not canon_cf:
            return
        d = getattr(self, "_destination_invalid_unresolved_parent_terminal", None)
        if not isinstance(d, dict):
            return
        if canon_cf in d:
            return
        d[canon_cf] = time.monotonic()
        order: list[str] = getattr(self, "_destination_invalid_unresolved_parent_terminal_order", None) or []
        order.append(canon_cf)
        cap = max(64, int(getattr(self, "_destination_invalid_unresolved_parent_terminal_cap", 512) or 512))
        while len(order) > cap:
            old = order.pop(0)
            d.pop(old, None)
        self._destination_invalid_unresolved_parent_terminal_order = order

    def _destination_invalid_unresolved_parent_previously_pruned(self, parent_path: str) -> bool:
        raw = (parent_path or "").strip().replace("/", "\\")
        if not raw:
            return False
        try:
            cf = str(
                self._canonical_planned_memory_path_for_graph_match(self.normalize_memory_path(raw)) or ""
            ).casefold()
        except Exception:
            cf = self.normalize_memory_path(raw).casefold()
        d = getattr(self, "_destination_invalid_unresolved_parent_terminal", None)
        return isinstance(d, dict) and cf in d

    def _destination_prune_invalid_unresolved_replay_parent_paths(self, *, context: str) -> dict[str, int]:
        """Remove structurally impossible parent keys from unresolved replay queues (not merely logged)."""
        pr_proposed = pr_alloc = 0
        n_prop_parents = n_alloc_parents = 0
        _pairs: list[tuple[str, str]] = []
        for p in list((getattr(self, "unresolved_proposed_by_parent_path", None) or {}).keys()):
            _pairs.append((str(p), "proposed"))
        for p in list((getattr(self, "unresolved_allocations_by_parent_path", None) or {}).keys()):
            _pairs.append((str(p), "allocation"))
        for pp, kind in _pairs:
            inv, inv_reason = self._destination_unresolved_replay_parent_path_structurally_invalid(pp)
            if not inv:
                continue
            if kind == "proposed":
                bucket = (getattr(self, "unresolved_proposed_by_parent_path", None) or {}).pop(pp, None)
                n_prop_parents += 1
            else:
                bucket = (getattr(self, "unresolved_allocations_by_parent_path", None) or {}).pop(pp, None)
                n_alloc_parents += 1
            n_entries = len(bucket) if isinstance(bucket, dict) else 0
            if kind == "proposed":
                pr_proposed += n_entries
            else:
                pr_alloc += n_entries
            try:
                cf = str(
                    self._canonical_planned_memory_path_for_graph_match(self.normalize_memory_path(str(pp or "")))
                    or ""
                ).casefold()
            except Exception:
                cf = self.normalize_memory_path(str(pp or "")).casefold()
            self._destination_remember_invalid_unresolved_parent_terminal(cf)
            _move_id = ""
            if isinstance(bucket, dict) and bucket:
                try:
                    first = next(iter(bucket.values()))
                    if isinstance(first, dict):
                        _move_id = str(
                            first.get("request_id") or first.get("allocation_id") or first.get("move_id") or ""
                        )[:120]
                except Exception:
                    _move_id = ""
            log_info(
                "destination_unresolved_parent_pruned_invalid",
                unresolved_kind=str(kind),
                parent_path_excerpt=str(pp or "")[:400],
                invalid_reason=str(inv_reason or "")[:120],
                context=str(context or "")[:120],
                bucket_entries_removed=int(n_entries),
                move_or_request_excerpt=_move_id,
                removal_reason=str(UnresolvedQueueRemovalReason.pruned_invalid_parent_structure),
            )
        try:
            self._sync_restore_destination_overlay_pending_from_unresolved_queues()
        except Exception:
            pass
        return {
            "pruned_proposed_parents": int(n_prop_parents),
            "pruned_allocation_parents": int(n_alloc_parents),
            "pruned_proposed_entries": int(pr_proposed),
            "pruned_allocation_entries": int(pr_alloc),
            "pruned_entry_total": int(pr_proposed + pr_alloc),
        }

    def _destination_payload_cannot_serve_as_folder_parent(self, ch: dict | None) -> bool:
        """True when a destination row cannot legally be the parent of a further path segment."""
        if not isinstance(ch, dict):
            return True
        if ch.get("is_folder") is True:
            return False
        if ch.get("is_folder") is False:
            return True
        rk = str(ch.get("row_kind") or "").strip().lower()
        if rk in ("planned_file", "live_file"):
            return True
        return False

    def _planned_move_terminal_is_file_leaf(self, move: dict | None) -> bool:
        """True when the planned move's destination leaf is a file (explicit metadata or leaf-name fallback)."""
        if not isinstance(move, dict):
            return False
        src = move.get("source") if isinstance(move.get("source"), dict) else {}
        if src.get("is_folder") is True:
            return False
        if src.get("is_folder") is False:
            return True
        sif = move.get("source_is_folder")
        if sif is True:
            return False
        if sif is False:
            return True
        leaf = str(self._move_target_name(move) or "").strip()
        return planned_leaf_filename_implies_document_file(leaf)

    def _source_tree_payload_implies_file_leaf(self, src: dict | None) -> bool:
        if not isinstance(src, dict):
            return False
        if src.get("is_folder") is True:
            return False
        if src.get("is_folder") is False:
            return True
        leaf = str(src.get("real_name") or src.get("name") or "").strip()
        return planned_leaf_filename_implies_document_file(leaf)

    def _allocation_projection_path(self, move):
        if not isinstance(move, dict):
            return ""
        raw = str(self._allocation_projection_destination_path_source(move) or "").strip()
        target_name = str(self._move_target_name(move) or "").strip()
        if raw and target_name and self._allocation_destination_path_includes_target_leaf(move):
            out = self._canonical_destination_projection_path(self.normalize_memory_path(raw)) or self.normalize_memory_path(
                raw
            )
            return self._canonical_planned_memory_path_for_graph_match(out)
        parent_path = self._allocation_parent_path(move)
        if not parent_path or not target_name:
            mid = self._canonical_destination_projection_path(self.normalize_memory_path(parent_path or target_name))
            return self._canonical_planned_memory_path_for_graph_match(mid or "")
        combined = self._canonical_destination_projection_path(
            self.normalize_memory_path(f"{parent_path}\\{target_name}")
        ) or self.normalize_memory_path(f"{parent_path}\\{target_name}")
        return self._canonical_planned_memory_path_for_graph_match(combined)

    def _allocation_move_key(self, move):
        return self._allocation_projection_path(move)

    def _rewrite_nonprimary_planned_moves_destination_prefix(
        self, old_root: str, new_root: str, *, primary_move: dict | None
    ) -> list[dict]:
        """When a planned allocation relocates, rewrite other draft moves whose projection lived under old_root.

        Keeps ``planned_moves`` / manifest / execution steps consistent for per-item rows under a moved folder branch.
        """
        out: list[dict] = []
        if not isinstance(primary_move, dict):
            primary_move = None
        norm_old = (
            self._canonical_destination_projection_path(self.normalize_memory_path(old_root))
            or self.normalize_memory_path(old_root)
        ).rstrip("\\")
        norm_new = (
            self._canonical_destination_projection_path(self.normalize_memory_path(new_root))
            or self.normalize_memory_path(new_root)
        ).rstrip("\\")
        if not norm_old or not norm_new:
            return out
        old_cf = norm_old.casefold()
        primary_is_folder = False
        if primary_move is not None:
            ps = primary_move.get("source") if isinstance(primary_move.get("source"), dict) else {}
            primary_is_folder = bool(ps.get("is_folder", False))
        for m in self.planned_moves:
            if primary_move is not None and m is primary_move:
                continue
            if self._is_move_submitted(m):
                continue
            proj = self._allocation_projection_path(m)
            if not proj:
                continue
            proj_n = (
                self._canonical_destination_projection_path(proj) or self.normalize_memory_path(proj)
            ).rstrip("\\")
            pcf = proj_n.casefold()
            if pcf == old_cf:
                rel_suffix = ""
            elif pcf.startswith(old_cf + "\\"):
                rel_suffix = proj_n[len(norm_old) + 1 :]
            else:
                continue
            if rel_suffix:
                next_full = self.normalize_memory_path(f"{norm_new}\\{rel_suffix}")
            else:
                msrc = m.get("source") if isinstance(m.get("source"), dict) else {}
                m_is_folder = bool(msrc.get("is_folder", False))
                file_leaf = str(self._move_target_name(m) or "").strip()
                if not m_is_folder and file_leaf:
                    # Exact projection match on old root with no relative suffix: do not assign every
                    # row norm_new's last segment (would stamp one file's leaf onto all siblings).
                    if primary_is_folder:
                        next_full = self.normalize_memory_path(f"{norm_new}\\{file_leaf}")
                    else:
                        segs = [x for x in str(norm_new).replace("/", "\\").split("\\") if x]
                        parent_new = "\\".join(segs[:-1]) if len(segs) > 1 else ""
                        next_full = (
                            self.normalize_memory_path(f"{parent_new}\\{file_leaf}")
                            if parent_new
                            else self.normalize_memory_path(f"{norm_new}\\{file_leaf}")
                        )
                else:
                    next_full = norm_new
            segs = [x for x in next_full.split("\\") if x]
            if not segs:
                continue
            parent_path = "\\".join(segs[:-1]) if len(segs) > 1 else ""
            leaf = segs[-1]
            m["destination_path"] = parent_path
            m["target_name"] = leaf
            m["destination_name"] = leaf
            dest = m.get("destination")
            if isinstance(dest, dict):
                dest = dict(dest)
                dest["display_path"] = next_full
                dest["item_path"] = next_full
                dest["destination_path"] = parent_path
                dest["name"] = leaf
                m["destination"] = dest
            out.append(m)
        return out

    def _expand_source_projection_paths_for_move_network(self, move: dict) -> set[str]:
        """Source tree paths to refresh so relationship / via labels match ``planned_moves`` for this row and descendants."""
        paths: set[str] = set()
        if not isinstance(move, dict):
            return paths
        src = move.get("source") if isinstance(move.get("source"), dict) else {}
        root_raw = self._tree_item_path(src) or move.get("source_path", "")
        canon = self._canonical_source_projection_path(root_raw)
        if canon:
            paths.add(canon)
        if bool(src.get("is_folder")) and root_raw:
            for other in self.planned_moves:
                if other is move:
                    continue
                other_src = other.get("source") if isinstance(other.get("source"), dict) else {}
                other_raw = self._tree_item_path(other_src) or other.get("source_path", "")
                if not other_raw:
                    continue
                if self.source_item_path_is_descendant_of(other_raw, root_raw):
                    op = self._canonical_source_projection_path(other_raw)
                    if op:
                        paths.add(op)
        return paths

    def _collect_source_projection_paths_under_destination_allocation_prefix(self, prefix: str) -> set[str]:
        """Union of source projection roots for moves whose allocation projection is under ``prefix``."""
        paths: set[str] = set()
        norm = (
            self._canonical_destination_projection_path(self.normalize_memory_path(prefix))
            or self.normalize_memory_path(str(prefix or "").strip())
        ).rstrip("\\")
        if not norm:
            return paths
        pcf = norm.casefold()
        for m in self.planned_moves:
            proj = self._allocation_projection_path(m)
            if not proj:
                continue
            proj_n = (
                self._canonical_destination_projection_path(proj) or self.normalize_memory_path(proj)
            ).rstrip("\\")
            qcf = proj_n.casefold()
            if qcf != pcf and not qcf.startswith(pcf + "\\"):
                continue
            paths |= self._expand_source_projection_paths_for_move_network(m)
        return paths

    def _planned_destination_move_origin(self, *, from_paste_here: bool, from_manual_planning_drag: bool) -> str:
        """Stable label for diagnostics: every successful planned destination reparent uses one of these."""
        if from_manual_planning_drag:
            return "manual_drag"
        if from_paste_here:
            return "paste_here"
        return "other"

    def _finalize_destination_move_planning_consistency(
        self,
        primary_move: dict,
        *,
        rewritten_related: list[dict] | None,
        old_destination_projection: str,
        new_destination_projection: str,
        table_refreshed: bool,
        incremental_lightweight: bool,
        move_origin: str,
    ) -> tuple[frozenset[str], bool]:
        """Single post-move contract for all planned destination reparent paths (drag, paste, other).

        Invalidates projection lookup caches (no planning generation bump), synchronously refreshes affected
        source rows when the source tree exists, and emits MOVEAUDIT in dev mode for every origin.

        Returns ``(normalized_source_paths, did_sync_refresh)``. When ``did_sync_refresh`` is True, callers
        should queue an empty deferred source-projection path set so a follow-up persist does not re-scan the
        entire visible relationship surface.
        """
        rewritten_related = rewritten_related or []
        paths: set[str] = set()
        paths |= self._expand_source_projection_paths_for_move_network(primary_move)
        for m in rewritten_related:
            paths |= self._expand_source_projection_paths_for_move_network(m)
        normalized_paths = {self._canonical_source_projection_path(p) for p in paths if p}
        normalized_paths.discard("")
        self._invalidate_projection_lookup_caches(
            bump_generation=False,
            clear_source_path_cache=False,
            source_eviction_paths=normalized_paths,
        )
        source_traceability_updated = False
        tw = getattr(self, "source_tree_widget", None)
        if normalized_paths and tw is not None:
            phase = (
                "planned_destination_move_sync_light"
                if incremental_lightweight
                else "planned_destination_move_sync_heavy"
            )
            self._refresh_source_projection_for_paths(
                normalized_paths,
                phase,
                trigger_path=sorted(normalized_paths, key=len)[0],
                source_perf_move_origin=str(move_origin or ""),
            )
            source_traceability_updated = True
        if tw is not None:
            tw.viewport().update()

        if is_dev_mode():
            src_path = self._canonical_source_projection_path(
                str(primary_move.get("source_path", "") or "").strip()
            ) or self._canonical_source_projection_path(self._tree_item_path(primary_move.get("source") or {}))
            log_info(
                "MOVEAUDIT",
                move_origin=str(move_origin or "other"),
                source_path=str(src_path or "")[:500],
                old_destination_path=str(old_destination_projection or "")[:500],
                new_destination_path=str(new_destination_projection or "")[:500],
                affected_record_count=int(1 + len(rewritten_related)),
                planned_move_map_updated=True,
                source_traceability_updated=source_traceability_updated,
                planned_moves_table_updated=bool(table_refreshed),
                execution_state_updated=True,
                descendant_count=int(len(rewritten_related)),
                incremental_lightweight=bool(incremental_lightweight),
            )

        did_sync_refresh = bool(normalized_paths and tw is not None)
        return frozenset(normalized_paths), did_sync_refresh

    def _sync_planning_after_proposed_branch_destination_relocate(
        self, paths_to_refresh: set, *, old_path: str, new_path: str, table_refreshed: bool = False
    ) -> None:
        """After :meth:`_rewrite_proposed_branch_runtime_paths`, refresh source relationship state synchronously."""
        normalized = {self._canonical_source_projection_path(p) for p in (paths_to_refresh or set()) if p}
        normalized.discard("")
        self._invalidate_projection_lookup_caches(
            bump_generation=False,
            clear_source_path_cache=False,
            source_eviction_paths=normalized,
        )
        tw = getattr(self, "source_tree_widget", None)
        trace_updated = False
        if normalized and tw is not None:
            self._refresh_source_projection_for_paths(
                normalized,
                "proposed_branch_destination_relocate",
                trigger_path=sorted(normalized, key=len)[0],
            )
            trace_updated = True
        if tw is not None:
            tw.viewport().update()
        if is_dev_mode():
            log_info(
                "MOVEAUDIT",
                move_origin="proposed_branch_relocate",
                kind="proposed_branch_relocate",
                source_path="",
                old_destination_path=str(old_path or "")[:500],
                new_destination_path=str(new_path or "")[:500],
                affected_record_count=int(len(normalized)),
                planned_move_map_updated=True,
                source_traceability_updated=trace_updated,
                planned_moves_table_updated=bool(table_refreshed),
                execution_state_updated=True,
                descendant_count=0,
                incremental_lightweight=True,
            )

    def _pilot_norm_destination_identity(self, path: str) -> str:
        """Canonical destination path for pilot pickers (matches dialog _norm_identity_dir)."""
        p = str(path or "").strip()
        if not p:
            return ""
        canonical = self._canonical_destination_projection_path(p)
        if canonical:
            return canonical.rstrip("\\")
        return self.normalize_memory_path(p).rstrip("\\")

    def _pilot_planned_move_folder_identity(self, move: dict) -> str:
        """
        Folder bucket for pilot filtering: where the move lands in the destination tree.
        """
        if not isinstance(move, dict):
            return ""
        src = move.get("source") if isinstance(move.get("source"), dict) else {}
        is_folder = bool(src.get("is_folder", False))
        if is_folder:
            # Prefer allocation projection path for folder moves so allocated subfolders
            # (e.g. Root\Personal\100GOPRO) remain visible in the pilot picker.
            proj = str(self._allocation_projection_path(move) or "").strip()
            if proj:
                proj_norm = self.normalize_memory_path(proj.replace("/", "\\")).rstrip("\\")
                if proj_norm:
                    return self._pilot_norm_destination_identity(proj_norm)
            # Fallback: parent destination path + leaf folder name.
            dst_parent = self.normalize_memory_path(
                str(move.get("destination_path", "") or "").replace("/", "\\")
            ).rstrip("\\")
            leaf = str(
                move.get("destination_name", "")
                or self._move_target_name(move)
                or move.get("source_name", "")
                or src.get("name", "")
                or ""
            ).strip()
            if dst_parent and leaf:
                return self._pilot_norm_destination_identity(f"{dst_parent}\\{leaf}")
            if dst_parent:
                return self._pilot_norm_destination_identity(dst_parent)
        # For file moves, keep projection fallback and return parent folder identity.
        proj = str(self._allocation_projection_path(move) or "").strip()
        if not proj:
            return ""
        norm = self.normalize_memory_path(proj.replace("/", "\\")).rstrip("\\")
        parts = [seg for seg in norm.split("\\") if seg]
        if len(parts) <= 1:
            return ""
        parent_only = "\\".join(parts[:-1])
        return self._pilot_norm_destination_identity(parent_only)

    def _pilot_allocated_folder_matches_row(self, selected_allocated: str, row_folder_identity: str) -> bool:
        """
        True when a transfer row belongs under the selected allocated-folder filter.

        Rows should belong to the selected allocated folder (or deeper under it).
        Ancestor rows are not shown here; prerequisite ancestor folder-copy rows are
        injected later only when needed for execution ordering.
        """
        if not selected_allocated:
            return True
        if not row_folder_identity:
            return False
        na = self._pilot_norm_destination_identity(selected_allocated)
        nb = self._pilot_norm_destination_identity(row_folder_identity)
        if not na or not nb:
            return False
        if self._paths_equivalent(na, nb, "destination"):
            return True
        if self._path_is_descendant(nb, na, "destination"):
            return True
        return False

    def _unresolved_allocation_queue_size(self):
        data = getattr(self, "unresolved_allocations_by_parent_path", None) or {}
        return sum(len(entries) for entries in data.values())

    def _reset_unresolved_proposed_queue(self):
        prev_n = int(self._unresolved_proposed_queue_size() or 0)
        self.unresolved_proposed_by_parent_path = {}
        for proposed_folder in self.proposed_folders:
            self._queue_unresolved_proposed_folder(proposed_folder, "restore_payload_loaded")
        self._log_restore_phase(
            "unresolved_proposed_queue_reset",
            queue_size=self._unresolved_proposed_queue_size(),
            parent_count=len(self.unresolved_proposed_by_parent_path),
            previous_cleared_entries=prev_n,
            bulk_removal_reason=str(UnresolvedQueueRemovalReason.planning_memory_queue_rebuilt),
        )

    def _reset_unresolved_allocation_queue(self):
        prev_n = int(self._unresolved_allocation_queue_size() or 0)
        self.unresolved_allocations_by_parent_path = {}
        for move in self.planned_moves:
            self._queue_unresolved_allocation(move, "restore_payload_loaded")
        self._log_restore_phase(
            "unresolved_allocation_queue_reset",
            queue_size=self._unresolved_allocation_queue_size(),
            parent_count=len(self.unresolved_allocations_by_parent_path),
            previous_cleared_entries=prev_n,
            bulk_removal_reason=str(UnresolvedQueueRemovalReason.planning_memory_queue_rebuilt),
        )

    def _sync_restore_destination_overlay_pending_from_unresolved_queues(self) -> None:
        """True only while proposed/allocation overlay rows are still unresolved for replay."""
        self._restore_destination_overlay_pending = bool(
            self._unresolved_proposed_queue_size() or self._unresolved_allocation_queue_size()
        )

    def _destination_unresolved_overlay_parent_visibility_diag(self) -> dict[str, int]:
        """Lightweight scan: queued parent paths already visible vs not (read-only path lookup).

        - **not_visible** → likely still waiting on Graph / folder expansion / anchor chain.
        - **visible** with non-zero unresolved → parent row exists but bind/replay has not cleared the queue yet.
        """
        alloc_vis = alloc_miss = prop_vis = prop_miss = 0
        for pp in list((getattr(self, "unresolved_allocations_by_parent_path", None) or {}).keys()):
            pps = str(pp or "").strip()
            if not pps:
                continue
            hit = self._find_visible_destination_item_by_path(pps)
            if hit is not None and getattr(hit, "isValid", lambda: False)():
                alloc_vis += 1
            else:
                alloc_miss += 1
        for pp in list((getattr(self, "unresolved_proposed_by_parent_path", None) or {}).keys()):
            pps = str(pp or "").strip()
            if not pps:
                continue
            hit = self._find_visible_destination_item_by_path(pps)
            if hit is not None and getattr(hit, "isValid", lambda: False)():
                prop_vis += 1
            else:
                prop_miss += 1
        return {
            "allocation_parent_visible": alloc_vis,
            "allocation_parent_not_visible": alloc_miss,
            "proposed_parent_visible": prop_vis,
            "proposed_parent_not_visible": prop_miss,
        }

    def _queue_unresolved_proposed_folder(self, proposed_folder, reason):
        parent_path = self._proposed_parent_path(proposed_folder)
        if not parent_path:
            return
        inv, inv_reason = self._destination_unresolved_replay_parent_path_structurally_invalid(parent_path)
        if inv:
            try:
                cf = str(
                    self._canonical_planned_memory_path_for_graph_match(self.normalize_memory_path(str(parent_path)))
                    or ""
                ).casefold()
            except Exception:
                cf = self.normalize_memory_path(str(parent_path)).casefold()
            self._destination_remember_invalid_unresolved_parent_terminal(cf)
            log_info(
                "destination_unresolved_parent_pruned_invalid",
                unresolved_kind="proposed",
                parent_path_excerpt=str(parent_path or "")[:400],
                invalid_reason=str(inv_reason or "")[:120],
                context="enqueue_blocked",
                bucket_entries_removed=0,
                move_or_request_excerpt=str(getattr(proposed_folder, "DestinationPath", "") or "")[:120],
                removal_reason=str(UnresolvedQueueRemovalReason.pruned_invalid_parent_structure),
            )
            return
        if self._destination_invalid_unresolved_parent_previously_pruned(parent_path):
            return
        bucket = self.unresolved_proposed_by_parent_path.setdefault(parent_path, {})
        bucket[self._proposed_folder_key(proposed_folder)] = proposed_folder
        self._log_restore_phase(
            "unresolved_proposed_parent_queued",
            reason=reason,
            parent_path=parent_path,
            destination_path=self._proposed_destination_path(proposed_folder),
            queue_size=self._unresolved_proposed_queue_size(),
            verbose=True,
        )

    def _queue_unresolved_allocation(self, move, reason):
        parent_path = self._allocation_parent_path(move)
        if not parent_path:
            return
        inv, inv_reason = self._destination_unresolved_replay_parent_path_structurally_invalid(parent_path)
        if inv:
            try:
                cf = str(
                    self._canonical_planned_memory_path_for_graph_match(self.normalize_memory_path(str(parent_path)))
                    or ""
                ).casefold()
            except Exception:
                cf = self.normalize_memory_path(str(parent_path)).casefold()
            self._destination_remember_invalid_unresolved_parent_terminal(cf)
            _mid = ""
            if isinstance(move, dict):
                _mid = str(move.get("request_id") or move.get("allocation_id") or move.get("move_id") or "")[:120]
            log_info(
                "destination_unresolved_parent_pruned_invalid",
                unresolved_kind="allocation",
                parent_path_excerpt=str(parent_path or "")[:400],
                invalid_reason=str(inv_reason or "")[:120],
                context="enqueue_blocked",
                bucket_entries_removed=0,
                move_or_request_excerpt=_mid,
                removal_reason=str(UnresolvedQueueRemovalReason.pruned_invalid_parent_structure),
            )
            return
        if self._destination_invalid_unresolved_parent_previously_pruned(parent_path):
            return
        bucket = self.unresolved_allocations_by_parent_path.setdefault(parent_path, {})
        bucket[self._allocation_move_key(move)] = move
        self._log_restore_phase(
            "unresolved_allocation_parent_queued",
            reason=reason,
            parent_path=parent_path,
            destination_path=self._allocation_projection_path(move),
            queue_size=self._unresolved_allocation_queue_size(),
            verbose=True,
        )

    def _unresolved_overlay_pass_audit_begin(self, pass_name: str) -> None:
        self._unresolved_overlay_pass_audit = {
            "pass": pass_name,
            "unresolved_prop_before": int(self._unresolved_proposed_queue_size() or 0),
            "unresolved_alloc_before": int(self._unresolved_allocation_queue_size() or 0),
            "visible_future_before": int(self._count_visible_destination_future_state_nodes() or 0),
            "removals_by_reason": Counter(),
            "illegal_count": 0,
        }

    def _unresolved_overlay_pass_audit_touch_illegal(self) -> None:
        snap = getattr(self, "_unresolved_overlay_pass_audit", None)
        if isinstance(snap, dict):
            snap["illegal_count"] = int(snap.get("illegal_count", 0) or 0) + 1

    def _unresolved_overlay_pass_audit_touch_removal(self, reason: UnresolvedQueueRemovalReason) -> None:
        snap = getattr(self, "_unresolved_overlay_pass_audit", None)
        if isinstance(snap, dict):
            c = snap.get("removals_by_reason")
            if isinstance(c, Counter):
                c[str(reason)] += 1

    def _unresolved_overlay_pass_audit_finish_replay(
        self, pass_name: str, *, applied_count: int, reason: str, trigger_path: str
    ) -> None:
        snap = getattr(self, "_unresolved_overlay_pass_audit", None)
        if not isinstance(snap, dict) or snap.get("pass") != pass_name:
            return
        vis_after = int(self._count_visible_destination_future_state_nodes() or 0)
        prop_b = int(snap.get("unresolved_prop_before", 0) or 0)
        alloc_b = int(snap.get("unresolved_alloc_before", 0) or 0)
        prop_a = int(self._unresolved_proposed_queue_size() or 0)
        alloc_a = int(self._unresolved_allocation_queue_size() or 0)
        illegal = int(snap.get("illegal_count", 0) or 0)
        removals = snap.get("removals_by_reason")
        removal_dict = dict(removals) if isinstance(removals, Counter) else {}
        vis_b = int(snap.get("visible_future_before", 0) or 0)
        offenders: list[str] = []
        if illegal:
            offenders = list(self._destination_planning_overlay_targets_missing_visible_evidence())[:8]
        self._log_restore_phase(
            "destination_unresolved_overlay_pass_audit",
            pass_name=pass_name,
            replay_reason=str(reason or "")[:200],
            trigger_path_excerpt=str(self.normalize_memory_path(trigger_path or ""))[:240],
            unresolved_proposed_before=prop_b,
            unresolved_allocation_before=alloc_b,
            unresolved_proposed_after=prop_a,
            unresolved_allocation_after=alloc_a,
            unresolved_delta_total=(prop_b + alloc_b) - (prop_a + alloc_a),
            visible_future_branch_count_before=vis_b,
            visible_future_branch_count_after=vis_after,
            visible_future_branch_delta=vis_after - vis_b,
            replay_applied_child_ops=int(applied_count or 0),
            queue_removals_by_reason=removal_dict,
            illegal_resolution_without_visible_outcome_count=illegal,
            planning_target_miss_samples=offenders,
        )
        self._unresolved_overlay_pass_audit = None

    def _unresolved_overlay_target_paths_equivalent(self, path_a: str, path_b: str) -> bool:
        aa = self._canonical_destination_projection_path(path_a) or self.normalize_memory_path(path_a)
        bb = self._canonical_destination_projection_path(path_b) or self.normalize_memory_path(path_b)
        if not aa or not bb:
            return False
        if aa.casefold() == bb.casefold():
            return True
        if destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            aa2 = self._canonical_destination_path_with_visible_library_anchor(aa)
            bb2 = self._canonical_destination_path_with_visible_library_anchor(bb)
            if aa2.casefold() == bb2.casefold():
                return True
            if aa.casefold() == bb2.casefold() or bb.casefold() == aa2.casefold():
                return True
        return False

    def _unresolved_overlay_visible_live_row_kind(self, node_data: dict) -> tuple[str, bool, bool]:
        """Return ``(row_kind_label, visible_meaningful_row, is_live_graph)``."""
        if not isinstance(node_data, dict) or node_data.get("placeholder"):
            return ("none", False, False)
        live = destination_payload_is_live_graph_row(node_data)
        is_folder = bool(node_data.get("is_folder", True))
        if live:
            return (("live_folder" if is_folder else "live_file"), True, True)
        if destination_payload_is_planned_workspace_row(node_data):
            return (str(node_data.get("row_kind") or ("planned_folder" if is_folder else "planned_file")), True, False)
        if bool(node_data.get("non_graph_structural_authority")) and (
            self.node_is_planned_allocation(node_data) or self.node_is_proposed(node_data)
        ):
            return ("workspace_overlay", True, False)
        if self.node_is_planned_allocation(node_data) or self.node_is_proposed(node_data):
            return ("legacy_planned_overlay", True, False)
        return ("real_non_live", True, False)

    def _unresolved_overlay_verify_proposed_outcome(self, outcome_ix: QModelIndex, expected_target_canonical: str) -> bool:
        if outcome_ix is None or not isinstance(outcome_ix, QModelIndex) or not outcome_ix.isValid():
            return False
        if not expected_target_canonical:
            return False
        try:
            dm = getattr(self, "destination_planning_model", None)
            if dm is not None and hasattr(dm, "is_index_live") and not dm.is_index_live(outcome_ix):
                return False
        except RuntimeError:
            return False
        nd = self._destination_model_index_user_role_dict(outcome_ix)
        if not nd:
            return False
        sem = self._destination_row_semantic_path(nd)
        if not self._unresolved_overlay_target_paths_equivalent(sem, expected_target_canonical):
            return False
        return bool(self.node_is_proposed(nd))

    def _unresolved_overlay_verify_allocation_outcome(self, outcome_ix: QModelIndex, expected_target_canonical: str) -> bool:
        if outcome_ix is None or not isinstance(outcome_ix, QModelIndex) or not outcome_ix.isValid():
            return False
        if not expected_target_canonical:
            return False
        try:
            dm = getattr(self, "destination_planning_model", None)
            if dm is not None and hasattr(dm, "is_index_live") and not dm.is_index_live(outcome_ix):
                return False
        except RuntimeError:
            return False
        nd = self._destination_model_index_user_role_dict(outcome_ix)
        if not nd:
            return False
        sem = self._destination_row_semantic_path(nd)
        if not self._unresolved_overlay_target_paths_equivalent(sem, expected_target_canonical):
            return False
        return bool(self.node_is_planned_allocation(nd))

    def _log_unresolved_queue_removal_event(
        self,
        *,
        queue_type: str,
        removal_reason: UnresolvedQueueRemovalReason,
        parent_path: str,
        target_canonical_path: str,
        request_id: str,
        outcome_ix: QModelIndex | None,
        illegal: bool,
    ) -> None:
        vis = live = False
        rk = "none"
        if outcome_ix is not None and isinstance(outcome_ix, QModelIndex) and outcome_ix.isValid():
            nd = self._destination_model_index_user_role_dict(outcome_ix)
            rk, vis, live = self._unresolved_overlay_visible_live_row_kind(nd)
        phase = (
            "unresolved_queue_illegal_resolution"
            if illegal or removal_reason == UnresolvedQueueRemovalReason.illegal_resolution_without_visible_outcome
            else "unresolved_queue_removal"
        )
        self._log_restore_phase(
            phase,
            queue_type=str(queue_type or "")[:32],
            removal_reason=str(removal_reason),
            parent_path_excerpt=str(parent_path or "")[:260],
            target_canonical_path_excerpt=str(target_canonical_path or "")[:260],
            request_id_excerpt=str(request_id or "")[:120],
            visible_row_observed=bool(vis),
            live_graph_row_observed=bool(live),
            row_kind=str(rk),
            illegal_resolution_without_visible_outcome=bool(illegal),
            verbose=True,
        )

    def _destination_find_planning_index_for_overlay_target_path(
        self, path_hint: str, *, for_planned_workspace_reconcile: bool = False
    ):
        """Resolve a destination planning QModelIndex using the same canonical keys as visible lookup.

        When ``for_planned_workspace_reconcile`` is True under Graph authority, a missing row schedules
        real Graph folder loads along the canonical path and registers the parent for reconcile when
        the folder appears (see :meth:`_destination_try_reconcile_pending_planned_parents_after_folder_load`).
        """
        dm = getattr(self, "destination_planning_model", None)
        if dm is None or not str(path_hint or "").strip():
            return None
        norm = self._materialize_cached_destination_lookup_norm(str(path_hint).strip())
        keys, _ = self._destination_visible_path_lookup_canonical_keys_ex(path_hint, norm)
        for ck in keys:
            if not ck:
                continue
            try:
                ixs = dm.find_indices_for_canonical_destination_path(ck)
            except Exception:
                ixs = []
            for ix in ixs:
                if ix is None or not ix.isValid():
                    continue
                try:
                    if hasattr(dm, "is_index_live") and not dm.is_index_live(ix):
                        continue
                except RuntimeError:
                    continue
                return ix
        if for_planned_workspace_reconcile and destination_authority_contract.graph_owns_visible_real_destination_structure(
            self
        ):
            if self._destination_stored_planned_workspace_snapshot_node_count_for_parent(path_hint) == 0:
                return None
            pck = self._destination_planned_reconcile_parent_canonical_key(path_hint)
            if pck:
                pend = getattr(self, "_destination_pending_planned_reconcile_parent_paths", None)
                if not isinstance(pend, set):
                    self._destination_pending_planned_reconcile_parent_paths = set()
                    pend = self._destination_pending_planned_reconcile_parent_paths
                pend.add(pck)
            self._destination_request_graph_destination_children_load_for_path(
                str(path_hint or "").strip(),
                reason="planned_reconcile_parent_not_in_model",
            )
            log_info(
                "destination_planned_reconcile_parent_deferred_graph_load",
                parent_path=str(norm or path_hint or "")[:400],
                pending_registered=bool(pck),
            )
        return None

    def _destination_planning_overlay_targets_missing_visible_evidence(self) -> list[str]:
        """Planning-memory projection targets without a visible row showing the expected overlay."""
        if not destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            return []
        missing: list[str] = []
        seen: set[str] = set()

        def _note(path_hint: str) -> None:
            c = self._canonical_destination_projection_path(path_hint) or self.normalize_memory_path(path_hint)
            ck = c.casefold()
            if c and ck not in seen:
                seen.add(ck)
                missing.append(c)

        def _ix_for_overlay_candidate(cand: str):
            ix = self._find_visible_destination_item_by_path(cand)
            if ix is not None and ix.isValid():
                return ix
            return self._destination_find_planning_index_for_overlay_target_path(cand)

        for move in self.planned_moves or []:
            if not isinstance(move, dict):
                continue
            ap = self._allocation_projection_path(move)
            if not ap:
                continue
            anchored = self._canonical_destination_path_with_visible_library_anchor(ap)
            ok = False
            for cand in (anchored, ap):
                if not cand:
                    continue
                ix = _ix_for_overlay_candidate(cand)
                if ix is None or not ix.isValid():
                    continue
                if self._unresolved_overlay_verify_allocation_outcome(ix, cand):
                    ok = True
                    break
            if not ok:
                _note(anchored or ap)

        for pf in self.proposed_folders or []:
            dest = self._proposed_destination_path(pf)
            if not dest:
                continue
            anchored = self._canonical_destination_path_with_visible_library_anchor(dest)
            ok = False
            for cand in (anchored, dest):
                if not cand:
                    continue
                ix = _ix_for_overlay_candidate(cand)
                if ix is None or not ix.isValid():
                    continue
                if self._unresolved_overlay_verify_proposed_outcome(ix, cand):
                    ok = True
                    break
            if not ok:
                _note(anchored or dest)

        return missing

    def _find_destination_child_by_allocation_exact_semantic_path(self, parent_ix: QModelIndex, lookup_path: str):
        if parent_ix is None or not isinstance(parent_ix, QModelIndex) or not parent_ix.isValid() or not lookup_path:
            return None
        model = getattr(self, "destination_planning_model", None)
        if model is None:
            return None
        want = self._canonical_destination_projection_path(lookup_path) or self.normalize_memory_path(lookup_path)
        want_cf = want.casefold()
        if not want_cf:
            return None
        for r in range(model.rowCount(parent_ix)):
            ix = model.index(r, 0, parent_ix)
            nd = self._destination_model_index_user_role_dict(ix)
            if nd.get("placeholder"):
                continue
            sem = self._destination_row_semantic_path(nd)
            got = self._canonical_destination_projection_path(sem) or self.normalize_memory_path(sem)
            if got.casefold() == want_cf:
                return ix
        return None

    def _quick_apply_allocated_node_under_parent(self, move):
        """Attach projected allocation under its destination parent without a full future-model rebuild."""
        if not isinstance(move, dict):
            return 0
        parent_path = self._allocation_parent_path(move)
        if not parent_path:
            return 0
        try:
            parent_item = None
            with _PerfExplorerTimer("quick_apply_allocated_node", step="ensure_parent"):
                parent_item = self._ensure_destination_projection_path(parent_path)
            if parent_item is None:
                return 0
            with _PerfExplorerTimer("quick_apply_allocated_node", step="apply_children"):
                return self._apply_allocation_children_to_item(parent_item)
        except Exception as exc:
            self._log_restore_exception("quick_apply_allocated_node_under_parent", exc)
            return 0

    def _register_and_project_planned_move(self, move, *, reason="planned_move"):
        with _PerfExplorerTimer("register_and_project_planned_move", subreason=str(reason or "")):
            self._queue_unresolved_allocation(move, reason)
            return self._quick_apply_allocated_node_under_parent(move)

    def _defer_destination_projection_if_quick_apply_failed(self, applied, *, reconcile_reason, delay_ms=120):
        if applied and int(applied) > 0:
            return
        self._schedule_deferred_destination_materialization(reconcile_reason, delay_ms=delay_ms)

    def _take_destination_tree_item(self, item):
        tree = getattr(self, "destination_tree_widget", None)
        if tree is None or item is None:
            return
        parent = item.parent()
        if parent is not None:
            parent.removeChild(item)
            self._refresh_destination_item_visibility(parent, expand=False)
        else:
            ix = tree.indexOfTopLevelItem(item)
            if ix >= 0:
                tree.takeTopLevelItem(ix)

    def _destination_tree_item_matches_move(self, item, move):
        if item is None or not isinstance(move, dict):
            return False
        if isinstance(item, QModelIndex):
            d = item.data(Qt.UserRole) or {}
        else:
            d = item.data(0, Qt.UserRole) or {}
        ms = self._canonical_source_projection_path(move.get("source_path", ""))
        ns = self._canonical_source_projection_path(d.get("source_path", ""))
        if ms and ns and ms.casefold() == ns.casefold():
            return True
        src = move.get("source") if isinstance(move.get("source"), dict) else {}
        mid = str(src.get("id", "") or "").strip()
        if mid and mid == str(d.get("source_item_id", "") or "").strip():
            return True
        return False

    def _remove_planned_allocation_projection_children(self, parent_item):
        if parent_item is None:
            return
        index = parent_item.childCount() - 1
        while index >= 0:
            child = parent_item.child(index)
            d = child.data(0, Qt.UserRole) or {}
            cid = str(d.get("id", "") or "")
            legacy_alloc = cid.lower().startswith("allocated::") or cid.lower().startswith(
                "allocated-descendant::"
            )
            if d.get("planned_allocation_descendant") or cid.lower().startswith("allocated-descendant::"):
                parent_item.takeChild(index)
            elif legacy_alloc and self.node_is_planned_allocation(d):
                parent_item.takeChild(index)
            elif (
                not cid
                and d.get("non_graph_structural_authority")
                and self.node_is_planned_allocation(d)
            ):
                parent_item.takeChild(index)
            index -= 1

    def _strip_planned_allocation_overlay_for_move(self, item, move):
        if item is None or not isinstance(move, dict):
            return
        node_data = dict(item.data(0, Qt.UserRole) or {})
        dest = move.get("destination") if isinstance(move.get("destination"), dict) else {}
        for key in ("display_path", "item_path", "destination_path"):
            v = dest.get(key)
            if v:
                node_data[key] = v
        node_data.pop("planned_allocation", None)
        node_data["node_origin"] = "Real"
        node_data.pop("overlay_state", None)
        name = str(node_data.get("real_name") or node_data.get("name", "") or "").strip() or "Item"
        base_label = self._tree_name_column_label(name)
        node_data["base_display_label"] = base_label
        item.setData(0, Qt.UserRole, node_data)
        self._apply_tree_item_visual_state(item, node_data)
        self._refresh_destination_item_visibility(item)

    def _strip_planned_allocation_overlay_model_index(self, ix, move):
        if ix is None or not isinstance(ix, QModelIndex) or not ix.isValid() or not isinstance(move, dict):
            return
        model = getattr(self, "destination_planning_model", None)
        if model is None:
            return
        node_data = dict(ix.data(Qt.UserRole) or {})
        dest = move.get("destination") if isinstance(move.get("destination"), dict) else {}
        for key in ("display_path", "item_path", "destination_path"):
            v = dest.get(key)
            if v:
                node_data[key] = v
        node_data.pop("planned_allocation", None)
        node_data["node_origin"] = "Real"
        node_data.pop("overlay_state", None)
        name = str(node_data.get("real_name") or node_data.get("name", "") or "").strip() or "Item"
        base_label = self._tree_name_column_label(name)
        node_data["base_display_label"] = base_label

        def _m(p):
            p.clear()
            p.update(node_data)

        model.update_payload_for_index(ix, _m)
        self._apply_tree_item_visual_state(None, node_data)
        self._refresh_destination_item_visibility_index(ix)

    def _quick_remove_planned_move_from_destination_tree(self, move):
        """Remove or unmark the visible destination projection for one planned move (no full tree bind)."""
        with _PerfExplorerTimer("quick_remove_planned_move_from_destination_tree"):
            if not isinstance(move, dict):
                return 0
            self._mark_allocation_resolved(
                move,
                reason=UnresolvedQueueRemovalReason.removed_from_tree_user_action,
                verify_visible_outcome=False,
            )
            parent_path = self._allocation_parent_path(move)
            child = None
            parent_item = self._find_visible_destination_item_by_path(parent_path) if parent_path else None
            if parent_item is not None:
                child = self._find_destination_child_by_allocation_equivalence(parent_item, move)
            if child is None:
                proj = self._allocation_projection_path(move)
                if proj:
                    child = self._find_visible_destination_item_by_path(proj)
            if child is None:
                return 0
            if not self._destination_tree_item_matches_move(child, move):
                node_data_probe = self.get_tree_item_node_data(child) or {}
                alloc = self._canonical_destination_projection_path(self._allocation_projection_path(move))
                ip = self._canonical_destination_projection_path(self._tree_item_path(node_data_probe))
                if not (
                    alloc
                    and ip
                    and ip == alloc
                    and (
                        self.node_is_planned_allocation(node_data_probe)
                        or bool(node_data_probe.get("planned_allocation"))
                    )
                ):
                    return 0
            node_data = self.get_tree_item_node_data(child) or {}
            cid = str(node_data.get("id", "") or "")
            overlay_only_alloc = (
                self.node_is_planned_allocation(node_data)
                and bool(node_data.get("non_graph_structural_authority"))
                and not cid
            ) or (cid.lower().startswith("allocated::") and self.node_is_planned_allocation(node_data))
            if isinstance(child, QModelIndex):
                model = getattr(self, "destination_planning_model", None)
                if overlay_only_alloc:
                    if model is not None:
                        model.remove_node_at(child)
                        return 1
                    return 0
                if self.node_is_planned_allocation(node_data):
                    if bool(node_data.get("is_folder")) and model is not None:
                        while model.rowCount(child) > 0:
                            ch = model.index(0, 0, child)
                            if not ch.isValid():
                                break
                            model.remove_node_at(ch)
                    self._strip_planned_allocation_overlay_model_index(child, move)
                    return 1
                return 0
            return 0

    def _mark_proposed_folder_resolved(
        self,
        proposed_folder,
        *,
        reason: UnresolvedQueueRemovalReason = UnresolvedQueueRemovalReason.bound_planned_chain_visible,
        outcome_ix: QModelIndex | None = None,
        expected_target_canonical: str = "",
        verify_visible_outcome: bool = True,
    ) -> bool:
        parent_path = self._proposed_parent_path(proposed_folder)
        prop_key = self._proposed_folder_key(proposed_folder)
        rid = str(prop_key or "")[:200]
        target_hint = expected_target_canonical or self._proposed_destination_path(proposed_folder)
        if verify_visible_outcome:
            ok = self._unresolved_overlay_verify_proposed_outcome(outcome_ix, expected_target_canonical)
            if not ok:
                self._unresolved_overlay_pass_audit_touch_illegal()
                self._log_unresolved_queue_removal_event(
                    queue_type="proposed",
                    removal_reason=UnresolvedQueueRemovalReason.illegal_resolution_without_visible_outcome,
                    parent_path=parent_path,
                    target_canonical_path=target_hint,
                    request_id=rid,
                    outcome_ix=outcome_ix,
                    illegal=True,
                )
                return False
        bucket = self.unresolved_proposed_by_parent_path.get(parent_path, {})
        bucket.pop(self._proposed_folder_key(proposed_folder), None)
        if not bucket and parent_path in self.unresolved_proposed_by_parent_path:
            self.unresolved_proposed_by_parent_path.pop(parent_path, None)
        self._sync_restore_destination_overlay_pending_from_unresolved_queues()
        self._unresolved_overlay_pass_audit_touch_removal(reason)
        self._log_unresolved_queue_removal_event(
            queue_type="proposed",
            removal_reason=reason,
            parent_path=parent_path,
            target_canonical_path=target_hint,
            request_id=rid,
            outcome_ix=outcome_ix,
            illegal=False,
        )
        return True

    def _mark_allocation_resolved(
        self,
        move,
        *,
        reason: UnresolvedQueueRemovalReason = UnresolvedQueueRemovalReason.bound_planned_chain_visible,
        outcome_ix: QModelIndex | None = None,
        expected_target_canonical: str = "",
        verify_visible_outcome: bool = True,
    ) -> bool:
        if not isinstance(move, dict):
            return False
        parent_path = self._allocation_parent_path(move)
        req = str(move.get("request_id") or move.get("allocation_id") or "").strip()[:120]
        alloc_path = self._allocation_projection_path(move)
        target_hint = expected_target_canonical or alloc_path
        if verify_visible_outcome:
            ok = self._unresolved_overlay_verify_allocation_outcome(outcome_ix, expected_target_canonical)
            if not ok:
                self._unresolved_overlay_pass_audit_touch_illegal()
                self._log_unresolved_queue_removal_event(
                    queue_type="allocation",
                    removal_reason=UnresolvedQueueRemovalReason.illegal_resolution_without_visible_outcome,
                    parent_path=parent_path,
                    target_canonical_path=target_hint,
                    request_id=req,
                    outcome_ix=outcome_ix,
                    illegal=True,
                )
                return False
        bucket = self.unresolved_allocations_by_parent_path.get(parent_path, {})
        bucket.pop(self._allocation_move_key(move), None)
        if not bucket and parent_path in self.unresolved_allocations_by_parent_path:
            self.unresolved_allocations_by_parent_path.pop(parent_path, None)
        self._sync_restore_destination_overlay_pending_from_unresolved_queues()
        self._unresolved_overlay_pass_audit_touch_removal(reason)
        self._log_unresolved_queue_removal_event(
            queue_type="allocation",
            removal_reason=reason,
            parent_path=parent_path,
            target_canonical_path=target_hint,
            request_id=req,
            outcome_ix=outcome_ix,
            illegal=False,
        )
        return True

    def _get_unresolved_candidates_for_parent(self, parent_path):
        matches = []
        for stored_parent_path, bucket in self.unresolved_proposed_by_parent_path.items():
            if self._paths_equivalent(stored_parent_path, parent_path, "destination"):
                matches.extend(bucket.values())
        return matches

    def _get_unresolved_allocation_candidates_for_parent(self, parent_path):
        matches = []
        for stored_parent_path, bucket in self.unresolved_allocations_by_parent_path.items():
            if self._paths_equivalent(stored_parent_path, parent_path, "destination"):
                matches.extend(bucket.values())
        return matches

    def _allocation_parent_candidates_for_touch_paths(self, touch_paths):
        """Unresolved allocation parents that are the touch path itself or a strict ancestor of it."""
        out = set()
        raw = [p for p in touch_paths if p]
        if not raw:
            return out
        for sp in list(self.unresolved_allocations_by_parent_path.keys()):
            sp_c = self._canonical_destination_projection_path(self.normalize_memory_path(sp)) or self.normalize_memory_path(
                sp
            )
            sp_cf = sp_c.casefold()
            for tp in raw:
                tp_c = self._canonical_destination_projection_path(self.normalize_memory_path(tp)) or self.normalize_memory_path(
                    tp
                )
                tp_cf = tp_c.casefold()
                if self._paths_equivalent(sp, tp, "destination"):
                    out.add(sp)
                    break
                if tp_cf.startswith(sp_cf + "\\") or tp_cf == sp_cf:
                    out.add(sp)
                    break
        return out

    def _reapply_allocation_overlays_for_paste_touch_paths(self, old_p, new_p, target_path):
        """Re-apply allocation overlays for every unresolved parent affected by a paste move (quick path)."""
        touch = (old_p, new_p, target_path)
        candidates = self._allocation_parent_candidates_for_touch_paths(touch)
        if not candidates:
            return 0, {}

        def _sort_key(s):
            s_c = self.normalize_memory_path(s)
            return (len([x for x in s_c.split("\\") if x]), s_c.casefold())

        total = 0
        per = {}
        for sp in sorted(candidates, key=_sort_key):
            try:
                with _PerfExplorerTimer("paste_touch_reapply", parent_path=str(sp)[:120]):
                    parent_item = self._ensure_destination_projection_path(sp)
                    if parent_item is None:
                        per[str(sp)[:200]] = 0
                        continue
                    n = self._apply_allocation_children_to_item(parent_item)
                    total += n
                    per[str(sp)[:200]] = n
            except Exception as exc:
                self._log_restore_exception("reapply_allocation_overlays_for_paste_touch_paths", exc)
                per[str(sp)[:200]] = 0
        return total, per

    def _dev_paste_allocation_badge_row(self, path_hint):
        if not path_hint:
            return None
        proj = self._canonical_destination_projection_path(self.normalize_memory_path(path_hint)) or self.normalize_memory_path(
            path_hint
        )
        ix = self._find_visible_destination_item_by_path(proj)
        if ix is None:
            return {"path": proj[:160], "visible": False}
        if isinstance(ix, QModelIndex):
            nd = dict(ix.data(Qt.UserRole) or {})
        else:
            nd = dict(ix.data(0, Qt.UserRole) or {})
        label = str(nd.get("base_display_label", nd.get("name", "")) or "")
        return {
            "path": proj[:160],
            "visible": True,
            "planned_allocation": bool(nd.get("planned_allocation")),
            "node_origin": str(nd.get("node_origin", "") or "")[:48],
            "has_allocated_tag": "[Allocated]" in label,
            "label_excerpt": label[:72],
        }

    def _tree_item_path(self, node_data):
        return self.normalize_memory_path(
            node_data.get("display_path")
            or node_data.get("item_path")
            or node_data.get("source_path")
            or node_data.get("destination_path")
            or ""
        )

    def _destination_row_raw_path_for_path_lookup_match(self, node_data):
        """Raw path aligned with :meth:`_destination_payload_index_raw_mem` for live Graph rows.

        :meth:`_tree_item_path` prefers ``display_path`` (human ``site / library / …``), which often
        does not canonicalize to the same segments as planning memory or the path index; overlay
        resolution must compare against ``item_path`` / ``destination_path`` for Graph-backed rows.
        """
        if not isinstance(node_data, dict):
            return ""
        if destination_authority_contract.graph_owns_visible_real_destination_structure(
            self
        ) and destination_payload_is_live_graph_row(node_data):
            raw = str(
                node_data.get("item_path")
                or node_data.get("destination_path")
                or ""
            ).strip()
            if raw:
                return self.normalize_memory_path(raw)
        return self._tree_item_path(node_data)

    def _destination_row_semantic_path(self, node_data):
        """Canonical planning path for a destination row (overlays, child cache, Graph walks).

        For live Graph-backed rows, drive ``item_path`` must drive canonicalization — the same
        basis as :meth:`_destination_payload_index_raw_mem`. :meth:`_tree_item_path` prefers
        human ``display_path``, which often disagrees and broke sibling maps and parent walks.
        """
        if not isinstance(node_data, dict):
            return ""
        raw = self._destination_row_raw_path_for_path_lookup_match(node_data)
        return self._canonical_destination_projection_path(raw) or self.normalize_memory_path(raw)

    def _log_destination_action_target(self, action: str, *, selected_semantic_path: str, resolved_target_path: str, **extra):
        if not is_dev_mode():
            return
        log_info(
            "destination_action_target",
            action=action,
            selected_semantic_path=selected_semantic_path or "",
            resolved_target_path=resolved_target_path or "",
            **extra,
        )

    def _resolve_tree_item_drive_id(self, panel_key, node_data):
        """Drive id for Graph folder loads: prefer the row's drive/library id, then the panel root."""
        if not isinstance(node_data, dict):
            return ""
        pending_roots = getattr(self, "pending_root_drive_ids", None) or {}
        return (
            str(node_data.get("drive_id") or node_data.get("library_id") or "").strip()
            or str(pending_roots.get(panel_key, "") or "").strip()
        )

    def _proposed_folder_exists_under(self, parent_item, destination_path):
        normalized_target = self.normalize_memory_path(destination_path)
        if isinstance(parent_item, QModelIndex):
            model = getattr(self, "destination_planning_model", None)
            if model is None:
                return False
            for r in range(model.rowCount(parent_item)):
                ix = model.index(r, 0, parent_item)
                child_data = ix.data(Qt.UserRole) or {}
                child_path = child_data.get("item_path") or child_data.get("display_path") or ""
                if self._paths_equivalent(child_path, normalized_target, "destination"):
                    return True
            return False
        return False

    def _build_proposed_payload(self, proposed_folder: ProposedFolder, parent_data):
        parent_path = self._tree_item_path(parent_data)
        destination_path = (
            self._canonical_destination_projection_path(f"{parent_path}\\{proposed_folder.FolderName}")
            if parent_path
            else self._canonical_destination_projection_path(proposed_folder.DestinationPath)
        )
        destination_path = destination_path or self.normalize_memory_path(proposed_folder.DestinationPath)
        base_label = self._tree_name_column_label(proposed_folder.FolderName, tag="(Proposed)")
        gid = graph_item_id_field(proposed_folder.DestinationId)
        _psk = self._ensure_proposed_folder_stable_key(proposed_folder)
        node_data = {
            "id": gid,
            "graph_item_id": gid,
            "overlay_node_id": new_overlay_node_id("proposed", destination_path),
            "name": proposed_folder.FolderName,
            "real_name": proposed_folder.FolderName,
            "display_path": destination_path,
            "item_path": destination_path,
            "destination_path": destination_path,
            "tree_role": "destination",
            "drive_id": parent_data.get("drive_id", ""),
            "site_id": parent_data.get("site_id", ""),
            "site_name": parent_data.get("site_name", ""),
            "library_id": parent_data.get("library_id", ""),
            "library_name": parent_data.get("library_name", ""),
            "is_folder": True,
            "children_loaded": True,
            "load_failed": False,
            "node_origin": "Proposed",
            "proposed": True,
            "web_url": parent_data.get("web_url", ""),
            "base_display_label": base_label,
            **overlay_row_marker("proposed"),
        }
        if _psk:
            node_data["proposed_folder_stable_id"] = _psk
        self._apply_tree_item_visual_state(None, node_data)
        return node_data

    def _destination_forensic_planned_item_materialization_logging_enabled(self) -> bool:
        raw = str(os.getenv("OZLINK_DESTINATION_FORENSIC_PLANNED_ITEM_BIND", "") or "").strip().lower()
        if raw in {"1", "true", "yes", "on"}:
            return True
        return is_dev_mode()

    def _forensic_count_unresolved_proposed_for_parent(self, parent_path: str) -> int:
        n = 0
        for stored, bucket in (getattr(self, "unresolved_proposed_by_parent_path", None) or {}).items():
            if self._paths_equivalent(stored, parent_path, "destination"):
                n += len(bucket)
        return n

    def _rebuild_planned_file_parent_index_for_overlay_pass(self) -> None:
        """One O(moves) pass: canonical parent -> planned file destination paths (overlay pass scope)."""
        idx: dict[str, list[str]] = {}
        rows = 0
        for move in self.planned_moves or []:
            if not isinstance(move, dict):
                continue
            if not self._planned_move_terminal_is_file_leaf(move):
                continue
            dest_raw = str(move.get("destination_path") or "").strip()
            if not dest_raw:
                continue
            dest_full = self._canonical_planned_memory_path_for_graph_match(dest_raw)
            segs = self._path_segments(dest_full)
            if len(segs) < 2:
                continue
            parent_dest = "\\".join(segs[:-1])
            parent_full = self._canonical_planned_memory_path_for_graph_match(parent_dest)
            key = parent_full.casefold()
            idx.setdefault(key, []).append(dest_full)
            rows += 1
        self._planned_file_children_by_parent_cf = idx
        self._planned_file_parent_index_build_row_count = rows
        self._planned_file_parent_index_build_distinct_parent_keys = len(idx)

    def _forensic_planned_file_destination_paths_under_folder_full_scan(self, f_raw: str) -> list[str]:
        """Full scan over ``planned_moves`` (fallback when parent index is not built). ``f_raw`` non-empty."""
        out: list[str] = []
        f_norm = self._canonical_planned_memory_path_for_graph_match(f_raw)
        f_cf = f_norm.casefold()
        fen = self._destination_forensic_planned_item_materialization_logging_enabled()
        br = self._destination_forensic_canon_diff_branch_hit(f_raw)
        move_n = len(self.planned_moves or [])
        nm_cap = 96
        nm_shown = 0
        for move in self.planned_moves or []:
            if not isinstance(move, dict):
                continue
            is_folder_move = not self._planned_move_terminal_is_file_leaf(move)
            dest_raw = str(move.get("destination_path") or "").strip()
            mismatch_reason = ""
            matched = False
            dest_full = ""
            parent_full = ""
            if is_folder_move:
                mismatch_reason = "source_is_folder_not_file_move"
            elif not dest_raw:
                mismatch_reason = "empty_destination_path"
            else:
                dest_full = self._canonical_planned_memory_path_for_graph_match(dest_raw)
                segs = self._path_segments(dest_full)
                if len(segs) < 2:
                    mismatch_reason = "destination_has_fewer_than_two_segments_after_canon"
                else:
                    parent_dest = "\\".join(segs[:-1])
                    parent_full = self._canonical_planned_memory_path_for_graph_match(parent_dest)
                    p_cf = parent_full.casefold()
                    if p_cf == f_cf:
                        matched = True
                    else:
                        mismatch_reason = "derived_parent_graph_canon_mismatch_vs_visited_folder"
            if matched:
                out.append(dest_full)
            if fen:
                log_probe = bool(
                    matched or move_n <= 64 or (bool(br) and (matched or nm_shown < nm_cap))
                )
                if log_probe:
                    log_info(
                        "destination_forensic_planned_move_file_parent_probe",
                        visited_folder_canonical_raw_excerpt=f_raw[:400],
                        visited_folder_graph_canonical_excerpt=f_norm[:400],
                        planned_move_destination_path_raw_excerpt=dest_raw[:400],
                        planned_move_destination_graph_canonical_excerpt=str(dest_full)[:400],
                        derived_immediate_parent_graph_canonical_excerpt=str(parent_full)[:400],
                        matched=bool(matched),
                        mismatch_reason=str(mismatch_reason)[:120],
                        branch_bundle=str(br)[:200] if br else "",
                    )
                    if br and not matched:
                        nm_shown += 1
        if br and fen:
            log_info(
                "destination_forensic_canon_diff_folder_file_scan_summary",
                branch_prefix_excerpt=str(br)[:200],
                visited_folder_graph_canonical_excerpt=f_norm[:400],
                matching_file_destinations_count=int(len(out)),
                detail="planned_move_file_enumerator_used_graph_anchor_plus_projection",
            )
        return out

    def _forensic_planned_file_destination_paths_under_folder(self, folder_canon: str) -> list[str]:
        """``planned_moves`` file rows whose destination parent folder matches ``folder_canon`` (graph-canonical)."""
        f_raw = str(folder_canon or "").strip()
        if not f_raw:
            return []
        idx = getattr(self, "_planned_file_children_by_parent_cf", None)
        if isinstance(idx, dict):
            self._planned_file_parent_index_lookup_total = (
                int(getattr(self, "_planned_file_parent_index_lookup_total", 0) or 0) + 1
            )
            f_norm = self._canonical_planned_memory_path_for_graph_match(f_raw)
            key = f_norm.casefold()
            out = list(idx.get(key) or [])
            self._planned_file_parent_index_children_returned_total = (
                int(getattr(self, "_planned_file_parent_index_children_returned_total", 0) or 0) + len(out)
            )
            fen = self._destination_forensic_planned_item_materialization_logging_enabled()
            if fen:
                log_info(
                    "destination_forensic_planned_move_file_parent_lookup",
                    source="parent_index",
                    visited_folder_graph_canonical_excerpt=f_norm[:400],
                    child_destination_count=int(len(out)),
                    branch_bundle_excerpt=str(self._destination_forensic_canon_diff_branch_hit(f_raw) or "")[
                        :200
                    ],
                )
            return out
        self._planned_file_parent_index_fallback_full_scans = (
            int(getattr(self, "_planned_file_parent_index_fallback_full_scans", 0) or 0) + 1
        )
        return self._forensic_planned_file_destination_paths_under_folder_full_scan(f_raw)

    def _forensic_planned_folder_move_destination_paths_under_folder(self, folder_canon: str) -> list[str]:
        """``planned_moves`` whose **source** is a folder and whose destination folder's parent matches ``folder_canon``."""
        out: list[str] = []
        f_raw = str(folder_canon or "").strip()
        if not f_raw:
            return out
        f_norm = self._canonical_planned_memory_path_for_graph_match(f_raw)
        f_cf = f_norm.casefold()
        for move in self.planned_moves or []:
            if not isinstance(move, dict):
                continue
            if self._planned_move_terminal_is_file_leaf(move):
                continue
            proj = self._allocation_projection_path(move)
            if not proj:
                continue
            dest_full = self._canonical_planned_memory_path_for_graph_match(proj)
            segs = self._path_segments(dest_full)
            if len(segs) < 2:
                continue
            parent_dest = "\\".join(segs[:-1])
            parent_full = self._canonical_planned_memory_path_for_graph_match(parent_dest)
            if parent_full.casefold() == f_cf:
                out.append(dest_full)
        return out

    def _forensic_destination_immediate_child_row_kinds(self, parent_ix: QModelIndex) -> dict[str, int]:
        dmodel = getattr(self, "destination_planning_model", None)
        if dmodel is None or not parent_ix.isValid():
            return {}
        counts: dict[str, int] = {"planned_file": 0, "planned_folder": 0, "live_or_other": 0, "placeholder": 0}
        col0 = parent_ix.siblingAtColumn(0) if parent_ix.column() != 0 else parent_ix
        for r in range(dmodel.rowCount(col0)):
            ch = dmodel.index(r, 0, col0)
            pl = self._destination_model_index_user_role_dict(ch)
            if pl.get("placeholder"):
                counts["placeholder"] += 1
                continue
            rk = str(pl.get("row_kind") or "").strip().lower()
            if rk == "planned_file":
                counts["planned_file"] += 1
            elif rk == "planned_folder":
                counts["planned_folder"] += 1
            else:
                counts["live_or_other"] += 1
        return counts

    def _materialize_planned_move_file_rows_under_parent(self, parent_ix: QModelIndex) -> int:
        """Bind ``planned_moves`` file destinations whose parent folder matches this row (read-only GETs).

        Uses :meth:`_ensure_destination_projection_path_sharepoint_graph_only` with
        ``leaf_is_file=True`` — same planned-chain bind as other projection paths; does not use
        ``unresolved_proposed`` or Graph mkdir.
        """
        if not parent_ix.isValid():
            return 0
        if not destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            return 0
        pl = self._destination_model_index_user_role_dict(parent_ix)
        if not destination_payload_is_planned_workspace_row(pl) or not bool(pl.get("is_folder", True)):
            return 0
        parent_raw = str(self._tree_item_path(pl) or "").strip()
        if not parent_raw:
            return 0
        parent_canon = self._canonical_planned_memory_path_for_graph_match(parent_raw)
        dest_paths = self._forensic_planned_file_destination_paths_under_folder(parent_canon)
        if not dest_paths:
            return 0
        p_col0 = parent_ix.siblingAtColumn(0) if parent_ix.column() != 0 else parent_ix
        attached = 0
        for dest_canon in dest_paths:
            hit = self._ensure_destination_projection_path_sharepoint_graph_only(dest_canon, leaf_is_file=True)
            if hit is None or not hit.isValid():
                continue
            hit_c = hit.siblingAtColumn(0) if hit.column() != 0 else hit
            if not hit_c.isValid():
                continue
            if hit_c.parent() != p_col0:
                continue
            hit_pl = self._destination_model_index_user_role_dict(hit_c)
            hit_path = self._canonical_planned_memory_path_for_graph_match(self._tree_item_path(hit_pl) or "")
            if hit_path.casefold() != str(dest_canon).casefold():
                continue
            if str(hit_pl.get("row_kind") or "").strip().lower() != "planned_file":
                continue
            attached += 1
        self._planned_file_parent_index_rows_attached = (
            int(getattr(self, "_planned_file_parent_index_rows_attached", 0) or 0) + int(attached)
        )
        return attached

    def _materialize_planned_move_folder_rows_under_parent(self, parent_ix: QModelIndex) -> int:
        """Bind ``planned_moves`` **folder** destinations whose parent folder matches this planned row.

        Same projection bind as allocations — :meth:`_ensure_destination_projection_path_sharepoint_graph_only`
        with ``leaf_is_file=False``. Does not use ``unresolved_proposed`` or Graph mkdir.
        """
        if not parent_ix.isValid():
            return 0
        if not destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            return 0
        pl = self._destination_model_index_user_role_dict(parent_ix)
        if not destination_payload_is_planned_workspace_row(pl) or not bool(pl.get("is_folder", True)):
            return 0
        parent_raw = str(self._tree_item_path(pl) or "").strip()
        if not parent_raw:
            return 0
        parent_canon = self._canonical_planned_memory_path_for_graph_match(parent_raw)
        dest_paths = self._forensic_planned_folder_move_destination_paths_under_folder(parent_canon)
        if not dest_paths:
            return 0
        p_col0 = parent_ix.siblingAtColumn(0) if parent_ix.column() != 0 else parent_ix
        attached = 0
        for dest_canon in dest_paths:
            hit = self._ensure_destination_projection_path_sharepoint_graph_only(dest_canon, leaf_is_file=False)
            if hit is None or not hit.isValid():
                continue
            hit_c = hit.siblingAtColumn(0) if hit.column() != 0 else hit
            if not hit_c.isValid():
                continue
            if hit_c.parent() != p_col0:
                continue
            hit_pl = self._destination_model_index_user_role_dict(hit_c)
            hit_path = self._canonical_planned_memory_path_for_graph_match(self._tree_item_path(hit_pl) or "")
            if hit_path.casefold() != str(dest_canon).casefold():
                continue
            if str(hit_pl.get("row_kind") or "").strip().lower() != "planned_folder":
                continue
            if not bool(hit_pl.get("is_folder", True)):
                continue
            attached += 1
        return attached

    def _destination_fixpoint_compute_deadline(self, t0: float) -> tuple[float | None, float | None]:
        """Return (deadline_perf, budget_ms_for_log) for chunked planned-workspace fixpoint.

        Target slice is 4–8 ms; wall time must never exceed 10 ms per timer invocation.
        """
        if not getattr(self, "_destination_chunk_planned_workspace_fixpoint", False):
            return None, None
        _slice_s = float(getattr(self, "_destination_startup_fixpoint_slice_s", 0.006) or 0.006)
        try:
            if self._destination_user_scroll_interaction_active():
                _slice_s = min(_slice_s, 0.004)
        except Exception:
            pass
        _slice_s = min(float(_slice_s), 0.008)
        deadline = min(t0 + _slice_s, t0 + 0.010)
        budget_ms = round((deadline - t0) * 1000.0, 3)
        return deadline, budget_ms

    def _materialize_planned_workspace_proposed_descendants_fixpoint(
        self, subtree_root_ix: QModelIndex, *, max_rounds: int = 48
    ) -> int:
        """Hydrate folder-backed descendants: proposed queue, ``planned_moves`` folders/files, allocations.

        Breadth-first under Graph authority visits destination folder rows and applies the matching
        binder(s): planned-workspace rows run proposed + planned-move folder/file projection; allocated
        and proposed folder rows run allocation / proposed queue hydration (no Graph mkdir).
        """
        dmodel = getattr(self, "destination_planning_model", None)
        if dmodel is None or not subtree_root_ix.isValid():
            return 0
        if not destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            return 0
        col0 = subtree_root_ix.siblingAtColumn(0) if subtree_root_ix.column() != 0 else subtree_root_ix
        if not col0.isValid():
            return 0
        _owned_pf_index = False
        if getattr(self, "_planned_file_children_by_parent_cf", None) is None:
            self._rebuild_planned_file_parent_index_for_overlay_pass()
            _owned_pf_index = True
        n = 0
        try:
            n = self._materialize_planned_workspace_proposed_descendants_fixpoint_core(col0, max_rounds=max_rounds)
        finally:
            if _owned_pf_index:
                self._planned_file_children_by_parent_cf = None
        if not getattr(self, "_destination_fixpoint_slice_incomplete", False):
            self._destination_fixpoint_no_progress_streak = 0
        if getattr(self, "_destination_fixpoint_slice_incomplete", False) and getattr(
            self, "_destination_chunk_planned_workspace_fixpoint", False
        ):
            c = int(getattr(self, "_destination_fixpoint_slice_continuations", 0) or 0)
            if c < 160:
                self._destination_fixpoint_slice_continuations = c + 1
                _ix_cap = subtree_root_ix
                _mr_cap = int(max_rounds)

                def _c():
                    self._materialize_planned_workspace_proposed_descendants_fixpoint(_ix_cap, max_rounds=_mr_cap)

                _delay_ms = 0
                try:
                    if self._destination_user_scroll_interaction_active():
                        self._destination_fixpoint_no_progress_streak = min(
                            48, int(getattr(self, "_destination_fixpoint_no_progress_streak", 0) or 0) + 1
                        )
                        _delay_ms = min(120, 8 * int(getattr(self, "_destination_fixpoint_no_progress_streak", 0) or 0))
                        log_info(
                            "destination_fixpoint_backoff_no_progress",
                            delay_ms=int(_delay_ms),
                            continuation_index=int(c) + 1,
                        )
                except Exception:
                    _delay_ms = 0
                QTimer.singleShot(
                    int(_delay_ms),
                    lambda: self._safe_invoke("destination_fixpoint_time_slice", _c),
                )
        return n

    def _materialize_planned_workspace_proposed_descendants_fixpoint_core(
        self, col0: QModelIndex, *, max_rounds: int
    ) -> int:
        dmodel = getattr(self, "destination_planning_model", None)
        if dmodel is None:
            return 0
        fen = self._destination_forensic_planned_item_materialization_logging_enabled()
        _ml_resume = getattr(self, "_destination_fixpoint_resume_mark_loaded_stack", None)
        if _ml_resume is not None:
            self._destination_fixpoint_resume_mark_loaded_stack = None
            _ml_seen = getattr(self, "_destination_fixpoint_resume_seen_mark", None)
            self._destination_fixpoint_resume_seen_mark = None
            _fix_slice_t0 = time.perf_counter()
            deadline_perf, budget_ms_log = self._destination_fixpoint_compute_deadline(_fix_slice_t0)
            if deadline_perf is not None:
                log_info(
                    "startup_lifecycle_temp_materialize_chunk_begin",
                    phase="planned_workspace_fixpoint",
                    subphase="mark_loaded_stack",
                    budget_ms=budget_ms_log,
                    budget_wall_cap_ms=10.0,
                    note="resume",
                )
            stack_ml: list[QModelIndex] = list(_ml_resume)
            seen_ml: set[int] = set(_ml_seen or [])
            self._destination_fixpoint_slice_incomplete = False
            while stack_ml:
                if deadline_perf is not None and time.perf_counter() >= deadline_perf:
                    self._destination_fixpoint_slice_incomplete = True
                    self._destination_fixpoint_resume_mark_loaded_stack = list(stack_ml)
                    self._destination_fixpoint_resume_seen_mark = set(seen_ml)
                    log_info(
                        "startup_lifecycle_temp_materialize_chunk_end",
                        phase="planned_workspace_fixpoint",
                        subphase="mark_loaded_stack",
                        wall_ms=round((time.perf_counter() - _fix_slice_t0) * 1000.0, 2),
                        budget_ms=budget_ms_log,
                        note="fixpoint_budget_yield_mark_loaded_stack",
                        planned_workspace_fixpoint_budget_enforced=True,
                    )
                    return 0
                _ix_ml = stack_ml.pop()
                if not _ix_ml.isValid():
                    continue
                _ptr_ml = _ix_ml.internalPointer()
                _pid_ml = id(_ptr_ml) if _ptr_ml is not None else None
                if _pid_ml is not None:
                    if _pid_ml in seen_ml:
                        continue
                    seen_ml.add(_pid_ml)
                _plm_ml = self._destination_model_index_user_role_dict(_ix_ml)
                if destination_payload_is_planned_workspace_row(_plm_ml) and bool(_plm_ml.get("is_folder", True)):

                    def _mut_loaded_ml(p: dict[str, Any]) -> None:
                        if destination_payload_is_planned_workspace_row(dict(p)) and p.get("is_folder", True):
                            p["children_loaded"] = True

                    dmodel.update_payload_for_index(_ix_ml, _mut_loaded_ml)
                _nrc_ml = int(dmodel.rowCount(_ix_ml))
                for _r_ml in range(_nrc_ml):
                    if deadline_perf is not None and time.perf_counter() >= deadline_perf:
                        for _r2 in range(_r_ml, _nrc_ml):
                            stack_ml.append(dmodel.index(_r2, 0, _ix_ml))
                        self._destination_fixpoint_resume_mark_loaded_stack = list(stack_ml)
                        self._destination_fixpoint_resume_seen_mark = set(seen_ml)
                        self._destination_fixpoint_slice_incomplete = True
                        log_info(
                            "startup_lifecycle_temp_materialize_chunk_end",
                            phase="planned_workspace_fixpoint",
                            subphase="mark_loaded_stack",
                            wall_ms=round((time.perf_counter() - _fix_slice_t0) * 1000.0, 2),
                            budget_ms=budget_ms_log,
                            note="fixpoint_budget_yield_mark_loaded_stack_mid_children",
                            row_index=int(_r_ml),
                            row_count=int(_nrc_ml),
                            planned_workspace_fixpoint_budget_enforced=True,
                        )
                        return 0
                    stack_ml.append(dmodel.index(_r_ml, 0, _ix_ml))
            if deadline_perf is not None:
                log_info(
                    "startup_lifecycle_temp_materialize_chunk_end",
                    phase="planned_workspace_fixpoint",
                    subphase="mark_loaded_stack",
                    wall_ms=round((time.perf_counter() - _fix_slice_t0) * 1000.0, 2),
                    budget_ms=budget_ms_log,
                    note="mark_loaded_stack_complete",
                    planned_workspace_fixpoint_budget_enforced=True,
                )
            return 0
        if fen:
            root_pl = self._destination_model_index_user_role_dict(col0)
            log_info(
                "destination_forensic_fixpoint_enter",
                subtree_root_path_excerpt=str(self._tree_item_path(root_pl) or "")[:400],
                row_kind_excerpt=str(root_pl.get("row_kind") or "")[:40],
                planned_workspace_folder=bool(
                    destination_payload_is_planned_workspace_row(root_pl) and root_pl.get("is_folder", True)
                ),
                explicit_planned_file_attach_helper=True,
                note="fixpoint_draining_worklist_requeues_parent_on_structural_or_queue_progress",
            )
        # Draining worklist: one pass from ``col0``; revisit a planned-workspace parent in
        # the same pass only when new rows appear or unresolved proposed count drops, so
        # we do not thrash ``_apply_proposed_children`` when a visit is already drained.
        # The old outer ``for range(max_rounds)`` + fresh ``seen_ptr`` BFS required one
        # outer round per unit of cross-level progress.
        cap = max(1, int(max_rounds))
        max_revisits_per_node = max(64, cap)
        max_worklist_steps = max(50_000, max_revisits_per_node * 10_000)
        round_idx = 1
        round_applied = 0
        queue: deque[QModelIndex] = deque([col0])
        visit_counts: dict[int, int] = {}
        unique_planned_ws_parent_ptrs: set[int] = set()
        planned_parents_visited = 0
        worklist_steps = 0
        self._destination_fixpoint_slice_incomplete = False
        _fix_slice_t0 = time.perf_counter()
        deadline_perf, budget_ms_log = self._destination_fixpoint_compute_deadline(_fix_slice_t0)
        if deadline_perf is not None:
            log_info(
                "startup_lifecycle_temp_materialize_chunk_begin",
                phase="planned_workspace_fixpoint",
                subphase="worklist",
                budget_ms=budget_ms_log,
                budget_wall_cap_ms=10.0,
            )
        if fen:
            log_info(
                "destination_forensic_fixpoint_round_start",
                round_index=int(round_idx),
                bfs_start_queue_size=1,
                fixpoint_mode="draining_worklist",
                max_revisits_per_node=int(max_revisits_per_node),
            )
        while queue and worklist_steps < max_worklist_steps:
            if deadline_perf is not None and time.perf_counter() >= deadline_perf:
                self._destination_fixpoint_slice_incomplete = bool(queue)
                if self._destination_fixpoint_slice_incomplete:
                    log_info(
                        "startup_lifecycle_temp_materialize_chunk_end",
                        phase="planned_workspace_fixpoint",
                        subphase="worklist",
                        wall_ms=round((time.perf_counter() - _fix_slice_t0) * 1000.0, 2),
                        budget_ms=budget_ms_log,
                        parent_count_processed=int(planned_parents_visited),
                        worklist_steps=int(worklist_steps),
                        note="time_slice_yield_with_pending_worklist",
                        planned_workspace_fixpoint_budget_enforced=True,
                    )
                break
            worklist_steps += 1
            ix = queue.popleft()
            if not ix.isValid():
                continue
            node_applied = 0
            ptr = ix.internalPointer()
            pid = id(ptr) if ptr is not None else None
            _res = getattr(self, "_destination_fixpoint_resume", None)
            skip_visit_count = False
            skip_main_materialize = False
            pw_step_local = 0
            child_r0 = 0
            if isinstance(_res, dict):
                _rix = _res.get("ix")
                if isinstance(_rix, QModelIndex) and _rix.isValid() and _rix == ix:
                    _k = str(_res.get("kind") or "")
                    if _k == "pw":
                        pw_step_local = int(_res.get("step", 0) or 0)
                        skip_visit_count = True
                        if pw_step_local >= 3:
                            skip_main_materialize = True
                        self._destination_fixpoint_resume = None
                    elif _k == "child":
                        child_r0 = int(_res.get("r", 0) or 0)
                        skip_visit_count = True
                        skip_main_materialize = True
                        self._destination_fixpoint_resume = None
                    elif _k == "after_apply":
                        skip_visit_count = True
                        skip_main_materialize = True
                        self._destination_fixpoint_resume = None
            if not skip_visit_count and pid is not None:
                n_vis = visit_counts.get(pid, 0) + 1
                visit_counts[pid] = n_vis
                if n_vis > max_revisits_per_node:
                    continue
            pl = self._destination_model_index_user_role_dict(ix)
            _break_while = False
            if not skip_main_materialize and destination_payload_is_planned_workspace_row(pl) and bool(
                pl.get("is_folder", True)
            ):
                if pid is not None:
                    unique_planned_ws_parent_ptrs.add(pid)
                if pw_step_local == 0:
                    planned_parents_visited += 1
                ppath = str(self._tree_item_path(pl) or "")[:400]
                br_vis = self._destination_forensic_canon_diff_branch_hit(ppath)
                un_before = self._forensic_count_unresolved_proposed_for_parent(ppath)
                files_planning = self._forensic_planned_file_destination_paths_under_folder(ppath)
                folders_planning = self._forensic_planned_folder_move_destination_paths_under_folder(
                    self._canonical_planned_memory_path_for_graph_match(str(self._tree_item_path(pl) or "").strip())
                )
                kinds_before = self._forensic_destination_immediate_child_row_kinds(ix)
                row_count_before = int(dmodel.rowCount(ix))
                if fen and pw_step_local == 0:
                    log_info(
                        "destination_forensic_fixpoint_visit_planned_workspace_parent",
                        round_index=int(round_idx),
                        parent_visit_count=int(visit_counts.get(pid, 1)) if pid is not None else 0,
                        parent_canonical_path_excerpt=ppath,
                        parent_graph_canonical_for_match_excerpt=self._canonical_planned_memory_path_for_graph_match(
                            str(self._tree_item_path(pl) or "").strip()
                        )[:400],
                        unresolved_proposed_count_for_parent=int(un_before),
                        planned_move_file_destinations_under_parent_count=len(files_planning),
                        planned_move_folder_move_destinations_under_parent_count=len(folders_planning),
                        planned_move_file_destinations_sample=" | ".join(files_planning[:6])[:400],
                        planned_move_folder_move_destinations_sample=" | ".join(folders_planning[:6])[:400],
                        immediate_children_before=dict(kinds_before),
                    )
                if fen and br_vis and pw_step_local == 0:
                    p_graph = self._canonical_planned_memory_path_for_graph_match(
                        str(self._tree_item_path(pl) or "").strip()
                    )
                    qh: list[str] = []
                    for sparent, bucket in (getattr(self, "unresolved_proposed_by_parent_path", None) or {}).items():
                        if not self._paths_equivalent(sparent, str(self._tree_item_path(pl) or ""), "destination"):
                            continue
                        qh.append(
                            f"queue_key_raw={str(sparent)[:200]}|key_graph="
                            f"{self._canonical_planned_memory_path_for_graph_match(str(sparent))[:200]}|n={len(bucket)}"
                        )
                    log_info(
                        "destination_forensic_canon_diff_fixpoint_visit_bundle",
                        branch_prefix_excerpt=str(br_vis)[:200],
                        visible_model_parent_path_raw_excerpt=str(self._tree_item_path(pl) or "")[:400],
                        visible_model_parent_graph_canonical_excerpt=str(p_graph)[:400],
                        unresolved_proposed_queue_hits=" || ".join(qh[:10])[:2000],
                        detail="compare_raw_model_path_proposed_queue_keys_and_graph_canon",
                    )
                delta = 0
                kinds_mid: dict[str, int] = {}
                folder_n = 0
                file_n = 0
                if pw_step_local <= 0:
                    delta = self._apply_proposed_children_to_model_index(ix, _materialize_recursive_pass=True)
                    if deadline_perf is not None and time.perf_counter() >= deadline_perf:
                        self._destination_fixpoint_resume = {"kind": "pw", "ix": ix, "step": 1}
                        queue.appendleft(ix)
                        self._destination_fixpoint_slice_incomplete = True
                        log_info(
                            "startup_lifecycle_temp_materialize_chunk_end",
                            phase="planned_workspace_fixpoint",
                            subphase="worklist",
                            wall_ms=round((time.perf_counter() - _fix_slice_t0) * 1000.0, 2),
                            budget_ms=budget_ms_log,
                            yield_phase="pw_after_apply_proposed",
                            note="fixpoint_budget_yield_after_apply_proposed",
                            planned_workspace_fixpoint_budget_enforced=True,
                        )
                        _break_while = True
                    if not _break_while:
                        kinds_mid = self._forensic_destination_immediate_child_row_kinds(ix)
                elif pw_step_local == 1:
                    kinds_mid = self._forensic_destination_immediate_child_row_kinds(ix)
                else:
                    kinds_mid = self._forensic_destination_immediate_child_row_kinds(ix)
                if not _break_while and pw_step_local <= 1:
                    folder_n = self._materialize_planned_move_folder_rows_under_parent(ix)
                    if deadline_perf is not None and time.perf_counter() >= deadline_perf:
                        self._destination_fixpoint_resume = {"kind": "pw", "ix": ix, "step": 2}
                        queue.appendleft(ix)
                        self._destination_fixpoint_slice_incomplete = True
                        log_info(
                            "startup_lifecycle_temp_materialize_chunk_end",
                            phase="planned_workspace_fixpoint",
                            subphase="worklist",
                            wall_ms=round((time.perf_counter() - _fix_slice_t0) * 1000.0, 2),
                            budget_ms=budget_ms_log,
                            yield_phase="pw_after_planned_move_folder",
                            note="fixpoint_budget_yield_after_planned_move_folder",
                            planned_workspace_fixpoint_budget_enforced=True,
                        )
                        _break_while = True
                if not _break_while and pw_step_local <= 2:
                    file_n = self._materialize_planned_move_file_rows_under_parent(ix)
                    if deadline_perf is not None and time.perf_counter() >= deadline_perf:
                        self._destination_fixpoint_resume = {"kind": "pw", "ix": ix, "step": 3}
                        queue.appendleft(ix)
                        self._destination_fixpoint_slice_incomplete = True
                        log_info(
                            "startup_lifecycle_temp_materialize_chunk_end",
                            phase="planned_workspace_fixpoint",
                            subphase="worklist",
                            wall_ms=round((time.perf_counter() - _fix_slice_t0) * 1000.0, 2),
                            budget_ms=budget_ms_log,
                            yield_phase="pw_after_planned_move_file",
                            note="fixpoint_budget_yield_after_planned_move_file",
                            planned_workspace_fixpoint_budget_enforced=True,
                        )
                        _break_while = True
                if not _break_while:
                    contrib_pf = int(delta) + int(folder_n) + int(file_n)
                    round_applied += contrib_pf
                    kinds_after = self._forensic_destination_immediate_child_row_kinds(ix)
                    un_after = self._forensic_count_unresolved_proposed_for_parent(ppath)
                    row_count_after = int(dmodel.rowCount(ix))
                    if contrib_pf > 0 and (
                        row_count_after > row_count_before or int(un_after) < int(un_before)
                    ):
                        par = ix.parent()
                        if par.isValid():
                            queue.appendleft(par)
                        queue.append(ix)
                    if fen:
                        log_info(
                            "destination_forensic_fixpoint_visit_planned_workspace_parent_done",
                            round_index=int(round_idx),
                            parent_canonical_path_excerpt=ppath,
                            proposed_folder_records_applied=int(delta),
                            planned_move_folder_rows_attached=int(folder_n),
                            planned_move_file_rows_attached=int(file_n),
                            immediate_children_after_proposed_pass=dict(kinds_mid),
                            immediate_children_after=dict(kinds_after),
                            unresolved_proposed_count_for_parent_after=int(un_after),
                            planned_file_children_added=int(
                                kinds_after.get("planned_file", 0) - kinds_before.get("planned_file", 0)
                            ),
                        )
            elif not skip_main_materialize and (
                bool(pl.get("is_folder", True))
                and not destination_payload_is_live_graph_row(pl)
                and self.node_is_planned_allocation(pl)
            ):
                alloc_n = self._apply_allocation_children_to_model_index(ix)
                node_applied += int(alloc_n)
                round_applied += int(alloc_n)
                if fen:
                    log_info(
                        "destination_forensic_fixpoint_visit_allocated_folder_parent",
                        round_index=int(round_idx),
                        parent_path_excerpt=str(self._tree_item_path(pl) or "")[:400],
                        allocation_children_applied=int(alloc_n),
                    )
                if deadline_perf is not None and time.perf_counter() >= deadline_perf:
                    self._destination_fixpoint_resume = {"kind": "after_apply", "ix": ix}
                    queue.appendleft(ix)
                    self._destination_fixpoint_slice_incomplete = True
                    log_info(
                        "startup_lifecycle_temp_materialize_chunk_end",
                        phase="planned_workspace_fixpoint",
                        subphase="worklist",
                        wall_ms=round((time.perf_counter() - _fix_slice_t0) * 1000.0, 2),
                        budget_ms=budget_ms_log,
                        yield_phase="after_allocation_apply",
                        note="fixpoint_budget_yield_after_allocation_apply",
                        planned_workspace_fixpoint_budget_enforced=True,
                    )
                    _break_while = True
            elif not skip_main_materialize and bool(pl.get("is_folder", True)) and self.node_is_proposed(pl):
                prop_n = self._apply_proposed_children_to_model_index(ix, _materialize_recursive_pass=True)
                node_applied += int(prop_n)
                round_applied += int(prop_n)
                if fen:
                    log_info(
                        "destination_forensic_fixpoint_visit_proposed_folder_parent",
                        round_index=int(round_idx),
                        parent_path_excerpt=str(self._tree_item_path(pl) or "")[:400],
                        proposed_folder_records_applied=int(prop_n),
                    )
                if deadline_perf is not None and time.perf_counter() >= deadline_perf:
                    self._destination_fixpoint_resume = {"kind": "after_apply", "ix": ix}
                    queue.appendleft(ix)
                    self._destination_fixpoint_slice_incomplete = True
                    log_info(
                        "startup_lifecycle_temp_materialize_chunk_end",
                        phase="planned_workspace_fixpoint",
                        subphase="worklist",
                        wall_ms=round((time.perf_counter() - _fix_slice_t0) * 1000.0, 2),
                        budget_ms=budget_ms_log,
                        yield_phase="after_proposed_folder_apply",
                        note="fixpoint_budget_yield_after_proposed_folder_apply",
                        planned_workspace_fixpoint_budget_enforced=True,
                    )
                    _break_while = True
            if _break_while:
                break
            rc = int(dmodel.rowCount(ix))
            for r in range(child_r0, rc):
                if deadline_perf is not None and time.perf_counter() >= deadline_perf:
                    self._destination_fixpoint_resume = {"kind": "child", "ix": ix, "r": r}
                    queue.appendleft(ix)
                    self._destination_fixpoint_slice_incomplete = True
                    log_info(
                        "startup_lifecycle_temp_materialize_chunk_end",
                        phase="planned_workspace_fixpoint",
                        subphase="worklist",
                        wall_ms=round((time.perf_counter() - _fix_slice_t0) * 1000.0, 2),
                        budget_ms=budget_ms_log,
                        yield_phase="child_enqueue",
                        child_r=int(r),
                        row_count=int(rc),
                        note="fixpoint_budget_yield_mid_child_enqueue",
                        planned_workspace_fixpoint_budget_enforced=True,
                    )
                    _break_while = True
                    break
                ch = dmodel.index(r, 0, ix)
                ch_pl = self._destination_model_index_user_role_dict(ch)
                if ch_pl.get("placeholder"):
                    continue
                queue.append(ch)
            if _break_while:
                break
            if node_applied > 0:
                par = ix.parent()
                if par.isValid():
                    queue.appendleft(par)
                queue.append(ix)

        total_applied = int(round_applied)
        if fen:
            if worklist_steps >= max_worklist_steps:
                log_info(
                    "destination_forensic_fixpoint_worklist_step_cap_hit",
                    round_index=int(round_idx),
                    worklist_steps=int(worklist_steps),
                    max_worklist_steps=int(max_worklist_steps),
                    queue_remaining_size=len(queue),
                )
            log_info(
                "destination_forensic_fixpoint_round_end",
                round_index=int(round_idx),
                planned_workspace_parents_visited=int(len(unique_planned_ws_parent_ptrs)),
                planned_workspace_parent_visit_events=int(planned_parents_visited),
                round_applied_total=int(round_applied),
                cumulative_applied=int(total_applied),
                worklist_steps=int(worklist_steps),
                fixpoint_mode="draining_worklist",
                queue_empty_at_end=not bool(queue),
                hit_worklist_cap=bool(worklist_steps >= max_worklist_steps),
            )

        if getattr(self, "_destination_fixpoint_slice_incomplete", False):
            return int(total_applied)

        if deadline_perf is not None and time.perf_counter() >= deadline_perf:
            self._destination_fixpoint_resume_mark_loaded_stack = [col0]
            self._destination_fixpoint_resume_seen_mark = set()
            self._destination_fixpoint_slice_incomplete = True
            log_info(
                "startup_lifecycle_temp_materialize_chunk_end",
                phase="planned_workspace_fixpoint",
                subphase="mark_loaded_stack",
                wall_ms=round((time.perf_counter() - _fix_slice_t0) * 1000.0, 2),
                budget_ms=budget_ms_log,
                note="fixpoint_defer_mark_loaded_stack_after_worklist",
                planned_workspace_fixpoint_budget_enforced=True,
            )
            return int(total_applied)

        stack: list[QModelIndex] = [col0]
        seen_mark: set[int] = set()
        while stack:
            if deadline_perf is not None and time.perf_counter() >= deadline_perf:
                self._destination_fixpoint_resume_mark_loaded_stack = list(stack)
                self._destination_fixpoint_resume_seen_mark = set(seen_mark)
                self._destination_fixpoint_slice_incomplete = True
                log_info(
                    "startup_lifecycle_temp_materialize_chunk_end",
                    phase="planned_workspace_fixpoint",
                    subphase="mark_loaded_stack",
                    wall_ms=round((time.perf_counter() - _fix_slice_t0) * 1000.0, 2),
                    budget_ms=budget_ms_log,
                    note="fixpoint_budget_yield_mark_loaded_stack",
                    planned_workspace_fixpoint_budget_enforced=True,
                )
                return int(total_applied)
            ix = stack.pop()
            if not ix.isValid():
                continue
            ptr = ix.internalPointer()
            pid = id(ptr) if ptr is not None else None
            if pid is not None:
                if pid in seen_mark:
                    continue
                seen_mark.add(pid)
            plm = self._destination_model_index_user_role_dict(ix)
            if destination_payload_is_planned_workspace_row(plm) and bool(plm.get("is_folder", True)):

                def _mut_loaded(p: dict[str, Any]) -> None:
                    if destination_payload_is_planned_workspace_row(dict(p)) and p.get("is_folder", True):
                        p["children_loaded"] = True

                dmodel.update_payload_for_index(ix, _mut_loaded)
            _rc_ml = int(dmodel.rowCount(ix))
            for r in range(_rc_ml):
                if deadline_perf is not None and time.perf_counter() >= deadline_perf:
                    for _r2 in range(r, _rc_ml):
                        stack.append(dmodel.index(_r2, 0, ix))
                    self._destination_fixpoint_resume_mark_loaded_stack = list(stack)
                    self._destination_fixpoint_resume_seen_mark = set(seen_mark)
                    self._destination_fixpoint_slice_incomplete = True
                    log_info(
                        "startup_lifecycle_temp_materialize_chunk_end",
                        phase="planned_workspace_fixpoint",
                        subphase="mark_loaded_stack",
                        wall_ms=round((time.perf_counter() - _fix_slice_t0) * 1000.0, 2),
                        budget_ms=budget_ms_log,
                        note="fixpoint_budget_yield_mark_loaded_stack_mid_children",
                        row_index=int(r),
                        row_count=int(_rc_ml),
                        planned_workspace_fixpoint_budget_enforced=True,
                    )
                    return int(total_applied)
                stack.append(dmodel.index(r, 0, ix))
        if deadline_perf is not None:
            log_info(
                "startup_lifecycle_temp_materialize_chunk_end",
                phase="planned_workspace_fixpoint",
                subphase="mark_loaded_stack",
                wall_ms=round((time.perf_counter() - _fix_slice_t0) * 1000.0, 2),
                budget_ms=budget_ms_log,
                note="mark_loaded_stack_complete",
                planned_workspace_fixpoint_budget_enforced=True,
            )
        return total_applied

    def _apply_proposed_children_to_model_index(
        self, parent_ix: QModelIndex, *, _materialize_recursive_pass: bool = False
    ) -> int:
        model = getattr(self, "destination_planning_model", None)
        if model is None:
            return 0
        attach_ix = parent_ix
        graph_auth = destination_authority_contract.graph_owns_visible_real_destination_structure(self)
        if not parent_ix.isValid():
            if graph_auth:
                return 0
            parent_path = self.normalize_memory_path("Root")
            parent_data = dict(self._destination_root_base_data())
        else:
            parent_data = dict(parent_ix.data(Qt.UserRole) or {})
            parent_path = self._tree_item_path(parent_data)
        if not parent_path:
            return 0
        matching_candidates = self._get_unresolved_candidates_for_parent(parent_path)
        fen_pb = self._destination_forensic_planned_item_materialization_logging_enabled()
        file_moves_here = self._forensic_planned_file_destination_paths_under_folder(parent_path)
        if fen_pb:
            log_info(
                "destination_forensic_proposed_bind_enter",
                parent_canonical_path_excerpt=str(parent_path)[:400],
                graph_authority=bool(graph_auth),
                materialize_recursive_pass=bool(_materialize_recursive_pass),
                unresolved_proposed_folder_candidate_count=len(matching_candidates),
                planned_move_file_destinations_under_parent_count=len(file_moves_here),
                planned_move_file_destinations_sample=" | ".join(file_moves_here[:8])[:500],
                candidate_source="unresolved_proposed_by_parent_path_ProposedFolder_records_only",
            )
        if not matching_candidates:
            if fen_pb and file_moves_here:
                log_info(
                    "destination_forensic_proposed_bind_skip",
                    outcome="suppressed_no_queue_entries",
                    parent_canonical_path_excerpt=str(parent_path)[:400],
                    skip_reason="parent_has_planned_move_files_not_in_proposed_folder_queue",
                    planned_file_paths_in_planning_state=" | ".join(file_moves_here[:12])[:600],
                    note="apply_proposed_children_does_not_iterate_planned_moves",
                )
            return 0
        applied_count = 0
        need_graph_child_load = False
        for proposed_folder in matching_candidates:
            normalized_parent_path = self._proposed_parent_path(proposed_folder)
            pf_key = str(self._proposed_folder_key(proposed_folder) or "")[:120]
            dest_path = self._proposed_destination_path(proposed_folder)
            if fen_pb:
                log_info(
                    "destination_forensic_proposed_bind_candidate",
                    row_kind_source="proposed_folder_record",
                    stable_key_excerpt=pf_key,
                    parent_path_model_excerpt=str(parent_path)[:400],
                    proposed_parent_path_excerpt=str(normalized_parent_path)[:400],
                    intended_destination_path_excerpt=str(dest_path)[:400],
                    bind_terminal_is_file=False,
                )
            if not self._paths_equivalent(normalized_parent_path, parent_path, "destination"):
                if fen_pb:
                    log_info(
                        "destination_forensic_proposed_bind_candidate_outcome",
                        stable_key_excerpt=pf_key,
                        attached=False,
                        skip_reason="proposed_parent_path_not_equivalent_to_model_parent",
                    )
                continue
            raw_dest_incoming = str(getattr(proposed_folder, "DestinationPath", "") or "").strip() or dest_path
            lookup_dest = dest_path
            if graph_auth:
                lookup_dest = self._canonical_destination_path_with_visible_library_anchor(dest_path)
                bare_dest = self._canonical_destination_projection_path(dest_path) or self.normalize_memory_path(
                    dest_path
                )
                self._log_sharepoint_overlay_destination_anchor_normalized(
                    overlay_kind="proposed",
                    raw_destination_excerpt=raw_dest_incoming,
                    bare_canonical_excerpt=bare_dest,
                    library_anchored_canonical_excerpt=lookup_dest,
                )
            strict = bool(graph_auth)
            existing_ix = self._find_destination_child_by_path(attach_ix, lookup_dest, overlay_path_strict=strict)
            if existing_ix is None and graph_auth and lookup_dest.casefold() != dest_path.casefold():
                existing_ix = self._find_destination_child_by_path(attach_ix, dest_path, overlay_path_strict=strict)
            if existing_ix is not None and isinstance(existing_ix, QModelIndex) and existing_ix.isValid():
                if graph_auth:
                    self._apply_proposed_overlay_to_existing_graph_row_model_index(
                        existing_ix, proposed_folder, parent_data
                    )
                nd_x = self._destination_model_index_user_role_dict(existing_ix)
                res_reason = (
                    UnresolvedQueueRemovalReason.attached_to_existing_live_row
                    if destination_payload_is_live_graph_row(nd_x)
                    else UnresolvedQueueRemovalReason.merged_to_equivalent_visible_planned_row
                )
                exp = lookup_dest if graph_auth else dest_path
                marked = self._mark_proposed_folder_resolved(
                    proposed_folder,
                    reason=res_reason,
                    outcome_ix=existing_ix,
                    expected_target_canonical=exp,
                    verify_visible_outcome=bool(graph_auth),
                )
                if marked:
                    applied_count += 1
                if fen_pb:
                    log_info(
                        "destination_forensic_proposed_bind_candidate_outcome",
                        stable_key_excerpt=pf_key,
                        attached=bool(marked),
                        mode="merged_existing_child_row",
                        existing_child_row_kind_excerpt=str(nd_x.get("row_kind") or "")[:40],
                        existing_is_live_graph=bool(destination_payload_is_live_graph_row(nd_x)),
                        skip_reason="" if marked else "mark_proposed_folder_resolved_returned_false",
                    )
                continue
            if graph_auth:
                col0 = attach_ix.siblingAtColumn(0) if attach_ix.column() != 0 else attach_ix
                raw_p = self._canonical_destination_path_with_visible_library_anchor(parent_path)
                pcanon = self._canonical_destination_projection_path(raw_p) or self.normalize_memory_path(raw_p)
                dcanon = self._canonical_destination_path_with_visible_library_anchor(dest_path)
                rel = self._sharepoint_canonical_path_segments_under_parent(pcanon, dcanon)
                leaf = None
                if rel:
                    _psk = self._ensure_proposed_folder_stable_key(proposed_folder)
                    _ppl_pf = self._destination_model_index_user_role_dict(col0)
                    _def_pf, _miss_pf, _cc_pf = self._graph_authority_planned_structural_bind_deferred_miss(
                        dcanon, live_graph_parent_pl=_ppl_pf, parent_anchor_index_valid=True
                    )
                    if _def_pf:
                        log_info(
                            "destination_planned_chain_bind_suppressed",
                            intended_path=str(dcanon)[:400],
                            reason="graph_authority_proposed_folder_bind_deferred",
                            miss_reason=_miss_pf,
                            path_excerpt=str(dcanon)[:260],
                            nearest_visible_parent=str(parent_path)[:400],
                            candidate_count=int(_cc_pf),
                        )
                    else:
                        leaf = self._sharepoint_bind_planned_segment_chain(
                            col0,
                            rel,
                            bind_kind="proposed_folder",
                            bind_context_excerpt=str(dcanon)[:220],
                            expected_parent_canonical=None,
                            projection_target_canonical=dcanon,
                            proposed_folder_stable_key=_psk,
                        )
                if not rel:
                    self._log_restore_phase(
                        "sharepoint_planned_bind_suffix_mismatch",
                        overlay_kind="proposed",
                        parent_canonical=str(pcanon)[:260],
                        destination_canonical=str(dcanon)[:260],
                        raw_destination_excerpt=str(raw_dest_incoming)[:260],
                        library_anchored_destination_excerpt=str(dcanon)[:260],
                        model_parent_path_excerpt=str(parent_path)[:220],
                        unresolved_hold_reason=str(UnresolvedQueueRemovalReason.deferred_suffix_mismatch),
                    )
                    if fen_pb:
                        log_info(
                            "destination_forensic_proposed_bind_candidate_outcome",
                            stable_key_excerpt=pf_key,
                            attached=False,
                            skip_reason="canonical_suffix_under_parent_empty_or_mismatch",
                            parent_canonical_excerpt=str(pcanon)[:400],
                            intended_destination_excerpt=str(dcanon)[:400],
                        )
                if leaf is None or not leaf.isValid():
                    leaf = self._ensure_destination_projection_path_sharepoint_graph_only(dcanon, leaf_is_file=False)
                if leaf is not None and leaf.isValid():
                    self._apply_proposed_overlay_to_existing_graph_row_model_index(leaf, proposed_folder, parent_data)
                    mk = self._mark_proposed_folder_resolved(
                        proposed_folder,
                        reason=UnresolvedQueueRemovalReason.bound_planned_chain_visible,
                        outcome_ix=leaf,
                        expected_target_canonical=dcanon,
                        verify_visible_outcome=True,
                    )
                    if mk:
                        applied_count += 1
                    if fen_pb:
                        leaf_pl = self._destination_model_index_user_role_dict(leaf)
                        log_info(
                            "destination_forensic_proposed_bind_candidate_outcome",
                            stable_key_excerpt=pf_key,
                            attached=bool(mk),
                            mode="sharepoint_planned_segment_chain_or_ensure_path",
                            terminal_row_kind_excerpt=str(leaf_pl.get("row_kind") or "")[:40],
                            terminal_is_folder=bool(leaf_pl.get("is_folder", True)),
                            bind_kind_used="proposed_folder_terminal_is_file_false",
                            skip_reason="" if mk else "mark_proposed_folder_resolved_returned_false",
                        )
                elif fen_pb:
                    log_info(
                        "destination_forensic_proposed_bind_candidate_outcome",
                        stable_key_excerpt=pf_key,
                        attached=False,
                        skip_reason="planned_chain_bind_and_ensure_projection_both_invalid",
                        intended_destination_excerpt=str(dcanon)[:400],
                    )
                need_graph_child_load = True
                continue
            self._remove_placeholder_children(attach_ix)
            pl = self._build_proposed_payload(proposed_folder, parent_data)
            model.append_child_payloads(attach_ix, [pl])
            self._refresh_destination_item_visibility_index(attach_ix, expand=True)
            child_ix = self._find_destination_child_by_path(attach_ix, dest_path, overlay_path_strict=False)
            mk2 = self._mark_proposed_folder_resolved(
                proposed_folder,
                reason=UnresolvedQueueRemovalReason.bound_planned_chain_visible,
                outcome_ix=child_ix,
                expected_target_canonical=dest_path,
                verify_visible_outcome=False,
            )
            if mk2:
                applied_count += 1
            if fen_pb:
                log_info(
                    "destination_forensic_proposed_bind_candidate_outcome",
                    stable_key_excerpt=pf_key,
                    attached=bool(mk2),
                    mode="local_append_child_payloads",
                    skip_reason="" if mk2 else "mark_proposed_folder_resolved_returned_false",
                )
        if fen_pb:
            log_info(
                "destination_forensic_proposed_bind_exit",
                parent_canonical_path_excerpt=str(parent_path)[:400],
                total_proposed_folder_records_applied=int(applied_count),
                graph_child_load_requested=bool(need_graph_child_load and graph_auth),
            )
        if graph_auth and attach_ix.isValid() and not _materialize_recursive_pass:
            self._materialize_planned_workspace_proposed_descendants_fixpoint(attach_ix)
        if graph_auth and need_graph_child_load:
            col0_ld = attach_ix.siblingAtColumn(0) if attach_ix.column() != 0 else attach_ix
            if col0_ld.isValid():
                self._request_graph_destination_children_load(col0_ld, reason="proposed_child_pending")
        return applied_count

    def _find_destination_child_by_allocation_equivalence(self, parent_item, move):
        """Match planned allocation path using the same rules as the old exists_under check.

        `_find_destination_child_by_path` can miss real SharePoint rows when only
        `item_path`/`display_path` line up via `_paths_equivalent`, which previously caused
        `_apply_allocation_children_to_item` to skip without upgrading the real child.
        """
        if parent_item is None or move is None:
            return None
        normalized_target = self._allocation_projection_path(move)
        if isinstance(parent_item, QModelIndex):
            model = getattr(self, "destination_planning_model", None)
            if model is None:
                return None
            for r in range(model.rowCount(parent_item)):
                ix = model.index(r, 0, parent_item)
                child_data = ix.data(Qt.UserRole) or {}
                if child_data.get("placeholder"):
                    continue
                child_path = child_data.get("item_path") or child_data.get("display_path") or ""
                if self._paths_equivalent(child_path, normalized_target, "destination"):
                    return ix
            return None
        return None

    def _ensure_planned_allocation_overlay_on_real_model_index(self, parent_ix, child_ix, move):
        model = getattr(self, "destination_planning_model", None)
        if model is None or not child_ix.isValid():
            return
        node_data = dict(child_ix.data(Qt.UserRole) or {})
        if self.node_is_planned_allocation(node_data):
            if not destination_payload_is_live_graph_row(node_data):
                source_node = move.get("source", {})
                is_folder_src = bool(source_node.get("is_folder", True))
                node_data["is_folder"] = is_folder_src
                node_data["row_kind"] = "planned_folder" if is_folder_src else "planned_file"
                if not is_folder_src:
                    node_data["children_loaded"] = True
            self._apply_tree_item_visual_state(None, node_data)

            def _m_same(p):
                p.clear()
                p.update(node_data)

            model.update_payload_for_index(child_ix, _m_same)
            self._refresh_destination_item_visibility_index(child_ix)
            if bool(node_data.get("is_folder", True)):
                self._dev_log_destination_folder_allocation_lifecycle(
                    "folder_allocation_badge_refresh_only",
                    self._tree_item_path(node_data),
                    source="_ensure_planned_allocation_overlay_on_real_model_index",
                )
            return
        parent_data = parent_ix.data(Qt.UserRole) or {}
        parent_path = self._tree_item_path(parent_data)
        source_node = move.get("source", {})
        source_name = self._move_target_name(move) or source_node.get("name", "Allocated Item")
        is_folder = bool(source_node.get("is_folder", True))
        base_label = self._tree_name_column_label(source_name, tag="[Allocated]")
        projection_path = (
            self._canonical_destination_projection_path(f"{parent_path}\\{source_name}")
            if parent_path
            else self._allocation_projection_path(move)
        )
        projection_path = projection_path or self._allocation_projection_path(move)
        node_data["planned_allocation"] = True
        node_data["node_origin"] = "PlannedAllocation"
        node_data["overlay_state"] = "PlannedAllocation"
        node_data["source_path"] = move.get("source_path", "")
        node_data["display_path"] = projection_path
        node_data["item_path"] = projection_path
        node_data["destination_path"] = projection_path
        node_data["base_display_label"] = base_label
        if not destination_payload_is_live_graph_row(node_data):
            node_data["is_folder"] = is_folder
            node_data["row_kind"] = "planned_folder" if is_folder else "planned_file"
            if not is_folder:
                node_data["children_loaded"] = True
        self._apply_tree_item_visual_state(None, node_data)

        def _m(p):
            p.clear()
            p.update(node_data)

        model.update_payload_for_index(child_ix, _m)
        self._refresh_destination_item_visibility_index(child_ix)
        if is_folder:
            self._dev_log_destination_folder_allocation_lifecycle(
                "folder_allocation_badge_attached",
                projection_path,
                source="_ensure_planned_allocation_overlay_on_real_model_index",
            )

    def _build_allocation_payload(self, move, parent_data):
        source_node = move.get("source", {})
        source_name = self._move_target_name(move) or source_node.get("name", "Allocated Item")
        is_folder = bool(source_node.get("is_folder", True))
        base_label = self._tree_name_column_label(source_name, tag="[Allocated]")
        parent_path = self._tree_item_path(parent_data)
        projection_path = (
            self._canonical_destination_projection_path(f"{parent_path}\\{source_name}")
            if parent_path
            else self._allocation_projection_path(move)
        )
        projection_path = projection_path or self._allocation_projection_path(move)
        node_data = {
            "row_kind": "planned_folder" if is_folder else "planned_file",
            "id": "",
            "graph_item_id": "",
            "overlay_node_id": new_overlay_node_id("allocation", projection_path),
            "name": source_name,
            "real_name": source_name,
            "display_path": projection_path,
            "item_path": projection_path,
            "destination_path": projection_path,
            "source_path": move.get("source_path", ""),
            "tree_role": "destination",
            "drive_id": parent_data.get("drive_id", ""),
            "site_id": parent_data.get("site_id", ""),
            "site_name": parent_data.get("site_name", ""),
            "library_id": parent_data.get("library_id", ""),
            "library_name": parent_data.get("library_name", ""),
            "is_folder": is_folder,
            "children_loaded": not bool(is_folder),
            "load_failed": False,
            "node_origin": "PlannedAllocation",
            "overlay_state": "PlannedAllocation",
            "planned_allocation": True,
            "web_url": parent_data.get("web_url", ""),
            "base_display_label": base_label,
            **overlay_row_marker("allocation"),
        }
        self._apply_tree_item_visual_state(None, node_data)
        return node_data

    def _build_projected_allocation_descendant_item(self, source_node_data, destination_path, parent_data):
        source_name = source_node_data.get("name", "") or self._path_segments(destination_path)[-1]
        is_folder = bool(source_node_data.get("is_folder", False))
        base_label = self._tree_name_column_label(source_name)
        node = QTreeWidgetItem([base_label, "", "", ""])
        normalized_path = self._canonical_destination_projection_path(destination_path) or self.normalize_memory_path(destination_path)
        node_data = self._build_destination_allocation_descendant_node_data(source_node_data, normalized_path, parent_data)
        node_data["base_display_label"] = base_label
        node.setData(0, Qt.UserRole, node_data)
        node.setChildIndicatorPolicy(QTreeWidgetItem.ShowIndicator if is_folder else QTreeWidgetItem.DontShowIndicator)
        self._apply_tree_item_visual_state(node, node_data)
        return node

    def _build_projected_allocation_descendant_payload(self, source_node_data, destination_path, parent_data):
        source_name = source_node_data.get("name", "") or self._path_segments(destination_path)[-1]
        is_folder = bool(source_node_data.get("is_folder", False))
        base_label = self._tree_name_column_label(source_name)
        normalized_path = self._canonical_destination_projection_path(destination_path) or self.normalize_memory_path(
            destination_path
        )
        node_data = self._build_destination_allocation_descendant_node_data(source_node_data, normalized_path, parent_data)
        node_data["base_display_label"] = base_label
        self._apply_tree_item_visual_state(None, node_data)
        return node_data

    def _apply_proposed_overlay_to_existing_graph_row_model_index(self, ix, proposed_folder, parent_data) -> None:
        model = getattr(self, "destination_planning_model", None)
        if model is None or not ix.isValid():
            return
        if hasattr(model, "is_index_live") and not model.is_index_live(ix):
            return
        _psk = self._ensure_proposed_folder_stable_key(proposed_folder)
        template = self._build_proposed_payload(proposed_folder, parent_data)
        existing = dict(ix.data(Qt.UserRole) or {})
        gid = str(existing.get("graph_item_id") or existing.get("id") or "").strip()
        merged = dict(existing)
        merged["proposed_folder_stable_id"] = _psk
        merged["proposed"] = True
        merged["node_origin"] = "Proposed"
        merged["overlay_state"] = "proposed"
        merged["overlay_node_id"] = template.get("overlay_node_id")
        merged["base_display_label"] = template.get("base_display_label", merged.get("base_display_label"))
        merged["id"] = gid
        merged["graph_item_id"] = gid
        merged.update(overlay_row_marker("proposed"))
        self._apply_tree_item_visual_state(None, merged)

        def _mut(p, m=merged):
            p.clear()
            p.update(m)

        model.update_payload_for_index(ix, _mut)

    def _apply_allocation_descendant_overlay_to_existing_model_index(
        self, ix: QModelIndex, source_desc_data: dict, dest_path: str, parent_data: dict
    ) -> None:
        dmodel = getattr(self, "destination_planning_model", None)
        if dmodel is None or not ix.isValid():
            return
        if hasattr(dmodel, "is_index_live") and not dmodel.is_index_live(ix):
            return
        existing = dict(ix.data(Qt.UserRole) or {})
        norm = self._canonical_destination_projection_path(dest_path) or self.normalize_memory_path(dest_path)
        template = self._build_destination_allocation_descendant_node_data(source_desc_data, norm, parent_data)
        merged = dict(template)
        for k in (
            "id",
            "graph_item_id",
            "drive_id",
            "site_id",
            "site_name",
            "library_id",
            "library_name",
            "web_url",
        ):
            v = existing.get(k)
            if v is not None and str(v).strip() != "":
                merged[k] = v
        gid = str(existing.get("graph_item_id") or existing.get("id") or "").strip()
        tmpl_folder = bool(template.get("is_folder"))
        if destination_payload_is_live_graph_row(existing):
            merged["id"] = gid
            merged["graph_item_id"] = gid
            merged["is_folder"] = bool(existing.get("is_folder", tmpl_folder))
        elif not gid and destination_payload_is_planned_workspace_row(existing):
            merged["id"] = ""
            merged["graph_item_id"] = ""
            merged["is_folder"] = tmpl_folder
            merged["row_kind"] = "planned_folder" if tmpl_folder else "planned_file"
            merged["verification_state"] = existing.get("verification_state") or "planned_only"
            merged["workspace_planned_row"] = True
            if existing.get("planning_uuid"):
                merged["planning_uuid"] = existing.get("planning_uuid")
        else:
            merged["id"] = gid
            merged["graph_item_id"] = gid
            # Source-derived template wins for overlay / projected rows. A row may have been a
            # projected folder segment before teardown or path churn; re-applying a file move must
            # not preserve stale is_folder=True from the old payload (regression: file shows as folder).
            if destination_payload_is_live_graph_row(existing):
                merged["is_folder"] = bool(existing.get("is_folder", tmpl_folder))
            else:
                merged["is_folder"] = tmpl_folder
                merged["row_kind"] = str(
                    template.get("row_kind") or ("planned_folder" if tmpl_folder else "planned_file")
                )
        if merged["is_folder"]:
            merged["children_loaded"] = bool(existing.get("children_loaded"))
            merged["load_failed"] = bool(existing.get("load_failed"))
        else:
            merged["children_loaded"] = bool(existing.get("children_loaded", True))
            merged["load_failed"] = bool(existing.get("load_failed", False))
        src_nm = source_desc_data.get("name", "") or (self._path_segments(norm)[-1] if norm else "")
        merged["base_display_label"] = self._tree_name_column_label(src_nm)
        self._apply_tree_item_visual_state(None, merged)
        self._destination_leaf_forensic_trace_payload(
            "_apply_allocation_descendant_overlay_to_existing_model_index", merged, "overlay_template_merge"
        )

        def _mut(p, m=merged):
            p.clear()
            p.update(m)

        dmodel.update_payload_for_index(ix, _mut)

    def _decorate_destination_graph_subtree_for_allocation_move(
        self,
        alloc_folder_ix: QModelIndex,
        move,
        *,
        on_complete=None,
        enqueue_reason: str = "",
        collect_reason: str = "",
        user_initiated: bool = False,
        idle_bounded: bool = False,
        explicit_repair_authorized: bool = False,
        expand_auth_class: str | None = None,
    ) -> int:
        """Project source subtree under a Graph-auth allocation folder (chunked; no single-wave bind).

        Reuses existing destination rows when paths match; otherwise injects one planned segment per timer slice.
        """
        self._enqueue_destination_descendant_apply_to_model(
            alloc_folder_ix,
            move,
            on_complete,
            enqueue_reason=enqueue_reason,
            collect_reason=collect_reason,
            user_initiated=bool(user_initiated),
            idle_bounded=bool(idle_bounded),
            explicit_repair_authorized=bool(explicit_repair_authorized),
            expand_auth_class=expand_auth_class,
        )
        return 0

    def _pause_destination_descendant_apply_for_finalize_alloc(self) -> None:
        """Stop allocation-descendant apply while merge finalize runs alloc_step (lazy_ap / lazy_df)."""
        if getattr(self, "_destination_descendant_apply_paused_for_finalize_alloc", False):
            return
        self._destination_descendant_apply_paused_for_finalize_alloc = True
        t = getattr(self, "_destination_descendant_apply_timer", None)
        if t is not None and t.isActive():
            t.stop()

    def _resume_destination_descendant_apply_after_finalize_alloc(self) -> None:
        """Restart descendant apply after finalize alloc_step (or merge cancel)."""
        if not getattr(self, "_destination_descendant_apply_paused_for_finalize_alloc", False):
            return
        self._destination_descendant_apply_paused_for_finalize_alloc = False
        if self._destination_descendant_apply_state is not None or self._destination_descendant_apply_queue:
            self._schedule_destination_descendant_apply_tick()

    def _schedule_destination_descendant_apply_tick(self) -> None:
        if getattr(self, "_application_shutting_down", False):
            return
        if getattr(self, "_destination_descendant_apply_paused_for_finalize_alloc", False):
            return
        t = getattr(self, "_destination_descendant_apply_timer", None)
        if t is None:
            if getattr(self, "_destination_descendant_apply_tick_running", False):
                self._post_tick_inline_descendant_schedule_pending = True
                self._destination_post_tick_deferred_boundary_log(
                    "inline_descendant_schedule_deferred_tick_running",
                )
                return
            self._destination_descendant_apply_inline_drain = True
            try:
                while getattr(self, "_destination_descendant_apply_state", None) is not None or getattr(
                    self, "_destination_descendant_apply_queue", None
                ):
                    self._run_destination_descendant_apply_tick()
            finally:
                self._destination_descendant_apply_inline_drain = False
            return
        if not t.isActive():
            t.start(0)

    def _destination_allocation_projection_resume_token(self, move, source_root_data) -> str:
        """Stable token tying persisted resume cursor to source subtree cache + allocation destination (not Graph structure)."""
        if not isinstance(move, dict):
            return ""
        try:
            sk = self._source_projection_descendants_cache_key_graph_subtree_stable(source_root_data or {})
        except Exception:
            sk = ()
        dest = self._allocation_projection_path(move) or ""
        dest_c = self._canonical_destination_projection_path(dest) or ""
        raw = f"{sk!s}|{dest_c}"
        try:
            return hashlib.sha256(raw.encode("utf-8")).hexdigest()[:32]
        except Exception:
            return ""

    def _destination_flush_descendant_apply_resume_to_model_payloads(self) -> None:
        """Stamp snapshot-bound allocation rows with graph-descendant apply cursor so session capture can resume after restart."""
        dm = getattr(self, "destination_planning_model", None)
        if dm is None:
            return
        st = getattr(self, "_destination_descendant_apply_state", None)
        if not isinstance(st, dict) or not st.get("graph_walk"):
            return
        pix = st.get("parent_ix")
        move = st.get("move")
        descendants = list(st.get("descendants") or [])
        if not isinstance(pix, QModelIndex) or not pix.isValid() or not isinstance(move, dict):
            return
        col0 = pix.siblingAtColumn(0) if pix.column() != 0 else pix
        if not col0.isValid():
            return
        source_item = self._find_source_item_for_planned_move(move)
        source_root_data = self._source_tree_row_payload(source_item) if source_item is not None else {}
        if not source_root_data:
            source_root_data = dict(move.get("source", {}) or {})
            source_root_data.setdefault("item_path", move.get("source_path", ""))
            source_root_data.setdefault("display_path", move.get("source_path", ""))
        token = self._destination_allocation_projection_resume_token(move, source_root_data)
        if not token:
            return
        desc_idx = int(st.get("desc_index") or 0)
        total = len(descendants)

        def _mut(p):
            p["allocation_projection_resume_source_token"] = token
            p["allocation_projection_resume_desc_index"] = desc_idx
            p["allocation_projection_resume_descendants_total"] = total

        try:
            dm.update_payload_for_index(col0, _mut)
        except Exception:
            pass

    def _destination_flush_pending_leaf_batches_for_snapshot_capture(self) -> None:
        """Append batched file leaves to the model before walking the tree for JSON snapshot.

        Non-graph allocation apply batches file descendants in ``pending_leaf_batches`` and flushes on
        folder boundaries; if capture runs between batches, :meth:`rowCount` can omit those rows even
        though the UI already painted them from prior appends in the same tick slice.
        """
        st = getattr(self, "_destination_descendant_apply_state", None)
        if not isinstance(st, dict):
            return
        model = st.get("model")
        if model is None:
            return
        pending = st.get("pending_leaf_batches") or {}
        if not pending:
            return
        self._allocation_apply_flush_all_pending_model(
            model, st.get("child_map_cache") or {}, pending
        )

    def _snapshot_capture_shutdown_drain_deadline_s(self) -> float:
        """Wall-clock budget for draining in-flight descendant apply during shutdown snapshot capture.

        Default 120s — insufficient drain (previously 12s) produced ``deadline_shutdown_cap`` with queue/state
        still active, so ``DestinationTreeSnapshot`` was serialized mid graph-walk. Override via
        ``OZLINK_SNAPSHOT_DRAIN_SHUTDOWN_S`` (15–600).
        """
        raw = os.environ.get("OZLINK_SNAPSHOT_DRAIN_SHUTDOWN_S", "").strip()
        if raw:
            try:
                v = float(raw)
                return max(15.0, min(600.0, v))
            except ValueError:
                pass
        return 120.0

    def _snapshot_capture_drain_no_progress_cap(self) -> int:
        """Max consecutive drain ticks with an identical progress fingerprint before early exit.

        Bounded snapshot capture must not spin when descendant state cannot advance. Override for tests
        via ``OZLINK_SNAPSHOT_DRAIN_NO_PROGRESS_TICKS`` (16–20000); default 512.
        """
        raw = os.environ.get("OZLINK_SNAPSHOT_DRAIN_NO_PROGRESS_TICKS", "").strip()
        if raw:
            try:
                v = int(raw)
                return max(16, min(20000, v))
            except ValueError:
                pass
        return 512

    def _destination_descendant_apply_drain_log_graph_tick_slice_if_needed(self, slice_kind: str) -> None:
        if not getattr(self, "_destination_snapshot_capture_drain_active", False):
            return
        sk = str(slice_kind or "")[:80]
        hot = sk in (
            "graph_flat",
            "graph_dead_or_terminal",
            "graph_progress",
            "graph_nested_noop",
            "non_graph_tick",
        )
        n = int(getattr(self, "_destination_descendant_apply_drain_slice_log_counter", 0) or 0) + 1
        setattr(self, "_destination_descendant_apply_drain_slice_log_counter", n)
        if not hot and n % 48 != 0:
            return
        st = getattr(self, "_destination_descendant_apply_state", None)
        liv = -1
        if isinstance(st, dict) and st.get("graph_walk"):
            try:
                liv = int(st.get("_snapshot_drain_graph_liveness") or 0)
            except Exception:
                liv = -1
        log_info(
            "descendant_apply_graph_tick_slice",
            slice_kind=sk,
            graph_walk_heartbeat=int(liv),
            snapshot_capture_drain_active=True,
        )

    def _destination_descendant_apply_drain_note_graph_tick_end(
        self, slice_kind: str, *, bump_liveness: bool | None = None
    ) -> None:
        """Record last descendant-apply tick slice for snapshot-capture drain (stall + fingerprint).

        When ``_destination_snapshot_capture_drain_active`` and ``bump_liveness`` allow, increments
        ``st['_snapshot_drain_graph_liveness']`` so drain can observe alive graph-walk ticks that do
        not mutate desc_index / seg_index / overlay_count (scroll deferral, yields, budget slices).
        """
        sk = str(slice_kind or "")[:80]
        setattr(self, "_destination_descendant_apply_drain_last_tick_slice_kind", sk)
        if bump_liveness is None:
            bump_liveness = sk in (
                "graph_scroll_deferred",
                "graph_yield_waiting",
                "graph_progress",
                "graph_budget_slice",
                "graph_inline_defer",
            )
        if bump_liveness and getattr(self, "_destination_snapshot_capture_drain_active", False):
            st = getattr(self, "_destination_descendant_apply_state", None)
            if isinstance(st, dict) and st.get("graph_walk"):
                try:
                    st["_snapshot_drain_graph_liveness"] = int(st.get("_snapshot_drain_graph_liveness") or 0) + 1
                except Exception:
                    st["_snapshot_drain_graph_liveness"] = 1
        self._destination_descendant_apply_drain_log_graph_tick_slice_if_needed(sk)

    def _destination_descendant_apply_drain_finalize_graph_walk_tick_slice(self, graph_ops: int, exit_kind: str) -> None:
        st = getattr(self, "_destination_descendant_apply_state", None)
        lk0 = str(getattr(self, "_destination_descendant_apply_drain_last_tick_slice_kind", "") or "")
        if lk0 == "graph_dead_or_terminal" and st is None:
            return
        ex = str(exit_kind or "")
        if isinstance(st, dict) and st.get("graph_walk"):
            if ex == "graph_yield_waiting":
                self._destination_descendant_apply_drain_note_graph_tick_end("graph_yield_waiting")
            elif ex == "graph_budget_slice":
                self._destination_descendant_apply_drain_note_graph_tick_end("graph_budget_slice")
            elif ex == "graph_inline_defer":
                self._destination_descendant_apply_drain_note_graph_tick_end("graph_inline_defer")
            elif int(graph_ops or 0) > 0:
                self._destination_descendant_apply_drain_note_graph_tick_end("graph_progress")
            elif ex == "":
                self._destination_descendant_apply_drain_note_graph_tick_end("graph_flat", bump_liveness=False)
            else:
                self._destination_descendant_apply_drain_note_graph_tick_end("graph_flat", bump_liveness=False)
        else:
            self._destination_descendant_apply_drain_note_graph_tick_end("non_graph_tick", bump_liveness=False)

    def _destination_snapshot_capture_drain_progress_fingerprint(self) -> tuple[Any, ...]:
        """Cheap fingerprint for bounded snapshot-capture drain stall detection (not a full model walk)."""
        dq = getattr(self, "_destination_descendant_apply_queue", None)
        try:
            qlen = len(dq) if dq is not None else 0
        except Exception:
            qlen = 0
        ltk = str(getattr(self, "_destination_descendant_apply_drain_last_tick_slice_kind", "") or "")[:80]
        st = getattr(self, "_destination_descendant_apply_state", None)
        if not isinstance(st, dict):
            return (qlen, None, ltk)
        pending = st.get("pending_leaf_batches") or {}
        pend_items = 0
        if isinstance(pending, dict):
            for _k, rows in pending.items():
                try:
                    pend_items += len(rows) if rows is not None and hasattr(rows, "__len__") else 0
                except Exception:
                    pass
        sg_cur = None
        liv = -1
        if st.get("graph_walk"):
            m = st.get("model")
            sgf = getattr(m, "structure_generation", None) if m is not None else None
            if callable(sgf):
                try:
                    sg_cur = int(sgf())
                except Exception:
                    sg_cur = None
            try:
                liv = int(st.get("_snapshot_drain_graph_liveness") or 0)
            except Exception:
                liv = -1
        return (
            qlen,
            str(st.get("walk_phase") or ""),
            bool(st.get("graph_walk")),
            int(st.get("added_count") or 0),
            int(st.get("desc_index") or 0),
            int(st.get("seg_index") or 0),
            int(st.get("overlay_count") or 0),
            pend_items,
            int(sg_cur) if sg_cur is not None else -1,
            ltk,
            int(liv),
        )

    def _destination_shutdown_capture_cutoff_graph_walk_for_snapshot(self, st: dict) -> None:
        """End in-flight graph-walk allocation descendant apply cheaply during shutdown snapshot capture.

        Live graph-walk ticks can spend the entire shutdown wall budget materializing descendants. For
        close we flush pending file batches, run the normal graph finalize bookkeeping (mark applied,
        callbacks, snapshot promotion when not suppressed by drain), then clear state so persist can
        proceed. Remaining path segments are not applied in this pass (best-effort snapshot).
        """
        if not isinstance(st, dict) or not st.get("graph_walk"):
            return
        n_ev = int(getattr(self, "_destination_shutdown_capture_graph_cutoff_events", 0) or 0)
        self._destination_shutdown_capture_graph_cutoff_events = n_ev + 1
        added = int(st.get("added_count") or 0)
        desc_i = int(st.get("desc_index") or 0)
        pend = st.get("pending_leaf_batches") or {}
        pend_n = 0
        if isinstance(pend, dict):
            for _k, rows in pend.items():
                try:
                    pend_n += len(rows) if rows is not None and hasattr(rows, "__len__") else 0
                except Exception:
                    pass
        log_info(
            "destination_shutdown_capture_graph_walk_cutoff",
            reason="shutdown_snapshot_capture_disallows_deep_graph_walk_continuation",
            added_count_partial=added,
            desc_index=int(desc_i),
            pending_leaf_payload_rows_pending=int(pend_n),
            walk_phase=str(st.get("walk_phase") or ""),
        )
        model = st.get("model")
        try:
            if model is not None:
                self._allocation_apply_flush_all_pending_model(
                    model, st.get("child_map_cache") or {}, st.get("pending_leaf_batches") or {}
                )
            self._destination_descendant_apply_finalize_job(st)
        except Exception as exc:
            log_warn(
                "destination_shutdown_capture_graph_walk_cutoff_finalize_failed",
                error=str(exc)[:240],
            )
            try:
                self._destination_descendant_apply_abort_stale(st, abort_kind="shutdown_graph_walk_cutoff_abort")
            except Exception:
                pass
        finally:
            self._destination_descendant_apply_state = None

    def _destination_post_tick_deferred_boundary_log(self, event: str, **fields: Any) -> None:
        n = int(getattr(self, "_post_tick_deferred_boundary_log_counter", 0) or 0) + 1
        self._post_tick_deferred_boundary_log_counter = n
        always = ("post_tick_descendant_drain_executed", "post_tick_snapshot_refresh_executed")
        if n % 32 != 0 and str(event or "") not in always:
            return
        log_info(str(event or "")[:120], **fields)

    def _destination_run_post_tick_descendant_deferred(self) -> None:
        """Run snapshot drain / promotion / inline schedule deferred while a descendant tick held the guard."""
        if getattr(self, "_application_shutting_down", False):
            # Close/save may still run synchronous snapshot drain ticks; never revive persist/UI timers here.
            self._post_tick_descendant_drain_pending = False
            self._post_tick_snapshot_refresh_pending = False
            self._post_tick_inline_descendant_schedule_pending = False
            try:
                self._post_tick_descendant_deferred_reenter_depth = 0
            except Exception:
                pass
            return
        if getattr(self, "_destination_descendant_apply_tick_running", False):
            return
        if not (
            getattr(self, "_post_tick_descendant_drain_pending", False)
            or getattr(self, "_post_tick_snapshot_refresh_pending", False)
            or getattr(self, "_post_tick_inline_descendant_schedule_pending", False)
        ):
            return
        d = int(getattr(self, "_post_tick_descendant_deferred_reenter_depth", 0) or 0)
        if d >= 8:
            return
        self._post_tick_descendant_deferred_reenter_depth = d + 1
        ran_drain = False
        ran_snap = False
        ran_inline = False
        try:
            if getattr(self, "_post_tick_descendant_drain_pending", False):
                self._post_tick_descendant_drain_pending = False
                ran_drain = True
                log_info("post_tick_descendant_drain_executed")
                try:
                    self._destination_finalize_inflight_descendant_apply_for_snapshot_capture()
                except Exception:
                    pass
            if getattr(self, "_post_tick_snapshot_refresh_pending", False):
                self._post_tick_snapshot_refresh_pending = False
                ran_snap = True
                log_info("post_tick_snapshot_refresh_executed")
                try:
                    self._destination_descendant_snapshot_coalesce_post_tick_refreshes += 1
                except Exception:
                    pass
                try:
                    self._promote_destination_workspace_snapshot_after_structure_change()
                except Exception:
                    pass
            if getattr(self, "_post_tick_inline_descendant_schedule_pending", False):
                self._post_tick_inline_descendant_schedule_pending = False
                ran_inline = True
                self._schedule_destination_descendant_apply_tick()
        finally:
            self._post_tick_descendant_deferred_reenter_depth = d
        if ran_drain or ran_snap or ran_inline:
            log_info(
                "post_tick_descendant_deferred_summary",
                ran_drain=bool(ran_drain),
                ran_snapshot_refresh=bool(ran_snap),
                ran_inline_schedule=bool(ran_inline),
            )

    def _destination_finalize_inflight_descendant_apply_for_snapshot_capture(self) -> None:
        """Bounded synchronous drain so session capture matches visible planning-model rows.

        Timer-sliced descendant injection may leave work in the active state or queue when autosave/close
        captures; without draining, :meth:`_serialize_source_model_subtree_snapshot` sees fewer children
        than the view (``rowCount`` includes only rows already linked under each parent node).

        During shutdown, :meth:`closeEvent` defers :meth:`_abort_destination_descendant_apply_for_shutdown`
        until after :meth:`_save_draft_shell` so this drain can run against a non-empty queue within a
        bounded wall budget (``OZLINK_SNAPSHOT_DRAIN_SHUTDOWN_S``), then snapshot capture walks the
        materialized model.
        """
        if int(getattr(self, "_destination_snapshot_capture_drain_depth", 0) or 0) >= 1:
            return
        if getattr(self, "_destination_descendant_apply_paused_for_finalize_alloc", False):
            self._destination_flush_pending_leaf_batches_for_snapshot_capture()
            return
        if getattr(self, "_destination_descendant_apply_tick_running", False):
            self._post_tick_descendant_drain_pending = True
            try:
                self._destination_flush_pending_leaf_batches_for_snapshot_capture()
            except Exception:
                pass
            self._destination_post_tick_deferred_boundary_log("drain_deferred_because_tick_running")
            return
        shutting = bool(getattr(self, "_application_shutting_down", False))
        if not shutting and self._destination_user_scroll_interaction_active():
            self._destination_snapshot_drain_deferred_for_scroll = True
            log_info(
                "background_snapshot_drain_paused_for_interaction",
                reason="destination_scroll_active",
            )
            t_idle = getattr(self, "_destination_tree_scroll_idle_timer", None)
            if t_idle is not None:
                idle_ms = max(120, int(getattr(self, "_destination_tree_scroll_idle_ms", 280) or 280))
                t_idle.start(idle_ms)
            return
        self._destination_snapshot_capture_drain_depth = 1
        self._destination_snapshot_capture_drain_active = True
        self._destination_descendant_apply_drain_slice_log_counter = 0
        t0 = time.perf_counter()
        shutdown_deadline_s = float(self._snapshot_capture_shutdown_drain_deadline_s()) if shutting else 0.0
        dq0 = getattr(self, "_destination_descendant_apply_queue", None)
        q0 = len(dq0) if dq0 else 0
        st0 = getattr(self, "_destination_descendant_apply_state", None)
        fc_pre = self._destination_forensic_destination_model_counts()
        pre_np = int(fc_pre.get("model_nodes_non_placeholder") or 0)
        if shutting:
            setattr(self, "_destination_shutdown_capture_pre_drain_model_np", pre_np)
            self._destination_shutdown_capture_graph_cutoff_events = 0
            log_info(
                "destination_shutdown_capture_drain_begin",
                model_nodes_iter_depth_first=int(fc_pre.get("model_nodes_iter_depth_first") or 0),
                model_nodes_non_placeholder=pre_np,
                queue_len_before=int(q0),
                descendant_apply_state_active=st0 is not None,
                graph_walk_active=bool((st0 or {}).get("graph_walk")) if isinstance(st0, dict) else False,
                shutdown_drain_budget_s=round(shutdown_deadline_s, 2),
                shutdown_graph_walk_deep_cutoff_policy_enabled=True,
                graph_walk_active_at_drain_begin=bool(
                    isinstance(st0, dict) and st0.get("graph_walk")
                ),
            )
        log_info(
            "destination_snapshot_capture_drain_begin",
            shutdown=bool(shutting),
            queue_len_before=int(q0),
            descendant_apply_state_active=st0 is not None,
            graph_walk_active=bool((st0 or {}).get("graph_walk")) if isinstance(st0, dict) else False,
            shutdown_drain_deadline_s=round(shutdown_deadline_s, 2) if shutting else None,
            model_nodes_non_placeholder_before=pre_np,
        )
        try:
            # Autosave: tight wall budget (~200ms). Shutdown: drain until queue/state idle or wall cap —
            # sibling reconcile during apply is suppressed while :attr:`_destination_snapshot_capture_drain_active`
            # so ``allocation_apply_model_index_yield`` cannot run unbounded full-tree reconcile passes.
            deadline_autosave = t0 + 0.2
            deadline_shutdown = t0 + shutdown_deadline_s
            max_ticks = 120000 if shutting else 600
            ticks = 0
            exit_reason = "idle"
            no_progress_cap = int(self._snapshot_capture_drain_no_progress_cap())
            stall_ticks = 0
            stall_peak = 0
            benign_stall_suppressed = 0
            self._destination_flush_pending_leaf_batches_for_snapshot_capture()
            prev_fp = self._destination_snapshot_capture_drain_progress_fingerprint()
            while ticks < max_ticks:
                dq = getattr(self, "_destination_descendant_apply_queue", None)
                st = getattr(self, "_destination_descendant_apply_state", None)
                qlen = len(dq) if dq else 0
                if qlen == 0 and st is None:
                    exit_reason = "idle"
                    break
                now = time.perf_counter()
                if shutting:
                    if now >= deadline_shutdown:
                        exit_reason = "deadline_shutdown_cap"
                        break
                elif now >= deadline_autosave:
                    exit_reason = "deadline_autosave"
                    break
                self._run_destination_descendant_apply_tick()
                ticks += 1
                cur_fp = self._destination_snapshot_capture_drain_progress_fingerprint()
                st_after = getattr(self, "_destination_descendant_apply_state", None)
                gw_active = isinstance(st_after, dict) and bool(st_after.get("graph_walk"))
                last_kind = str(getattr(self, "_destination_descendant_apply_drain_last_tick_slice_kind", "") or "")
                benign_gw_stall = bool(
                    gw_active
                    and last_kind
                    in (
                        "graph_nested_noop",
                        "graph_scroll_deferred",
                        "graph_yield_waiting",
                        "graph_budget_slice",
                        "graph_inline_defer",
                        "graph_progress",
                    )
                )
                if cur_fp == prev_fp:
                    if benign_gw_stall:
                        stall_ticks = 0
                        benign_stall_suppressed += 1
                    else:
                        stall_ticks += 1
                        if stall_ticks > stall_peak:
                            stall_peak = stall_ticks
                        if stall_ticks >= no_progress_cap:
                            exit_reason = "no_progress_stall"
                            break
                else:
                    stall_ticks = 0
                    prev_fp = cur_fp
            else:
                exit_reason = "max_ticks"
            self._destination_flush_pending_leaf_batches_for_snapshot_capture()
            dq1 = getattr(self, "_destination_descendant_apply_queue", None)
            q1 = len(dq1) if dq1 else 0
            st1 = getattr(self, "_destination_descendant_apply_state", None)
            wall_ms = round((time.perf_counter() - t0) * 1000.0, 2)
            liv_end = -1
            if isinstance(st1, dict) and st1.get("graph_walk"):
                try:
                    liv_end = int(st1.get("_snapshot_drain_graph_liveness") or 0)
                except Exception:
                    liv_end = -1
            log_info(
                "destination_snapshot_capture_descendant_apply_drain",
                tick_count=int(ticks),
                wall_ms=wall_ms,
                shutdown=bool(shutting),
                queue_len_before=int(q0),
                queue_len_after=int(q1),
                descendant_apply_state_after=st1 is not None,
                exit_reason=str(exit_reason),
                shutdown_drain_deadline_s=round(shutdown_deadline_s, 2) if shutting else None,
                no_progress_cap=int(no_progress_cap),
                no_progress_stall_peak=int(stall_peak),
                last_graph_tick_slice_kind=str(
                    getattr(self, "_destination_descendant_apply_drain_last_tick_slice_kind", "") or ""
                )[:80],
                graph_walk_liveness_heartbeat=int(liv_end),
                graph_drain_stall_benign_suppressed_ticks=int(benign_stall_suppressed),
                shutdown_descendant_tick_skip_logs_suppressed=int(
                    getattr(self, "_shutdown_descendant_tick_skip_logs_suppressed", 0) or 0
                ),
                shutdown_graph_walk_cutoff_events=int(
                    getattr(self, "_destination_shutdown_capture_graph_cutoff_events", 0) or 0
                ),
            )
            if (
                str(exit_reason) == "no_progress_stall"
                and (st1 is not None or int(q1) > 0)
                and not shutting
            ):
                stall_fp = self._destination_snapshot_capture_drain_progress_fingerprint()
                stall_last_kind = str(
                    getattr(self, "_destination_descendant_apply_drain_last_tick_slice_kind", "") or ""
                )[:80]
                self._destination_descendant_apply_force_clear_on_stall(
                    exit_reason=str(exit_reason),
                    queue_len_after=int(q1),
                    state_active=bool(st1 is not None),
                    drain_fingerprint=stall_fp,
                    stall_ticks=int(stall_ticks),
                    last_graph_tick_slice_kind=stall_last_kind,
                    force_clear_due_true_dead_stall=True,
                )
            if shutting and exit_reason == "deadline_shutdown_cap" and (q1 > 0 or st1 is not None):
                log_warn(
                    "destination_snapshot_capture_drain_incomplete",
                    queue_len_after=int(q1),
                    descendant_apply_state_after=st1 is not None,
                    wall_ms=wall_ms,
                    shutdown_drain_deadline_s=round(shutdown_deadline_s, 2),
                    hint="Raise OZLINK_SNAPSHOT_DRAIN_SHUTDOWN_S (15–600) if snapshots miss allocation descendants after close.",
                )
            if shutting:
                fc_post = self._destination_forensic_destination_model_counts()
                post_np = int(fc_post.get("model_nodes_non_placeholder") or 0)
                pre_stored = getattr(self, "_destination_shutdown_capture_pre_drain_model_np", None)
                try:
                    pre_int = int(pre_stored) if pre_stored is not None else -1
                except Exception:
                    pre_int = -1
                log_info(
                    "destination_shutdown_capture_drain_end",
                    model_nodes_iter_depth_first=int(fc_post.get("model_nodes_iter_depth_first") or 0),
                    model_nodes_non_placeholder_after=post_np,
                    model_nodes_non_placeholder_before=pre_int if pre_int >= 0 else None,
                    materialization_delta=(post_np - pre_int) if pre_int >= 0 else None,
                    queue_len_after=int(q1),
                    descendant_apply_state_after=bool(st1 is not None),
                    elapsed_ms=wall_ms,
                    exit_reason=str(exit_reason),
                    tick_count=int(ticks),
                    no_progress_cap=int(no_progress_cap),
                    no_progress_stall_peak=int(stall_peak),
                    shutdown_descendant_tick_skip_logs_suppressed=int(
                        getattr(self, "_shutdown_descendant_tick_skip_logs_suppressed", 0) or 0
                    ),
                    shutdown_graph_walk_cutoff_events=int(
                        getattr(self, "_destination_shutdown_capture_graph_cutoff_events", 0) or 0
                    ),
                    shutdown_graph_walk_deep_continuation_stopped=bool(
                        int(getattr(self, "_destination_shutdown_capture_graph_cutoff_events", 0) or 0) > 0
                    ),
                    descendant_apply_state_remaining_for_post_save_abort=bool(st1 is not None),
                )
        finally:
            self._destination_snapshot_capture_drain_active = False
            self._destination_snapshot_capture_drain_depth = 0

    def _build_destination_graph_allocation_descendant_apply_state(
        self,
        parent_ix: QModelIndex,
        move,
        on_complete,
        *,
        enqueue_reason: str = "",
        collect_reason: str = "",
        user_initiated: bool = False,
        idle_bounded: bool = False,
    ):
        """Graph-authority allocation descendant projection: chunked (see :meth:`_decorate_destination_graph_subtree_for_allocation_move`)."""
        self._alloc_apply_sibling_reconcile_coalesce_key = None
        model = getattr(self, "destination_planning_model", None)
        if model is None:
            return None
        resolved_parent, _resolve_s = self._find_destination_allocation_descendant_parent_index(move)
        if resolved_parent is not None and resolved_parent.isValid():
            rp0 = resolved_parent.siblingAtColumn(0) if resolved_parent.column() != 0 else resolved_parent
            if not hasattr(model, "is_index_live") or model.is_index_live(rp0):
                parent_ix = rp0
        if not parent_ix.isValid():
            return None
        if hasattr(model, "is_index_live") and not model.is_index_live(parent_ix):
            ap_try = self._destination_graph_descendant_expected_allocation_folder_anchor_path(move)
            alt = (
                self._destination_graph_descendant_resolve_model_index_for_path(model, ap_try)
                if ap_try
                else None
            )
            if (
                alt is not None
                and alt.isValid()
                and (not hasattr(model, "is_index_live") or model.is_index_live(alt))
            ):
                parent_ix = alt
                log_info(
                    "descendant_apply_enqueue_parent_rebound_before_state_build",
                    path_excerpt=str(ap_try)[:400],
                    move_key_excerpt=str(self._allocation_move_key(move) or "")[:120],
                )
            else:
                log_info(
                    "destination_child_lookup_invalid_parent_index",
                    reason="allocation_apply_parent_not_live",
                    parent_path_hint=self._canonical_destination_projection_path(
                        self._tree_item_path(parent_ix.data(Qt.UserRole) or {})
                    ),
                )
                return None
        if not destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            return None
        parent_data = parent_ix.data(Qt.UserRole) or {}
        tree_or_proj = self._tree_item_path(parent_data) or self._allocation_projection_path(move)
        allocation_destination_path = self._canonical_destination_path_with_visible_library_anchor(tree_or_proj)
        if not allocation_destination_path:
            return None
        source_item = self._find_source_item_for_planned_move(move)
        source_root_data = self._source_tree_row_payload(source_item) if source_item is not None else {}
        if not source_root_data:
            source_root_data = dict(move.get("source", {}) or {})
            source_root_data.setdefault("item_path", move.get("source_path", ""))
            source_root_data.setdefault("display_path", move.get("source_path", ""))
        expected_is_folder = bool(parent_data.get("is_folder", True))
        if source_root_data and source_root_data.get("is_folder", None) is None:
            source_root_data["is_folder"] = expected_is_folder
        if not source_root_data or not bool(source_root_data.get("is_folder", expected_is_folder)):
            return None
        source_root_path = self._canonical_source_projection_path(self._tree_item_path(source_root_data))
        cr = str(collect_reason or "").strip() or str(enqueue_reason or "").strip() or "graph_allocation_descendant_apply"
        self._invalidate_source_projection_descendants_cache_for_allocation_root(
            source_root_data,
            reason=str(cr)[:200],
            caller="_build_destination_graph_allocation_descendant_apply_state",
        )
        descendants = self._sort_descendants_for_allocation_apply(
            self._collect_source_descendants_for_projection(source_root_data, move, collect_reason=cr)
        )
        if not descendants:
            log_info(
                "destination_allocation_descendant_source_data_available",
                graph_authority=True,
                descendant_count=0,
                source_item_bound=bool(source_item is not None),
                move_key_excerpt=str(self._allocation_move_key(move) or "")[:120],
            )
            if source_item is None:
                log_info(
                    "destination_allocation_descendant_source_data_missing",
                    graph_authority=True,
                    source_path_excerpt=str(move.get("source_path", "") or "")[:400],
                    move_key_excerpt=str(self._allocation_move_key(move) or "")[:120],
                )
                log_info(
                    "destination_allocation_descendant_waiting_for_source_branch",
                    graph_authority=True,
                    reason="source_tree_row_not_resolved_for_move",
                    source_path_excerpt=str(move.get("source_path", "") or "")[:400],
                )
        cur_token = self._destination_allocation_projection_resume_token(move, source_root_data)
        resume_tok = str(parent_data.get("allocation_projection_resume_source_token") or "").strip()
        try:
            resume_total = int(parent_data.get("allocation_projection_resume_descendants_total"))
        except (TypeError, ValueError):
            resume_total = -1
        try:
            resume_idx = int(parent_data.get("allocation_projection_resume_desc_index"))
        except (TypeError, ValueError):
            resume_idx = -1
        seeded_desc_index = 0
        if (
            cur_token
            and resume_tok
            and resume_tok == cur_token
            and resume_total == len(descendants)
            and 0 <= resume_idx <= len(descendants)
        ):
            seeded_desc_index = resume_idx
            log_info(
                "allocation_projection_resume_desc_index_seeded",
                desc_index=int(resume_idx),
                descendants_total=int(len(descendants)),
                token_suffix=cur_token[-8:],
            )
        _gen_snap = None
        _sg = getattr(model, "structure_generation", None)
        if callable(_sg):
            try:
                _gen_snap = int(_sg())
            except Exception:
                _gen_snap = None
        _dtot = int(len(descendants or []))
        _hth = int(self._destination_heavy_replay_threshold())
        _heavy = bool(_dtot >= _hth)
        if _heavy:
            log_info(
                "destination_heavy_descendant_classified_replay_job",
                expected_descendant_count=_dtot,
                threshold=int(_hth),
            )
        _g_bs = float(getattr(self, "_destination_graph_descendant_apply_budget_s", 0.01) or 0.01)
        if bool(idle_bounded):
            _g_bs = 0.025
            try:
                self._destination_idle_replay_ops_this_slice = 0
            except Exception:
                pass
            log_info(
                "destination_idle_replay_budget_applied",
                max_ms=25,
                max_nodes=50,
                expected_descendant_count=int(_dtot),
            )
        out = {
            "parent_ix": parent_ix,
            "move": move,
            "on_complete": on_complete,
            "projection_enqueue_reason": str(enqueue_reason or "")[:240],
            "projection_collect_reason": str(cr)[:240],
            "model": model,
            "parent_data": parent_data,
            "allocation_destination_path": allocation_destination_path,
            "source_root_path": source_root_path,
            "descendants": descendants,
            "desc_index": seeded_desc_index,
            "graph_walk": True,
            "graph_auth": True,
            "child_map_cache": {},
            "overlay_count": 0,
            "walk_phase": "next_descendant",
            "rel_clean": None,
            "base_canon": "",
            "base_parts": [],
            "projection_terminal": None,
            "descendant_data": None,
            "descendant_source_path": "",
            "seg_index": 0,
            "graph_budget_s": _g_bs,
            "graph_model_structure_generation_snap": _gen_snap,
            "_snapshot_drain_graph_liveness": 0,
            "heavy_replay": _heavy,
            "expected_descendant_total": _dtot,
            "user_initiated_replay": bool(user_initiated),
        }
        if bool(idle_bounded):
            out["idle_replay_bounded"] = True
            out["idle_replay_max_ops_per_slice"] = 50
        return out

    def _build_destination_descendant_apply_state(
        self,
        parent_ix: QModelIndex,
        move,
        on_complete,
        *,
        enqueue_reason: str = "",
        collect_reason: str = "",
        user_initiated: bool = False,
        idle_bounded: bool = False,
    ):
        self._alloc_apply_sibling_reconcile_coalesce_key = None
        model = getattr(self, "destination_planning_model", None)
        if model is None or not parent_ix.isValid():
            return None
        if hasattr(model, "is_index_live") and not model.is_index_live(parent_ix):
            log_info(
                "destination_child_lookup_invalid_parent_index",
                reason="allocation_apply_parent_not_live",
                parent_path_hint=self._canonical_destination_projection_path(
                    self._tree_item_path(parent_ix.data(Qt.UserRole) or {})
                ),
            )
            return None
        if destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            return self._build_destination_graph_allocation_descendant_apply_state(
                parent_ix,
                move,
                on_complete,
                enqueue_reason=enqueue_reason,
                collect_reason=collect_reason,
                user_initiated=bool(user_initiated),
                idle_bounded=bool(idle_bounded),
            )
        parent_data = parent_ix.data(Qt.UserRole) or {}
        allocation_destination_path = self._canonical_destination_projection_path(
            self._tree_item_path(parent_data) or self._allocation_projection_path(move)
        )
        if not allocation_destination_path:
            return None
        source_item = self._find_source_item_for_planned_move(move)
        source_root_data = self._source_tree_row_payload(source_item) if source_item is not None else {}
        if not source_root_data:
            source_root_data = dict(move.get("source", {}) or {})
            source_root_data.setdefault("item_path", move.get("source_path", ""))
            source_root_data.setdefault("display_path", move.get("source_path", ""))
        expected_is_folder = bool(parent_data.get("is_folder", True))
        if source_root_data and source_root_data.get("is_folder", None) is None:
            source_root_data["is_folder"] = expected_is_folder
        if not source_root_data or not bool(source_root_data.get("is_folder", expected_is_folder)):
            return None
        source_root_path = self._canonical_source_projection_path(self._tree_item_path(source_root_data))
        cr = str(collect_reason or "").strip() or str(enqueue_reason or "").strip() or "destination_descendant_apply_non_graph"
        descendants = self._collect_source_descendants_for_projection(source_root_data, move, collect_reason=cr)
        descendants = self._sort_descendants_for_allocation_apply(descendants)
        if not descendants:
            log_info(
                "destination_allocation_descendant_source_data_available",
                graph_authority=False,
                descendant_count=0,
                source_item_bound=bool(source_item is not None),
                move_key_excerpt=str(self._allocation_move_key(move) or "")[:120],
            )
            if source_item is None:
                log_info(
                    "destination_allocation_descendant_source_data_missing",
                    graph_authority=False,
                    source_path_excerpt=str(move.get("source_path", "") or "")[:400],
                )
                log_info(
                    "destination_allocation_descendant_waiting_for_source_branch",
                    graph_authority=False,
                    reason="source_tree_row_not_resolved_for_move",
                    source_path_excerpt=str(move.get("source_path", "") or "")[:400],
                )
        _ng_gen_snap = None
        _ng_sg = getattr(model, "structure_generation", None)
        if callable(_ng_sg):
            try:
                _ng_gen_snap = int(_ng_sg())
            except Exception:
                _ng_gen_snap = None
        return {
            "parent_ix": parent_ix,
            "move": move,
            "on_complete": on_complete,
            "projection_enqueue_reason": str(enqueue_reason or "")[:240],
            "projection_collect_reason": str(cr)[:240],
            "model": model,
            "parent_data": parent_data,
            "allocation_destination_path": allocation_destination_path,
            "source_root_path": source_root_path,
            "descendants": descendants,
            "desc_index": 0,
            "seg_index": 0,
            "relative_segments": None,
            "descendant_data": None,
            "current_parent_ix": parent_ix,
            "current_parent_data": parent_data,
            "child_map_cache": {},
            "pending_leaf_batches": {},
            "visibility_targets": {},
            "added_count": 0,
            "walk_phase": "next_descendant",
            "graph_model_structure_generation_snap": _ng_gen_snap,
        }

    def _destination_graph_descendant_apply_prepare_next_descendant(self, st) -> str:
        """Advance graph-authority walk to the next descendant (same filters as sync decorate)."""
        descendants = st["descendants"]
        parent_ix = st["parent_ix"]
        parent_data = st["parent_data"]
        allocation_destination_path = st["allocation_destination_path"]
        source_root_path = st["source_root_path"]
        model = st["model"]
        graph_auth = bool(st.get("graph_auth"))

        while st["desc_index"] < len(descendants):
            if st["desc_index"] > 0 and st["desc_index"] % 50 == 0:
                self._reconcile_destination_sibling_folders_during_allocation_apply("model_index_yield")
            rb = self._destination_graph_descendant_apply_try_rebind_parent_ix(st)
            if rb == "terminal":
                log_info(
                    "descendant_apply_graph_prepare_terminal_target_gone",
                    allocation_destination_path_excerpt=str(st.get("allocation_destination_path") or "")[:400],
                    move_key_excerpt=str(self._allocation_move_key(st.get("move")) or "")[:120],
                )
                return "stale"
            if rb == "yield":
                return "yield"
            parent_ix = st["parent_ix"]
            parent_data = st["parent_data"]
            if not parent_ix.isValid() or (hasattr(model, "is_index_live") and not model.is_index_live(parent_ix)):
                log_info(
                    "descendant_apply_graph_prepare_parent_still_not_live_after_rebind",
                    allocation_destination_path_excerpt=str(allocation_destination_path or "")[:400],
                )
                return "yield"
            descendant_data = descendants[st["desc_index"]]
            descendant_source_path = self._canonical_source_projection_path(self._tree_item_path(descendant_data))
            if descendant_source_path == source_root_path:
                st["desc_index"] += 1
                continue
            relative_segments = self._allocation_projection_relative_source_segments(
                source_root_path, descendant_source_path
            )
            if not relative_segments:
                st["desc_index"] += 1
                continue
            if self._source_tree_payload_implies_file_leaf(descendant_data) and self._is_leaf_path_excluded_for_plan(
                descendant_source_path
            ):
                st["desc_index"] += 1
                continue
            exact_move = self._find_exact_planned_move_for_source_path(descendant_source_path)
            if exact_move is not None:
                exact_join = self.normalize_memory_path(
                    "\\".join(
                        [
                            str(exact_move.get("destination_path", "") or ""),
                            self._move_target_name(exact_move),
                        ]
                    )
                )
                exact_bare = self._canonical_destination_projection_path(exact_join) or exact_join
                exact_destination_path = (
                    self._canonical_destination_path_with_visible_library_anchor(exact_bare)
                    if graph_auth
                    else exact_bare
                )
                dest_here_bare = self._canonical_destination_projection_path(
                    "\\".join([allocation_destination_path] + relative_segments)
                ) or self.normalize_memory_path("\\".join([allocation_destination_path] + relative_segments))
                dest_here = (
                    self._canonical_destination_path_with_visible_library_anchor(dest_here_bare)
                    if graph_auth
                    else dest_here_bare
                )
                if graph_auth:
                    em_cmp = (
                        self._canonical_planned_memory_path_for_graph_match(str(exact_destination_path or "").strip())
                        or str(exact_destination_path or "").strip()
                    )
                    dh_cmp = (
                        self._canonical_planned_memory_path_for_graph_match(str(dest_here or "").strip())
                        or str(dest_here or "").strip()
                    )
                else:
                    em_cmp = str(exact_destination_path or "").strip()
                    dh_cmp = str(dest_here or "").strip()
                paths_equivalent = bool(em_cmp and dh_cmp and em_cmp.casefold() == dh_cmp.casefold())
                exact_struct_invalid, exact_struct_reason = self._destination_structural_path_chain_invalid_for_container_parent(
                    str(exact_destination_path or "")
                )
                if exact_struct_invalid:
                    log_info(
                        "destination_exact_move_invalid_terminal_ignored",
                        descendant_source_path_excerpt=str(descendant_source_path)[:400],
                        inherited_projection_terminal_excerpt=str(dh_cmp)[:400],
                        exact_move_destination_terminal_excerpt=str(em_cmp)[:400],
                        allocation_destination_path_excerpt=str(allocation_destination_path)[:400],
                        exact_move_key_excerpt=str(self._allocation_move_key(exact_move) or "")[:120],
                        exact_move_request_id_excerpt=str(exact_move.get("request_id", "") or "")[:80],
                        invalid_reason=str(exact_struct_reason or "file_before_terminal"),
                    )
                elif str(exact_destination_path or "").strip() and not paths_equivalent:
                    log_info(
                        "destination_exact_move_skips_allocation_descendant_projection",
                        descendant_source_path_excerpt=str(descendant_source_path)[:400],
                        inherited_projection_terminal_excerpt=str(dh_cmp)[:400],
                        exact_move_destination_terminal_excerpt=str(em_cmp)[:400],
                        allocation_destination_path_excerpt=str(allocation_destination_path)[:400],
                        exact_move_key_excerpt=str(self._allocation_move_key(exact_move) or "")[:120],
                        exact_move_request_id_excerpt=str(exact_move.get("request_id", "") or "")[:80],
                        skip_reason="exact_move_different_destination",
                    )
                    st["desc_index"] += 1
                    continue
            base_canon = self._canonical_destination_projection_path(allocation_destination_path) or self.normalize_memory_path(
                allocation_destination_path
            )
            rel_clean = [str(s or "").strip() for s in relative_segments if str(s or "").strip()]
            if not rel_clean:
                st["desc_index"] += 1
                continue
            base_parts = list(self._path_segments(base_canon))
            if not base_parts:
                self._log_restore_phase(
                    "sharepoint_allocation_descendant_empty_base",
                    allocation_destination_excerpt=str(allocation_destination_path)[:220],
                    descendant_source_excerpt=str(descendant_source_path)[:220],
                )
                st["desc_index"] += 1
                continue
            projection_terminal_bare = self._canonical_destination_projection_path(
                "\\".join(base_parts + rel_clean)
            ) or self.normalize_memory_path("\\".join(base_parts + rel_clean))
            projection_terminal = (
                (
                    self._canonical_destination_path_with_visible_library_anchor(projection_terminal_bare)
                    or projection_terminal_bare
                )
                if graph_auth
                else projection_terminal_bare
            ) or None
            cur_ix = parent_ix.siblingAtColumn(0) if parent_ix.column() != 0 else parent_ix
            st["rel_clean"] = rel_clean
            st["base_canon"] = base_canon
            st["base_parts"] = base_parts
            st["projection_terminal"] = projection_terminal
            st["descendant_data"] = descendant_data
            st["descendant_source_path"] = descendant_source_path
            st["seg_index"] = 0
            st["walk_phase"] = "walk"
            return "walk"
        return "done"

    def _destination_graph_descendant_stable_path_for_walk_cursor(self, st, seg_index: int) -> str:
        """Canonical path to the walk cursor row before consuming segment ``seg_index`` (path-only; no QModelIndex)."""
        base_canon = str(st.get("base_canon") or "").strip()
        base_parts = st.get("base_parts") or []
        rel_clean = st.get("rel_clean") or []
        i = int(seg_index)
        if i <= 0:
            return base_canon
        sub = "\\".join(base_parts + rel_clean[:i])
        if bool(st.get("graph_auth")):
            sub_bare = self._canonical_destination_projection_path(sub) or self.normalize_memory_path(sub)
            return (
                self._canonical_planned_memory_path_for_graph_match(sub_bare) or sub_bare or ""
            ).strip()
        return (
            self._canonical_destination_projection_path(sub) or self.normalize_memory_path(sub) or ""
        ).strip()

    def _destination_graph_descendant_stable_path_for_leaf(self, st) -> str:
        base_parts = st.get("base_parts") or []
        rel_clean = st.get("rel_clean") or []
        leaf_sub = "\\".join(base_parts + rel_clean)
        return (
            self._canonical_destination_projection_path(leaf_sub) or self.normalize_memory_path(leaf_sub) or ""
        ).strip()

    def _destination_graph_descendant_model_index_keys_for_lookup(self, path_hint: str) -> list[str]:
        """Canonical keys that may appear in DestinationPlanningModel path index (Graph hub vs library-relative)."""
        raw = (path_hint or "").strip()
        if not raw:
            return []
        seen_cf: set[str] = set()
        out: list[str] = []

        def _add(s: str) -> None:
            t = (s or "").strip()
            if not t:
                return
            cf = t.casefold()
            if cf in seen_cf:
                return
            seen_cf.add(cf)
            out.append(t)

        _add(self._canonical_destination_projection_path(raw) or "")
        _add(self.normalize_memory_path(raw))
        _add(raw)
        if destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            try:
                nt = self._materialize_cached_destination_lookup_norm(raw)
            except Exception:
                nt = ""
            keys, _ = self._destination_visible_path_lookup_canonical_keys_ex(raw, nt)
            for k in keys or []:
                _add(k)
        return out

    def _allocation_effective_destination_allocation_root_path(self, move: dict | None) -> str:
        """Canonical graph-relative allocation destination root (honors planned-parent fields when authoritative)."""
        if not isinstance(move, dict):
            return ""
        raw_path = self._allocation_projection_path(move)
        out = (
            self._canonical_planned_memory_path_for_graph_match(str(raw_path or "").strip())
            or self._canonical_destination_projection_path(str(raw_path or "").strip())
            or str(raw_path or "").strip()
        ).strip()
        ppp = str(move.get("DestinationParentPlannedPath") or "").strip()
        if ppp and str(move.get("LegacyMigrationPlannedParentResolved", "")).strip().lower() in (
            "true",
            "1",
            "yes",
        ):
            tn = str(self._move_target_name(move) or "").strip()
            if tn:
                joined = self.normalize_memory_path(f"{ppp}\\{tn}")
                jp = (
                    self._canonical_planned_memory_path_for_graph_match(joined)
                    or self._canonical_destination_projection_path(joined)
                    or joined
                ).strip()
                if jp:
                    out = jp
        return out

    def _find_destination_allocation_descendant_parent_index(self, move: dict | None) -> tuple[QModelIndex | None, str]:
        """Resolve QModelIndex for the allocation folder (overlay or live) under selected destination drive."""
        log_info(
            "destination_allocation_descendant_parent_resolve_started",
            move_key_excerpt=str(
                self._allocation_move_key(move) if isinstance(move, dict) else ""
            )[:120],
        )
        if not isinstance(move, dict):
            log_info("destination_allocation_descendant_parent_resolve_missing", reason="not_a_move_dict")
            return None, "not_a_move_dict"
        ap = self._allocation_effective_destination_allocation_root_path(move)
        if not ap:
            log_info("destination_allocation_descendant_parent_resolve_missing", reason="empty_effective_destination_root")
            return None, "empty_effective_destination_root"
        dm = getattr(self, "destination_planning_model", None)
        if dm is None:
            log_info("destination_allocation_descendant_parent_resolve_missing", reason="no_destination_model")
            return None, "no_destination_model"
        dst_drive = str(self._current_selected_destination_drive_id() or "").strip()
        find_fn = getattr(dm, "find_indices_for_canonical_destination_path", None)
        if not callable(find_fn):
            log_info("destination_allocation_descendant_parent_resolve_missing", reason="no_find_indices")
            return None, "no_find_indices"
        target_cf = ap.casefold()
        candidates: list[tuple[int, int, Any]] = []  # (score, overlay_subtree_nodes, index)
        try:
            for c in self._destination_graph_descendant_model_index_keys_for_lookup(ap):
                for h in find_fn(c) or []:
                    if h is None or not hasattr(h, "isValid") or not callable(getattr(h, "isValid", None)):
                        continue
                    try:
                        if not h.isValid():
                            continue
                    except Exception:
                        continue
                    h0 = h.siblingAtColumn(0) if h.column() != 0 else h
                    if hasattr(dm, "is_index_live") and not dm.is_index_live(h0):
                        continue
                    pl = dict(h0.data(Qt.UserRole) or {})
                    if pl.get("placeholder"):
                        continue
                    if not bool(pl.get("is_folder", True)):
                        log_info(
                            "destination_allocation_descendant_parent_resolve_not_folder",
                            path_excerpt=str(self._tree_item_path(pl))[:400],
                        )
                        continue
                    row_drive = str(pl.get("drive_id") or pl.get("library_id") or "").strip()
                    if dst_drive and row_drive and row_drive != dst_drive:
                        log_info(
                            "destination_allocation_descendant_parent_resolve_wrong_drive",
                            expected_drive_excerpt=dst_drive[:48],
                            row_drive_excerpt=row_drive[:48],
                            path_excerpt=str(self._tree_item_path(pl))[:400],
                        )
                        continue
                    vis_raw = self._tree_item_path(pl) or ""
                    if destination_authority_contract.graph_owns_visible_real_destination_structure(self):
                        vis = (
                            self._canonical_planned_memory_path_for_graph_match(str(vis_raw).strip())
                            or self._canonical_destination_projection_path(str(vis_raw).strip())
                            or str(vis_raw).strip()
                        )
                    else:
                        vis = (
                            self._canonical_destination_projection_path(str(vis_raw).strip())
                            or str(vis_raw).strip()
                        )
                    md = self._destination_parent_match_details(ap, vis)

                    score = 0
                    if destination_payload_is_live_graph_row(pl) and md.get("exact_match"):
                        score = 4
                        log_info(
                            "destination_allocation_descendant_parent_resolve_live_parent_allowed",
                            path_excerpt=str(vis)[:400],
                        )
                    elif destination_payload_is_structural_row_for_planned_workspace_bind(pl) and md.get("exact_match"):
                        score = 3
                        log_info(
                            "destination_allocation_descendant_parent_resolve_overlay_parent_allowed",
                            path_excerpt=str(vis)[:400],
                        )
                    elif md.get("exact_match"):
                        score = 2
                        log_info(
                            "destination_allocation_descendant_parent_resolve_overlay_parent_allowed",
                            path_excerpt=str(vis)[:400],
                        )
                    elif vis.casefold() == target_cf:
                        score = 1
                    if score <= 0:
                        continue
                    ov_n = 0
                    try:
                        ov_n = int(
                            self._destination_count_planned_snapshot_tree_nodes(
                                self._destination_collect_planned_workspace_children_under_model(h0)
                            )
                        )
                    except Exception:
                        ov_n = 0
                    candidates.append((score, ov_n, h0))
        except RuntimeError:
            log_info("destination_allocation_descendant_parent_resolve_missing", reason="runtime_errorenumerate")
            return None, "runtime_errorenumerate"
        if candidates:
            score_ov_ix = max(candidates, key=lambda t: (t[1], t[0]))
            best_score, best_ov, best_ix = score_ov_ix
            if best_ix.isValid():
                log_info(
                    "destination_allocation_descendant_parent_resolve_found",
                    path_excerpt=str(ap)[:400],
                    score=int(best_score),
                    overlay_descendant_count_for_choice=int(best_ov),
                    candidate_count=int(len(candidates)),
                )
                return best_ix, "ok"
        log_info("destination_allocation_descendant_parent_resolve_missing", reason="no_matching_row", path_excerpt=ap[:400])
        return None, "no_matching_row"

    def _destination_graph_descendant_resolve_model_index_for_path(self, dm, canonical_path: str) -> QModelIndex | None:
        """Fresh QModelIndex for a canonical destination path; prefers exact canonical matches over ambiguous keys."""
        if dm is None:
            return None
        raw = (canonical_path or "").strip()
        if not raw:
            return None
        if destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            want = (
                self._canonical_planned_memory_path_for_graph_match(raw)
                or self._canonical_destination_projection_path(raw)
                or raw
            ).strip()
        else:
            want = (self._canonical_destination_projection_path(raw) or self.normalize_memory_path(raw) or raw).strip()
        find_fn = getattr(dm, "find_indices_for_canonical_destination_path", None)
        best_any: QModelIndex | None = None
        best_len = -1
        if callable(find_fn):
            try:
                for c in self._destination_graph_descendant_model_index_keys_for_lookup(raw):
                    for h in find_fn(c) or []:
                        if not isinstance(h, QModelIndex) or not h.isValid():
                            continue
                        h0 = h.siblingAtColumn(0) if h.column() != 0 else h
                        if hasattr(dm, "is_index_live") and not dm.is_index_live(h0):
                            continue
                        pl = dict(h0.data(Qt.UserRole) or {})
                        vis_raw = self._tree_item_path(pl) or ""
                        if destination_authority_contract.graph_owns_visible_real_destination_structure(self):
                            vis = (
                                self._canonical_planned_memory_path_for_graph_match(str(vis_raw).strip())
                                or self._canonical_destination_projection_path(str(vis_raw).strip())
                                or str(vis_raw).strip()
                            )
                        else:
                            vis = (
                                self._canonical_destination_projection_path(str(vis_raw).strip())
                                or str(vis_raw).strip()
                            )
                        md = self._destination_parent_match_details(want, vis)
                        if md.get("exact_match"):
                            return h0
                        seg_ct = len([s for s in (vis or "").split("\\") if s])
                        if best_any is None or seg_ct > best_len:
                            best_any = h0
                            best_len = seg_ct
            except RuntimeError:
                return None
            if best_any is not None:
                return best_any
        c0 = (self._canonical_destination_projection_path(raw) or self.normalize_memory_path(raw) or raw).strip()
        try:
            vis = self._find_visible_destination_item_by_path(c0)
        except Exception:
            vis = None
        if vis is not None and isinstance(vis, QModelIndex) and vis.isValid():
            v0 = vis.siblingAtColumn(0) if vis.column() != 0 else vis
            try:
                if hasattr(dm, "is_index_live") and not dm.is_index_live(v0):
                    return None
            except RuntimeError:
                return None
            return v0
        return None

    def _destination_graph_descendant_resolve_child_under_walk_parent(
        self, dm, parent_ix: QModelIndex, next_branch: str
    ) -> QModelIndex | None:
        """When parent-scoped child map misses, recover a row already indexed under another canonical key."""
        if dm is None or not parent_ix.isValid() or not next_branch:
            return None
        p0 = parent_ix.siblingAtColumn(0) if parent_ix.column() != 0 else parent_ix
        find_fn = getattr(dm, "find_indices_for_canonical_destination_path", None)
        if not callable(find_fn):
            return None
        try:
            for c in self._destination_graph_descendant_model_index_keys_for_lookup(next_branch):
                for h in find_fn(c) or []:
                    if not isinstance(h, QModelIndex) or not h.isValid():
                        continue
                    h0 = h.siblingAtColumn(0) if h.column() != 0 else h
                    if hasattr(dm, "is_index_live") and not dm.is_index_live(h0):
                        continue
                    try:
                        par = h0.parent()
                    except RuntimeError:
                        continue
                    if not par.isValid():
                        continue
                    par0 = par.siblingAtColumn(0) if par.column() != 0 else par
                    if par0 != p0:
                        continue
                    pl = self._destination_model_index_user_role_dict(h0)
                    vis = self._destination_semantic_path(pl)
                    if self._destination_parent_match_details(next_branch, vis).get("exact_match"):
                        return h0
        except RuntimeError:
            return None
        return None

    def _destination_graph_descendant_apply_process_one_segment(self, st) -> str:
        """One graph-authority segment step: reuse visible/snapshot row or inject a single planned segment."""
        if int(getattr(self, "_destination_descendant_apply_graph_bind_depth", 0) or 0) > 0:
            n = int(st.get("_graph_bind_in_progress_yield_logged", 0) or 0)
            if n < 4:
                st["_graph_bind_in_progress_yield_logged"] = n + 1
                log_info(
                    "descendant_apply_stale_graph_bind_in_progress_yield",
                    move_key_excerpt=str(self._allocation_move_key(st.get("move")) or "")[:120],
                    allocation_destination_path_excerpt=str(st.get("allocation_destination_path") or "")[:400],
                )
            return "yield"

        rb0 = self._destination_graph_descendant_apply_try_rebind_parent_ix(st)
        if rb0 == "terminal":
            return "stale"
        if rb0 == "yield":
            return "yield"

        model = st["model"]
        rel_clean = st.get("rel_clean") or []
        descendant_data = st.get("descendant_data")
        parent_data = st.get("parent_data")
        base_parts = st.get("base_parts") or []
        base_canon = st.get("base_canon") or ""
        projection_terminal = st.get("projection_terminal")
        graph_auth = bool(st.get("graph_auth"))
        descendant_source_path = str(st.get("descendant_source_path") or "")
        allocation_destination_path = st.get("allocation_destination_path") or ""

        gen_fn = getattr(model, "structure_generation", None)
        if callable(gen_fn):
            cur_gen = int(gen_fn())
            snap = st.get("graph_model_structure_generation_snap")
            if snap is not None and cur_gen != int(snap):
                log_info(
                    "descendant_apply_model_mutation_guard_skip",
                    previous_generation=int(snap),
                    current_generation=cur_gen,
                )
                try:
                    self._destination_descendant_snapshot_coalesce_guard_skip_observed += 1
                except Exception:
                    pass
                self._destination_graph_descendant_apply_try_rebind_parent_ix(st)
            st["graph_model_structure_generation_snap"] = cur_gen

        st["child_map_cache"] = {}
        child_map_cache: dict = st["child_map_cache"]

        if not rel_clean or descendant_data is None or parent_data is None:
            st["desc_index"] += 1
            st["walk_phase"] = "next_descendant"
            return "next_descendant"

        i = int(st.get("seg_index") or 0)
        if i >= len(rel_clean):
            leaf_path = self._destination_graph_descendant_stable_path_for_leaf(st)
            cur_final = self._destination_graph_descendant_resolve_model_index_for_path(model, leaf_path)
            if cur_final is None or not cur_final.isValid():
                log_info(
                    "descendant_apply_index_invalid_resolved_by_path",
                    phase="leaf_overlay",
                    path_excerpt=str(leaf_path)[:400],
                )
                st["desc_index"] += 1
                st["walk_phase"] = "next_descendant"
                return "next_descendant"
            log_info(
                "descendant_apply_index_revalidated",
                phase="leaf_overlay",
                path_excerpt=str(leaf_path)[:400],
            )
            try:
                dest_full = self._tree_item_path(self._destination_model_index_user_role_dict(cur_final)) or leaf_path
            except Exception:
                dest_full = leaf_path or allocation_destination_path
            par_ix = QModelIndex()
            pd = parent_data
            try:
                par_ix = cur_final.parent()
                if par_ix.isValid():
                    pd = dict(self._destination_model_index_user_role_dict(par_ix))
            except RuntimeError:
                par_ix = QModelIndex()
                pd = parent_data
            self._apply_allocation_descendant_overlay_to_existing_model_index(
                cur_final, descendant_data, dest_full, pd
            )
            st["overlay_count"] = int(st.get("overlay_count") or 0) + 1
            self._mark_destination_tree_snapshot_dirty_after_injection(reason="allocation_descendant_graph_overlay")
            st["desc_index"] += 1
            st["walk_phase"] = "next_descendant"
            return "next_descendant"

        cursor_path = self._destination_graph_descendant_stable_path_for_walk_cursor(st, i)
        cur_ix = self._destination_graph_descendant_resolve_model_index_for_path(model, cursor_path)
        if cur_ix is None or not cur_ix.isValid():
            n = int(st.get("_walk_cursor_unresolved_yield_logged", 0) or 0)
            if n < 4:
                st["_walk_cursor_unresolved_yield_logged"] = n + 1
                log_info(
                    "descendant_apply_stale_walk_cursor_unresolved_yield",
                    phase="walk_cursor",
                    path_excerpt=str(cursor_path)[:400],
                    segment_index=int(i),
                    move_key_excerpt=str(self._allocation_move_key(st.get("move")) or "")[:120],
                )
            return "yield"
        log_info(
            "descendant_apply_index_revalidated",
            phase="walk_cursor",
            path_excerpt=str(cursor_path)[:400],
            segment_index=int(i),
        )

        if i == 0:
            expected_parent_before = base_canon
        else:
            join_p = "\\".join(base_parts + rel_clean[:i])
            join_p_bare = self._canonical_destination_projection_path(join_p) or self.normalize_memory_path(join_p)
            if graph_auth:
                expected_parent_before = (
                    self._canonical_planned_memory_path_for_graph_match(join_p_bare) or join_p_bare
                )
            else:
                expected_parent_before = join_p_bare
        cur_pl = self._destination_model_index_user_role_dict(cur_ix)
        cur_raw = self._tree_item_path(cur_pl) or ""
        if graph_auth:
            cur_canon = self._canonical_planned_memory_path_for_graph_match(cur_raw) or ""
        else:
            cur_canon = self._canonical_destination_projection_path(cur_raw) or ""
        walk_md = self._destination_parent_match_details(expected_parent_before, cur_canon)
        if not walk_md.get("exact_match"):
            log_info(
                "destination_allocation_descendant_walk_mismatch_detected",
                expected_parent_canonical=str(expected_parent_before)[:260],
                actual_current_canonical=str(cur_canon)[:260],
                cursor_path_excerpt=str(cursor_path)[:400],
                descendant_source_excerpt=str(descendant_source_path)[:220],
            )
            fix_ix = self._destination_graph_descendant_resolve_model_index_for_path(model, str(expected_parent_before))
            mv = st.get("move")
            if (fix_ix is None or not fix_ix.isValid()) and isinstance(mv, dict):
                fb, _fbr = self._find_destination_allocation_descendant_parent_index(mv)
                if fb is not None and fb.isValid():
                    fix_ix = fb.siblingAtColumn(0) if fb.column() != 0 else fb
            if fix_ix is not None and fix_ix.isValid():
                fix_pl = self._destination_model_index_user_role_dict(fix_ix)
                fix_raw = self._tree_item_path(fix_pl) or ""
                if graph_auth:
                    fix_canon = self._canonical_planned_memory_path_for_graph_match(fix_raw) or ""
                else:
                    fix_canon = self._canonical_destination_projection_path(fix_raw) or ""
                if self._destination_parent_match_details(expected_parent_before, fix_canon).get("exact_match"):
                    cur_ix = fix_ix
                    cur_canon = fix_canon
                    walk_md = {"exact_match": True}
                    log_info(
                        "destination_allocation_descendant_walk_mismatch_fixed",
                        expected_parent_canonical=str(expected_parent_before)[:260],
                        resolved_canonical=str(fix_canon)[:260],
                        descendant_source_excerpt=str(descendant_source_path)[:220],
                    )
            if not walk_md.get("exact_match"):
                self._log_restore_phase(
                    "sharepoint_allocation_descendant_walk_mismatch",
                    expected_parent_canonical=str(expected_parent_before)[:260],
                    actual_current_canonical=str(cur_canon)[:260],
                    descendant_source_excerpt=str(descendant_source_path)[:220],
                )
                log_info(
                    "destination_allocation_descendant_walk_mismatch_unresolved",
                    expected_parent_canonical=str(expected_parent_before)[:260],
                    actual_current_canonical=str(cur_canon)[:260],
                )
                st["desc_index"] += 1
                st["walk_phase"] = "next_descendant"
                return "next_descendant"

        join_child = "\\".join(base_parts + rel_clean[: i + 1])
        join_child_bare = (
            self._canonical_destination_projection_path(join_child) or self.normalize_memory_path(join_child)
        )
        if graph_auth:
            next_branch = self._canonical_planned_memory_path_for_graph_match(join_child_bare) or join_child_bare
        else:
            next_branch = join_child_bare

        ch = self._find_destination_child_by_path_index_cached(cur_ix, next_branch, child_map_cache)
        missing_for_inject = ch is None or not isinstance(ch, QModelIndex) or not ch.isValid()

        if missing_for_inject:
            ch_rec = self._destination_graph_descendant_resolve_child_under_walk_parent(model, cur_ix, next_branch)
            if ch_rec is not None and ch_rec.isValid():
                log_info(
                    "descendant_apply_child_recovered_parent_scoped_miss",
                    canonical_path_excerpt=str(next_branch)[:400],
                    segment_index=int(i),
                    bind_context_excerpt=str(descendant_source_path)[:220],
                )
                ch = ch_rec
                missing_for_inject = False

        if not missing_for_inject:
            ch_pl = self._destination_model_index_user_role_dict(ch)
            ch_raw = self._tree_item_path(ch_pl) or ""
            if graph_auth:
                ch_canon = self._canonical_planned_memory_path_for_graph_match(ch_raw) or ""
            else:
                ch_canon = self._canonical_destination_projection_path(ch_raw) or ""
            ch_md = self._destination_parent_match_details(next_branch, ch_canon)
            if ch_md.get("exact_match"):
                snap_hint = bool(
                    ch_pl.get("workspace_row_state")
                    or ch_pl.get("workspace_planned_row")
                    or str(ch_pl.get("verification_state") or "") == "planned_only"
                )
                log_info(
                    "startup_lifecycle_temp_snapshot_descendant_reused",
                    canonical_path_excerpt=str(next_branch)[:400],
                    segment_index=int(i),
                    snapshot_row_hint=bool(snap_hint),
                    bind_context_excerpt=str(descendant_source_path)[:220],
                )
                st["seg_index"] = i + 1
                return "continue"

            self._log_restore_phase(
                "sharepoint_allocation_descendant_child_mismatch",
                expected_child_canonical=str(next_branch)[:260],
                actual_child_canonical=str(ch_canon)[:260],
                descendant_source_excerpt=str(descendant_source_path)[:220],
            )
            rem = rel_clean[i:]
            self._destination_graph_descendant_apply_bind_one_segment(
                st, cur_ix, rem, expected_parent_before, descendant_data, descendant_source_path, projection_terminal
            )
            return "continue"

        if graph_auth:
            _def_ad, _miss_ad, _cc_ad = self._graph_authority_planned_structural_bind_deferred_miss(
                next_branch, live_graph_parent_pl=cur_pl, parent_anchor_index_valid=True
            )
            if _def_ad:
                self._log_restore_phase(
                    "sharepoint_overlay_planned_chain_suppressed_graph_authority",
                    normalized_target=str(projection_terminal or "")[:400],
                    depth=i,
                    path=next_branch,
                    miss_reason=_miss_ad,
                    candidate_count=int(_cc_ad),
                    bind_context="allocation_descendant_child_missing",
                )
                log_info(
                    "destination_planned_chain_bind_suppressed",
                    intended_path=str(projection_terminal or next_branch)[:400],
                    reason="graph_authority_allocation_descendant_deferred",
                    miss_reason=_miss_ad,
                    path_excerpt=str(next_branch)[:260],
                    nearest_visible_parent=str(expected_parent_before)[:400],
                    candidate_count=int(_cc_ad),
                )
                cur_pl_ld = self._destination_model_index_user_role_dict(cur_ix)
                if (
                    self._destination_row_is_live_graph_structure(cur_pl_ld)
                    and not cur_pl_ld.get("children_loaded")
                    and not cur_pl_ld.get("load_failed")
                ):
                    self._request_graph_destination_children_load(
                        cur_ix.siblingAtColumn(0) if cur_ix.column() != 0 else cur_ix,
                        reason="allocation_descendant_deferred",
                    )
                st["desc_index"] += 1
                st["walk_phase"] = "next_descendant"
                return "next_descendant"

        log_info(
            "startup_lifecycle_temp_live_descendant_missing_from_cache",
            canonical_path_excerpt=str(next_branch)[:400],
            segment_index=int(i),
            bind_context_excerpt=str(descendant_source_path)[:220],
        )
        rem = rel_clean[i:]
        self._destination_graph_descendant_apply_bind_one_segment(
            st, cur_ix, rem, expected_parent_before, descendant_data, descendant_source_path, projection_terminal
        )
        return "continue"

    def _destination_graph_descendant_apply_bind_one_segment(
        self,
        st,
        cur_ix: QModelIndex,
        rem: list[str],
        expected_parent_before: str,
        descendant_data,
        descendant_source_path: str,
        projection_terminal,
    ) -> None:
        """Bind exactly the first segment of ``rem`` (incremental injection)."""
        if not rem:
            return
        seg0 = rem[0]
        terminal_one = len(rem) == 1
        t0 = time.perf_counter()
        log_info(
            "startup_lifecycle_temp_live_descendant_injected_chunk_begin",
            segment_excerpt=str(seg0)[:200],
            remaining_segments=int(len(rem)),
            bind_context_excerpt=str(descendant_source_path)[:220],
        )
        self._destination_descendant_apply_graph_bind_depth = int(
            getattr(self, "_destination_descendant_apply_graph_bind_depth", 0) or 0
        ) + 1
        bound = None
        try:
            bound = self._sharepoint_bind_planned_segment_chain(
                cur_ix,
                [seg0],
                bind_kind="allocation_descendant",
                bind_context_excerpt=str(descendant_source_path)[:220],
                expected_parent_canonical=expected_parent_before,
                projection_target_canonical=projection_terminal,
                terminal_is_file=bool(terminal_one and self._source_tree_payload_implies_file_leaf(descendant_data)),
            )
        finally:
            self._destination_descendant_apply_graph_bind_depth = max(
                0,
                int(getattr(self, "_destination_descendant_apply_graph_bind_depth", 0) or 0) - 1,
            )
        wall_ms = round((time.perf_counter() - t0) * 1000.0, 2)
        log_info(
            "startup_lifecycle_temp_live_descendant_injected_chunk_end",
            wall_ms=wall_ms,
            entries_processed=1,
            segment_excerpt=str(seg0)[:200],
            bind_context_excerpt=str(descendant_source_path)[:220],
        )
        if bound is not None and bound.isValid():
            st["seg_index"] = int(st.get("seg_index") or 0) + 1
            self._destination_startup_descendant_injection_active = True
            try:
                _hint = str(projection_terminal or expected_parent_before or descendant_source_path or "")[:400]
            except Exception:
                _hint = str(expected_parent_before or "")[:400]
            self._mark_destination_tree_snapshot_dirty_after_injection(
                reason="allocation_descendant_bind_segment",
                affected_path=_hint,
            )
        else:
            st["desc_index"] += 1
            st["walk_phase"] = "next_descendant"

    def _destination_descendant_apply_prepare_next_descendant(self, st) -> str:
        """Advance to the next non-skipped descendant. Returns 'walk', 'done', or 'stale'."""
        if st.get("graph_walk"):
            return self._destination_graph_descendant_apply_prepare_next_descendant(st)
        descendants = st["descendants"]
        parent_ix = st["parent_ix"]
        parent_data = st["parent_data"]
        allocation_destination_path = st["allocation_destination_path"]
        source_root_path = st["source_root_path"]
        model = st["model"]

        while st["desc_index"] < len(descendants):
            if st["desc_index"] > 0 and st["desc_index"] % 50 == 0:
                self._reconcile_destination_sibling_folders_during_allocation_apply("model_index_yield")
            if not parent_ix.isValid() or (hasattr(model, "is_index_live") and not model.is_index_live(parent_ix)):
                return "stale"
            descendant_data = descendants[st["desc_index"]]
            descendant_source_path = self._canonical_source_projection_path(self._tree_item_path(descendant_data))
            if descendant_source_path == source_root_path:
                st["desc_index"] += 1
                continue
            relative_segments = self._allocation_projection_relative_source_segments(
                source_root_path, descendant_source_path
            )
            if not relative_segments:
                st["desc_index"] += 1
                continue
            descendant_destination_path = self._canonical_destination_projection_path(
                "\\".join([allocation_destination_path] + relative_segments)
            )
            if not descendant_destination_path:
                st["desc_index"] += 1
                continue
            if self._source_tree_payload_implies_file_leaf(descendant_data) and self._is_leaf_path_excluded_for_plan(
                descendant_source_path
            ):
                st["desc_index"] += 1
                continue
            exact_move = self._find_exact_planned_move_for_source_path(descendant_source_path)
            if exact_move is not None:
                exact_join = self.normalize_memory_path(
                    "\\".join(
                        [
                            str(exact_move.get("destination_path", "") or ""),
                            self._move_target_name(exact_move),
                        ]
                    )
                )
                exact_destination_path = self._canonical_destination_projection_path(exact_join) or exact_join
                em_cmp = str(exact_destination_path or "").strip()
                dh_cmp = str(descendant_destination_path or "").strip()
                paths_equivalent = bool(em_cmp and dh_cmp and em_cmp.casefold() == dh_cmp.casefold())
                exact_struct_invalid, exact_struct_reason = self._destination_structural_path_chain_invalid_for_container_parent(
                    str(exact_destination_path or "")
                )
                if exact_struct_invalid:
                    log_info(
                        "destination_exact_move_invalid_terminal_ignored",
                        descendant_source_path_excerpt=str(descendant_source_path)[:400],
                        inherited_projection_terminal_excerpt=str(dh_cmp)[:400],
                        exact_move_destination_terminal_excerpt=str(em_cmp)[:400],
                        allocation_destination_path_excerpt=str(allocation_destination_path)[:400],
                        exact_move_key_excerpt=str(self._allocation_move_key(exact_move) or "")[:120],
                        exact_move_request_id_excerpt=str(exact_move.get("request_id", "") or "")[:80],
                        invalid_reason=str(exact_struct_reason or "file_before_terminal"),
                    )
                elif str(exact_destination_path or "").strip() and not paths_equivalent:
                    log_info(
                        "destination_exact_move_skips_allocation_descendant_projection",
                        descendant_source_path_excerpt=str(descendant_source_path)[:400],
                        inherited_projection_terminal_excerpt=str(dh_cmp)[:400],
                        exact_move_destination_terminal_excerpt=str(em_cmp)[:400],
                        allocation_destination_path_excerpt=str(allocation_destination_path)[:400],
                        exact_move_key_excerpt=str(self._allocation_move_key(exact_move) or "")[:120],
                        exact_move_request_id_excerpt=str(exact_move.get("request_id", "") or "")[:80],
                        skip_reason="exact_move_different_destination",
                    )
                    st["desc_index"] += 1
                    continue
            st["relative_segments"] = relative_segments
            st["descendant_data"] = descendant_data
            st["seg_index"] = 0
            st["current_parent_ix"] = parent_ix
            st["current_parent_data"] = parent_data
            st["walk_phase"] = "walk"
            return "walk"
        return "done"

    def _destination_descendant_apply_process_one_segment(self, st) -> str:
        """Process one segment of the current descendant. Returns 'continue', 'next_descendant', 'stale', or 'done'."""
        if st.get("graph_walk"):
            return self._destination_graph_descendant_apply_process_one_segment(st)
        model = st["model"]
        relative_segments = st["relative_segments"]
        descendant_data = st["descendant_data"]
        allocation_destination_path = st["allocation_destination_path"]
        child_map_cache = st["child_map_cache"]
        pending_leaf_batches = st["pending_leaf_batches"]
        visibility_targets = st["visibility_targets"]

        if not relative_segments:
            st["desc_index"] += 1
            st["walk_phase"] = "next_descendant"
            return "next_descendant"

        idx = st["seg_index"]
        if idx >= len(relative_segments):
            st["desc_index"] += 1
            st["walk_phase"] = "next_descendant"
            return "next_descendant"

        current_parent_ix = st["current_parent_ix"]
        current_parent_data = st["current_parent_data"]
        if not current_parent_ix.isValid() or (hasattr(model, "is_index_live") and not model.is_index_live(current_parent_ix)):
            return "stale"

        segment = relative_segments[idx]
        branch_path = self._canonical_destination_projection_path(
            "\\".join([allocation_destination_path] + relative_segments[: idx + 1])
        )
        is_leaf = idx == len(relative_segments) - 1
        existing_child = self._find_destination_child_by_path_index_cached(
            current_parent_ix, branch_path, child_map_cache
        )
        if existing_child is None:
            new_pl = self._build_projected_allocation_descendant_payload(
                descendant_data if is_leaf else {"name": segment, "real_name": segment, "is_folder": True},
                branch_path,
                current_parent_data,
            )
            if is_leaf:
                pk = self._destination_child_map_cache_key_index(current_parent_ix)
                batch = pending_leaf_batches.setdefault(
                    pk, {"parent_ix": current_parent_ix, "payloads": []}
                )
                batch["payloads"].append(new_pl)
                visibility_targets[pk] = current_parent_ix
                st["added_count"] += 1
                self._mark_destination_tree_snapshot_dirty_after_injection(reason="allocation_descendant_project_leaf_batch")
                existing_child = current_parent_ix
            else:
                self._allocation_apply_flush_pending_model(
                    model, child_map_cache, pending_leaf_batches, current_parent_ix
                )
                self._remove_placeholder_children(current_parent_ix)
                model.append_child_payloads(current_parent_ix, [new_pl])
                self._mark_destination_tree_snapshot_dirty_after_injection(reason="allocation_descendant_project_folder_segment")
                new_row = model.rowCount(current_parent_ix) - 1
                existing_child = model.index(new_row, 0, current_parent_ix)
                self._destination_merge_new_children_into_index_map_cache(child_map_cache, current_parent_ix, 1)
                pk = self._destination_child_map_cache_key_index(current_parent_ix)
                visibility_targets[pk] = current_parent_ix
        st["current_parent_ix"] = existing_child
        st["current_parent_data"] = existing_child.data(Qt.UserRole) or {}
        st["seg_index"] = idx + 1
        if st["seg_index"] >= len(relative_segments):
            st["desc_index"] += 1
            st["walk_phase"] = "next_descendant"
            return "next_descendant"
        return "continue"

    def _try_mark_allocation_resolved_after_descendant_apply_finalize(
        self, outcome_ix: QModelIndex, move
    ) -> bool:
        """Pop unresolved-allocation queue entry when the folder row passes the same verify gate as replay."""
        if not isinstance(move, dict):
            return False
        if outcome_ix is None or not isinstance(outcome_ix, QModelIndex) or not outcome_ix.isValid():
            return False
        col0 = outcome_ix.siblingAtColumn(0) if outcome_ix.column() != 0 else outcome_ix
        if not col0.isValid():
            return False
        allocation_path = str(self._allocation_projection_path(move) or "").strip()
        if not allocation_path:
            return False
        graph_auth = destination_authority_contract.graph_owns_visible_real_destination_structure(self)
        if graph_auth:
            expected_target = str(
                self._canonical_destination_path_with_visible_library_anchor(allocation_path) or allocation_path
            ).strip()
            verify = True
        else:
            expected_target = str(
                self._canonical_destination_projection_path(allocation_path)
                or self.normalize_memory_path(allocation_path)
                or allocation_path
            ).strip()
            verify = False
        if not expected_target:
            return False
        nd = self._destination_model_index_user_role_dict(col0)
        res_reason = (
            UnresolvedQueueRemovalReason.attached_to_existing_live_row
            if destination_payload_is_live_graph_row(nd)
            else UnresolvedQueueRemovalReason.merged_to_equivalent_visible_planned_row
        )
        return bool(
            self._mark_allocation_resolved(
                move,
                reason=res_reason,
                outcome_ix=col0,
                expected_target_canonical=expected_target,
                verify_visible_outcome=verify,
            )
        )

    def _destination_descendant_apply_finalize_job(self, st) -> None:
        if st.get("graph_walk"):
            move = st["move"]
            overlay_count = int(st.get("overlay_count") or 0)
            dm = st.get("model")
            parent_ix = st.get("parent_ix")
            ap = str(st.get("allocation_destination_path") or "").strip()
            if dm is not None and ap:
                fresh = self._destination_graph_descendant_resolve_model_index_for_path(dm, ap)
                if fresh is not None and fresh.isValid():
                    parent_ix = fresh
                    log_info(
                        "descendant_apply_index_revalidated",
                        phase="graph_finalize_parent",
                        path_excerpt=str(ap)[:400],
                    )
            if parent_ix is not None and isinstance(parent_ix, QModelIndex) and parent_ix.isValid():
                self._mark_allocation_descendants_applied_on_allocation_folder_model_index(parent_ix, move)
                node_after = self._destination_model_index_user_role_dict(parent_ix)
                self._stamp_allocation_projection_cache_metadata_index(parent_ix, node_after, move)
                self._try_mark_allocation_resolved_after_descendant_apply_finalize(parent_ix, move)
            tree = getattr(self, "destination_tree_widget", None)
            if tree is not None:
                try:
                    tree.viewport().update()
                except Exception:
                    pass
            cb = st.get("on_complete")
            if cb is not None:
                try:
                    cb(overlay_count)
                except Exception:
                    log_info(
                        "destination_descendant_apply_on_complete_failed",
                        reason="callback_exception_graph_walk",
                    )
            self._destination_maybe_flush_descendant_snapshot_batch_after_apply_job_complete()
            log_info(
                "destination_allocation_descendant_replay_completed",
                graph_walk=True,
                overlay_count=int(overlay_count),
                allocation_destination_path_excerpt=str(ap)[:400],
            )
            return

        model = st["model"]
        parent_ix = st["parent_ix"]
        move = st["move"]
        descendants = st["descendants"]
        added_count = st["added_count"]
        child_map_cache = st["child_map_cache"]
        pending_leaf_batches = st["pending_leaf_batches"]
        visibility_targets = st["visibility_targets"]

        self._allocation_apply_flush_all_pending_model(model, child_map_cache, pending_leaf_batches)
        for rp in visibility_targets.values():
            self._refresh_destination_item_visibility_index(rp, expand=True)
        if added_count > 0:
            self._reconcile_destination_sibling_folders_during_allocation_apply("model_index_end")
        if added_count > 0 or not descendants:
            if parent_ix.isValid():
                self._mark_allocation_descendants_applied_on_allocation_folder_model_index(parent_ix, move)
                self._try_mark_allocation_resolved_after_descendant_apply_finalize(parent_ix, move)
        tree = getattr(self, "destination_tree_widget", None)
        if added_count > 0 and tree is not None:
            try:
                tree.viewport().update()
            except Exception:
                pass
        self._destination_maybe_flush_descendant_snapshot_batch_after_apply_job_complete()
        log_info(
            "destination_allocation_descendant_replay_completed",
            graph_walk=False,
            added_count=int(added_count or 0),
            descendant_total=int(len(descendants) if descendants is not None else 0),
        )

    def _run_destination_descendant_apply_tick(self) -> None:
        if _shutdown_mutation_skip_for_host(self, "_run_destination_descendant_apply_tick"):
            return
        if getattr(self, "_destination_descendant_apply_paused_for_finalize_alloc", False):
            return
        if getattr(self, "_destination_descendant_apply_tick_running", False):
            log_info("descendant_apply_reentrant_guard_skip", reason="nested_descendant_apply_tick")
            self._schedule_destination_descendant_apply_tick()
            self._destination_descendant_apply_drain_note_graph_tick_end(
                "graph_nested_noop", bump_liveness=False
            )
            return
        self._destination_descendant_apply_tick_running = True
        try:
            self._run_destination_descendant_apply_tick_body()
        finally:
            self._destination_descendant_apply_tick_running = False
            self._destination_run_post_tick_descendant_deferred()
            try:
                self._destination_maybe_log_startup_descendant_queue_completed()
            except Exception:
                pass
            try:
                self._destination_maybe_clear_stale_descendant_apply_state_if_idle()
            except Exception:
                pass
            try:
                self._destination_maybe_flush_projection_repair_after_descendant_apply_idle()
            except Exception:
                pass

    def _destination_maybe_flush_projection_repair_after_descendant_apply_idle(self) -> None:
        """Run one deferred overlay projection repair after descendant-apply queue drains (coalesced)."""
        if not getattr(self, "_destination_projection_repair_pending_after_descendant_apply", False):
            return
        dq = getattr(self, "_destination_descendant_apply_queue", None)
        if dq and len(dq) > 0:
            return
        if getattr(self, "_destination_descendant_apply_state", None) is not None:
            return
        self._destination_projection_repair_pending_after_descendant_apply = False
        self._destination_projection_repair_defer_suppress_count = 0
        log_info("destination_projection_repair_resumed_after_descendant_apply")
        try:
            self._run_overlay_projection_invariant_pass("projection_repair_after_descendant_apply_flush")
        except Exception as exc:
            self._log_restore_exception("destination_projection_repair_resumed_after_descendant_apply", exc)

    def _destination_maybe_clear_stale_descendant_apply_state_if_idle(self) -> None:
        """Clear orphaned active apply state when queues are drained and no graph walk is in progress."""
        if getattr(self, "_destination_descendant_apply_tick_running", False):
            return
        st = getattr(self, "_destination_descendant_apply_state", None)
        if st is None:
            return
        dq = getattr(self, "_destination_descendant_apply_queue", None)
        if dq and len(dq) > 0:
            return
        if int(self._unresolved_proposed_queue_size() or 0) > 0:
            return
        if int(self._unresolved_allocation_queue_size() or 0) > 0:
            return
        if isinstance(st, dict) and st.get("graph_walk"):
            return
        log_info(
            "destination_descendant_apply_state_cleared_stale_active",
            reason="queues_drained_no_real_active_work",
        )
        self._destination_descendant_apply_state = None

    def _run_destination_descendant_apply_tick_body(self) -> None:
        st_gate = getattr(self, "_destination_descendant_apply_state", None)
        _scroll_fn = getattr(self, "_destination_user_scroll_interaction_active", None)
        if (
            st_gate is not None
            and st_gate.get("graph_walk")
            and callable(_scroll_fn)
            and _scroll_fn()
        ):
            log_info(
                "background_graph_descendant_paused_for_interaction",
                reason="destination_tree_scroll_active",
            )
            self._destination_descendant_apply_deferred_for_scroll_resume = True
            t_idle = getattr(self, "_destination_tree_scroll_idle_timer", None)
            if t_idle is not None:
                idle_ms = max(120, int(getattr(self, "_destination_tree_scroll_idle_ms", 280) or 280))
                t_idle.start(idle_ms)
            self._destination_descendant_apply_drain_note_graph_tick_end("graph_scroll_deferred")
            return
        if (
            getattr(self, "_application_shutting_down", False)
            and getattr(self, "_destination_snapshot_capture_drain_active", False)
        ):
            st_sd = getattr(self, "_destination_descendant_apply_state", None)
            if isinstance(st_sd, dict) and st_sd.get("graph_walk"):
                self._destination_shutdown_capture_cutoff_graph_walk_for_snapshot(st_sd)
                return
        dm = getattr(self, "destination_planning_model", None)
        _prof = str(os.environ.get("OZLINK_DEST_INJECT_PROFILE", "") or "").strip().lower() in ("1", "true", "yes")
        _t0 = time.perf_counter() if _prof else None
        budget_s = float(getattr(self, "_destination_descendant_apply_budget_s", 0.005) or 0.005)
        if st_gate is not None and st_gate.get("graph_walk"):
            budget_s = float(
                st_gate.get("graph_budget_s") or getattr(self, "_destination_graph_descendant_apply_budget_s", 0.01) or 0.01
            )
        deadline = time.perf_counter() + budget_s
        max_graph_ops = int(getattr(self, "_destination_graph_descendant_apply_max_ops_per_tick", 8) or 8)
        if isinstance(st_gate, dict) and st_gate.get("graph_walk") and st_gate.get("idle_replay_bounded"):
            try:
                cap_idle = int(st_gate.get("idle_replay_max_ops_per_slice") or 50)
            except Exception:
                cap_idle = 50
            max_graph_ops = min(int(max_graph_ops), cap_idle)
        _heavy_replay_ops_capped = False
        graph_ops = 0
        _coalesced = False
        if dm is not None:
            cbs = getattr(dm, "begin_coalesce_destination_structure_signal", None)
            if callable(cbs):
                cbs()
                _coalesced = True

        def _budget_left() -> bool:
            return time.perf_counter() < deadline

        graph_tick_exit_kind = ""
        try:
            while _budget_left():
                st_cur = getattr(self, "_destination_descendant_apply_state", None)
                if (
                    st_cur is not None
                    and st_cur.get("graph_walk")
                    and st_cur.get("heavy_replay")
                    and not _heavy_replay_ops_capped
                ):
                    max_graph_ops = min(
                        int(max_graph_ops), int(self._destination_heavy_replay_max_ops_per_tick())
                    )
                    _heavy_replay_ops_capped = True
                    log_info(
                        "destination_heavy_replay_bounded_graph_ops",
                        max_ops_per_tick=int(max_graph_ops),
                        expected_descendant_total=int(st_cur.get("expected_descendant_total") or 0),
                    )
                if st_cur is not None and st_cur.get("graph_walk") and graph_ops >= max_graph_ops:
                    graph_tick_exit_kind = "graph_budget_slice"
                    break
                if getattr(self, "_destination_descendant_apply_state", None) is None:
                    dq = getattr(self, "_destination_descendant_apply_queue", None)
                    if not dq:
                        self._destination_drain_deferred_heavy_replay_one()
                        if getattr(self, "_destination_descendant_apply_state", None) is not None:
                            continue
                        try:
                            dq2 = getattr(self, "_destination_descendant_apply_queue", None)
                            if dq2 and len(dq2) > 0:
                                continue
                        except Exception:
                            pass
                        return
                    ent = dq.popleft()
                    if len(ent) >= 5:
                        parent_ix, move, on_complete, enq_r, col_r = ent[0], ent[1], ent[2], ent[3], ent[4]
                    else:
                        parent_ix, move, on_complete = ent[0], ent[1], ent[2]
                        enq_r, col_r = "", ""
                    u_i, idle_b = False, False
                    if len(ent) >= 6:
                        u_i = bool(ent[5])
                    if len(ent) >= 7:
                        idle_b = bool(ent[6])
                    st = self._build_destination_descendant_apply_state(
                        parent_ix,
                        move,
                        on_complete,
                        enqueue_reason=str(enq_r or ""),
                        collect_reason=str(col_r or ""),
                        user_initiated=u_i,
                        idle_bounded=idle_b,
                    )
                    if st is None:
                        if on_complete is not None:
                            try:
                                on_complete(0)
                            except Exception:
                                log_info(
                                    "destination_descendant_apply_on_complete_failed",
                                    reason="callback_exception_nil_state",
                                )
                        continue
                    self._destination_descendant_apply_state = st
                    log_info(
                        "destination_allocation_descendant_replay_tick",
                        enqueue_reason_excerpt=str(enq_r or "")[:160],
                        phase=str(st.get("walk_phase") or "")[:40],
                        graph_walk=bool(st.get("graph_walk")),
                    )

                st = self._destination_descendant_apply_state
                phase = st.get("walk_phase")
                if phase == "next_descendant":
                    nxt = self._destination_descendant_apply_prepare_next_descendant(st)
                    if nxt == "stale":
                        if st.get("graph_walk"):
                            self._destination_descendant_apply_drain_note_graph_tick_end(
                                "graph_dead_or_terminal", bump_liveness=False
                            )
                        self._destination_descendant_apply_abort_stale(
                            st,
                            abort_kind=(
                                "terminal_target_gone_or_prepare_fatal_stale"
                                if st.get("graph_walk")
                                else "stale_non_graph_prepare_parent"
                            ),
                        )
                        self._destination_descendant_apply_state = None
                        self._destination_after_descendant_apply_job_slot_cleared()
                        continue
                    if nxt == "yield":
                        graph_tick_exit_kind = "graph_yield_waiting"
                        break
                    if nxt == "done":
                        self._destination_descendant_apply_finalize_job(st)
                        if not st.get("graph_walk"):
                            cb = st.get("on_complete")
                            if cb is not None:
                                try:
                                    cb(st["added_count"])
                                except Exception:
                                    log_info(
                                        "destination_descendant_apply_on_complete_failed",
                                        reason="callback_exception",
                                    )
                        self._destination_descendant_apply_state = None
                        self._destination_after_descendant_apply_job_slot_cleared()
                        continue
                    st["walk_phase"] = "walk"
                    continue
                if phase == "walk":
                    r = self._destination_descendant_apply_process_one_segment(st)
                    if st.get("graph_walk") and r != "yield":
                        graph_ops += 1
                    if r == "stale":
                        if st.get("graph_walk"):
                            self._destination_descendant_apply_drain_note_graph_tick_end(
                                "graph_dead_or_terminal", bump_liveness=False
                            )
                        self._destination_descendant_apply_abort_stale(
                            st, abort_kind="stale_fatal_non_graph_or_graph_terminal"
                        )
                        self._destination_descendant_apply_state = None
                        self._destination_after_descendant_apply_job_slot_cleared()
                        continue
                    if r == "yield":
                        graph_tick_exit_kind = "graph_yield_waiting"
                        break
                    if r == "next_descendant":
                        st["walk_phase"] = "next_descendant"
                    continue
                st["walk_phase"] = "next_descendant"

            if getattr(self, "_destination_descendant_apply_inline_drain", False):
                st_post = getattr(self, "_destination_descendant_apply_state", None)
                if (
                    graph_tick_exit_kind == ""
                    and isinstance(st_post, dict)
                    and st_post.get("graph_walk")
                ):
                    graph_tick_exit_kind = "graph_inline_defer"
                return
            dq_tail = getattr(self, "_destination_descendant_apply_queue", None)
            if getattr(self, "_destination_descendant_apply_state", None) is not None or dq_tail:
                self._schedule_destination_descendant_apply_tick()
        finally:
            if _coalesced and dm is not None:
                cbe = getattr(dm, "end_coalesce_destination_structure_signal", None)
                if callable(cbe):
                    cbe()
            self._destination_descendant_apply_drain_finalize_graph_walk_tick_slice(
                graph_ops, graph_tick_exit_kind
            )
            if _prof and _t0 is not None:
                log_info(
                    "destination_inject_tick_profile",
                    wall_ms=round((time.perf_counter() - _t0) * 1000.0, 3),
                    graph_ops=int(graph_ops),
                    max_graph_ops=int(max_graph_ops),
                )

    def _destination_descendant_apply_abort_stale(self, st, *, abort_kind: str = "legacy_stale_or_inactive_index") -> None:
        try:
            model = st.get("model")
            if model is not None:
                self._allocation_apply_flush_all_pending_model(
                    model, st.get("child_map_cache") or {}, st.get("pending_leaf_batches") or {}
                )
        except Exception:
            pass
        mv = st.get("move") if isinstance(st, dict) else None
        mk = str(self._allocation_move_key(mv) or "")[:120] if isinstance(mv, dict) else ""
        ap_ex = str(st.get("allocation_destination_path") or "")[:400] if isinstance(st, dict) else ""
        pix = st.get("parent_ix") if isinstance(st, dict) else None
        dm = st.get("model") if isinstance(st, dict) else None
        cached_live = None
        if isinstance(pix, QModelIndex) and pix.isValid() and dm is not None:
            try:
                cached_live = bool(not hasattr(dm, "is_index_live") or dm.is_index_live(pix))
            except RuntimeError:
                cached_live = False
        else:
            cached_live = False
        sg = None
        if isinstance(st, dict) and st.get("model") is not None:
            sgf = getattr(st["model"], "structure_generation", None)
            if callable(sgf):
                try:
                    sg = int(sgf())
                except Exception:
                    sg = None
        log_info(
            "destination_descendant_apply_aborted",
            abort_kind=str(abort_kind or "")[:120],
            reason_legacy="stale_or_inactive_index",
            added_count_partial=int(st.get("added_count") or 0) if isinstance(st, dict) else 0,
            move_key_excerpt=mk,
            allocation_destination_path_excerpt=ap_ex,
            cached_parent_index_live=bool(cached_live),
            structure_generation=int(sg) if sg is not None else -1,
        )
        cb = st.get("on_complete")
        if cb is not None:
            try:
                cb(0)
            except Exception:
                log_info(
                    "destination_descendant_apply_on_complete_failed",
                    reason="callback_exception_stale_abort",
                )

    def _destination_descendant_apply_pending_for_parent_index(self, ix: QModelIndex) -> bool:
        """True while a descendant-apply job is active or queued for this allocation parent index."""
        if ix is None or not ix.isValid():
            return False
        t0 = ix.siblingAtColumn(0) if ix.column() != 0 else ix
        st = getattr(self, "_destination_descendant_apply_state", None)
        if isinstance(st, dict):
            pix = st.get("parent_ix")
            if isinstance(pix, QModelIndex) and pix.isValid():
                p0 = pix.siblingAtColumn(0) if pix.column() != 0 else pix
                if p0 == t0:
                    return True
        dq = getattr(self, "_destination_descendant_apply_queue", None)
        if dq:
            for ent in dq:
                if not ent:
                    continue
                qix = ent[0]
                if isinstance(qix, QModelIndex) and qix.isValid():
                    q0 = qix.siblingAtColumn(0) if qix.column() != 0 else qix
                    if q0 == t0:
                        return True
        return False

    def _destination_graph_descendant_expected_allocation_folder_anchor_path(self, move) -> str:
        """Canonical anchored destination folder path for an allocation move (matches graph apply state)."""
        if not isinstance(move, dict):
            return ""
        alloc = str(self._allocation_projection_path(move) or "").strip()
        if not alloc:
            return ""
        if destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            return str(self._canonical_destination_path_with_visible_library_anchor(alloc) or alloc).strip()
        return str(
            self._canonical_destination_projection_path(alloc) or self.normalize_memory_path(alloc) or alloc
        ).strip()

    def _destination_graph_descendant_apply_move_still_planned(self, move) -> bool:
        if not isinstance(move, dict):
            return False
        mk = str(self._allocation_move_key(move) or "").strip().casefold()
        if not mk:
            return True
        for m in getattr(self, "planned_moves", None) or []:
            if isinstance(m, dict) and str(self._allocation_move_key(m) or "").strip().casefold() == mk:
                return True
        return False

    def _destination_descendant_apply_graph_dest_lookup_matches_folder_paths(self, dest_lookup: str, folder_path: str) -> bool:
        dl = str(dest_lookup or "").strip()
        fp = str(folder_path or "").strip()
        if not dl or not fp:
            return False
        if dl.casefold() == fp.casefold():
            return True
        return bool(self._unresolved_overlay_target_paths_equivalent(dl, fp))

    def _destination_descendant_apply_pending_graph_walk_for_dest_lookup(self, dest_lookup: str, move) -> bool:
        """True when an in-flight or queued graph descendant-apply job owns this allocation folder (path identity)."""
        dl = str(dest_lookup or "").strip()
        if not dl:
            return False
        st = getattr(self, "_destination_descendant_apply_state", None)
        if isinstance(st, dict) and st.get("graph_walk"):
            ap = str(st.get("allocation_destination_path") or "").strip()
            if ap and self._destination_descendant_apply_graph_dest_lookup_matches_folder_paths(dl, ap):
                return True
        dq = getattr(self, "_destination_descendant_apply_queue", None)
        for ent in dq or []:
            if not ent or len(ent) < 2:
                continue
            mv = ent[1]
            if not isinstance(mv, dict):
                continue
            qanchor = self._destination_graph_descendant_expected_allocation_folder_anchor_path(mv)
            if qanchor and self._destination_descendant_apply_graph_dest_lookup_matches_folder_paths(dl, qanchor):
                return True
        return False

    def _destination_descendant_apply_active_graph_walk_blocks_dest_lookup(self, dest_lookup: str) -> bool:
        """True when the in-flight graph descendant job's canonical folder path matches ``dest_lookup``."""
        dl = str(dest_lookup or "").strip()
        if not dl:
            return False
        st = getattr(self, "_destination_descendant_apply_state", None)
        if isinstance(st, dict) and st.get("graph_walk"):
            ap = str(st.get("allocation_destination_path") or "").strip()
            if ap and self._destination_descendant_apply_graph_dest_lookup_matches_folder_paths(dl, ap):
                return True
        return False

    def _destination_graph_descendant_apply_try_rebind_parent_ix(self, st: dict) -> str:
        """Re-resolve graph allocation parent from canonical path. Returns ok | yield | terminal."""
        if not isinstance(st, dict) or not st.get("graph_walk"):
            return "ok"
        move = st.get("move")
        if not self._destination_graph_descendant_apply_move_still_planned(move):
            return "terminal"
        dm = st.get("model")
        ap = str(st.get("allocation_destination_path") or "").strip()
        if not ap or dm is None:
            return "terminal"
        prev = st.get("parent_ix")
        prev_bad = True
        if isinstance(prev, QModelIndex) and prev.isValid():
            try:
                prev_bad = bool(hasattr(dm, "is_index_live") and not dm.is_index_live(prev))
            except RuntimeError:
                prev_bad = True
        fresh = self._destination_graph_descendant_resolve_model_index_for_path(dm, ap)
        if (fresh is None or not fresh.isValid()) and isinstance(move, dict):
            fb, _fbr = self._find_destination_allocation_descendant_parent_index(move)
            if fb is not None and fb.isValid():
                fresh = fb.siblingAtColumn(0) if fb.column() != 0 else fb
        if fresh is not None and fresh.isValid():
            try:
                if hasattr(dm, "is_index_live") and not dm.is_index_live(fresh):
                    return "yield"
            except RuntimeError:
                return "yield"
            st["parent_ix"] = fresh
            st["parent_data"] = dict(fresh.data(Qt.UserRole) or {})
            if prev_bad:
                n = int(st.get("_graph_parent_rebind_ok_logged", 0) or 0)
                if n < 4:
                    st["_graph_parent_rebind_ok_logged"] = n + 1
                    _gen_rb = -1
                    _sgf = getattr(dm, "structure_generation", None)
                    if callable(_sgf):
                        try:
                            _gen_rb = int(_sgf())
                        except Exception:
                            _gen_rb = -1
                    log_info(
                        "descendant_apply_stale_parent_rebound_ok",
                        allocation_destination_path_excerpt=str(ap)[:400],
                        move_key_excerpt=str(self._allocation_move_key(move) or "")[:120],
                        structure_generation=int(_gen_rb),
                    )
            return "ok"
        n = int(st.get("_graph_parent_not_materialized_yield_logged", 0) or 0)
        if n < 4:
            st["_graph_parent_not_materialized_yield_logged"] = n + 1
            log_info(
                "descendant_apply_parent_not_currently_materialized_yield",
                allocation_destination_path_excerpt=str(ap)[:400],
                move_key_excerpt=str(self._allocation_move_key(move) or "")[:120],
                cached_parent_valid=bool(
                    isinstance(prev, QModelIndex) and prev.isValid() and not prev_bad
                ),
            )
        return "yield"

    def _enqueue_destination_descendant_apply_to_model(
        self,
        parent_ix: QModelIndex,
        move,
        on_complete=None,
        *,
        enqueue_reason: str = "",
        collect_reason: str = "",
        skip_heavy_replay_defer: bool = False,
        user_initiated: bool = False,
        idle_bounded: bool = False,
        explicit_repair_authorized: bool = False,
        expand_auth_class: str | None = None,
    ) -> bool:
        """Queue incremental allocation-descendant application for a QModelIndex. State is built when the job runs."""
        if _shutdown_mutation_skip_for_host(
            self,
            "_enqueue_destination_descendant_apply_to_model",
            enqueue_reason=str(enqueue_reason or "")[:200],
        ):
            return False
        if (
            hasattr(self, "_destination_startup_phase_active")
            and bool(getattr(self, "_destination_startup_phase_active"))
            and not bool(user_initiated)
        ):
            try:
                self._destination_startup_replay_blocked_count = int(
                    getattr(self, "_destination_startup_replay_blocked_count", 0) or 0
                ) + 1
            except Exception:
                pass
            log_info("destination_startup_replay_hard_blocked", enqueue_reason=str(enqueue_reason or "")[:200])
            return False
        if self._destination_should_block_cold_planned_descendant_replay(
            enqueue_reason=str(enqueue_reason or ""),
            collect_reason=str(collect_reason or ""),
            user_initiated=bool(user_initiated),
        ):
            if (
                hasattr(self, "_destination_startup_phase_active")
                and bool(getattr(self, "_destination_startup_phase_active"))
            ):
                try:
                    self._destination_startup_replay_blocked_count = int(
                        getattr(self, "_destination_startup_replay_blocked_count", 0) or 0
                    ) + 1
                except Exception:
                    pass
            self._destination_planned_replay_deferred_marker(
                parent_ix,
                move,
                log_reason="cold_start_replay_deferred",
            )
            log_info("destination_startup_descendant_replay_blocked_memory_overlay_mode")
            log_info("destination_descendant_replay_not_enqueued_startup_policy")
            return False
        model = getattr(self, "destination_planning_model", None)
        if model is None or not parent_ix.isValid():
            return False
        parent_ix = parent_ix.siblingAtColumn(0) if parent_ix.column() != 0 else parent_ix
        rp, _rq = self._find_destination_allocation_descendant_parent_index(move)
        if rp is not None and rp.isValid():
            rp0 = rp.siblingAtColumn(0) if rp.column() != 0 else rp
            if not hasattr(model, "is_index_live") or model.is_index_live(rp0):
                parent_ix = rp0
        if hasattr(model, "is_index_live") and not model.is_index_live(parent_ix):
            return False
        dq = getattr(self, "_destination_descendant_apply_queue", None)
        if dq is None:
            dq = deque()
            self._destination_descendant_apply_queue = dq
        st = getattr(self, "_destination_descendant_apply_state", None)
        if st is not None:
            pix = st.get("parent_ix")
            if isinstance(pix, QModelIndex) and pix.isValid():
                p0 = pix.siblingAtColumn(0) if pix.column() != 0 else pix
                if p0 == parent_ix:
                    log_info(
                        "destination_descendant_apply_enqueue_skipped_duplicate_parent",
                        enqueue_reason=str(enqueue_reason or "")[:200],
                        reason="active_job_same_parent_index",
                    )
                    return True
        for ent in dq:
            qix = ent[0]
            if isinstance(qix, QModelIndex) and qix.isValid():
                q0 = qix.siblingAtColumn(0) if qix.column() != 0 else qix
                if q0 == parent_ix:
                    log_info(
                        "destination_descendant_apply_enqueue_skipped_duplicate_parent",
                        enqueue_reason=str(enqueue_reason or "")[:200],
                        reason="already_queued_same_parent_index",
                    )
                    return True
        _graph_auth_enqueue = destination_authority_contract.graph_owns_visible_real_destination_structure(self)
        _auth_class_enq = str(expand_auth_class or "").strip() or self._destination_infer_expand_auth_class()
        _assess_enq: dict | None = None
        _assessor_called_enq = False
        _assess_out_enq = "not_called"
        _skip_heavy_replay = bool(skip_heavy_replay_defer)
        if _graph_auth_enqueue:
            _aq = f"enqueue:{str(enqueue_reason or '')[:80]}"
            _assess_enq = self._destination_descendant_snapshot_reuse_assess(parent_ix, move, audit_context=_aq)
            _assessor_called_enq = True
            _assess_out_enq = str((_assess_enq or {}).get("outcome") or "rejected")
            if _assess_enq.get("outcome") == "complete":
                self._log_destination_descendant_replay_reuse_gate_result(
                    enqueue_site="_enqueue_destination_descendant_apply_to_model",
                    enqueue_reason=str(enqueue_reason or ""),
                    collect_reason=str(collect_reason or ""),
                    move=move,
                    parent_ix=parent_ix,
                    graph_authority=True,
                    assessor_called=True,
                    assess_outcome="complete",
                )
                source_item = self._find_source_item_for_planned_move(move)
                source_root_data = self._source_tree_row_payload(source_item) if source_item is not None else {}
                if not source_root_data:
                    source_root_data = dict(move.get("source", {}) or {})
                cur_token = self._destination_allocation_projection_resume_token(move, source_root_data)
                self._destination_descendant_snapshot_reuse_mark_allocation_applied_index(
                    parent_ix,
                    move,
                    audit_context=_aq,
                    overlay_count=int(_assess_enq.get("overlay_descendant_count") or 0),
                    expected_count=int(_assess_enq.get("expected_descendant_count") or 0),
                    cur_token=str(cur_token or ""),
                )
                tree_rc = getattr(self, "destination_tree_widget", None)
                self._refresh_destination_item_visibility_index(parent_ix)
                self._apply_tree_item_visual_state(None, parent_ix.data(Qt.UserRole) or {})
                if tree_rc is not None:
                    tree_rc.viewport().update()
                if on_complete is not None:
                    try:
                        on_complete(int(_assess_enq.get("overlay_descendant_count") or 0))
                    except Exception:
                        log_info(
                            "destination_descendant_apply_on_complete_failed",
                            reason="reuse_snapshot_callback_exception",
                        )
                return True
            if _assess_enq.get("outcome") == "partial":
                log_info(
                    "destination_descendant_replay_partial_snapshot_resume",
                    enqueue_reason=str(enqueue_reason or "")[:200],
                    expected_descendant_count=int(_assess_enq.get("expected_descendant_count") or -1),
                    overlay_descendant_count=int(_assess_enq.get("overlay_descendant_count") or -1),
                    move_key_excerpt=str(self._allocation_move_key(move) or "")[:120],
                )
                log_info(
                    "destination_descendant_replay_full_replay_required",
                    reason="partial_subtree_missing_only_apply_not_seeded_from_snapshot_audit",
                    enqueue_reason=str(enqueue_reason or "")[:200],
                )
        if _graph_auth_enqueue and _assess_enq and self._destination_memory_overlay_mode_enabled():
            _er_ov = str(enqueue_reason or "").lower()
            _st_ov = getattr(self, "_destination_overlay_store", None)
            _dp3 = ""
            if isinstance(move, dict):
                try:
                    _dp3 = str(self._allocation_projection_path(move) or move.get("destination_path") or "")
                except Exception:
                    _dp3 = ""
            _dpc = ""
            if str(_dp3 or "").strip():
                _dpc = self._canonical_planned_memory_path_for_graph_match(
                    self.normalize_memory_path(str(_dp3).strip())
                )
            if _st_ov is not None and _dpc and (
                "startup" in _er_ov or "after_sharepoint" in _er_ov or "projection" in _er_ov
            ):
                if _st_ov.has_overlay_path_prefix(_dpc) and str((_assess_enq or {}).get("outcome") or "") not in (
                    "complete",
                ):
                    _skip_heavy_replay = True
                    log_info(
                        "destination_replay_disallowed_for_startup_visibility",
                        enqueue_reason=str(enqueue_reason or "")[:200],
                        has_overlay_for_branch=bool(_dpc),
                    )
                elif not _st_ov.has_overlay_path_prefix(_dpc) and str(
                    (_assess_enq or {}).get("outcome") or ""
                ) in ("partial", "rejected"):
                    log_info(
                        "destination_replay_fallback_admitted_missing_memory",
                        path_excerpt=str(_dp3)[:400],
                    )
        _exp_defer = int((_assess_enq or {}).get("expected_descendant_count") or 0) if _assess_enq else 0
        if _graph_auth_enqueue and isinstance(move, dict) and self._destination_memory_overlay_mode_enabled():
            pl_pr = dict(parent_ix.data(Qt.UserRole) or {})
            row_pr = str(self._tree_item_path(pl_pr) or "").strip()
            canon_pr = str(
                self._canonical_planned_memory_path_for_graph_match(row_pr) or self.normalize_memory_path(row_pr) or ""
            ).strip()
            _assess_pre = self._destination_assess_memory_backed_branch(
                canonical_path=canon_pr, move=move, node_data=pl_pr, dm=model, parent_ix=parent_ix
            )
            vdir_p = int(_assess_pre.get("visible_child_count") or 0)
            vtot_p = int(_assess_pre.get("visible_descendant_count") or 0)
            _mem_b = bool(_assess_pre.get("memory_backed_branch"))
            _deny = bool(
                _mem_b
                and (str(_auth_class_enq) not in ("explicit_user_repair",) and not bool(explicit_repair_authorized))
            )
            _deny_r = (
                "memory_backed_replay_requires_explicit_repair"
                if _deny
                else ("not_memory_backed" if not _mem_b else "explicit_repair_authorized")
            )
            log_info(
                "destination_pre_replay_branch_classification",
                canonical_path=canon_pr[:500],
                row_kind=str(pl_pr.get("row_kind") or "")[:40],
                auth_class=str(_auth_class_enq)[:40],
                memory_backed=_mem_b,
                stored_children_count=int(_assess_pre.get("stored_children_count") or 0),
                stored_descendant_count=int(_assess_pre.get("stored_descendant_count") or 0),
                visible_children_count=vdir_p,
                visible_descendant_count=vtot_p,
                explicit_repair_authorized=bool(explicit_repair_authorized),
                replay_denied=bool(_deny),
                deny_reason=str(_deny_r)[:120],
            )
            _mp = self._destination_pre_descendant_replay_memory_branch_policy(
                parent_ix,
                move,
                enqueue_reason=str(enqueue_reason or ""),
                user_initiated=bool(user_initiated),
                idle_bounded=bool(idle_bounded),
                explicit_repair_authorized=bool(explicit_repair_authorized),
                expand_auth_class=str(_auth_class_enq),
            )
            if _mp == "rehydrated_no_replay":
                tree_rc2 = getattr(self, "destination_tree_widget", None)
                self._refresh_destination_item_visibility_index(parent_ix)
                self._apply_tree_item_visual_state(None, parent_ix.data(Qt.UserRole) or {})
                if tree_rc2 is not None:
                    tree_rc2.viewport().update()
                if on_complete is not None:
                    try:
                        on_complete(0)
                    except Exception:
                        log_info(
                            "destination_descendant_apply_on_complete_failed",
                            reason="memory_rehydrate_no_replay_callback",
                        )
                return True
            if _mp == "blocked":
                return False
        if (
            bool(user_initiated)
            and bool(idle_bounded)
            and int(_exp_defer) > int(self._DESTINATION_IDLE_REPLAY_MAX_ESTIMATED_DESCENDANTS)
        ):
            if (
                hasattr(self, "_destination_startup_phase_active")
                and bool(getattr(self, "_destination_startup_phase_active"))
            ):
                try:
                    self._destination_startup_replay_blocked_count = int(
                        getattr(self, "_destination_startup_replay_blocked_count", 0) or 0
                    ) + 1
                except Exception:
                    pass
            log_info(
                "destination_idle_replay_blocked_large_allocation",
                expected_descendant_count=int(_exp_defer),
                threshold=int(self._DESTINATION_IDLE_REPLAY_MAX_ESTIMATED_DESCENDANTS),
            )
            return False
        if (
            not _skip_heavy_replay
            and _graph_auth_enqueue
            and _assess_enq
            and str((_assess_enq or {}).get("outcome") or "") not in ("complete",)
        ):
            _defer, _dcode = self._destination_heavy_replay_should_defer_enqueue(int(_exp_defer))
            if _defer:
                self._destination_deferred_heavy_replay_enqueue(
                    parent_ix,
                    move,
                    on_complete,
                    enqueue_reason=str(enqueue_reason or ""),
                    collect_reason=str(collect_reason or ""),
                    expected_n=int(_exp_defer),
                    defer_code=str(_dcode)[:100],
                    idle_bounded=bool(idle_bounded),
                    explicit_repair_authorized=bool(explicit_repair_authorized),
                )
                log_info(
                    "destination_descendant_replay_deferred_by_heavy_gate",
                    expected_descendant_count=int(_exp_defer),
                    threshold=int(self._destination_heavy_replay_threshold()),
                    gate_detail=str(_dcode)[:120],
                )
                return True
        self._log_destination_descendant_replay_reuse_gate_result(
            enqueue_site="_enqueue_destination_descendant_apply_to_model",
            enqueue_reason=str(enqueue_reason or ""),
            collect_reason=str(collect_reason or ""),
            move=move,
            parent_ix=parent_ix,
            graph_authority=bool(_graph_auth_enqueue),
            assessor_called=bool(_assessor_called_enq),
            assess_outcome=_assess_out_enq,
            skip_reason_if_no_assessor=(
                ""
                if _graph_auth_enqueue
                else "graph_authority_false_enqueue_without_assessor"
            ),
        )
        _auth_gate = str(expand_auth_class or "").strip() or str(_auth_class_enq)
        e_low = str(enqueue_reason or "").lower()
        _looks_like_deferred_bypass = (
            "deferred_user_expand" in e_low
            or "startup_visibility_bypass" in e_low
            or ("load_projected" in e_low and "bypass" in e_low)
        )
        if (
            _looks_like_deferred_bypass
            and bool(user_initiated)
            and not bool(explicit_repair_authorized)
            and _auth_gate not in ("explicit_user_repair",)
        ):
            pl_gate = dict(parent_ix.data(Qt.UserRole) or {})
            _pth_g = str(
                self._tree_item_path(pl_gate) or self._destination_semantic_path(pl_gate) or ""
            )[:500]
            log_info(
                "destination_replay_hard_blocked_non_explicit_auth",
                canonical_path=_pth_g,
                auth_class=str(_auth_gate)[:40],
                enqueue_reason=str(enqueue_reason or "")[:200],
                explicit_repair_authorized=bool(explicit_repair_authorized),
            )
            return False
        dq.append(
            (
                parent_ix,
                move,
                on_complete,
                str(enqueue_reason or ""),
                str(collect_reason or ""),
                bool(user_initiated),
                bool(idle_bounded),
                bool(explicit_repair_authorized),
                str(_auth_class_enq)[:64],
            )
        )
        if not bool(user_initiated):
            try:
                self._destination_startup_replay_enqueued_count = int(
                    getattr(self, "_destination_startup_replay_enqueued_count", 0) or 0
                ) + 1
            except Exception:
                pass
        log_info(
            "destination_descendant_apply_enqueued",
            enqueue_reason=str(enqueue_reason or "")[:200],
            collect_reason=str(collect_reason or "")[:200],
            queue_len=len(dq),
        )
        log_info(
            "destination_allocation_descendant_replay_enqueued",
            enqueue_reason=str(enqueue_reason or "")[:200],
            collect_reason=str(collect_reason or "")[:200],
            queue_len=len(dq),
            move_key_excerpt=str(self._allocation_move_key(move) or "")[:120],
            user_initiated=bool(user_initiated),
            idle_bounded=bool(idle_bounded),
            explicit_repair_authorized=bool(explicit_repair_authorized),
        )
        if getattr(self, "_overlay_followup_after_import", False) and not getattr(
            self, "_descendant_replay_after_import_started_logged", False
        ):
            log_info(
                "destination_allocation_descendant_replay_started_after_import",
                queue_len=len(dq),
            )
            self._descendant_replay_after_import_started_logged = True
        self._schedule_destination_descendant_apply_tick()
        return True

    def _apply_allocation_descendants_to_model_index(
        self,
        parent_ix: QModelIndex,
        move,
        completion_callback=None,
        *,
        enqueue_reason: str = "",
        collect_reason: str = "",
        user_initiated: bool = False,
        idle_bounded: bool = False,
        explicit_repair_authorized: bool = False,
        expand_auth_class: str | None = None,
    ) -> int:
        """Apply projected allocation descendants under parent_ix. Work is incremental; return value is always 0."""
        self._enqueue_destination_descendant_apply_to_model(
            parent_ix,
            move,
            completion_callback,
            enqueue_reason=enqueue_reason,
            collect_reason=collect_reason,
            user_initiated=bool(user_initiated),
            idle_bounded=bool(idle_bounded),
            explicit_repair_authorized=bool(explicit_repair_authorized),
            expand_auth_class=expand_auth_class,
        )
        return 0

    def _allocation_projection_relative_source_segments(self, source_root_path, descendant_source_path):
        """Segments of descendant path under allocation source root.

        Graph often returns paths relative to the resolved folder (e.g. ``Working with Children\\a.pdf``)
        while the tree uses a full canonical root (``...\\Working with Children``). Match via full prefix
        first, then longest suffix/prefix segment overlap (case-insensitive).
        """
        source_root_path = self._canonical_source_projection_path(source_root_path or "")
        descendant_source_path = self._canonical_source_projection_path(descendant_source_path or "")
        if not source_root_path or not descendant_source_path:
            return None
        if descendant_source_path == source_root_path:
            return []
        root_segs = self._path_segments(source_root_path)
        desc_segs = self._path_segments(descendant_source_path)
        if not desc_segs:
            return None
        if descendant_source_path.startswith(source_root_path + "\\") or descendant_source_path.startswith(
            source_root_path + "/"
        ):
            rel = descendant_source_path[len(source_root_path) :].lstrip("\\/")
            return self._path_segments(rel)
        if not root_segs:
            return None
        rlow = [s.casefold() for s in root_segs]
        dlow = [s.casefold() for s in desc_segs]
        max_k = min(len(root_segs), len(desc_segs))
        for k in range(max_k, 0, -1):
            if rlow[-k:] == dlow[:k]:
                return desc_segs[k:]
        return None

    def _apply_allocation_descendants_to_item(self, parent_item, move):
        """Deprecated: use _apply_allocation_descendants_to_model_index."""
        if parent_item is None or move is None:
            return 0
        if isinstance(parent_item, QModelIndex):
            return self._apply_allocation_descendants_to_model_index(parent_item, move)
        return 0

    def _destination_bind_normalized_expanded_targets(self, destination_expanded_paths):
        target_paths = {p for p in (destination_expanded_paths or set()) if p}
        target_paths.add("Root")
        normalized_targets = set(target_paths)
        for path in list(target_paths):
            k = self._destination_expansion_state_key(path)
            if k:
                normalized_targets.add(k)
        return normalized_targets

    def _destination_projection_eager_expand_all_destination(self):
        return bool((getattr(self, "_workspace_restore_expanded_all_intent", None) or {}).get("destination"))

    def _destination_bind_allocation_descendants_eager_active(self):
        """When False, bind never hydrates full allocation subtrees (lazy expand path only).

        Tests may enable this and override ``_destination_bind_should_apply_allocation_descendants_now``
        to exercise eager bind-time projection without walking every allocation row on each bind.
        """
        return False

    def _destination_bind_should_apply_allocation_descendants_now(self, allocation_semantic_path, normalized_targets):
        """Whether to materialize all projected descendants during bind (eager).

        When ``_destination_bind_allocation_descendants_eager_active()`` is False (production),
        projected descendants stay lazy on bind. Expand-all and session restore hydrate via the
        destination expand-all queue, expand signals, and ``_hydrate_destination_allocations_for_expanded_paths_*``
        after bind (signals unblocked).

        ``allocation_semantic_path`` and ``normalized_targets`` are retained for call-site compatibility
        when eager bind is enabled in future or in tests.
        """
        if not self._destination_bind_allocation_descendants_eager_active():
            _ = (allocation_semantic_path, normalized_targets)
            return False
        _ = (allocation_semantic_path, normalized_targets)
        return False

    def _destination_incremental_merge_root_needed_now(self, projected_root_semantic_path, normalized_targets):
        if self._destination_projection_eager_expand_all_destination():
            return True
        sp = self._canonical_destination_projection_path(projected_root_semantic_path)
        if not sp:
            return True
        if not normalized_targets:
            return False
        pfx = sp + "\\"
        for t in normalized_targets:
            ts = self._canonical_destination_projection_path(str(t).strip()) if t else ""
            if not ts:
                continue
            if ts == sp or ts.startswith(pfx):
                return True
        return False

    def _safe_resolve_live_indices_for_canonical_destination_path(self, model, canonical_path: str) -> List[QModelIndex]:
        """Resolve fresh QModelIndex rows for a canonical path after yields/processEvents (no stale index reuse).

        Do not call ``update_payload_for_index`` in a loop over this list — the first update can
        invalidate later sibling indices from the same snapshot. For repeated per-path mutations,
        use :meth:`_destination_allocation_apply_canonical_path_one_index_per_resolve` instead.
        """
        if not canonical_path or model is None:
            return []
        try:
            hits = model.find_indices_for_canonical_destination_path(canonical_path)
        except Exception:
            return []
        out: List[QModelIndex] = []
        for ix in hits or []:
            try:
                if not ix.isValid():
                    continue
                if hasattr(model, "is_index_live") and not model.is_index_live(ix):
                    continue
            except RuntimeError:
                continue
            out.append(ix)
        return out

    def _safe_resolve_index_for_path(self, model, canonical_path: str) -> Optional[QModelIndex]:
        """First live QModelIndex for ``canonical_path``, or None if the row no longer exists."""
        for ix in self._safe_resolve_live_indices_for_canonical_destination_path(model, canonical_path):
            return ix
        return None

    def _destination_allocation_apply_canonical_path_one_index_per_resolve(
        self,
        dmodel,
        canonical_path: str,
        *,
        predicate: Callable[[QModelIndex, Dict[str, Any]], bool],
        apply_once: Callable[[QModelIndex, Dict[str, Any]], None],
    ) -> int:
        """Apply allocation work for ``canonical_path`` without reusing stale sibling indices.

        Each round: resolve a fresh live-index list, scan it **read-only** for the first index that
        satisfies ``predicate``, apply at most one ``update_payload_for_index`` / structural change via
        ``apply_once``, then re-resolve. Repeat until no qualifying live index remains.

        Mutations must not run inside the read-only scan over ``indices`` — only after a single target
        is chosen.
        """
        applied_rounds = 0
        while True:
            indices = self._safe_resolve_live_indices_for_canonical_destination_path(dmodel, canonical_path)
            if not indices:
                break
            target: Optional[QModelIndex] = None
            for cand in indices:
                try:
                    if not dmodel.is_index_live(cand):
                        continue
                except RuntimeError:
                    continue
                nd = cand.data(Qt.UserRole) or {}
                if not isinstance(nd, dict):
                    nd = {}
                try:
                    if predicate(cand, nd):
                        target = cand
                        break
                except Exception:
                    continue
            if target is None:
                break
            nd = target.data(Qt.UserRole) or {}
            if not isinstance(nd, dict):
                nd = {}
            apply_once(target, nd)
            applied_rounds += 1
        return applied_rounds

    def _destination_model_build_allocation_apply_pairs(self, dmodel, pm_lookup):
        """Planned allocation folder rows with resolved moves: canonical path + move (indexes re-resolved at apply time)."""
        pairs: list[tuple[str, Any]] = []
        paths_with_pair: set[str] = set()
        alloc_by_path = pm_lookup.get("alloc_by_path") or {}
        for ap, move in alloc_by_path.items():
            if not ap:
                continue
            try:
                hits = dmodel.find_indices_for_canonical_destination_path(ap)
            except Exception:
                hits = []
            if not hits:
                continue
            any_ok = False
            for ix in hits:
                if not ix.isValid():
                    continue
                nd = ix.data(Qt.UserRole) or {}
                if self.node_is_planned_allocation(nd) and bool(nd.get("is_folder", False)):
                    any_ok = True
                    break
            if any_ok:
                pairs.append((ap, move))
                paths_with_pair.add(ap)

        for ix in dmodel.iter_depth_first():
            nd = ix.data(Qt.UserRole) or {}
            if not self.node_is_planned_allocation(nd) or not bool(nd.get("is_folder", False)):
                continue
            key = self._destination_payload_index_key(nd)
            if not key:
                continue
            if key in paths_with_pair:
                continue
            move = self._find_planned_move_for_destination_node_indexed(nd, pm_lookup)
            if move is None:
                continue
            pairs.append((key, move))
            paths_with_pair.add(key)
        return pairs

    def _apply_visible_destination_allocation_descendants(self, *, destination_expanded_paths=None):
        if getattr(self, "_startup_memory_minimal_replay_active", False):
            log_info(
                "startup_memory_minimal_replay_heavy_path_blocked",
                blocked="apply_visible_destination_allocation_descendants",
            )
            return 0
        tree = getattr(self, "destination_tree_widget", None)
        if tree is None:
            return 0

        if destination_expanded_paths is not None:
            ep = set(destination_expanded_paths or set())
        else:
            ep = self._destination_expanded_paths_for_planning_bind()
        nt = self._destination_bind_normalized_expanded_targets(ep)
        dmodel = self.destination_planning_model
        applied_count = 0
        allocation_pass = 0
        visited = 0
        if not self._destination_bind_allocation_descendants_eager_active():
            pm_lookup = self._build_planned_move_destination_lookup()
            alloc_by_path = pm_lookup.get("alloc_by_path") or {}
            touched = 0
            def _lazy_mark_children_loaded_pred(_ix, nd):
                return (
                    self.node_is_planned_allocation(nd)
                    and bool(nd.get("is_folder", False))
                    and bool(nd.get("allocation_descendants_applied"))
                    and not bool(nd.get("children_loaded"))
                )

            def _lazy_apply_children_loaded(ix, node_data):
                nd = dict(node_data)
                nd["children_loaded"] = True
                nd["projection_unresolved_terminal"] = False

                def _mut(p, repl=nd):
                    p.clear()
                    p.update(repl)

                dmodel.update_payload_for_index(ix, _mut)

            for ap in alloc_by_path:
                if not ap:
                    continue
                visited += 1
                if visited % 40 == 0:
                    QApplication.processEvents(QEventLoop.ProcessEventsFlag.ExcludeUserInputEvents)
                touched += self._destination_allocation_apply_canonical_path_one_index_per_resolve(
                    dmodel,
                    ap,
                    predicate=_lazy_mark_children_loaded_pred,
                    apply_once=_lazy_apply_children_loaded,
                )
            if touched:
                return applied_count
            fallback_paths: list[str] = []
            fallback_seen: set[str] = set()
            for ix in dmodel.iter_depth_first():
                node_data = ix.data(Qt.UserRole) or {}
                if not self.node_is_planned_allocation(node_data):
                    continue
                if not bool(node_data.get("is_folder", False)):
                    continue
                if not bool(node_data.get("allocation_descendants_applied")):
                    continue
                if bool(node_data.get("children_loaded")):
                    continue
                key = self._destination_payload_index_key(node_data)
                if not key or key in fallback_seen:
                    continue
                fallback_seen.add(key)
                fallback_paths.append(key)
            for ap in fallback_paths:
                visited += 1
                if visited % 40 == 0:
                    QApplication.processEvents(QEventLoop.ProcessEventsFlag.ExcludeUserInputEvents)
                self._destination_allocation_apply_canonical_path_one_index_per_resolve(
                    dmodel,
                    ap,
                    predicate=_lazy_mark_children_loaded_pred,
                    apply_once=_lazy_apply_children_loaded,
                )
            return applied_count

        pm_lookup = self._build_planned_move_destination_lookup()

        def _eager_allocation_descendant_work_pred(_ix, nd):
            if not self.node_is_planned_allocation(nd):
                return False
            if not bool(nd.get("is_folder", False)):
                return False
            if bool(nd.get("allocation_descendants_applied")):
                return not bool(nd.get("children_loaded"))
            sem = self._destination_semantic_path(nd)
            return self._destination_bind_should_apply_allocation_descendants_now(sem, nt)

        for path, move in self._destination_model_build_allocation_apply_pairs(dmodel, pm_lookup):
            visited += 1
            if visited % 40 == 0:
                QApplication.processEvents(QEventLoop.ProcessEventsFlag.ExcludeUserInputEvents)

            def _eager_apply_once(ix, node_data, _move=move):
                nonlocal applied_count
                if bool(node_data.get("allocation_descendants_applied")):
                    nd = dict(node_data)
                    nd["children_loaded"] = True
                    nd["projection_unresolved_terminal"] = False

                    def _mut(p):
                        p.clear()
                        p.update(nd)

                    dmodel.update_payload_for_index(ix, _mut)
                else:
                    applied_count += self._apply_allocation_descendants_to_model_index(
                        ix,
                        _move,
                        collect_reason="eager_bind_allocation_descendants",
                        enqueue_reason="eager_bind_allocation_descendants",
                        user_initiated=False,
                    )

            allocation_pass += self._destination_allocation_apply_canonical_path_one_index_per_resolve(
                dmodel,
                path,
                predicate=_eager_allocation_descendant_work_pred,
                apply_once=_eager_apply_once,
            )
            if allocation_pass % 2 == 0:
                QApplication.processEvents(QEventLoop.ProcessEventsFlag.ExcludeUserInputEvents)
        if applied_count:
            tree.viewport().update()
        return applied_count

    def _destination_node_state(self, node_data):
        if self.node_is_planned_allocation(node_data):
            return "allocated"
        if self.node_is_proposed(node_data):
            return "proposed"
        if str(node_data.get("node_origin", "")).lower() == "projecteddestination":
            return "projected"
        return "real"

    def _destination_resolution_rank(self, node_data):
        state = self._destination_node_state(node_data)
        if state == "real":
            return 0
        if state == "projected":
            return 1
        if state == "proposed":
            return 2
        return 3

    def _select_canonical_destination_item(self, items, prefer=None):
        if not items:
            return None
        first = items[0]
        if isinstance(first, QModelIndex):
            if prefer is not None and prefer.isValid():
                p = prefer.siblingAtColumn(0) if prefer.column() != 0 else prefer
                for it in items:
                    if isinstance(it, QModelIndex) and it.isValid() and it == p:
                        return it

            def _key_ix(ix):
                pl = ix.data(Qt.UserRole) or {}
                tree_path = self._tree_item_path(pl)
                return (
                    self._destination_resolution_rank(pl),
                    0 if self._destination_raw_path_uses_library_root_hub(tree_path) else 1,
                    -len(self._path_segments(tree_path)),
                )

            return min(items, key=_key_ix)
        if prefer is not None and not isinstance(first, QModelIndex):
            try:
                for it in items:
                    if it is prefer:
                        return it
            except TypeError:
                pass
        return min(
            items,
            key=lambda item: (
                self._destination_resolution_rank(item.data(0, Qt.UserRole) or {}),
                0
                if self._destination_raw_path_uses_library_root_hub(
                    self._tree_item_path(item.data(0, Qt.UserRole) or {})
                )
                else 1,
                -len(self._path_segments(self._tree_item_path(item.data(0, Qt.UserRole) or {}))),
            ),
        )

    def _destination_semantic_path(self, node_data):
        return self._canonical_destination_projection_path(self._tree_item_path(node_data))

    def _destination_folder_display_name_for_sibling_dedup(self, node_data):
        """Extract a comparable folder name token from explorer-style ``base_display_label``."""
        if not isinstance(node_data, dict):
            return ""
        label = str(node_data.get("base_display_label") or "").strip()
        if not label:
            return ""
        low = label.lower()
        if low.startswith("folder:"):
            label = label[7:].strip()
        # Strip trailing chrome: [Allocated], (Proposed), etc.
        label = re.sub(r"\s*\[[^\]]*\]\s*$", "", label, flags=re.IGNORECASE).strip()
        label = re.sub(r"\s*\([^)]*\)\s*$", "", label).strip()
        return label.casefold() if label else ""

    def _destination_sibling_folder_dedup_key(self, node_data):
        """Case-folded folder name for sibling dedup when canonical paths disagree but labels match."""
        if not isinstance(node_data, dict) or not node_data.get("is_folder"):
            return ""
        for k in ("real_name", "name"):
            v = str(node_data.get(k) or "").strip()
            if v:
                return v.casefold()
        dn = self._destination_folder_display_name_for_sibling_dedup(node_data)
        if dn:
            return dn
        segs = self._path_segments(self._tree_item_path(node_data))
        if segs:
            return str(segs[-1] or "").casefold()
        return ""

    @staticmethod
    def _destination_sibling_name_collision_token(name_key: str) -> str:
        """Map ``Sub`` and ``Sub - via F`` to one token so projection paths match snapshot names."""
        s = str(name_key or "").strip().casefold()
        if not s:
            return ""
        for ch in ("\u2013", "\u2014", "\u2212"):
            s = s.replace(ch, "-")
        if " - " in s:
            return s.split(" - ", 1)[0].strip()
        return s

    def _destination_sibling_folder_collision_key(self, node_data):
        """Weak folder identity under one parent (path segment vs ``Name - suffix``)."""
        dk = self._destination_sibling_folder_dedup_key(node_data)
        if not dk:
            return ""
        # Some API payloads store a full path in ``name`` / ``real_name`` while a sibling row uses
        # the leaf only; under one parent we compare by last segment (matches path-tail fallback).
        if "\\" in dk or "/" in dk:
            dk = dk.replace("/", "\\").split("\\")[-1].strip()
        return self._destination_sibling_name_collision_token(dk)

    def _destination_expansion_state_key(self, path: str) -> str:
        """Normalize paths for expand/collapse persistence across tree rebuilds.

        Live SharePoint rows often use ``Site\\Library\\Root\\...`` while future-model binds use
        ``Root\\...`` only. Without this, ``_restore_expanded_destination_paths`` after
        ``_bind_destination_tree_from_future_state_model`` only restores ``Root``, leaving deep
        nodes visually collapsed while the expand-all button still says *Collapse All*.
        """
        canon = self._canonical_destination_projection_path(path or "")
        if not canon:
            return ""
        segs = self._path_segments(canon)
        for i, seg in enumerate(segs):
            if str(seg).strip().lower() == "root":
                return "\\".join(segs[i:])
        return canon

    def _destination_future_state_rank(self, node_state):
        if node_state == "projected":
            return 0
        if node_state == "proposed":
            return 1
        if node_state == "allocated":
            return 2
        return 3

    def _destination_model_state_priority(self, node_state):
        # Higher wins on merge. Planned allocation at a path must replace a snapshot "real" row
        # at the same semantic path so reset_nested receives [Allocated] chrome in the payload.
        if node_state == "allocated":
            return 4
        if node_state == "real":
            return 3
        if node_state == "proposed":
            return 2
        if node_state == "projected":
            return 1
        if node_state == "projected_descendant":
            return 1
        return 0

    def _snapshot_real_destination_node(self, item):
        if item is None:
            return None
        node_data = item.data(0, Qt.UserRole) or {}
        if node_data.get("placeholder") or self._destination_is_future_state_node(node_data):
            return None
        semantic_path = self._destination_semantic_path(node_data)
        if not semantic_path:
            return None
        snapshot = {
            "semantic_path": semantic_path,
            "parent_semantic_path": self.normalize_memory_path("\\".join(self._path_segments(semantic_path)[:-1])),
            "data": dict(node_data),
            "children": [],
        }
        for index in range(item.childCount()):
            child_snapshot = self._snapshot_real_destination_node(item.child(index))
            if child_snapshot is not None:
                snapshot["children"].append(child_snapshot)
        return snapshot

    def _collect_real_destination_snapshot_entries(self, item, entries):
        if item is None:
            return
        node_data = item.data(0, Qt.UserRole) or {}
        if not node_data.get("placeholder"):
            semantic_path = self._destination_semantic_path(node_data)
            if semantic_path and not self._destination_is_future_state_node(node_data):
                entries.append({
                    "semantic_path": semantic_path,
                    "parent_semantic_path": self.normalize_memory_path("\\".join(self._path_segments(semantic_path)[:-1])),
                    "data": dict(node_data),
                    "children": [],
                })
        for index in range(item.childCount()):
            self._collect_real_destination_snapshot_entries(item.child(index), entries)

    def _collect_real_destination_snapshot_entries_index(self, entries):
        """Flat snapshot of real (non-placeholder, non-future-overlay) rows from ``destination_planning_model``."""
        model = getattr(self, "destination_planning_model", None)
        if model is None:
            return
        for ix in model.iter_depth_first():
            node_data = ix.data(Qt.UserRole) or {}
            if node_data.get("placeholder"):
                continue
            semantic_path = self._destination_semantic_path(node_data)
            if not semantic_path or self._destination_is_future_state_node(node_data):
                continue
            entries.append({
                "semantic_path": semantic_path,
                "parent_semantic_path": self.normalize_memory_path("\\".join(self._path_segments(semantic_path)[:-1])),
                "data": dict(node_data),
                "children": [],
            })

    def _mark_destination_real_tree_snapshot_stale(self) -> None:
        """Real (non-overlay) destination rows changed; next overlay build must rescan the tree."""
        self._destination_real_tree_snapshot_stale = True

    def _refresh_destination_real_tree_snapshot(self, *, force: bool = False):
        """Refresh the in-memory real-row snapshot used for overlay fingerprinting and digest logic.

        When the Graph full-library walk for the active drive has completed, enumerate paths are merged
        with visible planning-model real rows for this **in-memory** structure (full walk wins on path
        collision). Under SharePoint graph structural authority (:mod:`destination_authority_contract`),
        this merged data is **not** imported into the future model as bindable visible real rows
        (see ``_build_destination_future_model``); it supports trust, validation, and reconcile only.

        Until full enumerate completes, the snapshot reflects what is already in the planning model
        (root and expanded folders must come from live Graph loads).
        """
        if not force and not getattr(self, "_destination_real_tree_snapshot_stale", True):
            if is_dev_mode():
                _perf_explorer_log("destination_real_tree_snapshot_refresh_skipped", reason="snapshot_still_fresh")
            return
        current_drive_id = self._current_selected_destination_drive_id() or self.pending_root_drive_ids.get("destination", "")
        snapshot = []
        tree = getattr(self, "destination_tree_widget", None)
        if tree is None:
            self._destination_real_tree_snapshot = []
            self._destination_real_tree_snapshot_stale = False
            return
        self._collect_real_destination_snapshot_entries_index(snapshot)

        full_tree_ready = (
            bool(self._destination_full_tree_snapshot)
            and self._destination_full_tree_completed_drive_id == current_drive_id
        )
        if not full_tree_ready:
            self._destination_real_tree_snapshot = snapshot
            self._destination_real_tree_snapshot_stale = False
            return

        # Merge order for in-memory digest only (not visible bind authority under Graph ownership).
        merged_by_path = {}
        for entry in self._destination_full_tree_snapshot:
            semantic_path = self.normalize_memory_path(entry.get("semantic_path", ""))
            if semantic_path:
                merged_by_path[semantic_path] = dict(entry)
        promoted_cf = getattr(self, "_destination_startup_promoted_semantic_paths", None) or set()
        visible_filled_gaps = 0
        promoted_wins = 0
        for entry in snapshot:
            semantic_path = self.normalize_memory_path(entry.get("semantic_path", ""))
            if not semantic_path:
                continue
            cf = semantic_path.casefold()
            if cf in promoted_cf:
                had = semantic_path in merged_by_path
                merged_by_path[semantic_path] = dict(entry)
                visible_filled_gaps += 1
                if had:
                    promoted_wins += 1
                continue
            if semantic_path in merged_by_path:
                continue
            merged_by_path[semantic_path] = dict(entry)
            visible_filled_gaps += 1
        if promoted_wins:
            log_info(
                "destination_authority_preserved_promoted_startup_branch",
                promoted_merge_overrides=int(promoted_wins),
                visible_gap_fill_entries=int(visible_filled_gaps),
                policy="visible_planning_row_over_full_tree_on_promoted_path",
            )

        merged_snapshot = list(merged_by_path.values())
        merged_snapshot.sort(
            key=lambda value: (
                [segment.lower() for segment in self._path_segments(value.get("semantic_path", ""))],
            ),
        )
        self._destination_real_tree_snapshot = merged_snapshot
        self._destination_real_tree_snapshot_stale = False
        self._log_restore_phase(
            "destination_real_snapshot_merged_full_tree",
            merged_total=len(merged_snapshot),
            visible_model_entries=len(snapshot),
            full_tree_entries=len(self._destination_full_tree_snapshot or []),
            visible_gap_fill_entries=visible_filled_gaps,
            reconcile_policy="live_full_tree_wins_path_collision",
        )

    def _destination_begin_full_tree_idle_snapshot_merge_chunks(
        self,
        *,
        allow_defer: bool,
        prefer_chunked_projection: bool,
        narrow_restore_real_snapshot: bool,
    ) -> None:
        """Split full-tree / visible digest merge across GUI timer slices (not one blocking wave)."""
        self._destination_full_tree_idle_merge_chunk_active = True
        current_drive_id = self._current_selected_destination_drive_id() or self.pending_root_drive_ids.get(
            "destination", ""
        )
        snapshot: list = []
        tree = getattr(self, "destination_tree_widget", None)
        if tree is None:
            self._destination_real_tree_snapshot = []
            self._destination_real_tree_snapshot_stale = False
            self._destination_full_tree_idle_merge_chunk_active = False
            self._destination_full_tree_idle_light_overlay = True
            QTimer.singleShot(
                0,
                lambda: self._safe_invoke(
                    "destination_full_tree_idle_light_overlay_empty_tree",
                    lambda: self._apply_destination_planning_overlays(
                        "destination_full_tree_idle_success",
                        allow_defer=allow_defer,
                        prefer_chunked_projection=prefer_chunked_projection,
                        narrow_restore_real_snapshot=narrow_restore_real_snapshot,
                    ),
                ),
            )
            return
        self._collect_real_destination_snapshot_entries_index(snapshot)
        full_tree_ready = (
            bool(self._destination_full_tree_snapshot)
            and self._destination_full_tree_completed_drive_id == current_drive_id
        )
        if not full_tree_ready:
            self._destination_real_tree_snapshot = snapshot
            self._destination_real_tree_snapshot_stale = False
            self._destination_full_tree_idle_merge_chunk_active = False
            self._destination_full_tree_idle_light_overlay = True
            QTimer.singleShot(
                0,
                lambda: self._safe_invoke(
                    "destination_full_tree_idle_light_overlay_no_full_walk",
                    lambda: self._apply_destination_planning_overlays(
                        "destination_full_tree_idle_success",
                        allow_defer=allow_defer,
                        prefer_chunked_projection=prefer_chunked_projection,
                        narrow_restore_real_snapshot=narrow_restore_real_snapshot,
                    ),
                ),
            )
            return

        self._destination_ft_idle_merge_state = {
            "phase": "full_tree",
            "ft_list": list(self._destination_full_tree_snapshot or []),
            "i": 0,
            "merged_by_path": {},
            "visible_list": list(snapshot),
            "gap_i": 0,
            "visible_filled_gaps": 0,
            "saved_allow_defer": bool(allow_defer),
            "saved_prefer_chunked": bool(prefer_chunked_projection),
            "saved_narrow_restore": bool(narrow_restore_real_snapshot),
        }
        log_info(
            "startup_lifecycle_temp_full_tree_idle_finalize_bypassed",
            note="broad_inline_overlay_deferred_to_chunked_digest_merge",
            full_tree_entry_count=len(self._destination_full_tree_snapshot or []),
            visible_entry_count=len(snapshot),
        )
        QTimer.singleShot(
            0,
            lambda: self._safe_invoke(
                "destination_full_tree_idle_merge_chunk_tick",
                self._destination_full_tree_idle_merge_chunk_tick,
            ),
        )

    def _destination_full_tree_idle_merge_chunk_tick(self) -> None:
        st = getattr(self, "_destination_ft_idle_merge_state", None)
        if not isinstance(st, dict):
            self._destination_full_tree_idle_merge_chunk_active = False
            return
        if self._destination_user_scroll_interaction_active():
            log_info(
                "startup_lifecycle_temp_full_tree_idle_deferred_due_to_interaction",
                detail="destination_tree_scroll_window_active",
            )
            QTimer.singleShot(
                120,
                lambda: self._safe_invoke(
                    "destination_full_tree_idle_merge_after_scroll",
                    self._destination_full_tree_idle_merge_chunk_tick,
                ),
            )
            return
        t0 = time.perf_counter()
        budget_s = float(getattr(self, "_destination_full_tree_idle_chunk_budget_s", 0.01) or 0.01)
        cap = int(getattr(self, "_destination_full_tree_idle_chunk_max_entries", 32) or 32)
        phase = str(st.get("phase") or "")
        log_info(
            "startup_lifecycle_temp_full_tree_idle_chunk_begin",
            phase=phase,
            budget_ms=round(budget_s * 1000.0, 2),
            max_entries=int(cap),
        )
        entries_processed = 0
        merged = st["merged_by_path"]
        try:
            if phase == "full_tree":
                ft = st["ft_list"]
                i = int(st.get("i", 0) or 0)
                while (
                    i < len(ft)
                    and entries_processed < cap
                    and (time.perf_counter() - t0) < budget_s
                ):
                    entry = ft[i]
                    semantic_path = self.normalize_memory_path(entry.get("semantic_path", ""))
                    if semantic_path:
                        merged[semantic_path] = dict(entry)
                    i += 1
                    entries_processed += 1
                st["i"] = i
                if i >= len(ft):
                    st["phase"] = "gap_fill"
            if str(st.get("phase") or "") == "gap_fill":
                vis = st["visible_list"]
                j = int(st.get("gap_i", 0) or 0)
                visible_filled = int(st.get("visible_filled_gaps", 0) or 0)
                promoted_cf2 = getattr(self, "_destination_startup_promoted_semantic_paths", None) or set()
                promoted_chunk_wins = 0
                while (
                    j < len(vis)
                    and entries_processed < cap
                    and (time.perf_counter() - t0) < budget_s
                ):
                    entry = vis[j]
                    semantic_path = self.normalize_memory_path(entry.get("semantic_path", ""))
                    if semantic_path:
                        cf2 = semantic_path.casefold()
                        is_pr = cf2 in promoted_cf2
                        if is_pr or semantic_path not in merged:
                            if is_pr and semantic_path in merged:
                                promoted_chunk_wins += 1
                            merged[semantic_path] = dict(entry)
                            visible_filled += 1
                    j += 1
                    entries_processed += 1
                if promoted_chunk_wins:
                    log_info(
                        "destination_authority_preserved_promoted_startup_branch",
                        promoted_merge_overrides=int(promoted_chunk_wins),
                        phase="full_tree_idle_gap_fill_chunk",
                    )
                st["gap_i"] = j
                st["visible_filled_gaps"] = visible_filled
                if j >= len(vis):
                    st["phase"] = "commit"
            if str(st.get("phase") or "") == "commit":
                merged_snapshot = list(merged.values())
                merged_snapshot.sort(
                    key=lambda value: (
                        [segment.lower() for segment in self._path_segments(value.get("semantic_path", ""))],
                    ),
                )
                self._destination_real_tree_snapshot = merged_snapshot
                self._destination_real_tree_snapshot_stale = False
                self._log_restore_phase(
                    "destination_real_snapshot_merged_full_tree",
                    merged_total=len(merged_snapshot),
                    visible_model_entries=len(st.get("visible_list") or []),
                    full_tree_entries=len(st.get("ft_list") or []),
                    visible_gap_fill_entries=int(st.get("visible_filled_gaps", 0) or 0),
                    reconcile_policy="live_full_tree_wins_path_collision",
                )
                _ad = bool(st.get("saved_allow_defer", True))
                _pc = bool(st.get("saved_prefer_chunked", True))
                _nr = bool(st.get("saved_narrow_restore", False))
                self._destination_ft_idle_merge_state = None
                self._destination_full_tree_idle_merge_chunk_active = False
                self._destination_full_tree_idle_light_overlay = True
                wall_ms = round((time.perf_counter() - t0) * 1000.0, 2)
                log_info(
                    "startup_lifecycle_temp_full_tree_idle_chunk_end",
                    phase="commit",
                    wall_ms=wall_ms,
                    entries_processed=int(entries_processed),
                )

                def _light():
                    self._apply_destination_planning_overlays(
                        "destination_full_tree_idle_success",
                        allow_defer=_ad,
                        prefer_chunked_projection=_pc,
                        narrow_restore_real_snapshot=_nr,
                    )

                QTimer.singleShot(0, lambda: self._safe_invoke("destination_full_tree_idle_light_overlay", _light))
                return
        except Exception as exc:
            self._log_restore_exception("destination_full_tree_idle_merge_chunk_tick", exc)
            self._destination_ft_idle_merge_state = None
            self._destination_full_tree_idle_merge_chunk_active = False
            return
        wall_ms = round((time.perf_counter() - t0) * 1000.0, 2)
        log_info(
            "startup_lifecycle_temp_full_tree_idle_chunk_end",
            phase=str(st.get("phase") or ""),
            wall_ms=wall_ms,
            entries_processed=int(entries_processed),
        )
        QTimer.singleShot(
            0,
            lambda: self._safe_invoke(
                "destination_full_tree_idle_merge_chunk_continue",
                self._destination_full_tree_idle_merge_chunk_tick,
            ),
        )

    def _ensure_visible_destination_root_children_in_model(self, model_nodes, *, planning_relevant_paths: set[str] | None = None):
        _ = planning_relevant_paths  # Kept for callers; all real Root children are always merged (see loop below).
        if destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            # Graph authority: visible real root children come from Graph root bind, not future-model snapshot merge.
            return 0
        dmodel = getattr(self, "destination_planning_model", None)
        if dmodel is None:
            return 0
        root_ix = None
        for r in range(dmodel.rowCount(QModelIndex())):
            ix = dmodel.index(r, 0, QModelIndex())
            pl = ix.data(Qt.UserRole) or {}
            if pl.get("placeholder"):
                continue
            if self._destination_semantic_path(pl) == "Root":
                root_ix = ix
                break
        if root_ix is None or not root_ix.isValid():
            return 0
        ensured_count = 0
        for r in range(dmodel.rowCount(root_ix)):
            cix = dmodel.index(r, 0, root_ix)
            child_data = cix.data(Qt.UserRole) or {}
            if child_data.get("placeholder") or self._destination_is_future_state_node(child_data):
                continue
            semantic_path = self._destination_semantic_path(child_data)
            if not semantic_path:
                continue
            # Always materialize every visible real Root child, even when deep snapshot import is
            # narrowed to planning-relevant paths only (startup / restore fast path).
            name = child_data.get("name") or self._path_segments(semantic_path)[-1]
            self._upsert_destination_model_node(
                model_nodes,
                semantic_path,
                name=name,
                node_state="real",
                data=dict(child_data),
                parent_semantic_path="Root",
            )
            self._attach_destination_model_child(model_nodes, "Root", semantic_path)
            ensured_count += 1
        return ensured_count

    def _collect_destination_planning_relevant_semantic_paths(self) -> set[str]:
        """Canonical destination paths (and ancestor prefixes) implied by proposed folders and planned moves."""
        out: set[str] = {"Root", ""}

        def _add_prefix_chain(mem_path: str) -> None:
            segments = self._destination_projection_segments(mem_path)
            for depth in range(1, len(segments) + 1):
                px = self.normalize_memory_path("\\".join(segments[:depth]))
                if px:
                    out.add(px)

        for pf in self.proposed_folders or []:
            dest = self._proposed_destination_path(pf)
            if not dest:
                continue
            out.add(dest)
            segs = self._path_segments(dest)
            if len(segs) > 1:
                parent_path = self.normalize_memory_path("\\".join(segs[:-1]))
                _add_prefix_chain(parent_path)
        for move in self.planned_moves or []:
            parent_path = self._allocation_parent_path(move)
            alloc_path = self._allocation_projection_path(move)
            for p in (parent_path, alloc_path):
                if not p:
                    continue
                out.add(p)
                segs = self._path_segments(p)
                if len(segs) > 1:
                    parent_only = self.normalize_memory_path("\\".join(segs[:-1]))
                    _add_prefix_chain(parent_only)
        return out

    def _is_destination_semantic_path_planning_relevant(self, semantic_path: str, relevant_paths: set[str]) -> bool:
        return self._is_destination_real_snapshot_node_planning_relevant({"semantic_path": semantic_path}, relevant_paths)

    def _is_destination_real_snapshot_node_planning_relevant(
        self, snapshot_node: dict, relevant_paths: set[str]
    ) -> bool:
        sp = self.normalize_memory_path(snapshot_node.get("semantic_path", "") or "")
        if not sp:
            return False
        sp_cf = sp.casefold()
        if sp in relevant_paths:
            return True
        for rel in relevant_paths:
            if not rel or rel == "Root":
                continue
            rel_cf = rel.casefold()
            if sp_cf == rel_cf:
                return True
            if sp_cf.startswith(rel_cf + "\\"):
                return True
        return False

    def _destination_real_snapshot_node_is_direct_root_child(self, snapshot_node: dict) -> bool:
        """True when this snapshot row is an immediate child of the destination Root folder.

        Narrow restore snapshot import skips deep non-relevant folders for startup; direct Root children
        are still required so the visible tree matches the library (e.g. IT, Marketing siblings).
        """
        parent_path = self.normalize_memory_path(str(snapshot_node.get("parent_semantic_path", "") or ""))
        return parent_path in ("", "Root")

    def _destination_root_base_data(self):
        tree = getattr(self, "destination_tree_widget", None)
        if tree is not None:
            dmodel = getattr(self, "destination_planning_model", None)
            if dmodel is not None:
                # Root should exist as the first-level row in the planning model.
                for r in range(dmodel.rowCount(QModelIndex())):
                    ix = dmodel.index(r, 0, QModelIndex())
                    node_data = ix.data(Qt.UserRole) or {}
                    if node_data.get("placeholder"):
                        continue
                    semantic_path = self._destination_semantic_path(node_data)
                    if semantic_path == "Root":
                        base_data = dict(node_data)
                        base_data.setdefault("tree_role", "destination")
                        base_data.setdefault("name", "Root")
                        base_data.setdefault("real_name", "Root")
                        base_data.setdefault("display_path", "Root")
                        base_data.setdefault("item_path", "Root")
                        base_data.setdefault("destination_path", "Root")
                        base_data.setdefault("is_folder", True)
                        return base_data
        root_data = self._build_destination_projected_node_data("Root", "Root", {})
        root_data.setdefault("tree_role", "destination")
        root_data.setdefault("name", "Root")
        root_data.setdefault("real_name", "Root")
        root_data.setdefault("display_path", "Root")
        root_data.setdefault("item_path", "Root")
        root_data.setdefault("destination_path", "Root")
        root_data.setdefault("is_folder", True)
        return root_data

    def _make_destination_model_node(self, semantic_path, name, node_state, data, parent_semantic_path=""):
        return {
            "semantic_path": semantic_path,
            "parent_semantic_path": parent_semantic_path,
            "name": name,
            "node_state": node_state,
            "data": dict(data),
            "children": [],
        }

    def _merge_real_destination_row_with_allocation_node_data(self, real_data, allocation_data):
        """Apply planned-allocation fields onto a graph snapshot row (same contract as overlay on real items)."""
        out = dict(real_data or {})
        gid = str(out.get("graph_item_id") or out.get("id") or "").strip()
        if gid:
            out["graph_item_id"] = gid
        ad = dict(allocation_data or {})
        source_name = str(ad.get("name") or out.get("name") or "Allocated Item").strip() or "Allocated Item"
        out["planned_allocation"] = True
        out["node_origin"] = "PlannedAllocation"
        out["overlay_state"] = "PlannedAllocation"
        out["source_path"] = str(ad.get("source_path", "") or "")
        for key in ("display_path", "item_path", "destination_path"):
            if ad.get(key):
                out[key] = ad[key]
        out["real_name"] = str(ad.get("real_name", source_name) or source_name)
        out["name"] = source_name
        out["base_display_label"] = self._tree_name_column_label(source_name, tag="[Allocated]")
        out["tree_role"] = "destination"
        if ad.get("drive_id"):
            out["drive_id"] = ad["drive_id"]
        for k in ("site_id", "site_name", "library_id", "library_name", "web_url"):
            if ad.get(k):
                out[k] = ad[k]
        if "is_folder" in ad:
            out["is_folder"] = bool(ad["is_folder"])
        is_folder = bool(out.get("is_folder"))
        if is_folder:
            if bool(real_data.get("children_loaded")):
                out["children_loaded"] = True
            else:
                out.setdefault("children_loaded", bool(ad.get("children_loaded", False)))
        else:
            out["children_loaded"] = True
        out["load_failed"] = bool(real_data.get("load_failed", False))
        return out

    def _coerce_destination_model_node_state(self, semantic_path, node_state, data):
        normalized_path = self.normalize_memory_path(semantic_path)
        effective_state = node_state
        effective_data = dict(data)
        if normalized_path and node_state == "real":
            proposed_folder = self._find_proposed_folder_record_by_path(normalized_path)
            if proposed_folder is not None:
                effective_state = "proposed"
                effective_data = self._build_destination_proposed_node_data(
                    proposed_folder,
                    effective_data,
                )
        return effective_state, effective_data

    def _upsert_destination_model_node(self, model_nodes, semantic_path, *, name, node_state, data, parent_semantic_path=""):
        node_state, data = self._coerce_destination_model_node_state(semantic_path, node_state, data)
        node = model_nodes.get(semantic_path)
        if node is None:
            node = self._make_destination_model_node(semantic_path, name, node_state, data, parent_semantic_path=parent_semantic_path)
            model_nodes[semantic_path] = node
        else:
            old_state = node["node_state"]
            new_pri = self._destination_model_state_priority(node_state)
            old_pri = self._destination_model_state_priority(old_state)
            if new_pri > old_pri:
                if node_state == "allocated" and old_state == "real":
                    merged = self._merge_real_destination_row_with_allocation_node_data(node["data"], data)
                    node["node_state"] = node_state
                    node["data"] = merged
                    if is_dev_mode() and bool(merged.get("is_folder")):
                        log_info(
                            "destination_nested_model_allocated_folder",
                            phase="real_row_upgraded_to_allocated_in_model",
                            semantic_path=str(semantic_path)[:200],
                            has_allocated_label="[Allocated]" in str(merged.get("base_display_label", "")),
                        )
                else:
                    node["node_state"] = node_state
                    node["data"] = dict(data)
            node["name"] = name or node["name"]
            if parent_semantic_path:
                node["parent_semantic_path"] = parent_semantic_path
        return node

    def _attach_destination_model_child(self, model_nodes, parent_semantic_path, child_semantic_path):
        if not parent_semantic_path:
            return
        parent_node = model_nodes.get(parent_semantic_path)
        child_node = model_nodes.get(child_semantic_path)
        if parent_node is None or child_node is None:
            return
        if child_semantic_path not in parent_node["children"]:
            parent_node["children"].append(child_semantic_path)
            child_node["parent_semantic_path"] = parent_semantic_path

    def _build_destination_projected_node_data(self, semantic_path, name, parent_data):
        return {
            "id": "",
            "graph_item_id": str(parent_data.get("graph_item_id") or parent_data.get("id") or "").strip(),
            "overlay_node_id": new_overlay_node_id("projection", semantic_path),
            "name": name,
            "real_name": name,
            "display_path": semantic_path,
            "item_path": semantic_path,
            "destination_path": semantic_path,
            "tree_role": "destination",
            "drive_id": parent_data.get("drive_id", ""),
            "site_id": parent_data.get("site_id", ""),
            "site_name": parent_data.get("site_name", ""),
            "library_id": parent_data.get("library_id", ""),
            "library_name": parent_data.get("library_name", ""),
            "is_folder": True,
            "children_loaded": True,
            "load_failed": False,
            "node_origin": "ProjectedDestination",
            "overlay_state": "ProjectedDestination",
            "projected": True,
            "web_url": parent_data.get("web_url", ""),
            **overlay_row_marker("projection"),
        }

    def _build_destination_proposed_node_data(self, proposed_folder, parent_data):
        destination_path = (
            self._proposed_destination_path(proposed_folder)
            if isinstance(proposed_folder, ProposedFolder)
            else self._canonical_destination_projection_path(getattr(proposed_folder, "DestinationPath", "") or "")
        )
        dest_id = (
            str(proposed_folder.DestinationId).strip()
            if isinstance(proposed_folder, ProposedFolder)
            else str(getattr(proposed_folder, "DestinationId", "") or "").strip()
        )
        gid = graph_item_id_field(dest_id)
        return {
            "id": gid,
            "graph_item_id": gid,
            "overlay_node_id": new_overlay_node_id("proposed", destination_path),
            "name": proposed_folder.FolderName,
            "real_name": proposed_folder.FolderName,
            "display_path": destination_path,
            "item_path": destination_path,
            "destination_path": destination_path,
            "tree_role": "destination",
            "drive_id": parent_data.get("drive_id", ""),
            "site_id": parent_data.get("site_id", ""),
            "site_name": parent_data.get("site_name", ""),
            "library_id": parent_data.get("library_id", ""),
            "library_name": parent_data.get("library_name", ""),
            "is_folder": True,
            "children_loaded": True,
            "load_failed": False,
            "node_origin": "Proposed",
            "proposed": True,
            "web_url": parent_data.get("web_url", ""),
            **overlay_row_marker("proposed"),
        }

    def _build_destination_allocation_node_data(self, move, parent_data):
        source_node = move.get("source", {})
        source_name = self._move_target_name(move) or source_node.get("name", "Allocated Item")
        destination_path = self._canonical_destination_projection_path(self._allocation_projection_path(move))
        is_folder = not self._planned_move_terminal_is_file_leaf(move)
        base_label = self._tree_name_column_label(source_name, tag="[Allocated]")
        return {
            "row_kind": "planned_folder" if is_folder else "planned_file",
            "id": "",
            "graph_item_id": "",
            "overlay_node_id": new_overlay_node_id("allocation", destination_path),
            "name": source_name,
            "real_name": source_name,
            "display_path": destination_path,
            "item_path": destination_path,
            "destination_path": destination_path,
            "source_path": move.get("source_path", ""),
            "tree_role": "destination",
            "drive_id": parent_data.get("drive_id", ""),
            "site_id": parent_data.get("site_id", ""),
            "site_name": parent_data.get("site_name", ""),
            "library_id": parent_data.get("library_id", ""),
            "library_name": parent_data.get("library_name", ""),
            "is_folder": is_folder,
            "children_loaded": not is_folder,
            "load_failed": False,
            "node_origin": "PlannedAllocation",
            "overlay_state": "PlannedAllocation",
            "planned_allocation": True,
            "web_url": parent_data.get("web_url", ""),
            "base_display_label": base_label,
            **overlay_row_marker("allocation"),
        }

    def _build_destination_allocation_descendant_node_data(self, source_node_data, destination_semantic_path, parent_data):
        desc_is_folder = not self._source_tree_payload_implies_file_leaf(source_node_data)
        return {
            "row_kind": "planned_folder" if desc_is_folder else "planned_file",
            "id": "",
            "graph_item_id": "",
            "overlay_node_id": new_overlay_node_id("allocated_descendant", destination_semantic_path),
            "name": source_node_data.get("name", ""),
            "real_name": source_node_data.get("real_name", source_node_data.get("name", "")),
            "display_path": destination_semantic_path,
            "item_path": destination_semantic_path,
            "destination_path": destination_semantic_path,
            "source_path": self._tree_item_path(source_node_data),
            "tree_role": "destination",
            "drive_id": parent_data.get("drive_id", ""),
            "site_id": parent_data.get("site_id", ""),
            "site_name": parent_data.get("site_name", ""),
            "library_id": parent_data.get("library_id", ""),
            "library_name": parent_data.get("library_name", ""),
            "is_folder": desc_is_folder,
            # Descendant projection materializes the full nested subtree in one pass,
            # so projected descendant folders must not lazy-expand themselves again.
            "children_loaded": True,
            "load_failed": False,
            "node_origin": "ProjectedAllocationDescendant",
            "overlay_state": "PlannedAllocationDescendant",
            "planned_allocation_descendant": True,
            "web_url": parent_data.get("web_url", ""),
            **overlay_row_marker("projection"),
        }

    def _destination_preview_descendant_exists(self, model_nodes, semantic_path):
        existing = model_nodes.get(semantic_path)
        return existing is not None

    def _find_exact_planned_move_for_source_path(self, source_path):
        canonical_source_path = self._canonical_source_projection_path(source_path)
        if not canonical_source_path:
            return None
        signature = (
            int(getattr(self, "_planning_cache_generation", 0) or 0),
            id(self.planned_moves),
            len(self.planned_moves),
        )
        if signature != getattr(self, "_planned_move_by_source_path_cache_signature", None):
            lookup = {}
            for move in self.planned_moves:
                move_source_path = self._canonical_source_projection_path(move.get("source_path", ""))
                if move_source_path and move_source_path not in lookup:
                    lookup[move_source_path] = move
            self._planned_move_by_source_path_cache = lookup
            self._planned_move_by_source_path_cache_signature = signature
        return (getattr(self, "_planned_move_by_source_path_cache", {}) or {}).get(canonical_source_path)

    def _find_inherited_planned_move_for_source_path_raw(self, canonical_source_path):
        """Nearest ancestor folder move for a source path, ignoring leaf exclusions."""
        return find_inherited_planned_move_for_source_path_raw(
            canonical_source_path,
            self.planned_moves,
            lambda m: self._canonical_source_projection_path(m.get("source_path", "")),
            lambda c, p: self._path_is_descendant(c, p, "source"),
        )

    def _find_inherited_planned_move_for_source_path(self, source_path):
        canonical_source_path = self._canonical_source_projection_path(source_path)
        inherited = self._find_inherited_planned_move_for_source_path_raw(canonical_source_path)
        if inherited is None:
            return None
        if self._is_leaf_path_excluded_for_plan(canonical_source_path):
            return None
        return inherited

    def _is_leaf_path_excluded_for_plan(self, canonical_source_path):
        if not canonical_source_path:
            return False
        return canonical_source_path in getattr(self, "_plan_leaf_exclusions", set())

    def _plan_leaf_exclusion_display_active(self, panel_key, node_data):
        """True when this row is a file whose canonical source path is in PlanLeafExclusions."""
        if not node_data or node_data.get("is_folder") is not False:
            return False
        if panel_key == "source":
            canon = self._canonical_source_projection_path(self._tree_item_path(node_data))
        else:
            canon = self._canonical_source_projection_path(node_data.get("source_path", ""))
        return bool(canon and self._is_leaf_path_excluded_for_plan(canon))

    def _sync_destination_plan_leaf_exclusion_paint_contract(self) -> None:
        """Keep DESTINATION_PLAN_LEAF_EXCLUSION_PAINT_ROLE aligned with PlanLeafExclusions (cheap scroll probe)."""
        m = getattr(self, "destination_planning_model", None)
        if m is None:
            return
        excl = getattr(self, "_plan_leaf_exclusions", None) or set()
        if not excl:
            m.set_plan_leaf_exclusion_paint_contract(None, None)
        else:
            m.set_plan_leaf_exclusion_paint_contract(frozenset(excl), self._canonical_source_projection_path)

    def _mark_destination_indicators_for_leaf_planning_change(self, *, removed_direct_move=None, inherited_move=None):
        """Partial destination indicator refresh (avoids full destination materialization)."""
        paths: list[str] = []
        if removed_direct_move:
            dp = str(removed_direct_move.get("destination_path") or "").strip()
            if dp:
                paths.append(dp)
        if inherited_move:
            dp = str(inherited_move.get("destination_path") or "").strip()
            if dp:
                paths.append(dp)
        if paths:
            self._mark_destination_indicator_dirty_paths(paths)
            self._schedule_refresh_destination_tree_indicators(delay_ms=30)

    def _destination_file_key_for_execution_validation(self, move):
        """Canonical destination file path for a planned move (None for folder moves)."""
        if not isinstance(move, dict):
            return None
        src = move.get("source") or {}
        if bool(src.get("is_folder", False)):
            return None
        proj = self._allocation_projection_path(move)
        if not proj:
            return None
        return self._canonical_destination_projection_path(proj) or self.normalize_memory_path(proj)

    def _planning_blocked_duplicate_destination_message(
        self,
        candidate_move: dict,
        *,
        exclude_planned_index: int | None = None,
        extra_moves: list | None = None,
    ) -> str | None:
        """
        If a file move would use the same execution destination key as another file move
        (different source), return a user-facing warning message; else None.
        Folder moves are ignored (no file key). Aligns with _destination_file_key_for_execution_validation.
        """
        if not isinstance(candidate_move, dict):
            return None
        dest_key = self._destination_file_key_for_execution_validation(candidate_move)
        if not dest_key:
            return None
        nk = norm_execution_key(dest_key)
        cand_src = self._canonical_source_projection_path(candidate_move.get("source_path", ""))
        cand_disp = str(candidate_move.get("source_path", "") or "").strip() or cand_src or "(unknown)"

        def _conflicts_with(other: dict) -> bool:
            if not isinstance(other, dict):
                return False
            ok = self._destination_file_key_for_execution_validation(other)
            if not ok or norm_execution_key(ok) != nk:
                return False
            other_src = self._canonical_source_projection_path(other.get("source_path", ""))
            if cand_src and other_src and norm_execution_key(cand_src) == norm_execution_key(other_src):
                return False
            return True

        other_move: dict | None = None
        for i, m in enumerate(self.planned_moves or []):
            if exclude_planned_index is not None and i == exclude_planned_index:
                continue
            if _conflicts_with(m):
                other_move = m
                break
        if other_move is None:
            for m in extra_moves or []:
                if _conflicts_with(m):
                    other_move = m
                    break
        if other_move is None:
            return None

        dest_parent = str(candidate_move.get("destination_path", "") or "").strip()
        file_name = str(self._move_target_name(candidate_move) or "").strip()
        dest_line = f"{dest_parent}\\{file_name}" if dest_parent and file_name else dest_key
        other_disp = str(other_move.get("source_path", "") or "").strip() or (
            self._canonical_source_projection_path(other_move.get("source_path", "")) or "(unknown)"
        )
        return (
            f"Duplicate destination detected: {dest_line}\n\n"
            f"Source A: {cand_disp}\n"
            f"Source B: {other_disp}\n\n"
            "Please change destination or rename."
        )

    def _compute_graph_unsafe_folder_step_indices(self) -> list[int]:
        """Indices of planned folder moves that must not run as a single Microsoft Graph folder copy."""
        excl_raw = getattr(self, "_plan_leaf_exclusions", set()) or set()
        excl = {
            self._canonical_source_projection_path(str(x))
            for x in excl_raw
            if str(x).strip()
        }
        return compute_graph_unsafe_folder_step_indices(
            list(self.planned_moves or []),
            excl,
            canonical_source=lambda m: self._canonical_source_projection_path(m.get("source_path", "")),
            path_is_descendant=lambda c, p: self._path_is_descendant(c, p, "source"),
            allocation_projection_path=self._allocation_projection_path,
            normalize_memory_path=self.normalize_memory_path,
            canonical_destination_projection_path=self._canonical_destination_projection_path,
            paths_equivalent=lambda a, b, role: self._paths_equivalent(a, b, role),
        )

    def _compute_graph_expanded_transfer_steps_json(self) -> list[dict] | None:
        """Graph execution expansion from current plan; None = omit (runner uses block/fallback)."""
        unsafe = self._compute_graph_unsafe_folder_step_indices()
        if not unsafe:
            return None
        excl_raw = getattr(self, "_plan_leaf_exclusions", set()) or set()
        excl = {
            self._canonical_source_projection_path(str(x))
            for x in excl_raw
            if str(x).strip()
        }
        try:
            expanded = expand_graph_transfer_steps(
                list(self.planned_moves or []),
                excl,
                canonical_source=lambda m: self._canonical_source_projection_path(m.get("source_path", "")),
                path_is_descendant=lambda c, p: self._path_is_descendant(c, p, "source"),
                allocation_projection_path=self._allocation_projection_path,
                normalize_memory_path=self.normalize_memory_path,
                canonical_destination_projection_path=self._canonical_destination_projection_path,
                paths_equivalent=lambda a, b, role: self._paths_equivalent(a, b, role),
            )
        except ValueError as exc:
            log_warn("graph_expansion_duplicate_internal", error=str(exc))
            return None
        rows = expanded_graph_steps_to_transfer_step_json_dicts(list(self.planned_moves or []), expanded)
        ds, dd = duplicate_collision_report_from_transfer_steps(rows)
        if ds or dd:
            log_warn(
                "graph_expansion_manifest_duplicate_collision",
                duplicate_sources=ds,
                duplicate_destinations=dd,
            )
            return None
        return rows

    def _planned_moves_duplicate_validation_error(self, moves) -> str:
        ds, dd = duplicate_collision_report_from_moves(
            list(moves or []),
            canonical_source=lambda m: self._canonical_source_projection_path(m.get("source_path", "")),
            destination_file_key=self._destination_file_key_for_execution_validation,
        )
        return format_execution_duplicate_message(ds, dd)

    def _remove_planned_move_at_index(self, move_index: int) -> bool:
        """Remove one planned move by ``planned_moves`` list index (same side effects as unassign/remove allocation)."""
        n = len(self.planned_moves or [])
        if move_index < 0 or move_index >= n:
            return False
        move = self.planned_moves[move_index]
        if self._is_move_submitted(move):
            self._show_submitted_item_locked_message(
                "Remove from plan",
                f"'{move.get('source_name', 'This item')}'",
                self._submitted_batch_id_for_move(move),
            )
            return False
        removed_visually = self._quick_remove_planned_move_from_destination_tree(move) > 0
        self.planned_moves.pop(move_index)
        self._reset_unresolved_allocation_queue()
        self.refresh_planned_moves_table()
        self.planned_moves_status.setText("Planned move removed.")
        if not removed_visually:
            self._schedule_deferred_destination_materialization("remove_allocation_tree_reconcile", delay_ms=220)
        self._persist_planning_change(
            "planned_allocation_removed",
            source_projection_paths=self._narrow_source_projection_paths_for_move(move),
        )
        return True

    def _duplicate_review_leaf_base_ext(self, leaf: str) -> tuple[str, str]:
        leaf = str(leaf or "").strip()
        if not leaf:
            return "", ""
        dot = leaf.rfind(".")
        if dot > 0:
            return leaf[:dot], leaf[dot:]
        return leaf, ""

    def _duplicate_review_sanitize_leaf_segment(self, raw: str) -> str:
        s = str(raw or "").strip()
        out = []
        for ch in s:
            if ch in '<>:"/\\|?*' or ord(ch) < 32:
                out.append("_")
            else:
                out.append(ch)
        t = "".join(out).strip(" .")
        return t or "source"

    def _duplicate_review_source_parent_folder_label(self, source_path: str) -> str:
        p = str(source_path or "").replace("/", "\\").strip("\\")
        parts = [x for x in p.split("\\") if x]
        if len(parts) >= 2:
            return self._duplicate_review_sanitize_leaf_segment(parts[-2])
        if len(parts) == 1:
            return self._duplicate_review_sanitize_leaf_segment(parts[-1])
        return "source"

    def _duplicate_review_try_assign_leaf(self, move: dict, leaf: str, used_nk: set[str]) -> str | None:
        trial = dict(move)
        trial["target_name"] = leaf
        dk = self._destination_file_key_for_execution_validation(trial)
        if not dk:
            return None
        nk = norm_execution_key(dk)
        if nk in used_nk:
            return None
        used_nk.add(nk)
        return leaf

    def _duplicate_review_allocate_unique_leaf(self, move: dict, stem: str, ext: str, used_nk: set[str]) -> str | None:
        n = None
        for _ in range(500):
            if n is None:
                leaf = f"{stem}{ext}"
            else:
                leaf = f"{stem} ({n}){ext}"
            got = self._duplicate_review_try_assign_leaf(move, leaf, used_nk)
            if got is not None:
                return got
            n = 2 if n is None else n + 1
        return None

    def _build_duplicate_group_unique_name_preview_rows(
        self, group_indices: list[int], *, moves_for_context: list[dict] | None = None
    ) -> list[dict] | None:
        """Preview-only: proposed unique target_name values; does not mutate planned_moves.

        When ``moves_for_context`` is set, suggestions use that list for occupancy (e.g. chained bulk preview)
        without changing ``self.planned_moves``.
        """
        moves = list(moves_for_context if moves_for_context is not None else (self.planned_moves or []))
        ntot = len(moves)
        idxs = sorted({int(i) for i in group_indices if int(i) >= 0})
        if len(idxs) < 2:
            return None
        if any(i >= ntot for i in idxs):
            return None
        group_set = set(idxs)
        used_nk: set[str] = set()
        for j, m in enumerate(moves):
            if j in group_set:
                continue
            dk = self._destination_file_key_for_execution_validation(m)
            if dk:
                used_nk.add(norm_execution_key(dk))

        shared_base, shared_ext = self._duplicate_review_leaf_base_ext(self._move_target_name(moves[idxs[0]]))
        out: list[dict] = []
        for rank, idx in enumerate(idxs):
            move = moves[idx]
            if bool((move.get("source") or {}).get("is_folder")):
                return None
            cur = str(self._move_target_name(move) or "").strip()
            suggested: str | None
            if rank == 0:
                suggested = self._duplicate_review_try_assign_leaf(move, cur, used_nk)
                if suggested is None:
                    parent_lbl = self._duplicate_review_source_parent_folder_label(move.get("source_path", ""))
                    stem = f"{shared_base} - {parent_lbl}" if shared_base else parent_lbl
                    suggested = self._duplicate_review_allocate_unique_leaf(move, stem, shared_ext, used_nk)
            else:
                parent_lbl = self._duplicate_review_source_parent_folder_label(move.get("source_path", ""))
                stem = f"{shared_base} - {parent_lbl}" if shared_base else parent_lbl
                suggested = self._duplicate_review_allocate_unique_leaf(move, stem, shared_ext, used_nk)
            if not suggested:
                return None
            out.append(
                {
                    "index": idx,
                    "source_path": str(move.get("source_path", "") or "").strip(),
                    "current_leaf": cur,
                    "suggested_leaf": suggested,
                }
            )
        return out

    def _validate_duplicate_group_apply_preview_rows(self, rows: list[dict]) -> str | None:
        """All-or-none: return user-facing error message, or None if rows can be applied as-is."""
        if not rows:
            return "No suggested name rows to apply."
        moves = list(self.planned_moves or [])
        n = len(moves)
        by_idx: dict[int, str] = {}
        for r in rows:
            try:
                idx = int(r["index"])
            except (KeyError, TypeError, ValueError):
                return "Could not read planned move indices for this suggestion set."
            by_idx[idx] = str(r.get("suggested_leaf", "") or "").strip()
        for idx, leaf in by_idx.items():
            if idx < 0 or idx >= n:
                return "__stale_plan__"
            if not leaf:
                return "A suggested file name is empty; cannot apply."
            move = moves[idx]
            if bool((move.get("source") or {}).get("is_folder")):
                return "This group includes a folder move; cannot apply suggested file names."
        nk_to_index: dict[str, int] = {}
        for j, move in enumerate(moves):
            trial = dict(move)
            if j in by_idx:
                trial["target_name"] = by_idx[j]
            dk = self._destination_file_key_for_execution_validation(trial)
            if not dk:
                return (
                    "Applying these names would leave at least one planned move without a resolvable "
                    "destination file path. The plan was not changed."
                )
            nk = norm_execution_key(dk)
            if nk in nk_to_index:
                return (
                    "Applying these names would still produce a duplicate destination file in your plan. "
                    "The plan was not changed."
                )
            nk_to_index[nk] = j
        return None

    def _validate_duplicate_bulk_apply_preview_rows(self, rows: list[dict]) -> str | None:
        """All-or-none for bulk unique-name apply; duplicate index entries are rejected."""
        if not rows:
            return "No suggested name rows to apply."
        seen: set[int] = set()
        for r in rows:
            try:
                idx = int(r["index"])
            except (KeyError, TypeError, ValueError):
                return "Could not read planned move indices for this suggestion set."
            if idx in seen:
                return "Invalid bulk suggestion set (duplicate planned move index)."
            seen.add(idx)
        return self._validate_duplicate_group_apply_preview_rows(rows)

    def _duplicate_apply_structured_failure(
        self, rows: list[dict], v_err: str | None, *, bulk: bool
    ) -> dict[str, Any]:
        """Map validator/user messages to a stable reason code for inline UX (no validation logic change)."""
        affected: list[int] = []
        leaves: dict[int, str] = {}
        for r in rows or []:
            try:
                ix = int(r["index"])
            except (KeyError, TypeError, ValueError):
                continue
            affected.append(ix)
            leaves[ix] = str(r.get("suggested_leaf", "") or "").strip()
        msg = str(v_err or "").strip() or "Auto-fix could not be applied."
        reason = "unknown"
        ml = msg.lower()
        if v_err == "__stale_plan__" or "plan changed" in ml:
            reason = "stale_plan"
        elif "no renames" in ml or "no suggested name" in ml:
            reason = "no_rows"
        elif "could not read planned move indices" in msg:
            reason = "bad_indices"
        elif "empty" in ml and "name" in ml:
            reason = "invalid_name"
        elif "folder move" in ml:
            reason = "folder_conflict"
        elif "resolvable" in ml or "destination file path" in ml:
            reason = "destination_unresolved"
        elif "still produce a duplicate" in ml:
            reason = "destination_conflict"
        elif "duplicate planned move index" in ml:
            reason = "bulk_invalid"
        fix_hints = {
            "stale_plan": "The draft changed. Close this dialog and retry the run, or refresh the plan and open the inspector again.",
            "no_rows": "Nothing to apply. Rebuild suggestions from the Planning Workspace or Review & Fix tab.",
            "bad_indices": "Suggestion data no longer matches the plan. Refresh and try again.",
            "invalid_name": "One or more suggested file names are empty. Rename manually or use Retarget.",
            "folder_conflict": "This group includes a folder mapping — use Retarget or Remove on those rows, or the duplicate hub.",
            "destination_unresolved": "A destination path cannot be resolved. Retarget the row to a valid folder or fix the allocation.",
            "destination_conflict": "These names still collide with another planned file. Use Retarget, Remove, or rename manually.",
            "bulk_invalid": "Internal suggestion set was inconsistent. Try Auto-fix group again.",
            "unknown": "Adjust the highlighted rows manually, then retry auto-fix or continue with Rename / Retarget / Remove.",
        }
        return {
            "reason": reason,
            "message": msg,
            "affected_indices": affected,
            "suggested_leaf_by_index": leaves,
            "bulk": bool(bulk),
            "suggested_fix": fix_hints.get(reason, fix_hints["unknown"]),
        }

    def _dup_insp_inline_failure_headline_detail(
        self, failure_struct: dict, *, planned_row_index: int
    ) -> tuple[str, str, str]:
        """Short, action-oriented copy for duplicate inspector inline blocks (presentation only)."""
        code = str(failure_struct.get("reason") or "unknown")
        leaves = dict(failure_struct.get("suggested_leaf_by_index") or {})
        suggested_name = str(leaves.get(int(planned_row_index), "") or "").strip()
        rows: dict[str, tuple[str, str]] = {
            "destination_conflict": (
                "Name conflict",
                "A file with this name already exists at the destination.",
            ),
            "destination_unresolved": (
                "Destination not available",
                "Choose a valid destination folder or fix the allocation.",
            ),
            "folder_conflict": (
                "Folder mapping conflict",
                "Use Retarget or Remove on folder rows, or open duplicate review.",
            ),
            "invalid_name": (
                "Invalid file name",
                "Enter a valid destination file name.",
            ),
            "stale_plan": (
                "Plan changed",
                "Refresh from the workspace and try again.",
            ),
            "no_rows": (
                "No suggested name",
                "Use Rename, Retarget, or Remove.",
            ),
            "bad_indices": (
                "Plan out of date",
                "Refresh and try again.",
            ),
            "bulk_invalid": (
                "Could not apply names",
                "Try Auto-fix again or fix rows manually.",
            ),
            "submitted_locked": (
                "Submitted (locked)",
                "This mapping can't be edited here.",
            ),
            "unknown": (
                "Can't auto-fix",
                "Use Retarget or Remove, or open duplicate review.",
            ),
        }
        headline, sentence = rows.get(code, rows["unknown"])
        return headline, sentence, suggested_name

    @staticmethod
    def _dup_insp_inline_rename_button_label(suggested_name: str, *, max_chars: int = 40) -> str:
        if not str(suggested_name or "").strip():
            return "Rename…"
        sn = str(suggested_name).strip()
        if len(sn) > max_chars:
            sn = sn[: max_chars - 1] + "…"
        return f'Rename to "{sn}"'

    def _dup_insp_inline_action_priorities(
        self, reason: str
    ) -> tuple[list[str], str, str, str]:
        """Duplicate-inspector inline failure: button order (left→right) and dupPrimary/dupTertiary roles."""
        code = str(reason or "unknown")
        default_order = ["rename", "retarget", "remove"]
        if code == "destination_unresolved":
            return (
                ["retarget", "rename", "remove"],
                "secondary",
                "primary",
                "tertiary",
            )
        if code == "invalid_name":
            return (
                default_order,
                "primary",
                "hidden",
                "hidden",
            )
        if code == "destination_conflict":
            return (
                default_order,
                "primary",
                "secondary",
                "tertiary",
            )
        return (
            default_order,
            "primary",
            "secondary",
            "tertiary",
        )

    def _build_all_duplicate_groups_unique_name_preview_rows(self) -> list[dict] | None:
        """Preview rows for every duplicate destination file group; chains naming across groups via a scratch plan."""
        moves_live = list(self.planned_moves or [])
        grouped = grouped_duplicate_destination_moves(
            moves_live,
            destination_file_key=self._destination_file_key_for_execution_validation,
        )
        if not grouped:
            return None
        working: list[dict] = []
        for m in moves_live:
            working.append(dict(m) if isinstance(m, dict) else {})
        out: list[dict] = []
        for _nk, members in sorted(
            grouped.items(),
            key=lambda kv: (str(kv[1][0].get("destination", "") or "").lower(), kv[0]),
        ):
            indices = sorted({int(r["index"]) for r in members if int(r.get("index", -1)) >= 0})
            if len(indices) < 2:
                continue
            sub = self._build_duplicate_group_unique_name_preview_rows(indices, moves_for_context=working)
            if sub is None:
                return None
            dest_lbl = str(members[0].get("destination", "") or "").strip() or "(unknown)"
            for row in sub:
                out.append({**row, "group_destination": dest_lbl})
            for row in sub:
                ix = int(row["index"])
                if 0 <= ix < len(working):
                    working[ix]["target_name"] = str(row.get("suggested_leaf", "") or "").strip()
        return out or None

    def _planning_bulk_apply_duplicate_suggested_names(
        self, *, parent: QWidget, quiet_success: bool = False
    ) -> Literal["applied", "applied_no_dupes_left", "cancelled", "failed", "stale"]:
        """One-click apply: all auto-suggested unique destination file names across duplicate groups.

        Same planning-only semantics as the duplicate review dialog's bulk apply. Shows message boxes
        for errors, stale plan, and confirmation. When ``quiet_success`` is True, skips success info popups
        (for use from the review dialog preview).
        """
        grouped = grouped_duplicate_destination_moves(
            list(self.planned_moves or []),
            destination_file_key=self._destination_file_key_for_execution_validation,
        )
        if not grouped:
            QMessageBox.information(
                parent,
                "Duplicate destination files",
                "No duplicate destination files found.",
            )
            return "failed"
        fresh = self._build_all_duplicate_groups_unique_name_preview_rows()
        if fresh is None:
            QMessageBox.warning(
                parent,
                "Apply suggested names",
                "Could not build suggestions for all duplicate groups (invalid rows, folder moves, or could not find unique names).",
            )
            return "failed"
        v_err = self._validate_duplicate_bulk_apply_preview_rows(fresh)
        if v_err == "__stale_plan__":
            QMessageBox.warning(parent, "Apply suggested names", "The plan changed; refresh duplicate groups and try again.")
            return "stale"
        if v_err:
            QMessageBox.warning(parent, "Apply suggested names", v_err)
            return "failed"
        for r in fresh:
            move = self.planned_moves[int(r["index"])]
            if self._is_move_submitted(move):
                self._show_submitted_item_locked_message(
                    "Apply suggested names",
                    f"'{move.get('source_name', 'This item')}'",
                    self._submitted_batch_id_for_move(move),
                )
                return "failed"

        n_apply = len(fresh)
        if (
            QMessageBox.question(
                parent,
                "Apply suggested names",
                f"Apply all {n_apply} suggested unique names across every duplicate destination group?\n\n"
                "• Planned destination file names in your plan will change.\n"
                "• This is a planning change only.\n"
                "• It does not rename source files.\n"
                "• It does not rename existing SharePoint content.\n",
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.No,
            )
            != QMessageBox.Yes
        ):
            return "cancelled"

        fresh2 = self._build_all_duplicate_groups_unique_name_preview_rows()
        if fresh2 is None:
            QMessageBox.warning(
                parent,
                "Apply suggested names",
                "Could not rebuild suggestions before apply. The plan may have changed.",
            )
            return "failed"
        v_err2 = self._validate_duplicate_bulk_apply_preview_rows(fresh2)
        if v_err2 == "__stale_plan__":
            QMessageBox.warning(
                parent,
                "Apply suggested names",
                "The plan changed before apply; refresh duplicate groups and try again.",
            )
            return "stale"
        if v_err2:
            QMessageBox.warning(parent, "Apply suggested names", v_err2)
            return "failed"
        for r in fresh2:
            move = self.planned_moves[int(r["index"])]
            if self._is_move_submitted(move):
                self._show_submitted_item_locked_message(
                    "Apply suggested names",
                    f"'{move.get('source_name', 'This item')}'",
                    self._submitted_batch_id_for_move(move),
                )
                return "failed"

        for r in fresh2:
            idx = int(r["index"])
            self.planned_moves[idx]["target_name"] = str(r.get("suggested_leaf", "") or "").strip()
        self.planned_moves_status.setText("Applied suggested planned destination file names (all duplicate groups).")
        self.refresh_planned_moves_table()
        self._persist_planning_change("duplicate_bulk_unique_names_applied")
        still = grouped_duplicate_destination_moves(
            list(self.planned_moves or []),
            destination_file_key=self._destination_file_key_for_execution_validation,
        )
        if not still:
            if not quiet_success:
                QMessageBox.information(
                    parent,
                    "Duplicates resolved",
                    "Suggested names were applied. No duplicate destination files remain in this plan.",
                )
            return "applied_no_dupes_left"
        if not quiet_success:
            QMessageBox.information(
                parent,
                "Suggested names applied",
                "Suggested names were applied. Some duplicate destination files may still need review—open Duplicate hub for details.",
            )
        return "applied"

    def _build_execution_inspector_dest_suffix_preview_rows_for_moves(
        self,
        pr_sorted: list[int],
        *,
        moves_for_context: list[dict] | None = None,
    ) -> list[dict] | None:
        """Execution-inspector naming: first row keeps stem.ext priority, then stem (2).ext, stem (3).ext, …

        Uniqueness uses the same destination-key rules as duplicate validation, seeded with every planned
        move outside the group (or outside the group in ``moves_for_context`` when chaining).
        """
        moves = list(moves_for_context if moves_for_context is not None else (self.planned_moves or []))
        return build_execution_inspector_dest_suffix_preview_rows_for_moves(
            moves,
            pr_sorted,
            destination_file_key=self._destination_file_key_for_execution_validation,
            move_target_name=lambda m: str(self._move_target_name(m) or "").strip(),
            leaf_base_ext=self._duplicate_review_leaf_base_ext,
        )

    def _build_execution_inspector_chained_dest_suffix_preview_rows(
        self, group_pr_lists: list[list[int]]
    ) -> list[dict] | None:
        """Suffix-based suggestions for every duplicate-destination group, chained like bulk duplicate apply."""
        moves_live = list(self.planned_moves or [])
        return build_execution_inspector_chained_dest_suffix_preview_rows(
            moves_live,
            group_pr_lists,
            destination_file_key=self._destination_file_key_for_execution_validation,
            move_target_name=lambda m: str(self._move_target_name(m) or "").strip(),
            leaf_base_ext=self._duplicate_review_leaf_base_ext,
        )

    def _planning_apply_duplicate_preview_rows(
        self,
        rows: list[dict],
        parent: QWidget,
        *,
        change_note: str,
        suppress_submitted_lock_modal: bool = False,
    ) -> tuple[bool, str | None, dict | None]:
        """Apply suggested_leaf values after the same validation used by duplicate hub bulk apply.

        Returns ``(ok, err_message, structured_failure)`` where ``structured_failure`` is set for
        validation failures (for inline inspector UX). When ``suppress_submitted_lock_modal`` is True
        (duplicate inspector only), submitted-lock returns a structured payload instead of a modal.
        """
        bulk = len(rows) > 1
        if not rows:
            st = self._duplicate_apply_structured_failure([], "No renames to apply.", bulk=False)
            st["reason"] = "no_rows"
            return False, "No renames to apply.", st
        if len(rows) == 1:
            v_err = self._validate_duplicate_group_apply_preview_rows(rows)
        else:
            v_err = self._validate_duplicate_bulk_apply_preview_rows(rows)
        if v_err == "__stale_plan__":
            st = self._duplicate_apply_structured_failure(rows, v_err, bulk=bulk)
            return False, "The plan changed; refresh and try again.", st
        if v_err:
            st = self._duplicate_apply_structured_failure(rows, v_err, bulk=bulk)
            return False, v_err, st
        for r in rows:
            try:
                idx = int(r["index"])
            except (KeyError, TypeError, ValueError):
                st = self._duplicate_apply_structured_failure(
                    rows, "Invalid suggestion row.", bulk=bulk
                )
                st["reason"] = "bad_indices"
                return False, "Invalid suggestion row.", st
            if idx < 0 or idx >= len(self.planned_moves or []):
                st = self._duplicate_apply_structured_failure(rows, "__stale_plan__", bulk=bulk)
                return False, "The plan changed; refresh and try again.", st
            move = self.planned_moves[idx]
            if self._is_move_submitted(move):
                if suppress_submitted_lock_modal:
                    batch = self._submitted_batch_id_for_move(move)
                    lock_msg = (
                        f"This item has already been submitted and is locked."
                        + (f" Submitted batch: {batch}." if batch else "")
                    )
                    st_lock = self._duplicate_apply_structured_failure(
                        [{"index": idx, "suggested_leaf": str(r.get("suggested_leaf", "") or "")}],
                        lock_msg,
                        bulk=bulk,
                    )
                    st_lock["reason"] = "submitted_locked"
                    return False, "locked", st_lock
                self._show_submitted_item_locked_message(
                    "Apply suggested names",
                    f"'{move.get('source_name', 'This item')}'",
                    self._submitted_batch_id_for_move(move),
                )
                return False, "locked", None
        for r in rows:
            idx = int(r["index"])
            self.planned_moves[idx]["target_name"] = str(r.get("suggested_leaf", "") or "").strip()
        if hasattr(self, "planned_moves_status"):
            n = len(rows)
            self.planned_moves_status.setText(
                f"Applied {n} suggested planned destination file name(s)."
                if n > 1
                else "Applied suggested planned destination file name."
            )
        self.refresh_planned_moves_table()
        self._persist_planning_change(change_note)
        return True, None, None

    def _show_duplicate_destination_file_review_dialog(
        self, *, launched_from_execution_duplicate_inspector: bool = False
    ) -> None:
        grouped = grouped_duplicate_destination_moves(
            list(self.planned_moves or []),
            destination_file_key=self._destination_file_key_for_execution_validation,
        )
        if not grouped:
            if launched_from_execution_duplicate_inspector:
                QMessageBox.information(
                    self,
                    "Duplicate destination files",
                    "No multi-file duplicate groups in the draft plan.\n\n"
                    "Use this inspector to resolve execution collisions.",
                )
            else:
                QMessageBox.information(
                    self,
                    "Duplicate destination files",
                    "No duplicate destination files found.",
                )
            return
        dlg = QDialog(self)
        dlg.setWindowTitle("Duplicate destination hub")
        dlg.resize(720, 520)
        v = QVBoxLayout(dlg)
        hub_intro = QLabel(
            "Recommended: preview or apply suggested unique file names (planning-only—does not rename source or "
            "SharePoint files). Use remove or retarget when a mapping should not land in the same folder."
        )
        hub_intro.setObjectName("MutedText")
        hub_intro.setWordWrap(True)
        v.addWidget(hub_intro)
        tree = QTreeWidget()
        tree.setHeaderHidden(True)
        tree.setColumnCount(1)

        def rebuild_tree() -> bool:
            tree.clear()
            g = grouped_duplicate_destination_moves(
                list(self.planned_moves or []),
                destination_file_key=self._destination_file_key_for_execution_validation,
            )
            if not g:
                return False
            for _nk, members in sorted(
                g.items(),
                key=lambda kv: (kv[1][0].get("destination", "").lower(), kv[0]),
            ):
                dest = str(members[0].get("destination", "") or "").strip() or "(unknown)"
                parent_it = QTreeWidgetItem([f"Destination: {dest}"])
                for row in sorted(members, key=lambda r: int(r.get("index", -1))):
                    idx = int(row.get("index", -1))
                    src = str(row.get("source", "") or "").strip() or "(unknown)"
                    child_it = QTreeWidgetItem(parent_it, [f"[{idx}] {src}"])
                    child_it.setData(0, Qt.UserRole, idx)
                tree.addTopLevelItem(parent_it)
                parent_it.setExpanded(True)
            return True

        v.addWidget(tree)

        def selected_duplicate_group_member_indices(*, message_title: str) -> list[int] | None:
            it = tree.currentItem()
            if it is None:
                QMessageBox.information(
                    dlg,
                    message_title,
                    "Select a destination group header or a file row under that group.",
                )
                return None
            group_it = it if it.parent() is None else it.parent()
            if group_it.parent() is not None:
                QMessageBox.information(
                    dlg,
                    message_title,
                    "Select a destination group in the duplicate list.",
                )
                return None
            indices: list[int] = []
            for ci in range(group_it.childCount()):
                ch = group_it.child(ci)
                raw = ch.data(0, Qt.UserRole)
                if raw is None:
                    continue
                try:
                    indices.append(int(raw))
                except (TypeError, ValueError):
                    continue
            if len(indices) < 2:
                QMessageBox.information(
                    dlg,
                    message_title,
                    "This group does not contain multiple planned moves.",
                )
                return None
            return indices

        def on_remove_selected() -> None:
            it = tree.currentItem()
            if it is None:
                QMessageBox.information(
                    dlg,
                    "Remove from plan",
                    "Select a source row under a destination group.",
                )
                return
            if it.parent() is None:
                QMessageBox.information(
                    dlg,
                    "Remove from plan",
                    "Select a specific source row (child under a destination), not the destination group header.",
                )
                return
            raw_idx = it.data(0, Qt.UserRole)
            if raw_idx is None:
                QMessageBox.information(
                    dlg,
                    "Remove from plan",
                    "Select a specific source row under a destination group.",
                )
                return
            try:
                idx = int(raw_idx)
            except (TypeError, ValueError):
                QMessageBox.warning(dlg, "Remove from plan", "Could not read the planned move index for this row.")
                return
            n = len(self.planned_moves or [])
            if idx < 0 or idx >= n:
                QMessageBox.warning(
                    dlg,
                    "Remove from plan",
                    "The plan changed; the tree will refresh.",
                )
                if not rebuild_tree():
                    QMessageBox.information(
                        dlg,
                        "Duplicate destination files",
                        "No duplicate destination files remain.",
                    )
                    dlg.accept()
                return
            move = self.planned_moves[idx]
            src_path = str(move.get("source_path", "") or "").strip() or "(unknown)"
            dest_path = (
                self._destination_file_key_for_execution_validation(move)
                or self._allocation_projection_path(move)
                or str(move.get("destination_path", "") or "").strip()
                or "(unknown)"
            )
            if (
                QMessageBox.question(
                    dlg,
                    "Remove from plan",
                    "Remove this entry from your plan only?\n\n"
                    "This does not delete the source file and does not delete anything already in SharePoint. "
                    "It only removes this planned mapping (unassign).\n\n"
                    f"Source:\n{src_path}\n\n"
                    f"Planned destination file:\n{dest_path}",
                    QMessageBox.Yes | QMessageBox.No,
                    QMessageBox.No,
                )
                != QMessageBox.Yes
            ):
                return
            if idx >= len(self.planned_moves or []):
                QMessageBox.warning(dlg, "Remove from plan", "The plan changed; try again.")
                return
            if not self._remove_planned_move_at_index(idx):
                return
            if not rebuild_tree():
                QMessageBox.information(
                    dlg,
                    "Duplicate destination files",
                    "No duplicate destination files remain.",
                )
                dlg.accept()

        def on_rename_selected() -> None:
            it = tree.currentItem()
            if it is None:
                QMessageBox.information(
                    dlg,
                    "Rename mapping",
                    "Select a source row under a destination group.",
                )
                return
            if it.parent() is None:
                QMessageBox.information(
                    dlg,
                    "Rename mapping",
                    "Select a specific source row (child under a destination), not the destination group header.",
                )
                return
            raw_idx = it.data(0, Qt.UserRole)
            if raw_idx is None:
                QMessageBox.information(
                    dlg,
                    "Rename mapping",
                    "Select a specific source row under a destination group.",
                )
                return
            try:
                idx = int(raw_idx)
            except (TypeError, ValueError):
                QMessageBox.warning(dlg, "Rename mapping", "Could not read the planned move index for this row.")
                return
            n = len(self.planned_moves or [])
            if idx < 0 or idx >= n:
                QMessageBox.warning(
                    dlg,
                    "Rename mapping",
                    "The plan changed; the tree will refresh.",
                )
                if not rebuild_tree():
                    QMessageBox.information(
                        dlg,
                        "Duplicate destination files",
                        "No duplicate destination files remain.",
                    )
                    dlg.accept()
                return
            move = self.planned_moves[idx]
            src_obj = move.get("source") or {}
            if bool(src_obj.get("is_folder", False)):
                QMessageBox.information(
                    dlg,
                    "Rename mapping",
                    "Folder moves cannot be renamed from this dialog.",
                )
                return
            if self._is_move_submitted(move):
                self._show_submitted_item_locked_message(
                    "Rename mapping",
                    f"'{move.get('source_name', 'This item')}'",
                    self._submitted_batch_id_for_move(move),
                )
                return
            current_name = str(self._move_target_name(move) or "").strip()
            new_name, accepted = QInputDialog.getText(
                dlg,
                "Rename planned destination file name",
                "Enter the new file name as it should appear under the destination folder.\n"
                "This changes the planned destination name only; it does not rename the source file.",
                text=current_name or "",
            )
            new_name = new_name.strip()
            if not accepted:
                return
            if not new_name:
                QMessageBox.warning(dlg, "Rename mapping", "The new name cannot be empty.")
                return
            if new_name == current_name:
                return
            if idx >= len(self.planned_moves or []):
                QMessageBox.warning(dlg, "Rename mapping", "The plan changed; try again.")
                return
            move = self.planned_moves[idx]
            trial = dict(move)
            trial["target_name"] = new_name
            new_dk = self._destination_file_key_for_execution_validation(trial)
            if not new_dk:
                QMessageBox.warning(
                    dlg,
                    "Rename mapping",
                    "Could not resolve a destination file path after rename; check destination folder and name.",
                )
                return
            new_nk = norm_execution_key(new_dk)
            for j, other in enumerate(self.planned_moves or []):
                if j == idx:
                    continue
                ok = self._destination_file_key_for_execution_validation(other)
                if not ok:
                    continue
                if norm_execution_key(ok) == new_nk:
                    QMessageBox.warning(
                        dlg,
                        "Rename mapping",
                        "That name still matches another planned file move’s destination.\n\n"
                        f"Conflicting destination file:\n{new_dk}\n\n"
                        "Choose a different name.",
                    )
                    return
            move["target_name"] = new_name
            self.planned_moves_status.setText("Planned item renamed.")
            self.refresh_planned_moves_table()
            self._persist_planning_change("planned_item_renamed")
            _rn_alloc = self._allocation_projection_path(move)
            _rn_scope: set[str] = set()
            if _rn_alloc:
                _rn_c = self._canonical_destination_projection_path(str(_rn_alloc)) or self.normalize_memory_path(
                    str(_rn_alloc)
                )
                if _rn_c:
                    _rn_scope.add(_rn_c)
            self._schedule_local_first_edit_deferred_followup(
                "rename",
                scope_paths=_rn_scope if _rn_scope else None,
                path_excerpt=str(_rn_alloc or "")[:400],
            )
            if not rebuild_tree():
                QMessageBox.information(
                    dlg,
                    "Duplicate destination files",
                    "No duplicate destination files remain.",
                )
                dlg.accept()

        def on_retarget_selected() -> None:
            it = tree.currentItem()
            if it is None:
                QMessageBox.information(
                    dlg,
                    "Retarget mapping",
                    "Select a source row under a destination group.",
                )
                return
            if it.parent() is None:
                QMessageBox.information(
                    dlg,
                    "Retarget mapping",
                    "Select a specific source row (child under a destination), not the destination group header.",
                )
                return
            raw_idx = it.data(0, Qt.UserRole)
            if raw_idx is None:
                QMessageBox.information(
                    dlg,
                    "Retarget mapping",
                    "Select a specific source row under a destination group.",
                )
                return
            try:
                idx = int(raw_idx)
            except (TypeError, ValueError):
                QMessageBox.warning(dlg, "Retarget mapping", "Could not read the planned move index for this row.")
                return
            n = len(self.planned_moves or [])
            if idx < 0 or idx >= n:
                QMessageBox.warning(
                    dlg,
                    "Retarget mapping",
                    "The plan changed; the tree will refresh.",
                )
                if not rebuild_tree():
                    QMessageBox.information(
                        dlg,
                        "Duplicate destination files",
                        "No duplicate destination files remain.",
                    )
                    dlg.accept()
                return
            move = self.planned_moves[idx]
            src_obj = move.get("source") or {}
            if bool(src_obj.get("is_folder", False)):
                QMessageBox.information(
                    dlg,
                    "Retarget mapping",
                    "Folder moves cannot be retargeted from this dialog.",
                )
                return
            if self._is_move_submitted(move):
                self._show_submitted_item_locked_message(
                    "Retarget mapping",
                    f"'{move.get('source_name', 'This item')}'",
                    self._submitted_batch_id_for_move(move),
                )
                return

            QMessageBox.information(
                dlg,
                "Retarget mapping",
                "You will enter a new destination folder path for this planned file.\n\n"
                "This changes the planned destination location only.\n"
                "It does not move source files now.\n"
                "It does not change existing SharePoint content now.\n"
                "This is a planning change only.\n\n"
                "Use the same path format as the Planning Workspace destination tree. "
                "The folder must already be visible there (expand parent folders if needed).",
            )
            default_parent = self.normalize_memory_path(str(move.get("destination_path", "") or "").strip())
            new_parent, accepted = QInputDialog.getText(
                dlg,
                "Retarget mapping",
                "New destination folder path:",
                text=default_parent or "",
            )
            new_parent = str(new_parent or "").strip()
            if not accepted:
                return
            if not new_parent:
                QMessageBox.warning(dlg, "Retarget mapping", "The folder path cannot be empty.")
                return
            if self._destination_paths_match_exact(new_parent, move.get("destination_path", "")):
                return

            target_ref = self._find_visible_destination_item_by_path(new_parent)
            if target_ref is None:
                QMessageBox.warning(
                    dlg,
                    "Retarget mapping",
                    "That folder path is not visible in the destination tree.\n\n"
                    "Expand folders until the folder appears, then try again.",
                )
                return
            target_nd = self.get_tree_item_node_data(target_ref) or {}
            if not self.node_is_manual_drag_destination_folder(target_nd):
                QMessageBox.warning(
                    dlg,
                    "Retarget mapping",
                    "The resolved row is not a valid destination folder for planning.",
                )
                return
            target_path = self._destination_row_semantic_path(target_nd)
            if not target_path:
                QMessageBox.warning(
                    dlg,
                    "Retarget mapping",
                    "Could not resolve the selected destination folder path.",
                )
                return

            dest_snap = self._destination_target_snapshot(target_nd, target_path)
            trial = dict(move)
            trial["destination_path"] = target_path
            trial["destination_id"] = dest_snap.get("id", "")
            trial["destination_name"] = dest_snap.get("name", "")
            trial["destination"] = dict(dest_snap)
            trial["target_name"] = self._move_target_name(move)
            new_dk = self._destination_file_key_for_execution_validation(trial)
            if not new_dk:
                QMessageBox.warning(
                    dlg,
                    "Retarget mapping",
                    "Could not resolve a destination file path after retarget; check the folder path and file name.",
                )
                return
            new_nk = norm_execution_key(new_dk)
            for j, other in enumerate(self.planned_moves or []):
                if j == idx:
                    continue
                ok = self._destination_file_key_for_execution_validation(other)
                if not ok:
                    continue
                if norm_execution_key(ok) == new_nk:
                    QMessageBox.warning(
                        dlg,
                        "Retarget mapping",
                        "That destination folder would still collide with another planned file move.\n\n"
                        f"Conflicting destination file:\n{new_dk}\n\n"
                        "Choose a different folder or rename the file first.",
                    )
                    return

            if (
                QMessageBox.question(
                    dlg,
                    "Retarget mapping",
                    "Apply this retarget?\n\n"
                    "• The planned destination folder for this mapping will change.\n"
                    "• This is a planning change only.\n"
                    "• It does not move source files now.\n"
                    "• It does not change existing SharePoint content now.\n",
                    QMessageBox.Yes | QMessageBox.No,
                    QMessageBox.No,
                )
                != QMessageBox.Yes
            ):
                return

            if idx < 0 or idx >= len(self.planned_moves or []):
                QMessageBox.warning(dlg, "Retarget mapping", "The plan changed; the tree will refresh.")
                if not rebuild_tree():
                    QMessageBox.information(
                        dlg,
                        "Duplicate destination files",
                        "No duplicate destination files remain.",
                    )
                    dlg.accept()
                return
            move_after = self.planned_moves[idx]
            if self._is_move_submitted(move_after):
                self._show_submitted_item_locked_message(
                    "Retarget mapping",
                    f"'{move_after.get('source_name', 'This item')}'",
                    self._submitted_batch_id_for_move(move_after),
                )
                return
            if bool(((move_after.get("source") or {}).get("is_folder"))):
                QMessageBox.information(
                    dlg,
                    "Retarget mapping",
                    "Folder moves cannot be retargeted from this dialog.",
                )
                return

            trial2 = dict(move_after)
            trial2["destination_path"] = target_path
            trial2["destination_id"] = dest_snap.get("id", "")
            trial2["destination_name"] = dest_snap.get("name", "")
            trial2["destination"] = dict(dest_snap)
            trial2["target_name"] = self._move_target_name(move_after)
            new_dk2 = self._destination_file_key_for_execution_validation(trial2)
            if not new_dk2:
                QMessageBox.warning(
                    dlg,
                    "Retarget mapping",
                    "Could not resolve destination after retarget (plan may have changed).",
                )
                return
            new_nk2 = norm_execution_key(new_dk2)
            for j, other in enumerate(self.planned_moves or []):
                if j == idx:
                    continue
                ok = self._destination_file_key_for_execution_validation(other)
                if not ok:
                    continue
                if norm_execution_key(ok) == new_nk2:
                    QMessageBox.warning(
                        dlg,
                        "Retarget mapping",
                        "That destination would still collide with another planned file move. The plan was not changed.",
                    )
                    return

            leaf_sn = str(self._move_target_name(move_after) or "").strip()
            alloc_proj_sn = self._allocation_projection_path(move_after)
            alloc_canon_sn = self._canonical_destination_projection_path(alloc_proj_sn) or self.normalize_memory_path(
                str(alloc_proj_sn or "").strip()
            )
            if not leaf_sn or not alloc_canon_sn:
                QMessageBox.warning(
                    dlg,
                    "Retarget mapping",
                    "Could not resolve the current planned destination file path for this mapping.",
                )
                return
            dest_meta_sn = (
                move_after.get("destination") if isinstance(move_after.get("destination"), dict) else {}
            )
            source_node: dict = {
                "name": leaf_sn,
                "real_name": leaf_sn,
                "display_path": alloc_canon_sn,
                "item_path": alloc_canon_sn,
                "destination_path": alloc_canon_sn,
                "tree_role": "destination",
                "is_folder": False,
                "node_origin": str(dest_meta_sn.get("node_origin", "") or "Real"),
            }
            eid_sn = str(dest_meta_sn.get("id", "") or "").strip()
            if eid_sn:
                source_node["id"] = eid_sn
            for _k in ("drive_id", "library_id", "site_id", "site_name", "library_name"):
                if dest_meta_sn.get(_k):
                    source_node[_k] = dest_meta_sn[_k]

            if not self._move_planned_destination_node(
                source_node,
                target_nd,
                planned_move_index=idx,
            ):
                return
            if not rebuild_tree():
                QMessageBox.information(
                    dlg,
                    "Duplicate destination files",
                    "No duplicate destination files remain.",
                )
                dlg.accept()

        def on_review_all_duplicate_groups_suggested_names() -> None:
            rows = self._build_all_duplicate_groups_unique_name_preview_rows()
            if rows is None:
                QMessageBox.warning(
                    dlg,
                    "Review all groups",
                    "Could not build suggestions for all duplicate groups (invalid rows, folder moves, or could not find unique names).",
                )
                return

            preview = QDialog(dlg)
            preview.setWindowTitle("Suggested names — all duplicate groups (preview)")
            preview.resize(1100, 520)
            pv = QVBoxLayout(preview)
            info = QLabel(
                "Preview only until you click Apply all suggested names.\n"
                "Planned destination file names only.\n"
                "Does not rename source files.\n"
                "Does not rename existing SharePoint content.\n"
                "This is a planning change only."
            )
            info.setWordWrap(True)
            pv.addWidget(info)
            tbl = QTableWidget(len(rows), 5)
            tbl.setHorizontalHeaderLabels(
                [
                    "Duplicate destination (group)",
                    "Planned move index",
                    "Source path",
                    "Current planned file name",
                    "Suggested file name",
                ]
            )
            tbl.setEditTriggers(QAbstractItemView.NoEditTriggers)
            tbl.setSelectionBehavior(QAbstractItemView.SelectRows)
            for r, row in enumerate(rows):
                tbl.setItem(r, 0, QTableWidgetItem(str(row.get("group_destination", "") or "")))
                tbl.setItem(r, 1, QTableWidgetItem(str(row.get("index", ""))))
                tbl.setItem(r, 2, QTableWidgetItem(str(row.get("source_path", "") or "")))
                tbl.setItem(r, 3, QTableWidgetItem(str(row.get("current_leaf", "") or "")))
                tbl.setItem(r, 4, QTableWidgetItem(str(row.get("suggested_leaf", "") or "")))
            th = tbl.horizontalHeader()
            th.setSectionResizeMode(0, QHeaderView.Stretch)
            th.setSectionResizeMode(1, QHeaderView.ResizeToContents)
            th.setSectionResizeMode(2, QHeaderView.Stretch)
            th.setSectionResizeMode(3, QHeaderView.ResizeToContents)
            th.setSectionResizeMode(4, QHeaderView.ResizeToContents)
            pv.addWidget(tbl)

            def on_apply_all_bulk_suggested_names() -> None:
                out = self._planning_bulk_apply_duplicate_suggested_names(
                    parent=preview, quiet_success=True
                )
                if out == "stale":
                    preview.reject()
                    if not rebuild_tree():
                        QMessageBox.information(
                            dlg,
                            "Duplicate destination files",
                            "No duplicate destination files remain.",
                        )
                        dlg.accept()
                    return
                if out not in ("applied", "applied_no_dupes_left"):
                    return
                preview.accept()
                if not rebuild_tree():
                    QMessageBox.information(
                        dlg,
                        "Duplicate destination files",
                        "No duplicate destination files remain.",
                    )
                    dlg.accept()

            apply_all_row = QHBoxLayout()
            apply_all_pb = QPushButton("Apply all suggested names")
            apply_all_pb.setToolTip(
                "Apply every previewed suggestion in one planning-only update. "
                "Does not rename source files or SharePoint content."
            )
            apply_all_pb.clicked.connect(on_apply_all_bulk_suggested_names)
            close_pb = QPushButton("Close")
            close_pb.clicked.connect(preview.reject)
            apply_all_row.addWidget(apply_all_pb)
            apply_all_row.addStretch()
            apply_all_row.addWidget(close_pb)
            pv.addLayout(apply_all_row)
            preview.exec()

        def on_suggest_unique_names() -> None:
            indices = selected_duplicate_group_member_indices(message_title="Suggest unique names")
            if indices is None:
                return
            rows = self._build_duplicate_group_unique_name_preview_rows(indices)
            if rows is None:
                QMessageBox.warning(
                    dlg,
                    "Suggest unique names",
                    "Could not build suggestions (invalid rows, folder moves, or could not find unique names).",
                )
                return
            preview = QDialog(dlg)
            preview.setWindowTitle("Suggested names (preview only — not applied)")
            preview.resize(920, 360)
            pv = QVBoxLayout(preview)
            _prev_lbl = QLabel(
                "These names are suggestions only. Nothing has been changed in your plan.\n"
                "Close this window when finished reviewing."
            )
            _prev_lbl.setWordWrap(True)
            pv.addWidget(_prev_lbl)
            tbl = QTableWidget(len(rows), 3)
            tbl.setHorizontalHeaderLabels(
                ["Source path", "Current planned file name", "Suggested file name"]
            )
            tbl.setEditTriggers(QAbstractItemView.NoEditTriggers)
            tbl.setSelectionBehavior(QAbstractItemView.SelectRows)
            for r, row in enumerate(rows):
                tbl.setItem(r, 0, QTableWidgetItem(row["source_path"]))
                tbl.setItem(r, 1, QTableWidgetItem(row["current_leaf"]))
                tbl.setItem(r, 2, QTableWidgetItem(row["suggested_leaf"]))
            hdr = tbl.horizontalHeader()
            hdr.setSectionResizeMode(0, QHeaderView.Stretch)
            hdr.setSectionResizeMode(1, QHeaderView.ResizeToContents)
            hdr.setSectionResizeMode(2, QHeaderView.ResizeToContents)
            pv.addWidget(tbl)
            pbb = QDialogButtonBox(QDialogButtonBox.Close)
            pbb.rejected.connect(preview.reject)
            pv.addWidget(pbb)
            preview.exec()

        def on_apply_suggested_unique_names() -> None:
            indices = selected_duplicate_group_member_indices(message_title="Apply suggested names")
            if indices is None:
                return
            rows = self._build_duplicate_group_unique_name_preview_rows(indices)
            if rows is None:
                QMessageBox.warning(
                    dlg,
                    "Apply suggested names",
                    "Could not build suggestions (invalid rows, folder moves, or could not find unique names).",
                )
                return

            def _apply_validation_failed(msg: str, *, stale: bool) -> None:
                QMessageBox.warning(dlg, "Apply suggested names", msg)
                if stale and not rebuild_tree():
                    QMessageBox.information(
                        dlg,
                        "Duplicate destination files",
                        "No duplicate destination files remain.",
                    )
                    dlg.accept()

            v_err = self._validate_duplicate_group_apply_preview_rows(rows)
            if v_err == "__stale_plan__":
                _apply_validation_failed("The plan changed; the tree will refresh.", stale=True)
                return
            if v_err:
                _apply_validation_failed(v_err, stale=False)
                return
            for r in rows:
                move = self.planned_moves[int(r["index"])]
                if self._is_move_submitted(move):
                    self._show_submitted_item_locked_message(
                        "Apply suggested names",
                        f"'{move.get('source_name', 'This item')}'",
                        self._submitted_batch_id_for_move(move),
                    )
                    return

            n_apply = len(rows)
            confirm_text = (
                "Apply the suggested unique names for the selected duplicate group?\n\n"
                f"• {n_apply} planned destination file names will change.\n"
                "• This is a planning change only.\n"
                "• It updates planned destination file names in your plan only.\n"
                "• It does not rename source files.\n"
                "• It does not rename existing SharePoint content.\n"
            )
            if (
                QMessageBox.question(
                    dlg,
                    "Apply suggested names",
                    confirm_text,
                    QMessageBox.Yes | QMessageBox.No,
                    QMessageBox.No,
                )
                != QMessageBox.Yes
            ):
                return

            v_err2 = self._validate_duplicate_group_apply_preview_rows(rows)
            if v_err2 == "__stale_plan__":
                _apply_validation_failed(
                    "The plan changed before apply; the tree will refresh.",
                    stale=True,
                )
                return
            if v_err2:
                _apply_validation_failed(v_err2, stale=False)
                return
            for r in rows:
                move = self.planned_moves[int(r["index"])]
                if self._is_move_submitted(move):
                    self._show_submitted_item_locked_message(
                        "Apply suggested names",
                        f"'{move.get('source_name', 'This item')}'",
                        self._submitted_batch_id_for_move(move),
                    )
                    return

            for r in rows:
                idx = int(r["index"])
                self.planned_moves[idx]["target_name"] = str(r.get("suggested_leaf", "") or "").strip()
            self.planned_moves_status.setText("Applied suggested planned destination file names.")
            self.refresh_planned_moves_table()
            self._persist_planning_change("duplicate_group_unique_names_applied")
            if not rebuild_tree():
                QMessageBox.information(
                    dlg,
                    "Duplicate destination files",
                    "No duplicate destination files remain.",
                )
                dlg.accept()

        remove_btn = QPushButton("Remove mapping from plan")
        remove_btn.setToolTip(
            "Removes this planned mapping only. Does not delete the source file or existing SharePoint content."
        )
        remove_btn.clicked.connect(on_remove_selected)
        rename_btn = QPushButton("Rename planned destination file…")
        rename_btn.setToolTip(
            "Change the destination file name in the plan only. Does not rename the source file."
        )
        rename_btn.clicked.connect(on_rename_selected)
        retarget_btn = QPushButton("Retarget selected mapping…")
        retarget_btn.setToolTip(
            "Change the planned destination folder for one file mapping. Planning change only; "
            "does not move source files or SharePoint content."
        )
        retarget_btn.clicked.connect(on_retarget_selected)
        suggest_btn = QPushButton("Suggest unique names…")
        suggest_btn.setToolTip(
            "Preview suggested unique destination file names for one duplicate group. Does not change the plan."
        )
        suggest_btn.clicked.connect(on_suggest_unique_names)
        apply_suggest_btn = QPushButton("Apply suggested names for this group…")
        apply_suggest_btn.setToolTip(
            "Apply preview-style suggested unique destination file names for the selected group only. "
            "Planning change only; does not rename source files or SharePoint content."
        )
        apply_suggest_btn.clicked.connect(on_apply_suggested_unique_names)
        review_all_groups_btn = QPushButton("Review suggested unique names for all groups…")
        review_all_groups_btn.setToolTip(
            "Preview and optionally apply suggested unique file names for every duplicate destination group. "
            "Planning change only."
        )
        review_all_groups_btn.clicked.connect(on_review_all_duplicate_groups_suggested_names)
        btn_row = QHBoxLayout()
        btn_row.addWidget(remove_btn)
        btn_row.addWidget(rename_btn)
        btn_row.addWidget(retarget_btn)
        btn_row.addWidget(suggest_btn)
        btn_row.addWidget(apply_suggest_btn)
        btn_row.addStretch()
        v.addLayout(btn_row)
        btn_row2 = QHBoxLayout()
        btn_row2.addWidget(review_all_groups_btn)
        btn_row2.addStretch()
        v.addLayout(btn_row2)
        bb = QDialogButtonBox(QDialogButtonBox.Close)
        bb.rejected.connect(dlg.reject)
        v.addWidget(bb)
        rebuild_tree()
        dlg.exec()

    def _planned_move_row_for_folder_source_path(self, folder_src_path: str) -> int | None:
        target = self.normalize_memory_path(str(folder_src_path or ""))
        if not target:
            return None
        moves = getattr(self, "planned_moves", None) or []
        for i, m in enumerate(moves):
            if self._planned_move_is_file_allocation(m):
                continue
            fp = self.normalize_memory_path(str(m.get("source_path", "") or ""))
            if fp and norm_execution_key(fp) == norm_execution_key(target):
                return i
        return None

    def _inspector_close_after_plan_mutation(self, inspector_dlg: QDialog) -> None:
        QMessageBox.information(
            inspector_dlg,
            "Plan updated",
            "The plan changed. Close this inspector and retry the run so the execution manifest reflects the current draft.",
        )
        inspector_dlg.accept()

    def _planning_remove_planned_move_with_confirm(self, parent: QWidget, idx: int) -> bool:
        n = len(self.planned_moves or [])
        if idx < 0 or idx >= n:
            QMessageBox.warning(parent, "Remove from plan", "The plan changed; try again.")
            return False
        move = self.planned_moves[idx]
        src_path = str(move.get("source_path", "") or "").strip() or "(unknown)"
        dest_path = (
            self._destination_file_key_for_execution_validation(move)
            or self._allocation_projection_path(move)
            or str(move.get("destination_path", "") or "").strip()
            or "(unknown)"
        )
        if (
            QMessageBox.question(
                parent,
                "Remove from plan",
                "Remove this entry from your plan only?\n\n"
                "This does not delete the source file and does not delete anything already in SharePoint. "
                "It only removes this planned mapping (unassign).\n\n"
                f"Source:\n{src_path}\n\n"
                f"Planned destination file:\n{dest_path}",
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.No,
            )
            != QMessageBox.Yes
        ):
            return False
        if idx >= len(self.planned_moves or []):
            QMessageBox.warning(parent, "Remove from plan", "The plan changed; try again.")
            return False
        return bool(self._remove_planned_move_at_index(idx))

    def _planning_rename_planned_file_with_dialog(self, parent: QWidget, idx: int) -> bool:
        n = len(self.planned_moves or [])
        if idx < 0 or idx >= n:
            QMessageBox.warning(parent, "Rename mapping", "The plan changed; try again.")
            return False
        move = self.planned_moves[idx]
        src_obj = move.get("source") or {}
        if bool(src_obj.get("is_folder", False)):
            QMessageBox.information(
                parent,
                "Rename mapping",
                "Folder moves cannot be renamed from this dialog.",
            )
            return False
        if self._is_move_submitted(move):
            self._show_submitted_item_locked_message(
                "Rename mapping",
                f"'{move.get('source_name', 'This item')}'",
                self._submitted_batch_id_for_move(move),
            )
            return False
        current_name = str(self._move_target_name(move) or "").strip()
        new_name, accepted = QInputDialog.getText(
            parent,
            "Rename planned destination file name",
            "Enter the new file name as it should appear under the destination folder.\n"
            "This changes the planned destination name only; it does not rename the source file.",
            text=current_name or "",
        )
        new_name = new_name.strip()
        if not accepted:
            return False
        if not new_name:
            QMessageBox.warning(parent, "Rename mapping", "The new name cannot be empty.")
            return False
        if new_name == current_name:
            return False
        if idx >= len(self.planned_moves or []):
            QMessageBox.warning(parent, "Rename mapping", "The plan changed; try again.")
            return False
        move = self.planned_moves[idx]
        trial = dict(move)
        trial["target_name"] = new_name
        new_dk = self._destination_file_key_for_execution_validation(trial)
        if not new_dk:
            QMessageBox.warning(
                parent,
                "Rename mapping",
                "Could not resolve a destination file path after rename; check destination folder and name.",
            )
            return False
        new_nk = norm_execution_key(new_dk)
        for j, other in enumerate(self.planned_moves or []):
            if j == idx:
                continue
            ok = self._destination_file_key_for_execution_validation(other)
            if not ok:
                continue
            if norm_execution_key(ok) == new_nk:
                QMessageBox.warning(
                    parent,
                    "Rename mapping",
                    "That name still matches another planned file move’s destination.\n\n"
                    f"Conflicting destination file:\n{new_dk}\n\n"
                    "Choose a different name.",
                )
                return False
        move["target_name"] = new_name
        if hasattr(self, "planned_moves_status"):
            self.planned_moves_status.setText("Planned item renamed.")
        self.refresh_planned_moves_table()
        self._persist_planning_change("planned_item_renamed")
        _rn_alloc = self._allocation_projection_path(move)
        _rn_scope: set[str] = set()
        if _rn_alloc:
            _rn_c = self._canonical_destination_projection_path(str(_rn_alloc)) or self.normalize_memory_path(str(_rn_alloc))
            if _rn_c:
                _rn_scope.add(_rn_c)
        self._schedule_local_first_edit_deferred_followup(
            "rename",
            scope_paths=_rn_scope if _rn_scope else None,
            path_excerpt=str(_rn_alloc or "")[:400],
        )
        return True

    def _planning_retarget_planned_file_to_folder_node(
        self,
        parent: QWidget,
        idx: int,
        target_nd: dict,
        *,
        interactive_confirm: bool = True,
    ) -> bool:
        """Apply retarget for a draft file row using a resolved destination folder node (planning tree)."""
        n = len(self.planned_moves or [])
        if idx < 0 or idx >= n:
            QMessageBox.warning(parent, "Retarget mapping", "The plan changed; try again.")
            return False
        move = self.planned_moves[idx]
        src_obj = move.get("source") or {}
        if bool(src_obj.get("is_folder", False)):
            QMessageBox.information(
                parent,
                "Retarget mapping",
                "Folder moves cannot be retargeted from this dialog.",
            )
            return False
        if self._is_move_submitted(move):
            self._show_submitted_item_locked_message(
                "Retarget mapping",
                f"'{move.get('source_name', 'This item')}'",
                self._submitted_batch_id_for_move(move),
            )
            return False

        target_nd = dict(target_nd or {})
        if not self.node_is_manual_drag_destination_folder(target_nd):
            QMessageBox.warning(
                parent,
                "Retarget mapping",
                "The resolved row is not a valid destination folder for planning.",
            )
            return False
        target_path = self._destination_row_semantic_path(target_nd)
        if not target_path:
            QMessageBox.warning(
                parent,
                "Retarget mapping",
                "Could not resolve the selected destination folder path.",
            )
            return False

        dest_snap = self._destination_target_snapshot(target_nd, target_path)
        trial = dict(move)
        trial["destination_path"] = target_path
        trial["destination_id"] = dest_snap.get("id", "")
        trial["destination_name"] = dest_snap.get("name", "")
        trial["destination"] = dict(dest_snap)
        trial["target_name"] = self._move_target_name(move)
        new_dk = self._destination_file_key_for_execution_validation(trial)
        if not new_dk:
            QMessageBox.warning(
                parent,
                "Retarget mapping",
                "Could not resolve a destination file path after retarget; check the folder path and file name.",
            )
            return False
        new_nk = norm_execution_key(new_dk)
        for j, other in enumerate(self.planned_moves or []):
            if j == idx:
                continue
            ok = self._destination_file_key_for_execution_validation(other)
            if not ok:
                continue
            if norm_execution_key(ok) == new_nk:
                QMessageBox.warning(
                    parent,
                    "Retarget mapping",
                    "That destination folder would still collide with another planned file move.\n\n"
                    f"Conflicting destination file:\n{new_dk}\n\n"
                    "Choose a different folder or rename the file first.",
                )
                return False

        if interactive_confirm:
            if (
                QMessageBox.question(
                    parent,
                    "Retarget mapping",
                    "Apply this retarget?\n\n"
                    "• The planned destination folder for this mapping will change.\n"
                    "• This is a planning change only.\n"
                    "• It does not move source files now.\n"
                    "• It does not change existing SharePoint content now.\n",
                    QMessageBox.Yes | QMessageBox.No,
                    QMessageBox.No,
                )
                != QMessageBox.Yes
            ):
                return False

        if idx < 0 or idx >= len(self.planned_moves or []):
            QMessageBox.warning(parent, "Retarget mapping", "The plan changed; try again.")
            return False
        move_after = self.planned_moves[idx]
        if self._is_move_submitted(move_after):
            self._show_submitted_item_locked_message(
                "Retarget mapping",
                f"'{move_after.get('source_name', 'This item')}'",
                self._submitted_batch_id_for_move(move_after),
            )
            return False
        if bool(((move_after.get("source") or {}).get("is_folder"))):
            QMessageBox.information(
                parent,
                "Retarget mapping",
                "Folder moves cannot be retargeted from this dialog.",
            )
            return False

        trial2 = dict(move_after)
        trial2["destination_path"] = target_path
        trial2["destination_id"] = dest_snap.get("id", "")
        trial2["destination_name"] = dest_snap.get("name", "")
        trial2["destination"] = dict(dest_snap)
        trial2["target_name"] = self._move_target_name(move_after)
        new_dk2 = self._destination_file_key_for_execution_validation(trial2)
        if not new_dk2:
            QMessageBox.warning(
                parent,
                "Retarget mapping",
                "Could not resolve destination after retarget (plan may have changed).",
            )
            return False
        new_nk2 = norm_execution_key(new_dk2)
        for j, other in enumerate(self.planned_moves or []):
            if j == idx:
                continue
            ok = self._destination_file_key_for_execution_validation(other)
            if not ok:
                continue
            if norm_execution_key(ok) == new_nk2:
                QMessageBox.warning(
                    parent,
                    "Retarget mapping",
                    "That destination would still collide with another planned file move. The plan was not changed.",
                )
                return False

        leaf_sn = str(self._move_target_name(move_after) or "").strip()
        alloc_proj_sn = self._allocation_projection_path(move_after)
        alloc_canon_sn = self._canonical_destination_projection_path(alloc_proj_sn) or self.normalize_memory_path(
            str(alloc_proj_sn or "").strip()
        )
        if not leaf_sn or not alloc_canon_sn:
            QMessageBox.warning(
                parent,
                "Retarget mapping",
                "Could not resolve the current planned destination file path for this mapping.",
            )
            return False
        dest_meta_sn = (
            move_after.get("destination") if isinstance(move_after.get("destination"), dict) else {}
        )
        source_node: dict = {
            "name": leaf_sn,
            "real_name": leaf_sn,
            "display_path": alloc_canon_sn,
            "item_path": alloc_canon_sn,
            "destination_path": alloc_canon_sn,
            "tree_role": "destination",
            "is_folder": False,
            "node_origin": str(dest_meta_sn.get("node_origin", "") or "Real"),
        }
        eid_sn = str(dest_meta_sn.get("id", "") or "").strip()
        if eid_sn:
            source_node["id"] = eid_sn
        for _k in ("drive_id", "library_id", "site_id", "site_name", "library_name"):
            if dest_meta_sn.get(_k):
                source_node[_k] = dest_meta_sn[_k]

        if not self._move_planned_destination_node(
            source_node,
            target_nd,
            planned_move_index=idx,
        ):
            return False
        return True

    def _transfer_manifest_duplicate_validation_error(self, manifest: dict) -> str:
        steps = list((manifest or {}).get("transfer_steps") or [])
        ds, dd = duplicate_collision_report_from_transfer_steps(steps)
        return format_execution_duplicate_message(ds, dd)

    def _planned_move_table_row_for_transfer_request_id(self, request_id: str) -> int | None:
        rid = str(request_id or "").strip()
        if not rid or rid.startswith("recsub-"):
            return None
        moves = getattr(self, "planned_moves", None) or []
        for i, m in enumerate(moves):
            if self._mapping_id_for_planned_move_at_index(m, i) == rid:
                return i
        return None

    def _duplicate_inspector_recursive_folder_hint(self, step_source_path: str) -> str:
        sp = self.normalize_memory_path(str(step_source_path or ""))
        if not sp:
            return ""
        moves = getattr(self, "planned_moves", None) or []
        best_path = ""
        best_len = -1
        for m in moves:
            if self._planned_move_is_file_allocation(m):
                continue
            fp = self.normalize_memory_path(str(m.get("source_path", "") or ""))
            if not fp:
                continue
            if self.source_item_path_is_descendant_of(sp, fp):
                if len(fp) > best_len:
                    best_len = len(fp)
                    best_path = fp
        return best_path

    def _inspector_execution_options_allow_draft_manifest_refresh(self, eo: dict | None) -> bool:
        """True when duplicate inspector may rebuild transfer_steps from current draft via build_simulation_manifest."""
        eo = dict(eo or {})
        if bool(eo.get("snapshot_browsed_recursive")):
            return False
        if bool(eo.get("snapshot_recursive_subtree")):
            return False
        if list(eo.get("snapshot_scoped_request_ids") or []):
            return False
        if int(eo.get("pilot_max_graph_operations") or 0) > 0:
            return False
        for k in (
            "pilot_transfer_step_indices",
            "pilot_transfer_step_uids",
            "pilot_transfer_destination_keys",
            "pilot_transfer_destination_paths",
            "pilot_proposed_folder_destination_paths",
            "pilot_proposed_folder_name",
        ):
            if eo.get(k):
                return False
        return True

    def _inspector_append_recursive_transfer_steps(self, rm: dict, moves: list[dict]) -> None:
        if not moves:
            return
        steps = list(rm.get("transfer_steps") or [])
        max_i = max((int(s.get("index", -1)) for s in steps if isinstance(s, dict)), default=-1)
        for j, mv in enumerate(moves):
            steps.append(_planned_move_to_step(max_i + 1 + j, mv).to_json_dict())
        rm["transfer_steps"] = steps
        fixed_manifest, _ = upconvert_manifest_v1_to_v2(rm)
        rm.clear()
        rm.update(fixed_manifest)

    def _inspector_capture_duplicate_inspector_refresh_context(
        self, run_manifest: dict, browsed_recursive_context: dict | None
    ) -> dict | None:
        """Context to rebuild the duplicate inspector view after plan edits (subset/recursive only).

        Returns None when in-place rebuild would not match the blocked run (pilot, browse-recursive, etc.).
        """
        eo = dict((run_manifest or {}).get("execution_options") or {})
        if int(eo.get("pilot_max_graph_operations") or 0) > 0:
            return None
        for k in (
            "pilot_transfer_step_indices",
            "pilot_transfer_step_uids",
            "pilot_transfer_destination_keys",
            "pilot_transfer_destination_paths",
            "pilot_proposed_folder_destination_paths",
            "pilot_proposed_folder_name",
        ):
            if eo.get(k):
                return None
        if bool(eo.get("snapshot_browsed_recursive")) or browsed_recursive_context is not None:
            return None
        if not self._draft_pipeline_execution_enabled():
            return {"kind": "none"}
        if not list(eo.get("snapshot_scoped_request_ids") or []):
            return {"kind": "none"}
        return {
            "kind": "snapshot_subset",
            "selected_rows": list(self._planned_moves_selected_row_indices()),
            "use_recursive_subtree": bool(eo.get("snapshot_recursive_subtree")),
            "scoped_mode": str(eo.get("snapshot_scoped_mode") or "strict").strip() or "strict",
        }

    def _rebuild_inspector_run_manifest_from_refresh_context(self, ctx: dict) -> dict | None:
        """Rebuild manifest like _start_manifest_run_worker subset/recursive prep + preflight (draft pipeline only)."""
        kind = str(ctx.get("kind") or "")
        if kind == "none":
            return self._inspector_build_fresh_simulation_manifest_snapshot()
        if kind != "snapshot_subset":
            return None
        if not self._draft_pipeline_execution_enabled():
            return self._inspector_build_fresh_simulation_manifest_snapshot()
        selected_rows = list(ctx.get("selected_rows") or [])
        if not selected_rows:
            return None
        base = self._inspector_build_fresh_simulation_manifest_snapshot()
        if not base:
            return None
        run_manifest = copy.deepcopy(base)
        use_rec = bool(ctx.get("use_recursive_subtree"))
        scoped_mode = str(ctx.get("scoped_mode") or "strict").strip() or "strict"
        if scoped_mode not in ("strict", "dependency_closure"):
            scoped_mode = "strict"
        if use_rec:
            if not getattr(self.graph, "token", None):
                return None
            scoped_ids, _alloc_app, mv_app, exp_count, err = self._expand_snapshot_scoped_recursive_subtree(
                selected_rows
            )
            if err or not scoped_ids:
                return None
            eo = dict(run_manifest.get("execution_options") or {})
            eo["snapshot_scoped_request_ids"] = list(scoped_ids)
            eo["snapshot_scoped_mode"] = scoped_mode
            eo["snapshot_recursive_subtree"] = True
            eo["snapshot_recursive_subtree_expanded_file_count"] = int(exp_count or 0)
            run_manifest["execution_options"] = eo
            if mv_app:
                self._inspector_append_recursive_transfer_steps(run_manifest, list(mv_app))
        else:
            scoped_ids = self._derive_snapshot_scoped_file_seed_mapping_ids(selected_rows)
            if not scoped_ids:
                return None
            eo = dict(run_manifest.get("execution_options") or {})
            eo["snapshot_scoped_request_ids"] = list(scoped_ids)
            eo["snapshot_scoped_mode"] = scoped_mode
            run_manifest["execution_options"] = eo
        self._preflight_enrich_manifest_graph_ids(run_manifest)
        return run_manifest

    def _inspector_build_fresh_simulation_manifest_snapshot(self) -> dict | None:
        try:
            ctx = getattr(self, "current_session_context", None) or {}
            tenant_hint = str(ctx.get("tenant_domain", "") or "")
            draft_key = str(self.active_draft_session_id or "").strip()
            ss = getattr(self, "_draft_shell_state", None)
            if not draft_key and isinstance(ss, SessionState):
                draft_key = str(ss.DraftId or "").strip()
            if not draft_key:
                draft_key = "draft"
            return build_simulation_manifest(
                planned_moves=list(self.planned_moves or []),
                proposed_folders=list(self.proposed_folders or []),
                draft_id=draft_key,
                tenant_hint=tenant_hint,
                notes="Draft snapshot refresh from duplicate collision inspector.",
                manifest_version=2,
                plan_leaf_exclusions=sorted(getattr(self, "_plan_leaf_exclusions", set()) or []),
                graph_unsafe_folder_step_indices=self._compute_graph_unsafe_folder_step_indices(),
                graph_expanded_transfer_steps=self._compute_graph_expanded_transfer_steps_json(),
            )
        except Exception:
            return None

    def _inspector_capabilities_for_transfer_step(self, st: dict | None) -> dict:
        empty = {
            "rid": "",
            "src_path_step": "",
            "pr": None,
            "is_rec": False,
            "hh": "",
            "parent_pr": None,
            "can_go": False,
            "can_go_parent": False,
            "can_remove": False,
            "can_rename": False,
            "can_retarget": False,
        }
        if not isinstance(st, dict):
            return empty
        rid = str(st.get("request_id", "") or "").strip()
        src_path_step = str(st.get("source_path", "") or "").strip()
        pr = self._planned_move_table_row_for_transfer_request_id(rid)
        is_rec = rid.startswith("recsub-")
        hh = self._duplicate_inspector_recursive_folder_hint(src_path_step) if is_rec else ""
        parent_pr = self._planned_move_row_for_folder_source_path(hh) if hh else None
        move = self.planned_moves[pr] if pr is not None and pr < len(self.planned_moves or []) else None
        submitted = bool(move and self._is_move_submitted(move))
        is_file = bool(move and self._planned_move_is_file_allocation(move))
        dest_path_step = str(st.get("destination_path", "") or "").strip()
        return {
            "rid": rid,
            "src_path_step": src_path_step,
            "pr": pr,
            "is_rec": is_rec,
            "hh": hh,
            "parent_pr": parent_pr,
            "can_go": bool(pr is not None or bool(dest_path_step) or bool(src_path_step)),
            "can_go_parent": bool(is_rec and parent_pr is not None),
            "can_remove": bool(pr is not None and not submitted),
            "can_rename": bool(pr is not None and is_file and not submitted),
            "can_retarget": bool(pr is not None and is_file and not submitted),
        }

    def _inspector_focus_planned_moves_row(self, move_row: int) -> None:
        tabs = getattr(self, "workspace_tabs", None)
        box = getattr(self, "planned_moves_box", None)
        tbl_pm = getattr(self, "planned_moves_table", None)
        if tabs is not None and box is not None:
            tabs.setCurrentWidget(box)
        if tbl_pm is not None:
            tbl_pm.clearSelection()
            tbl_pm.selectRow(int(move_row))
            tbl_pm.setFocus()
            it0 = tbl_pm.item(int(move_row), 0)
            if it0 is not None:
                tbl_pm.scrollToItem(it0)

    def _inspector_run_go_from_step(self, st: dict) -> None:
        if not isinstance(st, dict):
            return
        rid = str(st.get("request_id", "") or "").strip()
        pr = self._planned_move_table_row_for_transfer_request_id(rid)
        if pr is not None:
            self._inspector_focus_planned_moves_row(pr)
            return
        src_path_step = str(st.get("source_path", "") or "").strip()
        if src_path_step:
            self._activate_workflow_source_row({"source_path": src_path_step})

    def _inspector_resolve_step_destination_file_path(self, st: dict) -> str:
        """Canonical destination file path for a transfer step — matches duplicate grouping semantics."""
        if not isinstance(st, dict):
            return ""
        dk = transfer_step_file_destination_key(st)
        if dk:
            return (
                self._canonical_destination_projection_path(dk)
                or self.normalize_memory_path(str(dk).strip())
            )
        target_path = ""
        rid = str(st.get("request_id", "") or "").strip()
        pr = self._planned_move_table_row_for_transfer_request_id(rid)
        pm = self.planned_moves or []
        if pr is not None and 0 <= int(pr) < len(pm):
            move = pm[int(pr)]
            target_path = (
                self._allocation_projection_path(move)
                or self._move_destination_target_path(move)
                or ""
            )
        if not str(target_path or "").strip():
            target_path = str(st.get("destination_path", "") or "").strip()
        return (
            self._canonical_destination_projection_path(target_path)
            or self.normalize_memory_path(str(target_path or "").strip())
        )

    def _inspector_destination_node_data_at_exact_path(self, canonical_path: str) -> dict | None:
        """Read-only: node payload at an exact canonical destination path, or None if not uniquely visible."""
        normalized_target = self._canonical_destination_projection_path(canonical_path) or self.normalize_memory_path(
            str(canonical_path or "").strip()
        )
        if not normalized_target:
            return None
        model = getattr(self, "destination_planning_model", None)
        if model is None:
            return None
        candidate_ixs = model.find_indices_for_canonical_destination_path(normalized_target)
        if not candidate_ixs:
            return None
        selected = self._select_canonical_destination_item(candidate_ixs, prefer=None)
        if selected is None or not selected.isValid():
            return None
        nd = selected.data(Qt.UserRole) or {}
        visible_path = self._tree_item_path(nd)
        if not visible_path:
            return None
        match_details = self._destination_parent_match_details(canonical_path, visible_path)
        if not match_details["exact_match"]:
            return None
        return nd if isinstance(nd, dict) else None

    def _inspector_existing_real_file_at_destination_path(self, canonical_path: str) -> bool:
        """True when a non-folder tree node at this path is loaded and treated as real (not projected/planned shell)."""
        nd = self._inspector_destination_node_data_at_exact_path(canonical_path)
        if not nd or nd.get("placeholder") or nd.get("is_folder"):
            return False
        return self._destination_node_state(nd) == "real"

    def _inspector_destination_selection_matches_canonical(self, expected_canon_path: str) -> bool:
        """True when the destination tree's current row matches ``expected_canon_path`` (normalized full path)."""
        exp_raw = self._canonical_destination_projection_path(expected_canon_path) or self.normalize_memory_path(
            str(expected_canon_path or "").strip()
        )
        exp = norm_execution_key(exp_raw)
        if not exp:
            return False
        tree = getattr(self, "destination_tree_widget", None)
        if tree is None:
            return False
        ix = tree.currentIndex()
        if not ix.isValid():
            return False
        nd = self.get_tree_item_node_data(ix) or {}
        vis = self._tree_item_path(nd)
        if not vis:
            return False
        cand_raw = self._canonical_destination_projection_path(vis) or self.normalize_memory_path(vis)
        cand = norm_execution_key(cand_raw)
        return bool(cand and cand == exp)

    def _inspector_navigate_destination_for_step(
        self,
        st: dict,
        *,
        mode: str,
        on_banner_fail: Any | None = None,
        success_banner: str = "",
        on_banner_info: Any | None = None,
    ) -> None:
        """Duplicate inspector: select destination tree row — ``mode`` is ``file`` or ``folder`` (parent of file path)."""
        if not isinstance(st, dict):
            return

        def _fail(msg: str = "This item could not be located in the destination tree.") -> None:
            if on_banner_fail is not None:
                on_banner_fail(msg)

        canon_file = self._inspector_resolve_step_destination_file_path(st)
        if not canon_file:
            _fail()
            return
        nav_path = canon_file
        if mode == "folder":
            parent = self._destination_parent_path(canon_file)
            nav_path = (
                self._canonical_destination_projection_path(parent)
                or self.normalize_memory_path(str(parent or "").strip())
            )
        if not nav_path:
            _fail()
            return
        navigated = False
        if self._select_destination_item_by_path(nav_path):
            if self._inspector_destination_selection_matches_canonical(nav_path):
                navigated = True
            else:
                tree_nd = None
                tw0 = getattr(self, "destination_tree_widget", None)
                if tw0 is not None:
                    ix0 = tw0.currentIndex()
                    if ix0.isValid():
                        tree_nd = self.get_tree_item_node_data(ix0) or {}
                sel_vis = self._tree_item_path(tree_nd) if tree_nd else ""
                log_warn(
                    "duplicate_inspector_nav_path_mismatch",
                    event="immediate_selection_mismatch",
                    projected_full_path_excerpt=str(nav_path or "")[:400],
                    tree_selected_path_excerpt=str(sel_vis or "")[:400],
                    norm_expected=norm_execution_key(
                        self._canonical_destination_projection_path(nav_path)
                        or self.normalize_memory_path(str(nav_path or "").strip())
                    ),
                    norm_selected=norm_execution_key(
                        self._canonical_destination_projection_path(sel_vis)
                        or self.normalize_memory_path(str(sel_vis or "").strip())
                    ),
                )
                navigated = self._start_destination_navigation(nav_path)
        else:
            navigated = self._start_destination_navigation(nav_path)
        tw = getattr(self, "destination_tree_widget", None)
        if navigated and tw is not None:
            tw.setFocus(Qt.FocusReason.OtherFocusReason)
            tw.activateWindow()
            if success_banner and on_banner_info is not None:
                on_banner_info(success_banner)
            return
        _fail()

    def _inspector_navigate_existing_destination_file_for_step(
        self,
        st: dict,
        *,
        on_banner_fail: Any | None = None,
        on_banner_info: Any | None = None,
    ) -> None:
        """Destination tree: select the existing library file at the step path (only when a real node is visible)."""
        if not isinstance(st, dict):
            return
        canon = self._inspector_resolve_step_destination_file_path(st)
        if not canon or not self._inspector_existing_real_file_at_destination_path(canon):
            if on_banner_fail is not None:
                on_banner_fail(
                    "No existing destination file is visible at this exact path in the tree — "
                    "expand folders or refresh, or use Show other planned row if this is only a plan overlap."
                )
            return
        self._inspector_navigate_destination_for_step(
            st,
            mode="file",
            on_banner_fail=on_banner_fail,
            success_banner="Showing existing destination file at this path",
            on_banner_info=on_banner_info,
        )

    def _inspector_go_to_destination_from_step(
        self,
        st: dict,
        *,
        on_banner: Any | None = None,
    ) -> None:
        """Backward-compatible: select the destination file row (no success banner)."""
        self._inspector_navigate_destination_for_step(
            st,
            mode="file",
            on_banner_fail=on_banner,
            success_banner="",
            on_banner_info=None,
        )

    def _inspector_run_go_parent_from_step(self, st: dict) -> None:
        if not isinstance(st, dict):
            return
        hh = self._duplicate_inspector_recursive_folder_hint(str(st.get("source_path", "") or ""))
        prow = self._planned_move_row_for_folder_source_path(hh)
        if prow is None:
            return
        self._inspector_focus_planned_moves_row(prow)

