        show_other_planned_btn.setToolTip(
            "Select another planned move in this duplicate group and open its row in Planned Moves."
        )
        show_existing_file_btn = QPushButton("Show existing file")
        show_existing_file_btn.setToolTip(
            "In the destination tree, select the existing library file at this exact path (when visible)."
        )
        show_dest_folder_btn = QPushButton("Show target folder")
        show_dest_folder_btn.setToolTip(
            "In the destination tree, expand and select the folder where this row would be placed."
        )
        go_parent_btn = QPushButton("Go to parent folder mapping")
        dup_review_btn = QPushButton("Open duplicate file review…")
        remove_btn = QPushButton("Remove mapping from plan")
        rename_btn = QPushButton("Rename planned destination file…")
        retarget_btn = QPushButton("Retarget planned destination…")
        dup_review_btn.setToolTip(
            "Open the planning duplicate destination hub (same as the Planned Moves banner)."
        )
        for b in (
            show_other_planned_btn,
            show_existing_file_btn,
            show_dest_folder_btn,
            go_parent_btn,
            remove_btn,
            rename_btn,
            retarget_btn,
        ):
            b.setEnabled(False)

        def _deselect_other_rows(keep: ConflictRowWidget | None) -> None:
            for rw in inspector_conflict_rows:
                if rw is not keep:
                    rw.set_selected(False)
            sel_row_widget["rw"] = keep

        def sync_from_conflict_row(rw: ConflictRowWidget | None) -> None:
            if rw is None:
                sel_step_holder["step"] = None
                hint.setText("")
                show_other_planned_btn.setVisible(False)
                show_existing_file_btn.setVisible(False)
                show_other_planned_btn.setEnabled(False)
                show_existing_file_btn.setEnabled(False)
                show_dest_folder_btn.setEnabled(False)
                go_parent_btn.setEnabled(False)
                remove_btn.setEnabled(False)
                rename_btn.setEnabled(False)
                retarget_btn.setEnabled(False)
                return
            st = rw.transfer_step if isinstance(rw.transfer_step, dict) else {}
            sel_step_holder["step"] = st
            if not st:
                hint.setText("")
                show_other_planned_btn.setVisible(False)
                show_existing_file_btn.setVisible(False)
                show_other_planned_btn.setEnabled(False)
                show_existing_file_btn.setEnabled(False)
                show_dest_folder_btn.setEnabled(False)
                go_parent_btn.setEnabled(False)
                remove_btn.setEnabled(False)
                rename_btn.setEnabled(False)
                retarget_btn.setEnabled(False)
                return
            cap = self._inspector_capabilities_for_transfer_step(st)
            rid = cap["rid"]
            pr = cap["pr"]
            is_rec = cap["is_rec"]
            hh = cap["hh"]

            canon_fp = self._inspector_resolve_step_destination_file_path(st)
            has_file_nav = bool(canon_fp)
            parent_fp = self._destination_parent_path(canon_fp) if canon_fp else ""
            has_folder_nav = bool(str(parent_fp or "").strip())

            is_dest = rw.group_kind == "dest"
            ck = str(getattr(rw, "inspector_clash_kind", "") or "")
            peer_pr = getattr(rw, "inspector_peer_planned_pr", None)
            has_real_existing = bool(
                canon_fp and self._inspector_existing_real_file_at_destination_path(canon_fp)
            )

            show_other_planned_btn.setVisible(is_dest and ck in ("planned_path", "both"))
            show_other_planned_btn.setEnabled(
                bool(is_dest and ck in ("planned_path", "both") and peer_pr is not None and cap["can_go"])
            )
            show_existing_file_btn.setVisible(is_dest and ck in ("existing_file", "both"))
            show_existing_file_btn.setEnabled(
                bool(
                    is_dest
                    and ck in ("existing_file", "both")
                    and cap["can_go"]
                    and has_file_nav
                    and has_real_existing
                )
            )
            if is_dest and ck in ("existing_file", "both") and not has_real_existing:
                show_existing_file_btn.setToolTip(
                    "No existing library file is visible at this exact path yet — expand the destination tree or refresh."
                )
            else:
                show_existing_file_btn.setToolTip(
                    "In the destination tree, select the existing library file at this exact path (when visible)."
                )

            show_dest_folder_btn.setEnabled(bool(cap["can_go"] and has_folder_nav))

            go_parent_btn.setEnabled(cap["can_go_parent"])
            go_parent_btn.setToolTip(
                "Open Planned Moves and select the folder mapping that produced this recsub- row."
                if cap["parent_pr"] is not None
                else "No parent folder mapping matched this recursive row."
            )

            remove_btn.setEnabled(cap["can_remove"])
            remove_btn.setToolTip(
                "Remove this planned mapping from the draft (same flow as duplicate file review)."
                if cap["can_remove"]
                else "Select a draft planned row (not a recsub- synthetic file row)."
            )
            rename_btn.setEnabled(cap["can_rename"])
            rename_btn.setToolTip(
                "Rename the planned destination file name (file mappings only)."
                if cap["can_rename"]
                else "Only available for non-submitted file mappings."
            )
            retarget_btn.setEnabled(cap["can_retarget"])
            retarget_btn.setToolTip(
                "Choose a folder in the destination tree on the right (file mappings only)."
                if cap["can_retarget"]
                else "Only available for non-submitted file mappings."
            )

            if is_rec:
                hint.setText(
                    f"Recursive expansion row ({rid}). Parent folder in plan: {hh or '—'}. "
                    "Remove / rename / retarget apply to draft mappings only — use parent folder or duplicate review."
                )
            elif pr is not None:
                hint.setText("Draft planned mapping — mutation actions use the same flows as Duplicate destination files.")
            else:
                hint.setText(
                    "This transfer step does not match a current Planned Moves row; use Show target folder on the right "
                    "or adjust the draft, then retry the run."
                )

        inspector_retarget_tree_hooks: list[tuple[Any, Any]] = []

        def _disconnect_inspector_retarget_tree() -> None:
            for sig, slot in list(inspector_retarget_tree_hooks):
                try:
                    sig.disconnect(slot)
                except (RuntimeError, TypeError):
                    pass
            inspector_retarget_tree_hooks.clear()

        def _exit_inspector_retarget_mode(*, restore_prior_banner: bool = False) -> None:
            was = bool(getattr(self, "_retarget_mode_active", False))
            self._retarget_mode_active = False
            self._retarget_row_index = None
            cancel_retarget_btn.setVisible(False)
            for rw in inspector_conflict_rows:
                rw.set_retarget_highlight(False)
            _disconnect_inspector_retarget_tree()
            if not was:
                return
            if restore_prior_banner and str(inspector_retarget_snapshot.get("text") or "").strip():
                _set_inspector_banner(
                    str(inspector_retarget_snapshot["text"]),
                    str(inspector_retarget_snapshot.get("flavor") or "info"),
                )
            elif restore_prior_banner:
                _dup_insp_hide_banner()

        def _on_dest_pick_for_retarget(item_ref) -> None:
            if not self._retarget_mode_active or self._retarget_row_index is None:
                return
            if self._planning_browse_mode("destination") == "local":
                _set_inspector_banner(
                    "Switch the destination panel to SharePoint (site/library tree), then pick a folder.",
                    "warning",
                )
                return
            pr = int(self._retarget_row_index)
            nd = self.get_tree_item_node_data(item_ref) or {}
            if not self.node_is_manual_drag_destination_folder(nd):
                _set_inspector_banner(
                    "That row is not a valid destination folder — choose another folder.",
                    "warning",
                )
                return
            tp = self._destination_row_semantic_path(nd)
            if 0 <= pr < len(self.planned_moves or []):
                cur = self.planned_moves[pr]
                if tp and self._destination_paths_match_exact(tp, cur.get("destination_path", "")):
                    _set_inspector_banner(
                        "Choose a different folder than the current destination.",
                        "warning",
                    )
                    return
            ok = self._planning_retarget_planned_file_to_folder_node(
                dlg, pr, nd, interactive_confirm=False
            )
            if ok:
                _exit_inspector_retarget_mode(restore_prior_banner=False)
                handle_post_mutation(feedback="Destination retargeted.")

        def _connect_inspector_retarget_tree() -> None:
            _disconnect_inspector_retarget_tree()
            tw = self.destination_tree_widget
            if isinstance(tw, QTreeView):

                def _slot(ix: QModelIndex) -> None:
                    _on_dest_pick_for_retarget(ix)

                tw.clicked.connect(_slot)
                inspector_retarget_tree_hooks.append((tw.clicked, _slot))
            else:

                def _slot2(it: QTreeWidgetItem, _col: int) -> None:
                    _on_dest_pick_for_retarget(it)

                tw.itemClicked.connect(_slot2)
                inspector_retarget_tree_hooks.append((tw.itemClicked, _slot2))

        def _start_inspector_retarget_mode(pr: int) -> None:
            if self._planning_browse_mode("destination") == "local":
                _set_inspector_banner(
                    "Switch the destination panel to SharePoint (site/library tree), then pick a folder.",
                    "warning",
                )
                return
            inspector_retarget_snapshot["text"] = (
                status_banner_text.text() if status_banner.isVisible() else ""
            )
            inspector_retarget_snapshot["flavor"] = str(last_inspector_banner_flavor.get("v") or "info")
            self._retarget_mode_active = True
            self._retarget_row_index = int(pr)
            cancel_retarget_btn.setVisible(True)
            _set_inspector_banner(
                "Select a destination folder to retarget this item",
                "info",
            )
            _clear_inspector_row_highlights()
            for rw in inspector_conflict_rows:
                match = rw.planned_row_index is not None and int(rw.planned_row_index) == int(pr)
                rw.set_retarget_highlight(bool(match))
                if match:
                    _deselect_other_rows(rw)
                    sync_from_conflict_row(rw)
            _connect_inspector_retarget_tree()

        def _dup_insp_clear_failure_state() -> None:
            """Clear row inline failures, selection highlights, and the inspector banner."""
            _exit_inspector_retarget_mode(restore_prior_banner=False)
            inspector_guidance_highlight_pr.clear()
            _dup_insp_hide_banner()
            for rw in inspector_conflict_rows:
                rw.clear_failure()
            _clear_inspector_row_highlights()

        def _clear_inspector_row_highlights() -> None:
            for rw in inspector_conflict_rows:
                rw.set_retarget_highlight(False)
                rw.set_selected(False)

        def _apply_inspector_guidance_highlights() -> None:
            _clear_inspector_row_highlights()
            if not inspector_guidance_highlight_pr:
                return
            for rw in inspector_conflict_rows:
                pr = rw.planned_row_index
                if pr is not None and int(pr) in inspector_guidance_highlight_pr:
                    rw.set_selected(True)
                else:
                    rw.set_selected(False)

        def _scroll_inspector_to_affected_pr(affected: set[int]) -> None:
            if not affected:
                return
            for rw in inspector_conflict_rows:
                pr = rw.planned_row_index
                if pr is None or int(pr) not in affected:
                    continue
                w: QWidget | None = rw
                for _ in range(12):
                    if w is None:
                        break
                    if isinstance(w, DuplicateGroupCard):
                        scroll.ensureWidgetVisible(w)
                        return
                    w = w.parentWidget()
                scroll.ensureWidgetVisible(rw)
                return

        def _focus_inspector_affected_row(affected: set[int]) -> None:
            if not affected:
                return
            for rw in inspector_conflict_rows:
                pr = rw.planned_row_index
                if pr is not None and int(pr) in affected:
                    _deselect_other_rows(rw)
                    sync_from_conflict_row(rw)
                    rw.setFocus(Qt.FocusReason.OtherFocusReason)
                    return

        def handle_post_mutation(
            *, feedback: str | None = None, banner_flavor: str = "info"
        ) -> None:
            _exit_inspector_retarget_mode(restore_prior_banner=False)
            ctx = refresh_context_holder.get("ctx")
            saved_rid = ""
            st_sel = sel_step_holder.get("step")
            if isinstance(st_sel, dict):
                saved_rid = str(st_sel.get("request_id", "") or "").strip()
            new_m = None
            if ctx is not None:
                if ctx.get("kind") == "snapshot_subset":
                    new_m = self._rebuild_inspector_run_manifest_from_refresh_context(ctx)
                    if new_m is None:
                        _set_inspector_banner(
                            "Could not refresh this collision view automatically (subset/recursive context, sign-in, "
                            "Graph expansion, or Planned Moves selection). Close this panel when ready and retry the run "
                            "from the workspace.",
                            "warning",
                        )
                        return
                elif ctx.get("kind") == "none":
                    new_m = self._inspector_build_fresh_simulation_manifest_snapshot()
            if new_m is None:
                eo = dict((manifest_holder.get("m") or {}).get("execution_options") or {})
                if self._inspector_execution_options_allow_draft_manifest_refresh(eo):
                    new_m = self._inspector_build_fresh_simulation_manifest_snapshot()
            if new_m is None:
                self._inspector_close_after_plan_mutation(dlg)
                return
            dup_err = self._transfer_manifest_duplicate_validation_error(new_m)
            manifest_holder["m"] = new_m
            if not dup_err:
                inspector_guidance_highlight_pr.clear()
                pending_inspector_auto_fix.clear()
                while host_layout.count():
                    item = host_layout.takeAt(0)
                    w = item.widget()
                    if w is not None:
                        w.deleteLater()
                inspector_conflict_rows.clear()
                inspector_dest_suffix_groups.clear()
                done_lbl = QLabel(
                    "This manifest no longer reports duplicate collisions for the current run context. "
                    "Close when you are ready, then retry the run from the workspace."
                )
                done_lbl.setObjectName("MutedText")
                done_lbl.setWordWrap(True)
                host_layout.addWidget(done_lbl)
                host_layout.addStretch(1)
                scroll.setWidget(host)
                title_label.setText("Collisions resolved")
                subtitle_label.setText("No further repair steps are required here.")
                summary_auto_fix_all_btn.setEnabled(False)
                _set_inspector_banner(
                    "Duplicates are cleared for this run — you can close this panel and retry execution.",
                    "success",
                )
                sel_step_holder["step"] = None
                hint.setText("")
                for b in (
                    show_other_planned_btn,
                    show_existing_file_btn,
                    show_dest_folder_btn,
                    go_parent_btn,
                    remove_btn,
                    rename_btn,
                    retarget_btn,
                ):
                    b.setEnabled(False)
                return
            rebuild_collision_tables()
            sel_step_holder["step"] = None
            hint.setText("")
            for b in (
                show_other_planned_btn,
                show_existing_file_btn,
                show_dest_folder_btn,
                go_parent_btn,
                remove_btn,
                rename_btn,
                retarget_btn,
            ):
                b.setEnabled(False)
            restored = False
            if saved_rid:
                for rw in inspector_conflict_rows:
                    st2 = rw.transfer_step if isinstance(rw.transfer_step, dict) else {}
                    if str(st2.get("request_id", "") or "").strip() == saved_rid:
                        _deselect_other_rows(rw)
                        sync_from_conflict_row(rw)
                        restored = True
                        break
            if not restored and inspector_conflict_rows:
                _deselect_other_rows(inspector_conflict_rows[0])
                sync_from_conflict_row(inspector_conflict_rows[0])
            if feedback:
                _set_inspector_banner(feedback, banner_flavor)
            elif ctx is not None and ctx.get("kind") == "snapshot_subset":
                _set_inspector_banner(
                    "Collision groups refreshed — same subset/recursive options and current draft.",
                    "info",
                )
            elif ctx is not None and ctx.get("kind") == "none":
                _set_inspector_banner("Collision groups refreshed.", "info")
            else:
                _set_inspector_banner(
                    "Collision groups refreshed. Subset, pilot, or recursive run context may not match this preview.",
                    "info",
                )
            _apply_inspector_guidance_highlights()
            _retry_pending_inspector_auto_fix()

        def _pr_rids_from_inspector_indices(idxs: list[int]) -> frozenset[str]:
            pm = self.planned_moves or []
            out: list[str] = []
            for i in idxs:
                try:
                    ii = int(i)
                except (TypeError, ValueError):
                    continue
                if 0 <= ii < len(pm):
                    rid = str((pm[ii] or {}).get("request_id", "") or "").strip()
                    if rid:
                        out.append(rid)
            return frozenset(out)

        def _find_inspector_retry_dest_group_for_rids(target_rids: frozenset[str]) -> list[int] | None:
            if len(target_rids) < 2:
                return None
            best: list[int] | None = None
            score = 0
            for g in inspector_dest_suffix_groups:
                g_rids = _pr_rids_from_inspector_indices(list(g))
                inter = len(target_rids & g_rids)
                if inter >= 2 and inter > score:
                    score = inter
                    best = list(g)
            return best

        def _register_pending_inspector_group_retry(rows_snapshot: list[dict]) -> None:
            pending_inspector_auto_fix.clear()
            idxs = []
            for r in rows_snapshot or []:
                try:
                    idxs.append(int(r["index"]))
                except (KeyError, TypeError, ValueError):
                    continue
            pending_inspector_auto_fix["kind"] = "group"
            pending_inspector_auto_fix["rids"] = _pr_rids_from_inspector_indices(idxs)

        def _register_pending_inspector_all_retry() -> None:
            pending_inspector_auto_fix.clear()
            pending_inspector_auto_fix["kind"] = "all"

        def _clear_inspector_auto_pending() -> None:
            pending_inspector_auto_fix.clear()

        def _retry_pending_inspector_auto_fix() -> None:
            if not pending_inspector_auto_fix:
                return
            kind = pending_inspector_auto_fix.get("kind")
            if kind == "all":
                groups = list(inspector_dest_suffix_groups)
                if not groups:
                    _clear_inspector_auto_pending()
                    return
                rows = self._build_execution_inspector_chained_dest_suffix_preview_rows(groups)
                if not rows:
                    _clear_inspector_auto_pending()
                    return
                ok, err, st = self._planning_apply_duplicate_preview_rows(
                    rows,
                    dlg,
                    change_note="execution_inspector_dest_suffix_all_retry",
                    suppress_submitted_lock_modal=True,
                )
                if ok:
                    _clear_inspector_auto_pending()
                    _dup_insp_clear_failure_state()
                    handle_post_mutation(
                        feedback=f"Suggested names applied to {len(rows)} items (auto-retry)."
                    )
                elif err == "locked":
                    _clear_inspector_auto_pending()
                    if st:
                        _dup_insp_apply_failure_state(st, register_pending="all")
                elif st:
                    _dup_insp_apply_failure_state(
                        st,
                        register_pending="all",
                    )
            elif kind == "group":
                target = pending_inspector_auto_fix.get("rids")
                if not isinstance(target, frozenset):
                    _clear_inspector_auto_pending()
                    return
                g = _find_inspector_retry_dest_group_for_rids(target)
                if not g or len(g) < 2:
                    _clear_inspector_auto_pending()
                    return
                rows = self._build_execution_inspector_dest_suffix_preview_rows_for_moves(sorted(g))
                if not rows:
                    _clear_inspector_auto_pending()
                    return
                ok, err, st = self._planning_apply_duplicate_preview_rows(
                    rows,
                    dlg,
                    change_note="execution_inspector_dest_suffix_group_retry",
                    suppress_submitted_lock_modal=True,
                )
                if ok:
                    _clear_inspector_auto_pending()
                    _dup_insp_clear_failure_state()
                    handle_post_mutation(
                        feedback=f"Suggested names applied to {len(rows)} items (auto-retry)."
                    )
                elif err == "locked":
                    _clear_inspector_auto_pending()
                    if st:
                        _dup_insp_apply_failure_state(
                            st,
                            register_pending="group",
                            pending_rows=rows,
                        )
                elif st:
                    _dup_insp_apply_failure_state(
                        st,
                        register_pending="group",
                        pending_rows=rows,
                    )

        def _inspector_inline_retarget(p: int) -> None:
            _start_inspector_retarget_mode(int(p))

        def _inspector_inline_remove(p: int) -> None:
            if self._planning_remove_planned_move_with_confirm(dlg, p):
                handle_post_mutation(feedback="Mapping removed from plan.")

        def _inspector_inline_rename_planned(pidx: int) -> None:
            if self._planning_rename_planned_file_with_dialog(dlg, pidx):
                handle_post_mutation(feedback="1 rename applied.")

        def apply_suggested_rename_for_planned_index(pidx: int) -> None:
            group_prs = None
            for gg in inspector_dest_suffix_groups:
                if pidx in gg:
                    group_prs = gg
                    break
            rows_f = self._build_execution_inspector_dest_suffix_preview_rows_for_moves(
                sorted(group_prs or [pidx])
            )
            row_one = next(
                (r for r in (rows_f or []) if int(r["index"]) == int(pidx)),
                None,
            )
            if not row_one or not str(row_one.get("suggested_leaf", "") or "").strip():
                st2 = self._duplicate_apply_structured_failure(
                    [{"index": pidx, "suggested_leaf": ""}],
                    "Could not build a suggested name for this row.",
                    bulk=False,
                )
                st2["reason"] = "no_rows"
                _dup_insp_apply_failure_state(
                    st2,
                    register_pending="group" if group_prs and len(group_prs) >= 2 else None,
                    pending_rows=rows_f,
                )
                return
            ve = self._validate_duplicate_group_apply_preview_rows([row_one])
            if ve:
                st3 = self._duplicate_apply_structured_failure([row_one], ve, bulk=False)
                _dup_insp_apply_failure_state(
                    st3,
                    register_pending="group"
                    if group_prs and len(group_prs) >= 2
                    else None,
                    pending_rows=rows_f or [row_one],
                )
                return
            ok2, err2, st4 = self._planning_apply_duplicate_preview_rows(
                [row_one],
                dlg,
                change_note="execution_inspector_dest_suffix_one",
                suppress_submitted_lock_modal=True,
            )
            if ok2:
                _dup_insp_clear_failure_state()
                _clear_inspector_auto_pending()
                handle_post_mutation(feedback="1 rename applied.")
            elif st4:
                _dup_insp_apply_failure_state(
                    st4,
                    register_pending="group"
                    if group_prs and len(group_prs) >= 2
                    else None,
                    pending_rows=rows_f or [row_one],
                )

        def _dup_insp_apply_failure_state(
            struct: dict,
            *,
            register_pending: str | None = None,
            pending_rows: list[dict] | None = None,
        ) -> None:
            """Coordinator: maps structured apply failures to row inline UI + inspector banner + focus."""
            affected = {int(x) for x in (struct.get("affected_indices") or []) if x is not None}
            inspector_guidance_highlight_pr.clear()
            inspector_guidance_highlight_pr.update(affected)
            banner = "Some automatic renames could not be applied — details are on each row below."
            if not affected:
                banner = (
                    str(struct.get("message") or struct.get("suggested_fix") or "").strip() or banner
                )
            _set_inspector_banner(banner, "warning" if affected else "info")
            for rw in inspector_conflict_rows:
                rw.clear_failure()
            pm = self.planned_moves or []

            def _disconnect_btn(btn: QPushButton) -> None:
                try:
                    btn.clicked.disconnect()
                except (RuntimeError, TypeError):
                    pass

            for rw in inspector_conflict_rows:
                pr = rw.planned_row_index
                if pr is None:
                    continue
                pri = int(pr)
                if pri not in affected:
                    continue
                if pri < 0 or pri >= len(pm):
                    continue
                mv = pm[pri]
                src = mv.get("source") if isinstance(mv.get("source"), dict) else {}
                is_folder = bool((src or {}).get("is_folder"))
                submitted = self._is_move_submitted(mv)
                file_row = not is_folder and not submitted
                title, sentence, sug = self._dup_insp_inline_failure_headline_detail(
                    struct, planned_row_index=pri
                )
                rename_label = self._dup_insp_inline_rename_button_label(sug)
                rename_tt = sug if sug and "…" in rename_label else ""
                fail_reason = str(struct.get("reason") or "unknown")
                bo, rn_rl, rt_rl, rm_rl = self._dup_insp_inline_action_priorities(fail_reason)
                rw.set_failure_ui(
                    title=title,
                    detail=sentence,
                    show_inline_rename=file_row,
                    show_retarget=file_row,
                    show_remove=file_row,
                    rename_button_label=rename_label,
                    rename_button_tooltip=rename_tt,
                    button_order=bo,
                    rename_button_role=rn_rl,
                    retarget_button_role=rt_rl,
                    remove_button_role=rm_rl,
                )
                rw.apply_inspector_inline_failure_alignment(title, sentence)
                ir = rw.inline_reason_block
                _disconnect_btn(ir.inline_rename_btn)
                _disconnect_btn(ir.inline_retarget_btn)
                _disconnect_btn(ir.inline_remove_btn)
                if sug:
                    ir.inline_rename_btn.clicked.connect(
                        lambda checked=False, p=pri: apply_suggested_rename_for_planned_index(p)
                    )
                else:
                    ir.inline_rename_btn.clicked.connect(
                        lambda checked=False, p=pri: _inspector_inline_rename_planned(p)
                    )
                ir.inline_retarget_btn.clicked.connect(
                    lambda checked=False, p=pri: _inspector_inline_retarget(p)
                )
                ir.inline_remove_btn.clicked.connect(
                    lambda checked=False, p=pri: _inspector_inline_remove(p)
                )
            if register_pending == "group" and pending_rows:
                _register_pending_inspector_group_retry(pending_rows)
            elif register_pending == "all":
                _register_pending_inspector_all_retry()
            _scroll_inspector_to_affected_pr(affected)
            _focus_inspector_affected_row(affected)
            _apply_inspector_guidance_highlights()

        def wire_conflict_row(
            rw: ConflictRowWidget,
            *,
            kind: str,
            group_prs: list[int],
        ) -> None:
            def on_context_menu(pos) -> None:
                st = rw.transfer_step
                if not isinstance(st, dict):
                    return
                _deselect_other_rows(rw)
                sync_from_conflict_row(rw)
                cap = self._inspector_capabilities_for_transfer_step(st)
                canon_ctx = self._inspector_resolve_step_destination_file_path(st)
                parent_ctx = self._destination_parent_path(canon_ctx) if canon_ctx else ""
                has_file_ctx = bool(canon_ctx)
                has_folder_ctx = bool(str(parent_ctx or "").strip())
                nav_ok = bool(cap["can_go"])
                rw_ck = str(getattr(rw, "inspector_clash_kind", "") or "")
                rw_peer = getattr(rw, "inspector_peer_planned_pr", None)
                is_dest = kind == "dest"
                has_real_ctx = bool(
                    canon_ctx and self._inspector_existing_real_file_at_destination_path(canon_ctx)
                )
                menu = QMenu(rw)
                if kind == "dest":
                    m_manual = menu.addMenu("Manual edits")
                    a_op = m_manual.addAction("Show other planned row")
                    a_sef = m_manual.addAction("Show existing file")
                    a_sf = m_manual.addAction("Show target folder")
                    a_par = m_manual.addAction("Go to parent folder mapping")
                    a_dup = m_manual.addAction("Open duplicate file review…")
                    m_manual.addSeparator()
                    a_rm = m_manual.addAction("Remove mapping from plan")
                    a_rn = m_manual.addAction("Rename planned destination file…")
                    a_rt = m_manual.addAction("Retarget planned destination…")
                else:
                    a_op = menu.addAction("Show other planned row")
                    a_sef = menu.addAction("Show existing file")
                    a_sf = menu.addAction("Show target folder")
                    a_par = menu.addAction("Go to parent folder mapping")
                    a_dup = menu.addAction("Open duplicate file review…")
                    menu.addSeparator()
                    a_rm = menu.addAction("Remove mapping from plan")
                    a_rn = menu.addAction("Rename planned destination file…")
                    a_rt = menu.addAction("Retarget planned destination…")
                a_op.setVisible(is_dest and rw_ck in ("planned_path", "both"))
                a_op.setEnabled(bool(is_dest and rw_ck in ("planned_path", "both") and nav_ok and rw_peer is not None))
                a_sef.setVisible(is_dest and rw_ck in ("existing_file", "both"))
                a_sef.setEnabled(
                    bool(
                        is_dest
                        and rw_ck in ("existing_file", "both")
                        and nav_ok
                        and has_file_ctx
                        and has_real_ctx
                    )
                )
                a_sf.setVisible(nav_ok and has_folder_ctx)
                a_sf.setEnabled(nav_ok and has_folder_ctx)
                a_par.setEnabled(cap["can_go_parent"])
                if cap["is_rec"]:
                    a_rm.setVisible(False)
                    a_rn.setVisible(False)
                    a_rt.setVisible(False)
                else:
                    a_rm.setEnabled(cap["can_remove"])
                    a_rn.setEnabled(cap["can_rename"])
                    a_rt.setEnabled(cap["can_retarget"])
                a_one_suffix = None
                a_grp_suffix = None
                a_all_suffix = None
                if kind == "dest":
                    m_auto = menu.addMenu("Automated fixes")
                    a_one_suffix = m_auto.addAction("Rename…")
                    a_grp_suffix = m_auto.addAction("Auto-fix group")
                    gprs = group_prs
                    a_grp_suffix.setEnabled(bool(gprs) and len(gprs) >= 2)
                    a_one_suffix.setEnabled(bool(cap.get("can_rename")) and bool(gprs) and len(gprs) >= 2)
                    menu.addSeparator()
                    a_all_suffix = menu.addAction("Auto-fix all")
                picked = menu.exec(rw.mapToGlobal(pos))
                if picked == a_op and is_dest and rw_ck in ("planned_path", "both") and nav_ok and rw_peer is not None:
                    otr = int(rw_peer)
                    for orw in inspector_conflict_rows:
                        if orw.planned_row_index is not None and int(orw.planned_row_index) == otr:
                            _deselect_other_rows(orw)
                            orw.set_selected(True)
                            sync_from_conflict_row(orw)
                            scroll.ensureWidgetVisible(orw)
                            break
                    self._inspector_focus_planned_moves_row(otr)
                    _set_inspector_banner("Showing the other planned row for this duplicate group.", "info")
                elif picked == a_sef and is_dest and rw_ck in ("existing_file", "both") and nav_ok and has_real_ctx:
                    self._inspector_navigate_existing_destination_file_for_step(
                        st,
                        on_banner_fail=lambda m: _set_inspector_banner(m, "warning"),
                        on_banner_info=lambda t: _set_inspector_banner(t, "info"),
                    )
                    sync_from_conflict_row(rw)
                elif picked == a_sf and nav_ok and has_folder_ctx:
                    self._inspector_navigate_destination_for_step(
                        st,
                        mode="folder",
                        on_banner_fail=lambda m: _set_inspector_banner(m, "warning"),
                        success_banner="Showing target folder for this row",
                        on_banner_info=lambda t: _set_inspector_banner(t, "info"),
                    )
                    sync_from_conflict_row(rw)
                elif picked == a_par and cap["can_go_parent"]:
                    self._inspector_run_go_parent_from_step(st)
                elif picked == a_dup:
                    self._show_duplicate_destination_file_review_dialog(
                        launched_from_execution_duplicate_inspector=True
                    )
                elif picked == a_rm and cap["can_remove"] and cap["pr"] is not None:
                    if self._planning_remove_planned_move_with_confirm(dlg, cap["pr"]):
                        handle_post_mutation(feedback="Mapping removed from plan.")
                elif picked == a_rn and cap["can_rename"] and cap["pr"] is not None:
                    if self._planning_rename_planned_file_with_dialog(dlg, cap["pr"]):
                        handle_post_mutation(feedback="1 rename applied.")
                elif picked == a_rt and cap["can_retarget"] and cap["pr"] is not None:
                    _start_inspector_retarget_mode(int(cap["pr"]))
                elif (
                    picked == a_one_suffix
                    and a_one_suffix is not None
                    and cap["can_rename"]
                    and cap["pr"] is not None
                ):
                    gprs = group_prs
                    if gprs and len(gprs) >= 2:
                        rows_full = self._build_execution_inspector_dest_suffix_preview_rows_for_moves(
                            sorted(gprs)
                        )
                        row_one = next(
                            (r for r in (rows_full or []) if int(r["index"]) == int(cap["pr"])),
                            None,
                        )
                        if not row_one:
                            st_nf = self._duplicate_apply_structured_failure(
                                [{"index": int(cap["pr"]), "suggested_leaf": ""}],
                                "Could not build a suggested name for this row.",
                                bulk=False,
                            )
                            st_nf["reason"] = "no_rows"
                            pr_stub = [{"index": int(i), "suggested_leaf": ""} for i in sorted(gprs)]
                            _dup_insp_apply_failure_state(
                                st_nf,
                                register_pending="group",
                                pending_rows=pr_stub,
                            )
                        else:
                            v_err_one = self._validate_duplicate_group_apply_preview_rows([row_one])
                            if v_err_one:
                                st_ve = self._duplicate_apply_structured_failure(
                                    [row_one], v_err_one, bulk=False
                                )
                                _dup_insp_apply_failure_state(
                                    st_ve,
                                    register_pending="group",
                                    pending_rows=rows_full or [row_one],
                                )
                            else:
                                ok, err, st_apply = self._planning_apply_duplicate_preview_rows(
                                    [row_one],
                                    dlg,
                                    change_note="execution_inspector_dest_suffix_one",
                                    suppress_submitted_lock_modal=True,
                                )
                                if not ok and st_apply:
                                    _dup_insp_apply_failure_state(
                                        st_apply,
                                        register_pending="group",
                                        pending_rows=rows_full or [row_one],
                                    )
                                elif ok:
                                    _dup_insp_clear_failure_state()
                                    _clear_inspector_auto_pending()
                                    handle_post_mutation(feedback="1 rename applied.")
                elif picked == a_grp_suffix and a_grp_suffix is not None:
                    gprs = group_prs
                    if gprs and len(gprs) >= 2:
                        rows = self._build_execution_inspector_dest_suffix_preview_rows_for_moves(
                            sorted(gprs)
                        )
                        pr_stub = [{"index": int(i), "suggested_leaf": ""} for i in sorted(gprs)]
                        if not rows:
                            st_b = self._duplicate_apply_structured_failure(
                                pr_stub,
                                "Could not build unique names for this group.",
                                bulk=True,
                            )
                            st_b["reason"] = "no_rows"
                            _dup_insp_apply_failure_state(
                                st_b,
                                register_pending="group",
                                pending_rows=pr_stub,
                            )
                        else:
                            rows2 = self._build_execution_inspector_dest_suffix_preview_rows_for_moves(
                                sorted(gprs)
                            )
                            if not rows2 or len(rows2) != len(rows):
                                st_ch = self._duplicate_apply_structured_failure(
                                    rows,
                                    "Suggestions changed before apply; try again.",
                                    bulk=True,
                                )
                                _dup_insp_apply_failure_state(
                                    st_ch,
                                    register_pending="group",
                                    pending_rows=rows,
                                )
                            else:
                                ok, err, st_apply = self._planning_apply_duplicate_preview_rows(
                                    rows2,
                                    dlg,
                                    change_note="execution_inspector_dest_suffix_group",
                                    suppress_submitted_lock_modal=True,
                                )
                                if not ok and st_apply:
                                    _dup_insp_apply_failure_state(
                                        st_apply,
                                        register_pending="group",
                                        pending_rows=rows2,
                                    )
                                elif ok:
                                    _dup_insp_clear_failure_state()
                                    _clear_inspector_auto_pending()
                                    handle_post_mutation(
                                        feedback=f"Suggested names applied to {len(rows2)} items."
                                    )
                elif picked == a_all_suffix and a_all_suffix is not None:
                    on_apply_all_dest_suffix_groups()

            rw.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
            rw.customContextMenuRequested.connect(on_context_menu)

            def _on_row_clicked() -> None:
                _deselect_other_rows(rw)
                rw.set_selected(True)
                sync_from_conflict_row(rw)

            rw.row_clicked.connect(_on_row_clicked)

        def rebuild_collision_tables() -> None:
            nonlocal inspector_conflict_rows
            inspector_dest_suffix_groups.clear()
            _update_subset_note_text()
            scroll_y = scroll.verticalScrollBar().value()
            while host_layout.count():
                item = host_layout.takeAt(0)
                w = item.widget()
                if w is not None:
                    w.deleteLater()
            inspector_conflict_rows = []

            def _elide_middle(text: str, max_len: int = 72) -> str:
                t = str(text or "")
                if len(t) <= max_len:
                    return t
                half = (max_len - 3) // 2
                return t[:half] + "…" + t[-(max_len - half - 3) :]

            m = manifest_holder.get("m") or {}
            steps = list(m.get("transfer_steps") or [])
            dest_groups = duplicate_transfer_step_groups_by_destination(steps)
            src_groups = duplicate_transfer_step_groups_by_source(steps)

            def add_grouped_section(title: str, groups: list, kind: str) -> None:
                if not groups:
                    return
                sec_title = QLabel(title)
                sec_title.setObjectName("SectionTitle")
                host_layout.addWidget(sec_title)
                for _nk, display_key, members in groups:
                    card = DuplicateGroupCard()
                    display_s = str(display_key or "").strip() or "(unknown)"
                    card.destination_path_label.setText(_elide_middle(display_s, 80))
                    card.destination_path_label.setToolTip(display_s)
                    if kind == "dest":
                        pix = card.style().standardPixmap(QStyle.StandardPixmap.SP_DirIcon)
                    else:
                        pix = card.style().standardPixmap(QStyle.StandardPixmap.SP_FileIcon)
                    card.icon_label.setPixmap(pix.scaled(18, 18, Qt.AspectRatioMode.KeepAspectRatio))

                    pr_row_indices: list[int] = []
                    preview_by_pr: dict[int, str] = {}
                    if kind == "dest":
                        for st in members:
                            if not isinstance(st, dict):
                                continue
                            rid = str(st.get("request_id", "") or "").strip()
                            if rid.startswith("recsub-"):
                                continue
                            pr = self._planned_move_table_row_for_transfer_request_id(rid)
                            if pr is None:
                                continue
                            if pr < 0 or pr >= len(self.planned_moves or []):
                                continue
                            move = self.planned_moves[pr]
                            if bool((move.get("source") or {}).get("is_folder")):
                                continue
                            if self._is_move_submitted(move):
                                continue
                            pr_row_indices.append(int(pr))
                        pr_row_indices = sorted(set(pr_row_indices))
                        if len(pr_row_indices) >= 2:
                            inspector_dest_suffix_groups.append(pr_row_indices)
                            prev_rows = self._build_execution_inspector_dest_suffix_preview_rows_for_moves(
                                sorted(pr_row_indices)
                            )
                            for rpv in pr_row_indices:
                                row_m = next(
                                    (r for r in (prev_rows or []) if int(r["index"]) == int(rpv)),
                                    None,
                                )
                                if row_m:
                                    preview_by_pr[rpv] = str(row_m.get("suggested_leaf", "") or "").strip()
                    card.dup_dest_prs = list(pr_row_indices)

                    if kind != "dest":
                        card.group_auto_fix_btn.setVisible(False)
                    else:

                        def _make_group_apply(prs: list[int]):
                            def on_group_apply(_checked: bool = False) -> None:
                                _ = _checked
                                if len(prs) < 2:
                                    return
                                rows = self._build_execution_inspector_dest_suffix_preview_rows_for_moves(
                                    sorted(prs)
                                )
                                pr_stub = [{"index": int(i), "suggested_leaf": ""} for i in sorted(prs)]
                                if not rows:
                                    st_b = self._duplicate_apply_structured_failure(
                                        pr_stub,
                                        "Could not build unique names for this group.",
                                        bulk=True,
                                    )
                                    st_b["reason"] = "no_rows"
                                    _dup_insp_apply_failure_state(
                                        st_b,
                                        register_pending="group",
                                        pending_rows=pr_stub,
                                    )
                                    return
                                rows2 = self._build_execution_inspector_dest_suffix_preview_rows_for_moves(
                                    sorted(prs)
                                )
                                if not rows2 or len(rows2) != len(rows):
                                    st_ch = self._duplicate_apply_structured_failure(
                                        rows,
                                        "Suggestions changed before apply; try again.",
                                        bulk=True,
                                    )
                                    _dup_insp_apply_failure_state(
                                        st_ch,
                                        register_pending="group",
                                        pending_rows=rows,
                                    )
                                    return
                                ok, err, st_apply = self._planning_apply_duplicate_preview_rows(
                                    rows2,
                                    dlg,
                                    change_note="execution_inspector_dest_suffix_group",
                                    suppress_submitted_lock_modal=True,
                                )
                                if not ok and st_apply:
                                    _dup_insp_apply_failure_state(
                                        st_apply,
                                        register_pending="group",
                                        pending_rows=rows2,
                                    )
                                elif ok:
                                    _dup_insp_clear_failure_state()
                                    _clear_inspector_auto_pending()
                                    handle_post_mutation(
                                        feedback=f"Suggested names applied to {len(rows2)} items."
                                    )

                            return on_group_apply

                        card.group_auto_fix_btn.setEnabled(len(pr_row_indices) >= 2)
                        card.group_auto_fix_btn.setToolTip(
                            "Assign stem.ext, stem (2).ext, ... using the first row's base name (planning-only)."
                            if len(pr_row_indices) >= 2
                            else "At least two draft file mappings are required in this group.",
                        )
                        card.group_auto_fix_btn.clicked.connect(_make_group_apply(list(pr_row_indices)))

                    scoped_ids = _current_scoped_ids()
                    row_widgets: list[ConflictRowWidget] = []
                    for st in members:
                        if not isinstance(st, dict):
                            continue
                        rw = ConflictRowWidget()
                        rw.apply_file_icon(rw.style())
                        rw.transfer_step = st
                        rw.group_kind = kind
                        rid = str(st.get("request_id", "") or "").strip()
                        pr = self._planned_move_table_row_for_transfer_request_id(rid)
                        rw.planned_row_index = int(pr) if pr is not None else None
                        rw.dup_group_prs = list(pr_row_indices) if kind == "dest" else []
                        cap = self._inspector_capabilities_for_transfer_step(st)
                        incoming_name = (
                            str(st.get("source_name", "") or "").strip()
                            or str(st.get("destination_name", "") or "").strip()
                            or "(unnamed)"
                        )
                        dest_leaf = str(st.get("destination_name", "") or "").strip() or incoming_name
                        dest_p = str(st.get("destination_path", "") or "").strip()
                        canon_fp = self._inspector_resolve_step_destination_file_path(st)
                        parent_raw = self._destination_parent_path(canon_fp) if canon_fp else ""
                        folder_display = _elide_middle(
                            self.normalize_memory_path(str(parent_raw or "").strip()),
                            96,
                        )
                        if not str(folder_display or "").strip():
                            folder_display = "—"

                        idx = int(st.get("index", -1))
                        in_sub = "Yes" if rid in scoped_ids else "No"
                        prov = "Recursive" if rid.startswith("recsub-") else "Planned"
                        pidx = rw.planned_row_index
                        sug = ""
                        if pidx is not None:
                            sug = preview_by_pr.get(int(pidx), "")
                        can_suffix = (
                            bool(kind == "dest")
                            and bool(cap.get("can_rename"))
                            and len(pr_row_indices) >= 2
                            and pidx is not None
                        )

                        rw.inspector_clash_kind = ""
                        rw.inspector_peer_planned_pr = None
                        if kind == "source":
                            rw.inspector_clash_kind = "source"
                            prob = "Same source file is planned to more than one destination."
                            conf_line = (
                                f"Conflict: this source maps to multiple destination paths "
                                f"(see group header). Step {idx} · {prov} · In run subset: {in_sub}"
                            )
                        elif not dest_p.strip():
                            prob = "Destination path is missing or not usable yet."
                            conf_line = (
                                f"Conflict: cannot resolve target folder for this row. "
                                f"Step {idx} · {prov} · In run subset: {in_sub}"
                            )
                        else:
                            peer_pr: int | None = None
                            if pidx is not None:
                                for q in pr_row_indices:
                                    if int(q) != int(pidx):
                                        peer_pr = int(q)
                                        break
                            elif pr_row_indices:
                                peer_pr = int(pr_row_indices[0])
                            has_peer = len(pr_row_indices) >= 2
                            has_existing = bool(
                                canon_fp and self._inspector_existing_real_file_at_destination_path(canon_fp)
                            )
                            if has_peer and has_existing:
                                rw.inspector_clash_kind = "both"
                            elif has_existing:
                                rw.inspector_clash_kind = "existing_file"
                            else:
                                rw.inspector_clash_kind = "planned_path"
                            rw.inspector_peer_planned_pr = peer_pr

                            dk_raw = transfer_step_file_destination_key(st) or ""
                            path_for_msg = (
                                self._canonical_destination_projection_path(str(dk_raw).strip())
                                or self.normalize_memory_path(str(dk_raw).strip())
                                or canon_fp
                            )
                            file_path_disp = _elide_middle(path_for_msg, 96) if path_for_msg else "—"

                            if rw.inspector_clash_kind == "planned_path":
                                prob = "Planned destination path overlap."
                                conf_line = (
                                    "Another planned move targets this same final destination path.\n"
                                    f"Target path: {file_path_disp}"
                                )
                            elif rw.inspector_clash_kind == "existing_file":
                                prob = "Existing destination file."
                                conf_line = (
                                    "A file already exists at this exact destination path.\n"
                                    f"Existing file path: {file_path_disp}"
                                )
                            else:
                                prob = "Planned overlap and existing destination file."
                                conf_line = (
                                    "This target path is already used by another planned row and also exists "
                                    f"in the destination.\nTarget path: {file_path_disp}"
                                )

                        if kind == "source" or not dest_p.strip():
                            if sug:
                                fix_line = f'Fix: Rename incoming file to "{sug}"'
                            elif can_suffix and cap.get("can_rename"):
                                fix_line = (
                                    "Fix: Use Rename… (planner can suggest a unique name in this group)."
                                )
                            elif cap.get("can_rename") and pidx is not None:
                                fix_line = "Fix: Use Rename… to change the planned destination file name."
                            else:
                                fix_line = (
                                    "Fix: Use Retarget…, Remove, or duplicate review where available."
                                )
                        elif sug:
                            fix_line = f'Fix: Rename incoming file to "{sug}"'
                        elif rw.inspector_clash_kind == "planned_path":
                            if can_suffix and cap.get("can_rename"):
                                fix_line = (
                                    "Fix: Rename or retarget one of the planned rows — or use Rename… for a "
                                    "planner suggestion."
                                )
                            else:
                                fix_line = "Fix: Rename or retarget one of the planned rows."
                        elif rw.inspector_clash_kind == "existing_file":
                            if can_suffix and cap.get("can_rename"):
                                fix_line = (
                                    "Fix: Rename the incoming file or retarget it — or use Rename… for a suggestion."
                                )
                            else:
                                fix_line = "Fix: Rename the incoming file or retarget it."
                        else:
                            if can_suffix and cap.get("can_rename"):
                                fix_line = (
                                    "Fix: Adjust planned rows or the incoming mapping (Rename… / Retarget… / Remove)."
                                )
                            else:
                                fix_line = "Fix: Rename or retarget planned rows, or rename / retarget this mapping."

                        folder_line = f"Target folder: {folder_display}"
                        meta_line = f"Step {idx} · {prov} · In run subset: {in_sub}"
                        detail_body = "\n".join([folder_line, conf_line, fix_line, meta_line])
                        file_line = f"Incoming file: {incoming_name}"

                        rw.set_inspector_row_baselines(
                            file_line=file_line,
                            problem_line=prob,
                            detail_block=detail_body,
                            folder_line=folder_line,
                            fix_line=fix_line,
                        )

                        if kind == "source":
                            badge = "Source clash"
                        elif not dest_p.strip():
                            badge = "Dest. clash"
                        elif rw.inspector_clash_kind == "both":
                            badge = "Plan + exists"
                        elif rw.inspector_clash_kind == "existing_file":
                            badge = "Exists"
                        else:
                            badge = "Planned dup"
                        rw.row_state_badge.setText(badge)
                        if cap.get("can_rename") and sug and len(sug) < 32:
                            rw.rename_btn.setText(f'Rename to "{sug}"')
                        else:
                            rw.rename_btn.setText("Rename…")
                        if can_suffix and sug:
                            rw.rename_btn.setToolTip(
                                f"Apply the planner's suggested destination file name: {sug}"
                            )
                        elif cap.get("can_rename") and pidx is not None:
                            rw.rename_btn.setToolTip(
                                "Open the rename dialog to edit the planned destination file name."
                            )
                        else:
                            rw.rename_btn.setToolTip("")
                        rw.rename_btn.setEnabled(
                            can_suffix or bool(cap.get("can_rename") and pidx is not None)
                        )

                        def _row_rename_clicked(_checked: bool = False) -> None:
                            _ = _checked
                            if not isinstance(rw, ConflictRowWidget):
                                log_warn(
                                    "duplicate_inspector_row_rename",
                                    event="invalid_row_widget",
                                )
                                return
                            pi = rw.planned_row_index
                            if pi is None:
                                log_warn(
                                    "duplicate_inspector_row_rename",
                                    event="missing_planned_row_index",
                                )
                                return
                            if (
                                kind == "dest"
                                and len(pr_row_indices) >= 2
                                and cap.get("can_rename")
                            ):
                                apply_suggested_rename_for_planned_index(int(pi))
                            elif cap.get("can_rename"):
                                if self._planning_rename_planned_file_with_dialog(dlg, int(pi)):
                                    handle_post_mutation(feedback="1 rename applied.")

                        rw.rename_btn.clicked.connect(_row_rename_clicked)

                        more_m = QMenu(rw)
                        a_rt = more_m.addAction("Retarget…")
                        a_rm = more_m.addAction("Remove")
                        more_m.addSeparator()
                        canon_m = self._inspector_resolve_step_destination_file_path(st)
                        parent_m = self._destination_parent_path(canon_m) if canon_m else ""
                        has_file_m = bool(canon_m)
                        has_folder_m = bool(str(parent_m or "").strip())
                        nav_ok_m = bool(cap["can_go"])
                        rw_ck_m = str(getattr(rw, "inspector_clash_kind", "") or "")
                        rw_peer_m = getattr(rw, "inspector_peer_planned_pr", None)
                        is_dest_m = kind == "dest"
                        has_real_m = bool(
                            canon_m and self._inspector_existing_real_file_at_destination_path(canon_m)
                        )
                        a_op_m = more_m.addAction("Show other planned row")
                        a_sef_m = more_m.addAction("Show existing file")
                        a_sf = more_m.addAction("Show target folder")
                        a_op_m.setVisible(is_dest_m and rw_ck_m in ("planned_path", "both"))
                        a_op_m.setEnabled(
                            bool(
                                is_dest_m
                                and rw_ck_m in ("planned_path", "both")
                                and nav_ok_m
                                and rw_peer_m is not None
                            )
                        )
                        a_sef_m.setVisible(is_dest_m and rw_ck_m in ("existing_file", "both"))
                        a_sef_m.setEnabled(
                            bool(
                                is_dest_m
                                and rw_ck_m in ("existing_file", "both")
                                and nav_ok_m
                                and has_file_m
                                and has_real_m
                            )
                        )
                        a_sf.setVisible(nav_ok_m and has_folder_m)
                        a_sf.setEnabled(nav_ok_m and has_folder_m)
                        a_par = more_m.addAction("Go to parent folder mapping")
                        a_dup = more_m.addAction("Open duplicate file review…")
                        a_par.setEnabled(cap["can_go_parent"])
                        if cap["is_rec"]:
                            a_rm.setVisible(False)
                            a_rt.setVisible(False)
                        else:
                            a_rm.setEnabled(cap["can_remove"])
                            a_rt.setEnabled(cap["can_retarget"])

                        def _bind_more(
                            act: QAction,
                            fn,
                            *,
                            rww: ConflictRowWidget = rw,
                        ) -> None:
                            act.triggered.connect(lambda *a: fn(rww))

                        _bind_more(
                            a_rt,
                            lambda rww: (
                                _inspector_inline_retarget(int(rww.planned_row_index))
                                if rww.planned_row_index is not None
                                else None
                            ),
                        )
                        _bind_more(
                            a_rm,
                            lambda rww: (
                                _inspector_inline_remove(int(rww.planned_row_index))
                                if rww.planned_row_index is not None
                                else None
                            ),
                        )
                        def _more_focus_peer_row(rww: ConflictRowWidget) -> None:
                            pr_peer = getattr(rww, "inspector_peer_planned_pr", None)
                            if pr_peer is None:
                                return
                            ppi = int(pr_peer)
                            for orw in inspector_conflict_rows:
                                if orw.planned_row_index is not None and int(orw.planned_row_index) == ppi:
                                    _deselect_other_rows(orw)
                                    orw.set_selected(True)
                                    sync_from_conflict_row(orw)
                                    scroll.ensureWidgetVisible(orw)
                                    break
                            self._inspector_focus_planned_moves_row(ppi)
                            _set_inspector_banner(
                                "Showing the other planned row for this duplicate group.",
                                "info",
                            )

                        def _more_show_existing_file(rww: ConflictRowWidget) -> None:
                            stx = rww.transfer_step
                            if isinstance(stx, dict):
                                self._inspector_navigate_existing_destination_file_for_step(
                                    stx,
                                    on_banner_fail=lambda m: _set_inspector_banner(m, "warning"),
                                    on_banner_info=lambda t: _set_inspector_banner(t, "info"),
                                )

                        _bind_more(a_op_m, lambda rww: _more_focus_peer_row(rww))
                        _bind_more(a_sef_m, lambda rww: _more_show_existing_file(rww))
                        _bind_more(
                            a_sf,
                            lambda rww: (
                                self._inspector_navigate_destination_for_step(
                                    rww.transfer_step,
                                    mode="folder",
                                    on_banner_fail=lambda m: _set_inspector_banner(m, "warning"),
                                    success_banner="Showing target folder for this row",
                                    on_banner_info=lambda t: _set_inspector_banner(t, "info"),
                                )
                                if isinstance(rww.transfer_step, dict)
                                else None
                            ),
                        )
                        _bind_more(
                            a_par,
                            lambda rww: (
                                self._inspector_run_go_parent_from_step(rww.transfer_step)
                                if isinstance(rww.transfer_step, dict)
                                else None
                            ),
                        )
                        a_dup.triggered.connect(
                            lambda: self._show_duplicate_destination_file_review_dialog(
                                launched_from_execution_duplicate_inspector=True
                            )
                        )
                        rw.more_btn.setMenu(more_m)

                        wire_conflict_row(rw, kind=kind, group_prs=list(pr_row_indices))
                        inspector_conflict_rows.append(rw)
                        row_widgets.append(rw)
                        card.rows_layout.addWidget(rw)

                    for j, rwj in enumerate(row_widgets):
                        rwj.set_last_in_group(j == len(row_widgets) - 1)

                    nconf = len(row_widgets)
                    need = sum(
                        1
                        for rw in row_widgets
                        if rw.planned_row_index is not None
                        and int(rw.planned_row_index) in inspector_guidance_highlight_pr
                    )
                    meta_parts = [f"{nconf} conflict" + ("s" if nconf != 1 else "")]
                    if need > 0:
                        meta_parts.append(
                            "1 needs attention" if need == 1 else f"{need} need attention"
                        )
                    card.group_meta_label.setText(" • ".join(meta_parts))
                    n_plan = sum(1 for rw in row_widgets if rw.planned_row_index is not None)
                    if need > 0 and n_plan > 0 and need < n_plan:
                        card.group_status_badge.setText("Partially fixed")
                    elif need > 0:
                        card.group_status_badge.setText("Needs attention")
                    elif kind == "dest" and len(pr_row_indices) >= 2:
                        card.group_status_badge.setText("Auto-fix available")
                    else:
                        card.group_status_badge.setText("Review")

                    host_layout.addWidget(card)

            add_grouped_section("Duplicate destination file targets", dest_groups, "dest")
            add_grouped_section("Duplicate source assignments", src_groups, "source")

            if not dest_groups and not src_groups:
                empty = QLabel(
                    "No duplicate groups could be built from transfer_steps (unexpected if validation failed)."
                )
                empty.setObjectName("MutedText")
                empty.setWordWrap(True)
                host_layout.addWidget(empty)

            host_layout.addStretch(1)
            scroll.setWidget(host)
            scroll.verticalScrollBar().setValue(min(scroll_y, scroll.verticalScrollBar().maximum()))
            _apply_inspector_guidance_highlights()
            if inspector_guidance_highlight_pr:
                _focus_inspector_affected_row(inspector_guidance_highlight_pr)
            elif inspector_conflict_rows:
                first_rw = inspector_conflict_rows[0]
                _deselect_other_rows(first_rw)
                first_rw.set_selected(True)
                sync_from_conflict_row(first_rw)

        def on_show_other_planned() -> None:
            rw = sel_row_widget.get("rw")
            if not isinstance(rw, ConflictRowWidget):
                _set_inspector_banner("Select a row in the duplicate list first.", "warning")
                return
            pr_peer = getattr(rw, "inspector_peer_planned_pr", None)
            if pr_peer is None:
                _set_inspector_banner("No other planned row is linked for this duplicate group.", "warning")
                return
            ppi = int(pr_peer)
            for orw in inspector_conflict_rows:
                if orw.planned_row_index is not None and int(orw.planned_row_index) == ppi:
                    _deselect_other_rows(orw)
                    orw.set_selected(True)
                    sync_from_conflict_row(orw)
                    scroll.ensureWidgetVisible(orw)
                    break
            self._inspector_focus_planned_moves_row(ppi)
            _set_inspector_banner("Showing the other planned row for this duplicate group.", "info")

