    def _handle_go_to_source_from_destination_menu(self, ctx, checked=False):
        """Bound slot for destination context menu: ``triggered(bool)`` must not overwrite the frozen context dict."""
        self.handle_go_to_source(ctx, entry_point="destination_context_menu")

    def handle_go_to_source(self, context=None, *, entry_point="unknown"):
        """Focus Source Content on the traced path (expand/select/scroll). Optional ``context`` for context-menu callers."""
        details_ctx = getattr(self, "_current_details_context", None)
        explicit_context_passed = context is not None
        if context is None:
            context = details_ctx
        log_info(
            "go_to_source_handle_entry",
            entry_point=str(entry_point or "unknown"),
            explicit_context_passed=explicit_context_passed,
            fell_back_to_current_details=not explicit_context_passed,
            panel_key=str((context or {}).get("panel_key", "")) if isinstance(context, dict) else "",
            in_menu_session=bool(getattr(self, "_go_to_source_trace_session", False)),
        )
        if self._full_trace_enabled():
            log_trace(
                "ui",
                "go_to_source_handle_entry",
                explicit_context_passed=explicit_context_passed,
                fell_back_to_current_details=not explicit_context_passed,
                context_same_object_as_details=(context is not None and context is details_ctx),
                panel_key=str((context or {}).get("panel_key", "")) if isinstance(context, dict) else "",
                in_menu_session=bool(getattr(self, "_go_to_source_trace_session", False)),
            )
        if context is None:
            QMessageBox.information(self, "Go to source", "Select an item first.")
            return
        action = context["actions"].get("Go to source", {})
        metadata = context["metadata"]
        if not action.get("enabled"):
            log_warn(
                "selection_action_open_source_folder_failed",
                item_name=metadata["item_name"],
                item_path=metadata["item_path"],
                tree_role=context["panel_key"],
                node_origin=metadata["node_origin"],
                has_source_traceability=context["traceability"].get("traceable_to_source", False),
                used_fallback=False,
                opened_url="",
            )
            log_warn(
                "selection_action_failed",
                item_name=metadata["item_name"],
                item_path=metadata["item_path"],
                tree_role=context["panel_key"],
                node_origin=metadata["node_origin"],
                action_name="Go to source",
                enabled=False,
                traceable_to_source=context["traceability"].get("traceable_to_source", False),
                selected_item_type=metadata["item_type"],
            )
            QMessageBox.information(
                self,
                "Go to source",
                "This item cannot be traced to a path in the current source library.",
            )
            return
        target_path = action.get("target", "")
        mode = action.get("mode", "")
        log_info(
            "selection_action_open_source_folder_branch",
            item_name=metadata["item_name"],
            item_path=metadata["item_path"],
            tree_role=context["panel_key"],
            node_origin=metadata["node_origin"],
            has_source_traceability=context["traceability"].get("traceable_to_source", False),
            used_fallback=False,
            opened_url="",
        )
        log_info(
            "selection_action_open_source_folder_trace_to_source",
            item_name=metadata["item_name"],
            item_path=metadata["item_path"],
            tree_role=context["panel_key"],
            node_origin=metadata["node_origin"],
            has_source_traceability=context["traceability"].get("traceable_to_source", False),
            used_fallback=False,
            opened_url="",
        )
        prefer_container = mode == "select_source_container"
        log_info(
            "go_to_source_handle_navigate",
            entry_point=str(entry_point or "unknown"),
            target_path_excerpt=str(target_path or "")[:400],
            prefer_container=prefer_container,
        )
        if self._full_trace_enabled():
            log_trace(
                "ui",
                "go_to_source_handle_navigate",
                target_path_excerpt=str(target_path or "")[:400],
                prefer_container=prefer_container,
                action_enabled=True,
                in_menu_session=bool(getattr(self, "_go_to_source_trace_session", False)),
            )
        navigated = self._select_source_item_by_path(target_path, prefer_container=prefer_container)
        log_info(
            "go_to_source_select_by_path",
            entry_point=str(entry_point or "unknown"),
            phase="immediate",
            found=bool(navigated),
            target_path_excerpt=str(target_path or "")[:400],
            prefer_container=prefer_container,
        )
        if not navigated:
            if self._full_trace_enabled():
                log_trace(
                    "ui",
                    "go_to_source_handle_fallback_start_navigation",
                    target_path_excerpt=str(target_path or "")[:400],
                    in_menu_session=bool(getattr(self, "_go_to_source_trace_session", False)),
                )
            navigated = self._start_source_navigation(target_path, prefer_container=prefer_container)
        deferred_pending = bool(getattr(self, "_pending_source_navigation", None))
        log_info(
            "go_to_source_handle_result",
            entry_point=str(entry_point or "unknown"),
            reported_navigated=bool(navigated),
            deferred_navigation_pending=deferred_pending,
        )
        if self._full_trace_enabled():
            log_trace(
                "ui",
                "go_to_source_handle_result",
                navigated=bool(navigated),
                in_menu_session=bool(getattr(self, "_go_to_source_trace_session", False)),
            )
        log_info(
            "selection_action_open_source_folder",
            item_name=metadata["item_name"],
            item_path=metadata["item_path"],
            tree_role=context["panel_key"],
            node_origin=metadata["node_origin"],
            action_name="Go to source",
            enabled=True,
            traceable_to_source=context["traceability"].get("traceable_to_source", False),
            selected_item_type=metadata["item_type"],
        )
        if not navigated:
            log_warn(
                "selection_action_open_source_folder_failed",
                item_name=metadata["item_name"],
                item_path=metadata["item_path"],
                tree_role=context["panel_key"],
                node_origin=metadata["node_origin"],
                has_source_traceability=context["traceability"].get("traceable_to_source", False),
                used_fallback=False,
                opened_url="",
            )
            log_warn(
                "selection_action_failed",
                item_name=metadata["item_name"],
                item_path=metadata["item_path"],
                tree_role=context["panel_key"],
                node_origin=metadata["node_origin"],
                action_name="Go to source",
                enabled=True,
                traceable_to_source=context["traceability"].get("traceable_to_source", False),
                selected_item_type=metadata["item_type"],
            )
            QMessageBox.information(
                self,
                "Go to source",
                "The linked source path could not be found or revealed in the Source Content tree.",
            )

    def handle_go_to_destination(self):
        context = getattr(self, "_current_details_context", None)
        if context is None:
            QMessageBox.information(self, "Go to Destination", "Select an item first.")
            return
        if context.get("panel_key") != "source":
            QMessageBox.information(
                self,
                "Go to Destination",
                "Select a source item that has an assignment.",
            )
            return
        action = context["actions"].get("Go to Destination", {})
        metadata = context["metadata"]
        if not action.get("enabled"):
            log_warn(
                "selection_action_failed",
                item_name=metadata["item_name"],
                item_path=metadata["item_path"],
                tree_role=context["panel_key"],
                node_origin=metadata["node_origin"],
                action_name="Go to Destination",
                enabled=False,
                traceable_to_source=context["traceability"].get("traceable_to_source", False),
                selected_item_type=metadata["item_type"],
            )
            QMessageBox.information(
                self,
                "Go to Destination",
                "This source item has no assignment to show in the destination tree.",
            )
            return
        self._handle_go_to_destination_for_source(dict(context.get("node_data") or {}))

    def get_tree_item_node_data(self, item):
        if item is None:
            return None

        raw_row = None
        raw_column = None
        if isinstance(item, QModelIndex):
            # Multi-column explorer models (destination/source QTreeView) attach Qt.UserRole only on column 0.
            if item.isValid():
                raw_row, raw_column = item.row(), item.column()
            if item.isValid() and item.column() != 0:
                item = item.siblingAtColumn(0)
            node_data = item.data(Qt.UserRole) or {} if item.isValid() else {}
        else:
            node_data = item.data(0, Qt.UserRole) or {}
        if node_data.get("placeholder"):
            return None

        out = dict(node_data)
        if str(out.get("tree_role", "")) == "destination":
            migrate_legacy_overlay_payload_row(out)
        if self._full_trace_enabled() and getattr(self, "_go_to_source_trace_session", False):
            log_trace(
                "ui",
                "go_to_source_get_tree_item_node_data",
                raw_row=raw_row,
                raw_column=raw_column,
                normalized_column=(item.column() if isinstance(item, QModelIndex) and item.isValid() else None),
                payload_keys=sorted(out.keys()),
            )
        return out

    def set_tree_item_node_data(self, item, node_data: dict | None):
        payload = dict(node_data or {})
        if isinstance(item, QModelIndex):
            model = item.model()
            if model is None:
                return

            def _mut(p):
                p.clear()
                p.update(payload)

            if hasattr(model, "update_payload_for_index"):
                model.update_payload_for_index(item, _mut)
            return
        item.setData(0, Qt.UserRole, payload)

    def get_selected_tree_node_data(self, tree_role):
        if self._planning_browse_mode(tree_role) == "local":
            tree = self.source_local_fs_tree if tree_role == "source" else self.destination_local_fs_tree
            ix = tree.currentIndex()
            return self._local_fs_node_from_index(tree, ix, tree_role)

        tree = self.source_tree_widget if tree_role == "source" else self.destination_tree_widget
        return self.get_tree_item_node_data(tree.currentIndex())

    def select_tree_item_at_position(self, tree, position):
        if isinstance(tree, QTreeView):
            ix = tree.indexAt(position)
            if not ix.isValid():
                tree.clearSelection()
                return None
            raw_column = int(ix.column())
            if ix.column() != 0:
                ix = ix.siblingAtColumn(0)
            tree.setCurrentIndex(ix)
            if self._full_trace_enabled():
                log_trace(
                    "ui",
                    "select_tree_item_at_position",
                    tree_kind="QTreeView",
                    row=ix.row(),
                    raw_column_from_hit_test=raw_column,
                    index_column_after_normalize=ix.column(),
                )
            return ix

        item = tree.itemAt(position)
        if item is None:
            tree.clearSelection()
            return None

        tree.setCurrentItem(item)
        item.setSelected(True)
        return item

    def build_node_key(self, node_data, default_role):
        if node_data is None:
            return None

        return (
            node_data.get("tree_role", default_role),
            node_data.get("drive_id", ""),
            node_data.get("id", ""),
            self._tree_item_path(node_data).lower(),
        )

    def node_keys_match(self, left_node, right_node, default_role):
        left_key = self.build_node_key(left_node, default_role)
        right_key = self.build_node_key(right_node, default_role)
        if left_key is None or right_key is None:
            return False

        left_role, left_drive, left_id, left_path = left_key
        right_role, right_drive, right_id, right_path = right_key
        if left_role != right_role:
            return False
        if left_drive and right_drive and left_drive != right_drive:
            return False
        if left_id and right_id:
            if left_id == right_id:
                return True
            low_l = str(left_id).lower()
            low_r = str(right_id).lower()
            if low_l.startswith("allocated::") or low_r.startswith("allocated::"):
                return self._paths_equivalent(left_path, right_path, left_role or default_role)
            return False
        if (not left_id or not right_id) and (
            str(left_node.get("overlay_node_id") or "")
            or str(right_node.get("overlay_node_id") or "")
        ):
            return self._paths_equivalent(left_path, right_path, left_role or default_role)
        return self._paths_equivalent(left_path, right_path, left_role or default_role)

    def find_planned_move_index_by_source(self, source_node):
        if self.build_node_key(source_node, "source") is None:
            return None

        for index, existing_move in enumerate(self.planned_moves):
            if self.node_keys_match(existing_move.get("source", {}), source_node, "source"):
                return index

        return None

    def _planned_move_index_for_source_node(self, source_node):
        """Resolve a planned move from a source tree row, including path fallback when ids diverge."""
        if not isinstance(source_node, dict):
            return None
        if self.build_node_key(source_node, "source") is not None:
            ix = self.find_planned_move_index_by_source(source_node)
            if ix is not None:
                return ix
        sp = self._canonical_source_projection_path(
            source_node.get("display_path") or source_node.get("item_path") or ""
        )
        if not sp:
            return None
        for index, existing_move in enumerate(self.planned_moves):
            sm = existing_move.get("source") or {}
            esp = self._canonical_source_projection_path(
                sm.get("display_path") or sm.get("item_path") or str(existing_move.get("source_path", "") or "")
            )
            if esp and esp == sp:
                return index
        return None

    def find_planned_move_index_by_destination(self, destination_node):
        if not isinstance(destination_node, dict):
            return None

        dest_path = self._destination_row_semantic_path(destination_node)
        if not dest_path:
            dest_path = self._canonical_destination_projection_path(
                destination_node.get("display_path")
                or destination_node.get("item_path")
                or destination_node.get("destination_path")
                or ""
            )
        dest_key = dest_path.casefold() if dest_path else ""

        if dest_key:
            for index, existing_move in enumerate(self.planned_moves):
                alloc_path = self._canonical_destination_projection_path(
                    self._allocation_projection_path(existing_move)
                )
                if alloc_path and alloc_path.casefold() == dest_key:
                    if is_dev_mode():
                        log_info(
                            "planned_move_match_by_destination",
                            match_kind="allocation_path_exact",
                            move_index=index,
                            semantic_path=dest_path,
                            allocation_path=alloc_path,
                        )
                    return index

        for index, existing_move in enumerate(self.planned_moves):
            if self.node_keys_match(existing_move.get("destination", {}), destination_node, "destination"):
                if is_dev_mode():
                    log_info(
                        "planned_move_match_by_destination",
                        match_kind="node_keys",
                        move_index=index,
                        semantic_path=dest_path,
                    )
                return index

        nid = str(destination_node.get("id") or "")
        nid_low = nid.lower()
        if nid_low.startswith("allocated::"):
            embedded = nid.split("::", 1)[-1] if "::" in nid else ""
            ep = self._canonical_destination_projection_path(embedded)
            if ep:
                ep_key = ep.casefold()
                for index, existing_move in enumerate(self.planned_moves):
                    ap = self._canonical_destination_projection_path(
                        self._allocation_projection_path(existing_move)
                    )
                    if ap and ap.casefold() == ep_key:
                        if is_dev_mode():
                            log_info(
                                "planned_move_match_by_destination",
                                match_kind="allocated_id_embedded_path",
                                move_index=index,
                                semantic_path=dest_path,
                                allocation_path=ap,
                            )
                        return index
        ovid = str(destination_node.get("overlay_node_id") or "")
        if ovid.startswith("ovl:allocation:"):
            for index, existing_move in enumerate(self.planned_moves):
                ap = self._canonical_destination_projection_path(self._allocation_projection_path(existing_move))
                if not ap:
                    continue
                if new_overlay_node_id("allocation", ap) == ovid:
                    return index

        if is_dev_mode():
            log_info("planned_move_match_by_destination", match_kind="none", semantic_path=dest_path or "")
        return None

    def is_proposed_destination_node(self, node_data):
        if node_data is None:
            return False
        if node_data.get("tree_role", "destination") != "destination":
            return False
        return self.node_is_proposed(node_data)

    def node_is_proposed(self, node_data):
        if node_data is None:
            return False

        return bool(node_data.get("proposed")) or str(node_data.get("node_origin", "")).lower() == "proposed"

    def node_is_planned_allocation(self, node_data):
        if node_data is None:
            return False

        origin = str(node_data.get("node_origin", "")).lower()
        overlay_state = str(node_data.get("overlay_state", "")).lower()
        return (
            bool(node_data.get("planned_allocation"))
            or origin == "plannedallocation"
            or overlay_state == "plannedallocation"
        )

    def node_is_valid_destination_target(self, node_data):
        """Whether Assign and related actions may use this destination row.

        Must match :meth:`node_is_manual_drag_destination_folder` so context-menu Assign works on the same
        folders as Explorer-style drag (including ``[Allocated]`` projection roots and allocation descendants).
        Previously this rejected planned-allocation folders only, which disabled Assign after restore while
        drag still worked.
        """
        return self.node_is_manual_drag_destination_folder(node_data)

    def node_is_manual_drag_destination_folder(self, node_data):
        """Folder rows that may receive Explorer-style manual planning drags.

        Includes [Allocated] containers and visible **allocation-projected descendant folders** (e.g. nested
        folders under an allocation subtree) when they are real folder rows. Rejects placeholders, local
        browse rows, explicit non-folders, and rows that are not folder-like unless ``is_folder`` is omitted
        only on planned-allocation roots (handled via :meth:`node_is_planned_allocation`).
        """
        if not isinstance(node_data, dict) or not node_data:
            return False
        if node_data.get("placeholder"):
            return False
        origin = str(node_data.get("node_origin", "")).lower()
        if origin == "localfilesystem":
            return False
        if node_data.get("is_folder") is False:
            return False
        if bool(node_data.get("is_folder")):
            return True
        if self.node_is_planned_allocation(node_data):
            return True
        if (
            bool(node_data.get("planned_allocation_descendant"))
            and origin == "projectedallocationdescendant"
            and node_data.get("is_folder") is not False
        ):
            return bool(node_data.get("is_folder", True))
        return False

    def _destination_drop_ref_is_folder_row(self, ref_node: dict) -> bool:
        """Whether the hovered row is treated as a folder for drop-band resolution (matches commit eligibility)."""
        if not isinstance(ref_node, dict) or not ref_node:
            return False
        if ref_node.get("is_folder") is False:
            return False
        if bool(ref_node.get("is_folder")):
            return True
        if self.node_is_planned_allocation(ref_node):
            return True
        if (
            bool(ref_node.get("planned_allocation_descendant"))
            and str(ref_node.get("node_origin", "")).lower() == "projectedallocationdescendant"
            and ref_node.get("is_folder") is not False
        ):
            return bool(ref_node.get("is_folder", True))
        return False

    def show_source_context_menu(self, position):
        tw = self._active_source_tree_widget()
        self.select_tree_item_at_position(tw, position)
        node_data = self.get_selected_tree_node_data("source")
        if node_data is None:
            return

        selected_destination = self.get_selected_tree_node_data("destination")
        has_assignment = self._planned_move_index_for_source_node(node_data) is not None
        can_assign = self.node_is_valid_destination_target(selected_destination)

        menu = QMenu(self)
        menu.setAttribute(Qt.WA_TranslucentBackground, False)
        assign_action = menu.addAction("Assign to Selected Destination")
        assign_action.setEnabled(can_assign)
        assign_action.triggered.connect(self.handle_assign)

        can_assign_individually = (
            can_assign
            and self._planning_browse_mode("source") == "sharepoint"
            and self.source_platform_combo.currentData() == "sharepoint"
            and self._graph_token_ready_for_sharepoint()
        )
        assign_individual_action = menu.addAction("Assign individually…")
        assign_individual_action.setEnabled(can_assign_individually)
        assign_individual_action.triggered.connect(self.handle_assign_individual_from_selection)

        unassign_action = menu.addAction("Unassign")
        unassign_action.setEnabled(has_assignment)
        unassign_action.triggered.connect(self.handle_unassign)

        leaf_flags = self._plan_leaf_exclude_include_menu_flags("source", dict(node_data))
        exclude_leaf_action = menu.addAction("Exclude from Plan")
        exclude_leaf_action.setEnabled(leaf_flags["can_exclude"])
        exclude_leaf_action.triggered.connect(lambda: self.handle_exclude_leaf_from_plan("source", dict(node_data)))
        include_leaf_action = menu.addAction("Include in Plan")
        include_leaf_action.setEnabled(leaf_flags["can_include"])
        include_leaf_action.triggered.connect(lambda: self.handle_include_leaf_in_plan("source", dict(node_data)))

        menu.addSeparator()

        go_to_dest_action = menu.addAction("Go to Destination")
        _pm = self._planned_move_for_source_node(node_data)
        go_to_dest_action.setEnabled(_pm is not None and not self._planned_move_uses_local_destination(_pm))
        go_to_dest_action.triggered.connect(
            lambda _checked=False, nd=dict(node_data): self._handle_go_to_destination_for_source(nd)
        )

        menu.addSeparator()

        preview_action = menu.addAction("Preview")
        preview_action.triggered.connect(lambda: self._handle_context_menu_preview("source", dict(node_data)))

        open_file_action = menu.addAction("Open File")
        open_file_action.triggered.connect(lambda: self.handle_open_source_item(node_data))

        open_browser_action = menu.addAction("Open in Browser")
        open_browser_action.triggered.connect(lambda: self.handle_open_item_in_browser(node_data))

        copy_link_action = menu.addAction("Copy Link")
        copy_link_action.triggered.connect(lambda: self.handle_copy_item_link(node_data))

        menu.exec(tw.viewport().mapToGlobal(position))

    def show_destination_context_menu(self, position):
        tw = self._active_destination_tree_widget()
        trace_menu = self._full_trace_enabled()
        if trace_menu:
            self._go_to_source_trace_session = True
            log_trace("ui", "go_to_source_destination_context_menu", phase="session_start")
        try:
            item = self.select_tree_item_at_position(tw, position)
            if item is None:
                return
            node_data = (
                self._local_fs_node_from_index(tw, item, "destination")
                if self._planning_browse_mode("destination") == "local"
                else self.get_tree_item_node_data(item)
            )
            if trace_menu and isinstance(item, QModelIndex):
                log_trace(
                    "ui",
                    "go_to_source_destination_context_menu",
                    phase="hit_test",
                    row=item.row(),
                    column=item.column(),
                    normalized_to_column_zero=(item.column() == 0),
                    node_data_keys=sorted((node_data or {}).keys()),
                    node_data_source_path_excerpt=str(node_data.get("source_path", "") or "")[:400],
                )
            if not node_data:
                return

            selected_source = self.get_selected_tree_node_data("source")
            is_planned_allocation = self.node_is_planned_allocation(node_data)
            is_proposed = self.node_is_proposed(node_data)
            node_origin = str(node_data.get("node_origin", "")).lower()
            is_local_fs_dest = node_origin == "localfilesystem"
            is_projected_descendant = node_origin == "projectedallocationdescendant"
            is_projected_destination = node_origin == "projecteddestination"
            is_real_destination = not (is_planned_allocation or is_proposed or is_projected_descendant or is_projected_destination)
            is_folder = bool(node_data.get("is_folder"))

            menu = QMenu(self)
            menu.setAttribute(Qt.WA_TranslucentBackground, False)

            assign_action = menu.addAction("Assign Selected Source Here")
            assign_action.setEnabled(
                selected_source is not None
                and self.node_is_valid_destination_target(node_data)
                and not is_projected_descendant
            )
            assign_action.triggered.connect(self.handle_assign)

            new_proposed_action = menu.addAction("New Proposed Folder Here")
            new_proposed_action.setEnabled(
                is_folder
                and not is_planned_allocation
                and not is_projected_descendant
                and not is_local_fs_dest
            )
            new_proposed_action.triggered.connect(lambda: self.handle_new_proposed_folder(node_data))

            rename_proposed_action = menu.addAction("Rename Proposed Folder")
            rename_proposed_action.setEnabled(is_proposed)
            rename_proposed_action.triggered.connect(lambda: self.handle_rename_proposed_folder(item))

            delete_proposed_action = menu.addAction("Delete Proposed Folder")
            delete_proposed_action.setEnabled(is_proposed)
            delete_proposed_action.triggered.connect(lambda: self.handle_delete_proposed_folder(item))

            menu.addSeparator()

            cut_action = menu.addAction("Cut")
            cut_action.setEnabled(
                self._build_destination_move_payload(node_data) is not None and not is_local_fs_dest
            )
            cut_action.triggered.connect(lambda: self.handle_cut_destination_item(node_data))

            paste_action = menu.addAction("Paste Here")
            paste_action.setEnabled(
                bool(getattr(self, "_destination_cut_buffer", None))
                and self._paste_here_destination_row_allowed(node_data)
            )
            paste_action.triggered.connect(
                lambda _=False, nd=dict(node_data), pit=item: self.handle_paste_destination_item(
                    nd, paste_target_item=pit
                )
            )

            menu.addSeparator()

            rename_planned_action = menu.addAction("Rename Planned Item")
            rename_planned_action.setEnabled(is_planned_allocation or is_projected_descendant)
            rename_planned_action.triggered.connect(lambda: self.handle_rename_planned_item(node_data))

            unassign_destination_action = menu.addAction("Unassign")
            unassign_destination_action.setEnabled(is_planned_allocation)
            unassign_destination_action.triggered.connect(lambda: self.handle_remove_planned_allocation(node_data))

            leaf_flags = self._plan_leaf_exclude_include_menu_flags("destination", dict(node_data))
            exclude_leaf_action = menu.addAction("Exclude from Plan")
            exclude_leaf_action.setEnabled(leaf_flags["can_exclude"])
            exclude_leaf_action.triggered.connect(lambda: self.handle_exclude_leaf_from_plan("destination", dict(node_data)))
            include_leaf_action = menu.addAction("Include in Plan")
            include_leaf_action.setEnabled(leaf_flags["can_include"])
            include_leaf_action.triggered.connect(lambda: self.handle_include_leaf_in_plan("destination", dict(node_data)))

            menu.addSeparator()

            preview_action = menu.addAction("Preview")
            preview_action.triggered.connect(lambda: self._handle_context_menu_preview("destination", dict(node_data)))

            open_file_action = menu.addAction("Open File")
            open_file_action.setEnabled(not is_folder)
            open_file_action.triggered.connect(self.handle_open_selected_file)

            open_browser_action = menu.addAction("Open in SharePoint")
            open_browser_action.setEnabled(bool(node_data.get("web_url")) or is_real_destination)
            open_browser_action.triggered.connect(self.handle_open_selected_in_browser)

            copy_link_action = menu.addAction("Copy Link")
            copy_link_action.setEnabled(bool(node_data.get("web_url") or node_data.get("display_path") or node_data.get("item_path")))
            copy_link_action.triggered.connect(self.handle_copy_selected_link)

            dest_ctx = self._resolve_selected_item_context("destination", dict(node_data))
            go_action = dest_ctx["actions"].get("Go to source", {})
            if trace_menu:
                log_trace(
                    "ui",
                    "go_to_source_destination_context_menu",
                    phase="before_exec",
                    go_to_source_enabled=bool(go_action.get("enabled")),
                    go_to_source_target_excerpt=str(go_action.get("target", "") or "")[:400],
                )
            go_to_source_action = menu.addAction("Go to source")
            go_to_source_action.setEnabled(bool(go_action.get("enabled")))
            go_to_source_action.setToolTip(str(go_action.get("tooltip") or ""))
            go_to_source_action.triggered.connect(partial(self._handle_go_to_source_from_destination_menu, dest_ctx))

            menu.exec(tw.viewport().mapToGlobal(position))
        finally:
            if trace_menu:
                log_trace("ui", "go_to_source_destination_context_menu", phase="session_end")
                self._go_to_source_trace_session = False

    def handle_open_source_item(self, node_data):
        if str(node_data.get("node_origin", "")).lower() == "localfilesystem":
            p = node_data.get("item_path") or node_data.get("display_path") or ""
            if p and Path(p).is_file() and QDesktopServices.openUrl(QUrl.fromLocalFile(str(Path(p).resolve()))):
                return
        local_path = self._resolve_local_open_file_target(node_data)
        if local_path and QDesktopServices.openUrl(QUrl.fromLocalFile(local_path)):
            return

        QMessageBox.information(
            self,
            "Open File",
            "No local file was found on disk. Use Open in Browser for SharePoint items.",
        )

    def handle_open_item_in_browser(self, node_data):
        web_url = node_data.get("web_url")
        if web_url and QDesktopServices.openUrl(QUrl(web_url)):
            return

        QMessageBox.information(self, "Open in Browser", "Open in Browser is not available for this item yet.")

    def handle_copy_item_link(self, node_data):
        link = node_data.get("web_url") or node_data.get("display_path") or node_data.get("item_path")
        if not link:
            QMessageBox.information(self, "Copy Link", "No link is available for the selected item.")
            return

        QGuiApplication.clipboard().setText(link)
        self.planned_moves_status.setText("Link copied to clipboard.")

    def _next_inline_proposed_folder_name(self, parent_item):
        existing_names = set()
        if isinstance(parent_item, QModelIndex):
            if not parent_item.isValid():
                pass
            else:
                par = parent_item.siblingAtColumn(0) if parent_item.column() != 0 else parent_item
                model = par.model()
                if model is not None:
                    for r in range(model.rowCount(par)):
                        cix = model.index(r, 0, par)
                        child_data = cix.data(Qt.UserRole) or {}
                        label = str(child_data.get("name") or cix.data(Qt.DisplayRole) or "").strip().lower()
                        if label:
                            existing_names.add(label)
        else:
            for index in range(parent_item.childCount()):
                child = parent_item.child(index)
                child_data = child.data(0, Qt.UserRole) or {}
                existing_names.add(str(child_data.get("name") or child.text(0) or "").strip().lower())

        base_name = "New Folder"
        if base_name.lower() not in existing_names:
            return base_name

        suffix = 2
        while True:
            candidate = f"{base_name} ({suffix})"
            if candidate.lower() not in existing_names:
                return candidate
            suffix += 1

    def _remove_inline_proposed_folder_item(self, item):
        if item is None:
            return
        parent_item = item.parent()
        if parent_item is not None:
            parent_item.removeChild(item)
        else:
            index = self.destination_tree_widget.indexOfTopLevelItem(item)
            if index >= 0:
                self.destination_tree_widget.takeTopLevelItem(index)

    def _refresh_destination_item_label(self, item):
        if item is None:
            return
        node_data = self.get_tree_item_node_data(item) or {}
        if not node_data:
            return
        name = str(node_data.get("name") or item.text(0) or "").strip()
        if self.node_is_proposed(node_data):
            base_label = self._tree_name_column_label(name, tag="(Proposed)")
        elif self.node_is_planned_allocation(node_data):
            base_label = self._tree_name_column_label(name, tag="[Allocated]")
        elif str(node_data.get("node_origin", "")).lower() == "projectedallocationdescendant":
            base_label = self._tree_name_column_label(name)
        else:
            return
        node_data["base_display_label"] = base_label
        item.setData(0, Qt.UserRole, node_data)
        self._apply_tree_item_visual_state(item, node_data)

    def _rename_visible_destination_subtree(self, item, original_path, updated_path):
        if item is None:
            return
        node_data = self.get_tree_item_node_data(item) or {}
        current_path = self.normalize_memory_path(node_data.get("display_path") or node_data.get("item_path") or "")
        if current_path == original_path or current_path.startswith(original_path + "\\"):
            suffix = current_path[len(original_path):]
            next_path = self.normalize_memory_path(updated_path + suffix)
            next_name = self._path_segments(next_path)[-1] if self._path_segments(next_path) else str(node_data.get("name", "")).strip()
            node_data["name"] = next_name
            node_data["real_name"] = next_name
            node_data["display_path"] = next_path
            node_data["item_path"] = next_path
            node_data["destination_path"] = next_path
            item.setData(0, Qt.UserRole, node_data)
            self._refresh_destination_item_label(item)
        for index in range(item.childCount()):
            self._rename_visible_destination_subtree(item.child(index), original_path, updated_path)

    def _rename_visible_destination_subtree_index(self, index: QModelIndex, original_path, updated_path):
        if not index.isValid():
            return
        model = getattr(self, "destination_planning_model", None)
        if model is None:
            return
        node_data = dict(index.data(Qt.UserRole) or {})
        current_path = self.normalize_memory_path(node_data.get("display_path") or node_data.get("item_path") or "")
        if current_path == original_path or current_path.startswith(original_path + "\\"):
            suffix = current_path[len(original_path) :]
            next_path = self.normalize_memory_path(updated_path + suffix)
            next_name = (
                self._path_segments(next_path)[-1]
                if self._path_segments(next_path)
                else str(node_data.get("name", "")).strip()
            )
            node_data["name"] = next_name
            node_data["real_name"] = next_name
            node_data["display_path"] = next_path
            node_data["item_path"] = next_path
            node_data["destination_path"] = next_path
            name = str(node_data.get("name") or "").strip()
            if self.node_is_proposed(node_data):
                node_data["base_display_label"] = self._tree_name_column_label(name, tag="(Proposed)")
            elif self.node_is_planned_allocation(node_data):
                node_data["base_display_label"] = self._tree_name_column_label(name, tag="[Allocated]")
            elif str(node_data.get("node_origin", "")).lower() == "projectedallocationdescendant":
                node_data["base_display_label"] = self._tree_name_column_label(name)

            def _mut_payload(p):
                p.clear()
                p.update(node_data)

            model.update_payload_for_index(index, _mut_payload)
            self._apply_tree_item_visual_state(None, dict(index.data(Qt.UserRole) or {}))
        for r in range(model.rowCount(index)):
            self._rename_visible_destination_subtree_index(model.index(r, 0, index), original_path, updated_path)

    def _remove_visible_destination_subtree_by_prefix(self, item, target_path):
        if item is None:
            return False
        node_data = self.get_tree_item_node_data(item) or {}
        current_path = self._canonical_destination_projection_path(
            node_data.get("display_path") or node_data.get("item_path") or ""
        ) or self.normalize_memory_path(node_data.get("display_path") or node_data.get("item_path") or "")
        normalized_target = self._canonical_destination_projection_path(target_path) or self.normalize_memory_path(target_path)
        if current_path == normalized_target or current_path.startswith(normalized_target + "\\"):
            self._remove_inline_proposed_folder_item(item)
            return True
        for index in range(item.childCount() - 1, -1, -1):
            child = item.child(index)
            self._remove_visible_destination_subtree_by_prefix(child, normalized_target)
        return False

    def _persist_planning_change_lightweight(
        self,
        *,
        planning_refresh_reason="planning_change_lightweight",
        notify_saved=True,
        deferred_source_projection_paths=None,
    ):
        self._notify_planning_mutation_destination_snapshot_dirty(
            str(planning_refresh_reason or "planning_change_lightweight"),
            surface="persist_lightweight",
        )
        self._rebuild_submission_visual_cache()
        if deferred_source_projection_paths is None:
            spd = set(self._collect_current_source_projection_paths())
        else:
            spd = set(deferred_source_projection_paths)
        if is_dev_mode() and deferred_source_projection_paths is not None:
            log_info(
                "SOURCEPERF",
                event="deferred_queue_paths",
                narrowed_deferred_scope=True,
                deferred_path_count=len(spd),
                planning_refresh_reason=str(planning_refresh_reason or ""),
            )
        self._queue_deferred_planning_refresh(
            planning_refresh_reason,
            source_projection_paths=spd,
            notify_saved=notify_saved,
        )
        self.update_progress_summaries()
        try:
            if getattr(self, "source_tree_widget", None) is not None:
                self.source_tree_widget.viewport().update()
            if getattr(self, "destination_tree_widget", None) is not None:
                self.destination_tree_widget.viewport().update()
        except Exception as exc:
            self._log_restore_exception("persist_planning_change_lightweight", exc)

    def _destination_path_exists_under_parent(self, parent_item, destination_path, *, ignore_item=None):
        if isinstance(parent_item, QModelIndex):
            return self._destination_path_exists_under_parent_index(
                parent_item, destination_path, ignore_ix=ignore_item
            )
        normalized_target = self.normalize_memory_path(destination_path)
        for index in range(parent_item.childCount()):
            child = parent_item.child(index)
            if child is ignore_item:
                continue
            child_data = child.data(0, Qt.UserRole) or {}
            child_path = child_data.get("item_path") or child_data.get("display_path") or ""
            if self._paths_equivalent(child_path, normalized_target, "destination"):
                return True
        return False

    def _destination_path_exists_under_parent_index(
        self, parent_ix: QModelIndex, destination_path, *, ignore_ix=None
    ):
        model = getattr(self, "destination_planning_model", None)
        if model is None:
            return False
        par = parent_ix if parent_ix.isValid() else QModelIndex()
        normalized_target = self.normalize_memory_path(destination_path)
        rows = model.rowCount(par)
        for r in range(rows):
            cix = model.index(r, 0, par)
            if ignore_ix is not None and cix == ignore_ix:
                continue
            child_data = cix.data(Qt.UserRole) or {}
            child_path = child_data.get("item_path") or child_data.get("display_path") or ""
            if self._paths_equivalent(child_path, normalized_target, "destination"):
                return True
        return False

    def _destination_drag_same_logical_planned_item(
        self,
        child_node_data: dict,
        move_index: int | None,
        move,
        inherited_move,
    ) -> bool:
        """True when a destination row represents the same planned/inherited allocation as the drag payload."""
        mi, m_row, inh = self._resolve_planned_move_for_destination_node(child_node_data or {})
        if inherited_move is not None and inh is not None:
            if inh is inherited_move:
                return True
            sp_h = self._canonical_source_projection_path((inh or {}).get("source_path", "") or "")
            sp_i = self._canonical_source_projection_path((inherited_move or {}).get("source_path", "") or "")
            if sp_h and sp_i and sp_h == sp_i:
                return True
        if move is not None:
            if move_index is not None and mi is not None and int(mi) == int(move_index):
                return True
            if m_row is not None and m_row is move:
                return True
            if m_row is not None:
                k0 = str(self._allocation_move_key(move) or "").strip().casefold()
                k1 = str(self._allocation_move_key(m_row) or "").strip().casefold()
                if k0 and k1 and k0 == k1:
                    return True
                s0 = self._canonical_source_projection_path(move.get("source_path", "") or "")
                s1 = self._canonical_source_projection_path(m_row.get("source_path", "") or "")
                if s0 and s1 and s0 == s1 and mi is not None and move_index is not None and int(mi) == int(move_index):
                    return True
        return False

    def _destination_planned_drag_name_taken_by_different_item(
        self,
        parent_item,
        target_projection_path: str,
        *,
        move_index: int | None,
        move,
        inherited_move,
    ) -> bool:
        """True if another *different* logical planned item already occupies target_projection_path under parent."""
        if isinstance(parent_item, QModelIndex):
            model = getattr(self, "destination_planning_model", None)
            if model is None:
                return False
            par = parent_item if parent_item.isValid() else QModelIndex()
            normalized_target = self.normalize_memory_path(target_projection_path)
            rows = model.rowCount(par)
            for r in range(rows):
                cix = model.index(r, 0, par)
                child_data = cix.data(Qt.UserRole) or {}
                child_path = child_data.get("item_path") or child_data.get("display_path") or ""
                if not self._paths_equivalent(child_path, normalized_target, "destination"):
                    continue
                id_excerpt = ""
                try:
                    if move is not None:
                        id_excerpt = str(self._allocation_move_key(move) or "")[:260]
                    elif inherited_move is not None:
                        id_excerpt = str(self._allocation_move_key(inherited_move) or "")[:260]
                except Exception:
                    pass
                log_info(
                    "drag_move_self_collision_detected",
                    item_identity=id_excerpt,
                    target_path=str(target_projection_path)[:400],
                )
                if self._destination_drag_same_logical_planned_item(
                    child_data, move_index, move, inherited_move
                ):
                    log_info("drag_move_self_collision_allowed", reason="same_logical_item")
                    return False
                log_info("drag_move_duplicate_blocked", reason="different_item_same_name")
                return True
            return False
        normalized_target = self.normalize_memory_path(target_projection_path)
        for index in range(parent_item.childCount()):
            child = parent_item.child(index)
            child_data = child.data(0, Qt.UserRole) or {}
            child_path = child_data.get("item_path") or child_data.get("display_path") or ""
            if not self._paths_equivalent(child_path, normalized_target, "destination"):
                continue
            id_excerpt = ""
            try:
                if move is not None:
                    id_excerpt = str(self._allocation_move_key(move) or "")[:260]
                elif inherited_move is not None:
                    id_excerpt = str(self._allocation_move_key(inherited_move) or "")[:260]
            except Exception:
                pass
            log_info(
                "drag_move_self_collision_detected",
                item_identity=id_excerpt,
                target_path=str(target_projection_path)[:400],
            )
            if self._destination_drag_same_logical_planned_item(child_data, move_index, move, inherited_move):
                log_info("drag_move_self_collision_allowed", reason="same_logical_item")
                return False
            log_info("drag_move_duplicate_blocked", reason="different_item_same_name")
            return True
        return False

    def _begin_inline_proposed_folder_creation(self, destination_node, parent_item):
        if isinstance(parent_item, QModelIndex):
            return self._begin_inline_proposed_folder_creation_index(destination_node, parent_item)
        proposed_path_base = self._tree_item_path(destination_node)
        if destination_authority_contract.graph_owns_visible_real_destination_structure(self):
            default_name = self._next_inline_proposed_folder_name(parent_item)
            folder_name, ok = QInputDialog.getText(
                self,
                "New proposed folder",
                "Folder name:",
                text=default_name,
            )
            if not ok or not str(folder_name or "").strip():
                self.destination_tree_status.setText("Proposed folder creation cancelled.")
                return None
            folder_name = str(folder_name).strip()
            proposed_path = self.normalize_memory_path(
                "\\".join(part for part in [proposed_path_base, folder_name] if part)
            )
            if self._destination_path_exists_under_parent(parent_item, proposed_path):
                QMessageBox.information(
                    self,
                    "Proposed Folder",
                    "A folder with that name already exists here.",
                )
                return None
            parent_data = self.get_tree_item_node_data(parent_item) or {}
            proposed_folder = ProposedFolder(
                DestinationId="",
                FolderName=folder_name,
                DestinationPath=proposed_path,
                ParentPath=proposed_path_base,
                StableKey=str(uuid.uuid4()),
                DestinationDriveId=str(parent_data.get("drive_id", "") or ""),
                DestinationParentItemId=str(parent_data.get("id", "") or ""),
                IsSelectable=True,
                IsProposed=True,
                Status="Proposed",
            )
            self.proposed_folders = [
                row
                for row in self.proposed_folders
                if self._proposed_destination_path(row) != self._proposed_destination_path(proposed_folder)
            ]
            self.proposed_folders.append(proposed_folder)
            self._queue_unresolved_proposed_folder(proposed_folder, "inline_proposed_graph_dialog")
            self._sync_restore_destination_overlay_pending_from_unresolved_queues()
            self._apply_destination_planning_overlays("inline_proposed_graph_dialog")
            self._rebuild_submission_visual_cache()
            self.update_progress_summaries()
            self.refresh_planned_moves_table()
            self.destination_tree_status.setText("Proposed folder added (pending library row).")
            return None
        default_name = self._next_inline_proposed_folder_name(parent_item)
        proposed_path = self.normalize_memory_path(
            "\\".join(part for part in [proposed_path_base, default_name] if part)
        )
        temp_node = {
            "id": f"INLINE-PROP-{datetime.utcnow().strftime('%H%M%S%f')[-8:]}",
            "name": default_name,
            "real_name": default_name,
            "display_path": proposed_path,
            "item_path": proposed_path,
            "destination_path": proposed_path,
            "tree_role": "destination",
            "is_folder": True,
            "proposed": True,
            "node_origin": "proposed",
            "overlay_state": "proposed",
            "_inline_new_proposed": True,
            "_inline_commit_ready": False,
            "_inline_parent_path": proposed_path_base,
        }
        self._remove_placeholder_children(parent_item)
        item = QTreeWidgetItem([default_name, "", "", ""])
        item.setData(0, Qt.UserRole, temp_node)
        self._apply_explorer_metadata_columns(item, temp_node)
        item.setFlags(item.flags() | Qt.ItemIsEditable)
        parent_item.addChild(item)
        parent_item.setExpanded(True)
        self.destination_tree_widget.setCurrentItem(item)
        item.setSelected(True)
        self.destination_tree_status.setText("Type the new folder name and press Enter.")
        def _start_inline_edit(target_item=item):
            current_node = self.get_tree_item_node_data(target_item) or {}
            self._inline_proposed_commit_item_id = str(current_node.get("id", "") or "")
            self.destination_tree_widget.setFocus()
            self.destination_tree_widget.scrollToItem(target_item)
            self.destination_tree_widget.setCurrentItem(target_item)
            index = self.destination_tree_widget.indexFromItem(target_item, 0)
            if index.isValid():
                self.destination_tree_widget.edit(index)

        QTimer.singleShot(180, _start_inline_edit)
        return item

